pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the minimum item (1) are fine,
    // but residuals that can't fit the NEXT item are dead space.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            // unusable for lookahead -> penalize proportionally to how close it is to being usable
            let gap = (next_item_size - post_residual) as f64;
            score += 3.0 * gap;
        } else {
            // reward a residual that can still host the next item, scaled by slack
            score -= 2.0 * (next_item_size as f64 / (post_residual as f64 + 1.0));
        }
    }

    // Penalize small residual gaps that are likely dead space under unknown distributions:
    // residuals in (0, 10) are almost unusable if min size were 10; be adaptive instead:
    // treat residuals below half of current item as increasingly dead.
    if post_residual > 0 && post_residual < item_size {
        score += 1.5 * (item_size - post_residual) as f64;
    }

    // Perfect fit reward
    if post_residual == 0 {
        score -= 10.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 5.0;
    }

    // Open bins pressure: penalize placements that leave large residuals when many bins are open
    let pressure = open_bins_count as f64 / (open_bins_count as f64 + 5.0);
    score += pressure * (post_residual as f64 / bin_capacity as f64) * 6.0;

    // New-bin candidate handling: only attractive when open bins fit poorly or mean residual is tiny
    if bin_residual == bin_capacity {
        let mean_fit = if next_item_size > 0 && mean_residual >= next_item_size as f64 { 1.0 } else { 0.0 };
        // make new bin costly unless nothing fits well
        let poor_alternatives = (fitting_bins_count as f64).min(3.0);
        score += 8.0 - 4.0 * (1.0 - mean_fit) - poor_alternatives;
        // early in stream, new bins are cheaper
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 2.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr_norm = pr / cap;

    // Base: prefer small post-residual, with smooth non-linear penalty growth
    let mut score = pr * (1.0 + 0.5 * pr_norm * pr_norm);

    // Tight-fit reward: smooth bump around post_residual near 0
    score -= 8.0 * (-pr / 6.0) * (-pr / 6.0) * (-1.0 + (-pr / 6.0) * (-pr / 6.0));

    // Polynomial coupling of post_residual with stream progress:
    // late in the stream, small residuals matter more (dead space is costlier)
    let coupling = pr_norm * pr_norm * (1.0 - pr_norm);
    score += 20.0 * coupling * (0.3 + progress);

    // Lookahead: reward leaving room for the next item (smooth interaction)
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        let fit_next = (pr - ns).max(0.0) / cap;
        let slack_gap = (pr - ns).abs();
        score -= 6.0 * fit_next;
        score += 0.05 * slack_gap * slack_gap / cap;
    }

    // Last-chance bin bonus: avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 {
        score -= 10.0 + 15.0 * (1.0 - pr_norm);
    }

    // Mild penalty for spreading across many bins; slightly relaxed late in stream
    score += 0.4 * (open_bins_count as f64).ln() * (1.0 - 0.5 * progress);

    // Prefer bins below mean residual (consolidation), smooth quadratic
    let dev = pr - mean_residual;
    score += 0.02 * dev * dev / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that no item (min size 1, practically >= 10)
    // can use are pure waste. Penalize tiny unusable gaps harshly.
    if post_residual == 0 {
        // Perfect fit: strongly reward.
        score -= 500.0;
    } else if post_residual < 10 {
        // Dead space below the smallest item size: heavily penalize.
        score += 200.0 + (10 - post_residual) as f64 * 20.0;
    } else if post_residual >= 10 && post_residual < 20 {
        // Marginal gap: only usable by very small items; mild penalty.
        score += 30.0;
    } else {
        // Usable gap: reward proportional to size.
        score -= 10.0;
    }

    // Lookahead coupling: if next item fits exactly in the post residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 150.0;
        } else if next_item_size <= post_residual {
            score -= 40.0;
        } else {
            // Next item won't fit here: the remaining gap risks becoming dead space.
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 80.0;
    }

    // Open-bin pressure: prefer using existing bins over opening new ones.
    score += open_bins_count as f64 * 2.0;

    // New-bin candidate handling: an empty bin has no scarcity; make it a fallback.
    if bin_residual == bin_capacity {
        // Slight penalty so open bins with decent fits win; but if all open bins
        // would create dead space, the above penalties make the new bin attractive.
        score += 25.0;
        // Early in the stream, opening bins is cheaper (more future items to fill them).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 30.0 * (1.0 - progress);
    }

    // Prefer bins whose residual is already below the mean (consolidating waste).
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: small unusable gaps (1..=15) are heavily penalized,
    // scaled by how close the gap is to zero.
    if post_residual > 0 && post_residual <= 15 {
        score += (16.0 - post_residual as f64) * 8.0;
    }
    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward;
    // if the next item would not fit in post residual but fits in a fuller bin,
    // penalize wasting space that could host it.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= (next_item_size as f64) * 0.8;
        } else {
            score += (next_item_size as f64) * 0.4;
        }
    }

    // Open-bin pressure: discourage spreading across many bins unless the fit is tight.
    score += (open_bins_count as f64) * 1.5;

    // Last chance: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: make empty bins attractive only when the current fit is bad.
    if bin_residual == bin_capacity {
        // Neutral-ish baseline; dead-space logic above will dominate for open bins.
        score += 10.0;
        if item_size >= bin_capacity / 2 {
            score -= 20.0; // big items prefer fresh bins
        }
    }

    // Mean residual coupling: prefer bins deviating below the mean residual
    // (fill the emptier-of-space bins first keeps others flexible).
    score += (mean_residual - bin_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Tight fit reward: fraction of residual consumed
    let fill_frac = item_size as f64 / bin_residual.max(1) as f64;
    score -= 40.0 * fill_frac;

    // Penalize small unusable leftovers (dead space), unless next item fits
    if post_residual > 0 {
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 15.0; // lookahead: leftover still useful
        } else {
            let dead = if next_item_size == 0 {
                1.0
            } else {
                (post_residual as f64 / next_item_size as f64).min(1.0)
            };
            score += 20.0 * dead;
        }
    }

    // Last-chance bin: strongly prefer to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate handling: only attractive when open bins are fragmented
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual - post_residual as f64).abs();
        let progress = step_index as f64 / total_items.max(1) as f64;
        let pressure = open_bins_count as f64 / (2.0 + progress * 10.0);
        // Prefer new bin when mean residual is small (poor fits everywhere)
        let new_bin_appeal = 30.0 + pressure * 10.0 - fragmentation * 0.5;
        score += 10.0 - new_bin_appeal;
    } else {
        // Reward using bins with below-average residual (consolidate large gaps)
        let diff = mean_residual - bin_residual as f64;
        score -= 0.3 * diff;
    }

    // Late stream: consolidate into fewer bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress > 0.8 && bin_residual < bin_capacity {
        score -= 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: squared penalty on post-residual.
    score += (post_residual as f64).powi(2) / (bin_capacity as f64);

    // Penalize dead space that cannot fit the next item (lookahead coupling).
    if next_item_size > 0 {
        if post_residual < next_item_size && post_residual > 0 {
            score += (next_item_size - post_residual) as f64 * 2.0;
        } else if post_residual >= next_item_size {
            // Bonus if this bin can also host the next item exactly.
            score -= 3.0;
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Prefer filling already-open bins when many are open.
    score += open_bins_count as f64 * 0.5;

    // Deviation from mean residual: prefer bins whose residual is close to item need.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.3;

    // Time horizon: later in the stream, be more conservative (favor tight packing).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.5 * progress;

    // New-bin candidate: make it moderately attractive only when current bin would leave bad residue.
    if bin_residual == bin_capacity {
        let waste_now = post_residual as f64;
        score = waste_now + 20.0 - 0.2 * open_bins_count as f64;
        if fitting_bins_count <= 1 {
            score -= 25.0; // no good open bin -> new bin is fine
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful
    // later are heavily penalized (non-linear "unusability" curve).
    if post_residual > 0 {
        // Usefulness threshold: next item must plausibly fit (min size 1, but
        // weight by lookahead item if known).
        let useful_threshold = if next_item_size > 0 && next_item_size <= 100 {
            next_item_size as f64
        } else {
            20.0
        };
        if (post_residual as f64) < useful_threshold {
            // Dead space: penalize quadratically as it approaches zero slack.
            let gap = useful_threshold - post_residual as f64;
            score += 8.0 + gap * gap * 0.35;
        }
    } else {
        // Perfect fill: strong reward.
        score -= 25.0;
    }

    // Reward tight fits: fraction of bin used by this placement.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 12.0;

    // Exact / near-exact fit bonus relative to residual.
    if bin_residual > 0 {
        let fit_tightness = item_size as f64 / bin_residual as f64;
        score -= fit_tightness * 10.0;
    }

    // Open-bin pressure: penalize placements that keep many bins open
    // unless they close a bin or are very tight.
    let bin_pressure = (open_bins_count as f64).ln().max(0.0) * 2.0;
    score += bin_pressure;

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate handling: only attractive when no open bin offers
    // a genuinely tight fit or when open bins are fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual - post_residual as f64).abs();
        if mean_residual > 0.0 && mean_residual < item_size as f64 * 1.2 {
            // Open bins are too fragmented to be useful -> new bin is good.
            score -= 20.0;
        } else {
            score += 15.0 + fragmentation * 0.05;
        }
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
    }

    // Lookahead coupling: if the next item fits exactly in post_residual,
    // reward this placement strongly.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward residuals that can host the next item exactly or well
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 400.0; // chain fit
        } else if post_residual >= next_item_size {
            score -= 60.0 * (1.0 - (post_residual as f64 - next_item_size as f64) / bin_capacity as f64);
        } else {
            // dead space relative to next item
            score += 30.0 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // Penalize residuals far below mean (fragmenting a rich bin) mildly
    score += 0.5 * (mean_residual - post_residual as f64).abs();

    // Last-chance bin: strong reward to use it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 250.0;
    }

    // New-bin candidate: penalize opening a new bin unless item is large relative to capacity
    if bin_residual == bin_capacity {
        score += 120.0 - 0.8 * item_size as f64;
    }

    // Late in stream: prefer tighter packing
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * post_residual as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_post = post / cap;

    // Base: reward tight fits (small post_residual), with non-linear emphasis
    let mut score = post.powf(1.5);

    // Smooth polynomial coupling of post_residual with stream progress:
    // early on tolerate slack, late in the stream punish it harder
    score *= 1.0 + 0.8 * progress * norm_post.powi(2);

    // Penalize residuals that are too small to ever be useful (dead space),
    // scaled by how much of the stream remains
    let dead = if post > 0.0 && post < 10.0 { (10.0 - post) / 10.0 } else { 0.0 };
    score += dead * (1.0 - progress) * 15.0;

    // Lookahead: reward bins whose post residual can host the next item
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if post >= next {
            score -= (1.0 - post / cap) * 10.0;
        } else {
            score += (next - post).powf(1.2) * 0.3;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        // mild competition scaling
        score += 2.0 * (fitting_bins_count as f64 - 1.0).ln();
    }

    // Prefer bins already below mean residual (consolidating slack)
    score += ((mean_residual - post) * 0.15).max(-5.0);

    // New-bin candidate: make it attractive only when no open bin fits well
    if bin_residual == bin_capacity {
        // base cost of opening a bin, discounted early in the stream
        score = 45.0 - 25.0 * progress;
        if next_item_size > 0 && (next_item_size as f64) <= cap - item_size as f64 {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (low post_residual).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize dead space that can never be filled by the next item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0 * (next_item_size - post_residual) as f64;
    }
    // Reward when the next item fits exactly in the post residual (perfect chaining).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 15.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    } else if fitting_bins_count > 1 {
        // When many bins fit, prefer the one with least waste.
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // Prefer filling bins that are already mostly full (low residual relative to mean).
    score += 0.35 * ((bin_residual as f64) - mean_residual);

    // Late in the stream, be more conservative: avoid opening new bins.
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses and when open bins exist.
        let mut new_bin_penalty = 25.0 + 45.0 * progress;
        if open_bins_count > 0 {
            new_bin_penalty += 10.0;
        }
        // If item is huge relative to capacity, new bin is more acceptable early.
        if (item_size as f64) > 0.7 * (bin_capacity as f64) {
            new_bin_penalty -= 15.0 * (1.0 - progress);
        }
        score += new_bin_penalty;
    } else {
        // Placing into an existing bin is rewarded more as stream progresses.
        score -= 10.0 * progress;
    }

    // Mild penalty for leaving very small unusable slivers.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead space penalty: residuals too small to hold the smallest item are useless.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual < 20 {
        score += 12.0;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Reward bins that can also host the lookahead item (k=2 chaining).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 6.0; // dead space relative to the known future item
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: make it attractive only when open bins are crowded or fit is poor.
    if bin_residual == bin_capacity {
        let pressure = (open_bins_count as f64) * 1.5 + mean_residual * 0.3;
        let fit_quality = (item_size as f64) / (bin_capacity as f64);
        score = bin_capacity as f64 - pressure - fit_quality * 20.0;
        if fitting_bins_count <= 1 {
            score -= 25.0; // opening fresh is better than forcing a bad fit
        }
    }

    // Mild open-bin pressure: prefer compacting into fewer bins early on.
    score += (open_bins_count as f64) * 0.05;

    // Late-stream consolidation: waste tolerance decreases as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += post_residual as f64 * progress * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus: item exactly fills the bin.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual can
    // accommodate the next item, with extra reward for near-perfect chaining.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            // Reward the chain; tighter chains (small slack) get more reward.
            score -= 150.0 + (post_residual as f64) - slack;
            if slack == 0.0 {
                // Perfect 2-item chain: fill bin completely with two items.
                score -= 500.0;
            }
        } else {
            // Next item cannot follow in this bin: penalize leftover dead space,
            // scaled by how badly the chain fails.
            let overflow = (next_item_size - post_residual) as f64;
            score += overflow * 0.5;
        }
    }

    // Penalize bins whose residual deviates upward from the mean (fragmented bins).
    score += (post_residual as f64 - mean_residual).abs() * 0.3;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0 + (item_size as f64 / bin_capacity as f64) * 100.0;
    }

    // New-bin candidate: make opening a new bin attractive only for tiny items
    // into a fresh bin or when no good fit exists elsewhere.
    if bin_residual == bin_capacity {
        // Fresh bin has full residual: baseline penalty so it loses to good fits,
        // but its large raw residual keeps it competitive for large items.
        score += 120.0;
        // Prefer new bins late in the stream when many bins are open and fragmented.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= progress * 60.0 + open_bins_count as f64 * 2.0;
    }

    // Mild preference for tighter bins early (best-fit core), relax later.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - progress) * (post_residual as f64) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = 0.0;

    // Base: prefer tight fit (small post_residual), but treat tiny dead gaps harshly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let post = post_residual as f64;

    if post_residual == 0 {
        // Perfect fill: strongly favored.
        score -= 60.0;
    } else if post_residual < 10 {
        // Unusable dead space (nothing smaller than 10 fits): penalize heavily.
        score += 45.0 + post * 2.0;
    } else {
        // Usable residual: mild penalty, scaled down as fit tightens.
        score += post * 0.6;
    }

    // Reward bins whose residual exactly accommodates the upcoming item (lookahead synergy).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // Residual can host next item: mild bonus proportional to snugness.
        score -= (post_residual - next_item_size) as f64 * 0.05;
    }

    // Open-bin pressure: with many bins open, prefer consolidating into existing ones.
    score += open_bins_count as f64 * 0.8;

    // Last-chance bin: if this is the only fitting bin, opening a new bin wastes it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Mean-residual coupling: prefer bins below mean residual (tighter than average).
    score += (mean_residual - post) * 0.15;

    // New-bin candidate handling: an empty bin has huge residual; make it attractive
    // only when the current item would leave a bad gap in any existing bin, or when
    // few bins are open. Penalize default new-bin slightly so consolidation wins on ties.
    if bin_residual == bin_capacity {
        // Empty bin baseline: moderate score.
        score = 30.0 + open_bins_count as f64 * 0.5;
        // Late in stream, opening fresh bins is cheaper than fragmenting.
        if progress > 0.7 {
            score -= 10.0 * progress;
        }
        // If next item is large, a fresh bin is valuable.
        if next_item_size >= 50 {
            score -= 8.0;
        }
    }

    // Slight preference for larger residual bins early (keeps flexibility).
    score -= (bin_residual as f64) * 0.02 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when the next item exactly fills the residual.
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = (post_residual as i64 - next_item_size as i64) as f64;
        // Perfect match for next item: strong reward.
        if gap == 0.0 {
            score -= 200.0;
        } else {
            // Partial match: reward proportional to tightness of the 2-step fit.
            score -= 120.0 * (1.0 - gap / bin_capacity as f64);
        }
    } else if next_item_size > post_residual && next_item_size > 0 {
        // Next item cannot use this bin's leftover: penalize dead space creation.
        score += 40.0 * (post_residual as f64 / bin_capacity as f64);
    }

    // Prefer bins whose residual is already small (compact packing relative to mean).
    let dev = post_residual as f64 - mean_residual;
    score += 0.35 * dev;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // Penalize wasteful fits that leave very small unusable slivers.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // New-bin candidate (pristine empty bin): make it attractive only when
    // no open bin offers a good 2-step match; otherwise keep it mildly costly.
    if bin_residual == bin_capacity {
        let good_lookahead = next_item_size > 0 && next_item_size <= post_residual
            && (post_residual as i64 - next_item_size as i64) <= 15;
        if good_lookahead {
            score += 30.0; // an existing bin likely matched already; don't open new
        } else {
            score -= 60.0 + 0.5 * open_bins_count as f64; // fresh bin is fine
        }
    }

    // Mild late-stream bias toward tightening existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 20.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Penalize creating unusable dead space (too small for the smallest plausible item).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // 2-step lookahead: reward when post_residual matches next item size exactly or closely.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual > next_item_size {
            // Next item can also fit here: reward proportionally to how well it fills.
            let fill = next_item_size as f64 / post_residual as f64;
            score -= 200.0 * fill;
        } else {
            // Next item won't fit in the residual: penalize wasted lookahead opportunity.
            score += 30.0 * (next_item_size - post_residual) as f64 / item_size.max(1) as f64;
        }
    }

    // Relative to mean residual: bins with larger-than-average residual are better targets.
    let dev = bin_residual as f64 - mean_residual;
    score -= 0.5 * dev;

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 300.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are crowded.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let crowded = mean_residual < item_size as f64 * 1.5;
        if crowded {
            score -= 50.0;
        } else {
            score += 150.0 + 100.0 * (1.0 - progress);
        }
    }

    // Slight preference for fuller bins overall.
    score -= 0.3 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
