    // 2-step lookahead: reward when next item fits the post residual
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // next item fits perfectly-ish: strong reward scaled by tightness
            let slack = (post_residual - next_item_size) as f64;
            score -= 200.0 - slack * 1.5;
            if slack == 0.0 {
                score -= 250.0; // chain of perfect fits
            }
        } else {
            // next item won't fit here: penalize leaving a gap smaller than next item (dead space)
            let gap = post_residual as f64;
            if gap < next_item_size as f64 {
                score += (next_item_size as f64 - gap) * 0.8;
            }
        }
    }

    // Compare post residual against mean residual: prefer bins that tighten the distribution
    score += (post_residual as f64 - mean_residual) * 0.5;

    // Last-chance bin bonus: if this is the only bin that fits, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
    }

    // Penalize opening a new bin early when a decent fit exists in an open bin
    if bin_residual == bin_capacity {
        // new bin candidate: base score is capacity; add penalty unless item is large
        score += 40.0;
        if item_size >= 50 {
            score -= 30.0; // large items are fine in fresh bins
        }
    }

    // Late in the stream, prefer tighter packing (close residual gaps)
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.3;

    // Slight preference for bins with larger residuals when many bins are open
    score -= (bin_residual as f64 / bin_capacity as f64) * open_bins_count as f64 * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small nonzero gaps are nearly useless.
    if post_residual > 0 {
        let dead = post_residual as f64;
        // Smallest plausible item is 1; gaps below ~10 are dead space.
        if dead < 10.0 {
            score += 40.0 * (10.0 - dead) / 10.0;
        } else {
            // Usable gap: mild reward proportional to how well future items fit.
            let usable = dead / bin_capacity as f64;
            score -= 6.0 * usable;
        }
    } else {
        // Perfect fit: strong reward.
        score -= 25.0;
    }

    // Reward exact-tight packing relative to item size (waste ratio penalty).
    let fill = item_size as f64 / bin_residual.max(1) as f64;
    score -= 15.0 * fill;

    // Lookahead: if the next item fits exactly in the post-residual, reward.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size <= post_residual {
            score -= 8.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // Next item won't fit here: penalize leaving a gap it can't use.
            score += 5.0;
        }
    }

    // Open-bin pressure: discourage spreading across too many bins when
    // mean residual is already large; encourage consolidation.
    let mean_res = mean_residual.max(0.0);
    score += 0.05 * open_bins_count as f64 * (1.0 - mean_res / bin_capacity as f64);

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score = 35.0;
        // Cheaper to open a new bin when many bins are open with tiny residuals.
        score -= 0.3 * open_bins_count as f64;
        // If item nearly fills a fresh bin, opening is attractive.
        score -= 10.0 * (item_size as f64 / bin_capacity as f64);
        // If the only alternative is a bad fit, opening a new bin is better.
        if fitting_bins_count == 0 {
            score -= 20.0;
        }
    }

    // Slight stream progression bias: as stream advances, prefer tighter packing.
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        score -= 3.0 * progress * fill;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that no plausible item (min size 10)
    // can use are pure waste -> heavy penalty.
    if post_residual < 10 && post_residual > 0 {
        score += 60.0;
    } else if post_residual < 20 {
        // small gap that only tiny items can fill: moderate penalty
        score += 25.0;
    }

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // Lookahead: if the next item fits exactly into the post-residual,
    // reward this placement (chain packing).
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack < 10.0 {
            score -= 40.0;
        } else {
            score -= 10.0;
        }
    } else if next_item_size > 0 && next_item_size > post_residual && post_residual < 10 {
        // dead space that next item can't use either
        score += 30.0;
    }

    // Open-bin pressure: discourage spreading across many bins unless the
    // fit is tight; the fuller the bin relative to capacity, the better.
    let tightness = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= tightness * 40.0;

    // Pressure grows with number of open bins: prefer compacting into
    // existing bins when many are open.
    score += (open_bins_count as f64) * 2.0;

    // Prefer bins whose residual deviates favorably from the mean residual:
    // placing into a below-average-residual bin compacts the stream.
    score += (mean_residual - bin_residual as f64) * 0.5;

    // Late in the stream, be more conservative: avoid creating new dead space.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * progress;
    }

    // New-bin candidate (empty bin): make it unattractive unless the item
    // cannot fit well anywhere else. An empty bin has residual == capacity.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, softened when few bins are open
        // (early stream) or when the item is large relative to capacity.
        let large_item_bonus = item_size as f64 / bin_capacity as f64; // big items waste less in a fresh bin
        let mut new_bin_cost = 120.0 - large_item_bonus * 60.0;
        // If no existing bin fits (this is the only candidate), the cost is
        // effectively irrelevant, but keep it competitive.
        if fitting_bins_count == 0 {
            new_bin_cost -= 200.0;
        }
        // Late in the stream, opening new bins is riskier: slight extra cost.
        new_bin_cost += 20.0 * progress;
        score = new_bin_cost + post_residual as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
