    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; with few,
    // discourage near-empty bins hoarding.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * 1.5 * (1.0 - progress);

    // Prefer bins whose residual deviates from the mean (consolidation).
    score += 0.3 * (bin_residual as f64 - mean_residual).abs();

