    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 30.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size.min(15) {
        score += 20.0; // dead space for the known next item
    }

    // New-bin candidate: neutral baseline, slightly above good fits but below
    // dead-space penalties, so it wins only against bad placements.
    if bin_residual == bin_capacity {
        score = 35.0 + open_bins_count as f64 * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
