    // Reward bins whose residual tightly matches the item (minimize fragmentation).
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += tightness * 10.0;

    // Lookahead: if the next item fits exactly in the post residual, reward this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = post_residual - next_item_size;
        if gap < 5 {
            score -= 20.0;
        } else {
            score -= 5.0;
        }
    } else if next_item_size > post_residual && (post_residual as f64) < dead_threshold {
        // Creating dead space that the next item cannot use: extra penalty.
        score += 10.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: discourage scattering across many bins,
    // but make the new-bin candidate progressively more attractive late in the stream.
    if bin_residual == bin_capacity {
        score += 15.0 + 2.0 * open_bins_count as f64;
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * progress;
    } else {
        score += 0.5 * open_bins_count as f64;
    }

    // Slight preference for bins deviating below the mean residual (tighter bins).
    score += 0.3 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Strong reward: post_residual exactly matches the next item (perfect 2-step chain)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (post - nxt).abs();
        if diff == 0.0 {
            score -= 45.0;
        } else if diff <= 5.0 {
            score -= 25.0 - 3.0 * diff;
        } else {
            // penalize leaving residuals the next item cannot use
            if post < nxt {
                score += 0.35 * (nxt - post);
            } else {
                score += 0.12 * (post - nxt);
            }
        }
        // next item would fit snugly leaving tiny remainder after it
        if nxt <= post && post - nxt <= 10.0 {
            score -= 8.0;
        }
    }

    // Compare against mean residual across open bins: prefer tighter-than-average packing
    score -= 0.5 * (mean_residual - post);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Penalize creating large dead space that nothing (>=10) can fill
    if next_item_size > 0 && post > 0.0 && post < next_item_size as f64 {
        let waste = cap / post - 1.0;
        score += 3.0 * waste;
    }
    if post == 0.0 {
        score -= 30.0; // perfect closure
    }

    // Early in stream: keep bins flexible, mildly prefer new-bin option
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual as f64 == cap {
        score -= 5.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) with a non-linear boost.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space: residuals too small for the smallest plausible item (1..100 range).
    if post_residual < 10 && post_residual > 0 {
        score += 18.0;
    }

    // Lookahead coupling: penalize residuals that exactly tempt the next item only partially;
    // reward residuals that can host the next item perfectly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0; // perfect two-item stacking
        } else if post_residual >= next_item_size {
            score -= 4.0;
        } else {
            score += 6.0; // next item won't fit here; wasted space risk
        }
    }

    // Last-chance bin: strongly prefer using the final fitting bin before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: open a new bin only when current bins fit poorly.
    if bin_residual == bin_capacity {
        // Base moderate score for a fresh bin; beaten by good fits, beats bad fits.
        score = 55.0;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 8.0; // fresh bin pairs well with a larger follower
        }
        // Late in the stream, prefer closing out existing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
        // Few open bins -> opening is cheaper.
        score -= 2.0 * (open_bins_count as f64).ln().max(0.0);
    }

    // Global state: if mean residual is large, encourage filling existing bins harder.
    if bin_residual != bin_capacity {
        let gap = mean_residual - bin_residual as f64;
        if gap > 0.0 {
            score += 0.15 * gap; // this bin is emptier than average -> deprioritize slightly
        } else {
            score -= 0.15 * (-gap); // fuller-than-average bin: good, use it
        }
    }

    // Time horizon: early on, keep bins balanced (mild); late, greedily minimize waste.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 8.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap; // normalized post-residual in [0,1]

    // Base: prefer tight fits (small post_residual)
    let mut score = pr;

    // Smooth non-linear coupling: waste penalty grows super-linearly as residual shrinks,
    // modulated by stream progress (tighter packing demanded later in the stream).
    let tightness = 1.0 - norm_pr;
    score += 30.0 * tightness * tightness * (0.5 + progress);

    // Reward bins whose post-residual can still accommodate the lookahead item smoothly
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fit_next = (norm_pr * cap - nxt).max(0.0);
        let fit_quality = fit_next / cap;
        score -= 25.0 * fit_quality * (1.0 - fit_quality) * 4.0; // smooth bump peaked at perfect lookahead fit
        // Penalize if post-residual is just barely too small for next item (dead space)
        let miss = (nxt - norm_pr * cap).max(0.0) / cap;
        score += 20.0 * miss * miss;
    }

    // Smooth last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 40.0 * (1.0 - progress * 0.5);
    }

    // Mild penalty for leaving residual far from mean (fragmentation smoothing)
    let dev = (pr - mean_residual) / cap;
    score += 10.0 * dev * dev * (0.5 + 0.5 * progress);

    // Mild pressure against proliferating bins when many are open
    score += 2.0 * (open_bins_count as f64).ln().max(0.0) * norm_pr;

    // Smooth reward for near-perfect fills late in the stream
    score -= 15.0 * (1.0 - norm_pr).powi(3) * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Dead-space penalty: residual too small for any plausible item (min size 1, but
    // treat residuals < 10 as nearly dead unless exact zero)
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Harmonic classes: reward post_residual that is "reusable" — divisible by common
    // item granularity (10, 20, 25, 50)
    if post_residual % 50 == 0 && post_residual > 0 {
        score -= 25.0;
    } else if post_residual % 25 == 0 && post_residual > 0 {
        score -= 15.0;
    } else if post_residual % 10 == 0 && post_residual > 0 {
        score -= 8.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post-residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size < post_residual {
            let nxt_res = post_residual - next_item_size;
            if nxt_res % 10 == 0 {
                score -= 20.0;
            }
            score -= (nxt_res as f64) * 0.05;
        } else {
            // next item won't fit here; penalize slightly to prefer bins where chain continues
            score += 10.0;
        }
    }

    // Last chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate logic: empty bin gets a moderate baseline so it only wins
    // when open bins are genuinely poor fits
    if bin_residual == bin_capacity {
        score += 40.0 + 0.3 * (open_bins_count as f64);
    }

    // Prefer filling bins that are already relatively full (low residual relative to mean)
    score += 0.2 * (mean_residual - bin_residual as f64).max(0.0);

    // Mild late-stream tightening: as stream progresses, discourage waste
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * (post_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps are the worst outcome.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64) / 10.0;
    }
    if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 40.0;
    } else if post_residual >= 10 {
        // Larger usable residuals are mildly preferred proportionally to
        // their ability to host future mid-size items.
        let usable = post_residual as f64 / bin_capacity as f64;
        score -= 8.0 * usable;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading further;
    // keep items consolidated in existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 1.5 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Residual alignment: prefer bins whose residual is close to the item
    // (tight fits), penalize wasteful placements into very large residuals.
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += 10.0 * tightness;

    // Lookahead coupling: if the next item could exactly consume the
    // post-residual, reward leaving that gap; if the gap is slightly smaller
    // than the next item, penalize (dead space for the lookahead).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0;
        } else if post_residual > 0 && post_residual < next_item_size {
            score += 15.0;
        }
    }

    // New-bin candidate: only attractive when no open bin offers a decent fit
    // (mean residual small relative to item) or pressure is high.
    if bin_residual == bin_capacity {
        let desperation = (item_size as f64 - mean_residual).max(0.0) / bin_capacity as f64;
        score = 45.0 - 30.0 * desperation + 2.0 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual equals next item size -> strong reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 1000.0;
        } else if post_residual > next_item_size {
            // Next item still fits after this placement: mild reward proportional to slack.
            score -= 30.0 - 0.3 * (post_residual - next_item_size) as f64;
        } else {
            // Next item won't fit: penalize leftover dead space below next_item_size.
            score += (next_item_size - post_residual) as f64 * 2.0;
        }
    }

    // Very small unusable remainder: penalize (dead space).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // Last-chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // Prefer bins tighter than the mean residual (good fit), penalize loose bins.
    score -= (mean_residual - bin_residual as f64) * 1.5;

    // Early in the stream, be slightly more willing to consolidate (fewer bins).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Time horizon: later in the stream, consolidation matters more.
    let t = step_index as f64 / (total_items.max(1) as f64);
    let horizon = 0.5 + 1.5 * t;

    // Reward tight fits: penalize large post_residual relative to capacity, more so later.
    let waste_frac = post_residual as f64 / bin_capacity as f64;
    score += horizon * 40.0 * waste_frac * waste_frac;

    // Lookahead coupling: if next item fits exactly in post_residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // partial reward scaled by how well it fills
            let fill = next_item_size as f64 / post_residual.max(1) as f64;
            score -= 30.0 * fill;
        } else {
            // next item won't fit here; slight penalty proportional to leftover size
            score += 10.0 * (next_item_size as f64 - post_residual as f64) / bin_capacity as f64;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0 + 15.0 * t;
    }

    // Many open bins: encourage filling existing bins rather than spreading.
    let crowding = open_bins_count as f64 / (1.0 + mean_residual.max(1.0) / bin_capacity as f64);
    score -= 5.0 * crowding.ln().max(0.0);

    // Penalize bins whose residual deviates badly from the mean (keep residual pool balanced),
    // unless the fit is very tight.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev * (1.0 - waste_frac);

    // Reward filling small residuals completely.
    if post_residual < 10 {
        score -= 20.0;
    }

    // New empty bin candidate: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        // base penalty so open bins are preferred unless they waste space
        score += 35.0;
        // if all fitting bins would leave big waste, new bin becomes competitive
        if fitting_bins_count == 0 {
            score -= 50.0;
        }
        score -= 20.0 * t; // later on, opening bins is more acceptable
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let x = post / cap; // normalized post residual

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early stream: prefer moderate residuals; late stream: strongly prefer small residuals.
    let base = x * x * (1.0 + 3.0 * progress) + x * (1.0 - progress);

    // Reward tight fits (small post_residual) more aggressively as stream progresses.
    let tight_bonus = -(1.0 - x).powi(3) * (1.0 + 2.0 * progress) * 20.0;

    // Penalize dead space relative to mean residual across open bins.
    let dead_penalty = if post > mean_residual { (post - mean_residual) * (0.5 + progress) } else { 0.0 };

    // Last-chance bin: strong reward to avoid opening a new bin.
    let last_chance = if fitting_bins_count == 1 && bin_residual != bin_capacity { -15.0 * (1.0 + progress) } else { 0.0 };

    // Lookahead coupling: reward if the next item fits into post_residual.
    let lookahead = if next_item_size > 0 && (next_item_size as f64) <= post {
        -8.0 * (1.0 - post / cap)
    } else {
        0.0
    };

    // New-bin candidate: smooth penalty growing with stream progress and open bins.
    let new_bin = if bin_residual == bin_capacity {
        30.0 + 40.0 * progress + 2.0 * open_bins_count as f64
    } else {
        0.0
    };

    let mut score = base * 10.0 + tight_bonus + dead_penalty + last_chance + lookahead + new_bin;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover lands on
    // "usable" residue classes (multiples of common item granularity) are
    // more likely to be filled later, so reward them.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Fraction of capacity remaining after placement.
    let frac = post / cap;

    // Class A: post_residual divisible by 10 (typical size quantum) -> highly reusable.
    if post_residual % 10 == 0 {
        score -= 6.0 * (1.0 - frac);
    }
    // Class B: divisible by 5 -> moderately reusable.
    else if post_residual % 5 == 0 {
        score -= 3.0 * (1.0 - frac);
    }
    // Class C: small awkward leftovers are dead space; penalize tiny residues.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Integer-division threshold: residue bucket by post_residual / 25.
    let bucket = post_residual / 25; // 0,1,2,3
    match bucket {
        0 => score += 4.0,        // nearly full bin: good, but tiny residue risk handled above
        1 => score -= 2.0,        // 25..49 left: useful mid-space
        2 => score -= 4.0,        // 50..74 left: very useful
        _ => score -= 1.0,        // mostly empty: weak preference
    }

    // Coupling with lookahead item: if the next item fits exactly into the
    // post residual, strongly favor this bin (perfect chaining).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            // Harmonic match: next item leaves again a class-A residue.
            let next_post = post_residual - next_item_size;
            if next_post % 10 == 0 {
                score -= 10.0;
            } else if next_post % 5 == 0 {
                score -= 5.0;
            }
            if next_post < 10 && next_post > 0 {
                score += 8.0; // chaining into dead space
            }
        } else {
            // Next item cannot follow here; slight penalty if this bin would
            // then be stranded with mid-size residue.
            if post_residual >= 10 && post_residual < 40 {
                score += 3.0;
            }
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when no open bin offers a decent fit
    // or the stream is early and spreading load is cheap.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let spread_bonus = (1.0 - progress) * 4.0;
        score = cap - spread_bonus + open_bins_count as f64 * 0.5;
        // If some open bin fits, make new bin clearly worse unless it's the only option.
        if fitting_bins_count >= 1 {
            score += 15.0;
        }
    }

    // Mild pressure to consolidate into fewer bins.
    score -= (bin_capacity as f64 - mean_residual).max(0.0) * 0.02;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (1.0 - post_residual as f64 / 10.0);
    }

    // Perfect / near-perfect fits get strong rewards.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual >= 10 && post_residual <= 20 {
        score -= 8.0; // gap likely reusable by typical small items
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Pressure against accumulating too many open bins.
    score += open_bins_count as f64 * 0.8;

    // Lookahead: if the next item fits exactly in the post-residual, reward it.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 45.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // next item can't use the leftover; penalize large stranded residuals
        score += post_residual as f64 * 0.3;
    }

    // Mild alignment with mean residual: prefer bins whose leftover stays near average.
    score += ((post_residual as f64 - mean_residual).abs()) * 0.15;

    // New-bin candidate: make it moderately attractive only when residuals are tight.
    if bin_residual == bin_capacity {
        score -= 5.0 + 2.0 * (mean_residual / 10.0).min(3.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong 2-step lookahead: reward bins whose post_residual matches the next item.
    if next_item_size > 0 {
        let look = next_item_size as f64;
        let gap = (post_residual as f64 - look).abs();
        // Perfect chain (next item exactly fills remaining space) -> huge reward.
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual >= next_item_size {
            // Next item fits here afterwards: reward proportional to tightness of chain.
            score -= 25.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // Next item would NOT fit after placement: penalize dead space growth.
            score += 10.0 + gap * 0.35;
        }
    }

    // Penalize post_residual being small-but-unusable relative to typical item scale.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let tiny_threshold = 8.0 + 6.0 * progress;
    if post_residual > 0 && (post_residual as f64) < tiny_threshold {
        score += 30.0;
    }

    // Compare against mean residual across open bins: prefer tighter-than-average bins.
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly reward using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Mild penalty when many bins fit the item (prefer leaving flexible bins for later).
    if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0);
    }

    // New-bin candidate: prefer it only when it produces a perfectly empty bin late in the
    // stream or when no good chain exists; otherwise keep using open bins.
    if bin_residual == bin_capacity {
        let chain_bonus = if next_item_size > 0 && post_residual >= next_item_size { 1.0 } else { 0.0 };
        score += 8.0 - 10.0 * progress - 15.0 * chain_bonus;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item nearly fills the bin.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize leaving awkward dead space (small but unusable post-residual).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Lookahead: reward if the next item can fit into the post-residual.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 8.0 + 0.1 * next_item_size as f64;
        } else {
            // Post-residual too small for next item: penalize proportionally to waste.
            let waste = post_residual as f64 / bin_capacity as f64;
            score += 6.0 * waste;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: mildly discourage opening new bins when
    // open bins exist with decent residual, but allow it when existing
    // residuals are fragmented (high mean residual relative to capacity).
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let fragmentation = mean_residual / bin_capacity as f64;
        // Fragmented state -> opening a fresh bin is attractive.
        score += 5.0 - 10.0 * fragmentation - 3.0 * progress;
    } else {
        // Existing bin: slight bonus for keeping bins consolidated.
        score -= 2.0;
        // Prefer bins whose residual is above the mean (use the roomy ones first).
        if bin_residual as f64 > mean_residual {
            score -= 3.0;
        } else {
            score += 3.0;
        }
    }

    // Early stream: be slightly conservative, favor filling existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 4.0 * (1.0 - progress) * (1.0 - fit_ratio);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Normalized stream progress
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Non-linear polynomial coupling of post_residual with progress:
    // waste is more costly late in the stream (quadratic/cubic ramp)
    let pr = post_residual as f64;
    let pr_norm = pr / cap;
    let ramp = 1.0 + 2.0 * progress * progress + 3.0 * progress * progress * progress;
    score += 12.0 * pr_norm * pr_norm * ramp;

    // Reward tight fits (small post_residual) with a superlinear bonus
    score -= 20.0 * (1.0 - pr_norm) * (1.0 - pr_norm) * (1.0 - pr_norm);

    // Lookahead coupling: penalize leaving residual that cannot serve the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            // residual is reusable by the next item: reward proportionally to usable fraction
            let usable = nxt / (pr + 1.0);
            score -= 10.0 * usable * (1.0 + progress);
        } else {
            // dead space relative to the lookahead item
            let dead = (pr - nxt) / cap;
            score += 25.0 * dead.abs() * (1.0 + 2.0 * progress);
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 30.0 * (1.0 + progress);
    } else if fitting_bins_count > 1 {
        // mild competition scaling among many fitting bins
        score += (fitting_bins_count as f64).ln() * 2.0;
    }

    // Penalize bins deviating from the mean residual (prefer balanced utilization)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 8.0 * dev * dev;

    // Discourage bin proliferation early; allow new bins more readily later
    score += open_bins_count as f64 * (1.0 - progress) * 0.5;

    // New-bin candidate: neutral baseline with progress-dependent openness
    if bin_residual == bin_capacity {
        score = cap * (0.9 + 0.4 * progress) + open_bins_count as f64 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residuals that lie in "useful" classes
    // (multiples of 10, and small residuals), penalize awkward dead space.
    let pr = post_residual;
    let class = pr % 10;
    let harmonic_bonus: f64 = match class {
        0 => -8.0,
        1 | 2 | 3 => 6.0,          // slivers: nearly unusable
        4 | 5 | 6 => 1.5,
        _ => -1.0,
    };
    score += harmonic_bonus;

    // Integer-division threshold: residual in [0,10] is near-perfect packing.
    if pr / 10 == 0 {
        score -= 12.0;
    } else if pr / 10 == 1 {
        score -= 5.0;
    }

    // Lookahead coupling: does post_residual exactly or closely match next item?
    if next_item_size > 0 {
        let gap = (pr as i64 - next_item_size as i64).abs() as f64;
        if pr >= next_item_size {
            score -= 10.0 * (1.0 - gap / cap);
            if gap == 0.0 { score -= 15.0; }
        } else {
            score += 4.0 + 0.1 * (next_item_size as f64 - pr as f64);
        }
        // Harmonic compatibility: shared divisor class with next item
        if pr % 5 == 0 && next_item_size % 5 == 0 {
            score -= 3.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when current bin fits are poor.
    if bin_residual == bin_capacity {
        score += 10.0 + 0.5 * mean_residual;
        if next_item_size > 0 && next_item_size >= bin_residual - item_size + 1 && bin_residual == bin_capacity {
            score -= 5.0;
        }
    }

    // Progress-based tightening: late in the stream, prefer tighter packs.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64) * 0.3;

    // Penalize bins far below mean residual (fragmented outliers).
    score += 0.2 * (mean_residual - post_residual as f64).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that no plausible item can use
    // are heavily penalized. Items are 1..=100; treat gaps below a small
    // usable threshold as near-wasted, with a nonlinear blow-up.
    let dead_threshold = 10.0f64;
    if (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 6.0;
    }
    // Nonlinear penalty on very tight fits that still strand space.
    score += (post_residual as f64) * (post_residual as f64) / (bin_capacity as f64);

    // Reward perfect / near-perfect fits strongly.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 2 {
        score -= 25.0;
    }

    // Lookahead coupling: if the next item fits in the post residual,
    // this placement is doubly valuable (chained packing).
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        score -= 8.0 + 0.3 * next_item_size as f64;
    } else if next_item_size > 0 && (bin_residual as f64) >= next_item_size as f64 && (post_residual as f64) < next_item_size as f64 {
        // This placement destroys the ability to host the next item.
        score += 5.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing bins rather than spreading; also makes new bins less attractive.
    let pressure = open_bins_count as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportional to open bins and stream progress.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 12.0 + pressure * 1.5 + 10.0 * progress;
        // A new bin is acceptable only when the item is huge relative to capacity
        // (few future pairing opportunities) and few bins are open.
        if item_size as f64 > 0.7 * bin_capacity as f64 && open_bins_count < 3 {
            score -= 15.0;
        }
    } else {
        // Existing bin: slight reward scaled by pressure to consolidate.
        score -= 0.05 * pressure;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Deviation from mean residual: prefer bins whose residual is already low
    // (tight bins) to keep other bins flexible.
    score += 0.3 * (post_residual as f64 - mean_residual).abs().signum()
        * ((post_residual as f64 - mean_residual).abs());

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 2-step lookahead: perfect match between post_residual and next_item_size
    let next = next_item_size as f64;
    if next > 0.0 {
        let post = post_residual as f64;
        let diff = (post - next).abs();

        // Perfect match: next item exactly fills the bin afterwards -> huge reward
        if diff < 0.5 {
            score -= 60.0;
        } else if next <= post {
            // Next item still fits: reward proportional to how tight the pair is
            score -= 20.0 * (1.0 - diff / bin_capacity as f64);
        } else {
            // Next item would NOT fit here: penalize leaving awkward residual
            score += 8.0 + 0.15 * (post - next).abs() as f64;
        }

        // Reward residuals close to mean residual (keeps bins balanced)
        score += 0.1 * (post - mean_residual).abs();
    }

    // Last chance: this is the only bin that fits -> strongly prefer using it
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Penalize opening a new bin when decent fits exist (new-bin candidate
    // has bin_residual == bin_capacity and post_residual is large)
    if bin_residual == bin_capacity {
        // New bin: baseline penalty unless item is huge relative to capacity
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        score += 15.0 - 10.0 * fill_ratio;
    }

    // Early in stream: slightly favor consolidation into fewer bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * (1.0 - progress) * (open_bins_count as f64).ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: normalized fill ratio of this placement.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 40.0 * fill * fill;

    // Penalize small unusable post-residuals that can't hold typical items,
    // unless it's an exact/near-exact fit.
    if post_residual > 0 && post_residual < 10 {
        score += 6.0;
    }

    // Lookahead: strongly reward if the next item fits exactly into post_residual,
    // reward if it fits at all, penalize otherwise.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            score -= 10.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            score += 4.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Crowding pressure: when many bins are open, discourage new bins and
    // prefer consolidating into existing ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins already open or late in stream.
        score += 8.0 + 0.3 * open_bins_count as f64 + 6.0 * progress;
        // But if the item is large relative to mean residual of open bins,
        // opening a fresh bin is more attractive.
        if (mean_residual + 0.001) < item_size as f64 {
            score -= 12.0;
        }
    } else {
        // Existing bin: mild bonus for placing into bins with residual close to mean
        // (keeps bin residuals balanced, preserving flexibility).
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.05 * dev;
    }

    // Slight preference for emptier bins early on (flexibility), tighter bins later.
    let emptiness = bin_residual as f64 / bin_capacity as f64;
    score += (0.5 - progress) * 4.0 * emptiness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Normalized post-residual within capacity
    let pr = post_residual as f64 / bin_capacity as f64;

    // Smooth non-linear coupling: dead space penalized more as stream progresses
    let dead_space_penalty = pr * pr * (0.5 + 2.0 * progress);
    score += 40.0 * dead_space_penalty;

    // Reward tight fits, amplified late in stream
    let tightness = 1.0 - pr;
    score -= 30.0 * tightness * tightness * (0.5 + progress);

    // Penalize very small residuals that are unlikely to be usable later
    let unusable = (pr - 0.1) * (pr - 0.1);
    score += 25.0 * unusable * (1.0 + progress);

    // Last-chance bin: strong reward to use it rather than open a new one
    if fitting_bins_count == 1 {
        score -= 20.0 + 15.0 * progress;
    }

    // Prefer bins with residual below mean (fill fuller bins first), smoothly
    let mean_gap = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    score += 10.0 * mean_gap * (0.5 + progress);

    // Lookahead: if next item fits exactly in post-residual, reward heavily
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 50.0;
        } else if post_residual > next_item_size {
            score -= 10.0 * (post_residual - next_item_size) as f64 / bin_capacity as f64;
        } else {
            score += 8.0 * (next_item_size - post_residual) as f64 / bin_capacity as f64;
        }
    }

    // Mild pressure against accumulating many open bins
    score += 0.5 * open_bins_count as f64 * pr;

    // New-bin candidate: penalize opening a new bin unless current fit is bad
    if bin_residual == bin_capacity {
        let fit_quality = 1.0 - (item_size as f64 / bin_capacity as f64);
        score += 15.0 + 35.0 * fit_quality * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: how "usable" is the dead space?
    // Class 0: perfect fit (post_residual == 0) -> strong reward.
    // Class 1: leftover can hold small items (<= 10) -> mild reward.
    // Class 2: leftover is awkward (> 10, < 30) -> penalize.
    // Class 3: leftover is roomy (>= 30) -> mild penalty (waste of big space).
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual <= 10 {
        score -= 30.0;
    } else if post_residual < 30 {
        score += 25.0;
    } else {
        score += 10.0;
    }

    // Integer-division harmonic classes on post_residual in units of 10:
    // leftovers that are exact multiples of 10 are more reusable.
    let pr_class = post_residual / 10;
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 8.0 * pr_class as f64;
    }

    // Lookahead coupling: if the next item fits exactly into the post residual,
    // this is a golden chain placement -> big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 120.0;
        } else if next_item_size <= post_residual {
            // next item fits: leftover after chain matters
            let chain_left = post_residual - next_item_size;
            if chain_left <= 10 {
                score -= 40.0;
            } else {
                score -= 15.0;
            }
        } else {
            // next item cannot use this leftover: penalize proportionally
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && post_residual < bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate handling: an empty bin has huge residual; make it
    // attractive only when the current item is large relative to capacity
    // (large items deserve fresh bins) and no tight fit exists elsewhere.
    if bin_residual == bin_capacity {
        let frac = item_size as f64 / bin_capacity as f64;
        // base cost of opening a bin
        score += 100.0;
        // large items justify fresh bins; small items should never open bins
        score -= frac * 90.0;
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            // room for the next item in the fresh bin
            score -= 20.0;
        }
    }

    // Tight-fit reward: item fills most of the bin
    let fill = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill * 20.0;

    // Stream progression: later in the stream, be greedier about tight fits
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * (100.0 - post_residual as f64) * 0.3;

    // Mild tie-breaker toward fewer open bins
    score += open_bins_count as f64 * 0.5;

    // Mean-residual context: when mean residual is low, preserve roomy bins
    if post_residual as f64 > mean_residual {
        score += 5.0;
    } else {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small for the smallest
    // plausible item are worthless. Penalize them quadratically.
    let dead_threshold = 12.0f64;
    if (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 6.0;
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    } else if post_residual <= 10 {
        score -= 12.0;
    }

    // Penalize leaving a gap that cannot fit the lookahead item either:
    // the residual becomes truly dead space.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 18.0 + 0.25 * (next_item_size - post_residual) as f64;
    }

    // Conversely, reward a residual that still accommodates the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    }

    // Open-bin pressure: discourage spreading across many bins unless the
    // fit is genuinely tight.
    score += 1.5 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when this bin's fit is poor
    // (large post_residual) or the bin residual is already awkwardly small.
    if bin_residual == bin_capacity {
        let mean_gap = post_residual as f64 - mean_residual;
        if post_residual as f64 > mean_residual + 10.0 {
            score -= 20.0 + 0.3 * mean_gap.max(0.0);
        } else {
            score += 15.0;
        }
        // Early in the stream, opening fresh bins is cheap and useful.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * (1.0 - progress);
    } else if bin_residual < 20 {
        // Awkwardly small residual: using it now clears a nearly-dead bin.
        score -= 10.0;
    }

    // Mild preference for bins whose residual is close to the mean
    // (keeps the bin pool homogeneous and flexible).
    score += 0.1 * ((bin_residual as f64 - mean_residual).abs());

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), with superlinear dead-space penalty.
    let post = post_residual as f64;
    score += 0.35 * (post * post) / bin_capacity as f64;

    // 2-step lookahead: reward when the next item exactly or nearly fills the post residual.
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = (post_residual - next_item_size) as f64;
        // Perfect match: big reward.
        if gap == 0.0 {
            score -= 45.0;
        } else {
            // Reward closeness of next item to post residual (tight 2-step chain).
            let closeness = 1.0 - gap / bin_capacity as f64;
            score -= 25.0 * closeness * closeness;
        }
    } else if next_item_size > 0 {
        // Next item cannot fit here: penalize creating dead space the next item can't use,
        // scaled by how much waste relative to mean residual.
        let waste = post - next_item_size as f64;
        score += 0.15 * waste.max(0.0);
    }

    // Relative-to-mean coupling: bins tighter than average are valuable; looser bins less so.
    let dev = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    score += 12.0 * dev;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate handling: keep empty bin moderately attractive early,
    // but discourage opening new bins when many bins are open and fit is decent.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Empty bin baseline: slightly worse than a good fit, better than a bad one.
        score = bin_capacity as f64 * 0.55 + 10.0 * (1.0 - progress) - 0.05 * open_bins_count as f64;
        // If next item is huge, opening fresh bin may be wise.
        if next_item_size > 0 && next_item_size >= post_residual.max(1) && next_item_size > bin_capacity / 2 {
            score -= 8.0;
        }
    }

    // Late-stream consolidation: favor filling existing bins as stream ends.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 6.0 * progress * (1.0 - post / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize small post_residual more strongly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize dead space that is too small to be useful (unusable gap).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 {
        score -= 40.0;
    } else if fitting_bins_count >= 2 {
        score += 3.0 * (fitting_bins_count as f64 - 1.0).min(5.0);
    }

    // Lookahead: if next item can fit into the post-residual, reward this bin.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0;
        } else if next_item_size <= post_residual + 5 {
            score -= 5.0;
        } else {
            // Next item won't fit here; slight penalty for wasting capacity.
            score += 4.0;
        }
    }

    // Time horizon: early in stream, be more conservative (prefer filling existing
    // bins to keep open-bin count low); late in stream, exploit exact fits.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * t * tightness;

    // Global state coupling: if many bins are open with high mean residual,
    // discourage opening/using loosely-fitting bins; prefer consolidation.
    let mean_resid_norm = mean_residual / bin_capacity as f64;
    if mean_resid_norm > 0.5 && open_bins_count > 3 {
        score += 8.0 * (mean_resid_norm - 0.5);
    }

    // Prefer bins whose residual is close to the item (perfect proportional fit).
    let fit_gap = (bin_residual as f64 - item_size as f64).abs();
    score += 0.15 * fit_gap;

    // Mild bonus for using a bin with residual near half capacity (versatile zone).
    let half = bin_capacity as f64 / 2.0;
    if (bin_residual as f64 - half).abs() < 10.0 {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_norm = pr / cap;

    // Base: prefer tight fits via non-linear (quadratic + cubic) coupling of post_residual
    let mut score = pr * (1.0 + 0.8 * fit_norm * fit_norm + 0.6 * fit_norm * fit_norm * fit_norm);

    // Dead-space penalty grows with stream progress (smooth cubic ramp)
    let dead = fit_norm * fit_norm * fit_norm;
    score += 35.0 * progress * dead;

    // Reward using nearly-full bins, stronger later in the stream
    score -= (1.0 - fit_norm) * (1.0 - fit_norm) * (10.0 + 25.0 * progress);

    // Last-chance bonus: if this is the only fitting bin, strongly favor it
    if fitting_bins_count == 1 {
        score -= 40.0 + 30.0 * progress;
    }

    // Lookahead: penalize leaving residual that barely fails to fit next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr < nxt {
            let gap = (nxt - pr) / cap;
            score += 20.0 * gap * gap * (1.0 - progress);
        } else {
            let slack = (pr - nxt) / cap;
            score -= 8.0 * (1.0 - slack) * (0.5 + 0.5 * progress);
        }
    }

    // Mild penalty for spreading across too many open bins relative to mean residual
    score += 0.15 * (open_bins_count as f64).ln().max(0.0) * fit_norm;

    // Alignment with mean residual: prefer bins near the average load state
    let dev = (pr - mean_residual) / cap;
    score += 5.0 * dev * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify leftover space by capacity fraction.
    // Class 0: perfect fit (post_residual == 0) -> strong reward.
    // Class 1: tiny dead space (1..=10) -> strong penalty (unusable).
    // Class 2: small (11..=25) -> mild penalty.
    // Class 3: medium (26..=50) -> neutral-ish.
    // Class 4: large (>50) -> reward, bin stays reusable.
    let class = if post_residual == 0 {
        0u8
    } else if post_residual <= 10 {
        1
    } else if post_residual <= 25 {
        2
    } else if post_residual <= 50 {
        3
    } else {
        4
    };

    match class {
        0 => score -= 60.0,
        1 => score += 35.0,
        2 => score += 12.0,
        3 => score -= 2.0,
        _ => score -= 10.0,
    }

    // Modulo coupling: leftover that is a multiple of 10 (common item quantum)
    // is more likely reusable by future items.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 8.0;
    }

    // Lookahead: does next_item_size fit into post_residual? Reward if yes.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack = post_residual - next_item_size;
            score -= 15.0 + (slack as f64).min(20.0) * 0.3;
        } else {
            // Next item won't fit here; penalize small leftovers more.
            score += (post_residual as f64) * 0.15;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible (tiny post_residual).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        if post_residual >= 10 {
            score -= 20.0;
        } else {
            score += 5.0;
        }
    }

    // New-bin candidate: penalize opening a new bin, more when many bins are open
    // and mean residual is large (fragmentation already high).
    if bin_residual == bin_capacity {
        score += 25.0 + 0.5 * mean_residual + 2.0 * (open_bins_count as f64).sqrt();
        // But if the item is huge, a fresh bin is fine (it will consume most capacity).
        if item_size >= 60 {
            score -= 20.0;
        }
    }

    // Progress-aware: late in the stream, prefer tight fits (consolidate).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (bin_capacity - post_residual) as f64 * 0.05 * progress;

    // Mean residual coupling: when open bins are already loose, tighten selection.
    score += (mean_residual - post_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals below the minimum item size are pure waste.
    let min_item = 1u32;
    if post_residual < min_item {
        score -= 1000.0; // perfect fill: residual becomes zero or unusable is good only if zero
        if post_residual == 0 {
            score -= 500.0;
        } else {
            score += 1000.0; // tiny unusable gap: worst outcome
        }
    }

    // Penalize "danger zone" residuals: too small for typical items but nonzero.
    if post_residual > 0 && post_residual < 10 {
        score += 150.0;
    } else if post_residual >= 10 && post_residual < 25 {
        score += 60.0;
    }

    // Reward tight fits (small waste relative to item size).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 40.0 * tightness;

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 80.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (open_bins_count as f64).ln().max(0.0) * 8.0 * (0.5 + progress);

    // Deviation from mean residual: prefer bins already below-average full (larger residual)
    // so small leftovers consolidate? No — prefer bins with SMALL residual to empty them.
    let dev = mean_residual - bin_residual as f64;
    score += 0.5 * dev; // lower bin_residual (more full) => positive dev => lower score => favored

    // Lookahead: if next item fits exactly in the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        score -= (30.0 - gap as f64).max(0.0);
    }
    // If next item would leave a dead gap, penalize mildly.
    if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size < 5 {
        score += 20.0;
    }

    // New-bin candidate: make it attractive only when existing fits are poor.
    if bin_residual == bin_capacity {
        // base cost of opening a bin; overridden when dead-space penalties dominate above
        score += 25.0 + 10.0 * (open_bins_count as f64).ln().max(0.0);
        // but if the item is large relative to capacity, a fresh bin is often fine
        if item_size as f64 > 0.6 * bin_capacity as f64 {
            score -= 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: if next item exactly fills post_residual, big reward
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            // next item fits: reward proportional to how well it fills
            let fill_after = (post_residual - next_item_size) as f64;
            score -= 200.0 * (1.0 - fill_after / bin_capacity as f64);
        } else {
            // next item won't fit here: penalize large dead space
            score += 50.0 * (post_residual as f64 / bin_capacity as f64);
        }
    }

    // Penalize small unusable residuals (dead space below min item size)
    if post_residual > 0 && post_residual < 10 {
        score += 300.0;
    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 {
        score -= 150.0;
    }

    // Relative to mean residual: prefer tighter-than-average bins
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Slight preference to fill existing bins over opening new ones
    if bin_residual == bin_capacity {
        score += 40.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to item size)
    if item_size > 0 {
        score -= (item_size as f64) * (1.0 - post_residual as f64 / bin_capacity as f64) * 0.5;
    }

    // Penalize dead space that is too small for typical future items
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward heavily
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            score -= (next_item_size as f64 / post_residual as f64) * 10.0;
        } else {
            // next item won't fit here; slight penalty proportional to wasted potential
            score += ((next_item_size as f64 - post_residual as f64) / bin_capacity as f64) * 5.0;
        }
    }

    // Prefer filling bins with large residuals when many bins are open
    score += (mean_residual - post_residual as f64) * 0.3;

    // Early in the stream, be more willing to open new bins (favor empty bin candidate)
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // new-bin candidate: penalize less early, more late
        score += 20.0 * (1.0 - progress) - 10.0 * progress;
        // discourage opening a new bin when an existing bin would be nearly perfect
        if post_residual < 15 {
            score += 50.0;
        }
    }

    // Dynamic coupling: with many open bins, consolidate (prefer bins below mean residual)
    if open_bins_count > 3 {
        score += (open_bins_count as f64).ln() * (bin_residual as f64 - post_residual as f64) * 0.05;
    }

    // Non-linear waste penalty: squared small residual
    if post_residual < 30 {
        score += (30 - post_residual) as f64 * 0.4;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Reward tight fits: squared normalized fill fraction coupling
    let fill = 1.0 - pr / cap;
    score -= 40.0 * fill * fill;

    // Non-linear progress coupling: later in stream, penalize residual waste more strongly
    let prog_term = progress * progress * (1.0 - progress);
    score += 20.0 * prog_term * pr / cap;

    // Lookahead: penalize if next item cannot fit the post residual (dead space)
    if next_item_size > 0 {
        if (next_item_size as f64) > pr {
            score += 15.0 + 10.0 * (next_item_size as f64 - pr) / cap;
        } else {
            // Reward if next item fits snugly
            let snug = 1.0 - (pr - next_item_size as f64) / cap;
            score -= 12.0 * snug * snug;
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive if open bins fit poorly
    if bin_residual == bin_capacity {
        let avg_waste = mean_residual / cap;
        score += 30.0 + 25.0 * avg_waste * (1.0 - progress);
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
    }

    // Mild penalty when many open bins already (consolidation pressure)
    score += (open_bins_count as f64).ln().max(0.0) * 2.0 * (pr / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Harmonic class of post-residual: perfect fits (0) are gold;
    // tiny residues (<10) are near-dead; mid residues are reusable.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 10 {
        score += 8.0; // dead space penalty
    } else {
        // quantize post_residual into harmonic bands of 10
        let band = post_residual / 10;
        score -= band as f64 * 1.5;
    }

    // Lookahead coupling: does the next item fit the post-residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // exact harmonic match is highly desirable
            if post_residual % next_item_size.max(1) == 0 {
                score -= 12.0;
            } else {
                score -= 5.0;
            }
            // reward leaving room proportional to next item size
            score -= (next_item_size as f64 / cap) * 6.0;
        } else {
            // next item won't fit here: penalize tight leftovers
            score += 3.0;
        }
    } else {
        // last item: prefer perfect packing
        score -= 5.0;
    }

    // Last-chance bin: strongly favor using it to avoid a new bin
    if fitting_bins_count == 1 {
        score -= 10.0;
    }

    // New-bin candidate: only attractive when open bins are crowded
    if bin_residual == bin_capacity {
        let crowd = open_bins_count as f64;
        score += 15.0;                       // base reluctance to open new bin
        score -= crowd * 0.8;                // many open bins -> spread is fine
        if mean_residual < item_size as f64 {
            score -= 10.0;                   // nothing useful open anyway
        }
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            score -= 4.0;                    // big next item, fresh bin helps
        }
    }

    // Progress-aware tightening: late in the stream, waste matters more
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * (pr / cap) * 4.0;

    // Slight preference for tighter existing bins
    score += (bin_residual as f64 - pr) / cap * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 8.0; // gap 1 => +72, gap 9 => +8
    }
    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward residuals that can still host the next item (lookahead k=2).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
        // Extra reward if next item fits *exactly* into the post residual.
        if post_residual == next_item_size {
            score -= 18.0;
        }
    } else if next_item_size > 0 {
        // Post residual too small for the next item: penalize proportionally.
        score += (next_item_size - post_residual) as f64 * 0.6;
    }

    // Open-bin pressure: discourage spreading across many bins unless fit is good.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (1.5 + 2.0 * progress);

    // Deviation from mean residual: prefer bins whose residual is near the mean
    // (keeps residuals homogeneous and reusable).
    score += (post_residual as f64 - mean_residual).abs() * 0.4;

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when no open bin is a decent fit.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 30.0 + open_bins_count as f64 * 2.0;
        // If other bins fit but are poor (large mean residual), opening can win.
        if fitting_bins_count > 0 && mean_residual > 45.0 {
            score -= (mean_residual - 45.0) * 1.2;
        }
        // Early in the stream, opening fresh bins is cheaper.
        score -= (1.0 - progress) * 10.0;
        // If the next item is large, a fresh bin gives flexibility.
        if next_item_size > 60 {
            score -= 8.0;
        }
    }

    // Slight preference for tighter fits overall.
    score += (bin_residual - item_size) as f64 * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match between post_residual and next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let post = post_residual as f64;
        let diff = (post - nxt).abs();
        if diff < 0.5 {
            score -= 60.0; // perfect 2-step match: next item fills bin exactly
        } else if post >= nxt {
            score -= 25.0 * (1.0 - diff / bin_capacity as f64);
        } else {
            // next item won't fit: penalize proportionally to how much it misses
            score += 10.0 + 0.5 * (nxt - post);
        }
    }

    // Penalize dead space relative to mean residual of open bins
    score += 0.3 * (post_residual as f64 - mean_residual).max(0.0);

    // Reward tight fits relative to current residual
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * fill_ratio * fill_ratio;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when no open bin fits well
    if bin_residual == bin_capacity {
        score = 150.0 + post_residual as f64;
        if fitting_bins_count == 0 {
            score = 0.0; // forced new bin
        } else if fitting_bins_count == 1 {
            score = 120.0; // discourage new bin when a lone bin can fit
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (post_residual small relative to item).
    let tight = (post_residual as f64) / (item_size.max(1) as f64);
    score += 6.0 * tight;

    // Last-chance bin: strong bonus to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if next item fits exactly into the post residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 8.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // dead space created that next item cannot use
            score += 0.15 * (next_item_size - post_residual) as f64;
        }
    }

    // Prefer bins with residual below mean (denser bins) mildly.
    score += 0.3 * (bin_residual as f64 - mean_residual).max(-50.0).min(50.0);

    // Penalize leaving very small unusable slivers.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // New-bin candidate handling: only attractive when no good fits exist.
    if bin_residual == bin_capacity {
        let pressure = (open_bins_count as f64) * (item_size as f64) / (bin_capacity as f64);
        let late = step_index as f64 / (total_items.max(1) as f64);
        // Default penalty so we prefer existing bins; relax if few fitting bins.
        let mut newbin = 20.0 + 10.0 * (1.0 - late);
        if fitting_bins_count <= 1 {
            newbin -= 18.0;
        }
        if pressure < 1.0 {
            newbin += 5.0;
        }
        score = newbin;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (0.5 + 1.5 * progress) + norm_pr * (1.0 - progress);

    let mut score = pr + 40.0 * poly;

    // Reward tight fits, more strongly later in the stream
    let tightness = 1.0 - norm_pr;
    score -= (1.0 + 2.0 * progress) * tightness * tightness * 10.0;

    // Penalize waste relative to mean residual across open bins
    score += (pr - mean_residual) * (0.3 + 0.7 * progress);

    // Lookahead: reward leaving space for the next item, penalize blocking it
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            score -= 8.0 * (1.0 - (pr - nx) / cap);
        } else {
            score += 6.0 + (nx - pr) * 0.2;
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0 * (1.0 + progress);
    }

    // Mild penalty for many open bins to encourage consolidation
    score += open_bins_count as f64 * 0.5 * progress;

    // New-bin candidate: discourage unless residuals are mostly unusable
    if bin_residual == bin_capacity {
        score += 12.0 - 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // ---- Harmonic class of the post residual: classify leftover space ----
    // Classes via integer division thresholds: tiny (0..=10), small (11..=25),
    // medium (26..=50), large (>50). Reward tiny leftovers (near-perfect fit).
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect closure
    } else if pr <= 10 {
        score -= 35.0;
    } else if pr <= 25 {
        score -= 18.0;
    } else if pr <= 50 {
        score -= 5.0;
    } else {
        // large dead space: penalize superlinearly
        score += 0.35 * (pr as f64 - 50.0);
    }

    // ---- Modulo arithmetic on residuals: harmonic residue classes mod 10 ----
    // Items/residuals in the same decade class pack well together.
    let res_class = pr % 10;
    if res_class == 0 {
        score -= 8.0; // round residual is reusable by many item sizes
    } else if res_class <= 3 {
        score -= 3.0; // small sliver, still usable by tiny items
    } else {
        score += 1.5; // awkward remainder
    }

    // ---- Lookahead coupling: does next_item_size fit into post_residual? ----
    if next_item_size > 0 {
        if next_item_size <= pr {
            // next item can be chained into this bin: strong reward,
            // scaled by how "snug" the chain is (harmonic class of the pair)
            let chain_left = pr - next_item_size;
            let snug = if chain_left <= 5 { 22.0 } else if chain_left <= 15 { 14.0 } else if chain_left <= 30 { 7.0 } else { 2.0 };
            score -= snug;
        } else {
            // next item won't fit here: if this bin would become a dead-end
            // for the lookahead, add mild penalty proportional to gap class
            let gap = next_item_size - pr;
            if gap <= 10 {
                score += 4.0;
            } else {
                score += 1.0;
            }
        }
    }

    // ---- Last-chance bin logic ----
    if fitting_bins_count == 1 && bin_residual >= item_size {
        // this is the only bin that fits; opening a new bin would waste
        // bin_residual entirely -> reward using it, scaled by wasted space avoided
        score -= 12.0 + 0.1 * (bin_residual as f64 - item_size as f64);
    }

    // ---- New-bin candidate handling (bin_residual == bin_capacity) ----
    if bin_residual == bin_capacity {
        // A fresh bin has post_residual = C - item. Compare that leftover
        // against mean residual of open bins: prefer new bin only if the
        // open-bin pool is already fragmented (high mean residual) or full.
        let fragmentation = (mean_residual / cap).clamp(0.0, 1.0);
        // pressure grows as open bins accumulate
        let pressure = (open_bins_count as f64 / 8.0).min(1.0);
        // base cost of a new bin
        score += 25.0;
        // discount the new bin when open bins are fragmented and plentiful
        score -= 20.0 * fragmentation * pressure;
        // if item is small, new bin wastes a lot of capacity -> extra penalty
        if item_size <= 30 {
            score += 10.0;
        }
        // late in the stream, prefer closing bins rather than opening more
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 8.0 * progress;
    }

    // ---- Global residual coupling: keep bin residuals near the pool mean ----
    // Placing into a bin whose residual deviates strongly from the mean
    // either strands outliers or over-concentrates space.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // ---- Tight-fit bonus via harmonic fraction of item in bin ----
    let fill_frac = item_size as f64 / cap;
    if fill_frac >= 0.8 {
        score -= 10.0; // big item nearly fills bin: excellent
    } else if fill_frac >= 0.5 {
        score -= 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: small gaps (<= 10) are nearly unusable since min item is 1,
    // but gaps that can't fit the next item are especially wasteful.
    if post_residual > 0 {
        let dead = if post_residual < 10 {
            40.0 * (10.0 - post_residual as f64) / 10.0
        } else {
            0.0
        };
        score += dead;
    }

    // Reward tight fits (small post_residual relative to bin).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 25.0 * tightness * tightness;

    // If this bin is the last chance to fit, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 60.0;
    }

    // Lookahead: if the next item fits exactly in the post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size < 10 {
        score -= 30.0;
    }
    // Penalize if post_residual can't fit the next item but is > 0 (wasted for lookahead).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 10.0;
    }

    // Open-bin pressure: when many bins are open, discourage opening new ones;
    // when few bins are open, a new bin is cheap.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses and bins accumulate.
        score += 35.0 + 45.0 * progress + 2.0 * open_bins_count as f64;
    } else {
        // Mild reward for consolidating into existing bins when many are open.
        score -= (open_bins_count as f64).ln().max(0.0) * 3.0;
    }

    // Prefer bins whose residual is above the mean (balance residuals across bins).
    let dev = bin_residual as f64 - mean_residual;
    score += 0.15 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 2-step lookahead: reward when next item fits exactly into post_residual
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack_after_next = post_residual - next_item_size;
            // perfect chain match: big reward
            if slack_after_next == 0 {
                score -= 50.0;
            } else {
                // reward proportional to how tight the chain is, penalize large dead space
                score -= 30.0 - (slack_after_next as f64).min(30.0);
            }
        } else {
            // next item cannot fit here: penalize leaving dead space
            score += 15.0;
        }
    }

    // Tight fit reward relative to mean residual
    let tightness = (bin_capacity as f64 - post_residual as f64) / bin_capacity as f64;
    score -= 10.0 * tightness;

    // Prefer bins whose residual is close to mean (avoid extreme outliers)
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.1 * dev;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when nothing good exists; make it costly
    if bin_residual == bin_capacity {
        score += 60.0;
        // early in stream, new bins are cheaper
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 30.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: quadratic bonus for small post-residual.
    score -= (bin_capacity as f64 - post_residual as f64) * (bin_capacity as f64 - post_residual as f64) * 0.01;

    // Dead-space penalty: post-residual that cannot fit the next item is wasted.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.8;
        } else {
            // Bonus if next item fits exactly into the new residual.
            if post_residual == next_item_size {
                score -= 15.0;
            }
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a bin unless current residuals are poor fits.
    if bin_residual == bin_capacity {
        let waste_now = if next_item_size > 0 && post_residual < next_item_size { 1.0 } else { 0.0 };
        score += 30.0
            - mean_residual * 0.5
            - (post_residual as f64) * 0.15
            + waste_now * 10.0
            + (open_bins_count as f64) * 0.5;
    } else {
        // Favor bins whose residual deviates from the mean (exploit diversity).
        let dev = (bin_residual as f64 - mean_residual).abs();
        score -= dev * 0.05;
    }

    // Time horizon: early in the stream, be conservative about fragmenting bins;
    // late in the stream, accept tighter packing more aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.2 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let r = bin_residual as f64;
    let it = item_size as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fill = it / cap;
    let norm_pr = pr / cap;

    // Base: quadratic waste penalty on post-residual (dead space grows quadratically)
    let mut score = 3.0 * norm_pr * norm_pr + 1.0 * norm_pr;

    // Smooth non-linear coupling of post-residual with stream progress:
    // early on, tolerate large residuals; late, punish them harder.
    let late = progress * progress;
    score += (0.5 + 6.0 * late) * norm_pr * norm_pr;

    // Reward tight fits: interaction between fill ratio and post-residual smallness
    let tight = (-norm_pr).exp();
    score -= 2.5 * fill * tight;

    // Penalize bins whose residual is much larger than the mean residual
    // (avoid scattering), smooth via tanh coupling.
    let dev = (r - mean_residual) / cap;
    score += 1.2 * dev.tanh() * norm_pr;

    // Last-chance bonus: if this is the only fitting bin, strongly reward placement
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 4.0 * (1.0 - norm_pr);
    }

    // New-bin candidate handling: prefer reusing open bins early/mid stream,
    // but allow opening new bins when the item is large and fits would leave
    // fragmented residuals across many bins.
    if bin_residual == bin_capacity {
        let fragmentation = (open_bins_count as f64).ln().max(0.0);
        let lookahead_waste = if next_item_size > 0 {
            ((next_item_size as f64) - pr).max(0.0) / cap
        } else {
            0.0
        };
        // Opening a new bin is attractive when existing fits would waste a lot
        // for the next item or when few bins are open.
        score = 2.0 + norm_pr * 0.5
            - 1.5 * lookahead_waste
            + 0.6 * fragmentation * (1.0 - progress)
            + 3.0 * late * (1.0 - fill);
    } else {
        // Lookahead: smooth reward if the next item fits into the post-residual
        if next_item_size > 0 {
            let nx = next_item_size as f64;
            let fits_next = (pr - nx).max(0.0) / cap;
            let gap = (nx - pr).max(0.0) / cap;
            score += 1.0 * fits_next * fits_next - 0.8 * (-8.0 * gap).exp();
        }
        // Mild penalty for spreading across many open bins
        score += 0.05 * (open_bins_count as f64).sqrt() * norm_pr;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
