pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps are the worst outcome.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 - 3.0 * post_residual as f64;
    }
    if post_residual == 0 {
        score -= 25.0; // perfect fit: strongly reward
    }

    // Reward leaving room for the lookahead item (k=2 lookahead).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 5.0; // gap neither empty nor usable by next item
    }

    // Perfect-fit-on-new-bin is fine, otherwise discourage opening new bins.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 30.0 + 2.0 * open_bins_count as f64;
        if post_residual == 0 {
            score -= 55.0; // item exactly fills a fresh bin
        }
    }

    // Last-chance bin: strong penalty for wasting it on a loose fit.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 12.0;
    }

    // Prefer bins with larger residuals when fits are loose (best-fit fallback).
    score -= 0.3 * bin_residual as f64;

    // Mild stream-progression pressure to consolidate late in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 3.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong base penalty for leftover space, weighted by stream progress.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 0.5 * (post_residual as f64 / bin_capacity as f64) * (1.0 + progress);

    // --- 2-step lookahead: reward exact/near matches of next_item_size into post_residual ---
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            // Perfect chain match: big bonus.
            if slack == 0.0 {
                score -= 40.0 + 20.0 * progress;
            } else {
                // Reward closeness of next item to post_residual (tight chaining).
                let tightness = 1.0 - slack / bin_capacity as f64;
                score -= 15.0 * tightness * tightness;
            }
            // Extra bonus if that leaves a small-but-usable residual for future items.
            if slack > 0.0 && slack <= 20.0 {
                score -= 5.0;
            }
        } else {
            // Next item cannot fit here: dead-end residual, penalize unless residual is tiny.
            let gap = (next_item_size - post_residual) as f64;
            score += 3.0 + 0.1 * gap;
            if post_residual > 40.0 {
                // Large unusable chunk wasted.
                score += 0.15 * post_residual as f64;
            }
        }
    }

    // --- Relative to mean residual: prefer bins that are already below-average filled ---
    // (packing into emptier bins keeps tight bins for tight items).
    let dev = (post_residual as f64 - mean_residual) / bin_capacity as f64;
    score += 4.0 * dev;

    // --- Last-chance bin: if this is the only bin that fits, strongly prefer using it ---
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // --- New-bin candidate handling: only open a new bin when no good fit exists ---
    if bin_residual == bin_capacity {
        // Default cost of opening a new bin.
        score += 60.0;
        // But if the item is huge and nothing tight is available, opening is fine.
        if item_size >= 70 && post_residual <= 30.0 {
            score -= 55.0;
        }
        // Lookahead: if next item is large and this item would leave no room anyway,
        // opening a fresh bin enables a clean chain.
        if next_item_size > 0 && post_residual < next_item_size && post_residual <= 10.0 {
            score -= 30.0;
        }
        // Late in the stream, avoid proliferating bins with tiny contents.
        if progress > 0.8 && open_bins_count > 3 {
            score += 20.0 * progress;
        }
    }

    // Mild preference to fill nearly-full bins (small residual => low score).
    if post_residual <= 10 {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: squaring post_residual amplifies large waste.
    score += (post_residual as f64).powi(2) / (bin_capacity as f64);

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Lookahead: penalize placements that leave a residual unusable by the next item,
    // reward placements where the next item nests perfectly into the leftover.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Next item could still fit here; mild reward, stronger if exact.
            if post_residual == next_item_size {
                score -= 45.0;
            } else {
                score -= 8.0 * (next_item_size as f64 / bin_capacity as f64);
            }
        } else {
            // Dead space for the known next item.
            score += 12.0 * (1.0 - (post_residual as f64 / next_item_size as f64).min(1.0));
        }
    } else {
        // Last item: just minimize waste.
        score -= 5.0;
    }

    // Penalize opening a new bin, more so when many bins are already open
    // and when their mean residual suggests consolidation is possible.
    if bin_residual == bin_capacity {
        score += 25.0 + 2.0 * (open_bins_count as f64);
        score += 0.5 * (mean_residual - post_residual as f64).max(0.0);
    } else {
        // Slight reward for using existing bins as the stream progresses
        // (early stream: allow exploration of multiple open bins).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 5.0 * progress;
    }

    // Prefer bins whose residual is below mean (consolidate the emptier space).
    if bin_residual != bin_capacity {
        score += 0.3 * (bin_residual as f64 - mean_residual);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_post = post / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let p2 = progress * progress;
    let p3 = p2 * progress;
    let base = post * (1.0 + 0.6 * p2 + 0.4 * p3);

    // Smooth dead-space penalty: quadratic in normalized residual waste
    let dead = 12.0 * norm_post * norm_post * (1.0 + progress);

    // Tight-fit reward: smooth Gaussian-like coupling of post_residual to next item
    let nxt = next_item_size as f64;
    let mut tight = 0.0;
    if nxt > 0.0 {
        let d = (post - nxt) / cap;
        tight = -6.0 * (-d * d * 40.0).exp();
    }

    // Scarcity pressure: smooth function of fitting bins
    let scarcity = if fitting_bins_count <= 1 { -8.0 * (1.0 - progress) } else { 0.0 };

    // Mild attraction toward bins with residuals near mean (balance)
    let dev = (post - mean_residual) / cap;
    let balance = -2.0 * (-dev * dev * 8.0).exp();

    // New-bin candidate: penalize slightly so it's chosen only for poor fits
    let new_bin_penalty = if bin_residual == bin_capacity { 3.0 + 5.0 * progress } else { 0.0 };

    let mut score = base + dead + tight + scarcity + balance + new_bin_penalty;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Base: prefer tight fits (best-fit core).
    score -= 8.0 * (1.0 - (post_residual as f64) / cap);

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Harmonic class: residual capacity classes via integer division.
    // Class the post-residual into deciles of capacity; small classes are good.
    let class = post_residual / (bin_capacity / 10).max(1);
    score += class as f64 * 2.5;

    // Modulo-10 harmonic: residuals divisible by common item sizes (10, 20, 25, 50)
    // are more likely to be exactly filled by future items.
    let pr = post_residual;
    if pr > 0 && (pr % 10 == 0 || pr % 25 == 0 || pr % 50 == 0) {
        score -= 6.0;
    }

    // Lookahead coupling: if next item fits the post-residual exactly, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 40.0;
        } else if next_item_size <= pr {
            let slack = (pr - next_item_size) as f64;
            // Harmonic threshold: slack below 10 is a near-perfect chain.
            if slack < 10.0 {
                score -= 15.0;
            } else {
                score += slack * 0.15;
            }
        } else {
            // Next item cannot use leftover: penalize proportionally.
            score += (next_item_size - pr) as f64 * 0.05;
        }
    }

    // Dead-space penalty: post-residual below the minimum item size (1..100 unknown,
    // assume small items possible) — but penalize unusable slivers hard.
    if pr > 0 && pr < 5 {
        score += 25.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: make opening a new bin attractive only when
    // existing fits are poor (large post_residual) or many bins already open.
    if bin_residual == bin_capacity {
        // New bin gets post_residual = cap - item_size; neutral base plus
        // a mild preference so it wins only when open-bin fits are bad.
        score -= 3.0 + (open_bins_count as f64).sqrt() * 2.0;
        if next_item_size > 0 && next_item_size <= pr && pr >= 50 {
            score -= 5.0;
        }
    } else {
        // Mild penalty for stuffing bins when many are open, to keep spread.
        score += (open_bins_count as f64) * 0.3;
    }

    // Progress-based tilt: late in the stream, consolidation matters more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 4.0;

    // Mean-residual anchoring: bins far below mean residual are underused.
    score += ((mean_residual - post_residual as f64) * 0.05).max(-5.0).min(5.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize unusable small gaps heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 15.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 200.0;
    }

    // Fit that leaves room for the lookahead item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 10.0;
    }

    // Open-bin pressure: discourage spreading across many bins.
    score += open_bins_count as f64 * 2.0;

    // Last-chance bin: strong reward to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: penalize so it is chosen only when fits are bad.
    if bin_residual == bin_capacity {
        score += 120.0;
    }

    // Late stream: prefer tightening existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 10.0 * (post_residual as f64 / bin_capacity as f64);

    // Prefer bins below mean residual (tighter bins).
    score += (mean_residual - bin_residual as f64) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual).
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let next = next_item_size as f64;

    // 2-step lookahead: strongly reward when next item fits into post_residual.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Perfect chain: next item exactly fills the remaining space.
            let slack_after_next = post_residual - next_item_size;
            let chain_quality = if slack_after_next == 0 {
                60.0 // perfect two-item fill
            } else {
                30.0 * (1.0 - (slack_after_next as f64) / cap)
            };
            score -= chain_quality;
        } else {
            // Next item cannot follow here; penalize proportional dead space,
            // heavier if post_residual is small (unusable fragment).
            let frag = post / cap;
            score += 15.0 * frag * frag;
        }
    } else {
        // Last item: just prefer minimal waste.
        score += 0.0;
    }

    // Compare against mean residual across open bins: bins with residual
    // below mean are scarcer resource; placing here is fine, but if this bin's
    // residual is far above mean, prefer filling the fuller bins first.
    let resid = bin_residual as f64;
    if mean_residual > 0.0 {
        let rel = (resid - mean_residual) / mean_residual;
        score += 8.0 * rel.max(-2.0).min(2.0);
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor it
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless current item is
    // large and no open bin offers a good (tight) fit.
    if bin_residual == bin_capacity {
        let tightness = (item_size as f64) / cap;
        // Opening is attractive only for large items (good future pairing space).
        let open_bonus = 40.0 * tightness - 20.0;
        score += 10.0 - open_bonus; // net: large items => lower score for new bin
        // Early in stream, slightly discourage hoarding many bins.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 10.0 * (1.0 - progress) * (open_bins_count as f64 / 8.0).min(1.0);
    }

    // Mild preference to keep number of open bins in check.
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: smaller post_residual relative to capacity is better.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 3.0 * tightness * tightness * (item_size as f64);

    // Penalize small dead space that likely becomes unusable (< next item size).
    if next_item_size > 0 {
        if post_residual > 0 && post_residual < next_item_size {
            score += 8.0 + 0.15 * (next_item_size - post_residual) as f64;
        }
        // Reward bins whose post_residual can still host the next item (chaining).
        if post_residual >= next_item_size && post_residual > 0 {
            score -= 2.0 * (next_item_size as f64) / (post_residual as f64);
        }
    } else {
        // Last item: just minimize waste.
        score -= 5.0 * tightness;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate logic: opening a bin is only attractive when the item
    // is large (poor candidates for later packing) or no real alternative exists.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let item_frac = item_size as f64 / bin_capacity as f64;
        let crowded = open_bins_count as f64 / (1.0 + mean_residual.max(1.0) / 10.0);
        // Penalize new bins generally; relax penalty for big items late in stream.
        score += 18.0 - 10.0 * item_frac * (0.5 + progress) - 2.0 * crowded.min(4.0);
        if fitting_bins_count <= 1 {
            score -= 10.0; // no real alternative: new bin is fine
        }
    }

    // Mild global balance: prefer bins below mean residual (keeps spread even).
    let res = bin_residual as f64;
    if res > mean_residual {
        score += 0.05 * (res - mean_residual);
    } else {
        score -= 0.05 * (mean_residual - res);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalized stream progress
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let progress = progress.clamp(0.0, 1.0);

    // Normalized post residual and item size
    let pr = post_residual as f64 / bin_capacity as f64;
    let it = item_size as f64 / bin_capacity as f64;

    // Non-linear polynomial coupling: post_residual shaped by progress
    // Early in the stream, prefer tight fills mildly; late in the stream, penalize large residuals strongly.
    let progress_shape = 1.0 + 2.0 * progress * progress;
    score += 8.0 * pr * pr * progress_shape;

    // Reward good fit: quadratic decay of score as post residual approaches zero
    let fit_quality = (1.0 - pr).powi(2);
    score -= 6.0 * fit_quality * (0.5 + it);

    // Interaction: small post-residual that still fits the next item is valuable (smooth coupling)
    if next_item_size > 0 {
        let ni = next_item_size as f64 / bin_capacity as f64;
        let fits_next = ((pr - ni) / (1.0 + ni)).max(0.0);
        score -= 4.0 * (1.0 - fits_next).powi(2) * (1.0 - pr);
    }

    // Penalize bins whose residual deviates from mean residual (smooth dispersion term)
    let dev = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    score += 3.0 * dev * dev;

    // Last-chance bonus: strongly favor the only bin that can fit the item
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else if fitting_bins_count > 2 {
        // When many bins fit, prefer tighter ones more aggressively
        score += 2.0 * (fitting_bins_count as f64).ln() * pr;
    }

    // Mild penalty for opening a new bin when open bins exist, scaled by progress
    if bin_residual == bin_capacity {
        let new_bin_penalty = 10.0 * (1.0 - 0.5 * progress);
        // But if item is large relative to capacity, opening a fresh bin is smoother
        score += new_bin_penalty - 5.0 * it * it;
    }

    // Small stream-progress drift to break ties deterministically
    score += 0.5 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify leftover space into
    // capacity-fraction buckets. Residuals that form "nice" fractions of the
    // capacity are more likely to be filled by future items.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let frac = post / cap; // 0..1

    // Class boundaries at 0, 1/4, 1/2, 3/4 of capacity.
    let class = if post_residual == 0 { 0 }
        else if frac <= 0.25 { 1 }
        else if frac <= 0.50 { 2 }
        else if frac <= 0.75 { 3 }
        else { 4 };

    // Small leftovers (class 0/1) are excellent: reward them strongly.
    match class {
        0 => score -= 60.0,
        1 => score -= 25.0,
        2 => score += 5.0,   // half-empty: mildly bad dead space
        3 => score += 15.0,
        _ => score += 25.0,  // nearly empty bin after placement: wasted placement
    }

    // Exact-fit harmonics: post_residual divisible structure (modulo classes)
    // on capacity 100. Residuals in {0, 10, 20, 25, 50} pair well with common
    // item sizes; reward those, penalize awkward residues like 1..9.
    let r = post_residual;
    if r <= 9 && r > 0 {
        score += 30.0; // unusable sliver
    }
    if r % 10 == 0 && r > 0 {
        score -= 10.0; // decade-aligned residual is reusable
    }
    if r == 50 {
        score -= 8.0;
    }
    if r == 25 || r == 75 {
        score -= 6.0;
    }

    // Lookahead coupling: if the next item fits the post residual exactly or
    // nearly, this placement chains well.
    if next_item_size > 0 {
        let gap = post_residual as i64 - next_item_size as i64;
        if gap == 0 {
            score -= 40.0; // perfect chain
        } else if gap > 0 && gap <= 10 {
            score -= 18.0;
        } else if gap < 0 && (-gap) <= 10 {
            score += 12.0; // next item just misses: dead end risk
        }
        // Harmonic class match: next item size in same decade class as residual.
        if next_item_size / 10 == r / 10 && r >= next_item_size {
            score -= 6.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using
    // it over opening a new bin (unless post residual would be a tiny sliver).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        if post_residual > 15 {
            score -= 35.0;
        } else {
            score -= 5.0;
        }
    }

    // New-bin candidate (empty bin): penalize mildly so we only open new bins
    // when no open bin gives a decent fit. Scale penalty with stream progress
    // and number of open bins (bin proliferation is costly late in the stream).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 45.0 + 20.0 * progress + 2.0 * open_bins_count as f64;
    } else {
        // Slight preference for tighter existing bins beyond raw post_residual:
        // reward filling bins that are already mostly full.
        let fill = (bin_capacity - bin_residual) as f64 / cap;
        score -= 10.0 * fill;
    }

    // Mean-residual coupling: if this bin's residual is far below the mean,
    // it is an outlier worth consuming; if far above, deprioritize.
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 8.0 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps
    // (gaps below the minimum item size 1..100 floor of 10 are pure waste;
    //  gaps that cannot fit the lookahead item are also likely waste).
    if post_residual > 0 {
        if post_residual < 10 {
            score += 60.0; // absolute dead space
        } else if next_item_size > 0 && post_residual < next_item_size {
            score += 35.0; // gap unusable by the next item
        }
    }

    // Non-linear dead-space curve: emphasize tight fits (low post_residual)
    score += (post_residual as f64).powi(2) / (bin_capacity as f64);

    // Reward using bins that are already well-filled
    let fill = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= 25.0 * fill;

    // Last-chance pressure: strongly prefer the only fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: when many bins are open, discourage opening new ones
    // (new-bin candidate has bin_residual == bin_capacity)
    if bin_residual == bin_capacity {
        score += 8.0 + 2.0 * open_bins_count as f64;
    } else {
        score -= 3.0 * open_bins_count as f64;
    }

    // Mean residual coupling: prefer bins deviating below the mean residual
    // (i.e., fuller than average bins get a bonus)
    score -= (mean_residual - bin_residual as f64).max(-30.0).min(30.0) * 0.5;

    // Lookahead synergy: if the next item fits exactly into post_residual, big reward
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 50.0;
    }

    // Mild progression term: later in the stream, tighten packing further
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * 0.3 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect or near-perfect fit (post_residual == next_item_size)
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    } else if next_item_size > 0 && post_residual > next_item_size {
        // Reward leaving exactly enough room for the next item plus small slack
        let slack = (post_residual - next_item_size) as f64;
        score -= 20.0 * (-slack / 15.0).exp();
    }

    // Penalize dead space: residuals too small for any plausible future item
    if post_residual < 10 {
        score += 25.0;
    }

    // Relative-to-mean coupling: prefer bins with residual above the mean (keeps big holes available)
    score += 0.35 * (bin_residual as f64 - mean_residual);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin unless the fit in existing bins is poor
    if bin_residual == bin_capacity {
        let tight_fit = next_item_size > 0 && post_residual == next_item_size;
        let base = if tight_fit { 0.0 } else { 30.0 };
        // As stream progresses, discourage proliferating bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += base + 20.0 * progress;
        // If many bins already open, new bins are even less attractive
        score += 2.0 * open_bins_count as f64;
    }

    // Mild preference for tighter bins overall
    score -= 0.1 * item_size as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Fractional dead space: small post_residual is good, but waste < 10 is nearly unusable.
    if post_residual < 10 {
        score -= 12.0; // perfect-ish fit bonus
    } else if post_residual < 20 {
        score -= 4.0;
    } else {
        // super-linear penalty for large leftover space
        score += (post_residual as f64) * (post_residual as f64) / 400.0;
    }

    let is_new_bin = bin_residual == bin_capacity;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    if is_new_bin {
        // Opening a new bin: penalize unless existing fits are poor or many bins already open.
        let mut new_bin_cost = 25.0;
        if fitting_bins_count == 0 {
            new_bin_cost = 0.0; // no alternative
        } else if fitting_bins_count == 1 {
            // last-chance bin: strongly prefer using it over a new bin
            new_bin_cost += 30.0;
        }
        // late in the stream, closing out residual space matters: new bins cost more
        new_bin_cost += 15.0 * progress;
        // many open bins: mild encouragement to consolidate by using existing bins
        new_bin_cost += (open_bins_count as f64).ln().max(0.0) * 2.0;
        score += new_bin_cost;
    } else {
        // Reward using a bin whose residual matches the item well
        let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
        score -= 8.0 * tightness * tightness;
        // If this is the only bin that fits, prefer it heavily (avoid opening new bins)
        if fitting_bins_count == 1 {
            score -= 20.0;
        }
        // Prefer bins below mean residual (consolidate emptier space usage)
        score += (mean_residual - bin_residual as f64) * 0.05;
    }

    // Lookahead: if the next item fits exactly in the post residual, big bonus for this bin.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual >= next_item_size && post_residual - next_item_size < 10 {
            score -= 10.0;
        } else if post_residual < next_item_size && post_residual > 0 {
            // leftover too small for the next item: penalize dead space creation
            score += (post_residual as f64) * 0.15;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap; // normalized post residual

    // Base: prefer small post residual, with non-linear emphasis
    let mut score = x * (1.0 + 1.5 * x * (1.0 - x));

    // Smooth coupling with stream progress: tolerate waste early, punish late
    score += 2.0 * x * x * progress;

    // Dead-space penalty: residual below smallest plausible item is wasted
    let dead = ((12.0 - pr).max(0.0)) / 12.0;
    score += 3.0 * dead * dead;

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 1.0;
    }

    // Lookahead: reward if next item fits into post residual
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 0.8 * (1.0 - pr / cap);
    }

    // Encourage filling bins when many are open
    score += 0.05 * open_bins_count as f64 * x;

    // Slight pull toward mean residual alignment
    score += 0.1 * (mean_residual - pr).abs() / cap;

    // New-bin candidate: neutral-ish baseline, penalize mildly so it wins only on bad fits
    if bin_residual == bin_capacity {
        score = 1.2 + 1.5 * progress + 0.02 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify dead space into capacity fractions.
    let cap = bin_capacity as f64;
    let post_f = post_residual as f64;
    let frac = post_f / cap; // capacity fraction remaining

    // Integer division thresholds on post_residual (harmonic classes: 0, (0,25], (25,50], (50,100])
    let class = post_residual / 25; // 0..4
    match class {
        0 => score -= 30.0,                      // near-perfect fill
        1 => score -= 12.0,                      // small gap, still useful for tiny items
        2 => score += 0.0,                       // neutral
        _ => {}                                  // large residual is fine (flexible)
    }

    // Penalize residuals that no plausible item can use well:
    // dead zone (0, 10) means unusable sliver; harmonic multiples of 25 are ideal.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }
    if post_residual % 25 == 0 {
        score -= 8.0;
    }

    // Lookahead coupling: reward if next item fits exactly into post_residual (harmonic pairing).
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = post_residual - next_item_size;
        if gap == 0 {
            score -= 40.0;
        } else if gap < 10 {
            score -= 20.0;
        } else {
            score -= (gap as f64).min(15.0) * 0.5;
        }
    } else if next_item_size > post_residual {
        // next item cannot use this residual: penalize proportional to wasted fraction
        score += (next_item_size - post_residual) as f64 * 0.3;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 35.0;
    }

    // New-bin candidate handling: empty bin should only win when open bins fit poorly.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, modulated by stream progress and congestion.
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut new_bin_cost = 45.0 + 25.0 * (1.0 - progress);
        if open_bins_count == 0 {
            new_bin_cost = -100.0; // must open a bin
        }
        // If mean residual across open bins is small, opening is less wasteful.
        new_bin_cost -= mean_residual * 0.3;
        score = new_bin_cost + post_f;
    }

    // Mild congestion pressure: prefer denser packing when many bins are open.
    score += open_bins_count as f64 * 0.15;

    // Fractional tie-breaker: prefer exact harmonic complements (item + post = 100).
    if (item_size as f64 + post_f - cap).abs() < f64::EPSILON {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals that are too small to fit the minimum item size are wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64);
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 100.0;
    }

    // If this bin's residual can still fit the next item after placement, reward it.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    } else if next_item_size > 0 && post_residual > 0 {
        //残 space cannot host next item: mild penalty scaled by gap size.
        score += 8.0;
    }

    // Last-chance bin: strongly favor using the only bin that fits, avoiding a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: discourage opening new bins when many are open.
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline cost plus pressure from open bins and mean residual.
        score += 30.0 + 3.0 * open_bins_count as f64;
        if mean_residual > item_size as f64 {
            score += 15.0; // existing bins have plenty of room; don't open a new one
        }
    } else {
        // Slight preference for tighter bins (smaller residual) beyond post_residual ordering.
        score += 0.1 * bin_residual as f64 / bin_capacity as f64;
    }

    // Late in the stream, be more conservative: prefer filling existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 20.0 * progress;
    } else {
        score -= 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
