pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: prefer bins where the item fills a large fraction of residual.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize leaving small unusable dead space (hard-to-fill gaps).
    if post_residual > 0 && post_residual < 10 {
        score += 18.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 6.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, strongly favor this bin.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual > next_item_size {
            // next item fits here afterwards: mild bonus scaled by how well it fills
            let nxt_fill = next_item_size as f64 / post_residual as f64;
            score -= 8.0 * nxt_fill;
        } else {
            // next item won't fit in this bin's remainder: slight penalty for tight fits
            score += 3.0;
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item, strongly prefer it.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Time horizon: early in the stream, be more conservative about fragmenting bins;
    // late in the stream, close out bins aggressively (tight fits worth more).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * fit_ratio;

    // Global state: if mean residual is high, prefer using the fullest bins (low residual)
    score += 0.15 * (bin_residual as f64 - mean_residual);

    // New-bin candidate: empty bin should only win when open bins are poor fits.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, reduced when many bins are open or stream is long.
        let mut new_bin_cost = 55.0;
        if fitting_bins_count == 0 {
            new_bin_cost = -10.0; // no open bin fits: must open
        }
        // If next item is large, a fresh bin is attractive (room to pair items).
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            new_bin_cost -= 10.0;
        }
        // Late in stream, opening new bins is less costly (fewer future pairings needed).
        new_bin_cost -= 15.0 * progress;
        score += new_bin_cost;
    }

    // Mild penalty for spreading across many open bins (encourage closing bins out).
    score += 0.05 * open_bins_count as f64 * (1.0 - fit_ratio);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let mut score = pr as f64;

    // Smooth polynomial coupling of post_residual with stream progress
    let quad = norm_pr * norm_pr;
    let cubic = quad * norm_pr;
    score += (1.0 + progress) * (quad * 30.0 - cubic * 20.0);

    // Reward tight fits more strongly as the stream progresses
    let tightness = 1.0 - norm_pr;
    score -= (item_size as f64 / cap) * tightness * 40.0 * (0.5 + progress);

    // Penalize dead space relative to mean residual (smooth interaction)
    score += (norm_pr * cap - mean_residual).abs() * 0.15;

    // Last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 * (1.0 + progress);
    }

    // Lookahead: reward leaving space compatible with the next item
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        score += gap * 0.2 * (1.0 - progress);
    }

    // Mild penalty for spreading across many open bins early
    score += (open_bins_count as f64) * 0.05 * (1.0 - progress);

    // New-bin candidate: keep it competitive but not dominant unless residuals are bad
    if bin_residual == bin_capacity {
        score += 8.0 + 12.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit is perfect.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of the leftover space: prefer leftovers in "reusable" classes.
    // Class A: post_residual divisible by 10 (clean fractions of capacity) -> reusable.
    // Class B: post_residual in {1,2,3} -> nearly dead space, penalize.
    let pr = post_residual;
    if pr >= 10 && pr % 10 == 0 {
        score -= 8.0;
    }
    if pr > 0 && pr < 4 {
        score += 12.0;
    }
    // Mid-range awkward leftovers (just above typical small items).
    if pr > 10 && pr < 20 {
        score += 4.0;
    }

    // Integer-division thresholds: how many "average" future items could still fit.
    let avg_future = if next_item_size > 0 { next_item_size } else { 30 };
    let slots = pr / avg_future.max(1);
    score -= slots as f64 * 3.0;

    // Lookahead coupling: if next item fits exactly in the post residual, big reward.
    if next_item_size > 0 && next_item_size <= pr {
        if pr == next_item_size {
            score -= 40.0;
        } else if pr - next_item_size < 5 {
            score -= 15.0;
        }
    } else if next_item_size > pr && next_item_size > 0 {
        // Next item won't fit here anyway; leftover should be as small as possible.
        score += 6.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Prefer bins tighter than average (best-fit flavor with harmonic twist).
    let diff = bin_residual as f64 - mean_residual;
    if diff < 0.0 {
        score -= (-diff) * 0.15;
    } else {
        score += diff * 0.10;
    }

    // New-bin candidate: only attractive when no open bin is a good harmonic fit.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let good_fit_exists = fitting_bins_count > 0 && (post_residual == 0 || (pr >= 10 && pr % 10 == 0));
        // base penalty so we prefer existing bins; stronger when open bins exist.
        score += 30.0 + open_bins_count as f64 * 2.0;
        if !good_fit_exists && next_item_size > 0 && next_item_size > mean_residual {
            // current open bins are too tight for the stream: opening is fine.
            score -= 35.0;
        }
    }

    // Early stream: be slightly more willing to open bins for flexibility.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if is_new_bin && progress < 0.3 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 12 {
        score += 60.0 * (1.0 - post_residual as f64 / 12.0);
    }
    // Mid-range gap that only fits items <= 30 is semi-dead if next item is large.
    if post_residual >= 31 && post_residual <= 49 && next_item_size as f64 > post_residual as f64 {
        score += 25.0;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 80.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Lookahead: reward if the next item fits the post residual exactly-ish.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 15.0 + 10.0 * (1.0 - (post_residual - next_item_size) as f64 / post_residual.max(1) as f64);
    }

    // Open-bin pressure: discourage opening a new bin when alternatives exist.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 35.0 + 4.0 * open_bins_count as f64;
        // But if this bin is the last chance and fit is terrible, allow new bin.
        if fitting_bins_count == 1 && post_residual < 12 {
            score -= 55.0;
        }
    } else {
        // Favor tighter existing bins slightly.
        score -= 2.0 * (1.0 - bin_residual as f64 / bin_capacity as f64);
    }

    // Mild preference to fill bins below mean residual (consolidate).
    if !is_new_bin && (bin_residual as f64) < mean_residual {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize unusable dead space: residual too small for any plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // 2-step lookahead: strongly reward bins whose post_residual exactly or
    // nearly matches the next item's size (perfect chain fit).
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if post_residual >= next_item_size {
            // next item fits here afterwards: reward tightness of the chain
            score -= 45.0 - diff * 0.6;
        } else {
            // next item won't fit after this placement: mild penalty
            score += 8.0 + diff * 0.15;
        }
        // Exact match is ideal
        if post_residual == next_item_size {
            score -= 30.0;
        }
    }

    // Compare residual against the mean residual across open bins:
    // prefer filling bins that are already below-average full (consolidate waste).
    if (bin_residual as f64) < mean_residual {
        score -= 12.0;
    } else {
        score += (bin_residual as f64 - mean_residual) * 0.25;
    }

    // Last-chance bin: if this is the only bin that fits the item, strongly
    // prefer it over opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 70.0 + (item_size as f64 / bin_capacity as f64) * 20.0;
    }

    // New-bin candidate handling: only open a new bin when no existing bin
    // offers a decent fit (post_residual large waste elsewhere).
    if bin_residual == bin_capacity {
        // neutral baseline; make it slightly unattractive so real bins win
        // unless every alternative leaves large dead space.
        score = bin_capacity as f64 - 5.0;
        if fitting_bins_count == 0 {
            score -= 200.0; // must open a new bin
        }
    }

    // Slight preference for tighter fits overall.
    score += (item_size as f64 / bin_residual.max(1) as f64) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post-residual relative to capacity)
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual < 10 {
        score -= 12.0;
    }

    // Penalize creating dead space that no plausible item can fill:
    // residual below the minimum item size is wasted capacity
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Lookahead: if the next item fits exactly into the post-residual,
    // strongly favor this bin (chain placement)
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 8.0 * (1.0 - slack / (bin_capacity as f64));
        } else {
            // next item won't fit here after placement; mild penalty scaled by gap
            score += 0.15 * (next_item_size - post_residual) as f64;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // this bin would leave a large unusable remainder or the fit is very poor
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        // early in stream: mildly favor consolidation into existing bins
        score += 6.0 * (1.0 - progress);
        // if the item is small relative to capacity, opening a bin wastes space
        score += 0.2 * (bin_capacity - item_size) as f64;
        // many open bins: discourage opening yet another
        score += 0.5 * open_bins_count as f64;
    } else {
        // reward reusing existing bins, more so when many are open
        score -= 1.5 + 0.3 * open_bins_count as f64;
    }

    // Global residual balance: prefer bins whose residual is near the mean
    // (keeps a portfolio of usable gaps), penalize outliers
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Late in the stream: emphasize closing bins tightly
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Base: prefer low post-residual, but with diminishing returns at small residuals
    let mut score = 40.0 * pr_norm.powf(0.5 + 0.5 * progress);

    // Non-linear coupling: post_residual vs stream progress — tighter fits matter more later
    score += 8.0 * pr_norm * pr_norm * (1.0 - progress) - 4.0 * pr_norm * progress;

    // Penalize residuals that cannot fit the lookahead item (dead space), smoothly
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = ((nxt - pr).max(0.0)) / cap;
        score += 6.0 * gap * gap;
        // Reward if lookahead fits snugly
        let snug = ((pr - nxt).max(0.0)) / cap;
        score -= 3.0 * (1.0 - snug.min(1.0)) * (1.0 - progress);
    }

    // Last-chance bonus: only one fitting bin -> strongly favor using it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 10.0 + 6.0 * progress;
    }

    // Slight penalty when bin is far below mean residual (wasting a good bin)
    score += 2.0 * ((mean_residual - bin_residual as f64) / cap).max(0.0);

    // Mild pressure against hoarding many open bins
    score += 0.15 * (open_bins_count as f64).powf(0.5) * pr_norm;

    // New-bin candidate: neutral-ish baseline, mildly penalized early, relaxed late
    if bin_residual == bin_capacity {
        score = 12.0 + 20.0 * (1.0 - progress) * pr_norm;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;

    // Harmonic class of post_residual: bins whose residual lies in a "usable"
    // class (divisible by common small sizes) are worth more.
    let pr = post_residual;
    if pr > 0 {
        let mut harmony = 0.0;
        for &d in &[10u32, 20, 25, 50] {
            if pr % d == 0 { harmony += 6.0; }
        }
        if pr <= 10 { harmony += 4.0; } // tiny dead space is acceptable
        score -= harmony;
    } else {
        score -= 25.0; // perfect fill
    }

    // Penalize large awkward residuals (wasted space) nonlinearly.
    let frac = pr as f64 / cap;
    if frac > 0.5 { score += 8.0 * frac; }

    // Lookahead coupling: reward residual that can host the next item exactly.
    if next_item_size > 0 && pr >= next_item_size {
        if pr % next_item_size == 0 { score -= 10.0; }
        score -= 3.0;
    } else if next_item_size > 0 {
        score += 5.0; // next item cannot fit here
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when current bin would leave big waste
    // and stream is early (plenty of future items to fill it).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = 30.0 + 40.0 * progress + 0.15 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 5.0; // fresh bin can host lookahead too
        }
    }

    // Mild pressure toward consolidating into fewer bins.
    score += 0.05 * open_bins_count as f64;
    score += 0.02 * (mean_residual - post_residual as f64).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that likely cannot host any future item
    // (assumed min size ~1, but practically small gaps < ~15 are wasteful)
    let dead_threshold = 15.0;
    if (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 3.0;
    }

    // Perfect fit reward
    if post_residual == 0 {
        score -= 50.0;
    }

    // Penalize bins whose post-residual is too small for the next item
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += next_item_size as f64 * 0.5;
    }

    // Reward reserving space for the next item when it fits
    if next_item_size > 0 && post_residual >= next_item_size {
