    // Penalize dead space that is too small to be useful later (below min item size).
    if post_residual < 10 {
        score += 50.0;
    } else if post_residual < 20 {
        score += 15.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless post_residual is terrible).
    if fitting_bins_count == 1 {
        score -= 30.0;
        if post_residual == 0 {
            score -= 40.0;
        }
    }

    // Lookahead: if the next item fits in the post residual, reward this placement.
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        let slack = post_residual as f64 - next_item_size as f64;
        score -= 10.0 + 0.3 * slack;
        // Perfect chain: next item exactly fills remaining space.
        if slack == 0.0 {
            score -= 25.0;
        }
    } else if next_item_size > 0 {
        // Next item won't fit here; penalize leaving large awkward gaps.
        score += 0.2 * (post_residual as f64 - next_item_size as f64).abs();
    }

    // Time horizon: early in stream, be more willing to open/spread across bins;
    // late in stream, consolidate to avoid waste.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += progress * (post_residual as f64 * 0.5);

    // Global state coupling: many open bins with high mean residual -> prefer
    // filling existing bins harder; few open bins -> more freedom.
    let crowding = open_bins_count as f64 / (open_bins_count as f64 + 5.0);
    score += crowding * (post_residual as f64 - mean_residual).abs() * 0.4;

    // Prefer bins whose residual is close to the mean (balanced packing) early,
    // but late prefer extreme (small) residuals.
    if progress > 0.7 {
        score += mean_residual * 0.1;
    }

    // New-bin candidate tuning: an empty bin has max residual; make it attractive
    // only when current item is large or no good fits exist.
    if bin_residual == bin_capacity {
        // Empty bin baseline: moderate score, beaten by good fits, beats bad fits.
        score += 5.0;
        if item_size > 60 {
            score -= 10.0;
        }
        if fitting_bins_count <= 1 {
            score -= 20.0;
        }
    }

    // Small bonus for exact fills.
    if post_residual == 0 {
        score -= 60.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits (small post_residual)
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let t = progress;
    let quad = norm_pr * norm_pr * (100.0 + 80.0 * t);
    let cubic = norm_pr * norm_pr * norm_pr * (60.0 * (1.0 - t));
    score += quad - cubic;

    // Penalize waste relative to mean residual of open bins
    score += 0.3 * (pr as f64 - mean_residual).abs();

    // Lookahead coupling: reward if next item fits the post residual smoothly
    if next_item_size > 0 {
        let fit_gap = (post_residual as f64 - next_item_size as f64).abs();
        let fit_quality = 1.0 - (fit_gap / cap).min(1.0);
        score -= 15.0 * fit_quality * (1.0 - t);
    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 {
        score -= 40.0 * (1.0 - 0.5 * t);
    }

    // Mild penalty for spreading across many bins early
    score += 0.05 * open_bins_count as f64 * t;

    // Smooth dead-space penalty: unusable space (< min item size)
    if post_residual < item_size.min(bin_capacity) {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Harmonic class of post_residual: reward residuals in "usable" classes.
    // Class thresholds via integer division on capacity quarters.
    let quarter = bin_capacity / 4;
    let class = post_residual / quarter; // 0..4
    match class {
        0 => score -= 25.0,                    // very tight fit: excellent
        1 => score -= 10.0,                    // small leftover: good
        2 => score += 5.0,                     // half-empty: mediocre
        3 => score += 15.0,                    // mostly empty: poor
        _ => {}
    }

    // Reward exact harmony: post_residual divisible by common item sizes.
    if post_residual > 0 && post_residual % 10 == 0 {
        score -= 6.0;
    }

    // Lookahead coupling: if next item fits the post residual, bonus.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 + 0.1 * next_item_size as f64;
    } else if next_item_size > 0 && post_residual > 0 {
        // dead space that next item cannot use
        score += 8.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a bin when decent fits exist,
    // unless item is large and no bin is harmonically tight.
    if bin_residual == bin_capacity {
        score += 40.0;
        if item_size > bin_capacity / 2 && fitting_bins_count == 0 {
            score -= 55.0; // big item: fresh bin is fine
        }
    }

    // Prefer filling bins when many are open (limit bin proliferation).
    score -= 0.5 * open_bins_count as f64 * (1.0 - progress);

    // Slight pull toward mean residual balance.
    score += 0.05 * (post_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize unusable dead space: gaps too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (10.0 - post_residual as f64);
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 60.0;
    }

    // Penalize residual that cannot fit the lookahead item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 15.0;
    }

    // Reward bins whose residual is close to item size (tight fit).
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += 30.0 * tightness;

    // Open-bin pressure: discourage spreading across many bins unless fit is good.
    score += 2.0 * open_bins_count as f64 * (1.0 - tightness);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate: only attractive when item barely fits elsewhere.
    if bin_residual == bin_capacity {
        score += 20.0 + mean_residual * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strongly reward zero post-residual.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: reward post_residual exactly matching next item.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs();
        score -= 40.0 / (1.0 + diff as f64);
        // Chain fit: item now + next item fills bin completely.
        if post_residual as i64 == next_item_size as i64 {
            score -= 500.0;
        }
        // Penalize leaving residual the next item cannot use at all.
        if next_item_size > post_residual {
            score += 0.5 * (next_item_size - post_residual) as f64;
        }
    } else {
        // Last item: minimize waste only.
        score -= 300.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Relative-to-mean coupling: prefer bins whose residual is tighter than average.
    let rel = (bin_residual as f64 - mean_residual) / (bin_capacity as f64);
    score += 10.0 * rel;

    // Penalize large unusable dead space (below typical small item size).
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 80.0;
    }

    // New-bin candidate: only attractive when few good options exist or fit is poor.
    if bin_residual == bin_capacity {
        let good_fit_exists = post_residual as f64 <= mean_residual;
        if fitting_bins_count > 0 && good_fit_exists {
            score += 250.0; // keep using existing bins
        } else {
            score -= 20.0; // allow opening a fresh bin
        }
        // Early in stream, prefer opening bins to build diversity.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 30.0 * (1.0 - progress);
    }

    // Mild penalty for many open bins (consolidation pressure).
    score += 0.3 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) non-linearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize dead space that is too small for typical items (unusable gap).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: if the next item fits into post_residual, reward strongly.
    if next_item_size > 0 && next_item_size <= post_residual {
        let leftover_after_next = post_residual - next_item_size;
        score -= 14.0 - 0.08 * leftover_after_next as f64;
    } else if next_item_size > 0 {
        // Next item won't fit here; slight penalty for consuming residual uselessly.
        score += 4.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when no good fit exists elsewhere.
    if bin_residual == bin_capacity {
        let bad_fit = (bin_residual - item_size) as f64;
        let pressure = if fitting_bins_count == 0 { 0.0 } else { 1.0 };
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Penalize new bins early and when mean residual across open bins is large.
        score += 22.0 * pressure + 10.0 * (1.0 - progress) + 0.15 * mean_residual;
        // Reward new bin if item is large relative to capacity.
        score -= 0.2 * item_size as f64;
    }

    // Mild penalty for spreading across many open bins.
    score += 0.05 * open_bins_count as f64;

    // Prefer bins whose residual is close to what we consume (good ratio fit).
    let ratio = item_size as f64 / bin_residual.max(1) as f64;
    score += 6.0 * (1.0 - ratio).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let is_new_bin = if bin_residual == bin_capacity { 1.0 } else { 0.0 };

    let mut score = pr as f64;

    // Smooth non-linear coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 - progress) + norm_pr * progress * (1.0 - norm_pr);
    score += 8.0 * poly * cap * 0.1;

    // Reward tight fits more strongly as stream progresses
    let tightness = 1.0 - norm_pr;
    score -= tightness * tightness * (10.0 + 20.0 * progress);

    // Penalize dead space (post residual too small to be useful later)
    let dead = if pr > 0.0 && pr < 10.0 { (10.0 - pr) / 10.0 } else { 0.0 };
    score += 15.0 * dead;

    // Last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 && is_new_bin == 0.0 {
        score -= 25.0;
    }

    // Lookahead: reward residual that can host the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            let slack = (pr - nx) / cap;
            score -= 6.0 * (1.0 - slack * slack);
        } else {
            score += 4.0 * (nx - pr) / cap;
        }
    }

    // Mild penalty for spreading across many open bins late in stream
    score += 0.5 * open_bins_count as f64 * progress * norm_pr;

    // New-bin candidate: prefer it only when existing fits are poor
    score += is_new_bin * (20.0 - 15.0 * (1.0 - norm_pr)) + if is_new_bin == 1.0 { 30.0 } else { 0.0 };

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: how "usable" is the leftover space?
    // Residuals that are multiples of common item sizes (or near-capacity fractions)
    // are more likely to be filled later.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Fraction of capacity left after placement
    let frac = pr / cap;

    // Reward residuals that divide cleanly into small harmonic classes
    // (multiples of 10/20/25/50 are classic "friendly" leftovers).
    let harmonic_bonus = if post_residual == 0 {
        15.0 // perfect fit: strongly reward
    } else if post_residual % 50 == 0 {
        10.0
    } else if post_residual % 25 == 0 {
        7.0
    } else if post_residual % 20 == 0 {
        6.0
    } else if post_residual % 10 == 0 {
        4.0
    } else {
        0.0
    };
    score -= harmonic_bonus;

    // Penalize tiny unusable dead space (post_residual < 10 can never hold any item
    // in the classic range; for unknown distributions, small residual is dead weight).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // this is a chain fit — reward heavily.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size <= post_residual {
            // next item fits but leaves another residual; scale by how tight
            let leftover = (post_residual - next_item_size) as f64;
            score -= 8.0 * (1.0 - leftover / cap);
        } else {
            // next item won't fit here; penalize residuals that just barely
            // miss the next item (wasted potential).
            let miss = (next_item_size - post_residual) as f64;
            if miss <= 15.0 {
                score += 0.6 * miss;
            }
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: make opening a new bin moderately expensive so
    // we only do it when the fit into open bins is bad. The empty-bin call has
    // post_residual == capacity; give it a baseline penalty plus a term that grows
    // with how many bins are already open.
    if bin_residual == bin_capacity {
        score += 30.0 + 2.0 * open_bins_count as f64;
        // but if the item is large relative to capacity and mean residual is low,
        // opening fresh is less bad
        let large_item = item_size as f64 / cap;
        score -= 15.0 * large_item * (1.0 - mean_residual / cap).min(1.0);
    }

    // Tightness reward: prefer bins where the item fills a large fraction of residual.
    let fill = item_size as f64 / bin_residual as f64;
    score -= 10.0 * fill;

    // Modulo-threshold on post_residual vs item_size harmonic class:
    // reward when post_residual and item_size share a common divisor class (gcd > 1),
    // hinting future items of that class can reuse the space.
    let g = gcd(post_residual, item_size);
    if g > 1 {
        score -= 1.5 * g as f64;
    }

    // Mild time-decay: late in the stream, avoid opening new bins even more.
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        if bin_residual == bin_capacity {
            score += 10.0 * progress;
        }
    }

    // Penalize deviations from mean residual to keep bin loads balanced.
    score += 0.3 * (pr - mean_residual).abs();

    score
}

fn gcd(a: u32, b: u32) -> u32 {
    if b == 0 { a } else { gcd(b, a % b) }
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps harshly.
    // A residual below the minimum item size (1) is impossible, but tiny
    // residuals (< 10) are statistically hard to fill later.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual < 20 {
        score += 12.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Reward leaving room for the lookahead item (k=2).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 5.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Open-bins pressure: many open bins -> prefer filling existing ones,
    // penalize the new-bin candidate.
    let bin_progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * (0.5 + bin_progress) * 2.0;

    // Prefer bins tighter than the mean residual (waste-averse matching).
    score += 0.5 * (post_residual as f64 - mean_residual).max(-20.0).min(20.0);

    // New-bin candidate: only attractive if no open bin fits well.
    if bin_residual == bin_capacity {
        score += 10.0 + open_bins_count as f64 * 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong preference for tight fits: reward low post_residual nonlinearly.
    score -= 40.0 * (1.0 - (post_residual as f64 / bin_capacity as f64)).powi(3);

    // 2-step lookahead: if the next item exactly fits the post_residual, big reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        score -= 25.0 / (1.0 + gap);
    }

    // Penalize post_residual that is too small to ever be useful again (dead space).
    if next_item_size == 0 || post_residual < next_item_size {
        score += 0.5 * post_residual as f64;
    }

    // Relative to mean residual: favor bins that are more filled than average.
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bin is a bad fit.
    if bin_residual == bin_capacity {
        score += 12.0;
        // If lookahead matches a fresh bin perfectly, allow it.
        if next_item_size > 0 && (bin_capacity as f64 - next_item_size as f64) < 10.0 {
            score -= 6.0;
        }
    }

    // Slight preference early in the stream to consolidate (fewer bins).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 2.0 * (1.0 - progress) * (open_bins_count as f64 / 20.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual).
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tight * tight;

    // Perfect fit gets a strong bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Penalize dead space that is too small for typical items (1..100 interface).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver
    }

    // Lookahead: if next item fits exactly into post_residual, big bonus.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            score -= 10.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item won't fit here; mild penalty proportional to overflow
            score += 5.0 * ((next_item_size - post_residual) as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Many fitting bins: slight penalty to encourage diversity of residual sizes,
    // keep bins with large residuals for future large items.
    if fitting_bins_count > 2 {
        score += 3.0 * (fitting_bins_count as f64 - 2.0);
    }

    // Prefer bins whose residual is close to the mean residual (balance load),
    // unless the fit is tight.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // New-bin candidate handling: opening a new bin wastes space; only attractive
    // when the item is large and no tight fit is possible elsewhere.
    if bin_residual == bin_capacity {
        let waste = (bin_capacity - item_size) as f64;
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut open_cost = 20.0 + 0.5 * waste;
        // Late in the stream, opening new bins is less costly (fewer future items to fill them).
        open_cost *= 1.0 - 0.5 * progress;
        // If this bin is the only option, opening is necessary.
        if fitting_bins_count == 0 {
            open_cost = -10.0;
        }
        // If next item is huge and would need a fresh bin anyway, opening now is fine.
        if next_item_size > 0 && next_item_size > post_residual && next_item_size >= 70 {
            open_cost -= 15.0;
        }
        score += open_cost;
    }

    // Mild time-dependent exploration: slightly vary preference across the stream.
    let phase = ((step_index as f64 * 0.05).sin()) * 2.0;
    score += phase;

    // Slight preference for fewer open bins (consolidation).
    score += 0.3 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let residual_norm = bin_residual as f64 / cap;

    // Base: waste after placement, with non-linear penalty for awkward small residuals.
    let mut score = post;

    // Quadratic waste amplification: small unusable leftovers are doubly bad.
    let waste_frac = post / cap;
    score += 40.0 * waste_frac * waste_frac * cap;

    // Cubic coupling of post_residual with stream progress: early on, keep bins
    // flexible (larger post_residual is fine); late, prefer tight packing.
    let flex = 1.0 - progress;
    score += 30.0 * (waste_frac * waste_frac * waste_frac) * cap * (1.0 - 2.0 * progress);

    // Interaction: residual tightness vs progress — tight fits rewarded more as stream advances.
    let tightness = 1.0 - residual_norm;
    score -= 25.0 * tightness * (0.5 + progress);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 60.0;
    }

    // Lookahead: if next item exactly fits the post residual, big reward.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= post {
            let perfect = (post - nx).abs() / cap;
            score -= 35.0 * (1.0 - perfect);
        } else {
            // Next item cannot use this leftover — mild penalty scaled by gap.
            score += 10.0 * ((nx - post) / cap);
        }
    }

    // Mean-residual coupling: penalize bins far below the mean residual
    // (they are the tightest; using them wastes scarce space) unless it's a near-perfect fit.
    let dev = (mean_residual - bin_residual as f64) / cap;
    score += 15.0 * dev * dev.abs() * cap * 0.01;

    // New-bin candidate: empty bin should only win if all open bins fit poorly.
    if bin_residual == bin_capacity {
        // Neutral-ish base; slightly favored early when few bins exist,
        // penalized when many bins are open (consolidation preferred).
        score = cap * 0.9 + 5.0 * (open_bins_count as f64).ln().max(0.0) - 20.0 * (1.0 - progress);
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a new bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "usable"
    // residue classes (multiples of 10 / small remainders) are preferred.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Penalize dead space: small unusable leftovers (1..=9) are worst.
    let rem10 = post_residual % 10;
    if post_residual > 0 && rem10 != 0 {
        score += (10 - rem10) as f64 * 1.5; // awkward leftover
    }

    // Reward leftovers that are "harmonically friendly" — divisible into
    // common item-size classes (10/20/25/50).
    if post_residual % 50 == 0 && post_residual > 0 {
        score -= 12.0;
    } else if post_residual % 25 == 0 && post_residual > 0 {
        score -= 6.0;
    } else if post_residual % 10 == 0 && post_residual > 0 {
        score -= 3.0;
    }

    // Integer-division threshold: leftover >= 50 is a half-bin, still very usable.
    let half = (post_residual / 50) as f64;
    score -= half * 4.0;

    // Lookahead: if next item fits exactly into the post residual, big reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 10.0;
        if next_item_size == post_residual {
            score -= 15.0; // perfect pairing
        }
        // Harmonic coupling: next item's class vs post residual class
        if post_residual % next_item_size.max(1) == 0 {
            score -= 5.0;
        }
    } else if next_item_size > post_residual {
        score += 2.0; // next item won't fit here anyway
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    } else {
        // Spread load when many bins fit: prefer fuller bins (small post residual)
        score += pr * 0.05;
    }

    // New-bin candidate: only attractive when current leftovers are all bad fits
    // (small mean residual relative to item) or stream is early with few bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // Baseline cost of opening a fresh bin.
        score = cap * 0.55;
        let avg_fit = mean_residual - item_size as f64;
        if avg_fit < 0.0 {
            score -= 30.0; // no open bin can really help
        }
        if open_bins_count == 0 {
            score -= 200.0;
        }
        if next_item_size > 0 && (cap - next_item_size as f64) < 15.0 && progress < 0.5 {
            score -= 8.0;
        }
        // Penalize new bins late in the stream when open bins could still serve.
        if fitting_bins_count > 0 && mean_residual > item_size as f64 {
            score += 25.0;
        }
    }

    // Mild tightness bonus: filling bins closer to capacity overall.
    score -= (item_size as f64 / cap) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small nonzero gaps are useless -> heavy penalty
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }
    // Perfect fit gets a strong reward
    if post_residual == 0 {
        score -= 15.0;
    }

    // Reward leaving gaps that the lookahead item can fill (k=2 lookahead)
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 0.5;
    }
    // Penalize if gap is just below the next item (dead space for lookahead)
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }

    // Open-bin pressure: discourage scattering across many bins
    score += (open_bins_count as f64) * 0.3;

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Prefer bins tighter than average (best-fit flavor)
    score += (bin_residual as f64 - mean_residual) * 0.2;

    // New-bin candidate: neutral baseline; only chosen when open bins are bad fits
    if bin_residual == bin_capacity {
        score += 10.0 + (open_bins_count as f64) * 0.2;
        // late in stream, opening new bins is cheap since stream ends soon
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= progress * 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit is ideal.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: reward if next item fits exactly into post_residual.
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = (post_residual - next_item_size) as f64;
        if gap == 0.0 {
            score -= 800.0;
        } else {
            score -= 300.0 / gap.sqrt();
        }
    } else if next_item_size > 0 {
        // Dead space relative to next item: penalize small unusable gaps.
        let dead = (next_item_size - post_residual) as f64;
        if dead > 0.0 && dead <= 10.0 {
            score += 150.0 / dead;
        }
    }

    // Penalize creating small stranded residuals relative to mean residual.
    if post_residual > 0 && (post_residual as f64) < mean_residual * 0.5 {
        score += 40.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 250.0;
    }

    // Slight bias toward fullest bins early in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (bin_capacity - bin_residual) as f64 * 0.3 * (1.0 - progress);

    // Discourage opening new bins when decent open bins exist.
    if bin_residual == bin_capacity {
        score += 120.0 + open_bins_count as f64;
        if next_item_size > 0 && next_item_size <= bin_residual {
            score += 50.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits: small post_residual is good.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 40.0 * fit_ratio * fit_ratio;

    // Penalize leaving dead space that no plausible item can fill.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0; // tiny unusable sliver
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            score -= 10.0 + 20.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item won't fit here: mild penalty proportional to waste
            score += 5.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Many open bins: prefer consolidating into existing bins.
    let pressure = open_bins_count as f64 / (1.0 + step_index as f64);
    score += 8.0 * pressure * (1.0 - fit_ratio);

    // Mean residual coupling: when average residual is low, conserve space carefully.
    score += 0.15 * (mean_residual - post_residual as f64);

    // New-bin candidate handling: only attractive when the item is large
    // relative to remaining capacity pressure late in the stream.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let large_item = item_size as f64 / bin_capacity as f64;
        // Opening a new bin is good for big items, or when existing bins are crowded.
        score -= 20.0 * large_item + 10.0 * progress;
        // But discourage hoarding new bins when a decent fit exists elsewhere.
        if fitting_bins_count > 0 && fit_ratio < 0.85 {
            score += 25.0;
        }
        if next_item_size > 0 && next_item_size <= item_size {
            score -= 5.0; // new bin can serve the lookahead too
        }
    }

    // Mild time-horizon term: late in the stream, prioritize perfect packing.
    let horizon = step_index as f64 / total_items.max(1) as f64;
    score -= 12.0 * horizon * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items as f64).max(1.0);
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let item = item_size as f64 / cap;

    // Base: prefer small post_residual, with non-linear polynomial shaping
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // Smooth interaction: as stream progresses, tighten preference for tight fits
    score += 12.0 * progress * norm_pr * (1.0 - norm_pr) * 4.0;

    // Penalize dead space relative to mean residual (smooth quadratic coupling)
    score += 0.5 * (pr - mean_residual) * (pr - mean_residual) / cap;

    // Last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0 * (1.0 + item);
    }

    // Lookahead coupling: reward leaving space compatible with next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let compat = if pr >= nxt {
            1.0 - ((pr - nxt) / cap).powi(2)
        } else {
            -0.5 * ((nxt - pr) / cap)
        };
        score -= 8.0 * compat * (0.5 + 0.5 * progress);
    }

    // Mild penalty on opening a new bin when alternatives exist
    if bin_residual == bin_capacity {
        score += 6.0 + 10.0 * (1.0 - progress) + 0.3 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residual mod 10 classes.
    // Small residues (mod 10 near 0) are "dead space" classes -> penalize.
    let r = post_residual;
    if r > 0 {
        let cls = r % 10;
        // classes 1..3 are nearly useless dead space
        if cls >= 1 && cls <= 3 {
            score += 6.0 - (cls as f64);
        } else if cls >= 8 {
            score -= 2.0; // near a full decade: next small item fits nicely
        }
        // Perfectly tight bins are ideal
        if r == 0 {
            score -= 15.0;
        }
    } else {
        score -= 15.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 && next_item_size <= r {
        let slack = (r - next_item_size) as f64;
        if slack == 0.0 {
            score -= 12.0; // perfect chained fit
        } else if slack < 5.0 {
            score -= 5.0;
        } else {
            // penalize if post_residual is much larger than next item (wasteful hold)
            score += slack * 0.02;
        }
    } else if next_item_size > 0 {
        // next item cannot fit here: this bin's leftover is final dead space
        score += (r as f64) * 0.15;
    }

    // Last-chance bonus: only one bin fits; avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 4.0;
    }

    // New-bin candidate: penalize unless current bin fit is poor.
    if bin_residual == bin_capacity {
        // opening a new bin is fine early or when many bins open (dispersion)
        let progress = step_index as f64 / total_items.max(1) as f64;
        let dispersion = (open_bins_count as f64) / (mean_residual + 1.0);
        score = 100.0 - dispersion * 0.5 - (1.0 - progress) * 10.0;
        if item_size > 70 {
            score -= 20.0; // big items start fresh bins
        }
    }

    // Fraction-of-capacity harmonic: reward placing so residual lands on
    // capacity/4 boundaries (25/50/75) which are common item-size divisors.
    let quarter = bin_capacity / 4;
    if r == quarter || r == 2 * quarter || r == 3 * quarter {
        score -= 3.0;
    }

    // Mild preference for tighter bins overall
    score -= (bin_residual as f64) * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small for any item (min size 1..10 band)
    // are unusable; punish them quadratically.
    if post_residual < 10 {
        score += (10 - post_residual) as f64 * 12.0;
    } else if post_residual <= 20 {
        // Risky zone: hard to fill exactly, mild penalty growing toward 10.
        score += (20 - post_residual) as f64 * 0.8;
    }

    // Reward tight fits: post_residual near zero is excellent.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Lookahead: if next item can exactly use the post residual, reward strongly.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0;
        if post_residual == next_item_size {
            score -= 10.0;
        }
    } else if next_item_size > 0 && next_item_size <= bin_residual && post_residual < next_item_size {
        // This placement kills the chance for the next item in this bin.
        score += 4.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones
    // (penalize spreading); when few bins open, keep flexibility.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += pressure * (post_residual as f64) * 0.15;

    // Last-chance bin: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Mean residual coupling: if this bin's residual is far below mean,
    // filling it reduces fragmentation spread.
    let res = bin_residual as f64;
    if res < mean_residual {
        score -= (mean_residual - res) * 0.2;
    } else {
        score += (res - mean_residual) * 0.1;
    }

    // New-bin candidate: make it moderately attractive only when the item
    // is large relative to capacity or no tight fit exists elsewhere.
    if bin_residual == bin_capacity {
        let frac = item_size as f64 / bin_capacity as f64;
        score += 8.0 - 20.0 * frac;
        if post_residual < 10 {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimal post_residual (tightest fit).
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let next = next_item_size as f64;

    // Aggressive 2-step lookahead: reward when next item exactly matches post_residual.
    if next_item_size > 0 {
        if (next_item_size as u32) == post_residual {
            score -= 60.0; // perfect chaining: next item fills this bin completely
        } else if next_item_size as u32 <= post_residual {
            let fill_ratio = next / post.max(1.0);
            score -= 40.0 * fill_ratio; // next item fits well in leftover space
        } else {
            // Next item cannot use the leftover: penalize dead space more if large.
            let waste = (next - post) / cap;
            score += 25.0 * waste;
        }
    }

    // Relative-to-mean coupling: bins with residual far below mean are "tight" —
    // prefer filling them; bins far above mean should stay flexible.
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 15.0 * dev;

    // Last-chance bonus: if this is the only bin that fits, strongly favor it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: empty bin should only win when no good fit exists.
    if bin_residual == bin_capacity {
        score += 30.0;
        // Early in stream, new bins are cheap; late in stream, prefer consolidation.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * (1.0 - progress);
        // If next item is huge, keeping fresh capacity may help.
        if next_item_size >= 60 {
            score -= 15.0;
        }
    }

    // Penalize leaving tiny unusable slivers unless next item can use them.
    if post_residual > 0 && post_residual < 10 && next_item_size as u32 != post_residual {
        score += 20.0;
    }

    // Mild pressure to consolidate when many bins are open.
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space: residuals too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bonus: only this bin can fit the item.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead coupling: prefer bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            score += 0.35 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // New-bin candidate handling: only attractive when open bins fit poorly.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let spread = (mean_residual - post_residual as f64).abs();
        // Favor new bins early or when mean residual is low (poor fits everywhere).
        score += 6.0 + 10.0 * (1.0 - progress) - 0.15 * mean_residual + 0.05 * spread;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 6.0;
        }
    } else {
        // Mild penalty when bin residual far exceeds item (wasteful fit).
        let waste = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
        score += 4.0 * waste;
    }

    // Global pressure: many open bins -> prefer filling existing ones.
    score += 0.05 * open_bins_count as f64;

    // Time horizon: later in stream, consolidate aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * progress * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: penalize leftover space, with polynomial sharpening
    let mut score = pr * (1.0 + norm_pr * norm_pr * 2.0);

    // Smooth cubic coupling: as stream progresses, dead space becomes more costly
    let prog_term = progress * progress * (3.0 - 2.0 * progress);
    score += pr * prog_term * 1.5;

    // Reward tight fits more strongly later in the stream
    score -= (cap - pr) * (0.3 + prog_term * 0.7);

    // Mean residual interaction: if this bin's residual deviates from mean, adjust
    let mean_norm = mean_residual / cap;
    score += (norm_pr - mean_norm) * (norm_pr - mean_norm) * 30.0 * (1.0 - prog_term);

    // Last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0 + 30.0 * prog_term;
    }

    // Lookahead: penalize leaving residual too small for next item
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if pr >= n {
            score -= 8.0 * (1.0 - ((pr - n) / cap).abs());
        } else {
            score += 12.0 + (n - pr) * 0.4;
        }
    }

    // New-bin candidate shaping: empty bin gets a smooth penalty scaled by open bins and progress
    if bin_residual == bin_capacity {
        score += 25.0 + 20.0 * prog_term + 2.0 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits: the smaller the post_residual fraction, the better.
    let post_frac = post_residual as f64 / cap;
    score += 40.0 * post_frac * post_frac;

    // Perfect fit is extremely attractive.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic classes: dead space in (0,10) is nearly unusable (items >= 1,
    // but small residuals waste capacity). Penalize tiny nonzero residuals hard.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Class of residual modulo 10: residuals that are multiples of 10 align
    // with common item granularities; slight reward.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 8.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // strongly prefer this bin; if next item cannot fit but could fit elsewhere,
    // penalize.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 120.0;
        } else if next_item_size <= post_residual {
            // next fits, but leftover after next matters
            let after_next = post_residual - next_item_size;
            score -= 20.0 - 0.3 * after_next as f64;
            if after_next < 10 {
                score += 15.0; // would create dead space after next
            }
        } else {
            // next item won't fit here; penalize more if this bin becomes a
            // near-empty leftover
            score += 10.0 + 0.2 * (next_item_size - post_residual) as f64;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate handling: an empty bin gets a baseline that keeps it
    // competitive only when open bins fit poorly.
    if bin_residual == bin_capacity {
        // base cost of opening a new bin, softened when many bins already open
        // or stream is late (consolidation phase).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = cap - 30.0 * progress - 2.0 * open_bins_count as f64;
        // if mean residual across open bins is large, prefer reusing them:
        // (this call's score rises when reuse is easy elsewhere)
        score += 0.5 * mean_residual;
    }

    // Mild preference to fill already-open bins when many are open.
    if bin_residual < bin_capacity {
        score -= 0.05 * open_bins_count as f64;
        // prefer bins with residual close to item (best-fit signal)
        score += 0.2 * (bin_residual - item_size) as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to accept
    // typical future items are heavily penalized (non-linearly).
    let r = post_residual as f64;
    if r < 10.0 {
        score += 40.0 * (10.0 - r); // tiny gap => very bad
    } else if r < 25.0 {
        score += 8.0 * (25.0 - r); // awkward medium-small gap
    }

    // Reward tight fits: the smaller the post_residual relative to capacity,
    // the better the packing.
    score -= 25.0 * (1.0 - r / bin_capacity as f64);

    // Pressure from number of open bins: prefer consolidating into existing
    // bins rather than spreading out.
    score += open_bins_count as f64 * 0.8;

    // Prefer bins whose residual is close to the mean residual (keeps the
    // open-bin population homogeneous, easier to fill later).
    score += 0.5 * (r - mean_residual).abs();

    // Last-chance bin: if this is the only bin that fits, strongly favor it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if the next item can exactly use the post-residual, big bonus.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 50.0;
        } else if next_item_size <= post_residual {
            score -= 10.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // next item won't fit here; penalize leaving residual that
            // blocks the next item while wasting space
            score += 5.0;
        }
    }

    // New-bin candidate (empty bin): make it unattractive unless there are no
    // fitting bins or the existing fit would be terrible.
    if bin_residual == bin_capacity {
        score += 35.0 + open_bins_count as f64 * 0.5;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // pairing potential for the new bin
        }
    }

    // Slight stream-progression pressure: later in the stream, be more
    // eager to close bins tightly.
    score -= 3.0 * (step_index as f64 / total_items.max(1) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through the stream (0..1)
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Fraction of capacity consumed by this placement
    let fill_ratio = item_size as f64 / bin_capacity as f64;

    // Reward high fill: subtract proportional to how well the bin is used
    score -= 60.0 * fill_ratio * fill_ratio;

    // Penalize large dead space nonlinearly: residuals that can't fit
    // typical future items are especially bad. Dead space threshold ~ 25.
    let dead = post_residual as f64;
    if dead > 0.0 {
        score += 0.35 * (dead * dead) / bin_capacity as f64;
    }

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + 20.0 * fill_ratio;
    }

    // New-bin candidate handling: an empty bin should only win when the fit
    // in existing bins is poor. Penalize the empty bin moderately.
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin, scaled by how many bins exist
        // and how much residual space is already floating around.
        score += 15.0 + 2.0 * open_bins_count as f64 + 0.1 * mean_residual;
        // Early in the stream, new bins are cheaper; late, expensive.
        score += 30.0 * progress;
        // If the next item is large, a fresh bin is more valuable.
        score -= 0.15 * next_item_size as f64;
        // If this bin would be nearly empty after placement, discourage.
        if item_size < 20 {
            score += 20.0;
        }
    }

    // Lookahead coupling: reward placements that leave room for the next item
    // exactly (post_residual == next_item_size), penalize leaving almost-but-not-
    // quite enough room (frustrated lookahead).
    if next_item_size > 0 {
        if post_residual as u32 == next_item_size {
            score -= 30.0;
        } else if post_residual as u32 > next_item_size
            && (post_residual as u32 - next_item_size) < 10
        {
            score += 12.0; // awkward sliver relative to next item
        }
    }

    // Global pressure: many open bins with high mean residual -> consolidate.
    // Favor bins below mean residual (tighter bins) when bins are plentiful.
    if open_bins_count > 3 {
        let dev = mean_residual - bin_residual as f64;
        score -= 0.15 * dev;
    }

    // Mild late-stream consolidation pressure: prefer fuller bins as stream ends.
    score -= 10.0 * progress * fill_ratio;

    // Small tie-break noise-free deterministic jitter on residual to break ties
    // toward bins with rounder residuals (avoid pathological slivers).
    if post_residual % 10 == 0 {
        score -= 1.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;
    let norm_next = next_item_size as f64 / cap;

    let mut score = pr as f64;

    // Smooth polynomial coupling of post_residual with stream progress
    let p = progress;
    score -= 30.0 * norm_pr * (1.0 - p) * (1.0 - norm_pr * norm_pr);
    score += 25.0 * norm_pr * norm_pr * p;

    // Reward tight fits via cubic term
    score -= 40.0 * (1.0 - norm_pr).powi(3) * norm_item;

    // Penalize dead space late in stream
    score += 15.0 * norm_pr * p * p;

    // Next-item lookahead coupling (smooth)
    if next_item_size > 0 {
        let fit_next = norm_next * norm_next / (norm_pr + 0.01).max(0.01);
        score -= 10.0 * fit_next.min(2.0) * (1.0 - p);
    }

    // Last-chance bonus (smooth decay with fitting bins count)
    if fitting_bins_count == 1 {
        score -= 20.0 * (1.0 - p);
    }
    score += 3.0 * (fitting_bins_count as f64).ln().max(0.0);

    // Mean residual dispersion penalty
    score += 5.0 * (mean_residual / cap - norm_pr).abs();

    // Mild new-bin preference when residuals are large and progress is early
    if bin_residual == bin_capacity {
        score += 8.0 * (1.0 - norm_item) * (1.0 - p);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Harmonic class of the item: bucket by size modulo capacity fractions
    let item_class = (item_size * 4) / bin_capacity; // 0..3 coarse class
    let post_class = (post_residual * 4) / bin_capacity;

    // Reward tight fits strongly (small post_residual classes)
    let tightness = 1.0 - (post / cap);
    score -= 18.0 * tightness * tightness;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            // next item fits, but penalize leftover waste after that
            let waste2 = post_residual - next_item_size;
            score -= 12.0 * (1.0 - waste2 as f64 / cap);
        } else {
            // next item cannot use this bin's residue: penalize residue a bit more
            score += 6.0 * (post / cap);
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 22.0;
    }

    // New empty bin candidate: penalize unless existing fits are bad
    if bin_residual == bin_capacity {
        score += 15.0;
        // opening new bin is attractive when many open bins exist with high mean residual
        score -= 0.35 * open_bins_count as f64;
        score -= 0.05 * mean_residual;
    }

    // Dead-space penalty: residues too small for typical items (harmonic class 0)
    if post_residual > 0 && post_residual < 10 {
        score += 14.0;
    }

    // Modulo-based coupling: residues that align with common item sizes are reusable
    let reusable = (post_residual % 10 == 0) || (post_residual % 5 == 0 && post_residual >= 20);
    if reusable {
        score -= 5.0;
    }

    // Slight preference to fill earlier bins as stream progresses
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 3.0 * progress * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize unusable small gaps harshly.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 40.0;
    }

    // Non-linear penalty on small residuals (dead space zones).
    let pr = post_residual as f64;
    if pr > 0.0 && pr < 20.0 {
        score += (20.0 - pr) * 1.5;
    }

    // Open-bins pressure: discourage spreading across many bins when fits exist.
    if fitting_bins_count > 1 {
        score -= 5.0;
    }
    if open_bins_count > 0 {
        score += (open_bins_count as f64).sqrt() * 2.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate (empty bin): only attractive when this bin would leave a bad gap
    // or when lookahead item fits the fresh bin well.
    if bin_residual == bin_capacity {
        score += 30.0; // default penalty: prefer existing bins
        if next_item_size > 0 && next_item_size as f64 >= bin_capacity as f64 * 0.5 {
            score -= 25.0;
        }
        if post_residual >= 50 {
            score -= 10.0;
        }
    }

    // Lookahead coupling: reward leaving room for the next item.
    if next_item_size > 0 && (post_residual as i64 - next_item_size as i64) == 0 {
        score -= 20.0;
    }
    if next_item_size > 0 && post_residual > 0 && (post_residual as f64) < next_item_size as f64 {
        score += (next_item_size as f64 - pr) * 0.5; // gap unusable for lookahead
    }

    // Late-stream tightening: mean residual deviation penalty.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (mean_residual - pr).abs() * 0.1 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 200.0;
    }

    // Aggressive 2-step lookahead: reward if next item fits into post_residual
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // next item fits: great, strong reward scaled by tightness
            score -= 80.0 * (next_item_size as f64 / post_residual.max(1) as f64);
        } else {
            // next item won't fit here; penalize large dead space
            score += 0.6 * post_residual as f64;
        }
    }

    // Compare post_residual to mean residual: prefer bins tighter than average
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate: penalize opening a new bin unless item is huge / no good fits
    if bin_residual == bin_capacity {
        score += 250.0;
        if item_size > 80 {
            score -= 200.0;
        }
        if fitting_bins_count == 0 {
            score -= 250.0;
        }
    }

    // Late in stream: be more conservative, prefer filling existing bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 40.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: quadratic penalty on wasted space
    score += 0.35 * (post_residual as f64 / bin_capacity as f64).powi(2) * bin_capacity as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual < 10 {
        score -= 12.0; // near-perfect fit, dead space unusable anyway
    }

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if next item fits in the post-residual, reward this placement
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0 + 0.1 * next_item_size as f64;
        } else if next_item_size <= bin_residual && post_residual < next_item_size {
            // this placement blocks a good follow-up fit
            score += 6.0;
        }
    }

    // New-bin candidate handling: prefer new bin when item fits poorly everywhere
    if bin_residual == bin_capacity {
        let waste = post_residual as f64;
        // Opening a new bin is attractive if existing bins would leave large dead space
        score = waste + 5.0;
        if fitting_bins_count == 0 {
            score -= 60.0; // no alternative: must open
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0; // fresh bin can host the next item too
        }
        // Late in stream, prefer filling existing bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 * progress;
        if open_bins_count > 0 && fitting_bins_count > 0 {
            score += 8.0;
        }
    }

    // Spread-awareness: penalize bins far above/below mean residual to consolidate space
    let diff = bin_residual as f64 - mean_residual;
    score += 0.05 * diff.abs();

    // Favor fuller bins overall (pack into emptier-residual bins)
    score -= 0.03 * (bin_capacity - bin_residual) as f64;

    // Many open bins: encourage consolidation
    if open_bins_count > 4 {
        score += 0.02 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let is_new_bin = (bin_residual as f64 - cap).abs() < 1e-9;

    // Base: prefer small post_residual (tight fit), with a convex penalty
    // that grows super-linearly as wasted space increases.
    let norm_post = post / cap;
    let mut score = norm_post + 1.6 * norm_post * norm_post;

    // Smooth non-linear coupling of waste with stream progress:
    // waste tolerance shrinks as the stream advances (late items must pack tight).
    let progress_coupling = 1.0 + 2.0 * progress * norm_post;
    score *= progress_coupling;

    // Last-chance bonus: if this is the only bin that fits, strongly reward using it.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 3.0 + 2.0 * progress;
    }

    // New-bin candidate: penalize opening a new bin, unless the item fits
    // very poorly everywhere (large item / large residual mismatch).
    if is_new_bin {
        let fit_quality = item_size as f64 / cap;
        // Opening is attractive only for large items or when few bins fit.
        let open_bonus = fit_quality * fit_quality * 2.5
            + (fitting_bins_count as f64).recip() * 0.8;
        let open_penalty = 2.2 + 1.5 * progress + 0.02 * open_bins_count as f64;
        score += open_penalty - open_bonus;
    }

    // Lookahead: reward bins whose post_residual accommodates the next item,
    // penalize bins that would strand awkward space.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let exact = (post - nxt).abs() / cap;
        if post >= nxt {
            score -= 0.9 * (1.0 - exact) * (1.0 - progress);
        } else {
            score += 0.5 * (nxt - post) / cap;
        }
    }

    // Mild preference for filling bins that deviate from the mean residual
    // (consolidate space in similarly-loaded bins).
    score += 0.15 * ((bin_residual as f64 - mean_residual) / cap).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic classes: classify post_residual by capacity fraction classes.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap; // fraction of capacity left

    // Integer-division thresholds on post_residual: dead-space classes.
    // Residuals below the minimum plausible item size are "dead" space -> penalize.
    let dead_threshold: u32 = 10; // smallest item class
    if post_residual < dead_threshold && post_residual > 0 {
        // Perfectly packed bin, but ensure it is truly near-zero
        score -= 25.0;
    } else if post_residual == 0 {
        score -= 60.0; // exact fill is ideal
    }

    // Modulo arithmetic on post_residual w.r.t. common item size classes (1..100 unknown,
    // but harmonics at small divisors capture typical size structure).
    for &m in &[2u32, 4, 5, 10, 20, 25, 50] {
        let r = post_residual % m;
        // If post_residual is a harmonic residue of a likely item size class, reward.
        if r == 0 && post_residual > 0 {
            score -= 2.0 + (m as f64) * 0.1;
        }
    }

    // Lookahead coupling: does the next item fit into the post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Next item fits exactly or nearly: strong reward scaled by tightness.
            let tight = 1.0 - ((post_residual - next_item_size) as f64 / cap);
            score -= 15.0 + 20.0 * tight;
        } else {
            // Next item will not fit here: the leftover becomes dead space for the horizon.
            let waste = (next_item_size - post_residual) as f64;
            score += 0.15 * waste.min(cap);
        }
    } else {
        // Last item: only current fill matters.
        score -= 10.0;
    }

    // Capacity-fraction thresholds: encourage leaving residuals in "usable bands".
    if frac > 0.0 && frac < 0.10 {
        score -= 5.0; // small but potentially usable residual
    } else if frac >= 0.10 && frac < 0.30 {
        score += 3.0; // awkward middle band
    } else if frac >= 0.30 {
        score += 8.0 * frac; // large leftover is wasteful
    }

    // Last-chance bin: strongly prefer using the only bin that fits.
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else {
        // More competing bins -> slight penalty to preserve flexibility elsewhere.
        score += 1.5 * (fitting_bins_count.saturating_sub(1)) as f64;
    }

    // New-bin candidate handling: opening a new bin is only attractive when no open bin
    // offers a good fit (post_residual would be huge relative to capacity).
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score = 0.55 * cap;
        // Attractive if current item is large and would leave a clean residual
        // that harmonizes with common size classes.
        if item_size >= 50 {
            score -= 10.0;
        }
        let r = item_size % 10;
        if r == 0 {
            score -= 5.0; // item size is a harmonic of 10 -> predictable residual
        }
        // If many open bins exist with large mean residual, prefer reusing them.
        score += 0.2 * mean_residual;
        // Early in the stream, opening bins is cheaper (more items to fill them later).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
        // If next item is small, a fresh bin can absorb it well.
        if next_item_size > 0 && next_item_size <= 20 {
            score -= 6.0;
        }
    }

    // Mild global pressure: with many open bins, favor consolidation into existing bins.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = 0.0;

    // Base: prefer filling bins tightly (low post_residual).
    score += post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful
    // later are heavily penalized (unusable gap creation).
    let dead_zone_max = 12u32;
    if post_residual > 0 && post_residual <= dead_zone_max {
        let depth = (dead_zone_max - post_residual + 1) as f64;
        score += 25.0 * depth / dead_zone_max as f64;
    }
    // Perfect fit is strongly rewarded.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward fitting snugly relative to bin residual (high fill ratio).
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 15.0 * fill_ratio;

    // Open-bin pressure: discourage spreading across many bins,
    // but relax pressure as the stream progresses.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 3.0 * open_bins_count as f64 * (1.0 - 0.5 * progress);

    // Prefer bins whose residual is already below average (consolidation).
    score += 0.3 * (mean_residual - bin_residual as f64).max(0.0);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead coupling: if the next item could use the post_residual,
    // reward leaving exactly that much space.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 35.0;
        } else if post_residual >= next_item_size {
            score -= 10.0;
        } else {
            // post_residual too small for next item: mild penalty unless it's ~0.
            if post_residual > 0 {
                score += 8.0;
            }
        }
    }

    // New-bin candidate handling: make the fresh bin attractive only when
    // placing here would create dead space or no open bin fits well.
    if bin_residual == bin_capacity {
        let poor_fit = post_residual > 0 && post_residual <= dead_zone_max;
        if poor_fit || (fitting_bins_count <= 1) {
            score -= 20.0; // open a new bin rather than fragment
        } else {
            score += 45.0; // keep using existing bins when fit is decent
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    }
    // Near-match bonus decaying with distance to next item size.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 20.0 * (-slack / 15.0).exp();
    }

    // Penalize unusable dead space (residual below smallest plausible item).
    if post_residual < 10 {
        score += 15.0;
    }

    // Prefer bins with residual close to mean (balanced packing), penalize outliers.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a new bin when open bins could still absorb the item.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 + 10.0 * progress;
    }

    // Mild penalty for spreading across too many open bins.
    score += 0.3 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Reward tight fits: subtract based on fraction of bin consumed.
    let fill_frac = item_size as f64 / bin_capacity as f64;
    score -= 30.0 * fill_frac * fill_frac;

    // Penalize small dead space less if it equals zero (perfect fit).
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual < 10 {
        score -= 12.0;
    }

    // Lookahead: reward leaving room for the next item.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 8.0 + 0.05 * next_item_size as f64;
        } else {
            // penalize blocking next item only mildly late in stream
            score += 6.0 * (1.0 - progress);
        }
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: it is the empty bin when residual == capacity.
    let is_new_bin = bin_residual == bin_capacity && post_residual == bin_capacity - item_size;
    if is_new_bin {
        // Prefer new bin when existing fits are poor (large post_residual elsewhere)
        // and when few bins are open or late in the stream.
        score = 55.0 + 0.3 * post_residual as f64 - 20.0 * progress - 1.5 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 10.0;
        }
    }

    // Prefer bins with below-mean residual (consolidate waste into few bins).
    if !is_new_bin {
        if (bin_residual as f64) < mean_residual {
            score -= 5.0;
        } else {
            score += 3.0;
        }
    }

    // Mild pressure to close bins as stream progresses.
    score += 0.02 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let capacity = bin_capacity as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let post = post_residual as f64;
    let post_norm = post / capacity;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let poly = post_norm * post_norm * (1.0 - post_norm) * (1.0 - post_norm);
    let coupling = poly * (progress * progress * (3.0 - 2.0 * progress));

    let mut score = post;

    // Reward tight fits more strongly as the stream progresses.
    score -= 30.0 * coupling;

    // Penalize dead space relative to capacity with a smooth saturating term.
    let dead = (post / capacity).powi(3);
    score += 12.0 * dead * (1.0 + progress);

    // Last-chance bin: strongly reward using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0 * (1.0 - post_norm);
    }

    // Lookahead: reward if next item fits into the post residual.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if next <= post {
            score -= 15.0 * (1.0 - (next / capacity));
        } else {
            score += 8.0 * ((next - post) / capacity);
        }
    }

    // Mild penalty for spreading across many open bins.
    score += 0.5 * open_bins_count as f64 * post_norm;

    // Smooth alignment with mean residual state.
    score += 0.1 * (post - mean_residual) * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: overwhelming reward.
    if post_residual == 0 {
        score -= 1000.0;
        return score;
    }

    // Harmonic class of post_residual: dead space in the lowest class
    // (1..=10) is nearly unusable since items are >= 1; penalize hard.
    let dead_class = post_residual <= 10;
    if dead_class {
        score += 60.0;
    }

    // Reward bins whose residual after placement can host the next item
    // (chained fit). Exact next-item fit is even better.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 - 0.2 * slack;
            if post_residual == next_item_size {
                score -= 300.0;
            }
        } else {
            // post_residual too small for the next item: dead space risk
            score += 15.0;
        }
    }

    // Integer-division thresholds on post_residual (harmonic bands).
    let band = post_residual / 25; // 0..=4
    score += band as f64 * 5.0; // prefer bins leaving larger, reusable chunks

    // Modulo arithmetic: residuals that are multiples of common size
    // fractions of capacity are more reusable.
    if post_residual % 10 == 0 {
        score -= 8.0;
    }
    if post_residual % 20 == 0 {
        score -= 8.0;
    }
    if post_residual % 50 == 0 {
        score -= 10.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: neutral-ish base, but attractive when current open
    // bins would leave bad dead space. Opening a bin is penalized slightly
    // so we only do it when placements are poor.
    if bin_residual == bin_capacity {
        score += 45.0 + 0.3 * mean_residual;
        // Late in the stream, avoid opening bins for small leftovers.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
    }

    // Prefer filling bins that are already well-used (large item share).
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 30.0 * fill_ratio;

    // Coupling with mean residual: prefer bins below the mean residual
    // (tighter bins) to consolidate fragmentation.
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Many open bins: encourage closing them out (prefer low-residual bins).
    if open_bins_count > 4 {
        score += 0.15 * post_residual as f64 * (open_bins_count as f64 / 10.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful
    // to any plausible future item are heavily penalized.
    let dead_threshold = 10.0;
    if post_residual > 0 && (post_residual as f64) < dead_threshold {
        score += 60.0 * (dead_threshold - post_residual as f64);
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 80.0;
    } else {
        // Mild convex penalty on leftover space to prefer tight fits.
        let r = post_residual as f64;
        score += 0.35 * (r * r) / bin_capacity as f64;
    }

    // Lookahead: if the next item fits into the post-residual, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    } else if next_item_size > 0 {
        // Next item won't fit here; penalize proportionally to how close we are.
        score += 8.0 * (next_item_size as f64 - post_residual as f64).min(20.0);
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Open-bin pressure: discourage opening new bins when many bins are open,
    // encourage consolidation into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (0.5 + 0.5 * progress);

    // New-bin candidate: make an empty bin moderately attractive only when the
    // item is large relative to capacity or mean residual across bins is tight.
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        let tight = mean_residual < item_size as f64 * 1.2;
        score -= 10.0 + 20.0 * fill_ratio;
        if tight {
            score += 30.0; // existing bins are nearly full; new bin is fine
        }
    }

    // Small nudge toward bins whose residual is close to the item (best-fit flavor).
    score += 0.2 * (bin_residual - item_size) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match of post_residual to next item.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= (bin_capacity as f64 / 2.0) * (1.0 - diff / (bin_capacity as f64 / 2.0)).max(0.0);
        // Perfect chain: next item fills bin exactly -> strong reward
        if post_residual == next_item_size {
            score -= 50.0;
        }
        // Chain: after placing next item, residual would be small
        if next_item_size <= post_residual {
            let chain_residual = post_residual - next_item_size;
            score -= (chain_residual < 10) as i32 as f64 * 20.0;
        } else {
            // Next item won't fit here; mild penalty if post_residual too small to be useful
            if post_residual < 10 {
                score += 15.0;
            }
        }
    } else {
        // Last item: prefer minimal residual
        score -= 30.0;
    }

    // Penalize wasted space relative to mean residual of open bins
    score += (post_residual as f64 - mean_residual) * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Penalize opening a new bin when open bins exist with reasonable residual
    if bin_residual == bin_capacity && open_bins_count > 0 {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 25.0 + 20.0 * progress;
    }

    // Slight preference for tighter fits overall
    score += (item_size as f64 / bin_residual.max(1) as f64) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual)
    score -= (post_residual as f64 / bin_capacity as f64).powf(2.0) * 20.0;

    // Penalize dead space: residual too small for the smallest plausible item
    if post_residual < 10 && post_residual > 0 {
        score += 15.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead coupling: reward leaving room for the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0 * (1.0 - (next_item_size as f64 / bin_capacity as f64));
        } else if bin_residual >= next_item_size && post_residual < next_item_size {
            // placing here destroys the chance to fit next item
            score += 6.0;
        }
    }

    // Global state: prefer filling bins when many bins are open
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= (open_bins_count as f64).ln().max(0.0) * 2.0 * (0.5 + progress);

    // Prefer bins with residuals far below mean residual (consolidate emptier bins)
    let diff = mean_residual - bin_residual as f64;
    score += diff * 0.15;

    // New-bin candidate: penalize opening a new bin unless current fits are terrible
    if bin_residual == bin_capacity {
        score += 12.0 + 10.0 * (1.0 - progress);
        // allow new bin when no open bin fits well
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let post = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_post = post / cap;

    // Smooth non-linear polynomial coupling of post_residual with stream progress.
    let mut score = post * (1.0 + 0.9 * progress * progress);

    // Penalize very tight fits less as stream progresses (use residual space while we can).
    let tightness = 1.0 - norm_post;
    score -= 12.0 * tightness * tightness * (0.4 + 0.6 * progress);

    // Penalize dead space that cannot hold a plausible next item: smooth sigmoid-like coupling.
    let gap = (post - next_item_size as f64).max(0.0);
    let unusable = gap / (1.0 + gap * 0.05);
    score += 0.8 * unusable * (1.0 - progress);

    // Reward bins whose residual is far from the mean (consolidation), smoothly weighted.
    let dev = (post - mean_residual).abs();
    score -= 0.25 * dev * dev / (mean_residual + 10.0);

    // Last-chance bin bonus: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 25.0 + 15.0 * progress;
    }

    // Mild penalty for spreading across many open bins, eased over time.
    score += 0.15 * open_bins_count as f64 * (1.0 - 0.5 * progress);

    // New-bin candidate: make empty bins less attractive unless item is large relative to residual norms.
    if bin_residual == bin_capacity {
        let large_item = item_size as f64 / cap;
        score += 10.0 - 14.0 * large_item * large_item;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify leftover space by
    // capacity fraction bands (integer division thresholds).
    let frac = (post_residual as f64) / (bin_capacity as f64);
    let class = post_residual / (bin_capacity / 10); // 10 discrete capacity-decile classes

    // Reward residual classes that are "harmonically useful": small leftovers
    // (tight fits) are good; mid-range leftovers (20..50) are dead-space risks.
    match class {
        0 => score -= 30.0,               // near-perfect fit
        1 => score -= 22.0,               // small leftover, still usable for tiny items
        2 | 3 => score += 8.0,            // risky dead space (20-40)
        4 | 5 => score += 14.0,           // worst zone: neither tight nor roomy
        _ => {}                            // large residuals are neutral-ish
    }

    // Modulo arithmetic on post_residual: leftovers divisible into common
    // small-item sizes (mod 5 == 0) are more likely reusable.
    if post_residual % 5 == 0 && post_residual > 0 {
        score -= 6.0;
    }
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 4.0;
    }

    // Lookahead coupling: does next item fit the post residual (exact or class match)?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0; // perfect follow-up
        } else if next_item_size <= post_residual {
            let slack = post_residual - next_item_size;
            // Harmonic bonus if the double leftover is again in a good class
            if slack <= bin_capacity / 10 {
                score -= 18.0;
            } else {
                score -= (slack as f64) * 0.3;
            }
        } else {
            // Next item won't fit here: penalize proportionally to overshoot
            score += ((next_item_size - post_residual) as f64) * 0.25;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Late in the stream, consolidate: prefer existing bins over new ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses and when
        // mean residual across open bins is still healthy.
        score += 25.0 + 30.0 * progress + mean_residual * 0.2;
    } else {
        score -= 10.0 * progress;
    }

    // Mild pressure toward bins below mean residual (use up emptier bins first).
    score += (mean_residual - bin_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

