    // are "dead" — penalize them quadratically.
    let dead_threshold = next_item_size.max(1);
    if post_residual < dead_threshold && post_residual > 0 {
        score += 40.0 + (dead_threshold - post_residual) as f64 * 2.0;
    }
    // Tiny unusable slivers (below minimum plausible item size) are worst.
    if post_residual < 10 && post_residual > 0 {
        score += 30.0 * (10.0 - post_residual as f64) / 10.0;
    }

    // Reward tight fits (small post_residual relative to capacity).
    score -= (bin_capacity - post_residual) as f64 * 0.3;

    // Open-bin pressure: discourage spreading across many bins when residuals
    // are still generous; encourage consolidation.
    if open_bins_count > 1 {
        score += open_bins_count as f64 * 0.5 * (mean_residual / bin_capacity as f64);
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if next item fits exactly in the post-residual, reward this placement.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 35.0;
    }

    // New empty bin candidate: penalize mildly, more so early in the stream
    // (consolidate first), less so later (dead-space escapes matter more).
    if bin_residual == bin_capacity {
        score += 15.0 + 20.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimal post_residual (tight fit), with quadratic penalty on waste.
    score += 0.5 * (post_residual as f64 / bin_capacity as f64).powi(2) * bin_capacity as f64;

    // Aggressive 2-step lookahead: reward exact match of post_residual with next item.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 8.0 * (1.0 - diff / (bin_capacity as f64)).max(0.0).powi(3);
        // Perfect chain bonus: next item fills bin exactly.
        if post_residual == next_item_size {
            score -= 15.0;
        }
        // Penalize post_residual slightly larger than next item (dead space just above it).
        if post_residual > next_item_size && post_residual - next_item_size < 10 {
            score += 6.0;
        }
    }

    // Relative-to-mean-residual coupling: prefer bins whose residual deviates
    // toward zero after placement relative to the fleet mean.
    let mean_post = mean_residual - item_size as f64;
    score += 0.35 * (post_residual as f64 - mean_post).max(0.0);

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a new bin is penalized when any open
    // bin gives a decent fit, but allowed when fits are terrible.
    if bin_residual == bin_capacity {
        let waste = bin_residual as f64 - post_residual as f64;
        let good_fit_threshold = 0.25 * bin_capacity as f64;
        if fitting_bins_count > 0 {
            // Only open new bin if best existing fit leaves large waste.
            score += 25.0 + (waste - good_fit_threshold).max(0.0) * -0.5;
            // Encourage new bin late in stream when many bins are nearly full.
            let progress = step_index as f64 / total_items.max(1) as f64;
            score -= 10.0 * progress * (mean_residual / bin_capacity as f64).powi(2);
        } else {
            score = -100.0;
        }
    }

    // Mild penalty for spreading across too many open bins.
    score += 0.05 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let is_new_bin = bin_residual == bin_capacity;

    if is_new_bin {
        // Penalize opening a new bin by default so existing bins win on tight fits.
        score += 28.0;
        // If no open bin can fit the item, opening a new bin is the only option.
        if fitting_bins_count == 0 {
            score -= 80.0;
        } else {
            // Prefer a new bin when the leftover here is very small (poor fit elsewhere)
            // or when the next item would not fit in this fresh bin's post-residual anyway.
            if post_residual <= 10 {
                score -= 18.0;
            }
            if next_item_size > 0 && next_item_size > post_residual {
                score -= 10.0;
            }
            // Late in the stream, avoid proliferating bins with large fresh residuals.
            score += 12.0 * progress;
        }
        // If current open bins are heavily fragmented (high mean residual), a fresh
        // bin is relatively more attractive.
        if mean_residual > 40.0 {
            score -= 6.0;
        }
    } else {
        // Reward choosing an existing bin (slight constant preference).
        score -= 6.0;
        // Last-chance bin: strongly favor using it to avoid opening a new bin.
        if fitting_bins_count == 1 {
            score -= 22.0;
        }
        // Perfect lookahead match: next item exactly fills the post-residual.
        if next_item_size > 0 && next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size > 0 && next_item_size <= post_residual {
            // Next item still fits here: mild bonus for keeping compatibility.
            score -= 6.0;
        } else if next_item_size > post_residual {
            // Next item would be stranded; penalize creating this dead space.
            score += 0.08 * (next_item_size - post_residual) as f64;
        }
        // Below-average residual means this bin is already tight — good to fill it.
        if (post_residual as f64) < mean_residual {
            score -= 5.0;
        } else {
            score += 2.0;
        }
        // Perfect fill bonus.
        if post_residual == 0 {
            score -= 40.0;
        }
        // Early in the stream, be slightly greedy about tight fits; later, conserve bins.
        score -= 5.0 * (1.0 - progress);
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;

    // Smooth non-linear polynomial coupling of post_residual with stream progress.
    let pr = post_residual as f64;
    let pr_norm = pr / cap;
    let p = progress;
    // Polynomial interaction: waste is penalized more heavily as the stream progresses.
    let coupling = pr_norm * pr_norm * (0.5 + 1.5 * p) + pr_norm * pr_norm * pr_norm * (1.0 + 2.0 * p);
    score += 30.0 * coupling;

    // Reward tight fits (small post_residual) with a smooth saturating term.
    let tightness = (-pr_norm * 4.0).exp();
    score -= 12.0 * tightness * (0.6 + 0.4 * p);

    // Lookahead: penalize if the next item cannot use this bin's post-residual.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            // Next item fits: reward proportionally to how well it fills the leftover.
            let fill_after = (pr - nxt) / cap;
            score -= 10.0 * (1.0 - fill_after) * (1.0 - fill_after);
        } else {
            // Next item won't fit here: penalize dead space more as stream progresses.
            score += 8.0 * pr_norm * (0.5 + p);
        }
    }

    // Last-chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 + pr_norm);
    }

    // Mild penalty for spreading across many open bins late in the stream.
    score += (open_bins_count as f64).ln().max(0.0) * (1.0 + 3.0 * p);

    // Encourage bins whose residual is near the mean (balanced packing).
    let dev = (pr - mean_residual).abs() / cap;
    score += 5.0 * dev * dev;

    // New-bin candidate: make it moderately attractive only for large items early on,
    // less attractive for small items or late in the stream.
    if bin_residual == bin_capacity {
        let item_frac = item_size as f64 / cap;
        score = 20.0 * (1.0 - item_frac) + 15.0 * p - 8.0 * item_frac * item_frac;
        if next_item_size > 0 && pr >= next_item_size as f64 {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo arithmetic on capacity fractions.
    // Residuals that are "nice" divisors of 100 (0, 10, 20, 25, 50) are reusable.
    let pr = post_residual;
    let harmonic_penalty: f64 = if pr == 0 {
        -40.0 // perfect fit
    } else if pr <= 10 {
        0.0 // small dead space, likely unusable but cheap
    } else if pr % 25 == 0 || pr % 10 == 0 {
        -8.0 // reusable residual class
    } else if pr < 20 {
        12.0 // awkward dead space: too big to waste, too small to reuse
    } else {
        4.0
    };
    score += harmonic_penalty;

    // Coupling with next item: does post_residual admit the lookahead item?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // How tightly does the next item fit into the leftover?
            let tight = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - tight / bin_capacity as f64);
            if (post_residual - next_item_size) == 0 {
                score -= 25.0; // chain of perfect fits
            }
        } else {
            score += 6.0; // leftover won't host next item
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only prefer opening when this bin is empty AND
    // the item leaves a bad residual in every plausible class.
    if bin_residual == bin_capacity {
        let bad_fit = post_residual > 0 && post_residual < 15;
        let late_stream = total_items > 0 && (step_index as f64) / (total_items as f64) > 0.7;
        if bad_fit && late_stream {
            score -= 5.0; // open new bin to avoid dead space late in stream
        } else {
            score += 20.0; // prefer filling open bins generally
        }
    }

    // Slight pressure to consolidate when many bins are open.
    score += 0.3 * open_bins_count as f64 * (mean_residual - post_residual as f64).max(0.0) / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the minimum item
    // (1..10) are unusable "waste"; penalize them heavily.
    if post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0;
    }

    // Reward tight fits (small but still usable residual).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 15.0 * tightness * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead: if next item fits exactly in the post-residual, reward strongly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap == 0 {
            score -= 50.0;
        } else if gap < 10 {
            score -= 20.0;
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        // Post-residual unusable by the lookahead item: penalize proportionally.
        score += 10.0 * (next_item_size as f64 - post_residual as f64) / 10.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones
    // (make the new-bin candidate expensive) but encourage consolidation.
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline cost plus pressure from open bins.
        score += 20.0 + 8.0 * open_bins_count as f64;
        // If nothing else fits well (few fitting bins), new bin is fine.
        if fitting_bins_count <= 1 {
            score -= 30.0;
        }
    } else {
        // Favor bins whose residual is close to the mean (consolidation).
        score -= 0.05 * (bin_residual as f64 - mean_residual).abs();
    }

    // Early in the stream, allow more bins; late in the stream, pack tighter.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress * (1.0 - tightness);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next item.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score += 0.9 * gap;
        if post_residual == next_item_size {
            score -= 25.0; // perfect 2-step pairing
        } else if post_residual > next_item_size {
            score -= 4.0; // can still fit next item after this
        } else {
            score += 2.0; // next item won't fit; dead space penalty
        }
    }

    // Prefer tight fits relative to mean residual
    score -= 0.35 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Penalize opening a new bin unless current bins are nearly full
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let avg_fill = bin_capacity as f64 - mean_residual;
        if avg_fill < 0.35 * bin_capacity as f64 {
            score += 30.0; // existing bins too empty, don't open new one
        } else {
            score -= 5.0 + 10.0 * progress;
        }
    }

    // Slight preference for filling fuller bins
    score -= 0.1 * (bin_capacity as f64 - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: quadratic penalty on wasted space relative to capacity.
    let waste_frac = post_residual as f64 / bin_capacity as f64;
    score += 60.0 * waste_frac * waste_frac;

    // Perfect or near-perfect fit gets a strong bonus.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    } else if post_residual < 10 {
        score -= 15.0;
    }

    // Lookahead: strongly reward bins whose post_residual exactly matches the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 80.0;
        } else if post_residual > next_item_size && post_residual - next_item_size < 10 {
            score -= 25.0;
        } else if next_item_size > post_residual && next_item_size - post_residual < 10 {
            // next item nearly fits after placement: mild bonus
            score -= 8.0;
        }
        // Penalize leaving residual slightly larger than next item (dead space trap)
        if post_residual > next_item_size && post_residual - next_item_size < 4 {
            score += 5.0;
        }
    }

    // Last-chance bin: avoid opening a new bin if this is the only fitting one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is terrible
    // or we are early with few open bins (spreading load can help).
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let fit_quality = item_size as f64 / bin_capacity as f64;
        // Base cost of a fresh bin
        score += 45.0;
        // Early in stream, opening bins is cheaper (build a portfolio of partial bins)
        score -= 40.0 * (1.0 - progress);
        // Very large items fit well in fresh bins
        score -= 35.0 * fit_quality;
        // If many open bins already have slack, prefer reusing them
        score += 0.3 * mean_residual;
        // If this bin is the only option, new bin is fine
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
    } else {
        // Reusing an existing bin: reward consolidation when many bins are open
        score -= (open_bins_count as f64).sqrt() * 2.0;
        // Reward placing into bins whose residual is below the mean (tightening loose bins)
        if (bin_residual as f64) < mean_residual {
            score -= 6.0;
        } else {
            score += 3.0;
        }
    }

    // Small global regularization
    score += 0.01 * mean_residual;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit = item_size as f64 / cap;

    // Base: post-residual, with non-linear (quadratic/cubic) coupling to progress.
    // Early on, larger residuals are fine; later, penalize leftover space more strongly.
    let mut score = pr * (1.0 + 0.8 * progress) + 0.004 * pr * pr * (0.3 + 0.7 * progress);

    // Reward tight fits: small post_residual relative to capacity gets a smooth discount.
    let tightness = 1.0 - (pr / cap);
    score -= 12.0 * tightness * tightness * fit;

    // Penalize dead space: residual too small for the smallest plausible item.
    let dead = (1.0 - pr / cap).min(1.0).max(0.0);
    if pr > 0.0 && pr < 10.0 {
        score += 8.0 * (10.0 - pr) as f64 * (0.5 + 0.5 * progress);
    }

    // Lookahead coupling: if the next item fits the post-residual, reward; smooth polynomial.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let gap = pr - nx;
        if gap >= 0.0 {
            let u = 1.0 - gap / cap;
            score -= 6.0 * u * u * u;
        } else {
            score += 3.0 * (-gap / cap) * (1.0 + progress);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    // over opening a new bin (smooth ramp with fitting_bins_count).
    if fitting_bins_count >= 1 {
        score -= 15.0 / fitting_bins_count as f64;
    }

    // Mean-residual divergence: placing into a bin far below mean residual
    // (i.e. leaving big bins untouched) is mildly penalized.
    score += 0.05 * (mean_residual - pr).abs() * (0.5 + 0.5 * progress);

    // New-bin candidate: empty bin has bin_residual == bin_capacity.
    if bin_residual == bin_capacity {
        // Prefer new bin only when existing bins would leave very poor fits
        // (post_residual small) or late in the stream; otherwise discourage.
        let poor_fit = (1.0 - pr / cap).max(0.0);
        score += 18.0 - 14.0 * poor_fit * poor_fit - 6.0 * progress;
    }

    // Mild penalty for proliferation of open bins.
    score += 0.3 * open_bins_count as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residuals divisible by 10 are
    // more reusable, since item sizes 1..100 commonly align to decade steps.
    let harmonic = if post_residual == 0 {
        -40.0 // perfect fit: strongly favored
    } else if post_residual % 10 == 0 {
        -12.0
    } else if post_residual % 5 == 0 {
        -4.0
    } else {
        6.0 // awkward residual, penalize
    };
    score += harmonic;

    // Small dead space is fine, large dead space is wasted capacity.
    if post_residual > 0 && post_residual < 10 {
        score -= 8.0;
    } else if post_residual > 50 {
        score += (post_residual as f64 - 50.0) * 0.5;
    }

    // Lookahead: if the next item fits exactly into the post residual,
    // reward chaining; if next item cannot fit anywhere else, keep space.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            score -= 5.0;
        } else {
            // next item won't fit here regardless; mild penalty for
            // leaving a residual that no typical item can use
            if post_residual > 0 && post_residual < 10 {
                score += 4.0;
            }
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin to
    // avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when current bins fit poorly
    // (large mean residual wasted) or few bins can fit the item.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 1.0 } else { 1.0 / fitting_bins_count as f64 };
        let waste = (mean_residual - item_size as f64).max(0.0);
        score = 60.0 + waste * 0.4 - pressure * 20.0;
        // late in the stream, prefer consolidating into open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 15.0;
    }

    // Prefer filling bins that are already quite full (tighter packing).
    let fullness = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= fullness * 6.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (< 10, min item size)
    // are the worst outcome; penalize them heavily.
    if post_residual < 10 {
        score += 60.0;
    } else if post_residual <= 20 {
        // Gaps too small for most items: dead-space zone.
        score += 25.0 * (1.0 - (post_residual as f64 - 10.0) / 10.0);
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 40.0;
    }

    // Reward tight fits: fraction of residual consumed.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 15.0 * fill_ratio;

    // Lookahead: if the next item fits the post-residual exactly, reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
        // Extra reward if next item consumes the gap almost fully.
        if post_residual - next_item_size < 10 {
            score -= 6.0;
        }
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Post-residual too small for the next item: penalize mildly.
        score += 5.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading; prefer
    // filling existing bins tightly.
    let open_pressure = (open_bins_count as f64).ln().max(0.0);
    score += 3.0 * open_pressure * (1.0 - fill_ratio);

    // New-bin candidate: penalize opening a new bin when open bins exist,
    // unless the item is large relative to capacity (better to start fresh).
    if bin_residual == bin_capacity {
        let base = 25.0 + 2.0 * open_bins_count as f64;
        if item_size >= 70 {
            score = base - 10.0; // large item: fresh bin is fine
        } else {
            score = base;
        }
        // Early in stream, new bins are cheaper.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 10.0 * (1.0 - progress);
    } else {
        // Prefer bins with residual close to mean (balanced packing) slightly.
        score += 0.05 * ((bin_residual as f64 - mean_residual).abs());
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus: nearly-full bin is ideal.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual < 5 {
        score -= 200.0;
    }

    // Aggressive 2-step lookahead: reward if next item fits into post_residual.
    if next_item_size > 0 && post_residual >= next_item_size {
        // Exact match of next item to post_residual is a chain fit.
        let slack = (post_residual - next_item_size) as f64;
        score -= 150.0 - slack * 0.8;
        if slack == 0.0 {
            score -= 500.0; // perfect 2-step chain
        }
    } else if next_item_size > 0 && post_residual > 0 {
        // Next item won't fit here: penalize dead space relative to next item.
        let waste = (post_residual as f64).min(next_item_size as f64);
        score += waste * 0.5;
    }

    // Compare residual to mean residual: prefer bins tighter than average.
    score += (bin_residual as f64 - mean_residual) * 0.3;

    // Last-chance bin: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 120.0;
    }

    // Penalize opening new bins early in the stream; accept later when crowded.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive if item is large and no tight fit exists.
        let large_item = item_size as f64 > bin_capacity as f64 * 0.6;
        score = 400.0
            - if large_item { 150.0 } else { 0.0 }
            - progress * 50.0
            + if fitting_bins_count > 0 { 200.0 } else { 0.0 };
    }

    // Slight preference to fill crowded sets of bins.
    score -= open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: strongly favor bins where the item fills most of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 40.0 * fill_ratio * fill_ratio;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual < 10 {
        score -= 30.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
            // Extra reward if next item then leaves a small remnant (chained fits).
            let chained = post_residual - next_item_size;
            if chained < 10 {
                score -= 8.0;
            }
        } else {
            // Dead space if next item can't use the leftover.
            score += 6.0 * (next_item_size as f64 - post_residual as f64).min(20.0) / 20.0;
        }
    } else {
        // Last item: prefer closing bins completely.
        score += 5.0 * post_residual as f64;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate logic: only attractive when existing fits are poor.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let poor_fit = post_residual as f64 > 40.0; // item leaves big hole in any bin
        if poor_fit || fitting_bins_count == 0 {
            score -= 35.0 + 15.0 * (1.0 - progress);
        } else {
            score += 30.0;
        }
        // Mild penalty for proliferating bins when mean residual is still large.
        score += 0.3 * mean_residual * (open_bins_count as f64).sqrt() * 0.2;
    }

    // Prefer bins below mean residual (consolidate fuller bins).
    score += 0.15 * (bin_residual as f64 - mean_residual).max(0.0);

    // Late in the stream, prioritize closing bins to avoid stranded capacity.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Base: minimize wasted residual, with a smooth non-linear (quadratic-ish) coupling
    let mut score = pr + 0.9 * (pr * pr) / cap;

    // Tight fits are strongly preferred: reward when post_residual is small relative to item
    let tightness = 1.0 - (post_residual as f64 / bin_residual.max(1) as f64);
    score -= 18.0 * tightness * tightness;

    // Lookahead: if the next item fits into the post-residual, reward this placement
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let slack_match = 1.0 - ((pr - nxt) / cap);
            score -= 10.0 * slack_match;
        } else {
            // next item won't fit here; mild penalty proportional to overshoot
            score += 3.0 * ((nxt - pr) / cap);
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        // among many candidates, mildly prefer fuller bins
        score += 2.0 * (fitting_bins_count as f64 - 1.0).ln().max(0.0);
    }

    // New-bin candidate handling: penalize opening a new bin, more so early on
    if bin_residual == bin_capacity {
        let open_penalty = 20.0 + 40.0 * (1.0 - progress);
        score += open_penalty;
        // but if no open bin fits, opening is fine
        if fitting_bins_count == 0 {
            score -= open_penalty;
        }
    }

    // Stream-progress coupling: later in the stream, be greedier about tight fits
    score -= 6.0 * progress * (1.0 - pr / cap);

    // Mild diversity term: prefer bins whose residual deviates from the mean
    score += 1.5 * ((pr - mean_residual) / cap).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: exact-fit classes are precious.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Perfect fit -> strong reward (subtract).
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Modulo classes on post_residual: residuals that are "usable" for
    // common small items (multiples of 5, 10) are worth more.
    let mod10 = post_residual % 10;
    let mod5 = post_residual % 5;
    if mod10 == 0 {
        score -= 30.0;
    } else if mod5 == 0 {
        score -= 15.0;
    } else {
        // Penalize awkward residuals (dead space).
        score += mod5 as f64 * 3.0;
    }

    // Integer-division thresholds: post_residual bucketed into capacity fractions.
    let quarter = (bin_capacity / 4) as f64;
    if pr <= quarter * 0.5 {
        score += 40.0; // tiny residual: nearly dead space
    } else if pr <= quarter {
        score += 10.0;
    } else if pr <= quarter * 2.0 {
        score -= 5.0;
    }

    // Next item lookahead: does this bin's post-residual fit the next item?
    if next_item_size > 0 && next_item_size <= post_residual {
        // Harmonic match: reward if next item also lands on a nice class boundary.
        let next_mod = next_item_size % 10;
        let bonus = if next_mod == 0 { 60.0 } else if next_mod == 5 { 35.0 } else { 20.0 };
        score -= bonus;
    } else if next_item_size > 0 {
        // Post residual cannot host next item -> penalty scaled by leftover gap.
        score += (next_item_size - post_residual) as f64 * 0.5;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // Brand-new empty bin candidate: only attractive when residuals are poor
    // or stream is early (lots of future items to fill it).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let early = 1.0 - progress;
        let mean_gap = (mean_residual - pr).abs();
        // Open a new bin when open bins are fragmented and stream is long.
        let fragmentation = open_bins_count as f64 * 2.0;
        score = cap * 0.9 - early * 40.0 + fragmentation * 0.5 - mean_gap * 0.1;
        if next_item_size > 0 && next_item_size <= bin_capacity / 2 {
            score -= 10.0;
        }
    }

    // Mild penalty for spreading across too many bins when residual is generous.
    if open_bins_count > 8 && pr > cap * 0.5 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: harshly penalize small unusable gaps.
    if post_residual > 0 {
        // Residuals that no realistic item (>=1, but practically >=10) can use are dead space.
        if post_residual < 10 {
            score += 60.0; // tiny dead gap
        } else if post_residual < 20 {
            score += 30.0; // likely dead space
        } else if post_residual < 30 {
            score += 12.0;
        } else {
            score -= 5.0; // roomy leftover, mildly rewarded
        }
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 80.0;
    }

    // Next-item lookahead: reward if the post-residual can host the lookahead item exactly or well.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 8.0;
        score += slack * 0.15;
    }

    // Last-chance bin pressure: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Open-bin pressure: discourage opening new bins when many bins are already open.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 20.0 + (open_bins_count as f64) * 1.5;
    } else {
        // Mild reward for filling existing bins as open count grows.
        score -= (open_bins_count as f64) * 0.3;
    }

    // Progress coupling: later in the stream, tighten dead-space tolerance.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (post_residual as f64) * 0.05 * progress;

    // Mean residual coupling: penalize adding to already-loose bins.
    score += ((mean_residual - post_residual as f64) * 0.05).max(-10.0).min(10.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for exact 2-step lookahead match: post_residual == next_item_size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }

    // Reward near matches to the lookahead item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * (1.0 - (post_residual - next_item_size) as f64 / 50.0);
    }

    // Penalize residuals too small for any plausible future item (dead space)
    if post_residual < 10 {
        score += 30.0;
    }

    // Penalize bins whose residual is far above the mean (large wasted space)
    let dev = post_residual as f64 - mean_residual;
    score += 0.5 * dev;

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when no open bin fits well
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 15.0 + 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Reward tight fits: penalize post_residual non-linearly (wasted space grows in cost).
    score += (post_residual as f64).powi(2) / (bin_capacity as f64 * 10.0);

    // Lookahead: if the next item fits exactly into post_residual, strongly favor this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 15.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Next item cannot use the leftover; penalize proportionally to dead space.
        score += 0.25 * post_residual as f64 * (0.5 + progress);
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Many fitting bins: slight penalty to encourage consolidation into few bins.
    if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0).sqrt();
    }

    // Prefer bins with residual close to the mean (balanced packing), especially early.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev * (1.0 - progress);

    // New-bin candidate: accept only when residuals of open bins are mostly unusable
    // for typical items, or the item is large relative to remaining space.
    if bin_residual == bin_capacity {
        let usable = if next_item_size > 0 { next_item_size } else { item_size };
        let scarcity = (usable as f64) / (mean_residual.max(1.0));
        let threshold = 1.2 + 0.6 * progress;
        if scarcity > threshold {
            score -= 18.0; // open bins too full for upcoming demand -> new bin
        } else {
            score += 25.0; // keep using open bins when they remain viable
        }
    }

    // Late in the stream, prioritize minimizing leftover waste more aggressively.
    score *= 1.0 + 0.5 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let post = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_post = post / cap;

    // Base: quadratic coupling of post_residual with stream progress.
    // Late in the stream, tight fits (small post_residual) matter more.
    let mut score = post * (1.0 + 0.8 * norm_post * norm_post) * (1.0 + progress);

    // Smooth interaction: reward small post_residual more as progress grows.
    score -= 12.0 * (1.0 - norm_post) * (1.0 - norm_post) * progress;

    // Last-chance bonus: strongly favor this bin when it's the only fitting one.
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 + progress);
    }

    // Mild penalty when this bin's residual deviates from mean (keep bin states homogeneous).
    score += 0.15 * (post - mean_residual).abs();

    // Lookahead coupling: if the next item fits into post_residual, reward.
    if next_item_size > 0 && (next_item_size as f64) <= post {
        score -= 8.0 * (1.0 - (next_item_size as f64) / cap) * (1.0 + progress);
    } else if next_item_size > 0 {
        // Dead-space penalty if next item cannot use the leftover space.
        score += 5.0 * norm_post * (0.5 + progress);
    }

    // New-bin candidate: penalize opening a new bin smoothly, unless residual
    // is essentially untouched (fresh bin) or remaining stream is long.
    if bin_residual == bin_capacity {
        let pressure = 1.0 - progress;
        score = post + 30.0 * pressure + 0.5 * open_bins_count as f64;
        if fitting_bins_count <= 1 && next_item_size > 0 {
            score -= 15.0; // allow escape hatch when no good open bin exists
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residue classes mod 10 and integer-division thresholds
    let pr = post_residual;
    let class = pr / 10; // 0..=9 harmonic band
    // Penalize small non-zero dead space bands (unusable slivers)
    match class {
        0 => score += 8.0,             // 0..9: nearly full, but sliver risk if 1..9
        1 => score -= 2.0,             // 10..19
        2 => score -= 3.0,             // 20..29 good target
        3 => score -= 1.0,
        4 => score += 0.5,
        5 => score += 1.5,
        6 => score += 2.5,
        7 => score += 3.5,
        8 => score += 4.5,
        _ => score += 5.5,             // 90..99: worst, bin almost untouched
    }
    // Exact-zero residual is perfect
    if pr == 0 { score -= 50.0; }
    // Tiny sliver 1..9 is dead space
    if pr >= 1 && pr <= 9 { score += 12.0; }

    // Coupling with next item: reward residuals that can host next_item_size
    if next_item_size > 0 {
        if next_item_size <= pr {
            // next item fits here: keep residual in a harmonic class matching next size
            let bucket = (pr / (next_item_size.max(1))) as f64;
            score -= 4.0 + bucket.min(3.0);
            // perfect chain: post_residual exactly equals next size
            if pr == next_item_size { score -= 15.0; }
        } else {
            // next item won't fit in this residual: mild penalty scaled by gap
            score += ((next_item_size - pr) as f64) * 0.15;
        }
        // modulo coupling: next_item_size class vs post_residual class
        let nclass = (next_item_size / 10) as f64;
        score += (nclass - class as f64).abs() * 0.4;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 20.0;
    } else if fitting_bins_count > 1 {
        // among many candidates, prefer tighter fits (already via post_residual)
        score += (fitting_bins_count as f64 - 1.0) * 0.5;
    }

    // New-bin candidate handling
    if bin_residual == bin_capacity {
        // Opening a new bin: baseline cost + discourage early in stream / when mean residual is large
        score = 60.0
            - mean_residual * 0.6
            - (open_bins_count as f64) * 1.5;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            // fresh bin can host anything; slight bonus late in stream
            score -= (step_index as f64 / total_items.max(1) as f64) * 5.0;
        }
        // Never open a new bin if this is a last-chance fit
        if fitting_bins_count == 1 { score += 100.0; }
        // Don't open new bin if post_residual sliver could be avoided elsewhere
        if pr >= 1 && pr <= 9 { score += 10.0; }
    }

    // Progression: as stream advances, be greedier about tight fits
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (bin_residual as f64 - post_residual as f64) * 0.3;

    // Mean residual alignment: prefer bins whose residual is near the mean (keeps balance)
    score += ((bin_residual as f64 - mean_residual).abs()) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize unusable dead space: gaps too small for typical items (1..=100).
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 25 {
        score += 25.0;
    }

    // Reward tight fits strongly.
    score -= 20.0 / (1.0 + post_residual as f64);

    // Exact fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead: reward if next item fits the post residual (keeps bin useful).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0;
        } else {
            score += 10.0;
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: with many open bins, favor filling existing ones
    // over opening new bins; make the new-bin candidate less attractive.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (1.0 + progress);
    if bin_residual == bin_capacity {
        score += 30.0 + pressure;
    } else {
        score -= pressure * 0.5;
    }

    // Prefer bins tighter than the mean residual (better consolidation).
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    } else {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward perfect or near-perfect fits (small dead space)
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 25.0;
    }

    // 2-step lookahead: reward if next item exactly fills the post residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if post_residual >= next_item_size {
            let leftover = post_residual - next_item_size;
            // reward proportionally to how well next item fits after this placement
            score -= 40.0 * (1.0 - leftover as f64 / bin_capacity as f64);
            if leftover <= 5 {
                score -= 30.0;
            }
        } else {
            // next item won't fit here after placement; slight penalty scaled by gap
            let gap = (next_item_size - post_residual) as f64;
            score += 5.0 * (gap / 100.0).min(1.0);
        }
    }

    // Penalize leaving residuals that are hard to reuse (large but unusable chunks)
    if post_residual > 0 && post_residual < 10 {
        score += 20.0; // tiny slivers are wasted unless perfect fit already rewarded
    }

    // Compare against mean residual: prefer bins tighter than average
    let diff = mean_residual - bin_residual as f64;
    score += 0.5 * diff.max(0.0); // penalize bins with more residual than mean (worse fit)
    score -= 0.3 * (-diff).max(0.0); // mild reward for tighter-than-average bins

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate handling: only attractive when no good fit exists
    if bin_residual == bin_capacity {
        let base = 150.0;
        // cheaper to open a new bin early in stream or when few bins open
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score = base + 100.0 * progress + 5.0 * open_bins_count as f64;
        // if item is large relative to capacity, new bin is fine
        score -= 20.0 * (item_size as f64 / bin_capacity as f64);
        // if only one fitting bin and it's tight, discourage abandoning it too eagerly
        if fitting_bins_count == 1 && (bin_residual - item_size) > 0 {
            let wasted = (bin_residual - item_size) as f64;
            if wasted > 40.0 {
                score += 30.0; // keep poor-fit bin penalty: opening new bin ok
            }
        }
        // lookahead: if next item is huge, a fresh bin may serve it better
        if next_item_size >= 70 {
            score -= 40.0;
        }
    }

    // Slight preference for consolidating when many bins are open
    if open_bins_count > 5 {
        score += 0.5 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through the stream (0..1)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Primary: reward tight fits — minimize post_residual with a mild superlinear shaping.
    let cap_f = bin_capacity as f64;
    let tightness = 1.0 - (post_residual as f64 / cap_f);
    score -= 18.0 * tightness * tightness;

    // Penalize residual that is too small to ever hold a typical item (dead space),
    // but only mildly — small residuals are the goal of packing.
    if post_residual > 0 && post_residual < 10 {
        score += 6.0;
    }

    // Lookahead (k=2): strongly reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Chain fit: reward proportionally to how well the leftover matches next item.
            let chain_tight = 1.0 - (post_residual as f64 - next_item_size as f64) / cap_f;
            score -= 12.0 + 10.0 * chain_tight;
        } else {
            // Next item won't fit here after placement: slight penalty, more if residual is wasted.
            score += 4.0 + 0.05 * (post_residual as f64 - next_item_size as f64).max(0.0);
        }
    }

    // Last-chance bin: if this is the ONLY bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Global congestion: when many bins are open, discourage opening new ones
    // (the new-bin candidate has bin_residual == bin_capacity and gets this penalty).
    if bin_residual == bin_capacity {
        let congestion = open_bins_count as f64;
        score += 8.0 + 2.0 * congestion.sqrt() + 10.0 * progress;
        // But if no existing bin fits well, the new-bin candidate becomes attractive:
        if fitting_bins_count == 0 {
            score -= 20.0;
        }
        // Opening a bin is cheaper early in the stream (more future items to fill it).
        score -= 15.0 * (1.0 - progress);
    } else {
        // Existing bin: compare against mean residual — prefer bins whose residual
        // is below average (they are already "committed" and would be wasted otherwise).
        if (bin_residual as f64) < mean_residual {
            score -= 5.0;
        } else {
            score += 2.0;
        }
    }

    // Mild time-horizon coupling: late in the stream, consolidate aggressively.
    score -= 8.0 * progress * tightness;

    // Tiny deterministic tie-breaker based on bin residual identity.
    score += 0.001 * (bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Normalize residuals
    let post_norm = post_residual as f64 / bin_capacity as f64;
    let item_norm = item_size as f64 / bin_capacity as f64;

    // Smooth polynomial coupling: waste penalty grows non-linearly with progress
    let waste_term = post_norm * post_norm * (0.5 + 2.0 * progress);
    score += 20.0 * waste_term;

    // Reward tight fits more aggressively as stream progresses
    let tight_fit = (item_norm * (1.0 - post_norm)).powi(2);
    score -= 15.0 * tight_fit * (0.5 + progress);

    // Penalize bins with residuals far from mean (fragmentation)
    let dev = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    score += 8.0 * dev * dev;

    // Last-chance bin: strong reward to avoid opening new bin
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - post_norm);
    }

    // Lookahead: bonus if next item fits well in post_residual
    if next_item_size > 0 && (next_item_size as f64) <= post_residual as f64 {
        let nxt = next_item_size as f64 / bin_capacity as f64;
        let nxt_fit = (nxt / post_norm.max(1e-6)).min(1.0);
        score -= 10.0 * nxt_fit * (1.0 - progress * 0.5);
    } else if next_item_size > 0 {
        // Dead space: post_residual too small for next item
        let dead = post_norm * (1.0 - post_norm);
        score += 12.0 * dead * (0.3 + progress);
    }

    // New-bin candidate: penalize opening bins when good fits exist
    if bin_residual == bin_capacity {
        let congestion = open_bins_count as f64 / (open_bins_count as f64 + 5.0);
        score += 30.0 * (1.0 - progress) * (1.0 - congestion) + 10.0 * congestion;
    }

    // Mild open-bins pressure to encourage consolidation
    score += 0.5 * (open_bins_count as f64).ln().max(0.0) * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: how it splits into capacity fractions
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap; // 0..1

    // Penalize post_residual that is "almost half" or "almost third" of capacity
    // (awkward dead space), reward residuals near multiples of common item sizes.
    let half_dist = (frac - 0.5).abs();
    let third_dist = (frac - 1.0 / 3.0).abs();
    let quarter_dist = (frac - 0.25).abs();
    score += 12.0 * (0.5 - half_dist).max(0.0);
    score += 8.0 * (1.0 / 3.0 - third_dist).max(0.0);
    score += 6.0 * (0.25 - quarter_dist).max(0.0);

    // Reward residuals exactly divisible by small harmonic classes (mod arithmetic)
    if post_residual > 0 {
        if post_residual % 10 == 0 { score -= 6.0; }
        else if post_residual % 5 == 0 { score -= 3.0; }
        if post_residual % 20 == 0 { score -= 4.0; }
        if post_residual % 25 == 0 { score -= 3.0; }
    }

    // Perfect fit is best
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead coupling: does post_residual fit next_item_size in a harmonic class?
    if next_item_size > 0 && post_residual >= next_item_size {
        let rem_after_next = post_residual - next_item_size;
        // Reward if next item leaves another clean class
        if rem_after_next % 10 == 0 { score -= 8.0; }
        if rem_after_next == 0 { score -= 15.0; }
        // Penalize leaving a tiny unusable sliver for the next item
        if rem_after_next < 1 { score += 0.0; }
        score -= 2.0; // mild general reward for keeping next item fittable
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Dead space relative to the next item
        score += 5.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate: penalize opening a bin unless current fit is bad
    if bin_residual == bin_capacity {
        // Base penalty; relax if this bin is a poor fit elsewhere
        let mut penalty = 20.0;
        if post_residual as f64 > cap * 0.6 { penalty -= 10.0; } // item is small, wasteful
        if fitting_bins_count == 0 { penalty -= 30.0; }
        score += penalty;
    }

    // Progress-based mild pressure: consolidate late in the stream
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 2.0 * progress * (mean_residual - pr) / cap.max(1.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to hold even the
    // smallest plausible item (or the lookahead item) are "dead space".
    if post_residual > 0 {
        let min_useful = if next_item_size > 0 && next_item_size <= post_residual {
            next_item_size
        } else {
            1
        };
        if post_residual < min_useful.max(10) {
            score += 60.0; // unusable gap penalty
        } else if next_item_size > 0 && next_item_size <= post_residual {
            // Reward residuals that exactly accommodate the lookahead item.
            score -= 25.0 * (1.0 - (post_residual - next_item_size) as f64 / 30.0).max(0.0);
        }
    } else {
        // Perfect fill is ideal.
        score -= 50.0;
    }

    // Tight fit reward: small post_residual relative to capacity.
    score -= 40.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Open-bin pressure: discourage spreading across many bins unless fit is tight.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (1.5 + 2.0 * progress);

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate: only attractive when no open bin fits well
    // (i.e., this call has a large post_residual anyway) or bin count is low.
    if bin_residual == bin_capacity {
        score += 30.0 + 3.0 * open_bins_count as f64;
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    } else {
        // Favor bins already below mean residual (consolidating emptier bins).
        score += (bin_residual as f64 - mean_residual) * 0.15;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward: post_residual exactly matches the next item (perfect 2-step chain).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Reward: next item fits into the post residual at all (2-step lookahead).
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 * (1.0 - slack / bin_capacity as f64);
    }

    // Penalize post residual that is too small for the next item but large enough
    // to become dead space relative to the mean residual of open bins.
    if next_item_size > 0 && post_residual < next_item_size {
        let dead = post_residual as f64;
        let min_useful = if next_item_size > 0 { (next_item_size as f64).min(30.0) } else { 30.0 };
        if dead < min_useful {
            score += 30.0 * (min_useful - dead) / min_useful;
        }
    }

    // Coupling with mean residual: prefer bins whose post residual is close to mean
    // (balanced packing) when many bins are open.
    if open_bins_count > 1 {
        let diff = (post_residual as f64 - mean_residual).abs();
        score += 0.15 * diff;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive when the
    // current item would leave a very poor fit everywhere else.
    if bin_residual == bin_capacity {
        // Mild default penalty so existing bins are preferred on decent fits.
        score += 5.0;
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 80.0; // fresh bin perfectly chains with next item
        }
        if item_size >= 70 {
            score -= 15.0; // big items pack better in a fresh bin
        }
        if fitting_bins_count > 0 && post_residual <= 20 {
            score += 25.0; // don't open a bin for a tight fit elsewhere
        }
    }

    // Late-stream tightening: reduce dead space as the stream nears its end.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.10 * progress * post_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins where the item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 8.0 * fit_ratio * fit_ratio;

    // Perfect fit gets a large bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Penalize small dead space that is hard to reuse (post_residual < 10).
    if post_residual > 0 && post_residual < 10 {
        score += 6.0;
    }

    // Lookahead: if the next item fits the post-residual exactly, reward heavily.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 4.0;
        if post_residual == next_item_size {
            score -= 12.0;
        }
        // If next item cannot fit in post_residual but could fit elsewhere, mild penalty.
        if next_item_size > post_residual {
            score += 2.0;
        }
    }

    // Last chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 5.0 + 0.05 * item_size as f64;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // existing bins fit poorly. Penalize new bins when good fits exist.
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin.
        score += 10.0;
        // If many bins fit, discourage opening a new one.
        if fitting_bins_count > 0 {
            score += 5.0 * fitting_bins_count as f64;
        }
        // Early in the stream, new bins are cheaper (plenty of stream left to fill them).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * (1.0 - progress);
        // If mean residual across open bins is small, opening a new bin is more attractive.
        score -= 0.05 * mean_residual;
    }

    // Mild preference to consolidate into fewer bins when many are open.
    if open_bins_count > 4 && bin_residual < bin_capacity {
        score -= 1.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let x = progress;
    let poly = x * x - 2.0 * x + 1.0; // (1-x)^2, smooth decay weight
    score += 8.0 * poly * (pr / cap) * (pr / cap) * cap * 0.1;

    // Reward tight fits more strongly as stream progresses
    let tightness = 1.0 - pr / cap;
    score -= 12.0 * tightness * tightness * (0.5 + x);

    // Penalize dead space relative to mean residual
    score += 0.15 * (pr - mean_residual) * (1.0 + x);

    // Last-chance bonus
    if fitting_bins_count == 1 {
        score -= 10.0 * (1.0 + tightness);
    }

    // Lookahead: reward if next item fits the post residual
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 6.0 * (next_item_size as f64 / cap);
    } else if next_item_size > 0 {
        score += 3.0 * (pr / cap) * (pr / cap);
    }

    // Mild pressure against hoarding many open bins late in stream
    score += 0.02 * open_bins_count as f64 * x;

    // New-bin candidate handling: slightly discourage unless residual is large
    if bin_residual == bin_capacity {
        score += 5.0 - 4.0 * x;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-fit residual: bins whose leftover falls into
    // "usable" residue classes (multiples of 5, small remainders) are favored.
    let pr = post_residual;
    let class_penalty = match pr {
        0 => -60.0,                       // perfect fit
        _ if pr % 10 == 0 => -30.0,       // decade-aligned residual
        _ if pr % 5 == 0 => -12.0,        // half-decade aligned
        _ if pr <= 9 => 25.0,             // tiny dead space
        _ => 0.0,
    };
    score += class_penalty;

    // Integer-division threshold: how well can next_item_size fit into the residual?
    if next_item_size > 0 && next_item_size <= pr {
        let fits = pr / next_item_size; // integer division = how many next items fit
        score -= 8.0 * fits as f64;
        // harmonic match: next item divides residual cleanly
        if pr % next_item_size == 0 {
            score -= 15.0;
        }
    } else if next_item_size > pr {
        // next item cannot use this residual anyway; residual quality matters more
        score += 5.0;
    }

    // Capacity-fraction coupling: residual as fraction of capacity.
    let frac = pr as f64 / bin_capacity as f64;
    score += 20.0 * (frac - 0.5) * (frac - 0.5); // penalize mid-range residuals mildly

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // Prefer tightest bins when many bins are open (fragmentation control).
    score += 0.5 * open_bins_count as f64 * (1.0 - bin_residual as f64 / bin_capacity as f64);

    // Late-stream consolidation: as the stream progresses, avoid spreading.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64 - mean_residual) * 0.3;

    // New-bin candidate: only attractive when residual is truly unusable.
    if bin_residual == bin_capacity {
        score += 35.0; // default penalty for opening a new bin
        if pr == bin_capacity && (next_item_size == 0 || next_item_size > bin_capacity / 2) {
            score -= 45.0; // big next item: fresh bin is fine
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps harshly.
    // Gaps below the minimum item size (1..=12) are dead space.
    if post_residual > 0 && post_residual < 12 {
        score += (12 - post_residual) as f64 * 40.0;
    }
    if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 60.0;
    }

    // Reward tight fits relative to bin capacity.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 25.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; with few,
    // allow opening new bins when fit is poor.
    let bin_pressure = open_bins_count as f64 / (mean_residual.max(1.0) / bin_capacity as f64);
    score += bin_pressure * 0.5;

    // Lookahead: if the next item fits exactly in the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap < 12 {
            score -= 45.0; // next item will nearly perfectly consume remainder
        } else {
            score -= 10.0;
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        // Next item cannot use the remainder: dead space guaranteed.
        score += post_residual as f64 * 1.5;
    }

    // New-bin candidate handling: an empty bin has large residual; make it
    // attractive only when current fit is bad (large post residual).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Slight preference for new bins early, penalty late.
        score += 15.0 - progress * 30.0;
        if post_residual as f64 > mean_residual {
            score -= 20.0; // item fits poorly everywhere; new bin is fine
        }
    }

    // Mean-residual coupling: prefer bins that are closer to the mean residual
    // (keeps bin states homogeneous, easier future packing).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.3;

    // Progress scaling: as stream advances, tighten packing further.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.5 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer perfect fits
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: reward when next item fits the post-residual exactly
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual > next_item_size {
            score -= (post_residual - next_item_size) as f64 * 0.5;
        } else {
            // next item won't fit here: penalize leftover dead space
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Compare against mean residual: bins with residuals near the mean are "typical",
    // prefer placing into bins whose residual is below the mean (tighter bins)
    score += (post_residual as f64 - mean_residual) * 0.4;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 300.0;
    }

    // Penalize large unusable post-residuals (dead space that few items can fill)
    if post_residual > 0 && post_residual < 10 {
        score += 50.0; // tiny slivers are wasted
    }

    // Early in the stream, be slightly more willing to open bins (spread load)
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // new-bin candidate: attractive early, or when fits are poor
        score -= 80.0 * (1.0 - progress);
        score += mean_residual * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual already does this); penalize
    // awkward dead space that is too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // nearly useless sliver
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // Lookahead: if the next item fits exactly in the post residual,
    // reward heavily; if next item cannot fit post residual but could
    // fit a fresh bin, mild penalty.
    if next_item_size > 0 {
        if next_item_size as f64 == post_residual as f64 {
            score -= 40.0;
        } else if (next_item_size as u32) > post_residual && next_item_size as u32 <= bin_capacity {
            score += 8.0;
        }
    }

    // New-bin candidate handling: fresh bin should only win when the fit
    // elsewhere is bad. Penalize the fresh bin mildly so tight fits in
    // open bins win, but less when current item is large (poor fit risk).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let base = 15.0 + 20.0 * progress;
        // If item leaves a large post residual in a fresh bin, it's fine
        // (fresh bin keeps flexibility); penalize less for big items.
        let big_item_bonus = (item_size as f64 / bin_capacity as f64) * 20.0;
        score += base - big_item_bonus;
    }

    // Prefer bins with below-mean residual (consolidate emptiness).
    score += (bin_residual as f64 - mean_residual) * 0.3;

    // Slight preference for using existing bins when many are open.
    score += open_bins_count as f64 * 0.5 * (1.0 - (item_size as f64 / bin_capacity as f64));

    // Time horizon: early in stream, be conservative (favor fresh bins
    // less); late in stream, squeeze into existing bins harder.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let prn = pr / cap;

    // Base: reward tight fits (low post residual), with non-linear emphasis.
    let mut score = pr + 30.0 * prn * prn * cap;

    // Smooth coupling of post-residual with stream progress:
    // early on, tolerate slack; later, penalize it more heavily.
    score += 60.0 * prn * (0.5 + progress) * (1.0 - prn);

    // Penalize bins whose residual deviates strongly from the mean
    // (keeps a diverse portfolio of residual sizes).
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 25.0 * dev * dev;

    // Reward filling bins when many are open (consolidation pressure).
    score -= 8.0 * (open_bins_count as f64).ln().max(0.0) * (1.0 - prn);

    // Last-chance bonus: strongly prefer the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Lookahead: reward if next item fits the post-residual, penalize otherwise.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let tight = 1.0 - ((pr - nxt) / cap);
            score -= 20.0 * tight * (1.0 - progress);
        } else {
            score += 10.0 + 0.2 * (nxt - pr);
        }
    }

    // Slight bias against opening new bins when a fit exists.
    if bin_residual == bin_capacity {
        score += 5.0 + 15.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class: prefer post-residuals in "reusable" classes (multiples of 10, 20, 25, 50)
    let pr = post_residual as i64;
    let mut bonus = 0.0;
    if pr % 50 == 0 { bonus += 18.0; }
    else if pr % 25 == 0 { bonus += 12.0; }
    else if pr % 20 == 0 { bonus += 10.0; }
    else if pr % 10 == 0 { bonus += 7.0; }
    else if pr % 5 == 0 { bonus += 3.0; }
    score -= bonus;

    // Dead space penalty: tiny residuals (< 10) are unusable for items >= 1 but mostly waste
    if pr > 0 && pr < 10 {
        score += 25.0;
    }

    // Perfect fit: huge reward
    if pr == 0 {
        score -= 100.0;
    }

    // Next-item coupling: reward if post_residual exactly accommodates next item (harmonic chaining)
    if next_item_size > 0 {
        if pr == next_item_size as i64 {
            score -= 40.0;
        } else if pr > 0 && next_item_size as i64 % pr.max(1) == 0 {
            // next item can be split across... prefer divisibility classes
            score -= 6.0;
        }
        // penalize if next item is slightly larger than post_residual (near miss wastes the slot)
        if next_item_size as i64 > pr && (next_item_size as i64 - pr) <= 10 {
            score += 8.0;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        // among many fitting bins, prefer tighter fit (score already tracks post_residual)
        score += 0.5 * (fitting_bins_count as f64 - 1.0);
    }

    // New-bin candidate: only open a new bin when current residual is small or item is large
    if bin_residual == bin_capacity {
        // base score is bin_capacity (100); adjust based on context
        let progress = step_index as f64 / (total_items.max(1) as f64);
        if item_size >= 60 {
            score -= 20.0; // large items like fresh bins
        }
        if pr_bonus_proxy(open_bins_count, mean_residual) {
            score -= 15.0;
        }
        // late in stream, reuse bins more aggressively
        score += 40.0 * progress;
    }

    // Mild pressure to consolidate when many bins are open
    score += 0.15 * open_bins_count as f64;

    // Slight preference for bins below mean residual (balance residuals)
    score += 0.05 * (bin_residual as f64 - mean_residual);

    score
}

#[inline]
fn pr_bonus_proxy(open_bins_count: usize, mean_residual: f64) -> bool {
    open_bins_count > 4 && mean_residual < 30.0
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful
    // for typical future items are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (1.0 - post_residual as f64 / 10.0);
    } else if post_residual >= 10 && post_residual < 25 {
        // Mild penalty for small-but-usable gaps, tapering off.
        score += 8.0 * (1.0 - (post_residual as f64 - 10.0) / 15.0);
    }

    // Reward near-perfect fills (small positive residual is fine if it's a wash).
    if post_residual == 0 {
        score -= 40.0; // perfect fit closes the bin cleanly
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bins pressure: penalize adding load when many bins are already open,
    // encouraging consolidation into fewer bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.6 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Relative fit quality: prefer bins where the item occupies a large share
    // of the residual (tight packing).
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 15.0 * fill_ratio;

    // Lookahead coupling: if the next item can use the post_residual, reward
    // leaving exactly that much space behind.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0 * (post_residual as f64 - next_item_size as f64 + 1.0).ln().max(0.0);
        } else if post_residual > 0 && post_residual < next_item_size {
            score += 5.0; // blocks the known next item
        }
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when existing bins are crowded
        // (mean residual low) or the fit into open bins would be very loose.
        let crowded = (mean_residual / bin_capacity as f64) < 0.25;
        let poor_fit = fill_ratio < 0.35;
        if crowded || poor_fit {
            score -= 20.0;
        } else {
            score += 35.0; // discourage opening new bins when good fits exist
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post_residual).
    score -= 0.8 * (bin_capacity as f64 - post_residual as f64).abs() * 0.0; // no-op guard
    score -= 4.0 / (1.0 + post_residual as f64);

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 20.0;
    }

    // 2-step lookahead: reward if next item fits the post residual exactly-ish.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 3.0 / (1.0 + slack);
            if post_residual == next_item_size {
                score -= 15.0;
            }
        } else {
            // Next item won't fit here: penalize dead space creation.
            let dead = (next_item_size - post_residual) as f64;
            score += 0.15 * dead;
        }
    }

    // Compare post_residual against mean residual: avoid making bin much tighter than average
    // unless it's a near-perfect fit.
    let dev = post_residual as f64 - mean_residual;
    if dev > 0.0 {
        score += 0.05 * dev;
    } else {
        score += 0.02 * dev.abs();
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 10.0;
    }

    // Mildly discourage opening new bins when many bins are already open and slack exists.
    if bin_residual == bin_capacity {
        score += 5.0 + 0.1 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size >= bin_capacity - item_size {
            score -= 3.0; // fresh bin useful for large follow-up items
        }
    }

    // Early in stream, be slightly conservative about fragmenting bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 2.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post-residual gets extra discount).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that no plausible item can fill later.
    if post_residual > 0 {
        let min_item = 1.0;
        if (post_residual as f64) < min_item {
            score += 25.0;
        }
        // Post-residual too small for typical items is wasted space.
        if post_residual < 10 {
            score += 8.0;
        }
    }

    // Lookahead: reward bins whose post-residual can still host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0;
        } else {
            score += 4.0;
        }
        // Perfect chain: post-residual exactly fits next item.
        if post_residual == next_item_size {
            score -= 10.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Time horizon: early in the stream, keep bins flexible (mild penalty for
    // very low post-residual); late in the stream, pack aggressively.
    let progress = if total_items > 0 {
        step_index as f64 / total_items as f64
    } else {
        0.0
    };
    score *= 1.0 + 0.3 * (1.0 - progress);

    // Global state: many open bins with high mean residual -> encourage
    // consolidating into existing bins rather than opening new ones.
    if bin_residual < bin_capacity {
        score -= 0.05 * mean_residual;
        score -= 0.5 * open_bins_count as f64;
    }

    // New-bin candidate: make it attractive only when no open bin fits well.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 30.0;
        // If current bin would leave a lot of dead space, new bin looks better.
        let waste = post_residual as f64 / bin_capacity as f64;
        if bin_residual >= item_size && waste > 0.5 {
            score -= 20.0 * (waste - 0.5);
        }
        // Late in stream with many open bins, prefer consolidation.
        score += 15.0 * progress * (open_bins_count as f64 / 10.0).min(1.0);
        // If the next item is large, a fresh bin is valuable.
        if next_item_size > 50 {
            score -= 8.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Base: post residual, mildly convex in normalized residual
    let mut score = pr * (1.0 + 0.35 * pr_norm * pr_norm);

    // Smooth non-linear coupling of residual with stream progress:
    // late in the stream, waste matters more (tighten packing).
    let urgency = progress * progress * (3.0 - 2.0 * progress); // smoothstep
    score += urgency * 12.0 * pr_norm;

    // Interaction: large post-residual penalized more when mean residual is low
    // (i.e., other bins are tight; this bin's slack is pure waste).
    let mean_norm = mean_residual / cap;
    score += 0.6 * pr_norm * (1.0 - mean_norm).powi(2) * cap;

    // Reward near-perfect fits smoothly (quadratic trough at pr_norm ~ 0.05)
    let trough = (pr_norm - 0.05) * (pr_norm - 0.05);
    score -= 10.0 * (-40.0 * trough).exp();

    // Lookahead: favor leaving room for the next item smoothly
    if next_item_size > 0 {
        let gap = (pr as i64 - next_item_size as i64) as f64;
        let fit_next = 1.0 / (1.0 + (-gap / 20.0).exp()); // sigmoid
        score -= 6.0 * fit_next * (next_item_size as f64 / cap);
    }

    // Last-chance bin: strongly reward using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - pr_norm);
    }

    // Mild penalty for spreading across many open bins
    score += 0.15 * (open_bins_count as f64).ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: exact quarter classes of capacity
    let q = post_residual / (bin_capacity / 4).max(1);
    let class_bonus: f64 = match q {
        0 => -40.0,          // near-perfect fill
        1 => -12.0,          // quarter class: still very usable
        2 => 6.0,            // half class: mediocre
        3 => 18.0,           // three-quarter dead zone
        _ => 30.0,           // nearly empty bin chosen -> wasteful
    };
    score += class_bonus;

    // Exact divisibility rewards: residual that divides capacity cleanly is reusable
    if bin_capacity % post_residual.max(1) == 0 {
        score -= 8.0;
    }
    if post_residual % 10 == 0 {
        score -= 4.0;
    }

    // Lookahead coupling: reward residuals that can host the next item exactly
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual >= next_item_size {
            score -= 6.0 + (post_residual - next_item_size) as f64 * 0.05;
        } else {
            // next item cannot fit here: penalize proportionally to wasted space
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
        // harmonic pairing: post_residual + next_item_size divides capacity
        if post_residual + next_item_size <= bin_capacity
            && bin_capacity % (post_residual + next_item_size).max(1) == 0 {
            score -= 10.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: only attractive when few bins fit or mean residual is tiny
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let pressure = (fitting_bins_count == 0) as i32 as f64 * 60.0
            + (mean_residual < item_size as f64 * 0.5) as i32 as f64 * 25.0
            - progress * 10.0;
        score = cap * 0.75 - pressure + (open_bins_count as f64) * 2.0;
        if next_item_size > 0 && next_item_size >= bin_capacity {
            score -= 30.0; // next item needs a fresh bin anyway
        }
    }

    // Mild penalty for spreading across many open bins when residual is abundant
    score += mean_residual * 0.03;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10 - post_residual) as f64;
    }
    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 80.0;
    }

    // Reward tight fits relative to residual.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * tightness;

    // Open-bin pressure: penalize bins in proportion to number of open bins,
    // discouraging scattering across many bins.
    score += 2.0 * open_bins_count as f64;

    // Last-chance bin: strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate: only attractive when it avoids future dead space,
    // i.e., when next item would fit well into a fresh bin but current bin
    // would leave a bad gap, or this bin's fit is loose.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, softened by open-bin pressure.
        score = 55.0 + 2.5 * open_bins_count as f64;
        // Lookahead: if next item fits nicely with the current item in a fresh bin, reward.
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 20.0;
        }
        // If the current bin would leave a tiny dead space anyway, prefer new bin.
        if bin_residual >= item_size && bin_residual - item_size < 10 {
            score -= 30.0;
        }
    }

    // Mean residual coupling: if this bin's residual is far below the mean,
    // it is already "used" — prefer filling it rather than leaving it half-empty.
    let dev = mean_residual - bin_residual as f64;
    if dev > 0.0 {
        score -= 0.3 * dev;
    }

    // Late in the stream, be more conservative about opening bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let capacity_f = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Reward tight fits: small post_residual is already the base, add nonlinear bonus.
    let tightness = 1.0 - (post / capacity_f);
    score -= 8.0 * tightness * tightness;

    // 2-step lookahead: strongly reward exact match of next_item_size into post_residual.
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        let next_fit = 1.0 - ((post_residual - next_item_size) as f64 / capacity_f);
        score -= 12.0 * next_fit * next_fit;
    } else if next_item_size > 0 {
        // Next item cannot fit here: penalize dead space relative to what next item needs.
        let waste = (next_item_size as f64 - post).max(0.0);
        score += 0.6 * waste;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Penalize creating residuals that are unusable relative to mean residual.
    if post > 0.0 && post < mean_residual * 0.5 {
        score += 0.5 * (mean_residual - post);
    }

    // Discard the new-bin option unless existing bins fit poorly.
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin; reduced if current fit is bad.
        score += 20.0;
        if item_size > (bin_residual as f64 * 0.5) as u32 {
            score -= 18.0; // poor fit elsewhere -> allow new bin
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 5.0; // stream has large items, fresh bin useful
        }
    }

    // Late-stream consolidation: prefer filling existing bins as stream ends.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 4.0 * progress * (1.0 - post / capacity_f);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor small post residuals.
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 45.0 * tight * tight;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        score -= 25.0;
    }

    // Penalize dead space that is too small for typical items (1..100 range).
    if post_residual > 0 && post_residual < 20 {
        score += 18.0;
    }

    // Lookahead coupling: reward bins whose post residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0 + 0.25 * next_item_size as f64;
        } else {
            score += 8.0;
        }
        // Chain fit: residual can host next item with room to spare.
        let chain_gap = post_residual as f64 - next_item_size as f64;
        if chain_gap > 0.0 && chain_gap < 15.0 {
            score -= 10.0;
        }
    } else {
        // Last item: just minimize post residual.
        score -= 15.0;
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Crowding: with many open bins, prefer consolidating into emptier bins.
    let crowding = open_bins_count as f64 / (1.0 + total_items as f64);
    score += 10.0 * crowding * (bin_residual as f64 / bin_capacity as f64);

    // Divergence from mean residual: prefer bins whose residual is below mean (fill fuller bins).
    score += 0.35 * (bin_residual as f64 - mean_residual).max(0.0);

    // Time horizon: early in the stream, be conservative; late, be greedy.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 20.0 * progress * tight;

    // New-bin candidate: only open a new bin when no open bin fits well
    // (item is large relative to residuals or all fits are terrible).
    if bin_residual == bin_capacity {
        let waste_elsewhere = if fitting_bins_count > 0 {
            mean_residual - item_size as f64
        } else {
            100.0
        };
        if fitting_bins_count == 0 {
            score -= 40.0; // must open new bin
        } else if waste_elsewhere > 30.0 {
            score -= 20.0; // existing fits are very wasteful
        } else {
            score += 35.0; // prefer reusing open bins
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let item = item_size as f64;

    // Non-linear penalty on wasted space, amplified over stream progress
    let waste_norm = pr / cap;
    score += 3.0 * waste_norm * waste_norm * cap * (0.5 + progress);

    // Reward tight fits (small post_residual) with smooth cubic term
    score -= 2.0 * (1.0 - waste_norm).powi(3) * (1.0 + progress);

    // Perfect-fit bonus via smooth exponential coupling
    score -= 8.0 * (-pr / (0.1 * cap)).exp();

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 + progress);
    }

    // Lookahead: bonus if the next item fits into the resulting residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let snug = 1.0 - (pr - nxt) / cap;
            score -= 6.0 * snug * snug;
        } else {
            // penalize residuals that no plausible next item can use
            score += 2.0 * (pr / cap) * (1.0 - progress);
        }
    }

    // Mild penalty when bin residual deviates from mean residual (balance open bins)
    score += 0.5 * ((bin_residual as f64 - mean_residual) / cap).abs();

    // Slight preference for consolidating into fewer bins when many are open
    score += 0.05 * open_bins_count as f64 * waste_norm;

    // New-bin candidate: penalize opening a new bin unless current fit is poor
    if bin_residual == bin_capacity {
        score += 10.0 + 20.0 * progress - 0.0;
        // allow new bin when existing fit would leave big waste
        score -= 1.5 * waste_norm * cap;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: how "usable" is the leftover space?
    // Class 0: post_residual in low fractions of capacity -> near-perfect fit.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Fine-grained tightness reward: strongly favor small leftovers.
    let tight = 1.0 - (post / cap);
    score -= 2.5 * tight * tight;

    // Modulo classes on post_residual: leftovers that are "harmonic" with
    // common item sizes (multiples of 10) are more reusable.
    let pr = post_residual % 10;
    if pr == 0 {
        score -= 6.0; // perfectly harmonic leftover
    } else if pr <= 3 {
        score += 3.0; // awkward sliver
    } else {
        score += 1.0;
    }

    // Integer-division threshold: leftover big enough to host a mid item?
    let reusable = post_residual >= 40;
    if reusable {
        score -= 4.0;
    } else if post_residual >= 20 {
        score -= 1.0;
    } else if post_residual > 0 {
        score += 4.0; // dead space penalty
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 15.0;
        } else if next_item_size < post_residual {
            let nxt = next_item_size as f64;
            let waste = post - nxt;
            // harmonic check: leftover after next item
            if (post_residual - next_item_size) % 10 == 0 {
                score -= 5.0;
            }
            score += 0.15 * waste;
        } else {
            score += 2.0; // next item won't fit here anyway
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 8.0;
    }

    // New-bin candidate logic: opening a new bin is only attractive when no
    // open bin offers a decent fit; penalize opening early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = 55.0 + 10.0 * (1.0 - progress);
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
        if next_item_size > 0 && next_item_size >= 60 {
            score -= 5.0; // big item coming, fresh bin useful
        }
    }

    // Mild pressure toward consolidating into fewer bins.
    score -= 0.05 * (open_bins_count as f64).recip().min(1.0) * 0.0;
    score += 0.02 * mean_residual.min(100.0) * 0.0; // no-op guards

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize residuals that are too small to be
    // useful for future items (unusable gaps below a "dead zone" threshold).
    let dead_zone = 12.0;
    if (post_residual as f64) < dead_zone && post_residual > 0 {
        score += (dead_zone - post_residual as f64) * 6.0;
    }
    if post_residual == 0 {
        score -= 25.0; // perfect fit reward
    }

    // Reward tight fits (small post_residual relative to residual).
    let tightness = 1.0 - (post_residual as f64 / bin_residual.max(1) as f64);
    score -= tightness * 10.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: many open bins -> prefer filling existing ones,
    // penalize opening new bins.
    score += open_bins_count as f64 * 1.5;

    // New-bin candidate (empty bin): make it attractive only when the item
    // would leave a very awkward remainder in existing bins, or few bins fit.
    if bin_residual == bin_capacity {
        let awkward = (post_residual as f64) < dead_zone || post_residual > 50;
        if awkward {
            score -= 30.0;
        } else {
            score += 15.0 + open_bins_count as f64 * 0.5;
        }
    }

    // Lookahead: if the next item fits perfectly into the post_residual,
    // reward this placement strongly.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 30.0;
    } else if next_item_size > 0 && next_item_size > post_residual && post_residual > 0 {
        // next item cannot use this gap: mildly penalize leaving it
        score += 3.0;
    }

    // Slight progression pressure: later in the stream, consolidation matters more.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: perfect match with next item is ideal.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Reward exact/near match with the next item's size.
        score -= (40.0 / (1.0 + diff)).min(40.0);
        // Penalize leaving a residual that is too small for the next item (dead space).
        if post_residual < next_item_size {
            score += 0.6 * (next_item_size - post_residual) as f64;
        }
    } else {
        // Last item: prefer filling as tightly as possible.
        score += 0.0;
    }

    // Relative-to-mean coupling: bins with more residual than average are
    // better targets (they can absorb the item without wasting scarce space).
    score += 0.3 * (mean_residual - bin_residual as f64);

    // Strongly penalize creating tiny unusable residuals (dead space < 10).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when no good fit exists elsewhere.
    if bin_residual == bin_capacity {
        score += 15.0;
        // If many bins fit, opening a new bin is wasteful.
        if fitting_bins_count > 0 {
            score += 10.0 * (fitting_bins_count as f64).sqrt();
        }
        // Early in the stream, allow more liberal bin opening.
        if total_items > 0 {
            let progress = step_index as f64 / total_items as f64;
            score -= 10.0 * (1.0 - progress);
        }
    }

    // Mild tie-break: prefer bins that are already fairly full.
    score += 0.2 * (bin_capacity - bin_residual) as f64 / bin_capacity as f64 * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: low post_residual is good, but penalize tiny residuals
    // that become dead space (residual too small for the smallest plausible item).
    let min_item = 1.0f64;
    if post_residual > 0 && (post_residual as f64) < min_item * 3.0 {
        score += 40.0; // near-zero dead space is wasted capacity
    }

    // Strong reward when post_residual can exactly host the lookahead item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual > next_item_size {
            score -= 10.0 * (post_residual as f64 / (next_item_size as f64 + 1.0)).min(1.0);
        } else {
            // post_residual smaller than next item: partially dead for lookahead
            score += 8.0 * (1.0 - post_residual as f64 / next_item_size as f64);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // Many fitting bins: competition is high, prefer the one with best residual match.
    if fitting_bins_count > 2 {
        let fit_quality = (post_residual as f64) / (bin_residual as f64 + 1.0);
        score += 15.0 * fit_quality; // penalize leaving proportionally large leftovers
    }

    // Global state: if mean residual is high, bins are loose — favor filling
    // existing bins rather than spreading.
    let mean_res = mean_residual;
    if mean_res > bin_capacity as f64 * 0.5 {
        score -= 10.0 * (mean_res / bin_capacity as f64 - 0.5);
    }

    // New-bin candidate handling: opening a new bin should only win when the
    // item fits poorly everywhere else.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let waste = (bin_capacity - item_size) as f64;
        // Base cost of a fresh bin, discounted slightly late in the stream.
        score = waste + 25.0 * (1.0 - 0.3 * progress);
        // If no existing bin fits at all, opening is mandatory: make it cheap.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        // If lookahead item is large and current item is small, a fresh bin
        // can absorb both — mild discount.
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 12.0;
        }
    }

    // Time-horizon coupling: early on, be conservative (keep residuals large
    // and flexible); later, be aggressive about compacting bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 12.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Slight penalty for proliferating open bins when residual space is abundant.
    if open_bins_count > 4 && mean_res > bin_capacity as f64 * 0.35 {
        score += 0.5 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Non-linear polynomial coupling of post_residual with stream progress
    let prn = pr / cap;
    let poly = prn * prn * (1.0 - progress) - prn * progress * (1.0 - prn);
    score += 8.0 * poly;

    // Reward tight fits more strongly as stream progresses
    let tightness = 1.0 - prn;
    score -= 12.0 * tightness * tightness * (0.5 + progress);

    // Penalize dead space below next item size
    if next_item_size > 0 && (prn * cap) < next_item_size as f64 {
        score += 6.0 * (next_item_size as f64 - prn * cap) / cap * (1.0 + progress);
    }

    // Reward exact match for lookahead item
    if next_item_size > 0 && post_residual as u32 == next_item_size {
        score -= 15.0;
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 10.0 * tightness;
    }

    // Mild pressure to fill existing bins when many are open
    score -= 0.5 * (open_bins_count as f64).ln() * tightness;

    // New-bin candidate: prefer it only when residuals are low and stream is early
    if bin_residual == bin_capacity {
        score += 4.0 + 6.0 * progress - 2.0 * (mean_residual / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Harmonic class of the post residual: residue classes modulo 20.
    let harmonic = post_residual % 20;
    let class_bonus = match harmonic {
        0 => -6.0,          // perfectly aligned residual, highly reusable
        1..=4 => -3.0,      // near-aligned, still useful for small items
        5..=9 => 0.0,
        10..=14 => 2.0,     // half-capacity dead zone, mildly penalized
        _ => 4.0,           // awkward residual class
    };
    score += class_bonus;

    // Integer-division threshold classes on post_residual.
    let tier = post_residual / 25; // 0: [0,24], 1: [25,49], 2: [50,74], 3: [75,99]
    match tier {
        0 => score -= 5.0,               // tiny residual = tight packing, good
        1 => score += 0.0,
        2 => score += 3.0,               // half-full bins are wasteful targets
        _ => score += 6.0,               // nearly empty bin being fragmented
    }

    // Lookahead coupling: reward leaving room exactly sized for the next item.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack = post_residual - next_item_size;
            if slack == 0 {
                score -= 22.0;           // perfect two-item pairing
            } else if slack <= 10 {
                score -= 14.0;           // near-perfect pairing
            } else {
                score -= 6.0;            // next item still fits, mild reward
            }
        } else {
            // Next item cannot use the leftover: penalize proportional dead space
            score += (post_residual as f64) * 0.05;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        if fitting_bins_count <= 1 {
            // No open bin can fit: opening is mandatory.
            score -= 60.0;
        } else {
            // Prefer existing bins; penalize new-bin opening, scaled by item size
            // (large items justify fresh bins a bit more as the stream progresses).
            let urgency = progress * 10.0 + (item_size as f64 - 40.0).max(0.0) * 0.15;
            score += 40.0 - urgency;
        }
    }

    // Global residual pressure: if open bins are already loose, avoid adding more.
    if mean_residual > 40.0 && bin_residual != bin_capacity {
        score -= 2.0;
    }
    // Crowding: many open bins → encourage consolidation into tight fits.
    if open_bins_count > 8 && post_residual < 30 {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that can never hold a useful
    // item (min item size 1, but tiny slivers < 10 are near-unusable)
    // are heavily penalized.
    if post_residual < 10 {
        score += 60.0; // unusable sliver
    } else if post_residual <= 20 {
        score += 25.0; // only fits very small items
    }

    // Perfect fit reward
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    }

    // Reward when post_residual can still fit the lookahead item
    if next_item_size > 0 {
        if post_residual >= next_item_size as f64 {
            score -= 20.0;
        } else {
            score += 10.0; // dead space relative to lookahead
        }
    }

    // Open-bin pressure: discourage scattering across many bins;
    // prefer filling existing bins when several are open.
    score += open_bins_count as f64 * 3.0;

    // Last-chance bin: strongly favor using the only bin that fits
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // New-bin candidate: make opening a new bin unattractive unless
    // the current fit is terrible (large post_residual).
    if bin_residual == bin_capacity {
        score += 45.0;
        // allow new bin if this placement would leave a big useless gap
        if post_residual > 50 {
            score -= 60.0;
        }
    }

    // Mild deviation from mean residual: prefer bins tighter than average
    score += (bin_residual as f64 - mean_residual) * 0.3;

    // Progress coupling: early in stream, be more selective about dead space
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - progress) * (post_residual as f64) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    } else if next_item_size > 0 {
        let gap = if post_residual > next_item_size {
            (post_residual - next_item_size) as f64
        } else {
            (next_item_size - post_residual) as f64 * 0.6
        };
        // Penalize mismatch, worse for small gaps that "just miss".
        score += gap * 0.35;
    }

    // Reward bins whose residual is already tight relative to the mean (compact bins).
    let dev = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    score -= dev * 25.0;

    // Last chance: strongly favor using the only bin that fits, avoid opening new bins.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Penalize opening a new bin when decent fits exist and many bins are open.
    if bin_residual == bin_capacity {
        score += 8.0 + 2.0 * open_bins_count as f64;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 12.0; // fresh bin can still host the next item
        }
    }

    // Dead-space penalty: residuals too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // Late in the stream, prefer consolidating into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post residual)
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize dead space that no future item can plausibly use
    let t = step_index as f64 / (total_items.max(1) as f64);
    if post_residual > 0 {
        let usable = if next_item_size > 0 && next_item_size <= post_residual { 1.0 } else { 0.0 };
        score += 10.0 * (1.0 - usable) * (post_residual as f64 / 100.0);
    }

    // Lookahead: reward bins whose post residual fits the next item exactly-ish
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            score -= 8.0 * (next_item_size as f64 / (post_residual as f64 + 1.0));
        } else {
            score += 4.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Prefer fullest bins when many bins are open (reduce fragmentation)
    let fill = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= 6.0 * fill * (open_bins_count as f64).ln().max(1.0);

    // New-bin candidate: penalize unless no good fit exists
    if bin_residual == bin_capacity {
        let good_fit_exists = fitting_bins_count > 0 && (post_residual as f64) <= mean_residual;
        score += if good_fit_exists { 40.0 } else { 12.0 - 10.0 * t };
        // opening new bin is more attractive early (many items remain)
        score -= 6.0 * (1.0 - t);
    }

    // Mild bonus for matching mean residual (keeps bin pool balanced)
    score -= 2.0 * (-((post_residual as f64) - mean_residual).abs() / 50.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr_norm = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = pr_norm * (1.0 - pr_norm);          // hump at half-full residual
    let poly2 = pr_norm * pr_norm * (3.0 - 2.0 * pr_norm); // smoothstep shape
    let mut score = pr
        - 18.0 * poly * (1.0 - progress)
        + 14.0 * poly2 * progress;

    // Reward tight fits (small post_residual)
    score -= (1.0 - pr_norm) * (1.0 - pr_norm) * 20.0;

    // Lookahead: penalize if next item fits the post residual (waste of pairing potential reversed)
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if ni <= pr {
            score -= 10.0 * (1.0 - (ni / cap - pr_norm).abs());
        } else {
            score += 6.0 * (ni - pr) / cap;
        }
    }

    // Last-chance bin bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Mean residual deviation penalty: prefer bins near the mean residual (balanced packing)
    let dev = (pr - mean_residual) / cap;
    score += 8.0 * dev * dev;

    // New-bin candidate: mildly penalize opening new bins early, allow late in stream
    if bin_residual == bin_capacity {
        score += 30.0 * (1.0 - progress) - 10.0 * progress;
    }

    // Slight penalty for many open bins to encourage consolidation
    score += open_bins_count as f64 * 0.5 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Harmonic class of post_residual: bins whose leftover falls on "nice" sizes
    // (multiples of 10, or exactly matching next item) are more reusable.
    let pr = post_residual;
    if pr == 0 {
        score -= 40.0; // perfect fit, ideal
    } else {
        // Reward post_residuals that are multiples of 10 (harmonic classes)
        if pr % 10 == 0 {
            score -= 12.0;
        }
        // Integer division thresholds: small leftovers (< 10) are dead space
        if pr / 10 == 0 {
            score += 25.0;
        } else if pr / 10 <= 2 {
            score += 6.0;
        }
    }

    // Lookahead coupling: reward residuals that can host the next item exactly or well
    if next_item_size > 0 {
        let nxt = next_item_size;
        if post_residual == nxt {
            score -= 35.0; // next item fills bin perfectly
        } else if post_residual >= nxt {
            score -= 10.0;
            // harmonic: residual minus next item lands on multiple of 10
            if (post_residual - nxt) % 10 == 0 {
                score -= 8.0;
            }
        } else {
            score += 15.0; // next item cannot use this residual
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when existing bins fit poorly
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // penalize opening new bins early / when many open
        score = cap * 0.9 + (open_bins_count as f64) * 2.0;
        // but if no open bin leaves a usable residual, allow it
        if fitting_bins_count == 0 || (next_item_size > 0 && post_residual < next_item_size && post_residual < 10) {
            score -= 55.0;
        }
    }

    // Tightness reward: prefer bins where the item fills a large fraction
    let fill_frac = item_size as f64 / bin_residual as f64;
    score -= 20.0 * fill_frac * fill_frac;

    // Mean-residual coupling: prefer bins deviating from mean residual
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Stream progression: later in stream, pack tighter / avoid new bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if is_new_bin {
        score += 40.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 + (10 - post_residual) as f64 * 6.0;
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 60.0;
    } else if post_residual <= 20 {
        score += 12.0;
    }

    // Reward tight fits (item fills most of the residual).
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fill_ratio * fill_ratio;

    // Open-bin pressure: with many open bins, prefer consolidating into existing bins.
    score += 2.0 * open_bins_count as f64;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if the next item can use this bin's post-residual, reward it.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 18.0 * (next_item_size as f64 / post_residual.max(1) as f64);
        } else if post_residual > 0 && next_item_size > post_residual {
            score += 8.0;
        }
    }

    // New-bin candidate: penalize opening a new bin unless existing residuals are poor.
    if bin_residual == bin_capacity {
        score += 35.0 + 3.0 * open_bins_count as f64;
        if mean_residual >= item_size as f64 {
            score += 25.0;
        }
    } else {
        // Favor bins whose residual is close to the item (best-fit flavor).
        score += (bin_residual as f64 - item_size as f64) * 0.4;
    }

    // Mean residual coupling: penalize placements that diverge badly from mean residual.
    score += 0.15 * (post_residual as f64 - mean_residual).abs();

    // Late-stream consolidation: near the end, avoid leaving many open bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if progress > 0.8 {
        score += 10.0 * progress * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strongly reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Near-perfect fit reward (dead space <= 10 is cheap).
    if post_residual <= 10 {
        score -= 60.0 * (10 - post_residual) as f64;
    }

    // 2-step lookahead: reward if next item exactly/nearly fits the post residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 200.0;
        } else if next_item_size <= post_residual {
            // next item fits: reward proportional to tightness of the chain
            score -= 80.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // next item will NOT fit here: penalize leaving residual that
            // matches next_item_size minus a small gap (tempting but wasteful)
            let gap = (next_item_size - post_residual) as f64;
            if gap <= 10.0 {
                score += 50.0 * (10.0 - gap);
            }
        }
    }

    // Relative to mean residual: placing into a bin with residual far below
    // mean (a crowded bin) is good; spreading into empty-ish bins is bad.
    let dev = post_residual as f64 - mean_residual;
    score += 0.5 * dev;

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: score = 100 - item_size. Only attractive when item
    // is large (little waste) or no good fit exists; penalize otherwise.
    if bin_residual == bin_capacity {
        score += 40.0;
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 30.0; // fresh bin can also host next item
        }
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Slight preference for consolidating into already-open bins early on.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 20.0 * (1.0 - progress) * (bin_residual != bin_capacity) as i32 as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: squared residual penalizes wasteful placements super-linearly.
    score += (post_residual as f64 / bin_capacity as f64).powi(3) * 30.0;

    // Exact fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Lookahead coupling: reward bins whose leftover can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0 + 8.0 * (next_item_size as f64 / 100.0);
        } else {
            // Dead space relative to the next item's need.
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
        // Chain fit: current + next fills the bin almost perfectly.
        if item_size + next_item_size == bin_residual {
            score -= 35.0;
        }
    }

    // Last-chance pressure: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    } else if fitting_bins_count > 2 {
        // Many alternatives: be pickier about poor fits.
        score += post_residual as f64 * 0.1;
    }

    // Global state: many open bins with high mean residual -> prefer consolidation.
    if open_bins_count > 1 && bin_residual as f64 > mean_residual {
        score -= 8.0;
    } else if open_bins_count > 1 && (bin_residual as f64 - mean_residual).abs() < 3.0 {
        score -= 4.0;
    }

    // Time horizon: early stream -> more willing to open new bins (keep flexibility);
    // late stream -> avoid opening new bins, squeeze existing ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let new_bin_penalty = 20.0 + 60.0 * progress;
    if bin_residual == bin_capacity {
        score += new_bin_penalty;
        // Opening a bin is fine if item is large and nothing tight exists.
        if item_size > bin_capacity * 3 / 4 && fitting_bins_count == 0 {
            score -= 45.0;
        }
    }

    // Prefer filling bins with large residuals when item is small.
    if item_size < 30 && bin_residual > 60 {
        score -= 6.0;
    }

    // Mild stochastic-free tie-break: favor slightly fuller bins.
    score -= (bin_capacity - bin_residual) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: quadratic penalty on post residual (dead space), weighted by progress
    let mut score = norm_pr * norm_pr * (1.0 + 2.0 * progress) * cap;

    // Smooth non-linear coupling: reward tight fits via exp decay of post residual
    score -= 8.0 * (-norm_pr * 4.0).exp() * (1.0 - progress * 0.5);

    // Cubic interaction: penalize mid-range residual waste more as stream progresses
    score += 3.0 * norm_pr * (1.0 - norm_pr) * (1.0 - norm_pr) * progress * cap;

    // Last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 6.0;
    }

    // Lookahead: reward if next item fits in post residual
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if pr >= next {
            let slack = (pr - next) / cap;
            score -= 5.0 * (-slack * 6.0).exp();
        } else {
            score += 1.5 * (next - pr) / cap;
        }
    }

    // Mild preference to keep mean residual balanced across bins
    score += 0.05 * (pr - mean_residual).abs() / cap;

    // New-bin candidate: penalize opening a new bin early, less so late
    if bin_residual == bin_capacity {
        score += 4.0 * (1.0 - progress) + 0.5 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic classes: reward residuals that fall into "usable" residue classes.
    // Residuals that are exact fractions of capacity (e.g. 50, 25, 20, 10) are
    // highly reusable; odd, prime-ish residues are dead space.
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect closure — best possible outcome
    } else {
        // Exact division classes: cap/pr integer => residual tiles perfectly
        if bin_capacity % pr == 0 {
            score -= 18.0;
        }
        // Half / quarter classes
        if pr * 2 == bin_capacity { score -= 14.0; }
        if pr * 4 == bin_capacity { score -= 8.0; }
        if pr * 3 == bin_capacity { score -= 6.0; }
        if pr * 5 == bin_capacity { score -= 4.0; }

        // Modulo-10 harmony: residuals divisible by 10 pair well with
        // typical item sizes drawn from multiples of 10.
        if pr % 10 == 0 { score -= 6.0; }
        if pr % 5 == 0 && pr % 10 != 0 { score -= 2.0; }

        // Penalize awkward prime-ish / odd residues
        if pr % 2 == 1 { score += 4.0; }
        if pr > 0 && pr < 10 { score += 12.0; } // unusable sliver
    }

    // Lookahead coupling: if the next item fits exactly into the post residual,
    // strongly reward; if it just barely fails, penalize.
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if next_item_size == pr {
            score -= 30.0;
        } else if next_item_size < pr {
            let slack = (pr - next_item_size) as f64;
            // harmonic class of the leftover after the lookahead placement
            let lr = pr - next_item_size;
            if lr == 0 { score -= 25.0; }
            else if bin_capacity % lr == 0 { score -= 10.0; }
            else if lr % 10 == 0 { score -= 5.0; }
            score -= 12.0 / (1.0 + slack / 10.0);
        } else {
            // next item cannot fit here: mild penalty scaled by overflow size
            score += 2.0 + (n - pr as f64) * 0.15;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
        if post_residual < 10 { score -= 10.0; } // near-perfect fill on last chance
    }

    // New-bin candidate handling: opening a new bin wastes the mean residual
    // of all open bins; make the empty-bin score less attractive when many
    // open bins still hold usable space.
    if bin_residual == bin_capacity {
        score += 25.0 + mean_residual * 0.4 + open_bins_count as f64 * 3.0;
        // But if nothing fits well anywhere, new bin should win: the base
        // post_residual (=capacity) keeps it competitive when penalties on
        // open bins are large.
        if fitting_bins_count == 0 { score -= 40.0; }
    }

    // Tight-fit bonus: reward placements that leave small-but-usable residue
    let tightness = 1.0 - (post_residual as f64 / cap);
    score -= 15.0 * tightness * tightness;

    // Late-stream consolidation: as the stream ends, prefer filling existing
    // bins aggressively to avoid leftover partially-filled bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - post_residual as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: harsh penalty for tiny unusable gaps.
    if post_residual > 0 && post_residual < 10 {
        score += (10.0 - post_residual as f64) * 8.0;
    }
    // Medium gaps (10..25) are moderately wasteful too.
    if post_residual >= 10 && post_residual < 25 {
        score += (25.0 - post_residual as f64) * 1.5;
    }

    // Reward tight fits (post_residual near zero but not dead).
    if post_residual == 0 {
        score -= 30.0;
    }

    // Perfect-fit bonus: residual exactly matches a plausibly useful chunk.
    if post_residual > 0 && post_residual >= 10 && post_residual <= 20 {
        score -= 6.0;
    }

    // Lookahead: if next item fits the post-residual, reward leaving that gap.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 2.0 + next_item_size as f64 * 0.1;
    }
    // Penalize if the leftover gap is just below the next item (frustrated fit).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 4.0;
    }

    // Open-bin pressure: prefer spreading across fewer bins early, allow more later.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += open_bins_count as f64 * (0.6 - 0.4 * progress);

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Deviation from mean residual: prefer bins whose residual is close to item need.
    let target = bin_residual as f64 - item_size as f64;
    score += (target - mean_residual).abs() * 0.3;

    // New-bin candidate: make it unattractive unless open bins are poor fits.
    if bin_residual == bin_capacity {
        score += 45.0;
        // If few bins fit the item, opening a new bin becomes more acceptable.
        if fitting_bins_count <= 1 {
            score -= 55.0;
        }
        if next_item_size > 0 && next_item_size >= bin_capacity {
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward perfect fit
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: reward post_residual matching next item size
    if next_item_size > 0 {
        let nr = next_item_size as f64;
        let diff = (post_residual as f64 - nr).abs();
        // Exact match for next item is excellent
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual >= next_item_size {
            // post_residual can host next item: mild reward scaled by closeness
            score -= 200.0 * (1.0 - diff / bin_capacity as f64);
        } else {
            // post_residual cannot host next item: penalize wasted dead space
            score += 50.0 + diff * 0.5;
        }

        // Compare against mean residual: bins whose residual deviates from mean
        // in a way that wastes space get penalized
        let mean_dev = (post_residual as f64 - mean_residual).abs();
        score += 0.3 * mean_dev;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 300.0;
    }

    // Penalize opening a new bin when decent fitting bins exist
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive if no good alternative exists
        if fitting_bins_count > 0 {
            let best_possible = if next_item_size > 0 {
                (post_residual as f64 - next_item_size as f64).abs()
            } else {
                0.0
            };
            score += 400.0 + best_possible;
        }
        // Slight preference for new bin late in stream if very crowded
        let progress = step_index as f64 / total_items.max(1) as f64;
        if fitting_bins_count == 0 {
            score -= 100.0 * progress;
        }
    }

    // Mild penalty for very small unusable post_residual (fragmentation)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: quadratic bonus for small post_residual.
    score -= (bin_capacity as f64 - post_residual as f64).powi(2) * 0.015;

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        score -= 25.0;
    } else if post_residual < 20 {
        score -= 10.0;
    }

    // Penalize post_residual that is too small for the next item (dead space),
    // but reward post_residual that can exactly host the lookahead item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0 + (next_item_size as f64).sqrt() * 2.0;
        } else {
            score += (next_item_size - post_residual) as f64 * 0.4;
        }
    } else {
        // Last item: strongly prefer wasting as little as possible.
        score += post_residual as f64 * 0.5;
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Discourage opening a new bin when decent fits exist and stream is early/mid.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: base penalty scaled by number of open bins and progress.
        score += 30.0 + open_bins_count as f64 * 2.0 + progress * 20.0;
        // But if mean residual across open bins is small (all bins nearly full),
        // opening a new bin becomes more attractive.
        score -= (mean_residual - 20.0).max(0.0) * 1.2;
    } else {
        // Mild penalty for spreading across too many bins.
        score += open_bins_count as f64 * 0.3 * progress;
    }

    // Reward using bins whose residual is close to the item (minimize fragmentation).
    let tightness = (bin_residual - item_size) as f64;
    score -= (bin_capacity as f64 - tightness) * 0.05;

    // Slight preference for bins with residual above mean (keep balanced pool).
    score += (mean_residual - bin_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Non-linear polynomial coupling of post_residual with stream progress.
    let pr = post_residual as f64 / bin_capacity as f64;
    let poly = pr * pr * (0.5 + 2.0 * progress) + pr * (1.0 - progress) * 0.3;
    score += 3.0 * poly;

    // Reward tight fits, more strongly as the stream progresses.
    let tightness = 1.0 - pr;
    score -= 4.0 * tightness * tightness * (0.4 + 1.2 * progress);

    // Penalize if the lookahead item cannot fit in the resulting residual.
    if next_item_size > 0 {
        if (post_residual as f64) < next_item_size as f64 {
            let waste = next_item_size as f64 - post_residual as f64;
            score += 0.6 * waste * (0.5 + progress);
        } else {
            let slack = post_residual as f64 - next_item_size as f64;
            score -= 0.4 * slack / bin_capacity as f64;
        }
    }

    // Last-chance bin: strong reward to use it rather than open a new one.
    if fitting_bins_count == 1 {
        score -= 8.0 * (0.5 + progress);
    } else if fitting_bins_count > 1 {
        score += 0.3 * (fitting_bins_count as f64 - 1.0);
    }

    // Penalize opening a brand-new bin when decent fits exist.
    if bin_residual == bin_capacity {
        let open_f = open_bins_count as f64;
        score += 6.0 + 0.5 * open_f + 4.0 * (1.0 - progress);
        // Allow a new bin if all existing residuals are small relative to item.
        if bin_residual as f64 - item_size as f64 >= mean_residual {
            score -= 3.0 * (mean_residual / bin_capacity as f64);
        }
    }

    // Mild preference for bins deviating favorably from mean residual.
    score += 0.2 * (bin_residual as f64 - mean_residual) / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

