        // Bonus if post_residual is an exact multiple of next item's class.
        if post_residual % next_item_size == 0 {
            score -= 15.0;
        }
    } else if next_item_size > 0 {
        // Residual too small for the next item: fragment penalty scaled by tightness.
        score += (next_item_size as f64 - pr).min(40.0) * 0.5;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a bin unless the item is large relative to capacity
    // or all open bins would leave bad fragments.
    if bin_residual == bin_capacity {
        let fill_frac = item_size as f64 / cap;
        score = cap * (1.0 - fill_frac); // base: waste after placing in fresh bin
        if next_item_size > 0 && (bin_capacity as u32 - item_size) >= next_item_size {
            score -= 10.0; // fresh bin can also take next item
        }
        if fitting_bins_count > 0 {
            score += 15.0; // prefer existing bins when any fit
        }
    }

    // Mild pressure against hoarding many open bins late in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * 0.05 * (1.0 - progress);

    // Tie-break toward bins below mean residual (consolidating fuller bins).
    score += (pr - mean_residual) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space zone: small leftover gaps are the enemy.
    let dead_zone_hi = 9.0f64;
    if post_residual > 0 && (post_residual as f64) < dead_zone_hi {
        score += 60.0 * (dead_zone_hi - post_residual as f64 + 1.0);
    }

    // Perfect fits are golden.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Reward large residual waste absorption: tight fit relative to item size.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * tightness;

    // Lookahead: bonus if the post residual can host the next item exactly-ish.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > post_residual as u32 && post_residual > 0 {
        // residual too small for next item: penalize proportionally
        score += 10.0 * (next_item_size - post_residual) as f64 / 10.0;
    }

    // Open-bin pressure: prefer filling existing bins when many are open.
    score += 2.5 * open_bins_count as f64;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when current bins are crowded.
    if bin_residual == bin_capacity {
        let pressure = open_bins_count as f64 * mean_residual / bin_capacity as f64;
        score += 15.0 + 20.0 * (1.0 - pressure.min(1.0));
    }

    // Mean residual alignment: prefer bins whose residual is near the mean (avoid outliers).
    score += 0.3 * ((bin_residual as f64 - mean_residual).abs());

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect-fit reward: strongly favor bins where the item fills the bin exactly.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward placements where the leftover residual can host
    // the next item (or nearly so), penalize placements creating dead space
    // relative to the upcoming demand.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let lookahead_scale = 30.0 + 20.0 * progress;

    if next_item_size > 0 {
        if post_residual as u64 >= next_item_size as u64 {
            // Next item fits perfectly into the new residual -> excellent chaining.
            if post_residual == next_item_size {
                score -= 120.0 * lookahead_scale / 30.0;
            } else {
                score -= 25.0 * lookahead_scale / 30.0;
            }
        } else {
            // Dead space penalty scaled by how close the next item is to fitting.
            let gap = (next_item_size - post_residual) as f64;
            score += 0.8 * gap * (1.0 + 0.5 * progress);
        }
    }

    // Relative residual coupling: bins tighter than the mean residual are
    // better candidates (less fragmentation introduced overall).
    let residual_diff = post_residual as f64 - mean_residual;
    score += 0.35 * residual_diff;

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are
    // heavily fragmented (post_residual on an empty bin = capacity - item).
    if bin_residual == bin_capacity {
        score += 40.0 + 0.5 * open_bins_count as f64;
        // But if no existing bin leaves a usable residual for the next item,
        // opening a fresh bin becomes attractive for large items.
        if item_size > 60 && next_item_size > 40 {
            score -= 55.0;
        }
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 80.0;
        }
    }

    // Mild preference for consolidating into fewer bins early in the stream.
    score += 0.15 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: penalize post-residual, but reward tight fits more than linearly.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 25.0 * fit_ratio * fit_ratio;

    // Dead space penalty: residuals too small for the smallest plausible item are wasted.
    if post_residual < 10 {
        score -= 15.0; // perfect closure bonus
    } else if post_residual <= 20 {
        score -= 8.0 * (1.0 - post_residual as f64 / 20.0);
    } else {
        // Large leftover: penalize if it cannot host the lookahead item.
        if (next_item_size as f64) > post_residual as f64 && next_item_size > 0 {
            score += 0.25 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // Lookahead synergy: strongly favor bins whose leftover matches next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 12.0 * (1.0 - slack / 100.0);
    }

    // Last-chance bin: avoid opening a new bin if this is the only fit.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate: usually costly, but attractive when open bins are crowded
    // or the current item is large and fits are poor.
    if bin_residual == bin_capacity {
        let crowding = open_bins_count as f64 / (1.0 + mean_residual / 50.0);
        let progress = step_index as f64 / total_items.max(1) as f64;
        let poor_fit = fit_ratio < 0.6 && post_residual > 40;
        let mut penalty = 30.0 + 5.0 * crowding;
        if poor_fit { penalty -= 25.0; }
        if item_size >= 70 { penalty -= 10.0; }
        // Late in the stream, prefer closing bins out rather than spreading.
        penalty -= 8.0 * progress;
        score += penalty;
    }

    // Mild preference for bins below mean residual (pack tight bins tighter).
    score += 0.05 * (bin_residual as f64 - mean_residual);

    // Slight bias toward fewer open bins when many are open.
    score += 0.02 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Base: waste after placement, non-linearly scaled by stream progress
    let mut score = pr * (1.0 + 0.8 * progress * progress);

    // Polynomial coupling: quadratic/cubic penalty on large post-residuals,
    // growing as the stream progresses (dead space matters more later)
    let poly = pr_norm * pr_norm * (1.0 + pr_norm) * (2.0 + 6.0 * progress);
    score += poly * cap;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 50.0 + 30.0 * progress;
    }

    // Lookahead: reward if next item fits the post-residual exactly or well
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        score -= 20.0 * (1.0 - gap / cap) * (1.0 - gap / cap);
    } else if next_item_size > 0 {
        // next item can't use this residual: penalize proportionally
        score += 5.0 * pr_norm * (1.0 - progress);
    }

    // Last-chance bin: strongly favor using it to avoid opening a bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + 15.0 * (1.0 - progress);
    }

    // New-bin candidate handling: slightly discourage opening a new bin early,
    // more willing late when open bins are fragmented
    if bin_residual == bin_capacity {
        score = 60.0 + 40.0 * (1.0 - progress) + 2.0 * open_bins_count as f64;
        // allow opening when residuals are tiny and fragmented
        if mean_residual < 15.0 && open_bins_count > 2 {
            score -= 30.0;
        }
    }

    // Tie-break: prefer bins whose residual deviates from mean (consolidate)
    let dev = (bin_residual as f64 - mean_residual).abs() / cap;
    score += 4.0 * dev * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit is always ideal.
    if post_residual == 0 {
        score -= 1000.0;
        return score;
    }

    // Harmonic class of the post residual: how "usable" is the leftover space?
    // Class 0: post_residual in {50..} halves, {25,75} quarters, multiples of 10
    // are easier to fill by typical small items (1..100 unknown distribution),
    // so reward residuals that are highly divisible.
    let pr = post_residual;
    let gcd_like = |mut a: u32, mut b: u32| -> u32 {
        while b != 0 { let t = a % b; a = b; b = t; }
        a
    };
    let div = gcd_like(pr, bin_capacity);
    score -= (div as f64) * 0.8; // divisible residuals pair better with future items

    // Quarter/half harmonics are especially valuable.
    if bin_capacity % pr == 0 {
        score -= 15.0;
    } else if pr % 10 == 0 {
        score -= 6.0;
    } else if pr % 5 == 0 {
        score -= 2.0;
    } else {
        score += 4.0; // awkward residual
    }

    // Lookahead coupling: reward when next item fits exactly into post_residual.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 200.0;
        } else if next_item_size < pr {
            let slack = pr - next_item_size;
            // harmonic class of the double-fill leftover
            if slack % 10 == 0 { score -= 25.0; }
            else if slack <= 10 { score -= 12.0; }
            else { score += (slack as f64) * 0.15; }
        } else {
            // next item cannot follow here; penalize more if this residual is small
            if pr < 20 { score += 8.0; }
        }
    } else {
        // last item: just minimize waste
        score += 0.0;
    }

    // Dead-space penalty: residuals below the smallest plausible item are dead.
    if pr < 10 {
        score += 50.0;
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate handling: opening a new bin wastes the residual of this
    // empty candidate. Make it generally unattractive unless open bins are many
    // and mean residual is tiny (fragmented state) or stream is near its end.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut nb = 40.0 + mean_residual * 0.5 + (open_bins_count as f64) * 1.5;
        // near end of stream, opening fresh bins is cheap (few future items to serve)
        nb -= (1.0 - progress) * 0.0 + progress * 20.0;
        // if mean residual is very small, fragmentation is high: new bin OK
        if mean_residual < 12.0 {
            nb -= 45.0;
        }
        score += nb;
    }

    // Mild preference to fill already-open bins to keep open_bins_count low.
    score += (open_bins_count as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals below the minimum item size (1..100
    // interface, min item 1) are pure loss; residuals in the small-gap band
    // (1..=15) are heavily penalized since almost nothing fits them.
    if post_residual > 0 && post_residual <= 15 {
        score += 60.0 * (1.0 - post_residual as f64 / 15.0);
    }

    // Perfect fit is maximally rewarded.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual >= item_size {
        // Residual still usable by same-size items: mild reward.
        score -= 10.0;
    }

    // Reward tight fits relative to bin capacity.
    score += 25.0 * (item_size as f64 / bin_capacity as f64 - (bin_residual as f64 - post_residual as f64).max(0.0) / bin_capacity as f64).abs();

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; with few,
    // discourage near-empty bins hoarding.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * 1.5 * (1.0 - progress);

    // Prefer bins whose residual deviates from the mean (consolidation).
    score += 0.3 * (bin_residual as f64 - mean_residual).abs();

    // Lookahead: if next item fits in the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 30.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size.min(15) {
        score += 20.0; // dead space for the known next item
    }

    // New-bin candidate: neutral baseline, slightly above good fits but below
    // dead-space penalties, so it wins only against bad placements.
    if bin_residual == bin_capacity {
        score = 35.0 + open_bins_count as f64 * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near-match: next item fits tightly into the post residual
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 30.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Next item won't fit here: penalize proportionally to wasted capacity
        let over = (next_item_size - post_residual) as f64;
        score += 15.0 * (over / bin_capacity as f64);
    }

    // Reward leaving post_residual below mean_residual (tight packing)
    let mean_gap = mean_residual - post_residual as f64;
    score -= 0.5 * mean_gap;

    // Penalize large unusable dead space (post_residual smaller than min item 1)
    if post_residual < 1 {
        score += 100.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when no open bin fits well
    if bin_residual == bin_capacity {
        let good_lookahead = next_item_size > 0 && post_residual >= next_item_size;
        if fitting_bins_count > 0 {
            // Opening a new bin when others fit is costly unless current fits are terrible
            let penalty = 50.0 + 10.0 * (open_bins_count as f64).sqrt();
            score += if good_lookahead { penalty * 0.5 } else { penalty };
        } else {
            score -= 25.0; // no alternative: new bin is fine
        }
    }

    // Late in stream: be more conservative, prefer filling existing bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (bin_capacity - bin_residual) as f64 / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = 0.0;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let c = bin_capacity as f64;
    let pr = post_residual as f64;
    let r = bin_residual as f64;
    let it = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let fit_ratio = it / r.max(1.0);

    // Base: prefer small post_residual (tight fit), non-linearly scaled
    let mut score = 0.7 * pr + 12.0 * (pr / c).powi(3) * c;

    // Reward high fill fraction with smooth coupling to stream progress
    let fill = 1.0 - pr / c;
    score -= 30.0 * fill.powi(2) * (0.5 + progress);

    // Penalize large absolute dead space quadratically
    score += 0.35 * (pr * pr) / c;

    // Smooth interaction: residual vs progress — later in stream, prefer tighter packing
    score += 8.0 * (pr / c) * (1.0 - progress) * (1.0 - progress);

    // Lookahead coupling: reward post_residual that can host next item, penalize near-miss
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let gap = pr - nx;
        if gap >= 0.0 {
            score -= 10.0 * (1.0 - (gap / c).powi(2));
        } else {
            score += 6.0 * (gap / c).powi(2) * c / 10.0;
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0 * (0.5 + fit_ratio);
    }

    // Crowding penalty: many open bins -> favor consolidation (fill existing bins)
    let crowd = (open_bins_count as f64 / (1.0 + open_bins_count as f64)).ln();
    score += 15.0 * crowd * (pr / c);

    // Mean residual deviation: prefer bins whose residual is below average (already tight)
    score += 5.0 * ((pr as f64) - mean_residual) / c;

    // New-bin candidate: mild penalty so it's only chosen when fits are terrible
    if bin_residual == bin_capacity {
        score += 20.0 + 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: quantize leftover space into capacity fractions.
    let pr = post_residual as f64;
    let class = (pr / cap * 8.0).floor(); // 0..7 harmonic class of leftover
    // Reward tight fits: class 0 (leftover < 12.5% of capacity) heavily rewarded.
    score -= (8.0 - class) * 6.0;

    // Exact-fill bonus
    if post_residual == 0 {
        score -= 60.0;
    }

    // Penalize dead space: leftover too small for the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Modulo arithmetic on next_item_size: does the lookahead item divide into leftover?
    if next_item_size > 0 && next_item_size <= post_residual {
        // Lookahead fits here -> reward reserving this bin.
        score -= 20.0;
        // Extra reward if lookahead would fill leftover almost exactly (harmonic pairing).
        let pair_gap = post_residual - next_item_size;
        if pair_gap <= 5 {
            score -= 15.0;
        }
    } else if next_item_size > 0 {
        // Lookahead won't fit here; penalize more if we'd be left with awkward class.
        let awkward = (post_residual % 10) as f64;
        score += awkward * 0.5;
    }

    // Integer-division thresholds: bins whose residual is in mid-range classes are good targets.
    let residual_class = bin_residual / (bin_capacity / 4).max(1); // 0..4
    score += match residual_class {
        0 => 30.0, // nearly full bin: avoid unless perfect fit
        1 => -5.0,
        2 => -10.0,
        3 => 5.0,
        _ => 0.0,
    };

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // New-bin candidate handling: only open a new bin when no good fit exists.
    if bin_residual == bin_capacity {
        // Base cost of a new bin.
        score = cap * 0.35;
        // Opening a bin is attractive if current item is large and mean residual is fragmented.
        if item_size as f64 > cap * 0.6 {
            score -= 15.0;
        }
        if mean_residual < cap * 0.25 {
            score -= 10.0;
        }
        // Late in the stream, prefer closing out existing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a bin
        }
    }

    // Mild pressure against proliferating bins.
    score += open_bins_count as f64 * 0.5;

    // Small tie-breaker favoring fuller bins.
    score -= (bin_capacity - bin_residual) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small for likely future
    // items are heavily penalized. Treat gaps < 10 as "unusable dead space".
    if post_residual > 0 && post_residual < 10 {
        score += 45.0;
    } else if post_residual < 20 {
        score += 12.0 * (1.0 - post_residual as f64 / 20.0);
    }

    // Reward near-perfect fits superlinearly.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post-residual,
    // strongly reward this placement; if the next item cannot use the residual
    // at all, penalize creating that gap.
    if next_item_size > 0 {
        let nr = next_item_size as f64;
        let pr = post_residual as f64;
        if nr <= pr {
            score -= 10.0 + 0.5 * (pr - nr);
        } else {
            score += 0.35 * (nr - pr);
        }
    }

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing ones; opening new bins is penalized via the empty-bin candidate
    // (bin_residual == bin_capacity).
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 / (1.0 + progress * 4.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: acceptable early, increasingly expensive later.
        score += 8.0 + 6.0 * pressure + 10.0 * progress;
        // If no open bin fits, opening a bin is unavoidable-ish: soften.
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
    } else {
        // Existing bin: reward slightly when many bins are open.
        score -= 2.0 * pressure;
        // Last-chance bin: strongly prefer using it over opening a new bin.
        if fitting_bins_count == 1 {
            score -= 30.0;
        }
    }

    // Prefer bins whose residual is below the mean residual (tighter bins),
    // mildly steering toward the fullest bin.
    if bin_residual != bin_capacity {
        score += 0.25 * (mean_residual - bin_residual as f64).max(-30.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: prefer bins whose post-residual is small dead space.
    score -= 0.6 * (bin_capacity as f64 - post_residual as f64).max(0.0) * 0.0; // no-op guard

    // Exact / near-exact fit bonus.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 10 {
        score -= 300.0;
    } else if post_residual <= 20 {
        score -= 120.0;
    }

    // Aggressive 2-step lookahead: strongly reward bins where the NEXT item
    // also fits into the post-residual (chained packing).
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Next item fits: reward proportional to how snugly it fits after.
            let chain_residual = post_residual - next_item_size;
            score -= 150.0 + (20.0 - chain_residual.min(20) as f64) * 3.0;
        } else {
            // Next item does not fit here: penalize wasted chain potential,
            // scaled by how close the miss was.
            let miss = (next_item_size - post_residual) as f64;
            score += miss.min(30.0) * 2.0;
        }
    }

    // Relative-to-mean coupling: bins below mean residual are already tight;
    // favor filling them further, penalize leaving big residuals above mean.
    let dev = post_residual as f64 - mean_residual;
    score += 0.35 * dev;

    // Penalize creating large unusable residuals (dead space) quadratically.
    if post_residual > 30 {
        score += 0.02 * (post_residual as f64 - 30.0).powi(2);
    }

    // Last-chance bin: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 250.0;
    }

    // New-bin candidate: make empty bins attractive only when no open bin
    // offers a decent fit; otherwise discourage spreading items thin.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Base reluctance grows with number of open bins and stream progress.
        score += 80.0 + 12.0 * open_bins_count as f64 + 60.0 * progress;
        // But if next item is large and current fit is poor, allow fresh bins.
        if next_item_size > 0 && next_item_size > post_residual + item_size {
            score -= 120.0;
        }
        // Late in the stream, prefer consolidating rather than opening bins.
        if progress > 0.8 {
            score += 100.0;
        }
    }

    // Slight preference for bins with larger residual when all else equal
    // (keeps big residuals usable).
    score -= 0.05 * bin_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: squared penalty on wasted space.
    score += (post_residual as f64).powi(2) / bin_capacity as f64;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Penalize large dead space relative to smallest plausible item (1..100 interface).
    if post_residual > 0 && post_residual < 10 {
        score += 8.0; // tiny unusable slivers
    }

    // Lookahead coupling: if next item fits exactly in the post-residual, reward strongly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 / (1.0 + slack / 10.0);
        } else {
            // next item won't fit here; slight penalty proportional to overflow gap
            score += ((next_item_size - post_residual) as f64) * 0.15;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Time horizon: early in stream, prefer consolidating into existing bins (favor open bins);
    // late in stream, allow opening new bins for better fits.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let new_bin_bias = 20.0 * (1.0 - progress);
    if bin_residual == bin_capacity {
        score += new_bin_bias;
        // discourage opening new bins when many bins already open and mean residual is large
        score += open_bins_count as f64 * 0.5 + mean_residual * 0.2;
    } else {
        // favor bins whose residual is above mean (keeps balance, avoids many near-full bins)
        score -= (bin_residual as f64 - mean_residual) * 0.1;
    }

    // Moderate reward for filling a bin past half when many bins are open.
    if post_residual < bin_capacity / 2 && bin_residual != bin_capacity {
        score -= 5.0 + open_bins_count as f64 * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post residual, with non-linear polynomial coupling to stream progress.
    let mut score = pr;

    // Smooth quadratic coupling: residual waste penalized more as stream progresses.
    score += (norm_pr * norm_pr) * cap * (0.5 + 1.5 * progress);

    // Cubic dead-space term: very small residuals are dead space; penalize smoothly.
    score += (norm_pr - 0.15) * (norm_pr - 0.15) * (norm_pr - 0.15) * cap * 20.0;

    // Perfect-fit reward (subtracted), stronger mid-stream.
    let fit_quality = 1.0 - (norm_pr - 0.0).abs();
    score -= fit_quality * fit_quality * 8.0 * (1.0 - progress);

    // Last-chance bonus: strongly favor the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * progress;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, reward.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (pr - nxt).abs();
        let closeness = 1.0 - gap / cap;
        if closeness > 0.0 {
            score -= closeness * closeness * 12.0 * (0.5 + 0.5 * progress);
        } else {
            score += (-closeness) * 3.0;
        }
    }

    // Mean residual context: prefer bins below mean residual (tighter packing).
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += dev * dev * 5.0 - dev * 2.0;

    // Mild penalty for scattering across many open bins.
    score += (open_bins_count as f64).ln() * 0.5;

    // New-bin candidate: neutral base score; encourage only when current bin leaves bad waste.
    if bin_residual == bin_capacity {
        score = cap * (0.35 + 0.4 * progress) + norm_pr * cap;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic classes of post_residual (mod-based dead-space quality).
    // Residuals that are "useful" (divisible into small item sizes) are less dead.
    let pr = post_residual;
    let mut deadness = 0.0;
    if pr > 0 {
        if pr % 10 == 0 {
            deadness = 0.0;                       // highly reusable residual
        } else if pr % 5 == 0 {
            deadness = 4.0;
        } else if pr % 2 == 0 {
            deadness = 8.0;
        } else {
            deadness = 14.0;                      // odd residuals are hardest to fill
        }
        // Very small residuals are dead space regardless of class.
        if pr < 10 {
            deadness += 30.0 * (10 - pr) as f64;
        }
        score += deadness;
    }

    // Lookahead: does the next item fit exactly into the post residual?
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 500.0;                       // chain a perfect follow-up
        } else if next_item_size < pr {
            let slack = (pr - next_item_size) as f64;
            // Prefer residuals that leave the next item with a good harmonic class.
            let ns = pr - next_item_size;
            let class_bonus = if ns == 0 { 400.0 } else if ns % 10 == 0 { 150.0 } else if ns % 5 == 0 { 60.0 } else if ns % 2 == 0 { 20.0 } else { 0.0 };
            score -= class_bonus + 30.0 / (1.0 + slack / 20.0);
        } else {
            // Next item won't fit here: mild penalty, stronger if this was the only fitting bin.
            score += 20.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 120.0;
    }

    // New-bin candidate handling: opening a new bin is justified when the fit
    // here is poor (large dead space) relative to mean residual.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // Empty bin: neutral baseline; attractive only if existing fits are bad.
        score = 60.0 + 40.0 * progress;
    } else {
        // Penalize wasting a bin whose residual is far above mean (fragmentation).
        let frag = (bin_residual as f64 - mean_residual).max(0.0);
        score += 0.15 * frag;
    }

    // Encourage filling bins when many are open (limit bin sprawl).
    score -= 0.5 * open_bins_count as f64;

    // Integer-division threshold: reward placements leaving residuals in
    // "quarter capacity" bands (25/50/75), which pair well with typical items.
    match post_residual {
        0 => score -= 200.0,
        25 => score -= 80.0,
        50 => score -= 60.0,
        75 => score -= 40.0,
        _ => {}
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps more harshly.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 15.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Reward tight fits relative to bin residual.
    let tightness = item_size as f64 / bin_residual as f64;
    score -= 25.0 * tightness;

    // Dead-space severity: small post_residual relative to item size is bad.
    if post_residual > 0 {
        let ratio = post_residual as f64 / item_size as f64;
        if ratio < 0.3 {
            score += 10.0 * (0.3 - ratio);
        }
    }

    // Open bins pressure: prefer filling existing bins when many are open.
    score += open_bins_count as f64 * 1.5;

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bin is a bad fit.
    if bin_residual == bin_capacity {
        score += 30.0;
        // But allow fresh bin if item is large and no tight fit available.
        if item_size > bin_capacity / 2 && fitting_bins_count <= 1 {
            score -= 20.0;
        }
    }

    // Lookahead: if next item fits into post_residual, reward this placement.
    if next_item_size > 0 && (post_residual as i64 - next_item_size as i64) == 0 {
        score -= 30.0;
    } else if next_item_size > post_residual as u32 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0; // dead space that next item cannot use
    }

    // Mean residual coupling: bins with residual far below mean are more valuable to fill.
    let dev = mean_residual - bin_residual as f64;
    score += 0.3 * dev;

    // Late-stream consolidation pressure.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    } else if next_item_size > 0 && post_residual > next_item_size {
        // Next item still fits after this one: mild reward proportional to slack
        let slack = (post_residual - next_item_size) as f64;
        score -= 8.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > post_residual {
        // Dead space relative to the lookahead item: penalize unusable gap
        let dead = (next_item_size - post_residual) as f64;
        score += 0.35 * dead;
    }

    // Reward tight fits (small post_residual) non-linearly
    let tightness = 1.0 - post_residual as f64 / bin_capacity as f64;
    score -= 12.0 * tightness * tightness;

    // Penalize placements far from the mean residual (wasted large residual)
    if post_residual as f64 > mean_residual {
        score += 0.2 * (post_residual as f64 - mean_residual);
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New empty bin candidate: penalize unless the item is large or many bins open
    if bin_residual == bin_capacity {
        let ratio = item_size as f64 / bin_capacity as f64;
        score += 18.0 * (1.0 - ratio);
        score += 0.8 * open_bins_count as f64;
    }

    // Slight preference for consolidating into fewer bins as stream progresses
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 3.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Reward tight fits
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize dead space that cannot hold the next item
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 0.6 * (next_item_size - post_residual) as f64;
        } else {
            score -= 0.3 * (post_residual - next_item_size) as f64;
        }
    }

    // Last-chance bonus: only bin that fits
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Scarcity pressure: fewer fitting bins -> favor this one
    if fitting_bins_count >= 1 {
        score -= 3.0 / fitting_bins_count as f64;
    }

    // Prefer bins whose residual is near the mean (keeps spread balanced)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // New-bin candidate handling
    if bin_residual == bin_capacity {
        let base = 40.0 + 20.0 * t;
        // Open a new bin only if this is a forced or very poor fit situation
        if fitting_bins_count == 0 {
            score -= 100.0;
        } else if fitting_bins_count == 1 {
            score += 10.0;
        } else {
            score += base;
        }
        // Early stream: slightly more willing to open bins
        score -= 10.0 * (1.0 - t);
    }

    // Mild penalty for too many open bins late in stream
    score += 0.05 * open_bins_count as f64 * t;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let pr = post / cap; // normalized post residual

    // Base: prefer tight fits, non-linearly scaled by stream progress.
    let mut score = post * (1.0 + 0.8 * progress);

    // Non-linear polynomial coupling: mid-range residuals are penalized more
    // as the stream progresses (dead space becomes costlier late).
    let bump = pr * (1.0 - pr); // peaks at pr = 0.5
    score += 30.0 * bump * bump * (0.5 + progress);

    // Quadratic penalty on post residual, growing with progress.
    score += 0.15 * pr * pr * cap * progress;

    // Last-chance bin: strong reward so scarce fits are used.
    if fitting_bins_count == 1 {
        score -= 25.0 + 20.0 * progress;
    }

    // Lookahead coupling: reward if next item fits into the resulting residual.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let slack = (post - nxt) / cap;
            score -= 12.0 * (1.0 - slack) * (1.0 - 0.5 * progress);
        } else {
            // Next item cannot follow here: penalize leaving residual sized
            // between next item and a useful threshold, smoothly.
            let gap = (nxt - post) / cap;
            score += 8.0 * gap * (1.0 - gap);
        }
    }

    // Prefer bins whose residual deviates favorably from the mean residual
    // (pack into fuller bins relative to the fleet).
    score += 0.05 * (mean_residual - post);

    // Mild preference for consolidating into fewer open bins.
    score += 0.3 * open_bins_count as f64 * pr;

    // New-bin candidate: only attractive when nothing fits well.
    let is_new = bin_residual == bin_capacity && item_size > 0;
    if is_new {
        score = cap - item_size as f64 + 20.0 * (1.0 - progress);
        if fitting_bins_count == 0 {
            score -= 50.0;
        }
        if fitting_bins_count == 1 {
            score += 60.0; // don't open a new bin when a last-chance bin exists
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: perfect fits (0) are heavily rewarded.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Dead space: small post_residual that no realistic item can fill.
    // Items are >= 1, but tiny residuals (1..=4) are essentially dead.
    if post_residual > 0 && post_residual <= 4 {
        score += 30.0;
    }

    // Harmonic classes via integer division: post_residual in [0,25), [25,50), [50,75), [75,100]
    let post_class = post_residual / 25;
    match post_class {
        0 => score -= 20.0,          // tight fit, nearly full bin: good
        1 => score += 5.0,           // moderate dead space
        2 => score += 10.0,          // half-empty bin
        _ => score -= 5.0,           // mostly empty bin: flexible
    }

    // Modulo arithmetic on post_residual: residuals divisible by common item sizes
    // (10, 20, 25, 50) are reusable, reward them.
    if post_residual > 0 && (post_residual % 10 == 0 || post_residual % 25 == 0) {
        score -= 8.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 200.0;
        } else if next_item_size < post_residual {
            let next_post = post_residual - next_item_size;
            // Reward leaving space the next item can use well.
            score -= (next_item_size as f64) * 0.3;
            if next_post <= 4 {
                score += 15.0; // would create dead space for the follower
            }
        } else {
            // Next item cannot use this bin's remainder anyway; slight penalty
            // unless post_residual is large (flexible).
            if post_residual < 25 {
                score += 12.0;
            }
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate handling: opening a new bin is expensive; make the empty
    // bin attractive only when current fits are poor.
    if bin_residual == bin_capacity {
        score = post_residual as f64 + 45.0;
        if fitting_bins_count == 0 {
            score -= 500.0; // no alternative: must open
        }
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 10.0;
    }

    // Prefer bins below mean residual (fill emptier bins less; keep tight bins tight).
    let residual_f = bin_residual as f64;
    if residual_f > mean_residual {
        score += (residual_f - mean_residual) * 0.15;
    } else {
        score -= (mean_residual - residual_f) * 0.05;
    }

    // Many open bins: encourage closing bins out (fill tight ones).
    if open_bins_count > 8 {
        score -= (25 - post_residual.min(25)) as f64 * 0.4;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals below the minimum item size (1..~10)
    // are "perfect" (bin nearly closed), residuals in the awkward small band
    // (just above the smallest typical item) are dead space -> heavy penalty.
    if post_residual == 0 {
        score -= 60.0; // perfect fill
    } else if post_residual < 10 {
        score -= 25.0; // unusable sliver, effectively a perfect fit
    } else if post_residual <= 20 {
        score += 30.0; // awkward gap: too small for most items, too big to ignore
    }

    // Reward tight fits: fraction of bin consumed by this placement.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 20.0 * fill_ratio;

    // Open-bin pressure: with many open bins, discourage spreading; prefer
    // consolidating into existing bins rather than opening new ones.
    score += 2.5 * open_bins_count as f64;

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: only attractive when no open bin fits well or
    // open bins are nearly full. Penalize opening new bins otherwise.
    if bin_residual == bin_capacity {
        score += 45.0 + 6.0 * open_bins_count as f64;
        if fitting_bins_count == 0 {
            score -= 80.0; // nothing fits anywhere: must open a bin
        } else if fitting_bins_count == 1 {
            score += 25.0; // a last-chance bin exists: prefer it
        }
        // If the next item is huge, a fresh bin is less useful now.
        if next_item_size > 0 && next_item_size > bin_capacity - item_size {
            score += 10.0;
        }
    }

    // Lookahead coupling: reward placements that leave exactly room for the
    // next item (perfect pairing), penalize leaving room that *almost* fits it.
    if next_item_size > 0 {
        let gap = post_residual as i64 - next_item_size as i64;
        if gap == 0 {
            score -= 30.0; // next item fills this bin exactly
        } else if gap > 0 && gap < 10 {
            score += 15.0; // near-miss leaves dead space
        } else if gap < 0 && (-gap) < 10 {
            score -= 10.0; // next item slightly overflows: still decent fit
        }
    }

    // Mean-residual coupling: bins far below the mean residual are "dusty"
    // (unlikely to be filled); prefer placing into bins near/above the mean.
    let dev = bin_residual as f64 - mean_residual;
    score += 0.15 * dev;

    // Slight early-stream aggression: open bins freely at the start,
    // become conservative as the stream progresses.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 10.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match of post_residual with next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0; // perfect chain: next item exactly fills this bin
        } else if post_residual > next_item_size {
            score -= 25.0 * (post_residual as f64 - next_item_size as f64).min(30.0) / 30.0;
        } else {
            // next item cannot follow into this bin; penalize proportionally to waste
            score += 15.0 * (next_item_size as f64 - post_residual as f64) / 40.0;
        }
    }

    // Prefer bins whose residual is close to the mean (keep pool balanced),
    // but break ties toward tight fits.
    let mean_gap = (post_residual as f64 - mean_residual).abs();
    score += 0.35 * mean_gap;

    // Tightness reward relative to capacity
    score -= 20.0 * (item_size as f64 / bin_capacity as f64);

    // Last-chance bin: strongly avoid opening a new bin when only this bin fits
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Penalize opening a new bin when existing bins have plenty of room
    if bin_residual == bin_capacity {
        let avg = if open_bins_count > 0 { mean_residual } else { 0.0 };
        if avg > item_size as f64 * 2.0 {
            score += 30.0;
        }
        score += 5.0; // mild default cost of new bin
    }

    // Late in stream: consolidate more aggressively
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: strongly favor bins where the item nearly fills the residual.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 45.0 * tightness * tightness;

    // Penalize dead space that is too small for typical future items.
    if post_residual > 0 {
        let dead = post_residual as f64;
        if next_item_size > 0 && (post_residual as u64) < (next_item_size as u64) {
            score += 0.6 * dead; // unusable for the next item
        } else {
            score -= 0.2 * dead; // still usable, mild bonus
        }
    }

    // Lookahead coupling: reward residuals that can host the next item exactly.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 12.0 / (1.0 + gap);
        if post_residual == next_item_size {
            score -= 30.0; // perfect chain placement
        }
    } else {
        // Last item: pure tightness matters most.
        score -= 0.5 * (post_residual as f64);
    }

    // Last-chance bin: strongly prefer using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 55.0;
    }

    // Crowding pressure: many open bins -> discourage spreading; few bins -> encourage consolidation.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let crowding = (open_bins_count as f64).ln().max(0.0);
    score += 2.0 * crowding * (0.5 + 0.5 * progress);

    // Mean residual alignment: prefer bins whose residual deviates from the mean in useful ways.
    let bin_res = bin_residual as f64;
    let dev = bin_res - mean_residual;
    score += 0.15 * dev * (1.0 - progress);

    // New-bin candidate handling: only attractive when the current fit is poor.
    if bin_residual == bin_capacity {
        let poor_fit = (post_residual as f64) / (bin_capacity as f64);
        if open_bins_count == 0 {
            score -= 100.0; // must open a bin
        } else if poor_fit > 0.55 {
            score -= 25.0 + 40.0 * (poor_fit - 0.55); // opening beats bad fit
        } else {
            score += 30.0 + 50.0 * (0.55 - poor_fit); // keep using open bins
        }
        // Late in the stream, avoid fragmenting across many bins.
        score += 10.0 * progress * crowding;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let prn = pr / cap;
    let is_new = (bin_residual as f64 - cap).abs() < 1e-9;

    let mut score = pr;

    // Smooth polynomial coupling of post_residual with stream progress.
    let w = 0.5 + 0.5 * (progress * std::f64::consts::PI).sin();
    score += 12.0 * prn * prn * (1.0 - w) * cap * 0.1;
    score -= 10.0 * prn * w * (1.0 - prn);

    // Penalize dead space relative to mean residual (smooth quadratic coupling).
    let dev = pr - mean_residual;
    score += 0.15 * dev * dev / cap;

    // Lookahead: reward residual that can still host the next item.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            score -= 8.0 * (1.0 - prn) * (nx / cap);
        } else {
            score += 6.0 * (nx - pr) / cap * (1.0 + progress);
        }
    }

    // Last-chance fitting bonus, stronger late in the stream.
    if fitting_bins_count == 1 && !is_new {
        score -= 15.0 * (0.5 + 0.5 * progress);
    }

    // New-bin candidate: mildly penalize early, allow late when residuals are tight.
    if is_new {
        score += 20.0 * (1.0 - progress) - 10.0 * progress * (1.0 - prn);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover: classify post_residual by capacity fraction.
    let c = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / c; // 0..1

    // Penalize dead space in awkward harmonic bands: (0, 10) unusable sliver,
    // (10, 20) fits almost nothing. Reward large, reusable residuals.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0;
    } else if post_residual == 0 {
        score -= 120.0; // perfect fit, huge reward
    }

    // Modulo class coupling: does post_residual align with typical item sizes?
    // Residuals congruent to 0 mod 10 pair well with decade-sized items.
    if post_residual % 10 == 0 {
        score -= 8.0;
    }

    // Lookahead: if next item fits exactly into post_residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size < post_residual {
            let npr = post_residual - next_item_size;
            // penalize if next placement leaves another sliver
            if npr < 10 { score += 15.0; } else { score -= 10.0; }
        } else {
            // next item can't use this bin's leftover: leftover likely dead
            score += 0.5 * (post_residual as f64) / c * 20.0;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate (empty bin): only attractive when current bin fit is bad
    // (large post_residual waste) or many bins already open with slack.
    if bin_residual == bin_capacity {
        let pressure = mean_residual / c; // average slack across open bins
        score = 100.0 + 0.6 * (post_residual as f64);
        // discourage new bins early in stream or when open bins are tight
        score -= 40.0 * (1.0 - pressure).min(1.0);
        score += 20.0 * (open_bins_count as f64 / 50.0).min(1.0);
    }

    // Late-stream tightening: value closing bins tightly as stream ends.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 15.0 * progress * (1.0 - frac);

    // Prefer bins below mean residual (tighter bins first) to keep slack bins flexible.
    score += 0.3 * ((bin_residual as f64) - mean_residual).max(-50.0).min(50.0) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: small unusable gaps (1..=15) are heavily penalized,
    // scaled by how close the gap is to zero.
    if post_residual > 0 && post_residual <= 15 {
        score += (16.0 - post_residual as f64) * 8.0;
    }
    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward;
    // if the next item would not fit in post residual but fits in a fuller bin,
    // penalize wasting space that could host it.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= (next_item_size as f64) * 0.8;
        } else {
            score += (next_item_size as f64) * 0.4;
        }
    }

    // Open-bin pressure: discourage spreading across many bins unless the fit is tight.
    score += (open_bins_count as f64) * 1.5;

    // Last chance: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: make empty bins attractive only when the current fit is bad.
    if bin_residual == bin_capacity {
        // Neutral-ish baseline; dead-space logic above will dominate for open bins.
        score += 10.0;
        if item_size >= bin_capacity / 2 {
            score -= 20.0; // big items prefer fresh bins
        }
    }

    // Mean residual coupling: prefer bins deviating below the mean residual
    // (fill the emptier-of-space bins first keeps others flexible).
    score += (mean_residual - bin_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when post_residual matches next item exactly.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect match for the next item is a strong bonus.
        if post_residual == next_item_size {
            score -= 60.0;
        } else {
            score += diff * 0.4;
        }
        // If next item fits in the post-residual, mild reward.
        if post_residual >= next_item_size {
            score -= 10.0;
        }
    } else {
        // Last item: prefer minimal waste.
        score += post_residual as f64 * 0.1;
    }

    // Relative to mean residual: prefer bins tighter than average.
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Last chance bin (only fitting bin): strong bonus to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Penalize creating dead space below typical minimum item size.
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // Early in stream: slightly favor keeping few bins open / compacting.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * (post_residual as f64 - mean_residual) * 0.1;

    // New-bin candidate: make it attractive only when current bins fit poorly.
    if bin_residual == bin_capacity {
        // Neutral base; lookahead makes opening attractive if next item pairs well.
        score += 5.0;
        if next_item_size > 0 && (bin_capacity - next_item_size) >= item_size {
            score -= 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits: minimize post_residual relative to capacity.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // Penalize leaving dead space that likely can't be reused by the next item.
    if next_item_size > 0 {
        let waste = (post_residual as i64 - next_item_size as i64).max(0) as f64;
        score += 0.9 * waste;
        // Reward bins whose post-residual exactly accommodates the next item.
        if post_residual == next_item_size {
            score -= 25.0;
        }
    } else {
        // Last item: just fill as tightly as possible.
        score -= 30.0 * tightness;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a new bin unless the fit is poor
    // everywhere else. The empty-bin call has post_residual = capacity - item.
    if bin_residual == bin_capacity {
        // Scale penalty with stream progress: later in stream, more value in
        // filling existing bins.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 15.0 + 25.0 * progress;
        // Opening a new bin is more attractive when many bins exist with high
        // mean residual (fragmentation) and item is large.
        if item_size as f64 > mean_residual {
            score -= 12.0;
        }
        // If the item would leave a tiny unusable sliver in an existing bin,
        // opening fresh can be better.
        if post_residual < 10 {
            score -= 18.0;
        }
    } else {
        // Mild preference for bins with larger residuals among open bins
        // (first-fit-decreasing-like consolidation of small items).
        score -= 0.05 * (bin_residual as f64 - mean_residual);
    }

    // Penalize spreading across too many open bins slightly.
    score += 0.15 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let pr = post / cap;

    let mut score = post;

    // Non-linear coupling: post_residual scaled by progress-dependent polynomial
    score += 40.0 * pr * pr * (0.5 + 0.5 * progress);

    // Penalize dead space that is too small to be useful (smooth trough)
    let dead = 1.0 - (post / 30.0).tanh().abs();
    score += 25.0 * dead * (0.3 + 0.7 * progress);

    // Reward tight fits more strongly as stream progresses
    score -= (1.0 - pr) * (1.0 - pr) * (10.0 + 30.0 * progress);

    // Last-chance bonus when this is the only fitting bin
    if fitting_bins_count == 1 {
        score -= 15.0 + 20.0 * progress;
    } else {
        score += 2.0 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // Mean residual coupling: prefer bins near mean early, below mean later
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 8.0 * dev * (1.0 - 2.0 * progress);

    // Lookahead: reward leaving space for next item
    if next_item_size > 0 {
        let n = next_item_size as f64;
        let compat = (post - n).abs();
        score += 12.0 * (1.0 - (-compat / 40.0).exp()) - 8.0 * ((post >= n) as i32 as f64);
    }

    // New-bin candidate: penalize mildly early, allow late when open bins are wasteful
    if bin_residual == bin_capacity {
        score += 6.0 - 12.0 * progress + 1.5 * open_bins_count as f64 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins with small post_residual.
    score -= (bin_capacity as f64 - post_residual as f64) * 0.5;

    // Harmonic class of post_residual: dead space in classes 1..=9 is nearly unusable
    // for items >= 10, so penalize small nonzero remainders.
    let pr = post_residual;
    if pr > 0 {
        let class = pr % 10;
        if class >= 1 && class <= 9 {
            score += (10 - class) as f64 * 8.0; // worse the closer to 9 (max dead space below 10)
        }
        // Perfect zero residual is ideal; already rewarded by tight-fit term.
        if pr >= 10 && pr <= 20 {
            score -= 6.0; // residue that can host a typical next item is valuable
        }
    }

    // Lookahead coupling: if the next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && next_item_size <= pr {
        let slack = (pr - next_item_size) as f64;
        score -= 15.0 - slack * 0.3; // exact harmonic match bonus
    } else if next_item_size > pr && next_item_size > 0 {
        score += 5.0; // next item won't fit here; slightly deprioritize
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: only attractive when no open bin fits well
    // (i.e., item leaves large unusable residue everywhere) or few bins open.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let waste_if_open = (bin_capacity - item_size) as f64;
        // Opening a new bin costs ~capacity of committed space; make it expensive
        // unless the best alternative would waste more.
        score = waste_if_open + 25.0 - 10.0 * progress;
        if open_bins_count == 0 {
            score = -100.0; // must open
        }
        if fitting_bins_count == 0 {
            score -= 60.0; // nothing fits, new bin is correct
        }
        if next_item_size > 0 && (bin_capacity - item_size) >= next_item_size {
            score -= 5.0; // new bin also accommodates lookahead
        }
    }

    // Mild preference to fill bins with larger residual first when many bins open.
    score += (open_bins_count as f64).sqrt() * 0.05 * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: post_residual in [1..=15] is nearly unusable
    // (min item size is small but such gaps rarely get filled) -> heavy penalty.
    if post_residual > 0 && post_residual <= 15 {
        score += 60.0 * (16.0 - post_residual as f64) / 16.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Tight fit bonus: item fills a large fraction of the bin's residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fill_ratio * fill_ratio;

    // Reward gaps that can still fit the lookahead item (k=2 lookahead).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    } else if next_item_size > 0 && post_residual > 0 {
        // Gap too small for the next item: mild dead-space penalty.
        score += 6.0;
    }

    // Last-chance pressure: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidation into existing
    // bins rather than opening new ones.
    score += 1.5 * open_bins_count as f64;

    // Progression: late in the stream, be more aggressive about filling bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * fill_ratio;

    // New-bin candidate: empty bin has residual == capacity; it should only win
    // when existing bins would leave bad dead space. Penalize it moderately.
    if bin_residual == bin_capacity {
        score += 30.0 + 2.0 * open_bins_count as f64;
    }

    // Deviation from mean residual: prefer bins tighter than average.
    score += 0.3 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }

    // Penalize dead space: post_residual too small for next item (wasted sliver).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 2.0;
    }

    // Reward when post_residual can still hold next item (flexibility), scaled by tightness.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (post_residual - next_item_size) as f64 * 0.5;
    }

    // Penalize opening a new bin when other bins fit, unless it's a perfect first fit.
    if bin_residual == bin_capacity && fitting_bins_count > 0 && !(next_item_size > 0 && post_residual == next_item_size) {
        score += 150.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // Relative to mean residual: prefer bins tighter than average.
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Slight preference for packing into existing bins over time.
    if bin_residual != bin_capacity {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: less waste after placement is better.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 40.0 * fit_ratio * fit_ratio;

    // Penalize dead space that is too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            // Next item won't fit here; mild penalty proportional to leftover.
            score += 5.0 * (1.0 - fit_ratio);
        }
    } else {
        // Last item: strongly prefer filling bins as fully as possible.
        score -= 20.0 * fit_ratio;
    }

    // Last-chance bin: strongly prefer using the only bin that can fit.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Discourage opening new bins when many open bins have room.
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize unless it's early or open bins are crowded.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowding = mean_residual / bin_capacity as f64;
        score += 12.0 + 20.0 * (1.0 - progress) - 15.0 * crowding;
        if open_bins_count == 0 {
            score -= 100.0; // must open a bin
        }
    } else {
        // Slight preference for bins with residual below mean (consolidate small leftovers).
        if (bin_residual as f64) < mean_residual {
            score -= 3.0;
        }
    }

    // Mild time-horizon modulation: later in the stream, favor tighter packing.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 6.0 * progress * fit_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let post_norm = post / cap;
    let mut score = post;

    // Non-linear polynomial coupling: waste grows quadratically with post_residual,
    // modulated by stream progress (later in stream => waste more costly).
    let coupling = post_norm * post_norm * (0.5 + 2.0 * progress) * cap;
    score += 0.6 * coupling;

    // Penalize bins whose residual deviates from mean residual (fragmentation avoidance).
    let dev = (bin_residual as f64 - mean_residual).abs() / cap;
    score += 4.0 * dev * (1.0 + progress);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 25.0 + 15.0 * progress;
    }

    // Lookahead: reward bins whose post_residual can still fit the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            score -= 8.0 * (1.0 - post / (2.0 * cap)) * (0.5 + progress);
        } else {
            score += 5.0 * (nxt - post) / cap;
        }
    }

    // New-bin candidate: prefer it only when open bins would leave bad dead space
    // or when few bins fit the item late in the stream.
    if bin_residual == bin_capacity {
        let base = 30.0 + 20.0 * progress;
        let bad_fit = if post_norm > 0.6 { 1.0 } else { 0.0 };
        score = base + bad_fit * 25.0 - (fitting_bins_count as f64).max(1.0).recip() * 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual modulo small divisors: prefer residuals
    // that remain "usable" for common item sizes.
    let pr = post_residual;
    if pr > 0 {
        // Dead-space penalty: residuals that few item sizes can use.
        if pr < 10 {
            score += 30.0;
        } else if pr < 20 {
            score += 12.0;
        }
        // Modulo classes: residuals divisible by 10 pair well with 10..80 items.
        let class = pr % 10;
        score -= match class {
            0 => 6.0,
            1 | 9 => 0.0,
            _ => 2.0,
        };
        // Integer-division thresholds: residual >= 40 still fits half the item range.
        if pr >= 40 {
            score -= 5.0;
        } else if pr >= 25 {
            score -= 2.0;
        }
        // Harmonic pairing with lookahead item (k=2): reward exact/near fits.
        if next_item_size > 0 && next_item_size <= pr {
            let gap = pr - next_item_size;
            if gap == 0 {
                score -= 25.0;
            } else if gap <= 10 {
                score -= 10.0;
            } else if gap <= 20 {
                score -= 4.0;
            } else {
                score += 2.0;
            }
        } else if next_item_size > pr {
            // Lookahead cannot use this bin's residual: mild penalty.
            score += 4.0;
        }
    } else {
        // Perfect closure of the bin.
        score -= 40.0;
    }

    // Tight fit reward relative to capacity fraction.
    let fill = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= 20.0 * fill;

    // Last-chance bin before opening a new one: strong incentive to use it.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Many open bins: prefer consolidating into existing bins over new ones.
    if open_bins_count > 4 {
        score -= 3.0 + (open_bins_count.min(50) as f64) * 0.2;
    }

    // New-bin candidate (residual == capacity): penalize unless current bin fit is bad.
    if bin_residual == bin_capacity {
        score += 18.0;
        // Opening fresh is attractive for large items early in the stream.
        let progress = step_index as f64 / total_items.max(1) as f64;
        if item_size >= 50 && progress < 0.5 {
            score -= 12.0;
        }
        if mean_residual < item_size as f64 * 0.5 {
            score -= 8.0;
        }
    }

    // Mean residual coupling: avoid dumping into bins far from the mean when mean is high.
    let dev = (bin_residual as f64 - mean_residual).abs();
    if mean_residual > 40.0 {
        score += dev * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the minimum item
    // (1..10) are essentially wasted; penalize them heavily.
    if post_residual < 10 {
        score += 40.0 * (10.0 - post_residual as f64);
    } else if post_residual < 20 {
        // Small gaps that only tiny items can use: moderate penalty.
        score += 8.0;
    }

    // Reward tight fits (perfect or near-perfect packing).
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Lookahead: if the next item fits into the post-residual, reward;
    // if not, penalize creating a gap the next item cannot use.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 10.0;
        } else {
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // Last-chance bin: strongly prefer using the only bin that fits,
    // avoiding a forced new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading;
    // a new empty bin gets a penalty scaled by open count.
    if bin_residual == bin_capacity {
        score += 20.0 + 3.0 * open_bins_count as f64;
    } else {
        // Prefer filling fuller bins among open ones.
        score -= 0.3 * (bin_capacity as f64 - bin_residual as f64);
    }

    // Mean-residual coupling: if this bin's residual is far below the mean,
    // it is a "lonely" small gap; deprioritize slightly to consolidate.
    score += 0.2 * (mean_residual - bin_residual as f64).abs();

    // Progress pressure: late in the stream, tighten packing further.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly fits next item
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }

    // Near-match: next item fits in the leftover space
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 50.0 + 25.0 * (next_item_size as f64 / post_residual as f64);
    } else if next_item_size > 0 {
        // Dead space relative to next item: penalize proportionally
        let waste = (next_item_size as f64 - post_residual as f64).abs();
        score += 10.0 * waste / bin_capacity as f64;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // Relative to mean residual: prefer bins tighter than average
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Prefer filling bins with small residuals (tight fit)
    score += 0.3 * (bin_residual as f64 - item_size as f64);

    // New-bin candidate: only attractive when the item is large relative to
    // typical residuals or no good fit exists among open bins
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let open_penalty = 40.0 + 30.0 * (open_bins_count as f64).ln();
        let waste_ratio = post_residual as f64 / bin_capacity as f64;
        score = open_penalty + 100.0 * waste_ratio - 60.0 * progress;
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 20.0;
        }
        if fitting_bins_count <= 1 {
            score -= 80.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual < 10 {
        score -= 300.0; // dead space smaller than smallest possible item is fine
    } else {
        // Penalize residuals that are hard to fill by future items (10..100 range).
        let fragility = (post_residual as f64 / bin_capacity as f64).powi(2);
        score += 150.0 * fragility;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 500.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 120.0;
        } else {
            score += 60.0;
        }
        // Extra reward if post-residual matches next item closely (leaves small waste).
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 80.0 * (1.0 - slack / bin_capacity as f64);
        }
    }

    // New-bin candidate handling: empty bin should only win when fits are poor.
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin.
        score += 250.0;
        // But if no existing bin fits well, opening is fine: reward proportional to
        // how bad the alternatives' post-residuals would be (approx via mean_residual).
        if fitting_bins_count == 0 {
            score -= 400.0;
        }
        // Late in the stream, prefer consolidating into existing bins less strongly.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 100.0 * progress;
        // If mean residual across open bins is low, opening a new bin is more attractive.
        if mean_residual < item_size as f64 {
            score -= 150.0;
        }
    } else {
        // Existing bin: prefer bins with residual close to item (tight packing).
        let tightness = 1.0 - ((bin_residual - item_size) as f64 / bin_capacity as f64);
        score -= 100.0 * tightness * tightness;
        // Slight penalty when many bins are open, to encourage consolidation.
        score += (open_bins_count as f64).sqrt() * 5.0;
    }

    // Prefer filling bins with larger residuals first (keep tight bins for tight items).
    score -= 0.1 * bin_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let mut score = pr as f64;
    score += 20.0 * x * x * (1.0 - progress);
    score -= 15.0 * x * x * progress;
    score += 10.0 * (1.0 - progress) * (1.0 - progress) * x;

    // Penalize dead space when no lookahead fits
    if next_item_size > 0 && (next_item_size as f64) > pr {
        score += 8.0 * x * (1.0 + progress);
    } else if next_item_size > 0 {
        score -= 6.0 * (1.0 - ((next_item_size as f64 - pr).abs() / cap));
    }

    // Reward last-chance bins
    if fitting_bins_count == 1 {
        score -= 12.0 * (1.0 - x);
    }

    // Mild penalty for opening new bins late in the stream
    if bin_residual == bin_capacity {
        score += 5.0 + 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: items of size 1..=100; dead space in
    // low harmonic classes is more likely reusable by future items.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Fractional capacity classes via integer division thresholds
    let post_class = post_residual / 10; // 0..=10 harmonic class
    let next_class = next_item_size / 10;

    // Reward if post_residual class exactly matches next item's class (perfect future fit)
    if next_item_size > 0 && post_class == next_class && post_class > 0 {
        score -= 8.0;
    }
    // Reward if next item fits exactly into post_residual
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 4.0 + (post_residual - next_item_size) as f64 * 0.05;
    } else if next_item_size > 0 {
        // penalize dead space that next item cannot use, weighted by how dead it is
        score += (next_item_size - post_residual) as f64 * 0.15;
    }

    // Modulo arithmetic: post_residual divisible by small harmonics is more flexible
    if post_residual > 0 {
        if post_residual % 10 == 0 { score -= 3.0; }
        else if post_residual % 5 == 0 { score -= 1.5; }
        else { score += 1.0; } // awkward residue class
    }

    // Very small post_residual = near-perfect packing; strong reward
    if post_residual < 10 {
        score -= 6.0;
    } else if post_residual < 25 {
        score -= 2.0;
    }

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are tight
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let avg_open = mean_residual / (open_bins_count.max(1) as f64);
        // open new bin if existing residuals are mostly too small for item + lookahead
        let tightness = 1.0 - (avg_open / cap);
        score = cap - (item_size as f64) * (0.5 + 0.5 * progress) + 20.0 * tightness;
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 6.0; // new bin can host item + lookahead pair
        }
    }

    // Prefer bins whose residual is close to item (tight fit)
    let tightness = 1.0 - ((bin_residual - item_size) as f64 / cap);
    score -= 5.0 * tightness;

    // Mild preference for consolidating into fewer bins
    score += 0.3 * open_bins_count as f64 * (post / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for any
    // future item (min size 1..100, but typical small items >= 10) are waste.
    // Penalize small non-zero post_residuals harshly; reward zero residual.
    if post_residual == 0 {
        score -= 60.0; // perfect fit bonus
    } else if post_residual < 10 {
        score += 45.0; // unusable tiny gap -> dead space
    } else if post_residual < 25 {
        score += 18.0; // marginal gap, hard to reuse
    } else if post_residual >= 50 {
        score -= 10.0; // large residual stays flexible
    }

    // Lookahead: if the next item fits the post-residual exactly-ish, reward;
    // if post-residual is just barely too small for the next item, penalize.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            let over = (next_item_size - post_residual) as f64;
            score += 8.0 * (1.0 - over / bin_capacity as f64);
        }
    }

    // Last-chance pressure: if this is the only fitting bin, strongly favor it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: penalize opening new bins when many are already open.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let new_bin_penalty = 20.0 + 25.0 * progress + 2.0 * open_bins_count as f64;
    if bin_residual == bin_capacity {
        score += new_bin_penalty;
        // A new bin is acceptable if this item is large and fits poorly elsewhere.
        if item_size >= 70 && post_residual <= 30 && post_residual > 0 {
            score -= 35.0;
        }
        if post_residual == 0 {
            score -= 60.0; // exact fit in fresh bin (item == capacity case)
        }
    } else {
        // Reward using existing bins relative to mean residual tightness.
        score -= (mean_residual - post_residual as f64).max(0.0) * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) nonlinearly.
    score -= (bin_capacity as f64 - post_residual as f64).powi(2) / (bin_capacity as f64 * bin_capacity as f64) * 40.0;

    // Penalize dead space that no plausible item can use: residual too small.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Lookahead: if next item fits into post_residual, reward this placement.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0 + 0.2 * next_item_size as f64;
        } else {
            score += 6.0;
        }
        // Chain fit: item + next exactly fill bin.
        if post_residual == next_item_size {
            score -= 30.0;
        }
    }

    // Global state coupling: many open bins with high mean residual -> prefer consolidation
    // into bins below mean residual (tighter bins).
    let diff = mean_residual - bin_residual as f64;
    score += 0.15 * diff;

    // When many bins are open, discourage opening new ones.
    if bin_residual == bin_capacity {
        score += 10.0 + 2.0 * open_bins_count as f64;
    }

    // Time horizon: late in the stream, be more conservative (favor tight fits even more).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (bin_capacity as f64 - post_residual as f64) * 0.3;

    // Mild preference for fuller bins overall.
    score -= 0.1 * (bin_residual - post_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;

    // Base: penalize leftover space, but with non-linear decay so tiny
    // residuals are heavily favored (tight fits) and large residuals saturate.
    let mut score = 30.0 * (1.0 - (-norm_post * 3.0).exp()) + 8.0 * norm_post * norm_post;

    // Polynomial coupling between post_residual and stream progress:
    // early on, waste is cheap (many items to come fill bins); late, waste is costly.
    let progress_poly = progress * progress * (3.0 - 2.0 * progress); // smoothstep
    score -= 12.0 * progress_poly * (1.0 - norm_post);

    // Lookahead: if the next item fits exactly into post_residual, reward strongly.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= post {
            let tight = 1.0 - (post - nx) / cap;
            score -= 10.0 * tight * tight;
        } else {
            // Next item won't fit here: mild penalty scaled by overflow gap.
            let gap = (nx - post) / cap;
            score += 5.0 * gap * gap;
        }
    }

    // Last-chance bin: strongly reward using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - norm_post);
    }

    // Penalize fragmentation relative to mean residual of open bins:
    // a bin far below the mean creates an awkward outlier.
    let dev = (mean_residual - post) / cap;
    score += 3.0 * dev * dev;

    // Crowding: with many open bins, prefer consolidating into tight fits.
    let crowd = (open_bins_count as f64).ln().max(0.0);
    score += 1.5 * crowd * norm_post;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // New-bin candidate: make it moderately attractive only when no open bin
    // is a good fit (post_residual near capacity) and stream is early/mid.
    if bin_residual == bin_capacity {
        score = 20.0 + 10.0 * (1.0 - progress_poly) - 8.0 * (fitting_bins_count as f64).recip();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strongly reward closing the bin exactly.
    if post_residual == 0 {
        score -= 1000.0;
        return score;
    }

    // Dead-space penalty: small nonzero residuals are hard to reuse.
    // Harmonic classes: residuals in (0,10] are nearly useless; penalize heavily.
    let pr = post_residual;
    if pr <= 10 {
        score += 60.0;
    } else if pr <= 20 {
        score += 25.0;
    } else if pr <= 40 {
        score += 8.0;
    }

    // Lookahead harmony: if next item exactly matches post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 120.0;
        } else if next_item_size < pr {
            // Next item fits here too: reward proportional to leftover class.
            let gap = pr - next_item_size;
            if gap <= 10 {
                score -= 40.0;
            } else if gap <= 20 {
                score -= 20.0;
            } else {
                score -= 5.0;
            }
        } else {
            // Next item cannot use this residual: mild penalty scaled by waste.
            score += (next_item_size - pr).min(50) as f64 * 0.4;
        }
    }

    // Modulo class of post_residual relative to capacity quarters:
    // residuals near C/2 are versatile (can host mid-size items).
    let half = bin_capacity / 2;
    let dist_half = (pr as i32 - half as i32).abs() as f64;
    score -= (50.0 - dist_half.min(50.0)) * 0.3;

    // Last-chance bonus: if this is the only bin that fits, prefer using it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0 + item_size as f64 * 0.2;
    }

    // New-bin candidate: neutral-ish baseline; discourage early when many
    // open bins exist and mean residual is large.
    if bin_residual == bin_capacity {
        score += 15.0;
        score += mean_residual * 0.5;
        score += open_bins_count as f64 * 2.0;
        // Late in stream, opening fresh bins is cheaper.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= progress * 20.0;
    }

    // Tightness reward: bins that are already well-filled are good targets.
    let fill = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= fill * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize unusable small gaps (dead space): residuals too small for typical items
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Reward tight fits (low post_residual) with a non-linear bonus
    score -= (1.0 - post_residual as f64 / bin_capacity as f64) * 25.0;

    // Last-chance bin: strong reward to use it instead of opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 60.0;
    }

    // New-bin candidate: penalize mildly so we prefer existing bins unless fit is bad
    if bin_residual == bin_capacity {
        score += 15.0 + open_bins_count as f64 * -0.5;
    }

    // Pressure from many open bins: prefer filling existing bins
    score += open_bins_count as f64 * 2.0;

    // Lookahead: if next item fits in post_residual, reward this placement
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 5.0;
    }

    // Dead-space penalty scaled by stream progression
    let progress = step_index as f64 / total_items.max(1) as f64;
    if post_residual > 0 && post_residual < item_size.min(50) {
        score += 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base fit quality: reward tight fits (small post_residual)
    score -= (bin_capacity as f64 - post_residual as f64) / bin_capacity as f64 * 10.0;

    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Lookahead reward: next item fits here, chain the packing
            let slack_after_next = post_residual - next_item_size;
            score -= 15.0 + (slack_after_next as f64).min(20.0) * 0.3;
        } else {
            // Next item won't fit in this bin after placement:
            // penalize more if leftover dead space is unusable for typical items
            let dead = post_residual as f64;
            score += dead * 0.4 + 8.0;
        }
    } else {
        // Last item: just prefer tight fit
        score -= 5.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only open a new bin when the item is large
    // and no good fit exists (post_residual of new bin = C - item is huge,
    // so the base score already penalizes it; add mild bias against opening)
    if bin_residual == bin_capacity {
        score += 6.0;
        // If current bin residual barely fits the item, opening new bin is fine
        if post_residual as f64 <= mean_residual {
            score -= 4.0;
        }
    }

    // Compare against mean residual: prefer bins with below-average residual
    // (tighter bins) to consolidate waste
    score += (post_residual as f64 - mean_residual) * 0.25;

    // Stream progression: later in stream, be more aggressive about filling
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 25.0 * tightness * tightness;

    // Penalize creating dead space that nothing typical can use.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0; // tiny unusable sliver
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 {
        score -= 40.0;
    } else if fitting_bins_count > 1 {
        // Mild crowding penalty when many bins compete: prefer best fit among them.
        score += 2.0 * (fitting_bins_count as f64 - 1.0).ln();
    }

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 20.0 * (next_item_size as f64 / bin_capacity as f64);
        } else if bin_residual >= next_item_size && post_residual < next_item_size {
            // placing here destroys ability to fit next item in this bin
            score += 8.0;
        }
        // If next item is huge, avoid wasting a big bin on a small item.
        if next_item_size >= 60 && item_size <= 30 && post_residual > next_item_size {
            score += 5.0;
        }
    }

    // Global state coupling: when mean residual is high, prefer bins far from the mean
    // (reduce variance / consolidate space).
    let dev = bin_residual as f64 - mean_residual;
    score += 0.3 * dev.abs() - 0.15 * dev;

    // Time horizon: early in the stream, be conservative (favor new bins less);
    // late in the stream, consolidate aggressively into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress * tightness;
    score += 8.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate handling: empty bin gets a baseline cost that shrinks
    // as the stream progresses or when no good existing option exists.
    if bin_residual == bin_capacity {
        score += 30.0 - 20.0 * progress;
        if fitting_bins_count == 0 {
            score -= 35.0;
        }
    }

    // Prefer filling bins that are already mostly full (close them out).
    let fill_ratio = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= 12.0 * fill_ratio * fill_ratio * fill_ratio;

    // Mild penalty on too many open bins.
    score += 0.5 * (open_bins_count as f64).ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 - progress) + norm_pr * (0.5 + 0.5 * progress);

    let mut score = pr * (1.0 + 0.35 * poly);

    // Reward tight fits smoothly (small post residual relative to capacity)
    score -= (1.0 - norm_pr) * (1.0 - norm_pr) * 8.0 * (0.5 + progress);

    // Penalize near-mean residuals that waste shared space
    score += 0.05 * (pr - mean_residual).abs();

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 5.0 * (1.0 - norm_pr);
    }

    // Lookahead: favor bins whose leftover can host the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            score -= 3.0 * (nx / cap);
        } else {
            score += 2.0 * (nx / cap) * norm_pr;
        }
    }

    // New-bin candidate: keep it neutral-to-slightly-poor unless residuals are high
    if bin_residual == bin_capacity {
        score += 2.0 + 4.0 * (mean_residual / cap);
    }

    // Mild penalty for bin proliferation
    score += 0.02 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residuals in "usable" classes
    // (multiples of 10 and small residuals that pair with common item sizes).
    let pr = post_residual;
    if pr == 0 {
        score -= 25.0; // perfect fit
    } else if pr % 10 == 0 {
        score -= 8.0;  // round residual, easy to fill later
    } else if pr < 10 {
        score += 15.0; // dead space below minimum item size
    } else {
        // penalize awkward residuals by distance to nearest multiple of 10
        let d = (pr % 10).min(10 - pr % 10) as f64;
        score += 1.5 * d;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 20.0;
        } else if next_item_size <= pr {
            score -= 4.0 * (pr - next_item_size) as f64 / cap;
        } else {
            // next item cannot fit here: mild penalty scaled by overflow
            score += 2.0 * (next_item_size - pr) as f64 / cap;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // Many open bins: discourage spreading; prefer tight packing of existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.02 * open_bins_count as f64 * (0.5 + progress);

    // Prefer bins tighter than average residual (compactness reward).
    score += 0.3 * (mean_residual - bin_residual as f64).max(-20.0).min(20.0);

    // New-bin candidate: only attractive when this bin is a genuinely bad host
    // (large dead space or next item mismatch) — otherwise penalize opening bins.
    if bin_residual == bin_capacity {
        let badness = if post_residual < 10 { 1.0 } else { 0.0 }
            + if next_item_size > 0 && next_item_size > post_residual { 1.0 } else { 0.0 };
        score += 18.0 - 10.0 * badness;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // dead space smaller than the minimum item size is wasted forever
    }
    if post_residual == 0 {
        score -= 25.0; // perfect fit reward
    }

    // Non-linear coupling: penalize moderate leftovers less if the next item could use them.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0; // lookahead item can fill the gap
        } else if post_residual < next_item_size {
            score += 0.15 * (next_item_size - post_residual) as f64;
        }
    }

    // Open-bins pressure: discourage spreading across many bins when residuals are already tight.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = 0.35 * open_bins_count as f64 * (1.0 + progress);
    score += pressure;

    // Penalize bins whose residual deviates far above the mean (fragmentation signal).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it over a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when the item is huge relative to capacity
    // or no open bin is a good fit; otherwise keep it slightly penalized.
    if bin_residual == bin_capacity {
        let big_item = (item_size as f64 / bin_capacity as f64) > 0.7;
        if big_item && (fitting_bins_count == 0 || post_residual < 15) {
            score -= 30.0;
        } else {
            score += 20.0;
        }
    }

    // Mild preference for filling tighter bins overall.
    score -= 0.1 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fit (small post_residual), with superlinear penalty on dead space.
    let frac = post_residual as f64 / bin_capacity as f64;
    score += 30.0 * frac * frac;

    // 2-step lookahead: reward bins whose post_residual matches the next item size.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        let match_bonus = 40.0 * (1.0 - diff / bin_capacity as f64).powi(3);
        score -= match_bonus;
        // Perfect chain: next item fills bin exactly.
        if post_residual == next_item_size {
            score -= 25.0;
        }
        // Avoid leaving residual that is too small for any plausible next item (dead space).
        if post_residual < next_item_size && post_residual < 10 {
            score += 20.0;
        }
    } else {
        // Last item: just minimize waste.
        score += 5.0 * frac;
    }

    // Contextual coupling with mean residual: prefer bins that keep the fleet balanced
    // when this bin is below-average residual (i.e., already tight).
    if (bin_residual as f64) < mean_residual {
        score -= 8.0;
    } else {
        score += 4.0 * (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: penalize slightly so it only wins when fits are terrible,
    // but allow opening early in the stream or when many bins are open and fragmented.
    if bin_residual == bin_capacity {
        let stream_frac = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 - 10.0 * stream_frac + 0.5 * open_bins_count as f64;
        // If the next item also fits in a fresh bin, opening is more attractive.
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 6.0;
        }
    }

    // Mild pressure to fill bins more fully as the stream progresses.
    score -= 5.0 * (step_index as f64 / total_items.max(1) as f64) * (1.0 - frac);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor small post-residuals (nonlinear).
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * tightness * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual < 10 {
        score -= 12.0;
    }

    // Penalize dead space that no plausible future item can use:
    // items are >= 1, but small residuals (< typical min size) are hard to fill.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Lookahead: if next item fits exactly in the post-residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            score -= 8.0 * (next_item_size as f64 / post_residual.max(1) as f64);
        } else {
            // Next item won't fit here; penalize leaving a mid-size gap that
            // neither the next item nor small items can exploit well.
            score += 5.0;
        }
    }

    // Last-chance logic: if this is the only bin that fits, prefer using it
    // over opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 18.0;
        if post_residual < 20 {
            score -= 10.0;
        }
    }

    // New-bin candidate handling: opening a new bin is attractive when the
    // item is large relative to capacity or open bins are mostly full.
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        // Base cost of opening a bin, amortized by stream progress.
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut new_bin_score = 35.0 - 25.0 * fill_ratio - 10.0 * progress;
        // If existing bins fit poorly (high mean residual wasted), new bin better.
        new_bin_score -= (mean_residual / bin_capacity as f64 - tightness) * 5.0;
        // If many bins already open and none fit well, avoid bin explosion.
        if fitting_bins_count == 0 {
            new_bin_score -= 10.0;
        }
        score = new_bin_score;
    }

    // Mild penalty for spreading across many open bins when residuals are large.
    score += 0.05 * open_bins_count as f64 * (mean_residual / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: quadratic penalty on post residual (dead space)
    let mut score = pr * (1.0 + 2.0 * norm_pr * (1.0 - progress));

    // Non-linear coupling: dead space hurts more as stream progresses
    score += norm_pr * norm_pr * cap * (0.5 + progress);

    // Interaction with mean residual: prefer bins deviating from mean to keep diversity
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 20.0 * dev * dev * (0.3 + 0.7 * progress);

    // Last-chance bonus: strongly reward using the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0 + 80.0 * progress;
    }

    // New-bin candidate: penalize opening a new bin, more so early and when other bins fit
    if bin_residual == bin_capacity {
        let openness = (open_bins_count as f64).ln() + 1.0;
        score += 25.0 + 40.0 * (1.0 - progress) + 8.0 * openness;
        if fitting_bins_count > 0 {
            score += 30.0;
        }
        // If next item is small, a fresh bin is more attractive
        if next_item_size > 0 && (next_item_size as f64) <= pr {
            score -= 15.0;
        }
    }

    // Lookahead: reward leaving residual that can host the next item
    if next_item_size > 0 {
        let gap = pr - next_item_size as f64;
        if gap >= 0.0 {
            score -= 12.0 * (1.0 - gap / cap) * (0.5 + progress);
        } else {
            score += 6.0 * (-gap / cap);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
