    // New-bin candidate (empty bin): only attractive when current bin would leave
    // a large awkward gap or no open bin fits well.
    if bin_residual == bin_capacity {
        let gap_penalty = if post_residual > 0 && post_residual <= 15 { 120.0 } else { 0.0 };
        score += 35.0 + gap_penalty - (open_bins_count as f64).min(10.0) * 2.0;
        if next_item_size > 0 && next_item_size > post_residual {
            score -= 45.0; // opening fresh bin helps the lookahead
        }
    }

    // Mild preference for filling fuller bins (mean residual contrast).
    score -= (mean_residual - r) * 0.25;

    // Late-stream consolidation: prefer tight fits as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= (100.0 - r) * progress * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 {
        let min_useful = 10u32.min(bin_capacity);
        if post_residual < min_useful {
            // Gap too small for any item (items >= 1, but tiny gaps waste capacity)
            score += 60.0 * (min_useful - post_residual) as f64;
        }
        // Penalize gaps that cannot fit the known next item (dead space for lookahead)
        if next_item_size > 0 && post_residual < next_item_size {
            score += 25.0 + 0.5 * (next_item_size - post_residual) as f64;
        }
    } else {
        // Perfect fit: strong reward
        score -= 80.0;
    }

    // Reward tight fits (post_residual relative to item size)
    score -= 0.8 * (item_size as f64 / bin_capacity as f64) * 100.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Open-bins pressure: with many open bins, discourage opening new ones;
    // when few bins are open, a fresh empty bin is more acceptable.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let pressure = open_bins_count as f64 / (1.0 + progress * 4.0);
        score += 30.0 + 8.0 * pressure;
    } else {
        score -= 5.0;
    }

    // Mild preference for bins tighter than the average residual (best-fit flavor)
    score += 0.15 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual already does this).

    // Aggressive 2-step lookahead: reward when next item exactly fills post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            // Perfect chain: this bin will be exactly filled by the next item.
            score -= 40.0;
        } else if next_item_size < post_residual {
            // Next item fits too: penalize proportional leftover after both items.
            let two_step_leftover = post_residual - next_item_size;
            score += two_step_leftover as f64 * 0.6;
            if two_step_leftover <= 10 {
                score -= 12.0; // near-perfect two-item fill
            }
        } else {
            // Next item cannot fit here; the post_residual becomes potential dead space.
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.35;
        }
    } else {
        // Last item: pure tightness matters most.
        score += (bin_residual - item_size) as f64 * 0.1;
    }

    // Relative-to-mean coupling: bins with residual far above mean waste space.
    let dev = bin_residual as f64 - mean_residual;
    score += dev * 0.15;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // (avoids opening a new bin for a mediocre fit).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a new bin when decent existing fits exist.
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive if the item is large relative to capacity
        // and few bins fit it (keeping large items isolated preserves flexibility).
        let large_item = item_size as f64 / bin_capacity as f64;
        score += 18.0 - 30.0 * large_item;
        if fitting_bins_count <= 2 {
            score -= 10.0;
        }
        // Late in the stream, consolidation matters more; discourage new bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 * progress;
    }

    // Small penalty for very low post_residual that is not a perfect fill
    // (tiny unusable slivers), unless chained with next item.
    if post_residual > 0 && post_residual < 5 && next_item_size != post_residual {
        score += 8.0;
    }

    // Mild pressure to reduce open bin count when many are open.
    score += (open_bins_count as f64).ln().max(0.0) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post-residual) more aggressively than linear.
    let tightness = (post_residual as f64) / (bin_capacity as f64);
    score -= (1.0 - tightness) * (1.0 - tightness) * 12.0;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual < 10 {
        score -= 15.0;
    }

    // Penalize dead space that is too small for the smallest plausible item.
    if post_residual > 0 && post_residual < 15 {
        score += 8.0;
    }

    // Lookahead coupling: if the next item fits the post-residual, reward heavily.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0;
        // Extra reward when next item nearly fills the remaining space.
        let gap = post_residual - next_item_size;
        if gap < 10 {
            score -= 10.0;
        }
    } else if next_item_size > 0 && post_residual > 0 {
        // Next item won't fit here: penalize leaving large stranded residuals.
        score += (post_residual as f64) * 0.15;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive when existing fits are poor
    // or the item is large relative to typical residuals.
    if bin_residual == bin_capacity {
        let avg_fit = if fitting_bins_count > 0 { 1.0 } else { 0.0 };
        let pressure = (item_size as f64) / (bin_capacity as f64);
        // Base penalty so open bins are preferred unless heavily rewarded otherwise.
        score += 18.0;
        // Large items or many open bins with big residuals favor a fresh bin.
        score -= pressure * 10.0 + avg_fit * 0.0;
        if open_bins_count > 0 && (mean_residual as f64) > (item_size as f64) * 1.5 {
            // Open bins have plenty of room; discourage new bin.
            score += 12.0;
        }
        if open_bins_count == 0 {
            score -= 100.0; // must open a bin
        }
        // Early in stream, allow opening bins more freely to build diversity.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= (1.0 - progress) * 6.0;
    }

    // Mild preference for fuller bins among open bins (best-fit bias).
    score -= (bin_residual as f64).ln().max(0.0) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let post_norm = post / cap;

    // Base: post residual, scaled by smooth progress coupling
    let mut score = post * (1.0 + 0.5 * progress);

    // Non-linear penalty for small dead space (unusable residuals)
    let dead = (1.0 - post_norm).powi(6);
    score += 30.0 * dead * (1.0 - progress);

    // Reward tight fits (low post residual) quadratically
    score -= 20.0 * (1.0 - post_norm) * (1.0 - post_norm);

    // Last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 + progress);
    }

    // Lookahead: reward if next item fits the post residual
    if next_item_size > 0 && (next_item_size as f64) <= post {
        score -= 8.0 * (next_item_size as f64 / cap);
    } else if next_item_size > 0 {
        score += 4.0 * (1.0 - post_norm);
    }

    // Prefer bins below mean residual (larger residuals) mildly
    score += 0.3 * (mean_residual - bin_residual as f64);

    // Mild penalty for proliferation of open bins
    score += 0.1 * open_bins_count as f64;

    // New-bin candidate: penalize slightly unless current residuals are poor
    if bin_residual == bin_capacity {
        let poor = (mean_residual / cap - 0.5).max(0.0);
        score += 15.0 - 20.0 * poor;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residuals divisible by small powers of 2
    // and by 5 are more reusable in typical integer size streams.
    let pr = post_residual;
    let harmonic_bonus = if pr == 0 {
        -8.0 // perfect fit is ideal
    } else if pr % 50 == 0 {
        -4.0
    } else if pr % 25 == 0 {
        -3.0
    } else if pr % 10 == 0 {
        -2.0
    } else if pr % 5 == 0 {
        -1.0
    } else {
        0.0
    };
    score += harmonic_bonus;

    // Penalize small dead space (unusable slivers), scaled by harmonic class
    if pr > 0 && pr < 10 {
        score += 6.0;
    } else if pr < 20 {
        score += 2.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 5.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, reward heavily
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 7.0;
        } else if next_item_size <= pr {
            let nr_class = if pr % next_item_size == 0 { -3.0 } else { -1.0 };
            score += nr_class - (pr - next_item_size) as f64 * 0.05;
        } else {
            // next item won't fit here; mild penalty for wasting a good bin
            score += 1.0;
        }
    }

    // Integer-division threshold on residual class: mid-range residuals (25..60)
    // are the sweet spot for future packing
    let q = pr / 20; // class 0..5
    score += match q {
        0 => 3.0,
        1 => 0.0,
        2 => -1.0,
        3 => -1.5,
        _ => 0.5,
    };

    // New-bin candidate handling: only prefer a fresh bin when current open bins
    // are crowded and this would be a poor fit
    if bin_residual == bin_capacity {
        let pressure = mean_residual / bin_capacity as f64;
        // fresh bin baseline: slightly worse than a decent fit, better than a bad one
        score = 45.0 - pressure * 20.0;
        if open_bins_count == 0 {
            score = -10.0; // must open first bin
        }
    }

    // Progress-based mild adaptation: late in stream, consolidate more aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (post_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: small post_residual gaps (<10) are unusable dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 - 2.0 * post_residual as f64;
    }
    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward bins whose residual can still fit the lookahead item after placement.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0 + 0.05 * next_item_size as f64;
        } else {
            // Creating a gap that cannot fit the next item: penalize proportionally.
            score += 0.10 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Open-bin pressure: when many bins are open, discourage opening new ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.5 + progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when open bins already exist and fit.
        score += 35.0 + pressure;
        if fitting_bins_count > 0 {
            score += 20.0;
        }
    } else {
        // Mildly reward filling existing bins, scaled by how full they are.
        score -= 0.05 * (bin_capacity - bin_residual) as f64;
        // Prefer bins below mean residual (more filled than average) slightly.
        score += 0.03 * (bin_residual as f64 - mean_residual);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 2-step lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            // Perfect chain: post-residual exactly matches next item.
            score -= 30.0;
        } else if post_residual >= next_item_size {
            // Next item still fits; reward tightness of the chain fit.
            let slack = (post_residual - next_item_size) as f64;
            score -= 18.0 - 0.25 * slack;
        } else {
            // Next item won't fit here; penalize wasted chain opportunity.
            let gap = (next_item_size - post_residual) as f64;
            score += 0.35 * gap;
        }
    } else {
        // Last item: prefer minimal post-residual (already the base), tiny bonus.
        score -= 2.0;
    }

    // Compare against mean residual: prefer bins that are relatively full.
    let diff = mean_residual - post_residual as f64;
    score += 0.30 * diff;

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Penalize very small dead space (< 10, unusable for min item size).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Slight preference for consolidating into fewer bins as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual < bin_capacity {
        score -= 5.0 * progress;
    } else {
        // New-bin candidate: mild penalty so it's chosen only when fits are poor.
        score += 8.0 + 4.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let is_new_bin = bin_residual == bin_capacity;
    let progress = step_index as f64 / (total_items.max(1) as f64);

    // Reward tight fits (small dead space) non-linearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Lookahead: if the next item fits exactly in the post residual, strongly reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack_after_next = post_residual - next_item_size;
        score -= 8.0 * (1.0 - slack_after_next as f64 / bin_capacity as f64);
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Post residual becomes dead space for the lookahead item; penalize proportionally.
        score += 0.15 * post_residual as f64;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 25.0;
    }

    // Penalize new-bin opening, more when many bins could fit the item.
    if is_new_bin {
        score += 20.0 + 3.0 * fitting_bins_count as f64;
        // Early in the stream, opening bins is cheaper (flexibility for the future).
        score -= 15.0 * (1.0 - progress);
    }

    // Prefer bins with residual below the mean (consolidate fragmentation).
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // Mild preference for spreading across bins when many are open late in stream.
    if open_bins_count > 4 {
        score += 0.05 * (post_residual as f64 - mean_residual).abs();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalize stream progress and key quantities
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let res = bin_residual as f64;
    let item = item_size as f64;

    // Non-linear decay of post_residual value as stream progresses:
    // tight fits matter more early, dead space is more forgivable late.
    let decay = (1.0 - progress).powi(2);
    score -= 8.0 * decay * (1.0 - post / cap).powi(3) * cap;

    // Smooth quadratic coupling: penalize post_residual near awkward
    // half-capacity zones (unusable dead space), scaled by item density.
    let x = post / cap;
    score += 6.0 * x * (1.0 - x) * item;

    // Reward filling a bin almost completely (post_residual small) with
    // a smooth exponential bonus.
    score -= 10.0 * (-3.0 * post / cap).exp();

    // Last-chance bonus: strongly prefer using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // Lookahead: if next item fits exactly in the post-residual, reward;
    // smooth coupling rather than hard threshold.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (post - nxt) / cap;
        if gap >= 0.0 {
            score -= 5.0 * (-4.0 * gap.abs()).exp();
        } else {
            score += 3.0 * gap.abs();
        }
    }

    // Mild preference to consolidate into fewer bins as stream progresses.
    score += progress * open_bins_count as f64 * 0.3;
    score += 0.5 * (res - mean_residual);

    // New-bin candidate: penalize opening a new bin unless current fit is poor.
    if bin_residual == bin_capacity {
        score += 12.0 * (1.0 - item / cap) + 10.0 * decay;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify dead space into residue buckets.
    let post = post_residual;
    let class: f64 = match post {
        0 => -30.0,                       // perfect fit — heavily reward
        1..=5 => -12.0,                   // near-perfect, still reusable for tiny items
        6..=15 => 4.0,                    // awkward dead zone
        16..=25 => -3.0,                  // medium-small usable
        26..=40 => -6.0,                  // comfortable zone
        41..=60 => 0.0,
        _ => -2.0,                        // large residual, plenty of room anyway
    };
    score += class;

    // Integer-division thresholds: how many "typical" items (>=10) fit in post_residual.
    let slots = post / 10;
    score -= (slots as f64) * 2.5;

    // Modulo arithmetic on post_residual: residuals divisible by common item classes
    // (10, 20, 25, 50) are likely to be exactly filled later.
    if post > 0 {
        if post % 10 == 0 { score -= 5.0; }
        if post % 25 == 0 { score -= 4.0; }
        if post % 20 == 0 { score -= 3.0; }
        if post % 50 == 0 { score -= 6.0; }
    }

    // Lookahead coupling: does next_item_size fit exactly into post_residual?
    if next_item_size > 0 {
        if next_item_size == post {
            score -= 25.0;                // perfect chained fit
        } else if next_item_size < post {
            score -= (post - next_item_size) as f64 * 0.15;
        } else {
            // next item cannot use this residual — penalize proportionally
            score += (next_item_size - post).min(30) as f64 * 0.3;
        }
    }

    // Last-chance bin before opening a new one: strong reward to avoid waste.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate: only attractive when no open bin fits well,
    // or stream is early and we want parallel capacity.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let poor_alternatives = (fitting_bins_count == 0) as f64;
        let early = (1.0 - progress) * 6.0;
        score = 100.0 - poor_alternatives * 40.0 - early
            - if next_item_size > 0 && next_item_size <= bin_capacity { 3.0 } else { 0.0 };
        // mean residual high => open bins have room, discourage new bin
        score += mean_residual * 0.2;
        score += open_bins_count as f64 * 1.5;
    }

    // Slight preference for tighter bins overall (waste minimization).
    score += (bin_residual as f64 - post as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small to fit typical future items are waste.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Reward tight fits.
    score -= (item_size as f64 / bin_capacity as f64) * 15.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Pressure from many open bins: prefer filling existing bins.
    score += open_bins_count as f64 * 2.0;

    // If the next item fits into the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    }
    // If next item leaves a near-perfect match, extra reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 20.0;
    }

    // New-bin candidate: keep it moderately attractive only when existing bins are few
    // or mean residual is low (nothing worth packing into).
    if bin_residual == bin_capacity {
        if open_bins_count == 0 {
            score -= 100.0;
        } else if (mean_residual < item_size as f64) && fitting_bins_count == 0 {
            score -= 50.0;
        } else {
            score += 30.0 + open_bins_count as f64 * 3.0;
        }
    }

    // Progress-based mild adjustment: later in stream, consolidate more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next_item_size
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if post_residual >= next_item_size {
            // next item can follow: reward tightness of match
            score -= 60.0 * (1.0 - diff / bin_capacity as f64);
            if diff == 0.0 {
                score -= 250.0; // exact 2-step chain
            }
        } else {
            // next item cannot follow: penalize dead space relative to next item
            score += 0.5 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // Relative-to-mean-residual coupling: prefer bins below mean residual (tighter packing)
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // Last-chance bin bonus: avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // Penalize wasting a fresh bin when the item fits poorly elsewhere
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // new bin baseline: keep it competitive only when fit is bad or few options
        score += 120.0;
        if fitting_bins_count == 0 || (next_item_size > 0 && item_size >= next_item_size && post_residual < next_item_size) {
            score -= 200.0;
        }
    }

    // Slight preference to consolidate into fewer bins early in the stream
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: quadratic penalty for wasted space.
    let waste = post_residual as f64;
    score += 0.35 * (waste * waste) / bin_capacity as f64;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless the item
    // fits poorly everywhere or the lookahead suggests big items are coming.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let lookahead_pressure = if next_item_size > 0 {
            (next_item_size as f64 / bin_capacity as f64).powi(2)
        } else {
            0.0
        };
        // Prefer existing bins by default.
        score += 25.0;
        // But if the item barely fits and next item is large, opening a fresh
        // bin preserves flexibility: reduce the penalty.
        let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
        score -= 30.0 * tightness * (0.5 + lookahead_pressure);
        // Late in the stream, consolidate: discourage new bins.
        score += 20.0 * progress;
        // Many open bins with low mean residual -> avoid fragmentation.
        if mean_residual < item_size as f64 {
            score += 15.0;
        }
    }

    // Lookahead synergy: if the next item fits exactly into post_residual,
    // reward this placement strongly (perfect chaining).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 45.0;
    } else if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size < 10 {
        score -= 20.0;
    }

    // Penalize leaving residuals that no plausible item (>=1) can use well:
    // dead space smaller than the smallest item is worthless.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Global load balancing: prefer bins whose residual deviates favorably
    // from the mean residual when open bin count is high (avoid many
    // half-empty bins).
    if open_bins_count > 1 {
        let dev = bin_residual as f64 - mean_residual;
        score += 0.05 * dev * (open_bins_count as f64).ln();
    }

    // Prefer placing into bins with less residual among comparable fits
    // (best-fit reinforcement), scaled mildly by stream progress.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post-residual, with non-linear polynomial shaping.
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // Smooth coupling of post-residual with stream progress: late in the stream,
    // tight fits matter more (penalize residual growth super-linearly).
    score += 40.0 * norm_pr * norm_pr * (0.5 + progress);

    // Reward filling a bin exactly / near-exactly with a smooth bump.
    score -= 30.0 * (-((pr as f64 - 5.0f64).powi(2)) / 50.0).exp();

    // Last-chance bonus: only one bin can fit; strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 60.0;
    }

    // Penalize opening a new bin when decent fits exist, more so early on.
    if bin_residual == bin_capacity {
        score += 25.0 * (1.0 - progress) + 0.5 * open_bins_count as f64;
        // But allow new bin if post-residual would be very tight elsewhere anyway.
        score -= 10.0 * progress;
    }

    // Lookahead: if next item fits into post-residual, reward this placement smoothly.
    if next_item_size > 0 {
        let gap = pr - next_item_size as f64;
        if gap >= 0.0 {
            score -= 20.0 * (-gap / 30.0).exp();
        } else {
            score += 8.0 * (-(-gap) / 40.0).exp();
        }
    }

    // Slight preference for bins with residuals above the mean (balance preservation),
    // smooth quadratic interaction with mean_residual.
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 15.0 * dev * dev - 5.0 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo-10 bucket structure.
    let pr = post_residual;
    let class = pr % 10;
    // Penalize residuals in "awkward" classes (1..9 small remainders are dead space;
    // 0 and 10 are harmonic anchors).
    match class {
        0 => score -= 6.0,
        10 => score -= 3.0,
        1 | 2 | 3 => score += 8.0,
        4 | 5 | 6 => score += 3.0,
        _ => score += 1.0,
    }

    // Integer-division thresholds: can the post residual host the next item?
    if next_item_size > 0 {
        if pr >= next_item_size {
            // Reward leaving room for the lookahead item, scaled by tightness.
            let slack = (pr - next_item_size) as f64;
            score -= 10.0 * (1.0 - slack / cap);
            // Harmonic bonus if post residual is a multiple of half the next item.
            if next_item_size > 0 && pr % next_item_size.max(1) == 0 {
                score -= 4.0;
            }
        } else {
            // Dead space penalty: next item cannot follow into this bin.
            score += 12.0 * (next_item_size as f64 / cap);
        }
    } else {
        // Last item: prefer tightest fit, exact fill is ideal.
        if pr == 0 {
            score -= 20.0;
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: neutral-ish baseline, penalized mildly so we prefer
    // existing bins unless the fit is truly poor; scale with stream progress.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 18.0 - 6.0 * progress;
        // Opening a new bin is more attractive early when many items remain.
        score -= 10.0 * (1.0 - progress) * (item_size as f64 / cap);
    }

    // Coupling with mean residual: prefer bins whose residual deviates favorably
    // (smaller than average => tighter packing).
    score += 0.5 * (mean_residual - bin_residual as f64).max(-cap) / cap * 5.0;

    // Small penalty for leaving very tiny unusable slivers.
    if pr > 0 && pr < 10 {
        score += (10 - pr) as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small to hold even a small item are wasted.
    // Penalize unusable small gaps super-linearly.
    let min_item = 1u32;
    if post_residual > 0 && post_residual < min_item.max(1) * 10 {
        score += 40.0 * ((11.0 - post_residual as f64) / 10.0).powi(3);
    }

    // Reward tight fits (low post_residual relative to item size).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fit_ratio;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 45.0;
    }
    // Penalize if post-residual is a dead gap that next item cannot use but could fit elsewhere.
    if next_item_size > post_residual && post_residual > 0 && post_residual < 15 {
        score += 15.0;
    }

    // Open-bin pressure: discourage spreading across many bins; encourage filling existing ones.
    score += 0.8 * open_bins_count as f64;

    // New-bin candidate handling: opening a new bin should be costly unless it's a last resort.
    if bin_residual == bin_capacity {
        score += 30.0;
        if fitting_bins_count > 0 {
            score += 25.0 * (fitting_bins_count as f64).min(3.0);
        }
        // Early in the stream, opening bins is cheap (need parallel bins anyway).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 35.0 * (1.0 - progress);
    }

    // Last-chance bin: strongly favor using the only bin that fits, avoiding a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Mean residual coupling: prefer bins deviating below the mean residual (tighter bins).
    score += 0.15 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward near-perfect fits (small post_residual)
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    if post == 0.0 {
        score -= 60.0;
    } else if post <= 10.0 {
        score -= 40.0;
    }

    // 2-step lookahead: reward when next item fits the post residual exactly
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt == post {
            score -= 55.0;
        } else if nxt < post {
            let slack = post - nxt;
            if slack <= 10.0 {
                score -= 35.0 - slack * 1.5;
            } else {
                score -= 15.0 / slack;
            }
        } else {
            // next item won't fit here; penalize leaving tight-but-wasted space
            let over = nxt - post;
            score += over.min(30.0) as f64 * 0.8;
        }
    }

    // Relative-to-mean residual coupling: prefer bins tighter than average
    score += (mean_residual - post) * -0.3;

    // Last-chance bin: strong bonus to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize unless current bin fit is poor
    if bin_residual == bin_capacity {
        let poor_fit = post > 40.0 && next_item_size > 0 && (next_item_size as f64) > post;
        if poor_fit {
            score -= 20.0; // opening fresh may be better than wasting a bin
        } else {
            score += 30.0; // default: prefer using an existing bin
        }
    }

    // Mild penalty for dead space scaled by stream progress
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post * (0.05 + 0.15 * progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Base: prefer minimal post residual (tight fit).
    let mut score = post_residual as f64;

    // Penalize placing small items into bins with large residuals (dead-space risk),
    // scaled by how much slack is wasted.
    let waste = (bin_residual as f64 - item_size as f64).max(0.0);
    score += 0.25 * (waste / bin_capacity as f64).powi(2) * bin_capacity as f64;

    // Lookahead: if the next item fits exactly in post_residual, reward strongly;
    // if next item fits but leaves tiny slack, mild reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 12.0;
        } else if next_item_size <= post_residual {
            score -= 6.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // Next item won't fit here: penalize leaving awkward mid-size gaps.
            let gap = post_residual as f64;
            if gap > 0.0 && gap < next_item_size as f64 {
                score += 0.15 * gap.min(next_item_size as f64);
            }
        }
    }

    // Last-chance bonus: this is the only fitting bin, avoid opening a new bin
    // unless the fit is truly terrible.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 8.0 + 6.0 * progress;
    }

    // Early in the stream, favor opening new bins to build a diverse residual pool;
    // later, consolidate to avoid bin proliferation.
    if is_new_bin {
        let pool_pressure = (open_bins_count as f64 / 10.0).min(3.0);
        score += 10.0 - 4.0 * progress + pool_pressure;
        // New bin is attractive if the item is large (fewer future regrets).
        score -= 0.05 * item_size as f64;
    }

    // Prefer bins with residual far below the mean (use up poor bins first),
    // keeping richer bins flexible.
    score += 0.08 * (mean_residual - bin_residual as f64).max(0.0);

    // Slight preference for bins that would be perfectly closed.
    if post_residual == 0 {
        score -= 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // Non-linear polynomial coupling: penalize large post-residuals more as stream progresses
    let norm_pr = pr / cap;
    score += 40.0 * norm_pr * norm_pr * (0.5 + progress);

    // Reward tight fits (small post-residual) with smooth decay
    score -= 25.0 * (-norm_pr * 6.0).exp();

    // Last-chance bonus: strongly favor the only bin that fits
    if fitting_bins_count == 1 {
        score -= 60.0;
    }

    // Prefer bins below mean residual (evening out load) with smooth coupling
    score += 0.15 * (pr - mean_residual);

    // Lookahead: penalize if next item cannot use the post-residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr < nxt {
            score += 8.0 * (1.0 - pr / nxt);
        } else {
            score -= 5.0 * (1.0 - nxt / pr);
        }
    }

    // New-bin candidate: make it slightly less attractive unless residuals are tight
    if bin_residual == bin_capacity {
        score += 12.0 * (1.0 - progress) + 5.0;
    }

    // Mild penalty for accumulating many open bins
    score += 0.5 * open_bins_count as f64 * norm_pr;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify leftover space by modulo classes.
    let class = post_residual % 10; // fine-grained harmonic class (0..9)
    let decade = post_residual / 10; // coarse class (0..9 for C=100)

    // Dead-space penalty: leftover space that no typical item (>=1) can pair with.
    // Penalize small nonzero leftovers harder than clean zeros.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 15.0;
    }

    // Lookahead coupling: reward if next item fits exactly into post_residual
    // (harmonic pairing), penalize if next item barely misses.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            score -= 6.0;
        } else {
            // next item cannot use this leftover: leftover is dead weight
            score += (post_residual as f64) * 0.15;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: make opening a fresh bin mildly attractive only when
    // the current bin's leftover would be very awkward (small odd class).
    if bin_residual == bin_capacity {
        // base score = capacity; adjust so it competes fairly
        score = bin_capacity as f64 - 8.0;
        // prefer new bin early when many bins are open and fragmented
        if mean_residual > 25.0 {
            score += 5.0;
        }
        if next_item_size > 0 && next_item_size > bin_capacity {
            score += 30.0;
        }
    }

    // Prefer filling bins with large decade-class leftovers (less fragmentation).
    score -= (decade as f64) * 1.5;

    // Odd-class penalty: leftovers like 1,3,7,9 mod 10 are hard to fill.
    if class % 2 == 1 && post_residual > 0 {
        score += 3.0;
    }

    // Slight preference for tighter bins as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (mean_residual - post_residual as f64) * 0.05 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

