    if bin_residual == bin_capacity {
        let poor_fit = post_residual as f64 > 0.0 && post_residual < 10;
        let lookahead_bad = next_item_size == 0 || post_residual < next_item_size;
        if !(poor_fit && lookahead_bad) {
            score += 120.0 + 0.3 * post_residual as f64;
        } else {
            score += 20.0;
        }
    }

    // Late-stream tightening: be pickier as stream progresses
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.4 * progress * post_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
