    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 30.0 + (next_item_size as f64 * 0.2);
        } else {
            // penalize wasting space that next item can't use
            score += (post_residual as f64).min(next_item_size as f64) * 0.15;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    } else if fitting_bins_count > 1 {
        // mild penalty when many options, prefer best fit handled by tightness
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // New-bin candidate handling: discourage opening new bins unless current
    // residuals are poor relative to item
    if bin_residual == bin_capacity {
        let mean_fit = mean_residual;
        if fitting_bins_count > 0 && mean_fit >= item_size as f64 {
            score += 60.0; // open bins can handle it; don't open a new one
        } else {
            score -= 20.0; // no good alternative; new bin is fine
        }
    }

    // Time horizon: early in stream, allow more bins for flexibility;
    // late in stream, consolidate aggressively
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - progress) * 5.0 * open_bins_count as f64;
    score -= progress * 10.0;

    // Prefer bins whose residual is above mean (keeps balance)
    let diff = bin_residual as f64 - mean_residual;
    score += diff * 0.1;

    // Slight preference for fuller bins
    score -= (bin_residual as f64 / bin_capacity as f64) * 8.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;

    // Base: post-residual, with smooth polynomial coupling to stream progress.
    let mut score = pr * (1.0 + 0.8 * progress * progress);

    // Reward tight fits: quadratic penalty on wasted fraction of capacity.
    let waste_frac = pr / cap;
    score += 40.0 * waste_frac * waste_frac;

    // Smooth interaction: tight fits matter more late in the stream.
    score -= (1.0 - waste_frac).powi(3) * (6.0 + 10.0 * progress);

    // Penalize bins whose residual deviates from mean (encourage balance), smoothly.
    score += 0.15 * ((bin_residual as f64 - mean_residual) / cap).abs();

    // Last-chance bonus: strongly favor the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // Lookahead: reward leaving space compatible with the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= 4.0 * (1.0 - ((pr - nxt) / cap).abs());
        } else {
            score += 3.0;
        }
    }

    // Mild preference for consolidating into fewer bins.
    score += 0.05 * open_bins_count as f64 * progress;

    // New-bin candidate: only attractive when item fits poorly everywhere.
    if bin_residual == bin_capacity {
        score += 8.0 - 6.0 * (1.0 - waste_frac);
        score -= 4.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: prefer residuals in "usable" classes
    // Class boundaries via integer division thresholds (capacity fractions)
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Dead-space penalty if next item cannot fit in the post residual
    if next_item_size > 0 {
        if next_item_size > post_residual {
            // wasted space relative to lookahead: penalize proportionally
            score += (next_item_size - post_residual) as f64 * 0.8;
        } else {
            // next item fits: strong reward, especially if it nearly fills bin
            let combined = (item_size + next_item_size) as f64;
            score -= 15.0 + 20.0 * (combined / cap);
            // harmonic bonus: post_residual divisible into useful chunk classes
            if post_residual % 10 == 0 {
                score -= 5.0;
            }
            if post_residual % 25 == 0 {
                score -= 5.0;
            }
        }
    }

    // Modulo-arity penalty: residuals in awkward small classes (1..10) are dead space
    let small_class = post_residual < 10;
    let mid_class = (10..=30).contains(&post_residual);
    if small_class {
        score += 40.0;
    } else if mid_class {
        score += 10.0;
    }

    // Integer division threshold on post_residual relative to capacity fractions
    let frac = pr / cap;
    if frac < 0.2 {
        score += 25.0 * (0.2 - frac);
    }

    // Last-chance bin: if only one bin fits, strongly favor using it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 60.0;
    }

    // New-bin candidate: empty bin should only win when no open bin fits well
    if bin_residual == bin_capacity {
        // prefer opening new bin early in stream or when open bins are crowded
        let progress = step_index as f64 / total_items.max(1) as f64;
        let crowding = mean_residual / cap;
        // penalize new bin generally, discount when open bins have low mean residual
        score += 80.0 - 60.0 * (1.0 - crowding) - 20.0 * progress;
        if next_item_size > 0 && next_item_size >= bin_capacity {
            score -= 30.0; // next item needs a fresh bin anyway
        }
    }

    // Mild preference to spread load across many open bins when mean residual is high
    if open_bins_count > 0 && mean_residual > 0.5 * cap {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A gap is "dead" if it cannot fit the smallest plausible item (1..100 range,
    // but treat gaps < 10 as near-dead, and gaps < next_item_size as unusable
    // for the immediate future).
    if post_residual > 0 {
        if post_residual < 10 {
            score += 60.0; // tiny sliver: worst kind of dead space
        } else if next_item_size > 0 && post_residual < next_item_size {
            score += 35.0; // gap too small for the lookahead item
        }
        // Waste fraction weighting: quadratic penalty on unusable remainder
        let waste_frac = post_residual as f64 / bin_capacity as f64;
        if next_item_size > 0 && (post_residual as f64) < next_item_size as f64 {
            score += 40.0 * waste_frac * waste_frac * bin_capacity as f64;
        }
    } else {
        // Perfect fit: strongly reward closing the bin exactly.
        score -= 50.0;
    }

    // Reward tight fits (small post_residual relative to item size)
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio;

    // Last-chance pressure: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Open-bin pressure: many open bins -> prefer consolidating into existing bins,
    // penalize opening new ones.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let bin_pressure = (open_bins_count as f64).ln1p() * 8.0;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportional to open bins and stream progress.
        score += 25.0 + bin_pressure + 20.0 * progress;
        // But if the item is large and mean residual is low, a new bin is fine.
        if item_size as f64 > mean_residual {
            score -= 30.0;
        }
    } else {
        // Existing bin: slight reward when open bin count is high.
        score -= 0.3 * bin_pressure;
    }

    // Lookahead synergy: if the next item fits exactly into post_residual, reward strongly.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    } else if next_item_size > 0 && post_residual > next_item_size {
        // Partial reward for leaving a usable gap for the next item.
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Primary term: prefer tight fits, penalize dead space non-linearly.
    let dead = post_residual as f64;
    score += 0.9 * (dead / bin_capacity as f64).powi(2) * bin_capacity as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual can
    // exactly or nearly host the next item.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            // Exact match is excellent: subtract strongly.
            score -= 25.0 * (1.0 - slack / bin_capacity as f64);
            // Bonus for perfect pairing (post_residual == next_item_size).
            if post_residual == next_item_size {
                score -= 30.0;
            }
        } else {
            // Next item won't fit here: penalize proportionally to the gap.
            let gap = (next_item_size - post_residual) as f64;
            score += 0.35 * gap;
        }
        // Coupling with mean residual: bins far below mean residual are
        // "waste candidates"; filling them is good if next item still fits.
        let dev = mean_residual - post_residual as f64;
        if dev > 0.0 {
            score -= 0.15 * dev;
        } else {
            score += 0.1 * (-dev);
        }
    } else {
        // Last item: pure tight-fit preference.
        score += 0.5 * (dead / bin_capacity as f64) * bin_capacity as f64;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
        if post_residual <= 10 {
            score -= 15.0; // near-perfect fill on a last-chance bin
        }
    }

    // New-bin candidate: make it moderately attractive only when the item
    // is large relative to typical residual space, or stream is early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let item_frac = item_size as f64 / bin_capacity as f64;
        score = bin_capacity as f64 * (1.0 - item_frac);
        // Penalize opening new bins when good existing options exist.
        if fitting_bins_count > 0 {
            score += 18.0 + 8.0 * (1.0 - progress);
        }
        // Attractive if item is huge (little else would fit anyway).
        if item_frac > 0.8 {
            score -= 10.0;
        }
        // Discourage new bins when mean residual is already plentiful.
        if mean_residual > item_size as f64 + 20.0 {
            score += 25.0;
        }
    }

    // Mild preference to consolidate: fewer open bins is better.
    score -= 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progression of the stream (0..1)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Strong penalty for opening a brand-new bin when other bins could fit,
    // scaled by how much usable residual the new bin would waste relative to demand.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let waste_pressure = (bin_capacity as f64 - post_residual as f64) / bin_capacity as f64;
        score += 40.0 + 60.0 * waste_pressure + 30.0 * progress;
        // If no existing bin fits, the new-bin penalty should be lifted.
        if fitting_bins_count == 0 {
            score -= 120.0;
        }
        // Lookahead: opening a fresh bin is attractive if the next item also needs space.
        if next_item_size > 0 && post_residual as f64 >= next_item_size as f64 {
            score -= 15.0;
        }
    } else {
        // Reward tight fits: small post_residual is already favored by the base term.
        // Extra reward when this is the last bin that can take the item (avoid new bin).
        if fitting_bins_count == 1 {
            score -= 25.0 + 20.0 * progress;
        }
        // Penalize leaving dead space that likely cannot host the next item.
        if next_item_size > 0 {
            if (post_residual as f64) < next_item_size as f64 && post_residual > 0 {
                score += 8.0; // small unusable gap for lookahead
            } else if (post_residual as i64 - next_item_size as i64).abs() <= 2 {
                score -= 18.0; // near-perfect setup for the next item
            }
        }
        // Penalize bins far above the mean residual (wasteful choice among open bins),
        // mildly reward bins close to mean residual (balanced packing).
        let dev = bin_residual as f64 - mean_residual;
        score += 0.15 * dev.abs();
        // Encourage filling nearly-full bins as the stream progresses.
        let fill_ratio = 1.0 - (post_residual as f64 / bin_capacity as f64);
        score -= 10.0 * fill_ratio * fill_ratio * (0.5 + 0.5 * progress);
        // Mild penalty for spreading across too many open bins early on.
        score += 0.05 * open_bins_count as f64 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Tight fit reward: quadratic coupling of post_residual with progress
    let tight = (1.0 - pr / cap).powi(2);
    score -= 25.0 * tight * (0.5 + progress);

    // Penalize large leftover dead space non-linearly
    score += 0.02 * pr * pr / cap;

    // Last-chance bin bonus
    if fitting_bins_count <= 1 {
        score -= 15.0;
    }

    // Prefer bins with residual below mean residual (compact usage)
    score += 0.5 * (pr - mean_residual);

    // Lookahead: reward leaving room for the next item
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if n <= pr {
            score -= 8.0 * (1.0 - (pr - n) / cap).abs();
        } else {
            score += 5.0;
        }
    }

    // New-bin candidate: penalize mildly so we prefer reusing open bins unless fit is poor
    if bin_residual == bin_capacity {
        score += 10.0 + 20.0 * progress * (open_bins_count as f64 / (open_bins_count as f64 + 5.0));
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: how "usable" the leftover space is.
    // Class 0: post_residual divisible by small harmonics (10, 20, 25, 50) -> highly reusable.
    let post = post_residual;
    let mut class_bonus = 0.0f64;
    if post == 0 {
        class_bonus = 40.0; // perfect fit, strongly reward
    } else {
        if post % 10 == 0 { class_bonus += 6.0; }
        if post % 20 == 0 { class_bonus += 4.0; }
        if post % 25 == 0 { class_bonus += 3.0; }
        if post % 50 == 0 { class_bonus += 3.0; }
        // Integer-division threshold bands on leftover size
        let band = post / 10; // 0..10
        class_bonus += match band {
            0 => 8.0,          // tiny dead space
            1..=3 => 3.0,      // small but usable
            4..=6 => 0.0,      // mid range: neutral
            7..=9 => -2.0,     // large leftover: mildly penalize waste
            _ => -4.0,         // nearly empty bin used for small item
        };
    }
    score -= class_bonus;

    // Harmonic compatibility between leftover and the next item (k=2 lookahead).
    if next_item_size > 0 {
        if next_item_size <= post {
            // Next item fits exactly into harmonic slots of this leftover
            if post % next_item_size.max(1) == 0 {
                score -= 10.0;
            } else {
                score -= 4.0;
            }
        } else {
            // Next item cannot use this leftover: penalize proportionally
            score += (next_item_size - post) as f64 * 0.15;
        }
        // Penalize if this placement leaves leftover in an awkward class for next item
        if post > 0 && post < next_item_size && post < 10 {
            score += 5.0; // creates unusable sliver before next arrival
        }
    }

    // Capacity fraction logic: reward filling the bin past harmonic fractions.
    let fill = (bin_capacity - post) as f64 / bin_capacity as f64;
    if fill >= 1.0 { score -= 30.0; }
    else if fill >= 0.9 { score -= 12.0; }
    else if fill >= 0.75 { score -= 6.0; }
    else if fill >= 0.5 { score -= 1.0; }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && post < bin_capacity {
        score -= 15.0;
        if post <= 20 { score -= 10.0; }
    }

    // New-bin candidate handling: make an empty bin unattractive unless nothing fits well.
    if bin_residual == bin_capacity {
        score += 25.0 + open_bins_count as f64 * 0.5;
        if fitting_bins_count == 0 { score -= 60.0; } // no open bin fits -> open new bin
        if post_residual > 0 && post_residual < 10 { score += 10.0; }
    }

    // Stream progression: early on, be more willing to open bins (explore);
    // later, consolidate tightly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score -= progress * 10.0;
    } else {
        score += progress * 3.0;
    }

    // Mean residual coupling: if this bin's residual is far below mean, it's a
    // lopsided bin; using it balances the population.
    let resid_f = post as f64;
    score += (resid_f - mean_residual) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps (<10) are unusable forever.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Penalize moderate dead space quadratically relative to capacity.
    let waste_frac = post_residual as f64 / bin_capacity as f64;
    score += 30.0 * waste_frac * waste_frac;

    // Reward tight fits (post_residual small but usable/zero).
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual >= next_item_size && next_item_size > 0 {
        // Leftover can host the next item: reward proportionally.
        score -= 10.0 * (next_item_size as f64 / post_residual as f64);
    }

    // Last-chance bin pressure: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: when many bins are open, discourage opening new ones;
    // when few bins are open, opening is cheaper.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let bin_pressure = open_bins_count as f64 / (1.0 + progress);
    score += 0.6 * bin_pressure * (bin_residual == bin_capacity) as i32 as f64;

    // New-bin candidate: make it attractive only when mean residual is too small
    // to host upcoming items; otherwise penalize it.
    if bin_residual == bin_capacity {
        if (mean_residual < item_size as f64) || (next_item_size > 0 && mean_residual < next_item_size as f64) {
            score -= 20.0;
        } else {
            score += 12.0;
        }
    }

    // Prefer bins whose residual is close to item size (best-fit flavor).
    score += 0.15 * ((bin_residual - item_size) as f64).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next_item_size
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 40.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Next item cannot fit here after placement: penalize dead space
        score += 0.5 * (next_item_size as f64 - post_residual as f64);
    }

    // Prefer tight fits relative to mean residual
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 15.0 * fit_ratio;

    // Penalize deviating from mean residual (favor balanced bins)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.3 * dev;

    // Last-chance bin bonus: avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when current bin would leave unusable sliver
    if bin_residual == bin_capacity {
        let wasted = (bin_residual - item_size) as f64;
        if next_item_size > 0 && wasted < next_item_size as f64 && wasted > 0.0 {
            score += 30.0; // would create dead space; prefer existing bins
        } else {
            score += 5.0 + 0.1 * open_bins_count as f64;
        }
    }

    // Slight early-stream conservatism: fill bins more tightly as stream progresses
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * fit_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Prefer tight fits: reward small post_residual nonlinearly.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize dead space that no future item can plausibly fill.
    if next_item_size > 0 {
        if post_residual > 0 && post_residual < next_item_size {
            score += 12.0; // dead space relative to lookahead
        }
        if post_residual == next_item_size {
            score -= 10.0; // perfect lookahead fit
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Brand-new bin candidate: penalize opening new bins, more so when
    // good alternatives exist and we're early in the stream.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let mut penalty = 30.0;
        if fitting_bins_count > 0 {
            penalty += 15.0 * (fitting_bins_count as f64);
        }
        penalty *= 1.0 - 0.5 * progress;
        // Late in stream, prefer closing out bins with small residuals.
        if progress > 0.8 {
            penalty -= 10.0;
        }
        score += penalty;
    }

    // Global balance: favor bins whose residual is near the mean (avoid
    // stranding extreme bins), scaled by how many bins are open.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev * (open_bins_count as f64).sqrt();

    // Slight preference for fuller bins overall.
    score += 0.03 * (bin_capacity as f64 - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: penalize leftover space, but with a non-linear (quadratic) coupling
    // so large dead space is punished super-linearly.
    let mut score = pr * (1.0 + 0.9 * norm_pr * norm_pr);

    // Stream-progress coupling: early on, prefer tight fills in existing bins
    // (keep bins open for future flexibility); later, residual waste matters more.
    let progress_coupling = 0.5 * (1.0 - progress) - 0.7 * progress;
    score += progress_coupling * pr * norm_pr;

    // Mean-residual coupling: if average residual across open bins is high,
    // slightly reward using this bin (smooth interaction, avoids opening more bins).
    let mr = mean_residual / cap;
    score -= 0.6 * mr * pr * (0.5 + 0.5 * progress);

    // Last-chance bonus: if this is the only fitting bin, strongly favor it
    // (smoothly scaled by how well the item fills the bin).
    if fitting_bins_count == 1 {
        let fill = item_size as f64 / cap;
        score -= 30.0 + 40.0 * fill;
    }

    // Mild penalty proportional to congestion: many open bins -> prefer consolidation.
    score += 0.05 * open_bins_count as f64 * norm_pr;

    // Lookahead coupling: if next item fits into post_residual, reward this placement
    // (smooth quadratic interaction between post_residual and next item size).
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if ni <= pr {
            score -= 5.0 * (1.0 - (ni - pr) / cap).abs();
        } else {
            // penalize placements that leave residual just barely too small for next item
            let miss = (ni - pr) / cap;
            score += 8.0 * miss * (1.0 - miss);
        }
    }

    // New-bin candidate: make empty-bin slightly unattractive unless residuals
    // elsewhere are large; smooth gate via mean residual and progress.
    if bin_residual == bin_capacity {
        score += 25.0 - 15.0 * mr - 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual)
    let frac = post_residual as f64 / bin_capacity as f64;
    score += frac * 30.0;

    // Harmonic class of post_residual: bins whose residual falls into
    // "small leftover" classes (<= 10, 11..=20, ...) are more valuable.
    let class = post_residual / 10; // integer division class 0..10
    score += class as f64 * 4.0;

    // Dead-space penalty: residuals that no plausible item can use.
    // Items >= 1, so residual 0 is perfect; residual 1..3 is nearly dead.
    if post_residual > 0 && post_residual < 4 {
        score += 25.0;
    }

    // Modulo coupling: residuals congruent to small useful sizes (mod 10)
    // are easier to fill later; reward them.
    let m = post_residual % 10;
    if m == 0 {
        score -= 6.0;
    } else if m <= 2 {
        score += 3.0;
    }

    // Lookahead: if next item fits exactly in the post-residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= (post_residual - next_item_size) as f64 * 0.5;
        } else {
            // next item cannot use this bin's leftover: mild penalty
            score += 5.0;
            // harmonic class of the wasted gap
            let gap = next_item_size - post_residual;
            score += (gap / 10) as f64 * 2.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
        if post_residual < 10 {
            score -= 15.0;
        }
    }

    // New-bin candidate handling: an empty bin has high post_residual naturally,
    // but add an explicit opening cost that shrinks as the stream progresses
    // and when existing bins fit badly.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 35.0 - 15.0 * progress;
        // If existing bins are crowded (low mean residual), opening is cheaper.
        score -= (mean_residual / bin_capacity as f64).max(0.0) * 20.0;
    }

    // Prefer bins below mean residual (tighter-than-average usage).
    score += (mean_residual - bin_residual as f64) * 0.15;

    // Slight penalty for proliferating open bins late in the stream.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals in the "unusable gap" band
    // (too small for the smallest plausible item) are heavily penalized.
    let min_item = 1u32;
    if post_residual > 0 && post_residual < min_item.max(1) * 1 + 9 {
        // small gap below ~10 is pure dead space
        score += 60.0 * (1.0 - post_residual as f64 / 10.0);
    }
    // Penalize any small-ish gap that the lookahead item cannot use
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0 + 0.35 * post_residual as f64;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // reward bins that can also host the next item (chaining)
        score -= 8.0 + 0.10 * next_item_size as f64;
    }

    // Perfect / near-perfect fits get strong rewards
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 15 {
        score -= 6.0;
    }

    // Open-bin pressure: discourage spreading across many bins unless fit is good
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += 3.0 * pressure * (post_residual as f64 / bin_capacity as f64);

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when no open bin fits well
    if bin_residual == bin_capacity {
        let tightness = item_size as f64 / bin_capacity as f64;
        // big items prefer a fresh bin; small items should use open bins
        score += 25.0 - 40.0 * tightness;
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a new bin
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // fresh bin useful for upcoming large item
        }
    }

    // Mild stream-phase adaptation: early on, be frugal with new bins
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 5.0 * (1.0 - progress) * (mean_residual / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Perfect 2-step match: post_residual exactly equals next item size -> strong reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Near match: next item fits with small slack afterwards.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 * (1.0 - slack / cap);
    } else if next_item_size > 0 {
        // Next item won't fit here: penalize creating dead space that blocks lookahead.
        let waste = (next_item_size - post_residual) as f64;
        score += 0.35 * waste.min(60.0);
    }

    // Penalize very small unusable residuals (dead space).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Compare against mean residual: filling below-average-residual bins is efficient.
    score -= 0.15 * (mean_residual - post);

    // Slight preference for keeping the pool of open bins small.
    score += 0.5 * open_bins_count as f64;

    // Progress-aware scaling: late in stream, prioritize tight packing.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.3 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (non-linear).
    let tight = item_size as f64 / bin_residual as f64;
    score -= 18.0 * tight * tight;

    // Penalize dead space: residuals too small for typical future items.
    if post_residual < 10 {
        score -= 6.0; // perfect fill bonus
    } else if post_residual < next_item_size.max(10) && next_item_size > 0 {
        score += 4.0 + 0.15 * post_residual as f64; // dead space penalty vs lookahead
    }

    // Lookahead coupling: reward bins whose post-residual fits the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 3.0 + 0.05 * next_item_size as f64;
    } else if next_item_size > 0 {
        score += 0.04 * next_item_size as f64;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // Many open bins: prefer consolidating into existing bins.
    score += 0.15 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Global state: if mean residual is high, prefer bins below mean (balance).
    score += 0.08 * (mean_residual - post_residual as f64);

    // Time horizon: early in stream, be pickier about dead space; late, just fill.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.25 * (1.0 - progress);

    // New-bin candidate: make it attractive only when item fits poorly elsewhere.
    if bin_residual == bin_capacity {
        score += 8.0 + 10.0 * (1.0 - tight);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalized stream progress
    let progress = step_index as f64 / total_items.max(1) as f64;
    let prog2 = progress * progress;
    let prog3 = prog2 * progress;

    // Smooth non-linear coupling of post_residual with stream progress:
    // late in the stream, compact residuals matter more (dead space penalized super-linearly).
    let pr = post_residual as f64;
    let dead = pr * pr / bin_capacity as f64;
    score += dead * (0.5 + 1.5 * prog2 + prog3);

    // Reward tight fits (small post_residual) increasingly as stream advances.
    let tightness = 1.0 - pr / bin_capacity as f64;
    score -= tightness * tightness * (10.0 + 40.0 * prog2);

    // Last-chance bonus: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 25.0 + 50.0 * progress;
    }

    // Lookahead: reward leaving room for the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let slack = pr - nxt;
            // ideal if next item exactly fits remaining space
            let gap = (slack / bin_capacity as f64 - 0.05).abs();
            score -= 8.0 * (1.0 - gap.min(1.0)) * (0.5 + progress);
        } else {
            // penalize placements that strand the next item
            score += 6.0 + 12.0 * progress;
        }
    }

    // Mild penalty when this bin deviates from mean residual (keep bins balanced),
    // smoothly scaled by number of open bins.
    let dev = (pr - mean_residual).abs() / bin_capacity as f64;
    score += dev * dev * (2.0 + (open_bins_count as f64).ln().max(1.0));

    // New-bin candidate: penalize opening a fresh bin unless residuals are all tiny
    // relative to item size (smooth gate, no hard threshold).
    if bin_residual == bin_capacity {
        let avg_fit = mean_residual / bin_capacity as f64;
        let need = item_size as f64 / bin_capacity as f64;
        let desperation = ((need - avg_fit) / need.max(0.1)).clamp(0.0, 1.0);
        score += 30.0 - 45.0 * desperation * (0.5 + 0.5 * progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: modulo arithmetic on capacity fractions.
    let cap = bin_capacity as f64;
    let pr = post_residual as u32;

    // Class A: perfect fit — reward heavily.
    if pr == 0 {
        score -= 1000.0;
    } else {
        // Dead-space danger: residuals below the smallest item class (<= 10) are waste.
        if pr < 10 {
            score += 60.0;
        }
        // Harmonic banding via integer division of residual into capacity eighths.
        let band = pr / 13; // ~capacity/8 quantum
        score += (band as f64) * 2.5;

        // Modulo-4 harmonic classes: residuals divisible by 4 tend to pair with
        // common item sizes; reward smooth residuals, penalize odd primes.
        let class = pr % 4;
        match class {
            0 => score -= 12.0,
            2 => score -= 4.0,
            _ => score += 6.0,
        }

        // Reward residuals that are exact multiples of common size classes (10, 20, 25).
        if pr % 10 == 0 { score -= 15.0; }
        if pr % 25 == 0 { score -= 20.0; }
        if pr % 50 == 0 { score -= 25.0; }
    }

    // Lookahead coupling: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 120.0;
        } else if post_residual >= next_item_size {
            // Fraction of post residual consumed by next item — the tighter the better.
            let fill = next_item_size as f64 / post_residual as f64;
            if fill > 0.6 {
                score -= 30.0 * fill;
            } else {
                score += 10.0 * (1.0 - fill);
            }
            // Harmonic check: post_residual - next_item_size leaves a friendly class.
            let after2 = post_residual - next_item_size as u32;
            if after2 < 10 && after2 > 0 {
                score += 25.0;
            }
            if after2 % 10 == 0 && after2 > 0 {
                score -= 10.0;
            }
        } else {
            // Next item cannot use this bin's leftover; leftover likely dead space.
            score += 20.0;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate handling: only attractive when open bins are crowded.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowdedness = mean_residual / cap;
        // Penalize new bin; penalty shrinks if existing residuals are poor fits.
        score += 90.0 - 60.0 * (1.0 - crowdedness) - 20.0 * progress;
        if next_item_size > 0 && next_item_size > bin_capacity - item_size {
            score += 15.0; // next item won't fit here anyway
        }
    }

    // Mild pressure to consolidate when many bins are open.
    score += (open_bins_count as f64) * 0.5;
    // Slight preference toward tighter fits overall.
    score += (item_size as f64) / cap * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals below the minimum item size (1..10)
    // are "perfect", but small unusable gaps (10..25) are heavily penalized.
    if post_residual == 0 {
        score -= 500.0; // perfect fill
    } else if post_residual < 10 {
        score -= 200.0; // effectively dead but tiny waste
    } else if post_residual <= 25 {
        score += 120.0; // small gap = worst dead space
    }

    // Reward tight fits relative to bin size
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 40.0 * fill_ratio;

    // Open-bin pressure: with many open bins, prefer consolidation into existing bins
    // and make the new-bin candidate (residual == capacity) less attractive.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.5 + progress);
    if bin_residual == bin_capacity {
        score += 30.0 + 8.0 * open_bins_count as f64;
    } else {
        score -= 5.0 * pressure.sqrt();
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big bonus
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 180.0;
        } else if post_residual >= next_item_size && post_residual - next_item_size < 10 {
            score -= 60.0;
        }
    }

    // Mild preference toward bins tighter than the mean residual
    score += 0.3 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Two-step lookahead: strongly reward exact match of next item into post_residual.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack_after_next = (post_residual - next_item_size) as f64;
        score -= 12.0 + 0.35 * slack_after_next; // fits next item AND leaves little waste
        // Perfect 2-step fill: post_residual == next_item_size
        if post_residual == next_item_size {
            score -= 25.0;
        }
    } else if next_item_size > 0 {
        // Next item cannot follow in this bin: penalize proportionally to how close we missed.
        let miss = (next_item_size - post_residual) as f64;
        score += 0.12 * miss;
    }

    // Penalize small dead space (<10) that nothing can ever use.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Reward tight fits relative to the bin (low post residual already does this; amplify).
    let tightness = 1.0 - (post_residual as f64) / cap;
    score -= 6.0 * tightness;

    // Relative-to-mean coupling: prefer bins whose post residual stays below the mean residual
    // (concentrating waste into fewer bins), but soften when this is the last fitting bin.
    score += 0.45 * (mean_residual - post_residual as f64);

    // Last-chance bonus: if this is the only bin that can fit the item, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: prefer opening a fresh bin only when current fit is terrible
    // and the next item is large (would waste this bin anyway).
    if bin_residual == bin_capacity {
        let poor_fit = (post_residual as f64) / cap; // == 1.0 for empty bin
        let next_pressure = if next_item_size > 0 { next_item_size as f64 / cap } else { 0.0 };
        score = cap * (1.0 - 0.30 * next_pressure) + 0.10 * (open_bins_count as f64);
        // Early in stream, opening bins is cheaper; late, consolidate.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 10.0 * progress;
        let _ = poor_fit;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual).
    let tight_fit = (post_residual as f64) / (bin_capacity as f64);
    score += 12.0 * tight_fit * tight_fit;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual < 10 {
        score -= 8.0;
    }

    // Penalize dead space that no future item (min size 1, typical >=10) can use.
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // Lookahead: reward bins whose post_residual fits the next item well.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let gap = (post_residual - next_item_size) as f64;
            score -= 10.0 * (1.0 - gap / (bin_capacity as f64));
        } else {
            // Next item won't fit here: slight penalty proportional to overflow.
            let over = (next_item_size - post_residual) as f64;
            score += 3.0 * (over / (bin_capacity as f64));
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Many open bins with high mean residual: encourage consolidation into existing bins.
    let consolidation = if mean_residual > 0.0 {
        (bin_residual as f64 / mean_residual - 1.0).clamp(-2.0, 2.0)
    } else {
        0.0
    };
    score -= 2.0 * consolidation;

    // Prefer bins with more residual when stream is early (flexibility), less when late.
    let progress = if total_items > 0 {
        step_index as f64 / total_items as f64
    } else {
        0.0
    };
    score += (1.0 - progress) * 0.05 * (bin_residual as f64);

    // New-bin candidate handling: usually worse than reusing, but attractive when
    // no good fit exists or open bins are nearly full.
    if bin_residual == bin_capacity {
        let avg_open_util = 1.0 - mean_residual / (bin_capacity as f64);
        let scarcity = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        let new_bin_score = 30.0
            - 20.0 * scarcity
            - 15.0 * avg_open_util.clamp(0.0, 1.0)
            - 5.0 * progress;
        // New bin loses to any decent existing fit but beats heavily fragmented ones.
        score = new_bin_score + 0.5 * (item_size as f64) * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Base: prefer small post-residual, with a non-linear (quadratic) penalty
    // that grows for large leftover space (wasted capacity).
    let mut score = pr + 30.0 * pr_norm * pr_norm * cap;

    // Smooth stream-progress coupling: later in the stream, waste matters more,
    // so amplify the quadratic term as progress increases.
    score *= 1.0 + 0.8 * progress * pr_norm;

    // Reward tight fits (small post_residual) especially when this bin is a
    // last-chance option — smooth sigmoid-like coupling via fitting_bins_count.
    let last_chance = 1.0 / (1.0 + (fitting_bins_count as f64 - 1.0).max(0.0));
    score -= 12.0 * last_chance * (1.0 - pr_norm);

    // Penalize bins far from the mean residual (smooth quadratic divergence),
    // scaled mildly by stream progress.
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 8.0 * progress * dev * dev * cap;

    // Lookahead: reward leaving room for the next item (smooth coupling),
    // penalize if post_residual neither fits next item nor is near zero.
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        let fits_next = (pr >= ni) as i32 as f64;
        let gap = (pr - ni).abs() / cap;
        score -= 10.0 * fits_next * (1.0 - gap * gap);
        score += 6.0 * (1.0 - fits_next) * (1.0 - pr_norm * pr_norm);
    }

    // Mild penalty for accumulating too many open bins late in the stream.
    score += 0.5 * progress * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the residual: residuals divisible by common item sizes
    // are more reusable. Reward residuals that are "harmonic" with capacity.
    let residual = post_residual;
    let cap_frac = residual as f64 / bin_capacity as f64;

    // Perfect fit: strongly reward
    if residual == 0 {
        score -= 1000.0;
    }

    // Dead space penalty: small unusable residuals (below min item size 1..10)
    if residual > 0 && residual < 10 {
        score += 25.0;
    }

    // Harmonic reward: residual divisible by 10 or 20 chunks is more reusable
    if residual % 10 == 0 {
        score -= 6.0;
    }
    if residual % 20 == 0 {
        score -= 4.0;
    }
    if residual % 25 == 0 {
        score -= 3.0;
    }

    // Integer-division threshold classes on post_residual
    let class = residual / 10; // 0..=10
    match class {
        0 => score += 12.0,          // tiny leftover, nearly dead
        1 => score += 4.0,
        2 => score -= 2.0,           // sweet spot for small items
        3 => score -= 5.0,
        4 => score -= 6.0,           // most reusable class (40-49)
        5 => score -= 6.0,
        6 => score -= 4.0,
        7 => score -= 2.0,
        _ => {}
    }

    // Lookahead coupling: if next item fits exactly into post_residual, reward heavily
    if next_item_size > 0 && next_item_size <= residual {
        if residual == next_item_size {
            score -= 30.0;
        } else if residual.saturating_sub(next_item_size) < 10 {
            score -= 12.0; // next item leaves near-perfect fit
        } else {
            score -= 3.0;
        }
    } else if next_item_size > residual {
        // next item won't fit here; leftover may become dead space
        score += cap_frac * 5.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when current fit is bad
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        score += 15.0;
        // open a new bin if this item is large relative to typical residuals
        if item_size as f64 > mean_residual {
            score -= 25.0;
        }
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 10.0; // pair next item with this one in fresh bin
        }
    }

    // Stream progression: early on, be frugal with bins; late, consolidate
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 2.0;

    // Mild preference to fill bins with large residuals when many bins are open
    score -= (open_bins_count as f64).ln().max(0.0) * (bin_residual as f64 - mean_residual) / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that nothing (min size 1..=10) can use are heavily penalized.
    if post_residual > 0 && post_residual <= 10 {
        score += (11 - post_residual as f64) * 25.0;
    }

    // Reward tight fits (exact fill is ideal).
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 20 {
        score += (20.0 - post_residual as f64) * 0.5;
    }

    // Reward bins whose residual can still host the next item (lookahead synergy).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, discourage opening another empty bin.
    if bin_residual == bin_capacity {
        score += open_bins_count as f64 * 6.0 + 10.0;
        // But allow a new bin if the only alternative is a terrible fit.
        if post_residual == bin_capacity && fitting_bins_count <= 1 {
            score -= 25.0;
        }
    } else {
        // Mild bonus for reusing already-open bins, scaled by mean residual dispersion.
        score -= 5.0 + (mean_residual - post_residual as f64).abs() * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post-residual
    // can host the next item (perfect 2-item chaining).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0; // exact 2-item fill
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // dead space penalty scaled by how badly next item misses
            let miss = (next_item_size - post_residual) as f64;
            score += 0.35 * miss;
        }
    }

    // Prefer bins tighter than the mean (best-fit flavor)
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Penalize near-empty usage of a mostly-full bin slightly less
    // (keeps large residuals for future big items)
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if post_residual < 10 {
        score -= 5.0 * (1.0 - t); // early stream: kill tiny residuals
    }

    // New-bin candidate: only attractive when nothing fits well
    if bin_residual == bin_capacity {
        let poor_fit = if next_item_size > 0 && post_residual < next_item_size { 1.0 } else { 0.0 };
        score += 25.0 - 20.0 * poor_fit;
        if fitting_bins_count == 0 {
            score -= 50.0; // no alternative: must open new bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual small relative to capacity.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 2.0 * tightness * tightness * (bin_capacity as f64);

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual < 10 {
        score -= 30.0;
    }

    // Lookahead: reward if next item fits into the post residual.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 15.0;
        } else if next_item_size > post_residual && post_residual < next_item_size {
            // dead space for the next item: penalize small but unusable leftovers
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Time horizon: early in the stream, prefer consolidating into fewer bins;
    // later, be more tolerant of new bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more early, less late.
        score += 20.0 * (1.0 - progress);
        // But if mean residual across open bins is small (all bins nearly full),
        // opening a new bin is reasonable.
        score -= (mean_residual / 10.0).min(15.0);
        // If no open bin other than a fresh one fits, new bin is fine.
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
    } else {
        // Favor bins whose residual is close to the mean (balanced packing).
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += dev * 0.1;
    }

    // Slight preference for bins with more open bins already (spread load late).
    if open_bins_count > 8 && progress > 0.5 {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let res = bin_residual as f64;
    let fit = item_size as f64 / cap;

    // Base: penalize wasted space, quadratically coupled with progress
    let mut score = pr * (1.0 + 2.0 * progress * pr / cap);

    // Non-linear interaction: post_residual vs fit ratio, smooth cubic coupling
    score += 8.0 * (pr / cap) * (1.0 - fit) * (1.0 - fit) * cap;

    // Reward tight fits more strongly as stream progresses
    score -= 20.0 * progress * (1.0 - pr / cap).powi(3) * cap;

    // Mean residual deviation: smooth coupling to prefer bins near mean
    score += 3.0 * ((res - mean_residual) / cap).powi(2) * cap;

    // Last-chance bonus (smooth, progress-modulated)
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 + progress);
    }

    // Lookahead: penalize blocking the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx > pr {
            score += 10.0 * progress * ((nx - pr) / cap).powi(2) * cap;
        } else {
            score -= 6.0 * (pr - nx) / cap;
        }
    }

    // New-bin candidate: mildly discourage opening a bin early, encourage late
    if bin_residual == bin_capacity {
        score += 12.0 * (1.0 - progress) * open_bins_count as f64;
        score -= 5.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: mod-10 residue classes
    let residue = (post_residual % 10) as f64;
    score += residue * 0.35; // prefer post_residuals landing on "round" classes

    // Small dead space is excellent: reward tight fits nonlinearly
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 10 {
        score -= 10.0;
    }

    // Integer-division thresholds: post_residual in [1..=9] is a near-perfect fill class
    let class = post_residual / 10; // 0..10 harmonic class
    score += class as f64 * 1.5;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Penalize bins far below mean residual (fragmented bins) mildly
    score += (mean_residual - bin_residual as f64) * 0.2;

    // Lookahead: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 55.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // next item fits but leaves residue: mild reward proportional to leftover tightness
        let nxt_left = post_residual - next_item_size;
        if nxt_left <= 10 {
            score -= 12.0;
        }
    } else if next_item_size > post_residual && post_residual > 0 && post_residual < 10 {
        // dead space too small for next item: penalize
        score += 8.0;
    }

    // New-bin candidate: only attractive when no good fit exists
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // default penalty so open bins win; reduced when many open bins are fragmented
        let mut pen = 30.0;
        if post_residual > 0 && fitting_bins_count >= 1 {
            // compare best possible leftover among fitting bins via mean residual proxy
            if mean_residual < (bin_capacity as f64) * 0.3 {
                pen -= 20.0;
            }
        }
        if progress > 0.7 {
            pen -= 5.0; // late stream: consolidation matters more
        }
        score += pen;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 {
        if post_residual < 10 {
            score += 60.0; // tiny dead space, nearly unusable
        } else if post_residual < 20 {
            score += 25.0;
        } else if post_residual < 30 {
            score += 8.0;
        }
    } else {
        score -= 40.0; // perfect fit: strongly reward closing the bin
    }

    // Reward leaving room for the lookahead item (k=2 lookahead).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else if post_residual > 0 {
            score += 10.0;
        }
    }

    // Open-bins pressure: discourage spreading across many bins,
    // but allow opening a new bin when this would be a last-chance fit.
    if bin_residual == bin_capacity {
        // New-bin candidate: attractive only if current bin fit is poor
        // or this is a fresh stream; otherwise penalize mildly.
        score += 15.0;
        if post_residual as f64 > mean_residual {
            score += 10.0;
        }
        if open_bins_count == 0 {
            score -= 100.0; // must open the first bin
        }
    } else if fitting_bins_count == 1 {
        // Last chance bin: strongly prefer using it over opening a new bin.
        score -= 30.0;
    }

    // Slight preference for tighter bins (below-mean residual).
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    }

    // Late-stream consolidation: favor filling existing bins as stream ends.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if progress > 0.8 {
        score += if bin_residual == bin_capacity { 25.0 } else { -8.0 };
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward when next item fits exactly into post_residual
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            // next item fits: penalize by leftover after two placements
            let two_step_left = post_residual - next_item_size;
            score += two_step_left as f64 * 0.8;
        } else {
            // next item does NOT fit here: reward tight fills that leave small residuals
            score -= 20.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
        }
    } else {
        // last item: strongly prefer tightest fit
        score -= 100.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Penalize bins with residual far below mean (fragmented), reward above-mean residuals
    score += (mean_residual - bin_residual as f64) * 0.5;

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: make it unattractive unless all fits are terrible
    if bin_residual == bin_capacity {
        score += 250.0;
        // early in stream, opening bins is cheaper
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 100.0 * (1.0 - progress);
    }

    // Slight preference for fewer open bins
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize residual that is too small to ever be reused
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // dead space: nothing (min item 1..10) may fit
    }

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead: if next item can fit into post_residual, reward this placement
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0 + 0.5 * (next_item_size as f64);
    } else if next_item_size > 0 && next_item_size > post_residual {
        score += 8.0; // next item will need another bin anyway
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 70.0;
    }

    // New-bin candidate handling: empty bin should only win when fits are poor
    if bin_residual == bin_capacity {
        // penalize opening a new bin, more so late in the stream
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 45.0 + 30.0 * progress;
        // but if item is large and leaves big residual elsewhere, mild bonus
        if item_size * 2 >= bin_capacity {
            score -= 15.0;
        }
    }

    // Prefer bins with residual close to item_size (best-fit sharpening)
    let fit_gap = (bin_residual as f64 - item_size as f64).abs();
    score += 0.3 * fit_gap;

    // Global state coupling: if mean residual is large, prefer reusing fuller bins
    score += 0.2 * (mean_residual - post_residual as f64);

    // Slight preference to fill bins when many bins are open
    score += 0.1 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let fit_norm = item_size as f64 / cap;
    let next_norm = next_item_size as f64 / cap;
    let mean_norm = mean_residual / cap;

    // Base: penalize leftover space, quadratically (dead space is doubly bad).
    let mut score = pr + 0.65 * pr * pr / cap;

    // Smooth coupling: leftover space hurts more as the stream progresses
    // (fewer future chances to fill gaps), modulated by mean residual pressure.
    let progress_coupling = 1.0 + progress * (1.0 - mean_norm.clamp(0.0, 1.0));
    score *= progress_coupling;

    // Reward tight fits: subtract a smooth bell around post_residual == 0.
    score -= 12.0 * (-pr / (0.15 * cap)).exp();

    // Lookahead: if the next item exactly consumes this bin's post-residual,
    // strongly reward this placement (perfect pair).
    let pair_gap = (pr - next_item_size as f64).abs();
    if next_item_size > 0 {
        score -= 8.0 * (-pair_gap / (0.10 * cap)).exp();
    } else {
        // Last item: leftover is pure waste, penalize harder.
        score += 15.0 * pr / cap;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0 + 20.0 * progress;
    }

    // New-bin candidate: prefer opening a fresh bin when the current item is
    // large (poor future fit potential in leftovers) or late in the stream.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let openness = 0.5 + 0.5 * (1.0 - fit_norm) * (1.0 - progress);
        score = cap as f64 * (1.0 - openness) + 0.65 * cap * openness;
    }

    // Mild penalty for spreading across too many open bins.
    score += (open_bins_count as f64).ln().max(0.0) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residues modulo 10 define
    // "dead space classes". Residues that rarely admit future items
    // (small residues like 1..=9) are penalized super-linearly.
    let r = post_residual % 10;
    if post_residual > 0 {
        let dead_penalty = match r {
            0 => -6.0,          // perfectly aligned leftover: excellent
            1..=4 => 8.0 + 2.0 * (4 - r) as f64, // tiny unusable slivers
            5..=9 => 1.0 + 0.2 * (9 - r) as f64, // mid residues are ok
            _ => 0.0,
        };
        score += dead_penalty;
    } else {
        // Exact fill is ideal: strong reward.
        score -= 25.0;
    }

    // Integer-division class: how many "size-10 slots" remain.
    let slots = post_residual / 10;
    score -= 3.0 * slots as f64;

    // Harmonic coupling with next item: does the next item divide
    // evenly into the post residual? If next_item_size > 0 and
    // post_residual % next_item_size == 0 (and next fits), reward.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 10.0;
            if post_residual % next_item_size == 0 {
                score -= 8.0;
            }
        } else {
            // Next item won't fit here: penalize proportionally to
            // how much dead space this creates relative to next item.
            score += 4.0 * (next_item_size - post_residual) as f64 / 10.0;
        }
    } else {
        // Last item: closing a bin fully is great, otherwise neutral.
        score -= 2.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly
    // prefer using it over opening a new bin (unless post residual
    // is a terrible tiny sliver).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
        if post_residual < 10 && post_residual > 0 {
            score += 6.0; // still, avoid creating a <10 sliver if possible
        }
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    // Prefer existing bins unless the current item fits an open bin
    // almost perfectly or the open-bin landscape is fragmented.
    if bin_residual == bin_capacity {
        // Base handicap so open bins usually win.
        score += 12.0;
        // But if many open bins exist with high mean residual (fragmented),
        // opening fresh is attractive to keep clean bins for big items.
        if open_bins_count > 3 && mean_residual > 40.0 {
            score -= 10.0;
        }
        // Large current item relative to capacity: keep big items together
        // in fresh bins to preserve small-bin residuals for small items.
        if item_size >= bin_capacity / 2 {
            score -= 8.0;
        }
        // Lookahead: if next item is large and this bin can't host both,
        // a fresh bin pairing them is good.
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 6.0;
        }
    }

    // Fit tightness: reward small post_residual generally (tight packing),
    // but only when it's a "good" class (>=10 or exactly 0).
    if post_residual >= 10 {
        score -= 0.5 * (bin_capacity - post_residual) as f64 / 10.0;
    }

    // Stream progression: late in the stream, prefer closing bins
    // (minimize open-bin count) over spreading.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress > 0.8 {
        score -= 3.0 * progress;
        if post_residual < 10 {
            score -= 5.0; // squeeze bins shut at the end
        }
    }

    // Mild penalty for spreading across many open bins.
    score += 0.3 * open_bins_count as f64;

    // Coupling with mean residual: prefer bins below mean residual
    // (fill the emptier bins first, keep tight bins for tight fits).
    let diff = mean_residual - bin_residual as f64;
    score += 0.15 * diff;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to host
    // typical future items are wasted. Penalize unusable gaps heavily.
    if post_residual > 0 {
        // A gap is "dead" if it cannot fit even the smallest plausible item (1..=10),
        // or if it falls in the awkward band below ~20.
        if post_residual < 10 {
            score += 60.0; // completely wasted sliver
        } else if post_residual < 20 {
            score += 25.0; // awkward small gap
        }
        // Diminishing value of leftover space: penalize non-linearly
        score += (post_residual as f64).powf(1.35) * 0.25;
    } else {
        // Perfect fit: strong reward
        score -= 80.0;
    }

    // Reward tight fits: post_residual small relative to item size
    if item_size > 0 {
        let tightness = post_residual as f64 / item_size as f64;
        score -= 30.0 * (1.0 - tightness.min(1.0));
    }

    // Open-bins pressure: with many open bins, prefer consolidating
    // (favoring existing bins over opening new ones).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.4 + 0.6 * progress);
    score += pressure * 0.6;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate handling: an empty bin has bin_residual == bin_capacity.
    // It should only win when no open bin fits well, so give it a baseline
    // penalty that grows with how well the item could otherwise be packed.
    if bin_residual == bin_capacity {
        score += 20.0;
        // Opening a new bin is more attractive early (plenty of stream left,
        // bins amortized) and when open bins are nearly full on average.
        score -= 25.0 * (1.0 - progress);
        score += (mean_residual / bin_capacity as f64).max(0.0) * 15.0;
    }

    // Lookahead: if the next item can exactly use this bin's post_residual,
    // reward the placement (chain fit).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 35.0;
        } else if post_residual > next_item_size {
            // leaving room for the next item is good
            score -= 8.0;
        }
    }

    // Mild preference for bins whose residual deviates from the mean
    // (fill the outliers, keep the pool homogeneous).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward bins where the next item fits exactly into post_residual
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual > next_item_size {
            // next item fits, but leaves a new residual — mild reward proportional to tightness
            let after_next = post_residual - next_item_size;
            score -= 100.0 * (1.0 - after_next as f64 / bin_capacity as f64);
        } else {
            // next item does NOT fit here: penalize leaving a residual smaller than next_item_size (dead space)
            score += 150.0 * (next_item_size as f64 - post_residual as f64) / 100.0;
        }
    }

    // Relative-to-mean residual coupling: prefer bins that reduce dispersion
    score += 0.5 * (post_residual as f64 - mean_residual).abs();

    // Last-chance bin: strongly favor using the only bin that can fit the item
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 300.0;
    }

    // Penalize opening a new bin when open bins fit reasonably well
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 200.0;
    }

    // Slight preference early in the stream for keeping residuals flexible
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 20.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize small post_residual.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    if fit_ratio > 0.85 {
        score -= 25.0 * (fit_ratio - 0.85) * 6.67;
    } else {
        score += 3.0 * (0.85 - fit_ratio);
    }

    // Penalize creating dead space that no plausible future item can use.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0; // tiny unusable sliver
    } else if post_residual >= 10 && post_residual < 20 {
        score += 2.0;
    }

    // Perfect fill bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Lookahead: if next item fits in post_residual, big bonus.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
            // chain bonus: next item exactly consumes remainder
            if post_residual == next_item_size {
                score -= 10.0;
            }
        } else {
            score += 0.05 * (next_item_size - post_residual) as f64;
        }
    }

    // Global state coupling: many open bins with large mean residual
    // suggests we should consolidate rather than spread.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if open_bins_count > 3 && mean_residual > item_size as f64 * 1.5 {
        score += 2.0 * mean_residual / bin_capacity as f64;
    }

    // Time horizon: early in the stream, be more willing to open new bins
    // (keep flexibility); late, consolidate aggressively.
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize early, reward when open bins are fragmented.
        score += 10.0 * (1.0 - progress);
        score += 1.5 * open_bins_count as f64;
        if mean_residual < 15.0 && open_bins_count > 2 {
            score -= 8.0; // open bins nearly full -> new bin is fine
        }
        if next_item_size > 0 && next_item_size >= bin_capacity as u32 - item_size {
            score -= 6.0; // next item is large, fresh bin helps
        }
    }

    // Mild penalty for wasting a large bin on a small item.
    score += 0.03 * (bin_capacity as f64 - item_size as f64) * (1.0 - fit_ratio);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_ratio = item_size as f64 / cap;
    let pr_norm = pr / cap;
    let next_norm = next_item_size as f64 / cap;

    // Base: post residual, softly damped by stream progress (waste matters more early)
    let mut score = pr * (1.0 - 0.5 * progress);

    // Non-linear polynomial coupling of post_residual with progress
    let poly = pr_norm * pr_norm * (1.0 - pr_norm) * (0.5 + progress);
    score += 40.0 * poly;

    // Reward tight fits: cubic in fit_ratio
    score -= 30.0 * fit_ratio * fit_ratio * fit_ratio * (1.0 - progress);

    // Lookahead: penalize if next item can't use post_residual (smooth interaction)
    if next_item_size > 0 {
        let gap = next_norm - pr_norm;
        if gap > 0.0 {
            score += 15.0 * gap * gap * (0.3 + 0.7 * progress);
        } else {
            score -= 10.0 * (-gap) * (1.0 - pr_norm);
        }
    }

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0 + 20.0 * progress;
    }

    // Mild penalty for spreading across many open bins relative to mean residual
    score += 0.05 * (open_bins_count as f64) * (mean_residual - pr).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residues near multiples of common
    // item sizes are more reusable. Reward residuals that fall into "friendly"
    // classes (small multiples of 10, or exact matches to the next item).
    let pr = post_residual;
    if pr == 0 {
        // Perfect fit: strongest reward.
        score -= 40.0;
    } else if pr <= 5 {
        // Nearly dead space, but small enough to be a rounding loss.
        score -= 5.0;
    } else {
        // Harmonic class: distance to nearest multiple of 10 within [0,5].
        let r10 = (pr % 10) as f64;
        let dist = if r10 > 5.0 { 10.0 - r10 } else { r10 };
        score -= 6.0 - dist * 1.2; // residual aligned to decade class is reusable
        // Integer-division thresholds: residuals in [10,30] hold a small item.
        if pr >= 10 && pr <= 30 {
            score -= 4.0;
        }
        // Large residual (pr / cap > 0.5) is a healthy bin.
        if pr * 2 >= bin_capacity {
            score -= 3.0;
        }
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // strongly prefer this bin (chain of harmonic placements).
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 25.0;
        } else if next_item_size < pr {
            let slack = (pr - next_item_size) as f64;
            score -= (10.0 - slack.min(10.0)) * 0.8;
            // next item leaves a decade-aligned residue again?
            let npr = pr - next_item_size;
            if npr % 10 == 0 && npr > 0 {
                score -= 3.0;
            }
        } else {
            // Next item cannot follow here; slight penalty proportional to gap.
            score += ((next_item_size - pr) as f64) * 0.15;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new
    // bin unless the fit is terrible (large post-residual waste).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0 + (bin_capacity - pr) as f64 * 0.05;
    }

    // New-bin candidate: penalize opening a new bin when the item is small
    // relative to capacity (wasteful), reward when item is large.
    if bin_residual == bin_capacity {
        let frac = item_size as f64 / bin_capacity as f64;
        score = 100.0 - frac * 60.0;
        if fitting_bins_count == 0 {
            score -= 50.0; // no alternative, must open
        }
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 8.0; // room for a paired next item
        }
    }

    // Stream progression: late in the stream, consolidate harder (fewer bins).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (mean_residual - pr as f64) * 0.1 * progress;

    // Prefer bins tighter than the mean (pack dense bins first).
    score += (pr as f64 - mean_residual) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for the minimum item are worthless.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Tightness: reward small post_residual relative to capacity.
    score += (post_residual as f64 / bin_capacity as f64) * 20.0;

    // Last chance: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (0.5 + 0.5 * progress);

    // New-bin candidate: make empty bin mildly attractive only when it truly helps
    // (item leaves a large usable residual and few bins fit), otherwise penalize.
    if bin_residual == bin_capacity {
        if post_residual >= 20 && fitting_bins_count <= 2 {
            score -= 5.0;
        } else {
            score += 15.0;
        }
    }

    // Lookahead: if the next item fits into the post residual, reward this placement.
    if next_item_size > 0 && (post_residual as i64) >= (next_item_size as i64) {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 8.0;
    }

    // Penalize bins far below mean residual (wasteful pick) slightly.
    score += (mean_residual - post_residual as f64).abs() * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when next item fits the post residual exactly-ish.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let post = post_residual as f64;
        let gap = (post - nxt).abs();
        if nxt <= post {
            // Next item fits after this placement: reward tightness of the chain.
            score -= 30.0 * (1.0 - gap / bin_capacity as f64);
            if gap < 1.0 {
                score -= 25.0; // perfect two-item chain fill
            }
        } else {
            // Next item cannot use this bin afterwards: penalize wasted residual
            score += 0.35 * post;
        }
    } else {
        // Last item: strongly prefer tightest final fit.
        score += 0.5 * post_residual as f64;
    }

    // Relative to mean residual: prefer bins that are more filled than average.
    score += 0.6 * (mean_residual - post_residual as f64);

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // New-bin candidate handling: empty bin gets a moderate penalty so it is
    // chosen only when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        score += 55.0;
        // But if lookahead chains well into a fresh bin, soften the penalty.
        if next_item_size > 0 && (post_residual as f64 - next_item_size as f64).abs() < 2.0 {
            score -= 30.0;
        }
    }

    // Late in the stream, consolidate: penalize spreading across many bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.15 * open_bins_count as f64 * progress;

    // Small bonus for very tight fits regardless of lookahead.
    if post_residual <= 5 {
        score -= 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual already favored by base).
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 14.0 * fit_ratio * fit_ratio;

    // Penalize tiny dead space that nothing else can use (wasted capacity).
    if post_residual > 0 && post_residual < 10 {
        score += 18.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            score -= 8.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item cannot use this bin's remainder: mild penalty for over-filling
            score += 4.0;
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin before opening a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Many open bins: encourage consolidation into existing bins.
    score += 2.5 * (open_bins_count as f64).ln().max(0.0);

    // Prefer bins whose residual is below mean residual (denser bins) when item fits well.
    score += 0.15 * (mean_residual - bin_residual as f64);

    // New-bin candidate: penalize opening a new bin unless the item is large and
    // existing residuals are poor (item barely fits anywhere).
    if bin_residual == bin_capacity {
        let scarcity = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        let big_item = (item_size as f64 / bin_capacity as f64).powi(2);
        let tight_existing = if mean_residual < item_size as f64 + 5.0 { 1.0 } else { 0.0 };
        score += 45.0 - 30.0 * scarcity - 20.0 * big_item - 15.0 * tight_existing;
    }

    // Time horizon: late in the stream, be more conservative (prefer existing bins).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 6.0 * progress * (1.0 - fit_ratio);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual
    let is_new = (bin_residual as f64 - cap).abs() < 1e-9;

    // Smooth non-linear polynomial coupling of post residual with stream progress.
    let base = pr
        + 8.0 * x * x * (1.0 - x)
        + 20.0 * progress * x * (1.0 - x)
        - 12.0 * (1.0 - progress) * x * x;

    // Penalize dead space relative to the next item's needs (smooth lookahead coupling).
    let nxt = next_item_size as f64;
    let waste = if nxt > 0.0 {
        let d = (pr - nxt) / cap;
        15.0 * d * d
    } else {
        0.0
    };

    // Last-chance bonus: strongly favor the only fitting bin.
    let last_chance = if fitting_bins_count == 1 && !is_new { -30.0 } else { 0.0 };

    // New-bin candidate: smooth penalty that relaxes as stream progresses.
    let new_pen = if is_new {
        25.0 + 30.0 * progress + 0.15 * mean_residual
    } else {
        0.0
    };

    // Mild congestion term: prefer spreading across many open bins when residuals are large.
    let crowd = 0.05 * open_bins_count as f64 * (1.0 - x);

    base + waste + last_chance + new_pen + crowd
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: how "usable" the leftover space is.
    // Residuals that are exact multiples of common item sizes (10,20,25,50) are valuable.
    let pr = post_residual;
    let harmonic_bonus = if pr == 0 { 0.0 }
        else if pr % 50 == 0 { -18.0 }
        else if pr % 25 == 0 { -12.0 }
        else if pr % 20 == 0 { -10.0 }
        else if pr % 10 == 0 { -8.0 }
        else { 0.0 };
    score += harmonic_bonus;

    // Fractional capacity class of post_residual: quarter / half thresholds.
    let frac = pr as f64 / cap;
    if frac >= 0.5 { score -= 6.0; }
    else if frac >= 0.25 { score -= 2.0; }
    else if frac > 0.0 { score += 4.0; } // tiny dead space penalized

    // Perfect fit reward dominates everything.
    if pr == 0 { score -= 100.0; }

    // Lookahead coupling: does the leftover space fit the next item exactly or well?
    if next_item_size > 0 {
        if next_item_size <= pr {
            let nxt = next_item_size as f64;
            let nxt_mod = next_item_size % 10;
            // next item fits: reward more if it fills the remainder well
            let fill_ratio = nxt / (pr as f64);
            score -= 10.0 * fill_ratio;
            if next_item_size == pr { score -= 25.0; } // chain perfect fit
            // harmonic alignment: next item size in a "round" class is easier to place elsewhere
            if nxt_mod == 0 { score += 1.0; }
        } else {
            // leftover cannot host the next item: penalize if leftover is small (dead space)
            if pr < next_item_size && pr < 20 { score += 8.0; }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // base penalty so open bins with decent fit win
        score += 30.0;
        // but if current bin would leave a bad (non-harmonic, tiny) residual, opening fresh is fine
        if pr > 0 && pr < 10 { score -= 20.0; }
        if next_item_size > 0 && next_item_size > pr && pr > 0 { score -= 10.0; }
        // late in the stream, prefer closing out existing bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * (1.0 - progress);
    }

    // Mild pressure to consolidate when many bins are open.
    score += (open_bins_count as f64).ln().max(0.0);

    // Integer-division threshold: residuals in [1..9] are near-dead space.
    if pr >= 1 && pr <= 9 { score += 6.0; }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals in the "unusable gap" band (1..12) are poison.
    if post_residual >= 1 && post_residual <= 12 {
        score += (13.0 - post_residual as f64) * 25.0;
    }
    // Perfect fit is heavenly.
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    }

    // Penalize creating a gap that is too small for typical items (<= 10).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Open-bin pressure: more open bins -> prefer consolidation into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * (2.0 + 4.0 * progress);

    // Prefer bins whose residual is close to the item (tight fit relative measure).
    let tightness = (bin_residual - item_size) as f64 / bin_capacity as f64;
    score += tightness * 20.0;

    // Deviation from mean residual: prefer bins that are already fuller than average.
    score += (bin_residual as f64 - mean_residual) * 0.5;

    // Lookahead: if next item fits exactly in the post residual, reward this placement.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 80.0;
    }
    // If next item cannot fit in post residual, mild penalty (dead end for lookahead).
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 15.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base cost of opening a new bin.
        score += 100.0 + open_bins_count as f64 * 3.0;
        // If this is the only fitting option (i.e., no other bin fits), new bin is fine.
        if fitting_bins_count == 0 {
            score -= 250.0;
        }
        // Late in stream, opening bins is less harmful if residuals are fragmented.
        if mean_residual < 15.0 {
            score -= 40.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus: item exactly fills the bin.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual can
    // accommodate the next item, with extra reward for near-perfect chaining.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            // Reward the chain; tighter chains (small slack) get more reward.
            score -= 150.0 + (post_residual as f64) - slack;
            if slack == 0.0 {
                // Perfect 2-item chain: fill bin completely with two items.
                score -= 500.0;
            }
        } else {
            // Next item cannot follow in this bin: penalize leftover dead space,
            // scaled by how badly the chain fails.
            let overflow = (next_item_size - post_residual) as f64;
            score += overflow * 0.5;
        }
    }

    // Penalize bins whose residual deviates upward from the mean (fragmented bins).
    score += (post_residual as f64 - mean_residual).abs() * 0.3;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0 + (item_size as f64 / bin_capacity as f64) * 100.0;
    }

    // New-bin candidate: make opening a new bin attractive only for tiny items
    // into a fresh bin or when no good fit exists elsewhere.
    if bin_residual == bin_capacity {
        // Fresh bin has full residual: baseline penalty so it loses to good fits,
        // but its large raw residual keeps it competitive for large items.
        score += 120.0;
        // Prefer new bins late in the stream when many bins are open and fragmented.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= progress * 60.0 + open_bins_count as f64 * 2.0;
    }

    // Mild preference for tighter bins early (best-fit core), relax later.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - progress) * (post_residual as f64) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

