    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    } else if post_residual < 10 {
        score -= 15.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a new bin when open bins can fit the item,
    // but allow it when the leftover would be very small (tight fit logic above).
    if bin_residual == bin_capacity {
        score += 20.0;
        // Early in the stream, new bins are cheaper to open (more future items to fill them).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 15.0 * (1.0 - progress);
        // If many bins are open with large mean residual, discourage yet another bin.
        score += 0.05 * open_bins_count as f64;
        score += (mean_residual - cap * 0.5).max(0.0) * 0.3;
    }

    // Lookahead: if the next item would fit exactly in the post-residual,
    // keep this bin attractive; if next item is large and post-residual is dead space, penalize.
    if next_item_size > 0 {
