        if (post_residual as f64) >= nxt && (post_residual as f64) - nxt <= 10.0 {
            score -= 20.0; // leaves room for a near-exact next fit
        } else if post_residual > 0 && (post_residual as u32) < next_item_size && post_residual < 10 {
            score += 10.0 * (10.0 - post_residual as f64); // dead space penalty
        }
    }

    // Mild preference for filling bins that are already relatively full.
    let used_frac = 1.0 - (bin_residual as f64 / cap);
    score -= 10.0 * used_frac;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

