    // Smooth non-linear coupling of post_residual with progress
    let pr = post_residual as f64;
    let pr_norm = pr / bin_capacity as f64;
    let coupling = pr_norm * (0.5 + 0.5 * progress) * (1.0 - pr_norm);
    score += 20.0 * coupling;

    // Penalize small post_residual (dead space) more strongly later in the stream
    let dead = 1.0 - pr_norm;
    score -= 15.0 * dead * dead * (0.3 + 0.7 * progress);

    // Reward tight fits (small post_residual) especially when bin is a last chance
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - pr_norm);
