    // Lookahead: favor bins whose post_residual can fit the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= 10.0 * (nxt / bin_capacity as f64);
        } else {
            score += 8.0 * (1.0 - pr / nxt.max(1.0));
        }
    }

    // Mean residual context: prefer bins deviating below mean residual (tighter bins)
    let dev = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    score += 6.0 * dev * (0.5 + 0.5 * progress);

    // Mild penalty for opening new bins when many bins are open and fit exists
    if bin_residual == bin_capacity {
        score += 30.0 + 10.0 * (1.0 - progress) - 5.0 * (open_bins_count as f64).sqrt();
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
    }

    // Smooth sinusoidal progress modulation for fine-tuning
    score += 3.0 * (std::f64::consts::PI * progress).sin() * pr_norm;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: buckets by capacity fraction.
    // Residuals that are "dead" (too small for typical future items) are penalized.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let frac = post / cap; // 0..1

    // Dead-space class: residual < 10 can never be used (min item size 1..100 unknown,
    // but small residuals are low value). Penalize quadratically within low classes.
    if post_residual < 10 {
        score += 25.0; // fully dead slot
    } else if post_residual < 25 {
        score += 8.0;
    } else if post_residual < 50 {
        score -= 2.0;
    } else if post_residual < 75 {
        score -= 5.0;
    }

    // Integer-division harmonic classes on post_residual (mod arithmetic):
    // residuals that are exact multiples of common item sizes are more reusable.
    let pr = post_residual;
    if pr > 0 {
        let mut reuse_bonus = 0.0;
        for d in [10u32, 20, 25, 30, 40, 50] {
            if pr % d == 0 {
                reuse_bonus += 3.0;
            }
        }
        score -= reuse_bonus;
    }

    // Lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0; // perfect follow-up fit
        } else if next_item_size <= post_residual {
            // partial compatibility: reward proportional to how well it fills
            let fill = next_item_size as f64 / post as f64;
            score -= 12.0 * fill;
        } else {
            // next item cannot use this residual: slight penalty if residual is small
            score += 4.0 * (1.0 - frac);
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive when
    // existing bins are crowded. Compare this bin's residual to mean residual.
    if bin_residual == bin_capacity {
        // brand-new bin: baseline cost of consuming one more bin
        score += 15.0;
        // more attractive if open bins are nearly full on average
        score -= 10.0 * (mean_residual / cap);
        // during early stream, opening bins is cheap; late stream, prefer consolidation
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * (1.0 - progress);
        // if next item is large and no bin will hold it well, new bin is safer
        if next_item_size > 60 && next_item_size > post_residual.max(1) {
            score -= 10.0;
        }
    } else {
        // existing bin: reward filling it tightly (small post_residual already base score)
        let tightness = 1.0 - frac;
        score -= 10.0 * tightness;
        // prefer bins whose residual is close to item size (good fit, not wasteful)
        let waste = (bin_residual - item_size) as f64;
        score += 0.15 * waste;
    }

    // Mild global consolidation pressure: many open bins -> favor existing bins.
    if bin_residual < bin_capacity {
        score -= (open_bins_count as f64).min(20.0) * 0.3;
    }

    // Mean-residual coupling: if this bin is below average residual (relatively full),
    // it is a good consolidation target.
    let dev = (mean_residual - post) / cap;
    score -= 5.0 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
