        } else if gap <= 20.0 {
            score += 12.0 * (20.0 - gap) / 10.0;
        }
        // Non-linear tightening reward: quadratic bonus for very tight fits.
        score -= (bin_capacity as f64 - gap).powi(2) * 0.001;
    } else {
        // Perfect fill: strong reward.
        score -= 50.0;
    }

    // Open-bin pressure: discourage spreading across many bins,
    // but relax pressure late in the stream when consolidation matters less.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * (2.5 - 1.5 * progress);

    // Last-chance bonus: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive
    // when the current bin's fit is poor. Penalize the empty-bin candidate
    // (bin_residual == bin_capacity) moderately so tight fits win.
    if bin_residual == bin_capacity {
        score += 15.0;
        // But if no existing bin fits, the new bin is the only option:
        // neutralize penalty via fitting_bins_count == 0.
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
    }

    // Lookahead: if the next item fits exactly into the post_residual,
    // this placement sets up a perfect follow-up; reward it.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 30.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // Partial lookahead alignment: mild reward proportional to fit quality.
        score -= 8.0 * (next_item_size as f64 / post_residual as f64);
    }

    // Mean-residual coupling: prefer bins whose residual deviates favorably
    // from the mean — placing into below-mean-residual bins keeps large
    // residuals available for larger future items.
    if bin_residual < bin_capacity {
        let dev = mean_residual - bin_residual as f64;
        score += 0.15 * dev;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for exact 2-step match: item + next item fill the bin.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 1000.0;
    }

    // Reward when next item fits into the post residual (chained placement).
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack_after_next = (post_residual - next_item_size) as f64;
        score -= 60.0 * (1.0 - slack_after_next / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Next item won't fit: penalize leaving dead space relative to next item.
        let dead = (post_residual as f64 - (next_item_size as f64 - post_residual as f64).max(0.0)).max(0.0);
        score += 0.5 * dead;
    }

    // Prefer bins tighter than the mean residual (good fits), penalize loose bins.
    score += 0.8 * (post_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // Penalize creating tiny unusable residuals (below min plausible item size).
    if post_residual < 10 && post_residual > 0 {
        score += 40.0;
    }

    // Early in the stream, tolerate opening new bins less; late, consolidate.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize unless post_residual perfectly chains next item.
        score += 30.0 + 50.0 * progress;
        if next_item_size > 0 && next_item_size == post_residual {
            score -= 1000.0;
        }
    }

    // Slight preference to fill fuller bins when many bins are open.
    score -= 0.3 * open_bins_count as f64 * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let mut score = post;

    // Tight-fit reward: strongly favor bins where the item fills most of the residual.
    let fit_ratio = item / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Perfect-fit bonus (item exactly fills the bin).
    if post_residual == 0 {
        score -= 50.0;
    }

    // Penalize small dead space that is hard to reuse (post_residual in awkward range),
    // but tolerate large post_residual since it may fit future items.
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // Lookahead coupling: penalize if the next item cannot fit into the post residual,
    // reward if it fits snugly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if next_item_size > post_residual {
            score += 8.0;
        } else {
            let next_fit = nxt / post.max(1.0);
            score -= 6.0 * next_fit;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 + 0.3 * (bin_residual - item_size) as f64;
    }

    // Late in the stream, consolidate: prefer reusing existing bins over opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost grows with progress and with number of open bins.
        score += 10.0 + 25.0 * progress + 0.5 * open_bins_count as f64;
    } else {
        score -= 3.0 * progress;
    }

    // Prefer bins whose residual is below the mean (consolidate fuller bins),
    // spreading work across emptier bins early on.
    let dev = (bin_residual as f64 - mean_residual) / cap;
    if progress < 0.5 {
        score += 5.0 * dev;
    } else {
        score -= 5.0 * dev;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;

    // Non-linear polynomial core: post_residual coupled with stream progress
    let p = progress;
    let poly = norm_post * (1.0 + 0.8 * p * p + 0.6 * p * (1.0 - p));

    let mut score = poly * cap;

    // Reward tight fits (small post residual) more strongly as stream progresses
    score -= (1.0 - norm_post).powi(3) * (item_size as f64) * (0.3 + 0.7 * p);

    // Penalize dead space that is too small for typical future items
    if post > 0.0 && post < 10.0 {
        score += (10.0 - post) * (1.5 + 2.0 * p);
    }

    // Last chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0 * (1.0 + p);
    }

    // Lookahead: reward if next item fits in the resulting residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            score -= 12.0 * (1.0 - post / cap) * (0.5 + 0.5 * p);
        } else {
            // penalize residuals that waste space relative to next item
            score += (nxt - post).min(cap) * 0.15 * (1.0 + p);
        }
    }

    // New-bin candidate: prefer it only when open bins are nearly full on average
    if bin_residual == bin_capacity {
        let mean_gap = (cap - mean_residual) / cap;
        let pressure = (mean_gap * mean_gap) * (1.0 + 2.0 * p);
        score += 25.0 * (1.0 - pressure);
        // late stream: opening new bins is less attractive
        score += 15.0 * p;
    }

    // Mild penalty for many open bins to encourage consolidation
    score += open_bins_count as f64 * 0.05 * (0.5 + p);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residual mod 10 buckets.
    let pr = post_residual as i64;
    let r10 = pr % 10;
    // Dead-space penalty: residuals not in "nice" classes (0, 10, multiples of 5)
    if r10 == 0 {
        score -= 8.0;
    } else if r10 == 5 {
        score -= 4.0;
    } else if r10 <= 4 {
        score += (5 - r10) as f64 * 1.5; // small unusable sliver penalty
    }

    // Perfect fit reward
    if post_residual == 0 {
        score -= 30.0;
    }

    // Lookahead coupling: does post_residual match next item's harmonic class?
    if next_item_size > 0 {
        let ni = next_item_size as i64;
        if ni <= pr {
            // next item fits exactly or with nice class
            if pr - ni == 0 {
                score -= 25.0;
            } else if (pr - ni) % 10 == 0 {
                score -= 12.0;
            } else if (pr - ni) % 5 == 0 {
                score -= 6.0;
            }
        } else {
            // next item won't fit here: mild penalty scaled by gap
            score += ((ni - pr) as f64).min(20.0) * 0.3;
        }
        // integer-division threshold: post_residual / next_item_size
        if ni > 0 {
            let k = pr / ni;
            if k >= 2 {
                score -= 3.0 * k as f64; // room for multiple future items
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: neutral-ish baseline, penalize opening bins
    // early in the stream or when good fits exist.
    if bin_residual == bin_capacity {
        score += 20.0;
        if open_bins_count == 0 {
            score -= 100.0; // must open first bin
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // large next item: fresh bin attractive
        }
        if fitting_bins_count == 1 {
            score -= 12.0; // only this bin fits -> don't open new
        }
    }

    // Mean residual coupling: prefer bins whose residual deviates toward item size
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    // Progress term: later in stream, be greedier about tight fits
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= (post_residual as f64) * 0.15 * progress;

    // Prefer filling larger-residual bins when many bins open (bin count control)
    score += (open_bins_count as f64) * 0.4 - (bin_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the minimum item (1) are fine,
    // but residuals that can't fit the NEXT item are dead space.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            // unusable for lookahead -> penalize proportionally to how close it is to being usable
            let gap = (next_item_size - post_residual) as f64;
            score += 3.0 * gap;
        } else {
            // reward a residual that can still host the next item, scaled by slack
            score -= 2.0 * (next_item_size as f64 / (post_residual as f64 + 1.0));
        }
    }

    // Penalize small residual gaps that are likely dead space under unknown distributions:
    // residuals in (0, 10) are almost unusable if min size were 10; be adaptive instead:
    // treat residuals below half of current item as increasingly dead.
    if post_residual > 0 && post_residual < item_size {
        score += 1.5 * (item_size - post_residual) as f64;
    }

    // Perfect fit reward
    if post_residual == 0 {
        score -= 10.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 5.0;
    }

    // Open bins pressure: penalize placements that leave large residuals when many bins are open
    let pressure = open_bins_count as f64 / (open_bins_count as f64 + 5.0);
    score += pressure * (post_residual as f64 / bin_capacity as f64) * 6.0;

    // New-bin candidate handling: only attractive when open bins fit poorly or mean residual is tiny
    if bin_residual == bin_capacity {
        let mean_fit = if next_item_size > 0 && mean_residual >= next_item_size as f64 { 1.0 } else { 0.0 };
        // make new bin costly unless nothing fits well
        let poor_alternatives = (fitting_bins_count as f64).min(3.0);
        score += 8.0 - 4.0 * (1.0 - mean_fit) - poor_alternatives;
        // early in stream, new bins are cheaper
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 2.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: extremely strong reward.
    if post_residual == 0 {
        score -= 1000.0;
        return score;
    }

    // 2-step lookahead: reward when post_residual exactly accommodates next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 400.0;
        } else if post_residual >= next_item_size {
            // Reward proportionally to how snugly next item fits.
            let slack = (post_residual - next_item_size) as f64;
            score -= 250.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Post residual too small for next item: penalize dead space.
            score += 60.0;
        }

        // Chain fit: residual + next item's leftover usable for nothing -> penalize.
        if post_residual < next_item_size && post_residual < 10 {
            score += 40.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: only attractive when existing bins would waste a lot.
    if bin_residual == bin_capacity {
        // Baseline penalty so new bins are used only when better than bad fits.
        score += 120.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 80.0; // fresh bin still leaves room for lookahead item
        }
        // Late in stream, prefer filling existing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 100.0 * progress;
    }

    // Penalize leaving residuals below the minimum item size (dead space),
    // scaled by how much below the typical residual it is.
    if post_residual > 0 && post_residual < 10 {
        score += 200.0;
    }

    // Relative to mean residual: prefer bins that become closer to the mean
    // (balanced packing), slight effect.
    let post_f = post_residual as f64;
    score += 0.3 * (post_f - mean_residual).abs();

    // Prefer fuller bins (smaller residual before placement) mildly.
    score += 0.2 * (bin_residual as f64 - post_f);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer perfect / near-perfect fits
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual < 10 {
        score -= 200.0;
    }

    // Penalize dead space relative to the smallest possible future item (1..100 unknown, use 10 as soft floor)
    let waste = post_residual as f64 / 10.0;
    score += waste * waste * 0.5;

    // Lookahead: reward bins whose post-residual can host the next item exactly or well
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 60.0 - slack.min(60.0);
            if post_residual == next_item_size {
                score -= 300.0;
            }
        } else {
            // next item cannot use this bin's leftover: penalize proportionally
            score += 15.0 + (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: only attractive when current residuals are fragmented
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = (mean_residual - post_residual as f64).abs();
        // Prefer new bin late in stream or when mean residual is small (poor fits elsewhere)
        let bias = 40.0 + 80.0 * progress + (mean_residual / bin_capacity as f64) * 50.0;
        score += bias - fragmentation * 0.2;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 30.0;
        }
    }

    // Mild preference for filling bins that are already mostly full
    let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= fill_ratio * 20.0;

    // Tie-break with open bin count: consolidate when many bins are open
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr as f64;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 - norm_pr);
    score += 40.0 * poly * (progress - 0.5);

    // Penalize large post residual late in the stream (wasted capacity)
    score += 10.0 * norm_pr * norm_pr * progress;

    // Reward tight fits (small post residual) more strongly as stream advances
    score -= 8.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * progress;

    // Last-chance bin bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - 0.5 * progress);
    }

    // Lookahead: reward residual that can accommodate next item
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        if pr >= ns {
            let fit_frac = ns / pr.max(1.0);
            score -= 12.0 * fit_frac * (1.0 - fit_frac) * 4.0;
        } else {
            score += 6.0 * (ns - pr) / cap;
        }
    }

    // Deviation from mean residual: prefer bins diverging from the pack average
    let dev = (pr - mean_residual) / cap;
    score += 5.0 * dev * dev * dev.signum();

    // New-bin candidate: penalize mildly, relax early in stream
    if bin_residual == bin_capacity {
        score += 3.0 + 15.0 * progress;
    }

    // Slight pressure to consolidate when many bins are open
    score += 0.05 * open_bins_count as f64 * (1.0 - norm_pr);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues modulo 10 create "dead space" classes.
    // Small post-residuals that are NOT reusable (residue < 10, i.e. below min item size)
    // are pure waste; larger reusable residuals are less penalized.
    let waste = if post_residual < 10 { post_residual as f64 * 3.0 } else { 0.0 };
    score += waste;

    // Harmonic coupling: post_residual that exactly matches next_item_size is golden.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    }
    // Post-residual class can hold next item with tight fit (within one harmonic band)
    if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size < 5 {
        score -= 25.0;
    }
    // Penalize post-residuals in awkward mid-bands (31..60) that waste capacity
    if post_residual >= 31 && post_residual <= 60 {
        score += 6.0;
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: neutral-ish, slightly penalized so good fits win,
    // but attractive when existing residuals are fragmented.
    if bin_residual == bin_capacity {
        score = 55.0 + 0.15 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 8.0; // reserving a fresh bin for large follow-ups is fine
        }
        if fitting_bins_count > 0 && mean_residual > item_size as f64 * 1.5 {
            score -= 10.0; // existing bins have room; discourage new bin
        }
        return score;
    }

    // Tight fit reward: fill fraction of the consumed space.
    let fill = item_size as f64 / bin_residual as f64;
    score -= 20.0 * fill * fill;

    // Prefer bins whose residual is in the same harmonic class as the item.
    if bin_residual % 10 == item_size % 10 {
        score -= 5.0;
    }

    // Slight preference for bins with below-mean residual (consolidate emptier bins).
    score += 0.05 * (bin_residual as f64 - mean_residual);

    // Late in stream: prioritize closing bins tightly.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * fill;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps (< 10) are nearly useless.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (1.0 - post_residual as f64 / 10.0);
    }
    // Perfect fit is heavily rewarded.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward placements that leave room for the lookahead item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }
    // Penalize if post_residual is small but nonzero and cannot fit next item (dead space).
    if next_item_size > post_residual && post_residual > 0 {
        score += post_residual as f64 * 0.5;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, discourage new-bin creation.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 + 2.0 * open_bins_count as f64 + 30.0 * (1.0 - progress);
    } else {
        // Slight preference for fuller bins.
        score -= (bin_capacity - bin_residual) as f64 * 0.05;
    }

    // Coupling with mean residual: if this bin is much emptier than average, deprioritize slightly.
    score += (mean_residual - bin_residual as f64).max(0.0) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward when post_residual exactly matches next item (2-step lookahead).
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 60.0 * (1.0 - diff / bin_capacity as f64).max(0.0);
        // Penalize leaving residual too small for next item (dead space).
        if post_residual < next_item_size {
            score += 0.5 * (next_item_size - post_residual) as f64;
        }
    }

    // Prefer bins tighter than mean residual.
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Last-chance bin bonus: avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate: penalize unless current bins are badly fragmented.
    if bin_residual == bin_capacity {
        score += 20.0 - 0.2 * mean_residual;
    }

    // Late in stream, pack tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.2 * post_residual as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post residual gets a strong bonus.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= 30.0 * (-fit_ratio * 6.0).exp();

    // Penalize dead space that cannot fit the next item (lookahead k=2).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Residual is reusable by the next item: reward proportionally.
            score -= 8.0 * (post_residual as f64 - next_item_size as f64 + 1.0).ln().max(0.0);
        } else {
            // Dead space relative to lookahead: penalize.
            let gap = (next_item_size - post_residual) as f64;
            score += 6.0 * gap / bin_capacity as f64 * 10.0;
        }
    }

    // Last-chance bin: strong reward to use it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize opening new bins when many bins are already open but underused.
    if bin_residual == bin_capacity {
        let avg_fill = 1.0 - mean_residual / bin_capacity as f64;
        let pressure = open_bins_count as f64 / (step_index as f64 + 1.0);
        score += 20.0 + 15.0 * avg_fill + 10.0 * pressure;
        // Early in the stream, new bins are cheaper; late, very expensive.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 25.0 * progress;
    }

    // Slight preference for bins with residuals above the mean (keeps small bins for small items).
    if bin_residual as f64 > mean_residual {
        score -= 2.0;
    } else {
        score += 2.0;
    }

    // Mild time-horizon coupling: encourage consolidation as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (1.0 - fit_ratio);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post residual, with non-linear shaping
    let mut score = pr * (1.0 + 0.5 * norm_pr * norm_pr);

    // Smooth coupling with stream progress: later in stream, penalize waste more
    score += 20.0 * norm_pr * norm_pr * (progress * (1.0 - progress) * 4.0 + 0.25);

    // Reward tight fits: quadratic bonus when post_residual is small
    let tight = 1.0 - norm_pr;
    score -= 15.0 * tight * tight * tight;

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Lookahead: if next item fits exactly in post residual, big reward
    if next_item_size > 0 {
        let diff = (pr - next_item_size as f64).abs();
        score -= 12.0 * (1.0 - diff / cap).max(0.0);
        // penalize post residual too small for next item (dead space)
        if pr < next_item_size as f64 {
            score += 5.0 * (next_item_size as f64 - pr) / cap;
        }
    }

    // Mild penalty for many open bins to encourage consolidation
    score += open_bins_count as f64 * 0.05 * (1.0 + progress);

    // Mean residual coupling: prefer bins near the mean residual (balance)
    let dev = (pr - mean_residual) / cap;
    score += 4.0 * dev * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of the residual (capacity fraction / modulo logic) ---
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Dead-space penalty: residuals too small for the smallest item (1..=10)
    if post_residual < 10 {
        score += 30.0;
    } else if post_residual < 20 {
        score += 12.0;
    }

    // Perfect-fit classes: post_residual in {0, 10, 20, 25, 50} are highly reusable
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual % 10 == 0 {
        score -= 15.0;
    } else if post_residual % 5 == 0 {
        score -= 6.0;
    }

    // Modulo-4 harmonic class: residuals divisible by 4 tile better with
    // common small item sizes; slight reward per class alignment.
    if post_residual % 4 == 0 {
        score -= 3.0;
    } else if post_residual % 2 == 0 {
        score -= 1.0;
    }

    // Integer-division thresholds on post_residual: mid-range residuals
    // (25..=60) are the most flexible "harmonic band".
    let band = post_residual / 25; // 0,1,2,3,4
    match band {
        1 => score -= 8.0,               // 25..49: sweet spot
        2 => score -= 5.0,               // 50..74
        3 => score -= 2.0,               // 75..99
        _ => {}                          // 0 (dead) or 4 (near-full) neutral
    }

    // --- Lookahead coupling (k=2): does the next item fit the post-residual? ---
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Next item lands here: strong reward, scaled by tightness of fit
            let slack = (post_residual - next_item_size) as f64;
            score -= 20.0 + 10.0 * (1.0 - slack / cap);
        } else {
            // Next item won't fit here: penalize proportional to overshoot class
            let overshoot = (next_item_size - post_residual) as f64;
            score += 4.0 + overshoot / 20.0;
        }
    }

    // --- Last-chance bin logic ---
    if fitting_bins_count == 1 && bin_residual >= item_size {
        // Only bin that fits: avoid opening a new bin
        score -= 25.0;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Fresh bin: attractive early, or when open bins are fragmented.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = (mean_residual - pr) / cap.max(1.0);
        score -= 10.0 + 15.0 * fragmentation.clamp(0.0, 1.0) + 10.0 * (1.0 - progress);
        // But discourage when a decent existing residual exists
        if mean_residual > item_size as f64 && open_bins_count > 0 {
            score += 8.0;
        }
    } else {
        // Mild penalty for leaving residual far from mean (keeps bins homogeneous)
        score += ((pr - mean_residual).abs() / cap) * 5.0;
    }

    // Stream-progression: tighten packing as stream advances (prefer tight fits late)
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += pr * (0.05 + 0.15 * progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny gaps (1..=12) are nearly unusable
    // for future items (sizes 1..100, typically >=10); penalize them hard.
    if post_residual > 0 && post_residual <= 12 {
        score += 60.0 * (1.0 - post_residual as f64 / 12.0) + 15.0;
    } else if post_residual > 12 && post_residual < 20 {
        // medium-small gaps: mild penalty
        score += 8.0;
    }

    // Perfect fit: heavily reward zero residual.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Reward leaving room for the lookahead item (k=2 lookahead).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 10.0; // gap too small for the known next item
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading;
    // with few open bins, slightly favor filling existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 / (1.0 + mean_residual / 20.0);
    score += pressure * (0.5 + 0.5 * progress) * 2.0;

    // New-bin candidate: residual == capacity. Make it attractive only
    // when the item fits poorly everywhere else; default mild penalty.
    if bin_residual == bin_capacity {
        score += 18.0;
        if fitting_bins_count == 0 {
            score -= 100.0; // nothing else fits: must open new bin
        }
        if next_item_size > 0 && item_size + next_item_size > bin_capacity {
            score -= 20.0; // big pair incoming, fresh bin is fine
        }
    }

    // Slight preference for bins whose residual is already small
    // (consolidate waste into few bins).
    score += (bin_residual as f64 - mean_residual) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size -> strong reward
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Near match: next item fits with small slack -> graded reward
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 * (1.0 - slack / bin_capacity as f64).max(0.0);
    } else if next_item_size > 0 {
        // Next item won't fit: penalize creating a dead residual smaller than the
        // smallest conceivable next item
        let dead = post_residual as f64;
        if dead < 10.0 {
            score += 30.0 * (10.0 - dead);
        }
    }

    // Compare post_residual against the mean residual of open bins:
    // leaving less than average waste is good
    let prog = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 8.0 * (mean_residual - post_residual as f64) * (0.5 + prog);

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0 + 15.0 * prog;
    }

    // Penalize opening a new bin when open bins could still hold future items comfortably
    if bin_residual == bin_capacity {
        // new-bin candidate: base cost plus pressure from many open bins
        score += 15.0 + 2.0 * open_bins_count as f64;
        // but if this is the last chance, allow the new bin
        if fitting_bins_count == 1 {
            score -= 40.0;
        }
        // if next item is large, a fresh bin is attractive
        if next_item_size >= 60 {
            score -= 10.0;
        }
    }

    // Tight fits (small post residual) are generally desirable
    score -= 10.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Tight-fit reward: the more of the bin the item consumes, the better.
    let fill_fraction = item_size as f64 / cap;
    score -= 12.0 * fill_fraction * fill_fraction;

    // Dead-space penalty: leftover space that cannot fit the lookahead item.
    if next_item_size > 0 && post_residual < next_item_size {
        let waste = (next_item_size as f64 - pr).max(0.0);
        score += 8.0 + 0.6 * waste;
    }
    // Perfect lookahead coupling: next item exactly fills this bin.
    if next_item_size > 0 && next_item_size as f64 == pr {
        score -= 20.0;
    }
    // Partial lookahead coupling: next item fits snugly (residual < 60% of next).
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = pr - next_item_size as f64;
        score -= 6.0 * (1.0 - slack / cap).max(0.0);
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it.
    let is_new_bin = bin_residual == bin_capacity;
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin, but less when the item is large
    // (a fresh bin with a big item leaves a well-shaped residual) or when existing
    // bins are fragmented (high mean residual relative to capacity).
    if is_new_bin {
        let fragmentation = (mean_residual / cap).clamp(0.0, 1.0);
        let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 45.0
            - 0.25 * item_size as f64
            - 15.0 * fragmentation
            - 5.0 * t;
        // Never open a new bin for a tiny item when many bins are open.
        if item_size < 30 && open_bins_count > 2 {
            score += 20.0;
        }
    }

    // Mild late-stream conservatism: late in the stream, tighten preference for
    // exact fits to avoid stranding residual capacity.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 3.0 * t * (pr / cap);

    // Crowd factor: with many open bins, favor consolidating into existing ones
    // (implicitly favors any open bin over the new-bin candidate).
    if !is_new_bin {
        score -= 0.05 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_ratio = item_size as f64 / cap;
    let norm_pr = pr / cap;

    // Base: prefer small post-residual, with non-linear (quadratic) penalty growth.
    let mut score = pr as f64 * (1.0 + 0.8 * norm_pr * norm_pr);

    // Smooth coupling: tight fits matter more as stream progresses.
    score -= 12.0 * fit_ratio * (1.0 - fit_ratio) * (1.0 + progress);

    // Penalize large residual waste non-linearly (dead space).
    score += 6.0 * norm_pr * norm_pr * (0.5 + progress);

    // Last-chance bonus: strongly favor the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 * (1.0 + progress);
    }

    // Lookahead: reward leaving residual that fits the next item (smooth kernel).
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        let diff = pr - next_item_size as f64;
        score -= 8.0 * (1.0 - diff / cap) * (1.0 + 0.5 * progress);
    } else if next_item_size > 0 {
        // Smooth penalty for residual too small for next item.
        let gap = (next_item_size as f64 - pr) / cap;
        score += 5.0 * gap * gap;
    }

    // New-bin candidate: prefer it early or when all open bins are tight.
    if bin_residual == bin_capacity {
        let tightness = (mean_residual / cap).max(0.0);
        score = pr as f64 - 15.0 * (1.0 - progress) * (1.0 - tightness)
            + 20.0 * progress * tightness;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual).
    score = post_residual as f64 * 1.0;

    // Harmonic class of post_residual: residue classes modulo 10.
    // Residuals that are "usable" by typical small items (multiples of 10)
    // are rewarded; awkward residues (1..9 offsets) are penalized.
    let pr = post_residual;
    let residue_class = (pr % 10) as f64;
    if pr > 0 {
        score += residue_class * 0.8;
    }

    // Integer-division thresholds on post_residual: classify dead space.
    if pr >= 50 {
        // Half-empty bin: still very reusable, mild reward.
        score -= 6.0;
    } else if pr >= 30 {
        score -= 2.0;
    } else if pr >= 10 {
        score += 1.5;
    } else if pr > 0 {
        // Tiny sliver: dead space penalty.
        score += 8.0 + (10 - pr) as f64 * 0.5;
    }

    // Perfect fill is ideal.
    if pr == 0 {
        score -= 20.0;
    }

    // Lookahead coupling: does next_item_size fit the post_residual exactly?
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 15.0; // perfect chain
        } else if next_item_size <= pr {
            // How well does the next item use the leftover? Harmonic fraction.
            let fill_frac = next_item_size as f64 / pr as f64;
            score -= 6.0 * fill_frac;
            // Reward when next item leaves another multiple-of-10 residual.
            let next_post = pr - next_item_size;
            if next_post % 10 == 0 {
                score -= 3.0;
            }
        } else {
            // Next item cannot use this bin's leftover: penalize proportionally
            // to how stranded the leftover is.
            score += 4.0 * (pr as f64 / cap);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: only open a new bin when the current item
    // is large relative to capacity and no good fit exists.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // New bin baseline: moderate score; beat it only if fits are terrible.
        score = cap * 0.45;
        if post_residual <= 20 {
            // Opening a new bin with a big item wastes little: attractive.
            score -= 5.0;
        }
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 4.0 * progress;
        // Many open bins: discourage adding more.
        score += (open_bins_count as f64).sqrt() * 1.5;
    }

    // Mean-residual coupling: if the fleet average residual is high,
    // prefer bins that bring the average down (tight placement).
    score -= 0.05 * (mean_residual - post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that no plausible item (>=1) can use well.
    if post_residual > 0 {
        // Small gaps (< 10) are almost certainly dead space -> heavy penalty.
        if post_residual < 10 {
            score += 60.0;
        } else {
            // Dead-space pressure grows superlinearly for mid-size leftovers
            // that are hard to fill (relative to capacity).
            let frac = post_residual as f64 / bin_capacity as f64;
            score += 25.0 * frac * frac;
        }
    } else {
        // Perfect fit: strong reward.
        score -= 100.0;
    }

    // Reward using a bin tightly: residual closer to item size is better.
    score -= (item_size as f64 / bin_capacity as f64) * 10.0;

    // Last chance: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: prefer spreading across fewer bins when many are open.
    score += open_bins_count as f64 * 0.5;

    // Lookahead: if the next item fits exactly in the post-residual, reward;
    // if next item would fit better elsewhere, slight penalty.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 50.0;
        } else if next_item_size > post_residual {
            score += 8.0;
        } else {
            let waste = post_residual - next_item_size;
            if waste < 10 { score += 20.0 * (1.0 - waste as f64 / 10.0); }
        }
    }

    // Prefer bins with below-mean residual (tighter bins get filled first),
    // keeping looser bins flexible.
    score += (bin_residual as f64 - mean_residual) * 0.3;

    // Late in the stream, consolidation matters more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * post_residual as f64 * 0.5;

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 80.0;
        } else {
            // Discourage opening a new bin when existing bins can fit;
            // but allow it if all fits would leave large dead space.
            let best_gap = (bin_residual - item_size) as f64;
            score += 30.0 - best_gap * 0.2;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size -> strong reward
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // If the next item also fits in the leftover space, reward proportionally
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 20.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Dead space the next item cannot use: penalize small unusable leftovers hard
        let waste = post_residual as f64;
        if waste < 10.0 {
            score += 15.0 * (10.0 - waste);
        }
    }

    // Reward tighter fits relative to mean residual of open bins
    score -= (bin_residual as f64 - mean_residual).max(-50.0).min(50.0) * 0.15;

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Mild preference for keeping few open bins
    score += open_bins_count as f64 * 0.5;

    // New-bin candidate: neutral-ish baseline so it wins only over bad fits
    if bin_residual == bin_capacity {
        score = 55.0 + post_residual as f64 * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: penalize large post_residual, especially small leftovers that are dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0; // tiny slivers are nearly unusable
    } else if post_residual >= 10 && post_residual < 20 {
        score += 2.0;
    }

    // Perfect fill bonus
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Lookahead: if next item fits exactly in the post residual, reward heavily.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 12.0;
        } else if next_item_size > post_residual && next_item_size <= bin_residual {
            // next item would fit here now but not after placement -> penalize
            score += 6.0;
        }
        // If next item is large, prefer conserving residual space.
        if next_item_size >= 50 && post_residual < next_item_size {
            score += 3.0;
        }
    }

    // Time horizon: early in stream, be more conservative (prefer tight fits to keep options open);
    // late in stream, accept looser fits to avoid opening new bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let openness = 1.0 - progress;
    score += openness * (post_residual as f64) * 0.3;

    // Global state: many open bins with high mean residual -> prefer filling existing bins.
    if open_bins_count > 2 {
        score -= (open_bins_count as f64).ln() * 1.5;
        if mean_residual > item_size as f64 * 1.5 {
            score -= 4.0;
        }
    }

    // New-bin candidate: penalize opening a new bin unless current fit is terrible
    // or no open bin fits well (this call has full residual).
    if bin_residual == bin_capacity {
        let waste = bin_capacity - item_size;
        score += 20.0; // base cost of a new bin
        if fitting_bins_count == 0 {
            score -= 30.0; // must open new bin
        } else if waste > 40 && progress > 0.2 {
            score -= 10.0; // poor fits elsewhere justify a new bin
        }
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post residual, with non-linear polynomial shaping
    let mut score = pr * (1.0 + 0.5 * norm_pr * norm_pr);

    // Smooth coupling: dead space penalized more as stream progresses
    let dead = norm_pr * norm_pr;
    score += 30.0 * dead * (progress * progress * (3.0 - 2.0 * progress));

    // Reward tight fits (small post residual) smoothly
    let tight = 1.0 - norm_pr;
    score -= 8.0 * tight * tight * tight;

    // Last-chance bonus: strongly favor this bin if it's the only fitting one
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Lookahead: if next item fits the post residual, reward this placement
    if next_item_size > 0 {
        let fits_next = if (post_residual as u32) >= next_item_size { 1.0 } else { 0.0 };
        let coupling = 1.0 - (post_residual as f64 - next_item_size as f64).abs() / cap;
        score -= 12.0 * fits_next * coupling.max(0.0);
    }

    // Mild penalty when many bins are open (encourage consolidation)
    score += 0.3 * (open_bins_count as f64).ln().max(0.0);

    // Deviation from mean residual: prefer bins with residuals close to mean
    let dev = (pr - mean_residual).abs() / cap;
    score += 4.0 * dev * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let pr = post_residual as i64;
    let cap = bin_capacity as f64;

    // Perfect fit: strong reward
    if pr == 0 {
        score -= 60.0;
    }

    // Harmonic dead-space classes: tiny unusable residues are penalized
    if pr > 0 && pr < 10 {
        score += 18.0; // dead space class (1..9)
    } else if pr >= 10 && pr < 20 {
        score += 6.0; // marginal class
    }

    // Modulo-10 harmonic class of post_residual: prefer residues that are
    // multiples of 10 (likely to combine with typical item sizes)
    score += ((pr % 10) as f64) * 0.25;

    // Lookahead (k=2): reward if next item fits into post_residual,
    // scaled by how tightly it fits
    if next_item_size > 0 && (next_item_size as i64) <= pr {
        score -= 10.0 + (pr - next_item_size as i64) as f64 * 0.35;
    }
    // Next item won't fit here and residue is small -> penalize stranded space
    if next_item_size > 0 && (next_item_size as i64) > pr && pr < 20 {
        score += 12.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate handling: mildly penalize opening a new bin unless
    // the item is large (good utilization of a fresh bin)
    if bin_residual == bin_capacity {
        let big_item_bonus = (item_size as f64 / cap) * 20.0;
        score += 14.0 - big_item_bonus;
    }

    // Coupling with mean residual: prefer bins below the mean residual
    // (tighter bins get priority), keeping balance across open bins
    score += (mean_residual - bin_residual as f64) * 0.15;

    // Late-stream pressure: as the stream progresses, tighten selection
    // to avoid wasting capacity near the end
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 - 0.12 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for even the
    // smallest conceivable future item are "dead space" -> heavy penalty.
    let min_useful = 10u32.min(bin_capacity); // smallest plausible item footprint
    if post_residual > 0 && post_residual < min_useful {
        score += 60.0; // unusable sliver
    } else if post_residual < item_size.min(20) && post_residual > 0 {
        // gap likely too small for typical next items: moderate penalty
        score += 25.0;
    }

    // Reward tight fits strongly (low post_residual relative to item size).
    if item_size > 0 {
        let tightness = 1.0 - (post_residual as f64 / bin_residual.max(1) as f64);
        score -= 40.0 * tightness * tightness;
    }

    // Perfect fit: complete elimination of the residual.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post residual,
    // this placement is excellent.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 70.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 && next_item_size <= bin_residual && post_residual < next_item_size {
        // next item would no longer fit here after this placement -> slight penalty
        score += 10.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 55.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, favor consolidation.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += 6.0 * pressure * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate handling: an empty bin has maximal residual; only allow it
    // when no open bin offers a decent fit (post_residual small) or bins are crowded.
    if bin_residual == bin_capacity {
        let decent_fit_exists = post_residual == 0 || (mean_residual > 0.0 && mean_residual > item_size as f64 * 1.2);
        if decent_fit_exists && open_bins_count > 0 {
            score += 90.0; // keep using open bins with usable residual
        } else {
            score -= 20.0; // opening fresh space is reasonable
        }
        // Early in the stream, opening bins is cheap and builds flexible inventory.
        if step_index as f64 / (total_items.max(1) as f64) < 0.2 {
            score -= 25.0;
        }
    }

    // Mild global preference for bins with residual close to the mean (balance workload).
    score += 0.15 * (bin_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
