pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual relative to capacity.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - tightness) * 15.0;

    // Penalize dead space that cannot fit the next item (lookahead-aware).
    if next_item_size > 0 {
        if post_residual < next_item_size {
            // Wasted residual: penalize proportional to unusable space.
            let waste = next_item_size - post_residual;
            score += waste as f64 * 0.6;
        } else {
            // Residual can host the next item: reward.
            let slack = post_residual - next_item_size;
            score -= slack as f64 * 0.25;
        }
    }

    // Perfect fill bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Exact fit for next item bonus.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 20.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate handling: prefer existing bins unless the item fits
    // very poorly everywhere. Penalize opening a new bin mildly, scaled by
    // how many open bins already exist (encourage consolidation early).
    if bin_residual == bin_capacity {
        score += 30.0 + (open_bins_count as f64).sqrt() * 5.0;
    }

    // Global state: if mean residual is large, we have slack capacity overall;
    // prefer filling bins with large residuals less aggressively (keep them
    // flexible), so add a term pushing toward bins with residual near mean.
    let resid_gap = (bin_residual as f64 - mean_residual).abs();
    score += resid_gap * 0.15;

    // Time horizon: as the stream progresses, be greedier about closing bins
    // (favor tight fits more), since fewer future items remain to use slack.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - tightness) * 10.0 * progress;

    // Penalize bins whose residual becomes awkwardly small but nonzero
    // (fragmentation zone: 1..=9 unusable for typical item sizes).
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Mild preference for bins with larger residual when item is small
    // (preserve tight bins for larger future items).
    if item_size < 30 {
        score += (bin_capacity - bin_residual) as f64 * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;

    // Base: quadratic waste penalty on post residual, modulated by stream progress
    let mut score = norm_post * (1.0 + 1.5 * norm_post) * (0.5 + progress);

    // Non-linear coupling: prefer residuals that exactly fit the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (post - nxt).abs() / cap;
        score -= 2.0 * (1.0 - gap.min(1.0)) * (1.0 - progress);
        // penalize leaving residual that is small but unusable for next item
        if post < nxt && post > 0.0 {
            score += 1.2 * (1.0 - post / nxt.max(1.0)) * (0.4 + progress);
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 3.0 * (1.0 - norm_post);
    }

    // New-bin candidate: penalize opening new bins unless current item is large
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / cap;
        score = 2.5 - 1.8 * fill_ratio + 1.5 * progress * (open_bins_count as f64 / 20.0);
        // allow new bin late in stream when open bins are nearly full on average
        if mean_residual < item_size as f64 {
            score -= 1.0;
        }
    }

    // Mild penalty proportional to deviation from mean residual (spread control)
    score += 0.3 * ((post - mean_residual).abs() / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space quality by residue class mod 10
    let class = post_residual % 10;
    let class_penalty = match class {
        0 => -6.0,   // perfectly divisible residual -> reusable
        5 => -3.0,   // half class still usable
        2 | 4 | 6 | 8 => -1.5,
        _ => 1.5,    // odd primes-ish residuals are awkward
    };
    score += class_penalty;

    // Integer division thresholds: how many "small items" (<=10) fit in post residual
    let fits_small = post_residual / 10;
    score -= (fits_small as f64) * 2.0;

    // Reward tight fits: post_residual small relative to item size
    let tightness = (item_size as f64) / (bin_residual as f64).max(1.0);
    score -= tightness * 8.0;

    // Lookahead coupling: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 10.0 - slack * 0.15;
        } else {
            // next item cannot use this residual: penalize proportionally
            score += ((next_item_size - post_residual) as f64) * 0.08;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening new bins unless existing fit is terrible
    if bin_residual == bin_capacity {
        score += 20.0 + mean_residual * 0.3 + (open_bins_count as f64) * 0.5;
        // allow new bin early in stream or when nothing fits well
        if post_residual < bin_capacity as f64 * 0.5 {
            score -= 10.0;
        }
    }

    // Mean residual alignment: prefer bins close to mean residual (balanced packing)
    score += ((post_residual as f64) - mean_residual).abs() * 0.05;

    // Progress-based drift: later in stream, be more conservative with new bins
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score += progress * 15.0;
    }

    // Capacity fraction classes of bin_residual
    let frac = (bin_residual as f64) / (bin_capacity as f64);
    if frac > 0.75 {
        score -= 2.0; // large residual bins are flexible, favor them slightly
    } else if frac < 0.15 && post_residual > 0 {
        score += 3.0; // nearly-full bins: avoid creating tiny dead slivers
    }

    // Modulo threshold on item_size: items in awkward classes (e.g. 17,23,...) leave bad gaps
    if item_size % 7 == 0 {
        score -= 1.0;
    }
    if post_residual % 7 == 3 || post_residual % 7 == 1 {
        score += 1.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that no item (min size 1, practically >= 10)
    // can use are pure waste. Penalize tiny unusable gaps harshly.
    if post_residual == 0 {
        // Perfect fit: strongly reward.
        score -= 500.0;
    } else if post_residual < 10 {
        // Dead space below the smallest item size: heavily penalize.
        score += 200.0 + (10 - post_residual) as f64 * 20.0;
    } else if post_residual >= 10 && post_residual < 20 {
        // Marginal gap: only usable by very small items; mild penalty.
        score += 30.0;
    } else {
        // Usable gap: reward proportional to size.
        score -= 10.0;
    }

    // Lookahead coupling: if next item fits exactly in the post residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 150.0;
        } else if next_item_size <= post_residual {
            score -= 40.0;
        } else {
            // Next item won't fit here: the remaining gap risks becoming dead space.
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 80.0;
    }

    // Open-bin pressure: prefer using existing bins over opening new ones.
    score += open_bins_count as f64 * 2.0;

    // New-bin candidate handling: an empty bin has no scarcity; make it a fallback.
    if bin_residual == bin_capacity {
        // Slight penalty so open bins with decent fits win; but if all open bins
        // would create dead space, the above penalties make the new bin attractive.
        score += 25.0;
        // Early in the stream, opening bins is cheaper (more future items to fill them).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 30.0 * (1.0 - progress);
    }

    // Prefer bins whose residual is already below the mean (consolidating waste).
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Aggressive 2-step lookahead matching ---
    // Strongly reward bins whose post_residual closely matches the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (post_residual as f64 - nxt).abs();
        // Perfect match: next item exactly fills the bin -> huge bonus.
        if post_residual as f64 == nxt {
            score -= 60.0;
        } else if post_residual >= next_item_size {
            // Next item fits: reward tightness of the match.
            score -= 25.0 * (1.0 - diff / (bin_capacity as f64));
        } else {
            // Next item does NOT fit: penalize leftover that is too small to reuse.
            let waste = nxt - post_residual as f64;
            score += 0.8 * waste;
        }
        // Slight preference for leaving room >= next item vs. slightly below.
        if post_residual as f64 >= nxt {
            score -= 3.0;
        }
    } else {
        // Last item: pure waste minimization, tightest fit wins.
        score -= 10.0;
    }

    // --- Relative-to-mean-residual coupling ---
    // Prefer bins that are already fuller than average (tight packing),
    // penalize bins with unusually large residuals (fragmentation risk).
    let res = post_residual as f64;
    if res < mean_residual {
        score -= 0.5 * (mean_residual - res);
    } else {
        score += 0.3 * (res - mean_residual);
    }

    // --- Last-chance bonus: only fitting bin, avoid opening a new bin ---
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // --- New-bin candidate logic ---
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when the current item nearly
        // fills it or existing residuals are all large (poor fits everywhere).
        let near_full = (item_size as f64 / bin_capacity as f64) > 0.7;
        let all_poor = mean_residual > 0.6 * bin_capacity as f64 && fitting_bins_count > 0;
        if near_full || all_poor {
            score -= 15.0;
        } else {
            // Discourage opening a new bin when good fits exist.
            score += 25.0;
        }
    }

    // --- Mild stream-progression pressure: pack tighter as stream advances ---
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.15 * progress * res;

    // --- Small tie-break: prefer fewer open bins (consolidation) ---
    score += 0.05 * open_bins_count as f64;

    // --- Dead-space penalty: residuals too small for any item (min size 1) ---
    if res > 0.0 && res < 10.0 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize large unusable dead space (post-residual that likely can't host future items).
    if post_residual < 10 && post_residual > 0 {
        score -= 8.0; // near-perfect fit: reward strongly
    } else if post_residual > 0 {
        // waste penalty grows quadratically with dead space
        score += (post_residual as f64).powi(2) / (bin_capacity as f64 * 2.0);
    }

    // Lookahead: if next item fits exactly in post-residual, strongly favor this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        score -= 12.0 - (gap as f64).min(20.0) * 0.3;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // next item can't follow here: mild penalty proportional to shortfall
        score += ((next_item_size - post_residual) as f64).min(30.0) * 0.25;
    }

    // Last-chance bin: strongly prefer using the only fitting bin before opening a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin when good alternatives exist,
    // but allow it when existing bins would create large waste.
    if bin_residual == bin_capacity {
        let open_f = open_bins_count as f64;
        // early stream: opening bins is cheap; late stream: prefer consolidation
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 6.0 + progress * 18.0 + open_f * 0.8;
        // if item is large, a fresh bin is actually attractive
        if item_size > bin_capacity / 2 {
            score -= 10.0;
        }
        // if mean residual is high, existing bins are roomy -> avoid new bin
        score += (mean_residual / 10.0).min(10.0);
    }

    // Prefer bins whose residual is close to item size (tight fit) beyond raw post_residual.
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += tightness * 6.0;

    // Slight preference for bins with residual below mean (consolidate small leftovers).
    score += (mean_residual - bin_residual as f64) * 0.15;

    // Time-horizon modulation: late in the stream, prioritize minimizing waste more aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.4 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let base = pr as f64;

    // Smooth non-linear polynomial coupling of post_residual with stream progress
    let t = progress;
    let poly = norm_pr * norm_pr * (1.0 + 3.0 * t) - norm_pr * (1.0 - t) * 2.0;

    let mut score = base + 40.0 * poly * cap * 0.01;

    // Reward tight fits (small post residual) more strongly as stream progresses
    score -= (1.0 - norm_pr) * (1.0 - norm_pr) * (10.0 + 30.0 * t);

    // Penalize dead space that cannot fit the next item (smooth interaction)
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        let gap = (ns - pr).max(0.0) / cap;
        score += 25.0 * gap * gap * cap * 0.01 * (0.5 + t);
        // Reward leaving exactly-fitting space for next item
        let fit = if pr >= ns { (pr - ns) as f64 } else { 999.0 };
        score -= 8.0 * (1.0 - (fit / cap).min(1.0)) * t;
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0 * (1.0 + t);
    }

    // Mild penalty when many bins are open and this placement wastes space
    score += 0.05 * open_bins_count as f64 * norm_pr;

    // Smooth alignment with mean residual: prefer bins near the mean residual
    let dev = (pr - mean_residual) / cap;
    score += 5.0 * dev * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: modulo arithmetic on capacity fractions.
    // Residuals that are "nice" multiples of common size classes (10, 20, 25, 50) are reusable.
    let pr = post_residual;
    let class_bonus = if pr == 0 {
        -40.0 // perfect closure: best possible outcome
    } else if pr % 50 == 0 {
        -18.0
    } else if pr % 25 == 0 {
        -12.0
    } else if pr % 10 == 0 {
        -8.0
    } else if pr % 5 == 0 {
        -3.0
    } else {
        4.0 // awkward residual, penalize slightly
    };
    score += class_bonus;

    // Dead-space penalty: small unusable leftovers (below the minimum item size 1,
    // but practically below common small sizes) are wasted capacity.
    if pr > 0 && pr < 10 {
        score += 15.0;
    } else if pr >= 10 && pr < 20 && next_item_size > pr && next_item_size != 0 {
        score += 6.0;
    }

    // Lookahead coupling: reward if next item fits exactly or snugly in the post-residual.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 22.0;
        } else if next_item_size <= pr {
            let slack = (pr - next_item_size) as f64;
            score -= 10.0 * (1.0 - slack / cap);
        } else {
            // next item won't fit here; mildly penalize leaving a large stranded residual
            score += 3.0 * (pr as f64 / cap);
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        let fit_ratio = item_size as f64 / bin_residual as f64;
        if fit_ratio > 0.6 {
            score -= 25.0;
        } else {
            score -= 8.0;
        }
    }

    // New-bin candidate handling: an empty bin should only win when no open bin
    // offers a decent fit. Penalize the fresh bin by its "unused" capacity unless
    // the current bin would leave a very poor residual.
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        score = cap * 0.9;
        // if existing fits are bad, discount the new bin
        if fitting_bins_count == 0 {
            score -= 30.0;
        } else if item_size as f64 / bin_capacity as f64 > 0.8 {
            // huge item: pairing it with fresh capacity is fine
            score -= 10.0;
        }
        // late in the stream, avoid proliferating bins
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 * progress;
    } else {
        // Tightness reward: the fuller the bin becomes, the better (best-fit bias).
        let tightness = 1.0 - (post_residual as f64 / cap);
        score -= 12.0 * tightness * tightness;
    }

    // Mean-residual coupling: placing into a bin whose residual is far below the
    // mean consolidates space; reward that.
    let dev = mean_residual - bin_residual as f64;
    score += 0.05 * dev;

    // Slight preference to keep the number of open bins small.
    score += 0.3 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for the
    // smallest plausible item are pure waste. Penalize them hard.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 25.0;
    } else if post_residual >= 20 && post_residual < 30 {
        score += 8.0;
    }

    // Reward tight fits (small post_residual) with a multiplicative bonus.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Lookahead: if the next item fits exactly in the post_residual, reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
        if post_residual == next_item_size {
            score -= 20.0;
        }
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here; penalize leaving a gap that traps it.
        score += 5.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Pressure against opening new bins when many bins are already open.
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus open-bin pressure.
        score += 40.0 + 3.0 * open_bins_count as f64;
        // Early in the stream, opening bins is cheaper (builds a pool).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
        // If mean residual of open bins is high, prefer filling them instead.
        score += mean_residual * 0.3;
    } else {
        // Mild reward for using existing bins as open count grows.
        score -= 2.0 * open_bins_count as f64;
    }

    // Perfect fill is always ideal.
    if post_residual == 0 {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact-fit reward: large subtraction when the item perfectly fills the bin.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward if the next item exactly matches the post residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 400.0;
        } else if post_residual > next_item_size {
            // Next item fits: mild reward proportional to how well it nests.
            let nest = (post_residual - next_item_size) as f64;
            score -= 60.0 - 0.5 * nest;
        } else {
            // Next item does NOT fit: penalize proportionally to the leftover gap,
            // stronger when the gap is small (near-miss dead space).
            let gap = (next_item_size - post_residual) as f64;
            score += 0.6 * gap;
        }
    }

    // Penalize creating large unusable dead space relative to the mean residual.
    let pr = post_residual as f64;
    if pr > mean_residual {
        score += 0.35 * (pr - mean_residual);
    } else {
        score -= 0.15 * (mean_residual - pr);
    }

    // Last-chance bonus: if this is the only bin that can fit the item, strongly favor it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 500.0;
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    // Prefer reusing existing bins for good fits; only prefer a new bin when
    // the item is large and no open bin nests it well.
    if bin_residual == bin_capacity {
        let tightness = item_size as f64 / bin_capacity as f64;
        if next_item_size > 0 && post_residual < next_item_size && tightness > 0.5 {
            score -= 80.0 * tightness;
        } else {
            score += 120.0; // discourage opening new bins when open bins suffice
        }
    }

    // Slight early-stream bias toward consolidating into fewer bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residual too small for any item (min size 1) is wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64);
    }

    // Reward near-perfect fits (post_residual small but usable).
    if post_residual > 0 && post_residual >= 10 {
        score -= 12.0 * (1.0 - post_residual as f64 / 40.0).max(0.0);
    }

    // Exact fit is ideal.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Lookahead: if the next item fits in the post residual, this placement
    // preserves a useful chain.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 8.0 + 0.1 * next_item_size as f64;
        } else if next_item_size > post_residual && post_residual > 0 {
            // next item won't fit here; mild penalty proportional to leftover.
            score += 0.05 * post_residual as f64;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate: only attractive when current bin fits are poor.
    if bin_residual == bin_capacity {
        score += 30.0 + 0.5 * open_bins_count as f64;
        // If the item would leave a large usable residual in an existing bin,
        // opening a new bin is wasteful.
        if post_residual >= 20 {
            score += 15.0;
        }
        // Late in stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 40.0 * progress;
    }

    // Prefer bins tighter than average (best-fit flavor).
    score += 0.3 * (mean_residual - bin_residual as f64).max(-50.0).min(50.0);

    // Mild preference for bins that will end up with small residuals overall.
    score += 0.1 * (post_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: penalize wasted residual, smoothly
    let mut score = pr;

    // Non-linear waste term: small residuals are near-perfect fits, large residuals are waste
    let waste = (norm_pr * (1.0 - norm_pr)).sqrt();
    score += 40.0 * (norm_pr - 0.5) * (norm_pr - 0.5) * cap * 0.1;
    score -= 20.0 * waste;

    // Stream progress coupling: later in stream, prefer tighter fits more aggressively
    let tightness = 1.0 - (norm_pr * norm_pr);
    score -= 30.0 * progress * tightness;

    // Last-chance bonus: strongly favor the only bin that fits
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: penalize mildly, but relax late in the stream or when fit is poor
    if bin_residual == bin_capacity {
        let fit_quality = item_size as f64 / cap;
        score += 45.0 - 35.0 * progress - 25.0 * (1.0 - fit_quality) * (1.0 - fit_quality);
    }

    // Lookahead: if next item fits perfectly into the post-residual, reward this placement
    if next_item_size > 0 {
        if next_item_size as f64 == pr {
            score -= 35.0;
        } else if (next_item_size as f64) < pr {
            let slack = pr - next_item_size as f64;
            score += 0.05 * slack;
        }
    }

    // Mean residual interaction: prefer bins deviating from mean (keeps diversity of residuals)
    let dev = (pr - mean_residual) / cap;
    score += 10.0 * dev * dev * cap * 0.01 - 5.0 * dev;

    // Open bins count: many open bins -> encourage consolidation
    score += 2.0 * (open_bins_count as f64).ln().max(0.0) * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the residual: classify post_residual into residue classes mod 10.
    let rclass = post_residual % 10;
    // "Harmonic" residuals are multiples of 10 (align with typical item granularities).
    let harmonic = if rclass == 0 { 0.0 } else { (10 - rclass) as f64 * 0.35 };

    // Reward tight fits strongly (post_residual small relative to capacity).
    let tightness = 1.0 - (post_residual as f64 / cap);
    score -= 18.0 * tightness * tightness;

    // Penalize non-harmonic dead space.
    score += harmonic;

    // If post_residual can exactly fit the next item, big reward (k=2 lookahead chaining).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual >= next_item_size {
            // next item fits, but leaves another residual: mild reward scaled by fit quality.
            let nr = post_residual - next_item_size;
            score -= 8.0 * (1.0 - nr as f64 / cap);
            // penalty if the chain leaves an awkward residue class again
            if nr % 10 != 0 { score += (10 - nr % 10) as f64 * 0.2; }
        } else {
            // next item cannot use this residual: penalize proportionally to wasted space.
            score += 3.0 * (next_item_size as f64 - post_residual as f64).min(40.0) / 10.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate logic (bin_residual == bin_capacity).
    if bin_residual == bin_capacity {
        // Opening a new bin is good only if the item fills it substantially or
        // no reasonable existing bin exists / existing fits are poor.
        let fill_fraction = item_size as f64 / cap;
        let mut new_bin_score = cap - 30.0 * fill_fraction * fill_fraction;
        if next_item_size > 0 && post_residual >= next_item_size {
            new_bin_score -= 12.0; // fresh bin can chain the next item
        }
        // If many bins already fit the item, discourage opening another.
        if fitting_bins_count > 1 {
            new_bin_score += 15.0 * (fitting_bins_count as f64 - 1.0).min(4.0);
        }
        // Early in stream, slightly discourage proliferation; late, allow it.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        new_bin_score += 6.0 * (1.0 - progress);
        // If mean residual across open bins is large, prefer using open bins.
        new_bin_score += (mean_residual / cap).clamp(0.0, 1.0) * 10.0;
        score = new_bin_score;
    }

    // Mild preference to keep number of open bins low when residuals are similar.
    if open_bins_count > 8 && bin_residual != bin_capacity {
        score -= 2.0;
    }

    // Integer-division threshold: residuals >= half capacity are semi-usable, give small bonus.
    if post_residual >= bin_capacity / 2 {
        score -= 4.0;
    } else if post_residual > 0 {
        // Tiny residuals are dead space: penalize.
        score += 6.0 * (1.0 - post_residual as f64 / (bin_capacity / 2) as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are the worst outcome.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0 * (1.0 - post_residual as f64 / 20.0);
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * tightness;

    // Penalize creating a gap that cannot fit the known next item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
