    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: when many bins are open, discourage opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 / (1.0 + progress);
    score += 0.35 * pressure * (bin_residual == bin_capacity) as i32 as f64;

    // New-bin candidate: penalize slightly more when mean residual is still usable.
    if bin_residual == bin_capacity {
        score += 10.0 + mean_residual * 0.2;
    } else {
        // Slight preference for bins with lower current residual (fuller bins).
        score += (bin_residual as f64 - mean_residual) * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Base: penalize large post_residual relative to capacity
    score = post * (1.0 + 0.5 * (post / cap));

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward when post_residual matches next_item_size exactly
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (post - nxt).abs();
        if diff == 0.0 {
            score -= 500.0; // exact chain fit
        } else if nxt <= post {
            // next item fits into resulting residual: reward proportionally
            score -= 200.0 * (1.0 - diff / cap);
        } else {
            // next item won't fit here: mild penalty proportional to wasted residual
            score += 0.3 * diff;
        }
    }

    // Compare residual against mean residual: prefer bins tighter than average
    score += 2.0 * (post - mean_residual);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 300.0;
    }

    // Penalize opening a new bin when good fitting bins exist and residual is usable
    if bin_residual == bin_capacity {
        // new-bin candidate: baseline score; penalize if open bins exist with room
        score += 150.0 * open_bins_count as f64;
        // but if mean residual is small (bins nearly full), new bin is fine
        score -= 2.0 * mean_residual;
    }

    // Late-stream: slightly favor closing bins tightly as stream ends
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.5 * progress * post;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for near-perfect fits (small dead space).
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 25.0 + (10 - post_residual) as f64 * 2.0;
    } else {
        // Penalize large dead space quadratically, normalized by capacity.
        let dead = post_residual as f64 / bin_capacity as f64;
        score += dead * dead * 40.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
