        new_bin_penalty += open_bins_count as f64 * 2.5;
        if fitting_bins_count >= 1 {
            new_bin_penalty += 15.0;
        }
        if post_residual > 0 && post_residual < next_item_size && next_item_size > 0 {
            new_bin_penalty -= 5.0; // fresh bin keeps space for the lookahead item
        }
        score += new_bin_penalty;
    } else {
        // Existing bin: bonus when its residual is below the mean (it's already tight);
        // encourage consolidating into tight bins to leave loose bins for big items.
        if (bin_residual as f64) < mean_residual {
            score -= 6.0;
        } else {
            score += 2.0;
        }
        // Reward bins that are "half-closable": residual small relative to typical item sizes.
        if bin_residual <= 20 {
