        }
    }

    // Mild coupling: with few open bins and early stream, opening a bin is cheap.
    if open_bins_count <= 2 && progress < 0.3 && bin_residual == bin_capacity {
        score -= 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    // normalized post-residual in [0,1]
    let x = pr / cap;

    // Base: prefer small post-residual (tight fit), non-linearly
    let mut score = pr as f64;

    // Smooth polynomial coupling of post-residual with stream progress:
    // early on, waste is cheap; later, waste is increasingly penalized.
    let waste_penalty = x * x * (1.0 + 3.0 * progress) + 0.5 * x * x * x * progress;
    score += 20.0 * waste_penalty;

    // Reward leaving residual that matches the next item (smooth kernel)
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        let match_bonus = (1.0 - gap / cap).max(0.0);
        score -= 8.0 * match_bonus * match_bonus;
    }

    // Last-chance bin: strongly favor using it (avoid opening a new bin)
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - x);
    }

    // Crowding: many open bins -> prefer filling existing ones (smooth in count)
    let crowd = open_bins_count as f64 / (open_bins_count as f64 + 5.0);
    score -= 6.0 * crowd * (1.0 - x);

    // Mean-residual coupling: if this bin is above-average full, reward placement
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score -= 5.0 * dev * (1.0 + progress);

    // Slight preference for new empty bin early when item is large
    if bin_residual == bin_capacity {
        score += 10.0 * x * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), with non-linear emphasis.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    score += 0.35 * (pr * pr) / cap;

    // Harmonic class of post_residual: modulo classes relative to capacity fractions.
    // Residuals divisible into "useful" slots (small classes) are less penalized.
    let class = post_residual % 25; // quarter-capacity harmonic class
    score -= 3.0 * (class as f64 / 25.0) * (1.0 - class as f64 / 25.0) * 4.0; // hump at mid-class

    // Integer-division thresholds: post_residual bucketed by eighths of capacity.
    let bucket = post_residual / 12;
    score += 2.5 * bucket as f64;

    // Lookahead: if next item fits exactly in post_residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            // partial compatibility: reward proportional to leftover after next item
            let after = post_residual - next_item_size;
            score -= 8.0 * (1.0 - (after as f64 / cap));
        } else {
            // next item cannot use this residual: penalize large dead space
            score += 4.0;
            // harmonic mismatch penalty: next_item_size class vs post_residual class
            let mismatch = (post_residual % 10) + (next_item_size % 10);
            score += 0.15 * mismatch as f64;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate handling: empty bin should only win when open bins fit poorly.
    if bin_residual == bin_capacity {
        // Neutral-ish baseline; penalize mildly when decent fits exist.
        if fitting_bins_count > 0 {
            let best_possible = mean_residual.min(cap);
            if best_possible < item_size as f64 * 1.6 {
                score += 20.0; // an open bin fits reasonably well -> avoid new bin
            }
        }
        // Early stream: opening bins is cheap; late stream: consolidate.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 6.0 * progress;
        // Few open bins -> new bin less costly.
        score -= 3.0 * (open_bins_count.min(10) as f64) / 10.0;
    }

    // Mean residual coupling: if this bin's residual is far below mean, it is scarce
    // capacity; penalize wasting it on a loose fit.
    let res = bin_residual as f64;
    if res < mean_residual {
        score += 0.5 * (mean_residual - res) * (pr / cap);
    } else {
        score -= 0.2 * (res - mean_residual) / cap;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Tiny residual creation penalty (dead space threshold via integer division).
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small non-zero post_residual gaps are likely unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // dead gap penalty
    }
    // Mid-range dead zones (e.g. 11..=20) are risky if next item is larger.
    if post_residual >= 11 && post_residual <= 20 && next_item_size > post_residual {
        score += 25.0;
    }

    // Reward tight fits.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 40.0 * fit_ratio;

    // Exact fill is ideal.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: many open bins -> prefer filling existing ones,
    // penalize opening new bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive when current bins are crowded or poor fits.
        score += 15.0 + 3.0 * open_bins_count as f64;
        // Late in stream, opening new bins is costly; early it's fine.
        score += 20.0 * progress;
        // If next item fits comfortably in a fresh bin, slight bonus.
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 5.0;
        }
    } else {
        // Existing bin: reward keeping open-bin count low.
        score -= 2.0 * open_bins_count as f64;
    }

    // Prefer bins whose residual deviates from mean (consolidation of small residuals).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score -= 0.3 * dev;

    // Lookahead: if next item exactly fills post_residual, big reward.
    if next_item_size == post_residual && post_residual > 0 {
        score -= 50.0;
    }
    // Penalize if next item can't use the post_residual and won't fit elsewhere well.
    if next_item_size > post_residual && next_item_size > 0 && post_residual < 10 {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual).
    score = post_residual as f64;

    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Strongly reward exact/near-exact fill of the bin.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0 + (5 - post_residual) as f64 * 20.0;
    } else if post_residual < 10 {
        // Dead space: residual too small for any item (min size 1, but tiny
        // residuals are hard to reuse) — penalize proportionally.
        score += (10 - post_residual) as f64 * 3.0;
    }

    // 2-step lookahead: if the next item fits exactly into post_residual,
    // this is a perfect chaining opportunity — reward heavily.
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if post_residual as u32 == next_item_size {
            score -= 500.0;
        } else if (pr - n).abs() <= 3.0 {
            score -= 300.0 - (pr - n).abs() * 40.0;
        } else if post_residual as u32 > next_item_size {
            // Next item fits with slack: mild reward proportional to tightness.
            score -= 80.0 * (n / pr).max(0.0).min(1.0);
        } else {
            // Next item will NOT fit here: post_residual becomes dead space
            // relative to lookahead — penalize, scaled by how close we were.
            let miss = n - pr;
            score += miss * 6.0;
        }
    } else {
        // Last item: just minimize waste; exact fit best.
        score -= 100.0;
    }

    // Relative-to-mean coupling: leaving more than the mean residual behind
    // is wasteful compared to other bins; less than mean is a tight fit.
    score += (pr - mean_residual) * 1.5;

    // Last-chance bin: if this is the only bin that fits, avoid opening a new
    // bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate (empty bin): post_residual = capacity - item_size is
    // large, so it's naturally disfavored; add extra penalty so we only open
    // a new bin when no reasonable fit exists, unless item is huge.
    if bin_residual == bin_capacity {
        score += 120.0;
        // But for very large items, opening a fresh bin is often optimal.
        if item_size >= 70 {
            score -= 200.0;
        }
    }

    // Late in the stream, prefer consolidating into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 10.0 * (pr / cap);

    // Prefer bins with below-average residual (they're already tight).
    if pr < mean_residual {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong best-fit preference: exact fits are highly rewarded.
    if post_residual == 0 {
        score -= 50.0;
    } else {
        // Penalize large leftover space nonlinearly (dead-space shaping).
        let pr = post_residual as f64;
        score += 0.02 * pr * pr / bin_capacity as f64;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward this bin.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            // Next item won't fit here; mildly penalize leaving awkward gaps.
            let gap = post_residual as f64;
            if gap > 0.0 && gap < next_item_size as f64 {
                score += 0.3 * (next_item_size as f64 - gap);
            }
        }
    }

    // Last-chance bonus: if this is the only bin that fits, prefer it strongly
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate handling: an empty bin has bin_residual == bin_capacity.
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when existing fits are poor.
        // Base penalty keeps preference for filling open bins.
        score += 12.0;
        // But if the item is large relative to capacity, a fresh bin is fine.
        let frac = item_size as f64 / bin_capacity as f64;
        score -= 20.0 * frac * frac;
        // Early in the stream, opening bins is cheaper.
        let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 10.0 * (1.0 - t);
    }

    // Global pressure: many open bins with high mean residual -> consolidate.
    if open_bins_count > 1 {
        let consolidation = (mean_residual - post_residual as f64).abs();
        score += 0.05 * consolidation;
        score -= 0.5 * open_bins_count as f64;
    }

    // Mild time-horizon modulation: later in stream, tighten fits more.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 3.0 * t * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let norm_pr = pr / cap;

    // Base: penalize post-residual, but weight it non-linearly by stream progress.
    // Early on, large residuals are acceptable (bins can be topped up later);
    // late in the stream, dead space is nearly permanent, so penalize harder.
    let progress_weight = 0.5 + 0.9 * progress * progress;
    let mut score = pr * progress_weight;

    // Non-linear coupling: quadratic penalty on small-but-nonzero residuals
    // (dead space that is too small to fit typical items) with a smooth
    // polynomial kernel rather than a hard threshold.
    let dead_zone = (norm_pr - 0.25).powi(2);
    score += 40.0 * (1.0 - dead_zone) * norm_pr * (1.0 - norm_pr);

    // Lookahead coupling: reward residuals that still fit the next item,
    // with a smooth cubic interaction in progress.
    if next_item_size > 0 {
        let fits_next = (pr >= next_item_size as f64) as f64;
        let tight = 1.0 - (pr - next_item_size as f64).abs() / cap;
        score -= 25.0 * fits_next * (1.0 + progress) * tight.max(0.0);
        // If the next item fits exactly-ish, extra reward (perfect pairing).
        score -= 15.0 * fits_next * (1.0 - ((pr - next_item_size as f64) / cap).powi(2)).max(0.0);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    // (opening a new bin wastes the residual entirely).
    if fitting_bins_count == 1 {
        score -= 60.0 * (1.0 + 0.5 * progress);
    }

    // Mean-residual coupling: prefer bins whose post-residual stays near the
    // fleet mean (keeps future items placeable), penalize outliers smoothly.
    let dev = (pr - mean_residual) / cap;
    score += 10.0 * dev * dev;

    // Slight preference for fuller bins (lower residual before placement)
    // expressed as a smooth normalized term.
    score += 0.15 * (bin_residual as f64 / cap);

    // New-bin candidate: empty bin starts with pr == cap; give it a mild
    // baseline penalty so it is chosen only when it beats real bins.
    if bin_residual == bin_capacity {
        score += 5.0 + 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: post_residual buckets by integer division.
    // Small leftovers are "dead space" classes -> penalize; large leftovers keep flexibility.
    let leftover_class = post_residual / 10;
    let class_penalty = match leftover_class {
        0 => 25.0,                       // 0..9  : near-perfect fit, reward below
        1 => 8.0,                        // 10..19: small dead space
        2 => 14.0,                       // 20..29
        3 => 20.0,                       // 30..39
        4 => 24.0,                       // 40..49: half-empty, risky
        _ => 0.0,                        // 50+   : still flexible
    };
    score += class_penalty;

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 18.0;
    } else if post_residual <= 10 {
        score -= 10.0;
    }

    // Lookahead coupling (k=2): does the leftover accommodate the next item?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Next item fits exactly-ish in the leftover: harmonic match reward.
            let gap = post_residual - next_item_size;
            score -= 12.0 + gap as f64 * -0.15; // tighter match -> bigger reward
            if gap == 0 {
                score -= 10.0;
            }
        } else {
            // Next item cannot use this leftover: leftover likely becomes dead space.
            score += 6.0;
            // Harmonic mismatch modulo classes: leftover and next item in same decade
            // means near-miss, extra frustration penalty.
            if post_residual / 10 == (next_item_size - 1) / 10 {
                score += 5.0;
            }
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
        if post_residual <= 20 {
            score -= 10.0;
        }
    }

    // New-bin candidate handling: opening a new bin wastes the mean residual
    // of all open bins. Penalize when open bins are collectively full-ish.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let waste = mean_residual * (open_bins_count as f64).sqrt();
        score = 60.0 + waste * 0.5 - progress * 10.0;
        // Late in the stream, opening new bins is fine (fewer future regrets).
        if progress > 0.8 {
            score -= 15.0;
        }
        // If existing bins fit terribly (all residuals tiny), new bin is attractive.
        if mean_residual < 5.0 && open_bins_count > 0 {
            score -= 20.0;
        }
    }

    // Mild preference to fill bins that are already well-loaded (tight packing).
    let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= fill_ratio * 5.0;

    // Tie-breaker: slight bias by item size class (big items deserve big residual bins).
    if item_size > 50 && bin_residual > 60 {
        score -= 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small nonzero gaps are nearly useless.
    if post_residual > 0 {
        // Dead-space penalty grows quadratically for gaps below the smallest
        // plausible future item size (assume ~10; unknown dist -> use 1..100).
        if post_residual < 10 {
            score += 60.0 * (10.0 - post_residual as f64);
        } else {
            score += 0.15 * (post_residual as f64) * (post_residual as f64) / bin_capacity as f64;
        }
    } else {
        // Perfect fill: strong reward.
        score -= 40.0;
    }

    // Exact-fit lookahead: if next item exactly fills post_residual, big reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 55.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // Mild reward if the lookahead still fits, scaled by how well it fills.
        let fill = next_item_size as f64 / post_residual as f64;
        score -= 12.0 * fill;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Lookahead cannot use this gap: penalize proportionally to gap size.
        score += 0.3 * (post_residual as f64) * (post_residual as f64) / bin_capacity as f64;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, favor filling.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += 2.0 * pressure * (post_residual as f64 / bin_capacity as f64);

    // Prefer bins with residual below the current mean (consolidate emptier space usage).
    score += 0.5 * (bin_residual as f64 - mean_residual);

    // New-bin candidate handling: only attractive for very large items or when
    // no open bin offers a good fit.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let good_fit_exists = fitting_bins_count > 1
            || (fitting_bins_count == 1 && bin_residual - item_size < 10);
        if good_fit_exists {
            score += 80.0; // discourage opening a new bin
        } else {
            // Large items waste less of a fresh bin.
            let item_frac = item_size as f64 / bin_capacity as f64;
            score -= 30.0 * item_frac;
        }
        // Late in the stream, opening bins is less costly (no need to keep many open).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward bins whose residual can host the next item exactly
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 120.0 - slack.min(120.0);
        } else {
            // next item won't fit here; penalize proportionally to wasted gap
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.8;
        }
    }

    // Penalize small dead space that nothing (min size 1..~10) can use
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Relative-to-mean coupling: bins tighter than average are better targets
    let dev = post_residual as f64 - mean_residual;
    score += dev * 0.5;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 200.0;
    }

    // New-bin candidate: only attractive when no good fit exists
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 0.0 } else { 150.0 };
        score += pressure;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 50.0;
        }
    }

    // Early in stream: slightly prefer consolidation; late: prefer tight fills
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - progress) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize residual that is unusably small relative to item scale.
    let tight = (post_residual as f64) / (bin_capacity as f64);
    score += tight * tight * 60.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 10 {
        score -= 20.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if next item fits in post_residual, reward this placement.
    if next_item_size > 0 && (post_residual as i64) >= (next_item_size as i64) {
        score -= 15.0;
    } else if next_item_size > 0 && (post_residual as i64) > 0 && (post_residual as u32) < next_item_size {
        // Dead space the next item cannot use: penalize more when post_residual is small.
        score += (next_item_size - post_residual) as f64 * 0.4;
    }

    // Global state coupling: when mean residual is high, prefer filling existing bins
    // rather than spreading; when low, mild preference for new bins.
    let mean_r = mean_residual;
    score -= (mean_r - post_residual as f64) * 0.15;

    // Time horizon: early in stream, allow more bins (explore); late, consolidate.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - progress) * (post_residual as f64) * 0.1 * (open_bins_count as f64).ln().max(0.0);

    // Penalize opening a new bin when a fitting bin exists and stream is late.
    if bin_residual == bin_capacity && fitting_bins_count > 0 {
        score += 25.0 + progress * 25.0;
    } else if bin_residual == bin_capacity {
        score -= 5.0; // no open bin fits: new bin is reasonable
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post-residual, with polynomial coupling to progress
    let mut score = pr * (1.0 + 0.5 * progress * norm_pr);

    // Penalize large dead space non-linearly
    score += 40.0 * norm_pr * norm_pr * (0.5 + progress);

    // Reward tight fits
    let tight = 1.0 - norm_pr;
    score -= 15.0 * tight * tight * (1.0 - progress);

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: reward if next item fits the post-residual
    if next_item_size > 0 {
        let fits_next = (post_residual as u32 >= next_item_size) as i32 as f64;
        score -= 12.0 * fits_next;
        // Penalize wasting space next item could use
        let waste = (post_residual as f64 - next_item_size as f64).max(0.0);
        score += 0.2 * waste;
    }

    // Mean residual coupling: prefer bins below mean residual (tighter bins)
    score += 0.3 * (mean_residual - pr).abs();

    // New-bin candidate handling: penalize mildly so it's chosen only when fits are bad
    if bin_residual == bin_capacity {
        score += 20.0 + 25.0 * progress;
    }

    // Mild open-bin pressure
    score += 0.5 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "usable"
    // residue classes (multiples of common item sizes) are preferred.
    let pr = post_residual;
    let harmonic_bonus: f64 = if pr == 0 {
        -30.0 // perfect fit: strongly reward
    } else if pr % 10 == 0 {
        -8.0 // leftover is a "clean" multiple of 10, reusable by many items
    } else if pr % 5 == 0 {
        -4.0
    } else {
        // penalize awkward dead space, worse for tiny leftovers
        let awkward = (pr as f64) / bin_capacity as f64;
        6.0 * awkward
    };
    score += harmonic_bonus;

    // Lookahead coupling: if next item fits exactly into post_residual,
    // strongly favor this bin (chain placement).
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 20.0;
        } else if next_item_size <= pr {
            // next item fits: reward proportionally to how well it fills
            let fill = next_item_size as f64 / pr as f64;
            score -= 10.0 * fill;
            // harmonic check: leftover after next item
            let pr2 = pr - next_item_size;
            if pr2 % 10 == 0 { score -= 4.0; }
        } else {
            // next item cannot use this leftover: penalize large leftovers mildly
            score += 3.0 * (pr as f64 / bin_capacity as f64);
        }
    }

    // Last-chance logic: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: prefer it only when current bin would leave a bad fit
    // and mean residual across open bins is already small.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // base new-bin score: slightly above a perfect fit, below bad fits
        score = (bin_capacity as f64) * 0.5;
        // opening new bins early in stream with many open bins is wasteful
        score += 5.0 * progress + 0.5 * open_bins_count as f64;
        // if mean residual is large, prefer reusing open bins -> raise new-bin score
        score += mean_residual * 0.3;
        if next_item_size > 0 && next_item_size >= bin_capacity {
            score -= 25.0; // fresh bin guarantees fit for huge next item
        }
    }

    // Integer-division threshold on post_residual: small leftovers (< half of
    // smallest item) are dead space; penalize.
    if pr > 0 && pr / 10 == 0 {
        score += 10.0;
    }

    // Mild preference for tighter bins overall (best-fit flavor)
    score += 0.05 * (bin_residual as f64 - post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to hold any item (1..=100, min size 1)
    // are worthless; a residual < 10 is essentially dead. Penalize hard.
    if post_residual < 10 {
        score += 60.0 + (10 - post_residual) as f64 * 4.0;
    }

    // Reward very tight fits (post_residual small but item fit well).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    if fit_ratio > 0.9 {
        score -= 25.0 * fit_ratio;
    } else if fit_ratio > 0.7 {
        score -= 10.0 * fit_ratio;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when this bin's fit would leave bad dead space
    // or the bin is nearly full and next item can't use leftover.
    if bin_residual == bin_capacity {
        // neutral baseline; penalize slightly so tight fits into existing bins win
        score += 5.0;
        if post_residual < 10 {
            // opening a fresh bin wastes capacity too; discourage
            score += 30.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            // a fresh bin could host next item too, mildly attractive if current fit is bad
            if fit_ratio < 0.5 {
                score -= 15.0;
            }
        }
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    } else if next_item_size > 0 && post_residual >= next_item_size && post_residual < next_item_size + 10 {
        score -= 15.0;
    }

    // Open bins pressure: with many open bins, consolidate (prefer existing bins).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (open_bins_count as f64).ln().max(0.0) * (4.0 + 6.0 * progress);

    // Prefer bins whose residual is below mean (fill fuller bins first).
    if (bin_residual as f64) < mean_residual {
        score -= 6.0;
    } else {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit is ideal
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: reward when next item fits the post residual exactly or well
    if next_item_size > 0 && post_residual >= next_item_size {
        let next_fit = post_residual - next_item_size;
        score -= 60.0 * (1.0 - next_fit as f64 / bin_capacity as f64);
        if next_fit == 0 {
            score -= 300.0; // perfect 2-chain
        }
    } else if next_item_size > 0 {
        // next item cannot fit here; penalize small dead residuals proportionally
        let dead = post_residual as f64;
        if dead < 10.0 {
            score += 40.0; // tiny unusable sliver
        } else {
            score += 10.0 * (1.0 - dead / bin_capacity as f64);
        }
    }

    // Compare against mean residual: prefer bins whose post residual is near the mean
    // (keeps residuals balanced), but avoid leaving residuals that are hard to fill.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.5 * dev;

    // Last chance: strongly favor using the only bin that fits
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 250.0;
    }

    // Prefer fuller bins (small residual before placement)
    score += 0.3 * (bin_residual as f64 / bin_capacity as f64);

    // Early in stream: be more willing to open new bins (penalize open bins less later)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New bin candidate: attractive early or when item is large relative to residuals
        score -= 80.0 * (1.0 - progress);
        if item_size as f64 > mean_residual {
            score -= 30.0;
        }
    } else {
        // Using existing bins gets more attractive as stream progresses
        score -= 20.0 * progress;
    }

    // Penalty proportional to number of open bins to discourage sprawl
    score += 2.0 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize relative waste.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 30.0;

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        score -= 40.0 / (1.0 + gap);
    }
    // If next item does NOT fit in post_residual but this bin would otherwise be good,
    // mildly penalize creating residual smaller than next item.
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 10.0;
    }

    // Penalize placing into a bin whose residual is far above the mean (fragmenting large residuals)
    // when the fit is loose; reward using below-mean-residual bins.
    let diff = bin_residual as f64 - mean_residual;
    score += 0.3 * diff;

    // New-bin candidate handling: make empty bins moderately attractive only when
    // open bins are fragmented or the item is large and no tight fit exists.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        // High fragmentation -> new bin is fine; low fragmentation -> discourage.
        score = 25.0 + 60.0 * (1.0 - fragmentation) - 20.0 * progress;
        if next_item_size > 0 && next_item_size >= item_size {
            // New bin will hold both current and next item well.
            let combined = item_size + next_item_size;
            if combined <= bin_capacity {
                score -= 35.0;
            }
        }
        if fitting_bins_count <= 1 {
            score -= 50.0; // few alternatives, opening new bin is acceptable
        }
    }

    // Slight preference for keeping many bins busy when many are open.
    if open_bins_count > 3 && bin_residual != bin_capacity {
        score -= 2.0;
    }

    // Dead-space penalty: residuals too small for the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let t = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    score += 12.0 * norm_pr * norm_pr * (0.5 + t) * (1.0 - t + 0.5);
    score -= 8.0 * norm_item * norm_item * (1.0 - t) * (1.0 - t);

    // Tight fit reward: strongly prefer small post residuals, modulated by progress
    score -= 15.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * (0.3 + 0.7 * t);

    // Dead-space penalty for residuals too small for typical future items
    let dead = (norm_pr * 10.0).floor() / 10.0;
    score += 20.0 * (1.0 - dead) * dead * dead * (0.5 + t);

    // Last-chance bin bonus
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0 * (1.0 - norm_pr);
    }

    // Lookahead: reward if next item fits the post residual
    if next_item_size > 0 {
        let nx = next_item_size as f64 / cap;
        if next_item_size <= post_residual {
            score -= 6.0 * nx * (1.0 - t);
        } else {
            score += 5.0 * nx * (1.0 - norm_pr);
        }
    }

    // Mean residual coupling: prefer bins close to the mean residual (balance)
    let dev = (pr - mean_residual) / cap;
    score += 4.0 * dev * dev;

    // New-bin candidate: penalize opening new bins early, allow later
    if bin_residual == bin_capacity {
        score += 6.0 * (1.0 - t) * (1.0 - t) - 3.0 * t * t;
        score += 2.0 * (open_bins_count as f64).sqrt() * (1.0 - t);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: perfect fits (0) heavily rewarded,
    // small dead zones penalized by class.
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect closure
    } else {
        // class = post_residual mod 10 : small residues are dead space
        let class = (pr % 10) as f64;
        score += class * 0.8;
        // very small but nonzero residue is worst (unusable)
        if pr < 5 {
            score += 25.0;
        } else if pr < 10 {
            score += 12.0;
        } else if pr >= 40 {
            score -= 8.0; // large residual still reusable
        }
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 45.0;
        } else if next_item_size < pr {
            score -= 10.0 * (next_item_size as f64 / cap);
            // harmonic match: next item leaves another perfect closure
            if (pr - next_item_size) == 0 {
                score -= 20.0;
            } else if pr >= next_item_size && (pr - next_item_size) < 10 {
                score += 6.0; // would create fresh dead zone
            }
        } else {
            // next item cannot use this bin's residue; residue wasted risk
            score += 4.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize mildly so it's chosen only when open bins score badly.
    if bin_residual == bin_capacity {
        score += 15.0 + 2.0 * open_bins_count as f64;
    }

    // Tightness coupling: prefer bins where item fills a large fraction of residual.
    let fill = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * fill;

    // Mean residual drift: if this bin is far below mean residual, it's a good "garbage" bin.
    let dev = mean_residual - bin_residual as f64;
    score += 0.15 * dev;

    // Stream progression: late in stream, consolidate more aggressively.
    let prog = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * prog * fill;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest item
    // (size 1) are pure waste; residuals that can't fit the next item are
    // semi-waste. Penalize both super-linearly.
    if post_residual > 0 {
        // absolute dead space: cannot hold anything
        score += 40.0;
    }
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // dead space relative to lookahead: unusable for the known future
        let gap = (next_item_size - post_residual) as f64;
        score += 12.0 + 0.8 * gap;
    }

    // Perfect / near-perfect fits are highly desirable
    if post_residual == 0 {
        score -= 60.0;
    } else if next_item_size > 0 && post_residual == next_item_size {
        score -= 35.0; // residual exactly matches lookahead item
    }

    // Last-chance pressure: if this is the only bin that fits, strongly
    // prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0 + 0.3 * item_size as f64;
    }

    // Open-bins pressure: when many bins are open, discourage spreading;
    // prefer filling existing bins rather than opening new ones.
    score += open_bins_count as f64 * (bin_residual as f64 / bin_capacity as f64) * 2.0;

    // New-bin candidate handling: only attractive when existing bins would
    // leave large unusable gaps or no bin fits well.
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        score += 30.0;
        // cheaper to open a new bin if open bins have small mean residual
        // (they are nearly full and item would waste space there)
        score -= 0.4 * mean_residual;
        // very expensive to hoard bins early in the stream
        score += 20.0 * (step_index as f64 / (total_items.max(1) as f64));
        // if the item fits snugly in a fresh bin and lookahead is large,
        // opening new bin is reasonable
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 10.0;
        }
    } else {
        // Favor bins whose residual is close to the item (tight fits)
        let tightness = (bin_residual - item_size) as f64;
        score += 0.5 * tightness;
        // Bonus for bins that remain useful after placement
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 8.0;
        }
    }

    // Mild preference for larger residuals overall (use space efficiently)
    score -= 0.05 * bin_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), but heavily reward
    // when the NEXT item exactly fills the leftover space (2-step lookahead).
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let post = post_residual as f64;
        if post == next {
            // Perfect 2-step completion: huge reward.
            score -= 1000.0;
        } else if next <= post {
            // Next item fits in the leftover: reward, scaled by how well
            // it uses the remaining space (post - next small => better).
            let fill_after_next = post - next;
            score -= 200.0 * (1.0 - fill_after_next / 100.0);
        } else {
            // Next item does not fit: penalize leaving awkward gaps
            // that are smaller than the next item (dead space).
            let waste = (next - post).min(100.0);
            score += 1.5 * waste;
        }
    }

    // Penalize post_residual relative to mean residual: creating a bin
    // with much larger leftover than average wastes capacity.
    score += 0.5 * (post_residual as f64 - mean_residual).max(0.0);

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 {
        score -= 80.0;
    }

    // Slight preference for filling nearly-full bins late in the stream.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 20.0 * progress * (1.0 - post_residual as f64 / 100.0);

    // New-bin candidate (empty bin): penalize mildly so it is only chosen
    // when no open bin offers a reasonable fit.
    if bin_residual == bin_capacity {
        score += 60.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: strongly favor placements that nearly fill the bin.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness * (item_size as f64 / bin_capacity as f64);

    // Dead-space penalty: post residual that is small but unusable is bad.
    if post_residual > 0 {
        let unusable = (post_residual as f64) / (post_residual as f64 + 18.0);
        score += 6.0 * unusable * (1.0 - tightness);
    }

    // Lookahead: reward if the next item can fit into the post residual.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack_after_next = (post_residual - next_item_size) as f64;
            score -= 8.0 * (1.0 - slack_after_next / (bin_capacity as f64));
        } else {
            // Penalize leaving a residual that the next item cannot use.
            score += 3.0 * (next_item_size - post_residual) as f64 / (bin_capacity as f64);
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a bin is only attractive when open bins
    // have poor residuals relative to the item or the stream is early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowding = open_bins_count as f64 / (1.0 + open_bins_count as f64);
        let pressure = (mean_residual - item_size as f64).max(0.0) / (bin_capacity as f64);
        score += 20.0 * crowding * (1.0 - progress * 0.5) - 14.0 * pressure;
        if fitting_bins_count > 0 {
            score += 8.0; // discourage opening when alternatives exist
        }
    }

    // Mild global-state coupling: prefer filling bins whose residual is below mean
    // (drain the small ones), penalize touching bins with above-mean residual.
    if bin_residual != bin_capacity {
        score += 2.5 * ((bin_residual as f64) - mean_residual) / (bin_capacity as f64);
    }

    // Time horizon: as the stream progresses, tighten preferences for perfect fits.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 4.0 * progress * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;

    // Base: post residual, mildly discounted early (waste less costly early)
    let mut score = pr * (1.0 - 0.25 * (1.0 - t));

    // Smooth polynomial coupling: penalize mid-range residuals (dead space),
    // reward very small residuals (tight fit) superlinearly
    let dead = norm_pr * (1.0 - norm_pr); // peaks at 0.5 residual
    score += 40.0 * dead * dead * (0.5 + t);

    // Tight-fit bonus: quartic decay near zero residual
    score -= 30.0 * (1.0 - norm_pr).powi(4);

    // Lookahead: reward leaving room for the next item (smooth interaction)
    if next_item_size > 0 {
        let nx = next_item_size as f64 / cap;
        let fit_next = (pr - nx).max(0.0) / cap;
        score -= 12.0 * fit_next * (1.0 - (t - 0.5).powi(2));
        // Penalize if next item barely fits: creates fragility
        let frag = ((pr - nx) / cap).min(1.0);
        score += 8.0 * frag * (1.0 - frag) * (1.0 - t);
    }

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 {
        score -= 25.0 + 20.0 * t;
    }

    // Many open bins: prefer consolidating into existing bins
    let open_norm = (open_bins_count as f64 / (open_bins_count as f64 + 5.0));
    score -= 6.0 * open_norm * (1.0 - norm_item);

    // Mean residual deviation: prefer bins close to the mean (balanced packing)
    let dev = (pr - mean_residual) / cap;
    score += 10.0 * dev * dev;

    // New-bin candidate: penalize opening a bin unless residuals are large relative to item
    if bin_residual == bin_capacity {
        let avg_fit = mean_residual / cap;
        let urgency = (norm_item - avg_fit).max(0.0);
        score += 15.0 + 35.0 * (1.0 - urgency) * (1.0 - t);
        score -= 5.0 * t;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: which capacity fraction band it lands in.
    let quarter = bin_capacity / 4;
    let eighth = bin_capacity / 8;
    let cls = post_residual / eighth; // 0..8 harmonic class

    // Penalize dead space by class: residuals in (0,10) are nearly useless.
    if post_residual < eighth {
        score += 40.0;
    } else if post_residual < quarter {
        score += 12.0;
    } else if post_residual < 2 * quarter {
        score -= 6.0;
    } else {
        score -= 10.0;
    }

    // Exact fill is perfect.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead: reward if next item fits the post residual (chaining).
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 18.0;
            // Extra reward for tight chain fit (small leftover after next).
            let after_next = post_residual - next_item_size;
            if after_next < eighth {
                score -= 10.0;
            }
        } else if next_item_size > post_residual && post_residual < quarter {
            // Small residual that next item cannot use: dead space risk.
            score += 8.0;
        }
        // Harmonic compatibility: next item in same class as residual.
        if (next_item_size / eighth) == cls && next_item_size > 0 {
            score -= 5.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening bins unless current residual is large
    // and could serve a future item; mild penalty scaled by stream progress.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut nb = 30.0 + 20.0 * (1.0 - progress);
        // If mean residual across open bins is small, opening a fresh bin is fine.
        if mean_residual < 0.25 * cap {
            nb -= 25.0;
        }
        // If the only alternative is a bad fit (large dead space), allow new bin.
        if post_residual < eighth {
            nb -= 35.0;
        }
        score += nb;
    }

    // Prefer packing into bins with residuals near the item (tight fit measure).
    let tightness = (bin_residual - item_size) as f64 / cap;
    score += 15.0 * tightness;

    // Mild pressure to consolidate when many bins are open.
    score += 0.3 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let post = post_residual as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Perfect fit: overwhelming reward, placement is essentially free.
    if post_residual == 0 {
        score -= 1000.0;
        // Even a perfect fit in a fresh bin should not be over-favored vs. closing an open bin.
        if is_new_bin {
            score += 30.0 + open_bins_count as f64 * 5.0;
        }
        return score;
    }

    // --- Strict dead-space avoidance ---
    // Small unusable slivers (nothing meaningful fits afterwards) are heavily penalized,
    // even though their raw residual is tiny. Prefer leaving either 0 or usable space.
    let dead_zone = 12.0;
    if post > 0.0 && post <= dead_zone {
        score += 90.0 + (dead_zone - post) * 4.0;
    }

    // Lookahead coupling (k=2): if the next item cannot use this bin's leftover,
    // the residual is dead at least for the immediate horizon.
    if next_item_size > 0 && post > 0.0 && post < next_item_size as f64 {
        score += 25.0 + (next_item_size as f64 - post) * 1.5;
    }

    if is_new_bin {
        // Opening a new bin: base post_residual is large already; add pressure that
        // grows with the number of currently open bins (fragmentation control).
        score += 35.0 + open_bins_count as f64 * 12.0;
    } else {
        // Reward reusing existing bins, stronger under bin-count pressure.
        score -= (open_bins_count as f64).min(8.0) * 3.0;

        // Last-chance bin: if this is the only open bin that fits, avoid opening a new one.
        if fitting_bins_count == 1 {
            score -= 70.0;
        }

        // Tight-fit bonus: bins tighter than the fleet mean concentrate fullness.
        let tightness = mean_residual - bin_residual as f64;
        if tightness > 0.0 {
            score -= (tightness * 0.4).min(30.0);
        }
    }

    // Late-stream consolidation: as the stream progresses, large leftover residuals
    // become increasingly unlikely to be filled, so penalize them proportionally.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += progress * post * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit: extremely attractive.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Perfect 2-step lookahead match: residual after this item exactly fits next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 800.0;
    }
    // Near match: next item fits with small slack left.
    else if next_item_size > 0 && post_residual > next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 300.0 / (1.0 + slack / 20.0);
    }
    // Next item cannot use the residual: penalize proportionally to wasted space.
    else if next_item_size > 0 && next_item_size > post_residual {
        score += (next_item_size - post_residual) as f64 * 0.5;
    }

    // Reward bins tighter than the mean residual (good consolidation targets).
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 250.0;
    }

    // Penalize new-bin candidate unless current bins are poor fits.
    if bin_residual == bin_capacity {
        score += 120.0 + 0.1 * open_bins_count as f64;
        // If no open bin fits well, allow opening a new bin.
        if fitting_bins_count == 0 {
            score -= 400.0;
        }
    }

    // Late in the stream, consolidate more aggressively into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 20.0;

    // Slight penalty for leaving small unusable slivers.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let is_new_bin = bin_residual == bin_capacity;
    let fit_ratio = item_size as f64 / bin_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Reward tight fits strongly
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize large dead space quadratically
    score += 0.05 * (post_residual as f64) * (post_residual as f64) / 100.0;

    // Dead space is worse if the next item could have used it
    if next_item_size > 0 {
        if post_residual > 0 && post_residual < next_item_size {
            score += 8.0 * (1.0 - post_residual as f64 / next_item_size as f64);
        }
        // Reward leaving room exactly for the next item
        if post_residual == next_item_size {
            score -= 10.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 25.0;
    }

    // New-bin candidate handling
    if is_new_bin {
        // Base penalty for opening a new bin
        score += 30.0;
        // More acceptable early in the stream
        score -= 15.0 * (1.0 - progress);
        // More acceptable when few bins are open
        score -= 5.0 * (1.0 / (1.0 + open_bins_count as f64));
        // If existing bins fit poorly, new bin looks better
        score -= 20.0 * (1.0 - fit_ratio);
        // If next item is large and mean residual is small, prefer fresh bin
        if next_item_size > 0 && mean_residual < next_item_size as f64 {
            score -= 6.0;
        }
    } else {
        // Prefer bins whose residual deviates favorably from the mean
        score -= 0.3 * (mean_residual - bin_residual as f64);
        // Many fitting bins: mild penalty to spread load, prefer best fit anyway
        if fitting_bins_count > 1 {
            score += 1.5 * (fitting_bins_count as f64).ln();
        }
    }

    // Late in stream: consolidate, avoid opening bins
    score += 10.0 * progress * if is_new_bin { 1.0 } else { -0.5 };

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let prn = pr / cap;
    let prog = progress.clamp(0.0, 1.0);
    let coupling = prn * prn * (0.5 + prog) - prn * (1.0 - prog) * 0.6;
    score += 12.0 * coupling;

    // Lookahead: reward leaving room for the next item (smooth quadratic).
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64) / cap;
        let fit_next = (gap.max(0.0)).powi(2);
        let miss_next = (gap.min(0.0)).powi(2);
        score -= 18.0 * fit_next;
        score += 10.0 * miss_next;
    }

    // Last-chance bonus: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - prn);
    }

    // Penalize bins that are outliers vs mean residual (smooth).
    let dev = (pr - mean_residual) / cap;
    score += 6.0 * dev * dev;

    // Mild penalty for having many open bins, eased late in stream.
    score += (open_bins_count as f64).ln().max(0.0) * (1.5 - prog);

    // Reward tight fits (small post residual) with smooth saturation.
    score -= 20.0 * (-prn * 4.0).exp();

    // New-bin candidate handling: make empty bins moderately attractive only
    // when the fit would be poor.
    if bin_residual == bin_capacity {
        score += 8.0 * (1.0 - prn) * (1.0 - prn) - 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: which quarter-band of capacity it falls in.
    let quarter = post_residual / (bin_capacity / 4);
    let band_penalty: f64 = match quarter {
        0 => -30.0, // post residual < 25: near-perfect packing, strong reward
        1 => -12.0, // 25..50: still quite usable
        2 => 6.0,   // 50..75: mediocre
        _ => 20.0,  // 75..100: wasteful placement
    };
    score += band_penalty;

    // Fine harmonic classes via modulo arithmetic on post_residual.
    let r = post_residual % 10;
    score -= match r {
        0 => 8.0, // residual is a multiple of 10: aligns with common item sizes
        1 | 2 | 3 => 3.0,
        4 | 5 | 6 => 0.0,
        _ => -2.0,
    };

    // Integer-division thresholds: how many "small units" of size 10 fit in the residual.
    let units = post_residual / 10;
    score -= (units as f64) * 1.5;

    // Lookahead coupling: reward if the next item fits exactly into the post residual,
    // penalize if post residual is just barely too small for the next item (dead space).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0; // perfect chaining
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 10.0 * (1.0 - slack / bin_capacity as f64); // tight fit still good
        } else {
            let miss = (next_item_size - post_residual) as f64;
            score += 6.0 * (miss / bin_capacity as f64).min(1.0); // near-miss dead space
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: only attractive when open bins are crowded
    // (high mean residual relative to capacity) or late in the stream.
    if bin_residual == bin_capacity {
        let crowd = mean_residual / bin_capacity as f64;
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 45.0 - 55.0 * crowd - 10.0 * progress;
        if open_bins_count == 0 {
            score -= 100.0; // must open the first bin
        }
    } else {
        // Prefer filling bins that deviate from the mean residual in a "tight" direction.
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 2.0 * dev / bin_capacity as f64;
    }

    // Mild pressure to consolidate when many bins are open.
    score -= (open_bins_count as f64).ln().max(0.0) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest item (1)
    // are pure waste; anything below a "useful threshold" is heavily penalized.
    let dead_threshold = 10.0f64;
    if (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 8.0;
    }

    // Reward tight fits: the smaller the post_residual relative to item size,
    // the better the packing density.
    if post_residual == 0 {
        score -= 25.0; // perfect fill
    } else {
        let tightness = item_size as f64 / (item_size + post_residual) as f64;
        score -= tightness * 15.0;
    }

    // Penalize leaving a gap that exactly (or nearly) matches the next item's size
    // is actually GOOD - reward it (lookahead harmony).
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap_ratio = next_item_size as f64 / post_residual as f64;
        if gap_ratio > 0.8 {
            score -= 10.0 * gap_ratio; // next item will slot in nicely
        }
    } else if next_item_size > 0 && post_residual > 0 {
        // Gap smaller than next item but nonzero: potential dead space
        score += 4.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless the fit is truly awful).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into existing
    // bins rather than spreading out.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * (0.5 + 0.5 * progress);

    // New-bin candidate handling: an empty bin has residual == capacity.
    // Only attractive when existing bins are crowded or the fit is poor.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, modulated by how full existing bins are.
        let crowdedness = mean_residual / bin_capacity as f64;
        score += 20.0 - crowdedness * 25.0;
        // If no open bin fits at all (fitting_bins_count counts only this new one),
        // opening is forced: make score competitive.
        if fitting_bins_count == 1 {
            score -= 30.0;
        }
    } else {
        // Slight preference for bins whose residual is close to item size
        // (best-fit flavor) beyond the raw post_residual already used.
        let fit_gap = (bin_residual as f64 - item_size as f64).abs();
        score += fit_gap * 0.05;
    }

    // Mean residual coupling: when average residual across open bins is small,
    // bins are nearly full - favor any placement that empties bins faster.
    if mean_residual < 15.0 && bin_residual != bin_capacity {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward perfect or near-perfect fills.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // 2-step lookahead: reward when next item exactly fits the remaining space.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size < post_residual {
            // Slack relative to next item: small slack is good.
            let slack = (post_residual - next_item_size) as f64;
            score -= 100.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item cannot fit in the residual -> dead space penalty.
            let overhang = (next_item_size - post_residual) as f64;
            score += 50.0 * (overhang / 100.0);
        }
    }

    // Compare bin residual against mean residual across open bins.
    let mean_diff = bin_residual as f64 - mean_residual;
    score += 0.3 * mean_diff; // prefer tighter (below-mean) bins

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // Discard the empty new-bin candidate unless existing fits are poor.
    if bin_residual == bin_capacity {
        score += 60.0;
        // If item is large relative to capacity, opening fresh is more attractive.
        score -= 0.2 * item_size as f64;
    }

    // Slight preference for keeping many bins consolidated as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Tight fit reward: fraction of residual consumed
    let fill_frac = item_size as f64 / bin_residual.max(1) as f64;
    score -= 40.0 * fill_frac;

    // Penalize small unusable leftovers (dead space), unless next item fits
    if post_residual > 0 {
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 15.0; // lookahead: leftover still useful
        } else {
            let dead = if next_item_size == 0 {
                1.0
            } else {
                (post_residual as f64 / next_item_size as f64).min(1.0)
            };
            score += 20.0 * dead;
        }
    }

    // Last-chance bin: strongly prefer to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate handling: only attractive when open bins are fragmented
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual - post_residual as f64).abs();
        let progress = step_index as f64 / total_items.max(1) as f64;
        let pressure = open_bins_count as f64 / (2.0 + progress * 10.0);
        // Prefer new bin when mean residual is small (poor fits everywhere)
        let new_bin_appeal = 30.0 + pressure * 10.0 - fragmentation * 0.5;
        score += 10.0 - new_bin_appeal;
    } else {
        // Reward using bins with below-average residual (consolidate large gaps)
        let diff = mean_residual - bin_residual as f64;
        score -= 0.3 * diff;
    }

    // Late stream: consolidate into fewer bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress > 0.8 && bin_residual < bin_capacity {
        score -= 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 + progress) - norm_pr * progress * 0.5;
    score += poly * cap * 0.3;

    // Tight fits are good: reward small post_residual non-linearly
    score -= (1.0 - norm_pr).powi(3) * cap * 0.4;

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if next item fits perfectly in post_residual, reward
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        score -= (1.0 - gap / cap).powi(2) * 15.0;
    } else {
        // End of stream: prefer filling bins as tightly as possible
        score -= norm_pr * 10.0;
    }

    // Penalize opening new bins as stream progresses
    if bin_residual == bin_capacity {
        score += 25.0 * (0.5 + progress) + open_bins_count as f64;
    }

    // Mild penalty when bin residual deviates from mean residual (keep balance)
    score += ((bin_residual as f64 - mean_residual) / cap).powi(2) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual)
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness;

    // Harmonic class of post_residual: dead space in low residues is more wasteful
    // Class residues by quarter-capacity bands via integer division
    let band = (post_residual / 25) as f64; // 0..4
    score += 6.0 * band;

    // Modulo-10 class: small leftovers (<10) are pure dead space for typical items
    if post_residual < 10 {
        score -= 20.0; // perfect fill class — strongly reward
    } else if post_residual < 20 {
        score += 4.0;
    } else if post_residual < 40 {
        score += 8.0;
    }

    // Lookahead: reward if next item fits exactly in post_residual (perfect chaining)
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            // fraction of next item consumed by this residual
            let fill = (next_item_size as f64) / (post_residual as f64).max(1.0);
            score -= 15.0 * fill;
        } else {
            // next item won't fit here: penalize large post_residuals that strand space
            score += 0.05 * (post_residual as f64);
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only open a new bin when existing fits are terrible
    if bin_residual == bin_capacity {
        // New bin: neutral baseline; make it unattractive unless post_residual here
        // (which is capacity - item) is small AND no existing tight options
        score += 18.0;
        if next_item_size > 0 && next_item_size >= post_residual {
            score += 10.0; // new bin leaves space the next item can't use well
        }
        // Early in stream, new bins are cheap (exploration)
        let progress = step_index as f64 / (total_items as f64).max(1.0);
        score -= 15.0 * (1.0 - progress);
    }

    // Prefer spreading load when many bins open with high mean residual
    if open_bins_count > 0 {
        let rel = (mean_residual - bin_residual as f64) / bin_capacity as f64;
        score += 5.0 * rel; // favor bins below-average residual (fill emptier-spaced ones)
    }

    // Harmonic threshold: post_residual divisible by common item sizes (10/20/25)
    if post_residual > 0 && (post_residual % 10 == 0 || post_residual % 25 == 0) {
        score -= 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Strict dead-space avoidance ---
    // Small unusable gaps are the worst outcome: penalize hard.
    if post_residual > 0 && post_residual < 10 {
        // Dead space zone: gap too small for any item (min size 1..100 range, treat <10 as near-dead)
        score += 40.0 * (1.0 - post_residual as f64 / 10.0) + 15.0;
    } else if post_residual == 0 {
        // Perfect fit: strongly reward
        score -= 60.0;
    } else {
        // Usable residual: mild reward proportional to how "round" the leftover is
        score -= 2.0;
    }

    // --- Last-chance pressure ---
    // If this is the only bin that fits, strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when no open bin fits well.
        // Penalize new bins mildly; escalate penalty with open bin count to force consolidation.
        score += 25.0 + 4.0 * open_bins_count as f64;
        // But if the item is huge and would leave a tiny gap in any bin, new bin is fine
        if item_size > bin_capacity * 9 / 10 {
            score -= 30.0;
        }
    }

    // --- Open-bin count pressure ---
    // Encourage filling existing bins as the stream progresses
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 0.15 * open_bins_count as f64 * (0.5 + progress);

    // --- Lookahead coupling ---
    // Favor bins whose post_residual can host the next item (chain packing)
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else if post_residual > 0 {
            score += 8.0; // leftover won't serve next item
        }
    }

    // --- Mean-residual coupling ---
    // Prefer bins below mean residual (more packed bins first)
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    } else {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fit (low post_residual), scaled against mean residual.
    score += (post_residual as f64 - mean_residual) * 0.5;

    // Aggressive 2-step lookahead: strongly reward if the NEXT item fits exactly-ish.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            // Perfect chain: consume residual with next item.
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // Next item fits; reward proportionally to how much of residual it uses.
            let usage = next_item_size as f64 / post_residual as f64;
            score -= 10.0 + 30.0 * usage;
        } else {
            // Next item does NOT fit in the residual we leave behind: penalize.
            let gap = (next_item_size - post_residual) as f64;
            score += 5.0 + gap.min(40.0);
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Penalize creating large unusable dead space (residual too small for typical items).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0; // tiny sliver is wasted
    }

    // New-bin candidate (empty bin): only attractive when existing bins are quite full
    // or the fit is poor elsewhere.
    if bin_residual == bin_capacity {
        // Neutral-ish base for fresh bin: score = capacity-ish residual.
        // Penalize opening new bins when many bins are open and mean residual is healthy.
        score += open_bins_count as f64 * 2.0;
        if mean_residual > item_size as f64 * 1.5 {
            score += 20.0; // existing bins still have room; discourage new bin
        }
        // But if next item is large and current fits are all tight, allow new bin.
        if next_item_size > 0 && next_item_size > mean_residual {
            score -= 10.0;
        }
    }

    // Late in the stream, consolidation matters more: tighten preference for low residual.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.3 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer tight fits: reward small post_residual non-linearly.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - tightness) * (1.0 - tightness) * 40.0;

    // Penalize leaving dead space that cannot fit any plausible future item.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0; // tiny unusable sliver
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect chained fit
        } else if next_item_size <= post_residual {
            let chain_tight = (post_residual - next_item_size) as f64 / bin_capacity as f64;
            score -= (1.0 - chain_tight) * 20.0;
        } else {
            // Next item won't fit here; mildly penalize wasting a large-fitting bin.
            score += (next_item_size - post_residual) as f64 * 0.1;
        }
    }

    // Prefer filling bins that are already relatively empty-remaining vs mean residual.
    score += (bin_residual as f64 - mean_residual) * 0.3;

    // Time horizon: early in stream, be more selective (penalize loose fits);
    // late in stream, prioritize closing out bins (favor smallest residual bins).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * tightness * 20.0;
    score -= progress * tightness * 10.0;

    // Many open bins: encourage consolidation into existing bins rather than opening new.
    score += open_bins_count as f64 * 0.5;

    // New-bin candidate handling: opening a new bin is only attractive when no open bin
    // fits well (large item, poor fits elsewhere) or stream is early with few bins.
    if bin_residual == bin_capacity {
        let desperation = if fitting_bins_count == 0 { 0.0 } else { 1.0 };
        // Base cost of a new bin: high, unless item is large and would leave good residual.
        let new_bin_base = 70.0;
        let residual_quality = post_residual as f64 / bin_capacity as f64;
        // A new bin is good if the item is large (small post_residual) and stream is early.
        score = new_bin_base + residual_quality * 30.0
              + desperation * 40.0
              - (1.0 - progress) * 10.0
              + open_bins_count as f64 * 2.0;
        // Perfect fit potential in fresh bin with lookahead.
        if next_item_size > 0 && next_item_size == post_residual {
            score -= 50.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let residual = bin_residual as f64;
    let item = item_size as f64;

    // Base: prefer small post residual (tight fit).
    let mut score = post;

    // Smooth non-linear coupling: reward tight fits quadratically, scaled by stream progress.
    let tightness = 1.0 - post / cap; // 1.0 = perfect fit
    score -= 12.0 * tightness * tightness * (0.5 + progress);

    // Penalize dead space: small post_residual that is still too small for typical items.
    let dead = (post / cap).powi(3);
    score += 40.0 * dead * (1.0 - progress);

    // Reward using bins that are relatively full already (consolidation).
    let fill = 1.0 - residual / cap;
    score -= 8.0 * fill * fill;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 + progress);
    }

    // Lookahead: if next item fits exactly in the post residual, reward; if post residual
    // is smaller than next item but nonzero, penalize creating a nearly-useless gap.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual >= next_item_size {
            let match_quality = 1.0 - ((post - nxt) / cap).abs();
            score -= 10.0 * match_quality * match_quality;
        } else if post_residual > 0 {
            score += 6.0 * (1.0 - post / nxt.max(1.0) as f64) * post / cap;
        }
    }

    // New-bin candidate: mildly discourage opening new bins early, more when many open bins exist.
    if bin_residual == bin_capacity {
        score += 15.0 + 3.0 * open_bins_count as f64 * (0.5 + progress);
    } else {
        // Slight preference for bins whose residual deviates from mean (variance reduction).
        let dev = (residual - mean_residual).abs() / cap;
        score += 4.0 * dev * dev;
    }

    // Smooth global scaling of exploration vs exploitation over the stream.
    score *= 1.0 + 0.15 * (progress * std::f64::consts::PI).sin();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of post_residual (mod-based dead-space taxonomy) ---
    let cap_f = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap_f; // capacity fraction of leftover

    // Class A: perfect or near-perfect fill -> strong reward
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    }

    // Class B: dead space that nothing (min item = 1) can't use, but small items can't:
    // penalize leftovers in awkward harmonic bands.
    let band = post_residual % 25; // quarter-capacity harmonic band
    let band_penalty = match band {
        0 => -15.0,                 // exact quarter classes: reusable
        1..=10 => 8.0,              // awkward sliver just above a class line
        11..=20 => 3.0,             // mildly awkward
        _ => 0.0,
    };
    score += band_penalty;

    // Harmonic divisibility: residual divisible by common item classes is reusable
    if post_residual % 10 == 0 {
        score -= 10.0;
    } else if post_residual % 5 == 0 {
        score -= 5.0;
    }

    // Non-linear dead-space curve: mid-size leftovers are worst
    score += 0.35 * (frac * std::f64::consts::PI).sin().abs() * pr;

    // --- Lookahead coupling (k=2) ---
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // next item still fits here: reward keeping chain alive
            let slack = (post_residual - next_item_size) as f64;
            score -= 18.0 - 0.25 * slack; // prefer tight follow-up fit
            if (post_residual % next_item_size.max(1)) == 0 {
                score -= 8.0; // harmonic tiling: residual is a multiple of next item
            }
        } else {
            // next item won't fit: this placement creates a stranded residual
            let gap = (next_item_size - post_residual) as f64;
            score += 6.0 + 0.3 * gap.min(50.0);
        }
    } else {
        // last item: any residual is pure waste
        score += 0.5 * pr;
    }

    // --- Last-chance bin logic ---
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0; // avoid opening a new bin if this is the only fit
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // fresh bin: base cost plus pressure from stream state
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = cap_f * 0.9 + 10.0 * progress + 0.5 * open_bins_count as f64;
        // if existing bins are nearly full on average, new bin is fine
        if mean_residual < 15.0 {
            score -= 12.0;
        }
        // never open a new bin when a perfect/near-perfect fill exists
        if post_residual == 0 || post_residual <= 5 {
            score += 200.0;
        }
        return score;
    }

    // Tightness reward: prefer bins where item fills a large fraction of residual
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * fill_ratio * fill_ratio;

    // Mild preference to fill older/crowded bin sets
    score += 0.15 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps (<10, min item size) are pure waste.
    if post_residual < 10 {
        score -= 40.0; // perfect/near-perfect closure is excellent
    } else if post_residual <= 20 {
        score += 12.0; // small but technically usable gap: mild penalty
    }

    // Penalize gaps that cannot fit the known next item (dead space relative to lookahead).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 6.0 + 0.25 * (next_item_size - post_residual) as f64;
    }
    // Reward gaps that exactly accommodate the lookahead item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 10.0;
    }

    // Reward filling a large fraction of the bin's current residual.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 15.0 * fill_ratio;

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: when many bins are open, discourage opening new ones;
    // when few are open, a new bin is cheap.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = (open_bins_count as f64).ln().max(0.0) * (1.0 - 0.5 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure; discount early in the stream.
        score += 30.0 + 8.0 * pressure;
        // If no open bin fits well, new bin becomes more attractive.
        if fitting_bins_count == 0 {
            score -= 20.0;
        }
    } else {
        // Slight bonus for keeping bin count low by reusing open bins.
        score -= 2.0 * pressure;
    }

    // Prefer bins whose residual is close to the item (tight fit over loose fit).
    let slack = (bin_residual - item_size) as f64;
    score += 0.15 * (slack - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 1 {
        step_index as f64 / total_items as f64
    } else {
        0.0
    };

    let is_new_bin = bin_residual == bin_capacity;

    // --- Aggressive 2-step lookahead matching ---
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Reward: the next item can chain into this bin's leftover space.
            // Perfect match (post_residual == next_item_size) gets the biggest bonus.
            let slack = (post_residual - next_item_size) as f64;
            score -= 10.0 - 0.15 * slack.min(30.0);
        } else {
            // Penalize dead space: next item cannot use the leftover.
            let miss = (next_item_size - post_residual) as f64;
            score += 0.2 * miss.min(50.0);
        }
    }

    // --- Last-chance bin bonus: avoid opening a new bin when this is the only fit ---
    if !is_new_bin && fitting_bins_count == 1 {
        score -= 12.0;
    }

    // --- New-bin candidate handling ---
    if is_new_bin {
        // Default: discourage opening a new bin when existing bins could fit.
        score += 14.0;
        // But if the item nearly empties a fresh bin AND the next item is small
        // enough to likely fit the fresh residual, opening a new bin is viable.
        if next_item_size > 0 && post_residual >= next_item_size && item_size >= bin_capacity / 2 {
            score -= 10.0;
        }
        // Late in the stream, opening fresh bins is less attractive (wasted capacity).
        score += 6.0 * progress;
    }

    // --- Relative residual coupling: prefer bins tighter than the fleet average ---
    score += 0.12 * (mean_residual - bin_residual as f64);

    // --- Slightly sharpen tightness preference as the stream progresses ---
    score *= 1.0 - 0.1 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Lookahead: reward if next item fits into post residual
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 + 0.05 * next_item_size as f64;
    }

    // Penalize leaving awkward dead space (small but nonzero residual)
    if post_residual > 0 {
        let pr = post_residual as f64;
        // dead space is worse when it can't fit typical small items
        if pr < 10.0 {
            score += 15.0;
        } else {
            score += 0.35 * pr;
        }
    }

    // Penalize using a bin with large residual for a small item (waste)
    let fit_tightness = item_size as f64 / bin_residual as f64;
    score += 20.0 * (1.0 - fit_tightness);

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when no good fit exists
    if bin_residual == bin_capacity {
        score += 60.0;
        // make new bins more attractive early in the stream
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 20.0 * (1.0 - progress);
        // if many open bins already, discourage spreading
        score += 2.0 * open_bins_count as f64;
    }

    // Prefer bins with residual below mean (tighter bins first)
    score += 0.15 * (bin_residual as f64 - mean_residual);

    // Mild time horizon scaling: later in stream, be greedier about tight fits
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * fit_tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: penalize leftover space, with non-linear growth (wasted dead space hurts more)
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // Reward tight fits: smooth polynomial coupling of post_residual with item size fraction
    let fill_frac = item_size as f64 / cap;
    score -= cap * (1.0 - norm_pr).powi(3) * (0.5 + fill_frac);

    // Stream progress coupling: as stream advances, tolerate less waste in open bins
    let progress_coupling = progress * progress * (1.0 - progress);
    score += pr * progress_coupling * 2.0;

    // Last-chance bin bonus: if this is the only fitting bin, strongly prefer it
    if fitting_bins_count == 1 {
        score -= 25.0 + 15.0 * (1.0 - norm_pr);
    }

    // Lookahead: reward if next item fits exactly in post_residual (perfect chaining)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let gap = (pr - nxt) / cap;
            score -= 20.0 * (1.0 - gap * gap) * (1.0 + progress);
        } else {
            // penalize residuals that can't hold the next item and are too small to be useful
            let useless = (pr / nxt).min(1.0);
            score += 10.0 * (1.0 - useless) * progress;
        }
    }

    // Mean residual coupling: prefer bins whose post-residual moves residual toward the mean
    let dev = (pr - mean_residual).abs();
    score += dev * 0.15;

    // New-bin candidate handling: empty bin gets a moderate penalty so existing bins win,
    // but is attractive when open bins are crowded (high mean residual) or late in stream
    if bin_residual == bin_capacity {
        let crowd = mean_residual / cap;
        score = cap * (0.6 + 0.4 * progress) - 30.0 * crowd * crowd;
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
    }

    // Mild penalty for proliferating bins early in the stream
    score += open_bins_count as f64 * 0.3 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover lands in a
    // "useful" residue class (divisible by small denominators) are favored.
    let pr = post_residual;
    if pr > 0 {
        let mut harmony_bonus = 0.0;
        if pr % 10 == 0 { harmony_bonus += 6.0; }
        if pr % 20 == 0 { harmony_bonus += 4.0; }
        if pr % 25 == 0 { harmony_bonus += 3.0; }
        if pr % 50 == 0 { harmony_bonus += 3.0; }
        // Integer-division thresholds: very small leftovers are dead space.
        let dead_class = pr / 10; // 0 => pr < 10 is unusable for items >= 10
        if dead_class == 0 {
            score += 25.0; // penalize creating tiny dead space
        } else if dead_class <= 2 {
            score += 8.0;  // small-ish leftover, mildly penalized
        } else {
            score -= harmony_bonus;
        }
        // Perfect fit is the best outcome.
        if pr == 0 {
            score -= 100.0;
        }
    }

    // Lookahead coupling: reward leftovers that can host the next item exactly
    // or at least comfortably.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            // harmonic class of slack after hosting next item
            if (post_residual - next_item_size) % 10 == 0 { score -= 6.0; }
            score -= 4.0 * (1.0 - slack / cap).min(1.0);
        } else {
            // next item cannot fit here: slight penalty proportional to gap
            score += 0.15 * (next_item_size - post_residual) as f64;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a bin is only attractive when the
    // item is large relative to capacity or existing residuals are poor.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fit_pressure = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        let item_frac = item_size as f64 / cap;
        let mean_bad = (mean_residual - item_size as f64) / cap;
        // prefer new bin when item is big, no good fits exist, or residuals are tight
        let attractiveness = 0.6 * item_frac + 0.5 * fit_pressure + 0.4 * mean_bad.max(0.0) + 0.2 * progress;
        score = cap - attractiveness * 45.0;
        if next_item_size > 0 && next_item_size > item_size {
            score -= 10.0; // save current bins for the larger next item
        }
    }

    // Mild congestion: with many open bins, prefer consolidating into existing ones.
    if bin_residual != bin_capacity {
        score -= (open_bins_count as f64).ln().max(0.0) * 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to ever hold
    // another item (min item size = 1, but practically < 10 are near-dead for
    // the typical distribution) get a heavy nonlinear penalty.
    if post_residual > 0 {
        let dead = (10u32.saturating_sub(post_residual)) as f64;
        score += dead * dead * 2.5; // quadratic blow-up for tiny gaps
    }

    // Perfect fit is extremely desirable.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward tight fits: fraction of bin consumed by this placement.
    let fill_frac = item_size as f64 / bin_capacity as f64;
    score -= 25.0 * fill_frac;

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Open-bin pressure: with many open bins, avoid leaving large residuals
    // scattered; with few bins, spreading is cheaper.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64).ln().max(1.0);
    score += pressure * 3.0 * (1.0 - fill_frac);

    // Lookahead: if the next item fits exactly into the post_residual,
    // reward this placement; if it clearly won't fit, mild penalty.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size > post_residual {
            score += 8.0;
        } else {
            score -= (post_residual - next_item_size) as f64 * 0.3;
        }
    }

    // Deviation from mean residual: prefer bins whose residual is close to
    // the item size (harmonizing leftovers across bins).
    let dev = (bin_residual as f64 - item_size as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // New-bin candidate (empty bin): only attractive when this item is large
    // relative to capacity or no good fit exists elsewhere.
    if bin_residual == bin_capacity {
        score += 30.0 - 20.0 * fill_frac;
        if fitting_bins_count <= 1 {
            score -= 25.0;
        }
    }

    // Mild progress-based tightening: later in the stream, be greedier.
    score -= 5.0 * progress * fill_frac;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: waste relative to capacity.
    let tightness = (item_size as f64) / (bin_residual as f64);
    score -= 30.0 * tightness;

    // Penalize dead space that is too small for typical items (1..100 range).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver
    } else if post_residual >= 10 && post_residual < 25 {
        score += 8.0; // hard-to-fill gap
    }

    // Lookahead: reward if next item fits exactly into the post residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0; // perfect chain
        } else if next_item_size <= post_residual {
            score -= 15.0 * (next_item_size as f64) / (post_residual as f64);
        } else {
            // next item won't fit here; slight penalty if we leave large gap
            score += 3.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Global state coupling: many open bins with high mean residual -> consolidate.
    let progress = (step_index as f64) / (total_items as f64).max(1.0);
    if open_bins_count > 3 && (bin_residual as f64) > mean_residual {
        score -= 5.0 * (open_bins_count as f64).ln();
    } else if (bin_residual as f64) < mean_residual {
        score += 4.0;
    }

    // New-bin candidate handling: default penalty, waived when fits are poor
    // or stream is early and item is large.
    if bin_residual == bin_capacity {
        let poor_fit = fitting_bins_count == 0 || tightness < 0.45;
        let early = progress < 0.25;
        if poor_fit {
            score -= 18.0; // opening a fresh bin is fine
        } else if early {
            score -= 2.0;
        } else {
            score += 30.0; // late stream: strongly prefer existing bins
        }
    }

    // Small dynamic time-horizon nudge: as stream progresses, tighten selection.
    score -= 6.0 * progress * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: prefer small post-residual, scaled by smooth progress coupling
    let mut score = pr * (0.6 + 0.8 * progress * (1.0 - progress) * 4.0 / 4.0 + 0.4 * progress);

    // Non-linear penalty for dead space: post-residual that is too small to matter
    // (unusable sliver) vs. mid-range gaps; smooth polynomial in normalized residual.
    let r = pr / cap; // 0..1
    let dead = r * r * (1.0 - r) * (1.0 - r); // peaks mid-range, vanishes at extremes
    score -= 30.0 * dead;

    // Penalize tightness relative to item size: smooth quadratic coupling
    let tight = (it / cap) * (it / cap);
    score += 20.0 * tight * (1.0 - r);

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual < cap {
        score -= 25.0 + 15.0 * progress;
    }

    // New-bin candidate handling: brand-new empty bin should only win when
    // no open bin offers a decent fit. Penalize by current fit availability.
    if bin_residual == bin_capacity {
        let crowded = if open_bins_count > 0 {
            (open_bins_count as f64).ln().max(0.0) / (1.0 + open_bins_count as f64).ln()
        } else { 0.0 };
        score += 12.0 + 20.0 * (1.0 - crowded) + 10.0 * progress;
        // If next item is large and this item is small, opening a fresh bin is risky
        if next_item_size > 0 {
            let nx = next_item_size as f64 / cap;
            score += 15.0 * nx * (1.0 - it / cap);
        }
    } else {
        // Reward leaving room for the lookahead item (smooth interaction)
        if next_item_size > 0 && (post_residual as u64) >= (next_item_size as u64) {
            let slack = pr - next_item_size as f64;
            score -= 8.0 * (1.0 - (slack / cap).min(1.0));
        }
    }

    // Mild preference for bins deviating from mean residual (smooth divergence term)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 5.0 * dev * dev * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: which capacity fraction "slot" do we land in?
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    let post_class = post_residual / quarter; // 0..=4 harmonic class
    let next_class = if next_item_size == 0 { 5 } else { next_item_size / quarter }; // 0..=4, 5 = none

    // Reward when next item's harmonic class matches (or fits within) the post-residual class:
    // exact class match => near-perfect pair fill
    if next_item_size > 0 {
        if next_class == post_class {
            score -= 18.0;
        } else if next_item_size <= post_residual {
            // next fits but imperfectly: penalize proportionally to wasted gap
            let gap = (post_residual - next_item_size) as f64;
            score += gap * 0.9;
            // harmonic resonance bonus: classes sum to a full bin
            if post_class + next_class + 1 == 4 {
                score -= 10.0;
            }
        } else {
            // next item cannot use this residual: dead space penalty grows with class depth
            score += (post_class as f64 + 1.0) * 7.0;
        }
    }

    // Integer-division thresholds: tiny residuals (class 0) are near-perfect fills
    if post_class == 0 && post_residual > 0 {
        score -= 25.0;
    }
    // Large awkward residuals (class 3, i.e. >75% empty) are wasteful unless last-chance
    if post_class >= 3 {
        score += 12.0;
    }

    // Last-chance bin: strongly favor using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate: prefer it only when no open bin offers a tight harmonic fit.
    if bin_residual == bin_capacity {
        // opening a bin is cheap early, expensive late
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = 45.0 + 55.0 * progress;
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 8.0;
        }
    }

    // Mild pressure to consolidate when many bins are open
    score += open_bins_count as f64 * 0.15;
    // Nudge toward bins with residuals near the mean (keeps bin states uniform)
    score += ((post_residual as f64 - mean_residual) / bin_capacity as f64).abs() * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small for any item (1..=100 range, min item 1)
    // are pure waste; weight them heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0 * (1.0 - post_residual as f64 / 20.0);
    }

    // Reward near-perfect fits (small but non-zero post_residual).
    if post_residual <= 5 {
        score -= 30.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Pressure to close bins: penalize spreading across many open bins
    // when residuals are already fragmented (mean residual low).
    let fragmentation = 1.0 - mean_residual / bin_capacity as f64;
    score += open_bins_count as f64 * 2.0 * fragmentation.max(0.0);

    // If the next item would fit exactly in the post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size < 10 {
        score -= 20.0;
    }
    // Penalize if post_residual can't fit the next item but bin_residual could have
    // (wasting the chance to keep a useful gap).
    if next_item_size > 0 && post_residual < next_item_size && post_residual < 10 {
        score += 15.0;
    }

    // New-bin candidate: neutral baseline, slightly penalized early so we prefer
    // existing bins, but attractive late in the stream when fragmentation is high.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = bin_capacity as f64 * 0.5 + 30.0 - 25.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match of post_residual to next item size.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 40.0 / (1.0 + diff); // strong bonus when post_residual ~ next_item_size
        // Perfect 2-step fit
        if post_residual == next_item_size {
            score -= 25.0;
        }
        // Perfectly tight fit for current item
        if post_residual == 0 {
            score -= 15.0;
        }
    }

    // Penalize leaving small unusable dead space (< smallest plausible item)
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Prefer bins tighter than the mean residual (better fill of crowded bins)
    score -= (mean_residual - post_residual as f64) * 0.3;

    // New-bin candidate: penalize mildly so we only open when fits are truly bad
    if bin_residual == bin_capacity {
        score += 10.0;
        // Early in stream, opening bins is cheaper
        if total_items > 0 {
            let progress = step_index as f64 / total_items as f64;
            score -= 10.0 * (1.0 - progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward near-perfect fits.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 25.0;
    } else if post_residual <= 25 {
        score -= 8.0;
    }

    // Dead-space penalty: residual too small to be useful later (min item size 1,
    // but small residuals are still weakly usable; scale with tightness).
    if post_residual > 0 && post_residual < item_size {
        score += (post_residual as f64) * 0.3;
    }

    // Lookahead: penalize if the next item cannot use the post residual.
    if next_item_size > 0 {
        if next_item_size > post_residual {
            score += (next_item_size - post_residual) as f64 * 0.4;
        } else {
            // Reward bins that can also host the next item (chaining).
            score -= (post_residual - next_item_size) as f64 * 0.2;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are crowded
    // or the fit here is terrible.
    if bin_residual == bin_capacity {
        score += 55.0;
        let crowding = open_bins_count as f64 * (mean_residual / bin_capacity as f64);
        // If open bins are mostly full, opening a new bin is fine.
        score -= crowding * 6.0;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            // A fresh bin is attractive when the next item is large.
            score -= next_item_size as f64 * 0.15;
        }
    }

    // Prefer filling fuller (more crowded) bins slightly more.
    score -= (bin_capacity - bin_residual) as f64 * 0.1;

    // Time-horizon modulation: early in the stream be conservative with new bins,
    // late in the stream accept tight fits more aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 10.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Mild penalty for spreading across many open bins when mean residual is high.
    score += open_bins_count as f64 * 0.05 * (mean_residual / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let norm_pr = pr / cap;
    let norm_it = it / cap;

    // Base: prefer small post-residual, with non-linear sharpening
    let mut score = norm_pr * (1.0 + 2.0 * norm_pr * (1.0 - norm_pr));

    // Quadratic coupling: tight fits (small post_residual relative to item) rewarded
    let tightness = 1.0 - norm_pr / (norm_it + 1e-6);
    score -= 0.35 * tightness * tightness * (1.0 - progress);

    // Stream progress: later in stream, residual waste matters more (cubic ramp)
    let late = progress * progress * (3.0 - 2.0 * progress);
    score += 1.2 * late * norm_pr;

    // Lookahead: if next item fits into post_residual, reward this bin
    if next_item_size > 0 {
        let nx = next_item_size as f64 / cap;
        if pr >= next_item_size as f64 {
            let combo = norm_it + nx;
            score -= 0.5 * (1.0 - (combo - 1.0).abs()) * (1.0 - late);
        } else {
            score += 0.15 * nx * late;
        }
    }

    // Last-chance bonus: only bin that fits
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 0.8;
    }

    // New-bin candidate: penalize mildly early, strongly late unless item is large
    if bin_residual == bin_capacity {
        let newbin_pen = 0.6 + 1.5 * late - 0.5 * norm_it * late;
        score += newbin_pen;
    } else {
        // Prefer bins with residual close to item (best-fit flavor, smooth)
        let gap = (bin_residual as f64 - it) / cap;
        score += 0.25 * gap * gap;
        // Slight preference for bins below mean residual (consolidate emptier bins)
        score += 0.05 * ((mean_residual - bin_residual as f64) / cap);
    }

    // Open bin count pressure: many open bins -> consolidate
    score += 0.02 * (open_bins_count as f64).ln().max(0.0) * (1.0 - late) * norm_pr;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: overwhelmingly favored
    if post_residual == 0 {
        score -= 1000.0;
        return score;
    }

    // Harmonic class of post_residual: classify dead space quality
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Waste tiers via integer-division thresholds on post_residual
    // Residual <= 10 is nearly unusable (min item is 10): heavy penalty
    if post_residual < 10 {
        score += 60.0;
    } else if post_residual <= 20 {
        score += 15.0;
    } else if post_residual <= 33 {
        score += 5.0;
    }

    // Modulo arithmetic: post_residual divisible by common item classes (10, 20, 25)
    if post_residual % 10 == 0 {
        score -= 8.0; // leaves a reusable harmonic slot
    }
    if post_residual % 25 == 0 {
        score -= 6.0;
    }
    if post_residual % 3 == 0 {
        score -= 1.0;
    }

    // Lookahead: does next_item_size fit exactly or well into post_residual?
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if next_item_size == post_residual {
            score -= 200.0; // chains a perfect fit
        } else if next_item_size < post_residual {
            let nxt_left = post_residual - next_item_size;
            if nxt_left < 10 {
                score -= 30.0; // near-perfect chain
            } else {
                score -= 10.0 * (1.0 - nxt_left as f64 / 100.0);
            }
        } else {
            // next item cannot use this residual: penalize proportional to gap
            score += 0.3 * (nx - pr).min(60.0);
        }
    }

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only prefer a fresh bin if all open bins
    // would leave terrible dead space and the item is large
    if bin_residual == bin_capacity {
        // baseline score for a fresh bin = capacity - item = post_residual (large),
        // so it naturally loses unless open bins are penalized heavily above.
        // Small nudge to make fresh bins slightly less attractive early on.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 * (1.0 - progress);
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 15.0; // fresh bin can host the next item too
        }
    }

    // Tightness coupling: reward filling bins below mean residual (compact bins)
    if (bin_residual as f64) < mean_residual {
        score -= 4.0;
    } else {
        score += 2.0;
    }

    // Many open bins: prefer consolidation into emptier bins
    if open_bins_count > 4 {
        score += 0.05 * open_bins_count as f64 * (1.0 - item_size as f64 / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let is_new_bin = bin_residual == bin_capacity;

    // Strict dead-space avoidance: gaps that are too small to hold the
    // lookahead item (or any plausible item) are heavily penalized.
    if !is_new_bin && post_residual > 0 {
        let threshold = if next_item_size > 0 { next_item_size } else { 10 };
        if post_residual < threshold {
            let dead = (threshold - post_residual) as f64;
            score += 2.0 + dead * 0.8 + dead * dead * 0.05;
        }
        // Very small unusable slivers (below the minimum plausible item size)
        if post_residual < 5 {
            score += 25.0;
        }
    }

    // Lookahead coupling: reward bins that remain usable for the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 3.0;
    }

    // Last-chance bonus: if this is the only bin that fits, prefer it strongly
    // over opening a new bin.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 30.0;
    }

    // Tight-fit reward: favor bins whose residual is close to the item size.
    if !is_new_bin {
        let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
        score -= (1.0 - tightness) * 5.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if is_new_bin {
        // Pressure from number of open bins: discourage proliferation.
        score += 12.0 + open_bins_count as f64 * 1.5;
        // If other bins can also fit the item, opening a new bin is wasteful
        // unless their residuals are large (mean_residual high).
        if fitting_bins_count > 1 {
            score += 20.0 - mean_residual * 0.15;
        }
        // Late in the stream, keep consolidating rather than opening bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact/near match of post_residual with next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (post_residual as f64 - nxt).abs();
        if post_residual as f64 >= nxt {
            // Next item fits perfectly: strong reward.
            if diff < 0.5 {
                score -= 60.0;
            } else {
                score -= 25.0 * (1.0 - diff / cap);
            }
        } else {
            // Next item won't fit here: penalize proportionally to how badly it misses.
            score += 10.0 + 20.0 * (nxt - post_residual as f64) / cap;
        }
    }

    // Tight fit reward: small post_residual is good (dead space minimization).
    score -= 15.0 * (1.0 - post_residual as f64 / cap);

    // Compare against mean residual: bins with residual close to item are best fits.
    let mean_gap = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * mean_gap;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // Early stream: encourage consolidation into few bins; late stream: be pickier.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * progress * (post_residual as f64 / cap);

    // New-bin candidate: penalize unless all open fits are poor.
    if bin_residual == bin_capacity {
        let baseline = 25.0 + 20.0 * progress;
        if fitting_bins_count == 0 {
            score -= 100.0; // forced new bin
        } else {
            score += baseline;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 40.0 * fit_ratio * fit_ratio;

    // Penalize large dead space relative to capacity.
    let dead = post_residual as f64 / bin_capacity as f64;
    score += 25.0 * dead * dead;

    // Lookahead: if next item fits in post_residual, big bonus.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 30.0;
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Penalize wasting space the next item could have used.
        score += 0.15 * (next_item_size as f64 - post_residual as f64).max(0.0);
    }

    // Last-chance bin: strong bonus to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Global state: many open bins with high mean residual -> prefer filling existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);
    score -= 0.1 * mean_residual * progress;

    // New-bin candidate handling: mildly penalize opening a new bin unless the item
    // fits poorly everywhere; empty-bin call has post_residual == capacity - item.
    if bin_residual == bin_capacity {
        // Base penalty so a decent fit in an open bin usually wins.
        score += 15.0;
        // But if the item is large, opening a fresh bin is attractive.
        if item_size as f64 / bin_capacity as f64 > 0.6 {
            score -= 12.0;
        }
        // Late in the stream, avoid spreading items across many bins.
        if progress > 0.7 {
            score += 10.0 * (progress - 0.7);
        }
    }

    // Small tie-breaker against fragmentation.
    score += 0.01 * (post_residual as f64 % 10.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early on: tolerate larger residuals; late: penalize wasted space quadratically.
    let prn = pr / cap;
    let phase = progress * progress * (3.0 - 2.0 * progress); // smoothstep
    score += prn * prn * (1.0 + 60.0 * phase) * cap;

    // Reward tight fits (small post_residual) increasingly as stream progresses.
    let tightness = 1.0 - prn;
    score -= tightness * tightness * (10.0 + 40.0 * phase);

    // Penalize bins whose residual deviates from the mean residual (waste spreading).
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 8.0 * dev * dev;

    // Lookahead: reward if next item fits into post_residual, penalize otherwise.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            score -= 15.0 * (1.0 - prn) * (0.5 + progress);
        } else {
            score += 12.0 * prn * (1.0 - progress);
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0 + 20.0 * phase;
    }

    // Many open bins: discourage fragmentation by favoring larger residual bins.
    let open_f = open_bins_count as f64;
    score -= 3.0 * (bin_residual as f64 / cap) * (open_f / (open_f + 5.0));

    // New-bin candidate: keep it neutral-ish, slightly penalized unless residual is huge.
    if bin_residual == bin_capacity {
        score += 5.0 - 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class: classify post_residual into capacity fractions
    let cap = bin_capacity as f64;
    let frac = post_residual as f64 / cap;

    // Penalize residual classes that are hard to fill (small dead space)
    if post_residual > 0 {
        if post_residual <= 10 {
            score += 40.0; // tiny dead space is useless
        } else if post_residual <= 20 {
            score += 15.0;
        } else if post_residual <= 50 {
            score -= 5.0; // sweet spot: half-ish space still useful
        } else {
            score -= 10.0; // large residual keeps flexibility
        }
    }

    // Integer-division thresholds on post_residual (harmonic buckets of 25)
    let bucket = post_residual / 25;
    score -= bucket as f64 * 6.0;

    // Lookahead coupling: does next item fit the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0;
            // exact match bonus
            if next_item_size == post_residual {
                score -= 30.0;
            }
        } else {
            score += 4.0; // next item won't fit here; waste of a good residual
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when current fit is bad
    if bin_residual == bin_capacity {
        let bad_fit = post_residual < item_size.min(next_item_size.max(1)) as u32
            || (post_residual <= 10 && post_residual > 0);
        if bad_fit {
            score -= 35.0;
        } else {
            score += 20.0;
        }
        // Opening bins early in the stream is cheaper than late
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= (1.0 - progress) * 10.0;
        score += open_bins_count as f64 * 2.0;
    }

    // Modulo arithmetic on post_residual: residues near multiples of 10 are
    // more likely to be filled by typical item sizes
    let r = post_residual % 10;
    if r == 0 && post_residual > 0 {
        score -= 8.0;
    } else if r >= 8 || r <= 2 {
        score += 6.0;
    }

    // Mean residual alignment: prefer bins whose residual is below mean
    // (tighten nearly-full bins first)
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    } else {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest plausible
    // future item (<= ~12) are nearly worthless -> heavy penalty.
    if post_residual < 12 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0;
    } else if post_residual < 35 {
        score += 8.0;
    }

    // Reward tight fits: small post_residual relative to item size is good.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * tightness;

    // Perfect fill is ideal.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead coupling: if the next item fits the post residual, big reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 35.0;
    }
    // If next item is large and post_residual is a tiny unusable gap, penalize.
    if next_item_size > post_residual && post_residual > 0 && post_residual < 15 {
        score += 20.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, favor filling.
    let pressure = (open_bins_count as f64).ln() * 4.0;
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive when existing fit is bad
        // (large post_residual dead space elsewhere) or many bins already open.
        score += 15.0 + pressure;
        if post_residual_like_existing(item_size, mean_residual) {
            score += 5.0;
        }
    } else {
        score -= pressure * 0.5;
    }

    // Progress-based nudge: late in the stream, consolidate harder.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual != bin_capacity {
        score -= 10.0 * progress;
    }

    score
}

// Helper inlined logic (kept as pure expression over allowed variables).
fn post_residual_like_existing(item_size: u32, mean_residual: f64) -> bool {
    item_size as f64 > mean_residual
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (waste minimization).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio;

    // 2-step lookahead: reward if next item fits exactly into post_residual.
    if next_item_size > 0 && post_residual >= next_item_size {
        let next_fit = next_item_size as f64 / post_residual as f64;
        score -= 10.0 * next_fit; // perfect chaining bonus
        if post_residual == next_item_size {
            score -= 15.0; // exact 2-item completion
        }
    } else if next_item_size > 0 {
        // Penalize dead space that next item cannot use.
        let dead = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
        score += 0.05 * dead;
    }

    // Penalize leaving residuals too small for typical items (dead space).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Relative-to-mean coupling: prefer bins with residual near/above mean to balance load.
    score += 0.3 * ((post_residual as f64 - mean_residual).abs());

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when the item is large or no good fit exists.
    if bin_residual == bin_capacity {
        score += 18.0; // default penalty for opening new bin
        if item_size > 50 || fitting_bins_count == 0 {
            score -= 25.0;
        }
        // Avoid opening new bins early in the stream.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * (1.0 - progress);
    }

    // Slight preference for fuller bins overall.
    score -= 0.1 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) nonlinearly.
    if post_residual == 0 {
        score -= 60.0; // perfect fill is excellent
    } else {
        let slack_ratio = post_residual as f64 / bin_capacity as f64;
        score += slack_ratio * slack_ratio * 40.0; // penalize dead space quadratically
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        // Slight preference for more crowded bins when alternatives exist.
        score += 2.0 * (fitting_bins_count as f64 - 1.0).min(5.0);
    }

    // Lookahead: if the next item fits into this bin's post_residual, reward it;
    // otherwise penalize leaving a residual that wastes the next item's chance.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else if post_residual > 0 && post_residual < next_item_size {
            score += 8.0 * (post_residual as f64 / next_item_size as f64);
        }
    } else {
        // Last item: just fill as tightly as possible.
        score -= 10.0;
    }

    // Global state: prefer filling bins when many bins are open (consolidate),
    // and prefer opening new bins early when few are open and fit is poor.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let consolidation = (open_bins_count as f64).ln_1p() * 3.0;
    score -= consolidation * (1.0 - progress * 0.5);

    // Mean residual coupling: if this bin is below-average residual (tighter),
    // favor it; if above-average, mildly penalize.
    score += 0.15 * (bin_residual as f64 - mean_residual);

    // New-bin candidate decision: only open a new bin when the item is large
    // relative to typical residuals and fit elsewhere is bad.
    if bin_residual == bin_capacity {
        let poor_fit_elsewhere = fitting_bins_count == 0
            || (post_residual as f64 > mean_residual && fitting_bins_count <= 2);
        if poor_fit_elsewhere {
            score -= 18.0;
        } else {
            score += 15.0; // discourage wasteful new bins
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr_norm = pr / cap;

    // Base: prefer small post-residual, with non-linear sharpening
    let mut score = pr * (1.0 + 0.8 * pr_norm * pr_norm);

    // Smooth coupling of post-residual with stream progress:
    // late in the stream, tight fits matter more; early, waste is cheaper
    let progress_coupling = pr_norm * (0.5 + 1.5 * progress * progress);
    score += 40.0 * progress_coupling;

    // Penalize post-residuals that no plausible item can use (dead space),
    // smoothly via distance to the smallest item size
    let dead = (pr - 1.0).max(0.0) as f64;
    score += 0.15 * dead * dead / cap;

    // Lookahead: reward leaving room for the next item, smoothly
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let diff = pr - nx;
        if diff >= 0.0 {
            let fit_quality = 1.0 - (diff / cap).min(1.0);
            score -= 12.0 * fit_quality * (1.0 + progress);
        } else {
            score += 6.0 * (-diff / cap).min(1.0);
        }
    }

    // Last-chance bin: strong reward to use it rather than open a new one
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 + progress);
    }

    // Mild penalty for spreading across many bins relative to mean residual
    score += 0.5 * (open_bins_count as f64).ln() * (mean_residual / cap);

    // New-bin candidate: make it moderately attractive only when residuals
    // across open bins are small (item barely fits anywhere)
    if bin_residual == bin_capacity {
        let tightness = (mean_residual / cap).min(1.0);
        score = 30.0 + 60.0 * (1.0 - tightness) - 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose residual falls into
    // "harmonic" residue classes (multiples of common item sizes) are
    // more likely to be filled by future items -> reward them.
    let pr = post_residual;
    let mut harmony: f64 = 0.0;
    for m in [10u32, 20, 25, 30, 40, 50].iter() {
        if pr >= *m && pr % m == 0 {
            harmony += 12.0;
        }
    }
    score -= harmony;

    // Dead-space penalty: tiny residuals that no item (1..=100 realistic
    // granularity ~10) can ever use are wasted. Penalize residuals < 10 hard.
    if pr > 0 && pr < 10 {
        score += 60.0;
    }

    // Perfect fit is ideal.
    if pr == 0 {
        score -= 100.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // strongly reward this bin (chained packing).
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 45.0;
        } else if next_item_size <= pr {
            let slack = (pr - next_item_size) as f64;
            // reward decreasing with leftover slack after the chain
            score -= 30.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item cannot follow; slight penalty if post_residual small
            score += 5.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: opening a new bin wastes (capacity - item).
    // Only attractive when the item is large relative to capacity or no
    // open bin fits well.
    if bin_residual == bin_capacity {
        let fill_frac = item_size as f64 / bin_capacity as f64;
        // base cost of a fresh bin
        score = 0.5 * bin_capacity as f64;
        // large items justify fresh bins
        score -= 40.0 * fill_frac;
        // if many bins fit already, prefer using them
        if fitting_bins_count > 0 {
            score += 25.0 + 5.0 * fitting_bins_count as f64;
        }
        // early in stream, opening bins is fine (builds diversity)
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 20.0 * (1.0 - progress);
        // avoid perfect-fit loss on fresh bin
        if pr == 0 { score -= 100.0; }
    }

    // Mild pressure to consolidate: prefer bins with below-mean residual
    score += 0.15 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small for the smallest plausible item are wasted.
    let min_useful = next_item_size.min(item_size).max(1);
    if post_residual < min_useful && post_residual > 0 {
        score += 40.0 + 0.5 * post_residual as f64;
