        score -= 20.0 / (1.0 + slack);
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 10.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Open-bin pressure: when many bins are open, prefer filling existing ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (2.0 + 4.0 * progress);

    // New-bin candidate: penalize unless current residuals are large/fragmented.
    if bin_residual == bin_capacity {
        let avg_gap = mean_residual;
        score += 35.0 - 25.0 * (avg_gap / bin_capacity as f64);
        if post_residual < 20 { score += 25.0; }
    }

    // Prefer bins whose residual is close to the mean (keep residual distribution tight).
    score += 0.3 * (bin_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let next = next_item_size as f64;

    let mut score = post;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size
    if next > 0.0 {
        let gap = (post - next).abs();
        if gap < 0.5 {
            score -= 40.0; // exact fit for the next item
        } else {
            score += gap * 0.6; // penalize mismatch with lookahead
        }
        // post_residual can still hold next item (even if not exact)
        if post >= next && post < next * 2.0 {
            score -= 8.0;
        }
        // dead space: residual too small for any plausible item (min size 1, but typical)
        if post < next.min(10.0) && post > 0.0 {
            score += 10.0;
        }
    }

    // Relative to mean residual: prefer bins tighter than average
    score += (post - mean_residual) * 0.3;

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin unless nothing fits well
    if bin_residual == bin_capacity {
        let new_bin_penalty = if next > 0.0 && next <= cap {
            // opening is fine if item nearly fills a fresh bin
            12.0 - (cap - item_size as f64) * 0.1
        } else {
            20.0
        };
        score += new_bin_penalty;
    }

    // Tight packing reward: waste fraction of capacity
    score += (post / cap) * 5.0;

    // Late in stream: consolidate harder, avoid spreading
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (post / cap) * 10.0 * progress;
    score -= 5.0 * progress * (open_bins_count as f64).ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer tight fits: reward small post_residual non-linearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize dead space that cannot fit a typical future item.
    if post_residual > 0 && (post_residual < 10 || post_residual > 50) {
        score += 12.0;
    }

    // Lookahead: bonus if next item fits exactly into post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 10.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            score += 8.0 * (1.0 - post_residual as f64 / next_item_size as f64);
        }
    }

    // Last chance bin: strong reward to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive when open bins fit poorly.
    if bin_residual == bin_capacity {
        score += 15.0 + 2.0 * open_bins_count as f64;
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score += 5.0 * (next_item_size as f64 / bin_capacity as f64);
        }
    }

    // Global state coupling: many open bins with high mean residual -> consolidate.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if mean_residual > (item_size as f64) * 1.5 && open_bins_count > 1 {
        score -= 6.0 * mean_residual / bin_capacity as f64 * (1.0 - progress);
    }

    // Mild time pressure: late in stream, avoid opening extra bins.
    score += 10.0 * progress * (open_bins_count as f64 / (total_items.max(1) as f64).sqrt());

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let br = bin_residual as f64;
    let it = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: prefer tight fits (small post_residual), with a convex polynomial
    // so very small residuals are rewarded super-linearly.
    let mut score = pr + 0.0035 * pr * pr / cap;

    // Smooth coupling of residual waste with stream progress:
    // early on, tolerate slack (future items may fill it); late, punish it.
    let waste_weight = 0.6 + 1.4 * progress * progress;
    score += waste_weight * (pr / cap) * (pr / cap) * cap * 0.25;

    // Penalize leaving residuals that match neither current nor next item well:
    // smooth mismatch term between post_residual and next_item_size.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let diff = (pr - nx).abs();
        score += 0.4 * (diff / cap) * (diff / cap) * cap;
        // Reward residual that can hold the lookahead item (smooth sigmoid-like)
        let fits_next = 1.0 / (1.0 + (-6.0 * (pr - nx) / cap).exp());
        score -= 3.0 * fits_next * (nx / cap);
    }

    // Penalize fragmentation relative to mean residual across open bins:
    // a bin far below mean residual is "dead" space; discourage deepening it.
    let frag = (pr - mean_residual).abs();
    score += 0.15 * (frag / cap) * (frag / cap) * cap;

    // Last-chance bin: strongly reward using the only fitting bin to avoid new bins.
    if fitting_bins_count <= 1 && bin_residual != bin_capacity {
        score -= 5.0 + 4.0 * progress;
    }

    // New-bin candidate handling: opening a new bin is only attractive when the
    // item fits poorly everywhere (large post_residual relative to capacity)
    // or few bins are open. Smooth gate instead of hard threshold.
    let is_new_bin = (bin_residual == bin_capacity) && (bin_capacity == bin_capacity);
    if is_new_bin {
        let poor_fit = (pr / cap).powi(2); // == 1.0 for a fresh bin, but gate by item context
        let openness = 1.0 / (1.0 + (open_bins_count as f64 / 6.0).ln().max(-6.0));
        score += 2.0 * openness * (1.0 - poor_fit) * (1.0 - progress);
        // A fresh bin has pr == cap; add intrinsic cost so it only wins when
        // existing-bin scores are inflated by bad fits.
        score += 4.0;
    }

    // Mild reward for filling a large fraction of the bin (high fill ratio),
    // smooth in item size.
    score -= 1.5 * (it / cap) * (it / cap);

    // Small penalty for proliferating bins early.
    score += 0.02 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the item: coarse size classes via integer division
    let item_class = item_size / 10;
    let next_class = if next_item_size == 0 { 0 } else { next_item_size / 10 };

    // Base fit quality: reward tight fits (small post_residual)
    let post_frac = post_residual as f64 / cap;
    score = post_frac * 100.0;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 50.0;
    }

    // Harmonic pairing: does next item fit exactly into post_residual?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            // next item fits, but with slack — mild reward scaled by tightness
            let slack = (post_residual - next_item_size) as f64 / cap;
            score -= 20.0 * (1.0 - slack);
        } else {
            // next item will not fit here: penalize bins that strand space
            score += 10.0;
        }
    }

    // Modulo / class complementarity: penalize if item class and post_residual
    // class are "misaligned" (post residual too small to host common classes)
    let post_class = post_residual / 10;
    if post_residual > 0 && post_residual < 10 {
        // tiny dead space is bad unless it's a perfect fit scenario
        score += 15.0;
    }
    // Reward when post_residual belongs to a "useful" harmonic class
    // (multiples of 10 host more future items)
    if post_residual >= 10 && post_residual % 10 == 0 {
        score -= 5.0;
    } else if post_residual >= 10 {
        score += 3.0;
    }

    // Last-chance bin: strongly favor using the only bin that fits
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: make empty bin attractive only when
    // open bins are crowded or fit is poor
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // baseline cost of opening a new bin
        score = 0.5 * cap;
        // cheaper to open when many bins are open and residuals are low
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 10.0 * progress;
        score += 5.0 * open_bins_count as f64;
        // if mean residual can't host this item comfortably, opening is fine
        if mean_residual < item_size as f64 {
            score -= 20.0;
        }
        // don't open a new bin if this is a large item (few alternatives anyway)
        if item_class >= 7 {
            score += 15.0;
        }
        // if next item is huge, opening a fresh bin now wastes it
        if next_class >= 7 && next_item_size > 0 {
            score += 10.0;
        }
    } else {
        // Prefer filling bins with high residual relative to mean
        if (bin_residual as f64) > mean_residual {
            score -= 5.0;
        } else {
            score += 3.0;
        }
    }

    // Penalize leaving residual that no typical class (10..80) fits into
    if post_residual > 0 && post_residual < 10 {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: heavily penalize small unusable gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 12.0;
    }

    // Reward perfect or near-perfect fits.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Open-bin pressure: many open bins -> prefer filling existing ones.
    let pressure = open_bins_count as f64 / 20.0;
    score -= pressure * (bin_residual as f64 - post_residual as f64);

    // Prefer bins whose residual is already below mean (concentrate fill).
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    }

    // Lookahead: reward if next item fits the post-residual exactly-ish.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap < 10 {
            score -= 15.0;
        } else {
            score -= 5.0;
        }
    } else if next_item_size > post_residual as u32 && post_residual > 0 {
        // next item cannot use leftover -> penalize dead space more.
        score += 10.0;
    }

    // New-bin candidate: baseline score so it's chosen only when fits are poor.
    if bin_residual == bin_capacity {
        score = 30.0 + open_bins_count as f64 * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Two-step lookahead: reward when the next item fits snugly after this placement.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let chain_residual = post_residual - next_item_size;
            // Perfect 2-step fill is heavily rewarded.
            score -= 40.0 - chain_residual as f64 * 0.8;
        } else {
            // Next item cannot follow: penalize proportionally to the shortfall.
            let shortfall = next_item_size - post_residual;
            score += shortfall as f64 * 0.6;
        }
    }

    // Penalize dead space that is too small for typical items (unusable gap).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Compare residual against mean residual: prefer bins that stay near average fill.
    score += (post_residual as f64 - mean_residual) * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // New-bin candidate: only attractive if no decent fit exists elsewhere;
    // make empty-bin score high unless many bins are open and fit is poor.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = bin_capacity as f64 * 0.9 + progress * 10.0
            - if fitting_bins_count == 0 { 60.0 } else { 0.0 };
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual small relative to capacity.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score -= 12.0 * (1.0 - tightness * 4.0).max(0.0); // bonus when post_residual < 25% of capacity

    // Penalize dead space that is too small for the smallest plausible item,
    // scaled by how much of the bin is consumed.
    if post_residual > 0 && post_residual < 10 {
        score += 6.0;
    }

    // Lookahead: if next item fits exactly in the post-residual, reward strongly.
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = (post_residual - next_item_size) as f64;
        score -= 10.0 * (1.0 - gap / bin_capacity as f64);
    } else if next_item_size > post_residual {
        // Next item won't fit here; slight penalty if we leave awkward space.
        score += 2.0 * tightness;
    }

    // Last-chance bonus: this is the only bin that fits the item.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Discourage opening new bins when existing bins fit reasonably well.
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost of a fresh bin, discounted late in the stream
        // or when open bins are crowded.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let crowd = open_bins_count as f64 / (open_bins_count as f64 + 3.0);
        score += 30.0 - 10.0 * progress - 8.0 * crowd;
        // If the new bin would hold the next item too, slightly cheaper.
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 4.0;
        }
    }

    // Global residual pressure: when mean residual is high, prefer using fuller bins
    // (i.e., bins whose residual is below mean).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    } else {
        score += 2.0;
    }

    // Mild preference for filling nearly-empty bins early to consolidate.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 5.0 * fill_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: penalize wasted residual, quadratically so small dead space is heavily avoided.
    let mut score = post + 0.9 * (post * post) / cap;

    // Reward tight fits: normalized fill ratio subtracts from score.
    let fill = (bin_residual as f64 - post) / cap;
    score -= 6.0 * fill * fill;

    // Smooth non-linear coupling with stream progress: early on, tolerate slack;
    // late in the stream, demand tight packing (amplify post_residual penalty).
    let phase = progress.sin();
    score *= 1.0 + 0.8 * phase * (post / cap);

    // Lookahead coupling: if the next item fits into the post residual, reward this bin.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let snug = 1.0 - ((post - nxt) / cap).abs();
            score -= 4.0 * snug;
        } else {
            // Next item won't fit here: mild penalty proportional to overflow fraction.
            score += 2.0 * (nxt - post) / cap;
        }
    }

    // Last-chance bonus: this is the only bin that fits the item; strongly prefer it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 5.0 + 3.0 * fill;
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    // Penalize opening a new bin when good fitting bins exist; allow it when
    // the item is large and fits would leave big dead space.
    if bin_residual == bin_capacity {
        score += 8.0;
        if fitting_bins_count > 0 {
            score += 4.0 * (item_size as f64 / cap);
        }
        // Opening fresh bins early is cheaper than late fragmentation.
        score -= 3.0 * (1.0 - progress);
    }

    // Context term: bins far from the mean residual are slightly deprioritized
    // to keep residuals homogeneous.
    score += 0.5 * ((post - mean_residual) / cap).abs();

    // Mild preference to spread load when many bins are open.
    score -= 0.3 * (open_bins_count as f64).ln().max(0.0) * fill;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residuals divisible by common
    // item sizes (10/20/25/50) are "usable" classes; odd leftovers are dead space.
    let pr = post_residual;
    let class_bonus: f64 = if pr == 0 {
        -60.0 // perfect fit
    } else if pr % 50 == 0 {
        -18.0
    } else if pr % 25 == 0 {
        -12.0
    } else if pr % 20 == 0 {
        -10.0
    } else if pr % 10 == 0 {
        -6.0
    } else {
        8.0 // awkward remainder
    };
    score += class_bonus;

    // Lookahead: reward if next item fits exactly into the post residual.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 45.0;
        } else if next_item_size <= pr {
            let slack = (pr - next_item_size) as f64;
            score += slack * 0.35;
        } else {
            // next item cannot use this residual: penalize proportionally
            score += 5.0 + (next_item_size as f64) * 0.05;
        }
    }

    // Fractional tightness: prefer bins where item fills a large share.
    let fill = item_size as f64 / bin_residual as f64;
    score -= fill * 25.0;

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a new bin wastes the residual
    // landscape; penalize unless current bins are nearly full on average.
    if bin_residual == bin_capacity {
        let avg_waste = mean_residual;
        let pressure = (open_bins_count as f64).ln().max(1.0);
        if fitting_bins_count > 0 {
            score += 55.0 + avg_waste * 0.15; // existing bins can fit: deprioritize new bin
        } else {
            score -= 5.0 * pressure; // forced open
        }
    } else {
        // Favor bins below mean residual (underfilled) to balance? No:
        // prefer bins close to being full -> residual near item size.
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += dev * 0.08;
    }

    // Late-stream consolidation: prefer filling existing bins tighter.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 4.0 - progress * (post_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest plausible
    // item are pure waste. Penalize them heavily (non-linearly).
    let dead_threshold = 10u32; // smallest classic item size
    if post_residual > 0 && post_residual < dead_threshold {
        score += 40.0 * (dead_threshold - post_residual) as f64;
    }
    // Perfect fit is maximally rewarded.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Tightness coupling: reward proportion of bin consumed by this item.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 15.0 * fill_ratio;

    // Dead-space ratio penalty: small post_residual relative to capacity is good,
    // but mid-range residuals that can't host typical items are bad.
    let pr = post_residual as f64;
    if pr > 0.0 {
        let unusable = (pr < 25.0) as f64; // gap too small for most items
        score += unusable * 12.0 * (1.0 - pr / 25.0);
    }

    // Lookahead: if the next item fits exactly in the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 50.0;
        } else if next_item_size < post_residual {
            score -= 5.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item won't fit here; residual likely becomes dead space
            score += 6.0;
        }
    }

    // Open-bin pressure: discourage spreading across many bins when a tight
    // alternative exists; encourage using existing bins when many are open.
    score += 0.8 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Last-chance bin: if this is the only bin that fits, avoid opening a new one
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Mean residual context: prefer bins below mean residual (tighter bins),
    // pushing fragmented bins to be consumed first.
    score += 0.5 * (mean_residual - bin_residual as f64);

    // New-bin candidate handling: an empty bin is a fallback. Make it attractive
    // only when no open bin offers a good fit, i.e. when its raw score (residual
    // after placement = capacity - item_size) is competitive. Add a mild bias so
    // we don't open bins gratuitously, but relax the bias late in the stream when
    // closing out.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 18.0 - 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward exact/near-perfect fills.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Tightness bonus: smaller post_residual relative to capacity is better.
        score += (post_residual as f64 / bin_capacity as f64) * 10.0;
    }

    // 2-step lookahead: if the next item fits exactly or well into post_residual, reward heavily.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size < post_residual {
            let pair_waste = (post_residual - next_item_size) as f64;
            score -= 60.0 * (1.0 - pair_waste / bin_capacity as f64);
        } else {
            // Next item cannot fit here; mild penalty proportional to overflow gap.
            let gap = (next_item_size - post_residual) as f64;
            score += gap.min(50.0) * 0.5;
        }
    }

    // Compare post_residual against mean residual: creating below-average residual
    // (tight packing) is good; leaving above-average residual is wasteful.
    score += (post_residual as f64 - mean_residual) * 0.3;

    // Last-chance bonus: if this is the only bin that fits, prefer using it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 80.0;
    }

    // Penalize opening a new bin unless current bins fit poorly.
    if bin_residual == bin_capacity {
        // New bin candidate: baseline score = full residual minus a modest opening discount,
        // so it wins only when all open bins would leave large waste.
        score = bin_capacity as f64 - 40.0;
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 30.0; // fresh bin pairs well with next item too
        }
    }

    // Late in the stream, prefer closing bins tightly (fewer open bins).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * open_bins_count as f64 * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong best-fit bias: reward tight fits non-linearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 8.0 * tightness * tightness;

    // Penalize small but awkward residuals (dead space that few future items can use).
    if post_residual > 0 && post_residual < 10 {
        score += 6.0;
    }

    // Lookahead: if the next item fits exactly or well into post_residual, reward this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 10.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 5.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit here; slight penalty if this bin would be nearly emptied.
            score += 1.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when current
    // open bins have poor fits or the item is large relative to mean residual.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score = bin_capacity as f64 * 0.9;
        // Cheaper to open a new bin when many bins are open and fragmented.
        score -= 2.0 * (open_bins_count as f64).ln().max(0.0);
        // If item is large, a fresh bin guarantees a good fit.
        if item_size as f64 > mean_residual {
            score -= 6.0;
        }
        // Late in the stream, prefer consolidation into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 8.0 * progress;
        // If next item is large, a fresh bin helps it too.
        if next_item_size >= 60 {
            score -= 3.0;
        }
    }

    // Global fragmentation pressure: prefer bins with residual below mean residual
    // (consolidate fragmented space into fewer bins).
    if bin_residual < bin_capacity {
        let dev = mean_residual - bin_residual as f64;
        score -= 0.5 * dev;
    }

    // Mild penalty for spreading across many open bins.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Reward tight fits: squared coupling of post_residual with progress.
    let pr = post_residual as f64;
    score -= (bin_capacity as f64 - pr) * (bin_capacity as f64 - pr) / bin_capacity as f64 * (1.0 + progress);

    // Penalize dead space relative to mean residual of open bins.
    let dead = pr - mean_residual;
    score += 0.5 * dead * dead / bin_capacity as f64 * (1.0 - progress);

    // Lookahead coupling: favor leaving room for the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = pr - nxt;
        if gap >= 0.0 {
            score -= gap * (1.0 + nxt / bin_capacity as f64);
        } else {
            score += (-gap) * 2.0;
        }
    }

    // Last-chance bonus: this is the only bin that fits.
    if fitting_bins_count == 1 {
        score -= 25.0 + 15.0 * progress;
    } else if fitting_bins_count > 1 {
        // Mild penalty when many alternatives exist, favoring poor-fit bins less.
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // Encourage consolidation early, discourage bin proliferation late.
    score += open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Smooth non-linear interaction: post_residual vs progress polynomial.
    let t = progress * std::f64::consts::PI;
    score += pr * 0.1 * (t.sin() - 0.5);

    // New-bin candidate: penalize opening a new bin unless residuals are all tiny.
    if bin_residual == bin_capacity {
        score += 30.0 + 40.0 * progress - mean_residual * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "usable"
    // classes (multiples of common small sizes) are less penalized.
    let pr = post_residual;
    let usable = if pr == 0 {
        3.0
    } else if pr <= 10 {
        2.0
    } else if pr % 10 == 0 {
        1.5
    } else if pr % 5 == 0 {
        1.0
    } else {
        0.0
    };
    score -= usable * 4.0;

    // Dead-space penalty: residual too small for typical minimum item (<=9)
    // is nearly worthless unless it is exactly 0.
    if pr > 0 && pr < 10 {
        score += 25.0;
    }

    // Lookahead coupling: reward if next item fits exactly into post_residual
    // (perfect chaining), penalize if next item cannot fit.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 30.0;
        } else if next_item_size <= pr {
            let frac = next_item_size as f64 / pr.max(1) as f64;
            score -= 10.0 * frac;
        } else {
            score += 6.0;
        }
    }

    // Integer-division threshold on post_residual: leftovers in the middle
    // band (11..=50) are still flexible; large leftovers are fine too.
    let band = pr / 25; // 0..=4 harmonic band
    score -= band as f64 * 2.0;

    // Last-chance bin: strongly favor using the only fitting bin to avoid
    // opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: prefer opening a new bin only when existing bins fit
    // poorly (large post_residual waste) or stream is early.
    if bin_residual == bin_capacity {
        score = 45.0 + post_residual as f64;
        if fitting_bins_count == 0 {
            score -= 60.0; // no alternative: must open
        }
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * (1.0 - progress);
    }

    // Mild pressure against hoarding many open bins with large mean residual.
    if open_bins_count > 3 && mean_residual > 50.0 && bin_residual < bin_capacity {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small to hold
    // anything useful (below the smallest plausible item footprint)
    // are heavily penalized as wasted capacity.
    let dead_threshold: u32 = 10;
    if post_residual > 0 && post_residual < dead_threshold {
        score += 60.0 * (dead_threshold - post_residual) as f64;
    } else if post_residual == 0 {
        // Perfect fit is the ideal outcome: strong reward.
        score -= 100.0;
    } else {
        // Favor leaving residuals that could still accommodate a
        // meaningful future item: reward proportionally to usefulness.
        score -= 10.0 * (post_residual as f64 / bin_capacity as f64);
    }

    // Tight-fit reward: the closer the item fills the bin, the better.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 40.0 * fill_ratio * fill_ratio;

    // Open-bin pressure: with many open bins, prefer consolidating
    // into existing ones rather than spreading out.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 1.5 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Last-chance bin: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate handling: only attractive when the item fits
    // badly everywhere else or no open bins exist.
    if bin_residual == bin_capacity {
        let bad_fit = bin_residual < item_size;
        if fitting_bins_count == 0 || bad_fit {
            score -= 50.0;
        } else {
            // Discourage opening a new bin when decent fits exist.
            score += 30.0 + 2.0 * open_bins_count as f64;
        }
    }

    // Lookahead coupling: if the next item would exactly consume the
    // post-residual, this placement sets up a perfect follow-up.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 70.0;
        } else if post_residual >= next_item_size {
            score -= 5.0;
        } else if post_residual > 0 {
            score += 10.0;
        }
    }

    // Mean residual alignment: prefer bins whose residual is near the
    // mean (balanced packing) — mildly penalize outliers.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.3 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect-fit reward: leave zero dead space.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Tight-fit reward relative to capacity.
    let tightness = (item_size as f64) / (bin_capacity as f64);
    score -= tightness * 30.0;

    // Aggressive 2-step lookahead: bonus if next item exactly fills the post-residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual >= next_item_size {
            // Next item fits here too — mild reward proportional to how well it nests.
            let nest = 1.0 - ((post_residual - next_item_size) as f64) / (bin_capacity as f64);
            score -= nest * 60.0;
        } else {
            // Next item won't fit in the leftover — penalize unusable residue.
            score += ((next_item_size - post_residual) as f64) * 0.5;
        }
    }

    // Compare post_residual against the mean residual across open bins:
    // leaving a residual below average concentrates waste; above average is fine.
    let residual_gap = (post_residual as f64) - mean_residual;
    score += residual_gap * 0.25;

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // Penalize opening a new bin when the item is small relative to capacity
    // and there are plenty of open bins with room.
    if bin_residual == bin_capacity {
        score += 150.0;
        if item_size <= 50 && open_bins_count > 0 {
            score += 100.0;
        }
        // A new bin is attractive only if the item is huge (no bin likely fits later items).
        if item_size >= 80 {
            score -= 100.0;
        }
    }

    // Late in the stream, consolidate: mildly favor bins that keep residuals balanced.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * residual_gap * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor placements that nearly fill the bin.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 8.0 * tightness * tightness * (item_size as f64);

    // Penalize dead space: residuals that are too small to be useful later.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // near-unusable sliver
    } else if post_residual >= 10 && post_residual < 25 {
        score += 6.0;
    }

    // Lookahead coupling: if next item fits in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 10.0 + 0.5 * slack;
        } else {
            // Next item won't chain here; penalize mildly, more so if it would have fit pre-placement.
            if next_item_size <= bin_residual {
                score += 3.0;
            }
            // If next item could fit in a fresh bin after this placement, opening new bins is viable.
            if next_item_size > bin_residual && fitting_bins_count <= 1 {
                score += 8.0;
            }
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when open bins are crowded.
    if bin_residual == bin_capacity {
        // Base penalty so a fresh bin is chosen only when genuinely better.
        score += 15.0;
        // More open bins with high mean residual => keep using them.
        score += open_bins_count as f64 * 2.0;
        score += (mean_residual / bin_capacity as f64) * 20.0;
        // Early in stream, opening bins is fine; later, consolidate.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * (1.0 - progress);
        // If item is large relative to capacity, fresh bin is natural.
        if item_size as f64 > 0.6 * bin_capacity as f64 {
            score -= 10.0;
        }
    }

    // Fragmentation pressure: penalize leaving residual far from mean when mean is low.
    let resid_f = post_residual as f64;
    let dev = (resid_f - mean_residual).abs();
    score += 0.15 * dev * (open_bins_count as f64).ln().max(1.0);

    // Mild preference to fill bins that are already partially full.
    score -= 0.1 * (bin_capacity - bin_residual) as f64;

    // Time-horizon damping: early items tolerate looser fits.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 - 0.1 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Tight fits are valuable: reward small post_residual non-linearly
    let tightness = 1.0 - (pr / cap);
    score -= 12.0 * tightness * tightness * tightness;

    // Penalize large post_residual quadratically (dead space)
    score += 0.10 * pr * pr / cap;

    // Prefer using existing bins over opening new ones, more so later in stream
    if bin_residual == bin_capacity {
        score += 6.0 + 10.0 * progress;
    } else {
        score -= 3.0 + 4.0 * progress;
    }

    // Last chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    } else if fitting_bins_count > 1 {
        score += 1.5 * (fitting_bins_count as f64 - 1.0);
    }

    // Lookahead: if next item fits exactly in post_residual, reward strongly
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = (post_residual as i64 - next_item_size as i64) as f64;
        score -= 10.0 * (1.0 - gap / cap);
    } else if next_item_size > post_residual {
        score += 2.0;
    }

    // Coupling with mean residual: avoid leaving bin far below mean (fragmentation)
    score += 0.5 * (pr - mean_residual).abs() * (0.5 + progress);

    // Slight non-linear progress tilt: waste less late in the stream
    score *= 1.0 + 0.3 * progress * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
