    } else if post_residual <= 20 {
        -6.0
    } else if post_residual <= 35 {
        0.0
    } else {
        -2.0
    };
    score += class_bonus;

    // Penalize dead space: residuals that no plausible item (<=80, >=1) can pair with
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Coupling with lookahead: reward if next item fits into post_residual
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0 + (post_residual as f64 - next_item_size as f64).min(20.0);
        } else {
            // penalty proportional to how badly next item misses this residual
            let miss = (next_item_size as f64 - pr).min(cap);
            score += 4.0 + miss * 0.15;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: opening a new bin should only win when fits are poor.
    if bin_residual == bin_capacity {
        // baseline cost of a fresh bin
        score = cap - item_size as f64; // post_residual of new bin = cap - item
        // make new bin attractive only if existing bins are fragmented
        score += mean_residual * 0.25;
        if open_bins_count == 0 {
            score -= 100.0;
        }
        if next_item_size > 0 && next_item_size <= (bin_capacity - item_size) {
            score -= 8.0;
        }
        // discourage hoarding bins early in the stream
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += (1.0 - progress) * 10.0;
    } else {
        // mild preference for tighter existing bins as stream progresses
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= progress * 5.0;
        // prefer bins whose residual deviates favorably from the mean
        score -= (mean_residual - bin_residual as f64) * 0.1;
    }

    // Integer-division threshold coupling: bins whose residual/10 class matches
    // the item's class get a small harmony bonus
    if bin_residual / 10 == (bin_capacity - item_size) / 10 && bin_residual != bin_capacity {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
