        } else {
            // Next item cannot fit in the residual: dead space likely.
            let miss = (next_item_size - post_residual) as f64;
            score += miss * 0.8;
        }
    }

    // Penalize creating residual far below the mean residual (fragmentation).
    let pr = post_residual as f64;
    if pr < mean_residual * 0.5 && pr > 0.0 {
        score += (mean_residual - pr) * 0.3;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // Mild preference to keep bins balanced early in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (pr - mean_residual).abs() * 0.05 * (1.0 - progress);

    // New-bin candidate: only prefer opening a new bin when no open bin gives
    // a good fit (post_residual large) and there are many open bins already.
    if bin_residual == bin_capacity {
        let poor_fit = pr > 40.0;
        if poor_fit && open_bins_count > 3 {
            score -= 30.0;
        } else {
            score += 120.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item fills most of the residual.
    let residual = bin_residual as f64;
    let fill_ratio = item_size as f64 / residual;
    score -= 12.0 * fill_ratio * fill_ratio;

    // Penalize dead space: small post_residual relative to typical future item sizes is good,
    // but post_residual that is too small to ever be useful is wasted capacity.
    if post_residual > 0 {
        let pr = post_residual as f64;
        // dead space penalty grows if post_residual is below the smallest plausible item (10)
        if pr < 10.0 {
            score += 30.0 * (10.0 - pr);
        }
        // moderate dead space is mildly bad
        score += 0.15 * pr;
    } else {
        // perfect closure
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly in the post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size < post_residual {
            // next item fits, but leaves another gap: partial reward scaled by fit quality
            let nl = next_item_size as f64 / post_residual as f64;
            score -= 15.0 * nl;
        } else {
            // next item won't fit here; slightly penalize leaving a gap it can't use
            score += 3.0;
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 20.0 + 0.5 * item_size as f64;
    }

    // New-bin candidate handling: only prefer a fresh bin when all open bins fit poorly.
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        let mut new_bin_cost = 18.0;
        // early in the stream, opening bins is cheaper (build a pool for future packing)
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        new_bin_cost *= 0.5 + progress;
        // fewer open bins -> cheaper to open another
        new_bin_cost *= 1.0 / (1.0 + open_bins_count as f64 * 0.15);
        // if mean residual across open bins is small, new bin is justified
        new_bin_cost -= 0.2 * mean_residual;
        // if many bins fit, opening a new one is wasteful
        new_bin_cost += 2.0 * fitting_bins_count as f64;
        score += new_bin_cost;
    }

    // Mild penalty for spreading load too thin when many bins are open
    score += 0.05 * open_bins_count as f64;

    // Slight normalization by bin capacity for scale robustness
    score *= 100.0 / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr_norm = pr / cap;

    // Base: prefer tight fits (low post residual), with smooth polynomial shaping.
    let mut score = pr + 8.0 * pr_norm * pr_norm * cap;

    // Stream-progress coupling: as the stream advances, tighten tolerance for waste.
    let tightness = progress * progress;
    score += 20.0 * tightness * pr_norm;

    // Penalize dead space that cannot fit the lookahead item (smooth interaction).
    if next_item_size > 0 {
        let gap = (next_item_size as f64 - pr).max(0.0);
        let gap_norm = gap / cap;
        score += 15.0 * gap_norm * (1.0 + progress);
        // Reward residual that exactly accommodates the next item.
        let match_term = 1.0 - (gap / cap).min(1.0);
        score -= 10.0 * match_term * match_term;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0 + 10.0 * progress;
    }

    // New-bin candidate: mildly penalize early, reward late when open bins are wasteful.
    if bin_residual == bin_capacity {
        let waste = (mean_residual - cap * 0.5).max(0.0) / cap;
        score += 5.0 - 15.0 * progress - 10.0 * waste;
        score += 3.0 * (open_bins_count as f64).ln().max(0.0);
    }

    // Mean-residual coupling: discourage bins far from the fleet average (fragmentation).
    let dev = (pr - mean_residual) / cap;
    score += 6.0 * dev * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = 0.0;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: heavily penalize small unusable gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual >= 10 && post_residual < 25 {
        score += 8.0;
    }

    // Reward perfect or near-perfect fits.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Penalize opening new bins when fitting bins exist (open-bin pressure).
    if bin_residual == bin_capacity {
        score += 25.0 + 2.0 * open_bins_count as f64;
    } else if fitting_bins_count == 1 {
        // Last-chance bin: strongly favor using it to avoid a new bin.
        score -= 15.0;
    }

    // Mild pressure to fill already-open bins when many are open.
    score += open_bins_count as f64 * 0.15;

    // Lookahead: favor bins whose leftover could fit the next item.
    if next_item_size > 0 {
        if post_residual as u32 >= next_item_size {
            score -= 6.0;
        } else if post_residual > 0 {
            score += 4.0;
        }
    }

    // Progress-based tightening: later in stream, waste matters more.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += post_residual as f64 * (0.3 + 0.7 * progress);

    // Mean residual coupling: prefer bins close to mean residual (balanced fill).
    score += (bin_residual as f64 - mean_residual).abs() * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let capacity = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Reward tight fits: post_residual close to zero is ideal.
    let tightness = 1.0 - (post / capacity);
    score -= 30.0 * tightness * tightness;

    // Exact-fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Aggressive 2-step lookahead: reward when next item fits the post residual.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if next_item_size <= post_residual {
            let next_fit_tightness = 1.0 - ((post_residual as f64 - next) / capacity);
            score -= 25.0 * next_fit_tightness;
            // Perfect chain: next item exactly fills the bin.
            if next_item_size == post_residual {
                score -= 50.0;
            }
        } else {
            // Next item cannot fit here: penalize wasted lookahead opportunity,
            // scaled by how much dead space would be stranded.
            let dead = post / capacity;
            score += 15.0 * dead * dead;
        }
    }

    // Compare post residual against mean residual: prefer bins whose residual
    // after placement is below the mean (concentrating usage).
    let mean = mean_residual.max(1.0);
    let rel = post / mean;
    if rel < 1.0 {
        score -= 10.0 * (1.0 - rel);
    } else {
        score += 8.0 * (rel - 1.0).min(2.0);
    }

    // Last-chance bin: strongly favor using the only fitting bin to avoid a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: only open a new bin when all open bins would
    // strand large dead space (poor fits) or none fit.
    if bin_residual == bin_capacity {
        let base = capacity * 0.55;
        if fitting_bins_count == 0 {
            score -= 100.0; // must open
        } else if fitting_bins_count == 1 {
            score += 30.0; // last-chance bin exists, don't open
        } else {
            // Open a new bin only if the best existing fit would leave big dead space.
            let item = item_size as f64;
            let dead_if_placed = (capacity - item) / capacity;
            if dead_if_placed > 0.6 {
                score -= 20.0;
            } else {
                score += base;
            }
        }
    }

    // Mild late-stream pressure: consolidate as stream ends.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (1.0 - post / capacity);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post_residual relative to capacity)
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize dead space that is too small for likely future items (below typical min size)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Lookahead: reward bins whose post_residual can host the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else if post_residual > 0 {
            score += 8.0 * (1.0 - (next_item_size as f64 - post_residual as f64) / next_item_size as f64);
        }
        // Prefer bins where item + next item exactly fill the bin
        if post_residual == next_item_size {
            score -= 15.0;
        }
    } else {
        // Last item: any fit is fine, prefer tightest
        score -= 10.0;
    }

    // Time horizon: early in the stream, be more selective (favor new bins when fit is poor);
    // late in the stream, pack aggressively into existing bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 20.0 * progress;

    // Crowded bin pool: encourage consolidation into existing bins
    score -= 3.0 * (open_bins_count as f64).ln().max(0.0);

    // Compare against mean residual: bins with residual far above mean are good consolidation targets
    let residual_gap = bin_residual as f64 - mean_residual;
    score -= 0.15 * residual_gap;

    // New-bin candidate handling: neutral baseline, penalized unless current best fit is poor
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin
        score = bin_capacity as f64 * 0.9;
        // Cheaper to open a new bin early in the stream
        score -= 30.0 * (1.0 - progress);
        // Cheaper if few bins are open
        score -= 5.0 * (open_bins_count as f64).ln().max(0.0);
        // Expensive if many bins already fit the item
        score += 10.0 * fitting_bins_count as f64;
        // Expensive if lookahead item would be stranded
        if next_item_size > 0 && next_item_size > bin_capacity - item_size {
            score += 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post residual, polynomially coupled with stream progress
    let mut score = pr;

    // Smooth non-linear coupling: quadratic and cubic terms in normalized residual,
    // modulated by progress (later in stream -> penalize large residuals more,
    // since fewer chances remain to fill them)
    let coupling = 0.5 + 1.5 * progress;
    score += coupling * 40.0 * norm_pr * norm_pr;
    score += (1.0 - progress) * 20.0 * norm_pr * norm_pr * norm_pr;

    // Reward tight fits: smooth sigmoid-like reward on small residuals
    let tightness = (-norm_pr * 6.0).exp();
    score -= 25.0 * tightness * (0.4 + 0.6 * progress);

    // Lookahead: reward residual that can fit the next item (smooth overlap measure)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fit = (pr - nxt).max(0.0);
        let overlap = 1.0 - (fit / cap).min(1.0);
        score -= 30.0 * overlap * overlap * (1.0 - progress);
    }

    // Last-chance bin: strongly favor using it (avoid opening a new bin)
    if fitting_bins_count == 1 {
        score -= 35.0 * (0.5 + 0.5 * progress);
    }

    // Deviation from mean residual: prefer bins below mean residual (tighter packing)
    let dev = (pr as f64 - mean_residual) / cap;
    score += 15.0 * dev * dev.abs();

    // Penalize opening a new bin when open bins can fit, more so late in the stream
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 20.0 + 40.0 * progress;
    }

    // Mild diversity term: many open bins -> prefer filling existing ones
    score += (open_bins_count as f64).ln().max(0.0) * 2.0 * norm_pr;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // ---- Harmonic class of the post-residual (modulo capacity fractions) ----
    // Class residuals into bands of C/10; small post residuals are "good" (dead space low).
    let class = (post_residual * 10) / bin_capacity; // 0..10 harmonic class
    score += match class {
        0 => -40.0,                       // perfect-ish fit
        1 => -25.0,
        2 => -12.0,
        3 => 0.0,
        4 => 8.0,
        _ => 12.0,                        // large leftover: penalize
    };

    // ---- Pairing bonus: does next_item_size fit the post residual? ----
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;                // exact complement
        } else if next_item_size <= post_residual {
            let gap = post_residual - next_item_size;
            let gap_class = (gap * 10) / bin_capacity;
            score -= 30.0 - gap_class as f64 * 3.0; // tight pair bonus
        } else {
            // next item cannot use the leftover: penalize proportionally
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // ---- Integer-division threshold: residual in [1..=10] is near-dead ----
    if post_residual >= 1 && post_residual <= 10 {
        score += 25.0;
    }

    // ---- Last-chance bin (only fitting bin) ----
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0; // prefer using it over opening a new bin
    }

    // ---- New-bin candidate handling ----
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when open bins fit poorly.
        // Reward when mean residual is small (open bins are full-ish),
        // penalize when there is plenty of slack in open bins.
        score = 45.0 - mean_residual * 0.6 - (open_bins_count as f64) * 0.5;
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        if next_item_size > 0 && next_item_size <= bin_capacity {
            let frac = (bin_capacity - next_item_size) as f64;
            score += frac * 0.05; // slight penalty if next item pairs with an open bin's slack
        }
        return score;
    }

    // ---- Tightness coupling: reward filling a bin whose residual was small ----
    score -= (bin_capacity - bin_residual) as f64 * 0.1;

    // ---- Stream progression: late in stream, consolidate aggressively ----
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (post_residual as f64) * 0.3;

    // ---- Mean residual context: if open bins are slack overall, avoid wasting ----
    score += (mean_residual - post_residual as f64).max(0.0) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: heavily penalize small unusable gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // tiny sliver is almost always dead space
    }
    // Penalize gaps that cannot fit the smallest plausible next item
    if post_residual > 0 && (next_item_size > 0 && post_residual < next_item_size) {
        score += 25.0;
    }

    // Reward tight fits strongly
    score -= (item_size as f64 / bin_capacity as f64) * 30.0;

    // Exact fill is ideal
    if post_residual == 0 {
        score -= 50.0;
    }

    // Dead-space-shaped residual: gap in (0, 10) or awkward mid-range
    let gap = post_residual as f64;
    if gap > 0.0 && gap < 15.0 {
        score += (15.0 - gap) * 3.0; // smaller unusable gap => bigger penalty
    }

    // Open-bin pressure: when many bins are open, prefer consolidation
    // (avoid opening new bins); penalize the empty new-bin candidate.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New bin candidate: only attractive if nothing fits well elsewhere
        let pressure = open_bins_count as f64 * 8.0 * (0.5 + progress);
        score += pressure;
        if fitting_bins_count > 0 {
            score += 40.0; // opening new bin while others fit is wasteful
        }
    } else {
        // Reward using existing bins, more so when many are open
        score -= open_bins_count as f64 * 1.5;
    }

    // Last-chance bin: strongly favor using it to avoid a near-empty extra bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Prefer bins whose residual is below mean (tighter bins first),
    // keeping looser bins available for larger future items.
    score += (bin_residual as f64 - mean_residual) * 0.4;

    // Lookahead: if the next item fits exactly in the post residual, reward
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 35.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact/near-exact match with next item
    if next_item_size > 0 && post_residual >= next_item_size {
        let match_quality = (post_residual - next_item_size) as f64;
        score -= 30.0 * (1.0 - match_quality / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Penalize leaving residual too small for the next item (dead space)
        score += 0.5 * (next_item_size - post_residual) as f64;
    }

    // Relative to mean residual: prefer bins whose post-residual deviates favorably
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Penalize opening a new bin when existing bins fit reasonably
    if bin_residual == bin_capacity {
        score += 15.0;
        // New bin more attractive only if existing residuals are large/wasteful
        if mean_residual > 50.0 {
            score -= 20.0;
        }
    }

    // Late in stream: tighten packing, avoid waste
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * post_residual as f64 * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: quadratic bonus for small post_residual.
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 40.0 * tight * tight;

    // Penalize dead space that is too small for typical future items
    // (residual in (0, 10) is nearly unusable waste).
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Lookahead: reward residuals that can host the next item exactly or well.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 80.0; // perfect chain placement
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 20.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // post_residual cannot host next item: mild penalty scaled by closeness of miss
            score += 8.0 * (1.0 - post_residual as f64 / next_item_size as f64).max(0.0);
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin to avoid a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate handling: opening a new bin should only win when
    // no open bin offers a decent fit. Give the empty bin a moderate default
    // score that tight fits beat, but poor fits lose to.
    if bin_residual == bin_capacity {
        score = 55.0
            - 0.05 * (open_bins_count as f64)
            + 10.0 * (step_index as f64 / total_items.max(1) as f64);
        // Late in stream, slightly prefer consolidating into existing bins.
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score += 5.0;
        }
    }

    // Global state coupling: when mean residual across open bins is high,
    // prefer bins below the mean (balance usage); when low, prefer tight fits more.
    if bin_residual < bin_capacity {
        let dev = mean_residual - bin_residual as f64;
        score += 0.15 * dev;
        // More open bins -> more pressure to fill existing ones.
        score -= 0.5 * (open_bins_count as f64).ln().max(0.0) * tight;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;
    let is_new_bin = (bin_residual == bin_capacity) as f64;

    // Base: quadratic waste coupling with progress
    let mut score = pr * (1.0 + 1.5 * pr_norm * pr_norm);

    // Smooth non-linear interaction: waste matters more as stream progresses
    score += pr_norm * progress * 30.0 * (progress * (1.0 - progress) * 4.0).sqrt();

    // Reward tight fits via smooth sigmoid-like term
    let tight = 1.0 - pr_norm;
    score -= 20.0 * tight * tight * tight;

    // Penalize opening a new bin when existing bins fit (soft, smooth)
    score += is_new_bin * (25.0 + 15.0 * progress) * (1.0 / (1.0 + fitting_bins_count as f64));

    // Last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 && is_new_bin == 0.0 {
        score -= 40.0;
    }

    // Lookahead coupling: prefer leaving residuals that fit next item
    if next_item_size > 0 {
        let fits_next = (next_item_size as f64 <= pr) as f64;
        score -= 12.0 * fits_next * (1.0 - (pr / cap - next_item_size as f64 / cap).abs());
        // Penalize residuals that are awkwardly small relative to next item
        let gap = (next_item_size as f64 - pr).max(0.0);
        score += 0.3 * gap * gap / cap;
    }

    // Mild pressure toward consolidating into fewer bins
    score += 0.05 * open_bins_count as f64 * pr_norm;

    // Deviation from mean residual: prefer balanced fills
    score += 0.2 * (pr - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: waste buckets via integer division.
    // Small post_residual is great; large post_residual in a partially-filled bin is waste.
    let c = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / c; // fraction of capacity wasted if bin closes here

    // Modulo classes: post_residual divisible by small harmonics is more "usable"
    // for common item sizes; odd/prime-ish leftovers are dead space.
    let p = post_residual;
    let harmonic_bonus = if p == 0 {
        6.0
    } else if p % 10 == 0 {
        3.0
    } else if p % 5 == 0 {
        1.5
    } else {
        0.0
    };
    score -= harmonic_bonus;

    // Dead-space penalty: post_residual too small for the smallest plausible item (1),
    // but too small for next item specifically is the real waste.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // This bin can also host the lookahead item: strong reward for chaining.
            let chain_fit = (post_residual - next_item_size) as f64;
            score -= 4.0 + 0.05 * chain_fit;
        } else {
            // Lookahead cannot follow: penalize proportionally to wasted fraction.
            score += 2.0 * frac;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate: opening a fresh bin is only attractive when the item is
    // large relative to capacity (poor fit candidates elsewhere) or no bin fits.
    if bin_residual == bin_capacity {
        let big_item = item_size as f64 / c;
        score += 10.0 - 6.0 * big_item; // base cost of a new bin, discounted for big items
        if fitting_bins_count > 0 {
            score += 1.0; // extra deterrent if some open bin already fits
        }
    }

    // Tight-fit reward: nearly exact packing (post_residual tiny) gets extra reward.
    if post_residual <= 5 && post_residual > 0 {
        score -= 3.0;
    }

    // Prefer filling bins with low mean residual (compact the open set) as stream matures.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 0.02 * progress * (mean_residual - pr).abs();

    // Integer-division threshold: if post_residual falls in the "unfillable sliver"
    // band (1..=9 under unknown distribution), treat as full-bin success.
    if post_residual >= 1 && post_residual <= 9 {
        score -= 2.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = 0.0;

    // Base: prefer tight fits (small post_residual), but punish "unusable" dead space.
    let pr = post_residual as f64;
    if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 60.0;
    } else if post_residual <= 10 {
        // Unusable dead space for future items (min item size 1..100, but small gaps rarely reusable):
        // penalize proportionally to how wasted the space is relative to bin capacity.
        score += 45.0 * (1.0 - pr / 10.0) + 20.0;
    } else {
        // Usable residual: mild preference for smaller leftovers.
        score += 0.35 * pr;
    }

    // Reward filling a bin deeply (high utilization of this placement).
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 25.0 * fill_ratio;

    // Open-bin pressure: discourage spreading across many bins slightly.
    score += 1.5 * open_bins_count as f64;

    // Last-chance bin: if this is the only fitting bin, strongly favor using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling (bin_residual == bin_capacity).
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive if no decent fit exists:
        // penalize it unless the item would leave a very awkward residual everywhere.
        score += 40.0;
        // If the new bin would be left nearly full anyway (huge item), soften penalty.
        if item_size as f64 / bin_capacity as f64 > 0.8 {
            score -= 30.0;
        }
        // If many bins already fit the item, opening a new one is clearly worse.
        score += 6.0 * fitting_bins_count as f64;
    }

    // Lookahead coupling: if the next item fits exactly into the post_residual,
    // reward preserving that residual.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if gap <= 5.0 {
            score -= 18.0 * (1.0 - gap / 5.0);
        } else if post_residual > 0 && (next_item_size as f64) > pr {
            // Next item won't fit here: slightly prefer bins where leftover stays flexible.
            score += 3.0;
        }
    }

    // Mean residual context: if this bin's residual is far below mean, it's already
    // crowded — placing here consolidates; if far above mean, placing here wastes it.
    let dev = bin_residual as f64 - mean_residual;
    score += 0.15 * dev;

    // Stream progression: late in the stream, be more conservative about new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 10.0 * progress;
    } else {
        score -= 5.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match between post_residual
    // and the next item size (bin becomes perfectly full after next item).
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect match: strong reward proportional to item size
        if gap == 0.0 {
            score -= 45.0 + item_size as f64 * 0.35;
        } else {
            // Decay reward as gap grows; near-matches still favored
            score -= (30.0 * (-gap / 25.0).exp()) - gap * 0.25;
        }

        // If next item fits in post_residual at all, mild bonus; else penalize
        if post_residual < next_item_size {
            score += 8.0; // dead space relative to lookahead
        }
    }

    // Perfect closure now (item exactly fills the bin)
    if post_residual == 0 {
        score -= 40.0;
    }

    // Penalize creating tiny unusable residuals relative to capacity
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Compare against mean residual: prefer leaving residuals near the mean
    // to keep the fleet homogeneous, penalize outliers.
    score += (post_residual as f64 - mean_residual).abs() * 0.30;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive when existing bins would
    // leave large dead space or when few bins are open early in the stream.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let dead_space_penalty = (bin_capacity - item_size) as f64 * 0.5;
        score += 55.0 - progress * 20.0 - dead_space_penalty * 0.4;
        // Early stream: opening fresh bins is cheap and useful
        if open_bins_count < 3 {
            score -= 30.0;
        }
        // If next item is large, a fresh bin is a good host for it later
        if next_item_size >= 60 {
            score -= 15.0;
        }
    }

    // Mild penalty for very full open fleet (encourage consolidation)
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post_residual relative to capacity)
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize dead space that can never be filled by typical items (residual < 10 unusable)
    if post_residual < 10 {
        score += 25.0;
    } else if post_residual < 20 {
        score += 10.0;
    }

    // Exact fill is ideal
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead: if next item fits in post_residual, big reward
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0 + 0.3 * (next_item_size as f64);
    } else if next_item_size > 0 && post_residual > 0 {
        // wasted space if next item can't use remainder
        score += 0.15 * (post_residual as f64);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin when decent alternatives exist,
    // unless current bin fit is terrible.
    if bin_residual == bin_capacity {
        let fit_quality = (item_size as f64) / (bin_capacity as f64);
        score += 15.0 + 20.0 * (1.0 - fit_quality);
        if fitting_bins_count > 2 {
            score += 25.0;
        }
        // early in stream, opening bins is fine to build diversity
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 10.0 * (1.0 - progress);
    }

    // Prefer fuller bins relative to mean residual of open bins
    if open_bins_count > 0 {
        let dev = (bin_residual as f64) - mean_residual;
        score -= 0.1 * dev;
    }

    // Mild penalty for spreading across many bins late in stream
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.02 * open_bins_count as f64 * progress;

    // Prefer bins whose residual is close to item size (minimal waste)
    let waste_ratio = (post_residual as f64) / (bin_capacity as f64);
    score += 8.0 * waste_ratio * waste_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early stream: prefer tight fits modestly. Late stream: strongly punish large residuals.
    let poly = pr_norm * pr_norm * (1.0 + progress) + progress * progress * pr_norm;
    score += 12.0 * poly;

    // Reward filling bins whose residual matches the upcoming item (k=2 lookahead).
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        let match_term = 1.0 - ((next_item_size as f64 - pr).abs() / cap);
        score -= 8.0 * match_term * (0.5 + progress);
    } else if next_item_size > 0 {
        // Penalize leaving residual unusable by the next item.
        score += 3.0 * (1.0 - pr_norm) * (0.5 + progress);
    }

    // Last-chance bin: strong reward to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0 * (1.0 - progress);
        score -= 5.0;
    }

    // Slight penalty when many bins are open and residual is large (fragmentation).
    score += 0.05 * (open_bins_count as f64) * pr_norm * pr_norm;

    // Prefer bins whose residual is below the mean residual (tighter bins first).
    score -= 2.0 * (mean_residual - pr).max(0.0) / cap;

    // New-bin candidate: make empty bin mildly unattractive unless residuals are all bad.
    if bin_residual == bin_capacity {
        score += 10.0 - 20.0 * progress * (1.0 - (mean_residual / cap).min(1.0));
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
