pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any item (1..10) are wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // unusable sliver penalty
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 40.0;
    } else {
        // Reward tight fits (small usable residual).
        let tightness = post_residual as f64 / bin_capacity as f64;
        score += tightness * 25.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Prefer bins whose residual is close to the item (best-fit core).
    let gap = (bin_residual as f64 - item_size as f64).abs();
    score += gap * 0.8;

    // Open bins pressure: when many bins are open, avoid spreading; when few, tolerate.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (open_bins_count as f64) * (0.4 + 0.6 * progress) * 0.5;

    // Lookahead: if the next item fits exactly in the post residual, reward heavily.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 55.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 8.0;
    } else if next_item_size > post_residual && post_residual > 0 && post_residual < 10 {
        score += 20.0; // dead space confirmed unusable for lookahead
    }

    // New-bin candidate: keep it neutral-ish; only attractive when current bin would
    // leave a big gap or many bins are open with high mean residual.
    if bin_residual == bin_capacity {
        score = 30.0 + mean_residual * 0.15 + (open_bins_count as f64) * 0.3;
        if post_residual >= item_size.saturating_sub(1).max(10) {
            // opening fresh is fine
        }
        if fitting_bins_count == 1 {
            score += 45.0; // don't abandon the last chance bin
        }
        if next_item_size > 0 && next_item_size >= 90 {
            score -= 20.0; // big item coming, fresh bin useful
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for exact or near-exact fits (dead-space minimization).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 10 {
        score -= 80.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 60.0 - slack.min(60.0); // exact next-fit match gets full bonus
        if slack == 0.0 {
            score -= 150.0; // perfect chain placement
        }
    } else if next_item_size > 0 && post_residual > 0 {
        // Penalize creating residual that the next item cannot use.
        score += 25.0;
    }

    // Compare post_residual against mean residual: prefer leaving typical slack,
    // penalize creating outliers (too small = dead space, too large = wasteful).
    let pr = post_residual as f64;
    if pr < mean_residual * 0.4 {
        score += (mean_residual * 0.4 - pr) * 1.5;
    } else if pr > mean_residual * 1.8 && post_residual > 20 {
        score -= (pr - mean_residual * 1.8) * 0.3;
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 {
        score -= 120.0;
    }

    // Penalize opening new bins when good open bins exist (new-bin candidate has
    // bin_residual == bin_capacity); make empty-bin score less attractive unless
    // no decent fit exists.
    if bin_residual == bin_capacity {
        score += 70.0;
        if fitting_bins_count == 0 {
            score -= 500.0;
        }
        // Late in the stream, opening fresh bins is cheaper (less residual waste risk).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= progress * 20.0;
    }

    // Mild pressure to consolidate: prefer bins with less residual overall.
    score += (bin_residual as f64 - post_residual as f64) * 0.0;

    // Small penalty for very large leftover chunks that nothing (10..80) may fill well.
    if post_residual > 80 {
        score -= 10.0;
    } else if post_residual > 50 && post_residual < 60 {
        score += 8.0; // awkward gap sizes
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let mut score = post;

    // Reward tight fits: smaller post_residual relative to capacity gets a bonus.
    let tightness = post / cap; // 0 = perfect fit, 1 = empty
    score -= (1.0 - tightness) * (1.0 - tightness) * 40.0;

    // Penalize creating dead space that cannot fit the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post > 0.0 && post < nxt {
            score += (nxt - post) * 1.5; // wasted relative to lookahead
        } else if post >= nxt {
            score -= 6.0; // bin stays usable for the lookahead item
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Compare against mean residual: choosing a bin far below mean residual
    // concentrates filling; choosing above mean spreads it out.
    score += (bin_residual as f64 - mean_residual) * 0.3;

    // Late in the stream, consolidate: penalize opening new bins more strongly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 18.0 + 30.0 * progress + 2.0 * open_bins_count as f64;
        // Opening a new bin is acceptable only if no bin fits well.
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
    }

    // Slight preference for bins whose residual is an exact fit class (post == 0).
    if post_residual == 0 {
        score -= 100.0;
    }

    // Mild fragmentation penalty: residual in awkward low band (1..10) is dead space.
    if post_residual >= 1 && post_residual < 10 {
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post-residual in [0,1]

    // Base: prefer tight fits (small post_residual), non-linearly.
    let mut score = 100.0 * x * x;

    // Smooth polynomial coupling with stream progress:
    // late in the stream, penalize waste more aggressively (cubic in progress).
    let late = progress * progress * progress;
    score += 80.0 * late * x * (1.0 - x);

    // Reward exact/near-perfect fits with a smooth dip.
    score -= 30.0 * (-((x * 4.0 - 0.05) * (x * 4.0 - 0.05))).exp();

    // Penalize leaving a residual that is too small to be useful for any
    // plausible next item (dead space), scaled by stream progress.
    let dead = (1.0 - x).powi(3);
    score += 15.0 * dead;

    // Lookahead: reward if the next item fits the post-residual, penalize otherwise.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr as f64 {
            score -= 20.0 * (1.0 - nxt / cap);
        } else {
            score += 10.0 * ((nxt - pr) / cap);
        }
    }

    // Last-chance bin: strong reward to use it rather than open a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive when current bins are poor fits.
    if bin_residual == bin_capacity {
        let fit_pressure = if fitting_bins_count > 0 { 1.0 / (1.0 + fitting_bins_count as f64) } else { 1.0 };
        // Opening a new bin costs ~1 bin; make it slightly worse than a decent fit
        // but better than a terrible fit, modulated by mean residual spread.
        score = 60.0 + 40.0 * fit_pressure + 10.0 * (mean_residual / cap);
        if next_item_size > 0 {
            score -= 5.0 * (1.0 - next_item_size as f64 / cap);
        }
    }

    // Mild penalty for bin proliferation late in the stream.
    score += 0.5 * open_bins_count as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: perfect fit strongly rewarded.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Classify post_residual into capacity-fraction classes (1/8 granularity).
        let frac = post_residual as f64 / bin_capacity as f64;
        let class = (frac * 8.0).floor() as i64;
        // Small class (dead space < capacity/8) is heavily penalized.
        score += match class {
            0 => 60.0,
            1 => 15.0,
            2 => 5.0,
            _ => 0.0,
        };
        // Reward post_residual that can host the next item (harmonic pairing).
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 12.0 + (post_residual - next_item_size) as f64 * 0.05;
        } else if next_item_size > 0 {
            // Dead space relative to lookahead: penalize proportionally.
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 0.0 } else { 25.0 };
        let tight_fit_elsewhere = fitting_bins_count > 0 && post_residual == 0; // unused here, keeps signature
        let _ = tight_fit_elsewhere;
        // Penalize opening a new bin; scale with progress and open bins.
        score += 55.0 + pressure + open_bins_count as f64 * 1.5
                 + (step_index as f64 / total_items.max(1) as f64) * 10.0;
        // If item is large, opening fresh is less bad.
        score -= item_size as f64 * 0.2;
    }

    // Mild best-fit bias toward bins tighter than average.
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny leftovers are unusable by future items (>=1),
    // so penalize small non-zero post_residual super-linearly.
    if post_residual > 0 {
        if post_residual <= 10 {
            score += (11 - post_residual as f64) * 18.0; // dead zone: 10..=180 extra
        } else if post_residual <= 25 {
            score += (26 - post_residual as f64) * 4.0;  // semi-dead zone
        } else {
            score -= 6.0; // generous residual is reusable
        }
    } else {
        // Perfect fit: strong reward.
        score -= 60.0;
    }

    // Reward tight fits (high fill ratio of the bin).
    let fill_ratio = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= fill_ratio * 25.0;

    // Open-bin pressure: with many open bins, prefer consolidating into existing bins
    // rather than opening new ones.
    score += open_bins_count as f64 * 3.0;

    // Last-chance bin: if this is the ONLY bin that fits, strongly avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: only attractive when no open bin fits well
    // (i.e., poor fits elsewhere) or stream is early and consolidation is cheap.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let poor_fits = fitting_bins_count == 0
            || (mean_residual - item_size as f64) < 5.0;
        if poor_fits {
            score -= 20.0;
        } else {
            score += 45.0 + open_bins_count as f64 * 2.0;
        }
    }

    // Lookahead: if the next item fits exactly in the post_residual, reward this placement.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 30.0;
    } else if next_item_size > 0 && next_item_size > post_residual && post_residual > 0 {
        // Next item cannot use this leftover: mild penalty for stranding space.
        score += 8.0;
    }

    // Late in the stream, closing bins tightly matters more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect or near-perfect fits (dead space suppression).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 15 {
        score -= 60.0;
    }

    // Two-step lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        let chain_waste = post_residual - next_item_size;
        score -= 80.0 + 0.5 * next_item_size as f64 - 0.3 * chain_waste as f64;
    } else if next_item_size > 0 {
        // Penalize leaving a residual that nearly-but-not-quite fits next item.
        let gap = next_item_size as f64 - post_residual as f64;
        if gap < 10.0 {
            score += 25.0 + gap;
        }
    }

    // Relative-to-mean term: prefer bins that are tighter (below mean residual)
    // since they are closer to being closed out.
    score += 0.35 * (mean_residual - bin_residual as f64);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // Mild penalty for spreading across many open bins; encourage consolidation
    // early, relax slightly as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 2.0 * open_bins_count as f64 * (1.0 - 0.5 * progress);

    // New-bin candidate: only attractive when item is large relative to capacity
    // or no good fit exists; make empty bin moderately costly by default.
    if bin_residual == bin_capacity {
        score += 40.0 + 0.5 * item_size as f64;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 30.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: exact or near-exact fits are strongly favored.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless there are
    // no (or very few) alternatives, or the item is huge relative to capacity.
    if bin_residual == bin_capacity {
        let scarcity = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        let big_item = (item_size as f64 / bin_capacity as f64).powi(3);
        let late_stream = (step_index as f64 / total_items.max(1) as f64) * 10.0;
        // Base penalty keeps new bins closed when open bins can fit the item.
        score += 35.0 - scarcity * 50.0 - big_item * 20.0 - late_stream;
    }

    // Lookahead coupling: reward bins whose post-residual can host the next item
    // (keeps chains tight), penalize bins leaving awkward small gaps that cannot.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else if post_residual > 0 && post_residual < 10 {
            // small dead space that likely cannot fit future items
            score += 6.0;
        }
    }

    // Global state: many open bins with high mean residual -> prefer consolidating
    // into existing space rather than fragmenting.
    if bin_residual != bin_capacity {
        let gap_from_mean = mean_residual - bin_residual as f64;
        score += 0.15 * gap_from_mean;
        score += 0.5 * open_bins_count as f64;
    }

    // Mild preference for bins with less residual overall (best-fit flavor),
    // scaled down for tiny items where placement flexibility matters less.
    let flexibility = 1.0 - (item_size as f64 / bin_capacity as f64);
    score += flexibility * (post_residual as f64 / bin_capacity as f64) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits, with non-linear polynomial shaping of post_residual.
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // Smooth coupling with stream progress: later in the stream, penalize large residuals harder.
    score += 25.0 * progress * norm_pr * norm_pr;

    // Reward bins whose residual is "used up" well relative to mean residual.
    let mean_norm = mean_residual / cap;
    score -= 10.0 * (mean_norm - norm_pr) * (1.0 - progress);

    // Last-chance bin: strong bonus to use it rather than open a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0 * (1.0 - 0.5 * progress);
    }

    // Crowding: more open bins -> slightly prefer filling existing ones.
    score += (open_bins_count as f64).ln() * norm_pr * 3.0;

    // Lookahead: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let slack = (pr - nxt) as f64;
            score -= 12.0 * (1.0 - slack / cap) * (1.0 - progress);
        } else {
            score += 6.0 * (nxt - pr) / cap;
        }
    }

    // New-bin candidate: keep neutral-ish but slightly discouraged unless residuals are large.
    if bin_residual == bin_capacity {
        score += 8.0 - 10.0 * mean_norm;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic classes of post_residual: residues modulo 10 define "dead zones".
    // Small residues (1..10) are nearly dead space; penalize them strongly,
    // except exact zero (perfect fit) which gets a large reward.
    let r = post_residual % 10;
    if post_residual == 0 {
        score -= 100.0; // perfect fit
    } else {
        // penalty grows as residue class gets "worse" (smaller nonzero residue)
        score += (10 - r) as f64 * 1.5;
        // tiny unusable slivers
        if post_residual < 10 {
            score += 25.0;
        }
    }

    // Integer-division thresholds: post_residual / 25 quarters.
    // Favor bins whose leftover can plausibly host future items (>= 10).
    let quarters = post_residual / 25;
    score -= quarters as f64 * 4.0;

    // Tight fit reward: fraction of bin consumed by this item.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= fill * 20.0;

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when the item is large
    // and no open bin offers a decent fit.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // New bins start with full residual; make them unattractive by default.
        score += 15.0;
        if item_size >= 60 && fitting_bins_count <= 1 {
            score -= 40.0; // large item with no good home -> open new bin
        }
        if open_bins_count == 0 {
            score -= 100.0; // must open first bin
        }
    }

    // Lookahead (k=2): reward leftover space that exactly or nearly fits next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 50.0;
        } else if post_residual >= next_item_size {
            score -= (next_item_size as f64 / 10.0) * 3.0;
        } else {
            // leftover too small for next item: penalize proportionally
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Stream progression: early on, be more willing to open bins (spread items);
    // late, consolidate aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if is_new_bin {
        score -= progress * 20.0;
    } else {
        score += progress * 5.0;
    }

    // Many open bins with high mean residual: favor consolidating into existing bins.
    if mean_residual > item_size as f64 && !is_new_bin {
        score -= 5.0;
    }
    score += open_bins_count as f64 * 0.5 * (if is_new_bin { 1.0 } else { -1.0 });

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize unusable small gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    // Medium dead space (hard to fill later) gets a graded penalty.
    if post_residual >= 10 && post_residual < 25 {
        score += 12.0;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; prefer filling existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (1.0 + progress);
    score += pressure * 0.6;

    // Prefer bins whose residual is close to the item (tight fit).
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score += tightness * 0.3;

    // Lookahead: if next item fits in the post residual, reward this placement.
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        score -= 15.0;
    }
    // If next item would NOT fit but post_residual is still sizable, mild penalty.
    if next_item_size > post_residual && post_residual > 0 {
        score += 5.0;
    }

    // Prefer bins below mean residual (filling emptier bins keeps tight bins for small items).
    score += (mean_residual - bin_residual as f64) * 0.2;

    // New-bin candidate: mild penalty so it only wins when fits are poor.
    if bin_residual == bin_capacity {
        score += 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: next item exactly fills this bin afterwards.
    if next_item_size > 0 {
        if post_residual as u32 == next_item_size {
            score -= 1000.0;
        } else if post_residual > next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 60.0 / (1.0 + slack);
        } else {
            // next item won't fit here; penalize leftover
            score += 20.0;
        }
    } else {
        // Last item: prefer minimal leftover
        score -= 50.0;
    }

    // Tight fit reward relative to capacity
    let tightness = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= 30.0 * tightness;

    // Reward bins whose residual is below mean (packing denser than average)
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: penalize opening a new bin unless nothing fits well
    if bin_residual == bin_capacity {
        score += 150.0;
        // If the item is large, opening a fresh bin is more attractive
        if item_size > bin_capacity / 2 {
            score -= 120.0;
        }
        // If next item also fits in a fresh bin alongside, slight bonus
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 30.0;
        }
    }

    // Penalize creating tiny unusable dead space (1..=5)
    if post_residual > 0 && post_residual <= 5 {
        score += 40.0;
    }

    // Mild pressure to consolidate into fewer bins early in the stream
    score += 0.1 * open_bins_count as f64 * (step_index as f64 / total_items.max(1) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (waste minimization), with non-linear coupling.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 18.0 * fit_ratio * fit_ratio;

    // Penalize large dead space relative to typical item sizes: residual that
    // cannot hold any plausible future item is waste.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let dead = post_residual as f64;
    score += 0.35 * (dead / 100.0).powf(2.2) * (1.0 + 0.8 * progress);

    // Lookahead: if the next item fits exactly into the post-residual, reward heavily.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            // Reward leaving room the next item can use, scaled by how snugly.
            let next_fit = next_item_size as f64 / post_residual.max(1) as f64;
            score -= 10.0 * next_fit;
        } else {
            // Post-residual too small for next item: penalize proportional dead gap.
            score += 0.15 * (next_item_size - post_residual) as f64;
        }
    } else {
        // Last item: pure waste minimization dominates.
        score -= 6.0 * fit_ratio;
    }

    // Last-chance bin: strongly favor using the only bin that fits, avoiding a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when this
    // item is large and the open-bin fit is poor (high post_residual).
    if bin_residual == bin_capacity {
        let poor_fit_penalty = (post_residual as f64) * 0.9;
        let congestion = (open_bins_count as f64).ln().max(0.0);
        // Favor new bin when mean residual across open bins is low (they are full-ish)
        // and current placement would leave big waste; otherwise penalize.
        score = 30.0 + poor_fit_penalty - 0.4 * mean_residual + 2.0 * congestion;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            // A fresh bin can host the next item too; slight discount.
            score -= 0.1 * next_item_size as f64;
        }
    }

    // Global state coupling: when many bins are open with high mean residual,
    // prefer spreading load into emptier bins (avoid fragmentation).
    if bin_residual < bin_capacity {
        let residual_gap = mean_residual - bin_residual as f64;
        score += 0.05 * residual_gap;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_ratio = item_size as f64 / cap;
    let pr_norm = pr / cap;

    // Base: quadratic penalty on post-residual (waste minimization)
    let mut score = pr * (1.0 + 0.8 * pr_norm);

    // Smooth non-linear coupling of post-residual with stream progress:
    // early on, tolerate larger residuals; late, punish them more.
    let late_weight = progress * progress;
    score += 25.0 * late_weight * pr_norm * (1.0 - fit_ratio);

    // Reward tight fits (small post_residual relative to item size)
    let tightness = 1.0 - pr_norm;
    score -= 12.0 * tightness * tightness * fit_ratio;

    // Last-chance bonus: strongly favor the only bin that fits
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0 * (1.0 + progress);
    }

    // New-bin candidate: penalize opening a new bin unless residuals are tight
    if bin_residual == bin_capacity {
        let slack = mean_residual / cap;
        score += 20.0 + 40.0 * (1.0 - slack) * (1.0 - progress);
    }

    // Lookahead: reward bins whose post_residual can host the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            score -= 8.0 * (nx / cap) * (1.0 - progress * 0.5);
        } else {
            score += 5.0 * (1.0 - pr / nx.max(1.0)) * progress;
        }
    }

    // Mild congestion coupling: many open bins -> prefer filling existing ones
    score += (open_bins_count as f64).ln().max(0.0) * 2.0 * pr_norm;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "small dead-space" classes (mod 10 buckets) are preferred.
    let pr = post_residual;
    let class = pr % 10;
    let class_bonus = match class {
        0 => 14.0,               // perfectly reusable residual
        1 | 2 | 3 | 4 => 9.0,    // near-perfect
        5 | 6 | 7 => 0.0,        // neutral mid classes
        8 | 9 => -7.0,           // awkward dead space, penalize
        _ => 0.0,
    };
    score -= class_bonus;

    // Integer-division thresholds: residual that still fits a "medium"
    // item (>= 20) is much more valuable than one that only fits tiny items.
    if pr >= 40 {
        score -= 12.0;
    } else if pr >= 20 {
        score -= 6.0;
    } else if pr > 0 {
        score += 5.0; // nearly dead bin
    }

    // Lookahead coupling: reward residuals that can also host the next item.
    if next_item_size > 0 && pr >= next_item_size {
        score -= 10.0;
        // extra harmony if next item also lands in a good class
        if (pr - next_item_size) % 10 == 0 {
            score -= 6.0;
        }
    } else if next_item_size > 0 && pr > 0 && pr < next_item_size {
        score += 4.0; // creates stranded space relative to lookahead
    }

    // Last-chance bin: strongly favor using it to avoid opening a bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when the item is huge relative to
    // capacity or the fit into open bins is poor (large post_residual).
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let tightness = item_size as f64 / cap;
        score += 18.0 * (1.0 - tightness); // prefer new bin only for big items
        if post_residual == 0 {
            score -= 20.0; // perfect fit in a fresh bin
        }
        if open_bins_count == 0 {
            score -= 50.0; // must open first bin
        }
    }

    // Progress-based mild pressure to consolidate early.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 3.0 * (mean_residual / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for the
    // smallest possible item (size 1) are still technically usable, but
    // residuals below a "dead zone" threshold relative to typical item mass
    // are nearly useless. Penalize small-but-nonzero post_residual hard.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (10.0 - post_residual as f64);
    }

    // Perfect fit is heavily rewarded.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Tight-but-usable fit: reward small positive residuals that could still
    // accept a small future item.
    if post_residual >= 10 && post_residual <= 20 {
        score -= 8.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a new bin is penalized, unless the
    // item fits perfectly nowhere else (post_residual == 0 on a fresh bin) or
    // open-bin pressure is extreme.
    if bin_residual == bin_capacity {
        let pressure = open_bins_count as f64;
        let mut new_bin_penalty = 35.0 + 2.0 * pressure;
        if post_residual == 0 {
            new_bin_penalty = 5.0;
        }
        // If item leaves a large gap in a fresh bin and next item is small
        // enough to use that gap, opening is less bad.
        if next_item_size > 0 && (next_item_size as f64) <= post_residual as f64 {
            new_bin_penalty -= 10.0;
        }
        // Early in the stream, allow more bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        new_bin_penalty -= 10.0 * (1.0 - progress);
        score += new_bin_penalty.max(0.0);
    } else {
        // Reward using existing bins, scaled by how much residual this bin
        // has relative to the mean (prefer consuming the fullest bins).
        let rel = bin_residual as f64 / bin_capacity as f64;
        score -= 5.0 * rel;
        if mean_residual > 0.0 {
            let dev = (bin_residual as f64 - mean_residual) / mean_residual;
            score -= 3.0 * dev;
        }
    }

    // Lookahead coupling: if next item exactly fills the post_residual,
    // strongly reward this placement (chaining).
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 20.0;
    } else if next_item_size > 0 && next_item_size < post_residual {
        score -= 2.0;
    }

    // Open-bin pressure: discourage spreading across many bins.
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through the stream
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // --- Exact / near-exact match with next item (2-step lookahead) ---
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect match: next item exactly fills the bin
        if post_residual == next_item_size {
            score -= 60.0;
        } else if gap <= 10.0 {
            // Near-perfect match: strongly reward tight coupling
            score -= 30.0 - gap * 2.0;
        } else {
            // Penalize residuals that are awkward relative to next item
            score += gap * 0.15;
        }
        // If next item is small, a large post_residual is less wasteful
        if next_item_size <= 20 && post_residual >= next_item_size {
            score -= 5.0;
        }
    }

    // --- Dead space penalty: small residuals that few items can use ---
    if post_residual > 0 && post_residual < 10 {
        score += 40.0; // nearly unusable gap
    } else if post_residual < 20 {
        score += 15.0;
    }

    // --- Perfect fill bonus ---
    if post_residual == 0 {
        score -= 100.0;
    }

    // --- Last-chance bin: only bin that fits, avoid opening new bin ---
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // --- Relative to mean residual: prefer bins tighter than average ---
    score += (mean_residual - post_residual as f64) * 0.3;

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin is fine early, or when item is large and
        // open bins would leave big dead space; otherwise discourage.
        let waste_if_open = open_bins_count as f64 * mean_residual;
        if open_bins_count == 0 || item_size >= 70 {
            score -= 20.0;
        } else if waste_if_open > item_size as f64 * 2.0 {
            score += 30.0; // plenty of room already, don't open
        } else {
            score += 5.0 - progress * 10.0;
        }
    }

    // --- Late stream: consolidate aggressively ---
    score -= progress * 8.0;

    // Prefer placing into bins with less residual overall (tight packing)
    score += (bin_residual as f64 / bin_capacity as f64) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress in the stream (0..1)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // --- Lookahead: penalize post-residuals that can't host the next item ---
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Favor residuals that still fit the next item, tighter is better
            let slack = (post_residual - next_item_size) as f64;
            score -= 6.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Dead space for the next item: penalize proportionally to waste
            let waste = (next_item_size - post_residual) as f64;
            score += 3.0 * waste / bin_capacity as f64 * (1.0 + progress);
        }
        // Bonus if post-residual perfectly complements next item
        if post_residual == next_item_size {
            score -= 12.0;
        }
    } else {
        // Last item: minimize leftover aggressively
        score -= 4.0;
    }

    // --- Last-chance bin: if this is the only bin that fits, strongly favor it ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // --- Tight fit reward: waste = residual - item should be small ---
    let tightness = item_size as f64 / bin_residual as f64;
    score -= 8.0 * tightness;

    // --- Penalize creating large unusable gaps (gap too small for typical items) ---
    if post_residual > 0 && post_residual < 10 {
        score += 15.0; // tiny dead space is worthless
    } else if post_residual >= 10 && post_residual < 20 {
        score += 3.0;
    }

    // --- Global state coupling ---
    // Prefer spreading load when many bins are open with high mean residual
    if open_bins_count > 1 {
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.5 * dev / bin_capacity as f64; // prefer bins near the mean residual (balance)
        score -= 0.05 * open_bins_count as f64;   // slight pressure to use existing bins
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Empty bin: default is bad unless all alternatives look poor.
        score += 25.0;
        // If very few bins can fit this item, opening fresh is more acceptable
        if fitting_bins_count <= 1 {
            score -= 30.0;
        }
        // Early in stream, tolerate opening bins more freely
        score -= 10.0 * (1.0 - progress);
        // If mean residual is low (open bins are nearly full), new bin is fine
        if mean_residual < item_size as f64 {
            score -= 15.0;
        }
    }

    // --- Time-horizon modulation: later in stream, be greedier about tight fits ---
    score -= 5.0 * progress * (bin_residual - post_residual) as f64 / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post residual, with non-linear polynomial shaping in normalized progress
    let mut score = pr * (1.0 + 0.5 * progress) - 30.0 * norm_pr * (1.0 - norm_pr) * (1.0 + progress);

    // Penalize large dead space quadratically, scaled by how full the stream is
    score += 0.25 * norm_pr * norm_pr * cap * (0.5 + progress);

    // Lookahead coupling: reward if next item fits snugly into the post residual
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let fit_gap = (pr - nx).abs();
        score -= 20.0 * (1.0 - fit_gap / cap).max(0.0);
        if nx > pr {
            score += 5.0; // next item can't use this residual anyway
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Mild penalty for proliferating open bins when mean residual is high
    score += 0.05 * open_bins_count as f64 * (mean_residual / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-fit residual: classify leftover space into
    // capacity-fraction buckets. Residuals in (0, 10] are near-perfect fits;
    // residuals in (50, 100) are "half-empty" dead zones worth penalizing.
    let post_class = post_residual / 10; // 0..=10 harmonic class
    match post_class {
        0 => score -= 60.0,                       // near-perfect fit: strongly reward
        1 => score -= 35.0,                       // excellent fit
        2 => score -= 20.0,                       // good fit
        3 => score -= 10.0,                       // decent fit
        4 => score -= 4.0,                        // ok
        5 => score += 6.0,                        // half bin wasted
        6 => score += 10.0,
        7 => score += 14.0,
        8 => score += 18.0,
        9 => score += 22.0,
        _ => {}                                   // class 10 = untouched bin
    }

    // Integer-division threshold coupling: if the lookahead item fits in the
    // post residual, reward; if it exactly fits, reward extra.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 25.0;
        if post_residual % next_item_size == 0 {
            score -= 15.0; // perfect chaining of harmonic classes
        }
    } else if next_item_size > 0 {
        // next item cannot use the leftover: penalize proportionally to how
        // stranded the residual is relative to the smallest plausible item.
        let stranded = post / cap;
        score += 20.0 * stranded;
    }

    // Last-chance bin: if this is the only bin that fits, heavily favor it
    // to avoid opening a new bin for a mediocre placement.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: neutral baseline; only attractive when all open bins
    // would leave badly fragmented residuals. Compare against mean residual.
    if bin_residual == bin_capacity {
        score = 45.0 + 0.3 * (open_bins_count as f64).ln().max(0.0);
        if mean_residual < 15.0 {
            score -= 20.0; // open bins are nearly full; a fresh bin is good
        }
    }

    // Slight preference to fill already-open bins as the stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * progress * (1.0 - post / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space zone: residuals too small to hold any plausible future item
    // are pure waste; penalize them super-linearly.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64);
    }
    if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 200.0;
    }

    // Reward placements that leave room for the lookahead item if it fits,
    // penalize blocking a known next item that would otherwise fit here.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 15.0;
        } else if next_item_size <= bin_residual {
            score += 25.0;
        }
    }

    // Tightness reward: prefer bins where the item fills a large fraction.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 40.0 * fill_ratio * fill_ratio;

    // Last-chance pressure: if this is the only fitting bin, strongly prefer
    // using it over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0 + 0.5 * item_size as f64;
    }

    // Open-bin pressure: many open bins -> discourage spreading; few bins ->
    // new-bin candidate is relatively cheap so allow it.
    if bin_residual == bin_capacity {
        // New-bin candidate baseline: slightly above using an existing bin,
        // but drops as open_bins_count shrinks.
        score = 20.0 + 8.0 * open_bins_count as f64 + 0.3 * mean_residual;
    } else {
        score += 2.0 * open_bins_count as f64;
    }

    // Prefer bins whose residual is close to the mean residual (balance load),
    // avoiding one bin hoarding space while others fragment.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.2 * dev;

    // Late in the stream, be more conservative: tighten fits, avoid new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core: reward tight fits (small post_residual)
    score *= 1.0 + (item_size as f64 / bin_capacity as f64) * 0.3;

    // Aggressive 2-step lookahead: exact match of next item into post_residual is excellent
    if next_item_size > 0 {
        let nr = next_item_size as f64;
        if (post_residual as f64 - nr).abs() < 1.0 {
            score -= 25.0; // perfect chain
        } else if post_residual >= next_item_size {
            // next item fits: leftover after chain
            let chain_left = post_residual as f64 - nr;
            score -= 12.0 * (1.0 - chain_left / bin_capacity as f64);
        } else {
            // next item will NOT fit here: dead space penalty scaled by gap
            let gap = nr - post_residual as f64;
            score += 8.0 * (gap / bin_capacity as f64).min(1.0);
        }
    }

    // Relative to mean residual: bins with more room than average absorb awkward items
    if (post_residual as f64 - mean_residual) > 0.0 {
        score += 3.0 * (post_residual as f64 - mean_residual) / bin_capacity as f64;
    } else {
        score -= 2.0 * (mean_residual - post_residual as f64) / bin_capacity as f64;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a new bin early; relax near end of stream
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score = bin_capacity as f64 * 0.55 - 10.0 * progress;
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 5.0; // pairing current+next in a fresh bin is attractive
        }
    }

    // Prefer filling bins when many are open (consolidation)
    score -= 0.5 * open_bins_count as f64 * (item_size as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for near-perfect fits.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 35.0;
    } else if post_residual < 10 {
        score -= 20.0; // avoid tiny dead space
    }

    // Lookahead: reward if the next item can fit in the post-residual.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // next item chains into this bin: good, but less good if it nearly fills
            let chain_left = post_residual - next_item_size;
            score -= 12.0 - (chain_left as f64) * 0.1;
        } else {
            // next item won't fit here; penalize leaving moderate-but-unusable gaps
            score += (post_residual as f64) * 0.25;
            if post_residual < next_item_size {
                score += 8.0;
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when no open bin is a good fit
    // or open bins are mostly full / few bins open early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let avg_fit = if fitting_bins_count > 0 { 1.0 } else { 0.0 };
        // base penalty for opening new bins, softened when many bins are open and full
        let mut nb = 40.0;
        nb -= (open_bins_count as f64).sqrt() * 2.0;
        nb -= progress * 10.0;
        nb -= mean_residual * 0.15; // if open bins have lots of room, new bin is wasteful
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            nb -= 10.0; // large next item: fresh bin may serve it well
        }
        let _ = avg_fit;
        score += nb;
    } else {
        // Prefer bins whose residual is closest to the item (best-fit flavor),
        // scaled by global mean residual.
        let tightness = (bin_residual as f64 - item_size as f64).abs();
        score += tightness * 0.1;
        score -= mean_residual * 0.05;
    }

    // Mild preference to consolidate into fewer bins over time.
    score += (open_bins_count as f64) * 0.05;

    // Slight time-horizon modulation: late in stream, be greedier about tight fits.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (post_residual.min(20) as f64) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let pr = post_residual as f64;
    let pr_norm = pr / bin_capacity as f64;
    let poly = pr_norm * pr_norm * (1.0 - progress) + pr_norm * progress * progress;
    score += 20.0 * poly;

    // Reward tight fits (small post_residual) more strongly as stream progresses.
    let tight = (1.0 - pr_norm).powi(3);
    score -= 15.0 * tight * (0.5 + progress);

    // Penalize waste relative to mean residual across open bins.
    score += 0.3 * (pr - mean_residual).abs() * (0.5 + progress);

    // Last-chance bin: strong reward to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 + progress);
    }

    // Lookahead: reward if the next item fits the post-residual well.
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        score += 0.4 * gap;
        if pr >= next_item_size as f64 {
            score -= 5.0 * (1.0 - gap / bin_capacity as f64);
        }
    }

    // Slight penalty for proliferating open bins late in the stream.
    score += 0.5 * open_bins_count as f64 * progress;

    // New-bin candidate: keep it neutral-to-slightly-high so real fits win,
    // but allow it when all open bins leave bad residuals.
    if bin_residual == bin_capacity {
        score += 8.0 + 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space that no plausible item (1..100) can fill
    let pr = post_residual;
    let dead = if pr == 0 {
        0.0
    } else if pr < 10 {
        60.0 + pr as f64 // tiny unusable sliver
    } else {
        // modulo structure: residuals divisible by common item sizes are reusable
        let reusable = (pr % 10 == 0) as f64 * 20.0
            + (pr % 25 == 0) as f64 * 15.0
            + (pr % 20 == 0) as f64 * 10.0;
        (pr as f64) - reusable
    };
    score += dead * 0.5;

    // Perfect fill is heavily rewarded
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Tight fit: post_residual smaller than half of typical smallest item
    if post_residual > 0 && post_residual < 15 {
        score += 80.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 400.0;
        } else if next_item_size <= post_residual {
            score -= (post_residual - next_item_size) as f64 * 1.5;
        } else {
            score += (next_item_size - post_residual).min(30) as f64 * 0.8;
        }
    }

    // Last-chance bin: penalize skipping it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: only attractive when current bins are crowded
    if bin_residual == bin_capacity {
        let crowded = (open_bins_count as f64) * (mean_residual / cap);
        score = 40.0 + crowded * 10.0 - (item_size as f64) * 0.3;
        if fitting_bins_count == 0 {
            score -= 500.0;
        }
    }

    // Mild preference for fuller bins early vs late in stream
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= (bin_capacity - bin_residual) as f64 * (0.3 + 0.4 * progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Strict dead-space avoidance: gaps that are unusable for likely items are heavily penalized.
    // A gap is "dead" if it is small (below the minimum plausible item footprint) or awkwardly small
    // relative to the lookahead item.
    let min_item = 1.0;
    if post > 0.0 && post < min_item.max(12.0) {
        score += 25.0 * (min_item.max(12.0) - post) / 12.0;
    }

    // Reward tight fits: small post_residual relative to bin size.
    let tightness = 1.0 - post / cap;
    score -= 15.0 * tightness * tightness;

    // Penalize creating a gap that the next item cannot use.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post < nxt {
            score += 8.0 * (nxt - post) / cap;
        } else {
            // reward leaving exactly enough room for the next item
            score -= 6.0 * (1.0 - ((post - nxt).abs()) / cap);
        }
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones
    // (penalize opening/keeping too many bins alive).
    score += 2.0 * (open_bins_count as f64).ln().max(0.0);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Slight preference to keep mean residual spread balanced: avoid bins far below mean fill.
    score += 0.05 * (mean_residual - post).abs();

    // Mild time-decay: later in the stream, packing tighter matters more.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.3 * progress;

    // New-bin candidate: empty bins should only win when open bins are genuinely crowded.
    if bin_residual == bin_capacity {
        score += 10.0 + 3.0 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for exact or near-exact fill
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 300.0;
    }

    // 2-step lookahead: reward residuals that can host the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // next item fits here afterwards: good chain
            let slack = (post_residual - next_item_size) as f64;
            score -= 80.0 - slack * 0.4;
            if post_residual == next_item_size {
                score -= 200.0; // perfect 2-item chain
            }
        } else {
            // dead space relative to next item
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 1.5;
        }
    }

    // Reward tight fits: small post_residual relative to mean residual
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 150.0;
    }

    // Penalize spreading across too many open bins when many fit
    if fitting_bins_count > 2 {
        score += 10.0;
    }

    // New-bin candidate: make it attractive only when current bin would leave bad residue
    if bin_residual == bin_capacity {
        let waste_if_open = (bin_capacity - item_size) as f64;
        score = waste_if_open * 2.0;
        if next_item_size > 0 && waste_if_open >= next_item_size as f64 {
            score -= 40.0; // fresh bin can chain with next item
        }
        if fitting_bins_count == 1 {
            score += 400.0; // don't abandon the only fitting bin
        }
    }

    // Late-stream consolidation: prefer filling existing bins as stream ends
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 20.0 * (bin_capacity - post_residual) as f64 / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits (small post residual) nonlinearly
    let tightness = 1.0 - (post_residual as f64) / cap;
    score -= 40.0 * tightness * tightness * tightness;

    // Penalize dead space that is too small for typical future items
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward if next item fits exactly in post residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            score -= 15.0 * (1.0 - ((post_residual - next_item_size) as f64) / cap);
        } else {
            // next item won't fit here; slight penalty if we waste space
            score += 8.0;
        }
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // Time horizon: early in stream, be more selective (penalize loose fits);
    // late in stream, prefer closing out bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * (bin_residual as f64 - post_residual as f64) * 0.1;
    score -= progress * 10.0 * (post_residual as f64 / cap);

    // Global state: many open bins -> discourage opening/spreading
    if open_bins_count > 3 {
        score -= 3.0 * (open_bins_count as f64).ln();
    }

    // Compare against mean residual: bins with residual far above mean are
    // good candidates to absorb this item
    let dev = bin_residual as f64 - mean_residual;
    score -= 0.15 * dev;

    // New-bin candidate: only attractive when nothing fits well
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // base cost of opening a bin; reduced when current bin fits are poor
        let poor_fit = (post_residual as f64) > cap * 0.4;
        score += 55.0;
        if poor_fit { score -= 30.0; }
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
    let nx = next_item_size as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Normalized post-residual and its smooth non-linear couplings
    let r = pr / cap;
    let r2 = r * r;
    let r3 = r2 * r;

    // Base: quadratic waste penalty, softened by cubic term
    let mut score = pr - 0.6 * pr * r2 + 0.25 * pr * r3;

    // Smooth polynomial coupling with stream progress: early stream tolerates
    // larger residuals (future items may fill them), late stream punishes waste.
    let p = progress;
    let w = p * p * (3.0 - 2.0 * p); // smoothstep in [0,1]
    score += w * (pr * r2 * 0.8) - (1.0 - w) * (pr * 0.15);

    // Reward tight fits: bonus when post_residual is small relative to item size
    let tight = (it / cap) * (1.0 - r);
    score -= 2.0 * tight * tight;

    // Lookahead coupling: if next item fits the post-residual exactly, reward strongly
    if nx > 0.0 && nx <= pr {
        let gap = (pr - nx) / cap;
        score -= 3.0 * (1.0 - gap) * (1.0 - gap);
    } else if nx > 0.0 {
        // next item cannot follow here: mild penalty scaled by residual
        score += 0.3 * r;
    }

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 {
        score -= 5.0;
    }

    // Mean-residual alignment: prefer bins whose residual tracks the fleet mean
    let dev = (pr as f64 - mean_residual) / cap;
    score += 0.5 * dev * dev;

    // New-bin candidate handling: empty bin gets a moderate default so that
    // only genuinely poor fits in open bins trigger opening a new bin.
    if bin_residual == bin_capacity {
        score = cap * 0.55 + w * cap * 0.15;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: integer division into deciles of capacity
    let post_class = post_residual / 10;
    let next_class = if next_item_size == 0 { 99 } else { next_item_size / 10 };

    // Reward exact or near-exact fits (dead space elimination)
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    } else if post_residual <= 10 {
        score -= 10.0;
    }

    // Coupling: post_residual class matches next item class -> strong reward
    if next_item_size > 0 && post_class == next_class && post_residual >= next_item_size {
        score -= 25.0;
    }
    // Lookahead: can next item also fit here afterwards
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 {
        score += 6.0;
    }

    // Modulo arithmetic on residual: residuals that are multiples of 10 pair well
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 5.0;
    }
    // Penalize awkward residuals (prime-like / odd small remainders)
    if post_residual % 2 == 1 && post_residual < 20 {
        score += 3.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Prefer filling bins with low residual relative to mean (consolidation)
    score += 0.5 * ((post_residual as f64) - mean_residual).max(0.0);
    score -= 0.3 * (mean_residual - post_residual as f64).max(0.0);

    // New-bin candidate: only attractive when no good fit exists
    if bin_residual == bin_capacity {
        let bad_fit = post_residual as f64 > cap * 0.4;
        let crowded = open_bins_count as f64 > 0.0 && mean_residual < item_size as f64;
        if bad_fit && (crowded || fitting_bins_count <= 1) {
            score -= 15.0;
        } else {
            score += 20.0;
        }
    }

    // Mild early-stream exploration: tolerate imperfect fits early
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= (1.0 - progress) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to ever hold
    // another item (min item size = 1, but practically small gaps are waste)
    if post_residual > 0 && post_residual < 10 {
