}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;

    // Base: best-fit core (minimize post_residual)
    let mut score = post_residual as f64;

    // Smooth polynomial coupling of post_residual with stream progress.
    // Early in the stream, keep residuals flexible; late, tighten packing.
    let pr = post_residual as f64 / cap;
    let flex = 1.0 - progress; // 1 early -> 0 late
    score += 8.0 * pr * pr * flex * cap * 0.05;      // mild early tolerance for slack
    score -= 6.0 * pr * (1.0 - pr) * progress;       // late-stream reward for tight fits

    // Penalize post_residual that cannot host a plausible next item (lookahead coupling)
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if (post_residual as f64) < ni {
            // dead space relative to the lookahead item, weighted by progress
            let dead = ni - post_residual as f64;
            score += 4.0 * (dead / cap) * (0.5 + progress);
        } else {
            // residual still usable for the next item: reward
            score -= 2.0 * (ni / cap) * (1.0 - progress);
        }
    }

    // Mean-residual alignment: prefer bins whose residual is near the mean
    // (keeps the pool homogeneous), with a smooth quadratic term.
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 3.0 * dev * dev;

    // Last-chance bin: strongly favor using the only bin that fits,
    // avoiding a needless new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling (bin_residual == bin_capacity):
    // opening a bin is only attractive when the item would leave a large,
    // awkward residual in existing bins, or few bins fit the item.
    if bin_residual == bin_capacity {
        let open_penalty = 10.0 + 2.0 * open_bins_count as f64;
        let scarcity = if fitting_bins_count > 0 { 1.0 / fitting_bins_count as f64 } else { 1.0 };
        // Reward opening when item is large (leaves small residual = efficient use)
        let fill_gain = (item_size as f64 / cap) * 12.0;
        score += open_penalty * (1.0 - scarcity) - fill_gain * (0.4 + 0.6 * progress);
        // Late in stream, opening fresh bins is cheaper than fragmenting
        score -= 5.0 * progress * (item_size as f64 / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
