    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        score -= 18.0; // near-perfect fit, residual likely unusable anyway
    }

    // Lookahead coupling: does next item fit the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
