    // New-bin candidate handling: opening a new bin is expensive
    if bin_residual == bin_capacity {
        score += 30.0 + 2.0 * open_bins_count as f64;
        // but if no open bin fits well (post_residual large in every fit), opening is OK
        if post_residual >= bin_capacity {
