    // far below mean wastes capacity, far above mean leaves fragmented space.
    let pr = post_residual as f64;
    let mr = mean_residual.max(1.0);
    score += 0.2 * (pr - mr).abs();

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a new bin when decent open bins exist (new-bin candidate guard).
    if bin_residual == bin_capacity {
        let tightness = if post_residual < 20 { 1.0 } else { 0.0 };
        score += 40.0; // base cost of a fresh bin
        score -= tightness * 35.0; // allow new bin only if item is huge relative to it
        if next_item_size > 0 && (next_item_size as f64) <= post_residual as f64 {
            score -= 10.0;
        }
    }

    // Late in the stream, prefer consolidating into fewer bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - pr / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 8.0 * fit_ratio * fit_ratio;

    // Penalize large leftover slivers that few future items can use.
    if post_residual > 0 && post_residual < 10 {
        score += 6.0;
    } else if post_residual >= 10 && post_residual < 25 {
        score += 2.0;
    }

    // Perfect fill bonus.
    if post_residual == 0 {
        score -= 15.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 5.0 + 0.05 * next_item_size as f64;
    }
    // Penalize leaving a residual slightly below the next item (near-miss dead space).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 3.0;
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Opening a new bin wastes residual capacity of existing bins; penalize
        // unless existing fits are poor (low fit_ratio across the board is
        // approximated via mean_residual vs item_size).
        score += 10.0;
        // If mean residual is small (bins are full-ish), a new bin is more acceptable.
        score -= (mean_residual / bin_capacity as f64) * 8.0;
        // If the best possible existing fit is bad (item barely differs from residual),
        // encourage opening a fresh bin: approximate via mean_residual comparison.
        if mean_residual < item_size as f64 * 0.75 {
            score -= 9.0;
        }
        // Early in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += (1.0 - progress) * 4.0;
        // Many open bins: discourage opening yet another.
        score += 0.3 * open_bins_count as f64;
    }

    // Mild preference for filling bins with lower residual overall (compactness).
    score += (bin_residual as f64 - mean_residual) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let r = post_residual as f64;
    let cap = bin_capacity as f64;
    let rn = r / cap; // normalized post residual
    let mut score = r;

    // Smooth non-linear coupling of post-residual with stream progress
    score += 12.0 * rn * rn * (1.0 + progress) * cap * 0.05;

    // Reward tight fits, more so late in the stream
    let tightness = 1.0 - rn;
    score -= 20.0 * tightness * tightness * (0.5 + progress);

    // Penalize dead space relative to mean residual of open bins
    score += 0.15 * (r - mean_residual).abs() * (0.5 + progress);

    // Last-chance bin: strong reward to use it
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Lookahead: reward leaving room for the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if r >= nx {
            score -= 8.0 * (1.0 - ((r - nx) / cap).abs());
        } else {
            score += 6.0;
        }
    }

    // Slight penalty for proliferating open bins early
    score += 0.02 * open_bins_count as f64 * (1.0 - progress);

    // New-bin candidate: prefer it only when existing residuals are poor
    if bin_residual == bin_capacity {
        score += 10.0 * (1.0 - tightness) + 5.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
