pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small nonzero gaps are nearly useless.
    if post_residual > 0 {
        let dead = post_residual as f64;
        // Smallest plausible item is 1; gaps below ~10 are dead space.
        if dead < 10.0 {
            score += 40.0 * (10.0 - dead) / 10.0;
        } else {
            // Usable gap: mild reward proportional to how well future items fit.
            let usable = dead / bin_capacity as f64;
            score -= 6.0 * usable;
        }
    } else {
        // Perfect fit: strong reward.
        score -= 25.0;
    }

    // Reward exact-tight packing relative to item size (waste ratio penalty).
    let fill = item_size as f64 / bin_residual.max(1) as f64;
    score -= 15.0 * fill;

    // Lookahead: if the next item fits exactly in the post-residual, reward.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size <= post_residual {
            score -= 8.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // Next item won't fit here: penalize leaving a gap it can't use.
            score += 5.0;
        }
    }

    // Open-bin pressure: discourage spreading across too many bins when
    // mean residual is already large; encourage consolidation.
    let mean_res = mean_residual.max(0.0);
    score += 0.05 * open_bins_count as f64 * (1.0 - mean_res / bin_capacity as f64);

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score = 35.0;
        // Cheaper to open a new bin when many bins are open with tiny residuals.
        score -= 0.3 * open_bins_count as f64;
        // If item nearly fills a fresh bin, opening is attractive.
        score -= 10.0 * (item_size as f64 / bin_capacity as f64);
        // If the only alternative is a bad fit, opening a new bin is better.
        if fitting_bins_count == 0 {
            score -= 20.0;
        }
    }

    // Slight stream progression bias: as stream advances, prefer tighter packing.
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        score -= 3.0 * progress * fill;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward perfect / near-perfect fits (low post_residual).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 300.0;
    }

    // 2-step lookahead: if the next item fits exactly into post_residual, strongly reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 800.0;
        } else if next_item_size <= post_residual {
            // Reward proportional to how much of post_residual the next item consumes.
            let fill = next_item_size as f64 / post_residual as f64;
            score -= 200.0 * fill;
        } else {
            // Next item cannot use the residual: penalize dead space proportionally.
            score += 0.5 * (post_residual as f64 - next_item_size as f64).abs();
        }
    }

    // Relative to mean residual: prefer bins whose post_residual is below average
    // (compact packing), penalize leaving bins far above the mean.
    let pr = post_residual as f64;
    if pr > mean_residual {
        score += 0.6 * (pr - mean_residual);
    } else {
        score -= 0.3 * (mean_residual - pr);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 250.0;
    }

    // Penalize wasting a fresh bin when open bins could fit (new-bin candidate guard).
    if bin_residual == bin_capacity {
        score += 50.0 + 0.2 * item_size as f64;
        // But allow opening a new bin if nothing fits well elsewhere.
        if fitting_bins_count == 0 {
            score -= 400.0;
        }
    }

    // Mild pressure toward fewer open bins over time.
    score += 0.01 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through the stream (0..1)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Tight-fit reward: quadratic bonus for small post-residual
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 45.0 * tightness * tightness;

    // Penalize dead space: residuals too small to hold even the smallest item (1)
    if post_residual == 0 {
        score -= 30.0; // perfect fill is excellent
    } else if post_residual < 10 {
        score += 18.0; // sliver of unusable space
    }

    // Lookahead: reward if the next item fits in the post-residual
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            score += 8.0;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize spreading across many open bins; encourage consolidation
    score += 0.6 * open_bins_count as f64;

    // Deviation from mean residual: prefer bins whose residual is below average
    // (i.e., fuller bins), scaled by progress so late stream tightens up.
    let dev = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    score += (10.0 + 30.0 * progress) * dev;

    // New-bin candidate: reserve new bins for cases where the item fits
    // existing bins poorly (large post-residual). Make empty-bin score
    // essentially equal to the waste it would create, plus an opening cost
    // that shrinks as the stream progresses.
    if bin_residual == bin_capacity {
        score = post_residual as f64 + 15.0 * (1.0 - progress) + 0.5 * open_bins_count as f64;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let ir = bin_residual as f64;
    let item = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Core: minimize waste, with super-linear penalty on dead space.
    let mut score = pr * (1.0 + 0.02 * (pr / cap) * (pr / cap));

    // Smooth polynomial coupling of waste with stream progress:
    // late in the stream, tight fits matter more (less room to consolidate).
    let tightness = pr / cap;
    score += (progress * progress) * 40.0 * tightness * (1.0 - tightness);

    // Reward near-perfect fits smoothly (small post_residual => big discount).
    score -= 15.0 * (-pr / 12.0).exp();

    // Penalize bins whose residual deviates far from the fleet mean
    // (keep residuals homogeneous so future items fit many bins).
    score += 0.05 * (pr - mean_residual).abs();

    // Lookahead: penalize leaving residual that fits next item badly
    // (either almost fits but not quite, or wastes too much).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let gap = (pr - nxt) / cap;
            score += 6.0 * gap * (1.0 - gap);
            // reward exact chain fit
            score -= 10.0 * (-(pr - nxt).abs() / 8.0).exp();
        } else {
            // next item cannot use leftover: mild penalty scaled by closeness
            score += 3.0 * (1.0 - (nxt - pr) / cap);
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: heavily penalize opening a new bin unless
    // the item is huge relative to capacity (then fresh bin is natural).
    if bin_residual == bin_capacity {
        let load = item / cap;
        score = cap * (1.0 - load) * (1.0 + 0.5 * progress);
        if fitting_bins_count >= 1 {
            score += 30.0; // some open bin fits; only open new bin if truly better
        }
    }

    // Mild preference to fill bins with more content already (fewer bins).
    score += 0.002 * open_bins_count as f64 * (pr / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: perfect fits (0) and tiny residues are golden.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Small dead space classes: residue <= 5 is nearly perfect.
        if post_residual <= 5 {
            score -= 120.0;
        } else if post_residual <= 10 {
            score -= 60.0;
        } else if post_residual <= 20 {
            score -= 20.0;
        }

        // Modulo-10 harmonic classes: residues that are multiples of 10 align with
        // typical item sizes (multiples of 10), making them reusable.
        let r = post_residual % 10;
        if r == 0 {
            score -= 15.0;
        } else if r >= 5 {
            score -= 3.0;
        } else {
            score += 5.0; // awkward residue class
        }

        // Integer-division thresholds: which size classes can still fit in residue?
        let fits_half = post_residual >= 50;
        let fits_quarter = post_residual >= 25;
        if !fits_half {
            score += 10.0; // bin nearly dead
        }
        if !fits_quarter && fits_half {
            score += 3.0;
        }

        // Lookahead coupling: reward residues that can host next_item_size exactly.
        if next_item_size > 0 {
            if next_item_size <= post_residual {
                // next item fits here: strong reward, scaled by how snug
                let snug = (post_residual - next_item_size) as f64;
                score -= 40.0 - snug * 0.3;
                if (post_residual - next_item_size) == 0 {
                    score -= 200.0; // chain of perfect fits
                }
            } else {
                // next item won't fit: penalize leaving this bin as a trap
                score += 12.0;
            }
        } else {
            // last item: just minimize waste
            score -= 5.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 {
        score -= 35.0;
    }

    // New-bin candidate handling: empty bin has residual == capacity.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin; make it competitive only when open bins
        // would leave large, unusable residues.
        score = cap * 0.45 + 15.0;
        // If mean residual across open bins is large, opening fresh is more attractive.
        score -= (mean_residual / cap) * 25.0;
        // If many bins already fit the item, opening a new one is wasteful.
        score += (fitting_bins_count as f64) * 10.0;
        // Early in the stream, opening bins is cheaper (builds a diverse portfolio).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= (1.0 - progress) * 10.0;
        // If next item is huge and current best residue is small, new bin helps.
        if next_item_size >= 50 && mean_residual < 20.0 {
            score -= 20.0;
        }
    }

    // Mild pressure against hoarding many open bins.
    score += (open_bins_count as f64) * 0.4;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A gap is "dead" if it's too small to hold even the smallest plausible item.
    if post_residual > 0 {
        let dead_threshold = 10u32.min(bin_capacity / 10);
        if post_residual <= dead_threshold {
            // The smaller (and thus more useless) the gap, the larger the penalty.
            let uselessness = 1.0 - (post_residual as f64 / (dead_threshold as f64 + 1.0));
            score += 40.0 * uselessness * uselessness;
        }
        // Zero residual is a perfect fit — reward strongly.
        if post_residual == 0 {
            score -= 25.0;
        }
    }

    // Perfect-fit lookahead: if the next item exactly fills the post_residual,
    // this placement is exceptionally valuable.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 30.0;
    }
    // If next item can still fit into the post gap, mildly reward leaving room.
    if next_item_size > 0 && post_residual >= next_item_size && post_residual > 0 {
        score -= 5.0;
    }
    // Penalize leaving a gap the next item cannot use (creates stranded space).
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 10.0;
    }

    // Open-bins pressure: discourage opening/keeping too many bins alive.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.6 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Last-chance bin: strongly prefer using the only bin that fits,
    // avoiding a fresh bin opening.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Mean residual coupling: prefer bins whose residual is below average
    // (fill the tighter bins first, keep large residuals flexible).
    score += 0.15 * (mean_residual - bin_residual as f64);

    // Prefer tighter fits generally: normalized fill ratio bonus.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 8.0 * fill_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

