    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual > next_item_size {
            let slack = post_residual - next_item_size;
            if slack <= 10 {
                score -= 150.0 - slack as f64 * 8.0;
            } else {
                score -= 20.0 / slack as f64;
            }
        } else {
            // Next item cannot use the leftover space; penalize proportionally.
            score += (next_item_size - post_residual) as f64 * 0.6;
        }
