    // Compare post_residual against the mean residual across open bins:
    // leaving less than average residue is good (tight packing), more is wasteful.
    let mean_post = mean_residual - item_size as f64;
    score += (post_residual as f64 - mean_post) * 0.8;

    // Last chance bin: strongly prefer using it instead of opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 300.0;
    }

    // Penalize opening a new bin when good fits exist, unless current fit is terrible.
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost of consuming fresh capacity.
        score += 60.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 40.0;
        }
        if fitting_bins_count > 0 {
            score += 120.0; // discourage opening when existing bins fit
