        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 50.0;
    } else {
        // Prefer bins with smaller residual before placement (tighter bins first).
        score += bin_residual as f64 * 0.1;
    }

    // Slight load balancing: many open bins -> prefer filling existing ones.
    if open_bins_count > 4 {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
