        } else {
            // Compare best possible existing fit vs fresh bin.
            let tightness = item_size as f64 / bin_capacity as f64;
            (1.0 - tightness) * (mean_residual / bin_capacity as f64)
        };
        // Fresh bin score: its post_residual is large; adjust by desperation.
        score = (bin_capacity - item_size) as f64 + 30.0 * fit_ratio * fit_ratio
            - 18.0 * desperation
            + 8.0 * (1.0 - step_index as f64 / total_items.max(1) as f64);
    }

    // Time horizon: early in stream, slightly discourage fragmenting bins
    // (long future needs capacity); late in stream, just fill anything.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 6.0 * (1.0 - progress) * fit_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;

    // Base: post-residual with non-linear shrinkage (quadratic coupling with progress).
    let mut score = post * (1.0 + 0.35 * norm_post * (1.0 - progress)) + 45.0 * progress * norm_post * norm_post;

    // Reward tight fits: smooth exponential bonus on low post-residual.
    score -= 30.0 * (-norm_post * 4.0).exp();

    // Penalize creating dead space that cannot fit the lookahead item.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).max(0) as f64;
        score += 0.12 * gap * (0.5 + progress);
        // Bonus if post-residual still fits the next item smoothly.
        let fits_next = (next_item_size as f64 / cap).max(0.0);
        score -= 8.0 * (-((post - fits_next * cap).abs() * 0.05)).exp();
    }

    // Last-chance bin: strong reward to avoid opening a new bin needlessly.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0 * (1.0 - progress);
    }

    // New-bin candidate: mild penalty so it's chosen only when open bins fit poorly.
    if bin_residual == bin_capacity {
        score += 6.0 + 10.0 * (1.0 - progress) - 0.02 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size <= item_size {
            score -= 4.0; // fresh bin is fine for clustered streams
        }
    }

    // Slight preference for bins below mean residual (consolidating space).
    score += 0.05 * (post - mean_residual).max(-50.0).min(50.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: residuals divisible by small
    // moduli are more likely reusable by future items.
    if post_residual > 0 {
        let pr = post_residual;
        let mut bonus = 0.0;
        if pr % 10 == 0 { bonus += 6.0; }
        if pr % 5 == 0 { bonus += 2.0; }
        if pr % 20 == 0 { bonus += 3.0; }
        if pr % 25 == 0 { bonus += 2.0; }
        if pr % 50 == 0 { bonus += 2.0; }
        // integer-division threshold: tiny leftovers are dead space
        if pr / 10 == 0 { bonus -= 12.0; }        // pr < 10
        else if pr / 10 == 1 { bonus -= 4.0; }    // 10..19
        else if pr / 10 >= 5 { bonus += 3.0; }    // >=50, very reusable
        score -= bonus;
    } else {
        score -= 10.0; // perfect fill is ideal
    }

    // Lookahead: if the next item fits exactly into post_residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 15.0;
        } else if next_item_size <= post_residual {
            let gap = (post_residual - next_item_size) as f64;
            score -= 8.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // next item cannot use this bin's leftover; slight penalty
            score += 2.0;
        }
    }

    // Last-chance bin: using it avoids opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 7.0;
    }

    // Capacity fraction coupling: prefer bins whose fill ratio is high.
    let fill = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= 5.0 * fill;

    // Prefer tightness relative to the mean residual of open bins.
    score += 0.3 * (post_residual as f64 - mean_residual).abs() / (1.0 + mean_residual);

    // New-bin candidate handling: only open a new bin when the item fits
    // poorly everywhere (or there is nothing open yet).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64).max(1.0);
        let poor_fit = post_residual as f64 > 0.45 * bin_capacity as f64;
        if fitting_bins_count == 0 || (poor_fit && open_bins_count > 2 && progress > 0.05) {
            score -= 3.0;
        } else {
            score += 14.0; // keep using existing bins by default
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals below the minimum item size are pure waste.
    if post_residual < 10 {
        score += 100.0;
    } else if post_residual < 20 {
        score += 25.0;
    } else if post_residual < 30 {
        score += 8.0;
    }

    // Reward tight fits (small post_residual relative to capacity) more aggressively.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Last chance: strongly favor using the only bin that fits, before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new bins,
    // and slightly prefer bins with larger residuals to consolidate.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = 2.0 + 3.0 * progress;
    score += pressure * (open_bins_count as f64).ln().max(0.0);

    // Prefer bins with residual above the mean (they can absorb more future items).
    if (bin_residual as f64) < mean_residual {
        score += 3.0;
    }

    // Lookahead: if next item fits the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    }
    // If next item would leave this bin's post-residual as dead space, penalize.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 5.0;
    }

    // New-bin candidate: make it moderately attractive only when few bins exist
    // or the item is large; otherwise open bins should be preferred.
    if bin_residual == bin_capacity {
        let base = 15.0 + 0.5 * open_bins_count as f64;
        score += base - (item_size as f64 / 10.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-exact fits strongly
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Penalize dead space relative to smallest plausible item
        let waste = post_residual as f64;
        score += (waste * waste) / 100.0;
    }

    // 2-step lookahead: reward when next item fits into post_residual
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 120.0 + 0.5 * next_item_size as f64;
        // Extra bonus if next item fills the bin exactly after this placement
        if post_residual == next_item_size {
            score -= 150.0;
        }
    } else if next_item_size > 0 {
        // Next item won't fit here: mild penalty scaled by mismatch
        score += 20.0 + 0.3 * (next_item_size as f64 - post_residual as f64).min(80.0);
    }

    // Relative-to-mean residual coupling: prefer bins with residual below mean (tighter bins)
    score -= 0.8 * (mean_residual - post_residual as f64);

    // Last-chance bin before opening a new one: strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: penalize opening a new bin unless current item is large
    if bin_residual == bin_capacity {
        score += 60.0 - 0.5 * item_size as f64;
    }

    // Early in stream: slightly discourage opening many bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity && progress < 0.3 {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) non-linearly.
    if post_residual > 0 {
        score -= 18.0 / (post_residual as f64).sqrt();
    } else {
        score -= 25.0; // perfect fit bonus
    }

    // Penalize dead space that cannot fit even the smallest future item.
    if post_residual > 0 && post_residual < 10 {
        score += 30.0; // unusable sliver
    }

    // Lookahead: if next item fits exactly in post_residual, strongly favor this bin.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let gap = (post_residual - next_item_size) as f64;
            score -= 15.0 / (1.0 + gap);
        } else {
            score += 6.0; // next item won't chain here
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Prefer filling bins with large residuals when many bins are open (reduce fragmentation).
    score -= 0.05 * (bin_residual as f64) * (open_bins_count as f64).ln();

    // Time horizon: early on, be conservative (prefer existing bins); late, pack tightly.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.3 * progress * (post_residual as f64 / bin_capacity as f64);

    // Relative-to-mean adjustment: a bin with residual far from the mean is either
    // a candidate for consolidation (large residual) or nearly full (small residual).
    let dev = bin_residual as f64 - mean_residual;
    score += 0.08 * dev;

    // New-bin candidate: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        let desperation = if fitting_bins_count == 0 { 0.0 } else { 12.0 + 4.0 * open_bins_count as f64 };
        score += desperation;
        // A new bin is fine if the item is large (would leave tiny residual anyway).
        score -= 0.1 * item_size as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;

    // Base: prefer small post-residual, with non-linear polynomial coupling
    let mut score = post * (1.0 + 0.5 * norm_post * norm_post);

    // Stream-progress coupling: later in the stream, dead space matters more
    let prog_coupling = progress * progress * (1.0 - progress);
    score += 40.0 * prog_coupling * norm_post * norm_post;

    // Penalize post-residual that cannot fit the lookahead item (smoothly)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let unusable = (nxt - post).max(0.0) / cap;
        score += 25.0 * unusable * unusable;
        // Reward when post-residual exactly accommodates next item
        let fit_gap = (post - nxt).abs() / cap;
        score -= 12.0 * (1.0 - fit_gap).max(0.0) * (1.0 - norm_post);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 30.0 * (1.0 - norm_post);
    }

    // Mild penalty when many open bins have large residuals (fragmentation pressure)
    let frag = (mean_residual / cap - norm_post).abs();
    score += 5.0 * frag;

    // Slight preference for filling bins tighter when many bins are open
    score += 0.02 * open_bins_count as f64 * norm_post;

    // Encourage closing near-full bins
    score -= 20.0 * (1.0 - norm_post) * (1.0 - norm_post) * norm_post;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space in low classes is worse.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap;

    // Penalize residuals that fall into "unusable" small bands (1..10 or 11..19 style gaps)
    if post_residual > 0 && post_residual < 10 {
        score += 40.0; // tiny sliver: near-waste
    } else if post_residual < 20 {
        score += 15.0;
    } else if post_residual < 35 {
        score -= 5.0; // sweet spot: fits small items
    }

    // Modulo logic on post_residual: residuals that are multiples of common item
    // sizes (10, 20, 25, 50) are reusable -> reward.
    let h = post_residual % 10;
    if post_residual > 0 {
        if h == 0 {
            score -= 8.0;
        } else if h <= 4 {
            score += h as f64; // awkward remainder
        }
    }
    if post_residual % 25 == 0 && post_residual > 0 {
        score -= 6.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 50.0;
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 10.0 * (1.0 - slack / cap);
        } else {
            // next item won't fit here; penalize leaving large dead space
            score += 5.0 + pr * 0.1;
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        score = cap * 0.6 + 10.0; // default: discourage opening new bin
        if fitting_bins_count == 0 || (fitting_bins_count == 1 && item_size > 60) {
            score = cap * 0.3; // allow opening when fits are poor
        }
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 5.0; // room to pair upcoming items
        }
    }

    // Mild pressure to fill bins tightly as stream progresses.
    score *= 1.0 - 0.15 * (step_index as f64 / total_items.max(1) as f64);

    // Prefer bins below mean residual (tighter packing toward fuller bins).
    score += 0.05 * (pr - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful
    // later are heavily penalized. Define a "useful floor" from item size range.
    let min_item = 1.0f64;
    let max_item = 100.0f64;
    let pr = post_residual as f64;

    // Dead zone: 0 < post_residual < min_item is pure waste.
    if pr > 0.0 && pr < min_item {
        score += 1000.0;
    }

    // Penalize residuals that no plausible future item can use efficiently:
    // anything below the smallest useful chunk is dead weight; scale penalty
    // as residual shrinks toward the dead zone.
    let usable = (pr - min_item).max(0.0) / max_item;
    score += (1.0 - usable) * 60.0;

    // Reward tight fits (small post_residual) superlinearly.
    score -= (item_size as f64 / bin_capacity as f64) * 25.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 80.0;
    }

    // Open-bins pressure: with many open bins, discourage opening new ones
    // (penalize the empty-bin candidate) and favor consolidating into
    // existing bins, especially the tightest ones.
    let open_pressure = open_bins_count as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are already open.
        score += 30.0 + open_pressure * 4.0;
    } else {
        // Existing bin: mild reward that grows with open bin count.
        score -= open_pressure.min(20.0) * 0.5;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if the next item fits exactly in the post residual,
    // this placement sets up a perfect follow-up; reward it.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack == 0 {
            score -= 50.0;
        } else {
            score -= (next_item_size as f64) * 0.2;
        }
    }

    // Slight preference for bins with below-average residual (consolidate
    // fullness into already-full bins, keep emptier bins flexible).
    if bin_residual != bin_capacity {
        score += (mean_residual - bin_residual as f64) * 0.15;
    }

    // Late-stream tightening: as the stream progresses, become more
    // aggressive about filling bins tightly and avoiding new bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score += progress * 25.0;
    } else {
        score -= progress * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong base preference for tight fits
    score += 0.6 * (post_residual as f64).powi(2) / bin_capacity as f64;

    // Lookahead: perfect 2-step match bonus (post_residual == next_item_size)
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let pr = post_residual as f64;
        if post_residual == next_item_size {
            score -= 40.0; // exact 2-step fill
        } else if post_residual >= next_item_size {
            let gap = pr - nx;
            score -= 12.0 * (1.0 - gap / bin_capacity as f64);
            // penalize leaving awkward leftovers after the lookahead item
            score += 0.25 * gap / bin_capacity as f64;
        } else {
            // next item cannot follow here: mild penalty scaled by overshoot
            score += 0.5 * (nx - pr) / bin_capacity as f64;
        }
    }

    // Relative-to-mean residual coupling: prefer bins with residual below mean (denser bins)
    score += 1.5 * (bin_residual as f64 - mean_residual) / bin_capacity as f64;

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Penalize opening a new bin when good fitting bins exist
    if bin_residual == bin_capacity {
        score += 5.0 + (fitting_bins_count as f64) * 3.0;
        // but a new bin is fine late in the stream or with lookahead mismatch
        if next_item_size > 0 && (next_item_size as f64) > (bin_capacity as f64 - item_size as f64) {
            score -= 8.0;
        }
    }

    // Early stream: consolidate into fewer bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 2.0 * (1.0 - progress) * (open_bins_count as f64 / (open_bins_count as f64 + 5.0));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to item size).
    let tightness = (post_residual as f64) / (bin_capacity as f64);
    score += 12.0 * tightness * tightness;

    // Penalize dead space that no plausible future item can use.
    if post_residual > 0 && post_residual < 10 {
        score -= 6.0; // near-perfect fill bonus
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly into the post-residual, reward this placement.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 18.0;
        } else if post_residual > next_item_size {
            score -= 4.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // Next item won't fit here; slight penalty proportional to wasted opportunity.
            score += 2.0 * (next_item_size as f64 / bin_capacity as f64);
        }
    }

    // Global state: when many bins are open with high mean residual, discourage
    // fragmenting further; prefer consolidating into existing space.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64) * (mean_residual / bin_capacity as f64);
    if bin_residual != bin_capacity {
        score -= pressure * (0.5 + 0.5 * progress);
    } else {
        // New-bin candidate: penalize more when open bins have plenty of slack.
        score += 8.0 + pressure * 3.0;
        // Late in the stream, opening new bins is costlier (less time to amortize).
        score += 15.0 * progress;
    }

    // Mild reward for placing into the emptiest available bin when residuals are large.
    if bin_residual as f64 > mean_residual + 20.0 && bin_residual != bin_capacity {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_post = pr / cap;

    // Base: minimize wasted space, but with non-linear penalty on small residuals
    let mut score = pr;

    // Smooth dead-space penalty: tiny post-residuals are nearly useless
    let dead = (1.0 - norm_post).powi(6);
    score += 12.0 * dead * norm_post.max(0.0);

    // Polynomial coupling with stream progress: early on, waste is cheap;
    // late, tight packing matters more, amplified smoothly.
    let tightness = (item_size as f64 / cap).powi(2);
    score -= 8.0 * tightness * (0.5 + progress);

    // Reward filling bins that match the lookahead item smoothly
    if next_item_size > 0 {
        let diff = (pr - next_item_size as f64).abs();
        score += 5.0 * (diff / cap).powi(2);
        // Reward leaving exactly enough room for the next item
        let fit_next = ((next_item_size as f64 - pr) / cap).exp();
        score -= 6.0 * fit_next * (1.0 - progress);
    }

    // Last-chance bonus: only one bin fits, smooth reward
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - progress * 0.5);
    }

    // Slight preference to use bins with below-mean residual (consolidate)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 4.0 * dev * dev - 2.0 * dev;

    // New-bin candidate: penalize mildly so it's chosen only when nothing fits well
    if bin_residual == bin_capacity {
        score += 20.0 + 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 40.0 * fit_ratio;

    // Harmonic class: bucket post_residual by capacity fractions (dead-space classes)
    let frac = post_residual as f64 / bin_capacity as f64;
    let class = (frac * 10.0).floor(); // 0..10 harmonic class of leftover
    // Penalize leftovers in "dead" classes that few items can fill
    score += match class as i32 {
        0 => -25.0,           // perfect fit
        1 => 10.0,            // tiny unusable sliver
        2 => 20.0,            // dead space (only items <= 20 fill it)
        3 | 4 => 8.0,         // partially reusable
        5 | 6 => 2.0,         // half-bin leftovers, usually fillable
        7 => 6.0,
        8 => 12.0,
        _ => 0.0,
    };

    // Modulo coupling: post_residual divisible by common item sizes is valuable
    if post_residual > 0 {
        if post_residual % 10 == 0 { score -= 8.0; }
        else if post_residual % 5 == 0 { score -= 4.0; }
    }

    // Lookahead: if next item fits the post residual exactly, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            score -= 10.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            score += 5.0; // next item won't fit here; this bin likely closes
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: neutral-ish baseline, slightly penalized early,
    // rewarded when open bins are fragmented (high mean residual spread)
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = mean_residual / bin_capacity as f64;
        score = 55.0 - 20.0 * fragmentation + 15.0 * progress;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // big next item: fresh bin is safer
        }
    }

    // Mild pressure to consolidate when many bins are open
    score += 0.3 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps much harder.
    // A gap is "dead" if it is smaller than the smallest plausible item (1..=100
    // domain, but treat gaps < 10 as nearly worthless, and gaps < 20 as risky).
    let pr = post_residual as f64;
    if post_residual == 0 {
        // Perfect fit: strongly reward.
        score -= 60.0;
    } else if post_residual < 10 {
        // Unusable sliver: worse than a larger gap of same nominal size.
        score += 25.0 - pr * 2.0;
    } else if post_residual < 20 {
        // Risky small gap.
        score += 8.0 - pr * 0.4;
    }

    // Reward leaving room for the lookahead item (k=2 lookahead synergy).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // This bin can also take the next item: reward proportionally.
            score -= 0.5 * (next_item_size as f64);
            if post_residual == next_item_size {
                score -= 10.0; // would make next item a perfect fit too.
            }
        } else {
            // Post-residual cannot host next item: mild penalty, scaled by
            // how "wasted" the gap is relative to the next item.
            let waste = (next_item_size as f64) - pr;
            if pr > 0.0 {
                score += 0.3 * waste.min(30.0);
            }
        }
    }

    // Open-bins pressure: discourage spreading across many open bins;
    // with many open bins, prefer filling existing ones over new ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.6 * (open_bins_count as f64) * (0.5 + 0.5 * progress);

    // Mean-residual coupling: if this bin's residual is far below the mean
    // (i.e., it is one of the emptier bins), filling it is good.
    let residual_f = bin_residual as f64;
    if residual_f < mean_residual {
        score -= 0.3 * (mean_residual - residual_f).min(50.0);
    } else {
        score += 0.2 * (residual_f - mean_residual).min(50.0);
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin unless the current item
    // is large and would leave a big, still-usable gap elsewhere is impossible.
    if bin_residual == bin_capacity {
        // Base penalty for new bin; reduced when item is large (big items
        // deserve fresh space) or many bins are open (consolidation pressure).
        let item_f = item_size as f64;
        let mut new_bin_penalty = 30.0 - 0.25 * item_f;
        if fitting_bins_count > 0 {
            new_bin_penalty += 10.0; // opening new bin when alternatives exist is costly
        }
        score += new_bin_penalty.max(0.0);
    } else {
        // Reward tightness of the fit in an existing bin.
        let fill_ratio = item_size as f64 / residual_f.max(1.0);
        score -= 10.0 * fill_ratio;
    }

    // Early-stream exploration: slightly favor new bins early when stream is long.
    if progress < 0.2 && open_bins_count < 4 {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: strongly reward when the next item fits into post_residual.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Perfect 2-chain: next item exactly fills leftover.
            let slack = (post_residual - next_item_size) as f64;
            score -= 40.0 + 0.6 * (bin_capacity as f64 - slack);
            if post_residual == next_item_size {
                score -= 25.0; // perfect closure of the bin
            }
        } else {
            // Next item won't fit here: penalize proportionally to the wasted gap.
            let gap = (next_item_size - post_residual) as f64;
            score += 0.35 * gap;
        }
    } else {
        // Last item: just minimize leftover.
        score += 0.1 * post_residual as f64;
    }

    // Tight fit reward relative to current residual.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 20.0 * fill_ratio * fill_ratio;

    // Penalize bins whose residual deviates from mean (keep pool homogeneous),
    // unless it's a very tight fit.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev * (1.0 - fill_ratio);

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0 + 0.2 * item_size as f64;
    }

    // New-bin candidate: only attractive when no open bin gives a decent fit.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, discounted early in the stream or with few bins.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let mut new_bin_cost = 55.0 - 15.0 * (1.0 - progress) - 2.0 * open_bins_count as f64;
        if new_bin_cost < 20.0 { new_bin_cost = 20.0; }
        // Attractive if next item is large (future pairing potential in fresh bin).
        new_bin_cost -= 0.15 * next_item_size as f64;
        score = new_bin_cost + 0.5 * (bin_capacity as f64 - item_size as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits: quadratic penalty on leftover space.
    score += 0.6 * (post_residual as f64).powi(2) / bin_capacity as f64;

    // Perfect fit gets an extra bonus.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 10 {
        // Near-perfect fits: residual too small for any item (min size 1, but small dead space is fine).
        score -= 15.0;
    }

    // Penalize creating dead space that no future item can plausibly use:
    // if post_residual is nonzero but very small relative to typical item sizes.
    if post_residual > 0 && post_residual < 10 {
        score += 5.0; // tiny sliver, mildly wasteful but unavoidable
    }

    // Lookahead: if the next item fits exactly in post_residual, big bonus.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 10.0 * (next_item_size as f64 / post_residual.max(1) as f64);
        } else {
            // Next item won't fit here after placement; slight penalty for fragmenting.
            score += 3.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    // Its raw score is post_residual == capacity (large), so it naturally loses
    // to decent fits. But if the best existing fit is bad (high post_residual
    // relative to capacity) and open bins are plentiful, opening fresh may win.
    if bin_residual == bin_capacity {
        // Slight bias against opening new bins early in the stream.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 8.0 * (1.0 - progress);
        // But if the item is large and mean residual across bins is small,
        // opening a new bin is attractive: subtract.
        if (item_size as f64) > mean_residual {
            score -= 12.0;
        }
    }

    // Prefer placing into bins with below-average residual (balancing):
    // keeps some bins tight for future large items.
    if bin_residual != bin_capacity {
        let diff = bin_residual as f64 - mean_residual;
        score += 0.15 * diff;
    }

    // Slight preference for using larger-residual bins when item is large,
    // to conserve tight bins for small items.
    if item_size >= 60 {
        score -= 0.1 * (bin_residual as f64 - item_size as f64).max(0.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;
    let norm_item = item_size as f64 / cap;

    // Smooth polynomial coupling of post_residual with stream progress
    let poly = norm_post * (1.0 + 1.8 * progress * progress + 0.9 * progress * norm_item);

    // Penalize large dead space more than linearly (quadratic waste term)
    let waste = 0.35 * norm_post * norm_post;

    // Tight fits are rewarded, especially late in the stream
    let tight_bonus = -0.6 * (1.0 - norm_post) * (1.0 - norm_post) * (0.5 + progress);

    // Last-chance bin: strongly favor using it to avoid opening a bin
    let last_chance = if fitting_bins_count == 1 && bin_residual != bin_capacity { -1.5 } else { 0.0 };

    // New-bin candidate: penalize mildly early, more when many bins are open
    let new_bin_penalty = if bin_residual == bin_capacity { 0.5 + 0.02 * open_bins_count as f64 } else { 0.0 };

    // Lookahead: reward if next item fits the post residual
    let lookahead = if next_item_size > 0 && (post_residual as u64) >= next_item_size as u64 { -0.4 } else { 0.1 * norm_post };

    // Deviation from mean residual: prefer bins near mean to balance residuals
    let mean_coupling = 0.2 * (post - mean_residual) / cap;

    let mut score = poly + waste + tight_bonus + last_chance + new_bin_penalty + lookahead + mean_coupling;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residual mod 10 buckets capture "dead space quality"
    let pr = post_residual as i64;
    let cap = bin_capacity as i64;
    let hclass = pr % 10;

    // Penalize residuals in awkward harmonic classes (small nonzero remainders)
    if hclass > 0 && hclass < 5 {
        score += 6.0; // tiny unusable slivers
    } else if hclass >= 5 {
        score += 2.0;
    }

    // Reward perfect or near-perfect fills
    if pr == 0 {
        score -= 30.0;
    } else if pr <= 5 {
        score -= 12.0;
    }

    // Integer-division threshold: post_residual divisible by common item sizes (10..20)
    for d in [10u32, 15, 20, 25, 30, 40, 50].iter() {
        if *d > 0 && pr % (*d as i64) == 0 && pr > 0 {
            score -= 4.0;
        }
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if next_item_size as i64 == pr {
            score -= 25.0;
        } else if (next_item_size as i64 - pr).abs() <= 5 {
            score -= 10.0;
        } else if next_item_size as i64 > pr {
            score += 3.0; // next item won't fit here anyway
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 8.0;
    }

    // New-bin candidate handling: neutral-ish baseline, discourage when open bins are well-utilized
    if bin_residual == bin_capacity {
        score = 55.0 - 0.3 * (open_bins_count as f64).min(20.0);
        if next_item_size > 0 && (bin_capacity as i64 - next_item_size as i64) < 10 {
            score += 5.0; // next item is big, fresh bin fine
        }
        if mean_residual < 25.0 && open_bins_count > 0 {
            score -= 6.0; // open bins nearly full, new bin reasonable
        }
        return score;
    }

    // Fraction-of-capacity coupling: tighter fit relative to capacity is better
    score -= 20.0 * (1.0 - (post_residual as f64) / (bin_capacity as f64)) * (item_size as f64 / bin_capacity as f64);

    // Mild pressure to consolidate as stream progresses
    let progress = step_index as f64 / (total_items.max(1) as f64).max(1.0);
    score -= 5.0 * progress * (mean_residual / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let nxt = next_item_size as f64;
    let is_new_bin = bin_residual == bin_capacity;
    let progress = step_index as f64 / (total_items.max(1) as f64);
    // Fragmentation pressure: the more open bins, the more we punish sloppy placements.
    let frag = 1.0 + 0.05 * open_bins_count as f64;
    // Scarcity of residual space across all open bins: when bins are nearly full,
    // every unit of dead space is more costly.
    let scarcity = (1.0 - mean_residual / cap).clamp(0.0, 1.0);

    let mut score = post;

    if is_new_bin {
        // New-bin candidate: pay a fragmentation toll that grows with the number of
        // already-open bins, discounted early in the stream.
        score += 2.5 * open_bins_count as f64 * (0.4 + 0.6 * progress);
        // Mild bonus if the fresh residual could also host the next item.
        if nxt > 0.0 && post >= nxt {
            score -= 5.0;
        }
    } else {
        // Last-chance bin: only open bin that fits -> strongly prefer it so we
        // never open a new bin when an existing one can take the item.
        if fitting_bins_count == 1 {
            score -= 25.0 + 15.0 * (1.0 - progress);
        }
        if post == 0.0 {
            // Perfect fit: bin closes with zero waste.
            score -= 20.0;
        } else if nxt > 0.0 {
            if post >= nxt {
                // Lookahead chain: the next item can land in the leftover space.
                score -= 6.0 * (1.0 - (post - nxt) / cap);
                if post == nxt {
                    // Perfect chain: this bin will be exactly filled by the next item.
                    score -= 12.0;
                }
            } else {
                // Dead space: leftover cannot host the next item.
                score += 0.2 * (nxt - post) * frag * (0.5 + scarcity);
            }
        }
        // Tiny awkward leftovers (1..4 units) are hard to reuse: penalize.
        if post > 0.0 && post < 4.0 {
            score += (4.0 - post) * 1.5 * frag;
        }
        // With many open bins, amplify the preference for tight fits (consolidation).
        score += 0.01 * open_bins_count as f64 * post;
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score += (1.0 - fit_ratio) * 10.0;

    // 2-step lookahead: reward bins whose post_residual can host next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Slack after next item would fit: reward closeness of next item to post_residual.
            let lookahead_waste = (post_residual - next_item_size) as f64;
            score -= (next_item_size as f64 / 100.0) * 20.0;
            score += lookahead_waste * 0.5;
        } else {
            // Next item won't fit after placement: penalize, scaled by how close it was.
            let miss = (next_item_size - post_residual) as f64;
            score += miss * 0.8;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Penalize creating tiny dead space (unusable fragments) relative to mean residual.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Compare against mean residual: prefer bins with residual below mean (tighter bins),
    // mild effect to spread load.
    score -= (mean_residual - post_residual as f64) * 0.05;

    // New-bin candidate: only attractive when no open bin fits well
    // (post_residual == capacity means empty bin) or few fitting bins.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 0.0 } else { 25.0 };
        score += pressure;
        // Early in stream, opening bins is fine; later prefer consolidation.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 5.0; // fresh bin has room for lookahead
        }
    }

    // Slight penalty for spreading across many bins when consolidation is possible.
    if open_bins_count > 3 && bin_residual < bin_capacity {
        score -= (open_bins_count.min(20) as f64) * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (low post_residual).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize dead space that can never be filled by the next item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0 * (next_item_size - post_residual) as f64;
    }
    // Reward when the next item fits exactly in the post residual (perfect chaining).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 15.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    } else if fitting_bins_count > 1 {
        // When many bins fit, prefer the one with least waste.
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // Prefer filling bins that are already mostly full (low residual relative to mean).
    score += 0.35 * ((bin_residual as f64) - mean_residual);

    // Late in the stream, be more conservative: avoid opening new bins.
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses and when open bins exist.
        let mut new_bin_penalty = 25.0 + 45.0 * progress;
        if open_bins_count > 0 {
            new_bin_penalty += 10.0;
        }
        // If item is huge relative to capacity, new bin is more acceptable early.
        if (item_size as f64) > 0.7 * (bin_capacity as f64) {
            new_bin_penalty -= 15.0 * (1.0 - progress);
        }
        score += new_bin_penalty;
    } else {
        // Placing into an existing bin is rewarded more as stream progresses.
        score -= 10.0 * progress;
    }

    // Mild penalty for leaving very small unusable slivers.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post-residual, with polynomial smoothing
    let mut score = pr;

    // Non-linear coupling: post-residual quality weighted by stream progress.
    // Early on, tight fits matter less (many items to come); late, minimize waste strongly.
    let tightness = 1.0 - norm_pr * norm_pr; // high when post-residual small
    score -= tightness * (20.0 + 60.0 * progress * progress);

    // Penalize large dead space superlinearly, more so late in the stream
    score += norm_pr * norm_pr * (30.0 + 40.0 * progress);

    // Lookahead coupling: reward post-residual that can fit the next item
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64 / cap;
        score -= 15.0 * (1.0 - slack) * (0.5 + 0.5 * progress);
    } else if next_item_size > post_residual {
        // post-residual unusable for next item: penalize dead space
        score += 8.0 * norm_pr * (0.5 + progress);
    }

    // Last-chance bin: strong reward to use it instead of opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0 + 15.0 * progress;
    }

    // Mean-residual coupling: if this bin's residual is far below mean, it is an outlier;
    // filling a low-residual bin is good (consolidating waste)
    let dev = mean_residual - pr;
    score -= 0.1 * dev * (1.0 + progress);

    // Mild penalty when many bins already open and this placement leaves big residual
    score += 0.05 * (open_bins_count as f64) * norm_pr * norm_pr;

    // New-bin candidate: keep it slightly attractive early, discourage late
    if bin_residual == bin_capacity {
        score += 10.0 - 30.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residues that pair well with
    // common item sizes (multiples of 10 and small leftovers) are less wasteful.
    let pr = post_residual;
    let class_bonus: f64 = match pr {
        0 => -30.0,                       // perfect fit, strongly reward
        r if r % 10 == 0 => -12.0,        // decadal residual stays reusable
        r if r < 10 => 25.0,              // dead space under 10 is nearly useless
        r if r % 5 == 0 => -6.0,
        _ => 0.0,
    };
    score += class_bonus;

    // Integer-division thresholds: how many "typical" items still fit.
    let slots = pr / 10;
    score -= slots as f64 * 3.0;

    // Lookahead coupling: if the next item fits exactly into the post residual,
    // reward heavily; if it nearly fits, penalize slightly.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 40.0;
        } else if next_item_size <= pr {
            score -= 15.0;
        } else if pr > 0 && next_item_size - pr <= 10 {
            score += 10.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 {
        score -= 35.0;
    }

    // New-bin candidate: penalize opening a fresh bin when a reasonable fit
    // exists; the penalty shrinks when this bin would be a tight fit anyway.
    if bin_residual == bin_capacity {
        let tight = item_size >= bin_capacity * 8 / 10;
        score += if tight { 5.0 } else { 60.0 };
    }

    // Prefer denser bins early in the stream (keep large residuals flexible).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (bin_residual as f64 / bin_capacity as f64) * (1.0 - progress) * 10.0;

    // Mild pressure toward bins below the mean residual (fill emptier ones first
    // keeps tight bins free for large items).
    score += ((mean_residual - bin_residual as f64) / bin_capacity as f64) * 8.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny gaps are almost unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (1.0 - post_residual as f64 / 10.0);
    }

    // Lookahead: if the next item cannot use the leftover gap, the gap is dead space.
    if next_item_size > 0 && post_residual > 0 && (next_item_size as u32) > post_residual {
        score += 25.0 + 0.5 * post_residual as f64;
    }
    // Reward when the next item exactly chains into this bin's remainder.
    if next_item_size > 0 && post_residual > 0 && (next_item_size as u32) == post_residual {
        score -= 20.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Tightness preference: favor bins with small residual before placement.
    score += 0.3 * (bin_residual as f64 - item_size as f64).max(0.0);

    // Open-bin pressure: discourage spreading across many bins.
    score += 0.8 * open_bins_count as f64;

    // Prefer bins with residuals below the mean (denser bins).
    score += 0.2 * (mean_residual - bin_residual as f64);

    // Last-chance bonus: if this is the only bin that fits, use it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Mild preference to reuse open bins over opening a new one as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score += 15.0 + 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Prefer tight fits: reward small post_residual relative to capacity.
    score += (post_residual as f64 / bin_capacity as f64) * 30.0;

    // Aggressive 2-step lookahead: big reward if next item exactly fills post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect chaining: bin becomes exactly full
        } else if next_item_size < post_residual {
            // next item fits here too; reward proportional to leftover after chain
            let chain_left = post_residual - next_item_size;
            score -= 25.0 * (1.0 - chain_left as f64 / bin_capacity as f64);
            score += chain_left as f64 * 0.15; // still penalize chain leftovers
        } else {
            // next item won't fit here; penalize leaving awkward dead space
            if post_residual < next_item_size && post_residual > 0 {
                score += (next_item_size - post_residual) as f64 * 0.5;
            }
        }
    } else {
        // Last item: just minimize post residual.
        score -= 10.0;
    }

    // Penalize large post_residual relative to mean residual (creating outlier dead space).
    score += 0.4 * (post_residual as f64 - mean_residual).max(0.0);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: make it unattractive unless it's the only option / residual is huge.
    if bin_residual == bin_capacity {
        score += 15.0 + 0.5 * open_bins_count as f64;
        // If next item is small and could pair with current item in a fresh bin, allow it slightly.
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 10.0;
        }
    }

    // Mild late-stream conservatism: keep bins tight when nearing the end.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Penalize small dead space that nothing can use (items >= 1)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Reward tight fits: fraction of bin used by this item
    let fit_tightness = item_size as f64 / bin_residual as f64;
    score -= 20.0 * fit_tightness;

    // Lookahead: if next item fits exactly in post_residual, strong bonus
    if next_item_size > 0 && post_residual >= next_item_size {
        let lookahead_tight = (post_residual - next_item_size) as f64;
        score -= 15.0 * (1.0 - lookahead_tight / bin_capacity as f64);
    } else if next_item_size > 0 && next_item_size > post_residual {
        // next item won't fit here anyway; slight penalty for wasting space
        score += 5.0;
    }

    // Last chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when no good fit exists
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Penalize new bins more when many bins are open (prefer consolidation)
        score += 60.0 + 10.0 * open_bins_count as f64;
        // Early in stream, new bins are cheaper; late, avoid fragmentation
        score += 40.0 * progress;
        // If item nearly fills a fresh bin, opening one is reasonable
        score -= 0.5 * item_size as f64;
        // If mean residual is large, existing bins likely suffice
        score += 0.3 * mean_residual;
    }

    // Mild preference for bins below mean residual (balance residuals)
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    } else {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalized stream progress
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Normalized post-residual
    let pr_norm = post_residual as f64 / bin_capacity as f64;

    // Non-linear penalty on wasted space, growing with stream progress
    // (late in the stream, dead space is more costly since fewer items remain to fill it)
    let waste_penalty = pr_norm * pr_norm * (1.0 + 2.0 * progress);
    score += 20.0 * waste_penalty;

    // Reward tight fits (small post_residual) with a smooth saturating term
    let tight_fit = (-pr_norm * 8.0).exp();
    score -= 10.0 * tight_fit * (1.0 + progress);

    // Reward bins whose residual matches the next item size (smooth coupling)
    if next_item_size > 0 {
        let diff = (post_residual as f64 - next_item_size as f64).abs();
        let match_term = (-diff / 30.0).exp();
        score -= 8.0 * match_term;
    } else {
        // Last item: strongly prefer minimal post-residual
        score += 15.0 * pr_norm;
    }

    // Penalize last-chance bins less (if this is the only fitting bin, prefer using it)
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 6.0;
    }

    // Mild penalty for spreading across too many open bins relative to mean residual
    score += 0.05 * (open_bins_count as f64) * (mean_residual - post_residual as f64).abs() / bin_capacity as f64;

    // Discourage opening a new bin when good fits exist, unless current bin residual is small
    if bin_residual == bin_capacity {
        // New-bin candidate: score = full capacity residual plus a smooth openness bias
        score = bin_capacity as f64;
        let scarcity = 1.0 / (1.0 + fitting_bins_count as f64);
        // Open a new bin more readily when existing bins are crowded (low mean residual)
        score -= 25.0 * scarcity * (mean_residual / bin_capacity as f64);
        // Later in the stream, prefer filling existing bins (penalize new bins)
        score += 15.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Penalize opening a new bin when existing bins could absorb the item.
    if is_new_bin {
        score += 55.0;
    }

    // Last-chance bonus: if this is the only open bin that fits, strongly prefer it
    // over leaving the item to a fresh bin.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 28.0;
    }

    // Harmonic class of post_residual (dead-space granularity, modulo-style buckets).
    // Small post_residual classes are rewarded; large ones penalized.
    let class = post_residual / 10;
    score += match class {
        0 => -32.0, // near-perfect fill
        1 => -12.0,
        2 => 0.0,
        3 => 6.0,
        4 => 12.0,
        _ => 18.0,  // huge dead space
    };

    // Lookahead: reward bins whose residual can still host the next item,
    // penalize bins that will strand capacity relative to the next demand.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 14.0;
        } else {
            score += 7.0;
        }
    }

    // Coupling with fleet state: bins far below the mean residual are less urgent;
    // bins tighter than the mean are preferred targets.
    score += (mean_residual - post_residual as f64) * 0.06;

    // Mild stream-progress term: late in the stream, consolidate harder.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 4.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for any plausible
    // future item (min item size ~1, but practical "useful" gap threshold) are
    // heavily penalized. Small unusable gaps waste capacity permanently.
    let dead_threshold: f64 = 12.0;
    if (post_residual as f64) < dead_threshold {
        // Dead space: penalize proportionally to how close it is to zero gap
        score += (dead_threshold - post_residual as f64) * 3.0;
    }

    // Perfect fit reward: post_residual == 0 is ideal
    if post_residual == 0 {
        score -= 50.0;
    }

    // Open bins pressure: with many open bins, prefer filling existing ones
    // rather than spreading; penalize candidates that keep many bins open.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 / (1.0 + progress * 5.0);
    score += pressure * 0.5;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: an empty bin should only win when no open bin
    // offers a decent fit. Penalize the fresh bin mildly so tight fits win,
    // but not so much that a dead-space-creating fit beats it.
    if bin_residual == bin_capacity {
        score += 20.0 + mean_residual * 0.1;
    }

    // Lookahead: if the next item fits exactly in the post_residual, reward this
    // placement for enabling a future perfect fit.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 15.0;
    }
    // If next item would be blocked by this placement's residual, mild penalty
    if next_item_size > 0 && next_item_size > post_residual && next_item_size <= bin_residual {
        score += 5.0;
    }

    // Prefer bins whose residual is close to the item (tight fit) beyond raw
    // post_residual: coupling with mean residual to normalize.
    score += ((bin_residual as f64 - item_size as f64) - mean_residual).abs() * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Primary: aggressive 2-step lookahead matching.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Next item fits here: reward tightness of the two-item chain.
            let chain_waste = (post_residual - next_item_size) as f64;
            score -= 30.0 - chain_waste * 0.4;
        } else {
            // Next item does not fit after this placement: penalize dead space.
            score += 15.0 + (next_item_size as f64 - post_residual as f64) * 0.25;
        }
    } else {
        // Last item: prefer minimal post residual.
        score -= 10.0;
    }

    // Perfect or near-perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual <= 5 {
        score -= 12.0;
    }

    // Relative to mean residual: prefer bins tighter than average.
    score -= (mean_residual - bin_residual as f64) * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize slightly so it's chosen only for poor fits,
    // less penalized late in the stream when consolidation matters more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 35.0 - progress * 10.0;
    }

    // Many open bins: encourage filling existing ones.
    score += open_bins_count as f64 * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual relative to capacity.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 6.0 * tightness;

    // Penalize dead space that can never be used by typical items (post_residual < 10).
    if post_residual < 10 && post_residual > 0 {
        score += 12.0;
    }

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 4.0 + 0.05 * next_item_size as f64;
    }
    // Penalize if post_residual is just barely too small for the next item (waste).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 3.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Prefer bins with below-mean residual (keep large residuals for future big items).
    score += 0.15 * (mean_residual - bin_residual as f64);

    // New-bin candidate handling: neutral-ish, penalized slightly unless current bin fit is bad.
    if bin_residual == bin_capacity {
        score += 8.0;
        // Opening a new bin is fine late in the stream or when many bins are open.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 10.0 * progress;
    }

    // Mild preference for fuller bins when many bins are open (bin consolidation).
    score -= 0.02 * (bin_capacity - bin_residual) as f64 * (open_bins_count.min(20) as f64) / 20.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let fit = item_size as f64 / cap;

    // Base: reward tight fits via smooth non-linear decay of post_residual
    let mut score = norm_pr.powf(1.5) * cap;

    // Stream-progress coupling: early on tolerate larger residuals; later penalize them more
    let progress_coupling = norm_pr * (0.5 + 2.0 * progress * progress);
    score += progress_coupling * cap;

    // Penalize residuals that are just below the typical item size (dead space),
    // smooth via quadratic in normalized post_residual
    let dead = (norm_pr - 0.2).powi(2);
    score += 30.0 * dead * (1.0 - progress);

    // Reward bins that can also fit the lookahead item smoothly
    if next_item_size > 0 {
        let nxt = next_item_size as f64 / cap;
        let fits_next = (pr - nxt).max(0.0) / cap;
        score -= 25.0 * (1.0 - fits_next) * (1.0 - fits_next);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0 * (1.0 - progress);
    }

    // Mild preference for consolidating into fewer bins
    score -= (open_bins_count as f64).ln().max(0.0) * 2.0 * norm_pr;

    // New-bin candidate: keep neutral-ish baseline so it wins only over genuinely bad fits
    if bin_residual == bin_capacity {
        score = 55.0 + 25.0 * progress - 20.0 * fit;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: bins whose residual falls into
    // "small residue" classes are nearly full -> reward using them (tight fit).
    let residue_class = post_residual % 10;
    match residue_class {
        0 => score -= 12.0,                    // perfectly packed class
        1 | 2 => score -= 6.0,                 // nearly perfect
        9 => score += 4.0,                     // awkward single-unit dead space
        3 | 4 | 5 | 6 | 7 => {
            // mid-class residues: penalize proportionally to wasted fraction
            score += (post_residual as f64) * 0.15;
        }
        _ => {}
    }

    // Integer-division thresholds on post_residual: classify leftover usability
    let usable_chunks = post_residual / 10; // how many minimum-size items fit
    if usable_chunks == 0 {
        score += 15.0; // dead space bin, deprioritize
    } else if usable_chunks <= 2 {
        score -= 3.0; // nearly closed bin, good target
    }

    // Lookahead coupling: if next item fits exactly into post_residual,
    // strongly favor this bin (chain packing).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size <= post_residual {
            score -= (post_residual - next_item_size) as f64 * 0.1;
        } else {
            // next item cannot fit here; penalize leaving a residue that
            // is just barely too small for the next item
            let gap = next_item_size - post_residual;
            if gap <= 10 {
                score += gap as f64 * 0.5;
            }
        }
    } else {
        // last item: minimize leftover as much as possible
        score -= 5.0;
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate handling: only attractive when item is large or
    // no open bin is a decent fit.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let big_item = item_size as f64 > bin_capacity as f64 * 0.6;
        if big_item && open_bins_count > 0 {
            score -= 8.0 + 10.0 * progress; // prefer fresh bin for big items later in stream
        } else {
            score += 12.0; // discourage opening bins for small items
        }
    }

    // Mean-residual coupling: when open bins are generally full, prefer
    // tight fits even more.
    if mean_residual < 20.0 && !is_new_bin {
        score -= 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit: perfect placement, strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Strict dead-space avoidance: penalize small unusable gaps heavily.
    // A gap that cannot hold the smallest item (or the known next item) is dead space.
    let min_item = 1u32;
    if post_residual > 0 && post_residual < min_item + item_size / 4 {
        score += 500.0;
    }
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 120.0; // gap too small for the lookahead item
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 30.0; // gap remains useful for next item
    }

    // Reward filling large residual bins (consolidation).
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 80.0 * fill_ratio;

    // Open-bin pressure: prefer already-open bins when many are open,
    // but allow new bins when few exist and fit is poor.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += open_bins_count as f64 * (2.0 + 6.0 * progress);

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 400.0;
    }

    // Mean residual coupling: if this bin is far below mean residual,
    // using it evens out residuals (good); penalize raiding the fullest bin.
    if (bin_residual as f64) < mean_residual - 20.0 {
        score += 40.0;
    } else if (bin_residual as f64) > mean_residual + 20.0 {
        score -= 20.0;
    }

    // New-bin candidate bias: opening a new bin is only attractive when
    // this is an early step or the item is huge relative to residual.
    if bin_residual == bin_capacity {
        let poor_fit = fill_ratio < 0.5;
        if poor_fit && open_bins_count > 0 && progress < 0.9 {
            score += 150.0; // discourage wasteful new bins
        } else {
            score += 10.0; // slight default bias toward existing bins
        }
        if item_size >= 80 {
            score -= 60.0; // big items may deserve fresh bins
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 200.0;
    }

    // 2-step lookahead: ideal if post_residual exactly matches next item
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 150.0;
        } else if post_residual >= next_item_size {
            // residual can host the next item; mild reward proportional to tightness
            let slack = (post_residual - next_item_size) as f64;
            score -= 40.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // dead space relative to next item: penalize proportionally
            let waste = (next_item_size - post_residual) as f64;
            score += 2.0 * waste;
        }
    }

    // Relative to mean residual: prefer bins tighter than average
    score += 0.5 * (bin_residual as f64 - mean_residual);

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 80.0;
    }

    // Penalize the brand-new empty bin candidate mildly so it wins only when
    // all open bins leave large unusable residuals.
    if bin_residual == bin_capacity {
        score += 60.0;
    }

    // Late in the stream, prefer closing out bins (reduce fragmentation)
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 10.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress ratio: later in the stream, waste becomes more costly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Perfect-fit lookahead reward: next item exactly fills the leftover space.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 40.0 + 20.0 * progress;
    }
    // Next item can still fit here: mild reward proportional to how well it fits.
    else if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 12.0 - slack * 0.15;
    }
    // Next item cannot follow into this bin: penalize stranded residual, scaled by progress.
    else if next_item_size > 0 && next_item_size > post_residual {
        score += 0.10 * post_residual as f64 * (0.5 + progress);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0 + 15.0 * progress;
    }

    // Prefer bins that are already well-filled relative to the fleet average.
    let residual_gap = mean_residual - bin_residual as f64;
    score += residual_gap * 0.25;

    // Penalize creating tiny unusable slivers (dead space below the smallest item).
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Brand-new empty bin candidate: neutral baseline, chosen only when no open bin
    // offers a decent fit. Better than a bin with huge stranded residual,
    // worse than any reasonable reuse.
    if bin_residual == bin_capacity {
        score = 55.0 - 10.0 * progress + (open_bins_count as f64).sqrt() * 2.0;
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 5.0; // pair fits cleanly in a fresh bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let pr_norm = pr / cap;
    let item_norm = item_size as f64 / cap;
    let mean_norm = mean_residual / cap;

    // Base: prefer small post-residual, with non-linear tightening
    let mut score = pr * (1.0 + 0.35 * pr_norm * pr_norm);

    // Smooth polynomial coupling with stream progress:
    // later in the stream -> punish residual waste more aggressively
    let progress_coupling = pr_norm * (0.5 + 1.5 * progress * progress);
    score += 40.0 * progress_coupling;

    // Dead-space penalty: quadratic in residual relative to mean
    let dead = (pr_norm - mean_norm).abs();
    score += 25.0 * dead * dead * (0.3 + 0.7 * progress);

    // Lookahead: reward residual that can fit the next item (smoothly)
    if next_item_size > 0 {
        let nxt = next_item_size as f64 / cap;
        let fits_next = (pr_norm - nxt).max(0.0);
        let exact = 1.0 - (pr_norm - nxt).abs();
        score -= 30.0 * exact * exact * fits_next.max(0.0).min(1.0);
        // penalize residuals slightly too small for next item
        let gap = (nxt - pr_norm).max(0.0);
        score += 20.0 * gap * gap;
    }

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 60.0 * (1.0 - pr_norm);
    } else {
        // mild penalty for spreading across many bins
        score += 2.0 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // Encourage tight packing when many bins are open
    score += 5.0 * (open_bins_count as f64).sqrt() * pr_norm;

    // New-bin candidate: make it unattractive unless residual is large
    if bin_residual == bin_capacity {
        score += 35.0 * (1.0 - progress) + 20.0 * item_norm;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit is perfect
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: tiny slivers are dead space
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    if post_residual > 0 && post_residual <= 10 {
        score += 60.0; // unusable sliver penalty (items >= 1 but typically larger)
    } else if post_residual <= 20 {
        score += 25.0;
    }

    // Modulo-10 harmonic class: residuals that are multiples of 10 pair well with
    // typical item sizes; reward them mildly.
    if post_residual % 10 == 0 {
        score -= 8.0;
    }

    // Lookahead: if next item fits exactly in post_residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 400.0;
        } else if next_item_size < post_residual {
            let npr = post_residual - next_item_size;
            score -= 30.0 - (npr as f64) * 0.3; // prefer chains leaving small-but-usable residue
        } else {
            score += 15.0; // next item won't fit here anyway
        }
    }

    // Last chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 200.0;
    }

    // New-bin candidate: penalize so it's only chosen when no open bin fits well
    if bin_residual == bin_capacity {
        score += 120.0 + mean_residual * 0.5;
    }

    // Prefer filling bins that are already relatively full (tight packing)
    let fullness = 1.0 - (bin_residual as f64) / cap;
    score -= fullness * 20.0;

    // Mild preference for using bins when many are open (consolidation)
    score -= (open_bins_count as f64) * 0.5;

    // Progress: early on, be more willing to open bins; later, pack tightly
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 10.0;

    // Mean residual coupling: if this bin is below mean residual, it's a good closer
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize unusable small gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 12.0;
    }

    // Reward near-perfect fills.
    if post_residual == 0 {
        score -= 80.0;
    }

    // Open bins pressure: discourage opening new bins when many are open.
    if bin_residual == bin_capacity {
        score += 25.0 + open_bins_count as f64 * 3.0;
    } else {
        score -= 3.0;
    }

    // Last-chance bonus: only one bin can fit this item.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: favor bins whose residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 8.0;
    }

    // Mean residual coupling: prefer bins near the mean residual.
    score += (bin_residual as f64 - mean_residual).abs() * 0.2;

    // Slight progression pressure to consolidate early.
    score -= (step_index as f64 / total_items.max(1) as f64) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fits are excellent: reward small post_residual aggressively.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual <= 5 {
        score -= 12.0;
    } else if post_residual <= 10 {
        score -= 6.0;
    }

    // 2-step lookahead: if the next item fits exactly into post_residual,
    // this bin is a perfect pipeline target.
    if next_item_size > 0 {
        if post_residual as u32 == next_item_size {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            // Next item fits, but leaves some waste afterwards.
            let leftover = post_residual as f64 - next_item_size as f64;
            score -= 8.0 - leftover * 0.15;
        } else {
            // Next item will NOT fit here: this bin becomes dead space
            // for the next step; penalize proportionally to how close it is.
            let miss = next_item_size as f64 - post_residual as f64;
            if miss <= 10.0 {
                score += 6.0 + miss * 0.5;
            } else {
                score += 3.0;
            }
        }
    }

    // Relative to mean residual: placing into a bin with residual below
    // average tightens the spread; placing into a huge bin wastes it.
    let mr = if mean_residual.is_finite() { mean_residual } else { bin_capacity as f64 };
    if (bin_residual as f64) < mr {
        score -= 4.0;
    } else {
        score += ((bin_residual as f64) - mr) * 0.05;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when no open bin is a decent fit.
    if bin_residual == bin_capacity {
        let bad_fit = fitting_bins_count == 0
            || (post_residual as f64 > 20.0 && fitting_bins_count <= 1);
        if bad_fit {
            score -= 10.0;
        } else {
            // Reuse existing bins when possible.
            score += 12.0;
        }
    }

    // Late in the stream, favor closing bins tightly (less fragmentation).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 2.0 * (post_residual as f64 / bin_capacity as f64);

    // Mild penalty for many open bins to encourage consolidation.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 10 {
        score -= 80.0;
    }

    // Penalize dead space that is too small for the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 400.0;
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 60.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit here; slight penalty for wasting large residual.
            score += 0.05 * (post_residual as f64);
        }
    }

    // Last-chance bonus: only bin that fits the item.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate handling: prefer new bin only when fits are poor.
    if bin_residual == bin_capacity {
        let tight = post_residual as f64 / bin_capacity as f64;
        if post_residual > 20 && fitting_bins_count > 0 {
            // Opening a new bin wastes (capacity - item) anyway; discourage unless bad fits.
            score += 120.0 + 50.0 * (1.0 - tight);
        } else if post_residual <= 20 {
            score -= 50.0;
        }
        // Early in stream, new bins are cheap.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 80.0 * (1.0 - progress);
    }

    // Prefer fuller bins relative to global mean residual.
    if (bin_residual as f64) < mean_residual {
        score -= 20.0;
    } else {
        score += 10.0;
    }

    // Spread across many open bins: encourage consolidation.
    if open_bins_count > 4 {
        score += 0.3 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: prefer small post_residual (tight fit), with non-linear shaping
    let mut score = post;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // early on, waste is cheap (many items left to fill gaps);
    // late, waste becomes progressively more costly.
    let waste_penalty = (post / cap).powi(2) * (1.0 + 3.0 * progress * progress) * 30.0;
    score += waste_penalty;

    // Cubic term: heavily penalize near-full-but-unusable residuals that
    // emerge as the stream matures (dead space amplification).
    let dead = (post / cap).powi(3) * progress * 80.0;
    score += dead;

    // Reward bins whose residual matches the next item's need (lookahead fit)
    if next_item_size > 0 {
        let gap = (post_residual as f64 - next_item_size as f64).abs();
        let match_bonus = (1.0 - gap / cap).max(0.0);
        score -= match_bonus * 15.0 * (0.5 + progress);
    }

    // Last-chance bin: strong bonus to use it rather than open a new one
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 + progress);
    }

    // Mild preference for bins below the mean residual (consolidate emptier space)
    score -= (mean_residual - post) * 0.05;

    // Slight pressure against accumulating many open bins early
    score += open_bins_count as f64 * 0.02 * (1.0 - progress);

    // New-bin candidate (empty bin): make it attractive only for large items
    // or when the fit is very loose; otherwise prefer existing bins.
    if bin_residual == bin_capacity {
        let tightness = item_size as f64 / cap;
        score += 12.0 - 25.0 * tightness * tightness;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "coarse" residue classes (multiples of capacity fractions) are more reusable.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Fractional position within capacity (0..1)
    let frac = post / cap;

    // Harmonic tier: which capacity fraction the residual is closest to.
    // Residuals near 50, 33, 25, 20 ... are "harmonic" (easy to fill later).
    let harmonics = [0.5f64, 1.0 / 3.0, 0.25, 0.2, 1.0 / 6.0];
    let mut h_bonus = 0.0f64;
    for (i, h) in harmonics.iter().enumerate() {
        let d = (frac - h).abs();
        if d < 0.04 {
            h_bonus += (5.0 - i as f64) * (1.0 - d / 0.04);
        }
    }
    score -= h_bonus;

    // Integer-division threshold: post_residual divisible by small integers
    // implies modular alignment with typical item granularities.
    let pr = post_residual;
    if pr > 0 {
        if pr % 10 == 0 { score -= 3.0; }
        else if pr % 5 == 0 { score -= 1.5; }
        else { score += 2.0; }
    }

    // Dead-space penalty: residuals too small for the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead coupling: reward residuals that can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
            // extra reward if post_residual - next_item_size stays usable
            let r2 = post_residual - next_item_size;
            if r2 >= 10 { score -= 4.0; }
        } else {
            score += 6.0;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // the stream is early or open bins are nearly full on average.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let tight = mean_residual / cap;
        // Penalize new bins more as the stream progresses and bins get full.
        score += 15.0 + 40.0 * progress - 20.0 * tight;
        if next_item_size > 0 && next_item_size > bin_residual {
            score -= 10.0; // new bin guaranteed to fit next item
        }
    }

    // Mild preference for filling fuller bins (waste minimization).
    score -= 0.05 * (item_size as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps are the worst outcome.
    if post_residual > 0 {
        let dead = post_residual as f64;
        // Penalize gaps too small for typical future items (below min item size).
        if dead < 10.0 {
            score += 40.0 * (10.0 - dead) / 10.0;
        }
        // Smooth quadratic penalty on small residual gaps.
        score += 0.05 * dead * dead / 10.0;
    } else {
        // Perfect fit is highly desirable.
        score -= 30.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward this bin.
    if next_item_size > 0 {
        let nd = next_item_size as f64;
        let pr = post_residual as f64;
        if pr >= nd {
            let gap = pr - nd;
            // Next item leaves a small remainder -> good chain fit.
            score -= 12.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // Post-residual cannot host next item: mild penalty scaled by dead space.
            score += 4.0 * (nd - pr).min(30.0) / 30.0;
        }
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones
    // (avoid fragmentation); with few bins, allow spreading.
    let bin_pressure = (open_bins_count as f64).ln().max(0.0);
    score += 6.0 * bin_pressure * (post_residual as f64 / bin_capacity as f64);

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when current residuals are poor fits
    // or item is large relative to mean residual.
    if bin_residual == bin_capacity {
        // Base handicap so new bins aren't opened frivolously.
        score += 25.0;
        // But if the item barely fits anywhere (large item, tight residuals),
        // a fresh bin is better than a terrible squeeze.
        let fit_ratio = item_size as f64 / bin_residual as f64;
        if fit_ratio > 0.85 || (next_item_size > 0 && (post_residual as f64) < next_item_size as f64) {
            score -= 35.0;
        }
        // Scale handicap down as stream progresses (consolidation phase).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * progress;
    }

    // Mean residual coupling: when average residual is small, hoard space.
    if (mean_residual - post_residual as f64).abs() > bin_capacity as f64 * 0.5 {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

