            score -= 40.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item won't fit here: penalize dead space creation
            let waste = (next_item_size - post_residual) as f64;
            score += 0.5 * waste;
        }
    }

    // Penalize residual far below mean residual (creating unusable small gap).
    let gap = (post_residual as f64 - mean_residual).abs();
    score += 0.15 * gap;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Prefer tight fits (small post_residual) even more aggressively.
    score += (bin_capacity as f64 / (post_residual as f64 + 5.0)) * 0.0;

    // New-bin candidate: penalize opening a new bin unless current fit is terrible
    // and next item pairs better with a fresh bin.
    if bin_residual == bin_capacity {
        score += 45.0;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            if next_item_size as f64 >= mean_residual.max(1.0) {
                score -= 50.0; // fresh bin better matches next item
            }
        }
        if post_residual as f64 > mean_residual + 10.0 {
            score += 10.0;
        }
    }

    // Late in stream, be more conservative with new bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score += 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: strongly prefer bins where the item nearly fills the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio;

    // Penalize leaving dead space that is too small for typical items.
    if post_residual > 0 && post_residual < 10 {
        score -= 15.0; // near-perfect fill
    }

    // Lookahead: if the next item could still fit in the post residual, reward preserving it.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack_use = next_item_size as f64 / post_residual as f64;
            score -= 10.0 * slack_use;
        } else {
            // Post residual can't hold the next item: penalize proportionally to wasted capacity.
            score += 5.0 * (1.0 - post_residual as f64 / next_item_size.max(1) as f64);
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when existing
    // residuals are large (poor fits available) and the stream is early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let avg_waste = mean_residual;
        // Penalize new bins more as mean residual grows (we should consolidate).
        score += 20.0 + avg_waste * 0.3;
        // Slightly more willing to open bins late in the stream (less future to plan for).
        score -= 10.0 * progress;
        // If many bins are open, prefer reusing one of them instead.
        score += (open_bins_count as f64).min(10.0) * 1.5;
        // If the item is huge, a fresh bin is actually a great fit.
        if item_size >= bin_capacity * 8 / 10 {
            score -= 35.0;
        }
        return score;
    }

    // Mild preference for bins whose residual deviates favorably from the mean
    // (consolidating into already-tight bins keeps looser bins flexible).
    let dev = bin_residual as f64 - mean_residual;
    if dev < 0.0 {
        score += dev * 0.05; // tighter-than-average bins get small penalty reduction... actually reward tight bins:
        score -= 0.05 * (-dev);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post residual, weighted by smooth progress-dependent polynomial
    let mut w = 1.0 + 0.8 * progress - 0.5 * progress * progress;
    let mut score = w * pr;

    // Non-linear penalty on dead space: small post_residual is bad unless near-zero
    let dead = (norm_pr * (1.0 - norm_pr)).max(0.0);
    score -= 30.0 * dead * (1.0 - progress);

    // Strong reward for near-perfect fits (quartic dip near zero residual)
    let tight = (1.0 - norm_pr).clamp(0.0, 1.0);
    score -= 25.0 * tight * tight * tight * tight;

    // Lookahead coupling: reward if next item fits the post residual (smooth kernel)
    if next_item_size > 0 {
        let diff = pr - next_item_size as f64;
        let k = (-diff * diff / 400.0).exp();
        score -= 20.0 * k;
        // penalize wasting space when next item is large
        score += 5.0 * (next_item_size as f64 / cap) * (1.0 - k);
    }

    // Last-chance bonus: only fitting bin
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * progress;
    }

    // Mild penalty for spreading across many open bins
    score += 0.5 * (open_bins_count as f64).ln().max(0.0) * norm_pr;

    // Deviation from mean residual: prefer bins with less residual than average
    score += 3.0 * (pr - mean_residual) / cap;

    // New-bin candidate: encourage opening fresh bin when post residual would be large
    if bin_residual == bin_capacity {
        score += 8.0 * (1.0 - (item_size as f64 / cap));
        score -= 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let pr = post_residual;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Perfect fit: strongly reward
    if pr == 0 {
        score -= 60.0;
    }

    // Harmonic classes: bucket post_residual by modulo-10 residue.
    // Residuals that are multiples of 10 are "harmonically aligned" with
    // common item sizes; tiny residues (1..3) are dead space.
    let class = pr % 10;
    match class {
        0 => score -= 10.0,                      // aligned residue, reusable
        1 | 2 | 3 => score += 6.0,               // dead-space risk
        4 | 5 | 6 => {}                          // neutral
        _ => score += 2.0,                       // mildly awkward
    }

    // Integer-division threshold: residual large enough to host another
    // typical item (>= 20) is valuable; sub-20 residues are near-dead.
    if pr >= 20 {
        score -= 4.0;
    } else if pr > 0 {
        score += (20 - pr) as f64 * 0.5;
    }

    // Lookahead pairing (k=2): if the next item fits the post-residual,
    // this placement chains nicely.
    if next_item_size > 0 {
        if next_item_size <= pr {
            score -= 12.0;
            // extra reward for exact modulo-class match with next item
            if pr % 10 == next_item_size % 10 {
                score -= 4.0;
            }
        } else {
            // next item won't fit here; penalize by the overflow amount
            score += ((next_item_size - pr) as f64).min(25.0);
        }
    }

    // Last-chance bin: if this is the only open bin that fits, strongly
    // prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling (bin_residual == bin_capacity).
    if bin_residual == bin_capacity {
        if fitting_bins_count <= 1 {
            // No open bin can host this item: opening a new bin is mandatory.
            score -= 100.0;
        } else {
            // An open bin fits; opening a new bin wastes capacity.
            // Penalty grows with stream progress and open-bin count.
            score += 20.0 + 0.15 * open_bins_count as f64 + 10.0 * progress;
        }
    }

    // Reward packing larger items into fuller bins (tightness coupling).
    score -= (item_size as f64 / bin_capacity as f64) * 10.0;

    // Mild pull toward bins near the mean residual (balance residuals).
    score += ((post_residual as f64 - mean_residual) / 10.0).abs().min(5.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that no plausible item (min size 10)
    // can use are pure waste -> heavy penalty.
    if post_residual < 10 && post_residual > 0 {
        score += 60.0;
    } else if post_residual < 20 {
        // small gap that only tiny items can fill: moderate penalty
        score += 25.0;
    }

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // Lookahead: if the next item fits exactly into the post-residual,
    // reward this placement (chain packing).
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack < 10.0 {
            score -= 40.0;
        } else {
            score -= 10.0;
        }
    } else if next_item_size > 0 && next_item_size > post_residual && post_residual < 10 {
        // dead space that next item can't use either
        score += 30.0;
    }

    // Open-bin pressure: discourage spreading across many bins unless the
    // fit is tight; the fuller the bin relative to capacity, the better.
    let tightness = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= tightness * 40.0;

    // Pressure grows with number of open bins: prefer compacting into
    // existing bins when many are open.
    score += (open_bins_count as f64) * 2.0;

    // Prefer bins whose residual deviates favorably from the mean residual:
    // placing into a below-average-residual bin compacts the stream.
    score += (mean_residual - bin_residual as f64) * 0.5;

    // Late in the stream, be more conservative: avoid creating new dead space.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * progress;
    }

    // New-bin candidate (empty bin): make it unattractive unless the item
    // cannot fit well anywhere else. An empty bin has residual == capacity.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, softened when few bins are open
        // (early stream) or when the item is large relative to capacity.
        let large_item_bonus = item_size as f64 / bin_capacity as f64; // big items waste less in a fresh bin
        let mut new_bin_cost = 120.0 - large_item_bonus * 60.0;
        // If no existing bin fits (this is the only candidate), the cost is
        // effectively irrelevant, but keep it competitive.
        if fitting_bins_count == 0 {
            new_bin_cost -= 200.0;
        }
        // Late in the stream, opening new bins is riskier: slight extra cost.
        new_bin_cost += 20.0 * progress;
        score = new_bin_cost + post_residual as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward perfect fits heavily.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: if the next item fits exactly into post_residual, strong reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 400.0;
        } else if post_residual >= next_item_size {
            // Next item fits: penalize leftover after the lookahead placement (chained waste).
            let chained_waste = post_residual - next_item_size;
            score -= 50.0;
            score += chained_waste as f64 * 0.8;
        } else {
            // Next item does NOT fit: leftover dead space is risky.
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.5;
        }
    }

    // Relative-to-mean residual coupling: prefer bins tighter than the mean.
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Last-chance bonus: only this bin can fit the item.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 200.0;
    }

    // Penalize opening a new bin when existing bins could hold the item reasonably well.
    if bin_residual == bin_capacity {
        score += 120.0;
        // Allow new bin if current item is large and fits poorly anywhere.
        if item_size > bin_capacity / 2 {
            score -= 60.0;
        }
    }

    // Mild stream-progression pressure: as stream nears end, prefer tight packing.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (low post-residual).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that is too small to be useful later:
    // residuals below the smallest plausible item are nearly worthless.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual < 20 {
        score += 8.0;
    }

    // Exact fit is perfect.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Lookahead: reward residuals that can still hold the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0;
        } else {
            // Wasting the bin for the known next item: penalize.
            score += 5.0;
        }
        // Bonus if the residual can hold a useful combination of future items.
        let useful = (post_residual as f64) / (next_item_size as f64);
        if useful >= 2.0 {
            score -= 4.0;
        }
    }

    // Penalize opening new bins when many bins are already open and fragmented.
    let progress = (step_index as f64) / (total_items.max(1) as f64);
    score += 0.15 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Prefer bins whose residual is close to the mean (balanced usage),
    // unless a tight fit overrides.
    let dev = ((bin_residual as f64) - mean_residual).abs();
    score += 0.05 * dev;

    // New-bin candidate: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 15.0;
        // If this bin is the last fitting option, opening a new bin is cheap.
        if fitting_bins_count == 0 {
            score -= 60.0;
        } else if post_residual as f64 > mean_residual * 0.5 {
            // Existing fit is poor (leaves big residual): allow a new bin.
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr as f64;

    // Smooth non-linear coupling: penalize large post_residual more as stream progresses
    let poly = norm_pr * norm_pr * (0.5 + progress) + norm_pr * progress * progress;
    score += 40.0 * poly;

    // Reward tight fits smoothly (small post_residual gets bonus, stronger late)
    score -= (1.0 - norm_pr) * (1.0 - norm_pr) * (10.0 + 30.0 * progress);

    // Penalize when next item cannot use the remaining space (smooth quadratic in gap)
    if next_item_size > 0 {
        let gap = (next_item_size as f64 - pr).max(0.0);
        let gap_n = gap / cap;
        score += 25.0 * gap_n * gap_n * (1.0 + progress);
        // Reward if next item fits perfectly into post_residual
        let fit_diff = (pr - next_item_size as f64).abs() / cap;
        score -= 15.0 * (1.0 - fit_diff.min(1.0)) * (1.0 - fit_diff.min(1.0)) * (0.5 + progress);
    }

    // Last-chance bin: reward using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 20.0 * (1.0 - norm_pr) + 10.0 * progress;
    }

    // Slight preference for bins deviating from mean residual (balance)
    let dev = (pr - mean_residual) / cap;
    score += 5.0 * dev * dev;

    // New-bin candidate: neutral-ish baseline, penalized mildly when good fits exist
    if bin_residual == bin_capacity {
        score += 8.0 + 12.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: perfect fits (0) are ideal,
    // tiny residuals (< 10) are dead space.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual < 10 {
        score += 60.0 * (10 - post_residual) as f64;
    }

    // Classify post_residual by harmonic band using integer division.
    let band = post_residual / 10; // 0..10
    score += band as f64 * 2.0;

    // Modulo-10 harmonic: residuals divisible by 10 leave "clean" slots
    // that typical item sizes can reuse; odd/prime-ish residuals are worse.
    let r10 = post_residual % 10;
    if r10 == 0 {
        score -= 15.0;
    } else if r10 >= 7 {
        score += 10.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post
    // residual, strongly favor this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 400.0;
        } else if next_item_size < post_residual {
            let gap = post_residual - next_item_size;
            score += gap as f64 * 0.5;
            // Harmonic bonus: next item leaves a multiple-of-10 remainder
            if (post_residual - next_item_size) % 10 == 0 {
                score -= 25.0;
            }
        } else {
            // next item cannot follow here; slight penalty scaled by overflow
            score += (next_item_size - post_residual) as f64 * 0.2;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid forcing a
    // new bin unless the fit is truly terrible.
    if fitting_bins_count == 1 {
        score -= 80.0;
    }

    // Empty new-bin candidate: prefer it only when it creates a large,
    // clean residual for future items late in the stream.
    if bin_residual == bin_capacity {
        // New bin baseline: post_residual == capacity; keep it competitive
        // but bias toward reusing open bins with good fits.
        score += 30.0;
        let progress = step_index as f64 / total_items.max(1) as f64;
        if progress > 0.8 && next_item_size >= 50 {
            score -= 20.0;
        }
        // penalize opening bins when many are already open with slack
        if mean_residual > 40.0 && open_bins_count > 2 {
            score += 40.0;
        }
    }

    // Spread-aware penalty: creating residuals far from the mean wastes
    // uniformity of open capacity.
    let diff = (post_residual as f64 - mean_residual).abs();
    score += diff * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Post-residual too small for any plausible future item (1..=100 range)
    // means the leftover space is dead unless exactly filled later.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (1.0 - post_residual as f64 / 10.0);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bins pressure: when many bins are open, prefer reusing existing bins
    // over opening new ones; when few bins are open, new bins are cheaper.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline plus pressure penalty, minus lookahead bonus.
        score += 15.0 + 8.0 * pressure;
        if next_item_size > 0 && next_item_size <= bin_residual {
            score -= 5.0;
        }
    } else {
        // Existing bin: reward reuse, scaled by pressure.
        score -= 6.0 + 4.0 * pressure;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size > post_residual {
            // Next item won't fit here anyway; slight penalty for wasting space.
            score += 3.0;
        }
    }

    // Mean-residual coupling: prefer bins whose residual is below the mean
    // (consolidating space into few bins leaves other bins larger).
    if bin_residual < bin_capacity {
        let diff = mean_residual - bin_residual as f64;
        if diff > 0.0 {
            score -= diff * 0.3;
        } else {
            score += (-diff) * 0.15;
        }
    }

    // Slight late-stream tightening: as the stream progresses, be pickier
    // about dead space since fewer items remain to fill gaps.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 5.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual), but not unusably tight.
    score -= 0.5 * (bin_residual as f64 - item_size as f64).abs().recip().max(0.0);

    // Dead-space penalty: post_residual too small to fit typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // 2-step lookahead: reward exact match of post_residual with next item.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let pr = post_residual as f64;
        if post_residual >= next_item_size {
            let diff = pr - nx;
            score -= 8.0 * (-diff / 20.0).exp(); // near-exact match strongly rewarded
        } else {
            // next item won't fit here: penalize by shortfall
            score += (nx - pr).min(40.0);
        }
    }

    // Compare against mean residual: bins tighter than average are good targets.
    score += 0.3 * (post_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate: only attractive late in the stream or when few bins fit.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let pressure = if fitting_bins_count == 0 { 0.0 } else { (fitting_bins_count as f64).recip() };
        score += 20.0 * (1.0 - pressure) * (1.0 - 0.5 * progress) + 5.0;
    }

    // Early stream: mild preference to spread load across bins (balance residuals).
    if open_bins_count > 0 {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += (1.0 - progress) * 0.1 * (post_residual as f64 - mean_residual).abs();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize small post_residual.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 3.0 * tightness * tightness;

    // Penalize dead space that is too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual < 20 {
        score += 6.0;
    }

    // Lookahead: bonus if next item fits exactly in the post residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0;
        } else if next_item_size <= post_residual {
            let leftover = post_residual - next_item_size;
            if leftover < 10 {
                score -= 12.0;
            } else {
                score -= 4.0;
            }
        } else {
            // Next item cannot use this bin's remainder; slight penalty for
            // leaving a gap that blocks the known successor.
            let gap = (next_item_size - post_residual) as f64;
            score += 0.15 * gap;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Global pressure: many open bins with high mean residual -> prefer
    // filling existing bins rather than spreading.
    let pressure = mean_residual / (bin_capacity as f64);
    if pressure > 0.5 {
        score += 2.0 * (pressure - 0.5);
    }

    // Time horizon: early in the stream, keep bins flexible (mild penalty for
    // very small remainders); late in the stream, prioritize closing bins out.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if progress > 0.7 {
        score -= 5.0 * progress * tightness;
    } else if post_residual > 0 && post_residual < 15 {
        score += 3.0 * (1.0 - progress);
    }

    // Perfect fit gets a decisive reward.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Slight aversion to opening new bins when many bins are already open.
    if bin_residual == bin_capacity {
        score += 1.0 + 0.05 * open_bins_count as f64;
        // But if nothing else fits well (many fitting bins means competition),
        // new bin stays penalized; keep it moderate.
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let post_norm = post / cap;
    let fit_ratio = item_size as f64 / cap;

    // Base: penalize large post residual, but non-linearly (quadratic coupling).
    let mut score = post * (1.0 + post_norm * post_norm);

    // Smooth stream-progress coupling: early on, waste matters less; late, tighten.
    let progress_weight = 0.5 + 2.0 * progress * (1.0 - 0.5 * progress);
    score += progress_weight * post * post_norm;

    // Reward tight fits (small post residual) with smooth decay.
    score -= 40.0 * (-3.0 * post_norm).exp();

    // Lookahead: if next item fits into the post residual, reward this bin.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let slack = (post - nxt) / cap;
            score -= 15.0 * (1.0 - slack) * (1.0 - 0.5 * progress);
        } else {
            // Next item won't fit here: mild penalty scaled by overflow.
            let overflow = (nxt - post) / cap;
            score += 10.0 * overflow * overflow;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0 + 15.0 * (1.0 - fit_ratio);
    } else if fitting_bins_count > 1 {
        // Slight penalty for hogging when alternatives exist, coupled with fill.
        score += 3.0 * fit_ratio * (fitting_bins_count as f64).ln();
    }

    // Mean-residual coupling: prefer bins deviating smoothly from the mean.
    let dev = (post - mean_residual) / cap;
    score += 8.0 * dev * dev - 5.0 * dev * (1.0 - progress);

    // New-bin candidate: make it attractive only when it genuinely helps
    // (large item, poor fits available, late stream).
    if bin_residual == bin_capacity {
        let new_bin_bonus = 60.0 * fit_ratio * (0.5 + 0.5 * progress);
        score = cap * 2.0 - new_bin_bonus;
        if fitting_bins_count <= 1 {
            score -= 30.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: how "usable" the leftover space is.
    // Residuals divisible by common item sizes (small classes) are more reusable.
    let cap = bin_capacity as f64;
    let pr = post_residual;
    let prf = pr as f64;

    // Perfect fit is heavily rewarded.
    if pr == 0 {
        score -= 1000.0;
        return score;
    }

    // Class bonus: residual that is a multiple of 10 (typical item granularity)
    // or leaves room for the lookahead item.
    if pr % 10 == 0 {
        score -= 20.0;
    }
    if pr % 25 == 0 {
        score -= 10.0;
    }

    // Lookahead coupling: reward if next item fits exactly or well in post_residual.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 300.0;
        } else if next_item_size < pr {
            let slack = (pr - next_item_size) as f64;
            // prefer tight lookahead fits; penalize large leftover slack
            score -= 40.0 * (1.0 - slack / cap);
        } else {
            // next item won't fit here after placement: penalize proportionally
            score += 0.15 * (next_item_size - pr) as f64;
        }
    }

    // Dead-space penalty: post residual too small to hold any item (1..100 range,
    // but treat < 12 as effectively dead unless zero).
    if pr < 12 {
        score += 25.0;
    }

    // Fraction-of-capacity thresholds: bins filled past 75% are "committed";
    // favor continuing to pack them tight.
    let fill_frac = 1.0 - prf / cap;
    if fill_frac > 0.75 {
        score -= 15.0;
    } else if fill_frac < 0.25 {
        // placing into a nearly-empty bin wastes its flexibility
        score += 10.0;
    }

    // Last-chance logic: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // existing residuals are fragmented or the item fits nothing well.
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        score += 30.0;
        // more attractive when open bins are fragmented (mean residual low
        // relative to item) or few bins fit
        if fitting_bins_count <= 1 {
            score -= 50.0;
        }
        if mean_residual < item_size as f64 {
            score -= 20.0;
        }
        // late in the stream, prefer consolidation into existing bins
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 40.0 * progress;
    }

    // Slight preference for bins whose residual is close to the mean
    // (keeps the bin set homogeneous and reusable).
    let dev = (prf - mean_residual).abs();
    score += 0.05 * dev;

    // Mild tie-break favoring earlier bins as open_bins_count grows (stability).
    score += 0.01 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for the next item (or the
    // minimum plausible item) are "dead" — penalize them sharply.
    let min_item = if next_item_size > 0 { next_item_size.min(80) } else { 10 };
    if post_residual > 0 && post_residual < min_item {
        score += 60.0 + (min_item - post_residual) as f64 * 2.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Tight fit reward: residual nearly consumed.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 30.0;

    // Lookahead: if the post-residual can still host the next item, reward it;
    // if it cannot, penalize proportionally to next item size.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 10.0;
        } else {
            score += next_item_size as f64 * 0.4;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones and
    // prefer consolidating into existing space.
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline slightly above using an existing bin,
        // rising with open_bins_count so we close bins out first.
        score += 15.0 + open_bins_count as f64 * 3.0;
        // But if nothing fits well (high mean residual wasted), a fresh bin
        // becomes attractive.
        if mean_residual > 0.5 * bin_capacity as f64 {
            score -= 20.0;
        }
        // Late in the stream, avoid spawning bins for small leftovers.
        if next_item_size > 0 && next_item_size <= post_residual {
            score += 5.0;
        }
    } else {
        // Existing bin: mild bonus scaled by how much slack it absorbs.
        score -= 5.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Global dead-space coupling: bins whose residual is far below the mean
    // residual are fragmented; prefer bins near the mean for balanced packing.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact-ish fits: small post_residual is good; penalize dead space
    // that can never hold typical items (below minimum plausible size ~1..100 range).
    if post_residual == 0 {
        score -= 40.0; // perfect fit
    } else if post_residual <= 10 {
        score -= 25.0;
    } else if post_residual <= 20 {
        score -= 10.0;
    } else if post_residual > 80 {
        score += 15.0; // wasteful near-empty bin use
    }

    // 2-step lookahead: if the next item fits into post_residual, strongly reward.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 30.0 - 0.15 * slack; // prefer chains that end tight
            if post_residual == next_item_size {
                score -= 15.0; // perfect 2-item chain
            }
        } else {
            // next item won't fit here: penalize proportionally to overshoot,
            // unless the bin is nearly full anyway.
            let overshoot = (next_item_size - post_residual) as f64;
            score += 0.25 * overshoot;
        }
    }

    // Relative-to-mean coupling: bins tighter than average are better targets.
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Last-chance bonus: this is the only bin that fits; avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive early in
    // the stream or when too many bins are open relative to progress.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score = 60.0 + 40.0 * progress - 5.0 * open_bins_count as f64;
        // If lookahead chains perfectly into a fresh bin, allow it occasionally.
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize large post_residual quadratically, but
    // dampen when the bin is nearly full anyway.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 6.0 * tightness * tightness;

    // Penalize creating small dead space that likely becomes unusable
    // (post_residual in 1..=10 is the classic waste zone).
    if post_residual > 0 && post_residual <= 12 {
        score += 18.0 - (post_residual as f64);
    }

    // Lookahead: if the next item fits exactly into post_residual, strongly
    // favor this bin (chain packing).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score += slack * 0.35; // mild penalty for imperfect chain fit
        }
    }

    // Last-chance bonus: this is the only bin that can fit the item;
    // avoid opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0 + 0.1 * (bin_residual - item_size) as f64;
    }

    // New-bin candidate handling: an empty bin should only win when no
    // open bin offers a decent fit. Give it a mild handicap so it wins
    // only when existing residuals are fragmented.
    if bin_residual == bin_capacity {
        score += 8.0;
        // Late in the stream, prefer consolidating into open bins even more.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 10.0 * progress;
        // If many bins are open and mean residual is large, opening a new
        // bin is less attractive.
        score += 0.05 * open_bins_count as f64;
        if (mean_residual as u32) >= item_size + 5 {
            score += 12.0;
        }
    }

    // Slight preference for fuller bins when residuals are spread out.
    let diff = (bin_residual as f64 - mean_residual).abs();
    score += 0.08 * diff;

    // Early stream: be a bit more willing to open bins (explores better
    // configurations); late stream: consolidate hard.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 4.0 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Smooth polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 + 2.0 * progress) + norm_pr * (1.0 - progress);
    let mut score = 100.0 * poly;

    // Prefer tight fits: reward small post_residual smoothly
    score -= (1.0 - norm_pr) * (1.0 - norm_pr) * item_size as f64 * 0.5;

    // Penalize dead space that can't fit typical future items, smoothly scaled by progress
    let dead = if next_item_size > 0 {
        let waste = (next_item_size as f64 - pr).max(0.0) / cap;
        waste * waste * (1.0 + progress)
    } else {
        0.0
    };
    score += 60.0 * dead;

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - progress + 0.5);
    }

    // Mild penalty for proliferating open bins relative to mean residual
    score += (open_bins_count as f64) * 0.05 * (mean_residual / cap - norm_pr).abs();

    // Smooth lookahead reward: if next item fits the post residual, reward this placement
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 8.0 * (1.0 - pr / cap);
    }

    // New-bin candidate: neutral-ish baseline so it wins only when open bins are bad
    if bin_residual == bin_capacity {
        score += 30.0 * (1.0 - progress) + 10.0 * norm_pr;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "small dead-space" classes are strongly preferred.
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fit: eliminate the bin
    } else if pr <= 10 {
        score -= 40.0; // near-perfect, unusable sliver anyway
    } else if pr <= 20 {
        score -= 15.0; // tight class
    } else if pr <= 30 {
        score -= 5.0;
    } else {
        // larger leftovers: penalize proportionally to wasted fraction
        score += (pr as f64 / cap) * 25.0;
    }

    // Harmonic divisibility: leftover that can exactly host the lookahead item
    // is a prime target (perfect next fit).
    if next_item_size > 0 {
        if pr == next_item_size {
            score -= 55.0;
        } else if next_item_size > 0 && pr % next_item_size.max(1) == 0 && pr > 0 && pr >= next_item_size {
            score -= 12.0; // leftover is an exact multiple of next item
        } else if pr < next_item_size {
            score += 8.0; // leftover too small for lookahead: dead space risk
        }
    }

    // Last-chance bin: strongly reward using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        // many candidates: prefer tighter fits, mild penalty for loose ones
        score += fitting_bins_count as f64 * 1.5;
    }

    // New-bin candidate: only attractive when current item is huge or all
    // open bins would leave terrible residue.
    if bin_residual == bin_capacity {
        let tight_alt = fitting_bins_count > 0 && (post_residual as f64) > 0.55 * cap;
        if tight_alt {
            score -= 20.0; // open fresh bin for a big item
        } else {
            score += 45.0; // keep using existing bins when fits are decent
        }
    }

    // Favor filling bins with high residual relative to mean (balance pressure).
    score += 0.35 * (mean_residual - bin_residual as f64);

    // Late-stream consolidation: as the stream ends, prefer closing bins out.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * (1.0 - post_residual as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: small gaps (1..=10) are nearly unusable for future items
    if post_residual > 0 && post_residual <= 10 {
        score += (11 - post_residual as i32) as f64 * 12.0;
    }
    // Medium gaps (11..=20) are mildly risky
    if post_residual > 10 && post_residual <= 20 {
        score += (21 - post_residual as i32) as f64 * 2.5;
    }

    // Reward very tight fits (low post_residual) strongly
    if post_residual <= 3 {
