    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Pressure on number of open bins: discourage spreading when many bins open
    score += open_bins_count as f64 * 0.8;

    // If this is the brand-new empty bin candidate: penalize slightly so we only
    // open a new bin when no open bin fits well (i.e., when best open-bin score is high)
    if bin_residual == bin_capacity {
        score += 15.0 + mean_residual * 0.2;
        // If the next item is large, having a fresh bin is valuable
        if next_item_size >= 50 {
            score -= 20.0;
        }
    }

    // Lookahead: if next item fits exactly in post_residual, reward this placement
    if next_item_size > 0 && post_residual > 0 && next_item_size == post_residual {
        score -= 40.0;
    }
    // If next item cannot fit in post_residual but could fit elsewhere, mild penalty for wasting
    if next_item_size > post_residual && post_residual > 0 && post_residual < 10 {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
