pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 60.0;
    }

    // Tight fit reward: residual after placement small relative to capacity
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * tightness * tightness;

    // Penalize bins that could not fit the *next* item after this placement
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0; // lookahead-friendly
        } else {
            score += 6.0 + 0.1 * (post_residual as f64);
        }
        // Exact lookahead match is very desirable
        if post_residual == next_item_size {
            score -= 15.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when current item is large
    // or all open bins are nearly full (mean residual small).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let openness = mean_residual / bin_capacity as f64;
        // prefer reusing bins when mean residual is healthy
        score += 30.0 * openness;
        // early on, opening bins is cheaper; late, discourage fragmentation
        score += 10.0 * (1.0 - progress);
        // large items justify a fresh bin
        if item_size > bin_capacity / 2 {
            score -= 12.0;
        }
        // if few alternatives exist, new bin is fine
        if fitting_bins_count == 0 {
            score -= 20.0;
        }
    }

    // Reward filling bins that are already mostly full (low residual)
    let fill_ratio = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= 10.0 * fill_ratio;

    // Mild penalty for spreading across too many open bins
    score += 0.3 * open_bins_count as f64;

    // Deviation from mean residual: prefer bins below mean (filler bins)
    score += 0.05 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr_norm = pr / cap;

    // Base: prefer small post-residual, with a non-linear convex penalty on wasted space
    let mut score = pr + 30.0 * pr_norm * pr_norm;

    // Stream-progress coupling: late in the stream, dead space matters more
    let late = progress * progress;
    score += 40.0 * late * pr_norm;

    // Last-chance bonus: strongly favor the only bin that fits
    if fitting_bins_count == 1 {
        score -= 25.0 + 20.0 * progress;
    }

    // Lookahead: reward if next item fits the post-residual, penalize near-miss dead space
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            score -= 12.0 * (1.0 - (nxt / (pr + 1.0)));
        } else {
            score += 8.0 * (nxt - pr) / cap;
        }
    }

    // Mild penalty when bin residual deviates from mean residual (encourage balanced fills)
    score += 3.0 * ((bin_residual as f64 - mean_residual) / cap).abs();

    // Slight preference to reuse existing bins over opening new ones
    if bin_residual == bin_capacity {
        score += 6.0 + 4.0 * (1.0 - progress);
    } else {
        score -= 2.0 * (open_bins_count as f64).ln().max(0.0) / 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Harmonic class of the residual: classify leftover space by which item
    // size classes can still use it. Residuals that only fit the smallest
    // class (< 10) are near-dead space.
    let dead = post_residual > 0 && post_residual < 10;
    if dead {
        score += 25.0;
    }

    // Lookahead: if the next item cannot use the leftover space, the residual
    // is wasted; penalize proportionally to how "unusable" it is.
    if next_item_size > 0 {
        if next_item_size > post_residual && post_residual > 0 {
            // Next item won't fit here; leftover is likely dead unless small
            // items follow. Penalize more when residual is in a "narrow band"
            // (fits nothing in [10..next_item_size)).
            score += 12.0 + 0.15 * post_residual as f64;
        } else if next_item_size <= post_residual {
            // Next item chains nicely: reward, scaled by tightness of chain.
            let chain_tight = (post_residual - next_item_size) as f64;
            score -= 8.0 - 0.05 * chain_tight;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 {
        score -= 15.0;
        if post_residual < 10 && post_residual > 0 {
            // Even last chance: dead space still bad, but new bin is worse.
            score += 8.0;
        }
    }

    // New-bin candidate handling: opening a fresh bin is only attractive when
    // current item is large (poor fit candidates elsewhere) or no bins fit.
    if bin_residual == bin_capacity {
        // Fresh bin: its post_residual equals capacity - item; that's a big
        // number so it rarely wins by default. Give a moderate discount when
        // the item is large relative to capacity (harmonic fraction >= 1/2),
        // making fresh bins competitive for big items.
        let frac = item_size as f64 / bin_capacity as f64;
        if frac >= 0.5 {
            score -= 30.0 * frac;
        }
        // But if some existing bin fits decently (small post_residual there),
        // discourage opening a new one.
        if fitting_bins_count > 0 && item_size <= 50 {
            score += 20.0;
        }
    }

    // Integer-division threshold coupling: residuals in the "high band"
    // (>= half capacity) are versatile; mild reward for keeping bins flexible
    // when many bins are open.
    if post_residual >= bin_capacity / 2 {
        score -= 3.0;
    }

    // Slight preference to consolidate into fewer bins early in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.02 * open_bins_count as f64 * (1.0 - progress);

    // Nudge toward bins whose residual is below the current mean (tighter bins
    // first), keeping loose bins available for awkward items.
    if (bin_residual as f64) < mean_residual {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Strict dead-space avoidance: penalize small unusable gaps (1..=9).
    if post_residual >= 1 && post_residual <= 9 {
        score += 25.0;
    }
    // Moderately awkward gaps (10..=19) get a mild penalty.
    else if post_residual >= 10 && post_residual <= 19 {
        score += 6.0;
    }
    // Large usable residuals are mildly attractive (room for future items).
    else if post_residual >= 30 {
        score -= 4.0;
    }

    // Open-bins pressure: discourage opening new bins when many bins are open.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 12.0 + (open_bins_count as f64) * 1.5;
        // A new bin is acceptable only if the item leaves a large usable gap
        // and no other bin fits well (last-chance logic below).
        if post_residual < 20 {
            score += 15.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if !is_new_bin && fitting_bins_count == 1 {
        score -= 10.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward.
    if next_item_size > 0 && post_residual > 0 && next_item_size == post_residual {
        score -= 20.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 3.0;
    }

    // Mild late-stream consolidation: prefer tighter bins as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (bin_residual as f64 - mean_residual) * 0.05;
    score -= progress * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect lookahead match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near match: next item fits with small slack left.
    else if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 30.0 * (1.0 - slack / bin_capacity as f64);
    }

    // Exact fit now is excellent.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Penalize tiny dead space (unusable slivers) more than moderate residual.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Prefer bins below mean residual (tighter bins first) mildly.
    score += 0.3 * (mean_residual - post_residual as f64);

    // Last chance bin: strong reward to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are poor fits.
    if bin_residual == bin_capacity {
        score += 25.0;
        // Early in stream, opening bins is cheaper; later, pack tighter.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * (1.0 - progress);
        // If the next item also fits a fresh bin alongside, opening may be fine.
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 6.0 * tightness * tightness * (item_size as f64);

    // Penalize dead space that cannot plausibly be filled by future items.
    // Dead space = post_residual smaller than the smallest plausible item (1..100 range).
    if post_residual > 0 && (next_item_size == 0 || post_residual < next_item_size) {
        score += 8.0 * (post_residual as f64 / bin_capacity as f64);
    }

    // Lookahead coupling: strongly reward bins that leave room for the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 10.0;
            // Extra reward if next item fits EXACTLY after this one (perfect chain).
            if post_residual == next_item_size {
                score -= 15.0;
            }
        } else {
            // Next item cannot use this bin's leftover: mild penalty proportional to waste.
            score += 4.0 * (1.0 - (post_residual as f64 / bin_capacity as f64));
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // New-bin candidate handling: empty bin should only win when open bins fit poorly.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, modulated by stream horizon and congestion.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let mut new_bin_cost = 25.0 + 10.0 * (1.0 - progress);
        // If many open bins with slack, opening new bins is wasteful.
        new_bin_cost += 2.0 * open_bins_count as f64;
        // If mean residual is large, prefer using existing bins.
        if mean_residual > item_size as f64 {
            new_bin_cost += 5.0;
        }
        // Exception: very large items nearly fill a fresh bin exactly.
        if item_size >= 90 {
            new_bin_cost -= 30.0;
        }
        score += new_bin_cost;
    } else {
        // Slight preference for fuller bins (best-fit bias) among open bins.
        score += 0.05 * (bin_residual as f64);
        // Congestion-aware tiebreak: when many bins compete, prefer tighter residual.
        if fitting_bins_count > 3 {
            score += 0.03 * (bin_residual as f64 - mean_residual).abs();
        }
    }

    // Time-horizon term: early in the stream, be conservative (keep bins flexible);
    // late in the stream, aggressively fill residual space.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 5.0 * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Non-linear waste penalty: quadratic coupling of post_residual with stream progress.
    // Early on, waste is cheaper (bins may still be filled by future items); later, dead space hurts.
    let waste = post / cap;
    score += waste * waste * (30.0 + 50.0 * progress);

    // Cubic interaction: strongly penalize mid-sized residual gaps that are hard to fill later.
    let mid_gap = 1.0 - ((post - cap * 0.35) / (cap * 0.35)).powi(2);
    if post > 1.0 {
        score += (1.0 - mid_gap).abs() * 8.0 * (0.5 + progress);
    }

    // Lookahead: reward if next item fits the post residual (smooth exponential bonus).
    if next_item_size > 0 && (next_item_size as f64) <= post {
        let fit_ratio = next_item_size as f64 / post.max(1.0);
        score -= 20.0 * fit_ratio * (1.0 - progress * 0.5);
    }

    // Last-chance bin: strongly favor using it instead of opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: neutral-ish baseline so it only wins when fits are poor.
    if bin_residual == bin_capacity {
        score = cap * (0.35 + 0.4 * progress) + waste * 5.0;
        // Opening a new bin is more attractive when many bins exist and mean residual is high.
        score -= (open_bins_count as f64).ln().max(0.0) * 2.0;
        score -= (mean_residual / cap - 0.5).max(0.0) * 15.0;
    }

    // Reward tight fits: small post residual relative to bin gets a discount.
    score -= (1.0 - waste) * (item_size as f64 / cap) * 6.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post-residual: small classes of dead space are worse
    // than large usable classes. Penalize tiny nonzero residuals.
    let pr = post_residual;
    if pr > 0 && pr < 10 {
        score += 60.0; // nearly dead space
    } else if pr < 20 {
        score += 25.0;
    } else if pr < 35 {
        score += 8.0;
    }

    // Reward exact fills (perfect packing).
    if pr == 0 {
        score -= 100.0;
    }

    // Class by post_residual mod 10: residuals that are multiples of 10
    // (or common small values) are more reusable by typical items.
    let m = (pr % 10) as f64;
    score += m * 0.8;

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 && next_item_size <= pr {
        score -= 30.0;
        // extra reward for near-exact two-item fill
        if pr - next_item_size < 5 {
            score -= 20.0;
        }
    } else if next_item_size > 0 {
        // next item cannot fit here; slight penalty so we prefer other bins
        score += 10.0;
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // New-bin candidate (empty bin): only attractive when current bin's
    // post-fit is poor or next item pairs well with a fresh bin.
    if bin_residual == bin_capacity {
        score = 45.0 + post_residual as f64;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            // a fresh bin can host item + next item if they pair
            if item_size + next_item_size <= bin_capacity {
                score -= 35.0;
            }
        }
        if fitting_bins_count <= 1 {
            score -= 30.0; // no good open bin exists -> open new bin
        }
        // late in the stream, prefer closing out open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 15.0;
    }

    // Mild pressure against bin proliferation.
    score += open_bins_count as f64 * 0.05;
    // Slight preference for bins tighter than average (better fits).
    score -= (mean_residual - bin_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that can never host even the
    // smallest future item (1..10) are pure waste -> heavy penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 12.0;
    }

    // Perfect / near-perfect fits are gold.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward tight fit relative to bin residual (waste ratio).
    if bin_residual > 0 {
        let waste_ratio = post_residual as f64 / bin_residual as f64;
        score += 25.0 * waste_ratio;
    }

    // Lookahead: if the next item fits exactly in the post residual,
    // strongly favor this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        score -= 18.0 - (gap as f64) * 0.35;
    } else if next_item_size > 0 && post_residual > 0 {
        // Next item cannot use this dead space at all.
        score += 8.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: discourage proliferation of bins unless fit is good.
    score += (open_bins_count as f64) * 0.8;

    // Prefer bins whose residual is below average (consolidating waste).
    score -= (mean_residual - post_residual as f64) * 0.25;

    // New-bin candidate: only attractive when it offers perfect modularity
    // for the item plus the lookahead, i.e. no obvious open bin can do better.
    if bin_residual == bin_capacity {
        let mut bonus = 6.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            let gap = post_residual - next_item_size;
            if gap == 0 {
                bonus -= 45.0; // item + next item exactly fill a fresh bin
            } else if gap < 10 {
                bonus += 15.0;
            }
        }
        if fitting_bins_count <= 1 {
            bonus -= 20.0;
        }
        score += bonus;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Penalize dead space that cannot host the next item (wasted gap).
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += (next_item_size - post_residual) as f64 * 0.8;
    }

    // Reward small positive post_residual (tight fits generally).
    score -= (bin_capacity as f64 - post_residual as f64) * 0.3;

    // Relative to mean residual: prefer bins tighter than average.
    score -= (mean_residual - post_residual as f64) * 0.4;

    // Last-chance bin before opening a new bin: strong bonus to use it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are poor fits.
    if bin_residual == bin_capacity {
        score += 40.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 15.0;
        }
    }

    // Late in stream: consolidate, avoid opening new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= progress * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) with a nonlinear bonus.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize dead space that no plausible future item can use.
    if post_residual > 0 {
        if next_item_size > 0 && next_item_size <= post_residual {
            // Lookahead: reward bins that can also host the next item.
            let gap = (post_residual as f64 - next_item_size as f64) / bin_capacity as f64;
            score -= 10.0 * (1.0 - gap);
        } else if next_item_size > post_residual {
            // Leftover space cannot fit the next item -> dead space risk.
            score += 0.35 * post_residual as f64;
        }
    }

    // Perfect fit gets a strong bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Prefer filling bins that are already below average residual
    // (keeps many medium-residual bins available for future items).
    let dev = mean_residual - bin_residual as f64;
    score += 0.15 * dev;

    // Time horizon: early in the stream, be more selective (penalize
    // loose fits since many items remain); late in the stream, just fill.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let horizon = 1.0 - progress;
    score += horizon * 0.20 * post_residual as f64;

    // When many bins are open, slightly discourage spreading to new bins
    // and encourage consolidating into existing ones.
    if bin_residual < bin_capacity {
        score -= 0.05 * open_bins_count as f64;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let desperation = if fitting_bins_count == 0 { 0.0 } else { 1.0 };
        score += 45.0 * desperation;
        // Early stream: opening a fresh bin is cheaper (more future items
        // to fill it); late stream: avoid opening new bins.
        score += 12.0 * horizon;
        if next_item_size > 0 {
            // A fresh bin can absorb the next item too.
            if next_item_size <= bin_capacity {
                score -= 3.0;
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early on (progress ~ 0): mild quadratic reward for tight fits.
    // Late (progress ~ 1): stronger cubic/quartic pressure to avoid dead space.
    let t = pr / cap; // normalized post residual in [0,1]
    let w_early = (1.0 - progress).powi(2);
    let w_late = progress.powi(2);
    let poly = 2.5 * t * t * w_early + 6.0 * t * t * t * w_late;
    score += poly * cap;

    // Reward last-chance bins (avoid opening new bins unnecessarily).
    if fitting_bins_count == 1 {
        score -= 12.0 + 10.0 * progress;
    }

    // Penalize bins whose residual is far from the mean (fragmentation signal).
    score += 0.15 * (pr as f64 - mean_residual).abs();

    // Coupling with lookahead: if next item fits the post-residual, reward.
    if next_item_size > 0 && (post_residual as u64) >= (next_item_size as u64) {
        score -= 4.0 + 0.05 * next_item_size as f64;
    } else if next_item_size > 0 {
        // penalize leaving dead space unusable by next item, scaled by progress
        score += 3.0 * (1.0 + progress);
    }

    // Slight penalty for spreading across too many open bins early.
    score += 0.02 * open_bins_count as f64 * (1.0 - progress);

    // Prefer fuller bins via a smooth concave term.
    score -= 1.5 * (1.0 - t) * (1.0 - t);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: how well it can host future items
    // Classes mod 10: residuals divisible by 10 are "harmonic" with the 10..80 item grid
    let post = post_residual as i64;
    let harmonic = (post % 10 == 0) as f64;
    score -= harmonic * 25.0;

    // Small unusable dead space penalty (residual in 1..=9 cannot host any item >= 1... but tiny gaps waste)
    if post > 0 && post < 10 {
        score += 40.0;
    }

    // Coupling with next item: reward residual that exactly fits lookahead
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 300.0;
        } else if post_residual > next_item_size {
            // lookahead fits comfortably: mild reward proportional to slack quality
            let slack = post_residual - next_item_size;
            if slack % 10 == 0 {
                score -= 20.0;
            }
            score += slack as f64 * 0.15;
        } else {
            // lookahead can't fit here: penalize if this bin becomes dead-ish
            score += 10.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // Integer-division threshold on post_residual: large residuals are flexible
    let quarter = bin_capacity / 4;
    if post_residual >= quarter {
        score -= 15.0;
    } else if post_residual < bin_capacity / 10 {
        score += 12.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is bad
    if bin_residual == bin_capacity {
        score += 60.0;
        if post_residual >= bin_capacity - 80 {
            // item is small; opening fresh bin for tiny item is wasteful
            score += 40.0;
        }
        // early in stream, allow new bins more freely
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= (1.0 - progress) * 30.0;
    }

    // Prefer filling bins that are already below mean residual (tighter bins first)
    if (bin_residual as f64) < mean_residual {
        score -= 8.0;
    }

    // Mild penalty for many open bins to encourage consolidation
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins where the item nearly fills the bin.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 3.0 * tightness * tightness * (item_size as f64);

    // Dead space penalty: post_residual gaps that are too small to be useful
    // (below the minimum plausible item size of 1..10) are pure waste.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }
    // Gaps in [10, 30) are semi-unusable for typical mid/large items.
    if post_residual >= 10 && post_residual < 30 {
        score += 8.0;
    }

    // Perfect fit: exact fill is ideal.
    if post_residual == 0 {
        score -= 20.0;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when the
    // current item would leave a poor gap elsewhere, or when open-bin pressure is low.
    if bin_residual == bin_capacity {
        // Base reluctance to open new bins, scaled by how many bins are open.
        score += 20.0 + 2.0 * open_bins_count as f64;
        // But if the item is large relative to mean residual, a fresh bin is fine.
        if (item_size as f64) > mean_residual {
            score -= 18.0;
        }
        // Lookahead: if next item is large, a fresh bin preserves flexibility.
        if next_item_size > 0 && (next_item_size as f64) > mean_residual {
            score -= 10.0;
        }
    }

    // Open-bin pressure: mildly discourage scattering items across many bins
    // when few bins exist; encourage consolidation when many are open.
    score += 0.5 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Lookahead synergy: reward leaving a gap that exactly fits the next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 12.0;
    }
    // Penalize leaving a gap slightly smaller than the next item (guaranteed dead space).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 6.0;
    }

    // Slight late-stream consolidation: as the stream progresses, prefer filling
    // existing bins over opening new ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 4.0 * progress * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // New-bin candidate handling: keep it attractive only when fits are poor.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Penalize opening a new bin mildly; the lookahead terms below can overcome it.
        score += 25.0;
    }

    // Aggressive 2-step lookahead: reward when the NEXT item exactly fills post_residual.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score += diff * 0.6; // penalize mismatch between leftover and next item
        if post_residual == next_item_size {
            score -= 40.0; // perfect chaining: this bin will be exactly closed next step
        } else if post_residual > next_item_size {
            score += (post_residual - next_item_size) as f64 * 0.15; // extra dead space
        } else {
            // next item won't fit here; leftover is dead space unless small
            score += (next_item_size - post_residual) as f64 * 0.1;
        }
    } else {
        // Last item: strongly prefer minimal leftover.
        score += 20.0;
    }

    // Relative-to-mean coupling: prefer bins tighter than average.
    score -= (mean_residual - post_residual as f64) * 0.5;

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 30.0;
    }

    // Prefer filling bins that are already well-used (low residual).
    score += (bin_residual as f64 / bin_capacity as f64) * 10.0;

    // Slight late-stream tightening: waste matters more as the stream ends.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly, but not perfect-zero waste (keep a little slack).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 24.0 * tightness * tightness;

    // Penalize very small dead space that no future item (min size 1) can waste,
    // but reward residual that could still fit a typical item.
    if post_residual > 0 && post_residual < 10 {
        score += 6.0;
    }

    // Lookahead: if the next item fits into the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0 + 0.15 * next_item_size as f64;
    } else if next_item_size > 0 && post_residual > 0 {
        // Post residual too small for the next item: mild penalty for creating dead space.
        score += 4.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Penalize opening a new bin when other bins could fit the item.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // New-bin candidate: add a penalty scaled by how good the alternatives are.
            let best_alt = mean_residual.max(item_size as f64);
            score += 30.0 + best_alt * 0.2;
            // Early in the stream, be more willing to open bins (spread load).
            let progress = step_index as f64 / (total_items.max(1) as f64);
            score -= 12.0 * (1.0 - progress);
        } else {
            // No alternative: new bin is fine, slight reward.
            score -= 5.0;
        }
    }

    // Prefer filling bins whose residual is below the mean residual (consolidating waste).
    if bin_residual < bin_capacity {
        let dev = mean_residual - bin_residual as f64;
        score += 0.05 * dev;
    }

    // Slight penalty per open bin to encourage bin consolidation over time.
    score += 0.02 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 - progress) + norm_pr * progress * progress;

    let mut score = 2.0 * poly * cap;

    // Reward tight fits (small post_residual) more strongly as stream progresses
    let tightness = 1.0 - norm_pr;
    score -= tightness * tightness * (10.0 + 40.0 * progress);

    // Lookahead coupling: penalize residual that cannot fit next item
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        let fits_next = if pr >= ns { 1.0 } else { 0.0 };
        let gap = ((pr - ns).abs()) / cap;
        score += (1.0 - fits_next) * (5.0 + 20.0 * progress);
        score -= fits_next * (1.0 - gap) * (5.0 + 15.0 * progress);
    }

    // Last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0 + 25.0 * progress;
    }

    // Mild penalty for opening new bins when many bins are open
    if bin_residual == bin_capacity {
        score += 3.0 + 10.0 * (1.0 - progress);
    }

    // Slight preference toward bins below mean residual (consolidation)
    score += 0.05 * (pr - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residues modulo 10 create
    // "compatibility classes" for future small items.
    let residue_class = post_residual % 10;
    // Residues 1..9 are awkward dead space; residue 0 is perfectly harmonic.
    let harmonic_penalty = match residue_class {
        0 => -6.0,
        5 => 1.0,
        r if r >= 7 => 3.0 + (r - 6) as f64,
        _ => 1.5,
    };
    score += harmonic_penalty;

    // Integer-division thresholds: classify post_residual into capacity fractions.
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    if post_residual < quarter {
        // Nearly full bin: good, pack it tight.
        score -= 8.0;
    } else if post_residual < half {
        score -= 3.0;
    } else if post_residual > 3 * quarter {
        // Large leftover: wasteful unless item is huge.
        score += 2.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual,
    // strongly reward this bin (perfect harmonic pair).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 15.0;
        } else if next_item_size <= post_residual {
            let gap = post_residual - next_item_size;
            // Reward tight fits, penalize large leftover after the next item.
            score -= (post_residual as f64 - gap as f64) * 0.05;
            if gap % 10 == 0 {
                score -= 4.0;
            }
            if gap > half {
                score += 5.0;
            }
        } else {
            // Next item won't fit here regardless; slight penalty if we waste a big residual.
            score += (next_item_size - post_residual) as f64 * 0.02;
        }
    } else {
        // Last item: just minimize waste.
        score += post_residual as f64 * 0.01;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate: penalize opening a new bin unless the item is large
    // and no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let decent_fit_exists = mean_residual >= item_size as f64;
        let mut penalty = 12.0;
        if item_size >= 3 * quarter {
            penalty -= 4.0; // big items justify fresh bins
        }
        if decent_fit_exists {
            penalty += 6.0;
        }
        if open_bins_count > 8 {
            penalty += 2.0 * progress; // too many open bins late in stream
        }
        score += penalty;
    }

    // Mild preference for tighter bins among equals.
    score -= (bin_capacity - bin_residual) as f64 * 0.02;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: minimal post residual strongly preferred
    if post_residual > 0 {
        score -= 8.0 / post_residual as f64;
    } else {
        score -= 15.0; // perfect fill
    }

    // Dead-space penalty: small unusable gaps (below min item size) are wasted
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    // Mid-range dead space that is hard to fill
    if post_residual >= 10 && post_residual <= 30 {
        score += 6.0 * (30 - post_residual) as f64 / 20.0;
    }

    // Reward if next item fits exactly in the post residual (lookahead chaining)
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0;
        if post_residual == next_item_size {
            score -= 6.0;
        }
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 10.0; // post residual blocks the next item
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Open bins pressure: prefer filling existing bins when many are open
    score += open_bins_count as f64 * 1.5;

    // Prefer bins below mean residual (larger holes) for better consolidation
    score -= (bin_residual as f64 - mean_residual) * 0.3;

    // New bin candidate: only attractive when no good fit exists
    if bin_residual == bin_capacity {
        score += 30.0;
        // Late in the stream, opening a fresh bin is cheaper than fragmenting
        if step_index as f64 / total_items as f64 > 0.8 {
            score -= 10.0;
        }
        if fitting_bins_count == 0 {
            score -= 50.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward perfect chains (next item fills post_residual)
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect chain: post_residual == next_item_size -> strong bonus
        if gap == 0.0 {
            score -= 40.0;
        } else {
            score += gap * 0.35;
            // If next item cannot fit at all, dead space penalty
            if (next_item_size as u32) > post_residual {
                score += (next_item_size as f64 - post_residual as f64) * 0.25;
            }
        }
    } else {
        // Last item: prefer tightest fit
        score += 5.0;
    }

    // Relative-to-mean coupling: bins with residual near mean are "average" targets;
    // penalize using bins far below mean (precious tight bins) for loose fits.
    let dev = post_residual as f64 - mean_residual;
    if dev < 0.0 {
        score += dev * -0.15; // penalize draining tight bins
    } else {
        score -= dev * 0.05; // mildly prefer filling loose bins
    }

    // Last-chance bin: strong bonus to avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fits are all poor.
    if bin_residual == bin_capacity {
        score += 30.0 + 0.3 * open_bins_count as f64;
        // But if lookahead shows next item pairs badly with everything, allow it
        if next_item_size > 0 && next_item_size > 50 {
            score -= 20.0;
        }
    }

    // Slight preference for using fewer bins as stream progresses
    score += (step_index as f64 / total_items.max(1) as f64) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let is_new_bin = bin_residual == bin_capacity;

    // Reward perfect fits strongly
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual <= 5 {
        score -= 10.0;
    }

    // Penalize creating dead space that the lookahead item cannot use
    if next_item_size > 0 && (post_residual as u32) < next_item_size && post_residual > 0 {
        let waste = next_item_size as f64 - post_residual as f64;
        score += 4.0 + waste * (0.3 + 0.4 * progress);
    }
    // Reward leaving room for the next item
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 3.0 + 0.05 * post_residual as f64;
    }

    // Last-chance bin: strong discount to avoid opening a needless bin
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 15.0 + 10.0 * (1.0 - progress);
    }

    // New-bin candidate: attractive early and when open bins are fragmented,
    // unattractive late in the stream or when few bins are open
    if is_new_bin {
        score -= 6.0 + 14.0 * (1.0 - progress);
        if open_bins_count > 3 && mean_residual < item_size as f64 * 0.6 {
            score -= 8.0;
        }
    }

    // Mild pressure toward bins with residual near the global mean (balanced packing)
    score += 0.08 * (mean_residual - post_residual as f64).abs();

    // Slight preference for keeping many small bins consolidated over time
    if open_bins_count > 8 {
        score += 0.3 * open_bins_count as f64 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Base: prefer small post-residual (best-fit core), smooth polynomial shaping.
    let mut score = pr / cap;

    // Non-linear coupling: residual waste penalized more as stream progresses.
    let pr_norm = pr / cap;
    score += 0.8 * pr_norm * pr_norm * (0.5 + progress);

    // Penalty for very tight fits that leave near-zero residual (dead space risk)
    // is relaxed late in the stream when filling bins exactly is valuable.
    let tightness = 1.0 - pr_norm;
    score -= 0.3 * tightness * tightness * tightness * (1.0 - progress);

    // Last-chance bonus: strongly reward using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 2.0;
    }

    // Lookahead: reward if next item fits the post residual (chain packing).
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 0.5 * (1.0 - (next_item_size as f64) / cap) * (0.5 + progress);
    } else if next_item_size > 0 {
        // Penalize leaving residual that next item cannot use, scaled by waste size.
        score += 0.4 * pr_norm * (0.5 + progress);
    }

    // Mild penalty for proliferating bins when many are already open.
    score += 0.02 * open_bins_count as f64 * (1.0 - progress);

    // Prefer bins with residual below mean residual (fill the fullest bins first).
    score += 0.1 * (mean_residual - bin_residual as f64) / cap;

    // New-bin candidate: neutral-to-slightly-high default so it wins only when
    // open bins would waste a lot of space.
    if bin_residual == bin_capacity {
        score += 0.6 + 0.5 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "usable" classes
    // (multiples of small denominators) are more likely to host future items.
    let cap = bin_capacity as f64;

    // Dead-space penalty: tiny leftovers (< 10, minimum item size) are unusable.
    if post_residual < 10 && post_residual > 0 {
        score += 25.0;
    }

    // Reward exact fits strongly.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Harmonic class bonus: post_residual divisible by common item granularities
    // (2, 4, 5, 10) suggests it can be tiled by future items.
    let mut harmony = 0.0;
    if post_residual % 10 == 0 { harmony += 6.0; }
    else if post_residual % 5 == 0 { harmony += 3.0; }
    if post_residual % 4 == 0 { harmony += 2.0; }
    if post_residual % 2 == 0 { harmony += 1.0; }
    score -= harmony;

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual >= next_item_size {
            // residual chain: leftover after hypothetical next placement
            let chain = post_residual - next_item_size;
            score -= 8.0 + (chain as f64).min(20.0) * 0.3;
        } else {
            // next item won't fit here; penalize slightly if we waste capacity
            score += 5.0;
        }
    }

    // Fraction-of-capacity class of the residual: mid-range residuals are flexible.
    let frac = post_residual as f64 / cap;
    if frac > 0.2 && frac < 0.6 {
        score -= 4.0;
    }

    // Mild pressure to consolidate when many bins are open.
    if open_bins_count > 4 {
        score -= (open_bins_count.min(20) as f64) * 0.4;
    }

    // Prefer bins tighter than the mean residual (best-fit flavor).
    score += (mean_residual - bin_residual as f64) * 0.2;

    // New-bin candidate: neutral-ish baseline; only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        score += 12.0;
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Small progression term: later in stream, consolidate harder.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: gaps too small to hold the smallest conceivable item are worthless.
    if post_residual < 10 {
        score += 60.0; // effectively unusable gap -> strong penalty
    } else if post_residual < item_size.min(20) {
        // gap smaller than the item itself and small in absolute terms: likely dead space
        score += 25.0 * (1.0 - post_residual as f64 / 20.0);
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    } else if post_residual <= 10 {
        score -= 15.0;
    }

    // Lookahead coupling: penalize leaving a gap that exactly baits the next item
    // but can't hold it (wasted slot), reward gaps that can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0; // gap remains useful for lookahead item
        } else if post_residual > 0 && post_residual < next_item_size.min(10) {
            score += 10.0; // gap baits but cannot fit next item -> dead space
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoid fragmentation).
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        // With multiple options, mild preference for tighter bins (already in post_residual).
        score += 0.5 * (fitting_bins_count as f64).log2();
    }

    // Open-bin pressure: discourage spreading across many bins when mean residual
    // is already low; encourage using existing slack.
    score += 0.15 * open_bins_count as f64 * (mean_residual / bin_capacity as f64).max(0.0);

    // Slight late-stream conservatism: as the stream progresses, avoid marginal
    // placements that create dead space (dead-space penalties scale up).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.3 * progress;

    // New-bin candidate handling: an empty bin has residual == capacity.
    // Only prefer it when the item is large and no open bin gives a decent fit;
    // otherwise make the fresh bin slightly unattractive to preserve packing density.
    if bin_residual == bin_capacity {
        let tightness = item_size as f64 / bin_capacity as f64;
        if tightness > 0.7 && post_residual < 30 {
            score -= 20.0; // big item, poor fits likely -> new bin is fine
        } else {
            score += 35.0; // default: prefer existing bins
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tightest fit (smallest post_residual)
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness;

    // Aggressive 2-step lookahead: reward if next item exactly fills post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect chaining
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - slack / (bin_capacity as f64));
        } else {
            // next item can't fit here; penalize proportionally to overshoot
            let over = (next_item_size - post_residual) as f64;
            score += 0.35 * over;
        }
    }

    // Relative to mean residual: bins with residual near mean are neutral,
    // much larger residual than mean suggests underused bin -> mild penalty
    let dev = (bin_residual as f64) - mean_residual;
    score += 0.08 * dev;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Penalize opening a new bin when open bins fit well
    if bin_residual == bin_capacity {
        score += 18.0;
        // early in stream, new bins are cheaper
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * (1.0 - progress);
        // if next item is large, a fresh bin is attractive
        if next_item_size >= 60 {
            score -= 8.0;
        }
    }

    // Dead-space penalty: small unusable leftovers
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Mild penalty for spreading across many open bins
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (wasted-space shaping)
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 18.0 * fit_ratio * fit_ratio;

    // Penalize very small post-residuals that create dead space
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Lookahead: reward if next item fits into post_residual
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0;
        } else {
            score += 4.0 * (next_item_size as f64 - post_residual as f64) / 100.0;
        }
    }

    // Time horizon: early in the stream, be more selective (favor tight fits);
    // late in the stream, tolerate looser fits to close bins out.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * fit_ratio;

    // Global state coupling: many open bins with high mean residual -> prefer
    // filling existing bins rather than opening new ones.
    let mean_res_gap = (mean_residual - post_residual as f64) / bin_capacity as f64;
    score -= 6.0 * mean_res_gap;

    // New-bin candidate handling: opening a new bin is only attractive when
    // the item is large relative to capacity or existing bins fit poorly.
    if bin_residual == bin_capacity {
        let item_frac = item_size as f64 / bin_capacity as f64;
        let pressure = if fitting_bins_count == 0 { 1.0 } else { 1.0 / (fitting_bins_count as f64) };
        let next_pressure = if next_item_size > 0 && next_item_size > mean_residual {
            0.5
        } else {
            0.0
        };
        // Base cost of a fresh bin, discounted by item size and pressure
        score = 40.0 * (1.0 - item_frac) + 20.0 * pressure + next_pressure * 10.0;
        if fitting_bins_count == 1 {
            // Never beat a genuine last-chance existing bin
            score += 30.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let mut score = pr;
    // Smooth polynomial coupling: residual squared normalized against capacity
    score += 6.0 * norm_pr * norm_pr * cap * (0.5 + progress);
    // Tight fits rewarded: penalize large post_residual more when few fitting bins
    let fit_factor = 1.0 + (fitting_bins_count as f64).recip();
    score -= 4.0 * (item_size as f64 / cap) * cap * fit_factor * (1.0 - norm_pr);
    // Lookahead: reward bins whose post-residual can host the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            score -= 3.0 * (nx / cap) * cap * (1.0 - progress);
        } else {
            score += 2.0 * (nx - pr) / cap * cap * progress;
        }
    }
    // Mean-residual coupling: prefer bins near the mean (smooth quadratic)
    let dev = (pr - mean_residual) / cap;
    score += 2.5 * dev * dev * cap * (0.5 + 0.5 * progress);
    // Congestion: many open bins -> favor consolidation of tight bins
    score -= (open_bins_count as f64).ln().max(0.0) * (cap - pr) * 0.05;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "usable"
    // residue classes (multiples of common small item sizes) are rewarded.
    let post = post_residual;
    let cap = bin_capacity as f64;

    // Reward exact-fit / near-tight placements.
    if post == 0 {
        score -= 60.0;
    } else if post <= 10 {
        score -= 25.0;
    }

    // Harmonic class check: post_residual divisible by small sizes => leftover
    // is reusable by future items in those classes.
    let harmonic_bonus = if post != 0 && (post % 10 == 0 || post % 20 == 0 || post % 25 == 0 || post % 50 == 0) {
        12.0
    } else if post != 0 && (post % 5 == 0) {
        6.0
    } else {
        0.0
    };
    score -= harmonic_bonus;

    // Penalize awkward dead space in "bad residue classes" (prime-ish leftovers).
    if post > 0 && post < 10 && post != 5 {
        score += 15.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post {
            score -= 40.0;
        } else if next_item_size <= post {
            // Harmonic class of next item vs post residual.
            if post % next_item_size == 0 {
                score -= 18.0;
            } else {
                score -= 8.0;
            }
        } else {
            // Next item won't fit here; penalize more if we wasted a tight bin.
            score += (next_item_size - post) as f64 * 0.15;
        }
    }

    // Fraction-of-capacity thresholds on bin_residual.
    let fill_frac = (bin_capacity - bin_residual) as f64 / cap;
    if fill_frac > 0.75 {
        score -= 10.0; // prefer completing well-filled bins
    } else if fill_frac < 0.25 {
        score += 5.0; // discourage scattering into barely-used bins
    }

    // New-bin candidate: penalize mildly so it's chosen only when open bins fit poorly.
    if bin_residual == bin_capacity {
        score += 30.0;
        // But if many open bins exist and mean residual is small, opening fresh
        // can be better (avoid fragmenting).
        if open_bins_count > 3 && mean_residual < 15.0 {
            score -= 25.0;
        }
        if next_item_size > 0 && next_item_size >= 60 {
            score -= 15.0; // reserve fresh space for large upcoming items
        }
    }

    // Stream progression: later in stream, be more conservative with new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.05 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps.
    // A gap is "dead" if it cannot hold the smallest plausible item (1..=10)
    // or, more usefully, cannot hold the lookahead item.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            // Gap too small for the lookahead item -> dead space penalty.
            // Harsher when the gap is tiny (cannot even fit small items).
            let dead = (next_item_size - post_residual) as f64;
            score += 2.0 * dead;
            if post_residual < 10 {
                score += 8.0;
            }
        } else if post_residual == next_item_size {
            // Perfect lookahead fit: strong reward.
            score -= 15.0;
        }
    }

    // Last-chance pressure: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Open-bin pressure: discourage opening new bins when many bins are open.
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline penalty that grows with open bins.
        score += 5.0 + (open_bins_count as f64) * 1.5;
        // But if nothing fits well, opening may be justified; soften when
        // many alternatives fit poorly (fitting_bins_count large).
        if fitting_bins_count > 0 {
            score += 4.0;
        }
        // Progress-aware: early in stream, new bins are cheaper to open.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 3.0 * (1.0 - progress);
    } else {
        // Reward using existing bins, scaled by how tight the fit is.
        let tightness = (item_size as f64) / (bin_residual as f64);
        score -= 6.0 * tightness;
    }

    // Mean-residual coupling: prefer bins whose residual is near the mean
    // (keeps a balanced portfolio of gaps); avoid extremes.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.3 * dev;

    // Prefer larger post_residual only mildly beyond base term (base already
    // counts post_residual linearly); add mild nonlinearity for very small gaps.
    if post_residual > 0 && post_residual < 5 {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Reward tight fits
        score += post_residual as f64 / bin_capacity as f64 * 30.0;
    }

    // 2-step lookahead: reward if next item fits into post_residual
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // next item fits here: reward proportionally to how well it fills
            let fill = next_item_size as f64 / post_residual as f64;
            score -= 40.0 * fill;
            // exact match of next item to post_residual is ideal
            if post_residual == next_item_size {
                score -= 200.0;
            }
        } else {
            // next item won't fit: penalize wasted residual
            score += 15.0;
        }
    }

    // Relative to mean residual: prefer bins that are more filled than average
    score -= (mean_residual - post_residual as f64) * 0.5;

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 250.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bin fit is bad
    if bin_residual == bin_capacity {
        score += 120.0;
        // if lookahead item is large, a fresh bin is attractive
        if next_item_size > item_size {
            score -= 60.0;
        }
    }

    // Late in stream: prefer closing bins tightly
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (low post residual).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that can't hold typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 6.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Lookahead: if next item fits into post residual, reward; else penalize.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 8.0;
        } else if next_item_size > post_residual && post_residual < next_item_size {
            score += 0.04 * (next_item_size - post_residual) as f64;
        }
    }

    // Prefer bins with residuals below mean residual (keeps large gaps open).
    if (bin_residual as f64) > mean_residual {
        score += 0.5 * (bin_residual as f64 - mean_residual) / (bin_capacity as f64);
    } else {
        score -= 0.3 * (mean_residual - bin_residual as f64) / (bin_capacity as f64);
    }

    // New-bin candidate handling: empty bin should only win when fits are poor.
    if bin_residual == bin_capacity {
        let waste = post_residual as f64; // == capacity - item_size
        // Penalize opening a new bin, more when many bins exist or stream is early.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 30.0 + 0.15 * open_bins_count as f64 + 20.0 * (1.0 - progress);
        // But if this bin's fit is the best possible and others are poor, allow it:
        if item_size >= 60 && waste < 40.0 {
            score -= 15.0;
        }
        if fitting_bins_count == 0 {
            score -= 100.0; // no open bin fits: must open new bin
        }
    }

    // Slight preference to consolidate into fewer bins early on.
    score += 0.02 * open_bins_count as f64 * (1.0 - tightness);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Smooth non-linear polynomial coupling of post_residual with stream progress.
    let norm_post = post / cap;
    let poly = norm_post * norm_post * (1.0 - progress) + norm_post * (0.5 + 0.5 * progress);

    let mut score = post + 20.0 * poly * cap;

    // Penalize tight fits that leave dead space, more so later in the stream.
    let tightness = 1.0 - norm_post;
    score += tightness * tightness * 30.0 * (0.3 + 0.7 * progress);

    // Reward using nearly-full bins (best-fit flavor) with smooth decay.
    score -= 15.0 * (-norm_post * 8.0).exp();

    // Last-chance bin bonus: avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // Lookahead: if next item fits the post-residual, reward this placement.
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 6.0 * (1.0 - progress);
    }

    // New-bin candidate: mildly discourage opening new bins early, allow later.
    if bin_residual == bin_capacity {
        score += 25.0 * (1.0 - progress) - 10.0 * progress;
    }

    // Coupling with mean residual: prefer bins deviating smoothly from mean.
    let dev = (post - mean_residual).abs() / cap;
    score += 10.0 * dev * (1.0 - dev);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // New-bin candidate: brand-new empty bin
    if bin_residual == bin_capacity {
        // Opening a new bin is attractive when this bin would otherwise be
        // the only fitting one (last chance) but leaves tiny dead space,
        // or when open bins are already congested.
        let tight = fitting_bins_count == 1;
        let bad_fit = post_residual > 0 && post_residual < 8;
        if tight && bad_fit {
            score -= 60.0; // prefer fresh bin over creating unusable sliver
        } else {
            score += 25.0; // default: prefer reusing an open bin
            if next_item_size > 0 && next_item_size >= post_residual && post_residual > 0 {
                score += 10.0; // new bin can also host next item later
            }
        }
        return score;
    }

    // Perfect fit: strongly reward
    if post_residual == 0 {
        score -= 100.0;
        return score;
    }

    // Harmonic classes of post_residual (modulo arithmetic on capacity fractions)
    let pr = post_residual;
    // Dead space classes: tiny residuals are nearly unusable
    if pr <= 5 {
        score += 45.0; // worst class: unusable sliver
    } else if pr <= 10 {
        score += 25.0;
    } else if pr <= 20 {
        score += 10.0;
    } else if pr <= 30 {
        score += 3.0;
    } else if pr <= 50 {
        score -= 4.0; // mid class: still useful
    } else {
        score -= 2.0; // large residual: flexible but wasteful
    }

    // Modulo-10 harmonic coupling: residuals that are multiples of 10
    // align with the common item-size lattice (sizes often multiples of 5/10)
    if pr % 10 == 0 {
        score -= 6.0;
    } else if pr % 5 == 0 {
        score -= 3.0;
    }

    // Lookahead: if next item exactly fits the post residual, big reward
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 80.0; // chained perfect fit
        } else if next_item_size <= pr {
            // next item fits: prefer residual classes matching next item's granularity
            let gap = pr - next_item_size;
            if gap <= 5 {
                score -= 20.0;
            } else if gap <= 15 {
                score -= 8.0;
            }
            if gap % 10 == 0 && gap > 0 {
                score -= 4.0;
            }
        } else {
            // next item won't fit here: penalize by how far off (harmonic distance)
            let miss = next_item_size - pr;
            score += (miss as f64) * 0.4;
            if miss <= 5 {
                score += 12.0; // agonizing near-miss: this bin becomes dead for next item
            }
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid wasting it
    // on an item that leaves bad dead space
    if fitting_bins_count == 1 && pr > 0 && pr <= 10 {
        score += 30.0;
    } else if fitting_bins_count == 1 {
        score -= 5.0; // using the last-chance bin is still better than a new bin
    }

    // Stream progression: late in the stream, consolidate harder
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0 * (bin_residual as f64 / bin_capacity as f64);

    // Prefer bins with below-average residual (tighter bins first)
    score -= (mean_residual - bin_residual as f64) * 0.15;

    // Many open bins: encourage consolidation into existing bins
    if open_bins_count > 4 {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps are heavily penalized
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10 - post_residual) as f64;
    }
    // Perfect fit bonus
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual >= 10 {
        // residual large enough to potentially host a future item: mild reward
        score -= 5.0;
    }

    // Prefer bins whose residual is close to item size (tight fit)
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += 40.0 * tightness;

    // Open bins pressure: discourage opening new bins when many are open
    if bin_residual == bin_capacity {
        // new-bin candidate: penalize proportional to open bins, reward if no fitting bins
        score += 15.0 + 2.0 * open_bins_count as f64;
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
    } else if fitting_bins_count == 1 {
        // last chance bin: strongly favor using it
        score -= 50.0;
    }

    // Lookahead: if next item fits in post_residual, reward this placement
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0;
    }
    // If next item is large and this placement would leave a gap it can't use,
    // slightly prefer a bin whose post_residual is either 0 or >= next_item_size
    if next_item_size > post_residual && post_residual > 0 {
        score += 10.0;
    }

    // Mean residual coupling: prefer bins below mean residual (fill the emptiest-first / fullest-first blend)
    score += 0.5 * (mean_residual - bin_residual as f64);

    // Late-stream consolidation: as stream progresses, favor filling existing bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= 20.0 * progress;
    } else {
        score += 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor small post_residual
    score -= (bin_residual as f64 - post_residual as f64) * 0.5;

    // 2-step lookahead: reward when post_residual matches next item size
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (post_residual as f64 - nxt).abs();
        // perfect match for next item: big reward
        if post_residual as u32 == next_item_size {
            score -= 40.0;
        } else if post_residual as u32 >= next_item_size {
            // next item can fit here too: mild reward proportional to closeness
            score -= (nxt / diff.max(1.0)).min(5.0);
        } else {
            // dead space relative to next item: penalize
            score += diff * 0.3;
        }
        // if next item cannot fit anywhere else after this placement, discourage wasting
        let waste = post_residual as f64;
        score += (waste / bin_capacity as f64).powi(2) * 20.0;
    } else {
        // last item: pure best-fit
        score += (post_residual as f64 / bin_capacity as f64) * 10.0;
    }

    // Last chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize opening new bins when decent fits exist
    if bin_residual == bin_capacity {
        // new-bin candidate: baseline penalty scaled by how many bins already fit the item
        score += 15.0 + 3.0 * fitting_bins_count as f64;
        // early in stream, slightly prefer consolidating
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= progress * 5.0;
    } else {
        // prefer bins with residual below mean (denser bins)
        score -= (mean_residual - post_residual as f64) * 0.2;
    }

    // mild preference for fewer open bins
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to capacity)
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize dead space that is too small for typical future items
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if the next item fits exactly into the post residual, big reward
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            // next item won't fit here; penalize wasted potential
            score += 4.0 * (next_item_size as f64 - post_residual as f64) / 100.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 22.0;
    }

    // Global state coupling: when many bins are open with high mean residual,
    // prefer consolidating into existing bins rather than opening new ones
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // new-bin candidate: penalize more as stream progresses / many bins open
        score += 15.0 + 25.0 * progress + 0.4 * open_bins_count as f64;
        if mean_residual >= item_size as f64 {
            score += 20.0; // an existing bin could take it; discourage new bin
        }
    } else {
        // existing bin: mild reward scaling with open bins count
        score -= 0.05 * open_bins_count as f64;
    }

    // Encourage leaving residuals that match common size ranges
    let residual_utility = (post_residual as f64 / bin_capacity as f64).powi(3);
    score += 12.0 * residual_utility;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let prog = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: prefer small post-residual (tight fit)
    let mut score = post;

    // Non-linear tightness reward: quadratic coupling of post_residual with item share
    let item_share = item_size as f64 / cap;
    score -= 30.0 * (1.0 - post / cap) * (1.0 - post / cap) * (0.5 + item_share);

    // Smooth stream-progress coupling: later in stream, tolerate residuals less (favor consolidation)
    let progress_pressure = prog * prog * (1.0 - prog / 2.0);
    score += 20.0 * progress_pressure * (post / cap);

    // Last-chance bonus: only one bin fits -> strongly favor it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: penalize if post-residual can't fit the next item (dead space), reward if it can
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if post >= nx {
            score -= 8.0 * (nx / cap) * (1.0 - prog);
        } else {
            score += 6.0 * (1.0 - post / cap) * (0.5 + prog);
        }
    }

    // New-bin candidate handling: make empty bin attractive only when current bin would leave large dead space
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // neutral-ish baseline; slightly penalized so tight fits in open bins win
        score = cap * 0.55 + 10.0 * (1.0 - item_share) + 15.0 * prog;
        if fitting_bins_count == 0 {
            score -= 60.0; // no open bin fits -> must open
        }
    } else {
        // penalize bins whose residual deviates strongly from mean (fragmentation signal)
        score += 0.15 * ((bin_residual as f64 - mean_residual).abs() / cap) * (1.0 + prog);
    }

    // Mild penalty for spreading across many open bins late in stream
    if !is_new_bin {
        score += 0.05 * open_bins_count as f64 * prog;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: bins whose leftover falls into
    // "small" classes (0..=10) are near-perfect; large leftovers are wasteful.
    let cls = post_residual / 10; // integer-division class 0..=10
    score += cls as f64 * 4.0;

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward leaving residuals that form "fillable" classes for typical
    // small items: post_residual in {0, 10..30} is reusable, {31..49} is dead.
    if post_residual <= 30 {
        score -= 8.0;
    } else if post_residual < 50 {
        score += 6.0;
    }

    // Coupling with next item (lookahead): if the next item fits exactly
    // into the post-residual, strongly favor this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 10.0;
        } else {
            // next item would not fit here; slight penalty
            score += 5.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening
    // a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: empty bin should only win when the fit
    // into open bins is bad. Penalize the fresh bin mildly.
    if bin_residual == bin_capacity {
        score += 30.0;
        // Early in the stream, opening bins is cheaper.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 20.0 * (1.0 - progress);
    }

    // Prefer filling bins that are already relatively full (low residual
    // relative to mean): keeps many mid-full bins for future items.
    if (bin_residual as f64) < mean_residual {
        score -= 6.0;
    } else {
        score += 3.0;
    }

    // Modulo-based harmonic bonus: residuals that are multiples of common
    // item granularity (10) are easier to fill later.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals that are too small for the smallest item are wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Prefer bins whose residual is close to the item (tight packing).
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += tightness * 30.0;

    // Lookahead: if next item fits exactly in post_residual, strongly favor this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        let next_gap = post_residual - next_item_size;
        if next_gap == 0 {
            score -= 35.0;
        } else if next_gap < 10 {
            score += 20.0; // would create dead space after next item
        } else {
            score -= 10.0;
        }
    } else if next_item_size > 0 && post_residual > 0 {
        // next item can't use the leftover -> dead space risk
        score += (post_residual as f64) * 0.3;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones;
    // the new-bin candidate has bin_residual == bin_capacity so this raises its score.
    if bin_residual == bin_capacity {
        score += 15.0 + 3.0 * open_bins_count as f64;
    }

    // Mean-residual coupling: bins far above mean residual are less attractive targets
    // when we want to consolidate into fuller bins.
    score += (bin_residual as f64 - mean_residual).max(0.0) * 0.2;

    // Early in the stream, allow slightly more freedom to open bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score -= 20.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // New-bin candidate: penalize opening a new bin unless this bin would otherwise be wasted.
    if bin_residual == bin_capacity {
        score += 60.0;
        // Opening a new bin is attractive when few bins fit and the next item is large.
        if fitting_bins_count <= 1 {
            score -= 45.0;
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0;
        }
        return score;
    }

    // Aggressive 2-step lookahead: reward exact/near match of post_residual with next item.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 80.0; // perfect two-step packing
        } else if next_item_size < post_residual {
            let slack = post_residual - next_item_size;
            // Reward proportional to how well the next item fills the leftover.
            score -= 40.0 * (1.0 - slack as f64 / bin_capacity as f64);
        } else {
            // Next item cannot fit in leftover: penalize dead space creation.
            score += (next_item_size - post_residual) as f64 * 0.35;
        }
    } else {
        // Last item: prefer tightest fit only.
        score -= 5.0;
    }

    // Penalize tiny unusable residuals (< 10, min item size).
    if post_residual < 10 {
        score += 25.0;
    }

    // Relative-to-mean coupling: bins with residual below mean are scarcer; favor
    // placing into them to consolidate waste, penalize if it creates extreme tightness.
    if (bin_residual as f64) < mean_residual {
        score -= 8.0;
    } else {
        score += 4.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Slight preference to fill bins earlier in the stream (reduce open-bin sprawl).
    score -= (open_bins_count as f64).ln() * 1.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward near-perfect fits (small but positive leftover is ideal).
    if post_residual > 0 && post_residual <= 5 {
        score -= 30.0;
    } else if post_residual == 0 {
        score -= 25.0; // exact fill, excellent
    }

    // Penalize large dead space relative to typical item sizes.
    let dead = post_residual as f64;
    score += 0.15 * dead * dead / bin_capacity as f64;

    // Lookahead: reward bins whose leftover can host the next item (chain packing).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0 + 0.1 * (post_residual - next_item_size) as f64;
        } else {
            // leftover too small for next item: penalize proportionally to waste
            score += 0.2 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Global context: when many bins are open with high mean residual, prefer
    // consolidating into existing bins rather than opening new ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if open_bins_count > 2 {
        score -= 0.5 * mean_residual.min(50.0);
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin; make it attractive only when existing
        // bins would leave very poor fits or the stream is early.
        let poor_fit_elsewhere = fitting_bins_count == 0 || (mean_residual < item_size as f64 * 0.5);
        if poor_fit_elsewhere {
            score -= 35.0 + 20.0 * (1.0 - progress);
        } else {
            score += 40.0; // discourage opening new bins when decent fits exist
        }
    }

    // Mild time-horizon shaping: late in the stream, be more conservative about
    // creating fragmented leftovers.
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
    let nz = pr / cap; // normalized post residual
    let mut score = pr;

    // Smooth non-linear coupling of post residual with stream progress:
    // early on, prefer tight fits (low post residual); later, tolerate slack
    // to keep bins flexible for remaining stream.
    let tightness = 1.0 - nz;
    score += (tightness * tightness - 0.5) * (20.0 * (1.0 - progress) + 5.0 * progress);

    // Reward near-perfect fills with a smooth quadratic bonus.
    score -= 30.0 * (1.0 - nz) * (1.0 - nz) * nz;

    // Penalize very small dead space only if it can't plausibly fit future items.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let slack_deficit = ((nx - pr).max(0.0) / cap).clamp(0.0, 1.0);
        score += 15.0 * slack_deficit * slack_deficit * (0.5 + 0.5 * progress);
        // Reward bins that can also fit the next item (smooth lookahead bonus).
        let lookahead_fit = ((pr - nx).max(0.0) / cap).clamp(0.0, 1.0);
        score -= 8.0 * lookahead_fit * (1.0 - progress);
    }

    // Last-chance bin: strong smooth reward to use it rather than open a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0 + 20.0 * (1.0 - nz);
    }

    // Mild coupling with mean residual: avoid draining bins far below average.
    score += 3.0 * ((mean_residual - pr) / cap).clamp(-1.0, 1.0);

    // New-bin candidate: penalize opening a new bin, more so early in the stream,
    // unless the item is large relative to the bin (poor fit elsewhere).
    if bin_residual == bin_capacity {
        score += 30.0 * (1.0 - progress) + 10.0 - 0.3 * it;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of the post residual (capacity fractions) ---
    let c = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / c; // residual as fraction of capacity

    // Perfect fits are golden: reward strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Dead-space class: residual too small for the smallest item (1..=100 range).
        // Items >= 10 in classic regime, but interface says 1..=100; use 10 as small-item floor
        // and treat tiny residuals (<10) as dead space.
        if post_residual < 10 {
            score -= 60.0; // sealed bin is good, but not as good as perfect fit
        } else {
            // Harmonic class penalty: residual that pairs well with common item sizes
            // (multiples of 10/25/50) are more likely to be filled later.
            let harmonic_bonus: f64 = if post_residual % 50 == 0 {
                25.0
            } else if post_residual % 25 == 0 {
                18.0
            } else if post_residual % 10 == 0 {
                12.0
            } else if post_residual % 5 == 0 {
                6.0
            } else {
                0.0
            };
            score -= harmonic_bonus;

            // Non-harmonic dead space: penalize residuals in awkward bands.
            let awkward = (pr - (pr / 10.0).floor() * 10.0) / 10.0; // 0..1
            score += awkward * 8.0;

            // Large leftover fraction is wasteful unless it can host the next item.
            if frac > 0.5 {
                score += (frac - 0.5) * 20.0;
            }
        }
    }

    // --- Lookahead coupling: does next_item_size fit the post residual? ---
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Chain fit: excellent, keeps bin productive.
            let tight = 1.0 - ((post_residual - next_item_size) as f64) / c;
            score -= 30.0 + 20.0 * tight;
        } else if next_item_size <= bin_residual && post_residual < next_item_size {
            // We consumed space the next item could have used elsewhere: mild penalty.
            score += 10.0;
        }
        // Harmonic pairing: post_residual + next_item_size near capacity multiples.
        let pair = (post_residual + next_item_size) as f64;
        if pair == c {
            score -= 40.0;
        } else if pair % 25 == 0 {
            score -= 12.0;
        }
    }

    // --- Last-chance logic: if this is the only fitting bin, prefer using it ---
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Fresh bin: neutral baseline slightly above good fits, but attractive when
        // the item is large or existing bins are fragmented.
        let fragmentation = if open_bins_count > 0 {
            (mean_residual / c).clamp(0.0, 1.0)
        } else {
            0.0
        };
        score = c * 0.55 - fragmentation * 15.0
            + if item_size > 70 { 30.0 } else { 0.0 }
            + if post_residual < 30 { 25.0 } else { 0.0 };
    }

    // --- Stream progression: late in the stream, consolidate aggressively ---
    let progress = if total_items > 0 {
        step_index as f64 / total_items as f64
    } else {
        0.0
    };
    if progress > 0.7 && bin_residual < bin_capacity {
        score -= progress * 10.0;
    }

    // Tie-break: prefer bins whose residual is closest to item size (tightest fit)
    score += (bin_residual - item_size) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (< 10, minimum item size)
    // are catastrophic; penalize them heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Penalize moderately small gaps that can only fit the smallest items.
    if post_residual >= 10 && post_residual < 25 {
        score += 15.0;
    }

    // Reward near-perfect fits (post_residual == 0 is best packing).
    if post_residual == 0 {
        score -= 30.0;
    }

    // If the lookahead item fits exactly into the post_residual, strongly reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }

    // If post_residual cannot hold the next item, penalize (dead space relative to lookahead).
    if next_item_size > 0 && post_residual < next_item_size {
        score += 8.0;
    }

    // Open-bin pressure: discourage spreading across too many bins; but when this
    // bin is the last chance to fit, reward using it instead of a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: make opening a new bin costly unless the current item
    // is large and open bins are tight.
    if bin_residual == bin_capacity {
        score += 20.0 + 2.0 * open_bins_count as f64;
        if item_size >= 60 {
            score -= 15.0;
        }
    }

    // Mild pressure against opening bins early in the stream.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score += 10.0 * (1.0 - progress);
    }

    // Prefer bins with below-mean residual (keep large gaps for future large items).
    let residual_gap = bin_residual as f64 - mean_residual;
    score += 0.05 * residual_gap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 50.0;
    }
    // Near match: next item fits with small waste
    if next_item_size > 0 && post_residual > next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 20.0 * (1.0 - slack / bin_capacity as f64).max(0.0);
    }
    // Next item cannot fit in remaining space: dead space penalty grows with tightness
    if next_item_size > 0 && post_residual < next_item_size {
        score += 15.0 * (next_item_size - post_residual) as f64 / bin_capacity as f64;
    }

    // Penalize tiny unusable post residuals (dead space)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }
    // Zero post residual is perfect packing
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Prefer bins tighter than the mean residual (best-fit flavor)
    score += (post_residual as f64 - mean_residual) * 0.3;

    // Late in the stream, prefer compacting into existing bins over opening new ones
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses and when alternatives exist
        score += 10.0 + 40.0 * progress + (open_bins_count as f64).sqrt() * 2.0;
        // But if the current bin barely fits the item, opening a new bin is fine
        if item_size > bin_residual.saturating_sub(item_size).max(0) && bin_residual - item_size < 5 {
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Tight-fit reward: quadratic bonus for small post-residual
    let tight = 1.0 - (post_residual as f64 / cap);
    score -= 12.0 * tight * tight;

    // Perfect fit gets a strong extra reward
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual < 10 {
        score -= 8.0;
    }

    // Penalize creating dead space that no plausible item can fill
    if post_residual > 0 && post_residual < 10 {
        score += 10.0; // unusable sliver (items >= 1 but tiny slivers waste)
    }

    // Lookahead: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size < post_residual {
            let slack = post_residual - next_item_size;
            score -= 6.0 * (1.0 - slack as f64 / cap);
        } else {
            // next item won't fit here; mild penalty proportional to overflow
            score += 2.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a new bin wastes the residual of all open bins
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base penalty for opening a new bin grows with number of open bins
        score += 20.0 + 3.0 * open_bins_count as f64;
        // But if existing bins would leave very bad fits, opening is OK
        let fit_quality = 1.0 - (post_residual as f64 / cap); // = 0 for empty bin
        let _ = fit_quality;
        // If current bin's residual barely exceeds item (poor fit elsewhere), reduce penalty
        let waste_elsewhere = (bin_residual - item_size) as f64;
        if waste_elsewhere < 5.0 {
            score -= 25.0;
        }
        // Late in stream, prefer consolidating into open bins
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 15.0 * progress;
    }

    // Global state coupling: prefer bins with residual below mean (fill fuller bins first)
    let dev = bin_residual as f64 - mean_residual;
    score += 0.05 * dev;

    // Encourage balancing: slightly favor bins whose post-residual aligns with common sizes
    if post_residual >= 10 && post_residual <= 50 {
        score -= 3.0;
    }

    // Mild time-decay of exploration: later items favor tighter packing
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 5.0 * progress * tight;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let r = post_residual as f64;
    let cap = bin_capacity as f64;
    let rn = r / cap;

    // Base: prefer tight fits, scaled by capacity
    let mut score = r;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // late in the stream, tight fits matter more (waste compounds)
    let tightness = (1.0 - rn).powi(3);
    score -= 30.0 * tightness * (0.5 + progress);

    // Penalize mid-range residuals (dead space) via smooth quadratic bowl
    score += 8.0 * (4.0 * rn * (1.0 - rn)) * (1.0 - progress);

    // Reward bins whose residual after placement matches the lookahead item
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let match_term = 1.0 - ((r - next) / cap).abs();
        score -= 12.0 * match_term.max(0.0) * match_term;
    } else {
        // last item: pure tightness
        score -= 15.0 * tightness;
    }

    // Last-chance bin bonus: avoid opening a new bin when only one fits
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: mildly penalize so open bins are preferred unless fit is bad
    if bin_residual == bin_capacity {
        score += 10.0 + 15.0 * progress;
    }

    // Mild dispersion penalty: prefer bins near the mean residual (keeps pool uniform)
    score += 0.05 * (r - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: how "usable" the leftover space is
    // for typical item sizes (1..=100). Class by integer division thresholds.
    let pr = post_residual;
    let class = if pr == 0 { 0u32 }
        else if pr < 10 { 1 }
        else if pr < 20 { 2 }
        else if pr < 35 { 3 }
        else if pr < 50 { 4 }
        else { 5 };

    // Reward large usable classes (less dead space), penalize tiny unusable ones.
    score -= (class as f64) * 3.0;
    if class <= 1 { score += 15.0; }

    // Modulo arithmetic: residual that is a multiple of common item sizes
    // (10, 20, 25, 50) is more likely to be exactly filled later.
    if pr % 10 == 0 { score -= 5.0; }
    if pr % 25 == 0 { score -= 4.0; }
    if pr % 50 == 0 && pr > 0 { score -= 6.0; }

    // Lookahead coupling: if next item fits exactly into post_residual,
    // strongly favor this bin (perfect pair).
    if next_item_size > 0 {
        if next_item_size == pr { score -= 25.0; }
        else if next_item_size <= pr {
            let slack = pr - next_item_size;
            // harmonic class of the double-fill leftover
            if slack % 10 == 0 { score -= 8.0; }
            score -= (100.0 - slack as f64) / 100.0 * 5.0;
        } else {
            // next item won't fit here; penalize slightly unless this bin
            // is nearly full anyway.
            if pr < 20 { score += 5.0; }
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 10.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when current open
    // bins are crowded and the item is large.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let crowded = mean_residual < item_size as f64 * 1.2;
        if crowded && item_size > bin_capacity / 2 {
            score -= 12.0 + 5.0 * progress;
        } else {
            score += 20.0; // default: prefer existing bins
        }
    }

    // Small tie-break toward tighter bins overall.
    score += (mean_residual - bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
