pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong base reward for tight fits (small post_residual).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio;

    // 2-step lookahead: reward if next item fits exactly / well into post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            // Perfect chain: bin becomes exactly full after next item.
            score -= 60.0;
        } else if next_item_size < post_residual {
            let next_waste = (post_residual - next_item_size) as f64;
            // Reward proportional to how well next item fits the leftover.
            score -= 40.0 * (1.0 - next_waste / bin_capacity as f64);
            // Extra bonus if post_residual is small enough to be nearly consumed.
            if next_waste <= 10.0 {
                score -= 15.0;
            }
        } else {
            // Next item cannot fit here: penalize large dead space left behind.
            let dead = post_residual as f64;
            score += 0.35 * dead;
            // Harsher penalty if the dead space is below the smallest useful item.
            if post_residual < 10 && post_residual > 0 {
                score += 25.0;
            }
        }
    } else {
        // Last item: simply prefer the tightest fit.
        score -= 50.0 * fit_ratio;
    }

    // Penalize leaving residual far below the mean (creating unusable slivers),
    // but reward residuals close to the mean (balanced bins).
    let diff = post_residual as f64 - mean_residual;
    if diff < 0.0 {
        score += 0.15 * (-diff);
    } else {
        score -= 0.05 * diff;
    }

    // Last-chance logic: if this is the only bin that can fit the item,
    // strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate: penalize opening a new bin unless the item is large
    // relative to capacity or no good fit exists (handled above).
    if bin_residual == bin_capacity {
        score += 55.0;
        // But allow new bin for big items that would leave awkward residue elsewhere.
        if item_size > bin_capacity / 2 {
            score -= 30.0;
        }
        // Early in stream, new bins are cheaper to open.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 20.0 * (1.0 - progress);
    }

    // Mild penalty for many open bins: encourage consolidation.
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual already does this; amplify non-linearly).
    score -= 12.0 * (1.0 - (post_residual as f64 / bin_capacity as f64)).powi(6);

    // Penalize dead space that no plausible item can use: residual smaller than the
    // smallest possible item is pure waste.
    if post_residual < 1 {
        score += 50.0;
    }

    // Lookahead coupling: bonus if the post-residual exactly accommodates the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 18.0;
        } else if post_residual >= next_item_size {
            score -= 4.0;
        } else {
            // Creating a gap smaller than the next item is mildly bad.
            score += 3.0 * (1.0 - post_residual as f64 / next_item_size as f64);
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Many open bins: prefer consolidating into existing ones; few open bins:
    // spreading is cheaper, so opening a new bin is less penalizing.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += 2.5 * pressure * (post_residual as f64 / bin_capacity as f64);

    // Global mean residual: if this bin's residual is far below the mean it is an
    // outlier with unusable space; penalize leaving it as an outlier.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Time horizon: late in the stream, avoid opening new bins (waste grows),
    // early on, allow some spreading.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate score: baseline slightly above a perfect existing fit.
        score = bin_capacity as f64 - 15.0 * progress - 8.0 * (1.0 - progress);
        if fitting_bins_count <= 1 {
            score -= 30.0; // no real alternative, new bin is fine
        }
        if next_item_size > 0 && next_item_size > bin_capacity {
            score -= 10.0;
        }
    } else {
        score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64) / (total_items.max(1) as f64);
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let base = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early: mild preference for tight fits; Late: strong tightness pressure.
    let tightness = base * base * (1.0 + 2.0 * progress) + 0.35 * base * progress;

    // Smooth reward for near-exact fills (post_residual close to 0).
    let exact_bonus = -2.5 * (1.0 - base).powi(6) * (0.5 + progress);

    // Lookahead coupling: penalize residuals that cannot host the next item,
    // reward residuals that can host it (smooth via normalized difference).
    let nx = next_item_size as f64 / cap;
    if nx > 0.0 {
        if nx <= base {
            -0.8 * (base - nx) * (1.0 - progress)
        } else {
            0.6 * (nx - base) * (nx - base) * (1.0 + progress)
        }
    } else {
        0.0
    };

    // New-bin candidate handling: opening a bin is penalized more when many
    // bins are open and stream is early; mild penalty overall to prefer reuse.
    let is_new_bin = (bin_residual as f64 - cap).abs() < 1e-6;
    let new_bin_penalty = if is_new_bin {
        0.45 + 0.25 * (open_bins_count as f64 / (open_bins_count as f64 + 3.0)) + 0.4 * (1.0 - progress)
    } else {
        0.0
    };

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    let last_chance = if fitting_bins_count == 1 && !is_new_bin {
        -1.2 * (1.0 - progress)
    } else {
        0.0
    };

    // Alignment with mean residual: prefer bins whose post-residual keeps the
    // fleet of residuals balanced (smooth quadratic deviation term).
    let dev = (pr - mean_residual) / cap;
    let balance = 0.25 * dev * dev;

    let mut score = pr as f64;
    score += 100.0 * tightness;
    score += 100.0 * exact_bonus;
    score += 100.0 * new_bin_penalty;
    score += 100.0 * last_chance;
    score += 100.0 * balance;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into a
    // "reusable" class (large enough chunks) are favored.
    let cap = bin_capacity as f64;
    let frac = post_residual as f64 / cap;

    // Class A: post_residual >= 50 -> still half a bin, very reusable.
    if post_residual >= bin_capacity / 2 {
        score -= 12.0;
    }
    // Class B: post_residual in [25, 50) -> medium chunk.
    else if post_residual >= bin_capacity / 4 {
        score -= 4.0;
    }
    // Class C: small dead space (< 25) -> penalize proportionally to deadness.
    else {
        score += 8.0 * (1.0 - frac * 4.0);
    }

    // Integer-division threshold: leftover that exactly matches a harmonic
    // block size (10, 20, 25, 50) is maximally reusable.
    let blocks = [50u32, 25, 20, 10];
    for b in blocks.iter() {
        if post_residual % b == 0 && post_residual > 0 {
            score -= 3.0;
            break;
        }
    }

    // Lookahead: if the next item fits exactly into post_residual, strongly reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 15.0;
        } else if next_item_size <= post_residual {
            score -= 6.0;
        } else {
            // Next item won't fit here; leftover becomes riskier dead space.
            score += 4.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new
    // bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when the current
    // item is large and no open bin offers a tight fit.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 20.0;
        if item_size >= bin_capacity / 2 {
            score -= 25.0; // large items justify fresh capacity
        }
        if next_item_size > 0 && next_item_size > post_residual {
            score -= 10.0; // lookahead won't fit residual bins anyway
        }
    }

    // Tightness reward: near-perfect fits are excellent.
    if post_residual <= 5 {
        score -= 18.0;
    }

    // Mean-residual coupling: when open bins are on average roomy, prefer
    // filling them rather than spreading.
    score += 0.05 * (mean_residual - post_residual as f64);

    // Mild stream-progression pressure: later in the stream, consolidate more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 3.0 * progress * (frac);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (1..=9) are heavily penalized.
    if post_residual > 0 && post_residual <= 9 {
        score += 60.0;
    } else if post_residual <= 19 {
        score += 18.0;
    } else if post_residual <= 39 {
        score += 6.0;
    } else {
        // Larger usable residuals are mildly attractive (room for future items).
        score -= (post_residual.min(60) as f64) * 0.15;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Open-bins pressure: discourage spreading when many bins are open.
    score += (open_bins_count as f64) * 0.35;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward this placement.
    if next_item_size > 0 && post_residual > 0 && next_item_size == post_residual {
        score -= 45.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // Next item fits comfortably: mild reward proportional to tightness.
        score -= 8.0 * (1.0 - (next_item_size as f64) / (post_residual as f64));
    } else if next_item_size > post_residual && post_residual > 0 && post_residual < 10 {
        // Next item won't fit and this bin would be left with a tiny dead gap: extra penalty.
        score += 30.0;
    }

    // New-bin candidate handling: empty bin has residual == capacity.
    if bin_residual == bin_capacity {
        // Prefer new bin only if all existing fits are terrible (tiny dead gaps).
        score = 70.0 + (open_bins_count as f64) * 0.2;
        if fitting_bins_count == 0 {
            score -= 80.0; // no other option: new bin is fine
        }
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 5.0;
        }
    }

    // Late-stream tightness: as the stream progresses, be more conservative with residuals.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 4.0;

    // Mean-residual coupling: if average residual is large, slightly prefer filling fuller bins.
    score -= (mean_residual - post_residual as f64).max(0.0) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
