pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to item size)
    let fit_ratio = post_residual as f64 / (item_size.max(1) as f64);
    score -= 40.0 * (-fit_ratio).exp();

    // Penalize dead space that cannot fit the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // next item fits here: reward synergy
            let slack_after_next = post_residual - next_item_size;
            score -= 8.0 * (slack_after_next as f64 / bin_capacity as f64);
        } else {
            // dead space penalty grows with how much is wasted
            score += 0.35 * post_residual as f64;
            score += 6.0 * (1.0 - (post_residual as f64 / next_item_size.max(1) as f64).min(1.0));
        }
    }

    // Last-chance bonus: only one fitting bin -> strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }
    // When many bins fit, prefer the emptiest usage (spread load)
    if fitting_bins_count > 1 {
        score += 0.6 * (fitting_bins_count as f64).ln();
    }

    // New-bin candidate handling: only open a new bin when open bins are poor fits
    if bin_residual == bin_capacity {
        // mild default penalty so existing bins are preferred unless they are bad
        score += 12.0;
        // but if open bins are very full (low mean residual), opening is attractive
        score -= 0.25 * mean_residual;
        // early in the stream, opening bins is cheap (future flexibility)
        let t = step_index as f64 / (total_items.max(1) as f64);
        score -= 10.0 * (1.0 - t);
        // if next item is large and this fresh bin could host it too, extra reward
        if next_item_size > 0 && next_item_size <= post_residual {
