        }
    } else {
        // Prefer bins whose residual is close to item_size (best-fit flavor)
        let gap = (bin_residual as i64 - item_size as i64).abs() as f64;
        score += 0.15 * gap;
        // Slight preference to fill fuller bins (reduce bin count)
        score -= 0.1 * (bin_residual as f64 / bin_capacity as f64) * 10.0;
    }

    // Late in stream: consolidate aggressively, avoid opening new bins
    let t = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity && t > 0.8 {
        score += 15.0 * t;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Normalized quantities
    let pr = post_residual as f64 / bin_capacity as f64;         // post residual in [0,1]
    let fit = item_size as f64 / bin_capacity as f64;            // item fraction
    let mean_res = mean_residual / bin_capacity as f64;

    // Smooth non-linear coupling: dead-space penalty grows quadratically as post residual shrinks
    let dead_space = (1.0 - pr) * (1.0 - pr) * (1.0 - pr);
    score += 12.0 * dead_space;

    // Reward tight fits more strongly later in the stream (polynomial progress coupling)
    let tightness = 1.0 - pr;
    score -= 30.0 * progress * tightness * tightness;

    // Penalize bins whose residual deviates from mean residual (smooth quadratic dispersion)
    let disp = pr - mean_res;
    score += 8.0 * disp * disp * (0.5 + progress);

    // Last-chance bonus: strongly prefer the only fitting bin, scaled by progress
    if fitting_bins_count == 1 {
        score -= 25.0 + 20.0 * progress;
    } else {
        // Mild crowding penalty for many fitting bins (less valuable placements)
        score += (fitting_bins_count as f64).ln().max(0.0) * 2.0;
    }

    // Lookahead: reward leaving room close to next item size (smooth Gaussian-like kernel)
    if next_item_size > 0 {
        let gap = (post_residual as f64 - next_item_size as f64).abs();
        let kern = (-gap * gap / (2.0 * 15.0 * 15.0)) as f64;
        score -= 18.0 * kern;
    }

    // Slight preference for reusing open bins over opening new ones, decaying with progress
    if bin_residual == bin_capacity {
        score += 6.0 * (1.0 - 0.5 * progress);
    } else {
        score -= 3.0;
    }

    // Cubic progress modulation of base residual weight
    let w = 1.0 + 0.5 * progress * progress * progress;
    score *= w;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space quality classes.
    // Residuals in [0,10] are nearly perfect; [11,30] awkward; >30 reusable.
    let pr = post_residual;
    if pr == 0 {
        score -= 50.0; // perfect fit
    } else if pr <= 10 {
        score -= 20.0 + (10 - pr) as f64;
    } else if pr <= 30 {
        score += 10.0 + (pr - 10) as f64 * 0.5;
    } else {
        score -= 5.0; // large residual still reusable
    }

    // Modulo harmonic classes: residuals that are multiples of common item
    // sizes (10,20,25,50) are more likely to be filled later.
    if pr % 10 == 0 && pr > 0 { score -= 8.0; }
    if pr % 25 == 0 && pr > 0 { score -= 5.0; }
    if pr % 20 == 0 && pr > 0 { score -= 4.0; }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 40.0;
        } else if next_item_size <= pr {
            score -= 12.0;
            // harmonic class match: next item leaves multiple-of-10 residual
            if (pr - next_item_size) % 10 == 0 { score -= 6.0; }
        } else {
            score += 6.0; // next item cannot use this bin's remainder
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Penalize very tight bins slightly less as stream progresses (endgame
    // consolidation), and penalize spreading across many open bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if open_bins_count > 4 {
        score -= 3.0 * progress; // consolidate late in stream
    }

    // Mean residual coupling: prefer bins below mean residual (fill emptier
    // bins keeps tight bins available for small items).
    if (bin_residual as f64) < mean_residual {
        score -= 2.0;
    } else {
        score += 2.0;
    }

    // New-bin candidate: only attractive when item is large relative to
    // typical residuals or no good harmonic class exists.
    if bin_residual == bin_capacity {
        let large_item = item_size > 60;
        let no_good_class = !(pr % 10 == 0 || pr == 0);
        if large_item || no_good_class {
            score -= 4.0;
        } else {
            score += 25.0; // prefer reusing an open bin with good class
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable dead space heavily
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    if post_residual >= 10 && post_residual < 20 {
        score += 15.0;
    }

    // Reward tight fits
    score -= (item_size as f64 / bin_capacity as f64) * 30.0;

    // Last-chance bin bonus
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: fewer open bins -> prefer reusing
    score += (open_bins_count as f64) * 2.0;

    // Prefer bins below mean residual (fill emptier bins less)
    score += (mean_residual - bin_residual as f64).max(0.0) * 0.5;

    // Lookahead: if next item fits in post_residual, reward
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0;
    }
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 10.0;
    }

    // New-bin candidate neutralization: only open new bin when desperate
    if bin_residual == bin_capacity {
        score += 25.0 + open_bins_count as f64 * 0.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward bins whose post_residual exactly matches next item
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0; // chain: current item + next item fills bin exactly
        } else if post_residual > next_item_size {
            // next item still fits after this placement; mild reward for tight chain
            score -= (post_residual - next_item_size) as f64 * 0.5;
        } else {
            // next item cannot follow into this bin; penalize large dead space
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Relative-to-mean coupling: prefer bins tighter than average
    score += (post_residual as f64 - mean_residual) * 0.8;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 300.0;
    }

    // New-bin candidate: penalize opening a new bin unless it enables a perfect
    // 2-step chain and existing fits are poor.
    if bin_residual == bin_capacity {
        let mut penalty = 250.0;
        if next_item_size > 0 && post_residual == next_item_size {
            penalty = 0.0; // perfect chain from fresh bin
        }
        if post_residual == 0 {
            penalty = 0.0;
        }
        if fitting_bins_count > 0 {
            penalty += 150.0 * (fitting_bins_count as f64).ln().max(1.0);
        }
        score += penalty;
    }

    // Prefer consolidating into fewer bins as stream progresses
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += post_residual as f64 * progress * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual near 0 is best.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize dead space that is too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if the next item could use the post-residual, reward this placement.
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        score -= 8.0;
    }
    // If next item is large and would need nearly a full bin, opening a new bin
    // is more attractive: penalize consuming big residuals for small items.
    if next_item_size >= 60 && post_residual > 0 && post_residual < next_item_size {
        score += 6.0;
    }

    // Prefer filling bins with residual below the mean residual (balance).
    score -= 0.15 * (mean_residual - post_residual as f64);

    // Time horizon: early in the stream, be more willing to open new bins
    // (keep residuals large for future flexibility); late, consolidate.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: attractive early, penalized late.
        score += 20.0 * (1.0 - progress) - 10.0 * progress;
        // Never open a new bin if a near-perfect fit exists.
        if fit_ratio > 0.8 {
            score += 50.0;
        }
    } else {
        // Late in stream, favor existing bins more.
        score -= 5.0 * progress;
    }

    // Mild penalty when many bins are open: encourage consolidation.
    score += 0.3 * open_bins_count as f64 * (1.0 - fit_ratio);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr_norm = pr / cap;

    // Base: quadratic in post-residual, modulated by stream progress
    let mut score = pr * (1.0 + 0.8 * pr_norm * pr_norm);

    // Early in the stream, tolerate loose fits (keep bins flexible); later, punish dead space
    score += pr * (0.5 + 1.2 * progress);

    // Perfect / near-perfect fits get strong reward, stronger late in stream
    if post_residual == 0 {
        score -= 60.0 + 40.0 * progress;
    } else if post_residual < 10 {
        score -= 30.0 + 20.0 * progress;
    } else if post_residual < 20 {
        score -= 10.0 + 10.0 * progress;
    }

    // Last-chance bin: strong reward so we don't open a new bin unnecessarily
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Lookahead coupling: reward if next item fits the post-residual, punish near-miss
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            score -= 15.0 * (1.0 - (nxt / (pr + 1.0)).powi(2));
        } else {
            score += 10.0 * ((nxt - pr) / cap);
        }
    }

    // Prefer bins with residual below mean (tighter bins) — smooth coupling
    score += 0.3 * (pr - mean_residual);

    // New-bin candidate: opening a new bin should be penalized unless it enables a tight fit
    if bin_residual == bin_capacity {
        score += 45.0 - 25.0 * (1.0 - (pr_norm - 0.2).powi(2)).max(-1.0);
        // Late in stream, new bins are cheaper to justify
        score -= 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: quantize leftover space into
    // capacity fractions (eighths). Residuals that fall into "useful"
    // classes (large enough to host typical small items) are rewarded.
    let eighth = bin_capacity as f64 / 8.0;
    let class = (post_residual as f64 / eighth).floor() as i32; // 0..=8

    // Dead-space penalty: residuals too small for the smallest plausible
    // item (<= 12) are nearly unusable -> heavy penalty.
    if post_residual < 12 {
        score += 40.0;
    }

    // Reward classes that leave a "harmonic" residual (close to multiples
    // of 25 or 50), since those pair well with common item sizes.
    let r = post_residual as i64;
    let harmonic_bonus = match r % 50 {
        0 => 25.0,
        25 => 18.0,
        _ => {
            let d = (r % 25).min(25 - (r % 25));
            8.0 - d as f64
        }
    };
    score -= harmonic_bonus;

    // Class-based shaping: mid classes (residual 25..=60) are prime slots;
    // very large residual classes are less urgent to fill.
    score += (class as f64 - 4.0).abs() * 3.0;

    // Integer-division threshold on item_size vs residual: exact fit tiers.
    if bin_residual == item_size {
        score -= 100.0; // perfect fill, close the bin
    } else if post_residual == 0 {
        score -= 100.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // strongly favor this bin (chained harmonic pairing).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // next item fits: penalize proportional to wasted pairing gap
            let gap = post_residual - next_item_size;
            score -= 20.0 - gap as f64 * 0.4;
        } else {
            // next item cannot fit here: mild penalty scaled by how far off
            score += ((next_item_size - post_residual) as f64) * 0.15;
        }
    }

    // Last-chance bin: if this is the only fitting bin, using it avoids
    // opening a new bin -> reward, unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 + (bin_residual - item_size) as f64 * 0.1;
    }

    // New-bin candidate handling: an empty bin is attractive only when the
    // item is large relative to capacity or open bins are poorly loaded.
    if bin_residual == bin_capacity {
        let load_ratio = item_size as f64 / bin_capacity as f64;
        let pressure = (open_bins_count as f64).ln().max(0.0);
        // Penalize new bins mildly; reward when item is huge (needs own bin)
        score += 10.0 - load_ratio * 30.0 + pressure * 2.0;
        if item_size >= 60 {
            score -= 25.0; // big items are better in fresh bins
        }
    }

    // Stream progression: late in the stream, prefer tighter packs.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0;

    // Mean-residual coupling: if this bin's residual is far below the mean,
    // it is already fragmented; penalize adding to it.
    let dev = mean_residual - post_residual as f64;
    if dev > 0.0 {
        score += dev * 0.2;
    } else {
        score += dev * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: post_residual in [1, 9] is nearly unusable
    // (items are >= 1 but small gaps rarely get filled) -> heavy penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (1.0 - (post_residual as f64) / 10.0);
    }

    // Perfect fit is ideal.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Reward tight fits relative to residual (best-fit flavor).
    score -= 30.0 * (item_size as f64 / bin_residual.max(1) as f64);

    // Dead space relative to capacity: large leftover gaps are wasteful.
    score += 0.3 * (post_residual as f64 / bin_capacity as f64) * (post_residual as f64);

    // Open bins pressure: discourage opening new bins when many are open.
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive if current bins are badly fragmented.
        score += 25.0 + 2.0 * open_bins_count as f64;
        score -= 0.5 * mean_residual;
        // If this item is a last chance in the only fitting bin, opening a new bin is bad.
        if fitting_bins_count == 1 {
            score += 80.0;
        }
        // If next item could combine with current one in a fresh bin, mildly favor it.
        if next_item_size > 0 && (next_item_size as f64 + item_size as f64) <= bin_capacity as f64 {
            score -= 10.0;
        }
    } else {
        // Existing bin: last-chance bonus to avoid wasting near-full bins.
        if fitting_bins_count == 1 {
            score -= 40.0;
        }
        // Lookahead: if next item exactly fills the post residual, strong reward.
        if next_item_size > 0 && next_item_size == post_residual {
            score -= 70.0;
        } else if next_item_size > 0 && next_item_size > post_residual {
            // Next item can't use the gap; penalize proportionally to gap smallness.
            if post_residual < next_item_size && post_residual < 15 {
                score += 25.0;
            }
        }
        // Slight preference for fuller bins among open bins (reduce fragmentation).
        score -= 1.5 * (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    }

    // Mild stream-progression term: later in stream, be more conservative
    // about spreading items across bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (item_size as f64 / bin_capacity as f64);

    // Tie-break by mean residual: prefer bins below mean residual (fuller bins).
    score += 0.1 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to item size)
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 8.0 * tightness;

    // Aggressive 2-step lookahead: reward if next item fits perfectly into post_residual
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0; // perfect two-item packing
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item cannot follow here; penalize proportionally to leftover dead space
            let gap = (next_item_size - post_residual) as f64;
            score += 10.0 * (gap / 100.0).min(1.0);
        }
    } else {
        // last item: strongly prefer fullest packing
        score += 2.0 * post_residual as f64;
    }

    // Penalize creating tiny unusable residues (dead space)
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Relative to mean residual: prefer bins with residual below mean (denser bins)
    score += 0.5 * (bin_residual as f64 - mean_residual);

    // Last-chance bin bonus: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fits are bad
    if bin_residual == bin_capacity {
        score += 45.0;
        // allow new bin late in stream when mean residual is small
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 30.0 * progress;
        // strongly discourage new bin if next item is small and could share
        if next_item_size > 0 && next_item_size <= post_residual {
            score += 20.0;
        }
    }

    // Slight penalty per open bin to encourage consolidation
    score += 0.3 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer tight fits: reward small post_residual non-linearly.
    if post_residual == 0 {
        score -= 50.0;
    } else {
        let pr = post_residual as f64;
        score += (pr * pr) / bin_capacity as f64;
    }

    // Penalize creating dead space that the next item cannot use.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as f64) < nxt {
            // wasted gap smaller than next item
            score += (nxt - post_residual as f64) * 0.8;
        } else {
            // gap usable by next item: reward
            score -= 5.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Many open bins with high mean residual: prefer filling existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let crowding = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
    score += crowding * 0.3 * (1.0 - progress);

    // New-bin candidate handling: only attractive when current bins fit poorly.
    let is_new_bin = bin_residual == bin_capacity && item_size < bin_capacity;
    if is_new_bin {
        let avg_waste = mean_residual - post_residual as f64;
        // open new bin if it would be a very tight fit and existing bins are loose
        if post_residual as f64 <= 5.0 && mean_residual > 20.0 {
            score -= 60.0;
        } else {
            score += 40.0 + avg_waste.abs() * 0.1;
        }
    }

    // Late in stream: consolidate; early: allow flexibility (keep some slack).
    score -= (1.0 - progress) * 3.0;
    score += progress * (post_residual as f64) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr as f64;
    // smooth non-linear coupling of post-residual with stream progress
    score += 12.0 * norm_pr * norm_pr * (progress * (1.0 - progress) * 4.0 + 0.25);
    score -= 8.0 * (norm_pr * (1.0 - norm_pr)) * (1.0 - progress);
    // penalize tight fits that leave dead space relative to next item
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).max(0) as f64;
        score -= 6.0 * (gap / cap) * (1.0 - progress);
        score += 4.0 * ((next_item_size as f64 - pr).max(0.0) / cap).powi(2);
    }
    // last-chance bonus
    if fitting_bins_count == 1 {
        score -= 10.0 * (1.0 - progress);
    }
    // mild pressure toward consolidating into few bins
    score += 0.5 * (open_bins_count as f64 / (mean_residual.max(1.0) / cap).max(1.0)) * 0.01;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-fit residual: residues mod 10 and mod 20
    let r = post_residual;
    let r10 = (r % 10) as f64;
    let r20 = (r % 20) as f64;

    // Penalize residuals that fall into "dead" classes: small nonzero leftovers
    // that few typical item sizes can ever fill.
    if r > 0 && r < 10 {
        score += 25.0 - 2.0 * r as f64; // worst dead space class
    } else if r >= 10 && r < 20 {
        score -= 6.0 - r10 * 0.6; // mild reward, mod-10 residue 0 best
    } else {
        score -= r10 * 0.4; // reward low mod-10 residue
        score -= (20.0 - r20) * 0.1; // reward low mod-20 residue
    }

    // Perfect fit reward
    if r == 0 {
        score -= 40.0;
    }

    // Harmonic thresholds on post_residual via integer division
    let q = r / 10;
    score -= q as f64 * 1.5;

    // Lookahead coupling: does next item fit harmonically into post_residual?
    if next_item_size > 0 {
        if next_item_size <= r {
            let nr20 = (next_item_size % 20) as f64;
            score -= 8.0 + nr20 * 0.1;
            // exact next-fit bonus
            if next_item_size == r {
                score -= 20.0;
            }
        } else {
            score += 6.0; // next item won't fit here; deprioritize
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when current bins are badly fragmented
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = (mean_residual - post_residual as f64).abs();
        // open a new bin if mean residual of open bins is small (fragmented)
        score = 60.0 + fragmentation * 0.3 - progress * 10.0 + open_bins_count as f64 * 0.5;
        if item_size > 60 {
            score -= 15.0; // big items like fresh bins
        }
        if mean_residual < 15.0 {
            score -= 25.0;
        }
    }

    // Mild penalty for spreading across too many bins
    score += open_bins_count as f64 * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize dead space: residuals too small to hold even the smallest item (1..10)
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Penalize residuals that can't fit the lookahead item (k=2 lookahead)
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size as f64 {
        score += 25.0;
    }

    // Reward tight fits
    score -= 8.0 * (item_size as f64 / bin_residual as f64);

    // Open-bin pressure: penalize using bins when many are open
    score += 0.8 * open_bins_count as f64;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Mean residual alignment: favor bins whose residual is near the mean (balanced packing)
    score += 0.3 * ((bin_residual as f64 - mean_residual).abs());

    // Late-stream consolidation: penalize opening new bins late in the stream
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 15.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
