pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (non-linear).
    score += (post_residual as f64 / bin_capacity as f64).powi(3) * 40.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Penalize dead space that no plausible future item can use.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny unusable sliver
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Lookahead: if next item fits exactly in the post residual, reward heavily.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 50.0;
        } else if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            // next item won't fit here; slight penalty proportional to leftover
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    } else {
        // Last item: just minimize waste.
        score -= 20.0;
    }

    // Prefer bins with residual below mean residual (consolidate large holes).
    score += (mean_residual - bin_residual as f64) * 0.5;

    // Early in stream: keep bins flexible, mild penalty for very low post residual
    // (leave room for future items); late in stream: pack greedily.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress < 0.5 {
        score += post_residual as f64 * 0.1;
    } else {
        score -= post_residual as f64 * 0.05;
    }

    // Mild bonus for using crowded bins (reduce open bin count pressure).
    if open_bins_count > 4 {
        score -= 3.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is bad.
    if bin_residual == bin_capacity {
        let tight = post_residual as f64 / bin_capacity as f64;
        if tight < 0.05 {
            score -= 15.0; // great fit elsewhere, don't open new bin
        } else if fitting_bins_count == 0 {
            score -= 40.0; // nothing fits, must open
        } else {
            score += 20.0 + tight * 30.0; // discourage wasteful new bins
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let t = progress;
    let prn = pr / cap;
    let coupling = prn * prn * (1.0 + 2.0 * t) + prn * (1.0 - t) * (1.0 - t);
    score += 20.0 * coupling;

    // Reward tight fits (small post_residual) more aggressively as stream progresses
    let tightness = 1.0 - prn;
    score -= 15.0 * t * tightness * tightness;

    // Penalize dead space: residuals too small for typical future items
    let min_future = if next_item_size > 0 { next_item_size as f64 } else { 10.0 };
    if pr < min_future {
        score += 12.0 * (min_future - pr) / cap;
    }

    // Reward lookahead compatibility: post_residual fits next item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 * (next_item_size as f64) / cap * (0.5 + 0.5 * t);
    }

    // Last-chance bin bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 + t);
    }

    // Mild penalty when many bins are open and this one is far from mean residual
    let dev = (pr - mean_residual).abs();
    score += 0.05 * dev * (open_bins_count as f64).sqrt() * (1.0 + t);

    // Slight preference for fuller bins overall
    score -= 5.0 * (it / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: perfect fills (0) strongly rewarded.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Dead-space classes: residuals that few item sizes (1..=100) can still use.
    // A residual r can host items of size 1..=r, but typical stream items are coarse;
    // penalize residuals in "awkward" bands via modulo arithmetic on capacity fractions.
    let cap_quarter = bin_capacity / 4;           // 25
    let cap_tenth = bin_capacity / 10;            // 10
    let awkward = post_residual % (cap_quarter + cap_tenth); // mod 35 harmonic class
    score += awkward as f64 * 0.7;

    // Integer-division thresholds: residuals < smallest plausible item are dead.
    if post_residual < cap_tenth {
        score += 120.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        if post_residual == next_item_size {
            score -= 400.0;
        } else {
            score -= (next_item_size as f64) * 0.5;
            // harmonic match: next item divides remaining space evenly
            if post_residual % next_item_size == 0 {
                score -= 60.0;
            }
        }
    } else if next_item_size > 0 && post_residual < next_item_size {
        // next item cannot use this bin's leftover: penalize proportional to waste
        score += (next_item_size as f64 - post_residual as f64) * 0.4;
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 300.0;
    }

    // New-bin candidate handling: empty bin gets a moderate default so that
    // only genuinely bad fits in open bins trigger opening a new bin.
    if bin_residual == bin_capacity {
        score = 500.0
            - (item_size as f64) * 0.5
            + (open_bins_count as f64) * 2.0;
        // late in the stream, prefer reusing bins even more
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 100.0;
        return score;
    }

    // Tight fits are good: reward small post_residual relative to item size.
    score -= (item_size as f64) / (bin_residual.max(1) as f64) * 30.0;

    // Prefer bins with residual above the mean (keep big holes flexible is bad;
    // actually prefer filling below-mean-residual bins to homogenize open bins).
    if (bin_residual as f64) < mean_residual {
        score -= 25.0;
    } else {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable gaps hard: post_residual in (0, 10) is dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }
    // Perfect fit gets strong reward.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Reward using bins whose residual is tight (low waste relative to capacity).
    let tightness = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= 8.0 * tightness;

    // Pressure from number of open bins: prefer consolidating when many bins open.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.6 * open_bins_count as f64 * (0.5 + progress);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Lookahead: if next item fits in the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    }
    // If next item would leave a dead gap, penalize slightly.
    if next_item_size > 0 && post_residual >= next_item_size && (post_residual - next_item_size) < 10 && (post_residual - next_item_size) > 0 {
        score += 6.0;
    }

    // New-bin candidate: make it moderately attractive only when open bins are wasteful.
    if bin_residual == bin_capacity {
        score += 5.0 * mean_residual / bin_capacity as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect-fit reward: item exactly fills the bin.
    if post_residual == 0 {
        score -= 100.0;
    }

    // 2-step lookahead: strongly reward bins whose post_residual matches next_item_size.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;
        if nxt <= pr {
            let gap = pr - nxt;
            if gap == 0.0 {
                // Next item will exactly fill this bin: excellent 2-chain.
                score -= 80.0;
            } else {
                // Reward closeness of next item to post_residual (tight 2-chain).
                let tightness = 1.0 - (gap / bin_capacity as f64);
                score -= 40.0 * tightness * tightness;
            }
            // Penalize leaving dead space the next item cannot use.
            score += gap * 0.5;
        } else {
            // Next item cannot fit in this bin's leftover: dead-space penalty.
            score += (pr - nxt).abs() * 0.3;
        }
    }

    // Compare post_residual against mean residual: prefer bins ending below-average residual
    // (consolidating space), penalize creating above-average leftover.
    if post_residual as f64 > mean_residual {
        score += (post_residual as f64 - mean_residual) * 0.4;
    } else {
        score -= (mean_residual - post_residual as f64) * 0.2;
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin early in the stream
    // (plenty of open bins can usually absorb the item), relax late.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 + 30.0 * (1.0 - progress);
        // But if next item is large and this item is small, a fresh bin is attractive.
        if next_item_size > item_size * 2 {
            score -= 20.0;
        }
    }

    // Slight penalty for spreading across too many open bins.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual relative to item size.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 25.0 * tightness * tightness;

    // Lookahead: if the next item fits exactly into post_residual, strongly reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            let fill = next_item_size as f64 / post_residual as f64;
            score -= 15.0 * fill;
        } else {
            // Next item cannot use leftover space; penalize large leftovers.
            score += (post_residual as f64) * 0.15;
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        // Many alternatives: mildly penalize wasting a scarce residual.
        if post_residual < 15 {
            score -= 10.0; // still reward near-perfect closures
        } else {
            score += 5.0 * (fitting_bins_count as f64).ln();
        }
    }

    // Prefer bins with residuals below the mean (consolidate small spaces).
    let dev = (bin_residual as f64) - mean_residual;
    score += 0.2 * dev;

    // Time horizon: early in stream, encourage filling existing bins to limit bin count;
    // late in stream, be more tolerant of opening new bins for clean splits.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= (1.0 - progress) * 10.0 * (post_residual as f64) / (bin_capacity as f64);

    // Penalize fragmentation: leftover in (20..40) is awkward dead space.
    if post_residual >= 20 && post_residual <= 40 {
        score += 8.0;
    }

    // Brand-new bin candidate: only attractive for large items or very poor fits elsewhere.
    if bin_residual == bin_capacity {
        if item_size > 60 || next_item_size == 0 {
            score += 5.0; // slight default penalty; existing bins usually preferred
        } else {
            score += 20.0;
        }
        // Late in stream with many bins, a fresh bin can enable perfect future packing.
        if progress > 0.7 && item_size <= 50 {
            score -= 12.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let x = post / cap;

    // Smooth non-linear base: quadratic in normalized post-residual
    let mut score = 2.0 * x - 1.5 * x * x;

    // Polynomial coupling of post_residual with stream progress:
    // early on, prefer tight fills (low post residual); later, conserve flexibility
    let coupling = (x * x - x) * (0.5 + 2.0 * progress * (1.0 - progress) * 4.0);
    score += coupling;

    // Dead-space penalty grows smoothly with progress
    score += progress * (x * x * x) * 3.0;

    // Last-chance bin: reward strongly, modulated by progress
    if fitting_bins_count == 1 {
        score -= 5.0 + 3.0 * progress;
    }

    // Lookahead: bonus if next item fits the post-residual exactly-ish
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let fit_quality = 1.0 - ((post - nxt) / cap).abs();
            score -= 1.5 * fit_quality;
        } else {
            score += 0.5 * ((nxt - post) / cap);
        }
    }

    // Mild preference for bins deviating from mean residual (diversity of sizes)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 0.3 * dev * dev - 0.2 * dev;

    // Slight penalty for opening new bins when many bins already fit
    if bin_residual == bin_capacity {
        score += 0.8 + 0.02 * open_bins_count as f64;
        if fitting_bins_count == 0 {
            score -= 2.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into
    // "usable" classes (large enough for typical future items) are rewarded.
    let cap_f = bin_capacity as f64;
    let post_f = post_residual as f64;

    // Class A: post_residual == 0 -> perfect fit, strong reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Class B: post_residual divisible by 10 -> "harmonic" leftover that
    // pairs well with common item sizes; mild reward.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 8.0;
    }

    // Class C: dead-space class — leftover too small for the smallest item
    // (1) is impossible, but leftover smaller than a typical chunk is bad.
    // Penalize leftovers in (0, 10): unusable sliver.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            // next item fits with some slack: reward proportional to tightness
            let tight = 1.0 - ((post_residual - next_item_size) as f64) / cap_f;
            score -= 20.0 * tight;
        } else {
            // next item cannot use this leftover at all: penalize large leftovers
            score += 6.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: discourage opening a new bin when a reasonable fit
    // exists in an open bin; encourage it when the item fits poorly everywhere.
    if bin_residual == bin_capacity {
        // Baseline score for a fresh bin: its post_residual equals capacity - item.
        // Add a mild opening cost, reduced late in the stream or with many bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 + 8.0 * (1.0 - progress);
        // If no open bin fits (this is the only option), remove the cost.
        if open_bins_count == 0 || fitting_bins_count == 0 {
            score -= 18.0;
        }
    }

    // Coupling with mean residual: placing into a bin far below mean residual
    // (i.e., keeping fat bins fat) balances the pool; slight reward.
    let dev = mean_residual - post_f;
    if dev > 0.0 {
        score -= 0.05 * dev;
    } else {
        score -= 0.05 * dev; // symmetric pull toward mean
    }

    // Integer-division threshold: leftover >= half capacity is a "rich" bin,
    // keep it rich only if item is small; penalize burning big bins on small items.
    if post_residual * 2 >= bin_capacity && item_size <= bin_capacity / 4 {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for the
    // minimum plausible item are "dead". Penalize them quadratically.
    let dead_threshold = 10.0f64; // smallest typical item size
    if (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64).powi(2) * 3.0;
    }

    // Reward tight fits (small but usable post residual).
    let post = post_residual as f64;
    if post > 0.0 && post <= 20.0 {
        score -= 15.0 * (1.0 - post / 20.0);
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly in post_residual, strong reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        if gap <= 10.0 {
            score -= 20.0 * (1.0 - gap / 10.0);
        } else {
            score -= 5.0;
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        // Next item won't fit here: penalize leaving a gap that strands space.
        score += 8.0;
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bins pressure: with many open bins, prefer consolidating into
    // existing bins rather than opening new ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64).ln() * (1.0 + progress);
    score += pressure * 2.0;

    // New-bin candidate handling: an empty bin gets a baseline cost so it is
    // only chosen when existing bins are genuinely poor fits.
    if bin_residual == bin_capacity {
        score += 10.0 + mean_residual * 0.3;
        // Late in the stream, opening fresh bins is more acceptable.
        score -= 15.0 * progress;
    } else {
        // Prefer bins whose residual is below average (tighter bins first).
        score += (mean_residual - bin_residual as f64).max(0.0) * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward perfect / near-perfect fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 300.0;
    }

    // 2-step lookahead: if the next item fits exactly into the post residual,
    // this bin becomes perfectly packed over two steps — huge reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 800.0;
        } else if post_residual > next_item_size && post_residual - next_item_size <= 5 {
            score -= 400.0;
        } else if next_item_size > post_residual && next_item_size <= bin_residual {
            // next item won't fit here after this placement; mild penalty for
            // leaving a gap the next item can't use.
            score += 40.0;
        }
    }

    // Relative-to-mean coupling: bins with residual below mean are "tighter"
    // and should be preferred to consolidate waste.
    let resid_f = bin_residual as f64;
    if mean_residual > 0.0 {
        if resid_f < mean_residual {
            score -= (mean_residual - resid_f).min(50.0);
        } else {
            score += (resid_f - mean_residual) * 0.3;
        }
    }

    // Last-chance bin: if this is the only bin that can fit the item,
    // strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 250.0;
    }

    // Penalize dead space proportional to how unusable the gap likely is.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // tiny slivers are hard to fill
    }

    // New-bin candidate: only attractive late in the stream or when open bins
    // are all tight; otherwise discourage opening a new bin.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let tightness = if mean_residual > 0.0 { (mean_residual / bin_capacity as f64).min(1.0) } else { 0.0 };
        score = 200.0 + progress * 100.0 - tightness * 150.0;
        if fitting_bins_count == 0 {
            score -= 500.0; // no open bin fits, must open new bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (low post_residual) with a non-linear term.
    score += (post_residual as f64 / bin_capacity as f64).powi(3) * 40.0;

    // Perfect fit bonus: eliminate dead space entirely.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Penalize leaving dead space that no plausible item (1..=100) can use well:
    // residuals in 1..=9 are nearly unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post_residual,
    // reward heavily; if next item cannot fit, mildly penalize.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            score -= 8.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            score += 5.0;
        }
    } else {
        // Last item: prefer closing bins as tightly as possible.
        score += post_residual as f64 * 0.5;
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // Many fitting bins: we can afford to be picky, punish loose fits more.
    if fitting_bins_count > 2 {
        score += post_residual as f64 * 0.3;
    }

    // Compare against mean residual: placing into bins far below the mean
    // residual (i.e., small residual already) balances the open-bin pool.
    let diff = mean_residual - bin_residual as f64;
    score += diff * 0.15;

    // New-bin candidate handling: an empty bin has high raw score via
    // post_residual already; add a dynamic penalty that decays over the stream,
    // encouraging reuse of open bins early but allowing new bins later when
    // fragmentation dominates.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let avg_open = mean_residual.max(0.0);
        // Penalize new bins more when open bins still have usable space.
        score += 30.0 + avg_open * 0.4 - progress * 15.0;
    }

    // Mild preference to fill bins with larger residuals when many bins are open
    // (consolidation pressure).
    score -= (bin_residual as f64 / bin_capacity as f64) * (open_bins_count.min(20) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let mut score = pr
        + 24.0 * pr_norm * pr_norm * (0.5 + progress)
        + 60.0 * pr_norm * pr_norm * pr_norm * (1.0 - progress);

    // Reward tight fits, stronger late in the stream
    let tightness = 1.0 - pr_norm;
    score -= 30.0 * tightness * tightness * (0.4 + 0.6 * progress);

    // Penalize dead space that cannot fit the next item (lookahead coupling)
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if pr < ni {
            score += 18.0 * (ni - pr) / cap * (0.5 + progress);
        } else {
            score -= 10.0 * (pr - ni) / cap;
        }
    }

    // Last-chance bin bonus: avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 {
        score -= 25.0 + 20.0 * progress;
    }

    // Mild penalty when many bins are open (encourage consolidation)
    score += (open_bins_count as f64).ln() * pr_norm * 8.0;

    // Nudge toward bins with residuals near the mean (smooth interaction)
    score += 6.0 * ((pr - mean_residual) / cap).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fits are excellent: reward small post_residual.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 10 {
        score -= 60.0;
    } else if post_residual <= 20 {
        score -= 25.0;
    }

    // Harmonic classes: residual slots divisible into common item sizes (1..100).
    // A post_residual that is an exact multiple of a small class size (5, 10, 20, 25, 50)
    // is reusable by future items -> reward.
    let pr = post_residual;
    if pr > 0 {
        let mut reusable = false;
        for class in [5u32, 10, 20, 25, 50] {
            if pr % class == 0 && pr >= class {
                reusable = true;
                break;
            }
        }
        if reusable {
            score -= 15.0;
        } else {
            // Dead space in awkward sizes is penalized more as it shrinks.
            if pr < 10 {
                score += 30.0;
            }
        }
    }

    // Lookahead: if next item fits exactly in post_residual, strongly favor this bin.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 40.0;
        if next_item_size == post_residual {
            score -= 60.0;
        }
        // Harmonic check: next item leaves a class-aligned residual again.
        let npr = post_residual - next_item_size;
        if npr % 10 == 0 || npr % 25 == 0 {
            score -= 10.0;
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        // Post-residual too small for next item: potential dead space.
        score += (post_residual as f64) * 0.5;
    }

    // Last-chance bin: if this is the only fitting bin, prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: neutral-ish baseline; open a new bin only when the best
    // existing fit is poor (large post_residual or dead-space class).
    if bin_residual == bin_capacity {
        // Compete with poor fits: new bin looks good when existing options are bad.
        // Score for new bin = item_size (post_residual = capacity - item_size),
        // adjusted by stream progress and open-bin count.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += (open_bins_count as f64) * 2.0 * (1.0 - progress);
        if item_size >= 50 {
            // Large items into fresh bins is fine.
            score -= 20.0;
        }
    }

    // Mean-residual coupling: if this bin's residual is far below the mean,
    // it's already fragmented; discourage adding more fragmentation.
    let diff = mean_residual - bin_residual as f64;
    if diff > 20.0 {
        score += diff * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold
    // typical future items are dead weight -> heavy penalty.
    let min_item = 1u32;
    if post_residual > 0 && post_residual < 10 {
        // unusable sliver of space
        score += 40.0;
    } else if post_residual == 0 {
        // perfect fit: strongly reward
        score -= 60.0;
    }

    // Reward tight fits relative to bin size (low relative waste).
    let tightness = (bin_residual - post_residual) as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * tightness;

    // Dead-space danger zone: residual just above min_item but below a
    // comfortable chunk (e.g. < 25) is likely wasted.
    if post_residual >= 1 && post_residual < 25 {
        score += 15.0 * (25.0 - post_residual as f64) / 25.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidation.
    score += 0.8 * open_bins_count as f64;

    // Last-chance bin: if this is the only fitting bin, strongly prefer it
    // over opening a new bin (unless post_residual is a tiny sliver).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
        if post_residual < 10 {
            score += 40.0; // undo: dead space outweighs last-chance benefit
        }
    }

    // Lookahead: if the next item fits the post-residual exactly-ish, reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 12.0 * (1.0 - slack / 50.0).max(0.0);
    } else if next_item_size > post_residual as u32 && post_residual > 0 {
        score += 8.0; // next item won't fit here: slight penalty
    }

    // Mean residual coupling: placing into a bin far below mean residual
    // leaves other bins high; prefer bins near/below mean.
    let dev = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    score += 10.0 * dev;

    // New-bin candidate handling: an empty bin has huge post_residual;
    // keep it attractive only when open-bin fits would create dead space.
    if bin_residual == bin_capacity {
        // baseline competitiveness: new bin raw score = post_residual (large).
        // give it a mild bonus so it wins only when open bins score badly.
        score -= 5.0;
        if fitting_bins_count == 0 {
            score -= 50.0; // no alternative: must open new bin
        }
        // early in stream, opening bins is cheap; late, consolidate.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fills strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 300.0;
    } else if post_residual <= 10 {
        score -= 120.0;
    }

    // Aggressive 2-step lookahead: exact match of post_residual with next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual > next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 100.0 / (1.0 + slack);
        } else {
            // next item cannot follow into this bin: penalize dead space
            let dead = (next_item_size - post_residual) as f64;
            score += 0.5 * dead;
        }

        // Two-item exact chain: item + next == residual exactly
        if post_residual == next_item_size && item_size + next_item_size == bin_residual {
            score -= 200.0;
        }
    }

    // Relative to mean residual: prefer bins whose post_residual is close to mean
    // (keeps residuals homogeneous), unless it is a tight fit.
    let pr = post_residual as f64;
    let dev = (pr - mean_residual).abs();
    score += 0.3 * dev;

    // Last chance bin: strong bonus to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 250.0;
    }

    // New-bin candidate: penalize opening a new bin, more when many bins open
    // or early in the stream, less when the item is huge (poor fit anywhere).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 200.0 + 20.0 * open_bins_count as f64 - 100.0 * progress;
        if item_size >= 70 {
            score -= 150.0; // big items: fresh bin is often fine
        }
    }

    // Prefer tighter current fits (smaller residual before placement).
    score += 0.2 * bin_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is already low, but amplify.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize dead space that is too small to be useful later.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, big reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 20.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // next item can't use this residual; slight penalty if residual is wasted-large
        score += 0.05 * post_residual as f64;
    }

    // New-bin candidate handling: only attractive when open bins are congested.
    if bin_residual == bin_capacity {
        let congestion = open_bins_count as f64 / (fitting_bins_count.max(1) as f64);
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // penalize opening a new bin when good fitting bins exist
        score += 25.0 / congestion.max(1.0);
        // late in stream, prefer reusing open bins even more
        score += 10.0 * progress;
        // if mean residual is large, open bins have room; penalize new bin
        score += 0.1 * mean_residual;
    }

    // Mild bonus for balancing residual against mean residual (avoid extremes).
    score += 0.03 * (bin_residual as f64 - mean_residual).abs();

    // Time-horizon coupling: early stream, slightly prefer filling bins fully.
    let t = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * (1.0 - t) * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let item = item_size as f64;
    let nxt = next_item_size as f64;

    // Core: quadratic dead-space penalty, sharpened late in the stream.
    let mut score = pr * (1.0 + 1.5 * progress * norm_pr);

    // Smooth interaction: residual relative to mean residual across bins.
    score += 0.4 * (pr - mean_residual) * (0.5 + progress);

    // Reward tight fits (small post_residual) super-linearly.
    score -= 30.0 * (1.0 - norm_pr).powi(3) * (0.6 + 0.4 * progress);

    // Last-chance bonus: strongly favor the only bin that fits.
    if fitting_bins_count == 1 {
        score -= 25.0 + 20.0 * progress;
    }

    // Lookahead: reward if next item fits exactly into post_residual.
    if nxt > 0.0 && nxt <= pr {
        let gap = pr - nxt;
        score -= 12.0 * (1.0 - gap / cap).powi(2);
    } else if nxt > pr {
        // Penalize blocking the next item.
        score += 8.0 * ((nxt - pr) / cap);
    }

    // New-bin candidate: penalize mildly early, more when open bins are few,
    // but relax penalty if this bin would be near-perfectly packed by item.
    if bin_residual == bin_capacity {
        let pack = item / cap;
        score += 15.0 + 10.0 * progress - 20.0 * pack.powi(2);
        // Discourage hoarding many open bins early.
        score += (open_bins_count as f64).powf(0.5) * 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the item: quarter-capacity classes
    let quarter = bin_capacity / 4;
    let item_class = item_size / quarter.max(1);
    let post_class = post_residual / quarter.max(1);

    // Reward tight fits: low post_residual, especially exact or near-exact fits
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= quarter / 2 {
        score -= 25.0;
    }

    // Penalize post_residual classes that are hard to fill later
    // (residuals in mid classes are "dead space" magnets)
    let dead_penalty = match post_class {
        0 => -10.0,           // tiny leftover: fine
        1 => 5.0,             // quarter-class leftover: moderately usable
        2 => 12.0,            // half-class leftover: awkward
        _ => 3.0,             // large leftover: still flexible
    };
    score += dead_penalty;

    // Modulo-10 harmonic structure: residual divisible by 10 pairs well
    // with typical item sizes drawn on a 10-grid
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 8.0;
    }
    if post_residual % 10 != 0 && post_residual < quarter {
        score += 6.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, strong reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            // next item fits: reward proportional to how well it packs
            let npost = post_residual - next_item_size;
            score -= 20.0 - (npost as f64) * 0.2;
        } else {
            // next item won't fit here: mild penalty if this bin was a good host
            score += 5.0;
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 18.0;
    }

    // New-bin candidate handling: empty bin gets neutral-ish score so it wins
    // only when open bins would create bad fits
    if bin_residual == bin_capacity {
        score = (bin_capacity as f64) * 0.5
            - (item_size as f64) * 0.3
            - if fitting_bins_count == 0 { 40.0 } else { 0.0 };
    }

    // Slight pressure against bin proliferation late in the stream
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * (0.3 + 0.5 * progress);

    // Mild attraction toward bins whose residual is above mean (spread the load)
    score -= (bin_residual as f64 - mean_residual) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps hard.
    if post_residual > 0 {
        if post_residual < 10 {
            score += 40.0; // tiny dead space is worst
        } else if post_residual <= 20 {
            score += 15.0;
        } else if post_residual <= 35 {
            score += 5.0;
        } else {
            score -= 10.0; // large residual still reusable
        }
    } else {
        score -= 30.0; // perfect fit
    }

    // Reward tight relative fit.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 25.0 * fill_ratio;

    // Open-bin pressure: prefer consolidating into existing bins.
    score += 3.0 * open_bins_count as f64;

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: only attractive when item is large or no good fit exists.
    if bin_residual == bin_capacity {
        let big_item = item_size as f64 > 0.7 * bin_capacity as f64;
        if big_item || fitting_bins_count == 0 {
            score -= 20.0;
        } else {
            score += 45.0; // discourage opening new bins when fits exist
        }
    }

    // Lookahead: favor bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size && post_residual > 0 {
            score -= 12.0;
        } else if post_residual > 0 && post_residual < next_item_size {
            score += 8.0;
        }
    }

    // Late in stream: slightly stronger consolidation.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * (mean_residual / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual), with a non-linear squaring
    // to heavily penalize large dead space.
    score += (post_residual as f64 / bin_capacity as f64).powi(3) * 60.0;

    // Aggressive 2-step lookahead: reward when post_residual exactly matches
    // the next item size (perfect chaining), penalize when next item cannot fit.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let post = post_residual as f64;
        if post >= nxt {
            let gap = post - nxt;
            // exact match => big bonus; larger gap => smaller bonus
            score -= 25.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // next item won't fit here; penalize proportionally to wasted chain
            score += 8.0 + (nxt - post) * 0.15;
        }
    }

    // Compare bin's residual against mean residual: using a below-average-residual
    // bin is good (consolidates fullness); using an above-average one is wasteful.
    let dev = bin_residual as f64 - mean_residual;
    score += dev * 0.10;

    // Last-chance bonus: if this is the only bin that can fit the item, strongly
    // prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are
    // nearly full or the fit is very poor. Scale penalty with stream progress.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fit_quality = post_residual as f64 / bin_capacity as f64;
        // opening a new bin is acceptable only if fit leaves much usable space
        score = 120.0 - 30.0 * progress - 60.0 * fit_quality;
        if fitting_bins_count == 1 {
            score += 200.0; // never open a new bin when it's the only fitting bin
        }
    }

    // Mild preference for filling bins early in the stream (keeps options open later).
    score += (1.0 - step_index as f64 / total_items.max(1) as f64) * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimal waste, but with diminishing returns for very small residuals
    score = (post_residual as f64).powf(0.85);

    // Reward perfect or near-perfect fits strongly
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly into the post-residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item won't fit here anyway; slight penalty for leaving medium holes
            let hole = post_residual as f64;
            if hole < next_item_size as f64 && hole > 20.0 {
                score += 8.0;
            }
        }
    }

    // Last chance: if this is the only bin that can fit the item, strongly favor it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    // Prefer reusing open bins unless the fit is poor.
    if bin_residual == bin_capacity {
        // Opening a new bin: neutral-ish baseline, penalize when many open bins
        // already exist with room (avoid bin proliferation).
        score += 35.0 + 2.0 * open_bins_count as f64;
        // Early in the stream, opening bins is cheaper (build diversity)
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 20.0 * (1.0 - progress);
        // If mean residual across open bins is large, avoid new bin
        score += 0.3 * mean_residual;
    } else {
        // Reusing a bin: reward keeping mean residual balanced (avoid many tiny holes)
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.05 * dev;
        // Slight reward for reusing fuller bins (best-fit bias)
        score -= 0.2 * (bin_capacity - bin_residual) as f64 / bin_capacity as f64 * 10.0;
    }

    // Dead-space penalty: residual too small for the smallest plausible item (1..100 range)
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;

    // Base: prefer tight fits (low post_residual), with non-linear shaping.
    let mut score = post;

    // Cubic penalty on wasted space: dead space grows super-linearly in badness.
    score += 12.0 * norm_post * norm_post * norm_post * cap;

    // Smooth interaction: as the stream progresses, tighten preference for small post_residual.
    let tightness = 1.0 + 1.5 * progress;
    score *= tightness;

    // Quadratic coupling of post_residual with mean residual: penalize bins whose
    // post-residual deviates from the fleet mean (encourages residual homogeneity).
    let dev = post - mean_residual;
    score += 0.05 * dev * dev / cap;

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 40.0;
    } else {
        // Mild penalty when many bins compete (spread items less greedily).
        score += 0.5 * (fitting_bins_count as f64).sqrt();
    }

    // Lookahead: reward leaving room for the next item; smooth quadratic fit term.
    if next_item_size > 0 {
        let n = next_item_size as f64;
        let slack = post - n;
        if slack >= 0.0 {
            // Perfect next-fit alignment gets a smooth bonus peaking at slack == 0.
            score -= 8.0 * (1.0 - (slack / cap).powi(2));
        } else {
            // Next item won't fit here; slight penalty proportional to overshoot.
            score += 0.3 * (-slack);
        }
    }

    // Penalize opening new bins more as the number of open bins grows,
    // modulated smoothly by stream progress.
    if bin_residual == bin_capacity {
        let open = open_bins_count as f64;
        score += 25.0 + 5.0 * open * (1.0 - 0.5 * progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify dead space into usable bands.
    // Residuals <= 10 are "perfect" (item sizes start at 1..100, small classes reusable).
    if post_residual == 0 {
        score -= 50.0; // perfect fit
    } else if post_residual <= 10 {
        score -= 20.0;
    } else if post_residual <= 25 {
        score -= 5.0;
    } else if post_residual <= 50 {
        score += 5.0;
    } else {
        score += 12.0;
    }

    // Modulo-10 harmonic class: residuals in the same class as next item size
    // are more likely reusable by the lookahead item.
    if next_item_size > 0 && post_residual >= next_item_size {
        let class_match = ((post_residual as i64 - next_item_size as i64) % 10).abs() <= 2;
        if class_match {
            score -= 15.0;
        }
        // Lookahead fits comfortably: reward leaving space for it
        if post_residual >= next_item_size * 2 {
            score -= 8.0;
        }
    } else if next_item_size > 0 {
        // next item cannot use this residual space: penalize tight leftover
        score += 6.0;
    }

    // Last-chance bin: strongly prefer filling it rather than opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is terrible.
    if bin_residual == bin_capacity {
        score += 30.0 + post_residual as f64;
        // Early in stream, allow more bins; later, discourage.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
        // If next item is large, a fresh bin is valuable.
        if next_item_size >= 60 {
            score -= 20.0;
        }
    }

    // Tight fits (small waste relative to item) are good.
    score -= (item_size as f64) / (bin_residual as f64 + 1.0) * 10.0;

    // Prefer bins below mean residual (more filled bins first).
    if (bin_residual as f64) < mean_residual {
        score -= 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps heavily.
    // Gaps below the smallest plausible item (1..100 stream => threshold ~12)
    // are "dead" unless exactly zero.
    if post_residual > 0 && post_residual < 12 {
        score += 60.0 + (12 - post_residual) as f64 * 8.0;
    } else if post_residual == 0 {
        // Perfect fit is the best outcome: strong reward.
        score -= 45.0;
    } else {
        // Mild reward for tight fits among viable residuals.
        score -= (bin_capacity - post_residual) as f64 * 0.15;
    }

    // Penalize creating residuals that cannot fit the lookahead item
    // when the current bin could have held it (wasted opportunity).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size as f64 {
        score += 10.0 + (next_item_size as f64 - post_residual as f64) * 0.5;
    }
    // Bonus if post_residual still accommodates the next item.
    if next_item_size > 0 && post_residual >= next_item_size as f64 {
        score -= 6.0;
    }

    // Last-chance pressure: strongly favor using the only fitting bin
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: when many bins are open, discourage opening new ones.
    let new_bin_candidate = bin_residual == bin_capacity;
    if new_bin_candidate {
        score += open_bins_count as f64 * 3.0 + 25.0;
        // Allow new bin only if remaining open capacity is highly fragmented.
        if mean_residual < item_size as f64 * 0.8 {
            score -= 20.0;
        }
    }

    // Stream progression: later in the stream, be more conservative
    // (tighten preference for filling existing bins).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0 * if new_bin_candidate { -1.0 } else { 1.0 };

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fits are excellent: reward small post_residual strongly.
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual < 10 {
        score -= 120.0;
    } else if post_residual < 20 {
        score -= 60.0;
    }

    // 2-step lookahead: if the next item fits exactly into the post residual,
    // this placement chains perfectly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let chain = post_residual - next_item_size;
        score -= 40.0 + 0.5 * chain as f64;
    }

    // Dead space: post residual smaller than the smallest possible next item
    // (below lookahead size and unusable) is penalized relative to mean residual.
    if next_item_size > 0 && post_residual < next_item_size && post_residual < 10 {
        score += 30.0;
    }

    // Compare against mean residual: prefer bins whose residual deviates
    // favorably (using a bin that is tighter than average).
    if (post_residual as f64) < mean_residual {
        score -= 15.0;
    } else {
        score += 0.2 * (post_residual as f64 - mean_residual);
    }

    // Last chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate: only attractive when no good fit exists elsewhere;
    // penalize opening new bins mildly, more when many bins are already open.
    if bin_residual == bin_capacity {
        score += 25.0 + 2.0 * open_bins_count as f64;
        // But if the next item also fits a fresh bin perfectly after this one,
        // a new bin can be reasonable.
        if next_item_size > 0 && next_item_size + item_size > bin_capacity {
            score -= 20.0;
        }
    }

    // Late in the stream, consolidation matters more: penalize waste harder.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post-residual) more aggressively.
    let tight_fit = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 35.0 * tight_fit * tight_fit;

    // Penalize dead space that is too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 12.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Lookahead: if the next item fits exactly into the post-residual, reward heavily.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 50.0;
        } else if post_residual >= next_item_size {
            score -= 10.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // Next item cannot fit here; slight penalty proportional to wasted potential.
            score += 5.0 * (next_item_size as f64 - post_residual as f64) / bin_capacity as f64;
        }
    }

    // Time horizon: early in the stream, be more willing to open new bins
    // (keep residuals flexible); late in the stream, consolidate tightly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 20.0 * progress * tight_fit;

    // Global state: many open bins with high mean residual -> prefer filling existing bins.
    if open_bins_count > 2 {
        let pressure = mean_residual / bin_capacity as f64;
        score += 15.0 * (1.0 - pressure) * (open_bins_count as f64).ln();
    }

    // New-bin candidate: penalize opening a fresh bin unless the item is large
    // or existing fits are poor (post_residual in this call equals capacity - item).
    if bin_residual == bin_capacity {
        let base_penalty = 25.0 + 40.0 * progress;
        // If item is large, opening a new bin is often fine (less penalty).
        let large_item_relief = 30.0 * (item_size as f64 / bin_capacity as f64);
        score += base_penalty - large_item_relief;
        // If no other bin fits, this call is the only option anyway; soften.
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
    }

    // Small bonus for perfectly full bins.
    if post_residual == 0 {
        score -= 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap; // normalized post residual
    let mut score = pr as f64;
    // smooth non-linear coupling of post residual with stream progress
    score += 40.0 * (x * x) * (0.5 + progress);
    score -= 25.0 * (1.0 - x) * (1.0 - x) * progress;
    // penalize dead space that cannot fit the lookahead item
    if next_item_size > 0 {
        let fits_next = if post_residual >= next_item_size { 1.0 } else { 0.0 };
        score -= 30.0 * fits_next * (1.0 - progress);
        score += 15.0 * (1.0 - fits_next) * (0.5 + 0.5 * progress);
    }
    // last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 20.0 * (0.3 + 0.7 * progress);
    }
    // mild preference toward bins tighter than the mean
    score += 5.0 * ((bin_residual as f64 - mean_residual) / cap);
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residue modulo 10 (capacity fractions / decade classes)
    let post = post_residual as i64;
    let cap = bin_capacity as f64;
    let res_mod = (post % 10) as f64;
    let quot = (post / 10) as f64;

    // Penalize residual that is too small to be useful for typical items (dead space)
    if post > 0 && post < 10 {
        score += 25.0; // dead space: nothing of size >=10 fits
    }

    // Reward residual sizes that form "harmonic" complements of common item sizes
    // Residuals divisible by 10 align with decade item sizes -> prefer them
    score -= 8.0 * (10.0 - res_mod) / 10.0 * (quot / 10.0).min(1.0);

    // Perfect fit: huge reward
    if post == 0 {
        score -= 60.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, strongly reward
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0;
        } else if post_residual > next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0 * (1.0 - slack / cap);
        } else {
            // next item won't fit here; penalize proportional to wasted fraction
            score += 10.0 * (next_item_size as f64 / cap);
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize mildly so it's chosen only when fits are bad,
    // but reward it late in the stream or when open bins are fragmented
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = (mean_residual / cap).clamp(0.0, 1.0);
        score = 55.0 + 30.0 * (1.0 - fragmentation) - 15.0 * progress;
        if next_item_size > 0 && next_item_size <= bin_residual {
            score -= 20.0; // fresh bin guarantees future fit
        }
    }

    // Mild tie-break toward fuller bins relative to mean residual
    score -= 0.05 * (bin_residual as f64 - mean_residual);

    // Modulo threshold coupling: residuals in [10,20) are second-worst class
    if post >= 10 && post < 20 {
        score += 6.0;
    }
    // Residuals >= 50 keep flexibility
    if post >= 50 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold
    // even the smallest plausible item are pure waste -> heavy penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 25.0;
    } else if post_residual >= 20 && post_residual < 30 {
        score += 8.0;
    } else if post_residual == 0 {
        // Perfect fill: strong reward.
        score -= 40.0;
    }

    // Reward tight fits: fraction of the residual actually consumed.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 15.0 * tightness;

    // Open-bin pressure: with many bins open, avoid opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * (0.4 + 0.6 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are open,
        // but allow it when existing bins would leave bad dead space.
        score += 30.0 + 2.5 * pressure;
        if post_residual >= 0 && item_size >= 60 {
            score -= 5.0; // large items in a fresh bin are fine
        }
    } else {
        // Reward using existing bins, especially under pressure.
        score -= 2.0 + 0.6 * pressure;
    }

    // Last-chance bin: strongly prefer filling it rather than wasting it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual,
    // this placement chains perfectly; if next item is larger than
    // post_residual but fits elsewhere, mild penalty for blocking.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            score -= 10.0;
        } else if next_item_size > post_residual && post_residual > 0 {
            score += 6.0;
        }
    }

    // Prefer bins with residual below mean (consolidate small leftovers).
    let res = bin_residual as f64;
    if res < mean_residual {
        score -= 4.0;
    } else {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (small post_residual relative to item size).
    let tightness = (item_size as f64) / (bin_residual.max(1) as f64);
    score -= 12.0 * tightness;

    // 2-step lookahead: if next item exactly matches post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            // next item fits: reward proportional to how well it fills remainder
            let fill2 = (next_item_size as f64) / (post_residual.max(1) as f64);
            score -= 20.0 * fill2;
        } else {
            // next item won't fit here: penalize wasted space if gap is small
            let gap = (next_item_size - post_residual) as f64;
            if post_residual > 0 && gap < 10.0 {
                score += 15.0 * (10.0 - gap);
            }
        }
    }

    // Penalize leaving dead space below the minimum item size (unusable).
    let min_item = 1.0f64;
    if (post_residual as f64) < min_item {
        score += 100.0;
    }

    // Compare against mean residual: prefer bins with above-average residual usage.
    score -= 3.0 * (mean_residual - post_residual as f64);

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a new bin when good open bins exist and stream is early.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score += 30.0 * (1.0 - progress);
        if next_item_size > 0 && (next_item_size as f64) <= (bin_capacity as f64) * 0.5 {
            score += 10.0;
        }
    }

    // Mild penalty on many open bins to consolidate.
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: squared penalty on post-residual.
    score += (post_residual as f64).powi(2) / (bin_capacity as f64);

    // Penalize dead space that cannot fit the next item (lookahead coupling).
    if next_item_size > 0 {
        if post_residual < next_item_size && post_residual > 0 {
            score += (next_item_size - post_residual) as f64 * 2.0;
        } else if post_residual >= next_item_size {
            // Bonus if this bin can also host the next item exactly.
            score -= 3.0;
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Prefer filling already-open bins when many are open.
    score += open_bins_count as f64 * 0.5;

    // Deviation from mean residual: prefer bins whose residual is close to item need.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.3;

    // Time horizon: later in the stream, be more conservative (favor tight packing).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.5 * progress;

    // New-bin candidate: make it moderately attractive only when current bin would leave bad residue.
    if bin_residual == bin_capacity {
        let waste_now = post_residual as f64;
        score = waste_now + 20.0 - 0.2 * open_bins_count as f64;
        if fitting_bins_count <= 1 {
            score -= 25.0; // no good open bin -> new bin is fine
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let item = item_size as f64;

    // Base: minimize waste, with non-linear polynomial shaping of post_residual
    let x = pr / cap;
    let waste_curve = 2.0 * x * x - 1.5 * x * x * x + x * x * x * x;
    let mut score = pr * (0.5 + waste_curve);

    // Smooth coupling of post_residual with stream progress:
    // late in the stream, tighten tolerance for leftover space
    let tightness = 0.5 + 1.5 * progress * progress;
    score += tightness * x * cap * (1.0 - x);

    // Penalize near-full bins only mildly early (they're fine), reward tight fits
    let fit_ratio = item / bin_residual.max(1) as f64;
    score -= (fit_ratio * fit_ratio) * (1.0 - progress) * 10.0;

    // Last-chance bin bonus (avoid opening new bins unnecessarily)
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + 20.0 * progress;
    }

    // Lookahead: favor bins whose post_residual can host next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr as u32 >= next_item_size {
            score -= 8.0 * (1.0 - (pr - nx) / cap);
        } else {
            score += 6.0 * (nx - pr) / cap;
        }
    }

    // Slight penalty when bin residual deviates from mean residual (fragmentation)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 3.0 * dev * dev * (0.3 + progress);

    // New-bin candidate: keep it attractive when open bins are fragmented
    if bin_residual == bin_capacity {
        let frag = mean_residual / cap;
        score = pr + 15.0 * (1.0 - frag) * (1.0 - progress) - 5.0 * progress * (1.0 - frag);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover belongs to a
    // "reusable" class (multiples of 10, or small enough to pair with tiny items)
    // are rewarded.
    let class = post_residual % 10;
    if class == 0 {
        score -= 6.0; // perfectly harmonic leftover
    } else if post_residual < 10 {
        score -= 2.0; // dead space but small
    } else {
        score += (class as f64) * 0.8; // awkward leftover penalized
    }

    // Reward tight fits strongly (waste-based shaping).
    let waste_frac = post_residual as f64 / bin_capacity as f64;
    score += waste_frac * waste_frac * 30.0;

    // Lookahead: if the next item fits exactly into the post residual, big bonus.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            score -= 8.0;
        } else {
            score += 5.0; // next item won't fit here; this bin likely dead
        }
    }

    // Last-chance bin: avoid opening a new bin if this is the only fit.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: only attractive when the item is large relative to
    // capacity or all open residuals are poorly matched.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let avg_gap = (mean_residual - item_size as f64).abs();
        score += 15.0 + avg_gap * 0.5 - progress * 5.0;
        if item_size >= 60 {
            score -= 10.0; // big items deserve fresh bins
        }
    }

    // Mild pressure to consolidate when many bins are open.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny gaps (1..=12) are nearly unusable
    // dead space -> heavy penalty so we don't strand small residuals.
    if post_residual >= 1 && post_residual <= 12 {
        score += 60.0 - 4.0 * post_residual as f64;
    }

    // Perfect / near-perfect fits are highly desirable.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 10.0;
    }

    // Reward filling most of the bin (post_residual small relative to capacity).
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 25.0 * fill_ratio;

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: many open bins -> favor consolidating into existing
    // bins rather than fragmenting; also mild new-bin resistance.
    score += 1.5 * open_bins_count as f64;

    // Mean residual coupling: if this bin's residual is far below the mean,
    // it is a "cramped" bin; using it up is good (reduces fragmentation).
    let res_gap = mean_residual - bin_residual as f64;
    score += 0.3 * res_gap;

    // Lookahead: if next item fits exactly into post_residual, big bonus.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size < post_residual {
            score -= 8.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // next item cannot use the leftover: slight penalty for wasteful gap
            score += 3.0;
        }
    }

    // New-bin candidate handling: empty bin gets a baseline cost that grows
    // with stream progress and number of open bins; only win when all open
    // bins are poor fits (their scores inflated by dead-space penalties).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 55.0 + 30.0 * progress + 2.0 * open_bins_count as f64;
        // If the item is large, a fresh bin is more attractive.
        score -= 20.0 * fill_ratio;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for exact 2-step fit: post_residual == next_item_size
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
        score -= 60.0 * (1.0 - diff / (bin_capacity as f64)).exp().exp();
        // penalize post-residuals that are small but not zero (dead space)
        if post_residual > 0 && post_residual < 10 {
            score += 15.0;
        }
        // reward when next item still fits comfortably
        if post_residual >= next_item_size {
            score -= 8.0;
        }
    } else {
        // last item: prefer tightest fit
        score += 5.0;
    }

    // Relative to mean residual: prefer bins tighter than average
    score += 0.3 * (post_residual as f64 - mean_residual);

    // Last-chance bin bonus: avoid wasting the only fitting bin on a bad fit
    if fitting_bins_count == 1 {
        score -= 10.0;
    }

    // New-bin candidate: only attractive when existing fits are poor
    if bin_residual == bin_capacity {
        score += 20.0 + 0.1 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 15.0; // fresh bin pairs well with upcoming large item
        }
    }

    // Slight preference to fill bins more as stream progresses
    score -= 5.0 * (1.0 - post_residual as f64 / bin_capacity as f64) * (step_index as f64 / total_items.max(1) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 8.0 * tightness * tightness;

    // Penalize dead space: residuals too small to plausibly fit future items.
    if post_residual > 0 && post_residual < 10 {
        score += 6.0;
    }

    // Lookahead: strongly reward bins whose post_residual fits the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 5.0 + 0.05 * next_item_size as f64;
        } else {
            // Wasting the next item's chance: penalize proportionally.
            let gap = (next_item_size - post_residual) as f64;
            score += 0.03 * gap;
        }
    }

    // Last-chance bin: strongly prefer using the only bin that fits,
    // avoiding a new bin opening.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // Time horizon: early in the stream, be conservative (favor filling
    // existing bins); later, allow more freedom to open new bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 4.0 * progress * tightness;

    // Global state coupling: many open bins with large mean residual
    // suggests fragmentation; discourage opening new bins then.
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus fragmentation pressure.
        score += 10.0 + 0.5 * open_bins_count as f64;
        score -= 0.15 * mean_residual;
        // Late in the stream, opening fresh bins is less costly.
        score -= 6.0 * progress;
        // If nothing else fits well (post_residual would be tiny elsewhere),
        // new bin becomes attractive via the tightness term above.
        if item_size >= 70 {
            score -= 4.0; // big items fit better in empty bins
        }
    } else {
        // Existing bin: mild penalty proportional to its current residual
        // deviation from the mean (prefer bins near the mean to balance).
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.05 * dev;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: quadratic coupling of post_residual with stream progress.
    // Late in the stream, tight fits (small post_residual) matter more,
    // so we amplify the quadratic term with progress.
    let mut score = pr * (1.0 + 2.0 * progress * norm_pr);

    // Cubic smoothing term: penalize large dead space superlinearly,
    // but soften it early in the stream.
    score += 8.0 * norm_pr.powi(3) * (0.5 + progress);

    // Last-chance bonus: if this is the only fitting bin, strongly reward using it.
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - norm_pr) * (0.5 + progress);
    }

    // Prefer bins whose residual is below the mean residual (tighter bins),
    // scaled by a smooth tanh-like coupling.
    let mean_norm = mean_residual / cap;
    score -= 5.0 * ((mean_norm - norm_pr) * 3.0).tanh();

    // Lookahead: if next item fits exactly into post_residual, reward heavily.
    if next_item_size > 0 {
        let nd = (next_item_size as f64 - pr).abs();
        if nd <= 1.0 {
            score -= 15.0;
        } else {
            score += 0.05 * nd * (1.0 + progress);
        }
    }

    // Slight preference for consolidating into fewer bins when many are open.
    score += 0.02 * open_bins_count as f64 * norm_pr;

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post_residual)
    score -= (bin_capacity as f64 - post_residual as f64).log2().max(0.0) * 3.0;

    // Penalize dead space: post_residual too small to hold the smallest plausible item
    if post_residual < 10 && post_residual > 0 {
        score += 25.0;
    }

    // Harmonic classes: quantize post_residual into capacity fractions
    let frac = post_residual as f64 / bin_capacity as f64;
    let harmonic = (frac * 8.0).floor(); // class 0..8
    score += harmonic * 2.0;

    // Last-chance bin bonus
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Lookahead: if next item fits exactly in post_residual, reward strongly
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= (post_residual - next_item_size) as f64 * 0.8 + 10.0;
    } else if next_item_size > post_residual && post_residual > 0 {
        // next item cannot use leftover; penalize proportionally
        score += post_residual as f64 * 0.3;
    }

    // Prefer filling bins when many bins are open
    score -= open_bins_count as f64 * 0.1;

    // Slight preference for existing bins over new bin
    if bin_residual == bin_capacity {
        score += 5.0;
    }

    // Progress coupling: later in stream, prefer tighter packing
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 - 0.2 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize unusable small gaps.
    // A residual that is too small for the smallest plausible item is pure waste.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    // Penalize gaps that cannot fit the known next item (lookahead-aware dead space).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0 + 0.25 * (next_item_size as f64 - post_residual as f64);
    }
    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Last-chance pressure: if this is the only fitting bin, strongly prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bins pressure: with many open bins, discourage spreading; favor filling
    // existing bins (new-bin candidate has bin_residual == bin_capacity, so this
    // hits it hardest as open_bins_count grows).
    score += 0.35 * open_bins_count as f64 * (bin_residual as f64 / bin_capacity as f64);

    // Mild tightness coupling: prefer bins tighter than the mean residual.
    score += 0.15 * (bin_residual as f64 - mean_residual);

    // Late-stream conservatism: as the stream progresses, favor filling existing bins
    // over opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * (bin_residual as f64 / bin_capacity as f64);

    // If the next item fits perfectly in the post residual, reward this placement.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect lookahead match: next item exactly fills the bin afterwards.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Reward exact match strongly; penalize mismatch proportionally.
        score += 2.0 * diff - 30.0 * (diff == 0.0) as f64;

        // If the next item fits in the post residual, reward leaving usable space.
        if next_item_size <= post_residual {
            score -= 10.0;
        } else {
            // Dead space the next item cannot use -> penalize.
            score += 8.0;
        }
    } else {
        // Last item: prefer tightest fill.
        score *= 2.0;
    }

    // Penalize creating tiny unusable slivers (< 10, minimum item size).
    if post_residual < 10 && post_residual > 0 {
        score += 25.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer it
    // over opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Prefer bins below mean residual (tighter bins), discourage spreading.
    score -= 0.15 * (mean_residual - post_residual as f64);

    // Discourage opening a new bin early in the stream when many bins are open.
    if bin_residual == bin_capacity {
        score += 5.0 + 3.0 * open_bins_count as f64 * (1.0 - step_index as f64 / total_items.max(1) as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual relative to capacity.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += fit_ratio * fit_ratio * 40.0;

    // Penalize large dead space that few future items could use.
    if post_residual > 0 && post_residual < 10 {
        score -= 15.0; // near-perfect fill
    }
    if post_residual > 50 {
        score += 8.0; // large residual, but keep base attraction
    }

    // Lookahead: if the next item fits the post-residual exactly or well, favor this bin.
    if next_item_size > 0 && next_item_size <= post_residual {
        let chain_waste = post_residual - next_item_size;
        score -= (post_residual as f64 - chain_waste as f64) * 0.25;
        if chain_waste == 0 {
            score -= 25.0; // perfect two-item chain
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 6.0; // next item can't use this residual
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Prefer bins with below-mean residual (more filled bins first).
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Early in the stream, be more willing to spread; later, consolidate tightly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 10.0 * (1.0 - fit_ratio);

    // New-bin candidate: opening a new bin is only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        score = 1000.0 - pressure * 900.0 + (fitting_bins_count as f64) * 50.0;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let fit_frac = item_size as f64 / cap;
    let pr_frac = pr / cap;

    // Base: prefer small post residual, with smooth non-linear shaping
    let mut score = pr_frac * (1.0 + 0.6 * fit_frac * (1.0 - progress));

    // Non-linear polynomial coupling of post_residual with stream progress
    let p = progress;
    score += pr_frac * pr_frac * (0.5 + 1.5 * p * p);
    score += 0.3 * pr_frac * fit_frac * (1.0 - p) * (1.0 - p);

    // Lookahead: reward if next item fits the post residual (smooth coupling)
    if next_item_size > 0 {
        let nxt = next_item_size as f64 / cap;
        let gap = (pr - next_item_size as f64).max(0.0) / cap;
        score -= 1.2 * nxt * (1.0 - gap) * (1.0 - gap) * (1.0 - 0.5 * p);
        // Penalize post residual that neither fits next item nor is small
        if next_item_size as f64 > pr {
            score += 0.8 * nxt * (0.5 + p);
        }
    }

    // Last chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 2.5;
    } else if fitting_bins_count > 2 {
        score += 0.15 * (fitting_bins_count as f64 - 2.0);
    }

    // Mean residual context: penalize creating dead space vs. average
    let mean_frac = mean_residual / cap;
    score += 0.4 * (pr_frac - mean_frac).abs() * (0.5 + 0.5 * p);

    // New-bin candidate: only attractive when existing fits are poor
    if bin_residual == bin_capacity {
        let poor_fit = if fitting_bins_count == 0 { 1.0 } else {
            (pr_frac - mean_frac.max(0.0)).abs() * 0.5 + (1.0 - fit_frac) * 0.5
        };
        score = 3.0 + cap * 0.02 - 2.0 * poor_fit + 1.5 * p;
        if fitting_bins_count == 1 { score += 4.0; }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class: post_residual falls into "dead zones" that few item sizes can fill.
    // Items are 1..=100, so residual r is usable if some plausible item ~ r.
    // Penalize residuals in awkward bands via modulo structure on bin capacity fractions.
    let r = post_residual;
    let quarter = bin_capacity / 4; // 25
    let eighth = bin_capacity / 8;  // 12

    // Residuals that are small but nonzero waste the bin's utility
    if r > 0 && r < eighth {
        score += 40.0 + (eighth - r) as f64;
    }

    // Modulo-class logic: residuals divisible by common item sizes are more reusable.
    // Reward residuals in classes {0 mod 10, 0 mod 20, 0 mod 25, 0 mod 50}.
    if r % 10 == 0 {
        score -= 15.0;
    }
    if r % 20 == 0 {
        score -= 10.0;
    }
    if r % 25 == 0 {
        score -= 12.0;
    }
    if r % 50 == 0 {
        score -= 15.0;
    }

    // Integer division thresholds: which harmonic "slot" does post_residual occupy?
    let slot = r / eighth; // 0..=8 slots
    match slot {
        0 => { score += 30.0; }      // tiny leftover: near-dead space
        1 => { score += 12.0; }      // small: only tiny items fit
        2 | 3 => { score -= 8.0; }   // mid: many item classes fit
        4 | 5 => { score -= 5.0; }   // comfortable
        _ => { score += 3.0; }       // large leftover: wasteful placement
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == r {
            score -= 300.0;
        } else if next_item_size <= r {
            // next item fits: residual class compatibility
            let slack = r - next_item_size;
            score -= 40.0 - (slack.min(50) as f64) * 0.5;
            // reward if post_residual is in a class next item's typical companions hit
            if (r % 10 == 0) && (next_item_size % 10 == 0) {
                score -= 20.0;
            }
        } else {
            // next item won't fit here: mildly penalize since we may strand residual
            score += 10.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 60.0;
    }

    // New-bin candidate handling: an empty bin is a fresh resource; prefer it only
    // when placing here would strand bad residual. Penalize opening new bins
    // when plenty of open bins exist and this placement is decent.
    if bin_residual == bin_capacity {
        score += 80.0; // base cost of a new bin
        if open_bins_count == 0 {
            score -= 200.0; // nothing else available
        }
        if fitting_bins_count == 0 {
            score -= 150.0;
        }
        // If current item is large, new bin is natural
        if item_size > bin_capacity / 2 {
            score -= 40.0;
        }
    }

    // Stream progression: late in stream, avoid opening new bins / consolidate.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 10.0 * (fitting_bins_count.max(1) as f64).recip().min(1.0);

    // Tie-break toward bins tighter than average (better packing density).
    score += (bin_residual as f64 - mean_residual) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64) / 10.0;
    }
    // Perfect fit is strongly rewarded.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual <= 5 {
        score += 20.0;
    }

    // Reward tight fits relative to bin residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 15.0 * fill_ratio;

    // Pressure from number of open bins: prefer existing bins when many are open.
    score += 0.35 * open_bins_count as f64;

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 18.0;
    }

    // Lookahead: if next item fits the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    }
    // If next item would be blocked by a tiny leftover, penalize.
    if next_item_size > post_residual && post_residual < 10 && post_residual > 0 {
        score += 8.0;
    }

    // Mean residual coupling: bins with residual far below mean are tighter; prefer them.
    let dev = mean_residual - bin_residual as f64;
    score -= 0.15 * dev;

    // Early stream: slightly favor opening new bins to build flexibility.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 6.0 * progress + 0.5 * open_bins_count as f64;
        if next_item_size > 0 && item_size + next_item_size as u32 <= bin_capacity {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is already good via base score.
    // Penalize dead space that is too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // 2-step lookahead: reward when next item fits into post_residual exactly/well.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack_after_next = post_residual - next_item_size;
            score -= 10.0 - slack_after_next as f64 * 0.3;
        } else {
            // next item cannot follow here; penalize proportionally to overflow
            let overflow = next_item_size - post_residual;
            score += overflow as f64 * 0.4;
        }
    }

    // Compare residual against mean residual of open bins:
    // prefer placing into bins with below-average residual (keep big-space bins flexible),
    // unless this is a tight fit.
    let mean_res = mean_residual;
    if (bin_residual as f64) > mean_res + 5.0 {
        score += (bin_residual as f64 - mean_res) * 0.25;
    } else if (bin_residual as f64) < mean_res - 5.0 {
        score -= (mean_res - bin_residual as f64) * 0.15;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when item is large relative to capacity
    // and no good fit exists (post_residual would be large dead space otherwise).
    if bin_residual == bin_capacity {
        let tightness = item_size as f64 / bin_capacity as f64;
        // Opening a new bin is good if item is large (leaves useful residual)
        score -= tightness * 20.0;
        // But discourage opening bins when many bins are already open and fitting
        if fitting_bins_count > 0 {
            score += 8.0 + fitting_bins_count as f64 * 1.5;
        }
        // Early in stream, slightly prefer consolidating into open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += (1.0 - progress) * 5.0;
    }

    // Mild penalty for many open bins (encourage consolidation).
    score += open_bins_count as f64 * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 50.0;
    } else {
        // Penalize small dead space that nothing can use
        if post_residual < 10 {
            score += 25.0;
        }
        // Reward residual that could fit a typical future item
        let progress = step_index as f64 / total_items.max(1) as f64;
        let horizon = 1.0 - progress;
        if (post_residual as f64) >= mean_residual * 0.5 {
            score -= 5.0 * horizon;
        }
        // Lookahead: if next item fits the post residual, reward strongly
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 20.0 + 0.3 * (next_item_size as f64);
        } else if next_item_size > 0 && next_item_size > post_residual {
            score += 3.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless open bins are badly fragmented
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual - (bin_capacity as f64 - item_size as f64)).abs();
        let pressure = if fitting_bins_count == 0 { 0.0 } else { 40.0 - 8.0 * (fitting_bins_count as f64) };
        score = bin_capacity as f64 + pressure + fragmentation * 0.2
            - if next_item_size > 0 && next_item_size <= bin_residual - item_size { 15.0 } else { 0.0 };
    }

    // Mildly discourage scattering across many open bins
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: quadratic penalty on post residual (dead space)
    let mut score = pr * (1.0 + 0.9 * norm_pr);

    // Smooth non-linear coupling with stream progress:
    // early on, tolerate larger residuals (bins can still be filled);
    // late in the stream, penalize residual more aggressively.
    let progress_coupling = 1.0 + 0.8 * progress * progress + 0.4 * progress;
    score *= progress_coupling;

    // Reward tight fits: subtract a smooth function of item_size / capacity
    let tightness = item_size as f64 / cap;
    score -= 6.0 * tightness * (1.0 - norm_pr) * (1.0 - progress * 0.5);

    // Lookahead coupling: if the next item fits the post residual, reward this placement
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let fit_ratio = nxt / pr.max(1.0);
            score -= 5.0 * fit_ratio * (1.0 - fit_ratio * 0.5);
        } else {
            // next item cannot use the leftover; penalize proportionally to waste
            score += 2.5 * (nxt / cap) * norm_pr;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 12.0 * (1.0 - norm_pr);
    } else if fitting_bins_count > 1 {
        // mild competition bonus scaled inversely with available options
        score -= 2.0 / fitting_bins_count as f64;
    }

    // Mean residual context: prefer bins whose residual differs from the mean
    // (filling atypical bins balances the pool of open bins)
    let dev = (pr - mean_residual).abs() / cap;
    score += 1.5 * dev * (1.0 - progress);

    // Slight preference for consolidating into fewer bins when many are open
    score += 0.05 * open_bins_count as f64 * norm_pr;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the bin residual: which quarter of capacity it lives in
    let quarter = bin_capacity / 4; // 25
    let residual_class = bin_residual / quarter; // 0..=4

    // Reward tight fits: penalize large post_residual non-linearly
    score += (post_residual as f64 / bin_capacity as f64).powi(3) * 40.0;

    // Perfect fit gets a strong bonus (very low score)
    if post_residual == 0 {
        score -= 60.0;
    }

    // Harmonic class logic: bins whose residual is an integer multiple of
    // common item sizes (10..20) are "harmonic" and easy to fill later.
    let harmonic = post_residual % 10 == 0 || post_residual % 20 == 0;
    if harmonic {
        score -= 8.0;
    } else {
        score += 4.0;
    }

    // Dead space penalty: post_residual too small for any item (min size 1..10 range)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Lookahead: if next item fits exactly in the post residual, big reward
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual > next_item_size {
            score -= 5.0;
        } else {
            // next item can't use the leftover: penalize proportional leftover
            score += post_residual as f64 * 0.15;
        }
    }

    // Prefer filling already-open bins when many are open (avoid bin sprawl)
    score += open_bins_count as f64 * 1.5;

    // New-bin candidate handling: an empty bin should only win if current bin
    // fit is poor. Penalize the empty-bin candidate moderately.
    if bin_residual == bin_capacity {
        score += 30.0;
        // but if stream is early, opening bins is fine
        if step_index < total_items / 4 {
            score -= 15.0;
        }
    }

    // Coupling with mean residual: prefer bins tighter than average
    if (bin_residual as f64) < mean_residual {
        score -= 6.0;
    } else {
        score += 3.0;
    }

    // Integer-division threshold: high residual class (mostly empty bin) mildly penalized
    score += residual_class as f64 * 2.0;

    // Early stream: keep scores lower overall to encourage consolidation later
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals below ~20 are nearly unusable
    // for future items (min item size 1..100 unknown, but small gaps waste).
    let dead_threshold = 12.0;
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += (dead_threshold - post_residual as f64) * 8.0;
    }

    // Reward near-perfect fills strongly.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Perfect-fit lookahead: if next item exactly fills post_residual.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 60.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item cannot fit here anyway; slight penalty for stranding space.
        score += (next_item_size - post_residual) as f64 * 0.3;
    }

    // Open-bin pressure: discourage spreading across many bins.
    score += open_bins_count as f64 * 0.8;

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        // Base new-bin score near mean residual of open bins, so it beats
        // only badly fitting open bins.
        score = mean_residual.max(1.0) + 10.0;
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a new bin
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 5.0; // fresh bin accommodates lookahead
        }
        return score;
    }

    // Prefer bins whose residual is close to item size (tight fit).
    let tightness = (bin_residual - item_size) as f64;
    score += tightness * 0.15;

    // Slight preference for tighter-than-average bins.
    score += (mean_residual - bin_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Core: reward tight fit (small post_residual)
    score -= 0.5 * (cap - post) / cap;

    // 2-step lookahead: if next item exactly fills post_residual, strongly reward
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (post - nxt).abs();
        if post >= nxt {
            score -= 12.0 * (1.0 - gap / cap);
        }
        // penalize leaving residuals that are awkwardly close-but-not-fitting for next item
        if post < nxt && post > 0.0 {
            score += 4.0 * (post / cap);
        }
        // penalize creating dead space unusable by next item
        if post > 0.0 && post < nxt {
            score += 6.0;
        }
    } else {
        // last item: prefer minimal waste
        score += 2.0 * post / cap;
    }

    // Relative to mean residual: prefer bins tighter than average
    score += 0.8 * (mean_residual - post) / cap;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate: penalize opening a new bin unless no good fit exists
    if bin_residual == bin_capacity {
        score += 15.0;
        if fitting_bins_count == 0 {
            score -= 20.0;
        }
        // early stream: opening bins is cheaper
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 5.0 * (1.0 - progress);
    }

    // slight preference for fuller bins among open ones
    score += 0.3 * (bin_residual as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: quadratic bonus for small post_residual.
    let pr = post_residual as f64;
    score -= (bin_capacity as f64 - pr).powi(2) / (bin_capacity as f64 * 0.5);

    // Penalize dead space that cannot fit typical future items.
    if post_residual > 0 && post_residual < 10 {
        score -= 8.0; // near-perfect fill
    } else if post_residual < 20 {
        score -= 3.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Lookahead coupling: reward if the next item fits into post_residual.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual as f64 >= nxt {
            score -= 6.0 * (nxt / (bin_capacity as f64 * 0.5)).min(1.0);
        } else {
            // Penalize leaving residual just slightly below next item size.
            let gap = nxt - pr;
            if gap < 20.0 {
                score += 4.0 * (1.0 - gap / 20.0);
            }
        }
    }

    // Global state: many open bins with large mean residual -> prefer consolidation.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let consolidation = (open_bins_count as f64).ln() * mean_residual / bin_capacity as f64;
    score += 2.0 * consolidation * (0.5 + progress);

    // New-bin candidate: penalize opening a new bin unless existing fits are poor.
    if bin_residual == bin_capacity {
        let waste_threshold = 0.35 * bin_capacity as f64;
        if pr >= waste_threshold {
            score += 10.0 + 5.0 * progress;
        } else {
            score += 2.0;
        }
        // If nothing else fits well, new bin is safer.
        if fitting_bins_count == 0 {
            score -= 12.0;
        }
    }

    // Mild reward for bins with below-mean residual (tighter bins first).
    if (bin_residual as f64) < mean_residual {
        score -= 1.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_post = pr / cap;
    let fit = item_size as f64 / cap;

    let mut score = pr as f64;

    // Smooth non-linear coupling: post residual shaped by stream progress.
    // Early on, prefer tight fills (low post residual); later, tolerate slack.
    let progress_weight = 0.6 * (1.0 - progress) + 0.2;
    score += progress_weight * (norm_post * norm_post) * cap * 0.5;

    // Penalize near-full-but-wasteful residuals quadratically.
    if norm_post > 0.0 {
        score += 0.3 * (1.0 - fit) * (norm_post).powf(1.5) * 10.0;
    }

    // Reward using the last fitting bin (avoid opening a new bin unnecessarily).
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * (1.0 - progress);
    }

    // Lookahead: reward leaving room for the next item (smooth kernel).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = pr - nxt;
        let kernel = (-((diff / cap).powi(2)) * 4.0).exp();
        score -= 8.0 * kernel;
        // Penalize when post residual is just barely below next item size.
        if diff < 0.0 {
            score += 4.0 * (-diff / cap) * (1.0 - progress);
        }
    }

    // Mild preference for bins with residuals near the mean (balance load).
    let dev = (pr - mean_residual) / cap;
    score += 0.5 * dev * dev * cap * 0.1;

    // Encourage consolidation when many bins are open.
    score -= 0.3 * (open_bins_count as f64).ln().max(0.0) * (1.0 - norm_post);

    // New-bin candidate: make empty bins slightly less attractive unless
    // nothing fits well (high post residual on existing bins is penalized above).
    if bin_residual == bin_capacity {
        score += 12.0 + 8.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: how "reusable" the leftover space is.
    // Residuals that are multiples of common small sizes (10/20/25/50) are valuable.
    let post = post_residual;
    let harmonic_bonus: f64 = if post == 0 {
        -40.0 // perfect fit: strongly reward
    } else if post % 50 == 0 {
        -18.0
    } else if post % 25 == 0 {
        -12.0
    } else if post % 20 == 0 {
        -10.0
    } else if post % 10 == 0 {
        -7.0
    } else if post % 5 == 0 {
        -3.0
    } else {
        0.0
    };
    score += harmonic_bonus;

    // Dead-space penalty: tiny unusable leftovers (below smallest plausible item class).
    if post > 0 && post < 10 {
        score += 15.0;
    }

    // Lookahead coupling: does the leftover space match the next item's class?
    if next_item_size > 0 {
        if post >= next_item_size {
            // leftover can host the next item: reward, scaled by tightness of fit
            let slack = (post - next_item_size) as f64;
            score -= 10.0 - 0.15 * slack;
            // exact class match (leftover == next item) is ideal
            if slack == 0.0 {
                score -= 8.0;
            }
        } else {
            // leftover too small for next item: penalize proportionally to wasted class
            let gap = (next_item_size - post) as f64;
            score += 0.10 * gap;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: prefer existing bins generally; opening a new
    // bin is only attractive when all open bins would leave bad classes.
    if bin_residual == bin_capacity {
        // empty bin baseline: slightly worse than a decent fit, better than a bad one
        score += 6.0;
        if post > 0 && post < 10 {
            score += 10.0; // opening fresh just to create dead space is bad
        }
        // late in the stream, prefer closing out open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 8.0 * progress;
    }

    // Many open bins with high mean residual: encourage consolidation into
    // existing bins rather than spreading.
    if open_bins_count > 2 && mean_residual > (item_size as f64) * 1.5 {
        score -= 3.0;
    }

    // Integer-division threshold on post residual: coarse class buckets.
    let bucket = post / 10; // 0..=10
    score += 0.8 * (bucket as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest item (1)
    // are pure waste; penalize small-but-nonzero gaps nonlinearly.
    if post_residual > 0 {
        // gap below typical small-item size is likely dead space
        let gap = post_residual as f64;
        if gap < 10.0 {
            score += (10.0 - gap) * 6.0; // unusable sliver -> heavy penalty
        } else if gap < 20.0 {
            score += (20.0 - gap) * 2.0; // risky gap -> moderate penalty
        }
        // Perfect fit bonus
        if post_residual == 0 {
            score -= 40.0;
        }
    }

    // Reward tight fits relative to bin capacity (low waste fraction)
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 15.0;

    // Open-bin pressure: discourage spreading across many bins unless the fit is great
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += open_bins_count as f64 * (1.0 + progress * 2.0);

    // Last-chance bin: strongly prefer using it before opening a new one
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Prefer bins with residual close to item size (minimal leftover)
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score += tightness * 0.5;

    // Lookahead: if next item fits the post-residual, reward this placement
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // post-residual can't host next item: penalize if it's also small (dead space)
        if post_residual < 10 {
            score += 8.0;
        }
    }

    // New-bin candidate handling: empty bin should only win when no open bin fits well.
    if bin_residual == bin_capacity {
        // base cost of opening a new bin, reduced early in the stream
        let mut new_bin_cost = 30.0 + open_bins_count as f64 * 2.0;
        // large items are hard to place later; be more willing to open a bin for them
        if item_size > bin_capacity / 2 {
            new_bin_cost -= 10.0;
        }
        score += new_bin_cost;
        // if next item is huge, having a fresh bin may help
        if next_item_size > 0 && next_item_size > bin_capacity / 2 {
            score -= 8.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
