pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize dead space super-linearly: small post-residuals are wasted capacity.
    let pr = post_residual as f64;
    score += (bin_capacity as f64 - pr) * 0.15 * (pr / bin_capacity as f64).powi(3);

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 + 0.25 * (next_item_size as f64);
    } else if next_item_size > 0 {
        // Next item cannot follow here: mild penalty proportional to leftover gap.
        score += 0.05 * pr;
    }

    // Perfect-fit bonus: leaving exactly nothing (or a tiny unusable sliver) is great.
    if post_residual == 0 || (post_residual < 10 && post_residual > 0) {
        score -= 20.0;
    }

    // Last-chance bin: if this is the only fitting bin, prefer it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // Late in the stream, consolidate into existing bins rather than opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 6.0;

    // Many open bins: encourage filling existing ones; few open bins: new bins are cheap.
    let open_pressure = (open_bins_count as f64 / (1.0 + mean_residual.max(1.0) / 10.0)).min(10.0);
    score += open_pressure * 0.5;

    // New-bin candidate: neutral base plus penalty that shrinks when the item is large
    // or the fit elsewhere would be terrible. A fresh bin is attractive when mean
    // residual across open bins is small (they are all nearly full).
    if bin_residual == bin_capacity {
        score = 45.0 - 0.2 * (item_size as f64) - 0.4 * mean_residual.max(0.0) + 10.0 * progress;
        // If the only alternative is a bad fit, opening a new bin is fine.
        if fitting_bins_count <= 1 {
            score -= 15.0;
        }
        // Never open a new bin for a tiny item when good space exists.
        if item_size < 30 && mean_residual > 40.0 {
            score += 25.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    let mut score = pr as f64;

    // Smooth non-linear coupling: penalize small-but-nonzero post residual more as stream progresses
    let tight = 1.0 - norm_pr;
    score -= 6.0 * tight * tight * (0.5 + progress);

    // Penalize dead space quadratic in normalized residual, weighted by progress
    score += 8.0 * norm_pr * norm_pr * (1.0 + progress);

    // Reward exact-ish fits with cubic shaping
    score -= 12.0 * (1.0 - norm_pr).powi(3);

    // Last-chance bin bonus (smooth via fitting count ratio)
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - progress);
    }

    // Lookahead: reward leaving room for next item, smoothly
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        let gap = (pr - ni).abs();
        score += 4.0 * (gap / cap) * (gap / cap);
        if pr >= ni {
            score -= 3.0 * (1.0 - progress) * (ni / cap);
        }
    }

    // Mild penalty for spreading across many bins early
    score += 0.05 * open_bins_count as f64 * progress;

    // Mean residual coupling: prefer bins near mean
    let dev = (pr - mean_residual) / cap;
    score += 3.0 * dev * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
