pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps harshly.
    // A gap is "dead" if no plausible future item (min size 1, but typical
    // sizes are much larger) can use it. Treat gaps below a threshold as waste.
    let dead_threshold = 10.0;
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += 40.0 * (dead_threshold - post_residual as f64) / dead_threshold;
    }

    // Perfect fit bonus: strongly reward leaving exactly zero residual.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Penalize leaving a gap that cannot fit the next item when the next item
    // could have co-fit here instead (lookahead coupling).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }
    // Reward a residual that still accommodates the lookahead item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 5.0;
    }

    // Last-chance pressure: if this is the only fitting bin, prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Open-bin pressure: when many bins are open, discourage opening new ones
    // and encourage consolidating into existing bins.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportionally to open bin pressure.
        score += 15.0 + 10.0 * pressure;
        // But if no existing bin fits well, allow a new bin via fitting count.
        if fitting_bins_count == 0 {
            score -= 25.0;
        }
    } else {
        // Existing bin: slight reward for fitting, scaled by pressure.
        score -= 3.0 * pressure;
    }

    // Mild preference for tighter existing bins relative to mean residual.
    if bin_residual != bin_capacity {
        let tightness = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
        score += 6.0 * tightness;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect fit (dead space elimination).
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Penalize small unusable residuals (< 10, minimum item size).
        if post_residual < 10 {
            score += 50.0;
        }
        // 2-step lookahead: reward exact match of next item into post residual.
        if next_item_size > 0 && next_item_size == post_residual {
            score -= 400.0;
        } else if next_item_size > 0 && next_item_size <= post_residual {
            // Next item still fits: mild reward scaled by tightness of fit.
            let slack = (post_residual - next_item_size) as f64;
            score -= 40.0 * (1.0 - slack / bin_capacity as f64);
        } else if next_item_size > post_residual {
            // Next item cannot follow in this bin: penalize proportionally.
            score += 30.0;
        }
    }

    // Prefer bins with residuals below mean residual (tighter bins used first).
    let mean_r = if mean_residual.is_finite() { mean_residual } else { bin_capacity as f64 };
    if (bin_residual as f64) < mean_r {
        score -= 15.0;
    } else {
        score += 15.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // Mild penalty for spreading across too many open bins early in stream.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if open_bins_count > 4 && progress < 0.5 {
        score += 5.0;
    }

    // New-bin candidate: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        score += 80.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits: quadratic bonus for small post_residual.
    score -= 2.0 * ((cap - post_residual as f64) / cap).powi(3) * 10.0;

    // Perfect fit is excellent.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 10 {
        score -= 15.0;
    }

    // Penalize creating dead space too small for the smallest item.
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // Lookahead: if the next item fits exactly into the post-residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            let slack_waste = (post_residual - next_item_size) as f64;
            score -= 10.0 * (1.0 - slack_waste / cap);
        } else {
            // Next item cannot use this bin's remainder; slight penalty if remainder is large.
            score += 3.0 * (post_residual as f64 / cap);
        }
    }

    // Last chance: if this is the only bin that fits, prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: make it attractive only when existing bins fit poorly.
    if bin_residual == bin_capacity {
        score = cap * 0.6 + mean_residual * 0.2;
        if fitting_bins_count == 0 {
            score -= 100.0; // nothing fits, must open
        }
        // Early in stream, more open bins is fine; late, prefer consolidation.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += progress * 10.0;
    }

    // Prefer bins whose residual is far below the mean (already fragmented) to absorb items,
    // keeping larger residuals available for future large items.
    let diff = (bin_residual as f64 - mean_residual) / cap;
    score += 8.0 * diff;

    // Prefer bins with moderate residual over near-empty ones when item is small.
    if item_size <= 30 && bin_residual > bin_capacity / 2 {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let pr_norm = pr / cap;
    let item = item_size as f64;

    // Base: minimize post residual, smoothed by polynomial coupling with progress
    let mut score = pr * (1.0 + 0.6 * progress * progress);

    // Non-linear penalty for awkward small-but-nonzero post residuals (dead space)
    let dead = pr_norm * (1.0 - pr_norm); // peaks at half-full residual
    score += 8.0 * dead * (0.5 + progress);

    // Reward tight fits more strongly later in the stream
    score -= (cap - pr) * 0.15 * (1.0 + progress);

    // Last-chance bonus: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 * (1.0 - pr_norm);
    }

    // New-bin candidate: penalize mildly early, allow opening when residual would be tiny
    let is_new = bin_residual == bin_capacity;
    if is_new {
        score += 12.0 - 8.0 * progress;
        // If the next item could fill the new bin well, encourage opening it
        if next_item_size > 0 {
            let nxt = next_item_size as f64;
            let future_fit = (pr - nxt).max(0.0);
            score -= 0.2 * future_fit;
        }
    } else {
        // Penalize bins that deviate from mean residual (keep diversity balanced)
        let dev = (bin_residual as f64 - mean_residual) / cap;
        score += 4.0 * dev * dev;
    }

    // Lookahead: reward leaving room for the next item
    if next_item_size > 0 && !is_new {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= 6.0 * (1.0 - (pr - nxt) / cap) * (0.5 + progress);
        } else {
            score += 3.0 * (nxt - pr) / cap;
        }
    }

    // Slight preference to consolidate into fewer bins when many are open
    score += 0.05 * open_bins_count as f64 * pr_norm;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the item: which capacity fraction band it belongs to.
    let item_class = item_size / 25;                       // 0..3 (1-24, 25-49, 50-74, 75-100)
    let post_class = post_residual / 25;                   // harmonic band of leftover space
    let next_class = (next_item_size as u32).min(bin_capacity) / 25;

    // Reward placements whose post-residual lands in a "harmonic" class that
    // a future item of a known class can still pair with.
    // A leftover is useful if it can hold a plausible next item (>= 1).
    if post_residual > 0 {
        // penalty grows super-linearly for dead space that nothing can fill
        let dead = post_residual < 10;
        if dead {
            score += 60.0;
        } else {
            // residual that exactly complements common item classes is valuable
            let complement = (bin_capacity - post_residual) as f64;
            score -= 0.35 * (100.0 - (complement - item_size as f64).abs());
        }
    } else {
        // perfect fill: strongly reward
        score -= 120.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post-residual,
    // this is an ideal chaining placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = post_residual - next_item_size;
        score -= 45.0 - (slack as f64) * 0.4;
    } else if next_item_size > 0 && next_item_size > post_residual {
        score += 8.0;
    }

    // Integer-division threshold on post_residual: leftovers below 25 are
    // nearly dead (min item size 1..100 unknown, but small leftovers rarely
    // pair well) -> push score up so bigger residuals win ties.
    if post_class == 0 && post_residual > 0 {
        score += 15.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 70.0;
    }

    // New-bin candidate: only attractive when the item is huge relative to
    // capacity or no good fit exists among open bins.
    if bin_residual == bin_capacity {
        let tight_fit = fitting_bins_count <= 1 && item_size as f64 > 0.6 * bin_capacity as f64;
        if tight_fit {
            score -= 30.0;
        } else {
            score += 40.0 + 0.5 * open_bins_count as f64;
        }
    }

    // Mean-residual coupling: when open bins are already slack, prefer packing
    // tightly into them rather than spreading.
    if (mean_residual - post_residual as f64).abs() < 10.0 {
        score -= 10.0;
    }

    // Stream progression: late in the stream, avoid opening new bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score += 25.0 * progress;
    }

    // Modulo arithmetic tie-breaker on post_residual: multiples of small
    // harmonic units (10, 20, 25, 50) are more reusable.
    let reusable = post_residual % 10 == 0 || post_residual % 25 == 0;
    if reusable {
        score -= 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize unusable small gaps harshly.
    // A residual that is too small for the smallest plausible item (<= ~10)
    // is dead space; gaps between 1 and 12 are worst.
    if post_residual > 0 && post_residual <= 12 {
        score += 60.0 * (13.0 - post_residual as f64) / 13.0;
    }
    // Also penalize gaps that cannot fit the lookahead item (wasted for k=2).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0 + (next_item_size as f64 - post_residual as f64) * 0.5;
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidation into
    // existing bins; opening new bins becomes expensive.
    let pressure = open_bins_count as f64 / (1.0 + mean_residual.max(1.0) / 20.0);
    score += pressure * 2.5;

    // Last-chance bin: if this is the only fitting bin, strongly prefer it
    // over opening a fresh bin (which would waste the remaining residual).
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate (empty bin): penalize opening a new bin unless the
    // current bin would be left with tiny dead space.
    if bin_residual == bin_capacity {
        let dead_left = if post_residual <= 12 && post_residual > 0 { 40.0 } else { 0.0 };
        score += 30.0 + dead_left;
        // Early in the stream, new bins are cheaper to open.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 25.0 * (1.0 - progress);
    }

    // Slight preference for tighter bins (smaller pre-residual) to keep
    // large residuals available for large future items.
    score += (bin_residual as f64) * 0.05;

    // Mean-residual coupling: when mean residual is small, avoid spreading.
    score += (mean_residual - post_residual as f64).abs() * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
