pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Prefer tight fits: reward small post_residual relative to item size.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += fit_ratio * (bin_capacity as f64 - item_size as f64) * 0.5;

    // Penalize using a very full bin for a small item (waste of a tight slot).
    if (bin_residual as i64 - item_size as i64) > 20 && bin_residual < 40 {
        score += (40.0 - bin_residual as f64) * 2.0;
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 60.0;
    } else {
        // Mild penalty spread when many bins compete (prefer the emptiest-ish).
        score += (fitting_bins_count as f64).ln() * 2.0;
    }

    // Lookahead: if next item fits into the post_residual, reward; else penalize.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= (post_residual - next_item_size) as f64 * 0.3;
        } else {
            score += (next_item_size - post_residual) as f64 * 0.2;
        }
    }

    // Global state coupling: when mean residual is high, prefer filling emptier bins.
    score += (mean_residual - post_residual as f64) * 0.15;

    // Time horizon: later in the stream, be more conservative about dead space.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.4;

    // New-bin candidate: only attractive when current bins fit poorly.
    if bin_residual == bin_capacity {
        score += 8.0 + mean_residual * 0.1;
        if fitting_bins_count <= 1 {
            score -= 40.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: penalize wasted space, amplified non-linearly by stream progress
    let mut score = pr * (1.0 + 2.0 * progress * norm_pr);

    // Dead-space penalty: small post-residuals are hard to fill
    if pr > 0.0 && pr < item_size as f64 {
        score += (cap - pr) * 0.15 * (1.0 - norm_pr) * (1.0 - norm_pr);
    }

    // Perfect fit reward (smooth, non-linear)
    if pr == 0.0 {
        score -= 20.0 * (1.0 + progress);
    }

    // Lookahead coupling: reward bins whose post-residual matches next item
    if next_item_size > 0 {
        let n = next_item_size as f64;
        let fit_gap = ((pr - n) / cap).abs();
        score -= 8.0 * (1.0 - fit_gap).max(0.0) * (1.0 - progress);
        // If next item cannot fit here, mild penalty for wasting this bin
        if n > pr {
            score += 3.0 * (1.0 - progress);
        }
    }

    // Last-chance bonus: only fitting bin -> strongly prefer it
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Prefer bins below mean residual (tighter bins) with smooth coupling
    score -= 2.0 * (mean_residual - pr) / cap;

    // Mild new-bin discouragement when many bins open
    if bin_residual == bin_capacity {
        score += 4.0 + 2.0 * (open_bins_count as f64).sqrt();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residues modulo 10 define
    // "usable" vs "dead" space classes. Small residues (0..9) are dead space.
    let dead = post_residual % 10;
    score += dead as f64 * 1.5;

    // Perfect / near-perfect fit classes get strong reward.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Harmonic complement: does the post residual pair well with typical
    // next item sizes? Reward if next item fits exactly or near-exactly.
    if next_item_size > 0 && next_item_size <= post_residual {
        let next_post = post_residual - next_item_size;
        if next_post == 0 {
            score -= 30.0;
        } else {
            score += next_post as f64 * 0.8;
            // penalize residues that leave awkward harmonic classes
            if next_post % 10 == 0 {
                score -= 5.0;
            }
        }
    } else if next_item_size > 0 {
        // next item cannot fit here: mild penalty, this bin becomes dead
        score += 8.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is bad.
    if bin_residual == bin_capacity {
        score += 45.0;
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            score -= 25.0; // big items pair well with future big items
        }
    }

    // Fraction-of-capacity harmonic thresholds on post_residual.
    let cap = bin_capacity as f64;
    let frac = post_residual as f64 / cap;
    if frac > 0.5 {
        score -= 6.0;      // still half usable: good bin
    } else if frac < 0.1 {
        score += 6.0;      // nearly dead bin
    }

    // Stream progression: late in the stream, prefer tighter packing.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.3 * progress;

    // Prefer bins with below-average residual (denser bins).
    score += (mean_residual - bin_residual as f64) * 0.15;

    // Many open bins: encourage consolidation into existing bins.
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Base: prefer small post_residual (tight fit).
    let mut score = post;

    // Strict dead-space avoidance: gaps in the "unusable" band
    // (too small to hold anything useful, i.e. < 10-ish or < next item)
    // are heavily penalized.
    let min_item = 1.0f64;
    if post > 0.0 && post < min_item * 10.0 {
        score += 60.0; // tiny dead gap: worthless space
    }
    if next_item_size > 0 && (post_residual as u64) < (next_item_size as u64) && post_residual > 0 {
        // gap can't fit the known next item -> dead space risk
        score += 25.0 + 0.5 * (next_item_size as f64 - post);
    }

    // Reward near-perfect fits.
    if post == 0 {
        score -= 80.0;
    } else if post <= 5.0 {
        score -= 30.0;
    }

    // Open-bin pressure: with many bins open, prefer reusing existing bins
    // (packing density) over opening new ones.
    score += open_bins_count as f64 * 1.5;

    // New-bin candidate: make empty bins moderately attractive only when
    // current bin fits are poor (large post_residual) or few bins fit.
    if bin_residual == bin_capacity {
        // baseline cost of a fresh bin
        score += cap * 0.6;
        // relax cost if this is a last-chance-free situation or fits are loose
        if post_residual == bin_capacity && item_size as f64 > cap * 0.5 {
            score -= cap * 0.35; // big item into fresh bin is fine
        }
        if fitting_bins_count == 0 {
            score -= cap * 0.5;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly favor it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual,
    // reward leaving that gap.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 45.0;
    } else if next_item_size > 0 && post_residual > next_item_size {
        // gap still usable for next item: mild reward proportional to slack
        score -= 5.0;
    }

    // Mean-residual coupling: if this bin's residual is far above the mean,
    // it is a good candidate to absorb the item (consolidate space).
    let residual = bin_residual as f64;
    let dev = residual - mean_residual;
    score -= dev * 0.3;

    // Stream progression: late in the stream, be greedier about tight fits.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - post / cap) * progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post_residual).
    if post_residual == 0 {
        score -= 60.0; // perfect fill
    } else if post_residual < 10 {
        score -= 30.0;
    } else if post_residual < 20 {
        score -= 10.0;
    }

    // 2-step lookahead: if the next item exactly fills the post_residual,
    // this is a chained perfect fit — heavily favor it.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            // next item fits: good chaining, scaled by how much remains after
            let after2 = post_residual as i64 - next_item_size as i64;
            score -= (20.0 * (1.0 - after2 as f64 / bin_capacity as f64)).max(0.0);
        } else {
            // next item cannot use this bin's remainder: penalize dead space
            score += (post_residual as f64 - mean_residual).max(0.0) * 0.3;
        }
    }

    // Relative-to-mean residual: prefer bins with less residual than average
    // (consolidating space), penalize dumping into already-loose bins.
    score += ((post_residual as f64 - mean_residual) * 0.4).max(0.0);

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when the item is large relative to
    // capacity and open bins are crowded (mean residual small).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let crowding = mean_residual / bin_capacity as f64;
        // prefer new bin when item barely fits typical open bins
        let tight = (item_size as f64 / bin_capacity as f64) > 0.6;
        if tight && crowding < 0.25 {
            score -= 15.0 + 10.0 * progress;
        } else {
            score += 40.0; // discourage opening bins when fits exist
        }
    }

    // Mild pressure to use fewer bins early vs late in the stream.
    score += 0.05 * open_bins_count as f64 * (1.0 - step_index as f64 / total_items.max(1) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize large post_residual relative to capacity.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 8.0 * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Penalize dead space: residual too small for the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Last-chance bonus: only this bin fits; strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if the next item can use this bin's post_residual, reward it.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 10.0;
        } else {
            // Next item won't fit here; penalize wasting space if post_residual is large.
            score += 0.05 * (post_residual as f64 - mean_residual).abs();
        }
    }

    // New-bin candidate logic: empty bin should only win when fits are poor.
    if bin_residual == bin_capacity {
        // Mild penalty so open bins with good fits win by default.
        score += 5.0;
        // But if many open bins exist and mean residual is fragmented, opening fresh is fine.
        if open_bins_count > 3 && mean_residual < 25.0 {
            score -= 15.0;
        }
        // Late in stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    }

    // Prefer fuller bins (smaller bin_residual) among open bins.
    score += 0.03 * (bin_residual as f64 - mean_residual);

    // Slight preference to spread across bins when few are open.
    if open_bins_count < 2 {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 + 2.0 * progress) + norm_pr * (1.0 - progress) * 0.5;

    let mut score = pr * (1.0 + poly);

    // Penalize dead space more aggressively as the stream advances
    score += (norm_pr * norm_pr) * cap * progress;

    // Reward tight fits (small post_residual) with a non-linear bonus
    let tight = 1.0 - norm_pr;
    score -= tight * tight * item_size as f64 * (0.3 + 0.4 * progress);

    // Last-chance bin: strong non-linear reward to avoid opening new bins late
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0 * (0.5 + 0.5 * progress) * (1.0 + norm_pr);
    }

    // New-bin candidate: prefer it only when post_residual is large (item leaves room)
    if bin_residual == bin_capacity {
        score += 12.0 + 30.0 * progress * (1.0 - norm_pr);
        if next_item_size as f64 > 0.0 && next_item_size as f64 <= pr {
            score -= 8.0 * (1.0 - progress);
        }
    }

    // Lookahead: reward bins whose post residual can still host the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            let slack = (pr - nx) / cap;
            score -= 10.0 * (1.0 - slack) * (1.0 - 0.5 * progress);
        } else {
            score += 6.0 * (1.0 - progress);
        }
    }

    // Mild dispersion penalty: prefer bins near the mean residual
    let dev = (bin_residual as f64 - mean_residual).abs() / cap;
    score += dev * dev * 15.0;

    // Crowd penalty grows smoothly with open bins
    score += (open_bins_count as f64).ln() * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo arithmetic on residual space.
    // Residuals that are "harmonic" (divisible by common item sizes) are more reusable.
    let pr = post_residual;
    let mut harmony_bonus = 0.0;
    for m in [10u32, 20, 25, 50].iter() {
        if pr > 0 && pr % m == 0 {
            harmony_bonus += 6.0;
        }
    }
    if pr == 0 {
        harmony_bonus += 40.0; // perfect fill
    }
    score -= harmony_bonus;

    // Integer division thresholds on post_residual: penalize dead space bands.
    if pr > 0 && pr < 10 {
        score += 30.0; // unusable sliver
    } else if pr < 25 {
        score += 8.0;
    }

    // Coupling with next item: does this residual class fit the lookahead?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // prefer exact harmonic fit for next item
            if pr % next_item_size.max(1) == 0 {
                score -= 12.0;
            } else {
                score -= 4.0;
            }
        } else {
            score += 5.0; // next item cannot use this bin
        }
    } else {
        // last item: prefer zero residual
        score += pr as f64 * 0.5;
    }

    // Last-chance bin: strong reward to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bin would leave bad residue.
    if bin_residual == bin_capacity {
        let waste_if_used = if pr > 0 && pr < 10 { 20.0 } else { 0.0 };
        score += 15.0 + waste_if_used + (open_bins_count as f64).sqrt() * 2.0;
        if fitting_bins_count == 1 {
            score += 60.0; // never open new bin when a last-chance bin exists
        }
    }

    // Tight-fit reward.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= tightness * 10.0;

    // Mild diversity pressure via mean residual.
    score += (mean_residual - post_residual as f64) * 0.05;

    // Stream progression: later in stream, be greedier about filling bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: any small unusable gap is heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 12.0; // gap only usable by tiny items: mild penalty
    }

    // Reward tight fits (post_residual near zero but not dead).
    if post_residual == 0 {
        score -= 25.0;
    } else {
        // relative fit quality: fraction of residual consumed
        let fill_ratio = item_size as f64 / bin_residual as f64;
        score -= 20.0 * fill_ratio;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; favor consolidation.
    let pressure = open_bins_count as f64 / (1.0 + mean_residual / 20.0);
    score += 2.5 * pressure;

    // New-bin candidate: only attractive when no open bin fits well or lookahead
    // suggests the current item is small and better saved for later gaps.
    if bin_residual == bin_capacity {
        score += 45.0; // base cost of opening a new bin
        if fitting_bins_count <= 1 {
            score -= 40.0; // last resort: opening new bin is fine
        }
        if next_item_size > 0 && next_item_size >= item_size && post_residual >= next_item_size {
            score -= 10.0; // fresh bin can serve the next (larger) item too
        }
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * (1.0 - progress); // early on, avoid bin proliferation
    }

    // Lookahead coupling: if next item fits exactly in post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap < 10 {
            score -= 15.0; // enables a near-perfect follow-up placement
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 8.0; // leftover can't serve next item
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for exact 2-step lookahead match: item + next item fills bin perfectly.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Reward near-exact matches (small slack after hypothetically placing next item).
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Next item cannot fit here; penalize dead space below next item size.
        let dead = (next_item_size - post_residual) as f64;
        score += 0.8 * dead.min(30.0);
    }

    // Penalize leaving small unusable gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Compare against mean residual: placing in a bin far below mean residual
    // (tight bin) is good; placing in a loose bin wastes its capacity.
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when residuals are fragmented
    // (few fitting bins or high mean residual spread).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = (mean_residual / bin_capacity as f64 - 0.5).max(0.0);
        score = 45.0 + 40.0 * fragmentation + 20.0 * progress;
        if fitting_bins_count <= 1 {
            score -= 30.0; // no good alternative: new bin is fine
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: quadratic penalty on post_residual
    score += (post_residual as f64 / bin_capacity as f64).powi(2) * 40.0;

    // Perfect fit gets a strong bonus
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual < 10 {
        score -= 15.0;
    }

    // Dead-space penalty: residuals too small for the smallest possible item
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Lookahead: if next item fits exactly in post_residual, strong bonus
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 80.0;
        } else if next_item_size < post_residual {
            score -= 10.0;
        } else {
            // next item won't fit here; slight penalty proportional to leftover
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 {
        score -= 50.0;
    }

    // Prefer bins with low residual relative to mean (denser bins first)
    score += (mean_residual - bin_residual as f64) * 0.5;

    // New-bin candidate logic: opening a new bin is only good when item is large
    // or all fits are poor; make the empty bin less attractive otherwise.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        // large items early: new bin fine; small items: discourage
        score += 55.0 - fill_ratio * 70.0 + (1.0 - progress) * 10.0;
        if fitting_bins_count > 0 && fill_ratio < 0.5 {
            score += 25.0;
        }
    }

    // Mild encouragement to consolidate when many bins are open
    if open_bins_count > 5 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = x * x * (1.0 - x) * (1.0 - x);
    let coupling = poly * (progress - 0.5) * 2.0;

    let mut score = pr;

    // Reward tight fits more strongly as stream progresses (smooth interaction)
    score -= 40.0 * progress * poly;

    // Penalize dead space that cannot fit the lookahead item (smooth gate via residual ratio)
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let usable = (x * cap / nx).min(1.0);
        score -= 12.0 * usable * usable;
        score += 8.0 * (1.0 - usable) * (1.0 - usable) * progress;
    }

    // Last-chance bin bonus (smooth in fitting count)
    let fit_factor = 1.0 / fitting_bins_count as f64;
    score -= 6.0 * fit_factor * (0.5 + progress);

    // Deviation from mean residual, scaled by openness
    let dev = (pr - mean_residual) / cap;
    score += 10.0 * dev * dev * (open_bins_count as f64).ln().max(1.0);

    // Apply smooth polynomial coupling term
    score += 25.0 * coupling;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 10 {
        score -= 12.0;
    }

    // Harmonic class logic: classify post_residual into residue classes mod 10.
    // Dead space that no future item (min size 10... but interface says >=1) can use is bad.
    // Residuals that are multiples of 10 are highly reusable.
    let pr = post_residual;
    if pr > 0 {
        let cls = pr % 10;
        // Multiples of 10 are "harmonic" with common item sizes: reward them.
        if cls == 0 {
            score -= 8.0;
        } else if cls == 5 {
            score -= 3.0;
        } else {
            // Awkward sliver classes get penalized proportionally.
            score += (10 - cls) as f64 * 0.8;
        }
    }

    // Integer division thresholds: residual in [1..=item_min) is dead space.
    let dead_threshold = 10u32.min(bin_capacity / 10);
    if pr > 0 && pr < dead_threshold {
        score += 20.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        // With multiple options, prefer tighter fits more aggressively.
        score += 3.0 * (fitting_bins_count as f64 - 1.0);
    }

    // Lookahead: if next item fits exactly in the post residual, big reward.
    if next_item_size > 0 && next_item_size <= pr {
        let slack = pr - next_item_size;
        if slack == 0 {
            score -= 35.0;
        } else if slack <= 10 {
            score -= 15.0;
        } else {
            score -= 5.0;
        }
        // Penalize leaving residual that the next item cannot use at all.
        if next_item_size > pr {
            score += 6.0;
        }
    }

    // New-bin candidate handling: an empty bin should only win when current fit is bad.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 55.0;
        // Cheaper to open new bin early in stream (more future items to fill it).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 25.0 * (1.0 - progress);
        // If no bin fits, opening is mandatory-ish.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        // If next item is large, a fresh bin is attractive.
        if next_item_size >= bin_capacity / 2 {
            score -= 10.0;
        }
    }

    // Prefer filling bins that are already mostly full (low residual) to consolidate.
    let fill_frac = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= 10.0 * fill_frac;

    // Slight pressure against bin sprawl.
    score += 0.5 * open_bins_count as f64;

    // Mean residual coupling: if mean residual is large, spreading items is less costly.
    score -= 0.05 * mean_residual;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small nonzero gaps are the worst outcome.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual == 0 {
        // Perfect fit is highly desirable.
        score -= 30.0;
    } else if post_residual >= 10 {
        // Larger gaps remain reusable; reward proportionally to reusability.
        score -= 0.2 * (post_residual as f64 - 10.0).min(40.0);
    }

    // Last chance: only one open bin can fit this item -> strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, favor filling.
    let pressure = open_bins_count as f64 / 10.0;
    if bin_residual != bin_capacity {
        score += pressure * 2.0;
    } else {
        // New-bin candidate: penalize slightly so we only open when open bins are bad.
        score += 15.0 + pressure * 3.0;
        // But if the item is large and would leave a big reusable gap, opening is fine.
        if item_size >= bin_capacity / 2 {
            score -= 20.0;
        }
    }

    // Lookahead: if next item fits in the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Dead space for the known next item: penalize.
        score += 10.0;
    }

    // Prefer bins whose residual is below the mean (fill the emptier-tail bins).
    if bin_residual != bin_capacity {
        score += 0.1 * (bin_residual as f64 - mean_residual);
    }

    // Early in the stream, allow more bins (future flexibility); late, consolidate.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= (1.0 - progress) * 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward exact/near-exact matches with the next item (2-step lookahead).
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        score -= 60.0 * (1.0 - gap / (bin_capacity as f64));
    } else if next_item_size > 0 {
        // Dead space that cannot host the next item: penalize small leftovers hard.
        score += 25.0 * (1.0 - (post_residual as f64) / (bin_capacity as f64));
    }

    // Perfect closure (no waste) is ideal.
    if post_residual == 0 {
        score -= 80.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Penalize wasting a very large bin on a small item when the fit is loose.
    let tightness = item_size as f64 / bin_residual as f64;
    score += 15.0 * (1.0 - tightness);

    // Prefer keeping residuals near the mean to preserve flexibility.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.1 * dev;

    // New-bin candidate: baseline slightly above well-fitting open bins,
    // but attractive when open bins would leave ugly dead space.
    if bin_residual == bin_capacity {
        score = bin_capacity as f64 - 30.0 + 0.05 * (next_item_size as f64);
    }

    // Early in the stream, be more willing to open bins for large items.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if item_size > 60 && progress < 0.5 {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: the closer post_residual is to 0, the better.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 25.0 * tightness * tightness;

    // Penalize leaving dead space that cannot fit typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0; // tiny unusable slivers
    }

    // Lookahead: if the next item fits exactly in post_residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 10.0 * (next_item_size as f64 / post_residual.max(1) as f64);
        } else {
            // next item won't fit here; penalize large leftover gaps slightly
            score += 5.0 * (post_residual as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin to avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Time horizon: early in the stream, be more conservative (favor filling existing bins
    // less aggressively to keep flexibility); late in the stream, close bins out fully.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress * tightness;

    // Global pressure: many open bins with high mean residual -> encourage consolidation.
    if open_bins_count > 2 && mean_residual > 0.0 {
        let pressure = (post_residual as f64 - mean_residual) / bin_capacity as f64;
        score += 8.0 * pressure; // prefer bins with below-average residual (already well filled)
    }

    // New-bin candidate: penalize opening a new bin unless the item is large relative to
    // capacity or no good fits exist. Empty bin has post_residual = capacity - item_size.
    if bin_residual == bin_capacity {
        let item_frac = item_size as f64 / bin_capacity as f64;
        score += 20.0 - 25.0 * item_frac; // large items justify a fresh bin; small ones don't
        if fitting_bins_count > 0 && item_frac < 0.5 {
            score += 15.0; // existing bins can take small items; don't open new bin
        }
    }

    // Mild fragmentation penalty for mid-range leftovers.
    if post_residual >= 10 && post_residual <= 30 {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits (low post residual), with smooth polynomial shaping
    let mut score = pr;

    // Smooth non-linear coupling of post_residual with stream progress:
    // later in the stream, dead space becomes more costly -> amplify post_residual
    let progress_coupling = 1.0 + 2.0 * progress * norm_pr * (1.0 - norm_pr * 0.5);
    score *= progress_coupling;

    // Penalize very small post residuals that are likely dead space
    // (smooth quadratic bump around small-but-nonzero residuals)
    let dead_threshold = 10.0;
    let deadness = ((dead_threshold - pr) / dead_threshold).max(0.0);
    score += 6.0 * deadness * deadness * (0.5 + progress);

    // Reward last-chance bins (only fitting bin) — smooth exponential reward
    if fitting_bins_count == 1 {
        score -= 8.0 * (1.0 + progress);
    } else if fitting_bins_count > 1 {
        // mild penalty for many alternatives to encourage diversity
        score += 1.5 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // Lookahead: if next item fits smoothly in post_residual, reward this bin
    if next_item_size > 0 {
        let next_fits = (post_residual as u32 >= next_item_size) as i32 as f64;
        let slack = (pr - next_item_size as f64).abs() / cap;
        score -= 5.0 * next_fits * (1.0 - slack) * (1.0 - 0.5 * progress);
    }

    // Compare against mean residual: bins far from mean residual get mild penalty
    let mean_norm = mean_residual / cap;
    score += 3.0 * (norm_pr - mean_norm).abs();

    // New-bin candidate handling: only prefer fresh bin when no open bin fits well
    let is_new_bin = (bin_residual as f64 - cap).abs() < 1e-6;
    if is_new_bin {
        // opening a new bin: penalize unless item is large relative to capacity
        let largeness = item_size as f64 / cap;
        score = 0.5 * cap + 20.0 * (1.0 - largeness) - 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Strong reward for tight fits: post_residual is the dominant term already.
    // Add a super-linear penalty on larger leftovers (dead space).
    let pr = post_residual as f64;
    score += 0.015 * pr * pr / cap;

    // Harmonic classes: bins whose post_residual falls into "small residue"
    // classes are more valuable; penalize residues that are likely unusable.
    let residue_class = post_residual % 10;
    let class_penalty: f64 = match residue_class {
        0 => -6.0,                       // perfectly flush-ish residue
        1..=3 => -2.0,                   // small residue, likely dead but tight now
        4..=6 => 0.0,
        7..=9 => 3.0,                    // awkward mid residue
        _ => 0.0,
    };
    score += class_penalty;

    // Integer-division thresholds on post_residual: residues below the smallest
    // plausible item are dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0; // dead space that nothing can ever use
    }

    // Lookahead coupling: reward if next item fits exactly in post_residual,
    // penalize if next item cannot fit (bin becomes useless for lookahead).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 12.0; // perfect chaining opportunity
        } else if next_item_size <= post_residual {
            score -= 4.0 * (post_residual - next_item_size) as f64 / cap;
        } else {
            score += 2.0; // next item won't fit here anyway
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 10.0;
    }

    // New-bin candidate handling: an empty bin should only win when open bins
    // fit poorly. Give it a mild penalty so decent fits beat it, but allow it
    // to win when post_residual elsewhere would be terrible.
    if bin_residual == bin_capacity {
        score = 55.0 + 0.05 * open_bins_count as f64;
        // If the current item is small relative to capacity, opening fresh is fine.
        if (item_size as f64) < 0.25 * cap {
            score -= 10.0;
        }
    }

    // Slight preference to fill bins with larger residuals early (keep tight
    // bins available), modulated by stream progress.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= (1.0 - progress) * (bin_residual as f64 - mean_residual) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps are heavily penalized.
    let min_item = 1u32;
    if post_residual < min_item {
        score -= 1000.0; // perfect fit
    } else if post_residual < 10 {
        score += 120.0; // dead space below minimum item size
    } else if post_residual < 20 {
        score += 40.0;
    }

    // Penalize gaps too small for the lookahead item (k=2 lookahead).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 25.0 + (next_item_size - post_residual) as f64 * 0.5;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // Reward bins that can also host the next item.
        score -= 8.0;
    }

    // Reward tight fits (post_residual small relative to residual).
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fill_ratio;

    // Open-bin pressure: discourage spreading across many bins.
    score += open_bins_count as f64 * 2.0;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate handling: only attractive when no open bin fits well
    // (i.e., mean residual is small relative to the item) or stream is early.
    if bin_residual == bin_capacity {
        let pressure = if mean_residual < item_size as f64 * 1.2 { 0.0 } else { 150.0 };
        score = bin_capacity as f64 - 20.0 + pressure
            - (1.0 - step_index as f64 / total_items.max(1) as f64) * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Next item still fits in the leftover space (good chaining).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 + 0.15 * next_item_size as f64;
    } else if next_item_size > 0 {
        // Leftover space too small for the next item: penalize dead space,
        // worse when the leftover is tiny (unusable).
        let waste = post_residual as f64;
        score += 12.0 * (1.0 - waste / bin_capacity as f64);
    }

    // Reward tight fills relative to mean residual of open bins.
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Last fitting bin: strong preference to use it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Mild penalty for opening a brand-new bin while open bins exist,
    // unless the current bin is empty-ish and item is large.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 - 10.0 * progress;
        if item_size > bin_capacity / 2 {
            score -= 12.0; // big items fine in a fresh bin
        }
    }

    // Prefer bins with less residual overall (tighter packing).
    score += 0.05 * bin_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness: reward filling bins snugly (small post_residual relative to item).
    let tight = (item_size as f64) / (bin_residual.max(1) as f64);
    score -= 18.0 * tight * (item_size as f64 / bin_capacity as f64);

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual < 10 {
        score -= 12.0;
    }

    // Lookahead: bonus if next item fits exactly into post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 55.0;
        } else if next_item_size <= post_residual {
            score -= 10.0;
        } else {
            // next item won't fit here; penalize leaving medium dead space
            score += 0.25 * post_residual as f64;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Penalize opening a new bin when open bins exist with decent residual.
    if bin_residual == bin_capacity {
        if open_bins_count > 0 {
            // new-bin candidate: only attractive if item is large and residuals are small
            let avg_tight = mean_residual / bin_capacity as f64;
            score += 25.0 * avg_tight;
            if item_size >= 60 {
                score -= 15.0;
            }
            // early stream: prefer consolidation into open bins
            let t = step_index as f64 / (total_items.max(1) as f64);
            score += 20.0 * (1.0 - t);
        } else {
            score -= 50.0; // must open first bin
        }
    } else {
        // mild preference for fuller bins among open ones
        score -= 0.1 * (bin_capacity - bin_residual) as f64;
    }

    // Dead-space penalty: residuals that are too small for typical items.
    if post_residual > 0 && post_residual < 5 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;

    // Base: prefer low post-residual, with smooth polynomial shaping
    let mut score = post * (1.0 + 0.5 * norm_post * norm_post);

    // Tight fits (small post_residual relative to capacity) get extra reward
    let tightness = 1.0 - norm_post;
    score -= 25.0 * tightness.powi(3) * (0.5 + progress);

    // Penalize dead space: post_residual that no typical item can use
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post < nxt {
            // dead space before next item arrives
            score += 8.0 * (nxt - post) / cap * (1.0 + 2.0 * progress);
        } else {
            // reward bins that can also host the next item
            score -= 6.0 * (1.0 - (post - nxt) / cap) * 0.0 + 4.0 * (1.0 - ((post - nxt) / cap).min(1.0));
        }
    }

    // Last-chance bonus: avoid opening a new bin when this is the only fitting one
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - norm_post);
    }

    // Late stream: consolidate into fewer bins
    let pressure = progress * (open_bins_count as f64 / (open_bins_count as f64 + 5.0));
    score -= 10.0 * pressure * (1.0 - norm_post);

    // Interaction: bin residual vs mean residual — prefer bins tighter than average
    let rel = (bin_residual as f64 - mean_residual) / cap;
    score += 5.0 * rel * (0.5 + progress);

    // New-bin candidate: smooth penalty growing with stream progress and open bins
    if bin_residual == bin_capacity {
        score += 20.0 + 30.0 * progress + 2.0 * (open_bins_count as f64).sqrt();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues mod 10 define "usable" niches
    let pr = post_residual;
    let residue = (pr % 10) as f64;
    // Reward post-residuals that sit on coarse harmonic boundaries (multiples of 10)
    score -= 8.0 * (1.0 - residue / 10.0);

    // Integer-division thresholds: post_residual bucketed by capacity fractions
    let q = pr / 25; // 0..4 quarter-capacity classes
    score -= 5.0 * q as f64;

    // Dead-space penalty: residuals too small for the smallest item class (<=9)
    if pr < 10 && pr > 0 {
        score += 40.0;
    }
    if pr == 0 {
        score -= 25.0; // perfect fill is excellent
    }

    // Lookahead coupling: does post_residual harmonically fit next item?
    if next_item_size > 0 {
        if pr >= next_item_size {
            let gap = pr - next_item_size;
            let gap_res = (gap % 10) as f64;
            score -= 6.0 * (1.0 - gap_res / 10.0);
            if gap < 10 && gap > 0 {
                score += 12.0; // leaves tiny dead space after next item
            }
        } else {
            score += 10.0; // next item won't fit here anyway
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate handling: prefer new bin only when all open fits are bad
    if bin_residual == bin_capacity {
        // new bin starts with full residual; penalize mildly so it's chosen
        // only when open bins would waste a lot
        let waste_est = mean_residual - item_size as f64;
        if waste_est > 0.0 {
            score -= waste_est.min(45.0);
        }
        score -= 3.0 * (open_bins_count as f64).ln();
    }

    // Stream progression: late in the stream, close bins tightly (favor small post_residual more)
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Small tie-breaker against bin proliferation
    score -= 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: gaps that are too small to hold even the smallest
    // plausible item are worthless; punish them extra hard.
    if post_residual < 10 && post_residual > 0 {
        score += 12.0;
    } else if post_residual < 20 {
        score += 5.0;
    }

    // Reward tight fits (post_residual near zero) with a strong discount.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 3.0 * tightness * tightness;

    // If the next item fits exactly in the post-residual, this placement
    // creates a perfect chain — reward it.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 8.0;
    } else if next_item_size > 0 && post_residual >= next_item_size && post_residual < next_item_size + 10 {
        score -= 3.0;
    }

    // Last-chance bin: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading items
    // into more bins; prefer filling existing ones (i.e., penalize new bins).
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 / (1.0 + progress * 10.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportionally to open bins pressure,
        // but relax the penalty when mean residual across open bins is small
        // (i.e., existing bins are nearly full anyway).
        score += 10.0 + pressure - 0.05 * mean_residual;
    } else {
        // Filling an existing bin slightly reduces pressure burden.
        score -= 0.02 * pressure;
    }

    // Prefer bins whose residual is below the mean (consolidating emptier bins).
    if bin_residual < bin_capacity {
        score += 0.05 * (mean_residual - bin_residual as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), scaled.
    score *= 1.0 + 0.02 * (item_size as f64 / 100.0);

    // Aggressive 2-step lookahead: reward bins whose post_residual
    // matches the next item size (perfect chained fit).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as f64) >= nxt {
            let gap = post_residual as f64 - nxt;
            // Strong bonus when next item fits exactly-ish.
            score -= 30.0 * (1.0 - gap / bin_capacity as f64);
            // Extra bonus if gap is very small (near-perfect chain).
            if gap <= 5.0 {
                score -= 20.0;
            }
        } else {
            // Next item won't fit here: penalize dead space relative to next item.
            score += 0.5 * (nxt - post_residual as f64);
        }
    }

    // Relative-to-mean coupling: bins with residual far below mean are
    // already tight; using them wastes their remaining capacity less.
    let dev = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    score += 10.0 * dev;

    // Last-chance bin: if this is the only fitting bin, strongly favor it
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless the item is
    // large and would leave a well-shaped residual for future items.
    if bin_residual == bin_capacity {
        let waste = (bin_capacity - item_size) as f64;
        score = (bin_capacity as f64) + waste * 0.3;
        if next_item_size > 0 && (bin_capacity - item_size) as f64 >= next_item_size as f64 {
            score -= 15.0;
        }
        // Late in stream, prefer reusing open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
    }

    // Mild penalty for many open bins (encourage consolidation).
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Strongly reward near-perfect fits (post_residual small relative to capacity)
    let tightness = post_residual as f64 / cap;
    score += 3.0 * tightness * tightness * cap;

    // Lookahead: reward if the next item fits into the post residual (chain packing)
    if next_item_size > 0 {
        if (next_item_size as u32) <= post_residual {
            score -= 8.0;
            score -= (next_item_size as f64) * 0.05;
        } else {
            // penalize leaving a gap that the next item just barely misses
            let gap = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
            if gap < 10.0 {
                score += (10.0 - gap) * 0.6;
            }
        }
    }

    // Last chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Penalize opening a new bin when good open bins exist (mild, so bad fits still trigger new bin)
    if bin_residual == bin_capacity {
        // new-bin candidate: base cost of opening a bin
        score += 12.0;
        // more attractive late in the stream or when many bins are open and fragmented
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 4.0 * progress;
        score += 0.02 * open_bins_count as f64;
        // if mean residual is large, existing bins are fragmented; opening new bin less bad
        score -= 0.05 * mean_residual;
        // small items can fill leftover space anywhere; new bin less urgent
        score += (item_size as f64) * 0.05;
    } else {
        // favor using bins with larger residual (biggest-fit tendency) slightly
        score -= 0.03 * bin_residual as f64;
    }

    // Penalize creating dead space that nothing (min size 1..100 range) can use
    if post_residual > 0 && post_residual < 10 {
        score += 6.0; // tiny unusable slivers
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr as f64;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 - progress) + norm_pr * progress * progress;
    score += 12.0 * poly;

    // Reward tight fits more strongly as the stream advances
    let tightness = 1.0 - norm_pr;
    score -= 8.0 * tightness * tightness * (0.5 + progress);

    // Penalize dead space relative to the next item's needs
    let nx = next_item_size as f64;
    if nx > 0.0 {
        let gap = (pr - nx).max(0.0) / cap;
        score += 6.0 * gap * gap * (1.0 + progress);
        // Reward leaving room exactly for the next item
        let exact = (pr - nx).abs() / cap;
        score -= 4.0 * (1.0 - exact.min(1.0)) * progress;
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 + progress);
    }

    // Mild penalty for proliferation of open bins
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);

    // Deviation from mean residual: prefer bins near the mean (balanced packing)
    let dev = (pr - mean_residual) / cap;
    score += 3.0 * dev * dev;

    // New-bin candidate: penalize slightly unless current bin is a bad fit
    if bin_residual == bin_capacity {
        score += 10.0 - 8.0 * tightness;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residuals divisible by small
    // moduli (e.g. 10, 25, 50) remain reusable by typical item sizes,
    // so reward them (subtract); odd/prime dead space is penalized (add).
    let pr = post_residual;
    if pr > 0 {
        if pr % 10 == 0 {
            score -= 6.0;
        }
        if pr % 25 == 0 {
            score -= 4.0;
        }
        if pr % 50 == 0 {
            score -= 3.0;
        }
        // Dead-space band: unusable slivers below the smallest item size.
        if pr < 10 {
            score += 40.0;
        } else if pr < 20 {
            score += 8.0;
        }
        // Integer-division threshold: post residual in [20,35) is a
        // moderately useful pocket; slight reward for landing there.
        if pr / 10 == 2 {
            score -= 2.0;
        }
    } else {
        // Perfect closure is ideal.
        score -= 15.0;
    }

    // Lookahead coupling: if next item fits exactly into the post
    // residual, strongly reward this bin.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 20.0;
        } else if next_item_size < pr {
            score -= 3.0;
        } else {
            // Next item cannot use leftover: dead space likely.
            score += 5.0;
        }
        // Harmonic pairing: next item + post residual hits a clean
        // capacity fraction of 100.
        let s = next_item_size + pr;
        if s % 50 == 0 {
            score -= 4.0;
        }
    }

    // Last-chance bin: if only this bin fits the item, avoid opening
    // a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 10.0;
    }

    // New-bin candidate: only attractive when no open bin gives a
    // decent fit (large item relative to residual) or stream is early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fit_quality = item_size as f64 / bin_capacity as f64;
        // Penalize opening new bins mildly; open when item is big and
        // open bins are fragmented.
        score += 12.0 - 10.0 * fit_quality - 5.0 * (1.0 - progress);
        if open_bins_count == 0 {
            score -= 30.0;
        }
        if mean_residual < item_size as f64 {
            score -= 15.0;
        }
    }

    // Prefer tight fits generally: reward small post residual relative
    // to bin capacity fraction.
    score -= 5.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftovers (<10) are nearly unusable
    // dead space -> strong penalty. Medium leftovers (10..30) are partially
    // usable -> mild penalty. Large leftovers are flexible -> small reward.
    if post_residual > 0 {
        if post_residual < 10 {
            score += 60.0; // pure dead space
        } else if post_residual < 25 {
            score += 18.0;
        } else if post_residual < 40 {
            score += 5.0;
        } else {
            score -= 8.0; // generous residual keeps bin useful
        }
    } else {
        // Perfect fit: heavily reward closing a bin exactly.
        score -= 120.0;
    }

    // Tight-fit reward: fraction of bin consumed by this item.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 25.0 * fill_ratio;

    // Open-bins pressure: many open bins -> prefer packing into existing bins
    // and discourage opening new ones.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += 4.0 * pressure;

    // New-bin candidate handling: empty bin has large residual by definition.
    if bin_residual == bin_capacity {
        // Opening a new bin is attractive only if no open bin fits well,
        // or the item is huge and would leave awkward gaps elsewhere.
        let would_waste = (bin_capacity - item_size) as f64;
        let waste_penalty = if would_waste < 10.0 { -70.0 } else if would_waste < 30.0 { 0.0 } else { 20.0 };
        score += 35.0            // base cost of expanding the bin set
               + 6.0 * pressure  // extra cost when many bins already open
               + waste_penalty   // reward opening when item nearly fills a bin
               - 10.0 * (mean_residual / bin_capacity as f64).min(1.0); // open bins already slack
    }

    // Lookahead: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        score -= 15.0;
    }
    // If next item is large and this placement strands a tiny gap, penalize more.
    if next_item_size > post_residual && post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bin: if this is the only bin that can fit the item, strongly
    // prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // Late-stream consolidation: as the stream progresses, favor filling
    // existing bins tighter rather than spreading.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * fill_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 500.0;
    }

    // 2-step lookahead: reward when next item fits the post residual
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // next item fits perfectly-ish: strong reward scaled by tightness
            let slack = (post_residual - next_item_size) as f64;
            score -= 200.0 - slack * 1.5;
            if slack == 0.0 {
                score -= 250.0; // chain of perfect fits
            }
        } else {
            // next item won't fit here: penalize leaving a gap smaller than next item (dead space)
            let gap = post_residual as f64;
            if gap < next_item_size as f64 {
                score += (next_item_size as f64 - gap) * 0.8;
            }
        }
    }

    // Compare post residual against mean residual: prefer bins that tighten the distribution
    score += (post_residual as f64 - mean_residual) * 0.5;

    // Last-chance bin bonus: if this is the only bin that fits, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
    }

    // Penalize opening a new bin early when a decent fit exists in an open bin
    if bin_residual == bin_capacity {
        // new bin candidate: base score is capacity; add penalty unless item is large
        score += 40.0;
        if item_size >= 50 {
            score -= 30.0; // large items are fine in fresh bins
        }
    }

    // Late in the stream, prefer tighter packing (close residual gaps)
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.3;

    // Slight preference for bins with larger residuals when many bins are open
    score -= (bin_residual as f64 / bin_capacity as f64) * open_bins_count as f64 * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: squared penalty on post residual.
    score += 0.35 * (post_residual as f64) * (post_residual as f64) / (bin_capacity as f64);

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual < 10 {
        score -= 8.0;
    }

    // Penalize creating dead space that no plausible item can fill.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0; // small unusable sliver
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Lookahead: reward bins whose post residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 10.0 + 0.2 * (next_item_size as f64);
        } else {
            score += 5.0;
        }
    }

    // New-bin candidate handling: only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        let waste_elsewhere = (mean_residual - item_size as f64).max(0.0);
        score -= pressure * 60.0;
        score += (1.0 - pressure) * (30.0 + waste_elsewhere * 0.5);
    }

    // Prefer filling existing bins when many bins are open (bin-count pressure).
    score += 0.4 * open_bins_count as f64;

    // Time horizon: late in the stream, consolidate more aggressively.
    let t = step_index as f64 / (total_items.max(1) as f64);
    score -= t * 5.0 * (bin_residual != bin_capacity) as i32 as f64;

    // Deviation from mean residual: prefer bins with below-average residual (fuller bins).
    score += 0.15 * ((bin_residual as f64) - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap;

    // Base: post residual, with smooth non-linear polynomial coupling to progress
    let mut score = pr * (1.0 + 0.8 * progress * x * x);

    // Penalize large dead space more strongly as stream progresses (waste matters late)
    score += cap * progress * x * x * x;

    // Reward tight fits (small post_residual) with a smooth quadratic bonus
    score -= (1.0 - x) * (1.0 - x) * 5.0;

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 {
        score -= 12.0 + 10.0 * progress;
    }

    // Lookahead: if next item fits into post_residual, reward this placement
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 6.0 * (1.0 - x) * (1.0 - progress * 0.5);
    } else if next_item_size > 0 {
        // smooth penalty when next item cannot use leftover space
        score += 2.0 * x * x;
    }

    // Coupling with mean residual: prefer bins whose residual deviates beneficially
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 3.0 * dev * dev * (1.0 - progress);

    // Mild penalty for spreading across too many open bins early
    score += 0.05 * open_bins_count as f64 * progress;

    // New-bin candidate: keep it attractive only when the fit would be poor
    if bin_residual == bin_capacity {
        score += 8.0 - 20.0 * x; // x = 1 for empty bin, so this reduces score
        score -= 4.0 * progress; // late in stream, new bins are cheaper than waste
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward small, "dead-space" residuals.
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fit is ideal
    } else if pr <= 10 {
        score -= 25.0;
    } else if pr <= 20 {
        score -= 10.0;
    } else if pr <= 35 {
        score += 5.0;
    } else {
        score += 15.0; // large leftover = wasteful class
    }

    // Modulo harmonic classes: residuals near multiples of 25 pair well with typical items.
    let m = pr % 25;
    if m == 0 && pr > 0 {
        score -= 8.0;
    } else if m >= 20 {
        score += 6.0;
    }

    // Integer-division thresholds: bins in the top half of capacity are attractive.
    if pr > bin_capacity / 2 {
        score += 12.0;
    }

    // Lookahead: if next item fits in post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 0.5;
    } else if next_item_size > 0 {
        score += (next_item_size as f64) * 0.2;
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize so it's only chosen when all open bins are bad fits.
    if bin_residual == bin_capacity {
        score += 40.0 + mean_residual * 0.1;
    }

    // Late in the stream, tighten packing (fewer wasted bins at the end).
    let progress = step_index as f64 / total_items as f64;
    score *= 1.0 + 0.3 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fill is perfect: heavily reward.
    if post_residual == 0 {
        score -= 1000.0;
        return score;
    }

    // Dead-space penalty: gaps too small for the minimum item size (1..100 unknown,
    // so treat gaps below a conservative threshold as likely unusable).
    if post_residual < 5 {
        score += 200.0;
    } else if post_residual < 10 {
        score += 80.0;
    } else if post_residual < 20 {
        score += 25.0;
    }

    // Reward tight fits: small post_residual relative to item size.
    let tightness = post_residual as f64 / (item_size.max(1) as f64);
    score += tightness * 15.0;

    // If the next item can fit exactly into the post residual, strongly favor this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        let chain_gap = post_residual - next_item_size;
        if chain_gap == 0 {
            score -= 300.0;
        } else if chain_gap < 10 {
            score -= 60.0;
        } else {
            score -= chain_gap as f64 * 0.5;
        }
    } else if next_item_size > post_residual {
        // Next item won't chain here; slight penalty scaled by mismatch.
        score += (next_item_size - post_residual) as f64 * 0.3;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // Open-bins pressure: with many open bins, discourage opening new ones
    // (empty-bin candidate gets penalized via open_bins_count too).
    score += open_bins_count as f64 * 2.0;

    // Penalize the brand-new bin candidate mildly when decent fits exist,
    // but less so as the stream progresses (consolidation late).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score += 40.0 * (1.0 - progress) + 10.0;
        // Opening a new bin is fine when mean residual across open bins is tiny.
        if mean_residual < 5.0 {
            score -= 50.0;
        }
    } else {
        // Reward using bins that are already below the mean residual (balancing).
        if (bin_residual as f64) < mean_residual {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-exact fits: small post_residual is doubly good.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 10 {
        score -= 60.0;
    }

    // 2-step lookahead: if next item exactly fills the post-residual, this is a perfect chain.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size < post_residual {
            // Next item fits here afterwards: mild bonus scaled by how well it fills.
            let fill_ratio = next_item_size as f64 / post_residual as f64;
            score -= 80.0 * fill_ratio;
        } else {
            // Next item cannot use the leftover: penalize dead space, worse for large leftovers.
            score += (post_residual as f64).min(50.0) * 0.8;
        }
    }

    // Compare post_residual against mean residual across open bins.
    // Leaving this bin below the mean keeps flexibility elsewhere; going far above mean wastes space here.
    if post_residual as f64 > mean_residual + 20.0 {
        score += 25.0;
    } else if post_residual as f64 <= mean_residual {
        score -= 15.0;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate: only attractive when no good fit exists (large post_residual elsewhere).
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin.
        score += 150.0;
        // Less penalty late in the stream? Keep constant; instead reduce penalty if next item is large
        // and this item is small (save big residual for big item).
        if next_item_size > 60 && item_size < 40 {
            score -= 100.0;
        }
        // If the current item nearly fills a fresh bin, opening is fine.
        if post_residual <= 20 {
            score -= 130.0;
        }
    }

    // Slight preference for tighter bins in general.
    score += (bin_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // Penalize dead space that is too small to be useful for typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward bins whose post_residual can still fit the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
            // Extra reward if post_residual matches next item nearly perfectly.
            let slack = (post_residual - next_item_size) as f64;
            score -= 8.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            score += 6.0;
        }
    } else {
        // Last item: strongly prefer tightest fit.
        score -= 30.0 * tightness;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Time horizon: late in the stream, consolidation matters more.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress * tightness;

    // Global state: many open bins with high mean residual -> discourage spreading,
    // favor filling existing bins harder.
    if open_bins_count > 1 {
        let spread = (bin_residual as f64 - mean_residual).abs();
        score += 0.05 * spread;
        score -= 0.3 * mean_residual * (1.0 - tightness);
    }

    // New-bin candidate: penalize opening a new bin unless current bins fit badly.
    if bin_residual == bin_capacity {
        score += 20.0;
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            // New bin can host a perfect pair; soften the penalty.
            score -= 18.0;
        }
        if fitting_bins_count > 0 {
            score += 10.0 * (fitting_bins_count as f64).ln().max(1.0);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post_residual (tight fit), with quadratic refinement
    let mut score = pr + 40.0 * norm_pr * norm_pr * cap;

    // Non-linear coupling of post_residual with stream progress:
    // later in the stream, tight fits matter more; early on, flexibility is valued
    score -= 30.0 * (1.0 - norm_pr) * norm_pr * (0.3 + 0.7 * progress);

    // Penalize large post_residual more heavily as stream progresses (dead space late is costly)
    score += 25.0 * norm_pr * norm_pr * norm_pr * (0.5 + progress);

    // Reward bins that can also fit the next item (lookahead synergy), smoothly gated by progress
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let slack_ratio = (pr - nxt) / cap;
            score -= 15.0 * (1.0 - slack_ratio) * (0.4 + 0.6 * (1.0 - progress));
        } else {
            score += 8.0 * (1.0 - pr / nxt.max(1.0)) * progress;
        }
    }

    // Last-chance bonus: only fitting bin -> strong reward, modulated by how full the fit is
    if fitting_bins_count == 1 {
        score -= 20.0 * (1.0 - norm_pr) * (0.5 + 0.5 * progress);
    }

    // Penalize spreading across many open bins mildly; encourage consolidation via mean residual
    let mean_norm = mean_residual / cap;
    score += 6.0 * (norm_pr - mean_norm).abs() * (0.5 + 0.5 * progress);

    // New-bin candidate: penalize opening a new bin unless it produces a very tight future profile
    if bin_residual == bin_capacity {
        score += 18.0 * (1.0 - progress) + 10.0 * (1.0 - item_size as f64 / cap);
        if fitting_bins_count <= 1 {
            score -= 25.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Strong reward for near-perfect fits (dead-space tiers).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 10 {
        score -= 200.0;
    } else if post_residual <= 20 {
        score -= 80.0;
    }

    // Harmonic classes: residual modulo 10 — residuals that are unlikely
    // to be filled by future items (not multiples of 5/10) are penalized.
    let rmod = post_residual % 10;
    if rmod != 0 {
        score += 12.0 * (rmod as f64);
    }
    if post_residual % 5 == 0 && post_residual > 0 {
        score -= 10.0;
    }

    // Penalize large unusable residual: dead space above half capacity.
    if post_residual > bin_capacity / 2 {
        score += (post_residual - bin_capacity / 2) as f64 * 2.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // Lookahead: if the next item fits exactly in the post residual,
    // this placement chains perfectly; reward it.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 300.0;
        } else if post_residual > next_item_size && post_residual - next_item_size <= 10 {
            score -= 60.0;
        } else if post_residual < next_item_size {
            // Residual can't host next item: mild penalty scaled by gap.
            score += 0.5 * (next_item_size - post_residual) as f64;
        }
    }

    // New-bin candidate: make empty bins attractive only when current
    // fits are poor (large post_residual). Baseline penalty keeps open
    // bins preferred unless they leave big dead space.
    if bin_residual == bin_capacity {
        score += 30.0 + mean_residual * 0.3;
        if item_size > bin_capacity / 2 {
            score -= 60.0; // big items are fine in fresh bins
        }
    }

    // Prefer consolidating into few bins as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 5.0 * open_bins_count as f64 / 100.0;

    // Tie-break: prefer tighter bins relative to mean residual.
    score += (mean_residual - bin_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 - 6.0 * post_residual as f64;
    }

    // Reward tight fits strongly (item nearly fills the bin).
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fill_ratio * fill_ratio;

    // Perfect fit gets a large bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 && post_residual > 0 {
        // Post-residual too small for next item -> dead space likely.
        score += 8.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: discourage opening new bins when many bins are open.
    if bin_residual == bin_capacity {
        score += 20.0 + 3.0 * open_bins_count as f64;
        // But if existing bins would waste lots of space, allow new bin.
        if mean_residual > 0.0 && (bin_residual as f64 - item_size as f64) < mean_residual * 0.5 {
            score -= 25.0;
        }
    } else {
        // Reward using bins with low residual relative to mean (consolidation).
        score += 0.05 * (bin_residual as f64 - mean_residual);
    }

    // Mild pressure to close out bins as stream progresses.
    score -= 5.0 * (step_index as f64 / total_items.max(1) as f64) * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match between post_residual
    // and the next item size (perfect chaining of two items).
    if next_item_size > 0 {
        let post = post_residual as f64;
        let nxt = next_item_size as f64;
        let diff = (post - nxt).abs();
        // Exact match: strong bonus.
        if diff < 0.5 {
            score -= 40.0;
        } else {
            // Near match: graded bonus proportional to closeness.
            let closeness = 1.0 - (diff / bin_capacity as f64).min(1.0);
            score -= 12.0 * closeness * closeness;
        }
        // If next item cannot fit after placement, penalize dead space creation.
        if post_residual < next_item_size {
            score += 8.0 + 0.15 * (next_item_size - post_residual) as f64;
        }
        // Bonus if next item fits snugly (post_residual >= next_item_size).
        else {
            score -= 4.0;
        }
    }

    // Relative residual context: bins with residual far below mean are tighter;
    // prefer placing into bins whose post_residual is below mean residual
    // (consolidating waste), penalize leaving large post_residual vs mean.
    let mr = mean_residual;
    if mr > 0.0 {
        let rel = (post_residual as f64 - mr) / mr;
        if rel > 0.0 {
            score += 6.0 * rel; // leaves more slack than average -> penalize
        } else {
            score -= 3.0 * (-rel); // tighter than average -> reward
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor it
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when the item is
    // large relative to residual and current bins are fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = if open_bins_count > 0 { mean_residual / bin_capacity as f64 } else { 0.0 };
        let large_item = (item_size as f64 / bin_capacity as f64) > 0.6;
        if large_item && fragmentation > 0.5 {
            score -= 15.0; // open a new bin for big items into fragmented state
        } else {
            score += 20.0; // otherwise discourage new bins
        }
    }

    // Slight progression-aware tightening: late in the stream, waste matters more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 2.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: quadratic decay of residual waste.
    let fit_frac = post_residual as f64 / bin_capacity as f64;
    score -= 8.0 * (1.0 - fit_frac) * (1.0 - fit_frac) * item_size as f64 / 100.0;

    // Penalize small unusable residuals (dead space below typical item sizes).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual < 20 {
        score += 6.0;
    }

    // Exact-fill jackpot.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Lookahead coupling: if next item fits in post_residual, reward this placement.
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        score -= 5.0 + next_item_size as f64 * 0.1;
    } else if next_item_size > 0 && (next_item_size as f64) > post_residual as f64 && (next_item_size as f64) <= bin_residual as f64 {
        // next item would have fit here before this placement — mild penalty
        score += 3.0;
    }

    // Prefer filling bins with larger mean residual when many bins are open.
    if open_bins_count > 2 {
        score += (mean_residual - post_residual as f64) * 0.05;
    }

    // Time horizon: late in stream, be conservative with new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses and bins accumulate.
        score += 12.0 + 15.0 * progress + 2.0 * open_bins_count as f64;
        if fitting_bins_count == 0 {
            score -= 30.0; // no open bin fits, must open new bin
        }
        if fitting_bins_count == 1 && progress > 0.5 {
            score += 10.0; // last chance bin exists; discourage new bin late
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Base: prefer tight fits, with non-linear penalty on dead space
    let mut score = pr + 12.0 * pr_norm * pr_norm * cap;

    // Smooth polynomial coupling of dead space with stream progress:
    // waste becomes more costly as the stream matures
    score += 18.0 * pr_norm * pr_norm * pr_norm * cap * progress;

    // Reward using the last fitting bin (avoid opening a new bin unnecessarily)
    if fitting_bins_count == 1 {
        score -= 9.0 * (1.0 - pr_norm);
    }

    // Lookahead: if next item fits the post-residual, reward this placement smoothly
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fit_frac = if pr as f64 >= nxt { 1.0 - (pr as f64 - nxt) / cap } else { 0.0 };
        score -= 10.0 * fit_frac * fit_frac * (1.0 - progress);
    }

    // Mild penalty for spreading across many open bins relative to mean residual
    score += 0.05 * (open_bins_count as f64) * ((bin_residual as f64 - mean_residual).abs() / cap);

    // Small smooth bonus for placing larger items early
    score -= 0.05 * item_size as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: bins whose leftover falls into
    // "small residue" classes are nearly full — reward them heavily.
    let cap = bin_capacity as f64;
    let fill_ratio = 1.0 - (post_residual as f64) / cap;

    // Integer-division thresholds on post_residual (harmonic bands).
    let band = post_residual / 10; // classes of 10 units of dead space
    score -= match band {
        0 => 60.0,           // post_residual < 10: perfect fit class
        1 => 45.0,           // 10..20
        2 => 30.0,           // 20..30
        3 => 18.0,           // 30..40
        4 => 8.0,            // 40..50
        _ => 0.0,
    };

    // Modulo-arithmetic coupling: residues that are multiples of common
    // item sizes (10, 20, 25, 50) remain reusable — reward them.
    let pr = post_residual;
    if pr > 0 {
        if pr % 10 == 0 { score -= 12.0; }
        if pr % 20 == 0 { score -= 6.0; }
        if pr % 25 == 0 { score -= 5.0; }
        if pr % 50 == 0 { score -= 8.0; }
    } else {
        score -= 70.0; // exact fill: zero waste
    }

    // Lookahead: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 55.0;
        } else if next_item_size <= pr {
            let slack = (pr - next_item_size) as f64;
            // harmonic class of the double-fit leftover
            let dbl_band = (pr - next_item_size) / 10;
            score -= (30.0 - 6.0 * dbl_band as f64).max(2.0);
            if slack < 5.0 { score -= 10.0; }
        } else {
            // next item cannot use this bin's residue: penalize small leftovers
            score += (pr as f64).min(40.0) * 0.15;
        }
    }

    // Fill ratio bonus: nonlinear reward for high utilization.
    score -= fill_ratio * fill_ratio * 25.0;

    // Last-chance bin: if this is the only bin that fits, avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: penalize unless current bin would leave a bad class.
    if bin_residual == bin_capacity {
        let bad_fit = post_residual > 0 && post_residual < 10 && next_item_size > 0 && next_item_size > post_residual;
        if bad_fit {
            score += 20.0; // still weakly discourage new bins
        } else {
            score += 90.0; // strongly prefer existing usable bins
        }
    }

    // Mild penalty for spreading across many open bins late in the stream.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * (1.0 - progress) * 0.05;

    // Mean-residual alignment: prefer bins close to the mean residual.
    score += ((mean_residual - post_residual as f64).abs()) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

