    }

    // Reward tight fits.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual <= 5 {
        score -= 10.0;
    }

    // Last-chance bonus: only bin that fits -> avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Open-bin pressure: many open bins -> prefer filling existing bins,
    // penalize opening new bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * 2.0 * (0.5 + progress);

    // New-bin candidate: empty bin starts with a penalty; allow it when
    // residual in this bin is large dead space relative to remaining need.
    if bin_residual == bin_capacity {
        score += 30.0;
        // If item leaves a large gap that nothing small will use, new bin ok.
        if next_item_size > 0 && (bin_residual - item_size) < next_item_size {
            score -= 20.0;
        }
    } else {
        // Prefer bins whose post-residual can host the next item.
        if next_item_size > 0 {
            if post_residual >= next_item_size {
                score -= 8.0;
            } else if post_residual > 0 {
                score += 6.0;
            }
        }
        // Slight preference for bins tighter than average.
        if (bin_residual as f64) < mean_residual {
            score -= 3.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
