    // Aggressive 2-step lookahead: reward if next item fits into post_residual.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let post = post_residual as f64;
        if post >= nxt {
            // Coupled reward: tighter the leftover relative to next item, the better.
            let tightness = (post - nxt) / bin_capacity as f64;
            score -= 18.0 * (1.0 - tightness);
        } else {
            // Penalize dead space that the next item cannot use.
            let unusable = (nxt - post) / bin_capacity as f64;
            score += 22.0 * unusable;
        }
        // If next item exactly fills post_residual, strong bonus.
        if post_residual == next_item_size {
            score -= 30.0;
        }
    }

    // Relative-to-mean coupling: prefer bins with residual below mean (denser bins),
    // penalize spreading items into already-large-residual bins.
    score += 0.8 * ((bin_residual as f64 - mean_residual).max(-50.0).min(50.0));

    // Last-chance bin: if this is the only bin that can fit, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // New-bin candidate handling: empty bin should only win when open bins are poor fits.
    if bin_residual == bin_capacity {
        // Base penalty so open bins with decent fits are preferred.
        score += 45.0;
        // But if many open bins exist with large mean residual (fragmented state),
        // opening a fresh bin becomes relatively more attractive.
        score -= (mean_residual / bin_capacity as f64) * 30.0;
        if next_item_size > 0 && next_item_size as f64 > mean_residual {
            score -= 20.0; // next item doesn't fit existing average residual either
        }
    }

    // Late in the stream, prefer closing bins tightly (less chance to consolidate later).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (post_residual small relative to item).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio;

    // Penalize dead space that becomes unusable for typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny unusable sliver
    } else if post_residual >= 10 && post_residual < 20 {
        score += 8.0;
    }

    // Last-chance bonus: only one bin can fit this item.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Lookahead coupling: if next item fits in the post residual, reward heavily.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 20.0;
        } else if next_item_size <= bin_residual && post_residual < next_item_size {
            // placing here would break the next item's fit here — mild penalty
            score += 5.0;
        }
        // If next item is large, prefer spreading into a fresh bin.
        if next_item_size > 60 && post_residual < next_item_size {
            score += 10.0;
        }
    }

    // New-bin candidate handling: empty bin has residual == capacity.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Opening a new bin is fine when existing bins are fragmented or none fit well.
        let avg_fragmentation = mean_residual / bin_capacity.max(1) as f64;
        // Slight bias against new bins early, in favor later when bins are full.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 15.0 - 10.0 * progress;
        // If many open bins with low mean residual, opening a new bin is attractive.
        if mean_residual < 20.0 && open_bins_count > 2 {
            score -= 12.0;
        }
        // Discard new-bin option if current bin would be a near-perfect fit.
        if fit_ratio > 0.85 {
            score += 50.0;
        }
        // If post_residual would be perfectly reusable by next item, discourage new bin.
        if next_item_size > 0 && next_item_size <= post_residual && post_residual <= 50 {
            score += 10.0;
        }
    } else {
        // Mild penalty for using bins that are already crowded relative to mean.
        if (bin_residual as f64) < mean_residual - 10.0 {
            score += 4.0;
        }
    }

    // Global pressure: many open bins → prefer filling existing ones.
    if open_bins_count > 5 {
        score -= (open_bins_count as f64).min(20.0) * 0.5;
    }

    // Small stochastic-free tie-break by residual ordering.
    score += post_residual as f64 * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post-residual, with smooth non-linear shaping
    let mut score = pr * (1.0 + 0.5 * norm_pr * norm_pr);

    // Stream-progress coupling: early on, tolerate larger residuals slightly;
    // late in the stream, penalize leftover dead space more aggressively.
    score += 20.0 * norm_pr * norm_pr * progress;

    // Dead-space penalty: residuals too small for any plausible item are worthless
    let min_item = 1.0f64;
    let usable = (pr as i64 - min_item as i64).max(0) as f64;
    let waste = cap - usable;
    score += 0.3 * waste * progress * progress;

    // Last-chance bonus: strongly favor using a bin when few can fit the item
    if fitting_bins_count <= 1 {
        score -= 15.0;
    }

    // Lookahead: reward if next item fits into post-residual
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 8.0 * (1.0 - pr / cap);
    } else if next_item_size > 0 {
        score += 3.0 * (next_item_size as f64 - pr) / cap;
    }

    // New-bin candidate: discourage opening new bins unless residual is nearly full
    if bin_residual == bin_capacity {
        score += 25.0 * (1.0 - progress) + 5.0;
    }

    // Mild dispersion term: prefer bins below mean residual (tighter bins first)
    score += 0.05 * (mean_residual - pr);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls on "nice"
    // fractions of capacity (multiples of 10, 20, 25, 50) are reusable.
    let pr = post_residual;
    if pr == 0 {
        score -= 30.0; // perfect fit: best possible outcome
    } else {
        if pr % 50 == 0 {
            score -= 12.0;
        } else if pr % 25 == 0 {
            score -= 8.0;
        } else if pr % 10 == 0 {
            score -= 5.0;
        } else if pr % 5 == 0 {
            score -= 2.0;
        } else {
            score += 4.0; // awkward remainder class
        }
        // Dead-space penalty: unusable slivers
        if pr < 10 {
            score += 25.0;
        }
    }

    // Lookahead coupling: reward a residual that exactly hosts next item
    if next_item_size > 0 && next_item_size <= pr {
        score -= 6.0;
        if pr - next_item_size < 10 {
            score -= 5.0; // next item will nearly perfect-fill
        }
    } else if next_item_size > 0 && next_item_size > pr {
        score += 3.0; // next item can't use this residual
    }

    // Last-chance bonus: only fitting bin -> avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling
    if bin_residual == bin_capacity {
        // Prefer opening a new bin only when existing bins are badly fragmented
        // or this is a fresh stream start.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = 40.0 + mean_residual * 0.3 + open_bins_count as f64 * 0.5 - progress * 10.0;
        if item_size > bin_capacity / 2 {
            score += 5.0; // big items like fresh bins
        }
    }

    // Mild preference for tighter existing bins when many are open
    score -= (bin_capacity - bin_residual) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = 0.0;

    // Base: prefer tight fit (small post_residual), but treat tiny dead gaps harshly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let post = post_residual as f64;

    if post_residual == 0 {
        // Perfect fill: strongly favored.
        score -= 60.0;
    } else if post_residual < 10 {
        // Unusable dead space (nothing smaller than 10 fits): penalize heavily.
        score += 45.0 + post * 2.0;
    } else {
        // Usable residual: mild penalty, scaled down as fit tightens.
        score += post * 0.6;
    }

    // Reward bins whose residual exactly accommodates the upcoming item (lookahead synergy).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // Residual can host next item: mild bonus proportional to snugness.
        score -= (post_residual - next_item_size) as f64 * 0.05;
    }

    // Open-bin pressure: with many bins open, prefer consolidating into existing ones.
    score += open_bins_count as f64 * 0.8;

    // Last-chance bin: if this is the only fitting bin, opening a new bin wastes it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Mean-residual coupling: prefer bins below mean residual (tighter than average).
    score += (mean_residual - post) * 0.15;

    // New-bin candidate handling: an empty bin has huge residual; make it attractive
    // only when the current item would leave a bad gap in any existing bin, or when
    // few bins are open. Penalize default new-bin slightly so consolidation wins on ties.
    if bin_residual == bin_capacity {
        // Empty bin baseline: moderate score.
        score = 30.0 + open_bins_count as f64 * 0.5;
        // Late in stream, opening fresh bins is cheaper than fragmenting.
        if progress > 0.7 {
            score -= 10.0 * progress;
        }
        // If next item is large, a fresh bin is valuable.
        if next_item_size >= 50 {
            score -= 8.0;
        }
    }

    // Slight preference for larger residual bins early (keeps flexibility).
    score -= (bin_residual as f64) * 0.02 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: less waste relative to capacity.
    let tightness = (bin_residual - post_residual) as f64 / bin_capacity as f64;
    score -= 12.0 * tightness;

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next item.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs();
        if diff == 0 {
            score -= 30.0; // perfect two-item fill
        } else if (post_residual as i64) >= (next_item_size as i64) {
            score -= 18.0 * (1.0 - diff as f64 / bin_capacity as f64);
        } else {
            // next item cannot fit here; penalize dead space growth
            score += 8.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
        }
    }

    // Penalize bins far above mean residual (avoid fragmenting well-filled bins).
    let dev = post_residual as f64 - mean_residual;
    score += 0.35 * dev;

    // Last chance bonus: if this is the only fitting bin, strongly prefer it over new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Prefer using existing bins over opening new ones (new bin has residual == capacity).
    if bin_residual == bin_capacity {
        score += 15.0 + 5.0 * (open_bins_count as f64 / (open_bins_count as f64 + 3.0));
    } else {
        score -= 6.0;
    }

    // Early in stream, be more willing to open new bins for large items.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if item_size > bin_capacity / 2 {
        score -= 5.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: squashed post-residual dominates the score.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 18.0 * tightness * tightness;

    // Reward bins whose residual is close to the item (good fill ratio).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio;

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if the next item also fits in the post-residual, this is a
    // valuable bin; reward keeping it. If next item is bigger than post
    // residual but small, mild penalty for creating dead space.
    if next_item_size > 0 {
        if (next_item_size as f64) <= post_residual as f64 {
            score -= 10.0;
        } else {
            let dead = (next_item_size as f64 - post_residual as f64) / bin_capacity as f64;
            score += 6.0 * dead;
        }
    }

    // Prefer bins with residual below the mean (consolidate waste) early,
    // but late in the stream prefer using the emptiest bins less wastefully.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let dev = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    score += dev * (8.0 - 10.0 * progress);

    // Penalize leaving very small unusable slivers (< 10) unless exact fit.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Mild penalty when many bins are open: encourage consolidation.
    score += (open_bins_count as f64).ln().max(0.0) * 0.5;

    // New-bin candidate: neutral-to-high baseline so it only wins when all
    // open bins fit poorly (large post_residual waste).
    if bin_residual == bin_capacity {
        score = 70.0 + 0.3 * (fitting_bins_count as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Smooth non-linear coupling of post_residual with stream progress.
    let mut score = pr * (1.0 + 0.35 * progress * progress);

    // Penalize dead space more strongly as the stream matures (non-linear).
    score += 12.0 * norm_pr * norm_pr * (0.5 + progress);

    // Reward tight fits with a smooth saturating term.
    let tightness = 1.0 - norm_pr;
    score -= 8.0 * tightness * tightness * tightness;

    // Lookahead: smooth reward if next item fits the post-residual.
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).max(0.0);
        let fit_frac = gap / cap;
        score -= 6.0 * (1.0 - fit_frac).min(1.0) * (1.0 - progress * 0.5);
        // Penalize near-exact leftovers that strand the next item awkwardly.
        let near = (pr - next_item_size as f64).abs();
        score += 3.0 * (-near / 10.0) * (progress + 0.2).exp() * 0.0;
        score += 2.0 * (1.0 - (near / cap).min(1.0));
    }

    // Last-chance bonus: smooth decay with number of fitting bins.
    if fitting_bins_count <= 1 {
        score -= 10.0 * (1.0 - progress * 0.3);
    } else {
        score += 1.5 * (fitting_bins_count as f64).ln();
    }

    // Mild penalty for bin proliferation, smooth in open_bins_count.
    score += 0.4 * (open_bins_count as f64).powf(1.2) * progress;

    // Encourage balance with mean residual via smooth quadratic deviation.
    let dev = (pr - mean_residual) / cap;
    score += 4.0 * dev * dev;

    // Discard tiny unusable slivers smoothly.
    score += 5.0 * (-pr / 15.0).exp();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: how "usable" is the leftover space?
    // Class by capacity fraction (eighths of capacity) and by divisibility.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let post_frac = post / cap;

    // Favor residuals that are harmonic with common item sizes (multiples of 5/10).
    let harmonic_bonus = if post_residual % 10 == 0 {
        6.0
    } else if post_residual % 5 == 0 {
        3.0
    } else {
        0.0
    };
    score -= harmonic_bonus;

    // Penalize tiny dead space: residuals in (0, 10) are near-unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Perfect fit is ideal.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead coupling: if next item fits exactly in the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            // Reward proportional to how well next item consumes leftover.
            let nx = next_item_size as f64;
            let fill = nx / post.max(1.0);
            score -= 10.0 * fill;
        } else {
            // Next item won't fit here; penalize large wasted residuals less if
            // they fall on a harmonic threshold (could serve later items).
            if post_residual % 20 == 0 {
                score -= 4.0;
            } else if post_frac > 0.7 {
                score += 3.0 * (post_frac - 0.7);
            }
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate handling: empty bin gets a baseline penalty so we only
    // open a new bin when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        score += 10.0;
        // But if the item is huge relative to capacity, opening fresh is fine.
        if (item_size as f64) / cap > 0.6 {
            score -= 8.0;
        }
        // If mean residual across open bins is small, new bin is more attractive.
        if mean_residual < 0.25 * cap {
            score -= 6.0;
        }
    }

    // Stream progression: later in the stream, consolidate harder (avoid new bins).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score += 5.0 * progress;
    } else {
        score -= 3.0 * progress;
    }

    // Mild penalty for proliferating open bins when this bin is empty.
    if bin_residual == bin_capacity {
        score += 0.3 * open_bins_count as f64;
    }

    // Integer-division threshold: residuals in the "half-capacity sweet spot"
    // (40..=60) are highly reusable; nudge them.
    if post_residual >= 40 && post_residual <= 60 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals in [1, 12] are nearly unusable
    // (item sizes >= 10 typically), so heavily penalize creating them.
    if post_residual > 0 && post_residual <= 12 {
        score += 40.0 * (13.0 - post_residual as f64);
    }

    // Perfect fit is maximally rewarded.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward tight fits: fraction of bin consumed by this item.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 15.0 * fill_ratio;

    // Reward bins whose residual was already small (consolidate small gaps).
    if bin_residual < 30 {
        score -= 8.0;
    }

    // Open-bin pressure: mildly prefer filling existing bins over opening new ones.
    score += 0.15 * open_bins_count as f64;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead coupling: if the next item fits the post-residual well,
    // reward leaving exactly that space behind.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 35.0;
        } else if post_residual > next_item_size && post_residual - next_item_size <= 12 {
            score += 20.0;
        }
    }

    // New-bin candidate: make the empty bin attractive only when nothing
    // reasonable fits (its raw post_residual is large, so it needs a
    // handicap that shrinks as open-bin pressure grows).
    if bin_residual == bin_capacity {
        score += 45.0 + 0.5 * open_bins_count as f64;
        if fitting_bins_count > 0 {
            score += 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when next item fits the post-residual exactly/well.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if post_residual >= next_item_size {
            // Next item fits after this placement: strong reward, tighter match = better.
            score -= 60.0 + 40.0 * (1.0 - gap / (bin_capacity as f64));
            // Perfect chain (post_residual == next_item_size) gets maximal reward.
            if gap == 0.0 {
                score -= 50.0;
            }
        } else {
            // Next item won't fit here regardless: mild penalty for wasting space.
            score += 5.0 + 0.2 * gap;
        }
    }

    // Penalize dead space that is too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Reward tight fits relative to current item.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 20.0 * fill_ratio;

    // Compare against mean residual: prefer bins with residual below mean (tighter bins).
    let res_f = bin_residual as f64;
    score += 0.3 * (res_f - mean_residual);

    // Last-chance bin: strong bonus to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate: make it less attractive unless open bins are badly fragmented.
    if bin_residual == bin_capacity {
        let mean_tightness = (bin_capacity as f64 - mean_residual) / bin_capacity as f64;
        // If existing bins are quite empty, prefer packing into them.
        if mean_tightness < 0.5 {
            score += 30.0;
        } else {
            score += 5.0;
        }
        // Large items start fresh bins more readily.
        if item_size > 60 {
            score -= 15.0;
        }
    }

    // Late in stream: consolidate harder, avoid opening bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual < bin_capacity {
        score -= 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: square of wasted space penalized.
    score += (post_residual as f64 / bin_capacity as f64).powi(3) * 120.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Small dead space that can't fit typical items is bad.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if next item fits in post_residual, reward this placement.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 18.0 * (next_item_size as f64 / bin_capacity as f64);
        } else {
            score += 8.0;
        }
        // If next item exactly fills post_residual, huge bonus.
        if post_residual == next_item_size {
            score -= 35.0;
        }
    }

    // Prefer fuller bins relative to mean residual.
    if bin_residual < mean_residual {
        score -= (mean_residual - bin_residual as f64) * 0.6;
    } else {
        score += (bin_residual as f64 - mean_residual) * 0.3;
    }

    // Time horizon: late in the stream, be more conservative (favor filling existing bins).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 12.0;

    // Many open bins: encourage consolidation into existing bins.
    score += open_bins_count as f64 * 0.8;

    // Slight preference for bins whose residual is close to item size (best-fit flavor).
    score += (bin_residual as f64 - item_size as f64).abs() * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let base = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early in the stream: tolerate larger residuals (bins stay flexible).
    // Late in the stream: penalize residuals strongly to close bins tightly.
    let progress_coupling = pr * (0.5 + 1.5 * progress * progress) - 0.8 * progress * (pr * pr) / cap;

    // Dead-space penalty: residuals too small to fit the smallest plausible item.
    let dead = if pr > 0.0 && pr < 10.0 { (10.0 - pr) * (10.0 - pr) * 0.15 } else { 0.0 };

    // Lookahead: reward if next item fits in post_residual, penalize otherwise.
    let lookahead = if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr { -0.9 * (1.0 - (nxt / pr).powi(2)) } else { 0.6 * (1.0 - pr / nxt) * nxt / cap * 10.0 }
    } else { 0.0 };

    // Last-chance bonus: strongly favor using the only fitting bin.
    let last_chance = if fitting_bins_count == 1 { -6.0 * (1.0 - progress) } else { 0.0 };

    // Crowding: many open bins -> prefer filling existing ones over new bins.
    let crowd = open_bins_count as f64 * 0.05 * (pr / cap);

    // New-bin candidate handling: empty bin should only win when fit is poor.
    let is_new_bin = bin_residual == bin_capacity;
    let new_bin_penalty = if is_new_bin {
        cap * 0.35 - 0.3 * mean_residual - 4.0 * (1.0 - progress)
    } else { 0.0 };

    // Smooth alignment with mean residual: prefer bins whose post residual tracks the average.
    let mean_align = -0.3 * ((pr - mean_residual) / cap).powi(2) * cap;

    base + progress_coupling + dead + lookahead + last_chance + crowd + new_bin_penalty + mean_align
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let res = bin_residual as f64;
    let post = post_residual as f64;
    let nxt = next_item_size as f64;
    let is_new = bin_residual == bin_capacity;

    // Lookahead (k=2) coupling: reward bins that can also host the next item,
    // especially when post_residual and next_item_size share a harmonic class.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0 + 0.10 * nxt;
            if (post_residual / 10) == (next_item_size / 10) {
                score -= 4.0; // same decile class: likely chainable pair
            }
        } else if post_residual > 0 {
            // residual too small for the known next item -> dead space penalty
            score += 10.0 + 0.20 * (nxt - post);
        }
    }

    // Very small unusable residual (below plausible minimum item size class)
    if post_residual > 0 && post_residual < 10 {
        score += 6.0;
    }

    // Last-chance bin: this is the only open bin that fits -> strong reward
    if fitting_bins_count == 1 && !is_new {
        score -= 15.0;
    }

    // Favor bins that are already more filled than the average open bin
    score -= 0.30 * (mean_residual - res);

    // New-bin candidate handling: default penalty so we prefer reusing bins,
    // but relax over the stream and when the fresh bin stays chainable.
    if is_new {
        score += 20.0;
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 5.0 * progress;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 5.0;
        }
        // If this bin would be the only fitter anyway, opening is neutral
        if fitting_bins_count <= 1 {
            score -= 10.0;
        }
    }

    // Mild modulo-structure tiebreak on post_residual classes
    let class = (post_residual % 25) as f64;
    score += 0.05 * class;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that can never fit even the
    // smallest plausible item (<= ~15) are wasted; penalize them hard.
    if post_residual > 0 && post_residual < 15 {
        score += 60.0;
    } else if post_residual < 30 {
        score += 12.0 * (1.0 - post_residual as f64 / 30.0);
    }

    // Reward tight fits (small post_residual relative to item size).
    if item_size > 0 {
        score -= 25.0 * (1.0 - post_residual as f64 / item_size as f64).abs() * (item_size as f64 / 100.0);
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead: if the next item fits exactly in the post_residual, reward it.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 35.0;
        } else if post_residual > next_item_size {
            score -= 8.0;
        } else if next_item_size > post_residual && post_residual > 0 {
            score += 10.0; // next item won't fit here; slight penalty
        }
    }

    // Last-chance bin pressure: if this is the only fitting bin, strongly
    // prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: many open bins -> discourage new bins, encourage
    // packing into existing ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64).ln().max(0.0) * 6.0 * (0.5 + progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: must beat well-fitting open bins, but should
        // win when open bins are fragmented / pressure is low.
        score += 18.0 + pressure - 0.15 * mean_residual;
    } else {
        score += 0.05 * (bin_residual as f64 - mean_residual);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Prefer tight fits: reward small post_residual.
    score -= 0.5 * (bin_capacity as f64 - post_residual as f64).max(0.0);

    // 2-step lookahead: reward if next item exactly fits the post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect chain fit
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            // reward proportional to how tight the chain is
            score -= 40.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item cannot fit here: penalize dead space
            let dead = (next_item_size - post_residual) as f64;
            score += 0.3 * dead;
        }
    }

    // Penalize creating residuals that are hard to reuse (small odd slacks).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless the item is large
    // and no good fit exists.
    if bin_residual == bin_capacity {
        score += 20.0;
        if item_size >= 50 && (fitting_bins_count == 0 || post_residual < 20) {
            score -= 45.0;
        }
    }

    // Mildly prefer bins with below-mean residual (keeps big slacks available).
    score += 0.2 * (bin_residual as f64 - mean_residual);

    // Early in stream: be slightly more willing to open bins (spread risk).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress < 0.2 {
        score -= 5.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize based on relative fill of the bin.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 30.0 * fill_ratio * fill_ratio;

    // Penalize small dead space (wasted slivers) but tolerate large residuals.
    if post_residual > 0 {
        let dead = post_residual as f64;
        if dead < 10.0 {
            score += 25.0 * (10.0 - dead);
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Lookahead: reward leaving space for the next item.
    if next_item_size > 0 {
        if post_residual as u32 >= next_item_size {
            score -= 8.0;
            // Perfect chain: next item exactly fills remaining space.
            if post_residual == next_item_size {
                score -= 15.0;
            }
        } else if next_item_size >= post_residual as u32 && next_item_size <= bin_capacity {
            // Next item could combine with another bin instead; slight penalty
            // if we strand a tiny residual that nothing else will use.
            if post_residual < 10 {
                score += 10.0;
            }
        }
        // If next item is huge, prefer spreading load: prefer emptier bins less.
        if next_item_size > 60 && post_residual > 0 && post_residual < next_item_size as u32 {
            score += 5.0;
        }
    }

    // Time horizon: early in stream, be more willing to open new bins
    // (keep flexibility); later, consolidate into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are open and
        // late in the stream; discount early when open_bins_count is low.
        score += 12.0 + 20.0 * progress + 1.5 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // new bin pairs well with similar large items
        }
    } else {
        // Slight consolidation pressure late in the stream.
        score -= 5.0 * progress;
    }

    // Prefer bins whose residual deviates from mean (keep a spread of sizes).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score -= 0.05 * dev;

    // Mild preference for fuller bins overall.
    score -= 0.1 * (bin_capacity as f64 - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let mut score = pr * (1.0 + 0.35 * progress * progress);

    // Reward tight fits via smooth decay of squared residual.
    score -= 40.0 * (1.0 - x) * (1.0 - x) * (0.5 + 0.5 * progress);

    // Penalize very small residuals (dead space) smoothly.
    score += 25.0 * (1.0 - x).powi(4);

    // Last-chance bonus when this is the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 30.0 * (1.0 - progress);
    }

    // Lookahead: reward residual that could hold next item smoothly.
    if next_item_size > 0 {
        let nx = next_item_size as f64 / cap;
        let fit = (1.0 - (nx - x).abs()).max(0.0);
        score -= 15.0 * fit * fit;
        // Penalize if post-residual slightly smaller than next item (blocking).
        if x < nx {
            score += 10.0 * (nx - x) * (1.0 + progress);
        }
    }

    // Mild dispersion penalty relative to mean residual.
    score += 0.2 * (pr - mean_residual).abs();

    // New-bin candidate: smooth penalty growing with stream progress.
    if bin_residual == bin_capacity {
        score += 8.0 + 12.0 * progress * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: post_residual mod 10.
    // Leftovers that are multiples of 10 are "harmonic" and more reusable.
    let harmonic = (post_residual % 10) as f64;
    score += harmonic * 0.8;

    // Perfect fit: zero post residual is ideal.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Dead-space penalty: small nonzero leftovers are nearly useless.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: does the next item fit exactly into the post residual?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            // Harmonic divisibility: next item divides leftover nicely.
            if post_residual % next_item_size == 0 {
                score -= 20.0;
            } else {
                score -= 8.0;
            }
        } else {
            // Next item won't fit here; penalize proportionally to overshoot.
            let overshoot = (next_item_size - post_residual) as f64;
            score += overshoot * 0.4;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Tightness reward: bins that are nearly full are good targets.
    let fill_ratio = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= fill_ratio * 15.0;

    // Integer-division threshold on post residual: leftover >= half capacity
    // keeps the bin flexible; leftover < quarter is nearly dead.
    if post_residual * 4 < bin_capacity {
        score += 12.0;
    } else if post_residual * 2 >= bin_capacity {
        score -= 6.0;
    }

    // New-bin candidate handling: prefer existing bins unless this item is huge
    // and the current bin's leftover would be badly fragmented.
    if bin_residual == bin_capacity {
        // Brand-new bin: baseline cost of opening a bin.
        score += 35.0;
        // Opening a new bin is attractive when the item is large and would
        // leave a non-harmonic tiny leftover in an existing bin.
        if item_size * 5 > bin_capacity * 4 && post_residual % 10 != 0 {
            score -= 40.0;
        }
        // Late in the stream, avoid proliferating bins.
        if total_items > 0 && (step_index as f64) / (total_items as f64) > 0.8 {
            score += 20.0;
        }
    }

    // Mild pressure against many open bins with scattered residuals.
    if open_bins_count > 4 && (post_residual as f64) > mean_residual {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: post_residual in the "unusable gap" band
    // (too small for the smallest plausible item) is heavily penalized.
    let min_item = 1u32;
    let dead_zone = 12u32; // gaps below ~12 are nearly useless
    if post_residual > 0 && post_residual <= dead_zone {
        score += (dead_zone - post_residual + 1) as f64 * 3.0;
    }

    // Perfect / near-perfect fit reward.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Reward leaving room for the lookahead item (k=2 lookahead coupling).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0 + (post_residual - next_item_size).min(20) as f64 * 0.3;
        } else if post_residual > 0 {
            // residual exists but cannot host next item: mild penalty
            score += 5.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bins pressure: with many open bins, prefer consolidation into
    // existing bins over spreading; penalize candidates that waste space.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    if bin_residual < bin_capacity {
        score -= pressure * 2.0;
    } else {
        // New-bin candidate: only attractive when open bins are few or
        // the item would create a large unusable gap everywhere else.
        score += pressure * 4.0;
        if post_residual == 0 {
            score -= 10.0;
        }
    }

    // Mean-residual coupling: if this bin is far above the mean residual,
    // it is underfilled; nudge score to prefer tighter bins.
    score += ((bin_residual as f64) - mean_residual).max(0.0) * 0.15;

    // Early stream: be slightly greedy toward tight fits; late stream:
    // tolerate imperfect fits to avoid opening bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= (1.0 - progress) * 3.0;
    if progress > 0.8 && bin_residual >= item_size {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post residual)
    score -= 30.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Aggressive 2-step lookahead: exact match of next item into post residual is ideal
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0; // perfect 2-step chain
        } else if post_residual >= next_item_size {
            // next item fits; penalize leftover slack after the hypothetical placement
            let slack2 = post_residual - next_item_size;
            score += 0.4 * slack2 as f64;
            if slack2 < 10 { score -= 15.0; } // near-perfect chain
        } else {
            // next item won't fit here; penalize proportionally to shortfall
            let shortfall = next_item_size - post_residual;
            score += 0.15 * shortfall as f64;
        }
    } else {
        // last item: prefer minimal post residual
        score += 0.2 * post_residual as f64;
    }

    // Relative to mean residual: prefer bins already below-average residual (well-filled)
    score += 0.3 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0);
    }

    // New-bin candidate handling: opening a new bin is only attractive when no open bin
    // offers a decent fit (post residual too small to be useful)
    if bin_residual == bin_capacity {
        // new empty bin: post_residual == capacity, so it looks great by default;
        // penalize it so existing bins with reasonable fits win
        score += 55.0;
        // but if it's the last item or nothing fits well, opening is fine
        if next_item_size == 0 { score -= 30.0; }
        if open_bins_count == 0 { score -= 55.0; }
    } else {
        // existing bin: reward if post residual is still usable for typical items
        if post_residual >= 10 && post_residual < 20 {
            score -= 10.0; // sweet-spot residual
        } else if post_residual < 10 {
            score -= 20.0; // nearly-full bin, great placement
        }
    }

    // Late in stream: consolidate, avoid opening new bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= 8.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) more strongly than linear.
    score += (post_residual as f64 / bin_capacity as f64).powf(2.0) * 40.0;

    // Penalize dead space: post_residual too small for any future item (min size 1).
    if post_residual > 0 {
