        }
    }

    // New-bin candidate handling: neutral-ish baseline, but encourage new bin
    // when current bins are fragmented (high mean residual relative to item).
    if bin_residual == bin_capacity {
        score = bin_capacity as f64 * 0.6;
        if mean_residual > item_size as f64 * 1.5 {
