        score += progress * 25.0;
    }

    // Global fragmentation pressure: many open bins with high mean residual
    // -> prefer filling existing bins harder.
    score -= (mean_residual / bin_capacity as f64) * (open_bins_count as f64).ln().max(1.0) * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let prn = pr / cap;

    // Base: penalize wasted residual, smoothed by quadratic coupling with progress
    let mut score = prn * prn * (1.0 + 2.0 * progress) + prn * (1.0 - progress);

    // Reward tight fits: cubic coupling of post_residual with item share
    let fill = item_size as f64 / cap;
    score -= 3.0 * fill * (1.0 - prn) * (1.0 - prn);

    // Penalize dead space that no typical next item can use
    if next_item_size > 0 {
        let nx = next_item_size as f64 / cap;
        if nx > prn {
            score += (nx - prn) * (nx - prn) * 4.0;
        } else {
            score -= (prn - nx) * 1.5;
        }
    }

    // Last-chance bonus when few fitting bins
    if fitting_bins_count <= 1 {
        score -= 2.0;
    }

    // Slight preference for bins below mean residual (consolidation)
    score += 0.3 * (pr - mean_residual) / cap;

    // New-bin candidate handling: mildly discourage opening new bins early,
    // more acceptable late in stream
    if bin_residual == bin_capacity {
        score += 1.5 - 2.5 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic classes of post_residual: perfect fits (residue 0) are ideal.
    if post_residual == 0 {
        score -= 60.0;
    } else {
        // Dead-space class: residuals below the smallest item are wasted.
        if post_residual < 10 {
            score += 80.0;
        }
        // Modulo classes: residuals divisible by common item sizes are reusable.
        let r = post_residual;
        if r % 10 == 0 { score -= 12.0; }
        else if r % 5 == 0 { score -= 6.0; }
        // Fractional capacity bands: large leftovers are flexible.
        let frac = r as f64 / bin_capacity as f64;
        if frac > 0.5 { score -= 8.0; }
        else if frac < 0.2 { score += 10.0; }

        // Integer-division thresholds on next item lookahead.
        if next_item_size > 0 {
            if next_item_size <= post_residual {
                // Next item chains into this bin: strong reward.
                score -= 20.0;
                // Exact chain fill: harmonic pair.
                if next_item_size == post_residual { score -= 25.0; }
                // Residual after hypothetical chain placement.
                let r2 = post_residual - next_item_size;
                if r2 == 0 { score -= 15.0; }
                else if r2 < 10 { score += 25.0; }
                else if r2 % 10 == 0 { score -= 8.0; }
            } else {
                // Next item cannot use this residual: penalize hoarding space.
                score += 5.0;
                if post_residual < next_item_size && post_residual < 25 { score += 12.0; }
            }
        }
    }

    // Last-chance bin: using it avoids opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate: keep it moderately attractive only when current fit is bad.
    if bin_residual == bin_capacity {
        score += 15.0;
        if post_residual < item_size / 2 { score -= 10.0; }
    }

    // Early stream: be slightly greedy with tight fits; late stream: consolidate.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 3.0 * (post_residual as f64 / bin_capacity as f64);
    score += progress * (post_residual as f64 - mean_residual).clamp(-20.0, 20.0) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to fit even the
    // smallest plausible item are pure waste -> heavy quadratic penalty.
    let dead_threshold = 10.0f64.min(cap * 0.1);
    if (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * (dead_threshold - post_residual as f64) * 8.0;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 40.0;
    } else if (post_residual as f64) <= cap * 0.05 {
        score -= 25.0;
    }

    // Tightness reward: fraction of bin consumed by this placement.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= fill_ratio * 15.0;

    // Open-bin pressure: discourage spreading across many bins unless fit is great.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // New-bin candidate: only attractive if no open bin fits well
    // (residual far above item) or stream is early and item is large.
    if bin_residual == bin_capacity {
        let poor_fit_elsewhere = mean_residual < item_size as f64 * 1.2;
        if poor_fit_elsewhere {
            score -= 20.0;
        } else {
            score += 35.0;
        }
        // Large items benefit from a fresh bin late in the stream less.
        if step_index as f64 / total_items.max(1) as f64 > 0.7 {
            score += 10.0;
        }
    }

    // Lookahead: if the next item fits exactly into the post residual,
    // reward this placement (chaining).
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 35.0;
    } else if next_item_size > post_residual as u32 && post_residual > 0 {
        // dead space relative to lookahead item
        score += (next_item_size - post_residual as u32) as f64 * 0.5;
    }

    // Mild preference toward bins below mean residual (consolidate emptier bins).
    if (bin_residual as f64) > mean_residual {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward perfect or near-perfect fits.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Penalize dead space that cannot fit the next item (2-step lookahead).
        if next_item_size > 0 {
            if post_residual >= next_item_size {
                // Reward leaving exactly enough room for the next item.
                score -= (post_residual - next_item_size) as f64 * 0.3;
                // Extra bonus for a perfect chain fit.
                if post_residual == next_item_size {
                    score -= 200.0;
                }
            } else {
                // Dead space penalty: unusable for the next item.
                let waste = post_residual as f64 / bin_capacity as f64;
                score += waste * 150.0;
            }
        } else {
            // Last item: just minimize waste.
            score -= 50.0;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate: penalize opening a new bin unless the item is large
    // and current residuals are tight (item barely fits anywhere).
    if bin_residual == bin_capacity {
        let tightness = item_size as f64 / bin_capacity as f64;
        let mean_tight = mean_residual / bin_capacity as f64;
        // Prefer new bin when item is big and open bins are fragmented/tight.
        score += 400.0 - 300.0 * tightness - 200.0 * mean_tight;
        // Late in the stream, discourage opening extra bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 150.0 * progress;
    }

    // Mild preference for bins tighter than average (fill crowded bins first).
    score += (bin_residual as f64 - mean_residual) * 0.2;

    // Prefer reusing bins over spreading across many open bins.
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual near zero is already low; amplify quadratic waste penalty.
    let pr = post_residual as f64;
    score += 0.6 * pr * pr / bin_capacity as f64;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual <= 5 {
        score -= 12.0;
    }

    // Penalize dead space that no future item (min size 1..10) can use.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Last chance: if this is the only fitting bin, strongly prefer using it over a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Lookahead: reward bins whose post_residual matches next item size.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score += 0.35 * gap;
        if post_residual as i64 == next_item_size as i64 {
            score -= 15.0;
        }
        // Penalize leaving residual too small for the next item.
        if (post_residual as u32) < next_item_size && post_residual > 0 {
            score += 10.0;
        }
    }

    // Prefer fuller bins relative to the mean residual across open bins.
    score += 0.5 * (bin_residual as f64 - mean_residual);

    // Time horizon: early in the stream, be more willing to open new bins (favor spreading);
    // late in the stream, consolidate tightly.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= (1.0 - progress) * 5.0 * (bin_residual as f64 / bin_capacity as f64);
    score += progress * 10.0 * (bin_residual as f64 / bin_capacity as f64);

    // Many open bins: encourage closing them out (use existing bins).
    score += 0.8 * open_bins_count as f64 * (1.0 - bin_residual as f64 / bin_capacity as f64);

    // Mild penalty for opening a brand-new bin when decent fits exist.
    if bin_residual == bin_capacity {
        score += 18.0 + 3.0 * fitting_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let item = item_size as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mean_res = mean_residual.max(0.0);

    // Core: prefer small post_residual, with non-linear shaping (quadratic coupling).
    let mut score = pr + 0.35 * (pr * pr) / cap;

    // Tight-fit reward: smooth sigmoid-like bonus when post_residual is small.
    let tight = (-pr / 12.0).exp();
    score -= 6.0 * tight;

    // Fullness reward: smootherstep on fill ratio of the bin.
    let fill = (bin_residual as f64) / cap;
    let s = fill * fill * fill * (fill * (fill * 6.0 - 15.0) + 10.0);
    score -= 8.0 * s;

    // Lookahead coupling: if next item fits in the post residual, reward this placement.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let slack = pr - nxt;
            score -= 4.0 * (-(slack as f64) / 15.0).exp();
        } else {
            // Next item won't fit here: mild penalty scaled by gap.
            score += 1.5 * ((nxt - pr) / cap);
        }
    } else {
        // Last item: strongly prefer filling bins tightly.
        score -= 10.0 * tight;
    }

    // Last-chance bin: if this is the only fitting bin, opening a new bin wastes its residual;
    // reward using it, more so early in the stream.
    if fitting_bins_count == 1 {
        score -= 3.0 + 3.0 * (1.0 - progress);
    }

    // Stream-progress coupling: late in the stream, be greedier about filling bins
    // (penalize leaving residual), early be more tolerant.
    score += (0.5 + 1.5 * progress) * (pr / cap);

    // Contextual: when mean residual across bins is high, prefer consolidating into
    // already-large-residual bins less (avoid fragmenting); interact smoothly.
    let norm_mean = mean_res / cap;
    score += 2.0 * norm_mean * (pr / cap).powi(2);

    // Slight penalty for spreading across many open bins when this bin is nearly empty.
    if fill > 0.95 {
        score += 1.0 + 0.02 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: divide capacity into octiles.
    // Residuals in the same octile class are "harmonically equivalent";
    // reward placements that land the bin into a low (nearly full) class.
    let octile = (post_residual * 8) / bin_capacity; // 0..=7
    score += octile as f64 * 4.0;

    // Exact-fit / near-fit reward (post_residual in lowest class).
    if octile == 0 {
        score -= 30.0;
    }

    // Dead-space penalty: leftover too small to hold any plausible item
    // (below the minimum item size), i.e. unusable remainder.
    if post_residual < 10 && post_residual > 0 {
        score += 25.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // strongly favor this bin (perfect chaining).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // Harmonic compatibility of the pair: next item leaves again a
            // low-class residual -> chain continues.
            let next_post = post_residual - next_item_size;
            let next_octile = (next_post * 8) / bin_capacity;
            score -= (8 - next_octile.min(7)) as f64 * 3.0;
        } else {
            // Next item cannot use this leftover: penalize proportionally
            // to how much of the leftover is wasted relative to next item.
            let waste = (next_item_size - post_residual) as f64;
            score += (waste / 20.0).min(10.0);
        }
    }

    // Last-chance bonus: this is the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: an empty bin has high raw residual; make it
    // attractive only when open bins are on average quite full or very fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = (mean_residual - post_residual as f64).abs();
        // Prefer a fresh bin when existing residuals are small (little room left)
        // or the stream is early and we can afford to spread items.
        let threshold = 18.0 + 20.0 * (1.0 - progress) + open_bins_count as f64 * 0.5;
        if mean_residual < threshold {
            score -= 15.0 + fragmentation * 0.2;
        } else {
            score += 20.0;
        }
    }

    // Mild preference to fill bins whose residual is close to the item
    // (tightness reward), scaled by how full the bin already is.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= tightness * 12.0;

    // Small penalty for leaving residual in awkward middle classes
    // (residuals that are too big to waste but too small to pair well).
    let mid = post_residual % 25;
    if mid > 5 && mid < 15 {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small but nonzero gaps are the worst.
    if post_residual == 0 {
        score -= 60.0; // perfect fit
    } else if post_residual < 10 {
        score += (10 - post_residual) as f64 * 8.0; // tiny unusable gap
    }

    // Reward bins whose residual stays large enough to be reusable.
    if post_residual >= 50 {
        score -= 6.0;
    } else if post_residual >= 25 {
        score -= 2.0;
    }

    // Last chance: strongly prefer placing into the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if next item fits the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 5.0;
    }
    // Penalize leaving a gap that just barely fails to fit the next item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 3.0;
    }

    // Open-bin pressure: mildly discourage spreading across many bins
    // unless the fit is good (score already low).
    score += open_bins_count as f64 * 0.15;

    // Slight drift over the stream: tighten packing as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += post_residual as f64 * progress * 0.5;

    // New-bin candidate: make it slightly unattractive unless all fits are bad.
    if bin_residual == bin_capacity {
        score += 12.0;
    }

    // Prefer bins tighter than the mean residual (good fits among open bins).
    score += (mean_residual - bin_residual as f64) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus: post_residual exactly matches the next item's size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Post-residual large enough for the next item is better than one that isn't.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0 + (post_residual - next_item_size) as f64 * 0.15;
        } else {
            score += (next_item_size - post_residual) as f64 * 0.35;
        }
    }

    // Penalize tiny unusable dead space strongly (dead space <= 10 is wasted).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 + (10 - post_residual) as f64 * 2.0;
    }

    // Reward tight fits: small post_residual relative to mean residual.
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when the fit into open bins is poor
    // (large post_residual waste) or few bins fit the item.
    if bin_residual == bin_capacity {
        let waste_penalty = if next_item_size > 0 && post_residual >= next_item_size { -8.0 } else { 0.0 };
        let poor_fit = (post_residual as f64 - mean_residual).max(0.0);
        score += 45.0 - poor_fit * 0.4 + waste_penalty
            - if fitting_bins_count <= 1 { 35.0 } else { 0.0 };
        // Early in the stream, opening bins is cheaper.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= (1.0 - progress) * 10.0;
    }

    // Slight preference for fuller bins when many bins are open.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress fraction: later in stream -> prefer using existing bins more aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.35 * progress;

    // Reward tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Lookahead: if the next item fits exactly into post_residual, strongly reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 8.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit here; penalize leaving a gap that nothing will fill.
            score += 4.0;
        }
    }

    // Dead-space penalty: residuals too small for the smallest plausible item are waste.
    if post_residual < 10 && post_residual > 0 {
        score += 22.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Penalize bins whose residual deviates far below the mean (already fragmented).
    let dev = bin_residual as f64 - mean_residual;
    if dev < 0.0 {
        score += 0.08 * (-dev);
    } else {
        score -= 0.04 * dev;
    }

    // When many bins are open, favor consolidation into existing bins.
    score += 0.05 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate handling: empty bin gets a moderate default so it's chosen
    // only when no open bin scores better (tight fits / last chance beat it).
    if bin_residual == bin_capacity {
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let post = post_residual as f64;
    let cap = bin_capacity as f64;
    let post_norm = post / cap;

    // Base: prefer tight fits (small post_residual), with a non-linear penalty
    // that grows super-linearly as wasted space increases.
    let mut score = post + 24.0 * post_norm * post_norm * cap;

    // Smooth polynomial coupling with stream progress: late in the stream,
    // waste is costlier, so amplify the quadratic waste term.
    let late = progress * progress;
    score += 60.0 * late * post_norm * post_norm * cap;

    // Interaction: post_residual relative to item_size (fit ratio).
    let fit_ratio = post / (item_size.max(1) as f64);
    score += 8.0 * (fit_ratio / (1.0 + fit_ratio)); // saturating smooth penalty

    // Lookahead coupling: if the next item fits into the post-residual,
    // reward this bin; else penalize proportionally to the gap.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            let slack = (post - nxt) / cap;
            score -= 18.0 * (1.0 - slack) * (1.0 - slack);
        } else {
            let gap = (nxt - post) / cap;
            score += 20.0 * gap * gap * cap;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it to avoid opening a new bin (smoothly scaled by progress).
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0 + 40.0 * progress;
    }

    // Mild penalty for scattering across many open bins with large mean residual.
    let spread = (mean_residual - post).abs() / cap;
    score += 4.0 * spread * spread * (open_bins_count as f64).sqrt();

    // New-bin candidate: make empty bins attractive only when no tight fit
    // exists elsewhere; an empty bin has zero waste but no synergy, so give
    // it a neutral-plus score that tight fits in open bins can beat.
    if bin_residual == bin_capacity {
        score += 15.0 + 20.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "usable"
    // classes (multiples of 10, i.e. divisible by common item sizes) are better.
    let pr = post_residual;
    let usable_class = if pr == 0 { 3 }
        else if pr % 10 == 0 { 2 }
        else if pr % 5 == 0 { 1 }
        else { 0 };
    score -= 12.0 * usable_class as f64;

    // Dead-space penalty: tiny unusable leftovers (1..=9) are wasted capacity.
    if pr > 0 && pr < 10 {
        score += 25.0;
    }

    // Perfect fit: huge reward.
    if pr == 0 {
        score -= 60.0;
    }

    // Lookahead harmony: does post_residual leave room for next item exactly?
    if next_item_size > 0 {
        if pr >= next_item_size {
            let nxt_post = pr - next_item_size;
            if nxt_post == 0 {
                score -= 45.0; // chain of perfect fits
            } else if nxt_post % 10 == 0 {
                score -= 18.0;
            } else if nxt_post < 10 {
                score += 15.0; // would create dead space for next item
            }
        } else {
            // next item won't fit here anyway; slight penalty for large leftover
            score += (pr as f64) * 0.05;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: prefer open bins unless this is a great fit.
    if bin_residual == bin_capacity {
        // brand-new bin: penalize so only chosen when open bins fit poorly
        score += 40.0;
        if item_size % 10 == 0 {
            score -= 10.0; // round sizes keep new bin tidy
        }
    }

    // Fraction-of-capacity coupling: item size classes relative to capacity.
    let frac = item_size as f64 / bin_capacity as f64;
    if frac > 0.5 {
        score -= 8.0; // big items belong in emptier bins
        score += (bin_capacity - bin_residual) as f64 * 0.02;
    }

    // Stream progression: late in the stream, be more frugal with open bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0 * (open_bins_count as f64).ln().max(0.0);

    // Mean residual coupling: if this bin is far from mean residual, mild penalty.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.03;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (1..=12) are heavily penalized.
    if post_residual > 0 && post_residual <= 12 {
        score += 60.0 * (13.0 - post_residual as f64);
    }
    // Medium gaps (13..=25) are mildly wasteful too.
    if post_residual > 12 && post_residual <= 25 {
        score += 15.0 * (26.0 - post_residual as f64) / 13.0;
    }

    // Reward perfect / near-perfect fits.
    if post_residual == 0 {
        score -= 80.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Open-bin pressure: many open bins => discourage spreading; favor filling existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * (1.5 + 3.0 * progress);

    // If the next item fits into the post_residual, reward this placement (chain packing).
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 20.0;
    }
    // If next item barely misses post_residual, this creates a dead end: penalize.
    if next_item_size > 0 && post_residual > 0 && next_item_size > post_residual && post_residual < 10 {
        score += 25.0;
    }

    // Mean residual coupling: if this bin is far below mean residual (already tight),
    // it's a good filler bin; if far above, penalize slightly.
    score += (mean_residual - bin_residual as f64) * 0.3;

    // New-bin candidate handling: an empty bin has residual == capacity.
    // Prefer it only when no open bin fits well; make it moderately unattractive by default.
    if bin_residual == bin_capacity {
        score += 55.0 + 2.0 * open_bins_count as f64;
        // But if the item is large relative to capacity, a fresh bin may be wise.
        if item_size * 4 >= bin_capacity * 3 {
            score -= 70.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward bins whose post_residual can host the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // chain-friendly placement: reward proportionally to tightness of chain fit
            let chain_waste = (post_residual - next_item_size) as f64;
            score -= 40.0 - 0.3 * chain_waste;
        } else {
            // dead space relative to next item: penalize small unusable gaps
            let gap = (next_item_size - post_residual) as f64;
            score += 0.4 * gap;
        }
    }

    // Penalize leaving large residual (wasted space) but tolerate it near stream start
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.25 * (post_residual as f64) * (0.5 + progress);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 150.0;
    }

    // Prefer bins tighter than the mean residual (good packing)
    score -= 0.5 * (mean_residual - bin_residual as f64);

    // Penalize opening a new bin when decent open bins exist
    if bin_residual == bin_capacity && open_bins_count > 0 && post_residual > 0 {
        let avg_post = mean_residual - item_size as f64;
        if avg_post >= 0.0 {
            score += 30.0 + 0.6 * avg_post;
        }
    }

    // Slight penalty for many open bins (encourage consolidation)
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (low post residual) with a non-linear penalty.
    let cap = bin_capacity as f64;
    let tightness = 1.0 - (post_residual as f64) / cap;
    score -= tightness * tightness * 12.0;

    // Penalize leaving dead space that the lookahead item cannot use.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as f64) < nxt {
            // dead space for the next item: penalize proportionally to waste
            let waste = nxt - post_residual as f64;
            score += waste * 0.8;
        } else {
            // reward bins where next item also fits snugly
            let nxt_fit = (post_residual as f64 - nxt) / cap;
            score -= (1.0 - nxt_fit) * 3.0;
        }
    } else {
        // last item: pure tightness matters most
        score -= 5.0 * tightness;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 8.0;
    }

    // When many bins are open, prefer consolidation; when few, new bins are cheap.
    let crowding = open_bins_count as f64;
    score += crowding * 0.15 * (post_residual as f64 / cap);

    // Global mean residual coupling: if average residual is high, penalize bins
    // that deviate upward (keep residuals homogeneous and small).
    let dev = post_residual as f64 - mean_residual;
    score += 0.25 * dev.max(0.0) - 0.10 * (-dev).max(0.0);

    // Time horizon: early in stream, be liberal with new bins (explore);
    // late in stream, squeeze into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let new_bin_penalty = 15.0 * progress;
    if bin_residual == bin_capacity {
        score += new_bin_penalty;
        // but a new bin is fine if the item is large and fits poorly elsewhere
        score -= (item_size as f64 / cap) * 5.0 * (1.0 - progress);
    }

    // Mild preference for filling bins that are already partially committed.
    let used_frac = 1.0 - (bin_residual as f64) / cap;
    score -= used_frac * 2.0;

    // Non-linear coupling: large items into already-low-residual bins.
    if item_size >= 50 && bin_residual < 100 {
        score -= (item_size as f64 - 50.0) * (bin_residual as f64 / cap) * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual in [0,1]

    // Base: prefer small post residual (tight fit), with non-linear shaping
    let mut score = pr * (1.0 + 0.8 * x * x);

    // Smooth polynomial coupling of post residual with stream progress:
    // early on, keep bins flexible (penalize very small residuals mildly),
    // later, chase tight fits aggressively.
    let flex = 3.0 * x * (1.0 - x); // peaks mid-range residuals
    score += flex * (1.0 - progress) * 8.0;
    score -= (1.0 - x) * (1.0 - x) * progress * 12.0;

    // Dead-space penalty: residuals too small for typical future items
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if pr < ni {
            score += (ni - pr) * (0.5 + 2.0 * progress);
        } else {
            // reward leaving room for the lookahead item
            score -= (1.0 - (pr - ni) / cap) * 4.0;
        }
    }

    // Last-chance bonus: strongly prefer filling the only fitting bin
    if fitting_bins_count == 1 {
        score -= 10.0 + 15.0 * progress;
    } else if fitting_bins_count > 1 {
        score += 1.5 * (fitting_bins_count as f64 - 1.0).min(3.0);
    }

    // Mild pressure toward consolidating into fewer bins
    score += (open_bins_count as f64).ln1p() * 0.3 * x;
    score += (mean_residual - pr) * 0.05;

    // Penalize opening a new bin unless item is large relative to capacity
    if bin_residual == bin_capacity {
        score += 6.0 - 10.0 * (item_size as f64 / cap) * (0.5 + progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let item = item_size as f64;
    let pr = post_residual as f64;
    let next = next_item_size as f64;
    let is_new_bin = bin_residual == bin_capacity;

    let mut score = pr;

    // --- Perfect / near-perfect fit reward ---
    if post_residual == 0 {
        score -= cap * 3.0;
    } else if post_residual <= 2 {
        score -= cap * 0.5;
    }

    // --- Harmonic class of the item (capacity-fraction thresholds) ---
    let item_class: u32 = if item > cap * 0.5 { 1 }
        else if item > cap / 3.0 { 2 }
        else if item > cap * 0.25 { 3 }
        else { 4 };

    // --- Lookahead chain logic (k=2) ---
    if next > 0.0 {
        if pr >= next {
            // The next item can chain into this bin after the current one.
            let slack = pr - next;
            score -= 6.0 + (cap - slack) * 0.02; // snug chains rewarded more
            if slack == 0.0 { score -= 8.0; }    // exact two-item chain bonus
        } else {
            // Next item won't fit after placement: dead-space penalty,
            // softened when this bin is the last resort.
            let gap = (next - pr).min(cap * 0.25);
            let avail = if fitting_bins_count > 1 { 1.0 } else { 0.3 };
            score += gap * 0.25 * avail;
        }
    }

    // --- Last-chance bin: strongly prefer it over opening a new bin ---
    if fitting_bins_count == 1 && !is_new_bin {
        score -= cap * 2.0;
    }

    // --- New-bin candidate penalty ---
    if is_new_bin {
        let mut penalty = cap * 0.6;
        // If open bins are nearly full on average, a new bin is more acceptable.
        penalty -= mean_residual.max(0.0).min(cap) / cap * cap * 0.15;
        // Many open bins already: discourage fragmentation.
        penalty += (open_bins_count as f64).min(10.0) * 0.5;
        // Large items (class 1) can't pair with each other: new bin mildly cheaper.
        if item_class == 1 { penalty -= cap * 0.1; }
        score += penalty.max(cap * 0.3);
    }

    // --- Harmonic residue alignment (modulo / integer-division flavor) ---
    if post_residual > 0 && post_residual % 10 == 0 {
        score -= 1.0; // residual aligned with common size granularity is more reusable
    }
    // Residuals just above a harmonic class boundary are awkward for future pairings.
    let half = cap * 0.5;
    let third = cap / 3.0;
    if pr > half && pr <= half + 5.0 { score += 2.0; }
    if pr > third && pr <= third + 5.0 { score += 2.0; }

    // --- Consolidation pressure: with many open bins, favor existing bins ---
    if !is_new_bin && open_bins_count > 2 {
        score -= (open_bins_count.min(12) as f64 - 2.0) * 0.2;
    }

    // --- End-of-stream tightening: penalize large residuals more late in the stream ---
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += pr * 0.1 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: exact or near-exact fills are ideal.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Penalize unusable dead space: gaps below the smallest plausible item
    // (1..=10) are pure waste, but only if not an exact fill.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Dead-space danger zone relative to known next item: if the leftover
    // cannot host the lookahead item, this fit strands space.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // Leaving room for the next item is valuable.
        score -= 6.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Open-bin pressure: discourage spawning new bins when many are open.
    // New-bin candidate has bin_residual == bin_capacity.
    if bin_residual == bin_capacity {
        score += 12.0 + 3.0 * open_bins_count as f64;
        // But a brand-new bin is fine if the item is large (poor fit elsewhere).
        if item_size > 60 {
            score -= 10.0;
        }
        // Early in the stream, opening bins is cheaper.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 8.0 * (1.0 - progress);
    }

    // Mild preference for bins below mean residual (spreads load, keeps
    // large residuals available for big future items).
    score += 0.05 * (bin_residual as f64 - mean_residual);

    // Prefer filling already-degraded bins: high fill ratio is good.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 10.0 * fill_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fill, but weight residual less than a perfect lookahead match.
    score = post_residual as f64 * 0.7;

    // Aggressive 2-step lookahead: strongly reward bins where the next item
    // fits exactly into the post residual.
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = (post_residual - next_item_size) as f64;
        score -= 25.0 + 0.6 * gap.recip().min(20.0);
        if gap == 0.0 {
            score -= 40.0; // perfect chain: item + next item fill bin exactly
        }
    } else if next_item_size > post_residual {
        // Next item cannot follow here: penalize leaving awkward dead space.
        let dead = post_residual as f64;
        if dead > 0.0 && next_item_size > 0 {
            score += dead * 0.4;
        }
    }

    // Relative-to-mean coupling: bins tighter than the mean are precious.
    let dev = mean_residual - post_residual as f64;
    if dev > 0.0 {
        score += dev * 0.5; // this bin is tighter than average -> prioritize
    } else {
        score -= dev * 0.1;
    }

    // Last-chance bin: if this is the only bin that fits, avoid wasting it
    // unless the fit is excellent.
    if fitting_bins_count == 1 {
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        if fill_ratio < 0.5 {
            score += 30.0 * (0.5 - fill_ratio);
        } else {
            score -= 10.0;
        }
    }

    // New-bin candidate handling: an empty bin is only attractive when the
    // current item is large or no open bin fits well.
    if bin_residual == bin_capacity {
        let large = item_size as f64 / bin_capacity as f64;
        if large > 0.7 || fitting_bins_count == 0 {
            score -= 15.0;
        } else {
            score += 20.0 + 10.0 * (1.0 - large);
        }
    }

    // Mild stream-progression pressure: late in the stream, consolidate.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 5.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = 0.0;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let resid = bin_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;
    let norm_next = next_item_size as f64 / cap;

    let mut score = pr as f64;

    // Non-linear polynomial coupling of post_residual with stream progress
    let t = progress;
    let poly = 1.0 + 0.8 * t - 1.6 * t * t + 0.8 * t * t * t;
    score *= poly;

    // Reward tight fits (low post_residual) more strongly as stream progresses
    score -= 6.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * (0.5 + t);

    // Penalize dead space that is too small for typical future items
    if norm_pr > 0.0 {
        let dead = (norm_pr / 0.35).min(1.0);
        score += 4.0 * (1.0 - dead) * (1.0 - dead) * norm_pr;
    }

    // Reward bins whose residual is well-matched to the item (smooth coupling)
    let fill_ratio = 1.0 - (resid / cap);
    score -= 3.0 * norm_item * fill_ratio * (1.0 + t);

    // Lookahead coupling: if next item fits the post residual, reward
    if next_item_size > 0 && post_residual >= next_item_size {
        let snug = 1.0 - ((post_residual - next_item_size) as f64 / cap);
        score -= 5.0 * snug * snug;
    } else if next_item_size > 0 {
        score += 2.0 * norm_next * (1.0 - norm_pr);
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 7.0 * (0.6 + 0.4 * t);
    }

    // Encourage consolidation when many bins are open
    let open_norm = (open_bins_count as f64 / (total_items.max(1) as f64)).min(1.0);
    score += 2.0 * open_norm * norm_pr;

    // Mild preference toward bins with residual near the mean (balance)
    score += 0.5 * ((resid - mean_residual) / cap).abs();

    // New-bin candidate: penalize slightly so it is only chosen when fits are bad
    if bin_residual == bin_capacity {
        score += 3.0 + 4.0 * (1.0 - t) + 2.0 * norm_item;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residual in [0..10) is "perfect",
    // larger classes are progressively less useful dead space.
    let class = post_residual / 10;
    score += match class {
        0 => -40.0,
        1 => -10.0,
        2 => 5.0,
        3 => 15.0,
        4 => 25.0,
        5 => 35.0,
        6 => 45.0,
        7 => 55.0,
        8 => 65.0,
        9 => 75.0,
        _ => 85.0,
    };

    // Exact fill is ideal.
    if post_residual == 0 {
        score -= 200.0;
    }

    // Reward when the lookahead item fits exactly into the post residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 120.0;
        } else if next_item_size <= post_residual {
            score -= 25.0;
        } else {
            // Lookahead cannot use this bin's remainder: penalize proportionally.
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 60.0;
    }
    // Many alternatives: mildly penalize wasting a scarce small residual.
    if fitting_bins_count > 3 {
        score += (fitting_bins_count as f64) * 2.0;
    }

    // Modulo-20 harmonic coupling on item size: large items prefer tight bins.
    let item_class = item_size % 20;
    if item_class >= 15 {
        score -= (100 - item_size) as f64 * 0.3;
    }

    // New-bin candidate: only attractive when no open bin offers a good fit.
    if bin_residual == bin_capacity {
        let tight_exists = fitting_bins_count > 0 && (mean_residual - item_size as f64).abs() < 20.0;
        if tight_exists {
            score += 150.0;
        } else {
            score -= 30.0;
        }
    }

    // Stream progression: late in the stream, prefer closing bins tightly.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 10.0 * (post_residual as f64 / 100.0);

    // Mean residual coupling: if open bins are generally loose, discourage
    // leaving another loose residual.
    if (post_residual as f64) > mean_residual {
        score += (post_residual as f64 - mean_residual) * 0.2;
    } else {
        score -= (mean_residual - post_residual as f64) * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A gap is "unusable" if it cannot accommodate even a mid-size item (>= 20).
    let gap = post_residual as f64;
    if gap > 0.0 && gap < 20.0 {
        score += (20.0 - gap) * 8.0; // dead space penalty
    } else if gap == 0.0 {
        score -= 60.0; // perfect fit reward
    } else {
        // Reward leaving gaps that can still fit likely future items
        score -= gap * 0.3;
    }

    // Reward bins whose residual closely matches the item (tight packing)
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += tightness * 40.0;

    // Open-bin pressure: discourage spreading across many bins,
    // but allow new bins when no good fit exists.
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize mildly, but relax when current bin fits are poor
        let poor_fit = gap > 0.0 && gap < 25.0;
        let last_chance = fitting_bins_count == 1;
        let mut new_bin_penalty = 30.0 + 2.0 * open_bins_count as f64;
        if poor_fit && !last_chance {
            new_bin_penalty -= 55.0; // opening a bin beats creating dead space
        }
        if next_item_size > 0 && next_item_size > bin_capacity {
            new_bin_penalty += 20.0;
        }
        score += new_bin_penalty;
    } else {
        // Existing bin: slight reward to consolidate into fewer bins
        score -= 5.0;
        if fitting_bins_count == 1 {
            score -= 25.0; // last chance: strongly prefer using this bin
        }
    }

    // Lookahead: if next item fits the post-residual, bonus for this placement
    if next_item_size > 0 && (next_item_size as f64) <= gap {
        score -= 15.0;
    } else if next_item_size > 0 && gap > 0.0 && (next_item_size as f64) > gap {
        score += gap * 0.2; // next item won't fit here; mild penalty for hoarding space
    }

    // Stream progression: later in the stream, be more conservative with new bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += progress * 10.0;
    }

    // Mean residual coupling: prefer bins below mean residual (tighter bins)
    score += (mean_residual - bin_residual as f64) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: strongly reward exact/excellent match with next item.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect chain (post_residual == next_item_size) is heavily rewarded.
        score -= 30.0 * (1.0 - diff / bin_capacity as f64).max(0.0) * (1.0 - diff / bin_capacity as f64).max(0.0);
        // If next item fits exactly into post_residual, big bonus.
        if post_residual as i64 == next_item_size as i64 {
            score -= 40.0;
        }
        // Penalize leaving a residual that neither fits next item nor is small.
        if (post_residual as i64) < next_item_size as i64 && post_residual > 0 {
            score += 15.0 * (post_residual as f64 / bin_capacity as f64);
        }
    } else {
        // Last item: prefer tightest fit.
        score -= 10.0;
    }

    // Compare post_residual against mean residual: avoid creating outlier dead space.
    let cap = bin_capacity as f64;
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.25 * dev;

    // Last-chance bin: strong bonus to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fits are terrible.
    if bin_residual == bin_capacity {
        score += 20.0;
        // If item is large relative to capacity, opening fresh may be wise.
        if (item_size as f64) > 0.7 * cap {
            score -= 35.0;
        }
    }

    // Mild progression term: late in stream, prefer tighter packing.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let is_new_bin = bin_residual == bin_capacity;

    // Base: prefer tight fits (small post_residual) but avoid tiny unusable slivers.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // dead-space penalty
    }

    // Lookahead: reward bins whose residual can host the next item exactly well.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual >= next_item_size {
            score -= 10.0;
        } else {
            score += 15.0; // next item won't fit here after this placement
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a bin.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 60.0;
    }

    // New-bin candidate: penalize opening a new bin when other bins fit,
    // unless the item is large and would leave open bins well-balanced.
    if is_new_bin {
        let crowding = open_bins_count as f64;
        let pressure = (item_size as f64 / bin_capacity as f64) * 100.0;
        score += 45.0 + 2.0 * crowding - pressure * 0.5;
        // Late in stream, opening fresh bins is more acceptable for large items.
        if item_size >= 60 && t > 0.5 {
            score -= 30.0;
        }
    } else {
        // Reward using bins that are more filled than average (consolidation).
        let fill = (bin_capacity - bin_residual) as f64;
        let mean_fill = bin_capacity as f64 - mean_residual;
        if fill > mean_fill {
            score -= (fill - mean_fill) * 0.3;
        } else {
            score += (mean_fill - fill) * 0.2;
        }
    }

    // Global balance: many open bins -> favor placements that empty bins out.
    if open_bins_count > 4 {
        if post_residual < 15 {
            score -= 20.0; // finishing off bins is valuable
        }
        score -= (open_bins_count.min(20) as f64) * 0.5;
    }

    // Mild time-horizon drift: early stream tolerates slack, late stream packs tight.
    score *= 1.0 + 0.15 * (1.0 - t);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr_norm = pr / cap;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let t = progress;
    let poly = pr_norm * pr_norm * (1.0 + t) + pr_norm * t * t;
    score += 40.0 * poly;

    // Tight fits are rewarded (small post_residual)
    score -= 25.0 * (1.0 - pr_norm) * (1.0 - pr_norm);

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Lookahead: reward leaving room for the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (pr - nxt).abs();
        score -= 15.0 * (1.0 - gap / cap);
        if pr >= nxt {
            score -= 8.0 * (nxt / cap);
        }
    }

    // Prefer bins with residuals near the mean (balance)
    let dev = (pr - mean_residual).abs() / cap;
    score += 10.0 * dev * dev;

    // Penalize opening new bins when good fits exist, more so late in stream
    if bin_residual == bin_capacity {
        score += 55.0 + 45.0 * t;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Perfect fit: overwhelmingly reward.
    if post_residual == 0 {
        score -= 1000.0;
        return score;
    }

    // Harmonic class of the leftover space: classify post_residual by
    // integer division into capacity-fraction buckets.
    let quarter = bin_capacity / 4;
    let eighth = bin_capacity / 8;
    let post = post_residual as f64;

    // Dead-space penalty grows super-linearly for awkward leftovers
    // (residuals that no typical item (1..100) can pair with well).
    if post_residual < eighth as u32 {
        score += (eighth as f64 - post) * 8.0; // tiny slivers are near-dead space
    } else if post_residual < quarter {
        score += (quarter as f64 - post) * 2.0;
    }

    // Reward leftovers that are "harmonic" with common item sizes:
    // divisible by 8 or 4 classes are easier to fill later.
    if post_residual % 8 == 0 { score -= 6.0; }
    else if post_residual % 4 == 0 { score -= 3.0; }

    // Lookahead coupling: if the next item fits exactly into this bin's
    // post residual, strongly favor this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual as u32 {
            score -= 400.0;
        } else if next_item_size <= post_residual {
            score -= 30.0 - ((post_residual - next_item_size) as f64).sqrt() * 3.0;
        } else {
            // Next item won't fit here; mildly penalize hoarding space
            // that becomes stranded anyway.
            score += 5.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening
    // a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0 + item_size as f64 * 0.2;
    }

    // New-bin candidate: penalize opening a bin when decent fits exist,
    // but allow it when all open bins would leave bad residues.
    if bin_residual == bin_capacity {
        let open_pressure = open_bins_count as f64;
        score += 60.0 - open_pressure * 2.0;
        // If next item is large, a fresh bin is valuable.
        if next_item_size >= 50 { score -= 25.0; }
        // If existing bins fit poorly (post_residual tiny), opening is fine.
        if post_residual == bin_capacity && fitting_bins_count > 0 {
            score += 30.0;
        }
    }

    // Progress-based mild regularization toward compacting early.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= mean_residual * 0.05 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable gaps more than large residuals
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual < 20 {
        score += 8.0;
    }

    // Reward near-perfect fits
    if post_residual == 0 {
        score -= 40.0;
    }

    // Pressure from number of open bins: prefer filling existing bins when many are open
    score += open_bins_count as f64 * 0.15;

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Lookahead: if next item fits in post_residual, reward this placement
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0;
    }

    // Slight preference for tighter bins relative to mean residual
    if (bin_residual as f64) < mean_residual {
        score -= 2.0;
    }

    // New-bin candidate: make it unattractive unless open bins are scarce
    if bin_residual == bin_capacity {
        score += 10.0 + open_bins_count as f64 * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual).
    score = post_residual as f64;

    // Aggressive 2-step lookahead: reward if next item fits exactly in post_residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0; // perfect chaining: bin becomes exactly full
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item won't fit here; penalize by how much it misses
            let miss = (next_item_size - post_residual) as f64;
            score += 0.15 * miss;
        }
    } else {
        // Last item: prefer filling as much as possible
        score -= 10.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Relative to mean residual: favor bins with residual above mean (use them up)
    score += 0.3 * (mean_residual - bin_residual as f64).max(0.0);
    score -= 0.1 * (bin_residual as f64 - mean_residual).max(0.0);

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when no open bin fits well
    if bin_residual == bin_capacity {
        // penalize opening new bins mildly, more when many open bins exist
        score += 12.0 + 2.0 * open_bins_count as f64;
        // but if mean residual is too small to fit the item, opening is fine
        if mean_residual < item_size as f64 {
            score -= 25.0;
        }
        // lookahead: fresh bin can hold next item too
        if next_item_size > 0 && (bin_capacity - item_size) >= next_item_size {
            score -= 15.0;
        }
    }

    // Early stream: be a bit more willing to open bins (build diversity)
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score -= 8.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Baseline best-fit: reward tight fits.
    score -= 8.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Penalize small dead space that can't host typical future items
    // (dead space below the smallest plausible item is nearly wasted).
    if post_residual > 0 {
        let waste = if post_residual < 10 { 15.0 } else { 0.0 };
        score += waste * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // this placement is a chain — strongly reward it.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0;
        } else if post_residual >= next_item_size {
            score -= 5.0 * (post_residual as f64 - next_item_size as f64) / bin_capacity as f64;
        } else {
            // Next item won't fit here; slight penalty proportional to leftover.
            score += 2.0 * (next_item_size as f64 - post_residual as f64) / bin_capacity as f64;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // Many open bins with high mean residual: encourage consolidation
    // into existing bins rather than spreading.
    if open_bins_count > 0 {
        let consolidation = mean_residual / bin_capacity as f64;
        if bin_residual >= mean_residual {
            score -= 3.0 * consolidation;
        } else {
            score += 3.0 * (1.0 - consolidation);
        }
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // the item is large relative to capacity or existing fits are very poor.
    if bin_residual == bin_capacity {
        let fit_quality = if fitting_bins_count > 0 {
            (bin_residual as f64 - item_size as f64) / bin_capacity as f64
        } else {
            1.0
        };
        // Prefer new bin when item is big (little residual waste) or fits are bad.
        score = 25.0 + 20.0 * fit_quality - 0.05 * open_bins_count as f64;
        if item_size as f64 / bin_capacity as f64 > 0.6 {
            score -= 10.0;
        }
        // Early in stream, be lenient about opening bins.
        if total_items > 0 {
            let progress = step_index as f64 / total_items as f64;
            score -= 8.0 * (1.0 - progress);
        }
    }

    // Mild time-horizon modulation: as the stream progresses, tighten fits.
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        score *= 1.0 + 0.1 * progress * (post_residual as f64 / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 - progress) + norm_pr * progress * (1.0 - norm_pr);
    score += 12.0 * poly;

    // Penalize large dead space more than linearly
    score += 0.05 * pr * pr / cap;

    // Reward tight fits
    score -= 8.0 * (1.0 - norm_pr) * (1.0 - norm_pr);

    // Last-resort bin: strong reward
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: reward if next item fits the post-residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            score -= 6.0 * (1.0 - (pr - nxt) / cap);
        } else {
            score += 4.0 * (nxt - pr) / cap;
        }
    }

    // New-bin candidate handling: mildly penalize opening a new bin early, allow it late
    if bin_residual == bin_capacity {
        score += 10.0 * (1.0 - progress) - 5.0 * progress;
    }

    // Slight pressure to consolidate when many bins are open
    score -= (open_bins_count as f64).ln().max(0.0) * (item_size as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: exact quarters/halves are reusable slots
    let pr = post_residual;
    if pr == 0 {
        score -= 1000.0; // perfect fit
    } else if pr <= 10 {
        score -= 200.0;
    } else {
        // classify by capacity fractions: residual close to C/4, C/3, C/2 are reusable
        let quarters: [u32; 4] = [bin_capacity / 4, bin_capacity / 2, (3 * bin_capacity) / 4, bin_capacity];
        let mut bonus = 0.0;
        for q in quarters.iter() {
            let d = if *q >= pr { *q - pr } else { pr - *q };
            if d <= 8 {
                bonus += 60.0 * (1.0 - d as f64 / 9.0);
            }
        }
        score -= bonus;

        // modulo harmonic classes: residuals divisible by common item sizes (10..80 multiples of 10)
        if pr % 10 == 0 {
            score -= 40.0 + pr as f64 * 0.2;
        }
        if pr % 25 == 0 {
            score -= 25.0;
        }
        if pr % 20 == 0 {
            score -= 20.0;
        }
        // penalize odd dead space in narrow band that nothing (min size 1 unknown) can use
        if pr < 25 && pr > 10 {
            score += 30.0;
        }
    }

    // Lookahead: reward if next item fits exactly in post_residual
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 500.0;
        } else if next_item_size <= pr {
            let waste = pr - next_item_size;
            score -= 120.0 * (1.0 - waste as f64 / cap);
            if waste % 10 == 0 { score -= 30.0; }
        } else {
            score += 15.0; // next item can't reuse this residual
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 80.0;
    } else if fitting_bins_count > 1 {
        // among many candidates, prefer tighter fits (already via post_residual)
        score += 5.0 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // New-bin candidate handling: only open a new bin when current bin would leave bad residue
    if bin_residual == bin_capacity {
        // fresh bin: attractive if current placement is poor and lookahead large
        let bad_fit = (post_residual as f64) > 0.55 * cap;
        let lookahead_big = next_item_size as f64 > 0.6 * cap;
        if bad_fit && lookahead_big && step_index + 1 < total_items {
            score -= 350.0;
        } else {
            score += 120.0; // prefer filling existing bins by default
        }
    }

    // late-stream consolidation: squeeze more into open bins
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 40.0 * progress;

    // prefer bins with residual near mean (balance load) mildly
    score += 0.05 * ((bin_residual as f64) - mean_residual).abs();

    // penalize proliferation of open bins
    score += 2.0 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for any
    // future item (min size 1, but realistically < ~10) are wasted forever.
    // Penalize hard when post_residual lands in an unusable "dead zone".
    let dead_threshold = 9.0;
    if post_residual > 0 && (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 12.0;
    }

    // Perfect / near-perfect fits get strong reward.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 3 {
        score -= 25.0;
    }

    // Tightness reward: fraction of bin consumed by this placement.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= fill * 20.0;

    // Prefer bins whose residual was already small (consolidate waste).
    score += (bin_residual as f64 / bin_capacity as f64) * 15.0;

    // Last-chance pressure: if this is the only fitting bin, strongly
    // prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones
    // (new-bin candidate gets penalized) and encourage filling existing ones.
    let obp = open_bins_count as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost + escalating pressure with open bins.
        score += 20.0 + obp * 4.0;
        // Allow a new bin if the item is large and no tight fit exists:
        // a big item in a fresh bin leaves a structured large residual.
        if item_size >= bin_capacity / 2 && fitting_bins_count <= 1 {
            score -= 30.0;
        }
    } else {
        // Existing bins get slight bonus when many bins are open.
        score -= obp.min(10.0) * 0.5;
    }

    // Lookahead coupling: if next item fits exactly in post_residual,
    // this placement is excellent; if next item barely misses, penalize.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size > post_residual && next_item_size <= bin_residual {
            score += 10.0;
        } else if next_item_size <= post_residual {
            score -= 8.0;
        }
    }

    // Mean-residual coupling: if this bin's residual is far below the mean,
    // finishing it off is good (reduces fragmentation across bins).
    let dev = mean_residual - bin_residual as f64;
    if dev > 0.0 {
        score -= dev * 0.3;
    }

    // Mild stream-progression term: later in the stream, be slightly more
    // eager to close bins tightly rather than leave scattered residuals.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward if next item fits into post_residual
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 50.0 + 0.5 * next_item_size as f64;
        // exact chain match: post_residual == next_item_size
        if post_residual == next_item_size {
            score -= 200.0;
        }
    } else if next_item_size > 0 {
        // penalize dead space that next item cannot use
        score += 0.3 * post_residual as f64;
    }

    // Relative to mean residual: prefer bins tighter than average
    score -= (mean_residual - post_residual as f64) * 0.4;

    // Last chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 300.0;
    }

    // New-bin candidate: penalize opening a new bin unless it enables a good chain
    if bin_residual == bin_capacity {
        score += 150.0;
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 100.0;
        }
    }

    // Late in stream: be more conservative, avoid many small open bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * open_bins_count as f64 * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit is ideal
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead: reward if the next item can also fit in the leftover space
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 + 0.15 * next_item_size as f64;
    }
    // Penalize leaving a gap that is just barely too small for the next item (dead space)
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 5.0 + 0.1 * (next_item_size - post_residual) as f64;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // Tightness: prefer bins where the item fills a large fraction of residual
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 10.0 * tightness;

    // Penalize creating small unusable residuals relative to capacity
    if post_residual > 0 && post_residual < 10 {
        score += 6.0;
    }

    // Time horizon: early in the stream, be more willing to spread items
    // (keep residuals flexible); late in the stream, pack tightly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= (1.0 - progress) * 3.0 * (mean_residual / bin_capacity as f64);
    score += progress * 2.0 * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: make it attractive only when open bins fit poorly
    if bin_residual == bin_capacity {
        let base_new = bin_capacity as f64 - item_size as f64;
        let crowded = open_bins_count as f64;
        let poor_fit_elsewhere = (fitting_bins_count == 0) as i32 as f64;
        let big_gap = ((mean_residual - item_size as f64).max(0.0)) / bin_capacity as f64;
        score = base_new - 20.0 * poor_fit_elsewhere * (1.0 + big_gap)
                       + 4.0 * crowded.min(10.0)
                       - (1.0 - progress) * 5.0;
        // If next item is large and would need a fresh bin anyway, opening now is fine
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 6.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Non-linear polynomial coupling of post_residual with normalized stream progress.
    let progress = (step_index as f64 / total_items as f64).clamp(0.0, 1.0);
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Smooth interaction: waste is penalized more heavily as the stream progresses.
    let waste_curve = pr_norm * pr_norm * (1.0 + 2.0 * progress) + 0.5 * pr_norm * progress * progress;
    score += 40.0 * waste_curve;

    // Reward near-perfect fits with a smooth quadratic bonus on post_residual closeness to zero.
    let tightness = 1.0 - pr_norm;
    score -= 25.0 * tightness * tightness * tightness;

    // Smoothly encourage filling bins when many are open (consolidation pressure).
    let open_pressure = (open_bins_count as f64).ln().max(0.0);
    score += 3.0 * open_pressure * pr_norm;

    // Lookahead coupling: penalize leaving a residual that awkwardly mismatches the next item,
    // reward residuals that can host the next item (smooth via quadratic mismatch).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let mismatch = pr - nxt;
        let m_norm = mismatch / cap;
        score += 15.0 * m_norm * m_norm * (1.0 - progress);
        if pr >= nxt {
            score -= 8.0 * (1.0 - (mismatch.abs()) / cap);
        }
    } else {
        // Last item: strongly prefer zero residual.
        score += 60.0 * pr_norm;
    }

    // Last-chance bin bonus (smooth): if this is the only fitting bin, favor using it.
    if fitting_bins_count == 1 {
        score -= 20.0 * (1.0 + progress);
    }

    // New-bin candidate: make the empty bin attractive only when residuals across open bins
    // are large (poor fits everywhere) — smooth function of mean residual vs item size.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let mean_gap = (mean_residual - item_size as f64).max(0.0) / cap;
        score = cap - 45.0 * mean_gap * (1.0 + 2.0 * progress) - 10.0 * open_pressure * mean_gap;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Base: prefer tight fits, but weight by stream progress.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 6.0 * progress;

    // Harmonic class of post_residual: residues mod 10 create "usable slot" classes.
    // Post-residuals divisible by 10 (and by 5) are more likely to be filled by future items.
    let r10 = post_residual % 10;
    let r5 = post_residual % 5;
    if r10 == 0 {
        score -= 8.0; // perfect harmonic slot
    } else if r5 == 0 {
        score -= 4.0;
    } else {
        score += (r5 as f64) * 1.5; // odd residues create dead space
    }

    // Integer-division threshold: classify post_residual into quarters of capacity.
    let quarter = (bin_capacity / 4) as f64;
    if pr < quarter * 0.5 {
        score += 5.0; // tiny residual: near-wasted bin
    } else if pr < quarter {
        score += 1.0;
    } else if pr > quarter * 3.0 {
        score -= 3.0; // lots of room left, bin stays flexible
    }

    // Lookahead coupling: reward if next item fits harmonically into post_residual.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if next_item_size <= post_residual {
            score -= 10.0;
            // extra reward if next item exactly matches the residual class
            if post_residual % next_item_size.max(1) == 0 {
                score -= 6.0;
            }
            if (post_residual - next_item_size) % 5 == 0 {
                score -= 3.0;
            }
        } else {
            // next item won't fit here; penalize proportionally to its size excess
            score += 0.05 * (nx - pr).max(0.0);
        }
    } else {
        // last item: just minimize residual
        score += 2.0 * pr / cap;
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // the item is large and current bins are crowded.
    if bin_residual == bin_capacity {
        let crowd = mean_residual / cap;
        let pressure = (open_bins_count as f64).ln().max(0.0);
        let benefit = 4.0 * pressure + 14.0 * (1.0 - crowd) - 0.06 * item_size as f64;
        score += benefit.max(-20.0).min(25.0);
    }

    // Mild preference to balance residuals toward the mean (avoid extreme fragmentation).
    score += 0.15 * (pr - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (< 10, the min item size)
    // are worthless; penalize them hard.
    if post_residual < 10 {
        score += 40.0;
    } else if post_residual <= 20 {
        // Near-dead space: mild penalty to prefer bins that leave larger usable gaps
        score += 8.0;
    }

    // Reward tight fits (small post_residual) with a non-linear bonus
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 15.0 * tightness * tightness;

    // Perfect fit is ideal
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly in the post_residual, reward strongly
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap < 10 {
            score -= 20.0; // next item closes this bin perfectly
        } else {
            score -= 5.0;
        }
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 6.0; // dead space for the known next item
    }

    // Last-chance pressure: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open bins pressure: when many bins are open, discourage opening new bins
    // (handled implicitly: the new-bin candidate gets no tightness/last-chance bonuses)
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure from open bin count
        score = bin_capacity as f64 - 10.0 * tightness + (open_bins_count as f64) * 4.0;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // a fresh bin is fine if the stream carries large items
        }
    } else {
        // Prefer bins whose residual deviates favorably from the mean (consolidation)
        let dev = post_residual as f64 - mean_residual;
        if dev < 0.0 {
            score += 0.05 * dev; // below-mean residual is slightly good
        }
        // Mild pressure to reduce open bin count by filling existing bins
        score -= (open_bins_count as f64).ln().max(0.0) * 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress factor: early in the stream, keep bins tight; later, be more flexible.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Core: penalize dead space quadratically relative to capacity.
    let frag = (post_residual as f64) / (bin_capacity as f64);
    score += 40.0 * frag * frag;

    // --- Aggressive 2-step lookahead matching ---
    if next_item_size > 0 {
        if post_residual == next_item_size {
            // Perfect 2-chain: this placement leaves exactly room for the next item.
            score -= 60.0;
        } else if post_residual >= next_item_size {
            // Next item fits; reward closeness of the resulting 2-chain fit.
            let slack = (post_residual - next_item_size) as f64;
            score -= 35.0 * (1.0 - slack / (bin_capacity as f64));
            score += 0.15 * slack; // still mildly prefer tight chains
        } else {
            // Next item will NOT fit here: this bin will likely be stranded.
            // Penalize proportionally to how unusable the leftover is.
            let stranded = next_item_size - post_residual;
            score += 8.0 + 0.5 * stranded as f64;
        }
    } else {
        // Last item: just minimize post residual.
        score -= 10.0;
    }

    // Compare post_residual against mean residual across open bins:
    // leaving residual far below mean creates fragmented outliers.
    if mean_residual > 0.0 {
        let dev = (post_residual as f64 - mean_residual) / mean_residual;
        if dev < 0.0 {
            score += 6.0 * (-dev); // leaving much less than average -> fragmented bin
        } else {
            score -= 2.0 * dev.min(1.0); // staying near/above mean keeps pool usable
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + 20.0 * (1.0 - progress);
    }

    // New-bin candidate handling: empty bin has residual == capacity.
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when the item is large or the
        // lookahead would be wasted in an existing bin.
        let big_item = (item_size as f64) / (bin_capacity as f64);
        score += 30.0 - 25.0 * big_item;
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            // A fresh bin can host a perfect 2-chain: encourage it.
            score -= 20.0;
        }
        if open_bins_count == 0 {
            score -= 100.0; // must open a bin
        }
    }

    // Mild preference for reusing bins over spawning many.
    score += 0.4 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: square the residual so large dead space is heavily penalized.
    score += 0.35 * (post_residual as f64 / bin_capacity as f64).powi(2) * bin_capacity as f64;

    let is_new_bin = bin_residual == bin_capacity;

    if is_new_bin {
        // Opening a new bin is a last resort: penalize unless few bins fit the item
        // or the item is large (poor fit anywhere).
        let urgency = if fitting_bins_count == 0 { 0.0 } else { (fitting_bins_count as f64).powf(1.5) * 4.0 };
        let large_item_bonus = if item_size > bin_capacity / 2 { -18.0 } else { 0.0 };
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Late in the stream, prefer closing out bins rather than spreading.
        let late_penalty = progress * 12.0 * (open_bins_count as f64).min(10.0) / 10.0;
        score += 55.0 + urgency + late_penalty + large_item_bonus;
    } else {
        // Lookahead: reward if the next item fits the post residual exactly-ish.
        if next_item_size > 0 {
            if next_item_size == post_residual {
                score -= 25.0; // perfect chain
            } else if next_item_size < post_residual {
                score -= 8.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
            } else {
                // Next item won't fit here; slight penalty if we leave awkward residue.
                score += 4.0;
            }
        }

        // Last-chance bin: strongly favor using it to avoid opening a new bin.
        if fitting_bins_count == 1 {
            score -= 30.0;
        }

        // Prefer bins below mean residual (pack fuller bins first).
        score += 0.15 * (mean_residual - bin_residual as f64);

        // Mild reward for leaving residue that pairs with common small items (<=20).
        if post_residual <= 20 {
            score -= 6.0;
        }
    }

    // Perfect fit dominates everything.
    if post_residual == 0 {
        score -= 100.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Smooth non-linear coupling of post_residual with stream progress
    let pr = post_residual as f64;
    let norm_pr = pr / bin_capacity as f64;
    let poly = norm_pr * norm_pr * (1.0 - progress) + norm_pr * progress;
    score += poly * 40.0;

    // Reward tight fits, stronger later in the stream
    let tightness = 1.0 - norm_pr;
    score -= tightness * tightness * (10.0 + 30.0 * progress);

    // Penalize last-chance bins being skipped (favor using the only fitting bin)
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: reward residual that matches next item size
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        let gap = post_residual as f64 - next_item_size as f64;
        score -= 12.0 * (1.0 - gap / bin_capacity as f64);
    } else if next_item_size > 0 {
        score += 8.0;
    }

    // New-bin candidate: mildly penalize early, allow late when open bins are full-ish
    if bin_residual == bin_capacity {
        let mean_norm = mean_residual / bin_capacity as f64;
        score += 20.0 - 35.0 * progress * mean_norm;
    }

    // Discourage spreading across too many open bins when residuals are large
    let mean_norm = mean_residual / bin_capacity as f64;
    score += (open_bins_count as f64).ln() * (1.0 - mean_norm) * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues mod 10 define "usable" classes.
    let pr = post_residual;
    let residue = (pr % 10) as f64;

    // Dead-space penalty: residuals that are small but cannot hold the next item.
    if next_item_size > 0 && pr > 0 && pr < next_item_size {
        score += 12.0 + 0.5 * (next_item_size - pr) as f64;
    }

    // Reward residuals that exactly fit next item (perfect pairing).
    if next_item_size > 0 && pr == next_item_size {
        score -= 15.0;
    }
    if next_item_size > 0 && pr >= next_item_size && pr - next_item_size < 10 {
        score -= 8.0;
    }

    // Modulo-class shaping: residuals in [0..5] are nearly perfect; [6..9] awkward.
    if residue <= 5.0 {
        score -= 4.0 * (5.0 - residue) / 5.0;
    } else {
        score += 3.0 * (residue - 5.0) / 5.0;
    }

    // Integer-division thresholds on post_residual (harmonic bands of capacity).
    let band = pr / 25; // 0..4 harmonic band
    match band {
        0 => score -= 6.0,   // very tight fit, good
        1 => score -= 2.0,   // decent
        2 => score += 1.0,   // half-full bin, mild penalty
        _ => score += 4.0,   // barely used bin
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 10.0;
    }

    // New-bin candidate: only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        score = (bin_capacity as f64) * 0.75;
        if fitting_bins_count == 0 {
            score -= 50.0; // must open new bin
        } else if next_item_size > 0 {
            // penalize opening new bin if some open bin fits next item reasonably
            let mean_ok = mean_residual >= next_item_size as f64;
            if mean_ok {
                score += 20.0;
            }
            // stream progression: late in stream, prefer closing out bins
            let progress = step_index as f64 / total_items.max(1) as f64;
            score += 15.0 * progress;
        }
        if open_bins_count == 0 {
            score -= 60.0;
        }
    }

    // Prefer bins below mean residual (consolidate emptier bins).
    score += 0.3 * (mean_residual - bin_residual as f64).max(-20.0).min(20.0);

    // Slight bonus for fitting into many-capable bins when few alternatives.
    if fitting_bins_count > 1 {
        score += 1.0; // keep flexibility, mildly discourage
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize unusable small gaps (dead space nothing can fill)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }
    // Penalize gaps too small for the next item when lookahead exists
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0;
    }
    // Reward near-perfect fills
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 10 {
        score -= 15.0;
    }

    // Tight fit reward: fraction of bin consumed
    score -= (item_size as f64 / bin_capacity as f64) * 20.0;

    // Pressure: prefer existing bins over opening new ones
    if bin_residual == bin_capacity {
        score += 15.0 + 2.0 * open_bins_count as f64;
    } else {
        score -= 5.0;
    }

    // Last chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Mild alignment with mean residual: avoid wasting bins with large residuals early
    score += 0.05 * (post_residual as f64 - mean_residual);

    // Late-stream tightening: waste matters more as stream progresses
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * (post_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward exact/near-exact fits.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // Lookahead: if next item can fit into post_residual, reward this placement.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 150.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item cannot follow here; penalize proportionally to leftover.
            let gap = (next_item_size - post_residual) as f64;
            score += 0.5 * gap.min(100.0);
        }
    }

    // Compare post_residual against mean residual across open bins.
    if post_residual as f64 > mean_residual * 1.5 {
        score += 30.0; // creates an unusually wasteful bin
    } else if (post_residual as f64 - mean_residual).abs() < 5.0 {
        score -= 10.0; // balanced residual spread
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate: prefer keeping it closed early; allow opening late
    // or when current bin would leave a large dead zone.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let dead = (bin_capacity - item_size) as f64;
        score = 250.0 + dead - 150.0 * progress;
        if fitting_bins_count == 0 {
            score -= 400.0; // no alternative
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 60.0; // stacking large items together is fine
        }
    }

    // Mild penalty for wasting space in bins with lots of residual peers.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual relative to capacity.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that no plausible item can fill.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 0.6 * (next_item_size - post_residual) as f64;
        } else if post_residual == next_item_size {
            score -= 8.0; // perfect pairing with lookahead item
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Penalize spreading across too many open bins when many fit.
    if fitting_bins_count > 1 {
        score += 1.5 * (fitting_bins_count as f64).ln();
    }

    // Global pressure: when mean residual is low, conserve space (penalize waste).
    let waste = post_residual as f64 - mean_residual;
    score += 0.4 * waste;

    // Time horizon: early on, prefer consolidating into open bins;
    // late in stream, waste matters less than bin count.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.3 * progress * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: make it unattractive unless no bin fits well.
    if bin_residual == bin_capacity {
        let mut penalty = 30.0 + 2.0 * open_bins_count as f64;
        if fitting_bins_count == 0 {
            penalty -= 40.0; // must open a new bin
        } else if item_size as f64 / bin_capacity as f64 > 0.8 {
            penalty -= 25.0; // huge item: fresh bin is fine
        }
        if progress > 0.9 {
            penalty += 10.0 * (1.0 - progress); // late stream: keep bins tight
        }
        score += penalty;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post residual, with non-linear polynomial shaping
    let mut score = pr;

    // Smooth polynomial coupling of post_residual with stream progress.
    // Early on (progress ~ 0): weight residual more lightly; late (progress ~ 1):
    // penalize residual sharply to consolidate.
    let poly = 0.5 + 1.5 * progress * progress;
    score += 40.0 * poly * norm_pr * norm_pr;

    // Dead-space penalty: residuals too small for typical items become waste.
    let dead = (norm_pr - 0.15).max(0.0);
    score += 30.0 * dead * dead * (0.5 + progress);

    // Fit quality: reward tight fits (small post_residual relative to item).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * tightness * tightness;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0 + 30.0 * progress;
    }

    // Lookahead coupling: prefer bins whose post_residual can hold the next item.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr as u32 >= next_item_size {
            score -= 10.0 * (1.0 - (pr - nx) / cap);
        } else {
            score += 8.0 * (nx - pr) / cap;
        }
    }

    // Mean residual deviation: pull toward bins near the mean (balanced packing).
    score += 0.3 * (pr - mean_residual).abs();

    // New-bin candidate: slight penalty so open bins are preferred unless bad fit.
    if bin_residual == bin_capacity {
        score += 5.0 + 15.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residuals in "usable" classes.
    // Class A: post_residual == 0 (perfect fit) -> huge reward.
    if post_residual == 0 {
        score -= 500.0;
    }
    // Class B: residual is small enough to be "dead space" (<= 10) -> mild reward.
    else if post_residual <= 10 {
        score -= 40.0;
    }
    // Class C: residual in mid-range 11..=30 is often refillable by typical items.
    else if post_residual <= 30 {
        score -= 15.0;
    }
    // Class D: large leftover space wastes the bin; penalize via quadratic term.
    else {
        let r = post_residual as f64;
        score += 0.02 * (r - 30.0) * (r - 30.0);
    }

    // Integer-division thresholds on post_residual: divisible-by-10 residuals
    // align with common item sizes -> reward.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 20.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // strongly favor this bin (chain fit).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 300.0;
        } else if next_item_size <= post_residual {
            score -= (post_residual - next_item_size) as f64 * 0.5;
        } else {
            // Next item cannot use leftover: penalize dead space proportionally.
            score += next_item_size as f64 * 0.1;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin, more so early in the stream
    // and when many bins are already open with usable mean residual.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 60.0 + 40.0 * (1.0 - progress) + 2.0 * open_bins_count as f64;
        // If mean residual across open bins is large, opening new bin is wasteful.
        score += 0.3 * mean_residual;
        // Exception: huge item with tiny next item may deserve fresh bin.
        if item_size >= 70 && next_item_size <= 20 {
            score -= 90.0;
        }
    }

    // Prefer filling bins with low residual relative to mean (tight packing).
    score += (bin_residual as f64 - mean_residual) * 0.2;

    // Modulo harmonic on (bin_residual - item_size) vs item_size class.
    if post_residual > 0 && item_size % post_residual == 0 {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 12.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += (20 - post_residual) as f64 * 3.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward leaving space that still accommodates the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 + 0.1 * next_item_size as f64;
    }
    // Penalize leaving a gap too small for the next item but nonzero.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 6.0;
    }

    // Last chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Open bins pressure: many open bins -> discourage spreading, encourage new-bin only when needed.
    score += 0.4 * open_bins_count as f64;

    // Penalize bins whose residual deviates badly from mean (fragmentation).
    score += 0.3 * (bin_residual as f64 - mean_residual).abs();

    // New empty bin candidate: only attractive if current bin fits poorly
    // (large dead space would result) or no real alternative.
    if bin_residual == bin_capacity {
        let dead = (bin_capacity - item_size).min(10) as f64;
        score = 60.0 + dead * 5.0 + 0.4 * open_bins_count as f64;
        if fitting_bins_count == 1 {
            score += 40.0; // keep last-chance bin favored over new bin
        }
        if post_residual == 0 {
            score -= 100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item -> huge reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Near-perfect lookahead match (small slack for next item).
    if next_item_size > 0 && post_residual > next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= (8.0 * (1.0 - slack / 20.0)).max(0.0);
    }

    // Penalize dead space below the minimum item size (unusable residual).
    let min_item = 1.0f64;
    if (post_residual as f64) < min_item {
        score += 50.0;
    }
    // Dead space below typical small item sizes is wasted.
    if post_residual < 10 {
        score += 12.0 * (10.0 - post_residual as f64) / 10.0;
    }

    // Reward tight fits relative to bin capacity.
    score -= 10.0 * (1.0 - (item_size as f64 / bin_capacity as f64));

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: make it slightly unattractive unless the fit in open bins is bad.
    if bin_residual == bin_capacity {
        score += 5.0;
        // If next item pairs well with current item in a fresh bin, encourage opening.
        if next_item_size > 0 && item_size + next_item_size >= bin_capacity {
            score -= 25.0;
        }
    }

    // Coupling with mean residual: prefer bins whose residual is below average (tighter bins).
    score -= 0.05 * (mean_residual - bin_residual as f64);

    // Early stream: be more conservative, keep bins flexible; late stream: pack tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (low post_residual) with a non-linear bonus.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - fit_ratio) * (1.0 - fit_ratio) * 40.0;

    // Penalize dead space that cannot hold even the smallest plausible item.
    if post_residual < 10 {
        score -= 15.0; // near-perfect fill bonus
    } else if post_residual < next_item_size.max(1) && next_item_size > 0 {
        score += 6.0; // residual too small for the lookahead item: dead space risk
    }

    // Lookahead coupling: reward residual that can still host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 * (next_item_size as f64 / bin_capacity as f64);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        // With many candidates, prefer the bin whose fill balances the fleet.
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += dev * 0.15;
    }

    // Time horizon: early in the stream, be frugal with open bins; later, consolidate.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += open_bins_count as f64 * (0.6 - 0.4 * progress);

    // New-bin candidate: open a fresh bin only when it beats poor fits,
    // i.e. when the item is large relative to capacity and fleet is congested.
    if bin_residual == bin_capacity {
        let congestion = open_bins_count as f64 / (open_bins_count as f64 + 3.0);
        score += 30.0 - 20.0 * congestion - 12.0 * (item_size as f64 / bin_capacity as f64);
        // If no open bin can host the next item either, opening fresh is fine.
        if next_item_size > 0 && next_item_size > item_size {
            score -= 10.0;
        }
    }

    // Mild preference for bins whose residual stays "usable" (>= 20) after placement.
    if post_residual >= 20 && post_residual < 50 {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

