    let mut score = post * post / cap;

    // Smooth polynomial coupling of post_residual with stream progress:
    // late in the stream, dead space becomes more costly.
    let norm_post = post / cap;
    let coupling = norm_post * (1.0 + progress * progress * 3.0);
    score += coupling * cap * 0.5;

    // Reward bins whose residual sits near the mean (keeps flexibility),
    // penalize outliers smoothly.
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += dev * dev * 20.0;

    // Last-chance bonus: strongly favor the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
