    // Lookahead: reward if next item can use the post-residual,
    // penalize if post-residual is awkwardly small for the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            score -= 8.0 * (nxt / cap);
        } else {
            score += 6.0 * (1.0 - post / nxt.max(1.0));
        }
    }

    // New-bin candidate: penalize opening a new bin unless the item is
    // large relative to capacity (then a fresh bin is genuinely useful).
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let item_frac = item_size as f64 / cap;
        score += 60.0 - 45.0 * item_frac * item_frac - 10.0 * progress;
        // discourage hoarding many open bins early
        score += open_bins_count as f64 * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
