        score += waste * waste / (bin_capacity as f64 * 0.5);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 50.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big bonus.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 300.0;
        } else if next_item_size <= post_residual {
            score -= 20.0 + (post_residual - next_item_size) as f64 * 0.3;
        } else {
            // Next item won't fit here; penalize leaving large gaps that lure nothing.
            score += (next_item_size - post_residual) as f64 * 0.1;
        }
    } else {
        // Last item overall: just minimize waste.
        score += waste_penalty(post_residual, bin_capacity);
    }

    // Global state coupling: prefer filling bins when many bins are open
    // (consolidate) vs. spreading when few are open.
    let open_f = open_bins_count as f64;
    score -= open_f * 0.5;

    // Mean residual coupling: if this bin's residual is far below mean,
    // it's a "tight" bin — prefer using tight bins.
    let residual_f = bin_residual as f64;
    let deviation = residual_f - mean_residual;
    score += deviation * 0.2;

    // New-bin candidate logic: an empty bin gets a baseline so we only open
    // a new bin when no decent fit exists.
    if bin_residual == bin_capacity {
        // Baseline cost of opening a new bin, softened when many bins are
        // already open and current fits are poor.
        score = 60.0 + open_f * 0.3;
        // If item is large, opening fresh is more attractive.
        score -= (item_size as f64) * 0.1;
    } else {
        // Time horizon: late in the stream, be more conservative about waste.
        let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += t * (post_residual as f64) * 0.4;
    }

    // Small tie-breaker toward bins with less residual (best-fit flavor).
    score += residual_f * 0.05;

    score
}

#[inline(always)]
fn waste_penalty(post_residual: u32, bin_capacity: u32) -> f64 {
    let w = post_residual as f64;
    let c = bin_capacity as f64;
    if w == 0.0 { -1000.0 } else { w * w / c }
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Base: post residual, with non-linear polynomial shaping by stream progress.
    // Early on, prefer tight fits less aggressively (waste tolerance); late, tighten.
    let tightness = 1.0 + 1.5 * progress * progress;
    let mut score = pr * tightness;

    // Smooth superlinear penalty for mid-range dead space (worst residuals ~ half-empty bins).
    let r = pr / cap;
    score += 40.0 * r * r * (1.0 - r) * (1.0 - progress * 0.5);

    // Lookahead: reward if next item fits into post_residual (smooth quadratic coupling with progress).
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        let slack = pr - next_item_size as f64;
        score -= (1.0 + progress) * (item_size as f64 / cap) * 20.0 * (1.0 - slack / cap);
    } else if next_item_size > 0 {
        // Penalize near-miss residuals that block the next item.
        let miss = (pr - next_item_size as f64).abs() / cap;
        score += 10.0 * (1.0 - miss) * (1.0 + progress);
    }

    // Last-chance bonus: strongly favor this bin if it's the only fitting one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0 * (1.0 - r);
    }

    // Mild penalty when many bins are open and this fit is loose (encourage consolidation).
    score += (open_bins_count as f64).ln().max(0.0) * r * 5.0 * (1.0 - progress);

    // Pull toward mean residual: prefer bins whose post residual is near the mean (balance).
    score += 0.3 * (pr - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Tightness reward: harmonic classes of post_residual
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fit
    } else if pr <= 5 {
        score -= 40.0;
    } else if pr <= 10 {
        score -= 25.0;
    } else {
        // modulo classes: residuals that are multiples of small sizes are reusable
        let reusable = (pr % 10 == 0) as i32 as f64 * 8.0
            + (pr % 20 == 0) as i32 as f64 * 6.0
            + (pr % 5 == 0) as i32 as f64 * 3.0;
        score -= reusable;
        // dead-space penalty for awkward residuals (prime-ish / odd chunks)
        if pr > 30 && pr % 2 == 1 {
            score += 6.0;
        }
    }

    // Lookahead coupling: does the next item fit the post residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            score -= 12.0;
            // harmonic bonus when next item exactly divides residual
            if pr % next_item_size == 0 {
                score -= 10.0;
            }
        } else {
            score += 5.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        // among many candidates, prefer tighter fits (post_residual already does this)
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // New-bin candidate handling: only attractive when current bins fit badly
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fit_quality = if next_item_size > 0 && next_item_size <= post_residual { 1.0 } else { 0.0 };
        score = cap - 0.5 * (post_residual as f64)
            + 25.0 * (1.0 - progress)
            - 20.0 * fit_quality
            + if fitting_bins_count <= 1 { -15.0 } else { 0.0 };
        // penalize new bins when mean residual across open bins is large
        score += (mean_residual / cap) * 30.0;
    }

    // mild pressure to fill existing bins as stream progresses
    score += (step_index as f64 / total_items.max(1) as f64) * 4.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that no realistic item (>=1) can use well.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // tiny unusable sliver is the worst outcome
    }
    if post_residual == 0 {
        score -= 25.0; // perfect closure is ideal
    }

    // Penalize mid-range dead space quadratically (waste grows with gap).
    let dead = post_residual as f64;
    score += 0.35 * dead * dead / bin_capacity as f64;

    // Prefer bins whose residual is close to the item (tight fit).
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score += 0.5 * tightness;

    // Lookahead: if the next item fits into the post residual, reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }
    // If next item almost fits (within 5), mild reward.
    if next_item_size > 0 && post_residual >= next_item_size.saturating_sub(5) && post_residual < next_item_size {
        score -= 4.0;
    }

    // Last-chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin, scaled by open-bin pressure.
    if bin_residual == bin_capacity {
        score += 30.0 + 8.0 * open_bins_count as f64;
        // But if open bins are all nearly full (low mean residual), opening is fine.
        score -= 0.4 * mean_residual;
        // If the item is large and would leave big dead space anywhere, new bin is attractive.
        score -= 0.2 * item_size as f64;
    }

    // Open-bin pressure: as bins accumulate, discourage spreading items thinly.
    score += 0.15 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Early stream: be slightly greedy on fill; late stream: prioritize closure.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (post_residual == 0) as i32 as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Prefer tight fits: reward small post_residual relative to item size.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio;

    // Aggressive 2-step lookahead: reward if next item fits exactly into post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0; // perfect chain match
        } else if next_item_size < post_residual {
            let rem2 = post_residual - next_item_size;
            // reward chaining, penalize leftover after chaining
            score -= 20.0;
            score += 0.35 * rem2 as f64;
        } else {
            // next item won't fit here; penalize more if leftover is dead space
            let waste = post_residual as f64;
            score += 0.25 * waste;
            if next_item_size > bin_capacity as u32 / 2 {
                score += 5.0;
            }
        }
    }

    // Penalize post_residual that is too small to ever be useful (dead space)
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Relative to mean residual: placing in a bin with residual far above mean
    // helps consolidate space.
    let dev = bin_residual as f64 - mean_residual;
    score -= 0.15 * dev;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is terrible
    // or we are early in the stream with few bins.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let bad_fit = fit_ratio < 0.6;
        if bad_fit || open_bins_count == 0 {
            score -= 18.0;
        } else {
            score += 30.0 * (1.0 - 0.5 * progress);
        }
    }

    // Mild penalty for having many open bins (encourage consolidation)
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-exact fits (small post_residual is already favored, amplify it).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 6.0 * tightness * tightness;

    // Penalize unusable dead space: residuals too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            score += 10.0 * (1.0 - (post_residual as f64) / (next_item_size as f64).max(1.0));
        }
        // If next item fits perfectly after this placement, big reward.
        if post_residual == next_item_size {
            score -= 15.0;
        }
    }

    // New-bin candidate logic: opening a new bin is acceptable only if
    // existing fits are poor (large post_residual waste) or few bins fit.
    if bin_residual == bin_capacity {
        // Mild base penalty so a decent fit in an open bin usually wins.
        score += 12.0;
        // But if no open bin fits well, new bin becomes attractive.
        if fitting_bins_count == 0 {
            score -= 60.0;
        } else if next_item_size > 0 && post_residual >= next_item_size {
            // Fresh bin guarantees room for the lookahead item too.
            score -= 18.0;
        }
        // Late in the stream, avoid opening new bins (harder to fill).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 * progress;
    }

    // Global state coupling: many open bins with high mean residual
    // -> encourage consolidating into existing bins.
    if open_bins_count > 3 && mean_residual > (item_size as f64) {
        score -= 5.0;
    }
    // Penalize spreading items across bins when mean residual is already low.
    if mean_residual < 15.0 && bin_residual != bin_capacity {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits, with mild convexity so tiny residuals are heavily favored.
    let mut score = pr + 2.5 * norm_pr * norm_pr * cap;

    // Smooth coupling of post_residual with stream progress:
    // early on, tolerate leftover space; late, penalize waste more.
    score += 12.0 * progress * norm_pr * norm_pr * cap;

    // Reward bins whose residual is close to the next item's size (smooth kernel).
    if next_item_size > 0 {
        let diff = (pr - next_item_size as f64) / cap;
        score -= 8.0 * (-diff * diff * 40.0);
    }

    // Penalize opening a new bin when open bins exist, more so early in the stream.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 20.0 + 30.0 * (1.0 - progress);
    }

    // Last-chance bonus: strongly favor the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Mild alignment with mean residual state: avoid bins far from fleet average.
    score += 0.5 * (pr - mean_residual).abs();

    // Small smooth tie-breaker using progress and item size.
    score += 0.05 * (item_size as f64) * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Prefer tight fits: reward small post_residual non-linearly.
    if post_residual == 0 {
        score -= 60.0; // perfect fit is ideal
    } else {
        let pr = post_residual as f64;
        // Harmonic-class penalty via integer division thresholds on post_residual
        let class = post_residual / 10; // classes 0..9
        score -= match class {
            0 => 45.0,          // 1..9 residual: nearly perfect
            1 => 35.0,          // 10..19
            2 => 20.0,          // 20..29
            3 => 10.0,          // 30..39
            4 => 2.0,           // 40..49
            5 => -4.0,          // 50..59: mid space often reusable
            6 => -2.0,
            7 => 4.0,
            8 => 8.0,
            _ => 12.0,          // 90..99: bad dead space
        };
        // Fraction-of-capacity coupling: penalize residuals that few item sizes can use
        let frac = pr / cap;
        if frac < 0.1 {
            score -= 15.0;
        } else if frac > 0.85 {
            score += 18.0;
        }
    }

    // Lookahead: if next item fits into post_residual, reward this placement strongly.
    if next_item_size > 0 && next_item_size <= post_residual {
        let snug = (post_residual - next_item_size) as f64;
        score -= 25.0 + 0.3 * snug.recip().min(50.0);
    }
    // If next item would NOT fit here, mild penalty proportional to how much we'd waste.
    if next_item_size > post_residual && next_item_size > 0 {
        score += 6.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        // With many options, prefer the one that preserves flexibility (larger post_residual classes)
        score += 0.15 * (fitting_bins_count as f64).ln();
    }

    // New-bin candidate handling: only open a new bin when current bins are poor fits.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 {
            1.0
        } else {
            (fitting_bins_count as f64).recip()
        };
        // Base cost of a fresh bin; reduced when few bins fit or stream is early.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let new_bin_cost = 55.0 + 40.0 * pressure - 10.0 * (1.0 - progress);
        // If next item is large, a fresh bin is more attractive.
        let lookahead_bonus = if next_item_size >= 60 { -12.0 } else { 0.0 };
        score = new_bin_cost + lookahead_bonus + 0.1 * mean_residual;
    }

    // Modulo-coupled tie-breaker on post_residual harmonics (small deterministic jitter).
    let m = (post_residual % 7) as f64;
    score += 0.4 * m;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals below the minimum item size (1) are
    // impossible, but tiny gaps (< 10) are nearly unusable -> heavy quadratic penalty.
    if post_residual < 10 {
        score += 40.0 + (10.0 - post_residual as f64) * 8.0;
    } else if post_residual < 25 {
        // Moderately unusable zone: penalize proportionally.
        score += (25.0 - post_residual as f64) * 2.5;
    }

    // Reward tight fits: the closer post_residual is to 0, the better.
    score -= (bin_capacity as f64 - post_residual as f64) / bin_capacity as f64 * 6.0;

    // Last chance: if this is the only bin that fits, strongly favor using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading into yet
    // another bin; with few bins, opening new ones is cheaper.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64).ln().max(0.0) * (3.0 + 4.0 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize by pressure so it only wins when fits are bad.
        score += 15.0 + pressure * 5.0;
        // But if no open bin fits well, the new bin becomes attractive when
        // mean residual is low (existing bins are nearly full).
        if mean_residual < item_size as f64 {
            score -= 30.0;
        }
    } else {
        // Existing bin: slight reward scaled by how much slack it absorbs.
        score -= pressure * 0.5;
    }

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // strongly favor this bin (perfect chain).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0;
        } else if post_residual >= next_item_size {
            score -= 5.0;
        } else {
            // Next item won't fit here; small penalty proportional to wasted opportunity.
            score += (next_item_size as f64 - post_residual as f64).min(15.0) * 0.4;
        }
    }

    // Prefer bins whose residual is close to the mean (balanced packing) when
    // many bins are open; prefer emptier bins when few are open.
    let diff = (bin_residual as f64 - mean_residual).abs();
    score += if open_bins_count > 4 { diff * 0.3 } else { -diff * 0.1 };

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward residuals that can host the next item exactly or well
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 400.0; // chain fit
        } else if post_residual >= next_item_size {
            score -= 60.0 * (1.0 - (post_residual as f64 - next_item_size as f64) / bin_capacity as f64);
        } else {
            // dead space relative to next item
            score += 30.0 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // Penalize residuals far below mean (fragmenting a rich bin) mildly
    score += 0.5 * (mean_residual - post_residual as f64).abs();

    // Last-chance bin: strong reward to use it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 250.0;
    }

    // New-bin candidate: penalize opening a new bin unless item is large relative to capacity
    if bin_residual == bin_capacity {
        score += 120.0 - 0.8 * item_size as f64;
    }

    // Late in stream: prefer tighter packing
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * post_residual as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: best-fit core with tightness bonus
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * tightness;

    // Penalize small unusable post_residual (dead space)
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }
    // Reward near-perfect fills
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if next item fits in the post residual, reward this placement
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0 + 0.3 * next_item_size as f64;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // post residual too small for next item: penalize proportionally
        score += 0.2 * (next_item_size as f64 - post_residual as f64);
    }

    // Global state: when many bins are open with large mean residual,
    // encourage consolidation into existing bins over opening new ones
    let progress = step_index as f64 / total_items.max(1) as f64;
    let consolidation_pressure = (open_bins_count as f64).sqrt() * (mean_residual / bin_capacity as f64);
    if bin_residual < bin_capacity {
        score -= 10.0 * consolidation_pressure;
    }

    // New-bin candidate (bin_residual == bin_capacity): only attractive when
    // item is large and no open bin fits well, or late in stream with spread residuals
    if bin_residual == bin_capacity {
        let item_frac = item_size as f64 / bin_capacity as f64;
        score += 35.0; // default cost of opening a new bin
        score -= 40.0 * item_frac * item_frac; // large items justify new bins
        score -= 15.0 * progress; // slightly cheaper to open bins late
        if mean_residual < 15.0 {
            score -= 10.0; // existing bins nearly full anyway
        }
    }

    // Mild time-horizon coupling: early stream, be conservative; late stream, pack tightly
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Normalized stream progress in (0,1]
    let t = (step_index as f64 / total_items as f64).clamp(0.0, 1.0);

    // Tightness of fit: fraction of bin consumed by this item
    let fill = item_size as f64 / cap;
    let tight = 1.0 - (post_residual as f64 / cap);

    // Non-linear polynomial coupling: reward tight fits more strongly as stream progresses
    let coupling = fill.powi(2) * (1.0 + 2.0 * t) + (fill * tight).powi(3);
    score -= 30.0 * coupling;

    // Penalize small dead space that nothing else can use (smooth quadratic in post_residual)
    let dead = post_residual as f64 / cap;
    score += 12.0 * dead * dead * (1.0 - t);

    // Lookahead: reward if next item fits into post_residual, penalize otherwise
    if next_item_size > 0 && (next_item_size as f64) <= post_residual as f64 {
        score -= 10.0 * (next_item_size as f64 / cap) * (0.5 + t);
    } else if next_item_size > 0 && post_residual > 0 {
        score += 6.0 * (1.0 - t) * (post_residual as f64 / cap);
    }

    // Last-chance bin: strong reward to use it instead of opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0 * (0.5 + 0.5 * t);
    }

    // New-bin candidate handling: prefer new bin only when open bins are quite full
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let fullness = 1.0 - mean_residual / cap;
        score += 20.0 + 25.0 * (1.0 - fullness.clamp(0.0, 1.0)) * (0.5 + t);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the resulting residual: capacity divided into 10 classes of 10.
    // Small post-residuals (tight fits) are strongly rewarded.
    let class = (post_residual / 10).min(9) as f64;
    score += class * class * 0.8; // quadratic penalty for larger leftover classes

    // Exact fit is a perfect placement.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward residual classes that are "harmonically useful": residuals that many
    // item sizes (1..=100) could still fill. Residuals in [0..10] or [50..60]
    // are prime targets for common item sizes.
    let pr = post_residual;
    if pr > 0 && pr <= 10 {
        score -= 25.0;
    } else if pr >= 50 && pr <= 60 {
        score -= 12.0;
    } else if pr >= 90 {
        score += 30.0; // nearly empty again: wasteful placement
    }

    // Dead-space penalty: residual smaller than the minimum plausible item (assume ~10)
    // is dead space, but exact 0 already handled.
    if pr > 0 && pr < 10 {
        score += 15.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // strongly favor this bin (perfect 2-chain).
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 45.0;
        } else if next_item_size <= pr {
            let npr = pr - next_item_size;
            let nclass = (npr / 10).min(9) as f64;
            score += nclass * 1.5 - 10.0; // next item still leaves a small class
        } else {
            score += 6.0; // next item won't fit here; slight penalty
        }
    }

    // Last-chance bonus: if this is the only bin that fits the item, avoid
    // opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: an empty bin has a high baseline; only
    // prefer it when open bins are crowded or the item is large.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowded = open_bins_count as f64 / (open_bins_count as f64 + 4.0);
        let item_frac = item_size as f64 / bin_capacity as f64;
        let base = 55.0
            - 35.0 * crowded
            - 25.0 * item_frac
            - 10.0 * progress;
        // If next item is large and won't combine well, opening fresh is better.
        if next_item_size > 0 && next_item_size > pr_max_hint(item_size, bin_capacity) {
            score = base - 5.0;
        } else {
            score = base;
        }
    }

    // Tie-break with mean residual: prefer bins whose residual is below mean
    // (they are already well-filled) -> placing into them is efficient.
    if bin_residual < bin_capacity {
        let dev = mean_residual - bin_residual as f64;
        score -= dev * 0.3;
    }

    score
}

#[inline]
fn pr_max_hint(item_size: u32, capacity: u32) -> u32 {
    // largest post_residual a non-new bin could offer for this item
    capacity.saturating_sub(item_size).min(capacity)
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize unusable dead space: residuals too small to fit typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 25 {
        // small gap that only fits tiny items: quadratic dead-space penalty
        score += (25.0 - post_residual as f64) * 2.5;
    }

    // Reward tight fits (post_residual near zero but still usable).
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 15 {
        score -= 10.0;
    }

    // Exact fit of the current bin residual is ideal.
    if post_residual == 0 {
        score -= 5.0 * (bin_capacity as f64 / (item_size as f64).max(1.0));
    }

    // Pressure from number of open bins: prefer filling existing bins when many are open.
    score += (open_bins_count as f64) * 1.5;

    // If this bin is the only one that fits, strongly prefer it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Penalize opening a new bin when existing bins have large mean residual.
    if bin_residual == bin_capacity {
        score += 25.0 + mean_residual * 0.3;
        // But allow a new bin if no open bin fits well (large item, large residual needed).
        if fitting_bins_count == 0 {
            score -= 50.0;
        }
    }

    // Lookahead: if next item fits exactly into post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap < 10 {
            score -= 20.0;
        } else {
            score -= 8.0;
        }
    } else if next_item_size > post_residual {
        score += 5.0;
    }

    // Mild preference to consolidate early in the stream.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - progress) * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly (non-linearly).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else {
        // Penalize dead space quadratically relative to capacity.
        let frac = post_residual as f64 / bin_capacity as f64;
        score += frac * frac * 120.0;
    }

    // Aggressive 2-step lookahead: reward bins whose residual matches the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual > next_item_size {
            let gap = (post_residual - next_item_size) as f64;
            score -= 150.0 * (-gap / 20.0).exp();
        } else {
            // Next item cannot follow into this bin; penalize proportionally.
            let shortfall = (next_item_size - post_residual) as f64;
            score += 40.0 + shortfall * 0.5;
        }
    }

    // Compare residual against mean residual: prefer bins tighter than average.
    score -= (mean_residual - post_residual as f64) * 0.8;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 120.0;
    }

    // New-bin candidate: penalize unless existing fits are poor.
    if bin_residual == bin_capacity {
        score += 250.0;
        // Allow opening a new bin late in the stream when few bins fit.
        let progress = step_index as f64 / total_items.max(1) as f64;
        if next_item_size > 0 && next_item_size > bin_capacity - item_size {
            score -= 180.0 * progress;
        }
        if fitting_bins_count <= 1 {
            score -= 100.0;
        }
    }

    // Mild preference to spread load when many bins are open.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post-residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 60.0 * tightness * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual < 10 {
        score -= 40.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 80.0;
        } else if post_residual >= next_item_size {
            score -= 15.0;
        } else {
            // Waste that the next item cannot use: penalize dead space.
            score += 0.3 * (next_item_size - post_residual) as f64;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate: penalize opening a new bin unless existing fits are bad.
    if bin_residual == bin_capacity {
        score += 45.0 + 0.5 * open_bins_count as f64;
        if fitting_bins_count > 0 && post_residual as f64 >= mean_residual {
            score += 30.0;
        }
    }

    // Penalize bins with residual far below the mean residual (fragmented bins)
    // unless this is a tight fit.
    if bin_residual != bin_capacity {
        let dev = mean_residual - bin_residual as f64;
        if dev > 0.0 {
            score += 0.2 * dev;
        }
    }

    // Time horizon: early in stream, be conservative about open bins;
    // late in stream, consolidate into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress * tightness;
    score += 10.0 * (1.0 - progress) * (open_bins_count as f64 / (open_bins_count as f64 + 5.0));

    // Mild penalty for very large dead space left behind.
    if post_residual > 0 && post_residual < next_item_size.max(1) {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let coupling = norm_pr * norm_pr * (1.0 + 2.0 * progress) + norm_pr * progress * (1.0 - progress);
    score += 12.0 * coupling;

    // Reward tight fits: small post_residual gets a smooth discount
    let tightness = 1.0 - norm_pr;
    score -= 8.0 * tightness.powi(3) * (1.0 + progress);

    // Penalize post_residual that cannot fit the lookahead item (smoothly)
    if next_item_size > 0 {
        let gap = next_item_size as f64 - pr;
        if gap > 0.0 {
            score += 4.0 * (gap / cap) * (1.0 + 2.0 * progress);
        }
    }

    // Last-chance bin: strong reward to use it rather than open a new one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 * (1.0 + progress);
    }

    // New-bin candidate: baseline cost that grows with open bins and progress
    if bin_residual == bin_capacity {
        score += 10.0 + 3.0 * open_bins_count as f64 * (0.5 + progress);
    } else {
        // Slight preference for bins with residual close to mean residual (balance)
        let dev = (pr - mean_residual) / cap;
        score += 2.0 * dev * dev;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: how "reusable" the leftover space is.
    // Residuals divisible into coarse classes (multiples of 10, 25, 50) are more
    // likely to host future items, so reward them.
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fit, best possible outcome
    } else {
        if pr % 10 == 0 { score -= 12.0; }
        if pr % 25 == 0 { score -= 8.0; }
        if pr % 50 == 0 { score -= 6.0; }
        // Very small dead space (< 10) is nearly useless: penalize harshly.
        if pr < 10 { score += 45.0; }
        else if pr <= 15 { score += 20.0; }
    }

    // Lookahead coupling: does the leftover fit the next item?
    if next_item_size > 0 && next_item_size <= pr {
        let slack = (pr - next_item_size) as f64;
        // Reward leftovers that exactly or nearly host the next item.
        score -= 25.0 - slack * 0.15;
        if pr == next_item_size { score -= 20.0; }
    } else if next_item_size > pr && pr > 0 {
        // Leftover too small for the next item: mild penalty scaled by waste.
        score += ((next_item_size - pr) as f64).min(40.0) * 0.3;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 35.0;
    } else if fitting_bins_count > 1 {
        // With many candidates, prefer tighter fits (lower post_residual already does),
        // add mild pressure toward fuller bins.
        score += (bin_residual as f64 / bin_capacity as f64) * 5.0;
    }

    // Fraction-of-capacity utilization reward for the current placement.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= fill * 10.0;

    // Mean-residual coupling: when open bins are already quite full on average,
    // prefer placing into existing bins rather than fragmenting.
    if pr as f64 <= mean_residual {
        score -= 6.0;
    } else {
        score += 3.0;
    }

    // Stream progression: late in the stream, avoid opening new bins; early on,
    // allow spreading for better long-run packing.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses.
        score += 20.0 + progress * 30.0;
        // Opening a bin is attractive early when few bins are open.
        if open_bins_count < 2 && progress < 0.3 { score -= 15.0; }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong dead-space penalty: residuals too small for any future item (1..=10)
    // are unusable, so punish them heavily; residuals >= 10 remain usable.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10 - post_residual) as f64;
    }

    // Reward perfect / near-perfect fits.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    }

    // Tightness: reward small fraction of capacity wasted.
    score += (post_residual as f64 / bin_capacity as f64) * 25.0;

    // Lookahead: if the next item fits exactly in the post residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 80.0;
        } else if next_item_size <= post_residual {
            score -= 15.0;
        } else {
            // Next item won't fit here; if post residual becomes dead space, penalize.
            if post_residual < 10 {
                score += 25.0;
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // Open-bin pressure: when many bins are open, prefer filling existing ones
    // (penalize the new-bin candidate which has bin_residual == bin_capacity).
    if bin_residual == bin_capacity {
        score += 40.0 + 8.0 * open_bins_count as f64;
        // Early in stream with few open bins, opening a new bin is cheaper.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 30.0 * (1.0 - progress) + 3.0 * open_bins_count as f64;
    }

    // Prefer bins whose residual deviates from mean residual toward fullness.
    score += 0.5 * (mean_residual - bin_residual as f64);

    // Mild preference for filling fuller bins overall.
    score -= (bin_capacity - bin_residual) as f64 * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimal post_residual (tight fit).
    // Perfect 2-step match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near-match: next item still fits after this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Next item won't fit here afterwards: dead-space penalty grows with waste.
        let waste = post_residual as f64;
        score += 10.0 * (waste / 100.0);
    }

    // Penalize residuals too small for any future item (min size 1, but small slivers are dead).
    if post_residual < 10 {
        score += 35.0 * (10.0 - post_residual as f64);
    }

    // Compare against mean residual: bins with residual well above mean are less "urgent"
    // targets; bins near mean give balanced packing.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Last-chance bonus: only this bin fits the item -> strongly prefer it over opening new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: make it attractive only when nothing fits well.
    if bin_residual == bin_capacity {
        let poor_fit = post_residual as f64 > 70.0; // item is small, lots of space left
        if poor_fit {
            score -= 15.0;
        } else {
            score += 20.0;
        }
        // Early in stream, opening bins is cheap; late, consolidate.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 25.0 * progress;
        score += 2.0 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) non-linearly.
    let cap = bin_capacity as f64;
    let tightness = 1.0 - (post_residual as f64 / cap);
    score -= 45.0 * tightness * tightness;

    // Penalize dead space: residuals too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Last-chance bonus: only bin that fits -> strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 25.0;
        } else {
            score += 15.0;
        }
        // Perfect chaining: post_residual exactly fits next item.
        if post_residual == next_item_size {
            score -= 20.0;
        }
    }

    // New-bin candidate handling: empty bin.
    if bin_residual == bin_capacity {
        // Prefer new bin only when no open bin fits well, or stream is early
        // and we expect many items (spread load).
        let progress = step_index as f64 / total_items.max(1) as f64;
        let poor_fits = fitting_bins_count == 0
            || (mean_residual - item_size as f64) < 0.0;
        if poor_fits {
            score -= 35.0;
        } else {
            score += 20.0 + 40.0 * (1.0 - progress);
        }
        // Extra penalty for opening bins late when many bins already open.
        score += 0.4 * open_bins_count as f64;
    }

    // Slight preference for bins below mean residual (consolidate slack).
    score += 0.15 * (mean_residual - bin_residual as f64).abs();

    // Time-horizon modulation: early on, be frugal with big residual bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 0.1 * bin_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Tight fit reward: strongly favor bins leaving small post_residual,
    // with a non-linear (quadratic) coupling scaled by stream progress.
    let tightness = 1.0 - (post / cap);
    score -= 30.0 * tightness * tightness * (0.5 + progress);

    // Penalize post_residual that matches the next item poorly: dead space.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (post - nxt).abs();
        let waste = if post >= nxt { gap } else { gap * 0.5 };
        score += 0.15 * waste * (1.0 + progress);
        // Reward residual that closely matches next item (chain packing).
        let match_term = 1.0 - (gap / cap).min(1.0);
        score -= 12.0 * match_term * match_term;
    }

    // Last-chance bin: strong reward to use the final fitting bin.
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 + progress);
    }

    // Penalize spreading across many open bins when residuals are large;
    // encourage consolidating into bins with small residual.
    let residual_dev = (mean_residual - post) / cap;
    score += 8.0 * residual_dev * residual_dev;

    // New-bin candidate handling: empty bin gets a mild opening penalty,
    // growing with progress, so new bins only open for large items.
    if bin_residual == bin_capacity {
        score += 18.0 * (0.6 + 0.8 * progress);
        if next_item_size > 0 {
            let nxt = next_item_size as f64;
            let cover = (post - nxt).abs() / cap;
            score += 10.0 * cover;
        }
    }

    // Smooth non-linear coupling of post_residual with progress.
    let norm_post = post / cap;
    score += 6.0 * norm_post * norm_post * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: how close it is to a "dead" residue class
    // relative to capacity fractions (1/4, 1/2, 3/4 of capacity).
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    let three_quarter = 3 * quarter;

    // Penalize post_residuals that fall into unusable small dead zones:
    // residue too small for the smallest plausible next item (<= ~10).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }
    // Integer division thresholds: classify post_residual into coarse bands
    let band = post_residual / quarter; // 0..4
    match band {
        0 => { score += 5.0; }               // tiny dead space, hard to reuse
        1 => { score -= 8.0; }               // ~1/4 capacity left: often reusable
        2 => { score -= 4.0; }               // ~1/2 capacity left: decent
        3 => { score -= 2.0; }               // ~3/4: loose fit, bin barely used
        _ => { score -= 0.0; }               // near-empty placement
    }

    // Lookahead coupling: reward if the next item fits exactly into post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0; // perfect chaining
        } else if next_item_size <= post_residual {
            let slack = post_residual - next_item_size;
            if slack < 10 {
                score -= 18.0; // near-perfect chain, minimal new dead space
            } else {
                score -= (10.0 * post_residual as f64 / (slack as f64 + 10.0)).min(10.0);
            }
        } else {
            // next item cannot use this residue: penalize proportionally to how
            // "orphaned" the residue is (modulo-style harmonic mismatch)
            let mismatch = (next_item_size - post_residual) % (quarter.max(1));
            score += 4.0 + mismatch as f64 / 8.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when current fit is poor
    // (large post_residual means item barely uses the bin).
    if bin_residual == bin_capacity {
        // Base cost of opening a bin.
        score = bin_capacity as f64 * 0.55;
        // Attractive if no bin fits well and the item is large-ish.
        if post_residual >= 0 {
            let poor_fit = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
            score -= poor_fit * 45.0;
            score -= (item_size as f64 / bin_capacity as f64) * 20.0;
        }
        // Slightly cheaper to open bins early in the stream (more future use).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 15.0;
        // Discard proliferation of open bins when mean residual is still large.
        if mean_residual > half as f64 && open_bins_count > 2 {
            score += 10.0;
        }
    }

    // Mild pressure to consolidate: prefer bins with below-average residual
    // (tighter bins) when the fit is not perfect.
    if post_residual > 0 && (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Hard penalty for tiny unusable gaps (dead space that likely can never be filled)
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual < 20 {
        score += 12.0;
    }

    // Reward near-perfect fits
    if post_residual == 0 {
        score -= 30.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // If the next item fits the post residual, this placement is doubly good
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && post_residual < 10 {
        score += 10.0; // blocks the next item with a useless gap
    }

    // Open-bin pressure: discourage spreading across many bins when mean residual is large
    if bin_residual < bin_capacity {
        let spread = (mean_residual - post_residual as f64).abs();
        score += spread * 0.3;
        score += open_bins_count as f64 * 0.5;
    } else {
        // New-bin candidate: only attractive when existing bins are too full
        score += mean_residual * 0.6 + open_bins_count as f64 * 2.0;
        if fitting_bins_count > 0 {
            score += 15.0; // bias against opening a bin when one could fit
        }
    }

    // Late in the stream, tighten packing further
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual)
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 12.0 * fit_ratio;

    // 2-step lookahead: reward bins whose post_residual matches next item
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0; // perfect chain
        } else if post_residual >= next_item_size {
            let gap = (post_residual - next_item_size) as f64;
            score -= 10.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // next item cannot fit here; penalize wasted space
            score += 0.25 * (next_item_size as f64 - post_residual as f64);
        }
    } else {
        // last item: just minimize residual
        score += 0.0;
    }

    // Penalize leaving small unusable slivers (dead space)
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Relative to mean residual: prefer consuming bins with above-average fill
    score += 0.5 * (post_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: neutral-ish baseline, penalize slightly unless current
    // open bins all have poor fits (encouraged via above bonuses)
    if bin_residual == bin_capacity {
        score += 8.0 + 0.3 * open_bins_count as f64;
        // but if lookahead item is large and nothing fits well, new bin is fine
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 6.0;
        }
    }

    // Late in stream: consolidate, avoid opening new bins
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        score += 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: squared waste penalty dominates small residuals.
    let waste = post_residual as f64;
    score += 0.35 * waste * waste / bin_capacity as f64;

    // Last-chance bin: strong reward to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // Crowding pressure: when many bins fit the item, prefer the one
    // whose residual is closest to the item (best-fit sharpening).
    if fitting_bins_count > 1 {
        score += 0.15 * (bin_residual as f64 - item_size as f64);
    }

    // Lookahead: if the next item fits in the post-residual, reward this placement
    // (keeps a compatible gap); if post-residual is a dead zone for the next item
    // but nonzero, penalize.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual >= next_item_size {
            score -= 12.0;
            // extra reward if next item exactly or nearly fills the gap
            let gap = (post_residual - next_item_size) as f64;
            score -= 8.0 * (1.0 - gap / bin_capacity as f64);
        } else if post_residual > 0 {
            score += 10.0 + 0.2 * nxt;
        }
    }

    // Global state: penalize placements into bins whose residual deviates
    // upward from the mean residual (fragmentation control).
    let dev = bin_residual as f64 - mean_residual;
    score += 0.08 * dev;

    // Time horizon: late in the stream, be more conservative about leaving
    // large residuals (fewer future items to fill them); early on, allow slack.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 0.25 * waste;

    // New-bin candidate handling: opening a new bin is only attractive when
    // no open bin fits well, or the item is large and current bins are crowded.
    if bin_residual == bin_capacity {
        let mut nb = 45.0;
        if fitting_bins_count == 0 {
            nb -= 100.0; // forced: no alternative
        } else {
            // discourage opening when a decent fit exists
            nb += 0.9 * (bin_capacity as f64 - item_size as f64);
            if fitting_bins_count == 1 {
                nb += 80.0; // last chance exists -> keep item in it
            }
            if open_bins_count > 0 {
                let avg_open_util = 1.0 - mean_residual / bin_capacity as f64;
                nb += 25.0 * avg_open_util; // crowded bins -> new bin more OK
            }
        }
        if progress > 0.85 {
            nb += 15.0; // late stream: avoid spawning near-empty bins
        }
        score += nb;
    }

    // Mild reward for filling bins completely (closing them out).
    if post_residual == 0 {
        score -= 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = (step_index as f64 / total_items as f64).clamp(0.0, 1.0);
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;

    // Base: prefer small post-residual, with non-linear tightening over time
    let mut score = pr * (1.0 + 1.5 * progress * progress);

    // Polynomial coupling: waste term grows super-linearly with residual size
    score += 12.0 * norm_pr * norm_pr * (0.5 + progress);

    // Reward tight fits (small post-residual relative to item)
    score -= 10.0 * norm_item * (1.0 - norm_pr) * (1.0 - norm_pr);

    // Penalize leaving residual that matches nothing: compare with next item
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let gap = (pr - next).abs();
        score += 0.6 * gap;
        // Bonus if next item fits exactly-ish
        if pr >= next {
            score -= 4.0 * (next / cap) * (1.0 - gap / cap);
        }
    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - norm_pr);
    }

    // Many open bins: discourage spreading; prefer filling existing bins
    score += 0.15 * open_bins_count as f64 * norm_pr;

    // Pull toward mean residual to keep bins balanced
    score += 0.3 * (pr - mean_residual).abs();

    // New-bin candidate: penalize slightly so it's chosen only when fits are bad
    if bin_residual == bin_capacity {
        score += 8.0 + 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover lands in "useful"
    // residue classes (divisible by common small sizes) are rewarded.
    let pr = post_residual;
    let mut harmonic_bonus = 0.0;
    if pr > 0 {
        if pr % 10 == 0 { harmonic_bonus += 6.0; }
        else if pr % 5 == 0 { harmonic_bonus += 3.0; }
        if pr % 20 == 0 { harmonic_bonus += 3.0; }
        if pr >= 10 && pr <= 30 { harmonic_bonus += 4.0; } // sweet spot leftover
        if pr < 10 { harmonic_bonus += 2.0; } // near-perfect fill
    } else {
        harmonic_bonus += 15.0; // perfect fit
    }
    score -= harmonic_bonus;

    // Penalize large unusable dead space (waste) nonlinearly.
    if pr > 30 {
        let waste = (pr - 30) as f64;
        score += 0.35 * waste * (1.0 + waste / cap);
    }

    // Tight fit reward: item fills most of the bin.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    if fill_ratio > 0.8 { score -= 8.0 * fill_ratio; }

    // Lookahead coupling: if the next item fits the post residual, big reward.
    if next_item_size > 0 && (pr as u64) >= (next_item_size as u64) {
        score -= 10.0;
        // harmonic check: next item leaves another class-friendly residual
        let pr2 = pr - next_item_size;
        if pr2 % 10 == 0 { score -= 4.0; }
    } else if next_item_size > 0 {
        // next item won't fit here; mild penalty scaled by gap
        let gap = (next_item_size - pr) as f64;
        score += 0.08 * gap;
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: opening a bin is expensive early, cheap late.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score = 25.0 + 15.0 * (1.0 - progress) + 0.5 * open_bins_count as f64;
        // If nothing decent exists (item barely fits anywhere), allow new bin.
        if fitting_bins_count == 0 { score -= 30.0; }
    }

    // Prefer bins whose residual is far below mean (consolidating emptier bins).
    score += 0.15 * (mean_residual - bin_residual as f64).max(-30.0).min(30.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: the smaller the post_residual, the better.
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tight;

    // Strict dead-space penalty: residuals that are too small for typical
    // future items (small gap zone) are heavily penalized.
    if post_residual > 0 {
        let r = post_residual as f64;
        if r < 10.0 {
            score += 25.0 * (1.0 - r / 10.0); // tiny unusable sliver
        } else if r < 20.0 {
            score += 8.0 * (1.0 - (r - 10.0) / 10.0); // hard-to-fill gap
        }
    }

    // Perfect fill is ideal.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Open-bin pressure: prefer spreading across bins when many are open,
    // but discourage opening new bins unnecessarily.
    score += open_bins_count as f64 * 0.8;

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a fresh bin unless the current item
    // is large or no bin fits well.
    if bin_residual == bin_capacity {
        let base_new = 20.0;
        // If lookahead item can't coexist well, opening new bin may be fine.
        let lookahead_bad = next_item_size > 0 && next_item_size > post_residual;
        score += if lookahead_bad { base_new * 0.4 } else { base_new };
    }

    // Lookahead synergy: reward if next item fits exactly in post_residual.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 18.0;
    } else if next_item_size > 0 && next_item_size < post_residual {
        score -= 3.0;
    } else if next_item_size > post_residual && post_residual > 0 {
        // Next item can't use this residual: residual becomes dead space.
        score += 6.0;
    }

    // Mean residual coupling: if this bin's residual is far below mean,
    // it's already well-utilized; favor filling it further.
    let dev = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    score -= 5.0 * dev;

    // Early in stream, be slightly more willing to open bins; later, consolidate.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += progress * 4.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong base reward for tight fits (low post_residual).
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - fit_ratio) * 30.0;

    // Aggressive 2-step lookahead: reward bins whose post_residual
    // exactly (or nearly) accommodates the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            // Perfect pairing: two items fill the bin completely.
            score -= 100.0;
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            // Prefer bins where the next item leaves minimal slack.
            score -= 25.0 * (1.0 - slack / bin_capacity as f64);
            // Extra bonus if next item then fills bin to near-capacity.
            if slack <= 5.0 {
                score -= 20.0;
            }
        } else {
            // Next item cannot follow in this bin; penalize leftover
            // space that is too small to be useful later.
            let waste = post_residual as f64;
            if waste < 10.0 {
                score += 15.0; // dead space penalty
            }
        }
    }

    // Relative-to-mean coupling: bins with residual far below mean
    // are "almost full" — placing here consolidates waste.
    let dev = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    score -= dev * 10.0;

    // Last-chance bonus: if this is the only bin that fits, avoid
    // opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && post_residual > 0 {
        score -= 12.0;
    }

    // New-bin candidate handling: opening a bin is only attractive
    // when no good fit exists; penalize fresh bins moderately so
    // existing bins are preferred unless they create dead space.
    if bin_residual == bin_capacity {
        score += 8.0;
        // But allow a new bin when lookahead suggests a perfect pairing
        // with the next item (item + next fill a fresh bin exactly).
        if next_item_size > 0 && item_size + next_item_size == bin_capacity {
            score -= 60.0;
        }
    }

    // Early-stream exploration: slight preference for consolidating
    // into fewer bins as the stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * 0.05 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: quadratic bonus for small post-residual.
    let tight = (post_residual as f64) / (bin_capacity as f64);
    score -= 40.0 * (1.0 - tight) * (1.0 - tight);

    // Penalize dead space that cannot fit the average remaining item.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if post_residual > 0 && (post_residual as f64) < 0.5 * mean_residual {
        score += 6.0 * (1.0 - progress);
    }

    // Lookahead: reward residuals that can host the next item too.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else if bin_residual >= next_item_size && post_residual < next_item_size {
            score += 4.0; // would consume the space the next item needs
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Discourage spreading when many bins are open; encourage consolidation.
    score += (open_bins_count as f64).ln().max(0.0) * 2.0;

    // Early in the stream, prefer filling existing bins less aggressively
    // (keep flexibility); late, pack tightly.
    score += 8.0 * (1.0 - progress) * tight;

    // New-bin candidate: only attractive when no open bin fits well.
    let is_new = bin_residual == bin_capacity;
    if is_new {
        let poor_fit = if fitting_bins_count == 0 { 0.0 } else {
            (post_residual as f64) / (bin_capacity as f64)
        };
        score = bin_capacity as f64 * 0.9 + 10.0 * (1.0 - progress);
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 5.0;
        }
        if fitting_bins_count == 1 {
            score -= 15.0; // existing bin is a last chance, avoid new bin
        }
        let _ = poor_fit;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
