    // Stream progress: early on, prefer keeping bins flexible (mild);
    // late, prefer filling existing bins aggressively.
    score += (1.0 - t) * 3.0 * (mean_residual - post).abs() * 0.05;
    score -= t * 4.0 * tightness;

