    if is_new_bin {
        let poor_fit = (bin_residual - item_size) as f64;
        let mut base = 30.0 + 0.5 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size as f64 > poor_fit {
            base -= 15.0; // new empty bin helps the lookahead item
        }
        if fitting_bins_count <= 1 {
            base -= 20.0; // few alternatives: new bin acceptable
        }
        score += base;
    }

    // Mild preference to balance residuals against mean.
    score += 0.15 * (post - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: quantize leftover space into capacity fractions.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let class = (pr / 10.0).floor(); // 10-unit harmonic classes

    // Reward exact / near-perfect fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 10 {
        score -= 80.0;
    } else if post_residual <= 20 {
        score -= 20.0;
    }

    // Penalize dead-space classes that few item sizes can still use:
    // leftover in (1..10) is nearly unusable; (10..20) usable only by small items.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Lookahead: reward if next item fits in post_residual (chain packing).
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 50.0 + 0.5 * next_item_size as f64;
            // extra reward for exact harmonic match (next item fills class exactly)
            if post_residual % next_item_size.max(1) == 0 {
                score -= 30.0;
            }
        } else {
            // next item cannot use this bin's leftover: penalize large leftovers
            let gap = (next_item_size - post_residual) as f64;
            score += 0.3 * gap.min(50.0);
        }
    } else {
        // Last item: prefer zero residual absolutely.
        score += 0.1 * pr;
    }

    // Harmonic class bonus: leftover divisible by common item sizes (10/20/25/50).
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 15.0;
    }
    if post_residual == 25 || post_residual == 50 || post_residual == 75 {
        score -= 10.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // New-bin candidate handling: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        score = cap - item_size as f64;
        // if other bins fit, make new bin slightly worse unless they fit poorly
        if fitting_bins_count >= 1 {
            score += 25.0;
        }
        // lookahead: a fresh bin gives max flexibility for the next item
        if next_item_size > 0 && next_item_size > post_residual {
            score -= 20.0;
        }
        // early in stream, opening bins is cheaper (more future to fill them)
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 30.0 * (1.0 - progress);
    }

    // Spread load when many bins are open and mean residual is high.
    if open_bins_count > 1 {
        let dev = mean_residual - pr;
        score += 0.1 * dev; // prefer bins with residual below mean (tighter bins)
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals that are too small to fit typical future items
    // (below the minimum item size of 1..100 stream, treat < 10 as pure waste).
    if post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0;
    } else if post_residual < 35 {
        score += 10.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 120.0;
    }

    // Tight fit reward: fraction of bin used by this placement.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 40.0 * fill_ratio;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: when many bins are open, prefer consolidating into
    // existing bins (penalize the new-bin candidate implicitly via residual logic,
    // but add pressure term scaled by number of open bins).
    score += 1.5 * open_bins_count as f64;

    // Prefer bins whose residual is close to the item (minimize waste relative to mean).
    let waste_vs_mean = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * waste_vs_mean;

    // Lookahead: if the next item fits exactly in the post-residual, reward heavily.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 90.0;
        } else if next_item_size <= post_residual {
            // Next item fits but leaves more dead space; mild reward.
            score -= 20.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // Next item cannot use the leftover; penalize proportionally to how
            // close it is (near-miss waste is worst).
            let miss = (next_item_size - post_residual) as f64;
            score += 0.3 * miss;
        }
    }

    // New-bin candidate handling: an empty bin has full residual; make it
    // attractive only when no open bin fits well (handled via last-chance and
    // dead-space terms). Give the fresh bin a mild baseline preference early in
    // the stream when open bins are few.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * (1.0 - progress);
        score += 5.0 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward a perfect fit (no dead space).
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward if the next item exactly fills the new residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 800.0;
        } else if next_item_size <= post_residual {
            // Next item fits here: reward proportionally to how snugly it fits.
            let snug = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
            score -= 200.0 * snug;
        } else {
            // Next item will not fit in the leftover: penalize large unusable leftovers.
            score += 0.5 * (next_item_size - post_residual) as f64;
        }
    }

    // Penalize residuals that are too small to ever hold a typical item again.
    if post_residual > 0 && post_residual < 10 {
        score += 150.0;
    }

    // Compare against mean residual: prefer bins whose post_residual is near the mean
    // (keeps residual distribution balanced), penalize outliers.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.3 * dev;

    // Last-chance bin: if this is the only fitting bin, strongly favor using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 300.0;
    }

    // New-bin candidate: mildly discourage opening a new bin when the stream is early
    // and few bins are open; encourage it late when open bins are fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 120.0 - 100.0 * progress;
        score += 5.0 * open_bins_count as f64;
    }

    // Prefer filling bins that are already mostly full.
    score += 0.2 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits: prefer bins where post_residual is small relative to capacity.
    let tightness = 1.0 - (post_residual as f64) / cap;
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that is too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver
    } else if post_residual >= 10 {
        let usable = post_residual as f64 / cap;
        score += 6.0 * usable; // mild penalty for leftover space
    }

    // Exact fit is ideal.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Lookahead: if the next item can fill this bin's post_residual, strongly favor it.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            let chain = 1.0 - ((post_residual - next_item_size) as f64) / cap;
            score -= 18.0 * chain;
        } else {
            // Next item cannot use the leftover; penalize proportionally to waste.
            score += 8.0 * (post_residual as f64 / cap);
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits, avoiding a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a bin is justified when no open bin fits well.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score = cap * 0.9 + 15.0;
        // Cheaper to open a bin early in the stream (more future use) or when few bins open.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 20.0 * (1.0 - progress);
        score -= 3.0 * (open_bins_count as f64).ln().max(0.0);
        // If the item fits very well nowhere else (many fitting bins = good alternatives exist),
        // make the new bin less attractive.
        if fitting_bins_count > 0 {
            score += 10.0 * (fitting_bins_count as f64).min(6.0);
        }
        // If next item is large and this fresh bin could chain it, slightly favor opening.
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 8.0;
        }
    }

    // Global state coupling: prefer bins whose residual is below mean (consolidating fuller bins).
    let res = bin_residual as f64;
    if res < mean_residual {
        score -= 4.0 * (mean_residual - res) / cap;
    } else {
        score += 4.0 * (res - mean_residual) / cap;
    }

    // Mild preference for bins with large residual when item is large (avoid fragmentation).
    let frac = item_size as f64 / cap;
    if frac > 0.6 && res > frac * cap {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let x = pr / cap; // normalized post residual

    // Base: prefer tight fits (low post_residual), non-linearly penalize both
    // large waste and extremely small unusable slivers.
    let mut score = 40.0 * x * x + 10.0 * x * x * x;

    // Dead-space penalty: residuals too small for the smallest plausible item.
    if pr > 0.0 && pr < 10.0 {
        score += (10.0 - pr as f64) * 3.0;
    }

    // Smooth coupling with stream progress: early on, waste is cheap (bins get
    // filled later); late in the stream, waste is costly, so tighten preference.
    score *= 1.0 + 0.8 * progress * (1.0 - x);

    // Lookahead: reward leaving room for the next item, smoothly.
    let nx = next_item_size as f64;
    if nx > 0.0 {
        let gap = x - nx / cap;
        if gap >= 0.0 {
            score -= 6.0 * gap * (1.0 - gap.abs());
        } else {
            score += 4.0 * (-gap) * (-gap);
        }
    }

    // Scarcity bonus: if this is the only fitting bin, strongly favor using it
    // over opening a new bin (smooth in fitting_bins_count).
    let scarcity = 1.0 / (fitting_bins_count as f64 + 1.0);
    score -= 12.0 * scarcity;

    // Mild load-balancing: prefer bins below the mean residual when many bins open.
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 2.0 * dev * dev * (open_bins_count as f64).ln().max(1.0);

    // New-bin candidate: make empty bins attractive only when the item is large
    // relative to capacity or the fit elsewhere would be poor.
    if bin_residual == bin_capacity {
        score += 8.0 + 6.0 * (1.0 - item_size as f64 / cap) - 10.0 * scarcity;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo classes on capacity fractions
    let pr = post_residual;
    let class = pr % 10; // fine harmonic class
    let big_class = (pr / 25) % 4; // coarse quarter class

    // Reward residuals that are "perfect fit" or exactly reusable by common classes
    if pr == 0 {
        score -= 50.0; // perfect fill
    } else {
        // Penalize dead space depending on harmonic class
        match class {
            0 => score -= 12.0,           // multiples of 10 are reusable
            5 => score -= 6.0,            // half-class
            1 | 3 | 7 | 9 => score += 8.0, // awkward odd classes
            _ => score += 2.0,
        }
        // Coarse class coupling: very small post residuals are near-perfect
        if pr <= 5 {
            score -= 20.0;
        } else if pr <= 10 {
            score -= 10.0;
        } else if pr > 50 {
            score -= 5.0; // large residual still flexible
        }
        // Integer-division threshold: residual in [1,9] wastes capacity potential
        if (pr / 10) == 0 {
            score += 6.0;
        }
    }

    // Lookahead: does next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            let slack = (pr - next_item_size) as f64;
            // Reward if next item fits with small slack (chain packing)
            score -= 15.0 - 0.3 * slack;
            // Harmonic bonus: next_item mod class match
            if next_item_size % 10 == pr % 10 {
                score -= 5.0;
            }
        } else {
            score += 5.0; // next item won't chain here
        }
    } else {
        // Last item: prefer perfect fill strongly
        score -= 10.0;
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate handling: empty bin has residual == capacity
    if bin_residual == bin_capacity {
        // Opening a new bin is costly; penalize unless current bins are nearly full
        score = 60.0 + 0.1 * open_bins_count as f64;
        // If item is small relative to capacity, new bin is wasteful
        if (item_size as f64) / cap < 0.5 {
            score += 20.0;
        }
        // If mean residual is large, prefer existing bins
        if mean_residual > (item_size as f64) * 1.2 {
            score += 15.0;
        }
        // Late in stream, opening bins less attractive
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    }

    // Mild pressure against hoarding many open bins
    score += 0.05 * open_bins_count as f64;

    // Mean residual deviation: prefer bins below mean residual (tighter bins first)
    score += 0.2 * (mean_residual - bin_residual as f64).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small nonzero gaps are the worst outcome.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (1.0 - post_residual as f64 / 10.0);
    }

    // Reward tight fits (small post_residual relative to item).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * tightness;

    // Perfect fit is ideal.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead: if the next item can use the leftover space, reward it.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    }
    // If leftover space is too small for the next item, mildly penalize.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 10.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; with few bins,
    // opening a new one is cheaper.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * (0.4 + 0.6 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportional to open bins and mean residual.
        score += 40.0 + pressure * 3.0 + mean_residual * 0.3;
    } else {
        // Existing bin gets a mild bonus scaled by how full the fleet is.
        score -= pressure * 0.5;
    }

    // Prefer bins whose residual deviates below the mean (consolidating space).
    if bin_residual != bin_capacity {
        score += (bin_residual as f64 - mean_residual).max(-30.0).min(30.0) * 0.4;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual exactly
    // accommodates the next item (perfect chain fit).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0; // perfect two-item fill
        } else if post_residual >= next_item_size {
            let leftover_after_next = post_residual - next_item_size;
            // reward small leftovers after the chain
            score -= 30.0 * (1.0 - leftover_after_next as f64 / bin_capacity as f64);
        } else {
            // next item cannot follow here: penalize proportionally to the gap
            let gap = (next_item_size - post_residual) as f64;
            score += 0.5 * gap;
        }
    } else {
        // last item: prefer minimal post residual (tight fill)
        score += 0.0;
    }

    // Tight-fit bonus relative to current residual (classic best-fit flavor).
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fill_ratio;

    // Penalize post_residual that is small but unusable (dead space).
    if post_residual > 0 {
        let min_item = 1.0;
        if (post_residual as f64) < min_item * 2.0 {
            score += 20.0;
        }
        // dead space penalty: small residual unlikely to fit future items
        if next_item_size > 0 && post_residual < next_item_size {
            score += 0.3 * (next_item_size - post_residual) as f64;
        }
    } else {
        score -= 15.0; // perfect fill of the bin
    }

    // Contextual coupling with mean residual: prefer bins below mean residual
    // (concentrate waste in few bins rather than spreading it).
    if (bin_residual as f64) > mean_residual {
        score += 0.15 * (bin_residual as f64 - mean_residual);
    } else {
        score -= 0.10 * (mean_residual - bin_residual as f64);
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor it
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: empty bin should only win when no open bin
    // offers a decent fit. Penalize it mildly so tight fits in open bins win,
    // but let it win when post_residual in open bins would be very wasteful.
    if bin_residual == bin_capacity {
        score += 12.0;
        if next_item_size > 0 && next_item_size == item_size {
            score -= 8.0; // pair of equal items fills a fresh bin nicely
        }
        // early in the stream, opening bins is cheaper
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 10.0 * (1.0 - progress);
    }

    // Slight preference to keep the number of open bins manageable.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins where the item fills most of the residual.
    let fit_ratio = if bin_residual > 0 { item_size as f64 / bin_residual as f64 } else { 0.0 };
    score -= 3.0 * fit_ratio * fit_ratio * (bin_residual as f64);

    // Lookahead: reward if next item can exactly use the post residual (perfect chain).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // partial chain usefulness, better when waste after both items is small
            let two_step_waste = (post_residual - next_item_size) as f64;
            score -= 12.0 * (1.0 - two_step_waste / cap);
        } else {
            // next item cannot use this residual: penalize large dead space
            score += 0.5 * (post_residual as f64 - mean_residual).abs();
        }
    }

    // Last chance: this is the only bin that fits; avoid opening a new bin unless fit is terrible.
    if fitting_bins_count == 1 && post_residual < bin_residual {
        score -= 40.0 + 0.3 * (item_size as f64);
    }

    // Many open bins with slack: discourage spreading into a fresh-ish bin; encourage consolidation.
    if open_bins_count > 1 {
        score += 0.15 * (open_bins_count as f64).ln() * (post_residual as f64 - mean_residual);
    }

    // Time horizon: early in stream, keep bins flexible (penalize tiny residuals);
    // late in stream, squeeze hard (reward minimal post_residual).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let flexibility = (post_residual as f64 / cap).powf(1.0 + 2.0 * (1.0 - progress));
    score += 20.0 * flexibility * (1.0 - progress);

    // Penalize new empty bin candidate unless no good fit exists among open bins
    // or the item is huge relative to capacity.
    if bin_residual == bin_capacity {
        let open_good = if open_bins_count > 0 { fitting_bins_count as f64 / open_bins_count as f64 } else { 0.0 };
        let pressure = (item_size as f64 / cap) * (1.0 - open_good);
        let time_pressure = progress * progress;
        score += 45.0 - 30.0 * pressure - 25.0 * time_pressure;
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a new bin
        }
    }

    // Mild waste penalty scaled by bin's remaining usefulness for typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0; // unusable sliver dead space
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 1 { step_index as f64 / (total_items - 1) as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;

    // Base: quadratic dead-space penalty, mildly softened by stream progress
    let mut score = norm_post * norm_post * cap * (1.0 - 0.25 * progress);

    // Reward tight fits: subtract proportional to fill ratio achieved
    let fill = (item_size as f64) / cap;
    score -= 12.0 * fill * fill;

    // Lookahead coupling: reward residual that can host the next item smoothly
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let compat = (post - nx).max(0.0) / cap;
        let slack = (post - nx).abs() / cap;
        score -= 8.0 * compat * (1.0 - slack);
        // Penalize residuals that almost-but-don't fit next item (near-miss trap)
        if post < nx && post > 0.0 {
            score += 6.0 * (1.0 - post / nx.max(1.0));
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: penalize opening a new bin, more so early
    // and when decent fitting bins exist; allow it when existing residuals are large
    if bin_residual == bin_capacity {
        let mean_fit = if mean_residual >= item_size as f64 { 1.0 } else { 0.0 };
        let decent_fits = if mean_residual > (item_size as f64) * 0.5 { 1.0 } else { 0.0 };
        score += 20.0 + 10.0 * (1.0 - progress) + 12.0 * decent_fits * mean_fit;
        // If no open bin can fit at all, opening is necessary: cancel penalty
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
    }

    // Smooth interaction: prefer bins whose residual is close to item size (perfect packing)
    let diff = (bin_residual as f64 - item_size as f64) / cap;
    score += 10.0 * diff * diff;

    // Mild diversity pressure via mean residual coupling
    score += 0.05 * (post - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residual modulo capacity classes
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let class_mod = (post_residual % 17) as f64;
    score += class_mod * 0.05;

    // Reward tight fits: post_residual in small dead-space classes
    if post_residual < 10 {
        score -= 25.0;
    } else if post_residual < 20 {
        score -= 10.0;
    }

    // Penalize residuals that no plausible item can use (dead space)
    if post_residual > 0 && post_residual < 10 {
        score += 40.0; // below min item size -> pure waste
    }

    // Integer-division threshold on post_residual: half-capacity fractions
    let half = (bin_capacity / 2) as f64;
    if pr > half {
        score -= 5.0; // bin still roomy, fine
    } else if pr > 0.0 {
        score += (half - pr) * 0.1; // moderately filled bins slightly penalized vs tight
    }

    // Lookahead coupling: if next item fits exactly in post_residual, reward strongly
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 20.0 * (1.0 - slack / cap);
        } else {
            // next item won't fit here; penalize less if post_residual near a harmonic class
            score += 8.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: empty bin gets baseline score
    if bin_residual == bin_capacity {
        // neutral baseline; open new bin only if no open bin scores below this
        score = cap * 0.6;
        if fitting_bins_count == 0 {
            score -= 20.0; // must open a new bin
        }
        // late in stream, prefer closing out open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 5.0;
    }

    // Mean residual coupling: prefer bins below mean residual (more filled)
    score -= (mean_residual - pr) * 0.15;

    // Prefer filling bins when many bins are open (bin consolidation pressure)
    score += open_bins_count as f64 * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for the smallest plausible item are wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 20 {
        // Moderately unusable gap: penalize proportionally to how far below 20 it is.
        score += (20 - post_residual) as f64 * 2.5;
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 40.0;
    }

    // Tightness reward: fraction of residual consumed by this item.
    let tightness = item_size as f64 / bin_residual as f64;
    score -= 25.0 * tightness;

    // Last-chance bin: if this is the only fitting bin, heavily favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: opening a new bin should only win when no open bin
    // offers a decent fit. Penalize the empty-bin candidate mildly, but relax the
    // penalty when all open bins would leave terrible dead space.
    if bin_residual == bin_capacity {
        let mut new_bin_penalty = 45.0 + open_bins_count as f64 * 3.0;
        // If the next item is large, a fresh bin is more attractive.
        new_bin_penalty -= (next_item_size as f64) * 0.25;
        // If progress is late in the stream, prefer reusing bins.
        let progress = step_index as f64 / total_items as f64;
        new_bin_penalty += 20.0 * progress;
        score += new_bin_penalty;
    }

    // Lookahead coupling: reward placing item here if the next item then fits
    // the resulting post_residual well (leaves a usable gap for it).
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Next item fits exactly-ish here: reward leaving a compatible gap.
            let gap_match = 1.0 - ((post_residual - next_item_size) as f64 / bin_capacity as f64);
            score -= 12.0 * gap_match;
        } else if post_residual > 0 && post_residual < next_item_size {
            // Leftover gap is smaller than next item: dead space penalty.
            score += (next_item_size - post_residual) as f64 * 0.6;
        }
    }

    // Open-bins pressure: with many open bins, prefer consolidating into existing ones.
    score += open_bins_count as f64 * 0.8;

    // Mean-residual coupling: if this bin's residual is far below the mean (already tight),
    // prefer it to keep loose bins available for larger future items.
    let dev = mean_residual - bin_residual as f64;
    score -= 0.3 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 100.0; // chain both items perfectly
    }

    // Post-residual too small for the next item: dead space relative to lookahead
    if next_item_size > 0 && post_residual < next_item_size {
        let waste = (next_item_size - post_residual) as f64;
        score += 0.8 * waste;
    }

    // Post-residual leaves room for next item plus margin: mild reward
    if next_item_size > 0 && post_residual > next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 0.3 * slack.min(30.0);
    }

    // Last chance bin: strongly favor using it instead of opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bin fit is bad
    if bin_residual == bin_capacity {
        score += 40.0;
        // But if no open bin fits well, opening is fine
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
    }

    // Prefer bins tighter than the mean residual (best-fit flavor)
    score += 0.2 * ((post_residual as f64) - mean_residual);

    // Late in the stream: consolidate, avoid leaving many scattered bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * progress * (post_residual as f64) / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual near zero is good, dead space is bad.
    let post = post_residual as f64;
    if post_residual == 0 {
        score -= 50.0; // perfect fill
    } else {
        // Nonlinear penalty on unusable dead space (anything < 10 can never be filled
        // under classic 10..80 assumption, but sizes 1..100 possible; still penalize small gaps).
        let dead = if post < 10.0 { 40.0 } else { 0.0 };
        score += dead + (post / 100.0).powf(2.0) * 20.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, strongly favor this bin.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 - (slack / 100.0) * 10.0; // exact follow-up fit best
        } else {
            score += 3.0; // next item can't follow here
        }
        // If next item is huge and this bin would be left with a gap smaller than it,
        // slightly prefer using this bin now to consolidate space.
        if nxt > post && nxt > 50.0 && post < nxt {
            score -= 2.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: an empty bin should only win when no open bin is decent.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin; decreases late in stream (less future to amortize)
        // and when many bins are already open (consolidation less valuable).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let mut new_bin_cost = 30.0 - 10.0 * progress - (open_bins_count as f64).min(20.0) * 0.5;
        if new_bin_cost < 5.0 { new_bin_cost = 5.0; }
        score += new_bin_cost;
    } else {
        // Slight preference for bins whose residual deviates below mean (tighter bins first).
        let dev = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
        score += dev * 5.0;
    }

    // Early in stream: keep bins balanced so future items have varied residuals.
    if total_items > 0 && (step_index as f64 / total_items as f64) < 0.2 {
        let imbalance = (bin_residual as f64 - mean_residual).abs();
        score += imbalance * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_ratio = item_size as f64 / cap;
    let next_ratio = next_item_size as f64 / cap;
    let pr_norm = pr / cap;
    let mean_norm = mean_residual / cap;

    // Smooth polynomial base: penalize wasted residual quadratically
    let mut score = pr_norm * pr_norm * cap * 0.5 + pr_norm * 2.0;

    // Non-linear coupling of post_residual with stream progress:
    // early on, tolerate slack; late, punish it more strongly
    let progress_coupling = pr_norm * (0.5 + 2.5 * progress * progress);
    score += progress_coupling * cap * 0.3;

    // Smooth interaction: reward tight fits (small pr) especially when
    // the next item could use the residual
    let next_coupling = (pr_norm - next_ratio).abs();
    score -= (1.0 - next_coupling).max(0.0) * (1.0 + progress) * 3.0;

    // Reward bins whose residual matches the item size well (tight packing)
    let tightness = 1.0 - fit_ratio;
    score += tightness * tightness * 2.0;

    // Last-chance bonus: strongly favor the only bin that fits
    if fitting_bins_count == 1 {
        score -= 6.0 + 4.0 * progress;
    }

    // Mild penalty for spreading across many open bins when residuals are high
    let spread = (mean_norm - pr_norm).abs();
    score += spread * spread * (open_bins_count as f64).ln().max(1.0) * 0.5;

    // New-bin candidate: make it moderately attractive only when no open bin
    // fits well (post_residual large relative to capacity)
    if bin_residual == bin_capacity {
        score = cap * 0.35 + pr_norm * cap * 0.2 - fit_ratio * 5.0 + progress * 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the item: quantize item into capacity fractions
    let item_class = (item_size * 4) / bin_capacity; // 0..3 coarse class
    let post_class = (post_residual * 4) / bin_capacity;

    // Reward tight fits: post_residual small relative to item class
    let tight_fit = if post_residual <= bin_capacity / 8 {
        -30.0
    } else if post_residual <= bin_capacity / 4 {
        -12.0
    } else {
        0.0
    };
    score += tight_fit;

    // Penalize post_residual that falls into a "dead zone": too small for any
    // plausible future item (items >= 10 in classic case, >= 1 in general).
    let min_item = 1u32;
    if post_residual < min_item {
        score += 50.0; // perfectly packed, but avoid overflow weirdness
    } else if post_residual < 10 {
        // dead space: unusable for typical items
        score += 25.0;
    } else {
        // harmonic coupling: post_residual vs next item size modulo classes
        if next_item_size > 0 {
            let next_class = (next_item_size * 4) / bin_capacity;
            if next_class == post_class {
                score -= 8.0; // next item likely fits this residual class
            } else if post_residual >= next_item_size {
                score -= 4.0;
            } else {
                score += (next_item_size - post_residual.min(next_item_size)) as f64 * 0.5;
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Prefer bins with below-average residual (keep large residuals for big items)
    let drift = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    score += drift * 10.0;

    // New-bin candidate handling: only prefer fresh bin when all open bins fit poorly
    if bin_residual == bin_capacity {
        let open_pressure = open_bins_count as f64;
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Base penalty so new bins are used only when needed
        score += 20.0 + open_pressure * 0.5;
        // Early in stream, allow new bins more readily if item is large
        if item_class >= 2 {
            score -= 10.0 * (1.0 - progress);
        }
        if next_item_size > 0 && next_item_size >= bin_residual - item_size {
            // next item is big; fresh bin keeps flexibility
            score -= 6.0;
        }
    }

    // Integer-division threshold on post_residual: reward residuals that are
    // "friendly" multiples (likely to be exactly filled later)
    if post_residual > 0 && bin_capacity % post_residual == 0 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are the worst outcome.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64);
    }
    // Perfect fits strongly rewarded.
    if post_residual == 0 {
        score -= 80.0;
    }

    // Tight fit bonus: fill most of the bin.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 25.0 * fill_ratio;

    // If lookahead item can use the post_residual, reward this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 20.0;
        // Extra reward if lookahead fits almost exactly.
        let gap = post_residual as f64 - next_item_size as f64;
        if gap < 10.0 {
            score -= 15.0 * (10.0 - gap);
        }
    }
    // Penalize creating a gap just below the minimum item size (1 here) is moot,
    // but penalize gaps that no typical small item can exploit relative to mean residual.
    if post_residual > 0 {
        let usable = (post_residual as f64 / mean_residual.max(1.0)).min(1.0);
        score += 10.0 * (1.0 - usable);
    }

    // Open-bin pressure: discourage scattering across many bins unless fit is tight.
    score += 3.0 * open_bins_count as f64 * (1.0 - fill_ratio);

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate: only attractive when no open bin offers a decent fit
    // (handled implicitly by fitting_bins_count == 1 bonus above); otherwise penalize.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 1 {
            score += 40.0;
        }
        score += 5.0 * open_bins_count as f64;
    }

    // Slight early-stream bias to consolidate into few bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
