pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through the stream: later on, prefer consolidating into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += progress * 12.0;

    // Lookahead: if the next item fits exactly into the post-residual, strongly reward this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit here anyway; slight penalty if this placement wastes a lot.
            score += (post_residual as f64 - 0.0).min(10.0) * 0.3;
        }
    }

    // Reward tight fits (small post-residual relative to item size).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * tightness;

    // Penalize creating dead space that nothing (min size 1..100) can use well:
    // residuals below the smallest plausible item are pure waste.
    if post_residual < 10 && post_residual > 0 {
        score += 15.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Many open bins: discourage spreading; favor filling the emptiest-feeling fit.
    let crowding = open_bins_count as f64;
    score += (post_residual as f64 - mean_residual) * 0.25 * (1.0 + crowding / 50.0);

    // New-bin candidate handling: opening a new bin is only attractive when no open bin
    // fits well, or when the item is large and would leave awkward residue elsewhere.
    if bin_residual == bin_capacity {
        let good_alternative_exists = fitting_bins_count > 0
            && mean_residual >= item_size as f64 + 5.0;
        if good_alternative_exists {
            score += 45.0; // prefer placing into an existing bin
        } else {
            score -= 10.0; // allow opening a new bin
        }
        // Late in the stream, opening bins is less costly per-item; early on, avoid it.
        score += (1.0 - progress) * 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Smooth non-linear polynomial coupling of post_residual with stream progress.
    // Early on: prefer tight fits mildly; late: penalize residual more strongly.
    let poly = norm_pr * norm_pr * (1.0 + 3.0 * progress);
    score += poly * cap * 0.6;

    // Reward near-perfect fits (low post residual) progressively harder as stream advances.
    score -= (1.0 - norm_pr) * (1.0 - norm_pr) * (10.0 + 40.0 * progress);

    // Dead-space penalty: residual too small for the smallest plausible item is wasted.
    if pr > 0 && pr < 10 {
        score += 25.0 * (1.0 - pr as f64 / 10.0);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 30.0;
    } else if next_item_size > post_residual as u32 && post_residual > 0 {
        // Residual can't host next item: mild penalty growing with progress.
        score += 5.0 * (0.5 + progress);
    }

    // Prefer bins with below-average residual (keep big holes for big future items).
    score += 0.3 * (mean_residual - bin_residual as f64).max(0.0);

    // New-bin candidate: discourage unless no good fit exists (post residual large or many bins).
    if bin_residual == bin_capacity {
        score += 20.0 + 10.0 * progress - 5.0 * (open_bins_count as f64).min(10.0);
        if fitting_bins_count <= 1 {
            score -= 25.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify dead space by residue classes
    let pr = post_residual;
    let cls = match pr {
        0 => 0.0,                    // perfect fit
        1..=5 => 1.0,                // near-perfect
        6..=15 => 2.0,
        16..=30 => 3.0,
        _ => 4.0,                    // large usable residual
    };
    score += cls * 3.0;

    // Modulo arithmetic on post_residual: residues that pair well with common item sizes
    let m = pr % 10;
    score -= (m == 0) as i32 as f64 * 6.0;      // round residual is reusable
    score += (m >= 8 && m <= 9) as i32 as f64 * 2.0; // awkward residue

    // Integer division thresholds: can post_residual hold half / quarter of next item?
    if next_item_size > 0 {
        let nxt = next_item_size;
        if pr >= nxt {
            score -= 8.0; // next item fits here too: strong reward
            // harmonic bonus: exact division
            if pr % nxt == 0 { score -= 5.0; }
            if nxt % 2 == 0 && pr >= nxt * 2 { score -= 3.0; }
        } else if pr >= nxt / 2 {
            score += 1.0; // partial future usability
        } else {
            score += 4.0; // dead space relative to lookahead
        }
        // modulo coupling between item class and next item class
        let im = item_size % 10;
        let nm = nxt % 10;
        if im + nm <= 10 && pr >= nxt { score -= 2.0; }
    } else {
        // last item: prioritize tight fit only
        score = post_residual as f64 * 2.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a bin
    if fitting_bins_count == 1 {
        score -= 12.0;
    } else if fitting_bins_count > 1 {
        // competition: prefer bins where fit is tighter relative to others
        score += (fitting_bins_count as f64 - 1.0) * 0.5;
    }

    // New-bin candidate handling
    if bin_residual == bin_capacity {
        // base cost of a fresh bin: slightly above a mediocre residual
        let mut new_score = cap * 0.55;
        // prefer new bins early in stream or when open bins are fragmented
        let progress = step_index as f64 / (total_items.max(1) as f64);
        new_score -= progress * 5.0;
        new_score += (open_bins_count as f64) * 0.3;
        if mean_residual < item_size as f64 {
            new_score -= 4.0; // existing bins are fragmented; fresh start good
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            new_score -= 3.0;
        }
        return new_score;
    }

    // Reward tightness relative to bin capacity fractions
    let fill = (bin_capacity - post_residual) as f64 / cap;
    if fill > 0.9 { score -= 6.0; }
    else if fill > 0.75 { score -= 3.0; }
    else if fill < 0.25 { score += 2.0; }

    // Penalize bins far from mean residual (outliers are poor partners)
    score += ((post_residual as f64 - mean_residual).abs()) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps heavily.
    if post_residual > 0 {
        // Assume next items are at least ~10 units; gaps below that are dead space.
        let dead_threshold = 10.0f64;
        if (post_residual as f64) < dead_threshold {
            score += 60.0 * (dead_threshold - post_residual as f64);
        }
        // Non-linear penalty: small residuals are disproportionately wasteful.
        let frac = post_residual as f64 / bin_capacity as f64;
        score += 40.0 * frac * frac;
    } else {
        // Perfect fit is highly rewarded.
        score -= 80.0;
    }

    // Tight-fit reward: item fills most of the bin.
    let fill = item_size as f64 / bin_residual.max(1) as f64;
    if fill > 0.8 {
        score -= 30.0 * (fill - 0.8);
    }

    // Lookahead coupling: if the next item fits exactly in post_residual, reward strongly.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 70.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 10.0;
    } else if next_item_size > post_residual {
        // Next item won't fit here; slight penalty if this creates a stranded gap.
        score += 8.0;
    }

    // Open-bin pressure: discourage spreading across many bins unless fit is good.
    score += 0.35 * open_bins_count as f64;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when current bins fit poorly.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, reduced by stream progression pressure.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = 55.0 + 30.0 * (1.0 - progress) - 0.2 * mean_residual;
        // If no open bin fits well, opening new is fine.
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
        // If next item is large, a fresh bin is valuable.
        if next_item_size > item_size {
            score -= 12.0;
        }
    }

    // Mean residual alignment: prefer bins whose residual is near the mean (balanced packing),
    // but slightly favor below-mean residuals (tighter bins).
    score += 0.15 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact or near-exact fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // Aggressive 2-step lookahead: if the next item fits in the post residual,
    // reward this bin heavily (chained packing).
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack_after_pair = post_residual - next_item_size;
        score -= 50.0 + slack_after_pair as f64 * 0.5;
        // Extra bonus if the pair nearly fills the bin.
        if slack_after_pair <= 5 {
            score -= 150.0;
        }
    } else if next_item_size > 0 && post_residual > 0 {
        // Penalize leaving dead space the next item cannot use,
        // scaled by how close post_residual is to next_item_size.
        let gap = next_item_size as f64 - post_residual as f64;
        if gap < 10.0 {
            score += 30.0 + gap * 2.0;
        }
    }

    // Compare residual against mean residual across open bins:
    // favor bins with less residual (tighter bins) to consolidate packing.
    let res = post_residual as f64;
    if mean_residual > 0.0 {
        score += (mean_residual - res) * 0.3;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: penalize opening a new bin mildly, more so early in the
    // stream and when many bins are open with usable residual.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 40.0 + 60.0 * (1.0 - progress) + open_bins_count as f64 * 2.0;
        // If next item is large, a fresh bin is more attractive.
        if next_item_size > 0 && next_item_size > item_size {
            score -= 20.0;
        }
    }

    // Mild preference for bins whose residual is small relative to capacity.
    score += res * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward perfect or near-perfect fills.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 50.0;
    }

    // Reward tight fits relative to item size.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 30.0 * fit_ratio;

    // Lookahead: if the next item can fit into the post residual, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
        // Extra reward if next item nearly fills the leftover space.
        let next_fit = next_item_size as f64 / post_residual as f64;
        score -= 20.0 * next_fit;
    }
    // Penalize leaving a gap that is too small for the next item (dead space).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 10.0 + 0.5 * post_residual as f64;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // Penalize opening a new bin when good alternatives exist, unless many bins
    // are open and residuals are fragmented (better to start fresh).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = mean_residual / bin_capacity as f64;
        // New bin penalty shrinks as fragmentation grows.
        let penalty = 80.0 * (1.0 - 0.8 * fragmentation) * (1.0 - 0.3 * progress);
        score += penalty;
        // If the item fits poorly everywhere else, new bin becomes attractive:
        // poor fit means large post_residual, already captured in base score.
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
    }

    // Mild penalty for wasting large residual capacity on a small item.
    let waste = bin_residual as f64 - item_size as f64;
    score += 0.1 * waste * waste / bin_capacity as f64;

    // Slight preference for filling bins with larger mean residual (consolidation).
    if bin_residual < bin_capacity {
        score += 0.05 * (mean_residual - bin_residual as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let resid = bin_residual as f64;
    let item = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post;

    // Non-linear waste penalty: quadratic in post_residual normalized by capacity
    let post_norm = post / cap;
    score += 12.0 * post_norm * post_norm * cap * 0.1;

    // Tight fits rewarded: smooth cubic decay of bonus as post grows
    let tight = (1.0 - post_norm).max(0.0);
    score -= 8.0 * tight * tight * tight;

    // Lookahead coupling: penalize leaving residual that cannot help the next item,
    // reward residual that matches next item smoothly
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            let match_quality = 1.0 - ((post - nxt) / cap);
            score -= 6.0 * match_quality * match_quality;
        } else {
            let gap = (nxt - post) / cap;
            score += 10.0 * gap * gap * cap * 0.05;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * progress;
    }

    // Stream progress: later in stream, be more frugal with new space (smooth coupling)
    score += progress * post * 0.15;

    // Mean residual interaction: if this bin is far from mean residual, mild penalty (smooth)
    let dev = (resid - mean_residual) / cap;
    score += 4.0 * dev * dev;

    // New-bin candidate: penalize unless existing bins are badly fragmented
    let is_new_bin = (bin_residual as u32 == bin_capacity) && item_size <= bin_residual;
    if is_new_bin {
        let fragmentation = if open_bins_count > 0 { mean_residual / cap } else { 0.0 };
        score += 25.0 - 20.0 * fragmentation * fragmentation;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into a
    // "reusable" residue class (small, or large enough for typical items)
    // are preferred; awkward mid-range leftovers are penalized.
    let pr = post_residual;
    let pr_mod = (pr % 10) as f64;
    if pr == 0 {
        score -= 60.0; // perfect fill
    } else if pr < 10 {
        score -= 25.0; // negligible waste
    } else if pr >= 40 {
        score -= 10.0 + pr_mod; // large residual still highly reusable
    } else {
        // awkward 10..40 zone: penalize, more if residue is not round
        score += 12.0 + (10.0 - pr_mod);
    }

    // Lookahead coupling: reward residual that exactly fits the next item,
    // penalize residuals that just barely fail to fit it.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (pr as f64) >= nxt {
            let slack = pr as f64 - nxt;
            if slack < 10.0 {
                score -= 30.0 - slack; // near-perfect lookahead match
            } else {
                score -= 5.0;
            }
        } else {
            score += (nxt - pr as f64) * 0.5; // next item won't fit here
        }
    } else {
        // last item: prefer tightest fit strongly
        score -= 40.0;
    }

    // Last-chance bin: strongly favor using the only bin that fits,
    // avoiding a new bin opening.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: neutral-ish baseline, but discourage opening a new
    // bin when many bins fit the item or mean residual is still large.
    if bin_residual == bin_capacity {
        score += 45.0;
        score -= 0.3 * mean_residual.min(cap);
        if fitting_bins_count == 0 {
            score -= 80.0; // no alternative: must open new bin
        }
        if fitting_bins_count == 1 {
            score += 20.0; // only one fit: opening new bin is risky
        }
    }

    // Stream progression: early on, prefer packing into existing bins to
    // keep bin count low; late in stream, allow tighter greedy fills.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * (1.0 - progress);

    // Mild pressure to consolidate when many bins are open.
    score += 0.05 * open_bins_count as f64;

    // Deviation from mean residual: prefer bins whose residual is typical
    // (keeps the bin portfolio balanced) unless it's a near-perfect fit.
    if pr >= 10 {
        score += 0.1 * ((pr as f64) - mean_residual).abs();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead space avoidance: heavily penalize small unusable gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }
    // Penalize residuals that cannot fit even the smallest item (1..10).
    if post_residual > 0 {
        let dead = if post_residual < 10 { 1.0 } else { 0.0 };
        score += dead * (10.0 - post_residual as f64) * 3.0;
    }

    // Reward tight fits (waste-minimizing placements).
    let tightness = item_size as f64 / bin_residual as f64;
    score -= 12.0 * tightness;

    // Open bins pressure: discourage spreading when many bins are open.
    score += 0.6 * open_bins_count as f64;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 18.0;
    }

    // Lookahead: if next item fits the post-residual, reward this placement.
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 8.0;
    }
    // If next item would leave another dead gap, penalize.
    if next_item_size > 0 && post_residual >= next_item_size && (post_residual - next_item_size) < 10 && (post_residual - next_item_size) > 0 {
        score += 6.0;
    }

    // Mean residual coupling: prefer bins below mean residual (tighter bins).
    score += 0.15 * (mean_residual - bin_residual as f64);

    // New-bin candidate: opening a new bin is penalized mildly, but allowed
    // when no open bin offers a decent fit (handled via fitting_bins_count).
    if bin_residual == bin_capacity {
        score += 10.0;
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
    }

    // Stream progression: early on, be pickier about dead space.
    let progress = step_index as f64 / total_items as f64;
    score -= 4.0 * (1.0 - progress) * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near match: next item fits snugly in the post-residual
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 30.0 * (1.0 - slack / bin_capacity as f64);
    }
    // Next item would NOT fit here: residual is dead space unless tiny
    if next_item_size > 0 && next_item_size > post_residual {
        score += 15.0;
    }

    // Favor bins tighter than the mean residual (good packing so far)
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a new bin when decent open bins exist
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 + 10.0 * progress;
        if fitting_bins_count > 0 && post_residual > 0 {
            score += 10.0;
        }
    }

    // Small bonus for very tight fits (wasted space < 10)
    if post_residual < 10 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // Mild pressure to consolidate as bins accumulate
    score += 0.3 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post_residual relative to capacity).
    let tightness = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - tightness).powi(6) * 40.0;

    // Penalize dead space that is too small for typical items (waste pockets).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual >= 10 && post_residual < 25 {
        score += 8.0;
    }

    // Lookahead: reward bins where the next item also fits in the post residual.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 + 0.1 * next_item_size as f64;
    } else if next_item_size > 0 {
        // Mild penalty if next item cannot follow into this bin.
        score += 4.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Time horizon: early in the stream, prefer compacting into few bins;
    // later, be slightly more open to spreading load.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 5.0 * (open_bins_count as f64).sqrt().recip();

    // Prefer bins with residuals close to the item (minimize fragmentation).
    let gap = (bin_residual as f64 - item_size as f64).abs();
    score += gap * 0.15;

    // Penalize bins far from the mean residual (keeps bin population homogeneous).
    score += (bin_residual as f64 - mean_residual).abs() * 0.2;

    // New-bin candidate: only attractive when item leaves a well-usable residual
    // or no open bin is a good fit.
    if bin_residual == bin_capacity {
        if post_residual >= 30 {
            score -= 10.0;
        } else if fitting_bins_count == 0 {
            score -= 5.0;
        } else {
            score += 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Non-linear waste penalty: quadratic in wasted fraction, amplified as stream progresses.
    let waste_frac = post_residual as f64 / cap;
    score += 30.0 * waste_frac * waste_frac * (0.5 + progress);

    // Tight-fit reward: polynomial coupling of post_residual with progress.
    let tightness = 1.0 - (post_residual as f64 / cap);
    score -= 10.0 * tightness * tightness * (1.0 - 0.5 * progress);

    // Last-chance bin: strongly reward using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0 * (1.0 + progress);
    }

    // New-bin candidate: penalize opening bins, more so early when consolidation matters.
    if bin_residual == bin_capacity {
        let scarcity = (open_bins_count as f64 + 1.0).ln();
        score += 8.0 + 4.0 * scarcity * (1.0 - progress);
        // But if the next item would fit nicely in the fresh bin, soften the penalty.
        if next_item_size > 0 && (next_item_size as f64) >= 0.5 * cap {
            score -= 5.0;
        }
    }

    // Lookahead coupling: reward leaving room shaped for the next item.
    if next_item_size > 0 {
        let gap = (post_residual as f64 - next_item_size as f64).abs();
        let fit_next = 1.0 - gap / cap;
        score -= 6.0 * fit_next * fit_next;
    }

    // Mild attraction toward bins whose residual deviates from the mean (diversity of sizes).
    let dev = (bin_residual as f64 - mean_residual).abs() / cap;
    score += 2.0 * dev * dev * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residuals that belong to "useful"
    // small-capacity classes (multiples of small integers), penalize primes/odd dead space.
    let pr = post_residual;
    if pr == 0 {
        score -= 1000.0; // perfect fit, always take it
    } else {
        // Harmonic divisibility reward: residual divisible by small d is reusable
        let mut harmonic_bonus = 0.0;
        for d in [2u32, 4, 5, 10, 20, 25, 50] {
            if pr % d == 0 {
                harmonic_bonus += 8.0 + 50.0 / d as f64;
            }
        }
        score -= harmonic_bonus;

        // Penalize residual in awkward band: too small for typical items (1..100 unknown,
        // but assume mid-range items ~25+): residual < 20 is near-dead space
        if pr < 20 {
            score += (20 - pr) as f64 * 3.0;
        }

        // Coupling with next item: if next item fits exactly in post_residual, big reward
        if next_item_size > 0 {
            if next_item_size == pr {
                score -= 400.0;
            } else if next_item_size <= pr {
                // next fits: reward closeness of fit
                score -= 60.0 * (1.0 - (pr - next_item_size) as f64 / pr as f64);
                // harmonic check: does next item leave a harmonic residual again?
                let pr2 = pr - next_item_size;
                if pr2 % 10 == 0 || pr2 % 25 == 0 {
                    score -= 30.0;
                }
            } else {
                // next item won't fit here: mild penalty scaled by how much it overflows
                score += ((next_item_size - pr) as f64) * 0.5;
            }
        }

        // Last-chance bin: strongly favor using it to avoid opening a new bin
        if fitting_bins_count == 1 && bin_residual != bin_capacity {
            score -= 250.0;
        }

        // New-bin candidate handling: only prefer a fresh bin when this bin's fit is bad
        if bin_residual == bin_capacity {
            // fresh bin baseline: slight penalty so existing bins with decent fit win,
            // but reward when item is large (poor fit anywhere) or few fitting bins
            score += 40.0;
            if item_size >= 50 {
                score -= 30.0;
            }
            if fitting_bins_count <= 1 {
                score -= 60.0;
            }
        }

        // Fraction-of-capacity phase: reward bins whose fill level crosses capacity quarters
        let fill = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
        let q = (fill * 4.0).floor();
        score -= q * 6.0;

        // Spread control: avoid piling into bins far from mean residual early on
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += dev * 0.15 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold
    // even the smallest plausible item are pure waste; punish them hard.
    let min_item = 1.0f64;
    if post_residual > 0 && (post_residual as f64) < min_item {
        score += 1000.0;
    }

    // Non-linear dead-space penalty: residual gaps in the "unusable band"
    // (small relative to capacity) are penalized super-linearly.
    let pr = post_residual as f64;
    let frac = pr / cap;
    if frac > 0.0 && frac < 0.2 {
        score += 60.0 * (0.2 - frac) * (0.2 - frac) * cap;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 80.0;
    }

    // Tight fit bonus: reward leaving a gap that next_item_size can exactly use.
    if next_item_size > 0 && post_residual > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let slack = pr - nxt;
            if slack == 0.0 {
                score -= 40.0; // lookahead perfect fit
            } else if (slack / cap) < 0.1 {
                score -= 15.0; // near-perfect lookahead fit
            } else {
                score += 5.0; // loose lookahead fit slightly discouraged
            }
        } else {
            // next item cannot use this residual at all: dead space likely
            score += 20.0 * (nxt - pr) / cap;
        }
    }

    // Open-bins pressure: with many open bins, prefer packing into existing
    // ones (especially this one) rather than spreading; new-bin candidate
    // (full residual) gets penalized when many bins are already open.
    let pressure = open_bins_count as f64;
    if bin_residual == bin_capacity {
        score += 25.0 + 8.0 * pressure.sqrt();
    } else {
        score -= 3.0 * pressure.sqrt();
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // Mean-residual coupling: if this bin's residual is far below the mean,
    // it is a "cramped" bin — using it consolidates waste; slightly reward.
    let dev = (bin_residual as f64) - mean_residual;
    score -= 0.3 * dev;

    // Slight late-stream tightening: as the stream progresses, be greedier
    // about filling existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for exact fits (post_residual == 0)
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 10 {
        score -= 200.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let post = post_residual as f64;
        let diff = (post - nxt).abs();
        // Perfect match for next item: heavily reward
        if diff == 0.0 {
            score -= 500.0;
        } else if diff <= 10.0 {
            score -= 150.0 * (1.0 - diff / 10.0);
        } else {
            // Penalize leaving residual that neither fits next item nor is small
            score += diff * 0.5;
        }
        // If next item cannot fit anywhere else after this placement, prefer leaving room
        if nxt > post_residual && post_residual > 0 {
            score += 50.0;
        }
    }

    // Compare post_residual relative to mean residual across open bins
    if post_residual as f64 > mean_residual {
        score += (post_residual as f64 - mean_residual) * 0.3;
    } else {
        score -= (mean_residual - post_residual as f64) * 0.3;
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 300.0;
    }

    // Penalize creating large dead space (> 20) that likely becomes unusable
    if post_residual > 20 && post_residual < 10 {
        // unreachable guard (kept for clarity)
    }
    if post_residual >= 21 && post_residual <= 40 {
        score += 20.0;
    }

    // New-bin candidate: only attractive when few open bins or late in stream
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let pressure = open_bins_count as f64;
        score += 250.0 - 100.0 * progress - 5.0 * pressure;
        // If next item is large, fresh bin is useful
        if next_item_size >= 50 {
            score -= 80.0;
        }
        // If existing bins fit poorly (many fitting bins means good alternatives exist)
        if fitting_bins_count > 2 {
            score += 100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post residual).
    score += (post_residual as f64).powi(2) / (bin_capacity as f64);

    // Reward placements where the lookahead item also fits into the post residual.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 8.0 + 0.25 * next_item_size as f64;
    }
    // Penalize if next item almost fits but not quite (dead-space risk).
    if next_item_size > post_residual && post_residual > 0 && next_item_size > 0 {
        score += 0.1 * (next_item_size as f64 - post_residual as f64);
    }

    // Last-chance bonus: if this is the only bin that can fit the item, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a new bin should only win when fit elsewhere is bad.
    if bin_residual == bin_capacity {
        // Penalize new bins more when many bins are open (consolidation pressure),
        // and when the mean residual is large (existing space is plentiful).
        score += 30.0 + 2.0 * open_bins_count as f64 + 0.5 * mean_residual;
        // Early in the stream, new bins are cheaper to open.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 15.0 * (1.0 - progress);
        // If the item perfectly fills a fresh bin, opening is fine.
        if item_size == bin_capacity {
            score -= 200.0;
        }
    } else {
        // Reward using bins that are already fairly full.
        let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
        score -= 10.0 * fill_ratio;
        // Slight preference for bins below the mean residual (balancing).
        score += 0.05 * (bin_residual as f64 - mean_residual).abs();
    }

    // Penalize very small unusable post residuals slightly less than mid-range gaps
    // (small gaps may still combine with tiny items).
    if post_residual > 0 && post_residual < 10 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Smooth non-linear coupling: reward tight fits via cubic shaping of post_residual.
    let prn = pr / cap;
    let tightness = (1.0 - prn).powi(3);
    score -= 12.0 * tightness;

    // Stream-progress interaction: later in the stream, favor filling bins more aggressively.
    score -= 8.0 * tightness * progress;

    // Penalize residuals that are too small to be useful (dead space), smoothly.
    let dead = (-(prn - 0.15) / 0.15).max(0.0).min(1.0);
    score += 6.0 * dead * dead;

    // Lookahead coupling: reward leaving residual close to next item size (smooth gaussian).
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let d = (pr - nx) / cap;
        score -= 10.0 * (-d * d * 40.0).exp();
    }

    // Last-chance bin: strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Mild penalty for proliferating bins relative to mean residual.
    score += 0.05 * (open_bins_count as f64 - mean_residual / 10.0).abs();

    // New-bin candidate: make it slightly unattractive unless post_residual is large.
    if bin_residual == bin_capacity {
        score += 3.0 - 2.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: mod-10 buckets (items are 1..100).
    let pr = post_residual;
    let class = pr % 10;
    // Reward residuals that are "harmonically useful": multiples of 10, 20, 25, 50.
    if pr > 0 {
        if pr % 50 == 0 { score -= 12.0; }
        else if pr % 25 == 0 { score -= 8.0; }
        else if pr % 20 == 0 { score -= 6.0; }
        else if pr % 10 == 0 { score -= 4.0; }
        else if class <= 2 { score -= 2.0; } // near-multiple: tiny dead space
        else if class >= 8 { score += 3.0; } // just below a multiple: bad fit zone
        else { score += 1.5; }
    } else {
        // Perfect fill is ideal.
        score -= 40.0;
    }

    // Dead-space penalty: residual that no future item (>=1) can pair into usefully.
    // Small residuals (<10) are essentially dead; penalize strongly.
    if pr > 0 && pr < 10 {
        score += 8.0 + (10 - pr) as f64;
    }

    // Integer-division threshold coupling with next item (lookahead k=2).
    if next_item_size > 0 {
        if next_item_size <= pr {
            // Next item fits here: strong reward, scaled by how snugly.
            let slack = (pr - next_item_size) as f64;
            score -= 10.0 - 0.1 * slack;
            // Harmonic bonus if combined fill is near-capacity multiples.
            let combined = item_size + next_item_size;
            if combined % 25 == 0 || combined % 50 == 0 { score -= 5.0; }
        } else {
            // Next item won't fit here: mild penalty if this bin's leftover is awkward.
            if pr > 0 && next_item_size > pr && pr < next_item_size {
                score += 2.0;
            }
        }
    } else {
        // Last item: just minimize waste.
        score -= 5.0;
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new one
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 7.0;
    }

    // New-bin candidate handling: an empty bin has huge residual; make it
    // unattractive unless all open fits would create large dead space.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin grows with stream progress and open bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = bin_capacity as f64 + 15.0 * progress + 0.5 * open_bins_count as f64;
        // If item is large relative to capacity, new bin is fine (near-perfect start).
        if item_size >= 80 { score -= 10.0; }
        if fitting_bins_count == 0 { score -= 25.0; }
    }

    // Mild preference for bins tighter than average (best-fit flavor).
    score += 0.05 * (mean_residual - bin_residual as f64);

    // Slight bonus for fuller bins (smaller residual) to consolidate.
    score += 0.02 * bin_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 12.0;
    }
    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Coupling: penalize dead space more when few bins can fit the item
    // (wasting the last chance bin is costly).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive when no open bin fits well
    // or open-bin pressure is high.
    if bin_residual == bin_capacity {
        let pressure = open_bins_count as f64 / 8.0;
        score = 100.0 + pressure * 10.0;
        // If the next item could use this fresh bin fully, slightly favor it.
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 5.0;
        }
        // Opening a bin when a perfect fit exists elsewhere is bad.
        if post_residual == bin_capacity - item_size && item_size > bin_capacity / 2 {
            score += 15.0;
        }
    }

    // Mild open-bins pressure: prefer filling existing bins when many are open.
    score += open_bins_count as f64 * 0.8;

    // Reward bins whose residual is close to the mean (balanced packing),
    // penalize outliers creating fragmented space.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    // Lookahead: if next item fits exactly into the post residual, reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 40.0;
    }
    // Penalize leaving a gap the next item almost fits but wastes.
    if next_item_size > post_residual && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 0.3;
    }

    // Early stream: be slightly conservative about opening bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity && progress < 0.2 {
        score += 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next item well
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let post = post_residual as f64;
        if next <= post {
            // Next item fits after this placement: strong reward proportional to tightness
            let slack_after_pair = post - next;
            score -= 25.0 * (1.0 - slack_after_pair / bin_capacity as f64);
        } else {
            // Next item won't fit: penalize proportionally to the gap
            score += 0.15 * (next - post);
        }
    }

    // Relative residual coupling: prefer bins whose residual deviates favorably from mean
    let post_f = post_residual as f64;
    let mean = if mean_residual.is_finite() { mean_residual } else { post_f };
    score += 0.3 * (post_f - mean);

    // Tight fit reward: small post_residual is good
    score += 0.5 * (post_f / bin_capacity as f64);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Penalize opening new bins when decent fits exist
    if bin_residual == bin_capacity {
        score += 20.0 + 0.1 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size as f64 <= mean {
            score -= 10.0; // new bin still fine if mean residual is small
        }
    }

    // Late-stream consolidation: favor filling existing bins more aggressively
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.2 * progress * (post_f / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly (non-linear).
    let tight = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score -= 18.0 * (-tight * 9.0).exp();

    // Penalize dead space that is too small for typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if the next item fits in the post residual, reward this bin.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
            // extra reward for a chain fit (item + next exactly fills)
            if post_residual == next_item_size {
                score -= 10.0;
            }
        } else {
            // next item cannot follow here; slight penalty proportional to gap
            score += 3.0 * ((post_residual as f64 - next_item_size as f64) / bin_capacity as f64).max(0.0);
        }
    }

    // Scarcity: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0);
    }

    // New-bin candidate logic: opening a new bin is attractive only when
    // the current bin would leave large awkward residual relative to mean.
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin, discounted when open bins are fragmented
        // or the fit in existing bins is poor.
        score = 45.0 + mean_residual * 0.15;
        if fitting_bins_count == 0 {
            score -= 60.0; // nothing fits anyway; new bin necessary
        }
        if next_item_size > 0 && next_item_size > bin_capacity - item_size {
            score += 8.0; // lookahead won't chain here
        }
        // Later in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
    }

    // Prefer bins with smaller residuals (fill fuller bins first).
    score += (bin_residual as f64 - mean_residual) * 0.25;

    // Mild preference for bins that are already partially filled.
    let fill = 1.0 - bin_residual as f64 / bin_capacity as f64;
    score -= 6.0 * fill;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Late in the stream, tighter packing matters more: weight small residuals.
    let tight = norm_pr * norm_pr * (1.0 + 3.0 * progress) * 40.0;
    score -= tight;

    // Dead-space penalty: residuals too small for typical items are wasted.
    let dead = if pr > 0.0 && pr < 10.0 { (10.0 - pr) * (2.0 + 4.0 * progress) } else { 0.0 };
    score += dead;

    // Lookahead coupling: reward residuals that still fit the next item,
    // quadratic in how well the next item matches the post residual.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let diff = pr - nx;
        if diff >= 0.0 {
            score -= 12.0 * (1.0 - (diff / cap).powi(2));
        } else {
            score += (-diff / cap) * 15.0;
        }
    }

    // Last-chance bonus: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 25.0 * (0.5 + progress);
    }

    // Slight preference for bins deviating from mean residual (balance pressure).
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 5.0 * dev * dev * (1.0 - progress);

    // New-bin candidate: penalize opening a new bin, more so early on.
    if bin_residual == bin_capacity {
        score += 30.0 + 40.0 * (1.0 - progress) + open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual modulo capacity quartiles
    let q = bin_capacity / 4; // 25
    let class = post_residual / q; // 0..4
    match class {
        0 => score -= 18.0,          // tiny dead space: excellent fit
        1 => score -= 6.0,           // quarter-left: decent
        2 => score += 4.0,           // half-left: mediocre
        3 => score += 12.0,          // three-quarters left: wasteful
        _ => score += 25.0,          // nearly untouched bin used for a small item
    }

    // Penalize leaving residual that next item cannot use
    if next_item_size > 0 {
        if next_item_size > post_residual {
            score += (next_item_size - post_residual) as f64 * 0.35;
        } else if next_item_size <= post_residual {
            // reward if next item exactly harmonizes (divides residual)
            if post_residual % next_item_size.max(1) == 0 {
                score -= 8.0;
            } else {
                score -= 2.0;
            }
        }
    } else {
        // last item: prefer tightest fit only
        score = post_residual as f64;
    }

    // Last-chance bin: strong bonus to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: only attractive when open bins are congested
    if bin_residual == bin_capacity {
        let congestion = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = 40.0 + congestion * 5.0 - progress * 5.0;
        // discourage new bin if current item leaves a good harmonic residual in an open bin
        if post_residual <= q {
            score += 20.0;
        }
    }

    // Mild pressure to use bins with low mean residual (tighten globally)
    score += (mean_residual - post_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize unusable dead space: gaps too small for typical items
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }
    if post_residual > 0 && post_residual < item_size.min(20) {
        score += 15.0;
    }

    // Perfect fit reward
    if post_residual == 0 {
        score -= 100.0;
    }

    // Last-chance bin: strong bonus to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: prefer using existing bins when many are open
    score += open_bins_count as f64 * 0.5;

    // New-bin candidate: only attractive when item fits poorly everywhere
    if bin_residual == bin_capacity {
        // base penalty so existing bins usually win
        score += 40.0;
        // lookahead: if next item is large, opening a fresh bin now is worse
        if next_item_size > bin_residual - item_size {
            score += next_item_size as f64 * 0.3;
        }
        // early stream: opening bins cheap is fine
        if (step_index as f64) / (total_items.max(1) as f64) < 0.2 {
            score -= 20.0;
        }
    }

    // Prefer bins whose residual is close to mean (balanced packing)
    score += ((bin_residual as f64 - mean_residual) / 10.0).abs();

    // Lookahead synergy: reward leaving space the next item can use
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core: reward exact 2-step lookahead match — post_residual equals next item size.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect match: next item exactly fills the bin -> huge reward.
        if gap == 0.0 {
            score -= 50.0;
        } else {
            score += gap * 0.6;
        }
        // Bonus when next item fits exactly leaving zero residual after two placements.
        if next_item_size >= post_residual {
            // Next item won't fit here; slight penalty proportional to overshoot.
            score += (next_item_size - post_residual) as f64 * 0.2;
        }
        // Reward leaving a residual that is either 0 or large enough to be reusable.
        if post_residual == 0 {
            score -= 20.0;
        } else if post_residual >= 10 {
            score -= (post_residual as f64).sqrt() * 1.5;
        } else {
            // Small dead space (1..9) is nearly unusable given typical item sizes.
            score += (10 - post_residual) as f64 * 2.0;
        }
    } else {
        // Last item: prefer exact fill.
        if post_residual == 0 {
            score -= 40.0;
        }
    }

    // Relative to mean residual: bins tighter than average are better targets.
    score += (mean_residual - bin_residual as f64) * 0.5;

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Penalize the brand-new empty bin candidate unless open bins are badly fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = mean_residual / bin_capacity as f64;
        // Open new bin only if existing bins have large residuals (poor fits likely).
        if fragmentation > 0.35 {
            score -= 8.0 * (fragmentation - 0.35);
        } else {
            score += 25.0;
        }
    }

    // Mild late-stream consolidation: prefer filling existing bins as stream ends.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize bins whose residual barely exceeds item size.
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score -= (1.0 - tightness) * 12.0;

    // Lookahead: if the next item can fit into the post-residual, reward this bin.
    if next_item_size > 0 {
        if (post_residual as f64) >= next_item_size as f64 {
            score -= 6.0;
            // Extra reward if next item fits almost exactly in post-residual.
            let slack = post_residual as f64 - next_item_size as f64;
            score -= (1.0 - slack / bin_capacity as f64) * 5.0;
        } else {
            // Penalize leaving a residual the next item cannot use (dead space risk).
            score += 4.0;
        }
    } else {
        // Last item: strongly prefer minimal post residual.
        score += post_residual as f64 * 0.5;
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let pressure = mean_residual / bin_capacity as f64;
        // Early stream or high mean residual -> new bin is fine.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 10.0 * (1.0 - progress) + 20.0 * pressure;
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
    } else {
        // Prefer bins below the mean residual (fill emptier bins first to consolidate).
        if (bin_residual as f64) < mean_residual {
            score -= 3.0;
        } else {
            score += 2.0;
        }
    }

    // Mild penalty for proliferating open bins.
    score += open_bins_count as f64 * 0.15;

    // Nonlinear dead-space shaping: residuals in the awkward 1..=10 zone are wasted.
    if post_residual >= 1 && post_residual <= 10 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Normalized post-residual in [0,1]
    let r = post / cap;

    // Smooth polynomial coupling of post_residual with stream progress:
    // early on, prefer bins with small post_residual (tight packing);
    // later, allow slightly larger residuals as waste tolerance rises.
    let phase = progress * (1.0 - progress) * 4.0; // peaks mid-stream, smooth
    let poly = r * r * (1.0 - r) * 4.0;            // penalizes both extremes smoothly

    let mut score = post;
    score += poly * cap * (0.5 + 0.5 * progress);          // non-linear residual curvature
    score -= phase * cap * 0.35 * (1.0 - r);               // mid-stream bonus for tight fits
    score *= 1.0 + 0.25 * progress * (r * r);              // late-stream dead-space penalty

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0 + 60.0 * (1.0 - r);
    }

    // Lookahead: reward if next item fits in the post-residual
    if next_item_size > 0 && (post_residual as u64) >= (next_item_size as u64) {
        score -= 12.0 + 0.3 * next_item_size as f64;
    } else if next_item_size > 0 {
        // penalize residuals that nearly-but-don't fit the next item
        let gap = (next_item_size as f64 - post).max(0.0);
        score += 0.15 * gap;
    }

    // New-bin candidate: make it moderately attractive only for large items / poor fits
    if bin_residual == bin_capacity {
        score += 55.0 - 0.2 * item_size as f64 - 25.0 * progress;
    }

    // Slight penalty for bins far below mean residual (fragmentation avoidance)
    score += 0.1 * (mean_residual - post).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: how "usable" is the leftover space?
    // Residuals divisible by small class sizes (10, 20, 25, 50) are more reusable.
    let pr = post_residual;
    let class_bonus = if pr == 0 {
        -60.0 // perfect fit, huge reward
    } else if pr % 50 == 0 {
        -18.0
    } else if pr % 25 == 0 {
        -12.0
    } else if pr % 20 == 0 {
        -10.0
    } else if pr % 10 == 0 {
        -7.0
    } else if pr % 5 == 0 {
        -3.0
    } else {
        // awkward residue: penalize small dead space
        if pr < 10 { 25.0 } else { 2.0 }
    };
    score += class_bonus;

    // Dead-space penalty: leftover that no plausible item can use.
    if pr > 0 && pr < 10 {
        score += (10 - pr) as f64 * 3.0;
    }

    // Lookahead coupling: does post_residual accommodate the next item exactly/nicely?
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 30.0; // sets up a perfect follow-up
        } else if next_item_size < pr {
            let nxt_post = pr - next_item_size;
            if nxt_post % 10 == 0 || nxt_post == 0 {
                score -= 12.0;
            } else if nxt_post < 10 {
                score += 8.0; // chains into dead space
            }
        } else {
            // next item cannot use this bin's leftover anyway; slight penalty
            score += 3.0;
        }
    }

    // Last-chance logic: if this is the only fitting bin, strongly prefer using it
    // rather than opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
        if post_residual < 10 {
            score -= 10.0; // still fine to use it up
        }
    }

    // New-bin candidate: empty bin should only win when current fit is poor.
    if bin_residual == bin_capacity {
        // neutral baseline slightly above a good fit, below a bad fit
        score += 35.0;
        if item_size % 10 == 0 {
            score -= 5.0; // large round items pair well with fresh bins
        }
    }

    // Fraction-of-capacity harmony: item that fills bin to a clean fraction is good.
    let used = bin_capacity - pr;
    if bin_capacity > 0 && used % 25 == 0 {
        score -= 6.0;
    } else if bin_capacity > 0 && used % 10 == 0 {
        score -= 3.0;
    }

    // Stream progression: late in stream, consolidate aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (post_residual as f64 / bin_capacity.max(1) as f64) * 10.0;

    // Prefer tighter bins when many bins are open (contain bin proliferation).
    score += (open_bins_count as f64).sqrt() * (post_residual as f64 - mean_residual) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small nonzero gaps are almost unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    if post_residual >= 10 && post_residual < 20 {
        score += 15.0;
    }

    // Reward exact / near-exact fits strongly.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Lookahead: if the next item fits exactly into the post residual, favor this bin.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 80.0;
        } else if post_residual > next_item_size {
            score -= 5.0;
        } else {
            // post residual too small for the next item: penalize proportionally
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // Pressure against proliferating open bins: mildly penalize when many bins are open,
    // unless the fit is very tight (dead-space logic already handles that).
    let open_pressure = open_bins_count as f64 * 0.3;
    let tightness = (bin_residual - item_size) as f64 / bin_capacity as f64;
    score += open_pressure * (1.0 - tightness);

    // New-bin candidate: empty bin should only win if the item fits poorly everywhere.
    if bin_residual == bin_capacity {
        // Base penalty: prefer existing bins by default.
        score += 25.0;
        // But if item is large relative to mean residual across open bins, opening
        // a fresh bin is more attractive (existing bins would waste more space).
        let waste_elsewhere = mean_residual - item_size as f64;
        if waste_elsewhere > 0.0 {
            score -= waste_elsewhere * 0.8;
        }
        // Late in the stream, keep bins consolidated.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong base penalty on leftover space (tight fit preferred).
    score += (post_residual as f64 / bin_capacity as f64) * 40.0;

    // 2-step lookahead: reward bins whose post_residual matches next item size.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;
        if pr >= nxt {
            let gap = pr - nxt;
            // Exact match is ideal; penalize gap quadratically.
            score -= (nxt / (gap + 1.0)) * 12.0;
        } else {
            // Next item won't fit here: penalize proportional dead space.
            score += (nxt - pr) * 0.8;
        }
    } else {
        // Last item: prefer minimal final residual.
        score += post_residual as f64 * 0.5;
    }

    // Relative-to-mean coupling: bins tighter than average get a bonus.
    let rel = mean_residual - post_residual as f64;
    score -= rel * 0.6;

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Penalize very small unusable leftovers (dead space < 10).
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Early in stream: be slightly more willing to open bins for good structure.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: attractive when post_residual could host next item.
        if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
            score -= 6.0;
        }
        score += progress * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: squared penalty on wasted space.
    let waste = post_residual as f64;
    score += 0.35 * waste * waste / bin_capacity as f64;

    // Reward near-perfect fills.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual < 10 {
        score -= 12.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 18.0 + 0.25 * item_size as f64;
    }

    // Lookahead: if the next item would fit the post-residual exactly or well,
    // reward this placement; if it would be blocked, penalize.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if next_item_size <= post_residual {
            let nx_waste = (post_residual - next_item_size) as f64;
            score -= 10.0 - 0.12 * nx_waste;
        } else {
            score += 4.0 + 0.10 * (nx - post_residual as f64);
        }
    }

    // Global state coupling: prefer filling bins when mean residual is low
    // (bins are already fragmented); prefer spreading when residuals are large.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let mr = mean_residual;
    score -= 0.08 * (mr - post_residual as f64) * (1.0 - progress);
    score += 0.05 * (mr - post_residual as f64) * progress;

    // New-bin candidate handling: opening a new bin is only attractive when
    // the item fits poorly everywhere else (large waste) or few bins are open.
    if bin_residual == bin_capacity {
        let poor_fit_elsewhere = fitting_bins_count == 0
            || (post_residual as f64 > 0.5 * bin_capacity as f64 && fitting_bins_count <= 2);
        if poor_fit_elsewhere && open_bins_count > 0 {
            score -= 6.0;
        } else {
            score += 25.0 + 0.15 * open_bins_count as f64;
        }
        // Early stream: new bins are cheap to open.
        if progress < 0.15 {
            score -= 8.0;
        }
    }

    // Mild preference for keeping the number of open bins bounded.
    score += 0.03 * open_bins_count as f64 * (waste / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let fit_norm = pr / cap; // normalized post residual in [0,1]

    // Base: prefer small post residual (tight fits), with smooth polynomial shaping
    let mut score = pr;

    // Non-linear coupling: reward tight fits more strongly as the stream progresses
    let tightness = (1.0 - fit_norm).powi(3);
    score -= 30.0 * tightness * (0.5 + progress);

    // Penalize moderately large dead space quadratically (unusable gaps)
    score += 12.0 * fit_norm * fit_norm * (1.0 + progress);

    // Lookahead: reward if next item fits the post residual exactly-ish
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let slack = (pr - nxt) / cap;
            score -= 20.0 * (1.0 - slack) * (1.0 - slack);
        } else {
            score += 8.0 * ((nxt - pr) / cap);
        }
    } else {
        // last item: strongly prefer tightest fit
        score -= 25.0 * tightness;
    }

    // Last-chance bin bonus: only fitting bin -> strong reward to use it
    if fitting_bins_count == 1 {
        score -= 40.0;
    } else if fitting_bins_count > 1 {
        // mild penalty to spread across bins when many fit
        score += 2.0 * (fitting_bins_count as f64 - 1.0).sqrt();
    }

    // Empty new-bin candidate: penalize unless residual situation is bad
    if bin_residual == bin_capacity {
        let pressure = mean_residual / cap;
        score += 60.0 - 45.0 * pressure - 30.0 * progress * (1.0 - pressure);
    }

    // Mild preference to balance load across open bins
    score += 0.05 * (pr - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: perfect fits are golden.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap; // fraction of capacity left

    // Zero residual: strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Modulo arithmetic classes on post_residual (capacity 100 baseline).
    let m = post_residual % 10;
    match m {
        0 => score -= 40.0,          // multiple of 10: very reusable class
        1 | 9 => score += 25.0,      // awkward 1-slug dead space
        2 | 8 => score += 12.0,
        3 | 7 => score += 5.0,
        4 | 6 => score -= 5.0,
        5 => score -= 2.0,
        _ => {}
    }

    // Harmonic fraction classes: reward residuals that are "nice" capacity fractions.
    if (frac - 0.5).abs() < 1e-9 {
        score -= 30.0; // half-full residual is highly reusable
    } else if (frac - 0.25).abs() < 1e-9 || (frac - 0.75).abs() < 1e-9 {
        score -= 15.0;
    }

    // Penalize small unusable residuals more as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if post_residual < 10 && post_residual > 0 {
        score += 60.0 + 80.0 * progress; // dead space
    }

    // Lookahead coupling: does the next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Harmonic class of the match: exact multiple alignment is great.
            if post_residual % next_item_size == 0 {
                score -= 45.0;
            } else {
                score -= 20.0 + 10.0 * (next_item_size as f64 / 100.0);
            }
        } else {
            // Next item won't fit here: mild penalty scaled by overshoot class.
            let over = (next_item_size - post_residual) % 10;
            score += 8.0 + over as f64;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 70.0;
    }

    // New-bin candidate logic: only attractive if current bins are badly fragmented.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let fragmentation = (mean_residual - pr).abs();
        // Prefer opening a new bin early or when open bins have tiny residuals.
        if open_bins_count > 0 && mean_residual < 20.0 {
            score -= 55.0;
        }
        score += 30.0 * (open_bins_count as f64).sqrt() - 20.0 * progress;
        let _ = fragmentation;
    } else {
        // Prefer tighter existing bins: reward closeness of fit.
        let tightness = item_size as f64 / bin_residual as f64;
        score -= 25.0 * tightness;
        // Slight penalty for spreading across too many bins.
        score += 0.5 * open_bins_count as f64;
    }

    // Mean-residual anchoring: prefer bins near the mean (balanced packing).
    score += 0.15 * (pr - mean_residual).abs();

    // Integer-division threshold on post_residual / 25 (quarter classes).
    let quarter = post_residual / 25;
    score -= match quarter {
        0 => 5.0,   // tiny residual: bad
        1 => 10.0,
        2 => 12.0,
        3 => 8.0,
        _ => 0.0,
    };

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: unusable gaps (post_residual < smallest plausible item)
    if post_residual > 0 {
        let dead = if post_residual < 20 { 3.0 } else if post_residual < 40 { 1.5 } else { 0.0 };
        score += dead * post_residual as f64;
    } else {
        // Perfect fill is heavily rewarded
        score -= 60.0;
    }

    // Prefer tight fits: small post_residual relative to item size
    score += (item_size as f64 / (post_residual as f64 + 1.0)) * 2.0;

    // Open-bin pressure: discourage spreading across too many bins
    score += open_bins_count as f64 * 0.8;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if next item fits into post_residual, reward this placement
    if next_item_size > 0 && (post_residual as i64 - next_item_size as i64) == 0 {
        score -= 30.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Dead space relative to the known next item
        score += (next_item_size - post_residual) as f64 * 0.5;
    }

    // New-bin candidate: make it moderately attractive only when residuals are fragmented
    if bin_residual == bin_capacity {
        let frag = (mean_residual - post_residual as f64).abs();
        if mean_residual < 30.0 && fitting_bins_count > 0 {
            score -= 15.0; // open bins are nearly full, fresh bin is fine
        } else {
            score += 20.0 + frag * 0.1; // keep using open bins normally
        }
    }

    // Mean residual coupling: penalize placing into bins far from mean (fragmentation)
    score += (bin_residual as f64 - mean_residual).abs() * 0.15;

    // Mild stream progression: tighten criteria as stream advances
    let progress = step_index as f64 / total_items as f64;
    score += post_residual as f64 * progress * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect fit (post_residual == 0)
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: reward when next item fits exactly into post_residual
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 900.0;
        } else if post_residual > next_item_size {
            // Next item fits, but leaves some waste; reward proportionally
            let lookahead_waste = (post_residual - next_item_size) as f64;
            score -= 300.0 - 2.0 * lookahead_waste;
        } else {
            // Next item does NOT fit in this bin after placement: penalize
            let gap = (next_item_size - post_residual) as f64;
            score += 2.5 * gap;
        }
    }

    // Penalize dead space that is too small to be useful (below minimum item size 1..100 heuristic threshold)
    if post_residual > 0 && post_residual < 10 {
        score += 150.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 250.0;
    }

    // Relative-to-mean coupling: bins with residual far below mean are "tight" fits, prefer them
    let rel = post_residual as f64 - mean_residual;
    score += 0.5 * rel;

    // Prefer filling more-opened bins early (keep many bins available); penalize opening new bin
    if bin_residual == bin_capacity {
        score += 80.0 + 0.3 * open_bins_count as f64;
    }

    // Slight stream-progression bias: later in stream, prioritize tight packing
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 20.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post residual) with a non-linear boost.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 8.0 * tightness * tightness;

    // Penalize leaving dead space that cannot fit the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Lookahead: reward bins whose post residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0 + 0.05 * next_item_size as f64;
    } else if next_item_size > 0 {
        score += 3.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else if fitting_bins_count > 2 {
        // Many alternatives: be pickier about waste.
        score += 0.03 * (post_residual as f64);
    }

    // Time horizon: early in the stream, prefer consolidating into open bins
    // (keep options open); late, tolerate opening bins less since stream ends.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Global residual pressure: if mean residual is high, prefer filling
    // bins that are below-average full (reduce fragmentation spread).
    let avg_post = mean_residual - item_size as f64;
    let dev = post_residual as f64 - avg_post;
    score += 0.08 * dev;

    // New-bin candidate: make it attractive only when item is large or
    // existing bins would be badly fragmented.
    if bin_residual == bin_capacity {
        let poor_fit = fitting_bins_count == 0
            || (post_residual > 0 && post_residual < 20)
            || item_size >= 60;
        if poor_fit {
            score -= 20.0;
        } else {
            score += 10.0 + 0.1 * open_bins_count as f64;
        }
    }

    // Mild preference to balance load across many open bins.
    score -= 0.02 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Non-linear penalty on wasted residual, amplified by stream progress
    let waste = post / cap;
    score += 60.0 * waste * waste * (0.5 + progress);

    // Reward tight fits (small post_residual) with smooth exponential coupling
    score -= 25.0 * (-post / (0.15 * cap)).exp() * (1.0 + progress);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 40.0 * (1.0 - waste);
    }

    // Penalize bins with residual far from the mean residual (keeps residual spread tight)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 10.0 * dev * dev;

    // Lookahead: if next item fits in post_residual, reward this placement
    if next_item_size > 0 && (next_item_size as f64) <= post {
        score -= 15.0 * (1.0 - (next_item_size as f64 / cap));
    } else if next_item_size > 0 {
        // smooth penalty if next item won't fit into the leftover
        score += 8.0 * ((next_item_size as f64 - post) / cap);
    }

    // Mild penalty for spreading across too many open bins late in the stream
    score += 2.0 * (open_bins_count as f64).ln() * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: exact-fit classes are golden.
    let pr = post_residual as u32;
    let class = pr % 10;
    match class {
        0 => score -= 30.0,           // residual multiple of 10: reusable
        1 | 2 | 3 => score += 8.0,    // tiny slivers: dead space
        4 | 5 => score -= 5.0,        // half-class useful
        _ => score += 2.0,
    }

    // Integer-division thresholds on post_residual.
    if pr == 0 { score -= 100.0; }
    else if pr <= 10 { score += 25.0; }        // unusable sliver
    else if pr <= 20 { score += 5.0; }
    else if pr >= 50 { score -= 6.0; }         // still half a bin usable

    // Perfect fit detection.
    if post_residual == 0 { score -= 200.0; }

    // Lookahead coupling: does post_residual fit next item exactly-ish?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = post_residual - next_item_size;
            if slack == 0 { score -= 60.0; }
            else if slack <= 10 { score -= 20.0; }
            else { score += slack as f64 * 0.3; }
        } else {
            // next item won't fit here; penalize proportional to overflow
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
        // Harmonic class of next item size
        match next_item_size % 10 {
            0 => score -= 3.0,
            _ => {}
        }
    }

    // Last-chance bin bonus.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Prefer tight bins vs mean residual.
    let res = bin_residual as f64;
    if res < mean_residual { score -= (mean_residual - res) * 0.4; }
    else { score += (res - mean_residual) * 0.2; }

    // New-bin candidate: only attractive when open bins are fragmented.
    if bin_residual == bin_capacity {
        let frag = if mean_residual > 0.0 { mean_residual / cap } else { 1.0 };
        score = cap * 0.9 - (1.0 - frag) * 30.0
              + if next_item_size > 0 && next_item_size > item_size { 15.0 } else { 0.0 }
              - (open_bins_count as f64) * 0.5;
        if fitting_bins_count <= 1 { score -= 25.0; }
        if pr >= 30 && next_item_size > 0 && post_residual >= next_item_size { score += 20.0; }
    }

    // Late-stream tightening.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * (0.1 + 0.25 * progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to ever be useful
    // (below the minimum plausible item size) are pure waste -> heavy penalty.
    let min_item = 1.0f64;
    if (post_residual as f64) < min_item * 10.0 {
        score += 40.0;
    }

    // Penalize "awkward" residuals: gaps that only very small items could fill.
    let pr = post_residual as f64;
    if pr > 0.0 && pr <= 25.0 {
        score += (25.0 - pr) * 1.5;
    }

    // Reward exact / near-exact fits strongly.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Perfect fit for the lookahead item: reserve this gap for it.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 45.0;
    } else if next_item_size > 0 && post_residual > next_item_size && (post_residual as i64 - next_item_size as i64) <= 5 {
        score -= 15.0;
    }

    // Open-bin pressure: prefer spreading load when many bins are open,
    // discourage hoarding items in few bins when few bins exist.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += pressure * 2.0;

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // New-bin candidate: opening a new bin is only attractive when the current bin
    // would leave a large unusable gap or when residuals across bins are already huge.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let gap_after = post_residual as f64;
        let mean_r = mean_residual;
        // Penalize new bin mildly by default; the tighter the fit elsewhere, the less we open.
        score += 12.0;
        // But if all open bins would leave terrible dead space (< 15 usable), allow opening.
        if fitting_bins_count >= 1 && gap_after >= bin_capacity as f64 - item_size as f64 {
            if mean_r > 45.0 {
                score -= 20.0;
            }
        }
        // Late in the stream, avoid spawning bins with tiny future utility.
        let progress = step_index as f64 / total_items.max(1) as f64;
        if progress > 0.9 {
            score += 8.0 * progress;
        }
    }

    // Mild tie-break: prefer bins whose residual is closest to the mean (balanced use).
    score += ((bin_residual as f64 - mean_residual) / bin_capacity as f64).abs() * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual closely matches the next item.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect chain (next item fills bin exactly) is highly desirable.
        if post_residual == next_item_size {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            // Next item fits here afterwards: reward tight coupling.
            score -= 25.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // Next item cannot use the post residual: penalize dead space proportionally.
            score += 0.35 * gap;
        }
        // Bonus if the pair (item, next) nearly fills the bin.
        let pair_fill = (item_size + next_item_size) as f64 / bin_capacity as f64;
        if pair_fill > 0.95 && (item_size + next_item_size) <= bin_residual {
            score -= 15.0;
        }
    } else {
        // Last item: minimize leftover as usual.
        score += 0.1 * post_residual as f64;
    }

    // Penalize deviations from the mean residual: prefer bins that are either tight
    // (below mean) or that keep residual diversity balanced.
    let dev = post_residual as f64 - mean_residual;
    if dev > 0.0 {
        score += 0.08 * dev;
    } else {
        score += 0.04 * (-dev);
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
        // Still penalize very wasteful usage in the last-chance bin.
        if post_residual as f64 > 0.5 * bin_capacity as f64 {
            score += 0.3 * (post_residual as f64 - 0.5 * bin_capacity as f64);
        }
    }

    // New empty bin candidate: only attractive when the item is large or few bins fit,
    // otherwise discourage fragmentation across many bins.
    if bin_residual == bin_capacity {
        let frac = item_size as f64 / bin_capacity as f64;
        if frac > 0.6 || fitting_bins_count == 0 {
            score -= 20.0 + 20.0 * frac;
        } else {
            score += 25.0 + 10.0 * (1.0 - frac);
        }
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 * progress;
    }

    // Mild pressure to prefer fuller bins overall.
    score += 0.05 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize large post residual (wasted space), non-linearly.
    let pr = post_residual as f64;
    score += 0.35 * (pr / bin_capacity as f64).powi(3) * bin_capacity as f64;

    // Reward tight fits (small post_residual relative to item size).
    score -= 1.2 * (item_size as f64 / (item_size as f64 + pr + 1.0));

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if next item fits in post_residual, reward; otherwise penalize.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 8.0 + 0.15 * next_item_size as f64;
        } else {
            // Dead-space penalty if leftover can't host the next item.
            let dead = pr - if pr > next_item_size as f64 { next_item_size as f64 } else { pr };
            score += 0.25 * dead;
        }
    }

    // New-bin candidate handling: only open a new bin when current fits are poor.
    if bin_residual == bin_capacity {
        let tightness = if fitting_bins_count > 0 {
            let best_gap: f64 = 0.0; // unknown; use mean residual as proxy
            best_gap
        } else { 0.0 };
        let pressure = (pr / bin_capacity as f64) * 100.0;
        let open_pressure = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
        // Prefer new bin when open bins are crowded and many bins already open.
        score += 30.0 - 0.5 * pressure - open_pressure;
        if fitting_bins_count <= 1 {
            score -= 40.0; // no alternatives: opening new bin is fine
        }
    }

    // Time horizon: early in stream, be conservative with bin openings.
    let t = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * t * (1.0 - t) * 4.0; // mid-stream urgency bonus for reuse

    // Prefer bins whose residual deviates from mean (consolidate similar leftovers).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.08 * dev;

    // Mild penalty on high open bin count to discourage sprawl.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post_residual, with non-linear shaping
    let mut score = pr * (1.0 + 0.5 * norm_pr * norm_pr);

    // Stream-progress coupling: later in the stream, tolerate residual less (tighten packing)
    let progress_coupling = 1.0 + 0.8 * progress * (1.0 - norm_pr);
    score *= progress_coupling;

    // Last-chance bonus: strongly reward using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 40.0 + 20.0 * progress;
    }

    // Reward when post_residual aligns with the next item's size (lookahead fit)
    if next_item_size > 0 {
        let diff = (pr - next_item_size as f64).abs();
        score += 0.3 * diff;
        if next_item_size as f64 <= pr && pr > 0.0 {
            score -= 10.0 * (1.0 - diff / cap);
        }
    }

    // Penalize bins whose residual deviates strongly from the mean residual (keeps bin pool balanced)
    let dev = (pr - mean_residual).abs();
    score += 0.15 * dev * (0.5 + progress);

    // Slight penalty when many bins are open relative to stream progress (discourage spreading)
    let open_norm = open_bins_count as f64 / (total_items as f64).max(1.0);
    score += 50.0 * open_norm * (1.0 - progress);

    // New-bin candidate: make empty bins mildly unattractive unless residual would be very tight elsewhere
    if bin_residual == bin_capacity {
        score += 15.0 * (1.0 - progress) - 5.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: how "reusable" is the residual?
    // Residuals divisible into common item classes (10,20,25,50) are valuable.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Reward residuals that are exact multiples of frequent item classes
    for class in [10u32, 20, 25, 50] {
        if post_residual % class == 0 {
            score -= 6.0 * (class as f64 / 10.0);
        }
    }

    // Penalize dead space: residuals too small for the smallest plausible item
    if post_residual < 10 && post_residual > 0 {
        score += 25.0;
    }

    // Perfect fit is ideal
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead coupling: does the leftover fit the next item well?
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0; // chains perfectly
        } else if post_residual >= next_item_size {
            let frac = next_item_size as f64 / pr.max(1.0);
            // prefer leftover that the next item fills densely
            score -= 12.0 * frac;
        } else {
            // leftover unusable by next item: penalize proportionally
            score += 8.0 * (1.0 - pr / cap);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Prefer fuller bins overall (best-fit bias beyond raw post_residual)
    score -= 0.15 * (bin_residual as f64 / cap) * 10.0;

    // New-bin candidate: only attractive when open bins have poor fits
    if bin_residual == bin_capacity {
        let pressure = mean_residual / cap; // low mean residual => bins nearly full
        let late = step_index as f64 / (total_items.max(1) as f64);
        if fitting_bins_count == 0 {
            score -= 50.0; // must open a bin anyway
        } else {
            // opening a new bin is good if existing residuals are small/fragmented
            score += 30.0 * pressure;
            if next_item_size > 0 && next_item_size > mean_residual {
                score -= 15.0; // next item won't fit open bins anyway
            }
            score -= 5.0 * late;
        }
    }

    // Mild penalty for spreading across many open bins
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable dead space heavily (gaps below minimum item size 1..=small)
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0;
    }

    // Reward tight fits (post_residual near zero but usable)
    if post_residual == 0 {
        score -= 100.0;
    }

    // Reward bins whose post_residual can still fit the lookahead item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 10.0; // dead space relative to lookahead
    }

    // Perfect-fit bonus relative to bin capacity
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 40.0 * fit_ratio;

    // Pressure: prefer already-open bins over opening new ones.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Opening a new bin is penalized by number of open bins and stream progress
        score += 30.0 + 8.0 * open_bins_count as f64 + 40.0 * (step_index as f64 / total_items.max(1) as f64);
        // But if no open bin fits (last chance situation), reduce penalty
        if fitting_bins_count == 0 {
            score -= 90.0;
        }
    } else {
        // Mild bonus for using existing bins, stronger when many bins are open
        score -= 5.0 + 1.5 * open_bins_count as f64;
        // Last-chance bin: strongly favor filling it to avoid waste
        if fitting_bins_count == 1 {
            score -= 35.0;
        }
    }

    // Prefer bins with residuals below the mean (consolidating waste)
    score -= 0.3 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward: post_residual exactly matches the next item (perfect 2-step fit)
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Reward: bin can still fit the next item after this placement
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0 + (post_residual - next_item_size) as f64 * 0.3;
    }

    // Penalize dead space: post_residual too small to fit the next item
    if next_item_size > 0 && post_residual < next_item_size {
        score += 20.0;
        // Especially bad if the leftover is a tiny unusable sliver
        if post_residual < 10 {
            score += 15.0;
        }
    }

    // Last-chance bonus: this is the only bin that can fit the item
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Penalize opening a new bin when decent open bins exist
    if bin_residual == bin_capacity {
        score += 30.0;
        // Less penalty if open bins are nearly full on average
        score -= (mean_residual / bin_capacity as f64) * 20.0;
    }

    // Mild tie-breaking: prefer bins whose residual deviates below the mean
    // (fill tighter bins first, keep larger residuals available)
    if bin_residual != bin_capacity {
        score -= (mean_residual - bin_residual as f64) * 0.2;
    }

    // Early in the stream, be slightly more willing to keep bins compact
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward filling bins densely: bigger item relative to capacity -> lower score
    score -= (item_size as f64 / bin_capacity as f64) * 40.0;

    // Last-chance bin: strongly prefer using it before opening a new one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: reward placements that leave room for the next item
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 15.0;
        } else if post_residual < 10 {
            // bin nearly sealed is also good even if next item won't fit
            score -= 10.0;
        }
    }

    // Penalize small unusable slivers slightly less than medium dead space
    if post_residual > 0 && post_residual < 10 {
        score -= 5.0;
    }

    // New-bin candidate handling
    if bin_residual == bin_capacity {
        // Base reluctance to open a new bin while others could fit
        score += 30.0 + 0.15 * mean_residual;
        // If no open bin fits, opening a new bin is necessary
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
        // Large items are fine in fresh bins
        if item_size > 60 {
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr_norm = pr / cap;

    // Base: prefer small post-residual, with smooth non-linear penalty growth
    let mut score = pr * (1.0 + 0.5 * pr_norm * pr_norm);

    // Tight-fit reward: smooth bump around post_residual near 0
    score -= 8.0 * (-pr / 6.0) * (-pr / 6.0) * (-1.0 + (-pr / 6.0) * (-pr / 6.0));

    // Polynomial coupling of post_residual with stream progress:
    // late in the stream, small residuals matter more (dead space is costlier)
    let coupling = pr_norm * pr_norm * (1.0 - pr_norm);
    score += 20.0 * coupling * (0.3 + progress);

    // Lookahead: reward leaving room for the next item (smooth interaction)
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        let fit_next = (pr - ns).max(0.0) / cap;
        let slack_gap = (pr - ns).abs();
        score -= 6.0 * fit_next;
        score += 0.05 * slack_gap * slack_gap / cap;
    }

    // Last-chance bin bonus: avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 {
        score -= 10.0 + 15.0 * (1.0 - pr_norm);
    }

    // Mild penalty for spreading across many bins; slightly relaxed late in stream
    score += 0.4 * (open_bins_count as f64).ln() * (1.0 - 0.5 * progress);

    // Prefer bins below mean residual (consolidation), smooth quadratic
    let dev = pr - mean_residual;
    score += 0.02 * dev * dev / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover: which residue class mod capacity fractions
    let c = bin_capacity as f64;
    let pr = post_residual as f64;

    // Dead-space classes: leftovers that are hard to fill later get penalized.
    // Classes: 0 (perfect), small (1..=10), awkward (11..=25), medium (26..=50), large (>50)
    if post_residual == 0 {
        score -= 30.0; // perfect fit reward
    } else if post_residual <= 10 {
        score -= 8.0; // small leftovers are near-perfect
    } else if post_residual <= 25 {
        score += 6.0; // awkward dead space
    } else if post_residual <= 50 {
        score += 2.0; // medium, still usable
    } else {
        score -= 4.0; // large residual, still flexible
    }

    // Integer-division threshold: does the NEXT item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // chain bonus, scaled by how tightly the next item nests
            let tightness = 1.0 - (pr - next_item_size as f64) / c;
            score -= 10.0 + 12.0 * tightness;
        } else {
            // next item cannot follow here; penalize proportionally to wasted potential
            score += 5.0 * (next_item_size as f64 / c);
        }
    }

    // Last-chance logic: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: opening a new bin should only win when the current item
    // leaves an awkward class in every open bin. Penalize the empty bin mildly,
    // but forgive it when post_residual of the empty bin (= C - item) is a
    // "clean class" (multiple of 10 or > 50, i.e. very large or very small item).
    if bin_residual == bin_capacity {
        let clean = (post_residual % 10 == 0) || post_residual > 50;
        if clean {
            score += 4.0;
        } else {
            score += 18.0 + 0.1 * open_bins_count as f64;
        }
    }

    // Progress-aware dead-space penalty: late in the stream, leftover waste matters more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (pr / c) * 6.0;

    // Coupling with mean residual: prefer bins whose residual deviates favorably
    // (using a tighter-than-average bin avoids fragmenting large residuals).
    if bin_residual < bin_capacity {
        let dev = mean_residual - bin_residual as f64;
        score += 0.05 * dev;
    }

    // Harmonic modulo tie-breaker on post_residual classes (period 7)
    score += (post_residual % 7) as f64 * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residual gaps that are too small to hold
    // even the smallest item (<= 1..10 range) are pure waste -> heavy penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual <= 20 {
        // Small but potentially usable gap: moderate penalty, scaled by how
        // unlikely a future item fits it (items 1..100 unknown distribution).
        score += 15.0 * (1.0 - post_residual as f64 / 20.0);
    }

    // Reward tight fits (near-zero post residual is ideal when >= 10).
    if post_residual == 0 {
        score -= 40.0; // perfect fill
    } else if post_residual <= 10 {
        score -= 20.0;
    }

    // Last-chance pressure: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, favor
    // consolidating into existing bins; few open bins -> opening is cheaper.
    let bin_pressure = (open_bins_count as f64).ln().max(0.0);
    score += 4.0 * bin_pressure;

    // New-bin candidate handling: empty bin should only win when the item
    // fits poorly in all open bins or open-bin set is congested.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, amortized by stream progress
        // (early in the stream, new bins are cheaper to open).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 25.0 + 30.0 * progress;

        // If a lookahead item could combine with the post residual, opening
        // a fresh bin is more attractive: discount the cost.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 18.0;
        }
        // If this bin is the last chance elsewhere, opening is bad.
        if fitting_bins_count == 1 {
            score += 50.0;
        }
    } else {
        // Reward using existing bins relative to mean residual: bins with
        // less residual than average are closer to closure -> slight bonus.
        if (bin_residual as f64) < mean_residual {
            score -= 8.0;
        }
    }

    // Lookahead coupling: penalize placements that leave a residual exactly
    // unusable by the next item while other gaps could have used it.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimal post-residual, but weight it relative to mean residual
    let mean_r = if mean_residual.is_finite() { mean_residual.max(1.0) } else { bin_capacity as f64 };
    score += (post_residual as f64 - mean_r) * 0.15;

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next_item_size well
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;
        if pr >= nxt {
            // next item fits perfectly after this placement: strong reward
            let match_quality = 1.0 - ((pr - nxt) / bin_capacity as f64);
            score -= 8.0 + 12.0 * match_quality * match_quality;
        } else if pr == 0.0 {
            // bin closed exactly: good, no dead space
            score -= 10.0;
        } else {
            // next item won't fit: penalize dead space scaled by how much it exceeds next item
            let dead = pr - nxt;
            score += 2.0 + dead * 0.08;
        }
    } else {
        // last item: just close bins tightly
        score -= 5.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Penalize opening a new bin when good fitting bins exist
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let pressure = (open_bins_count as f64) / (1.0 + progress * 3.0);
        score += 6.0 + pressure;
        // allow new bin if post_residual would be unusable for typical next item
        if next_item_size > 0 && (post_residual as f64) < next_item_size as f64 {
            score -= 4.0;
        }
    }

    // Slight preference for tighter existing bins as stream progresses
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (bin_residual as f64) * 0.02;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through the stream (0.0 .. 1.0)
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };

    // --- Lookahead synergy: reward bins whose post-residual can host the next item ---
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Perfect chaining: next item exactly fills leftover space -> strong reward
            let gap = (post_residual - next_item_size) as f64;
            score -= 12.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // Leftover too small for next item: penalize dead space, more so if tiny
            let dead = post_residual as f64;
            if dead < 10.0 {
                score += 8.0 * (1.0 - dead / 10.0);
            }
        }
    }

    // --- Last-chance bonus: only this bin can fit the item ---
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // --- Tightness reward: prefer minimal post-residual nonlinearly ---
    let tightness = 1.0 - post_residual as f64 / bin_capacity as f64;
    score -= 6.0 * tightness * tightness;

    // --- Global state coupling: many open bins with high mean residual -> prefer filling existing bins ---
    if open_bins_count > 0 {
        let pressure = mean_residual / bin_capacity as f64;
        if bin_residual < bin_capacity {
            score -= 4.0 * pressure;
        }
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin is attractive only for very large items or when existing
        // bins would be badly fragmented (high mean residual spread, few fitting bins).
        let item_frac = item_size as f64 / bin_capacity as f64;
        let fragmentation = if open_bins_count > 0 {
            (mean_residual - bin_residual as f64).abs() / bin_capacity as f64
        } else {
            0.0
        };
        // Reward new bin for big items late in stream or when alternatives are poor
        let new_bin_bonus = 10.0 * item_frac * item_frac
            + 8.0 * fragmentation
            + 6.0 * progress;
        // But penalize when other bins fit fine (avoid bin proliferation)
        let fit_penalty = if fitting_bins_count > 0 {
            14.0 / fitting_bins_count as f64
        } else {
            0.0
        };
        score += 25.0 - new_bin_bonus - fit_penalty;
        // Perfect-fit lookahead makes a fresh bin more appealing
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let item = item_size as f64;
    let nxt = next_item_size as f64;

    let mut score = post;

    // Smooth polynomial coupling of post_residual with stream progress:
    // late in the stream, tight fits matter more (post_residual weighted up)
    let prog_coupling = post * (0.5 + 1.5 * progress * progress);
    score += 0.35 * prog_coupling - 0.35 * post;

    // Penalize dead space quadratically when small (unusable slivers)
    let dead = post / cap;
    score += 8.0 * dead * dead * (1.0 - dead);

    // Reward near-perfect fills smoothly (post_residual near 0)
    score -= 6.0 * (1.0 - dead) * (1.0 - dead) * dead;

    // Lookahead: if next item fits exactly in the post residual, reward
    if nxt > 0.0 && nxt <= post {
        let fit_ratio = nxt / post.max(1.0);
        score -= 4.0 * fit_ratio * (1.0 - fit_ratio) * 4.0;
    } else if nxt > post {
        score += 2.0 * (nxt - post) / cap;
    }

    // Last-chance bin: strongly favor using it rather than opening a new one
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // Many open bins: prefer consolidating into existing bins
    let ob = open_bins_count as f64;
    score += 0.05 * ob * (1.0 - progress);

    // Mean residual context: prefer bins below mean residual (tighter bins first)
    score += 0.15 * (mean_residual - post);

    // New-bin candidate: penalize opening a new bin unless residual is large
    if (bin_residual as f64 - cap).abs() < 1e-6 {
        score += 10.0 + 5.0 * (1.0 - progress);
        if fitting_bins_count == 0 {
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), with non-linear sharpening.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let frac = post / cap; // capacity fraction of leftover

    // Harmonic class of post_residual: integer-division thresholds.
    // Class 0: post_residual == 0 (perfect fill) -> huge reward.
    // Class 1: post_residual <= 10 (dead-space risk low) -> strong reward.
    // Class 2: post_residual <= 20 -> mild reward.
    // Class 3+: penalize increasingly.
    let class = post_residual / 10;
    match class {
        0 => score -= 60.0,
        1 => score -= 30.0,
        2 => score -= 10.0,
        3 => score += 5.0,
        4 => score += 15.0,
        _ => score += 25.0 + 0.5 * (class as f64),
    }

    // Modulo-arithmetic coupling: residuals that are "harmonious" with common
    // item sizes (multiples of 10, 25) are more likely to be filled later.
    let harmonious = (post_residual % 10 == 0) || (post_residual % 25 == 0);
    if harmonious {
        score -= 8.0;
    } else {
        score += 4.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            let slack = post_residual - next_item_size;
            // prefer bins where next item leaves a small (or harmonious) remainder
            if slack <= 10 {
                score -= 20.0;
            } else if slack % 10 == 0 {
                score -= 12.0;
            } else {
                score -= 4.0;
            }
        } else {
            // next item cannot use this residual: penalize proportional to waste
            let unusable = (next_item_size - post_residual) as f64;
            score += 0.15 * unusable;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: empty bin should only win when no open bin fits well.
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin.
        score += 55.0;
        // Reduce penalty when many open bins exist with large mean residual
        // (open bins are congested / fragmented, a fresh bin is attractive).
        let congestion = (open_bins_count as f64) * (mean_residual / cap);
        score -= congestion.min(50.0);
        // Early in the stream, opening bins is cheap.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 15.0 * (1.0 - progress);
        // If item is large relative to capacity, fresh bin is natural.
        let item_frac = item_size as f64 / cap;
        if item_frac > 0.6 {
            score -= 10.0;
        }
    }

    // Slight global regularization by mean residual: prefer bins below mean
    // residual (fill the emptiest-relative bins less, tightest bins more).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    } else {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 8.0;
    }
    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 25.0;
    } else {
        // Reward tight fits relative to capacity.
        score -= (item_size as f64 / bin_capacity as f64) * 12.0;
    }

    // Penalize bins that are already mostly empty (avoid scattering).
    if (bin_residual as f64) > mean_residual * 1.4 {
        score += 4.0;
    }

    // Open-bin pressure: discourage opening new bins when several are open.
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline penalty grows with open bins and stream progress.
        score += 18.0 + open_bins_count as f64 * 2.5 + (step_index as f64 / total_items.max(1) as f64) * 10.0;
        // If nothing else fits well, new bin becomes attractive.
        if fitting_bins_count == 0 {
            score -= 20.0;
        }
    } else if fitting_bins_count == 1 {
        // Last chance bin: strong reward to avoid opening a new bin.
        score -= 15.0;
    }

    // Lookahead: if the next item could use the post_residual, reward leaving that gap.
    if next_item_size > 0 && post_residual >= next_item_size && post_residual > 0 {
        score -= 6.0 + (next_item_size as f64 / post_residual as f64) * 4.0;
    }
    // Penalize leaving a gap that is just barely too small for the next item.
    if next_item_size > post_residual && post_residual > 0 && post_residual < 15 {
        score += (15 - post_residual) as f64 * 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // New-bin candidate: neutral baseline so it only wins when open bins score poorly.
    if bin_residual == bin_capacity {
        return 120.0 - 0.15 * (post_residual as f64);
    }

    // 2-step lookahead: reward exact match between post_residual and next item size.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 55.0 / (1.0 + diff); // strong bonus as diff -> 0
        // extra jackpot for perfect fill after next item
        if post_residual == next_item_size {
            score -= 40.0;
        }
        // penalize residuals too small for the next item (dead space)
        if post_residual < next_item_size {
            score += 0.35 * (next_item_size - post_residual) as f64;
        }
    } else {
        // last item: prefer tightest fill
        score -= 30.0;
    }

    // Relative-to-mean coupling: bins below mean residual are "richer", prefer filling them.
    score -= 0.25 * (mean_residual - post_residual as f64);

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Penalize leaving awkward mid-range dead space (hard to fill later).
    let pr = post_residual as f64;
    if pr > 0.0 && pr < 10.0 {
        score += 12.0; // tiny unusable slivers
    }

    // Slight preference to consolidate into fewer bins early in the stream.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: best-fit core — tightest residual wins.
    score += 0.5 * (bin_residual as f64 - item_size as f64) / bin_capacity as f64;

    // Penalize dead space that no typical item can use.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny unusable sliver
    }
    if post_residual >= 10 && post_residual < 20 {
        score += 3.0;
    }

    // Lookahead: strongly reward residuals that can still host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 6.0 + 0.05 * slack;
        } else {
            // This placement strands the bin before the next item arrives.
            score += 8.0 + 0.3 * (next_item_size - post_residual) as f64;
        }
        // Perfect pairing: residual exactly matches next item.
        if post_residual == next_item_size {
            score -= 10.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: make it attractive only when open bins are crowded.
    if bin_residual == bin_capacity {
        let pressure = mean_residual / bin_capacity as f64;
        // Baseline new-bin score: neutral, slightly high.
        score = bin_capacity as f64 * 0.6;
        // If existing bins have little room (high pressure), opening a new bin is good.
        score -= 40.0 * pressure;
        // Few fitting bins also favors opening fresh capacity.
        if fitting_bins_count <= 1 {
            score -= 20.0;
        }
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 10.0 * progress;
        // Big items fit best in fresh bins.
        if item_size > bin_capacity / 2 {
            score -= 8.0;
        }
    } else {
        // Reward filling existing bins proportionally to how full the item makes them.
        let fill = item_size as f64 / bin_residual as f64;
        score -= 12.0 * fill;
        // Coupling with global state: many open bins with high mean residual →
        // prefer packing into existing space aggressively.
        if open_bins_count > 3 && mean_residual > item_size as f64 {
            score -= 2.0;
        }
    }

    // Exact fit is always excellent.
    if post_residual == 0 {
        score -= 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr_norm = pr / cap;

    let mut score = pr;

    // smooth non-linear coupling of residual with stream progress
    let poly = pr_norm * pr_norm * (1.0 + progress) - 0.5 * pr_norm * progress * (1.0 - progress);
    score += 40.0 * poly;

    // reward tight fits more aggressively as stream progresses
    let tight = (it / cap).powi(2);
    score -= 30.0 * tight * (0.5 + progress);

    // penalize post residual close to but below smallest plausible item
    let waste = (10.0_f64).min(pr) / 10.0;
    if pr > 0.0 {
        score += 15.0 * (1.0 - waste) * (1.0 - progress);
    }

    // lookahead: favor bins whose post residual fits the next item
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 12.0 * (next_item_size as f64 / cap) * (1.0 + progress);
    }

    // last-chance bonus: avoid opening a new bin when this is the only fitting one
    if fitting_bins_count == 1 {
        score -= 20.0 * (1.0 - progress);
    }

    // discourage proliferation of open bins with large mean residual
    score += 2.0 * open_bins_count as f64 * (mean_residual / cap - pr_norm).abs();

    // new-bin candidate: penalize mildly, allow it when open bins are crowded
    if bin_residual == bin_capacity {
        score += 10.0 - 8.0 * (fitting_bins_count == 0) as i32 as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "small"
    // residue classes are preferred (waste minimization via integer division).
    let class = post_residual / 10; // 0..=10 harmonic class
    score -= (10 - class) as f64 * 3.0; // reward low post-residual classes

    // Penalize dead space that no plausible item (>=1) can ever use is trivial;
    // instead penalize residuals that are unusable relative to lookahead item.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // lookahead fits: strong reward, scaled by how snugly
            let slack = (post_residual - next_item_size) as f64;
            score -= 20.0 - slack.min(20.0);
        } else {
            // lookahead won't fit: penalize proportionally to wasted capacity
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    // Prefer it only when post_residual is large (i.e., item is small) or
    // when open bins are congested.
    if bin_residual == bin_capacity {
        score += 15.0; // base cost of opening a new bin
        if post_residual as f64 > mean_residual * 1.5 {
            score -= 25.0; // item is small; fresh bin keeps big residuals usable
        }
        if open_bins_count == 0 {
            score -= 100.0; // must open
        }
    } else {
        // Existing bin: reward tight fits via modulo harmony on post_residual
        if post_residual % 10 == 0 {
            score -= 5.0; // round residuals align with typical item sizes
        }
        // Prefer bins with below-average residual (fill fuller bins first)
        if (post_residual as f64) < mean_residual {
            score -= 4.0;
        }
    }

    // Early in stream, be more willing to open bins to build a good portfolio
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity && progress < 0.3 {
        score -= 8.0;
    }

    // Penalize very large post-residuals on existing bins (waste) unless lookahead uses them
    if post_residual > 60 && next_item_size > 0 && next_item_size > post_residual {
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small non-zero post_residuals are the worst
    // outcome (space that almost nothing can use). Penalize gaps in the
    // "unusable band" (1..=9) heavily, and taper as gaps become reusable.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64);
    } else if post_residual == 0 {
        // Perfect fit: strongly reward closing the bin exactly.
        score -= 120.0;
    }

    // Reward tight fits relative to bin capacity: low post_residual fraction.
    let residual_frac = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * residual_frac * residual_frac;

    // Dead-space coupling: if post_residual is smaller than the smallest
    // plausible future item (use next_item_size as signal when available),
    // the gap is likely wasted forever.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 25.0 + 0.5 * (next_item_size - post_residual) as f64;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // This bin can also serve the next item: reward chainability.
        score -= 15.0 * (post_residual as f64 / next_item_size as f64).min(3.0);
    }

    // Last-chance pressure: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: with many open bins, avoid spreading; discourage
    // opening new bins when open_bins_count is already high.
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure from open bins.
        score += 20.0 + 8.0 * open_bins_count as f64;
        // Early in the stream, opening bins is cheaper (build capacity).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 30.0 * (1.0 - progress);
    } else {
        // Using an existing bin relieves open-bin pressure slightly.
        score -= 2.0 * open_bins_count as f64;
    }

    // Mean-residual coupling: prefer bins below mean residual (tighter bins
    // first), leaving larger residuals for future larger items.
    score += 0.3 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match of post_residual with next item.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Tight match bonus (strong subtraction when post_residual == next_item_size)
        score -= 60.0 * (1.0 - diff / (next_item_size.max(1) as f64 + post_residual.max(1) as f64));
        // Penalize leaving residual too small for the next item (dead space)
        if post_residual < next_item_size {
            score += 25.0 * (1.0 - post_residual as f64 / next_item_size.max(1) as f64);
        }
    }

    // Penalize large wasted residual relative to mean residual across bins
    let mean_diff = post_residual as f64 - mean_residual;
    score += 0.15 * mean_diff;

    // Last-chance bin: strongly favor using it (avoid opening a new bin)
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Slight bias toward filling tighter bins first
    score -= 0.1 * (item_size as f64 / bin_capacity as f64) * (bin_capacity - post_residual) as f64;

    // Prefer fewer open bins (mild consolidation pressure)
    score += 0.5 * open_bins_count as f64;

    // New-bin candidate: make it costly unless current bin would leave unusable dead space
    if bin_residual == bin_capacity {
        score += 30.0;
        // But allow new bin when no open bin fits well (post_residual tiny relative to capacity)
        if post_residual < 10 {
            score -= 35.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: normalized fill ratio of the item into this bin.
    let fill = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fill * fill;

    // Penalize leaving dead space that is too small for typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // strongly favor this bin; if it nearly fits, penalize.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            score -= 8.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            score += 4.0;
        }
    }

    // Last-chance bonus: this is the only bin that fits; avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when the item is large or no good fit exists.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let big_item = item_size as f64 / bin_capacity as f64;
        score += 20.0 - 18.0 * big_item - 10.0 * (1.0 - progress);
        // Discard new bins when many bins are open and mean residual is high.
        score += 0.05 * open_bins_count as f64 + 0.02 * mean_residual;
    }

    // Prefer fuller bins when many bins are open (consolidation pressure).
    score += 0.03 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let c = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = pr;

    // Smooth non-linear penalty on residual waste, amplified as stream progresses
    let prn = pr / c;
    score += 40.0 * prn * prn * (0.3 + 0.7 * progress);

    // Reward tight fits (near-zero post residual) with smooth exponential bonus
    score -= 30.0 * (-(pr / 8.0)).exp();

    // Penalize creating residual that is too small for typical future items
    // but reward residual that can hold the lookahead item exactly
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        let gap = (pr - ni).abs();
        score -= 12.0 * (-(gap / 15.0)).exp();
        score += 5.0 * (pr / c) * (ni / c);
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0 * (1.0 - 0.5 * progress);
    }

    // Mild preference for bins below mean residual (balancing loads) early on
    score += 3.0 * ((pr - mean_residual) / c) * (1.0 - progress);

    // New-bin candidate: penalize opening bins when open bins fit well
    if bin_residual == bin_capacity {
        score += 20.0 * (1.0 - progress) + 10.0 * (fitting_bins_count as f64).min(5.0) / 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: classify dead space into residue classes mod 10
    let post_class = post_residual % 10;
    // Small residues (1..9) that aren't multiples of 5 are "dead" fragments
    if post_residual > 0 && post_residual < 10 && post_class != 0 {
        score += 40.0; // unusable sliver penalty
    }
    // post_residual in harmonic multiples of 10 is reusable
    if post_residual >= 10 && post_residual % 10 == 0 {
        score -= 15.0;
    }
    // post_residual in [1..9] but multiple of 5 (i.e., 5) is half-dead
    if post_residual == 5 {
        score += 20.0;
    }

    // Integer division thresholds on post_residual
    let post_quarter = post_residual / (bin_capacity / 4);
    match post_quarter {
        0 => score -= 10.0,   // very tight fit, good
        1 => score += 0.0,
        2 => score += 5.0,
        _ => score += 15.0,   // lots left, maybe better bin exists
    }

    // Lookahead coupling: does next item fit in post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Next item fits exactly or leaves harmonic residue
            let next_post = post_residual - next_item_size;
            if next_post == 0 {
                score -= 200.0; // chain of perfect fits
            } else if next_post % 10 == 0 {
                score -= 60.0;
            } else {
                score -= 10.0;
            }
        } else {
            // Next item won't fit here; penalize more if post_residual is a dead class
            let deadness = if post_residual < 10 && post_residual % 5 != 0 { 1.5 } else { 1.0 };
            score += 25.0 * deadness * (next_item_size as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 300.0;
    }

    // New-bin candidate handling: only attractive if no open bin fits well
    if bin_residual == bin_capacity {
        let base_penalty = 120.0;
        // If many bins fit the item, opening a new bin is wasteful
        let crowd = if fitting_bins_count > 0 { fitting_bins_count as f64 } else { 0.0 };
        score = base_penalty + 30.0 * crowd;
        // Early in stream, slightly cheaper to open bins to build a diverse pool
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 60.0 * (1.0 - progress);
        // If next item is large, a fresh bin is valuable
        if next_item_size >= bin_capacity / 2 {
            score -= 80.0;
        }
    }

    // Mean residual alignment: prefer bins whose residual is near the mean
    // (keeps the pool homogeneous, avoids stranding outliers)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.3 * dev;

    // Mild preference for fuller bins as stream matures
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 20.0 * progress * (item_size as f64 / bin_capacity as f64);

    // Tie-break: slight noise-free deterministic jitter from harmonic class
    let harmonic = (post_residual % 7) as f64;
    score += 0.05 * harmonic;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: heavily penalize small unusable gaps (< 10)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }
    // Penalize medium dead zones (10..25) proportionally
    if post_residual >= 10 && post_residual < 25 {
        score += 0.35 * (25.0 - post_residual as f64);
    }

    // Reward exact / near-exact fits
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 12.0;
    }

    // Reward bins whose residual is consumed to a level the next item could fit
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 4.0;
    }
    // Penalize leaving a gap that the known next item cannot use (dead space risk)
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 6.0;
    }

    // Open-bins pressure: discourage spreading when many bins are open
    score += 0.30 * open_bins_count as f64;

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate: make empty bins mildly attractive only when open bins
    // are fragmented (high mean residual relative to capacity)
    if bin_residual == bin_capacity {
        let fragmentation = mean_residual / bin_capacity as f64;
        score -= 3.0 + 10.0 * fragmentation;
        // Late in the stream, prefer consolidation into open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 6.0 * progress;
    }

    // Mild preference for fuller bins overall
    score -= 0.05 * (item_size as f64 / bin_capacity as f64) * 100.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near match: next item fits with little slack left.
    else if next_item_size > 0 && post_residual > next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 * (1.0 - slack / bin_capacity as f64);
    }
    // Next item cannot fit in the leftover: dead space unless post_residual is tiny.
    else if next_item_size > 0 && post_residual < next_item_size {
        let waste = post_residual as f64;
        if waste <= 10.0 {
            score -= 10.0; // small unusable residual is fine
        } else {
            score += 15.0 * (waste / bin_capacity as f64);
        }
    }

    // Compare post_residual against mean residual: creating below-average residual is good (tighter bins).
    let pr = post_residual as f64;
    if pr < mean_residual {
        score -= 0.5 * (mean_residual - pr);
    } else {
        score += 0.3 * (pr - mean_residual);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Penalize leaving large residuals when many bins are open (fragmentation pressure).
    if open_bins_count > 3 && post_residual > 40 {
        score += 0.2 * ((post_residual - 40) as f64);
    }

    // Early in stream: slightly prefer filling fewer bins, i.e. discourage new bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score += 8.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress fraction of the stream
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Reward near-perfect fits strongly (post_residual close to 0)
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 10 {
        score -= 25.0;
    }

    // Lookahead: if next item fits into the post-residual, reward this bin
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 12.0 + 10.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Next item won't fit here; penalize wasted residual proportional to its size
        score += 0.15 * post_residual as f64;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 20.0 + 10.0 * (1.0 - progress);
    }

    // Penalize creating large dead space that likely nothing fits into
    if post_residual > 0 && post_residual < 10 {
        score -= 8.0; // small dead space is fine
    } else if post_residual > 40 {
        score += 5.0; // big leftover is only OK if reusable; lookahead term handles reuse
    }

    // New-bin candidate handling: only attractive when existing bins are fragmented
    if bin_residual == bin_capacity {
        let fragmentation = if open_bins_count > 0 { (mean_residual / bin_capacity as f64).abs() } else { 0.0 };
        // Early in stream or many fragmented bins: opening fresh is OK
        score = 30.0 + 40.0 * progress - 25.0 * fragmentation;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // fresh bin can serve next item too
        }
        // Never open a new bin if this is a perfect fit elsewhere is impossible to know here,
        // but make new bin clearly worse than a zero-residual placement
        if post_residual == 0 { score += 100.0; }
    }

    // Global pressure: few bins relative to items -> conserve, prefer tight fits
    if open_bins_count > 0 {
        let pressure = step_index as f64 / (open_bins_count as f64 * 10.0);
        score -= 3.0 * pressure.min(3.0) * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Mild tie-break: prefer bins with residual close to mean (keeps pool uniform)
    score += 0.05 * ((bin_residual as f64 - mean_residual).abs());

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap;

    // Base: post-residual (favor tight fits), with smooth non-linear shaping
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = x * x * (1.0 - progress) + x * x * x * progress;
    score += 30.0 * poly;

    // Reward when post-residual exactly matches next item (k=2 lookahead), smoothly gated by progress
    if next_item_size > 0 {
        let match_term = (pr - next_item_size as f64).abs();
        score -= 20.0 * (1.0 - match_term / cap).max(0.0) * (0.5 + 0.5 * progress);
    }

    // Last-chance bonus: strongly favor using the only fitting bin, more so late in stream
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 + progress);
    }

    // Penalize bins with much larger residual than mean (avoid hoarding space)
    score += 0.5 * (bin_residual as f64 - mean_residual).max(0.0) * (0.3 + 0.7 * progress);

    // Mild penalty for many open bins late in stream (encourage consolidation)
    score += open_bins_count as f64 * progress * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residuals divisible by 25 are "clean"
    let clean = (post_residual % 25 == 0) as i32;
    score -= 6.0 * clean as f64;

    // Penalize dead space that no plausible item (1..=80) can fill exactly
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Perfect fit is golden
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead: reward if next item fits exactly into post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            score -= 8.0;
        } else {
            score += 5.0;
        }
        // Harmonic compatibility: next item in same quarter-class as residual
        let q_r = post_residual / 25;
        let q_n = next_item_size as u32 / 25;
        if q_r == q_n {
            score -= 4.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening fresh bins unless current fit is terrible
    if bin_residual == bin_capacity {
        score += 15.0 + mean_residual * 0.3;
        if post_residual < 20 {
            score += 10.0;
        }
    }

    // Tight fit reward: item fills most of the residual
    let fill = item_size as f64 / bin_residual.max(1) as f64;
    score -= 10.0 * fill;

    // Waste penalty scaled by stream progress (be more conservative late)
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 12.0 * (post_residual as f64 / bin_capacity as f64) * (0.5 + 0.5 * progress);

    // Prefer spreading across many open bins when mean residual is high
    if mean_residual > 30.0 && post_residual as f64 >= mean_residual {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals in [1, 10] are nearly unusable
    // (items are >= 1 but typical sizes are large), so penalize them hard.
    if post_residual > 0 && post_residual <= 10 {
        score += 40.0 + 3.0 * (10 - post_residual) as f64;
    }
    // Perfect fit is ideal.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Reward tight fits relative to the bin residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fit_ratio;

    // Last chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // Open-bin pressure: when many bins are open, discourage spreading;
    // when few bins are open, opening a new bin is less costly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 2.0 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Mean residual coupling: prefer bins with residual close to the mean
    // (keeps bin states homogeneous, easier to pack future items).
    score += 0.3 * (bin_residual as f64 - mean_residual).abs();

    // New-bin candidate: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        let base = 55.0 + 3.0 * open_bins_count as f64;
        // If the next item could use the leftover space, avoid new bin.
        if next_item_size > 0 && next_item_size <= post_residual {
            score = base + 30.0;
        } else {
            score = base;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base tightness: reward small post_residual
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 100.0;
    }

    // Aggressive 2-step lookahead: if next item fits exactly in post_residual, strong bonus
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 90.0;
        } else if next_item_size < post_residual {
            let next_waste = post_residual - next_item_size;
            score -= 50.0 * (1.0 - next_waste as f64 / bin_capacity as f64);
        } else {
            // next item cannot fit here: penalize leaving a gap that's too small for next item
            let gap = next_item_size - post_residual;
            if post_residual > 0 {
                score += 15.0 * (1.0 - gap as f64 / next_item_size as f64);
            }
        }
    }

    // Relative to mean residual: prefer bins with residuals below mean (tighter bins)
    let diff = post_residual as f64 - mean_residual;
    score += 0.3 * diff;

    // Last-chance bin: strong reward to use it instead of opening new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 70.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are nearly full / bad fits
    if bin_residual == bin_capacity {
        let avg_fullness = 1.0 - mean_residual / bin_capacity as f64;
        // if open bins are mostly full, opening a new bin is fine
        score += 30.0 * (1.0 - avg_fullness);
        if fitting_bins_count > 0 {
            score += 45.0; // discourage abandoning usable bins
        }
    }

    // Early stream: keep bins open and flexible slightly more
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress ratio through the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Exact fit reward: strong bonus for leaving zero residual.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Tight fit: penalize large dead space quadratically.
    score += (post_residual as f64) * (post_residual as f64) * 0.01;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 300.0;
    }

    // New-bin candidate: penalize opening a new bin unless the fit is poor
    // or many bins are open with low residuals.
    if bin_residual == bin_capacity {
        let avg_pressure = mean_residual / bin_capacity as f64;
        // Early in stream: prefer filling existing bins; late: more willing to open.
        let new_bin_penalty = 500.0 - 300.0 * progress;
        score += new_bin_penalty + 50.0 * avg_pressure;
        // If next item is large and this item is small, new bin may help.
        if next_item_size as f64 > item_size as f64 + 20.0 {
            score -= 150.0;
        }
    }

    // Lookahead: reward placements that leave room for the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 60.0;
        } else if post_residual > 0 {
            // Dead space relative to next item: penalize.
            let waste = next_item_size as f64 - post_residual as f64;
            score += waste * 0.5;
        }
    }

    // Prefer bins with residual close to item size (best-fit behavior).
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += tightness * 40.0;

    // Prefer filling bins that are already mostly full (low residual).
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Slight preference for consolidating into fewer bins when many are open.
    score += open_bins_count as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let post = post_residual as f64;
    let cap = bin_capacity as f64;
    let post_norm = post / cap;
    let item = item_size as f64;

    let mut score = post;

    // Non-linear coupling of post_residual with stream progress:
    // later in the stream, compactness matters more (post_residual penalized quadratically).
    let progress_coupling = post_norm * post_norm * (0.5 + 2.0 * progress);
    score += 100.0 * progress_coupling;

    // Smooth reward for tight fits, modulated by progress.
    let tightness = 1.0 - post_norm;
    score -= 40.0 * tightness * tightness * (0.3 + progress);

    // Penalize leaving residual that fails to fit the next item (smooth interaction).
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let gap = (post - next).max(0.0);
        let shortfall = (next - post).max(0.0);
        score += 0.6 * gap * (0.5 + progress);
        score += 0.8 * shortfall * (1.0 + progress);
    }

    // Last-chance bin: reward using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0 * (0.5 + progress);
    }

    // Mild penalty proportional to open bins count (prefer consolidation).
    score += 0.5 * open_bins_count as f64 * post_norm;

    // Penalize deviations from mean residual (prefer balanced bins), smooth quadratic.
    let dev = post - mean_residual;
    score += 0.15 * dev * dev / cap;

    // New-bin candidate: baseline so it only wins when fits are poor.
    if bin_residual == bin_capacity {
        score += 60.0 + 40.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit is ideal
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: dead space buckets.
    // Residuals < 10 are nearly unusable (min item size ~1 but small items rare);
    // treat tiny residuals as "closed" bins and reward them.
    if post_residual < 10 && post_residual > 0 {
        score -= 50.0 + (10 - post_residual) as f64 * 2.0;
    }

    // Modulo-10 class: residuals that are multiples of 10 are "harmonic" —
    // likely to be exactly filled by future items aligned to decile sizes.
    let harmonic = post_residual % 10 == 0;
    if harmonic {
        score -= 8.0;
    } else {
        // Non-harmonic residuals: penalize by distance to nearest multiple of 10
        let d = (post_residual % 10).min(10 - post_residual % 10);
        score += d as f64 * 1.5;
    }

    // Integer-division thresholds: residual in [25, 50) vs [50, 75) vs [75, 100)
    let class = post_residual / 25;
    score += class as f64 * 5.0; // prefer filling fuller bins (lower class = fuller = lower score)

    // Lookahead: if next item fits exactly into post_residual, strong reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 200.0;
        } else if next_item_size <= post_residual {
            // next fits: reward proportionally to how well it fills
            let fill = next_item_size as f64 / post_residual as f64;
            score -= 30.0 * fill;
            // harmonic chain: next leaves a multiple-of-10 residual too
            if (post_residual - next_item_size) % 10 == 0 {
                score -= 15.0;
            }
        } else {
            // next item won't fit here: this bin is dead for the future —
            // penalize leftover space that will be wasted
            score += post_residual as f64 * 0.4;
        }
    }

    // Last-chance bin: only one fitting bin — avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // New-bin candidate handling: empty bin gets a mild penalty so we prefer
    // reusing open bins unless the fit is poor; the base post_residual (=100)
    // already makes it look large.
    if bin_residual == bin_capacity {
        // Opening a new bin is fine when current bins are quite full or many bins open
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 + mean_residual * 0.2 - progress * 10.0 - open_bins_count as f64 * 0.5;
    }

    // Slight preference to use bins whose residual is above average (balance)
    if (bin_residual as f64) > mean_residual {
        score -= 3.0;
    } else {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable dead space: gaps that cannot fit typical items
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual <= 30 {
        // Moderate dead space: penalize proportionally, more when it can't fit the next item
        score += 8.0;
        if next_item_size > 0 && next_item_size > post_residual {
            score += 12.0;
        }
    }

    // Reward near-perfect fits strongly
    if post_residual == 0 {
        score -= 80.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open bins pressure: when many bins are open, discourage opening new ones
    let open_pressure = open_bins_count as f64 * 0.5;
    if bin_residual == bin_capacity {
        score += 15.0 + open_pressure;
    } else {
        score -= open_pressure * 0.1;
    }

    // Lookahead: reward bins whose post_residual can fit the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 5.0;
    }

    // Stream progression: late in the stream, be more aggressive about filling existing bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= progress * 5.0;
    }

    // Slight preference for bins below mean residual (tighter bins first)
    score += (bin_residual as f64 - mean_residual) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), but penalize unusable slivers.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // dead space smaller than the minimum item size is wasted
    }

    // 2-step lookahead: reward when next item exactly fills the residual.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score += diff * 0.8;
        if post_residual == next_item_size {
            score -= 60.0; // perfect 2-step match
        } else if post_residual > next_item_size {
            // next item fits: good, but the remaining chain matters
            score -= 10.0;
        } else {
            // next item won't fit in this bin afterwards
            score += 5.0;
        }
        // if next item is bigger than any residual, prefer leaving larger residual
        if next_item_size > post_residual {
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Compare against mean residual: bins far above mean are "loose"; filling them is cheap.
    score -= (mean_residual - post_residual as f64) * 0.25;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // New-bin candidate (empty bin): penalize so we only open when fits are poor,
    // but relax as stream progresses or when many bins are open.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 45.0 - 20.0 * progress;
        // if next item is large, a fresh bin is more valuable
        if next_item_size > 50 {
            score -= 15.0;
        }
    }

    // Mild preference to consolidate into fewer bins.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize large post_residual non-linearly.
    if post_residual > 0 {
        score += (post_residual as f64).powi(2) / (bin_capacity as f64);
    } else {
        score -= 25.0; // perfect fit bonus
    }

    // Lookahead: reward bins whose post_residual can still host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 + 0.15 * (next_item_size as f64);
    } else if next_item_size > 0 && post_residual > 0 {
        // Dead space that next item cannot use: penalize more when many bins are open.
        score += 4.0 + 0.05 * open_bins_count as f64;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Time horizon: early on, be conservative (keep residuals flexible); late, squeeze tightly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 10.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Global residual context: prefer bins whose residual deviates favorably from mean.
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // New-bin candidate: only attractive when nothing fits well (large item, few options).
    if bin_residual == bin_capacity {
        let poor_fit = (item_size as f64 / bin_capacity as f64) > 0.8 || fitting_bins_count <= 1;
        if poor_fit {
            score -= 12.0;
        } else {
            score += 30.0;
        }
    }

    // Mild penalty for spreading across many open bins when residuals are large.
    score += 0.02 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;

    // Base: prefer tight fits (low post residual), with polynomial shaping
    let mut score = pr * (1.0 + 0.6 * norm_pr * norm_pr);

    // Non-linear coupling of post residual with stream progress:
    // early on, tolerate leftover space; late in the stream, penalize it harder
    score += 12.0 * norm_pr * (0.5 + progress * progress);

    // Reward near-perfect fills, stronger as stream progresses
    let perfect = (norm_pr * (1.0 - norm_pr)).max(0.0); // peaks at norm_pr ~ 0.5
    score -= 6.0 * perfect * (1.0 + progress);

    // Lookahead: penalize if leftover cannot fit next item, reward if it can exactly
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if pr >= ni {
            let slack = (pr - ni) as f64;
            score -= 3.0 * (1.0 - slack / cap);
        } else {
            score += 4.0 * (ni - pr) / cap;
        }
    }

    // Last-chance bonus: avoid opening a new bin when this is the only fitting bin
    if fitting_bins_count == 1 {
        score -= 8.0 * (1.0 - progress);
    }

    // New-bin candidate: mildly penalize unless current residual is very tight
    if bin_residual == bin_capacity {
        score += 2.0 + 10.0 * norm_item * (1.0 - progress);
        if norm_item > 0.7 {
            score -= 3.0; // big items justify fresh bins
        }
    }

    // Mild penalty for spreading across many open bins
    score += 0.15 * open_bins_count as f64 * norm_pr;

    // Dead-space penalty for small unusable leftovers
    if pr < 10.0 {
        score -= 2.0 * (10.0 - pr) / 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residues divisible by 10 are "clean"
    // (likely to absorb future items of typical granularity), odd residues are dead space.
    let pr = post_residual as u32;
    let residue_class = pr % 10;
    if residue_class == 0 {
        score -= 8.0;
    } else if residue_class <= 2 || residue_class >= 8 {
        score += 6.0;
    } else {
        score += 2.0;
    }

    // Integer-division thresholds: post_residual in low bands is efficient packing.
    let quarter = bin_capacity / 4;
    if pr < quarter / 2 {
        score -= 5.0;
    } else if pr <= quarter {
        score -= 2.0;
    } else if pr > bin_capacity / 2 {
        score += 4.0;
    }

    // Lookahead coupling: reward exact fit for the next item's harmonic class.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 30.0;
        } else if pr >= next_item_size && (pr - next_item_size) % 10 == 0 {
            score -= 10.0;
        } else if pr < next_item_size {
            score += 3.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: penalize mildly so we prefer reusing bins unless fit is bad.
    if bin_residual == bin_capacity {
        score += 15.0 + 0.5 * open_bins_count as f64;
        // But allow a fresh bin for large items that leave a clean residue.
        if item_size % 10 == 0 {
            score -= 10.0;
        }
    }

    // Slight preference for tightest bins early, spreading later in the stream.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (bin_residual as f64 - mean_residual) * 0.1 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (< 10, min item size)
    // are worthless; penalize them heavily, scaled by how tight the fit was.
    if post_residual < 10 {
        score -= 60.0; // perfect fill: highly desirable
    } else {
        // Waste fraction of the bin: the more of the bin left as residue,
        // the less attractive this bin relative to a fresh one.
        let waste_frac = post_residual as f64 / bin_capacity as f64;
        score += 40.0 * waste_frac * waste_frac;

        // Dead-zone: residues that no future item (10..100) can efficiently use
        if post_residual < 20 {
            score += 25.0;
        } else if post_residual < 35 {
            score += 10.0;
        }
    }

    // Reward bins whose residual exactly accommodates the next item (lookahead)
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack == 0 {
            score -= 30.0; // next item fills this bin perfectly
        } else if slack < 10 {
            score -= 12.0;
        }
    } else if next_item_size > 0 && post_residual < next_item_size {
        // This bin becomes useless for the next item; mild penalty unless it was a near-perfect fit now
        if post_residual < 10 {
            score -= 5.0; // still fine, bin is essentially closed
        } else {
            score += 8.0;
        }
    }

    // Last-chance bonus: if only this bin fits, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: prefer compacting into existing bins when many are open
    score += open_bins_count as f64 * 0.35;

    // Early stream: be slightly greedier toward existing bins to keep bin count low
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= (1.0 - progress) * 4.0;

    // Deviation from mean residual: prefer bins tighter than average (best-fit style)
    score += (mean_residual - bin_residual as f64) * 0.3;

    // New-bin candidate: make it attractive only when this bin would be left with
    // a large, likely-unusable residue and the item is big.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin
        score += 18.0;
        // But if placing here would strand a big residue in an existing bin,
        // opening fresh is better: the new-bin residual (100 - item) is maximal usable space.
        if post_residual > 40 {
            score -= 30.0;
        }
        if item_size >= 60 {
            score -= 10.0; // big items pair well with a fresh bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual
    // exactly matches the next item size (perfect chaining).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual > next_item_size {
            // next item fits here afterwards; mild reward, tighter is better
            score -= 8.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // next item cannot use the leftover: penalize dead space
            score += 0.6 * (next_item_size - post_residual) as f64;
        }
    }

    // Exact fit of the current item is always excellent.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Small unusable leftovers are dead space unless they match lookahead.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Compare residual against the mean: prefer placing into bins that
    // are already emptier than average (balance load across bins).
    score += 0.35 * (post_residual as f64 - mean_residual);

    // New-bin candidate handling: only attractive when no open bin fits
    // well (many bins competing means we should reuse).
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let pressure = if fitting_bins_count > 0 { fitting_bins_count as f64 } else { 8.0 };
        score += 20.0 + 3.0 * pressure.min(15.0);
        // Early in the stream, opening bins is cheap and useful.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 15.0 * (1.0 - progress);
    }

    // Slight preference for tight fits relative to bin capacity.
    score += 0.1 * (bin_residual as f64 - item_size as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fits are excellent: reward low post_residual non-linearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that no future item (>=10) can use.
    if post_residual < 10 && post_residual > 0 {
        score += 6.0;
    }

    // Lookahead: if the next item fits exactly into the post-residual, strongly favor this bin.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 8.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            score += 3.0;
        }
    }

    // Last-chance bin: avoid opening a new bin when this is the only fitting one.
    if fitting_bins_count == 1 {
        score -= 5.0;
    } else {
        score += 1.5 * (fitting_bins_count as f64 - 1.0).min(4.0);
    }

    // Prefer filling bins that are already relatively full compared to the fleet mean.
    let rel_fullness = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    score -= 4.0 * rel_fullness;

    // Time horizon: late in the stream, be more conservative about spreading across bins;
    // early on, tolerate opening bins to preserve flexibility.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: open early for flexibility, discourage late when many bins are open.
        let openness = (open_bins_count as f64).ln() + 1.0;
        score += 4.0 + 6.0 * progress * openness;
    } else {
        score += 2.0 * progress * (post_residual as f64 / bin_capacity as f64);
    }

    // Mild pressure to use bins when many are open (consolidation).
    score += 0.15 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64) / (total_items.max(1) as f64);
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;

    // Base: prefer small post-residual (tight fit) with a non-linear penalty
    let mut score = post;

    // Smooth normalized tightness: fraction of bin consumed by this placement
    let fill = item / cap;
    let tightness = (fill * (2.0 - fill)).powi(3); // peaks near perfect fill
    score -= 30.0 * tightness * (1.0 + progress);

    // Non-linear coupling of post_residual with stream progress:
    // early on, dead space is more tolerable; later, penalize it super-linearly
    let post_norm = post / cap;
    score += post_norm.powf(1.5 + 1.5 * progress) * (20.0 + 40.0 * progress);

    // Lookahead: reward if the next item exactly fills the post-residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let match_frac = 1.0 - ((post - nxt) / cap);
            score -= 15.0 * match_frac.powi(2);
        } else {
            // next item cannot fit here: mild penalty scaled by excess
            score += ((nxt - post) / cap).powi(2) * 10.0;
        }
    }

    // Last-chance bin: strongly reward using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0 + 20.0 * progress;
    }

    // Fragmentation context: if this bin's residual is far below the mean,
    // finishing it off (small post) is extra valuable
    let dev = (mean_residual - bin_residual as f64) / cap;
    score += dev.abs().powi(2) * 8.0 - 5.0 * dev;

    // Mild pressure against accumulating many open bins early
    score += (open_bins_count as f64).sqrt() * (1.0 - progress) * 2.0;

    // New-bin candidate: make empty bin moderately attractive only when
    // this placement would leave a very awkward residual
    if bin_residual == bin_capacity {
        score = 45.0 - 20.0 * post_norm.powf(2.0 + 2.0 * progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += fit_ratio * 30.0;

    // Harmonic classes on post_residual: classify leftover space by integer division bands
    let class = post_residual / 10; // 0..10 harmonic class
    score += match class {
        0 => -50.0,          // near-perfect fill
        1 => -20.0,          // very good
        2 | 3 => -5.0,       // decent
        4 | 5 => 8.0,        // mediocre
        6 | 7 => 15.0,       // poor
        _ => 25.0,           // mostly empty bin used badly
    };

    // Modulo arithmetic: residuals divisible by common item sizes are reusable
    if post_residual > 0 {
        let mut reuse_bonus = 0.0;
        for m in [10u32, 20, 25, 50] {
            if post_residual % m == 0 {
                reuse_bonus += 12.0;
            }
        }
        score -= reuse_bonus;
    }

    // Lookahead: penalize if this placement leaves post_residual that cannot fit next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 18.0; // chain-friendly placement
            // extra reward if post_residual exactly matches next item class
            if post_residual % 10 == 0 && next_item_size % 10 == 0
                && post_residual / 10 == next_item_size / 10 {
                score -= 15.0;
            }
        } else {
            score += 10.0; // dead space for the lookahead item
        }
    }

    // Last-chance bin logic
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when current fit is terrible
    if bin_residual == bin_capacity {
        if post_residual as f64 > bin_capacity as f64 * 0.5 && fitting_bins_count > 0 {
            score += 40.0; // don't open new bin for a wasteful fit
        } else if fitting_bins_count == 0 {
            score -= 100.0; // must open new bin
        } else {
            score += 5.0;
        }
    }

    // Mild pressure toward consolidating open bins
    score += open_bins_count as f64 * 0.5;

    // Slight preference to fill bins more as stream progresses
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (mean_residual - post_residual as f64) * 0.1 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the minimum item (1..=10)
    // are worthless; penalize them quadratically.
    if post_residual > 0 && post_residual < 11 {
        score += (11 - post_residual) as f64 * (11 - post_residual) as f64 * 2.5;
    }
    // Perfect fit is heavily rewarded.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Reward residual that can still fit the lookahead item (k=2 lookahead synergy).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0 + 0.15 * next_item_size as f64;
        } else if post_residual > 0 {
            // Lookahead cannot fit here: mild penalty proportional to waste.
            score += 0.1 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // Open-bin pressure: discourage spreading across many bins unless the fit is good.
    score += 0.05 * open_bins_count as f64;

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive when the
    // item is large or existing residuals are poor fits.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let poor_fit_penalty = if post_residual < 11 { 20.0 } else { 0.0 };
        score += 30.0 - 0.4 * item_size as f64 + poor_fit_penalty - 10.0 * progress;
        // If the next item could pair with this item in a fresh bin, encourage it.
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 5.0;
        }
    }

    // Slight preference for bins below mean residual (consolidate emptier space usage).
    score += 0.05 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit is perfect.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward bins whose post_residual can host the next item exactly.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 60.0;
        if post_residual == next_item_size {
            score -= 240.0; // chain of perfect fits
        }
        // small leftover after hypothetical next placement
        let second_residual = post_residual - next_item_size;
        score -= 0.5 * second_residual as f64;
    } else if next_item_size > 0 {
        // next item cannot use this bin's leftover: penalize wasted space
        score += 0.3 * post_residual as f64;
    }

    // Relative-to-mean coupling: prefer bins tighter than average.
    let residual_f = bin_residual as f64;
    score += 0.4 * (residual_f - mean_residual);

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: penalize moderately so we only open when fits are poor.
    if bin_residual == bin_capacity {
        score += 120.0 + 0.5 * mean_residual;
        // but if current item is huge and mean residual is small, opening is fine
        if (item_size as f64) > mean_residual {
            score -= 90.0;
        }
    }

    // Late-stream tightening: keep bins closed efficiently near the end.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Prefer tight fits: reward small post_residual non-linearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize dead space that can never fit a typical next item.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 8.0 + (next_item_size - post_residual) as f64 * 0.25;
        } else {
            // Reward bins that can also hold the lookahead item (chained fit).
            score -= 6.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Mild penalty for spreading across many open bins when residuals are plentiful.
    let pressure = mean_residual / bin_capacity as f64;
    if pressure > 0.5 {
        score += 3.0 * (open_bins_count as f64).ln().max(0.0);
    }

    // Time horizon: early in the stream, be conservative (favor new bins slightly
    // to preserve flexibility); late in the stream, fill aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress * tightness;

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let escape = (post_residual as f64) - 0.5 * mean_residual;
        score += 12.0 + escape.max(0.0);
        if fitting_bins_count == 0 {
            score -= 30.0; // no open bin fits: new bin is necessary
        }
    }

    // Exact-fill reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post;

    // Tightness reward: non-linearly favor small post-residual (good fill).
    let tightness = (post / cap).powi(2);
    score -= (1.0 - tightness) * 12.0 * (1.0 + progress);

    // Penalize dead space that cannot serve the lookahead item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post < nxt {
            score += 8.0 + (nxt - post) * 0.35 * (1.0 + progress);
        } else {
            // Reward leaving exactly the space the next item needs (smooth coupling).
            let gap = (post - nxt) / cap;
            score -= 6.0 * (-gap * 6.0).exp();
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0).ln().max(0.0);
    }

    // New-bin candidate: make it attractive only when existing residuals are poor fits.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let mean_gap = (mean_residual - item_size as f64).abs();
        score = cap * 0.9 + mean_gap * 0.5 - 10.0 * (1.0 - progress);
        // Discourage hoarding many open bins late in the stream.
        score += open_bins_count as f64 * 0.8;
    } else {
        // Mild penalty for bins deviating from mean residual (fragmentation control).
        let dev = (bin_residual as f64 - mean_residual).abs() / cap;
        score += dev * 4.0;
    }

    // Smooth stream-progress coupling: later items prefer tighter packing overall.
    score -= (post / cap) * 5.0 * progress.sin();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues divisible by small classes are more reusable
    let pr = post_residual;
    let mut reusability = 0.0;
    if pr % 10 == 0 { reusability += 3.0; }
    if pr % 25 == 0 { reusability += 2.5; }
    if pr % 20 == 0 { reusability += 1.5; }
    if pr % 50 == 0 { reusability += 2.0; }
    score -= reusability;

    // Dead space penalty: small odd residuals are hard to fill
    if pr > 0 && pr < 10 {
        score += 12.0;
    } else if pr < 20 && pr % 2 == 1 {
        score += 4.0;
    }

    // Perfect fit bonus
    if pr == 0 {
        score -= 30.0;
    }

    // Lookahead harmony: does post_residual pair with the next item?
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 25.0; // exact pairing next step
        } else if pr >= next_item_size {
            let gap = pr - next_item_size;
            if gap % 10 == 0 { score -= 8.0; }
            score += gap as f64 * 0.15;
        } else {
            score += 6.0; // next item can't use this bin's leftover
        }
    }

    // Last chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening bins early unless current fit is terrible
    if bin_residual == bin_capacity {
        let tightness = (post_residual as f64 / cap).abs();
        score += 5.0 + 10.0 * (1.0 - tightness);
        if fitting_bins_count > 0 && (bin_residual - item_size) < 15 {
            score -= 20.0; // allow new bin if existing fit leaves tiny waste... actually prefer existing tight fit
        }
    }

    // Fractional capacity coupling: items near half/full capacity prefer matching residuals
    let half = cap / 2.0;
    let if_ratio = item_size as f64 / cap;
    if (if_ratio - 0.5).abs() < 0.05 && (bin_residual as f64 - half).abs() < 0.05 * cap {
        score -= 6.0;
    }

    // Mild stream-progress scaling of dead-space penalty
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (pr as f64 / cap) * (1.0 + progress) * 2.0;

    // Prefer consolidating among many open bins
    score += open_bins_count as f64 * 0.05;

    // Distance from mean residual: prefer bins near/below mean waste
    score -= (mean_residual - post_residual as f64).max(0.0) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small to hold the smallest plausible item are waste.
    if post_residual > 0 {
        if post_residual < 10 {
            score += 40.0; // unusable sliver
        } else if post_residual < 20 {
            score += 18.0; // near-unusable gap
        } else if post_residual < 35 {
            score += 6.0;  // marginal gap
        }
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Last-chance pressure: if this is the only bin that fits, prefer using it
    // over opening a new bin (penalize new-bin candidate implicitly via this bonus).
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Open-bin pressure: when many bins are open, discourage spreading; but
    // when few bins are open, allow opening new bins to keep flexibility.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let bin_pressure = open_bins_count as f64 * (0.5 + 0.5 * progress);
    score += bin_pressure * 0.3;

    // New-bin candidate handling: an empty bin should only win when the fit is bad.
    if bin_residual == bin_capacity {
        // Base reluctance to open a new bin; reduced when current fit is poor
        // (large post_residual relative to capacity) or many bins already open.
        let poor_fit = post_residual as f64 / bin_capacity as f64;
        score += 55.0 - 45.0 * poor_fit;
        // Late in the stream, closing gaps matters more: make new bins less attractive.
        score += 20.0 * progress;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap_after_next = post_residual - next_item_size;
        if gap_after_next == 0 {
            score -= 35.0;
        } else if gap_after_next < 10 {
            score -= 12.0;
        } else {
            score -= 5.0;
        }
    }

    // Slight pull toward bins whose residual deviates least from the mean (balance).
    score += ((bin_residual as f64 - mean_residual) / bin_capacity as f64).abs() * 4.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strongly reward closing the bin exactly.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: reward if the next item fits exactly
    // into the post residual; penalize if it cannot fit at all.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual < next_item_size {
            // Dead space for the lookahead item: penalize proportionally.
            let waste = (next_item_size - post_residual) as f64;
            score += 0.5 * waste;
        } else {
            // Next item fits: slight reward for tighter residual match.
            score -= 0.2 * (post_residual - next_item_size) as f64;
        }
    }

    // Relative-to-mean-residual term: prefer bins whose post residual
    // deviates favorably (smaller) from the current mean residual.
    score += 0.3 * (post_residual as f64 - mean_residual);

    // Last-chance bin: if this is the only bin that can fit the item,
    // strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate handling: make an empty bin attractive only when
    // no open bin offers a good fit (large item or tight residuals).
    if bin_residual == bin_capacity {
        let tight_open = open_bins_count > 0
            && (mean_residual < item_size as f64 * 1.05
                || item_size > 60);
        if tight_open {
            score -= 50.0; // allow opening a fresh bin
        } else {
            score += 150.0; // discourage wasting a fresh bin
        }
    }

    // Late-stream consolidation: as the stream progresses, prefer
    // filling existing bins tighter to reduce final bin count.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.4 * progress * post_residual as f64;

    // Slight preference for bins with larger residual overall
    // (use big bins for big items implicitly via post_residual already).
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fits are excellent: reward small post-residual relative to capacity.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Exact or near-exact fill: massive reward.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    }

    // Lookahead: if the next item fits into post_residual, reward this placement.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 8.0 * (1.0 - slack / (bin_capacity as f64));
        } else {
            // Penalize placements that leave a gap just barely too small for next item.
            let miss = (next_item_size - post_residual) as f64;
            if miss <= 20.0 {
                score += 0.6 * miss;
            }
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate (empty bin): penalize when decent open fits exist,
    // but allow opening when open bins would waste space or none fit well.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        let waste = (post_residual as f64) - (mean_residual - item_size as f64).abs();
        if waste > 0.0 {
            score += 0.5 * waste;
        }
        // Early in the stream, opening bins is cheaper; later, consolidate.
        let t = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 * t;
        // If the item is large and mean residual is small, new bin is fine.
        if item_size as f64 > mean_residual {
            score -= 10.0;
        }
        // Don't open a new bin if an existing bin would be left nearly full anyway.
        if fitting_bins_count > 0 && post_residual as f64 > mean_residual + 15.0 {
            score += 15.0;
        }
    }

    // Slight penalty for leaving dead space that is too small for typical items (1..100 unknown).
    if post_residual > 0 && post_residual < 10 {
        score += 5.0;
    }

    // Mild consolidation pressure: prefer bins with smaller residuals among equals.
    score += 0.05 * (bin_residual as f64 - mean_residual).abs();

    // Jitter-free deterministic tiebreak by residual to stabilize selection.
    score += 0.001 * bin_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let mut score = pr;

    // Smooth interaction: residual value weighted by progress-dependent curvature
    let curve = 1.0 + 0.8 * progress * (1.0 - progress) * 4.0; // peaks mid-stream
    score *= curve;

    // Penalize large residuals more strongly as stream progresses (dead space matters later)
    let dead = norm_pr * norm_pr * (0.5 + progress);
    score += 60.0 * dead;

    // Reward tight fits (small post_residual) with a smooth quadratic discount
    score -= 40.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * (1.0 - progress);

    // Lookahead: reward leaving room for the next item smoothly
    let nis = next_item_size as f64;
    if nis > 0.0 {
        let fits_next = (pr - nis).max(0.0);
        let next_util = nis / cap;
        score += 10.0 * (fits_next / cap) * (0.3 + next_util);
        // smooth bonus if next item exactly fits remaining space
        let exact = 1.0 - (pr - nis).abs() / cap;
        score -= 15.0 * exact * exact * (1.0 - progress);
    }

    // Last-chance bin: strong smooth discount to use it before opening a new one
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - progress * 0.5);
    }

    // Mild pressure to prefer fuller bins among many open bins
    score += 2.0 * (open_bins_count as f64).ln() * norm_pr;

    // Mean residual coupling: penalize deviating far from mean residual smoothly
    let dev = (pr - mean_residual) / cap;
    score += 8.0 * dev * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover is divisible by small
    // moduli tend to recombine better with future items.
    let pr = post_residual;
    if pr > 0 {
        if pr % 10 == 0 { score -= 12.0; }
        if pr % 5 == 0 { score -= 4.0; }
        if pr % 2 == 0 { score -= 2.0; }
        // Very small dead space classes are near-useless
        if pr < 10 { score += 25.0; }
        if pr <= 3 { score += 20.0; }
    } else {
        // Perfect fill is ideal
        score -= 30.0;
    }

    // Integer-division threshold coupling: leftover in [20, 40] pairs well with
    // typical mid-size items; leftover in [50, 100] is flexible.
    let q = pr / 25; // 0..=4 harmonic band
    score -= match q { 0 => 0.0, 1 => 6.0, 2 => 10.0, 3 => 8.0, _ => 12.0 };

    // Lookahead: reward if next item fits the post residual (modulo alignment)
    if next_item_size > 0 {
        if next_item_size <= pr {
            score -= 15.0;
            // exact modulo harmony between next item and leftover band
            if pr % next_item_size.max(1) == 0 { score -= 8.0; }
        } else {
            score += 5.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: neutral-ish baseline, only attractive when open bins are crowded
    if bin_residual == bin_capacity {
        score += 55.0
            - 0.35 * mean_residual
            - 2.0 * open_bins_count as f64
            + (step_index as f64 / (total_items as f64).max(1.0)) * 10.0;
        if next_item_size > 0 && next_item_size > bin_capacity - item_size {
            score -= 10.0; // next item won't fit here anyway; fresh bin still fine
        }
    }

    // Mild preference for tight bins as stream matures
    let progress = step_index as f64 / (total_items as f64).max(1.0);
    score -= progress * (bin_capacity - bin_residual) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit is perfect: heavily reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Strict dead-space avoidance: penalize unusable small gaps.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 25.0;
    }

    // Reward post_residuals that can still fit typical small items (>=10).
    if post_residual >= 10 {
        score -= 15.0;
    }

    // Lookahead: if next item fits the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0;
    }
    // If next item would NOT fit even in a fresh bin region, no extra pressure.

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // Open bins pressure: when many bins are open, discourage opening new bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let new_bin_bonus = 60.0 + 80.0 * (1.0 - progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline penalty grows with open bins count.
        score += new_bin_bonus + open_bins_count as f64 * 5.0;
        // But if the item is large and current bin fits poorly, new bin is fine.
        if item_size as f64 > 0.6 * bin_capacity as f64 {
            score -= 50.0;
        }
        // If mean residual across open bins is small (all bins tight), opening a
        // new bin is reasonable.
        if mean_residual < item_size as f64 {
            score -= 30.0;
        }
    } else {
        // Using an existing bin slightly reduces open-bin pressure.
        score -= open_bins_count as f64 * 0.5;
        // Prefer bins whose residual is closest above the item (tight fit).
        score += (bin_residual - item_size) as f64 * 0.1;
    }

    // Mild preference for filling fuller bins overall.
    score -= (1.0 - (bin_residual as f64 / bin_capacity as f64)) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }

    // Post-residual can fit the next item: mild bonus.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 30.0;
        // Bonus scaled by tightness of the fit for the next item.
        let slack = (post_residual - next_item_size) as f64;
        score -= 40.0 / (1.0 + slack / 10.0);
    }

    // Dead space: post_residual too small for next item (or nothing next)
    // is likely wasted; penalize proportionally more as it shrinks.
    if post_residual > 0 {
        let dead = if next_item_size > 0 && post_residual < next_item_size {
            post_residual as f64
        } else if next_item_size == 0 {
            post_residual as f64
        } else {
            0.0
        };
        if dead > 0.0 {
            score += 50.0 * (1.0 - dead / bin_capacity as f64);
        }
    }

    // Relative to mean residual: prefer bins that are tighter than average.
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: penalize opening a fresh bin unless current item is large
    // and would leave an awkward residual in any existing bin.
    if bin_residual == bin_capacity {
        score += 45.0;
        if item_size >= 50 {
            score -= 30.0;
        }
        if next_item_size > 0 && next_item_size >= bin_residual - item_size.min(bin_residual) {
            score -= 10.0;
        }
    }

    // Early in the stream: allow more bins to be opened to build flexibility.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity && progress < 0.2 {
        score -= 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual)
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize dead space: post_residual too small to ever be useful
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if next item fits exactly in post_residual, strongly reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            score -= 8.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item won't fit here; slight penalty if this bin becomes near-full waste
            if post_residual < 10 {
                score += 5.0;
            }
        }
    } else {
        // last item: prefer fullest packing
        score -= 10.0 * fit_ratio;
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: prefer opening a new bin only when fits are bad
    if bin_residual == bin_capacity {
        // neutral base, but discourage when a decent fit exists elsewhere
        score += 15.0;
        if fit_ratio >= 0.9 {
            score -= 40.0; // shouldn't happen for empty bin, safety
        }
        if open_bins_count > 0 && fitting_bins_count > 0 && mean_residual >= item_size as f64 {
            // there are open bins that can fit; make new bin less attractive
            score += 10.0 + mean_residual - item_size as f64;
        }
        // early in stream, opening bins is cheap
        let progress = step_index as f64 / total_items as f64;
        score -= 10.0 * (1.0 - progress);
    }

    // Global state: many open bins with large residuals -> prefer consolidating into fuller bins
    if open_bins_count > 3 {
        let avg = mean_residual;
        if (bin_residual as f64) < avg {
            score -= 3.0; // prefer below-average residual (fuller) bins
        } else {
            score += 2.0;
        }
    }

    // Slight preference for bins with small residual overall (best-fit flavor)
    score += (bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let pr_norm = pr / cap;

    // Smooth non-linear coupling: penalize residual quadratically as stream progresses
    score += progress * pr_norm * pr_norm * 40.0;

    // Cubic dead-space penalty for very tight fits late in stream
    score += progress * pr_norm * pr_norm * pr_norm * 60.0;

    // Reward tight fits more strongly as stream advances (subtract)
    let fill = (cap - pr) / cap;
    score -= progress * fill * fill * 25.0;

    // Lookahead synergy: if next item fits the post-residual smoothly, reward
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let slack = pr - nxt;
            score -= (1.0 - slack / cap) * 12.0 * (0.5 + progress);
        } else {
            let gap = (nxt - pr) / cap;
            score += gap * gap * 15.0;
        }
    }

    // Last-chance bin: strongly favor using it when it fits well
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0 * (1.0 - pr_norm);
    }

    // Penalize opening new bins when many bins already fit the item
    if bin_residual == bin_capacity {
        score += 8.0 + 3.0 * fitting_bins_count as f64;
        score -= progress * 5.0;
    }

    // Mean-residual coupling: encourage balancing residual toward the mean
    score += (pr - mean_residual).abs() / cap * 6.0;

    // Small smooth interaction between item size and open bins
    let isz = item_size as f64;
    score += (isz / cap) * (open_bins_count as f64).ln().max(0.0) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strongest reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: dead space value depends on residue class mod 10
    let dead = post_residual as f64;
    let class = (post_residual % 10) as f64;
    // small residues (1..=9) are near-useless; penalize non-zero small leftovers
    if post_residual > 0 && post_residual < 10 {
        score += 30.0 - 2.0 * class;
    }

    // Waste relative to capacity fraction: quadratic penalty on unusable space
    score += 0.05 * dead * dead / 100.0;

    // Next-item lookahead: reward bins whose post_residual can host next item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0 + 0.5 * next_item_size as f64;
    } else if next_item_size > 0 {
        // post_residual too small for next item: penalize proportional to closeness
        score += 5.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: keep it attractive only when existing bins fit poorly
    if bin_residual == bin_capacity {
        let tight_existing = if fitting_bins_count == 0 { 0.0 } else {
            (bin_residual as f64 - item_size as f64).min(100.0)
        };
        // prefer new bin if post_residual would be tiny dead space elsewhere
        if post_residual < 15 && fitting_bins_count >= 1 {
            score -= 10.0; // opening fresh bin beats leaving dead space
        } else {
            score += 25.0; // default: prefer reusing open bins
        }
        let _ = tight_existing;
    }

    // Stream progression: late in stream, consolidate more aggressively
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * (mean_residual / bin_capacity as f64);

    // Many open bins: favor filling existing ones over opening more
    score += 0.3 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (< 10, min item size)
    // are the worst outcome; penalize them quadratically.
    if post_residual < 10 {
        score += 50.0 + (10 - post_residual) as f64 * 20.0;
    } else if post_residual <= 20 {
        // Mid-small gaps are risky too (few future items fit)
        score += (20 - post_residual) as f64 * 2.0;
    }

    // Reward near-perfect fits strongly (post_residual close to 0 but usable)
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= fit_ratio * fit_ratio * 30.0;

    // Open-bin pressure: discourage spreading across many bins
    score += open_bins_count as f64 * 1.5;

    // Last-chance bin: if this is the only fitting bin, strongly prefer it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate handling: an empty bin is attractive only when the
    // item fits poorly in all open bins. Base new-bin cost plus lookahead.
    if bin_residual == bin_capacity {
        score += 40.0;
        if fitting_bins_count == 0 {
            score -= 60.0; // no open bin fits: new bin is correct
        }
        // If next item is large, keeping residual space open is valuable
        if next_item_size as f64 > mean_residual {
            score -= 15.0;
        }
    }

    // Lookahead: if the next item exactly matches the post_residual,
    // this placement is ideal; reward it.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 35.0;
    }
    // If next item fits in post_residual, mildly reward leaving usable space
    if next_item_size > 0 && next_item_size < post_residual {
        score -= 5.0;
    }

    // Mean residual coupling: bins far below mean residual are "fresher";
    // prefer filling bins with residual below the mean first.
    if (bin_residual as f64) < mean_residual {
        score -= 8.0;
    } else {
        score += 4.0;
    }

    // Early in stream: be slightly conservative about opening bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity && progress < 0.2 {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when post_residual matches next item size.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 40.0 / (1.0 + diff); // perfect match for next item gets big bonus
        // Penalize leaving residual slightly below next item (dead space)
        if (post_residual as i64) < (next_item_size as i64) {
            score += (next_item_size - post_residual) as f64 * 0.8;
        }
    } else {
        // Last item: prefer tightest fit
        score += 0.0;
    }

    // Dead-space penalty: residuals too small for the minimum item are wasted.
    if post_residual < 1 {
        score -= 100.0; // perfect fill
    } else {
        score += 25.0 * (1.0 - post_residual as f64 / 20.0f64.max(post_residual as f64).min(20.0) / 20.0);
    }

    // Relative to mean residual: prefer bins whose post residual stays near/below mean
    score += 0.5 * (post_residual as f64 - mean_residual);

    // Last chance: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when no good fit exists elsewhere.
    if bin_residual == bin_capacity {
        score += 15.0 + 0.3 * mean_residual;
    }

    // Slight progression bias: later in stream, be greedier about tight fits.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize low post-residual relative to capacity.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_ratio * 12.0;

    // Penalize creating small, hard-to-fill dead space (post residual in awkward zone).
    let pr = post_residual as f64;
    if pr > 0.0 && pr < 10.0 {
        score += 25.0;
    } else if pr >= 10.0 && pr <= 20.0 {
        score += 8.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Lookahead coupling: if next item fits in post-residual, reward this placement.
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 15.0;
    }
    // Penalize if next item is slightly larger than post-residual (near-miss waste).
    if next_item_size > 0 && (post_residual as u32) < next_item_size && (next_item_size - post_residual as u32) <= 10 {
        score += 10.0;
    }

    // Time horizon: early in stream, prefer consolidating into open bins less;
    // late in stream, favor tight packing to avoid opening extra bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 10.0;

    // Global residual pressure: if mean residual is high, prefer spreading load
    // into the emptiest bins; if low, be frugal with new bins.
    score -= (mean_residual - pr) * 0.3;

    // New-bin candidate handling: make empty bins attractive only when item is large
    // or open bins are crowded.
    if bin_residual == bin_capacity {
        let large_item = item_size as f64 / bin_capacity as f64;
        score -= large_item * 30.0;
        score += open_bins_count as f64 * 2.0;
        if fitting_bins_count > 0 && item_size < 50 {
            score += 20.0; // small items should use existing bins
        }
    }

    // Mild penalty for many open bins to discourage fragmentation.
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual in [0,1]

    // Base: prefer small post residual, with non-linear penalty on dead space
    let mut score = pr as f64;

    // Smooth polynomial coupling with stream progress:
    // early on, waste matters less; later, tight fits are rewarded more strongly.
    let tightness = 1.0 - x; // fraction of residual used
    score -= 30.0 * progress * tightness * tightness * tightness;

    // Penalize post residuals that are too small to fit any plausible item,
    // but do it smoothly (quartic bump around small x).
    let dead = (1.0 - x).max(0.0);
    score += 12.0 * (1.0 - dead) * (1.0 - dead) * x * x;

    // Lookahead coupling: if next item fits exactly in post residual, reward strongly.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr as f64 {
            let fit_quality = 1.0 - ((pr - nx) / cap);
            score -= 20.0 * fit_quality * fit_quality;
        } else {
            let gap = (nx - pr) / cap;
            score += 8.0 * gap * gap;
        }
    }

    // Last-chance bin: reward using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 + progress);
    }

    // Many open bins with high mean residual: prefer spreading load,
    // mildly favor bins whose residual is below the mean (consolidation).
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 5.0 * dev * dev.abs();

    // Smooth preference for opening a new bin when current bins are nearly full
    // and the item is small: new-bin candidate gets a moderate score via x near 1.
    score += 10.0 * x * x * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead-space penalty grows for residuals
    // in "awkward" classes (small, prime-like, hard to fill later).
    let pr = post_residual;
    if pr == 0 {
        score -= 40.0; // perfect fit: strongly reward
    } else if pr < 10 {
        score += 25.0; // tiny dead space is nearly unusable
    } else {
        // class by residue mod 10: multiples of 5/10 are more reusable
        let m = pr % 10;
        score += match m {
            0 => -6.0,
            5 => -3.0,
            2 | 4 | 6 | 8 => 1.0,
            _ => 3.0,
        };
    }

    // Integer-division thresholds: how many "typical" items (size ~20) still fit
    let slots = pr / 20;
    score -= slots as f64 * 4.0;

    // Lookahead coupling: if next item fits exactly in post_residual, reward
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 20.0;
        } else if next_item_size <= pr {
            score -= 8.0;
            // penalize wasting a large next item on a bin that barely fits
            if next_item_size > pr * 3 / 4 {
                score += 5.0;
            }
        } else {
            // next item won't fit here; residual becomes dead space risk
            score += (pr as f64) * 0.05;
        }
    } else {
        // last item: prefer tightest packing, reward full bins
        score -= 10.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    } else if fitting_bins_count > 1 {
        // many options: mild preference for tighter bins
        score += fitting_bins_count as f64 * 0.5;
    }

    // New-bin candidate logic: empty bin should only win when open bins are poor
    if bin_residual == bin_capacity {
        // neutral baseline slightly worse than a good fit, better than bad fits
        score = (bin_capacity - item_size) as f64 + 12.0;
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
        // late in stream, prefer reusing open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
    }

    // Spread-awareness: if mean residual is high, prefer bins below it (tighter)
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    } else {
        score += 1.0;
    }

    // Mild pressure to consolidate when many bins are open
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: small unusable gaps are the enemy.
    if post_residual > 0 {
        if post_residual < 10 {
            score += 60.0; // tiny dead gap, nearly unusable
        } else if next_item_size > 0 && post_residual < next_item_size {
            score += 25.0; // gap can't fit the next item
        }
    } else {
        score -= 30.0; // perfect closure
    }

    // Reward tight fits (waste ratio).
    let fill = item_size as f64 / bin_residual as f64;
    score -= 40.0 * fill;

    // Last-chance bonus: if this is the only fitting bin, prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading to new bins,
    // but encourage closing out near-empty bins.
    score += 0.8 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Encourage using bins whose residual is close to the item (best fit).
    score += (bin_residual as f64 - item_size as f64) * 0.5;

    // Slight preference for larger residual bins early in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * mean_residual * 0.05;

    // New-bin candidate: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        score += 15.0 + 2.0 * open_bins_count as f64 * 0.0;
        if next_item_size > 0 && item_size == next_item_size {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core: reward tight fits (small post_residual)
    score += (post_residual as f64 / bin_capacity as f64) * 30.0;

    // Exact fit is excellent
    if post_residual == 0 {
        score -= 100.0;
    }

    // 2-step lookahead: if next item fits exactly into post_residual, strongly favor
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 80.0;
        } else if next_item_size <= post_residual {
            score -= (next_item_size as f64 / post_residual.max(1) as f64) * 25.0;
        } else {
            // next item won't fit here; penalize leaving medium dead space
            if post_residual < 10 {
                score += 15.0; // tiny dead space is bad
            } else {
                score += 5.0;
            }
        }
    }

    // Compare residual against mean residual: prefer bins with less residual (fuller bins)
    score += (mean_residual - bin_residual as f64).max(-50.0).min(50.0) * 0.3;

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless current bins are poor fits
    if bin_residual == bin_capacity {
        let waste_if_open = bin_capacity as f64 - item_size as f64;
        score += 60.0;
        if fitting_bins_count == 0 {
            score -= 200.0; // no alternative, must open
        } else if waste_if_open > 40.0 && mean_residual < item_size as f64 * 0.9 {
            score -= 30.0; // open bins are all too full-ish; new bin reasonable
        }
        // lookahead: new bin leaves room for next item
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 10.0;
        }
    }

    // Late in stream: consolidate, avoid new bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual < bin_capacity {
        score -= progress * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual is primary; extra bonus for very small leftovers.
    if post_residual > 0 {
        score += (post_residual as f64).powi(2) / (bin_capacity as f64);
    } else {
        score -= 25.0; // perfect fit bonus
    }

    // Lookahead: penalize bins whose leftover can't host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else if post_residual > 0 {
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
        // Reward leaving exactly room for the next item (chain fit)
        if post_residual == next_item_size {
            score -= 12.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        // Prefer new bin only when existing fits are poor or item is large.
        let tightness = (item_size as f64) / (bin_capacity as f64);
        let avg_fit_quality = 1.0 - ((mean_residual - item_size as f64).abs() / bin_capacity as f64).min(1.0);
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let pressure = (open_bins_count as f64).ln().max(1.0);

        let mut new_bin_penalty = 30.0
            - tightness * 20.0
            - (1.0 - avg_fit_quality) * 25.0
            - progress * 5.0
            + pressure * 2.0;

        // If no open bin can fit the item, new bin is the only option.
        if fitting_bins_count == 0 {
            new_bin_penalty = -10.0;
        }
        score += new_bin_penalty;
    }

    // Mild global regularization: prefer bins with residuals near mean to keep spread low.
    score += ((bin_residual as f64 - mean_residual) / bin_capacity as f64).abs() * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap;

    // Base: penalize wasted post-residual, non-linearly.
    let mut score = pr as f64;

    // Polynomial coupling: residual squared term scaled by stream progress.
    // Early on, moderate residuals are fine (room for future items);
    // late in the stream, small residuals (tight fits) are preferred.
    score += 40.0 * x * x * (1.0 - progress);
    score -= 25.0 * x * progress;

    // Dead-space penalty: residuals too small for the smallest plausible item.
    let dead = (1.0 - (pr as f64 / (next_item_size.max(1) as f64 + 1.0))).clamp(0.0, 1.0);
    score += 30.0 * dead * dead * x;

    // Last-chance bonus: strongly favor the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 45.0;
    } else if fitting_bins_count > 2 {
        score += 5.0 * (fitting_bins_count as f64 - 2.0);
    }

    // New-bin candidate: prefer opening a new bin early or when mean residual is high.
    if bin_residual == bin_capacity {
        let openness = mean_residual / cap;
        score -= 20.0 * openness * openness + 15.0 * (1.0 - progress);
    } else {
        // Reward bins whose residual is close to the item (tight fit).
        let tightness = 1.0 - (item_size as f64 / bin_residual.max(1) as f64);
        score += 20.0 * tightness * tightness;
    }

    // Lookahead: if the next item fits exactly in post_residual, reward heavily.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 35.0;
    } else if next_item_size > post_residual && post_residual < 10 {
        score += 10.0; // unusable sliver
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residuals that sit in "combinable" classes
    // (multiples of 10 and small values), penalize awkward mid-range dead space.
    let post_class = post_residual % 10;
    let post_div = post_residual / 10;
    match post_class {
        0 => score -= 6.0 + post_div as f64,               // perfectly harmonic residual
        1 | 2 | 3 => score -= 2.0,                          // near-harmonic, still fillable
        4 | 5 | 6 => score += 3.0,                          // awkward mid-range gap
        _ => score += 1.0,
    }

    // Very tight fits are excellent: waste below 10 is nearly free.
    if post_residual < 10 {
        score -= 8.0;
    }
    if post_residual == 0 {
        score -= 15.0; // perfect closure
    }

    // Dead-space penalty grows super-linearly in the awkward zone (20..50 residual)
    // where few item sizes (10..80) can still fit.
    if post_residual > 50 {
        score -= 4.0; // large residual is still broadly usable
    } else if post_residual > 20 {
        let awkward = (post_residual - 20) as f64;
        score += awkward * 0.25;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size <= post_residual {
            let gap = (post_residual - next_item_size) as f64;
            score -= 6.0 - gap.min(10.0) * 0.4;
        } else {
            // next item cannot use this bin's leftover: mild penalty scaled by waste
            score += (post_residual as f64) * 0.05;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: an empty bin is a fallback; make it attractive only
    // when existing bins would create large dead space. Base cost for opening a bin.
    if bin_residual == bin_capacity {
        score = 45.0 + (open_bins_count as f64).sqrt() * 2.0;
        if next_item_size > 0 && next_item_size >= 90 {
            score -= 10.0; // big item coming, fresh bin is fine
        }
    }

    // Stream progression: late in the stream, tighten up — prefer closing bins well.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += mean_residual * 0.03 * (1.0 - progress);

    // Slight preference to fill already-open bins vs spreading across many.
    score += (open_bins_count as f64).ln().max(0.0) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit is perfect: strongly reward.
    if post_residual == 0 {
        score -= 1000.0;
        return score;
    }

    // Dead-space penalty: residual gaps too small to hold the next item
    // (or any plausible item) are wasted space.
    let min_item = 1u32;
    let unusable_threshold = next_item_size.max(min_item);
    if post_residual < unusable_threshold {
        // This gap likely becomes dead space -> heavy penalty.
        score += 40.0 + 0.5 * post_residual as f64;
    }

    // Moderate dead space (small but potentially usable) gets a mild penalty
    // proportional to how little of it there is.
    if post_residual > 0 && post_residual <= 15 {
        score += 8.0;
    }

    // Reward tight fits (small usable post residual).
    score -= 30.0 / (post_residual as f64 + 1.0);

    // Pressure: with many open bins, prefer filling existing bins over opening new ones.
    score += 0.35 * open_bins_count as f64;

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless existing bins are crowded.
    if bin_residual == bin_capacity {
        score += 30.0 + 2.0 * open_bins_count as f64;
        // If mean residual across open bins is small, opening new bin is less bad.
        score -= mean_residual * 0.1;
    }

    // Lookahead: if next item fits exactly into the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap_ratio = next_item_size as f64 / post_residual as f64;
        if gap_ratio > 0.85 {
            score -= 20.0 * gap_ratio;
        }
    }

    // Late in the stream, closing out bins matters more: favor tighter fits.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * post_residual as f64 * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual equals next item size
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
        // Reward exact match strongly, taper with distance
        score -= 40.0 * (-diff / 12.0).exp();
        // Bonus if next item also fits after this placement (chain potential)
        if next_item_size <= post_residual {
            score -= 10.0;
        }
    } else {
        // Last item: just minimize wasted space
        score -= 5.0;
    }

    // Penalize dead space below the minimum item size (unusable residual)
    let min_item = 1u32;
    if post_residual < min_item {
        score += 25.0;
    }
    // Small residuals relative to capacity are wasteful unless perfectly matched
    if post_residual < 10 && next_item_size != post_residual {
        score += 8.0;
    }

    // Compare against mean residual: prefer bins that stay near the mean
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Mild preference for consolidating into fewer bins
    score += 0.5 * open_bins_count as f64;

    // New-bin candidate: only attractive when no good fit exists
    if bin_residual == bin_capacity {
        score += 15.0;
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let is_new_bin = bin_residual == bin_capacity;

    // Penalize large dead space more than linearly.
    if post_residual > 0 {
        score += (post_residual as f64).powf(1.4) * 0.05;
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= tightness * 12.0;

    // Lookahead: if the next item fits exactly in the post-residual, reward heavily.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = post_residual - next_item_size;
            score -= 10.0 + (slack as f64) * 0.1;
        } else {
            // Next item cannot follow here; slight penalty.
            score += 4.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless it's early,
    // many bins exist, or the mean residual is high (poor fits everywhere).
    if is_new_bin {
        let poor_fits = mean_residual > item_size as f64 * 1.8;
        let early = progress < 0.25;
        if !early && !poor_fits {
            score += 30.0 + (open_bins_count as f64) * 0.5;
        } else {
            score += 6.0;
        }
    }

    // Late in the stream, prefer consolidating into existing bins.
    score += progress * (bin_residual - item_size.min(bin_residual)) as f64 * 0.15;

    // Slight preference for bins below mean residual (balancing).
    score += ((bin_residual as f64) - mean_residual) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: post residual, with polynomial penalty for small-but-unusable residuals
    let mut score = pr;

    // Smooth polynomial coupling of post_residual with stream progress:
    // early on, prefer leaving mid-size gaps (score curves gently);
    // late in the stream, small residuals become dead weight, penalize harder.
    let poly = norm_pr * norm_pr * (1.0 - norm_pr);
    score += 30.0 * poly * (0.5 + progress);

    // Penalize residuals too small for the lookahead item (smoothly)
    if next_item_size > 0 {
        let gap = pr - next_item_size as f64;
        if gap < 0.0 {
            let deficit = (-gap / cap).min(1.0);
            score += 12.0 * deficit * deficit * (0.4 + 0.6 * progress);
        } else {
            // reward residuals that exactly/nearly fit the next item
            let fit = (1.0 - (gap / cap)).max(0.0);
            score -= 8.0 * fit * fit * fit;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * progress;
    }

    // Mild preference for bins tighter than the mean (good packing density)
    score -= 0.5 * (mean_residual - pr) / cap;

    // Slight penalty for spreading across many open bins early
    score += 0.3 * (open_bins_count as f64).ln() * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: classify post_residual into
    // capacity-fraction buckets (1/8 granularity) to reward "harmonic" dead space
    // that other items can plausibly fill.
    let frac = post_residual as f64 / cap; // in [0,1]
    let class = (frac * 8.0).floor() as u32; // 0..7 harmonic class
    // Harmonic bonus: leftover in classes that match typical item sizes (1/8..=3/8 of capacity)
    let harmonic_bonus: f64 = match class {
        0 => 0.0,               // perfect fit
        1 | 2 | 3 => -6.0,      // sweet-spot leftovers
        4 | 5 => 2.0,           // half-ish leftovers, less useful
        _ => 6.0,               // nearly empty leftover = wasted capacity
    };
    score += harmonic_bonus;

    // Strong reward for tight fits (small post_residual), non-linear.
    score -= 14.0 * (-post_residual as f64 / 8.0).exp();

    // Penalize large post_residual quadratically to discourage dead space.
    score += 0.03 * (post_residual as f64).powi(2) / cap;

    // Lookahead: if next item can fit into post_residual, reward this bin.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 5.0 + 0.25 * (post_residual - next_item_size) as f64;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here after placement; slight penalty unless residual tiny.
        score += 2.0 * (post_residual as f64 / cap);
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate handling: opening a bin is only attractive when the item
    // fits poorly everywhere else or open bins are very full on average.
    if bin_residual == bin_capacity {
        let mean_frac = mean_residual / cap;
        // Penalize new bins generally, less when existing bins are crowded.
        let mut new_bin_penalty = 12.0 - 10.0 * mean_frac;
        // If item is huge and mean residual can't hold next item well, new bin ok.
        if item_size as f64 > mean_residual {
            new_bin_penalty -= 3.0;
        }
        // Early stream: be frugal with bins; late stream: less concern.
        let progress = step_index as f64 / total_items.max(1) as f64;
        new_bin_penalty += 4.0 * (1.0 - progress);
        score += new_bin_penalty;
    }

    // Mild preference for fuller bins among open bins (deviation from mean residual).
    if bin_residual != bin_capacity {
        score += 0.15 * (bin_residual as f64 - mean_residual);
    }

    // Modulo-based tie-breaking on post_residual: multiples of 8 align with
    // harmonic classes and slightly preferred leftovers.
    if post_residual % 8 == 0 && post_residual > 0 {
        score -= 1.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit: huge reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (10.0 - post_residual as f64);
    }
    // Medium gaps are mildly penalized relative to a plain residual count.
    else if post_residual < 25 {
        score += 5.0;
    }

    // Reward if the leftover gap can host the next item (lookahead synergy).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }
    // Penalize leaving a gap just under the next item's size (near-miss dead space).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 10.0;
    }

    // Last chance: strongly prefer filling the only bin that fits rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading into new bins.
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure from open bins and mean residual.
        score += 20.0 + 3.0 * open_bins_count as f64 + mean_residual * 0.5;
    } else {
        // Filling existing bins is mildly encouraged when many bins are open.
        score -= 0.5 * open_bins_count as f64;
        // Prefer bins tighter than average (good fits).
        if (bin_residual as f64) < mean_residual {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits (dead space penalty is quadratic).
    let residual_frac = post_residual as f64 / bin_capacity as f64;
    score += 30.0 * residual_frac * residual_frac;

    // Exact fit: huge reward.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual < 10 {
        score -= 200.0; // effectively dead space created
    }

    // 2-step lookahead: if the next item fits exactly into post_residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            let next_fit_quality = next_item_size as f64 / post_residual as f64;
            score -= 80.0 * next_fit_quality; // better packing density for next item
        } else {
            // Next item won't fit here; penalize leaving a gap the next item overshoots badly.
            let overshoot = (next_item_size - post_residual) as f64;
            score += 0.5 * overshoot;
        }
    }

    // Compare residual to mean residual: prefer bins with below-average residual
    // (tighter bins), i.e. fill the fullest-fitting bin first (best-fit flavor).
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Last-chance bonus: if this is the only bin that can fit the item, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 300.0;
    }

    // Penalize opening a new bin unless residuals of open bins are genuinely bad.
    if bin_residual == bin_capacity {
        let open_pressure = open_bins_count as f64;
        let avg_usability = mean_residual / bin_capacity as f64;
        // New bin is attractive only when existing residuals are small/fragmented.
        score += 150.0 - 100.0 * avg_usability + 2.0 * open_pressure;
        // Late in the stream, be more conservative about opening new bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 50.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize large post_residual nonlinearly.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += fit_ratio * fit_ratio * 40.0;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        // Slight penalty when many bins compete (avoid wasting tight bins).
        score += 2.0 * (fitting_bins_count as f64 - 1.0);
    }

    // Lookahead: if the next item fits exactly in the post residual, reward heavily.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual >= next_item_size {
            // Next item can still go here; mild reward proportional to leftover after it.
            let after_next = (post_residual - next_item_size) as f64;
            score += after_next * 0.15;
        } else {
            // Next item won't fit here; penalize small dead space more.
            score += 8.0;
        }
    } else {
        // Last item in stream: just minimize waste directly.
        score += 0.0;
    }

    // Time horizon: early in stream, prefer opening new bins less (consolidate);
    // late in stream, avoid leaving unusable slivers.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 5.0 * fit_ratio;

    // Global state coupling: if mean residual is high, tighten preference for
    // bins below mean residual (keep large-residual bins flexible).
    if (bin_residual as f64) > mean_residual {
        score += 3.0;
    } else {
        score -= 1.0;
    }

    // New-bin candidate handling: empty bin gets a moderate penalty so it's
    // chosen only when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        score += 55.0 + 10.0 * (open_bins_count as f64).sqrt();
    }

    // Discourage creating dead space smaller than the minimum plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Smooth polynomial coupling of post_residual with stream progress
    let mut score = pr * (1.0 + 0.6 * progress * progress) - 0.35 * (1.0 - progress) * norm_pr * norm_pr * cap;

    // Penalize residual that cannot fit the lookahead item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let waste = (pr - nx).max(0.0);
        score += 0.5 * (waste / cap) * (1.0 + progress) * cap;
        if nx <= pr {
            score -= 0.4 * nx * (1.0 - progress);
        }
    }

    // Last-chance bonus: reward using the only fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 8.0 * (1.0 - 0.5 * progress);
    }

    // Mild penalty when bin residual deviates from mean residual (fragmentation control)
    score += 0.15 * (pr - mean_residual).abs() * (1.0 - progress);

    // Slight preference for tighter fits overall
    score += 0.1 * (pr as f64 / cap) * cap * 0.1;

    // Encourage opening new bins late in the stream when current bins are poor fits
    if bin_residual == bin_capacity {
        score += 2.0 * (1.0 - progress) - 1.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: capacity fractions
    let c = bin_capacity as f64;
    let quarter = c / 4.0;
    let half = c / 2.0;
    let pr = post_residual as f64;

    // Reward tight fits: post_residual in low harmonic classes
    if pr == 0.0 {
        score -= 60.0; // perfect fit
    } else if pr < quarter {
        score -= 15.0;
        // integer-division threshold: dead space classes
        if post_residual % 10 == 0 {
            score -= 5.0; // reusable class (multiple of 10)
        } else {
            score += 8.0; // awkward dead space
        }
    } else if pr < half {
        score -= 5.0;
    } else {
        // large residual kept: fine, but mild penalty if item was small
        score += 3.0;
    }

    // Modulo coupling between item and next item
    if next_item_size > 0 {
        let pair_sum = item_size + next_item_size;
        if pair_sum <= bin_residual {
            score -= 10.0; // this bin can chain-fit the next item too
        }
        if post_residual >= next_item_size {
            score -= 12.0; // lookahead fits exactly after placement
        }
        // harmonic class of next item
        if next_item_size > 50 && post_residual >= next_item_size {
            score -= 8.0; // reserve space for big next item
        }
    } else {
        // last item: just close bins tightly
        score -= 5.0;
    }

    // Last-chance bin: strongly favor using it to avoid a new bin
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Penalize opening new bins when plenty of fitting bins exist
    if bin_residual == bin_capacity {
        score += 10.0;
        if fitting_bins_count > 0 {
            score += 25.0;
        }
        // early stream: keep bins few
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 * (1.0 - progress);
    }

    // Prefer bins below mean residual (consolidate emptier bins)
    if (bin_residual as f64) < mean_residual {
        score -= 4.0;
    } else {
        score += 2.0;
    }

    // Open bins count pressure: more open bins -> prefer filling existing
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps harshly.
    let dead_zone = 1.0 + (bin_capacity as f64) * 0.15; // gaps <= 15 units are near-dead
    if post_residual > 0 && (post_residual as f64) < dead_zone {
        let severity = (dead_zone - post_residual as f64) / dead_zone;
        score += 40.0 * severity * severity;
    }
    // Perfect fit bonus
    if post_residual == 0 {
        score -= 30.0;
    }

    // Reward leaving residual that can still fit the next item (lookahead).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0 * (post_residual as f64 / next_item_size.max(1) as f64).min(2.0);
        } else {
            // residual too small for next item: dead space for lookahead
            score += 15.0;
        }
    }

    // Open-bin pressure: discourage spreading across many bins unless it's a great fit.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = 0.5 + 2.0 * progress;
    score += pressure * (open_bins_count as f64).ln().max(0.0) * 2.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Prefer bins tighter than the mean (best-fit coupling).
    score += 0.3 * (mean_residual - bin_residual as f64);

    // New-bin candidate: make it attractive only when the fit into open bins is poor
    // (large post_residual dead space). Otherwise keep new bins slightly penalized.
    if bin_residual == bin_capacity {
        score += 20.0;
        if post_residual as f64 > dead_zone {
            score -= 10.0; // fresh bin keeps usable space; acceptable
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: strongly reward bins whose post_residual
    // exactly matches the next item's size (perfect chaining).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let post = post_residual as f64;
        let gap = (post - nxt).abs();
        if post >= nxt {
            // Next item fits here afterwards: reward tight chains.
            score -= 40.0 * (1.0 - gap / bin_capacity as f64);
            if gap == 0.0 {
                score -= 25.0; // perfect chain bonus
            }
        } else {
            // Next item won't fit after placement: penalize proportionally
            // to how much dead space we leave relative to the next item.
            score += 10.0 * (nxt - post) / nxt.max(1.0);
        }
        // Compare against mean residual: bins far from the mean are either
        // hoarders or nearly empty; keep scores aligned with the fleet state.
        score += 0.15 * (post - mean_residual);
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Penalize large post_residual (wasted space) super-linearly.
    let post = post_residual as f64;
    score += 0.05 * post * post / bin_capacity as f64;

    // New-bin candidate handling: opening a fresh bin is only attractive when
    // no open bin offers a decent fit (tight packing elsewhere) or the stream
    // is early and future items are likely large.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let decent_fit_exists = open_bins_count > 0 && mean_residual >= item_size as f64 + 5.0;
        if decent_fit_exists {
            score += 35.0; // discourage new bin when decent fits exist
        } else {
            score -= 10.0 + 10.0 * (1.0 - progress);
        }
        // If lookahead item is large and nothing fits it, a fresh bin chains well.
        if next_item_size > 0 && (bin_capacity as f64 - next_item_size as f64) < 5.0 {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) more aggressively as it grows relative.
    let tightness = (item_size as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * (post_residual as f64) / (bin_capacity as f64);

    // Penalize creating small unusable dead space (post_residual that likely can't fit future items).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if the next item fits exactly in post_residual, strongly reward this placement.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            // Next item won't fit here; slight penalty proportional to wasted potential.
            score += 4.0 * (1.0 - (post_residual as f64) / (next_item_size as f64));
        }
    } else {
        // Last item: prefer filling bins as tightly as possible.
        score -= 15.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Penalize opening a new bin when open bins with reasonable residual exist.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // New bins are more acceptable early and when mean residual is high.
        score += 18.0 * (1.0 - progress);
        if mean_residual > item_size as f64 {
            score += 10.0;
        }
        if open_bins_count > 0 && fitting_bins_count > 0 {
            score += 6.0;
        }
    } else {
        // Reward using existing bins, more so when they are below-mean residual (balancing).
        if (bin_residual as f64) < mean_residual {
            score -= 3.0;
        }
    }

    // Mild penalty for very full bins being "spent" — keep them for tiny items later.
    if post_residual == 0 {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;

    let mut score = pr;

    // Non-linear coupling: post_residual quadratic with progress weighting
    let quad = norm_pr * norm_pr;
    score += 30.0 * quad * (0.5 + progress);

    // Cubic interaction between post_residual and item fraction
    score += 20.0 * quad * norm_pr * (1.0 - norm_item);

    // Tight fits rewarded smoothly (post_residual near zero)
    score -= 25.0 * (1.0 - norm_pr).powi(6) * (0.4 + 0.6 * progress);

    // Last-chance bin bonus (smoothly scaled)
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - progress * 0.5);
    }

    // Penalize bins far from mean residual (deviation penalty, smooth)
    let dev = (pr - mean_residual) / cap;
    score += 10.0 * dev * dev;

    // Lookahead coupling: reward leaving space for the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fit_next = if pr as f64 >= nxt { 1.0 } else { 0.0 };
        let closeness = 1.0 - ((pr as f64 - nxt).abs() / cap);
        score -= 12.0 * fit_next * closeness * closeness;
        // Penalize dead space the next item cannot use
        score += 8.0 * (1.0 - fit_next) * norm_pr * norm_pr;
    }

    // Mild new-bin preference early when residuals are fragmented
    if bin_residual == bin_capacity {
        score += 3.0 + 10.0 * (1.0 - progress) * norm_item;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: rewards residuals that are
    // "clean" multiples of common item-size classes (perfect fits).
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Harmonic classes: post_residual divisible by small common sizes
        for d in [5u32, 10, 20, 25, 50] {
            if post_residual % d == 0 && post_residual >= d {
                score -= 3.0 + (d as f64) * 0.1;
            }
        }
        // Integer-division threshold: small dead space is bad
        if post_residual < 10 {
            score += 40.0; // unusable dead space (min item 10... but sizes 1..100)
        } else if post_residual < 20 {
            score += 15.0;
        }
    }

    // Fraction-of-capacity coupling: prefer filling a large fraction
    let fill_frac = 1.0 - pr / cap;
    score -= 20.0 * fill_frac * fill_frac;

    // Lookahead: if the next item fits exactly in the post-residual, big bonus
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 250.0;
        } else if next_item_size <= post_residual {
            score -= 10.0;
        } else {
            // next item won't fit here: slight penalty for blocking chain
            score += 5.0;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 80.0;
    }

    // New-bin candidate handling: empty bin gets moderate penalty so we
    // prefer open bins unless their residuals are fragmented.
    if bin_residual == bin_capacity {
        score += 35.0 + 2.0 * (open_bins_count as f64).sqrt();
    }

    // Mean-residual coupling: penalize bins far from the mean (fragmentation)
    score += 0.5 * ((bin_residual as f64) - mean_residual).abs();

    // Late in the stream: consolidate more aggressively
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * fill_frac;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Prefer bins whose residual is large enough to host the lookahead item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 10.0;
    }

    // Open-bin pressure: discourage spreading across many bins when a tight fit exists.
    score += (open_bins_count as f64) * 0.6;

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless the fit is genuinely poor.
    if bin_residual == bin_capacity {
        score += 55.0;
        if post_residual < 20 {
            score += 25.0;
        }
    }

    // Late in the stream, tighten packing to close out bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 8.0 * (1.0 - (post_residual as f64 / bin_capacity as f64));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post-residual exactly
    // matches the next item size, penalize near-misses that strand space.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;
        let diff = (pr - nxt).abs();
        if diff < 0.5 {
            // Perfect chain: item + next item fill the bin completely.
            score -= 60.0;
        } else if nxt <= pr {
            // Next item fits here: scale reward by tightness of the chain.
            let tight = 1.0 - diff / pr.max(1.0);
            score -= 40.0 * tight;
        } else {
            // Next item will not fit in the residual: penalize dead space
            // relative to how badly the chain breaks.
            score += 0.5 * (nxt - pr);
        }
        // Bonus if the residual after the chain would be tiny.
        if pr >= nxt {
            let chain_post = pr - nxt;
            if chain_post < 10.0 {
                score -= 15.0;
            }
        }
    }

    // Relative-to-mean coupling: prefer bins that are tighter than average
    // (small residual), avoid bins far looser than the mean.
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // Last-chance bin: if this is the only fitting bin, strongly favor it
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when the item is large relative to
    // capacity or open bins are all poor fits; otherwise penalize opening.
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        if fill_ratio > 0.7 {
            score -= 20.0 * (fill_ratio - 0.7) / 0.3;
        } else {
            score += 15.0 * (1.0 - fill_ratio);
        }
        // Late in the stream, prefer consolidating into existing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    }

    // Mild preference for tighter fits overall.
    score += 0.2 * post_residual as f64 / bin_capacity as f64 * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Prefer tight fits: reward small post_residual nonlinearly.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += fit_ratio * fit_ratio * 40.0;

    // Penalize large dead space when item nearly fills the bin is good:
    // reward high fill fraction.
    let fill = item_size as f64 / bin_residual as f64;
    score -= fill * fill * 25.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if the next item fits well in the post residual, reward this placement.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let next_fit = (post_residual - next_item_size) as f64 / bin_capacity as f64;
            score -= 12.0 * (1.0 - next_fit);
        } else {
            // Next item won't fit here; penalize leaving awkward residuals.
            score += 6.0;
        }
    }

    // Global state coupling: many open bins with high mean residual -> prefer
    // filling existing bins rather than spreading.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if open_bins_count > 2 && mean_residual > item_size as f64 * 1.5 {
        score -= 8.0 * (1.0 - progress);
    }

    // New-bin candidate: make empty bins less attractive unless current bin
    // would leave unusable sliver or the item is large relative to residuals.
    if bin_residual == bin_capacity {
        let sliver = post_residual > 0 && post_residual < 10;
        let poor_alternative = mean_residual < item_size as f64;
        if !sliver && !poor_alternative && fitting_bins_count > 0 {
            score += 45.0;
        } else {
            score += 5.0;
        }
        // Late in stream, opening new bins is more acceptable.
        score -= 15.0 * progress;
    }

    // Mild penalty for tiny residuals that become dead space.
    if post_residual > 0 && post_residual < 8 {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Non-linear waste penalty: quadratic in post_residual scaled by capacity.
    score += (post / cap) * (post / cap) * 30.0;

    // Smooth stream-progress coupling: later in the stream, waste is costlier.
    score += progress * post * 0.35;

    // Reward tight fits: cubic falloff of reward as post_residual grows.
    let tightness = 1.0 - post / cap;
    score -= tightness * tightness * tightness * 25.0;

    // Penalize bins whose residual deviates strongly from mean residual
    // (smooth interaction, keeps residual distribution homogeneous).
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += dev * dev * 20.0;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin (smooth exponential reward).
    if fitting_bins_count <= 1 {
        score -= 40.0 * (-post / cap).exp();
    }

    // Lookahead coupling: if next item fits exactly in post_residual, reward;
    // smooth interaction between post_residual and next_item_size.
    if next_item_size > 0 {
        let gap = (post - next_item_size as f64).abs();
        let fit_next = 1.0 / (1.0 + gap / cap);
        score -= fit_next * 18.0 * (1.0 - progress * 0.5);
    }

    // Mild penalty for proliferating open bins when residual is large.
    score += open_bins_count as f64 * (post / cap) * 2.0;

    // New-bin candidate: brand-new empty bin should only win when existing
    // bins are poor fits; give it a smooth handicap based on item size.
    if bin_residual == bin_capacity {
        score += 15.0 + (item_size as f64 / cap) * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let is_new_bin = bin_residual == bin_capacity;

    // Harmonic class of post_residual: bins whose leftover falls in a "usable"
    // class (divisible by common small sizes) are worth more; penalize dead space.
    let pr = post_residual;
    let usable = if pr == 0 { 3.0 }
        else if pr % 10 == 0 { 2.0 }
        else if pr % 5 == 0 { 1.0 }
        else if pr % 2 == 0 { 0.5 }
        else { 0.0 };

    // Reward usable leftovers, scaled by remaining stream length.
    score -= usable * (1.0 + 2.0 * (1.0 - progress));

    // Perfect fit gets a strong bonus.
    if pr == 0 {
        score -= 50.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big bonus.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 40.0;
        } else if next_item_size <= pr {
            // Fractional capacity match quality: how well next item divides leftover.
            let frac = next_item_size as f64 / pr as f64;
            score -= 15.0 * frac * frac;
        } else {
            // Leftover too small for next item: mild penalty unless it's a usable class.
            score += 5.0 * (1.0 - usable / 3.0);
        }
    }

    // Last-chance bin: strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 12.0;
    }

    // New-bin candidate: penalize relative to mean residual of open bins;
    // opening a bin when open bins are already loose is wasteful.
    if is_new_bin {
        score += 8.0 + mean_residual * 0.3;
        // Late in the stream, prefer closing out open bins.
        score += 15.0 * progress;
        // But if nothing fits well (post_residual would be a bad class), let it win.
        score -= (1.0 - usable / 3.0) * 6.0;
    }

    // Slight preference for filling bins that are already tight.
    score -= (bin_capacity - bin_residual) as f64 * 0.05;

    // Tie-break by open bins count: keep bin count stable when many bins open.
    score += open_bins_count as f64 * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to accept
    // typical future items (1..=10) are heavily penalized.
    if post_residual > 0 && post_residual <= 10 {
        score += 40.0 * (11.0 - post_residual as f64);
    } else if post_residual > 10 && post_residual < 20 {
        score += 8.0;
    }

    // Reward tight fits (small post_residual is already low base, add bonus).
    if post_residual == 0 {
        score -= 25.0; // perfect fill
    }

    // Open-bin pressure: discourage spreading across many bins.
    score += open_bins_count as f64 * 0.6;

    // Last-chance bin: strongly prefer using the only bin that fits,
    // otherwise a new bin gets opened.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: an empty bin should only win when no
    // open bin fits well. Make the empty bin moderately unattractive.
    if bin_residual == bin_capacity {
        score += 15.0;
        // But if the current item leaves a residual that the NEXT item
        // could use, opening a fresh bin aligned with the lookahead is good.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 22.0;
        }
    }

    // Lookahead coupling: prefer bins whose post_residual exactly or
    // closely accommodates the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 10.0 / (1.0 + slack);
    }

    // Slight preference to use bins with residuals below the mean
    // (consolidate small leftovers rather than fragmenting large ones).
    if bin_residual < bin_capacity && (bin_residual as f64) < mean_residual {
        score -= 2.0;
    }

    // Late in the stream, be more conservative: keep residual quality high.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.3 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual), with mild normalization.
    score += (post_residual as f64 / bin_capacity as f64) * 20.0;

    // Aggressive 2-step lookahead: reward if the next item fits into post_residual.
    if next_item_size > 0 && post_residual >= next_item_size {
        // Perfect chaining: next item exactly fills the bin -> strong reward.
        if post_residual == next_item_size {
            score -= 60.0;
        } else {
            // Reward proportional to how well the next item uses the leftover space.
            let chain_util = next_item_size as f64 / post_residual as f64;
            score -= 40.0 * chain_util;
        }
    } else if next_item_size > 0 {
        // Next item does NOT fit here: penalize, worse if post_residual is dead space
        // (too small for typical items but nonzero).
        let deadness = if post_residual > 0 && post_residual < next_item_size {
            1.0 - (post_residual as f64 / next_item_size as f64)
        } else {
            0.0
        };
        score += 15.0 * deadness;
    }

    // Compare post_residual against mean residual of open bins:
    // leaving less than the mean residual suggests creating an outlier hole.
    if post_residual as f64 > mean_residual {
        score += 0.3 * (post_residual as f64 - mean_residual);
    } else {
        score -= 0.15 * (mean_residual - post_residual as f64);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        // When many bins fit, mild penalty to break ties toward best fit only.
        score += 2.0 * (fitting_bins_count as f64 - 1.0).min(10.0);
    }

    // New-bin candidate: penalize opening a new bin unless the item is large
    // relative to residual pattern (i.e., current bin fits are poor).
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin.
        score += 45.0;
        // If next item is large and won't chain well anywhere, a new bin
        // can still be reasonable: reduce penalty slightly.
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            score -= 10.0;
        }
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    }

    // Small penalty for very wasteful placements (large dead space that no
    // plausible item can use).
    if post_residual > 0 && post_residual < 10 {
        score += 20.0; // unusable sliver
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual relative to capacity.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 0.6 * tightness * (bin_capacity as f64);

    // Penalize leaving dead space that few future items could use.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0; // tiny unusable sliver
    } else if post_residual >= 10 && post_residual <= 30 {
        score -= 4.0; // still usable by small items
    }

    // Lookahead: if the next item fits in the post-residual, reward this placement.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 8.0;
            // bonus if next item then leaves another usable residual
            let next_post = post_residual - next_item_size;
            if next_post <= 30 {
                score -= 3.0;
            }
        } else {
            score += 5.0; // breaks the chain for the lookahead item
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a new bin is attractive when current
    // open bins are fairly full (mean residual low) or many bins are open.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let avg_fill = 1.0 - mean_residual / (bin_capacity as f64);
        // penalize new bin mildly by default; discount when bins are nearly full
        score += 15.0
            - 20.0 * avg_fill
            - 5.0 * progress
            - (open_bins_count as f64).min(10.0);
        // if item is large, opening a fresh bin is often better
        if item_size > bin_capacity / 2 {
            score -= 6.0;
        }
    } else {
        // Prefer filling bins that are already more loaded (less mean deviation).
        let dev = mean_residual - bin_residual as f64;
        score += 0.15 * dev;
    }

    // Mild preference to keep number of open bins from exploding early.
    if open_bins_count > 20 {
        score += 0.5 * (open_bins_count as f64 - 20.0).min(10.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: wasted space after placement, penalized quadratically (dead space is nonlinearly bad)
    let mut score = pr + 40.0 * norm_pr * norm_pr * cap;

    // Smooth non-linear coupling of post_residual with stream progress:
    // early on, waste is tolerable; late in the stream, waste is costly.
    let progress_weight = 1.0 + 2.0 * progress * progress;
    score *= progress_weight;

    // Tight-fit reward: smooth sigmoid-like term favoring small post_residual
    let tightness = (-norm_pr * 8.0).exp() - 1.0;
    score -= 15.0 * tightness * (0.5 + 0.5 * progress);

    // Penalize bins whose residual deviates from the mean residual (smooth coupling)
    let dev = (mean_residual - pr) / cap;
    score += 10.0 * dev * dev * cap;

    // Last-chance bin: strong reward to use the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Lookahead coupling: reward if next item fits the post residual smoothly
    if next_item_size > 0 {
        let fits_next = (pr >= next_item_size as f64) as f64;
        let snug = 1.0 - ((pr - next_item_size as f64) / cap).abs();
        score -= 12.0 * fits_next * snug.max(0.0);
    } else {
        // last item: only post-residual matters, damp other terms slightly
        score -= 5.0 * norm_pr;
    }

    // Mild penalty for spreading across many open bins (encourage consolidation late)
    score += (open_bins_count as f64).ln().max(0.0) * 0.5 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residual mod 10 buckets.
    let r = post_residual;
    let class = r % 10;

    // Perfect-fit reward (zero residual is ideal).
    if r == 0 {
        score -= 1000.0;
    }

    // Penalize "dead" residuals that are too small for typical future items
    // (items >= 1, but small residuals < 10 are nearly useless).
    if r > 0 && r < 10 {
        score += 40.0;
    }

    // Harmonic class reward: residuals that are multiples of 10 are more
    // reusable by items drawn on a 10-grid; multiples of 5 next best.
    if class == 0 {
        score -= 12.0;
    } else if class == 5 {
        score -= 6.0;
    } else {
        score += (10 - class) as f64 * 0.8; // smoother fill toward next multiple of 10
    }

    // Lookahead coupling: if next item fits exactly into post_residual,
    // strongly favor this bin (chain of perfect fills).
    if next_item_size > 0 {
        if next_item_size == r {
            score -= 300.0;
        } else if next_item_size < r {
            // Next item fits: reward proportional to how well it fills remainder
            let npost = r - next_item_size;
            score -= (r - npost) as f64 * 0.5;
            if npost % 10 == 0 {
                score -= 8.0;
            }
        } else {
            // Next item won't fit here: mild penalty proportional to leftover size
            score += (r as f64) * 0.15;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor it
    // to avoid opening a new bin for a poor fit.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 150.0;
    }

    // New-bin candidate handling: empty bin (residual == capacity).
    // Only attractive when no open bin fits well or open bins are crowded.
    if bin_residual == bin_capacity {
        let pressure = if open_bins_count == 0 {
            1.0
        } else {
            (mean_residual / bin_capacity as f64).clamp(0.0, 1.0)
        };
        // Base penalty so open bins with decent residuals win; relax under pressure.
        score += 90.0 - 80.0 * pressure;
        // If nothing else fits, opening is fine.
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
    }

    // Tightness reward: bins whose residual is close to item size are tight fits.
    let tightness = (bin_residual - item_size) as f64 / bin_capacity as f64;
    score += tightness * 20.0;

    // Slight global pressure: prefer filling bins when many are open.
    score -= (open_bins_count as f64).ln().max(0.0) * 2.0;

    // Phase term: later in stream, be more aggressive about closing gaps.
    let phase = step_index as f64 / (total_items.max(1) as f64);
    score -= phase * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small for the smallest plausible item are wasted.
    let min_item = 1.0f64;
    if (post_residual as f64) < min_item.max(0.0) {
        score += 1000.0;
    }
    // Unusable gap: post_residual smaller than next item AND smaller than typical sizes => strong penalty
    if next_item_size > 0 && (post_residual as u32) < next_item_size {
        score += 25.0 + 0.5 * post_residual as f64;
    }

    // Reward tight fits (small post_residual relative to item size)
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * tightness;
    // Perfect fit bonus
    if post_residual == 0 {
        score -= 60.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: penalize adding to bins when many are open, to encourage consolidation
    score += (open_bins_count as f64) * 0.8 * (post_residual as f64 / bin_capacity as f64);

    // Mean residual coupling: if this bin's residual is far below mean, it's already dense; prefer it
    score -= (mean_residual - bin_residual as f64).clamp(-50.0, 50.0) * 0.3;

    // Lookahead: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 80.0;
    } else if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size < 10 {
        score -= 20.0;
    }

    // New-bin candidate handling: only attractive when no good open option exists
    if bin_residual == bin_capacity {
        // base cost of opening a bin; grows with stream progression (sunk bins)
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = 55.0 + 40.0 * progress;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            // new bin leaves full room for next item: mild discount early
            score -= 10.0 * (1.0 - progress);
        }
        if fitting_bins_count <= 1 {
            score -= 45.0; // no alternative: opening is fine
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Perfect-fit reward: fill the bin exactly.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: reward if the next item exactly fills
    // the post_residual of this bin (chain fit).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;
        if (pr - nxt).abs() < 1.0 {
            score -= 500.0;
        } else if nxt <= pr {
            // next item still fits after this placement: good chaining,
            // reward proportionally to how tightly it fits.
            score -= 60.0 * (1.0 - (pr - nxt) / cap);
        } else {
            // next item won't fit here: penalize leaving large dead space
            // relative to the next item's size.
            score += 0.5 * (pr - nxt).min(pr);
        }
    }

    // Compare post_residual against mean residual across open bins:
    // leaving less than average waste is good.
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using the only bin that fits,
    // avoiding a new bin opening.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 250.0;
    }

    // Penalize opening a new bin when good existing fits exist,
    // unless the item is large and fits poorly everywhere.
    if bin_residual == bin_capacity {
        score += 120.0;
        if item_size as f64 > 0.7 * cap {
            score -= 100.0; // big items: fresh bin is fine
        }
    }

    // Late in the stream, be greedier about tight fits.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 50.0 * (1.0 - post_residual as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post-residual relative to capacity)
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += tightness * tightness * 30.0;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 50.0;
    }

    // Penalize dead space that no plausible future item can use
    let progress = step_index as f64 / total_items.max(1) as f64;
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny unusable sliver
    }

    // Lookahead: reward bins whose leftover can host the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0;
        } else {
            score += (next_item_size - post_residual) as f64 * 0.4;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin when open bins exist,
    // unless the item fits poorly everywhere (handled by last-chance bonus)
    if bin_residual == bin_capacity {
        let open_pressure = if open_bins_count == 0 { 0.0 } else { 1.0 };
        score += 35.0 * open_pressure
            - (mean_residual / bin_capacity as f64) * 20.0 * open_pressure;
        // Late in the stream, closing gaps matters more; slightly favor new bins
        score -= progress * 10.0;
    }

    // Prefer bins with residuals far from the mean (diversity of gap sizes)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score -= dev * 0.1;

    // Mild preference for fuller bins as stream progresses
    score -= (1.0 - tightness) * progress * 8.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * (1.0 - norm_pr); // peaks at half-full bins
    score -= 8.0 * poly * (1.0 + progress);

    // Penalize large dead space quadratically as stream advances
    score += 0.02 * pr * pr * progress / cap;

    // Reward tight fits
    let tightness = 1.0 - norm_pr;
    score -= 3.0 * tightness * tightness;

    // Lookahead: reward residual that can host the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            score -= 5.0 * (1.0 - (pr - nx) / cap);
        } else {
            score += 4.0 * (nx - pr) / cap;
        }
    }

    // Last-chance bin before opening a new one
    if fitting_bins_count == 1 {
        score -= 6.0;
    }

    // Mild pressure against proliferation of open bins
    score += 0.05 * open_bins_count as f64 * progress;

    // Pull toward mean residual to keep bins balanced
    score += 0.5 * (pr - mean_residual) / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: mod 10 buckets create stepped preferences.
    let cls = post_residual % 10;
    // Residuals that are "nice" (small, or exact multiples of common item sizes) get rewarded.
    let harmonic_bonus: f64 = match cls {
        0 => -18.0, // multiple of 10: highly reusable
        5 => -10.0, // multiple of 5
        2 | 4 | 6 | 8 => -4.0, // even
        _ => 6.0,   // odd primes-ish: dead space risk
    };
    score += harmonic_bonus;

    // Integer-division thresholds on post_residual: tiny leftovers are dead space.
    let q = post_residual / 10;
    if q == 0 {
        score += 25.0; // post_residual < 10: nearly unusable
    } else if q <= 2 {
        score -= 8.0; // 10..=29: still useful for small items
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Fraction of capacity: penalize leaving large but awkward gaps.
    let frac = post_residual as f64 / bin_capacity as f64;
    if frac > 0.5 {
        score += 12.0 * frac; // wasteful split of a bin
    }

    // Lookahead coupling: if next item fits exactly into post_residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            score -= 15.0;
            // harmonic match: next item size shares class with post_residual
            if (next_item_size % 10) == cls {
                score -= 10.0;
            }
        } else {
            // next item won't fit here: slight penalty for stranding residual
            score += 5.0 + 0.1 * (post_residual as f64);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when open bins are crowded or fit is terrible.
    if bin_residual == bin_capacity {
        let crowded = open_bins_count as f64 * (mean_residual / bin_capacity as f64);
        score += 55.0 - 20.0 * crowded;
        // Opening a new bin is good if item is large and nothing fits well.
        if item_size > bin_capacity / 2 && fitting_bins_count == 0 {
            score -= 25.0;
        }
        // Late in stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 * progress;
    }

    // Mild pressure to fill bins tightly as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (1.0 - frac);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest plausible
    // item (<= ~12) are "dead space" -> heavy penalty scaled by how dead they are.
    if post_residual > 0 && post_residual <= 12 {
        score += 60.0 * (1.0 - post_residual as f64 / 12.0);
    } else if post_residual > 12 && post_residual <= 25 {
        // semi-dead zone: mild penalty
        score += 8.0 * (1.0 - (post_residual as f64 - 12.0) / 13.0);
    } else if post_residual == 0 {
        // perfect fit: strong reward
        score -= 40.0;
    }

    // Reward tight fits relative to bin residual (small waste ratio).
    if bin_residual > 0 {
        let waste_ratio = post_residual as f64 / bin_residual as f64;
        score += 10.0 * waste_ratio;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless dead space would be created).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones;
    // the new-bin candidate (bin_residual == bin_capacity) gets penalized via
    // its large post_residual already, but add explicit pressure.
    if bin_residual == bin_capacity {
        score += 15.0 + 3.0 * open_bins_count as f64;
    } else {
        score -= 1.5 * open_bins_count as f64;
    }

    // Lookahead coupling: if the next item fits exactly in the post_residual,
    // reward this placement strongly (chain fit).
    if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 5 {
        score -= 20.0;
    }
    // If next item cannot fit here but could fit if we kept more residual, slight penalty.
    if next_item_size > 0 && next_item_size > post_residual && next_item_size <= bin_residual {
        score += 5.0;
    }

    // Stream progression: late in the stream, consolidate harder (favor existing bins).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= 10.0 * progress;
    }

    // Mean-residual coupling: bins with residual far below mean are more "used up";
    // prefer bins whose residual is close to what we need (avoid scattering).
    score += 0.1 * (mean_residual - bin_residual as f64).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let pr = post_residual as f64;
    let nis = next_item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Perfect 2-step match: strong reward
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else {
            let d = pr - nis;
            if d < 0.0 {
                // dead space: next item cannot fit here
                score += (-d) * 0.8;
            } else {
                // usable leftover, but prefer tightness
                score -= d * 0.15;
            }
        }
    }

    // Reward tight fits relative to mean residual
    score -= (mean_residual - pr).max(0.0) * 0.3;
    score += (pr - mean_residual).max(0.0) * 0.1;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Penalize opening new bins when many bins are already open and stream is early
    if bin_residual == bin_capacity {
        score += 15.0 + 10.0 * (open_bins_count as f64).ln().max(0.0) + 20.0 * (1.0 - progress);
        // new bin is attractive only if the leftover here is genuinely usable by next item
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 12.0;
        }
    }

    // Mild preference for small dead space overall
    score += (pr * pr) / (bin_capacity as f64 * 4.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits: small post_residual relative to capacity.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that likely cannot be used by future items.
    if post_residual > 0 {
        if post_residual < 10 {
            score -= 6.0; // nearly perfect fit
        } else if post_residual < 20 {
            score -= 2.0;
        } else if post_residual < 30 {
            score += 1.5; // moderately wasted space
        } else {
            score += 4.0 * (post_residual as f64) / 100.0; // large dead space
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Lookahead: reward if the next item fits into the post-residual (chaining).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let chain_eff = 1.0 - ((post_residual - next_item_size) as f64) / (bin_capacity as f64);
            score -= 8.0 * chain_eff;
        } else if bin_residual >= next_item_size && post_residual < next_item_size {
            // This bin could fit next item but current item blocks it mildly.
            score += 2.0;
        }
        // Penalize leaving a gap that is just barely too small for the next item.
        if post_residual > 0 && post_residual < next_item_size && post_residual >= 5 {
            score += 3.0;
        }
    }

    // Global state coupling: with many open bins, prefer consolidating into
    // bins whose residual is near the mean (avoid fragmenting outliers).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Time horizon: late in the stream, be more conservative about spreading
    // items across bins; prefer bins with less residual left overall.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += progress * (bin_residual as f64) * 0.08;

    // Opening a new bin is acceptable early (many items remain) but costly late.
    if bin_residual == bin_capacity {
        let new_bin_cost = 20.0 * (1.0 - progress) + 30.0 * progress;
        // Only open a new bin if existing bins are very poor fits.
        let poor_fit = if post_residual > 40 { 1.0 } else { 0.0 };
        score += new_bin_cost - 25.0 * poor_fit * progress;
    }

    // Mild penalty for accumulating too many open bins relative to stream length.
    if total_items > 0 {
        let bin_ratio = open_bins_count as f64 / (total_items as f64).max(1.0);
        score += 5.0 * bin_ratio;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let fill_ratio = 1.0 - (post_residual as f64 / cap);

    // Reward tight fits more strongly as the stream progresses (smooth polynomial coupling)
    let tightness = (fill_ratio * fill_ratio) * (1.0 + 3.0 * progress * progress);
    score -= 12.0 * tightness;

    // Penalize leaving small unusable residuals (dead space), scaled by progress
    let dead = if post_residual > 0 {
        let r = post_residual as f64 / cap;
        r * (1.0 - r) * (1.0 - r)
    } else {
        0.0
    };
    score += 20.0 * dead * (1.0 + progress);

    // Lookahead: reward if next item fits the post-residual
    if next_item_size > 0 && next_item_size <= post_residual {
        let chain = 1.0 - ((post_residual - next_item_size) as f64 / cap);
        score -= 6.0 * chain * (0.5 + progress);
    } else if next_item_size > 0 {
        score += 3.0 * (1.0 + progress);
    }

    // Last-chance bonus: only bin that fits
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Penalize opening new bins when good fits exist among open bins
    if bin_residual == bin_capacity {
        let open_pressure = open_bins_count as f64;
        let mean_gap = (mean_residual - post_residual as f64).abs();
        score += 8.0 + 2.0 * open_pressure + mean_gap * 0.5;
    } else {
        // Mild preference for bins with residual close to mean (balanced usage)
        score += 0.3 * (bin_residual as f64 - mean_residual).abs();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: perfect fits and small dead zones.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Reward near-perfect fits (post_residual in small harmonic classes).
    if post_residual == 0 {
        score -= 200.0; // exact fit is ideal
    } else if post_residual <= 10 {
        score -= 60.0;
    } else if post_residual <= 20 {
        score -= 25.0;
    }

    // Modulo-10 harmonic classes: residuals divisible by 10 pair well
    // with typical item sizes.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 15.0;
    }

    // Integer-division thresholds: post_residual bucketed by quarters.
    let quarter = bin_capacity / 4;
    if post_residual < quarter {
        score -= 8.0; // tight bin, good packing
    } else if post_residual > 3 * quarter {
        score += 10.0; // leaving bin nearly empty wastes capacity
    }

    // Lookahead coupling: can next item fit in the post residual?
    if next_item_size > 0 {
        if next_item_size > post_residual {
            score += 20.0; // dead space for the known next item
        } else if post_residual - next_item_size <= 10 {
            score -= 30.0; // next item nearly closes this bin
        } else {
            score -= (post_residual - next_item_size) as f64 * 0.3;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Penalize opening new bins when existing bins have healthy residuals.
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus penalty proportional to
        // how well existing bins could absorb the item.
        score += 100.0
            + 10.0 * (fitting_bins_count as f64)
            - 0.5 * mean_residual
            - 30.0 * (step_index as f64 / total_items.max(1) as f64);
    }

    // Mild preference to fill bins with large residuals early in stream.
    score += 0.05 * (bin_residual as f64 - mean_residual);

    // Small noise-free tiebreak by bin residual class (divisibility by 5).
    if bin_residual % 5 != 0 {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to host
    // anything useful (below the minimum plausible item size ~10) are
    // essentially wasted capacity -> heavy penalty.
    if post_residual > 0 {
        let dead = (10u32.saturating_sub(post_residual)) as f64;
        score += 6.0 * dead;
        // Non-linear escalation for tiny unusable gaps.
        if post_residual < 5 {
            score += 25.0;
        }
    }

    // Perfect fit bonus: strongly reward leaving exactly 0 residual.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Coupling with mean residual: prefer bins whose residual is above the
    // mean (i.e. emptier bins) so tight bins are preserved for tight fits.
    score += 0.5 * (mean_residual - bin_residual as f64).max(0.0);

    // Open-bin pressure: penalize adding to bins when many bins are open,
    // to discourage uncontrolled bin proliferation... but invert: opening a
    // new bin should be discouraged when few bins are open.
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost of opening a fresh bin.
        score = bin_capacity as f64 - 10.0;
        // Cheap to open early in the stream or when open bins are few.
        score -= 15.0 * (1.0 - (open_bins_count as f64 / (open_bins_count as f64 + 4.0)));
        // Discourage opening new bins if the next item is large and current
        // bin could host it too.
        if next_item_size > 0 && next_item_size <= post_residual as u32 {
            score -= 8.0;
        }
        // Last-chance protection: if only this bin fits, never open a new bin.
        if fitting_bins_count == 1 {
            score += 1000.0;
        }
    } else {
        // Last-chance bin: strong bonus to use it rather than open a new one.
        if fitting_bins_count == 1 {
            score -= 30.0;
        }
        // Lookahead: reward placements that still leave room for next item.
        if next_item_size > 0 {
            if post_residual as u32 >= next_item_size {
                score -= 10.0;
            } else if post_residual > 0 {
                score += 8.0; // creates a stranded gap relative to lookahead
            }
        }
        // Mild penalty for very full bins late in stream handled by base
        // post_residual already; add open-bin pressure shaping.
        score += (open_bins_count as f64).sqrt() * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match of post_residual to next item.
    if next_item_size > 0 {
        let match_gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect match -> strong bonus; near-perfect -> scaled bonus.
        let match_bonus = 60.0 * (-match_gap / 12.0).exp();
        score -= match_bonus;

        // If next item fits exactly, heavily favor this bin.
        if post_residual == next_item_size {
            score -= 40.0;
        }
        // Penalize leaving residual that is smaller than next item (dead space for one step)
        // unless it is tiny (< 10), which is near-perfect packing.
        if post_residual < next_item_size && post_residual >= 10 {
            score += 15.0;
        }
    } else {
        // Last item: minimize leftover directly (already in base score).
        score -= 10.0;
    }

    // Contextual adjustment: relative to mean residual across open bins.
    let prog = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mean_gap = post_residual as f64 - mean_residual;
    score += 0.25 * mean_gap * (0.5 + prog);

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin, especially early/mid stream.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0 + 25.0 * (1.0 - prog);
    }

    // New-bin candidate: penalize opening a new bin when open bins exist and fit,
    // unless the current item is huge relative to capacity (fresh space valuable).
    if bin_residual == bin_capacity {
        if open_bins_count > 0 && fitting_bins_count >= 1 {
            let fresh_need = (item_size as f64 / bin_capacity as f64).powi(3);
            score += 30.0 * (1.0 - fresh_need) + 10.0 * (1.0 - prog);
        } else {
            score -= 5.0;
        }
    }

    // Mild preference for tighter bins (waste minimization) with nonlinear scaling.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 8.0 * tightness * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: strongly favor small post_residual relative to capacity.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 2.0 * tightness * tightness * bin_capacity as f64;

    // Perfect-fit bonus.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual < 10 {
        score -= 50.0;
    }

    // Penalize creating dead space that no plausible item can fill.
    // Assume min item size ~1..10; residual below 10 is nearly dead.
    if post_residual > 0 && post_residual < 5 {
        score += 200.0; // tiny unusable sliver
    }

    // Lookahead coupling: if the next item fits exactly into the post residual,
    // reward heavily; if next item cannot fit, mild penalty for wasted chain.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let chain = post_residual - next_item_size;
            score -= 30.0 - (chain as f64) * 0.5;
        } else {
            score += 5.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0 + 0.5 * (post_residual as f64);
    }

    // New-bin candidate logic: opening a new bin is attractive when current bins
    // are fragmented (high mean residual spread) or few bins fit the item.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = (mean_residual - post_residual as f64).abs();
        // Base cost of opening a bin, discounted late in the stream.
        let mut new_bin_score = 60.0 - 30.0 * progress;
        // If item is large, a fresh bin guarantees fit; encourage it.
        if item_size > bin_capacity / 2 {
            new_bin_score -= 20.0;
        }
        // If the item fits poorly anywhere (few fitting bins), fresh bin is fine.
        if fitting_bins_count <= 1 {
            new_bin_score -= 15.0;
        } else {
            new_bin_score += 10.0 * (fitting_bins_count as f64).ln();
        }
        // Fragmentation of existing bins favors opening fresh capacity.
        new_bin_score -= fragmentation * 0.2;
        score += new_bin_score;
    } else {
        // Reward spreading load: prefer bins with residual far below mean
        // (consolidating small residuals), penalize dumping into already-full-ish bins.
        let dev = bin_residual as f64 - mean_residual;
        score += 0.15 * dev;
        // Mild penalty for overusing many open bins: encourage filling existing ones.
        score -= (open_bins_count as f64).ln().max(0.0);
    }

    // Small time-horizon modulation: early in the stream, be conservative
    // (avoid waste); late, be greedy about tight fits.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.1 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Smooth polynomial coupling: penalize residual more as stream progresses
    let pr = post_residual as f64 / bin_capacity as f64;
    score += 30.0 * pr * pr * (0.5 + progress);

    // Reward tight fits smoothly
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 15.0 * tightness * tightness;

    // Lookahead: favor bins whose post-residual can host the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        let reuse = next_item_size as f64 / post_residual as f64;
        score -= 10.0 * reuse * (1.0 - progress);
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize mildly early, more when many bins open
    if bin_residual == bin_capacity {
        score += 20.0 + 2.0 * open_bins_count as f64 * (0.3 + progress);
    }

    // Deviation from mean residual: prefer bins with less residual than average
    score += 0.3 * (post_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: reward residuals that fall into
    // "usable" classes (divisible by common item-size buckets).
    let pr = post_residual;
    if pr > 0 {
        // Residuals divisible by 10 (or 5) are more likely reusable.
        if pr % 10 == 0 {
            score -= 8.0;
        } else if pr % 5 == 0 {
            score -= 3.0;
        } else {
            score += 2.0;
        }
        // Harmonic ladder: residual in [0,10) is dead space, penalize hard.
        if pr < 10 {
            score += 25.0 + (10 - pr) as f64;
        }
    } else {
        // Perfect fit: strong reward.
        score -= 40.0;
    }

    // Coupling with next item size: if next item fits exactly in post_residual,
    // this is a great chain placement.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 30.0;
        } else if next_item_size < pr {
            // how well next item harmonizes with post residual
            let slack = pr - next_item_size;
            if slack % 10 == 0 {
                score -= 6.0;
            }
            score += slack as f64 * 0.15;
        } else {
            // next item won't fit here; mild penalty for tight residuals
            score += 1.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else if fitting_bins_count > 2 {
        // many alternatives: prefer tightest fit, add mild spread penalty
        score += 2.0;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive
    // if the item fits poorly everywhere (large post residual would be wasted).
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score = bin_capacity as f64 * 0.55;
        // Attractive when item is large (little waste) and few bins fit it.
        score -= (item_size as f64 / bin_capacity as f64) * 20.0;
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 5.0;
        }
    }

    // Stream progression: late in the stream, waste matters more (no future
    // to amortize), so penalize residual harder.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += post_residual as f64 * 0.1 * progress;

    // Prefer bins with below-mean residual (tighter bins) when many bins open.
    if open_bins_count > 1 {
        let diff = mean_residual - bin_residual as f64;
        score += diff * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the lookahead item
    // (or for the smallest plausible item, 1) are wasted capacity.
    let usable_threshold = if next_item_size > 0 { next_item_size } else { 1 };
    if post_residual < usable_threshold && post_residual > 0 {
        // Dead space penalty: smaller gaps are proportionally more wasteful.
        score += 12.0 + (usable_threshold - post_residual) as f64 * 0.8;
    }

    // Perfect fit is heavily rewarded.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Reward tight fits relative to bin capacity.
    let fill_ratio = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= 6.0 * fill_ratio;

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // no open bin offers a decent fit. Penalize opening when fitting bins exist
    // with reasonable residuals.
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin.
        score = bin_capacity as f64 * 0.55;
        // If open bins are crowded (high mean residual consumed), opening is fine.
        let mean_free = mean_residual;
        if mean_free < item_size as f64 * 1.2 {
            score -= 10.0;
        }
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 8.0 * progress;
        // Many open bins: discourage spreading further.
        score += open_bins_count as f64 * 1.5;
    }

    // Open-bin pressure: with many open bins, favor placements that consume
    // existing bins rather than leaving them half-used.
    score -= open_bins_count as f64 * 0.35 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Slight bonus for leaving post_residual exactly matching the lookahead item
    // (setting up a perfect follow-up placement).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for near-perfect fits (small post_residual).
    let tightness = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - tightness) * 30.0;
    if post_residual == 0 {
        score -= 60.0; // exact fit: perfect closure
    } else if post_residual < 10 {
        score -= 25.0; // near-exact fit leaves unusable sliver anyway
    }

    // 2-step lookahead: reward when next item fits the post residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0; // perfect chain match
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= (30.0 - slack * 0.6).max(-10.0); // close chain matches rewarded
        } else {
            // next item cannot fit: post residual becomes dead-ish space
            let overflow = (next_item_size - post_residual) as f64;
            score += overflow * 0.25;
        }
    }

    // Penalize creating residuals that no small future item would plausibly use,
    // relative to mean residual across open bins.
    if (post_residual as f64) > mean_residual + 20.0 {
        score += (post_residual as f64 - mean_residual - 20.0) * 0.3;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Mild pressure to fill existing bins when many are open.
    score -= open_bins_count as f64 * 0.15;

    // Late in the stream, prefer tighter packing (less room to recover).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.2;

    // New-bin candidate: only attractive when nothing fits reasonably.
    if bin_residual == bin_capacity {
        score = 100.0 - (fitting_bins_count as f64) * 5.0;
        if fitting_bins_count == 0 {
            score = -100.0; // must open a new bin
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // pairing large consecutive items in fresh bins
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize large dead space relative to smallest plausible future item.
    let dead = post_residual as f64;
    if dead > 0.0 && dead < 10.0 {
        score -= 25.0; // near-perfect fill bonus
    } else {
        score += 0.15 * dead;
    }

    // Lookahead: if next item fits in the post-residual, reward this bin.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 18.0;
        // Extra reward if next item nearly fills remaining space.
        let next_fit = next_item_size as f64 / post_residual.max(1) as f64;
        score -= 12.0 * next_fit;
    } else if next_item_size > post_residual && post_residual > 0 {
        // Dead space that the next item cannot use: penalize more over time.
        let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 10.0 + 20.0 * t;
    }

    // Last-chance bin: strong reward to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // Many open bins: prefer consolidating into existing bins.
    score += 2.0 * (open_bins_count as f64).ln().max(0.0);

    // Mean residual coupling: bins far below mean residual are good targets
    // (they are the "emptier" ones; filling them balances the pool).
    let dev = mean_residual - bin_residual as f64;
    score += 0.08 * dev;

    // New-bin candidate handling: only open a new bin if no open bin fits well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base cost of opening a bin; grows with number of open bins and time.
        let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let open_cost = 45.0 + 3.0 * open_bins_count as f64 + 10.0 * t;
        // If the item is large relative to capacity, a fresh bin is natural.
        let size_bonus = if item_size >= bin_capacity / 2 { -15.0 } else { 0.0 };
        // If the next item is huge, a fresh bin preserves space for it.
        let lookahead_bonus = if next_item_size > bin_capacity / 2 { -8.0 } else { 0.0 };
        score = open_cost + size_bonus + lookahead_bonus + 0.1 * item_size as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Base: penalize wasted post residual, scaled smoothly by stream progress.
    let mut score = pr * (1.0 + 0.8 * progress);

    // Non-linear polynomial coupling of post residual with progress:
    // normalized dead space fraction, cubed, penalizes large unusable gaps late in stream.
    let dead_frac = pr / cap;
    score += 40.0 * dead_frac * dead_frac * dead_frac * (0.3 + progress);

    // Reward tight fits (small post residual) more strongly as stream progresses.
    score -= 25.0 * (1.0 - dead_frac) * (1.0 - dead_frac) * progress;

    // Last-chance bonus: strongly favor the only fitting bin to avoid opening new bins.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: penalize if next item cannot fit into post residual.
    if next_item_size > 0 && (next_item_size as f64) > pr {
        score += 8.0 + 6.0 * progress;
    }

    // Mild penalty when many bins are open relative to items processed (fragmentation guard).
    let frag = open_bins_count as f64 / (step_index as f64 + 1.0);
    score += 5.0 * frag * frag * (1.0 - progress);

    // New-bin candidate: keep it neutral-ish but discourage when a decent fit exists.
    if bin_residual == bin_capacity {
        score += 12.0 * (1.0 - dead_frac) + 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "usable"
    // residue classes (multiples of 10, i.e. common item granules) are favored.
    let usable = post_residual % 10 == 0;
    if usable {
        score -= 6.0;
    } else if post_residual < 10 {
        // Dead space: tiny leftover that almost nothing can use.
        score += 12.0;
    } else {
        score += 4.0;
    }

    // Integer-division threshold classes on post_residual.
    let class = post_residual / 20; // 0..=5 harmonic buckets
    score -= class as f64 * 1.5;

    // Coupling with lookahead: leftover that can host the next item is valuable.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 9.0;
        // Extra reward if the leftover is an exact multiple of the next item.
        if post_residual % next_item_size == 0 {
            score -= 5.0;
        }
    } else if next_item_size > 0 {
        score += 3.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a fresh bin unless the current item
    // is large and would leave a well-structured residual elsewhere is unlikely.
    if bin_residual == bin_capacity {
        score += 18.0;
        // Large items pair naturally with a fresh bin.
        if item_size >= 60 {
            score -= 14.0;
        }
        // Early in the stream, opening bins is cheaper.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 6.0;
    }

    // Prefer bins whose residual is below the mean (denser bins absorb item).
    if (bin_residual as f64) < mean_residual {
        score -= 2.0;
    }

    // Mild pressure on many open bins: pack tighter.
    score += open_bins_count as f64 * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that no item (min size 1..100 range)
    // can use well are heavily penalized. Treat very small gaps (< 12) as dead.
    if post_residual > 0 && post_residual < 12 {
        score += 25.0;
    }
    // Perfect fit: zero residual is excellent.
    if post_residual == 0 {
        score -= 15.0;
    }

    // Tightness reward: relative fill of the bin.
    let fill_ratio = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= 10.0 * fill_ratio;

    // Open-bins pressure: prefer packing into existing bins; penalize spreading.
    score += 0.35 * open_bins_count as f64;

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward;
    // if the next item would not fit here anyway, mild bonus for using this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 18.0;
        } else if next_item_size > post_residual {
            score -= 4.0;
        } else {
            // next item fits but leaves a gap; penalize proportionally to waste
            score += 0.1 * (post_residual - next_item_size) as f64;
        }
    }

    // Deviation from mean residual: prefer bins whose residual is near the mean
    // (balanced packing), avoid extreme outliers.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Stream progression: later in the stream, be slightly more conservative
    // about creating tiny residuals.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if post_residual > 0 && post_residual < 12 {
        score += 15.0 * progress;
    }

    // Brand-new empty bin candidate: only attractive when current bin fit is bad.
    if bin_residual == bin_capacity {
        score += 8.0 + 0.5 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit is perfect.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual
    // closely matches the next item size.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
        score -= 60.0 * (1.0 - gap / bin_capacity as f64).max(0.0);
        if post_residual == next_item_size {
            score -= 400.0; // perfect 2-chain
        }
        // Penalize leaving dead space the next item cannot use.
        if next_item_size > post_residual {
            score += 0.5 * (post_residual as f64);
        }
    }

    // Tight fits relative to capacity are good.
    score -= 30.0 * (item_size as f64 / bin_capacity as f64);

    // Prefer fuller bins vs the mean residual of open bins.
    score += 0.4 * (bin_residual as f64 - mean_residual);

    // Last-chance bin before opening a new bin: strong incentive to use it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 250.0;
    }

    // New-bin candidate: penalize unless current bins are mostly full
    // or this is a poor-fit situation.
    if bin_residual == bin_capacity {
        let avg_fill = 1.0 - mean_residual / bin_capacity as f64;
        score += 120.0 * avg_fill;
        if next_item_size > 0 && next_item_size >= bin_residual {
            score -= 80.0; // fresh bin fits the lookahead perfectly
        }
    }

    // Late in the stream, consolidate harder.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 20.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits: prefer minimal post-residual, normalized.
    score += (post_residual as f64 / cap) * 30.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual < 10 {
        score -= 20.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 80.0;
        } else if next_item_size <= post_residual {
            score -= 15.0 + 10.0 * (1.0 - (post_residual - next_item_size) as f64 / cap);
        } else {
            // Post residual too small for next item: penalize proportionally to wasted space.
            score += 5.0 * (post_residual as f64 / cap);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Penalize opening a brand-new bin when decent alternatives exist.
    if bin_residual == bin_capacity {
        // New bin is attractive only if it enables a perfect future fit or few bins fit.
        let lookahead_bonus = if next_item_size > 0 && (next_item_size + item_size) as f64 <= cap { 10.0 } else { 0.0 };
        let scarcity = if fitting_bins_count == 0 { 0.0 } else { fitting_bins_count as f64 };
        score += 25.0 + 2.0 * open_bins_count as f64 - lookahead_bonus + scarcity;
        // Late in stream, prefer reusing open bins to avoid stranding them.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
    }

    // Global balance: prefer bins whose residual is below the mean (tighter bins),
    // which concentrates waste in fewer bins.
    score += 8.0 * (bin_residual as f64 - mean_residual) / cap;

    // Slight preference for bins with larger residual when item is large (safety margin).
    if item_size as f64 > 0.6 * cap {
        score -= 5.0 * (bin_residual as f64 / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Non-linear polynomial coupling: quadratic dead-space penalty scaled by progress
    let norm_pr = pr / cap;
    score += progress * norm_pr * norm_pr * cap * 0.5;

    // Reward tight fits more strongly as stream progresses
    score -= (1.0 - norm_pr) * (0.5 + progress) * item_size as f64 * 0.3;

    // Penalize new bins (residual == capacity) with smooth interaction
    if bin_residual == bin_capacity {
        score += cap * (0.8 + 0.4 * progress) * (1.0 + (open_bins_count as f64).ln().max(0.0));
    }

    // Last-chance bonus when few fitting bins
    if fitting_bins_count == 1 {
        score -= 5.0 + 10.0 * progress;
    }

    // Lookahead: penalize leaving residual that barely misses next item
    if next_item_size > 0 {
        let gap = (next_item_size as f64 - pr).abs();
        score += 0.15 * progress * (1.0 - gap / cap).max(0.0) * cap * 0.2;
        // Reward residuals that exactly accommodate next item
        if next_item_size as f64 <= pr {
            score -= 3.0 * (1.0 - (pr - next_item_size as f64) / cap);
        }
    }

    // Mild preference toward bins with below-mean residual (consolidation)
    score += 0.1 * ((bin_residual as f64 - mean_residual) / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: how "usable" the leftover space is.
    // Residuals that are multiples of common small item sizes are more reusable.
    let cap_frac = post_residual as f64 / bin_capacity as f64;

    // Penalize very small unusable leftovers (dead space), reward mid-range leftovers.
    if post_residual == 0 {
        score -= 60.0; // perfect fill
    } else if post_residual < 10 {
        score += 45.0; // dead space: too small for anything
    } else if post_residual <= 20 {
        score += 12.0;
    } else if post_residual <= 40 {
        score -= 8.0; // sweet spot: fits typical medium items
    } else if post_residual <= 60 {
        score -= 14.0;
    } else {
        score -= 4.0;
    }

    // Harmonic divisibility bonuses: leftover divisible by 10/20/25 is more likely
    // to be exactly consumed by future items.
    if post_residual % 10 == 0 { score -= 6.0; }
    if post_residual % 20 == 0 { score -= 4.0; }
    if post_residual % 25 == 0 { score -= 3.0; }
    if post_residual % 5 == 0 { score -= 1.5; }

    // Lookahead coupling: if next item fits exactly in post_residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 55.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 18.0 * (1.0 - slack / bin_capacity as f64);
            // penalize if next item leaves a dead remainder
            if (post_residual - next_item_size) < 10 && (post_residual - next_item_size) > 0 {
                score += 10.0;
            }
        } else {
            // next item won't fit here: mild penalty scaled by how badly it misses
            let miss = (next_item_size - post_residual) as f64;
            score += 3.0 * (miss / 40.0).min(2.0);
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate handling: empty bin should only win when open bins are poor fits.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 55.0;
        // Cheaper to open a new bin early in the stream (long horizon to amortize).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 20.0 * (1.0 - progress);
        // If item is large relative to capacity, keeping bins tight matters more.
        if item_size >= 50 { score -= 8.0; }
        // If many bins are open with fat residuals, discourage another.
        if mean_residual > 50.0 && open_bins_count > 2 { score += 15.0; }
    } else {
        // Prefer tighter bins slightly (best-fit bias beyond raw post_residual).
        score += 0.15 * (bin_residual as f64 / bin_capacity as f64) * 10.0;
        // Congestion: when many bins fit the item, mild tie-breaking via mean residual.
        if (bin_residual as f64) > mean_residual {
            score += 2.0;
        } else {
            score -= 2.0;
        }
    }

    // Integer-division threshold on post_residual: quartile classes.
    let q = post_residual / 25;
    score -= match q {
        0 => 0.0,
        1 => 2.0,
        2 => 3.5,
        _ => 2.0,
    };

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual), scaled.
    score = post_residual as f64 * 1.0;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 - (post_residual as f64) * 6.0; // gap of 1 -> +54, gap of 9 -> +6
    }
    // Medium gaps (10..20) mildly penalized since only small items can use them.
    else if post_residual >= 10 && post_residual < 20 {
        score += 4.0;
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 5.0;
    }

    // Open-bin pressure: discourage spreading across many bins unless the fit is good.
    score += (open_bins_count as f64) * 0.3 * (post_residual as f64 / bin_capacity as f64);

    // Last-chance bin: if this is the only fitting bin, opening a new bin wastes it;
    // favor using it unless the dead space penalty already dominates.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // Lookahead coupling: if the next item fits in the post residual, reward it.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0;
    }
    // If next item is large and would leave this bin's residual stranded, mild penalty.
    if next_item_size > post_residual && post_residual > 0 && post_residual < 10 {
        score += 3.0;
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    // Its post_residual = capacity - item_size is naturally large, so it only wins
    // when all open bins fit poorly. Add a mild fixed cost so it doesn't win on ties.
    if bin_residual == bin_capacity {
        score += 8.0;
        // But early in the stream or when many bins are open, opening is cheaper.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 6.0 * (1.0 - progress);
    }

    // Mean-residual coupling: if this bin is far below average residual (already tight),
    // slightly favor other bins with more room to avoid fragmentation.
    score += 0.05 * (mean_residual - bin_residual as f64).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Perfect chaining: post residual exactly matches next item -> big reward.
            if post_residual == next_item_size {
                score -= 30.0;
            } else {
                score -= 12.0;
            }
        } else {
            // Dead space relative to the next item: penalize proportionally.
            let waste = (next_item_size - post_residual) as f64;
            score += 0.35 * waste;
        }
    } else {
        // Last item: pure tightness fit.
        score -= 5.0;
    }

    // Compare against mean residual: prefer bins tighter than average.
    let resid_f = post_residual as f64;
    if resid_f < mean_residual {
        score -= 0.25 * (mean_residual - resid_f);
    } else {
        score += 0.15 * (resid_f - mean_residual);
    }

    // Last-chance bin bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Penalize opening new bins early in the stream; allow more new bins later.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 25.0 - 20.0 * progress;
    }

    // Slight preference for filling existing bins when many are open.
    score += 0.05 * open_bins_count as f64;

    // Tiny tie-breaker: prefer larger items placed into tighter bins.
    score += 0.01 * item_size as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward near-perfect fits.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Tightness: prefer bins where post_residual is small relative to capacity.
        let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
        score -= 60.0 * tightness * tightness;
    }

    // Lookahead: penalize residuals that cannot host the next item (dead space),
    // reward residuals that can host it snugly.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            score += 10.0 + 0.5 * (next_item_size - post_residual) as f64;
        }
    }

    // Last-chance bin: only bin that fits this item -> strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: only attractive when item is large relative to
    // capacity (fresh bin gives a clean large residual) or stream is early.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        let item_ratio = item_size as f64 / bin_capacity as f64;
        let openness = (1.0 - progress).max(0.0);
        let value = 80.0 * item_ratio * item_ratio + 25.0 * openness
            - 3.0 * open_bins_count as f64;
        score += (bin_capacity - post_residual) as f64 - value.max(0.0);
        // baseline penalty so new bins aren't opened for tiny items late in stream
        score += (1.0 - item_ratio) * 30.0 * progress;
    }

    // Global state coupling: prefer bins below mean residual (consolidate space).
    score += 0.3 * (mean_residual - bin_residual as f64);

    // Mild preference for filling fuller bins as stream progresses.
    score += 8.0 * progress * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early on, prefer tight fits (minimize post_residual strongly);
    // later, tolerate residual but reward leaving space for the lookahead item.
    let pr_norm = pr / cap;
    let poly = pr_norm * pr_norm * (1.0 - pr_norm); // peaks mid-range residual
    score += 40.0 * poly * (1.0 - progress);

    // Reward post_residual that can accommodate the next item (smooth kernel).
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let diff = pr - nx;
        let kernel = (-diff * diff / (2.0 * 30.0 * 30.0)).exp();
        score -= 25.0 * kernel;
    }

    // Penalize creating dead space relative to mean residual (smooth).
    let dead = (pr - mean_residual).abs();
    score += 0.15 * dead * dead / cap;

    // Last-chance bin bonus: smooth sigmoid on fitting_bins_count.
    let last_chance = 1.0 / (1.0 + (fitting_bins_count.saturating_sub(1)) as f64);
    score -= 20.0 * last_chance * (1.0 - progress * 0.5);

    // Mild pressure against spreading across many bins late in the stream.
    score += 0.05 * open_bins_count as f64 * progress;

    // Perfect-fill reward with smooth quadratic decay.
    score -= 30.0 * (1.0 - pr_norm) * (1.0 - pr_norm) * (1.0 - pr_norm);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: exact-fill classes are golden.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Perfect fit is unbeatable.
    if post_residual == 0 {
        score -= 1000.0;
        return score;
    }

    // Harmonic classes: post_residual in {1..=10} is near-perfect; treat via integer division thresholds.
    let class = post_residual / 10; // 0..10 harmonic class of dead space
    score += class as f64 * 12.0;

    // Non-linear penalty: tiny residuals are either gold or poison depending on future usefulness.
    if post_residual < 10 {
        score -= 30.0; // tight fit reward
    } else if post_residual < 20 {
        score += 8.0;
    }

    // Reward bins whose residual matches modulo-class of likely next items.
    if next_item_size > 0 && next_item_size <= post_residual {
        // next item fits too: strong reward scaled by how snugly
        score -= 25.0 * (1.0 - (post_residual - next_item_size) as f64 / cap);
    } else if next_item_size > post_residual && next_item_size > 0 {
        // next item won't fit here after placement: penalize proportionally to waste
        score += 10.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin unless residuals are all tiny.
    if bin_residual == bin_capacity {
        score += 55.0;
        if mean_residual < 15.0 && open_bins_count > 0 {
            score -= 30.0; // existing bins nearly full anyway -> new bin is fine
        }
    }

    // Progress coupling: early in stream, keep bins flexible (avoid small residuals);
    // late in stream, pack tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * pr * 0.15;
    score -= progress * pr * 0.05;

    // Favor bins with residual far below mean (already fragmented) to absorb items.
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small to hold the
    // smallest plausible item (<= 10) are pure waste; punish them hard.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Small-but-usable gaps are only useful if the lookahead item fits them.
    if post_residual > 0 && post_residual < 25 {
        if next_item_size > 0 && next_item_size > post_residual {
            score += 15.0; // gap likely wasted even if technically usable
        } else if next_item_size > 0 && next_item_size <= post_residual {
            score -= 20.0; // perfect chain for the lookahead item
        }
    }

    // Reward tight fills (exact or near-exact fits).
    if post_residual == 0 {
        score -= 80.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing ones; opening new bins becomes progressively more expensive.
    let pressure = (open_bins_count as f64).powf(1.3) * 2.0;
    if bin_residual == bin_capacity {
        // New-bin candidate: acceptable only if this bin is a last chance
        // is false (i.e., alternatives exist) and current bins are cramped.
        score += 25.0 + pressure;
        if fitting_bins_count == 1 {
            score -= 90.0; // last-chance bin: strongly prefer it over a new bin
        }
        if post_residual as f64 > mean_residual {
            score += 5.0;
        }
    } else {
        // Existing bin: reward when it is the last chance to avoid a new bin.
        if fitting_bins_count == 1 {
            score -= 35.0;
        }
        // Slight preference for bins whose residual is below the mean
        // (consolidating the fullest bins first).
        if (bin_residual as f64) < mean_residual {
            score -= 6.0;
        } else {
            score += 3.0;
        }
    }

    // Late in the stream, squeeze existing bins harder.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0 * (post_residual == 0) as i32 as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: perfect match with next item
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0; // exact pairing: bin becomes perfectly full after next item
        } else {
            let gap = (post_residual as i64 - next_item_size as i64).unsigned_abs();
            // reward small gaps, penalize larger ones nonlinearly
            score += (gap as f64).powf(1.3) * 0.35;
            if gap <= 10 {
                score -= 12.0;
            }
        }
    } else {
        // last item: minimize leftover as hard as possible
        score += (post_residual as f64 / cap) * 40.0;
    }

    // Tightness reward: small post_residual is good
    score -= (1.0 - post_residual as f64 / cap) * 5.0;

    // Compare against mean residual across open bins:
    // bins with residual below mean are scarcer space; penalize wasting them on loose fits
    if post_residual as f64 > mean_residual {
        score += (post_residual as f64 - mean_residual) * 0.25;
    } else {
        score -= (mean_residual - post_residual as f64) * 0.15;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when no open bin fits well
    if bin_residual == bin_capacity {
        let poor_fit_penalty = if next_item_size > 0 {
            ((item_size as f64 + next_item_size as f64) / cap).min(1.0)
        } else {
            item_size as f64 / cap
        };
        // opening a new bin is good only if current item + next item nearly fill it
        score += 30.0 - poor_fit_penalty * 55.0;
        // opening more bins when many already open is costly
        score += open_bins_count as f64 * 1.5;
    }

    // Slight stream-position modulation: later in the stream, prefer consolidation
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += post_residual as f64 * progress * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let post_norm = post / cap;
    let item_norm = item_size as f64 / cap;

    let mut score = post;

    // Non-linear penalty on residual, modulated by stream progress:
    // early on, tight fits matter less; later, minimize dead space aggressively.
    score += 40.0 * post_norm * post_norm * (0.5 + progress);

    // Reward good fits (small post residual) more strongly as stream progresses.
    score -= 30.0 * (1.0 - post_norm) * (1.0 - post_norm) * progress;

    // Interaction: item size relative to residual — prefer filling large fraction.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 25.0 * fill_ratio * fill_ratio;

    // Smooth coupling with mean residual: avoid bins far below average residual
    // (wasting space) when mean residual is high.
    score += 10.0 * (mean_residual / cap) * (mean_residual / cap) * (1.0 - fill_ratio);

    // Lookahead: penalize leaving residual that neither fits next item well nor is tiny.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post as u32 >= next_item_size {
            let slack = (post - nxt) / cap;
            score += 15.0 * slack * slack;
        } else {
            // next item can't fit here: mild penalty scaled by unusable gap
            score += 8.0 * post_norm * (nxt / cap);
        }
    }

    // Last-chance bin: strongly reward using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0 * (1.0 - post_norm);
    }

    // New-bin candidate: penalize opening new bins, more so early and when
    // many open bins still have room.
    if bin_residual == bin_capacity {
        score += 30.0 + 40.0 * (1.0 - progress) + 5.0 * open_bins_count as f64;
        if fitting_bins_count > 0 {
            score += 25.0;
        }
    }

    // Small smooth jitter-free regularization on very small residuals.
    score += 5.0 * (post_norm * std::f64::consts::PI).sin().abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post * 1.0;

    // Harmonic class of post_residual: residues mod 10 / mod 25
    let r10 = post_residual % 10;
    let r25 = post_residual % 25;
    // Penalize awkward residues (dead space that rarely matches future items)
    if r10 != 0 { score += (10 - r10) as f64 * 0.15; }
    if r25 != 0 { score += (25 - r25) as f64 * 0.10; }

    // Integer-division thresholds: tiny unusable slivers are bad
    if post_residual > 0 && post_residual < 10 {
        score += 40.0; // dead space below min item size
    }
    if post_residual == 0 {
        score -= 30.0; // perfect fit reward
    }

    // Lookahead coupling: reward if next item fits the post residual
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= (next_item_size as f64) * 0.8;
        } else {
            let overflow = (next_item_size - post_residual) as f64;
            score += overflow * 0.3;
        }
        // Harmonic class match between post residual and next item (mod 10)
        if post_residual >= next_item_size && (post_residual % 10) == (next_item_size % 10) {
            score -= 8.0;
        }
    }

    // Tightness: prefer bins where the item fills a large fraction
    let fill_frac = item_size as f64 / cap;
    score -= fill_frac * 20.0;

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive when no good fit exists
    if bin_residual == bin_capacity {
        let poor_fit = post > 0 && post < 20.0;
        if fitting_bins_count == 0 || poor_fit {
            score -= 15.0; // opening a new bin is reasonable
        } else {
            score += 35.0 + 2.0 * (open_bins_count as f64); // prefer existing bins
        }
    }

    // Mild consolidation pressure: favor bins with below-mean residual (fuller bins)
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    } else {
        score += 2.0;
    }

    // Early stream: be slightly greedy with new bins to build a good pool
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= (1.0 - progress) * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 50.0;
    }

    // Dead-space penalty: residuals too small for the smallest item (<=1 assumed tiny),
    // penalize gaps that are unlikely to be reusable relative to next item
    let progress = step_index as f64 / total_items.max(1) as f64;

    if next_item_size > 0 {
        if post_residual < next_item_size {
            // gap unusable by the next item: penalize proportionally to wasted space
            score += 0.8 * post_residual as f64 * (1.0 + 0.5 * progress);
        } else {
            // gap usable by next item: reward
            score -= 0.4 * post_residual as f64;
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open bins pressure: when many bins are open, prefer filling existing ones
    score += 0.15 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Slight preference for bins below mean residual (keep balance)
    if (bin_residual as f64) < mean_residual {
        score -= 2.0;
    }

    // New-bin candidate: only attractive if no open bin fits well
    if bin_residual == bin_capacity {
        score += 5.0 + 0.1 * open_bins_count as f64;
        if next_item_size > 0 && item_size <= next_item_size {
            score += 10.0; // discourage opening new bin when lookahead is bigger
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when post_residual matches next item exactly.
    if next_item_size > 0 {
        let match_gap = (post_residual as i64 - next_item_size as i64).unsigned_abs();
        if match_gap == 0 {
            score -= 45.0; // perfect two-item fill
        } else if post_residual >= next_item_size {
            score -= 12.0 * (1.0 - match_gap as f64 / bin_capacity as f64);
        } else {
            // next item cannot fit here; penalize small dead space that blocks it
            score += 8.0 * (next_item_size - post_residual) as f64 / item_size.max(1) as f64;
        }
    }

    // Relative-to-mean coupling: prefer bins whose residual is below average (tighter bins used first).
    score += 0.35 * (post_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Penalize opening a new bin when existing bins can still pack the item reasonably.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let waste = bin_capacity as f64 - item_size as f64;
        score += 30.0 + 0.25 * waste + 10.0 * (1.0 - progress);
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score += 5.0; // new bin fine for lookahead but don't prefer it
        }
    }

    // Slight preference to fill bins with large residual capacity usage ratio.
    score -= 5.0 * (item_size as f64 / bin_residual.max(1) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (small post_residual is good).
    score -= (bin_capacity as f64 - post_residual as f64) * 0.15;

    // Penalize leaving dead space that typical items cannot use.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0; // unusable sliver
    } else if post_residual >= 10 && post_residual < 20 {
        score += 8.0;
    }

    // Last-chance bin: strong bonus to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if next item fits exactly in post_residual, reward heavily.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual >= next_item_size {
            score -= (next_item_size as f64) * 0.3;
        } else {
            // next item won't fit here; slight penalty proportional to waste
            score += (next_item_size as f64 - post_residual as f64) * 0.1;
        }
    }

    // Prefer fuller bins as the stream progresses (settle into closed bins).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += mean_residual * (0.05 + 0.15 * progress);

    // Discourage spreading across many open bins early; encourage consolidation.
    score += open_bins_count as f64 * 0.5;

    // Brand-new bin candidate: neutral baseline, only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        score += 25.0 + 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Core: non-linear polynomial coupling of post_residual with stream progress
    let mut score = pr * (1.0 + 0.8 * progress) + 40.0 * norm_pr * norm_pr * (0.5 + progress);

    // Reward tight fits more strongly as stream progresses
    let tightness = 1.0 - norm_pr;
    score -= 25.0 * tightness * tightness * (0.4 + progress);

    // Penalize dead space that cannot fit the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr < nx {
            score += 0.5 * (nx - pr);
        } else {
            score -= 0.3 * (1.0 - nx / cap) * (pr - nx).min(nx);
        }
    } else {
        // Last item: strongly prefer filling bins completely
        score -= 30.0 * tightness;
    }

    // Last-chance bin bonus: avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0 + 20.0 * progress;
    }

    // Mild penalty when many bins are open and residual is large (fragmentation)
    let frag = norm_pr * (open_bins_count as f64).ln1p();
    score += 3.0 * frag * (1.0 - progress);

    // New-bin candidate: keep it slightly unattractive unless current bin would waste a lot
    if bin_residual == bin_capacity {
        score += 12.0 - 10.0 * progress - 0.2 * (item_size as f64);
        if next_item_size > 0 && (next_item_size as f64) > item_size as f64 {
            score += 0.1 * (next_item_size as f64 - item_size as f64);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover is 0 or lands in
    // "small residue" classes are ideal; residues that could host future items
    // (10..=80 range granularity) should be penalized less than dead space.
    let pr = post_residual;
    if pr == 0 {
        score -= 40.0; // perfect fit: strongly favored
    } else if pr < 10 {
        score += 30.0; // unusable dead space below minimum item size
    } else {
        // modulo arithmetic on post_residual: classify by divisibility
        if pr % 10 == 0 {
            score -= 6.0; // aligned class, likely reusable
        }
        if pr % 20 == 0 {
            score -= 4.0; // highly reusable harmonic class
        }
        if pr % 50 == 0 {
            score -= 5.0;
        }
    }

    // Integer-division thresholds: fraction of bin still usable after placement
    let fill_frac = (bin_capacity - post_residual) as f64 / cap_f;
    if fill_frac > 0.9 {
        score -= 15.0;
    } else if fill_frac > 0.7 {
        score -= 7.0;
    } else if fill_frac < 0.5 {
        score += 10.0; // wasteful placement into a mostly empty bin
    }

    // Lookahead coupling: does post_residual accommodate next item?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // residue remains useful: mild reward proportional to tightness
            let tight = next_item_size as f64 / post_residual as f64;
            score -= 8.0 * tight;
        } else {
            score += 5.0; // kills lookahead opportunity
        }
    } else {
        // last item: prefer zero residual above all
        score -= 12.0 * fill_frac;
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        // among many candidates, prefer tighter fits
        score += 2.0 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // New-bin candidate handling: only open a new bin when no open bin fits
    // well; make empty-bin score moderately high so it loses to decent fits.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 45.0 + 20.0 * (1.0 - progress);
        // if item is large relative to capacity, opening fresh is more tolerable
        score -= (item_size as f64 / cap_f) * 20.0;
        // many open bins with slack: discourage new bin
        if mean_residual > item_size as f64 {
            score += 15.0;
        }
    } else {
        // prefer bins with smaller residual (tight packing) as baseline
        score += 0.15 * (mean_residual - bin_residual as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful
    // (unusable gaps) are heavily penalized, unless the bin is almost exactly filled.
    let pr = post_residual as f64;
    if post_residual > 0 && post_residual < 12 {
        score += 60.0 - pr * 2.0; // tiny gap = wasted capacity
    } else if post_residual >= 12 && post_residual < 25 {
        score += 8.0; // mildly awkward gap
    }

    // Reward near-perfect fills.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Last-chance pressure: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into existing
    // bins rather than spawning more (mild, uniform-ish tilt that still
    // discriminates against the empty-bin candidate via its large base residual).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let open_pressure = (open_bins_count as f64).ln().max(0.0) * (3.0 + 4.0 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportionally to how many bins already fit.
        score += 25.0 + open_pressure + (fitting_bins_count as f64) * 6.0;
        // But if the item is large and would leave a big usable chunk anyway,
        // soften slightly late in the stream.
        score -= progress * 5.0;
    } else {
        score -= open_pressure * 0.3;
    }

    // Lookahead: if the next item exactly fits the post residual, reward strongly.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 50.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 5.0;
    } else if next_item_size > post_residual {
        // next item cannot use this gap; dead space becomes permanent
        score += pr * 0.2;
    }

    // Slight preference for bins tighter than the mean (keep mean residual low).
    score += (mean_residual - bin_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits (small post residual) nonlinearly.
    score -= (bin_capacity as f64 - post_residual as f64) * 0.05;

    // 2-step lookahead: if the next item exactly fills the post residual, strong reward.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let post = post_residual as f64;
        let diff = (post - next).abs();
        if diff == 0.0 {
            score -= 40.0;
        } else if next <= post {
            // next item fits: reward proportionally to tightness
            score -= (1.0 - diff / bin_capacity as f64) * 15.0;
            // extra reward if next item fills bin completely
            if post == next { score -= 10.0; }
        } else {
            // next item won't fit here; penalize leaving a tempting-but-unusable gap
            score += (next - post) * 0.3;
        }
    }

    // Compare against mean residual: prefer bins tighter than average.
    score += (post_residual as f64 - mean_residual) * 0.4;

    // Last chance bin: avoid opening a new bin if this is the only fitting one.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Penalize new-bin candidate mildly unless current bin would leave big dead space.
    if bin_residual == bin_capacity {
        score += 8.0;
        // opening new bin is attractive if item is large and would leave tiny residual elsewhere anyway
        if item_size >= 70 { score -= 5.0; }
    }

    // Late in stream, consolidate more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0;

    // Penalize many open bins to encourage filling existing ones.
    score += open_bins_count as f64 * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

