    score -= 12.0 * tightness * tightness;

    // Penalize dead space that no future item can plausibly fill
    // (items are at least size 1; strongly penalize residual < typical item sizes).
    if post_residual > 0 && post_residual < 10 {
        score -= 8.0; // near-perfect fill
    } else if post_residual > 60 {
        score += 4.0; // large leftover is wasteful
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Lookahead: if the next item can use the post-residual, reward this placement.
    if next_item_size > 0 {
