            score -= 6.0 + 4.0 * (next_item_size as f64 / post_residual as f64);
        } else if post_residual > 0 && next_item_size > bin_residual {
            // next item can't fit anywhere well; keep residual flexible
            score += 2.0;
        }
    }

    // New-bin candidate handling: only open a new bin when no open bin offers a good fit.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 55.0;
        // More acceptable late in the stream or when many bins are open and mean residual is low.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 20.0 * progress;
        if open_bins_count > 0 {
            let spread = (mean_residual - item_size as f64).abs();
            score += 0.3 * spread;
        }
        if fitting_bins_count == 0 {
            score -= 60.0; // no alternative, must open
        }
    } else {
        // Prefer bins whose residual is close to the item (minimizes waste).
        let gap = (bin_residual - item_size) as f64;
        score += 0.15 * gap;
        // Slight preference to fill bins with lower residual first (compactness).
        score += 0.05 * bin_residual as f64;
    }

    // Mild pressure to consolidate: fewer open bins relative to items favors reuse.
    if open_bins_count > 0 {
        score += 0.02 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
