        let match_quality = 1.0 - (fits_next / cap).min(1.0);
        score -= match_quality * match_quality * 35.0;
        // Penalize when next item barely misses fitting the post residual.
        let miss = (nx - pr) as f64;
        if miss > 0.0 && miss <= 10.0 {
            score += (1.0 - miss / 10.0) * 15.0;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // Many open bins: prefer filling existing bins rather than spreading.
    let ob = open_bins_count as f64;
    score += (ob / (ob + 5.0)) * (10.0 + 20.0 * progress);

    // Mean residual coupling: if this bin's residual is far below the mean,
    // it is already tightly packed — reward closing it out.
    let dev = (mean_residual - r) / cap;
    score -= dev * dev * 30.0;

    // New-bin candidate: neutral-ish baseline, only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        score = 80.0 + 40.0 * progress + (ob / (ob + 4.0)) * 30.0;
        if fitting_bins_count <= 1 {
            score -= 60.0; // no real alternative, opening is fine
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Harmonic class of the post residual: classify leftover space by capacity fraction bands.
    let post_class = (post_residual * 4) / bin_capacity; // 0..3 harmonic band
    // Dead-space penalty: small leftovers (< 10, min item size) are pure waste.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Band-dependent shaping: band 0 (very full bin) is desirable, high bands less so.
    match post_class {
        0 => score -= 25.0,
        1 => score -= 5.0,
        2 => score += 5.0,
        _ => score += 10.0,
    }

    // Lookahead coupling: reward if next item fits exactly into the post residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 80.0;
        } else if next_item_size < post_residual {
            let nxt_class = (next_item_size * 4) / bin_capacity;
            score -= 10.0 - (nxt_class as f64) * 2.0;
        } else {
            score += 15.0;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin to avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when no open bin is a good home
    // (i.e., mean residual is small relative to the item) or many bins are open.
    if bin_residual == bin_capacity {
        let pressure = item_size as f64 / mean_residual.max(1.0);
        score = 20.0 + cap * 0.5;
        if mean_residual < item_size as f64 {
            score -= 30.0 + pressure * 10.0;
        }
        if open_bins_count > 8 {
            score += (open_bins_count as f64 - 8.0) * 2.0;
        }
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Slight progression tilt: prefer consolidating early, spreading later.
    if total_items > 0 {
        let t = step_index as f64 / total_items as f64;
        score -= t * 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (1.0 - post_residual as f64 / 10.0);
    }

    // Reward tight fits (low post_residual relative to item size).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead: reward if next item fits into post_residual exactly or well.
    if next_item_size > 0 && post_residual >= next_item_size {
        let next_fit = (post_residual - next_item_size) as f64;
        score -= 8.0 * (1.0 - next_fit / bin_capacity as f64);
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Post-residual too small for the lookahead item: dead space penalty.
        score += 10.0;
    }

    // Pressure from open bins count: discourage spreading across many bins.
    score += 0.35 * open_bins_count as f64 * (step_index as f64 / total_items.max(1) as f64);

    // Penalize bins whose residual deviates badly from the mean residual (fragmentation).
    score += 0.15 * (bin_residual as f64 - mean_residual).abs();

    // New-bin candidate handling: base penalty so we prefer existing bins,
    // but allow opening when no open bin fits or only a poor fit exists.
    if bin_residual == bin_capacity {
        let new_bin_penalty = 20.0 + 2.5 * open_bins_count as f64;
        if fitting_bins_count == 0 {
            score = -50.0; // must open a new bin
        } else if post_residual as f64 > mean_residual + 15.0 && fitting_bins_count > 1 {
            score = new_bin_penalty;
        } else {
            score = new_bin_penalty + 30.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Near match: next item fits with small slack.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Next item cannot fit here; penalize proportional to leftover unusability.
        let gap = (next_item_size - post_residual) as f64;
        score += 0.5 * gap;
    }

    // Penalize very small dead space that nothing (min size 1) may later use well.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Slight preference for bins tighter than the mean residual (best-fit flavor).
    score += 0.3 * (mean_residual - bin_residual as f64);

    // New-bin candidate: mildly discouraged unless current bin would leave big waste.
    if bin_residual == bin_capacity {
        score += 12.0;
    }

    // Late in the stream: consolidate harder.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 - 0.15 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (non-linear).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 8.0 * fit_ratio * fit_ratio;

    // Penalize dead space relative to capacity, especially small unusable slivers.
    if post_residual > 0 && post_residual < 10 {
        score += 6.0; // sliver likely unusable
    }

    // Lookahead coupling: reward if post_residual exactly fits next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 12.0;
        } else if post_residual >= next_item_size {
            score -= 2.0;
        } else {
            // next item cannot use leftover: penalize proportionally
            score += 1.5 * (1.0 - post_residual as f64 / next_item_size as f64);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Time horizon: early in stream, be picky (penalize mediocre fits);
    // late in stream, consolidate aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 6.0 * progress * fit_ratio;

    // Global state: many open bins with high mean residual -> prefer filling existing bins.
    if open_bins_count > 2 && mean_residual > item_size as f64 {
        score -= 2.0 * (mean_residual / bin_capacity as f64);
    }

    // New-bin candidate: only attractive when no good fit exists or item is large.
    if bin_residual == bin_capacity {
        let good_fit_exists = fitting_bins_count > 0 && fit_ratio > 0.7;
        if good_fit_exists || (fitting_bins_count > 0 && item_size < 40 && progress < 0.8) {
            score += 10.0; // discourage opening new bin
        } else if fitting_bins_count == 0 {
            score -= 5.0; // must open
        }
    }

    // Mild penalty for leaving residual close to common small item sizes (waste prevention).
    for s in [10u32, 20, 25, 30, 40, 50].iter() {
        if post_residual > *s && post_residual < *s + 8 {
            score += 1.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Base: reward tight fits via non-linear coupling of post_residual with progress.
    let mut score = post * (1.0 + 0.8 * progress * post / cap);

    // Penalize leaving awkward residuals that can't fit typical items: smooth U-curve.
    let r = post / cap;
    score += 6.0 * r * (1.0 - r) * (1.0 - r) * (1.0 - progress);

    // Lookahead: bonus if next item fits in post_residual (smooth reward).
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 4.0 * (1.0 - (next_item_size as f64 / cap)) * (0.5 + 0.5 * progress);
    }

    // Penalize opening a new empty bin, more strongly late in the stream.
    let is_new = bin_residual == bin_capacity;
    if is_new {
        score += 8.0 + 10.0 * progress + 0.05 * open_bins_count as f64;
    } else {
        // Last-chance bin gets a strong reward to avoid opening bins.
        if fitting_bins_count == 1 {
            score -= 5.0 + 3.0 * progress;
        }
        // Slight reward for using bins with larger residuals (balance spreading).
        score -= 0.3 * (bin_residual as f64 - mean_residual) / cap;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Base: strong best-fit pressure, scaled dead-space penalty (quadratic).
    score += 0.02 * (post_residual as f64) * (post_residual as f64) / cap;

    // Harmonic classes of post_residual: dead space in small classes is nearly unusable.
    let pr = post_residual;
    if pr > 0 {
        let class: u32 = match pr {
            0..=10 => 0,
            11..=20 => 1,
            21..=35 => 2,
            36..=50 => 3,
            _ => 4,
        };
        score += [6.0, 4.0, 2.0, 0.5, 0.0][class as usize];
        // Modulo-style granularity penalty: residual not near multiples of 10 wastes slots.
        let m = pr % 10;
        score += 0.3 * (5.0 - (m as f64 - 5.0).abs());
    }

    // Perfect fit reward.
    if pr == 0 {
        score -= 20.0;
    }

    // Lookahead: reward if the next item fits into the post residual (chaining).
    if next_item_size > 0 {
        if next_item_size <= pr {
            score -= 4.0 + 0.05 * next_item_size as f64;
        } else {
            // Penalize leaving residual that next item cannot use but is close (near-miss waste).
            let gap = next_item_size - pr;
            if gap <= 10 {
                score += 0.4 * gap as f64;
            }
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bin fit is bad,
    // or many open bins already and the stream is early (keep future flexibility).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let waste = (bin_capacity as f64 - item_size as f64) / cap;
        score = 30.0 + 40.0 * waste - 15.0 * progress
            - if next_item_size > 0 && next_item_size <= bin_capacity { 3.0 } else { 0.0 }
            + 2.0 * (open_bins_count as f64).sqrt();
    }

    // Mild tie-break toward bins already below mean residual (consolidation).
    score += 0.05 * ((bin_residual as f64) - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful
    // for typical items (1..100, min item 1) are penalized super-linearly.
    // A residual below ~10 is nearly dead space; below ~20 is risky.
    let r = post_residual as f64;
    if r < 10.0 {
        score += (10.0 - r) * 4.0; // hard dead space
    } else if r < 20.0 {
        score += (20.0 - r) * 1.5; // risky gap
    }

    // Reward near-perfect packing: tiny post_residual gets a bonus.
    if r == 0.0 {
        score -= 30.0;
    } else if r <= 3.0 {
        score -= 15.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post residual,
    // strongly favor this bin; if next item is close, mild bonus.
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if n == r {
            score -= 40.0;
        } else if n <= r {
            score -= 8.0 * (r / n).ln().max(0.0);
        } else if n <= r + 10.0 {
            // next item almost fits: slight penalty for wasting that chance
            score += 3.0;
        }
    }

    // Last-chance pressure: if this is the only fitting bin, avoid opening a
    // new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0 + 0.05 * (post_residual as f64);
    }

    // Open-bin pressure: many open bins -> discourage spreading, prefer filling
    // existing bins tightly; few open bins -> opening a new bin is cheap.
    let pressure = (open_bins_count as f64).ln().max(0.0) * 2.0;
    score += pressure * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate handling: an empty bin has residual == capacity.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, modulated by how bad the best
        // alternative likely is (high mean residual => alternatives fine).
        score = bin_capacity as f64 * 0.9;
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a new bin
        } else if fitting_bins_count == 1 {
            score += 25.0; // prefer using the last-chance bin
        }
        if open_bins_count > 0 && mean_residual > item_size as f64 * 1.5 {
            score += 20.0; // plenty of room elsewhere, don't open
        }
        if next_item_size > 0 && next_item_size as f64 >= bin_capacity as f64 * 0.9 {
            score -= 15.0; // keep a fresh bin for a big next item
        }
    }

    // Mild progression coupling: later in the stream, tighten packing further.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * (post_residual as f64 * 0.3);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: strongly favor small post_residual (best-fit core).
    let tight = post_residual as f64 / bin_capacity as f64;
    score -= 12.0 * (1.0 - tight) * (1.0 - tight);

    // Exact or near-exact fill is excellent.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 10 {
        score -= 15.0;
    }

    // Dead-space penalty: residual too small to ever fit typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward if the next item fits the post residual.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 18.0;
        } else {
            // next item won't fit here; mild penalty scaled by leftover size
            score += 4.0 * tight;
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Crowding: when many bins are open, prefer consolidation into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 2.0 * (open_bins_count as f64).ln().max(0.0);

    // Mean residual coupling: bins with residual far below mean are good targets
    // (they are being "closed out"); bins far above mean are better left for later.
    let dev = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    score += 8.0 * dev;

    // New-bin candidate handling: empty bin starts at residual == capacity.
    if bin_residual == bin_capacity {
        // Base new-bin cost: discourage unless current bins fit poorly.
        score += 30.0;
        // If only one bin (or none) can fit the item, opening is fine.
        if fitting_bins_count <= 1 {
            score -= 35.0;
        }
        // Late in the stream, avoid opening bins with large leftover potential.
        score += 10.0 * progress;
        // If the next item is large, a fresh bin gives it room.
        if next_item_size > 0 && next_item_size > bin_residual - item_size {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let post_norm = post / cap;
    let fit = item_size as f64 / cap;

    // Core: quadratic coupling of post_residual with stream progress.
    // Early stream: mild preference for tight fits (post_residual small).
    // Late stream: strong preference to exhaust bins completely.
    let progress_weight = 0.5 + 1.5 * progress * progress;
    let mut score = post * (1.0 + progress_weight * post_norm);

    // Dead-space penalty: cubic in post_residual, amplified by item size
    // (large items leaving big gaps are worse than small ones).
    let dead = post_norm * post_norm * post_norm;
    score += 40.0 * dead * (0.5 + fit);

    // New-bin candidate handling: an empty bin gets a baseline penalty so we
    // only open it when no open bin gives a decent fit; the penalty relaxes
    // smoothly as the stream progresses and mean residual shrinks.
    let is_new_bin = (bin_residual as f64 - cap).abs() < 1e-6;
    if is_new_bin {
        let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
        score += 6.0 + 30.0 * (1.0 - progress) * (1.0 - 0.5 * (mean_residual / cap))
                 - 8.0 * scarcity * fit;
    } else {
        // Last-chance bonus: if this is the only bin that fits, strongly favor it
        // to avoid opening a new bin.
        if fitting_bins_count == 1 {
            score -= 5.0 + 10.0 * progress;
        }
        // Reward bins whose residual after placement matches the next item
        // (smooth lookahead coupling, only when a lookahead exists).
        if next_item_size > 0 {
            let nxt = next_item_size as f64;
            let gap = (post - nxt) / cap;
            score -= 6.0 * (-gap * gap * 8.0).exp() * (0.5 + progress);
        }
        // Slight preference for bins tighter than the mean (consolidation).
        score += 2.0 * (post - mean_residual) / cap;
    }

    // Open-bin count pressure: with many open bins, prefer filling existing
    // ones over leaving them scattered (smooth sigmoid-ish coupling).
    let pressure = open_bins_count as f64 / (open_bins_count as f64 + 4.0);
    score += 4.0 * pressure * post_norm;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "reusable"
    // classes (multiples of common small sizes) are favored.
    let reusable: [u32; 6] = [10, 20, 25, 30, 40, 50];
    let mut class_bonus = 0.0;
    for r in reusable.iter() {
        if post_residual >= *r && post_residual % r == 0 {
            class_bonus = 8.0;
            break;
        }
        if post_residual % r == 0 {
            class_bonus = 4.0;
        }
    }
    score -= class_bonus;

    // Perfect fit is heavily rewarded.
    if post_residual == 0 {
        score -= 200.0;
    }

    // Penalize tiny dead space that no item (>=1) can still use poorly:
    // leftover in (0, 10) is nearly dead.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 120.0;
        } else if next_item_size < post_residual {
            score -= 10.0 + (post_residual - next_item_size) as f64 * 0.3;
        } else {
            // next item won't fit here; penalize proportionally to wasted capacity
            score += (next_item_size - post_residual) as f64 * 0.2;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 {
        score -= 60.0;
    } else if fitting_bins_count > 1 {
        score += 5.0 * (fitting_bins_count as f64 - 1.0);
    }

    // New-bin candidate handling: empty bin gets neutral residual (capacity),
    // discourage opening a new bin when good fits exist, encourage when
    // remaining open bins have low mean residual.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = bin_capacity as f64
            - 30.0 * (mean_residual / bin_capacity as f64)
            + 20.0 * progress;
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    } else {
        // Prefer bins tighter than the mean (better packing pressure).
        let diff = mean_residual - bin_residual as f64;
        score += diff * 0.5;
    }

    // Mild pressure to consolidate when many bins are open.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for the
    // smallest possible item (size 1..=10) are pure waste. Penalize them
    // super-linearly so bins with unusable slivers are deprioritized.
    let dead_threshold: f64 = 9.0;
    if (post_residual as f64) > 0.0 && (post_residual as f64) <= dead_threshold {
        score += (dead_threshold - post_residual as f64 + 1.0).powf(2.2) * 12.0;
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 60.0;
    } else if (post_residual as f64) <= 4.0 {
        score -= 25.0;
    }

    // Coupling with mean residual: placing into a bin whose residual is far
    // below the mean concentrates packing (good); far above the mean is bad.
    score += (bin_residual as f64 - mean_residual) * 0.9;

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading into
    // fresh bins; the new-bin candidate should score worse as open count grows.
    if bin_residual == bin_capacity {
        score += 30.0 + 8.0 * open_bins_count as f64;
    } else {
        score -= 3.0 * open_bins_count as f64;
    }

    // Lookahead: if the next item fits exactly into the post residual,
    // reward this placement (chain fit).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 35.0;
        } else if post_residual > next_item_size {
            score -= 8.0;
        }
    }

    // Slight early-stream conservatism: keep options open at the start.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - progress) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Non-linear tightness preference: super-linear penalty on leftover space.
    score = post.powf(1.25) / cap.powf(0.25);

    // Reward near-perfect fills (post_residual small relative to capacity).
    if post <= 5.0 {
        score -= 20.0;
    } else if post <= 10.0 {
        score -= 10.0;
    }

    // Lookahead (k=2): if the next item fits into the post residual, reward;
    // if it doesn't fit but the residual is large, penalize dead space.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            score -= 6.0 * (1.0 - nxt / cap);
        } else {
            // Dead space that the next item cannot use.
            score += 0.15 * post.min(nxt);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Penalize opening a brand-new bin when other bins could fit,
    // unless the item is huge and leaves little residual anyway.
    if bin_residual == bin_capacity {
        let fit_bonus = if fitting_bins_count > 0 {
            let best_alternative = (item_size <= 70) as f64;
            12.0 * best_alternative
        } else {
            0.0
        };
        score += fit_bonus;
        // Opening new bins early is fine (room for future items), later it's wasteful.
        let t = step_index as f64 / (total_items.max(1) as f64);
        score += 10.0 * t;
    } else {
        // Favor bins whose residual deviates favorably from the mean (reuse lopsided bins).
        let dev = (bin_residual as f64 - mean_residual) / cap;
        score -= 3.0 * dev;
    }

    // Mild penalty for proliferating open bins.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let fit_frac = item_size as f64 / cap;
    let pr_frac = pr / cap;

    let mut score = pr;

    // Reward tight fits: non-linear bonus for small post_residual
    score -= 40.0 * (1.0 - pr_frac).powi(6);

    // Stream-progress coupling: early on, prefer moderate residuals; late, chase tight fits harder
    score -= (1.0 - progress) * 15.0 * pr_frac * (1.0 - pr_frac);
    score -= progress * 30.0 * (1.0 - pr_frac).powi(3);

    // Penalize dead space relative to mean residual of open bins
    score += 0.3 * (pr - mean_residual).max(0.0);

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 {
        score -= 25.0 + 20.0 * progress;
    }

    // Lookahead: favor bins whose residual can still hold the next item
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if pr as f64 >= ni {
            score -= 10.0 * (1.0 - (pr as f64 - ni) / cap);
        } else {
            score += 8.0 * (ni - pr as f64) / cap;
        }
    }

    // Mild penalty for spreading across too many open bins early
    score += 0.5 * open_bins_count as f64 * (1.0 - progress) * fit_frac;

    // New-bin candidate: only attractive when no open bin fits well
    if bin_residual == bin_capacity {
        score += 20.0 + 30.0 * (1.0 - fit_frac);
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits; strong reward for very small post_residual.
    if post_residual == 0 {
        score -= 1000.0; // perfect fit is always best
    } else if post_residual <= 5 {
        score -= 120.0;
    } else if post_residual <= 10 {
        score -= 60.0;
    }

    // Harmonic class of item size: classify by capacity fractions.
    let frac = item_size as f64 / bin_capacity as f64;
    let class = if frac > 0.5 { 1 }
        else if frac > 1.0 / 3.0 { 2 }
        else if frac > 0.25 { 3 }
        else { 4 };

    // Dead-space penalty scaled by harmonic class: big items tolerate waste less.
    let dead = post_residual as f64 / bin_capacity as f64;
    score += match class {
        1 => 400.0 * dead,
        2 => 250.0 * dead,
        3 => 150.0 * dead,
        _ => 90.0 * dead,
    };

    // Modulo arithmetic on post_residual: residuals that pair with common
    // small-item sizes (multiples of 10/5) are reusable, reward them.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 25.0;
    } else if post_residual % 5 == 0 && post_residual > 0 {
        score -= 10.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 80.0;
        if post_residual - next_item_size <= 10 {
            score -= 70.0;
        }
    }
    // Penalize leaving a residual that is just barely too small for next item
    // (unusable sliver relative to lookahead).
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 0.5 * (next_item_size - post_residual) as f64;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 55.0;
        if post_residual > 0 && post_residual < 10 {
            score -= 40.0;
        }
    }

    // New-bin candidate handling: opening a new bin is expensive early and when
    // many bins are open; encourage consolidation when open bins are roomy.
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin: its residual is large, so add opening penalty.
        score += 30.0 + 8.0 * open_bins_count as f64;
        // If mean residual across open bins is large, opening new bin is wasteful.
        score += 1.5 * mean_residual;
        // Late in the stream, prefer closing out existing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 60.0 * progress;
        // If next item is large and no open bin hints, new bin may be fine: soften.
        if next_item_size > 60 && fitting_bins_count == 0 {
            score -= 50.0;
        }
    }

    // Small global tie-breaker: mildly prefer bins with below-average residual
    // (denser bins) to keep others flexible.
    if bin_residual != bin_capacity {
        score -= 0.3 * (mean_residual - bin_residual as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny gaps are nearly worthless.
    let dead_threshold = 9.0f64;
    if (post_residual as f64) < dead_threshold {
        score += 60.0; // creating an unusable sliver
    } else if post_residual == 0 {
        score -= 40.0; // perfect fill
    }

    // Reward tight fits (small post_residual relative to capacity).
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 30.0 * tightness * tightness;

    // Last chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, favor filling.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (0.6 + 0.8 * progress);

    // Prefer bins whose residual is above mean (keep big holes for big items)?
    // No: prefer consuming bins that are already small-residual (consolidation).
    if (bin_residual as f64) < mean_residual {
        score -= 8.0;
    }

    // Lookahead: if next item fits the post residual, bonus.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 12.0;
    }
    // If next item would leave another dead gap, slight penalty.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && (post_residual as f64) < dead_threshold {
        score += 15.0;
    }

    // New-bin candidate: opening a new bin is costly; only attractive when
    // item is large and would leave a large usable residual elsewhere anyway.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 20.0 + 10.0 * (1.0 - progress);
        if item_size >= 60 {
            score -= 10.0; // large items are fine starting fresh bins
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual).
    score = post_residual as f64 * 1.0;

    // Aggressive 2-step lookahead: reward when next item fits the post residual exactly-ish.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as f64) >= nxt {
            let gap = post_residual as f64 - nxt;
            // Perfect chaining (gap 0) is heavily rewarded.
            score -= 30.0 * (1.0 - gap / bin_capacity as f64);
            // Extra bonus if the chain leaves another small residual for future items.
            if gap <= 10.0 {
                score -= 15.0;
            }
        } else {
            // Next item cannot fit here: post space is likely dead space; penalize.
            let dead = nxt - post_residual as f64;
            score += 8.0 + 0.5 * dead;
        }
    } else {
        // Last item: just minimize waste.
        score -= 20.0;
    }

    // Compare against mean residual: bins with residual far below mean are "special";
    // wasting them hurts more. Penalize large post_residual relative to mean_residual.
    if post_residual as f64 > mean_residual {
        score += 0.6 * (post_residual as f64 - mean_residual);
    } else {
        score -= 0.3 * (mean_residual - post_residual as f64);
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (avoid fragmentation).
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate (empty bin): make it attractive only when item is large
    // relative to capacity or open bins are numerous/fragmented.
    if bin_residual == bin_capacity {
        let frac = item_size as f64 / bin_capacity as f64;
        // Large items start fresh bins cheaply; small items should reuse open bins.
        score = 40.0 * (1.0 - frac) + 2.0 * open_bins_count as f64;
        // If next item pairs well with leftover (100 - item), opening is good.
        if next_item_size > 0 && (bin_capacity - item_size) >= next_item_size {
            score -= 20.0;
        }
        // Last-chance override: never open when an existing bin is the only fit.
        if fitting_bins_count == 1 {
            score += 100.0;
        }
    }

    // Mild stream progression term: later in stream, consolidation matters more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 3.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: quadratic bonus for small post_residual
    let tightness = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - tightness) * (1.0 - tightness) * 40.0;

    // Lookahead: reward if next item fits into post_residual
    if next_item_size > 0 && next_item_size <= post_residual {
        let chain = next_item_size as f64 / bin_capacity as f64;
        score -= 12.0 + 18.0 * chain;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Dead space risk: post_residual unusable by next item
        let waste = post_residual as f64;
        score += 0.15 * waste;
        // If next item fits nowhere else anyway, dead space matters less
        if next_item_size > bin_residual {
            score -= 0.1 * waste;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate handling
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin
        let mut new_bin_score = 30.0;
        // Early in stream: opening bins is cheaper (builds a pool)
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        new_bin_score -= 20.0 * (1.0 - progress);
        // Many open bins with high mean residual: reuse instead
        new_bin_score += (open_bins_count as f64) * 1.5;
        new_bin_score += (mean_residual - 50.0).max(0.0) * 0.4;
        // If item is large relative to typical residual, new bin is fine
        new_bin_score -= (item_size as f64 / bin_capacity as f64) * 10.0;
        // Few/no fitting alternatives favor opening
        if fitting_bins_count == 0 {
            new_bin_score -= 40.0;
        }
        score = new_bin_score;
    } else {
        // Mild reward for draining bins when many are open
        if open_bins_count > 3 {
            score -= (bin_residual as f64 / bin_capacity as f64) * (open_bins_count as f64);
        }
        // Prefer bins with residual below mean (compact them)
        if (bin_residual as f64) < mean_residual {
            score -= 4.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let mut score = pr * (1.0 + 0.6 * progress * x) + 40.0 * x * x * (0.5 + progress);

    // Reward tight fits (small post_residual) more strongly later in the stream
    score -= (1.0 - x) * (1.0 - x) * 25.0 * (0.4 + 0.6 * progress);

    // Penalize opening new bins when good fits exist
    if bin_residual == bin_capacity {
        score += 30.0 + 50.0 * (1.0 - progress);
        if fitting_bins_count > 0 {
            score += 60.0 / (fitting_bins_count as f64);
        }
    }

    // Last-chance bin bonus: avoid wasting the only fitting bin on a bad fit
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0 * (1.0 - x);
    }

    // Lookahead: prefer bins leaving room for the next item
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if pr >= n {
            score -= 12.0 * (1.0 - ((pr - n) / cap).abs()) * (0.5 + progress);
        } else {
            score += 10.0 * (n - pr) / cap;
        }
    }

    // Mild pressure toward consolidating residuals near the mean
    score += 0.05 * (pr - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post_residual)
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    } else if post_residual <= 10 {
        score -= 25.0;
    }

    // Harmonic class logic: classify post_residual into dead-space classes
    // via integer division thresholds (post_residual / 10).
    let pr_class = post_residual / 10;
    score += match pr_class {
        0 => -10.0,           // post_residual < 10: near-perfect fit
        1 => 0.0,             // 10..19: acceptable
        2 => 8.0,             // 20..29: moderate waste
        3 => 15.0,            // 30..39
        4 => 22.0,            // 40..49
        _ => 30.0,            // >=50: large dead space
    };

    // Modulo coupling: post_residual % 10 indicates fine-grain dead space;
    // small remainders pair well with typical small items (10-20).
    let rem = post_residual % 10;
    if rem <= 2 && post_residual < 30 {
        score -= 6.0;
    } else if rem >= 8 {
        score += 4.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = post_residual - next_item_size;
        if slack == 0 {
            score -= 45.0;
        } else if slack <= 10 {
            score -= 20.0;
        } else {
            score -= 8.0;
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        // Next item can't use the leftover: penalize proportionally
        score += (post_residual as f64) * 0.3;
    }

    // Last-chance bonus: only this bin fits -> avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: prefer opening a new bin only when
    // the best existing fit is poor (large post_residual) or stream is early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // New bin baseline: moderate score; attractive if open bins are fragmented
        score = 55.0
            - progress * 10.0
            + (open_bins_count as f64) * 0.5
            - mean_residual * 0.1;
        if next_item_size > 0 && next_item_size >= 60 {
            score -= 10.0; // big next item: fresh bin useful
        }
        if post_residual == bin_capacity && item_size > 70 {
            score -= 5.0; // huge item likes a fresh bin
        }
    }

    // Mean-residual context: if mean residual is high, bins are fragmented;
    // slightly favor tighter fits to consolidate.
    if mean_residual > 30.0 && post_residual < (mean_residual as u32) {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A gap is "dead" if it is too small to fit even the smallest plausible item.
    let min_gap = 1u32;
    if post_residual < min_gap {
        score -= 1000.0; // perfect fit, extremely rewarded
    } else if post_residual <= 10 {
        // Small gap: likely unusable dead space -> strong penalty
        score += 40.0 + (10 - post_residual) as f64 * 4.0;
    } else if post_residual <= 25 {
        // Moderate gap: mildly risky
        score += (25 - post_residual) as f64 * 0.8;
    } else {
        // Large gap: still useful, slight reward relative to raw post_residual
        score -= 5.0;
    }

    // Coupling: dead space is worse when many bins are open (bin pressure).
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = (open_bins_count as f64).ln().max(0.0) * (0.5 + progress);
    score += pressure * (post_residual as f64 / bin_capacity as f64) * 10.0;

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly into the post-residual, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack <= 10 {
            score -= 15.0; // next item fills this bin almost perfectly
        } else {
            score -= 3.0;
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        // Next item cannot use the residual -> residual becomes dead space risk
        score += 8.0;
    }

    // Prefer bins tighter than the mean (best-fit flavor), scaled by mean residual.
    if mean_residual > 0.0 {
        let tightness = (mean_residual - bin_residual as f64) / mean_residual;
        score += tightness * 6.0;
    }

    // Mild preference to fill existing bins rather than open new ones.
    if bin_residual == bin_capacity {
        score += 12.0 + open_bins_count as f64 * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = 0.0;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual)
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 20.0 * fit_ratio * fit_ratio;

    // Lookahead: reward if the next item exactly fills the post-residual,
    // penalize if next item can't use the leftover dead space
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0; // perfect chaining
        } else if next_item_size <= post_residual {
            score -= 12.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // dead space likely: penalize large leftovers relative to typical item scale
            let waste = post_residual as f64;
            if waste > 0.0 && waste < 10.0 {
                score -= 8.0; // small crumbs are fine
            } else if waste >= 10.0 && waste < next_item_size as f64 {
                score += 6.0; // unusable gap given lookahead
            }
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: neutral-ish baseline, only chosen when open bins fit badly.
    if bin_residual == bin_capacity {
        // Opening a new bin costs ~1 bin; make it slightly worse than a good fit
        // but better than leaving huge unusable gaps in existing bins.
        score = 45.0 - 0.05 * open_bins_count as f64;
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a new bin
        }
        // Early in stream, opening bins is cheaper (more future utility)
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 15.0 * (1.0 - progress);
    }

    // Global residual coupling: if this bin's residual is far below the mean,
    // it's already cramped — using it consolidates space (reward).
    let dev = mean_residual - bin_residual as f64;
    score += 0.15 * dev;

    // Penalize leaving a bin with residual that no plausible item (1..100) pairs well with
    if post_residual > 0 && post_residual < 10 {
        score -= 10.0; // near-full bin is "closed" efficiently
    }

    // Mild penalty for spreading across many open bins
    score += 0.4 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_norm = pr / cap;

    // Base: waste after placement, softly scaled by non-linear progress coupling
    let mut score = pr * (1.0 + 0.8 * progress * progress);

    // Penalize residuals that are hard to reuse: quadratic dead-space term
    score += 12.0 * fit_norm * fit_norm * (1.0 - fit_norm).powi(2) * cap;

    // Reward tight fits (small post_residual) more strongly as stream progresses
    score -= 30.0 * (1.0 - fit_norm) * (1.0 - fit_norm) * (0.4 + 0.6 * progress);

    // Last-chance bin: strong reward to use it instead of opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + 20.0 * progress;
    }

    // Lookahead: bonus if the next item can fit into post_residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let slack = (pr - nxt) as f64;
            score -= 10.0 * (1.0 - slack / cap) * (0.5 + 0.5 * progress);
        } else {
            score += 6.0 * ((nxt - pr) / cap);
        }
    }

    // Mild penalty for spreading many open bins when mean residual is large
    score += 0.5 * open_bins_count as f64 * (mean_residual / cap).powi(2);

    // New-bin candidate: keep neutral baseline, slightly discouraged early
    if bin_residual == bin_capacity {
        score += 15.0 * (1.0 - progress) + 5.0 * (mean_residual / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward near-perfect fits (post_residual in harmonic low classes).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 30.0;
    } else if post_residual <= 20 {
        score -= 10.0;
    }

    // Harmonic class logic: post_residual classes via division thresholds.
    let class = post_residual / 10; // 0..=10
    score -= (10 - class) as f64 * 2.0;

    // Penalize dead space that no future item can plausibly fill:
    // post_residual < next_item_size and post_residual < 10 (min item size).
    if post_residual > 0 && next_item_size > 0 {
        if post_residual < next_item_size {
            score += post_residual as f64 * 1.5;
        } else {
            // reward bins that can also host the next item (pairing bonus)
            score -= 8.0;
