    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: only attractive when open bins fit poorly.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        if pressure > 0.0 {
            score -= 50.0; // no open bin fits -> open new bin
        } else {
            // opening a new bin wastes mean_residual of all open bins
            score += 70.0 + mean_residual * 0.3 + (open_bins_count as f64) * 2.0;
        }
    }

    // Mild preference for fuller bins relative to mean residual.
    if bin_residual < bin_capacity {
        score += (bin_residual as f64 - mean_residual) * 0.2;
    }

    // Late-stream tightening: reduce tolerance for slack as stream ends.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += post_residual as f64 * progress * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: post_residual in the "unusable gap" band
    // (0 < gap < 10, minimum item size) is pure waste -> heavy penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 + (10.0 - post_residual as f64) * 3.0;
    } else if post_residual == 0 {
