    // a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: many open bins -> prefer consolidating into existing
    // bins rather than opening new ones.
    score += open_bins_count as f64 * 1.5;

    // New-bin candidate handling: only attractive when current bins fit badly
    // (post_residual small but nonzero) or when residual is far below mean.
    if bin_residual == bin_capacity {
        let waste_here = if post_residual < 10 && post_residual > 0 { 90.0 } else { 0.0 };
        score += 55.0 + waste_here - (mean_residual - post_residual as f64).max(0.0) * 0.4;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 45.0;
    } else if next_item_size > 0 && next_item_size > post_residual && post_residual > 0 {
        // Dead space locked against the known next item.
        let unusable = post_residual as f64;
        score += 0.5 * unusable;
    }

    // Late-stream consolidation: as the stream progresses, tighten up.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * 0.3 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
