    }

    // new-bin candidate: penalize unless current fits are very poor
    if bin_residual == bin_capacity {
        score += 55.0;
    }

    // late in stream: consolidate, prefer filling existing bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= 10.0 * progress;
    }

    // many open bins: discourage spreading, favor tight bins
    score += 0.3 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

