        let avg_waste = mean_residual.max(0.0);
        // Prefer new bin when open bins are already quite full / fragmented.
        let new_bin_bonus = 8.0 + 20.0 * (1.0 - avg_waste / bin_capacity as f64) + 10.0 * progress;
        score += new_bin_bonus;
        // Opening bins when many are already open is expensive.
        score += 2.0 * (open_bins_count as f64).ln().max(0.0);
    }

    // Prefer filling bins that are already mostly used (consolidation).
    let fill = 1.0 - (bin_residual as f64) / (bin_capacity as f64);
    score -= 10.0 * fill;

    // Time horizon: later in the stream, be greedier about tight fits.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 15.0 * progress * (1.0 - tightness);

    // Mild penalty proportional to open bins to discourage spreading items.
    score += 0.5 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: quadratic waste penalty with progress-coupled curvature.
    let curvature = 1.0 + 2.0 * progress;
    let mut score = pr * (1.0 + curvature * norm_pr);

    // Reward very tight fits (small post-residual) more strongly later in stream.
    let tightness = 1.0 - norm_pr;
    score -= tightness * tightness * cap * (0.5 + 0.5 * progress);

    // Last-chance bonus: strongly favor the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 0.35 * cap;
    }

    // Lookahead: penalize if post-residual is awkward for next item
    // (next item fits neither cleanly nor is blocked).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt && pr - nxt < 10.0 {
            score += 0.25 * (pr - nxt); // creates tiny dead space
        } else if pr < nxt && pr > 0.0 {
            score += 0.15 * (nxt - pr); // next item can't use this space
        } else if pr >= nxt {
            score -= 0.10 * (1.0 - progress) * (pr - nxt) / cap * cap * 0.1;
        }
    }

    // Mild penalty for opening new bins early / spreading residual too thin.
    if bin_residual == bin_capacity {
        score += cap * (0.05 + 0.10 * (1.0 - progress)) + 0.02 * mean_residual;
    }

    // Dampen fragmentation across many open bins.
    score += 0.01 * open_bins_count as f64 * norm_pr * cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify leftover space into modulo buckets.
    // Small post_residual classes (< 10) are excellent (near-perfect fit) -> reward.
    let pr = post_residual;
    let class = pr % 10;
    if pr == 0 {
        score -= 25.0; // perfect closure
    } else if pr < 10 {
        score -= 18.0 - pr as f64;
    } else if class == 0 {
        score -= 6.0; // clean multiples of 10 pair well with typical sizes
    } else if class >= 5 {
        score -= 2.0;
    } else {
        score += 4.0; // awkward odd remainder
    }

    // Dead-space penalty: leftover too small for the minimum plausible item.
    if pr > 0 && pr < 10 {
        score += 8.0; // unusable sliver
    }

    // Lookahead coupling: does the leftover invite the next item?
    if next_item_size > 0 {
        if next_item_size <= pr {
            score -= 10.0 + (pr - next_item_size) as f64 * 0.3;
        } else {
            // leftover can't host next item; mild penalty scaled by gap
            score += ((next_item_size - pr) as f64).min(20.0) * 0.4;
        }
        // Harmonic pair: post_residual and next_item_size in same decade class
        if pr >= next_item_size && (pr / 10) == (next_item_size / 10) {
            score -= 5.0;
        }
    }

    // Tightness reward: fraction of bin consumed by this placement.
    let fill = (bin_residual - pr) as f64 / cap;
    score -= fill * 15.0;

    // Last-chance bin: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // New-bin candidate handling: empty bin has bin_residual == bin_capacity.
    if bin_residual == bin_capacity {
        // Opening a new bin is attractive only when no open bin fits well
        // (post_residual here equals capacity - item_size; judge it as leftover).
        let fresh_leftover = bin_capacity - item_size;
        if fitting_bins_count == 0 {
            score -= 40.0; // forced: no alternative
        } else if fresh_leftover < 10 {
            score -= 30.0; // item nearly fills a fresh bin anyway
        } else {
            // penalize spreading when existing bins can host the item,
            // unless bins are crowded and residuals are fragmented
            let crowding = open_bins_count as f64 / (1.0 + mean_residual / cap);
            score += 12.0 + crowding.min(10.0);
        }
        // late in the stream, prefer consolidation into open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
    }

    // Mild preference for bins with residuals harmonically aligned to item size.
    let res_class = bin_residual % 10;
    let item_class = item_size % 10;
    if res_class >= item_class && res_class != 0 {
        score -= 1.5;
    }

    // Fragmentation guard: penalize placing into bins far above mean residual
    // (keeps a balanced pool of large residuals for future big items).
    if (bin_residual as f64 - mean_residual).abs() > 30.0 {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small gaps (< 10, minimum item size) are unusable.
    let dead = (post_residual as u32).min(9) as f64;
    score += dead * 30.0;

    // Non-linear penalty on small post-residuals that no typical item can use.
    if post_residual > 0 && post_residual < 20 {
        score += (20 - post_residual) as f64 * 4.0;
    }

    // Reward tight fits (post_residual near zero) strongly.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Reward bins whose residual closely matches the item (exact-fill tendency).
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score += tightness * 0.8;

    // Lookahead coupling: if next item fits in post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }
    // Penalize if next item almost fits but not quite (creates regret).
    if next_item_size > post_residual && next_item_size - post_residual <= 10 {
        score += 10.0;
    }

    // Last-chance pressure: if this is the only fitting bin, strongly favor using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: penalize creating new bins when many bins already open.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure from open bins and mean residual.
        score += 40.0 + open_bins_count as f64 * 3.0 + mean_residual * 0.5 * (1.0 - progress);
    } else {
        // Mild reward for consolidating into existing bins as stream progresses.
        score -= progress * 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Lookahead: reward post_residual exactly matching next item (k=2 chaining)
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 400.0;
        } else if post_residual > next_item_size {
            // leftover after hypothetical next placement
            let chain_left = post_residual - next_item_size;
            if chain_left == 0 {
                score -= 400.0;
            }
            // penalize leaving awkward slivers (1..=9) after chain
            if chain_left > 0 && chain_left < 10 {
                score += 40.0;
            }
        } else {
            // post_residual too small for next item: dead space risk
            score += (next_item_size - post_residual) as f64 * 1.5;
        }
    }

    // Penalize small nonzero residuals (unusable dead space), scaled by capacity
    if post_residual > 0 {
        let r = post_residual as f64;
        if r < 10.0 {
            score += (10.0 - r) * 8.0;
        }
    }

    // Prefer tight bins relative to mean residual of open bins
    score -= (mean_residual - post_residual as f64) * 0.5;

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 300.0;
    }

    // New-bin candidate: penalize mildly so it's chosen only when open bins are poor fits,
    // but relax the penalty as stream progresses and open bins accumulate.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let pressure = (open_bins_count as f64).ln().max(0.0);
        score += 250.0 - 120.0 * progress - 15.0 * pressure;
        // opening a new bin is attractive if next item would fit it too
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 30.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual small relative to capacity
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 8.0 * tightness * tightness;

    // Penalize dead space: residuals too small to ever fit another item
    let min_item = 1u32;
    if post_residual < min_item {
        score += 50.0;
    } else if post_residual < 10 {
        score += 6.0; // small dead-space penalty for tiny residuals
    }

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 15.0;
    }

    // Lookahead: reward if next item fits the post-residual (chaining)
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 5.0 + 0.05 * next_item_size as f64;
        } else {
            // penalize leaving a residual just barely too small for next item
            let miss = (next_item_size - post_residual) as f64;
            if miss < 20.0 {
                score += 0.3 * miss;
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // Many open bins with high mean residual: prefer filling existing bins
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score -= 1.5 * pressure * (bin_residual as f64 / bin_capacity as f64);

    // Time horizon: early on be exploratory (favor new bins less), later consolidate
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 5.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    // Mean residual coupling: if this bin's residual is far above mean, slightly deprioritize
    let dev = bin_residual as f64 - mean_residual;
    score += 0.05 * dev.abs();

    // New-bin candidate handling: only open a new bin when fits are scarce
    if bin_residual == bin_capacity {
        let scarcity = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        let big_item = item_size as f64 / bin_capacity as f64;
        score = 30.0 + 40.0 * scarcity * big_item - 20.0 * (1.0 - scarcity);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let mut score = pr * (1.0 + 0.6 * progress * norm_pr);
    score += 12.0 * norm_pr * norm_pr * (0.5 + progress);

    // Reward tight fits (small post residual), more strongly as stream progresses
    score -= (1.0 - norm_pr) * (1.0 - norm_pr) * 8.0 * (0.3 + 0.7 * progress);

    // Penalize dead space that can't fit a typical next item
    if next_item_size > 0 && (next_item_size as f64) > pr {
        score += 6.0 * progress + 3.0;
    } else if next_item_size > 0 {
        score -= 2.0;
    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0 * (0.5 + progress);
    }

    // Slight preference for consolidating into fewer bins
    score -= (open_bins_count as f64).ln().max(0.0) * (1.0 - norm_pr);

    // Encourage opening fresh bins early when mean residual is low
    if bin_residual == bin_capacity {
        score += 4.0 * (1.0 - progress) * (1.0 - mean_residual / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify leftover space into capacity fractions.
    let pr = post_residual as f64;
    let frac = pr / cap; // fraction of capacity left after placement

    // Penalize residuals that fall into "dead zones": too small to fit typical
    // items (harmonic classes 0..=10, 11..=20, etc. via integer division).
    let class = post_residual / 10; // 0..=10 harmonic class
    score += match class {
        0 => 0.0,                      // perfect-ish fit, ideal
        1 => 4.0,                      // tiny dead space, mostly unusable
        2 => 6.0,
        3 => 7.0,
        4 => 6.0,
        5 => 4.0,                      // ~50% left, still quite usable
        6 => 2.0,
        7 => 1.0,
        8 => 0.5,
        _ => 0.0,
    };

    // Reward tight fits nonlinearly.
    score -= (1.0 - frac) * (1.0 - frac) * 12.0;

    // Lookahead coupling: penalize if the next item cannot use the post residual.
    if next_item_size > 0 {
        if next_item_size > post_residual {
            score += (next_item_size - post_residual) as f64 * 0.35;
        } else {
            score -= (post_residual - next_item_size) as f64 * 0.15;
        }
        // Harmonic pairing: if next item exactly fills post residual, strong reward.
        if next_item_size == post_residual {
            score -= 25.0;
        }
    }

    // Last chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Prefer bins with residual below the mean (consolidating waste).
    score += (mean_residual - pr) * 0.5;

    // Slight pressure to close bins as the stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * pr * 0.05;

    // Mild penalty for opening new bins when many are already open.
    if bin_residual == bin_capacity {
        score += 8.0 + 0.3 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to be useful are heavily penalized.
    let min_useful = 10u32.min(bin_capacity); // smallest plausible item footprint
    if post_residual > 0 && post_residual < min_useful {
        score += 40.0 + (min_useful - post_residual) as f64;
    }

    // Dead space relative to the lookahead item: if the next item can't fit here
    // but could fit a fresh bin, this placement strands capacity.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 15.0 + 0.5 * (next_item_size - post_residual) as f64;
    }

    // Reward perfect and near-perfect fits.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Reward leaving room for the lookahead item (chained fit).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }

    // Last-chance bin: strongly prefer using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading into new bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.6 * open_bins_count as f64 * (0.5 + progress);

    // Prefer bins whose residual deviates favorably from the mean (consolidate fullness).
    score += 0.3 * (mean_residual - bin_residual as f64);

    // New-bin candidate: penalize mildly so it only wins when all open bins score badly.
    if bin_residual == bin_capacity {
        score += 45.0 + 2.0 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Strong reward for exact match, decaying with distance.
        let match_reward = if gap == 0.0 {
            30.0
        } else if gap <= 5.0 {
            15.0 - 2.0 * gap
        } else {
            (5.0 - gap * 0.15).max(0.0)
        };
        score -= match_reward;

        // Penalize post_residual that is too small for the next item (dead space
        // unless it's near zero), but only mildly.
        if next_item_size > post_residual && post_residual > 0 {
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Prefer bins whose residual is already below average (consolidating small residuals).
    score += (mean_residual - post_residual as f64) * 0.4;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Penalize opening a new bin when decent fits exist, but allow it when
    // post_residual would be very small (tight fit) or no other bin fits well.
    if bin_residual == bin_capacity {
        let tight_fit = post_residual <= 10;
        let poor_existing = fitting_bins_count == 0 || mean_residual < item_size as f64 * 0.6;
        if fitting_bins_count > 0 && !tight_fit && !poor_existing {
            score += 25.0;
        } else {
            score -= 5.0;
        }
    }

    // Small bonus for very small post_residual (wasted space minimized).
    if post_residual < 10 {
        score -= (10 - post_residual) as f64 * 0.8;
    }

    // Late in stream: prefer tighter packing, discourage new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += progress * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: prefer bins whose post-residual is small.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 40.0 * fit_ratio * fit_ratio;

    // Penalize post-residuals that become unusable "dead space"
    // (too small for typical items, i.e. < 10% of capacity).
    if post_residual < bin_capacity / 10 {
        score += 25.0 * (1.0 - post_residual as f64 / (bin_capacity as f64 / 10.0));
    }

    // Lookahead: if the next item fits exactly in the post-residual,
    // strongly reward this placement (perfect chain).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // next item still fits: mild reward proportional to fit tightness
            score -= 15.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item won't fit here: slight penalty for leaving awkward gap
            score += 8.0 * (next_item_size as f64 / post_residual as f64 - 1.0).min(2.0);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // When many bins are open, encourage consolidation into existing bins.
    score += (open_bins_count as f64).ln().max(0.0) * 3.0;

    // Time horizon: early in the stream, be more willing to open new bins
    // (keep residuals flexible); late in the stream, pack tightly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress;

    // New-bin candidate handling: an empty bin has neutral post-residual = capacity.
    // Make it attractive only when no open bin fits well (large post-residual there)
    // or when mean residual is high (fragmented state).
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual - post_residual as f64) / bin_capacity as f64;
        // If existing bins are fragmented (high mean residual), opening fresh is fine.
        score += 15.0 - 20.0 * fragmentation.max(0.0);
        // Late in the stream, discourage opening new bins.
        score += 20.0 * progress;
    } else {
        // Reward using bins that are already relatively full.
        let used = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
        score -= 12.0 * used;
    }

    // Slight preference for bins whose residual is close to item size (exact-ish fits)
    let gap = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += 20.0 * gap * gap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_ratio = item_size as f64 / cap;
    let norm_pr = pr / cap;

    // Base: post residual (waste minimization), smoothly amplified by progress.
    let mut score = pr * (0.9 + 0.6 * progress * progress);

    // Non-linear coupling: quadratic penalty on normalized post residual,
    // stronger late in the stream (small dead space increasingly valuable).
    score += 40.0 * norm_pr * norm_pr * (0.5 + progress);

    // Reward tight fits: smooth Gaussian-like term around near-full packing.
    let tightness = (fit_ratio - 1.0).abs();
    score -= 30.0 * (-(norm_pr * norm_pr) * 8.0).exp() * (1.0 - tightness * 0.5);

    // Lookahead coupling: penalize residuals that can't hold the next item,
    // reward residuals that can (smooth logistic interaction).
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let can_hold = 1.0 / (1.0 + (-(pr - nx) * 0.15).exp());
        score -= 12.0 * can_hold * (0.4 + 0.6 * progress);
        // Smooth penalty if this placement strands a large unusable gap
        let stranded = 1.0 / (1.0 + ((nx - pr) * 0.12).exp());
        score += 15.0 * stranded * norm_pr;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0 * (0.6 + 0.4 * progress);
    }

    // Mean-residual coupling: prefer bins deviating below mean residual
    // (consolidate fuller bins), smooth quadratic form.
    score += 0.25 * (mean_residual - pr) * (mean_residual - pr) / cap;

    // Mild penalty for spreading across many open bins late in stream.
    score += 0.4 * open_bins_count as f64 * (0.3 + 0.7 * progress);

    // New-bin candidate: penalize lightly early (reuse bins), more strongly
    // when the item is large (better to fill a fresh bin completely).
    if bin_residual == bin_capacity {
        let early_bias = 1.0 - progress;
        score += 6.0 * early_bias + 10.0 * (1.0 - fit_ratio);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: dead space in (0, 10) is nearly unusable
    let small = post_residual < 10 && post_residual > 0;
    if small {
        score += 25.0;
    }
    // Modulo classes: residuals divisible by common item granularities (5, 10) are reusable
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 8.0;
    } else if post_residual % 5 == 0 && post_residual > 0 {
        score -= 4.0;
    }

    // Perfect fit is ideal
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead compatibility: does next item fit in the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // reward, scaled by how well the pair fills the bin
            let pair_fill = (item_size + next_item_size) as f64 / cap;
            score -= 6.0 + 10.0 * pair_fill;
        } else {
            // next item cannot use residual: penalize proportionally to wasted space
            score += 0.15 * post_residual as f64;
        }
    }

    // Last chance bin: strongly favor using it instead of opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Fraction-of-capacity coupling: prefer bins whose residual is a small fraction of capacity
    let res_frac = post_residual as f64 / cap;
    score += 30.0 * res_frac * res_frac;

    // Prefer reusing existing bins over opening new ones when residuals are comparable
    if bin_residual < bin_capacity {
        score -= 5.0;
    } else {
        // new-bin candidate: penalize unless mean residual of open bins is large (all bins nearly full)
        score += 15.0;
        if open_bins_count > 0 && mean_residual < 0.35 * cap {
            score -= 10.0; // open bins are roomy; don't open a new one
        }
    }

    // Late-stream pressure: consolidate more aggressively as the stream progresses
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 8.0 * progress * (1.0 - res_frac);

    // Harmonic integer-division threshold: residual classes 10..=20 are moderately reusable
    if post_residual >= 10 && post_residual <= 20 {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit: massive reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Strict dead-space avoidance: residuals too small for the minimum item
    // (1..=9 here, but treat < 10 as near-dead) are unusable waste.
    let dead_threshold: u32 = 10;
    if post_residual > 0 && post_residual < dead_threshold {
        score += 60.0 * (dead_threshold - post_residual) as f64;
    }

    // Small-but-reusable residuals are mildly penalized relative to large ones
    // (tight packing preference): non-linear coupling on post_residual.
    if post_residual > 0 {
        let frac = post_residual as f64 / bin_capacity as f64;
        score += 40.0 * frac * (1.0 - frac);
    }

    // Lookahead coupling: reward residuals that can still hold the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    } else if next_item_size > 0 && post_residual > 0 {
        // residual wasted relative to the arriving next item
        score += 10.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // Open-bin pressure: discourage spreading across many bins; favor filling
    // existing bins when many are open.
    score += (open_bins_count as f64) * 2.0;

    // New-bin candidate handling: an empty bin is only attractive when the fit
    // elsewhere would create dead space. Penalize opening a new bin unless the
    // item is large relative to capacity.
    if bin_residual == bin_capacity {
        let fill = item_size as f64 / bin_capacity as f64;
        if fill >= 0.9 {
            score -= 120.0; // large item: fresh bin is fine
        } else {
            score += 150.0 * (1.0 - fill); // discourage wasting a fresh bin
        }
    }

    // Progression: later in the stream, be slightly more conservative with
    // residual quality (tighten preference for tight fits).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += progress * (post_residual as f64) * 0.3;

    // Deviation from mean residual: prefer bins whose residual is close to the
    // item (fit tightness) — penalize bins far above the mean residual.
    score += 0.5 * ((bin_residual as f64) - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: reward when next item fits into post_residual
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 60.0 + 0.5 * next_item_size as f64;
    } else if next_item_size > 0 {
        // Dead space relative to next item penalized
        score += 0.8 * (next_item_size as f64 - post_residual as f64);
    }

    // Prefer bins with residual near mean (balanced packing)
    score += 0.3 * (bin_residual as f64 - mean_residual).abs();

    // Last-chance bin bonus: avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Penalize opening a new bin when a decent fit exists
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let decent_fit = post_residual <= 30 && post_residual != bin_capacity;
        if decent_fit || fitting_bins_count <= 1 {
            score += 150.0;
        } else {
            score += 20.0 * (1.0 - progress);
        }
    }

    // Tight fill reward: waste ratio penalty
    score += 0.2 * (post_residual as f64 / bin_capacity as f64).powi(2) * 100.0;

    // Prefer larger residual bins for large items (better utilization)
    if item_size > 50 {
        score -= 0.1 * bin_residual as f64;
    }

    // Mild penalty for too many open bins
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: quadratic penalty on wasted capacity.
    let waste_frac = post_residual as f64 / bin_capacity as f64;
    score += 30.0 * waste_frac * waste_frac;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 10 {
        score -= 15.0;
    }

    // Last chance: strongly favor the only bin that fits to avoid opening a bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Lookahead: reward if next item can use the post_residual exactly or well.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score += 0.3 * slack;
        } else {
            // Next item cannot use leftover; penalize proportionally to leftover size.
            score += 0.15 * post_residual as f64;
        }
    }

    // Prefer bins with below-average residual (fill emptier-targeted bins first? no:
    // favor bins whose residual is close to item, penalize deviating from mean).
    let dev = bin_residual as f64 - mean_residual;
    score += 0.1 * dev.abs();

    // When many bins are open, consolidate: penalize using a new bin.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 + 10.0 * open_bins_count as f64 * (0.5 + 0.5 * progress);
    }

    // Late in the stream, be more aggressive about closing bins tightly.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * (1.0 - waste_frac);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post-residual, smoothly warped by stream progress
    let mut score = pr * (1.0 + 0.5 * progress * norm_pr);

    // Non-linear penalty for dead space (quadratic in normalized residual)
    score += 40.0 * norm_pr * norm_pr * (0.5 + progress);

    // Reward tight fits with smooth exponential coupling
    let tightness = 1.0 - norm_pr;
    score -= 30.0 * tightness * tightness * (1.0 + 0.3 * progress);

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0 + 15.0 * tightness;
    }

    // Lookahead: penalize if next item can't use the post-residual, smoothly
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt > pr {
            let gap = (nxt - pr) / cap;
            score += 20.0 * gap * (1.0 - 0.5 * progress);
        } else {
            score -= 10.0 * (1.0 - (nxt / (pr + 1.0)));
        }
    }

    // Deviation from mean residual: prefer bins deviating smoothly
    let dev = (pr - mean_residual) / cap;
    score += 8.0 * dev * dev - 5.0 * dev * (0.5 + progress);

    // New-bin candidate: mild penalty so it's chosen only when open bins fit poorly
    if bin_residual == bin_capacity {
        score += 12.0 + 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: reward residuals in "usable" bands.
    // Residuals divisible into common small item sizes (10,20,25,50) are more reusable.
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fit, best possible outcome
    } else {
        let mut bonus = 0.0;
        if pr % 10 == 0 { bonus += 6.0; }
        if pr % 20 == 0 { bonus += 4.0; }
        if pr % 25 == 0 { bonus += 4.0; }
        if pr % 50 == 0 { bonus += 6.0; }
        // class by integer division: small residuals are dead space, mid residuals useful
        let cls = pr / 10; // 0..10
        bonus += match cls {
            0 => -4.0,           // 1..9: nearly dead
            1..=3 => 3.0,        // 10..39: usable by small items
            4..=6 => 5.0,        // 40..69: sweet spot
            7..=9 => 2.0,        // 70..99: large but only for big items
            _ => 0.0,
        };
        score -= bonus;
    }

    // Lookahead: if next item fits exactly in post_residual, strongly favor this bin.
    if next_item_size > 0 && next_item_size <= pr {
        if pr == next_item_size {
            score -= 25.0; // chained perfect fit
        } else {
            score -= 8.0;
            // harmonic coupling: next item divides the post residual
            if pr % next_item_size.max(1) == 0 {
                score -= 6.0;
            }
        }
    } else if next_item_size > pr {
        // next item won't fit here regardless; mild penalty for creating unusable space
        score += 3.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a new bin, more so when good fits exist
    // and the stream is early (many items left to fill this bin with).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 45.0 + 25.0 * (1.0 - progress);
        // but if mean residual across open bins is tiny (all nearly full), opening is fine
        if mean_residual < 15.0 {
            score -= 30.0;
        }
        if open_bins_count == 0 {
            score -= 100.0; // must open
        }
    }

    // Mild pressure to consolidate into fewer bins when many are open.
    score -= (open_bins_count as f64).ln().max(0.0) * (bin_residual as f64 / cap) * 2.0;

    // Tightness term: prefer bins where the item fills a large fraction of residual.
    let fill_frac = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_frac * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps heavily.
    // A residual gap is "dead" if it is smaller than the smallest plausible item.
    let dead_threshold = 9.0f64;
    if (post_residual as f64) < dead_threshold {
        score += 60.0 * (dead_threshold - post_residual as f64);
    }

    // Non-linear penalty on leftover that cannot combine with the lookahead item.
    if next_item_size > 0 {
        if post_residual > 0 && post_residual < next_item_size {
            score += 25.0 + 0.5 * (next_item_size - post_residual) as f64;
        }
        // Reward residuals that can exactly host the next item.
        if post_residual == next_item_size {
            score -= 40.0;
        }
    }

    // Reward tight fits (small post_residual relative to bin capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 20.0 * tightness * tightness;

    // Open-bin pressure: discourage spreading across many bins when residuals
    // are plentiful elsewhere; encourage closing out nearly-full bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
    score += 3.0 * pressure * (0.5 + 0.5 * progress);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: make it moderately unattractive unless current fits are bad.
    if bin_residual == bin_capacity {
        score += 15.0 + 0.3 * open_bins_count as f64;
        // But if no open bin fits well, opening fresh is fine.
        if fitting_bins_count == 0 {
            score -= 50.0;
        }
    }

    // Slight preference for bins with above-average residual when post_residual is large.
    if post_residual as f64 > mean_residual {
        score += 2.0 * (post_residual as f64 - mean_residual) / bin_capacity as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let capacity_f = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Base: normalized wasted space (post_residual relative to capacity)
    score = (post_residual as f64) * 1.0;

    // Strong reward for near-perfect fit (small post_residual)
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    } else if post_residual <= 10 {
        score -= 12.0;
    }

    // Aggressive 2-step lookahead: reward if next item fits exactly into post_residual
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let post = post_residual as f64;
        if next_item_size == post_residual {
            score -= 45.0; // perfect chain
        } else if next_item_size <= post_residual {
            let slack = post - next;
            if slack <= 5.0 {
                score -= 25.0; // near-perfect chain
            } else {
                score -= 10.0 * (1.0 - slack / capacity_f); // fits with slack
            }
        } else {
            // next item won't fit: penalize proportionally to overshoot
            let overshoot = next - post;
            score += 8.0 * (overshoot / capacity_f).min(1.0);
        }
    }

    // Relative to mean residual: prefer bins with residuals close to what we consume
    let mean = mean_residual;
    if mean > 0.0 {
        let rel = (bin_residual as f64) / mean;
        if rel > 1.2 {
            score += 6.0 * (rel - 1.2).min(2.0); // bin has unusually large residual; ok to use it
        } else if rel < 0.6 {
            score += 4.0; // nearly exhausted bin; using it creates dead space unless perfect fit
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // no open bin offers a good fit and the item is large (poor future flexibility)
    if bin_residual == bin_capacity {
        let item_f = item_size as f64;
        let waste = capacity_f - item_f;
        // Base cost of a fresh bin: its full residual
        score = capacity_f as f64 * 0.9;
        // Reward opening new bin for large items (less leftover waste)
        score -= 15.0 * (item_f / capacity_f);
        // Penalize new bin if a decent fit exists elsewhere
        if fitting_bins_count > 0 {
            let best_possible = if next_item_size > 0 { 0.0 } else { 0.0 };
            score += 10.0 + best_possible;
        }
        // Early in stream, opening bins is fine (builds portfolio)
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 5.0 * (1.0 - progress);
        // If next item is large and won't fit anywhere else anyway, new bin with room is good
        if next_item_size > 0 && next_item_size as f64 > mean_residual {
            score -= 8.0;
        }
        let _ = waste;
    }

    // Mild pressure to consolidate: fewer open bins relative to progress -> prefer existing bins
    if open_bins_count > 0 && bin_residual != bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 2.0 * (open_bins_count as f64 / (open_bins_count as f64 + 10.0)) * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress of the stream (0..1)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Tight fit reward: squared residual keeps tight placements on top.
    score = (post_residual as f64).powf(1.6);

    // Perfect fill bonus
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead: penalize leaving a gap that is useless for the next item,
    // reward leaving a gap that exactly fits it.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            if post_residual == next_item_size {
                score -= 25.0; // chain-friendly exact fit
            } else if post_residual < next_item_size + 10 {
                score -= 8.0; // next item likely lands here too
            } else {
                score += 3.0; // leftover too big to be safely reusable
            }
        } else {
            // Dead space: cannot host the next item
            let dead = post_residual as f64;
            score += dead * 0.25;
        }
    }

    // Last-chance bin: strongly prefer using the only bin that fits,
    // otherwise we pay for a fresh bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Crowding pressure: many open bins -> prefer consolidating into
    // bins below-average residual (denser bins), keep spread tight.
    if open_bins_count > 1 {
        let diff = mean_residual - bin_residual as f64;
        score += diff * 0.6; // favor bins with residual below mean (fuller bins)
        score += open_bins_count as f64 * 0.4;
    }

    // Late in the stream: be greedy about tight fits, avoid opening bins.
    score += progress * (post_residual as f64) * 0.5;

    // New-bin candidate handling: empty bin gets a baseline cost so it is
    // chosen only when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        score = 55.0 + progress * 20.0;
        // If the item is huge relative to capacity, a fresh bin is fine.
        if item_size as f64 > 0.8 * bin_capacity as f64 {
            score -= 20.0;
        }
        // If next item is large, opening a fresh bin is attractive.
        if next_item_size > 0 && next_item_size > bin_capacity / 2 {
            score -= 12.0;
        }
        // Many open bins already: discourage yet another bin.
        score += open_bins_count as f64 * 1.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits, with non-linear sharpening of small residuals.
    let mut score = pr as f64;
    score += 30.0 * norm_pr * norm_pr;
    score -= 20.0 * (1.0 - norm_pr) * (1.0 - norm_pr);

    // Polynomial coupling with stream progress: early on tolerate slack, later punish it.
    let prog_term = progress * progress;
    score += 40.0 * prog_term * norm_pr * (1.0 - norm_pr) * 2.0;
    score -= 25.0 * (1.0 - progress) * norm_pr;

    // Last-chance bonus: strongly favor the only bin that fits.
    if fitting_bins_count == 1 {
        score -= 60.0;
    }

    // Dead-space penalty if post_residual can't hold the lookahead item but could hold typical items.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr < nxt {
            score += 15.0 * (1.0 - pr / cap) * (1.0 + progress);
        } else {
            score -= 10.0 * (pr - nxt) / cap;
        }
    }

    // Mean-residual coupling: penalize bins far from the fleet mean (fragmentation signal).
    let dev = (pr - mean_residual) / cap;
    score += 12.0 * dev * dev * cap / 10.0;

    // Mild penalty for spreading across many open bins.
    score += (open_bins_count as f64).ln() * 2.0 * norm_pr;

    // New-bin candidate: only attractive when current bins fit poorly.
    if bin_residual == bin_capacity {
        score = 55.0 + 45.0 * progress - 20.0 * (1.0 - norm_pr);
        if fitting_bins_count <= 1 {
            score -= 80.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose residual falls into "friendly"
    // classes (multiples of small sizes) are easier to fill later -> reward.
    let pr = post_residual;
    if pr > 0 {
        if pr % 10 == 0 {
            score -= 12.0;
        } else if pr % 5 == 0 {
            score -= 6.0;
        } else if pr % 2 == 0 {
            score -= 2.0;
        }
        // dead-space penalty: tiny unusable residuals
        if pr < 4 {
            score += 40.0;
        } else if pr < 10 {
            score += 15.0;
        }
    }

    // Lookahead: if next item fits exactly into post_residual, strongly favor.
    if next_item_size > 0 && next_item_size <= pr {
        if next_item_size == pr {
            score -= 60.0;
        } else {
            let slack = (pr - next_item_size) as f64;
            score -= 20.0 * (1.0 - slack / cap);
        }
    } else if next_item_size > pr && next_item_size > 0 {
        // next item won't fit here afterwards; penalize proportionally
        score += 10.0;
    }

    // Last-chance bin: avoid opening a new bin if this is the only fitting one.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Prefer tighter bins: reward small residual before placement.
    score += (bin_residual as f64) * 0.15;

    // Prefer near-full bins: fraction of capacity consumed by this item.
    score -= (item_size as f64 / cap) * 20.0;

    // Mild pressure against opening new bins as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score += 30.0 + 40.0 * progress;
    } else {
        score -= 5.0 * (mean_residual / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold the
    // smallest plausible item are pure waste -> heavy penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 12.0;
    }

    // Reward tight fits (small post_residual relative to bin capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 25.0 * tightness * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead: if next item fits exactly into the post residual, big reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        score -= 30.0 * (1.0 - gap / bin_capacity as f64);
    } else if next_item_size > 0 && post_residual > 0 {
        // Next item cannot use this residual; penalize proportionally.
        score += 8.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading into new bins.
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure from open bins count.
        score += 35.0 + 6.0 * open_bins_count as f64;
        // Slightly cheaper early in the stream when few bins exist.
        if open_bins_count == 0 {
            score -= 30.0;
        }
    } else {
        // Mild reward for filling already-open bins as pressure rises.
        score -= 1.5 * open_bins_count as f64;
    }

    // Mean-residual coupling: prefer bins below mean residual (tighter bins).
    score += 0.4 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: reward bins where the next item fits the post residual
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 50.0 + (post_residual - next_item_size) as f64 * 0.1;
    } else if next_item_size > 0 {
        // Penalize dead space that next item can't use
        score += (next_item_size as f64 - post_residual as f64) * 0.3;
    }

    // Relative to mean residual: prefer bins tighter than average
    score += (post_residual as f64 - mean_residual) * 0.5;

    // Last chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // Penalize opening a new bin when open bins could fit well
    if bin_residual == bin_capacity {
        score += 150.0;
        // Allow new bin if item is large and few fitting bins
        if item_size > 60 && fitting_bins_count <= 1 {
            score -= 100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Primary driver: reward tight fits (small post residual).
    score = post_residual as f64 * 1.0;

    // Strong preference for near-perfect fills.
    if post_residual <= 5 {
        score -= 40.0;
    } else if post_residual <= 10 {
        score -= 20.0;
    }

    // Lookahead: penalize post_residual that is dead space for the next item,
    // but reward residuals that can host the next item (chaining).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // next item can still fit here -> chaining bonus
            score -= 8.0 + (post_residual as f64 - next_item_size as f64).min(30.0) * 0.1;
        } else {
            // dead space relative to lookahead: worse the larger the gap
            score += (next_item_size as f64 - post_residual as f64) * 0.5;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // to avoid opening a new bin for a poor fit.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Penalize creating large unusable residue relative to smallest plausible item (1..100 range).
    if post_residual < 10 && post_residual > 0 {
        score += 5.0; // tiny slivers are nearly useless
    }

    // New-bin candidate: reserve it — only attractive when existing fits are poor.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, softened when many items remain
        // (long horizon amortizes a fresh bin) and when few bins are open.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let mut new_bin_score = 55.0 - 25.0 * progress + open_bins_count as f64 * 2.0;
        // If the current item is large, a fresh bin is more acceptable.
        if item_size > bin_capacity / 2 {
            new_bin_score -= 15.0;
        }
        // If mean residual across open bins is small, existing bins are congested;
        // a new bin becomes relatively better.
        new_bin_score -= (mean_residual - 20.0).max(0.0) * 0.3;
        score = new_bin_score + post_residual as f64 * 0.5;
    } else {
        // Mild penalty for placing into bins with much larger residual than needed
        // when other context suggests saving big residuals for big items.
        let waste_ratio = post_residual as f64 / bin_capacity as f64;
        score += waste_ratio * 10.0;
        // Slight bonus for using bins whose residual is close to the item (best-fit shaping)
        let tightness = 1.0 - (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
        score -= tightness * 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let fit_norm = item_size as f64 / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let mut score = pr * (1.0 + 0.5 * progress * progress);

    // Reward tight fits via cubic decay of normalized post-residual
    score -= 30.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * (1.0 - norm_pr) * fit_norm;

    // Penalize dead space that likely cannot fit the lookahead item
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).max(0.0);
        score += 0.3 * gap * gap / cap;
    }

    // Last-chance bonus: strongly favor the only bin that fits
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0 * (1.0 - progress);
    }

    // New-bin candidate: discourage early, allow late when fits are poor
    if bin_residual == bin_capacity {
        score += 40.0 * (1.0 - progress) - 20.0 * progress;
        score += 0.2 * open_bins_count as f64;
    }

    // Divergence from mean residual: prefer bins near the mean to balance
    score += 0.1 * (pr - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo arithmetic on capacity fractions.
    // post_residual == 0 is a perfect fit -> huge reward.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Class residuals into buckets: tiny residues (<=10) are "harmonically usable"
        // since typical small items (1..=10 range exists under interface note) can fill them.
        let pr = post_residual;
        if pr <= 10 {
            score -= 60.0;
        } else if pr <= 20 {
            score -= 25.0;
        } else if pr <= 30 {
            score -= 10.0;
        }
        // Penalize residues in "dead zones": (30,50) leaves a half-capacity hole
        // that no medium item cleanly fills; (60,80) is worse.
        if pr > 30 && pr < 50 {
            score += 15.0;
        }
        if pr >= 50 && pr < 60 {
            score += 5.0;
        }
        if pr > 60 && pr < 80 {
            score += 20.0;
        }
        // Harmonic coupling: if next item exactly fills post_residual, strong reward.
        if next_item_size > 0 && next_item_size == pr {
            score -= 120.0;
        }
        // If next item fits inside post_residual, mild reward (chaining).
        if next_item_size > 0 && next_item_size < pr {
            score -= (pr - next_item_size) as f64 * 0.5;
        }
        // If next item does NOT fit this residue but would fit elsewhere, penalize waste.
        if next_item_size > pr && next_item_size > 0 {
            score += 10.0;
        }
    }

    // New-bin candidate logic: opening a new bin is only attractive when
    // few bins fit the item or mean residual is high (fragmentation).
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base cost of opening a bin scaled by stream progress (late bins are riskier to waste).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 45.0 + 30.0 * progress;
        // If this item is a last-chance fit, opening a bin is bad.
        if fitting_bins_count == 1 {
            score += 80.0;
        }
        // If many open bins already have high mean residual, opening a new one
        // spreads fragmentation; penalize.
        score += mean_residual * 0.3;
        // Reward opening a new bin when the item is large (few future fits likely).
        if item_size >= 70 {
            score -= 35.0;
        }
        // If next item is large too, having a fresh bin helps.
        if next_item_size >= 60 {
            score -= 15.0;
        }
    } else {
        // Reward using existing bins, especially when they are the only fit.
        if fitting_bins_count == 1 {
            score -= 70.0;
        }
        // Mild reward for consolidating when many bins are open.
        if open_bins_count > 4 {
            score -= 5.0;
        }
        // Prefer bins whose residual is below mean (tighter bins first).
        if (bin_residual as f64) < mean_residual {
            score -= 8.0;
        } else {
            score += 4.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to ever fit
    // another item (>= 1 minimum, but practically < ~15) are heavily penalized.
    if post_residual > 0 && post_residual < 15 {
        score += 60.0 + (15 - post_residual) as f64 * 4.0;
    }

    // Reward tight fits (small post_residual) more aggressively than plain best-fit.
    score -= 25.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Perfect fit: near-zero residual is excellent.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Dead space relative to the next item: if the leftover cannot host the
    // lookahead item, penalize; if it can, reward (chaining potential).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else if post_residual > 0 {
            score += 10.0;
        }
    }

    // Open-bin pressure: mildly discourage spreading across many bins,
    // but strongly discourage opening yet another bin when good fits exist.
    score += open_bins_count as f64 * 0.5;

    // New-bin candidate (empty bin): only attractive when this bin is the
    // last chance or the fit elsewhere would create large dead space.
    if bin_residual == bin_capacity {
        score += 45.0;
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: new bin is fine
        }
        if post_residual as f64 > mean_residual {
            score += 10.0;
        }
    }

    // Last-chance bin: strongly favor using it rather than opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Prefer bins whose residual is close to the mean (balanced packing).
    score += 0.3 * (bin_residual as f64 - mean_residual).abs();

    // Slight late-stream tightening: waste matters more as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * 0.2 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly favor exact/near-exact fits: small post_residual is good.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Penalize dead space that cannot fit even the smallest plausible item.
        if post_residual < 10 {
            score -= 150.0;
        }
        // 2-step lookahead: reward bins whose post_residual can host the next item.
        if next_item_size > 0 {
            if post_residual >= next_item_size {
                let slack = (post_residual - next_item_size) as f64;
                score -= 120.0 - slack * 0.8;
                // Perfect chain: post_residual exactly equals next item.
                if post_residual == next_item_size {
                    score -= 200.0;
                }
            } else {
                // Next item won't fit here: penalize proportionally to the gap.
                let gap = (next_item_size - post_residual) as f64;
                score += gap * 0.5;
            }
        } else {
            // Last item: only tight fits matter.
            score -= 50.0;
        }
    }

    // Relative tightness against mean residual across open bins.
    let residual_diff = bin_residual as f64 - mean_residual;
    // Prefer bins tighter (smaller residual) than average.
    score += residual_diff * 0.6;

    // Last-chance bonus: if this is the only bin that fits the item, use it
    // to avoid opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 180.0;
    }

    // Penalize the new-bin candidate so it's only chosen for genuinely bad fits.
    if bin_residual == bin_capacity {
        score += 250.0;
        // Late in the stream, opening new bins is less wasteful (fewer leftovers).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= progress * 60.0;
    }

    // Mild preference for keeping the number of open bins bounded.
    score += open_bins_count as f64 * 0.5;

    // Small nudge toward larger items filling larger residual bins.
    score += (item_size as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: strongly favor bins where the item nearly fills the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 18.0 * fit_ratio * fit_ratio;

    // Penalize large dead space relative to capacity (unusable leftovers).
    let dead = post_residual as f64 / bin_capacity as f64;
    if dead > 0.0 && dead < 0.10 {
        score -= 6.0 * (0.10 - dead); // small-but-usable leftovers are fine
    } else {
        score += 10.0 * dead * dead;
    }

    // Lookahead: if the next item fits exactly into the post-residual, big bonus.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 8.0 / (1.0 + gap);
        if post_residual == next_item_size {
            score -= 12.0;
        }
        // Penalize leaving residual that is too small for the next item (dead space trap)
        if post_residual < next_item_size && post_residual > 0 {
            score += 0.05 * post_residual as f64;
        }
    } else {
        // Last item: prefer filling as much as possible.
        score -= 5.0 * fit_ratio;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 9.0 * fit_ratio;
    }

    // New-bin candidate handling: opening a new bin is only attractive when the
    // item is large relative to capacity or existing bins have poor fits.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let item_frac = item_size as f64 / bin_capacity as f64;
        // Attractive when item is big (fewer awkward leftovers later) or many bins open
        score -= 14.0 * item_frac;
        score -= 1.5 * (open_bins_count as f64).ln().max(0.0);
        // Late in stream: prefer consolidating into open bins.
        score += 8.0 * progress;
        // If mean residual of open bins comfortably fits the item, discourage new bin.
        if mean_residual >= item_size as f64 {
            score += 10.0;
        }
    } else {
        // Slight bonus for using existing bins when their residual is well above average
        if (bin_residual as f64) > mean_residual {
            score -= 2.0;
        }
    }

    // Mild preference for bins with residual close to item size (perfect-ish fit)
    let diff = (bin_residual as f64 - item_size as f64).abs();
    score -= 3.0 / (1.0 + diff);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early in the stream, tolerate slack; late in the stream, punish it super-linearly.
    let slack_penalty = post * post / cap * (0.5 + progress);
    score += slack_penalty;

    // Reward near-perfect fits with a smooth cubic falloff.
    let tightness = 1.0 - (post / cap);
    score -= 12.0 * tightness * tightness * tightness;

    // Lookahead coupling: if next item fits the post residual, reward this bin.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= post {
            let fill = nx / post.max(1.0);
            score -= 8.0 * fill * fill;
        } else {
            // Post residual too small for next item: penalize wasted near-fit space.
            let gap = (nx - post) / cap;
            score += 6.0 * gap;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Discourage spreading across many bins when mean residual is large elsewhere.
    score += 0.05 * (open_bins_count as f64).sqrt() * (mean_residual - post).abs() / cap;

    // New-bin candidate: make it attractive only when no good fit exists;
    // penalize opening bins early, less so as stream progresses.
    if bin_residual == bin_capacity {
        score = cap - post + 20.0 * (1.0 - progress) + 0.3 * mean_residual;
        if fitting_bins_count > 0 {
            score += 10.0; // discourage opening when an open bin can fit
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residues near zero are "perfect fits".
    let pr = post_residual as u32;
    if pr == 0 {
        score -= 60.0; // perfect closure
    } else if pr <= 10 {
        score -= 25.0; // nearly perfect
    } else {
        // Dead-space penalty grows super-linearly for unusable slivers
        // (residuals below the smallest plausible item are worthless).
        let sliver = (10u32.saturating_sub(pr)) as f64;
        score += sliver * 8.0;
        // Modulo-class harmonic: residuals in {25,33,50} fractions pair well
        // with common item sizes; reward them.
        match pr % 25 {
            0 => score -= 6.0,
            10 | 20 => score -= 3.0,
            _ => {}
        }
        if pr % 2 == 0 { score -= 1.0; }
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // strongly reward this placement (chained packing).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0 - slack.min(12.0) * 0.4; // tight chain preferred
        } else if post_residual >= next_item_size / 2 {
            score -= 2.0; // partial usability
        } else {
            score += 3.0; // next item cannot use leftover
        }
        // Harmonic class of next item: big items (>50) prefer bins with big residual
        if nxt > 50.0 && post_residual < 50 {
            score += 4.0;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin to avoid opening one.
    if fitting_bins_count == 1 {
        score -= 18.0;
    }

    // Prefer bins below mean residual (tighter bins absorb the item better).
    score -= 0.35 * (mean_residual - bin_residual as f64);

    // New-bin candidate (empty bin): make it attractive only when few bins fit
    // the item or the item is huge; otherwise discourage spreading.
    if bin_residual == bin_capacity {
        let frac_fitting = if open_bins_count > 0 {
            fitting_bins_count as f64 / open_bins_count.max(1) as f64
        } else { 1.0 };
        let pressure = 1.0 - frac_fitting; // scarcity of alternatives
        let big_item = item_size as f64 / cap; // fraction of capacity
        let openness = step_index as f64 / total_items.max(1) as f64;
        score = cap as f64 * 0.9
            - pressure * 55.0
            - big_item * 30.0
            - openness * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize unusable small gaps hard.
    if post_residual > 0 {
        let min_item = 1u32;
        if post_residual < min_item + 9 {
            // tiny gap below smallest plausible item: total dead space
            score += 40.0 + (10 - post_residual) as f64 * 6.0;
        } else if post_residual <= 15 {
            score += 12.0; // risky small gap
        }
    }

    // Reward tight fits (near-perfect packing).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= tightness * 15.0;

    // Reward using a bin that only this item fits in (last chance).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a new bin when open bins could fit.
    if bin_residual == bin_capacity {
        score += 30.0 + 2.0 * open_bins_count as f64;
    } else {
        // Open-bin pressure: prefer filling already-open bins.
        score += 0.5 * open_bins_count as f64;
    }

    // Prefer bins with residual below mean (consolidate space).
    score += (bin_residual as f64 - mean_residual) * 0.3;

    // Lookahead: bonus if post_residual accommodates next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 5.0;
    }

    // Late-stream pressure to close out bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is already the base score.
    // Penalize "dead space": residuals too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0; // unusable sliver
    }

    // 2-step lookahead: reward if next item fits exactly in the post-residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 120.0; // perfect pair
        } else if post_residual >= next_item_size {
            score -= 30.0 + 0.5 * (post_residual - next_item_size) as f64;
        } else {
            // next item won't fit here; penalize proportionally to waste
            score += 0.3 * (next_item_size - post_residual) as f64;
        }
    }

    // Compare against mean residual: prefer bins whose post-residual is near/below mean
    score += 0.4 * (post_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 80.0;
    }

    // New-bin candidate handling: mildly discourage opening new bins early,
    // more strongly when many bins are already open with slack.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 40.0 + 60.0 * (1.0 - progress) + 2.0 * open_bins_count as f64;
        // but allow new bin if it enables a perfect next-item fit
        if next_item_size == bin_capacity {
            score -= 200.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual relative to capacity.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 0.9 * tightness * (item_size as f64);

    // Penalize leaving awkward small residual gaps (dead space) that few items can use.
    if post_residual > 0 {
        let dead_zone = (post_residual as f64 / bin_capacity as f64).powf(2.0);
        score += 25.0 * dead_zone;
    }

    // Perfect fit gets a strong bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward this placement.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size <= post_residual {
            score -= 12.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // Next item cannot use this bin's leftover; penalize large leftovers slightly.
            score += 0.15 * (post_residual as f64 - mean_residual).abs();
        }
    }

    // Global state coupling: many open bins -> discourage spreading, prefer filling existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let spread_pressure = (open_bins_count as f64).ln().max(0.0);
    score += 0.08 * spread_pressure * (1.0 - progress);

    // Prefer bins whose residual is close to the item (best-fit flavor) with a nonlinear term.
    let fit_gap = (bin_residual - item_size) as f64;
    score += 0.05 * (fit_gap / bin_capacity as f64).powf(3.0) * (bin_capacity as f64);

    // New-bin candidate handling: opening a new bin is only attractive when current bins fit poorly.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, reduced when few bins are open or late in stream.
        let mut new_bin_cost = 45.0;
        new_bin_cost -= 6.0 * (open_bins_count as f64).min(6.0);
        if next_item_size > 0 && next_item_size <= bin_capacity {
            // New empty bin can always fit next item; slightly cheaper if next item is large.
            new_bin_cost -= 0.1 * (next_item_size as f64);
        }
        // If no open bin fits (this call is the only fitting option), opening is cheap.
        if fitting_bins_count == 0 {
            new_bin_cost -= 50.0;
        }
        score = new_bin_cost + 0.3 * (item_size as f64);
    }

    // Mild time-horizon modulation: later in the stream, be more conservative (favor consolidation).
    score *= 1.0 - 0.1 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let fit_norm = item_size as f64 / cap;

    // Base: residual after placement (minimize wasted space)
    let mut score = pr as f64;

    // Non-linear coupling: quadratic penalty on small post-residuals that
    // grows with stream progress (late in stream, tight fits matter more)
    let tight = (1.0 - norm_pr).powi(2);
    score -= 12.0 * tight * (0.3 + 0.7 * t);

    // Cubic interaction of normalized post-residual with progress:
    // mid-sized residuals become more valuable as stream advances
    let mid = 4.0 * norm_pr * (1.0 - norm_pr);
    score -= 8.0 * mid * (1.0 - t);

    // Reward near-perfect fills strongly, smoothed (no hard cutoff)
    score -= 20.0 * (-(norm_pr * norm_pr) / 0.02).exp();

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 + 10.0 * t;
    }

    // New-bin candidate: penalize mildly so we prefer reusing open bins,
    // but relax late in the stream when mean residual is low
    if bin_residual == bin_capacity {
        let open_pressure = (open_bins_count as f64 / (1.0 + mean_residual / 10.0)).ln().max(0.0);
        score += 6.0 + 14.0 * (1.0 - t) - 5.0 * open_pressure.min(3.0) * t;
    }

    // Lookahead: favor bins whose post-residual can host the next item
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 6.0 * (1.0 - slack / cap) * (0.5 + 0.5 * t);
    } else if next_item_size > 0 {
        // Penalize leaving residual too small for the lookahead item
        score += 4.0 * (1.0 - (pr / (next_item_size as f64)).min(1.0));
    }

    // Mean-residual coupling: prefer bins close to the mean residual
    // (keeps the bin pool homogeneous, easier future packing)
    let dev = (pr - mean_residual).abs() / cap;
    score += 5.0 * dev * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover: residuals divisible into "clean" classes
    // (perfect fit, small-cap classes) are more valuable than mid-range waste.
    let cap = bin_capacity as f64;
    let pr = post_residual;

    // Perfect fit is gold.
    if pr == 0 {
        score -= 1000.0;
        return score;
    }

    // Class the residual by integer division thresholds (harmonic bands).
    let band = pr / 10; // 0..=10 harmonic class
    let band_bonus: f64 = match band {
        0 => 60.0,          // 1..9 : nearly dead space
        1 => 25.0,          // 10..19 : fits smallest class
        2 => 5.0,           // 20..29
        3 => -10.0,         // 30..39
        4 => -20.0,         // 40..49 : very reusable
        5 => -25.0,         // 50..59
        6 => -20.0,         // 60..69
        7 => -12.0,         // 70..79
        8 => -4.0,          // 80..89
        _ => 8.0,           // 90..100 : mostly-empty bin, don't waste it
    };
    score += band_bonus;

    // Modulo-5 / modulo-10 resonance: residuals that are multiples of 5 or 10
    // pair well with typical item sizes.
    if pr % 10 == 0 {
        score -= 15.0;
    } else if pr % 5 == 0 {
        score -= 7.0;
    }

    // Lookahead coupling: if the next item fits the post-residual exactly or well,
    // reward this bin strongly.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 120.0;
        } else if next_item_size <= pr {
            let gap = pr - next_item_size;
            score -= 40.0 * (1.0 - gap as f64 / cap);
            // harmonic class match: gap in a good band
            let gap_band = gap / 10;
            if gap_band <= 1 { score -= 20.0; }
            if gap % 10 == 0 { score -= 10.0; }
        } else {
            // next item cannot follow here; residual becomes dead space
            score += 30.0;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 90.0;
    }

    // New-bin candidate: only attractive when the item is huge relative to capacity
    // or existing residuals are all poor fits.
    if bin_residual == bin_capacity {
        let tight = item_size as f64 / cap;
        score = score * 0.5 + (cap - item_size as f64) * (0.6 + 0.8 * tight);
        if open_bins_count == 0 {
            score -= 200.0;
        }
        // late in stream, prefer consolidating rather than opening
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 40.0 * progress;
    }

    // Mild pressure toward fuller bins relative to the fleet mean residual.
    score += 0.3 * (mean_residual - bin_residual as f64);

    // Slight preference for bins with residuals that share a class with item size.
    if (bin_residual - item_size) % 10 == item_size % 10 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps are heavily penalized.
    let min_item = 1u32; // smallest possible future item
    if post_residual > 0 && post_residual < min_item.max(1) + 9 {
        score += 1000.0; // effectively forbid leaving a sub-minimal sliver
    }
    // Penalize gaps too small for the lookahead item (wasted for k=2 lookahead)
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 25.0 + 0.5 * (next_item_size - post_residual) as f64;
    }

    // Reward tight fits (near-perfect packing).
    let tightness = (bin_capacity as f64 - post_residual as f64) / bin_capacity as f64;
    score -= 30.0 * tightness * tightness;

    // Open-bin pressure: discourage spreading across many bins unless fit is good.
    score += 2.0 * (open_bins_count as f64).ln().max(0.0);

    // Last-chance bin bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive when
    // no open bin offers a clean fit, or the current fit is terrible.
    if bin_residual == bin_capacity {
        let bad_fit = post_residual > 0 && post_residual < 10;
        let no_fitting = fitting_bins_count == 0;
        if bad_fit || no_fitting {
            score -= 35.0; // prefer fresh capacity over creating dead space
        } else {
            score += 60.0 + 0.3 * mean_residual; // keep using existing bins
        }
    }

    // Late-stream consolidation: as the stream progresses, favor filling bins fully.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 20.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0 + 0.5 * post_residual as f64;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // Can also fit the next item: reward tight multi-packing
        let slack = (post_residual - next_item_size) as f64;
        score -= 15.0 - 0.15 * slack;
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Next item won't fit here; penalize dead space relative to mean residual
        let dead = next_item_size as f64 - post_residual as f64;
        score += 0.25 * dead;
    }

    // Penalize leaving very small unusable residuals (1..10)
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Prefer bins tighter than average residual
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Last-chance bin before opening a new one: strong reward
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
    }

    // New empty bin candidate: penalize moderately so it only wins when fits are bad
    if bin_residual == bin_capacity {
        score += 18.0;
        // If nothing else fits well, opening a new bin is fine
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward perfect/near-perfect fills strongly.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    } else if post_residual <= 10 {
        score -= 12.0;
    }

    // Lookahead: if the next item exactly fits the residual left behind,
    // this placement chains nicely into the future.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).unsigned_abs();
        if next_item_size as u32 == post_residual {
            score -= 45.0;
        } else if gap <= 10 {
            score -= 18.0;
        } else if post_residual < next_item_size as u32 && post_residual <= 10 {
            // residual too small for next item: mild penalty for dead space
            score += 8.0;
        }
        // favor leaving room proportional to typical upcoming sizes
        score += 0.15 * (post_residual as f64 - next_item_size as f64).abs();
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize bins whose residual deviates wildly from the mean residual
    // (keeps the pool of open bins homogeneous and reusable).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.08 * dev;

    // Slight pressure to consolidate into fewer bins as stream progresses.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += progress * 0.05 * post_residual as f64;

    // New-bin candidate: make it costly so it only wins when existing bins
    // are genuinely poor fits (large post_residual on existing bins).
    if bin_residual == bin_capacity {
        score += 35.0 + 0.25 * open_bins_count as f64;
    }

    // Mild reward for filling fuller bins first (best-fit flavor).
    score -= 0.1 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: waste after placement, non-linearly shaped
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // Smooth polynomial coupling with stream progress:
    // early on, prefer filling bins; later, tolerate more residual
    let progress_coupling = 1.0 - t + 0.5 * t * t;
    score *= progress_coupling;

    // Reward tight fits: subtract a smooth function of normalized item size
    let fit = item_size as f64 / cap;
    score -= 12.0 * fit * (1.0 - norm_pr) * (1.0 - t * 0.5);

    // Penalize dead space that cannot fit the next item (smooth interaction)
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let gap = (nx - pr).max(0.0) / cap;
        score += 15.0 * gap * gap;
        // Reward leaving space exactly usable by the next item
        let usable = (pr - nx).max(0.0) / cap;
        score -= 6.0 * (1.0 - usable) * usable;
    }

    // Last-chance bin: strong reward to use it rather than open a new one
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0 * (1.0 - t);
    }

    // Mild penalty for proliferating open bins relative to mean residual
    score += 0.05 * open_bins_count as f64 * (1.0 - norm_pr);

    // New-bin candidate handling: empty bin gets a moderate baseline
    if bin_residual == bin_capacity {
        score = cap * (1.0 + 0.3 * t) + 5.0 * (mean_residual / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual small relative to capacity.
    let tightness = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= 12.0 * tightness;

    // Harmonic class of post_residual: residuals divisible by 10 (common item
    // sizes 10..80) are more reusable than awkward ones.
    let pr = post_residual as u32;
    let class_penalty = match pr {
        0 => -20.0,
        r if r % 10 == 0 => -8.0,
        r if r % 5 == 0 => 0.0,
        r if r < 10 => 15.0, // tiny dead space
        _ => 5.0,
    };
    score += class_penalty;

    // Lookahead coupling: reward if next item fits exactly or well in post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 10.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item won't fit here; penalize more if residual becomes dead space
            if post_residual < 10 {
                score += 12.0;
            }
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly favor using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate (empty bin): penalize mildly so we prefer filling open
    // bins, unless open bins leave terrible residuals.
    if bin_residual == bin_capacity {
        score += 8.0 + 0.05 * open_bins_count as f64;
        // But if next item is huge, a fresh bin is attractive.
        if next_item_size >= 60 {
            score -= 10.0;
        }
    }

    // Late in stream, prefer consolidating: avoid opening bins near the end.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 6.0 * progress;
    }

    // Prefer bins with residual below mean (fill the emptiest-relative bins less
    // aggressively, keep balanced residual pool).
    score += 0.1 * (mean_residual - post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest plausible
    // item (<= 10) are nearly worthless; treat them as full dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0;
    }

    // Reward tight fits (small waste relative to capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Perfect fit: strong bonus.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Last chance bin: strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Open-bin pressure: when many bins are open, discourage spreading into
    // loose fits; when few bins are open, opening new bins is cheap.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = (open_bins_count as f64).ln() * (0.5 + 0.5 * progress);
    score += pressure * (post_residual as f64 / bin_capacity as f64) * 20.0;

    // Lookahead: if the next item fits exactly in the post-residual, reward it.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 40.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 8.0;
    }

    // New-bin candidate: baseline attractiveness so it only wins when open bins
    // are badly fragmented or under heavy pressure.
    if bin_residual == bin_capacity {
        let fragmentation = if mean_residual > 0.0 { (mean_residual / bin_capacity as f64) - (item_size as f64 / bin_capacity as f64) } else { 0.0 };
        score = 15.0 + 10.0 * pressure - 12.0 * fragmentation;
        if fitting_bins_count == 1 {
            score += 80.0; // never open a new bin when a last-chance bin exists
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), with non-linear penalty on dead space.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Aggressive 2-step lookahead: reward when the next item exactly fills post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0; // perfect chain: this placement sets up the next item perfectly
        } else if next_item_size <= post_residual {
            // next item fits: reward proportionally to how well it uses the leftover space
            let fill_after = (post_residual - next_item_size) as f64;
            score -= 20.0 * (1.0 - fill_after / (bin_capacity as f64));
        } else {
            // next item cannot use the leftover: penalize dead space relative to gap size
            let gap = (next_item_size - post_residual) as f64;
            score += 0.6 * gap.min(40.0);
        }
    }

    // Relative-to-mean coupling: placing in a bin with residual far below mean is good
    // (it closes out small bins); placing in an above-mean bin wastes space.
    let dev = (bin_residual as f64) - mean_residual;
    score += 0.08 * dev;

    // Last-chance bonus: if this is the only bin that can fit the item, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when no open bin
    // fits well (large item relative to typical residuals) or many bins are open.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let waste = (bin_capacity - item_size) as f64;
        // Penalize new bins generally, less so when item is large / many bins open.
        score += 30.0 + 0.5 * waste - 0.15 * open_bins_count as f64 - 10.0 * progress;
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 15.0; // a fresh bin can chain with the next item
        }
    }

    // Mild bonus for consolidating when many bins are open (reduce fragmentation).
    score -= 0.05 * open_bins_count as f64 * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: penalize bins that leave large post residual quadratically.
    score += 0.35 * (post_residual as f64) * (post_residual as f64) / (bin_capacity as f64);

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual < 10 {
        score -= 12.0;
    }

    // Lookahead: reward bins whose post residual can host the next item (k=2 chaining).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0 + 0.15 * next_item_size as f64;
        } else {
            // Dead space for the known next item: penalize.
            score += 0.2 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin to avoid opening a bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0 + 0.5 * item_size as f64;
    }

    // Many open bins: discourage spreading; prefer consolidation.
    if open_bins_count > 2 {
        score += 0.6 * (open_bins_count as f64).ln() * (bin_residual as f64 - mean_residual).abs();
    }

    // Time horizon: late in the stream, be more conservative (favor tight fits harder).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.25 * progress;

    // New-bin candidate: only attractive when item is large or nothing fits well.
    if bin_residual == bin_capacity {
        let large_item = item_size as f64 > 0.7 * bin_capacity as f64;
        let poor_fits = fitting_bins_count <= 1;
        if large_item || poor_fits {
            score -= 18.0;
        } else {
            score += 25.0 + 0.3 * item_size as f64;
        }
    }

    // Waste fraction penalty relative to capacity.
    score += 40.0 * (post_residual as f64) / (bin_capacity as f64) * (1.0 - (item_size as f64) / (bin_capacity as f64));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;

    // Base: wasted space, polynomially coupled with stream progress.
    // Late in the stream, residual space is more costly to waste.
    let mut score = post * (1.0 + 0.6 * progress * progress);

    // Non-linear coupling: post_residual^2 normalized by capacity creates
    // super-linear penalty for very small leftovers (dead space).
    score += 0.9 * (post * post) / cap;

    // Reward tight fits: small post_residual relative to item size.
    let tightness = 1.0 - post / cap;
    score -= 12.0 * tightness * tightness;

    // Last-chance bonus: if this is the only fitting bin, strongly favor it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 * (1.0 + progress);
    }

    // New-bin candidate handling: penalize opening a new bin, more so
    // when existing bins could fit and mean residual is healthy.
    if bin_residual == bin_capacity {
        let mean_fit = if mean_residual >= item { 1.0 } else { 0.0 };
        score += 30.0 + 0.3 * open_bins_count as f64;
        score += mean_fit * (mean_residual - item) * 0.5;
    }

    // Lookahead: penalize leaving a residual that fails to fit next item
    // while a slightly looser placement could have accommodated it.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if post < nx && bin_residual >= nx {
            score += 8.0 + 0.1 * nx;
        }
        // Reward residual that leaves room for the next item.
        if post >= nx {
            score -= 3.0 * (post / cap);
        }
    }

    // Mild dispersion penalty: prefer bins near mean residual to keep
    // the pool of usable residuals coherent.
    let dev = (post - mean_residual).abs();
    score += 0.05 * dev * dev / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic classes: classify post_residual into residue classes mod 10
    let class = (post_residual % 10) as f64;
    score += class * 0.5;

    // Fraction of capacity wasted
    let waste_frac = post_residual as f64 / bin_capacity as f64;
    score += waste_frac * 40.0;

    // If next item fits exactly in post_residual, big reward
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 - slack * 0.3;
        if post_residual == next_item_size {
            score -= 200.0;
        }
    } else if next_item_size > 0 {
        // next item cannot use this residual; penalize proportionally
        score += 10.0 + (next_item_size as f64) * 0.15;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 60.0;
    } else {
        // prefer fuller bins when alternatives exist
        score += (fitting_bins_count as f64) * 2.0;
    }

    // New-bin candidate: only attractive when nothing fits well
    let is_new_bin = bin_residual == bin_capacity && item_size <= bin_capacity;
    if is_new_bin {
        // baseline for a fresh bin: its post_residual = capacity - item
        score += 30.0;
        if fitting_bins_count == 0 {
            score -= 500.0; // must open a new bin
        }
        // late in the stream, prefer consolidating into open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 15.0;
    }

    // Prefer bins with residual above mean (balance residuals), mildly
    score += ((bin_residual as f64) - mean_residual) * 0.05;

    // Integer division threshold: penalize residuals in dead zone (1..10)
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // Reward large fills relative to item size
    score -= (item_size as f64 / bin_capacity as f64) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small to hold the
    // smallest plausible item (>= 10) are pure waste; penalize them hard.
    if post_residual < 10 {
        score += 40.0; // tiny unusable sliver
    } else if post_residual < 20 {
        score += 18.0; // nearly unusable gap
    } else if post_residual < 30 {
        score += 6.0;
    }

    // Non-linear coupling: quadratic penalty on dead space relative to capacity,
    // but only when the gap cannot accommodate the lookahead item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        let waste_frac = (next_item_size - post_residual) as f64 / bin_capacity as f64;
        score += 25.0 * waste_frac * waste_frac * 10.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a bin is justified only when the item
    // would leave a large, reusable residual (good for future items) or when
    // current bins create dead space.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 30.0;
        // Reward opening when the placement leaves a versatile gap.
        if post_residual >= 30 {
            score -= 12.0;
        }
        // Under pressure (many open bins), discourage adding more.
        score += (open_bins_count as f64) * 2.0;
        // Early in the stream, opening bins is cheaper (builds a portfolio).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 10.0 * (1.0 - progress);
        // If existing bins would waste space, opening is more attractive.
        if bin_residual as f64 - mean_residual > 0.0 && post_residual < 10 {
            score -= 20.0;
        }
    } else {
        // Mild pressure to consolidate into fewer bins when many are open.
        score += (open_bins_count as f64) * 0.3;
    }

    // Prefer bins whose residual is close to the item (tight fits).
    let tightness = (bin_residual - item_size) as f64;
    score += 0.05 * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits: penalize heavily as post_residual shrinks below a small threshold.
    let perfect_fit_bonus = if post_residual == 0 {
        -50.0
    } else if post_residual <= 10 {
        -30.0
    } else if post_residual <= 20 {
        -15.0
    } else {
        0.0
    };
    score += perfect_fit_bonus;

    // 2-step lookahead: if the next item fits exactly into post_residual, strongly favor this bin.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual >= next_item_size && post_residual - next_item_size <= 10 {
            score -= 20.0;
        } else if post_residual < next_item_size && post_residual < 10 {
            // dead space too small for typical items: mild penalty
            score += 5.0;
        }
        // If next item fits into bin_residual but not post_residual, placing here wastes the fit
        if bin_residual >= next_item_size && post_residual < next_item_size && post_residual > 0 {
            score += 8.0;
        }
    }

    // Compare against mean residual: bins with less residual than average are scarcer,
    // prefer filling them (tight-packing strategy).
    score += 0.3 * (mean_residual - bin_residual as f64);

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin, unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate (empty bin): penalize opening a new bin when a decent fit exists.
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin; reduced when many bins are open and all
        // residuals are small (item may genuinely not fit well anywhere).
        let mut new_bin_penalty = 18.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            // A fresh bin perfectly sets up the next item
            new_bin_penalty -= 30.0;
        }
        if fitting_bins_count == 0 {
            new_bin_penalty = -10.0; // must open a new bin
        }
        score += new_bin_penalty;
    }

    // Slight preference early in the stream to keep bins open and consolidate.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 2.0 * (1.0 - progress);

    // Mild penalty proportional to wasted fraction of the bin.
    score += 5.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimal post_residual, scaled relative to capacity.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += tightness * 30.0;

    // Reward near-perfect fits (post_residual small relative to item).
    if post_residual <= 2 {
        score -= 40.0;
    } else if post_residual <= 8 {
        score -= 25.0;
    } else if post_residual <= 15 {
        score -= 10.0;
    }

    // Penalize dead space that is too small for the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // Lookahead coupling: if the next item fits the post_residual exactly-ish,
    // strongly favor this bin (chaining placements).
    if next_item_size > 0 {
        let nd = post_residual as i64 - next_item_size as i64;
        if nd == 0 {
            score -= 50.0;
        } else if nd > 0 && nd <= 10 {
            score -= 20.0;
        } else if nd < 0 {
            // next item cannot fit here; slight penalty for wasting the gap
            score += (-nd as f64) * 0.15;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 {
        score -= 35.0;
    } else if fitting_bins_count > 1 {
        // With multiple candidates, mild bonus to keep selection competitive.
        score -= 5.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // the current fit is bad (large post_residual) or few bins are open.
    if bin_residual == bin_capacity {
        let open_cost = 45.0;
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Early in the stream, opening bins is cheaper (more items to fill them).
        let discount = 25.0 * (1.0 - progress);
        let mut new_bin_score = open_cost - discount;
        // If the mean residual across open bins is large, prefer reusing them.
        new_bin_score += (mean_residual / bin_capacity as f64) * 30.0;
        // If this bin is the only fitting one, opening a new bin is worse.
        if fitting_bins_count == 1 {
            new_bin_score += 40.0;
        }
        // Compare against typical placement scores: neutral baseline.
        score = score.min(new_bin_score + 10.0);
        score = new_bin_score;
    }

    // Global pressure: many open bins with low mean residual -> be pickier,
    // penalize placements that leave large residuals.
    if open_bins_count > 3 {
        let pressure = (mean_residual / bin_capacity as f64).min(1.0);
        score += pressure * (post_residual as f64) * 0.3;
    }

    // Time horizon: late in the stream, prefer consolidation into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * (post_residual as f64) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_norm = pr / cap;

    // Base: waste after placement
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // early stream -> mild penalty on large residuals (keep flexibility),
    // late stream -> strong penalty on waste (tighten packing).
    let poly = 0.5 + progress * progress * 2.0 + progress * (1.0 - progress) * 0.5;
    score += poly * fit_norm * fit_norm * cap * 0.5;

    // Quadratic dead-space penalty: residuals that can't fit typical future items
    let dead = if next_item_size > 0 && (post_residual as u64) < (next_item_size as u64) {
        let d = (next_item_size as f64 - pr).max(0.0);
        d * d / cap
    } else {
        0.0
    };
    score += dead;

    // Reward near-perfect fits with smooth bell-like term
    let tight = 1.0 - (fit_norm - 0.05) * (fit_norm - 0.05) * 4.0;
    score -= tight.max(0.0) * 10.0 * (1.0 + progress);

    // Last-chance bin: reward using it to avoid opening new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0 * (1.0 + progress);
    }

    // Mild penalty for spreading across many open bins early on
    score += (open_bins_count as f64).ln() * fit_norm * 2.0 * (1.0 - progress);

    // New-bin candidate: smooth sigmoid-ish gate on whether current item leaves
    // a reusable residual in a fresh bin vs wasting space in open bins
    if bin_residual == bin_capacity {
        let scarcity = (fitting_bins_count as f64).recip();
        let benefit = ((item_size as f64 / cap) - 0.5).abs();
        score += 15.0 * scarcity * (0.5 + benefit) * (1.0 - progress) - 5.0 * progress;
    }

    // Small lookahead coupling: if next item fits the post residual, reward
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 3.0 + 4.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: how "usable" is the leftover space?
    // Residuals divisible by common item sizes (harmonic to capacity grid) are valuable.
    let pr = post_residual;
    let harmony = if pr == 0 {
        20.0 // perfect fit: strongly rewarded
    } else {
        let mut h = 0.0;
        // harmonic to small sizes => leftover likely reusable
        if pr % 10 == 0 { h += 6.0; }
        if pr % 20 == 0 { h += 4.0; }
        if pr % 25 == 0 { h += 3.0; }
        if pr % 50 == 0 { h += 2.0; }
        // dead-space penalty: residual in awkward band (1..10) is nearly unusable
        if pr < 10 { h -= 12.0; }
        else if pr < 20 { h -= 6.0; }
        h
    };
    score -= harmony;

    // Capacity fraction thresholds on post_residual
    let frac = post_residual as f64 / cap;
    if frac > 0.5 {
        score -= 4.0; // bin still half-empty: good target for future items
    } else if frac < 0.1 && pr > 0 {
        score += 5.0; // sliver left: penalize
    }

    // Lookahead coupling: does post_residual fit next item exactly / well?
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 15.0; // perfect chain
        } else if next_item_size <= pr {
            score -= (pr - next_item_size) as f64 * 0.5; // decent chain
        } else {
            // next item won't fit here; mild penalty scaled by overshoot
            score += ((next_item_size - pr).min(30)) as f64 * 0.3;
        }
        // harmonic class of next_item_size vs residual grid
        if next_item_size % 10 == 0 && pr % 10 == 0 {
            score -= 3.0;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when no open bin is a good fit
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        // penalty grows with number of open bins (avoid bin proliferation)
        score += 18.0 + 2.0 * open_bins_count as f64 * (1.0 - progress);
        // but if mean residual is tiny (all bins nearly full), opening is fine
        if mean_residual < 15.0 {
            score -= 22.0;
        }
        // if item is huge, new bin is natural
        if item_size >= 70 {
            score -= 10.0;
        }
    }

    // Tightness reward: prefer bins where item fills a large fraction of residual
    let fill = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill * 8.0;

    // Progress modulation: later in stream, be slightly greedier about tight fits
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 2.0 * (100.0 - post_residual as f64).max(0.0) / 100.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // Gaps that cannot fit even the smallest plausible item (<= 10) are dead space.
    let dead_threshold = 10u32;
    if post_residual < dead_threshold && post_residual > 0 {
        score += 60.0; // near-zero gap: wasted space, strongly penalize
    } else if post_residual == 0 {
        score -= 25.0; // perfect fit: reward heavily
    } else if post_residual <= 20 {
        // Small residual that only tiny items can use: moderate penalty scaled by gap smallness
        score += (20.0 - post_residual as f64) * 2.5;
    }

    // Coupling with lookahead: if next item fits in post_residual, reward this placement
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 18.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // residual too small for next item: dead space for the lookahead
        score += 12.0;
    }

    // Last-chance bin pressure: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, prefer tight fills
    let open_pressure = open_bins_count as f64;
    score += open_pressure * 1.5;

    // Deviation from mean residual: bins far tighter than average are precious, use them;
    // bins with large residuals relative to mean can absorb without much cost.
    let tightness = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    score -= tightness * 15.0;

    // New-bin candidate: penalize opening a new bin unless current residuals are all poor fits.
    if bin_residual == bin_capacity {
        // Opening a new bin is costly when many bins are open or when some bin fits well.
        score += 35.0 + open_pressure * 2.0;
        if fitting_bins_count > 0 && fitting_bins_count <= 2 {
            score += 20.0; // opening new bin while few fitting bins exist is wasteful
        }
        // Exception: if the item is huge relative to typical residual, new bin may be best
        if item_size as f64 > mean_residual {
            score -= 25.0;
        }
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 30.0; // reserve a fresh bin for a paired packing of item + next
        }
    }

    // Progression: later in the stream, closing bins tightly matters more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual already does this).

    // Aggressive 2-step lookahead: reward when post_residual exactly matches
    // the next item, or is very close (chain packing).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (post_residual as f64 - nxt).abs();
        if post_residual as f64 >= nxt {
            // Next item can chain into this bin: reward tight chain.
            score -= 60.0 * (1.0 - diff / nxt.max(1.0));
            if diff == 0.0 {
                score -= 40.0; // perfect 2-item chain
            }
        } else {
            // Next item won't fit here: post_residual becomes dead space
            // unless it's small. Penalize proportionally to wasted space.
            let waste = post_residual as f64 / bin_capacity as f64;
            score += 30.0 * waste;
        }
    } else {
        // Last item: minimize leftover as usual.
        score += 10.0 * (post_residual as f64 / bin_capacity as f64);
    }

    // Relative-to-mean coupling: bins with residual far below mean are
    // "nearly full" — placing here is efficient; reward it.
    let dev = mean_residual - post_residual as f64;
    score -= 0.15 * dev;

    // Last-chance logic: if this is the ONLY bin that fits the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a fresh bin wastes capacity when
    // any open bin gives a decent fit. Penalize the new bin unless the best
    // alternative would leave huge dead space. New bin has post_residual
    // = capacity - item_size; penalize it so it only wins when open-bin
    // fits are terrible (large post_residual elsewhere already penalized).
    if bin_residual == bin_capacity {
        score += 20.0;
        // Early in stream, mildly discourage bin proliferation.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 * (1.0 - progress);
        // If next item is large, a fresh bin keeps flexibility: small relief.
        if next_item_size >= item_size && next_item_size > 0 {
            score -= 10.0;
        }
    }

    // Discard tiny-waste noise: prefer leaving <10 dead space over ~50.
    if post_residual < 10 {
        score -= 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good, already covered by base.
    // Penalize creating dead space that no plausible future item can use.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Lookahead coupling: if the next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // next item fits, but leaves how much dead space after?
            let nxt_post = post_residual - next_item_size;
            score -= 20.0 - (nxt_post as f64).min(20.0);
        } else {
            // next item cannot use this residual: penalize proportional waste
            score += 5.0 + 0.3 * (next_item_size.saturating_sub(post_residual) as f64);
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: empty bin (residual == capacity).
    if bin_residual == bin_capacity {
        // Prefer reusing open bins unless they fit poorly.
        // Base penalty grows with how well the item would fit elsewhere;
        // here we only know this is fresh: give it a moderate default score.
        score = (bin_capacity - item_size) as f64 + 25.0;
        // Late in the stream, opening new bins is less attractive (leftover waste).
        score += 30.0 * t;
        // If many bins are open, prefer filling them rather than adding more.
        score += 2.0 * open_bins_count as f64;
        // If next item is small, a fresh bin is more flexible.
        if next_item_size > 0 && next_item_size <= 30 {
            score -= 15.0;
        }
    } else {
        // Reward using bins with residuals close to the item (perfect packing).
        let tightness = (bin_residual - item_size) as f64 / bin_capacity as f64;
        score += 10.0 * tightness;
        // Prefer bins whose residual is below mean residual (filling emptier space
        // keeps a spread of usable residuals alive).
        if (bin_residual as f64) < mean_residual {
            score -= 5.0;
        } else {
            score += 3.0;
        }
        // Early stream: keep large residuals flexible; late stream: fill greedily.
        score -= 15.0 * (1.0 - t) * (post_residual as f64 / bin_capacity as f64);
    }

    // Global pressure: many open bins -> discourage spreading, encourage consolidation.
    score += 0.5 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let c = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_norm = pr / c;
    let mut score = pr as f64;
    // non-linear quadratic coupling of post_residual with progress
    score -= 12.0 * fit_norm * fit_norm * (1.0 - progress);
    // reward tight fits more strongly as stream progresses
    score -= 8.0 * (1.0 - fit_norm) * (1.0 - fit_norm) * progress;
    // penalize dead space relative to mean residual
    score += 0.3 * (pr - mean_residual).abs();
    // lookahead: reward residual that can host next item smoothly
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let host = (pr / nx).min(1.0);
        score -= 6.0 * host * host;
    }
    // last-chance bonus
    if fitting_bins_count == 1 {
        score -= 15.0;
    }
    // slight penalty for opening new bins early
    if bin_residual == bin_capacity {
        score += 10.0 * (1.0 - progress) + 0.5 * open_bins_count as f64;
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover belongs to a
    // "dead zone" (too small for typical next items) are heavily penalized
    // when post_residual is large but awkward; tight fits are rewarded.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Perfect (near-zero) residual is ideal.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Modulo-style harmonic classes on post_residual (capacity 100):
        // class 0: pr <= 10  (nearly full, excellent)
        // class 1: 10 < pr <= 25 (usable for mid items)
        // class 2: 25 < pr <= 50 (half-empty, mediocre)
        // class 3: pr > 50 (wasteful placement)
        let class = if pr <= 10.0 { 0 }
                    else if pr <= 25.0 { 1 }
                    else if pr <= 50.0 { 2 }
                    else { 3 };
        score += match class {
            0 => -300.0,
            1 => -100.0,
            2 => 0.0,
            _ => 150.0,
        };

        // Integer-division threshold: does the lookahead item fit exactly
        // into the post residual? Reward chain-ability.
        if next_item_size > 0 {
            let nxt = next_item_size as f64;
            if next_item_size <= post_residual {
                // next item fits here: strong reward, scaled by tightness
                let tight = 1.0 - (pr - nxt) / cap;
                score -= 200.0 + 250.0 * tight;
            } else {
                // next item cannot use this leftover: penalize large leftovers
                score += 60.0 * (pr / cap);
            }
            // Exact division harmony: post_residual is an integer multiple
            // of next_item_size -> multiple future items slot in perfectly.
            if next_item_size > 0 && post_residual % next_item_size == 0 && post_residual > 0 {
                score -= 120.0;
            }
        }
    }

    // Last-chance bin: if this is the only bin that fits, force usage.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 500.0;
    }

    // New-bin candidate (empty bin): only attractive when nothing fits well
    // elsewhere, i.e. when open bins are crowded on average.
    if bin_residual == bin_capacity {
        // Baseline mild preference against opening new bins.
        score += 250.0;
        // But if mean residual across open bins is too small to hold the
        // next item comfortably, opening fresh space is wise.
        if next_item_size > 0 && mean_residual < next_item_size as f64 {
            score -= 350.0;
        }
        if fitting_bins_count == 0 {
            score -= 400.0;
        }
        // Late in the stream, avoid proliferating bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 200.0 * progress;
    }

    // Mild pressure to consolidate into fewer bins when many are open.
    score += 5.0 * open_bins_count as f64 * (pr / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 12.0;
    } else if post_residual == 0 {
        // Perfect fit reward
        score -= 30.0;
    }

    // Reward tight fits: fraction of bin used by this placement.
    let tightness = item_size as f64 / bin_residual as f64;
    score -= 15.0 * tightness;

    // Open-bin pressure: with many open bins, prefer filling existing ones
    // rather than spreading; penalize candidates in proportion to open count.
    score += 0.35 * open_bins_count as f64;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive when current bins are
    // mostly full (low mean residual) or no good fit exists.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = bin_capacity as f64 - 0.5 * mean_residual;
        // Slightly less eager to open bins late in the stream.
        score += 10.0 * progress;
        if post_residual < 20 {
            score += 20.0;
        }
    }

    // Lookahead coupling: if next item fits in the post residual, reward.
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        score -= 8.0;
    } else if next_item_size > 0 && post_residual > 0 && (post_residual as u32) < next_item_size {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 50.0;
    }

    // Aggressive 2-step lookahead: reward when next item fits exactly into post_residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 400.0;
        } else if post_residual > next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 120.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit here; penalize wasted space relative to next item.
            score += 0.3 * (next_item_size - post_residual) as f64;
        }
    }

    // Compare post_residual against mean residual across open bins.
    score += 0.5 * (post_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: prefer it only when it promises a good chain with the next item
    // and existing fits are poor.
    if bin_residual == bin_capacity {
        let base_penalty = 150.0;
        let lookahead_bonus = if next_item_size > 0 && next_item_size <= bin_capacity {
            (bin_capacity - next_item_size) as f64 * 0.5
        } else {
            0.0
        };
        // As stream progresses, be more reluctant to open new bins.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score = base_penalty + lookahead_bonus + 100.0 * progress;
        // If many open bins, discourage opening yet another.
        score += 5.0 * open_bins_count as f64;
    }

    // Mild penalty for leaving large awkward gaps (dead space in 60..100 residual range).
    if post_residual > 60 {
        score += 0.2 * (post_residual - 60) as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fits are strongly preferred
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 40.0 * fit_ratio * fit_ratio;

    // Penalize dead space relative to smallest plausible future item
    let dead = post_residual as f64;
    if dead > 0.0 && dead < 10.0 {
        score -= 15.0; // tiny residual is great (near-perfect fill)
    } else if dead >= 10.0 && dead < 20.0 {
        score -= 5.0;
    } else {
        score += 0.15 * dead;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else {
        score += 3.0 * (fitting_bins_count as f64 - 1.0);
    }

    // Lookahead: bonus if next item fits the post residual
    if next_item_size > 0 {
        if (next_item_size as f64) <= dead {
            score -= 12.0 * (1.0 - (next_item_size as f64 / bin_capacity as f64));
        } else {
            // penalize leaving residual just under next item (wasted gap)
            let gap = dead - (next_item_size as f64 - 1.0);
            if gap > 0.0 && gap < 8.0 {
                score += 8.0;
            }
        }
    }

    // Global state: many open bins -> consolidate into existing ones
    score += 0.5 * open_bins_count as f64 * (1.0 - fit_ratio);

    // Mean residual coupling: prefer bins below mean residual (fill fuller bins first)
    score += 0.3 * (mean_residual - bin_residual as f64);

    // New-bin candidate handling: opening a new bin is costly unless current fit is bad
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let threshold = 55.0 - 10.0 * progress;
        if fit_ratio > 0.75 || fitting_bins_count <= 1 {
            score -= 5.0; // acceptable to open when fits are poor
        } else {
            score += threshold;
        }
    }

    // Time horizon: late in stream, push toward tighter packing
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.2 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = (step_index as f64 / total_items as f64).clamp(0.0, 1.0);
    let fit_norm = pr / cap;
    let tightness = 1.0 - fit_norm;

    // Smooth non-linear coupling of post_residual with stream progress
    let mut score = pr * (1.0 + 0.8 * progress * progress);

    // Reward tight fits more strongly later in the stream
    score -= 2.0 * cap * tightness.powi(3) * (0.5 + progress);

    // Penalize residuals that are unusable relative to typical item sizes
    let unusable = (pr as u32).min(100);
    score += 0.05 * (unusable as f64).powi(2) * (1.0 - fit_norm);

    // Last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Lookahead: reward leaving room for the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr as f64 >= nxt {
            score -= 5.0 * (1.0 - pr / (pr + nxt));
        } else {
            score += 10.0;
        }
    }

    // Mild penalty for opening a new bin when many bins are open
    if bin_residual == bin_capacity {
        score += 5.0 + 0.5 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residuals that are "nice" fractions
    // of capacity (0, 10, 20, 25, 50) are more reusable.
    let harmonic = post_residual % 10 == 0 || post_residual % 25 == 0;
    if harmonic {
        score -= 6.0;
    }

    // Dead-space penalty: tiny residuals (< 10) are unusable.
    if post_residual < 10 && post_residual > 0 {
        score += 40.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Lookahead coupling: does the next item fit in the post-residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0;
            // Extra reward if next item nearly fills remaining space.
            let gap = post_residual - next_item_size;
            if gap <= 10 {
                score -= 10.0;
            }
        } else {
            // Next item won't fit here; penalize leaving large unusable space.
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    } else {
        // Last item: strongly prefer filling bins as tightly as possible.
        score -= 15.0;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate (empty bin): penalize so we only open when open bins fit badly.
    if bin_residual == bin_capacity {
        score += 55.0;
        // But if existing fits leave lots of waste, opening is fine.
        if post_residual < 30 {
            score -= 45.0;
        }
    }

    // Prefer bins below mean residual (keep bins balanced, save tight bins).
    if (post_residual as f64) < mean_residual {
        score -= 3.0;
    } else {
        score += 2.0;
    }

    // Late in the stream, consolidation matters more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 8.0;

    // Mild penalty for many open bins: encourage closing bins out.
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Medium dead space is also undesirable.
    if post_residual >= 10 && post_residual < 20 {
        score += 15.0;
    }

    // Reward tight fits.
    score -= (bin_residual - post_residual) as f64 * 0.5;

    // Pressure from many open bins: prefer filling existing bins.
    score += open_bins_count as f64 * 2.0;

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Lookahead: if next item fits into post_residual, reward this placement.
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 25.0;
    }
    // Penalize leaving a gap that almost fits next item (dead space trap).
    if next_item_size > 0 && post_residual > 0 && (post_residual as u32) < next_item_size && (post_residual as u32) > next_item_size / 2 {
        score += 10.0;
    }

    // New-bin candidate: penalize opening a new bin unless current residuals are bad.
    if bin_residual == bin_capacity {
        score += 30.0 + open_bins_count as f64 * -1.5;
        if mean_residual > 20.0 {
            score += 20.0;
        }
    }

    // Stream progression: later in stream, be more conservative about waste.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Tight fit reward: fraction of bin used by this item
    let tightness = item_size as f64 / bin_capacity as f64;
    score -= 30.0 * tightness;

    // 2-step lookahead: reward if next item fits into post_residual
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // chainability bonus, stronger the tighter the chain
            let chain_tight = (post_residual - next_item_size) as f64;
            score -= 40.0 * (1.0 - chain_tight / bin_capacity as f64);
        } else {
            // post_residual is dead space for the next item
            score += 0.5 * post_residual as f64;
            // extra penalty if post_residual is small but unusable (fragmentation)
            if post_residual < 10 {
                score += 25.0;
            }
        }
    }

    // Compare residual against mean residual across open bins:
    // prefer placing into bins with more residual than average (consolidate emptier bins)
    let dev = bin_residual as f64 - mean_residual;
    score -= 0.3 * dev;

    // Last-chance bin: strongly favor using the only bin that fits
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate handling: penalize opening a new bin, but allow it
    // when no open bin would give a good fit (large dead space avoided).
    if bin_residual == bin_capacity {
        let mut penalty = 150.0;
        // If next item is large and this item would leave a bad residual elsewhere,
        // opening fresh is relatively better.
        if next_item_size > 0 && post_residual < next_item_size {
            penalty -= 60.0;
        }
        // Later in the stream, avoid bin proliferation
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        penalty += 50.0 * progress;
        // Many open bins already -> discourage new bins
        penalty += 10.0 * open_bins_count as f64;
        score += penalty;
    }

    // Mild preference for filling older/denser bins as stream progresses
    score += 5.0 * (1.0 - step_index as f64 / total_items.max(1) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
