pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let resid = bin_residual as f64;
    let item = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: prefer minimal post residual, with smooth quadratic refinement.
    let mut score = post + (post / cap) * (post / cap) * 20.0;

    // Tightness reward: fraction of bin consumed by this placement.
    let fill = item / cap;
    score -= 30.0 * fill * (1.0 - 0.5 * progress);

    // Smooth coupling of post_residual with stream progress:
    // late in the stream, dead space is costlier; early, flexibility is fine.
    let dead_penalty = (post / cap).powi(2) * (10.0 + 40.0 * progress * progress);
    score += dead_penalty;

    // Perfect-ish fits get strong smooth reward (Gaussian-like bump around zero post residual).
    let tightness = (-post * post / (2.0 * 25.0)).exp();
    score -= 25.0 * tightness;

    // Lookahead: if the next item exactly fits the post residual, big reward (smooth).
    if next_item_size > 0 && (next_item_size as f64) <= post {
        let gap = (post - next_item_size as f64) / cap;
        score -= 35.0 * (-gap * gap * 8.0).exp();
    }
    // Penalize post residual that no plausible item can use.
    if next_item_size > 0 && (next_item_size as f64) > post {
        score += 6.0 * (1.0 - post / cap);
    }

    // Last-chance bin: strongly prefer using the only fitting bin.
    if fitting_bins_count <= 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // Many open bins: prefer consolidating into bins with small residual relative to mean.
    let rel = if mean_residual > 0.0 { resid / mean_residual } else { 1.0 };
    score += (rel - 1.0).abs() * (open_bins_count as f64).sqrt() * 3.0;

    // New-bin candidate handling: opening a new bin wastes capacity; penalize unless
    // current placements would leave very poor fits (large post residual everywhere).
    if bin_residual == bin_capacity {
        let avg_waste = mean_residual / cap;
        let desperation = (post * 0.0 + avg_waste * avg_waste * 60.0) * progress.max(0.2);
        score += 45.0 - desperation - 20.0 * progress;
        // If no open bin fits tightly, new bin becomes attractive.
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-fit residual: bins whose leftover falls into
    // "useful" classes (divisible by common item sizes) are rewarded.
    let post = post_residual;
    let cap = bin_capacity;

    // Reward small post_residual (tight fit) super-linearly.
    let tightness = 1.0 - (post as f64 / cap as f64);
    score -= 18.0 * tightness * tightness * (item_size as f64 / cap as f64);

    // Penalize "dead zones": residuals that are too small for the smallest
    // plausible item (1..100 interface => anything < ~10 is nearly dead,
    // but keep general: residual below a small fraction of capacity).
    let dead_threshold = cap / 20;
    if post > 0 && post < dead_threshold {
        score += 25.0 * (1.0 - post as f64 / dead_threshold as f64);
    }

    // Harmonic classes: check if post_residual can host the lookahead item.
    if next_item_size > 0 {
        if next_item_size <= post {
            // Perfect chain: next item fits exactly into the remainder.
            let slack = (post - next_item_size) as f64;
            let chain_bonus = if slack == 0.0 {
                40.0
            } else if slack < (cap / 10) as f64 {
                28.0
            } else {
                14.0
            };
            score -= chain_bonus;
            // Extra reward if the chain residual again lands on a harmonic class.
            if (post - next_item_size) % (cap / 4) == 0 && post != next_item_size {
                score -= 6.0;
            }
        } else {
            // Lookahead cannot use this bin: penalize proportionally to how
            // much of the residual is wasted relative to the next item.
            score += 8.0 * (1.0 - post as f64 / next_item_size as f64);
        }
    } else {
        // Last item: pure tightness matters most.
        score -= 10.0 * tightness;
    }

    // Integer-division thresholds on post_residual (harmonic bins).
    let quarter = cap / 4;
    let half = cap / 2;
    if post == 0 {
        score -= 30.0; // perfect fill
    } else if post % half == 0 && post > 0 {
        score -= 10.0; // residual is a half-capacity class, reusable
    } else if post % quarter == 0 && post > 0 {
        score -= 5.0;
    } else {
        // Non-harmonic residual: mild penalty scaled by residual size.
        score += 3.0 * (post as f64 / cap as f64);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 22.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when all open bins
    // would create large dead space and the item is large.
    if bin_residual == bin_capacity {
        let crowd_pressure = (open_bins_count as f64 / (1.0 + mean_residual / cap as f64)) * 0.5;
        let item_fraction = item_size as f64 / cap as f64;
        // New bin is penalized normally, but relief grows with crowding and
        // large items that would fragment existing bins.
        score = item_fraction * 100.0
            - 12.0 * (1.0 - item_fraction)
            + crowd_pressure
            - (if fitting_bins_count == 0 { 20.0 } else { 0.0 });
        // Prefer opening a new bin when the next item is large and would
        // otherwise need its own bin anyway.
        if next_item_size >= cap / 2 {
            score -= 8.0;
        }
    }

    // Mild preference to balance load across many open bins late in stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score += 2.0 * progress * (post as f64 / cap as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (< 10, minimum item size)
    // are worthless; penalize them extra hard.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Near-dead gaps (10..=15) are only usable by tiny items; soft penalty.
    else if post_residual >= 10 && post_residual <= 15 {
        score += 12.0;
    }

    // Reward tight fits: exact fill is ideal.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward bins whose residual is close to the item (snug placement).
    let snugness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score -= 20.0 * (1.0 - snugness);

    // Lookahead: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }
    // If next item would be blocked by post-residual, penalize.
    if next_item_size > post_residual && next_item_size > 0 {
        score += 6.0;
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Open-bins pressure: more open bins -> prefer filling existing ones over
    // opening new bins (raise the new-bin candidate's score implicitly by
    // lowering scores of real bins with usable residuals).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 0.8 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Prefer bins with residual below the mean residual (consolidating fullness).
    if (bin_residual as f64) < mean_residual {
        score -= 8.0;
    } else {
        score += 8.0;
    }

    // Penalize the brand-new empty bin candidate mildly, unless current bins
    // are all crowded (low mean residual means open bins are quite full).
    if bin_residual == bin_capacity {
        score = bin_capacity as f64 * 0.5 + 10.0 * open_bins_count as f64;
        // If open bins are nearly exhausted on average, opening a new bin is fine.
        if mean_residual < 25.0 {
            score -= 30.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward: eliminate dead space entirely.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: does the next item fit into the leftover?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Next item chains perfectly: strong reward, tighter for exact chain.
            let chain_slack = (post_residual - next_item_size) as f64;
            score -= 60.0 - 0.5 * chain_slack;
            if next_item_size == post_residual {
                score -= 200.0; // perfect 2-chain
            }
        } else {
            // Next item won't fit here: penalize leftover dead space, scaled by
            // how close the next item is to fitting (near-miss = wasted potential).
            let miss_gap = (next_item_size - post_residual) as f64;
            score += 20.0 + 0.8 * miss_gap;
        }
    }

    // Relative waste vs. mean residual across open bins: prefer bins whose
    // post-residual deviates favorably (smaller) from the mean.
    score += 0.6 * (post_residual as f64 - mean_residual);

    // Last-chance bin: if this is the only bin that fits, avoid opening a new
    // bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0 + 0.5 * item_size as f64;
    }

    // New-bin candidate handling: opening a new bin should only win when the
    // item fits poorly everywhere else (large item, many open bins, high mean
    // residual). Make the empty-bin baseline moderately high.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = 80.0
            - 0.3 * item_size as f64          // big items are fine in fresh bins
            + 0.5 * mean_residual              // poor average fit elsewhere -> open
            + 2.0 * open_bins_count as f64
            - 20.0 * progress;                 // slightly prefer opening late
        if fitting_bins_count <= 1 {
            score += 500.0; // never open when a usable bin exists as sole option
        }
    }

    // Mild preference for tighter fits among comparable bins.
    score += 0.1 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
