    // New-bin candidate handling: only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin; reduced late in the stream or when
        // the lookahead would fill the fresh bin well.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let mut new_bin_cost = 55.0 - 20.0 * progress;
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            new_bin_cost -= 20.0;
        }
        // If many bins fit the item, opening a new one is rarely needed.
        new_bin_cost += 5.0 * fitting_bins_count as f64;
        score += new_bin_cost;
    }

    // Small bonus for keeping open bin count manageable.
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Tight-fit reward: strongly favor small post residuals (non-linear).
    if post > 0.0 {
        score -= 24.0 * (1.0 - post / cap).powi(6);
    } else {
        score -= 30.0; // perfect fit
    }

    // Penalize creating dead space that no plausible future item (10..80) can use.
    if post > 0.0 && post < 10.0 {
        score += 20.0; // unusable sliver
    }

    // Lookahead coupling: reward if next item fits into post_residual.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let slack = post - nxt;
            score -= 10.0 * (1.0 - slack / cap).max(0.0);
        } else {
            score += 4.0 * ((nxt - post) / cap);
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Global-state coupling: many open bins with high mean residual -> prefer consolidation.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if open_bins_count > 2 && mean_residual > (item_size as f64) {
        score -= 6.0 * (mean_residual / cap) * progress.min(1.0);
    }

    // New-bin candidate handling: penalize opening a new bin when alternatives exist.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 40.0; // forced new bin
        } else {
            // Only open new bin if existing fits are poor (large post residuals elsewhere
            // are handled by their own scores); add a moderate opening cost.
            score += 12.0 + 8.0 * (1.0 - progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let fit = (item_size as f64) / cap;
    let tight = 1.0 - fit; // fraction of bin left after placement

    // Reward tight fits (small post_residual) with a smooth non-linear coupling
    // that strengthens as the stream progresses.
    let tightness = (1.0 - tight).powi(3);
    score -= 30.0 * tightness * (0.5 + t);

    // Penalize dead space: post_residual too small to ever be useful
    // (smooth ramp once post_residual falls below the smallest plausible item).
    let dead = ((14.0 - pr) / 14.0).max(0.0);
    score += 60.0 * dead * dead;

    // Lookahead coupling: if next item fits into the post residual, reward;
    // if it nearly fits, mildly penalize (chaining risk).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= 12.0 * (1.0 - ((pr - nxt) / cap)) * (0.5 + 0.5 * t);
        } else {
            let gap = (nxt - pr) / cap;
            score += 10.0 * (1.0 - gap).max(0.0);
        }
    }

    // Last-chance bin: strongly favor using it instead of opening a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    } else if fitting_bins_count > 2 {
        // many alternatives: mild penalty to keep fragmentation low
        score += 4.0 * ((fitting_bins_count - 2) as f64).min(6.0);
    }

    // Contextual term: when open bins collectively have lots of slack
    // (mean residual high), prefer consolidating into them rather than
    // opening new bins; when slack is scarce, opening a new bin is fine.
    let mr_norm = mean_residual / cap;
    score -= 15.0 * mr_norm * (1.0 - t);

    // New-bin candidate: its post_residual equals capacity - item_size.
    // Give it a smooth handicap that shrinks when it is the only viable
    // consolidation point (low mean residual, many open bins).
    if bin_residual == bin_capacity {
        let handicap = 25.0 * (1.0 - mr_norm.max(0.0).min(1.0)) * (1.0 - (open_bins_count as f64 / (open_bins_count as f64 + 8.0)));
        score += handicap;
    }

    // Smooth non-linear stream-progress interaction: later in the stream,
    // waste hurts more (fewer chances to recover).
    score += 8.0 * t * (pr / cap).powi(2);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress fraction of the stream
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // ---- New-bin candidate handling ----
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base cost of opening a new bin: high, but decays as stream progresses
        // (late in the stream, hoarding residuals is less useful).
        let mut new_bin_cost = 60.0 - 25.0 * progress;

        // If very few bins can fit this item, opening a bin is more acceptable.
        if fitting_bins_count == 0 {
            new_bin_cost -= 30.0;
        } else if fitting_bins_count == 1 {
            new_bin_cost -= 10.0;
        }

        // Large items leave little room for waste; opening fresh is fine for them.
        if item_size > bin_capacity * 3 / 4 {
            new_bin_cost -= 15.0;
        }
        // Small items should almost always go into existing bins.
        if item_size <= bin_capacity / 5 {
            new_bin_cost += 20.0;
        }

        // If existing bins are already quite full on average, a new bin is natural.
        let mean_fill = 1.0 - (mean_residual / bin_capacity as f64);
        new_bin_cost -= 20.0 * mean_fill;

        return new_bin_cost;
    }

    // ---- Existing-bin scoring ----
    // Perfect fit is ideal.
    if post_residual == 0 {
        score -= 1000.0;
        return score;
    }

    // Reward tight fits (small post_residual) non-linearly.
    let pr = post_residual as f64;
    score -= (bin_capacity as f64 / (pr + 1.0)) * 2.0;

    // Harmonic-class penalty: post_residual divisible by common item sizes
    // (10..80 multiples) is more likely reusable by future items.
    let mut reusable = 0u32;
    for d in [10u32, 20, 25, 50] {
        if post_residual % d == 0 && post_residual > 0 {
            reusable += 1;
        }
    }
    score -= 8.0 * reusable as f64;

    // Penalize awkward dead space: residuals in (0,10) are nearly useless.
    if post_residual < 10 {
        score += 25.0;
    }
    // Penalize the "just over half" dead zone: residual in 51..=60 fits few items.
    if post_residual > bin_capacity / 2 && post_residual <= bin_capacity * 3 / 5 {
        score += 10.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // strongly favor this bin (sets up a perfect fit).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 120.0;
        } else if next_item_size < post_residual {
            let next_pr = post_residual - next_item_size;
            if next_pr < 10 {
                score -= 15.0; // leaves tiny waste, fine
            } else if next_pr > bin_capacity / 2 {
                score += 8.0; // wastes the bin on the lookahead too
            }
        } else {
            // Next item won't fit here; prefer bins whose residual is small anyway.
            score += 5.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Slight preference for fuller bins when many bins are open (bin consolidation).
    score -= 5.0 * (1.0 - bin_residual as f64 / bin_capacity as f64);

    // Mild pressure to consolidate when many bins are open.
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 18.0;
    }

    // Reward tight fits: post_residual near zero is best.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Reward bins whose residual closely matches the item (good packing ratio).
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score += tightness * 0.15;

    // Pressure from number of open bins: discourage opening/spreading too much.
    score += open_bins_count as f64 * 0.8;

    // Last-chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is bad.
    if bin_residual == bin_capacity {
        score += 30.0;
        // But if this bin would be nearly empty anyway and the fit elsewhere is poor,
        // allow it: keep base post_residual = capacity - item_size.
        if post_residual as f64 > mean_residual {
            score += 10.0;
        }
    }

    // Lookahead: if the next item can use the post residual, reward leaving it.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }

    // Mean residual coupling: prefer bins with residual below mean (denser bins).
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    }

    // Mild progression scaling: later in stream, be slightly more conservative.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 4.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches next item size
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 200.0 * (1.0 - diff / bin_capacity as f64).max(0.0);
        // exact lookahead match bonus
        if post_residual == next_item_size {
            score -= 300.0;
        }
        // penalize leaving dead space the next item cannot use
        if post_residual < next_item_size {
            score += 0.5 * (next_item_size - post_residual) as f64;
        }
    }

    // Tightness reward relative to mean residual
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Penalize spreading across too many open bins when plenty fit
    if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New bin candidate: penalize unless current bin would be nearly full
    if bin_residual == bin_capacity {
        let fill = item_size as f64 / bin_capacity as f64;
        score += 120.0 * (1.0 - fill);
        if fitting_bins_count > 0 {
            score += 250.0;
        }
    }

    // Early stream: mild preference for consolidation
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Tight-fit reward: strongly prefer bins where the item fills most of the residual.
    let fill_ratio = 1.0 - post / cap;
    score -= 3.0 * fill_ratio * fill_ratio * (item_size as f64);

    // Penalize leaving dead space that nothing small can use later.
    if post > 0.0 && post < 10.0 {
        score += 8.0; // tiny unusable sliver
    }

    // Lookahead: if the next item would fit exactly in the post residual, reward;
    // if post residual is large enough for next item anyway, mild reward; else small penalty.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            score -= 2.0 * (1.0 - (post - nxt) / cap);
        } else {
            score += 1.5 * (nxt - post) / cap;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly favor using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 6.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when all
    // open bins would leave large post residuals (poor fits) or few bins are open.
    if bin_residual == bin_capacity {
        let best_alternative_penalty = if fitting_bins_count == 0 { 0.0 } else {
            // cost of abandoning open capacity proportional to mean residual
            mean_residual * 0.05 * (open_bins_count as f64)
        };
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = 0.35 * cap + best_alternative_penalty - 5.0 * (1.0 - progress);
        if next_item_size > 0 && (next_item_size as f64) <= cap - item_size as f64 {
            score -= 1.0; // fresh bin pairs well with next item
        }
    }

    // Mild preference to consolidate into fewer bins when many are open.
    score += 0.02 * (open_bins_count as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let tightness = 1.0 - pr / cap;

    // Smooth non-linear coupling of post_residual with stream progress
    let progress_coupling = (pr / cap) * (1.0 - progress) * (1.0 - progress);
    score += 12.0 * progress_coupling;

    // Quadratic penalty on wasted residual, scaled by progress
    score += (pr * pr / cap) * (0.3 + 0.7 * progress);

    // Cubic tightness reward: favor bins that become nearly full
    score -= 8.0 * tightness * tightness * tightness;

    // Lookahead: penalize residual that cannot fit next item, smooth ramp
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let gap = (nx - pr).max(0.0) / cap;
        score += 10.0 * gap * (1.0 + progress);
        // Reward residual that exactly accommodates next item
        let fit = 1.0 - ((pr - nx).abs() / cap).min(1.0);
        score -= 6.0 * fit * fit;
    }

    // Last-chance bin bonus (smooth, via fitting_bins_count)
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 + progress);
    }

    // Mild penalty for scattering across many open bins
    score += (open_bins_count as f64).ln().max(0.0) * 0.5;

    // Mean-residual deviation: prefer bins deviating from mean (consolidation)
    let dev = (pr - mean_residual).abs();
    score -= 2.0 * (1.0 - (dev / cap).min(1.0));

    // New-bin candidate: only attractive when nothing fits well
    let is_new = (bin_residual as f64 - cap).abs() < 1e-6;
    if is_new {
        score += 5.0 + 10.0 * (1.0 - progress) - 4.0 * (pr / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-fit residual: residues divisible by common
    // item granularity (e.g. 10) are more reusable than odd dead space.
    let res = post_residual;
    let class_bonus = match res % 10 {
        0 => 12.0,
        5 => 6.0,
        _ => 0.0,
    };
    score -= class_bonus;

    // Integer-division thresholds: classify residual into usability tiers.
    let tier = res / 10; // 0..=10
    if tier == 0 && res > 0 {
        // Tiny unusable sliver -> strong penalty (dead space).
        score += 18.0;
    } else if tier >= 3 && tier <= 6 {
        // Mid-range residual is highly attractive for future items.
        score -= 5.0;
    }

    // Perfect / near-perfect fit rewards.
    if res == 0 {
        score -= 40.0;
    } else if res <= 5 {
        score -= 20.0;
    }

    // Lookahead coupling: if the next item fits the post residual exactly,
    // strongly reward this placement (chained packing).
    if next_item_size > 0 {
        if res == next_item_size {
            score -= 25.0;
        } else if res >= next_item_size {
            let post2 = res - next_item_size;
            if post2 % 10 == 0 || post2 == 0 {
                score -= 10.0;
            }
        } else {
            // Next item cannot use this bin's remainder: mild penalty scaled
            // by how much of the remainder is wasted relative to capacity.
            score += (res as f64 / bin_capacity as f64) * 8.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: empty bin should only win when no open bin
    // offers a decent fit. Penalize it proportionally to open bins and mean
    // residual so we exhaust existing capacity first.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 30.0 + 5.0 * open_bins_count as f64 + 10.0 * (mean_residual / bin_capacity as f64) * (1.0 - progress);
        // Late in the stream, allow new bins more readily (bins won't be reused much).
        if progress > 0.85 {
            score -= 20.0;
        }
    } else {
        // Favor bins whose residual is close to the item (tight packing).
        let tightness = 1.0 - (bin_residual - item_size) as f64 / bin_capacity as f64;
        score -= tightness * 6.0;
        // Prefer bins below mean residual (concentrate filling).
        if (bin_residual as f64) < mean_residual {
            score -= 4.0;
        } else {
            score += 2.0;
        }
    }

    // Modulo coupling between item size and capacity: items that leave
    // capacity-aligned remainders are easy to pack later.
    if (bin_capacity - item_size) % item_size == 0 && bin_residual == bin_capacity - item_size {
        score -= 8.0;
    }

    // Mild pressure to consolidate when many bins are open.
    score += 0.3 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize dead space: small unusable gaps left after placement.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    // Perfect fit reward.
    if post_residual == 0 {
        score -= 25.0;
    }
    // Reward tight fits (small post_residual relative to item).
    score -= (item_size as f64) * (1.0 - post_residual as f64 / bin_residual.max(1) as f64) * 2.0;

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open bins pressure: with many open bins, discourage opening new ones.
    if bin_residual == bin_capacity {
        score += open_bins_count as f64 * 8.0;
        // But if mean residual is small (bins nearly full), opening new bin is fine.
        score -= mean_residual * 0.3;
    } else {
        score -= open_bins_count as f64 * 1.5;
    }

    // Lookahead: if next item fits into post_residual, reward this placement.
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 15.0;
    }
    // Penalize if next item would leave this residual wasted.
    if next_item_size > 0 && next_item_size > post_residual && post_residual > 0 && post_residual < next_item_size.min(10) {
        score += 10.0;
    }

    // Late in stream: prefer consolidating into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual < bin_capacity {
        score -= progress * 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }
    // Near match: next item fits with small waste
    else if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 200.0 - slack * 2.0;
    }
    // Next item does NOT fit: penalize proportionally to dead space created
    else if next_item_size > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 3.0;
    }

    // Reward tight fits relative to mean residual
    let mr = if mean_residual > 0.0 { mean_residual } else { 1.0 };
    score -= (bin_capacity as f64 / mr) * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Last-chance bonus: only this bin fits the item
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // Penalize opening a new bin when good open bins exist
    if bin_residual == bin_capacity {
        score += 500.0;
        // But allow a new bin if the current item would leave terrible residue everywhere
        if post_residual <= 5 {
            score -= 400.0;
        }
    }

    // Mild late-stream pressure to close bins tightly
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * post_residual as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins where the item nearly fills the residual.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 35.0 * tightness * tightness;

    // Exact fill is ideal.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead: penalize leaving a residual that cannot host the next item,
    // reward residuals that can host it (keeps bins usable for the future).
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 0.25 * (next_item_size - post_residual) as f64;
        } else if post_residual >= next_item_size && post_residual < next_item_size * 2 {
            score -= 6.0;
        }
    } else {
        // Last item: only exact/tight fills matter.
        score -= 10.0 * tightness;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (which wastes the current residual).
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive when
    // the item fits poorly everywhere else. Penalize new bins mildly by default,
    // scaled by how much residual would be left unused elsewhere.
    if bin_residual == bin_capacity {
        let open_pressure = open_bins_count as f64;
        score += 18.0 + 2.0 * open_pressure;
        // If the item is large relative to capacity, a new bin is less wasteful.
        score -= 12.0 * (item_size as f64 / bin_capacity as f64);
        // Late in the stream, avoid spawning bins with tiny leftover demand.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    }

    // Global state: many open bins with high mean residual -> prefer reusing
    // bins to consolidate space; few open bins -> opening new bins is cheaper.
    score += 0.15 * mean_residual * (open_bins_count as f64 / (open_bins_count as f64 + 3.0));

    // Prefer bins whose residual is close to the item (avoid fragmenting large gaps).
    let gap = (bin_residual as f64 - item_size as f64).abs();
    score += 0.08 * gap;

    // Mild reward for using bins with lower-than-average residual (drain small holes).
    if (bin_residual as f64) < mean_residual {
        score -= 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fill = 1.0 - pr / cap;
    let tight = (pr / cap).powi(2);

    let mut score = pr;

    // Reward tight fits more strongly as stream progresses
    score -= 40.0 * fill * fill * (0.5 + progress);

    // Penalize mid-range residual dead space (non-linear bowl)
    score += 25.0 * tight * (1.0 - tight) * 4.0 * (1.0 - progress);

    // Last-chance bonus
    if fitting_bins_count == 1 {
        score -= 30.0 * fill;
    }

    // Lookahead: reward leaving room for next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let match_factor = 1.0 - ((pr - nx) / cap).abs();
        score -= 20.0 * match_factor.max(0.0) * (pr >= nx) as i32 as f64;
    } else {
        score -= 15.0 * fill;
    }

    // Discourage spreading when many bins open
    score += 2.0 * (open_bins_count as f64).ln() * (1.0 - fill);
    score += 0.5 * (mean_residual - pr) / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: quadratic bonus for small post_residual.
    let tight = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - tight).powi(3) * 30.0;

    // Perfect fit: massive reward.
    if post_residual == 0 {
        score -= 500.0;
    }

    // Harmonic class logic: classify post_residual into residue classes
    // modulo common item sizes (10..=80 step). Small residues that are
    // "dead space" (unlikely to be filled by typical items) get penalized.
    let dead_thresholds: [u32; 8] = [10, 20, 25, 30, 40, 50, 60, 80];
    let mut dead_penalty = 0.0;
    for t in dead_thresholds.iter() {
        if post_residual > 0 && post_residual < *t {
            dead_penalty += 1.0;
        }
    }
    // Residue in a "harmonic" class (divisible by 10) is more reusable.
    if post_residual % 10 == 0 {
        dead_penalty -= 0.5;
    }
    score += dead_penalty * 8.0;

    // Integer division threshold: post_residual bucketed by quarter capacity.
    let quarter = bin_capacity / 4;
    if post_residual < quarter {
        score += 12.0; // tiny unusable residue
    } else if post_residual >= quarter && post_residual < 2 * quarter {
        score -= 4.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual,
    // strongly reward this placement (chain packing).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 200.0;
        } else if next_item_size <= post_residual {
            let nfit = (post_residual - next_item_size) as f64;
            score -= 20.0 * (1.0 - nfit / bin_capacity as f64);
        } else {
            // next item won't fit here; penalize leaving large gap slightly less
            score += (next_item_size - post_residual) as f64 * 0.1;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate handling: opening a new bin wastes the residual
    // capacity of all open bins. Penalize proportional to open bins and
    // mean residual, unless this bin is a fresh candidate itself.
    if bin_residual == bin_capacity {
        // Fresh bin: baseline score; discourage unless open bins are nearly full.
        score += open_bins_count as f64 * 5.0
            + mean_residual * 0.8
            + 40.0 * (step_index as f64 / total_items.max(1) as f64);
        // A fresh bin is attractive if the item is large relative to mean residual.
        if (item_size as f64) > mean_residual {
            score -= 25.0;
        }
    } else {
        // Existing bin: reward using bins with lower residual (fill fuller bins first).
        score += (mean_residual - bin_residual as f64) * 0.3;
    }

    // Mild pressure to consolidate as stream progresses.
    score -= (open_bins_count as f64).ln().max(0.0) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that can no longer fit the smallest
    // plausible item (<= 10) are pure waste; penalize them heavily.
    if post_residual < 10 {
        score += 40.0;
    } else if post_residual < 20 {
        score += 18.0;
    } else if post_residual < 35 {
        score += 7.0;
    }

    // Reward near-perfect fits superlinearly.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 12 {
        score -= 8.0;
    }

    // Tightness relative to capacity: prefer bins where the item fills
    // a large fraction of the remaining space.
    let fill_ratio = if bin_residual > 0 {
        item_size as f64 / bin_residual as f64
    } else {
        1.0
    };
    score -= 20.0 * fill_ratio * fill_ratio;

    // Open-bin pressure: with many open bins, avoid spreading into
    // additional bins; favor consolidating into existing ones.
    let pressure = open_bins_count as f64 / 8.0;
    score += pressure * (post_residual as f64 / bin_capacity as f64) * 12.0;

    // Last-chance bin: if this is the only bin that fits, using it
    // avoids opening a new bin; reward strongly.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive
    // when no existing bin gives a decent fit and item is large.
    if bin_residual == bin_capacity {
        let poor_fit_elsewhere = mean_residual < item_size as f64 * 0.6;
        if poor_fit_elsewhere {
            // New bin is a clean home for a large item: moderate score.
            score = (bin_capacity - item_size) as f64 + 5.0;
            if item_size >= 60 {
                score -= 10.0;
            }
        } else {
            // Existing bins fit reasonably; discourage opening new bins.
            score += 45.0 + pressure * 10.0;
        }
    }

    // Lookahead: if the next item would fit into the post-residual gap,
    // leaving exactly that gap is valuable; reward keeping usable gaps.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0;
    }
    // Penalize gaps that are too small for the lookahead item but still
    // occupy space (likely dead space).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && post_residual < 10 {
        score += 12.0;
    }

    // Mild early-stream exploration: fewer bins early means longer
    // compaction later; slightly discourage new bins early on.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += (1.0 - progress) * 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits (small post_residual relative to capacity).
    let tightness = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - tightness) * 20.0;

    // Aggressive 2-step lookahead: reward when the next item fits the post_residual.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Next item chains perfectly: strong reward scaled by how well it fills.
            let chain_fill = next_item_size as f64 / post_residual as f64;
            score -= 15.0 * chain_fill;
        } else {
            // Next item won't fit here: penalize wasted residual that can't chain.
            let waste = (next_item_size - post_residual) as f64;
            score += 0.3 * waste.min(50.0);
        }
    }

    // Compare residual against mean residual across open bins: prefer bins that
    // reduce dispersion (place into larger-than-average residual bins).
    score += 0.5 * (mean_residual - bin_residual as f64);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a new bin when decent existing fits exist.
    if bin_residual == bin_capacity {
        score += 30.0;
        // But allow new bin if all existing fits are terrible (post_residual tiny).
        if post_residual < 5.0 as u32 && next_item_size > post_residual {
            score -= 35.0;
        }
    }

    // Mild pressure over stream progression to consolidate bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 5.0 * (open_bins_count as f64 / (open_bins_count as f64 + 5.0));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins where the item nearly fills the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fill_ratio * fill_ratio;

    // Penalize leaving large, hard-to-use residuals (dead space shaping).
    if post_residual > 0 && post_residual < 10 {
        score -= 8.0; // tiny slivers are fine, effectively closed
    } else if post_residual >= 10 && post_residual <= 30 {
        score += 6.0 * (1.0 - (post_residual as f64 - 10.0) / 20.0); // awkward mid-range gaps
    }

    // Lookahead: reward if the next item fits exactly or well in the post residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 15.0; // perfect chaining
        } else if next_item_size < post_residual {
            let chain_waste = post_residual - next_item_size;
            score -= 6.0 * (1.0 - chain_waste as f64 / post_residual.max(1) as f64);
        } else {
            // next item cannot fit here; mild penalty proportional to overflow
            score += 2.0 * (next_item_size - post_residual) as f64 / bin_capacity as f64;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a bin is only attractive when no open bin
    // offers a decent fit, or when open bins are nearly full anyway.
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin.
        score = bin_capacity as f64;
        // If other bins fit the item, only open new when their fits are poor.
        if fitting_bins_count > 0 {
            let best_possible = mean_residual.max(0.0);
            if best_possible - item_size as f64 >= 15.0 {
                score += 25.0; // an open bin has decent room; don't open a new one
            } else {
                score -= 5.0; // open bins are cramped; new bin acceptable
            }
        } else {
            score -= 10.0; // forced open
        }
        // Late in the stream, slightly discourage hoarding fresh bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 8.0 * progress;
    }

    // Global pressure: many open bins with high mean residual -> encourage
    // consolidating into existing space.
    if open_bins_count > 3 && bin_residual != bin_capacity {
        let pressure = mean_residual / bin_capacity as f64;
        score -= 5.0 * pressure;
    }

    // Small time-dependent jitter-free tie-breaker: prefer earlier-opened bins
    // (implicitly via lower residual) already captured; add mild step decay so
    // late items pack tighter.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.15 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let mut score = pr as f64;

    // Smooth progress-modulated shaping: penalize large residuals more as stream matures
    let shape = x * x * (1.0 + 2.0 * progress) - 0.8 * x * x * x * progress;
    score += 60.0 * shape;

    // Reward tight fits (small post_residual) increasingly with progress
    score -= 40.0 * (1.0 - x) * (1.0 - x) * progress;

    // Penalize waste relative to mean residual across open bins
    score += 0.3 * (pr - mean_residual) * (0.5 + progress);

    // Last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0 + 20.0 * progress;
    }

    // Lookahead: prefer bins whose post-residual can host the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0 + 15.0 * (post_residual as f64 - next_item_size as f64) / cap;
    } else if next_item_size > 0 {
        score += 8.0 * progress;
    }

    // Mild pressure to consolidate when many bins are open
    score += 0.5 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: reward "clean" residual classes
    // (multiples of 10 are highly reusable given item sizes 10..80).
    let class = post_residual % 10;
    score += match class {
        0 => -12.0,
        1 | 9 => 6.0,
        2 | 8 => 3.0,
        _ => 0.0,
    };

    // Exact fit is always excellent.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Dead space penalty: residuals that cannot fit even the smallest item.
    if post_residual < 10 && post_residual > 0 {
        score += 15.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Lookahead: if the next item fits the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 14.0 + 0.25 * (next_item_size as f64);
        } else {
            // Waste: next item won't fit here; penalize proportionally.
            score += 0.15 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // Prefer tighter bins when many bins are open (fragmentation control).
    let tightness = 1.0 - (bin_residual as f64) / (bin_capacity as f64);
    score -= 8.0 * tightness;

    // Early in the stream, prefer spreading across bins (keep residuals large);
    // late in the stream, prefer packing tightly.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - progress) * (post_residual as f64) * 0.05;
    score -= progress * (post_residual as f64) * 0.05;

    // Mean-residual coupling: if this bin is much tighter than average, favor it.
    score -= 0.3 * (mean_residual - bin_residual as f64);

    // New-bin candidate: only attractive when no open bin is a good home
    // (i.e., item barely fits anywhere) — penalize opening bins by default.
    if bin_residual == bin_capacity {
        score += 25.0 + 0.2 * (open_bins_count as f64);
        if fitting_bins_count <= 1 {
            score -= 30.0; // last chance -> new bin is fine
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize unusable small gaps (dead space below smallest plausible item)
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual > 0 && post_residual < 20 {
        score += 15.0;
    }

    // Reward tight fits
    score -= (item_size as f64 / bin_capacity as f64) * 10.0;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 50.0;
    }

    // Open bins pressure: discourage spreading across many bins
    score += open_bins_count as f64 * 0.5;

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if next item fits the post-residual, reward this placement
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        score -= 12.0;
    } else if next_item_size > 0 && next_item_size <= bin_residual && next_item_size > post_residual {
        score += 8.0;
    }

    // New-bin candidate: mildly penalize so it's chosen only when open bins are bad
    if bin_residual == bin_capacity {
        score += 10.0 + mean_residual * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits
    score = post_residual as f64 * 1.0 + (item_size as f64 / bin_capacity as f64) * 5.0;

    // Aggressive 2-step lookahead: reward exact match between post_residual and next item
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0; // perfect two-item completion
        } else if post_residual > next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            // penalize leftover after hypothetically placing next item
            score += slack * 0.8;
            if slack <= 10.0 {
                score -= 10.0; // near-perfect chain
            }
        } else {
            // next item cannot fit here; penalize dead space
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.5;
        }
    }

    // Relative to mean residual: prefer bins tighter than average
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Last-chance bin: strong bonus to use it rather than open a new bin
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New empty bin candidate: penalize mildly so it's chosen only when fits are bad
    if bin_residual == bin_capacity {
        score += 25.0;
        // but if lookahead suggests a fresh bin pairs well with next item, ease penalty
        if next_item_size >= 90 {
            score -= 20.0;
        }
    }

    // Late in stream: consolidate, avoid spreading
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize large waste relative to capacity.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 40.0 * fit_ratio;

    // Penalize leaving dead space that nothing typical can use.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, strongly favor this bin.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual >= next_item_size {
            score -= 0.5 * next_item_size as f64;
        } else {
            score += 0.3 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Time horizon: later in the stream, consolidate more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - fit_ratio);

    // Global state coupling: when many bins are open with high mean residual,
    // discourage opening new bins; encourage filling existing ones.
    let residual_gap = mean_residual - post_residual as f64;
    score += 0.1 * residual_gap;
    score -= 0.05 * open_bins_count as f64 * fit_ratio;

    // New-bin candidate: penalize opening a fresh bin unless it is genuinely better
    // than a poor fit (large item with no good existing home).
    if bin_residual == bin_capacity {
        let poor_fit = fitting_bins_count == 0
            || (item_size > 50 && fit_ratio < 0.9 && mean_residual < item_size as f64);
        if poor_fit {
            score -= 15.0;
        } else {
            score += 35.0 + 0.2 * open_bins_count as f64;
        }
    }

    // Mild preference for bins with residual close to item size (exact-ish fits).
    let diff = (bin_residual as f64 - item_size as f64).abs();
    score += 0.05 * diff;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_post = post / cap;

    // Base: reward tight fits (small post_residual), with non-linear emphasis
    let mut score = post.powf(1.5);

    // Smooth polynomial coupling of post_residual with stream progress:
    // early on tolerate slack, late in the stream punish it harder
    score *= 1.0 + 0.8 * progress * norm_post.powi(2);

    // Penalize residuals that are too small to ever be useful (dead space),
    // scaled by how much of the stream remains
    let dead = if post > 0.0 && post < 10.0 { (10.0 - post) / 10.0 } else { 0.0 };
    score += dead * (1.0 - progress) * 15.0;

    // Lookahead: reward bins whose post residual can host the next item
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if post >= next {
            score -= (1.0 - post / cap) * 10.0;
        } else {
            score += (next - post).powf(1.2) * 0.3;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        // mild competition scaling
        score += 2.0 * (fitting_bins_count as f64 - 1.0).ln();
    }

    // Prefer bins already below mean residual (consolidating slack)
    score += ((mean_residual - post) * 0.15).max(-5.0);

    // New-bin candidate: make it attractive only when no open bin fits well
    if bin_residual == bin_capacity {
        // base cost of opening a bin, discounted early in the stream
        score = 45.0 - 25.0 * progress;
        if next_item_size > 0 && (next_item_size as f64) <= cap - item_size as f64 {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify by capacity fractions
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Class 0: perfect fit -> huge reward
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Dead-space class: residual too small to hold any plausible item (items >= ~1..100 unknown,
        // but tiny residuals are unusable). Penalize residuals in (0, 10] heavily.
        if post_residual <= 10 {
            score += 60.0;
        }
        // Harmonic bands: residual in (0, C/4), (C/4, C/2], (C/2, 3C/4], (3C/4, C)
        let band = (pr / (cap / 4.0)).floor() as i32; // 0..3
        match band {
            0 => score += 25.0,   // small leftover, likely dead space
            1 => score += 0.0,    // half-cap class, neutral
            2 => score -= 15.0,   // large residual, versatile bin
            _ => score -= 25.0,   // nearly-full-cap residual, very versatile
        }
    }

    // Integer-division threshold coupling with lookahead item (k=2)
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // this bin can still serve the next item: reward, scaled by tightness
            let tight = (post_residual - next_item_size) as f64;
            score -= 20.0 - (tight / cap) * 20.0;
        } else {
            // next item won't fit here; penalize proportionally to wasted potential
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
        // Harmonic match: next item exactly fills post residual
        if next_item_size == post_residual {
            score -= 40.0;
        }
        // Modulo-class harmony: next item leaves another exact-fit class
        if next_item_size > 0 && post_residual % next_item_size == 0 && post_residual > 0 {
            score -= 10.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: penalize opening a new bin unless residuals are all tight
    if bin_residual == bin_capacity {
        let avg_tightness = mean_residual / cap;
        // open new bin only if mean residual across open bins is small (< 15% of capacity)
        if open_bins_count > 0 && avg_tightness < 0.15 {
            score -= 30.0;
        } else {
            score += 120.0;
        }
    }

    // Stream progression: later in the stream, be more conservative with new bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += progress * 40.0;
    } else {
        score -= progress * 10.0;
    }

    // Mild preference to spread load when many bins open
    score += (open_bins_count as f64) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for the
    // minimum plausible item are "dead". Penalize them nonlinearly.
    let dead_threshold = 10u32.min(bin_capacity / 2);
    if post_residual > 0 && post_residual < dead_threshold {
        score += 40.0 + (dead_threshold - post_residual) as f64 * 3.0;
    }

    // Perfect fit is heavily rewarded.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward residuals that can still fit the lookahead item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else {
            score += 8.0; // lookahead item won't fit here -> dead space risk
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading;
    // with few open bins, opening a new bin is relatively cheap.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 / (1.0 + mean_residual / bin_capacity as f64);
    score += pressure * (0.5 + 0.5 * progress) * 2.0;

    // New-bin candidate (empty bin): default slightly unattractive so that
    // open bins with decent fit are preferred, but allow opening when all
    // open fits are poor (their scores get dead-space / pressure penalties).
    if bin_residual == bin_capacity {
        score += 15.0 + 3.0 * (open_bins_count as f64).ln().max(0.0);
        if fitting_bins_count == 0 {
            score -= 100.0; // no open bin fits: must open a new bin
        }
    }

    // Mild preference for tighter fits overall.
    score += (post_residual as f64 / bin_capacity as f64) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact/near match of post_residual to next item
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect match bonus: next item exactly fills the leftover space
        if post_residual == next_item_size {
            score -= 60.0;
        } else {
            score -= 25.0 * (1.0 - diff / (bin_capacity as f64)).max(0.0);
        }
        // Penalize leaving a gap that is too small for the next item (dead space)
        if post_residual > 0 && post_residual < next_item_size {
            score += 0.35 * (next_item_size - post_residual) as f64;
        }
    }

    // Penalize small unusable leftovers (dead space), scaled by how small
    if post_residual > 0 && post_residual < 10 {
        score += 15.0 * (10 - post_residual) as f64 / 10.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Compare against mean residual: prefer bins tighter than average
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Prefer fuller bins relative to capacity
    score += 0.3 * (post_residual as f64 / bin_capacity as f64) * 20.0;

    // Slight penalty for opening a new bin when many bins are open
    if bin_residual == bin_capacity {
        score += 8.0 + 0.5 * open_bins_count as f64;
    }

    // Mild time-based pressure: as stream progresses, be more conservative with new bins
    if bin_residual == bin_capacity && total_items > 0 {
        score += 10.0 * (step_index as f64 / total_items as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (low post residual), superlinear.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += fit_ratio * fit_ratio * 20.0;

    // Penalize opening a new bin when the item fits elsewhere.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 25.0;
        // But if this is the last fitting bin scenario and nothing fits well, allow new bin.
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
    }

    // Last-chance bonus: this is the only bin that can fit the item.
    if !is_new_bin && fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item exactly or well.
    if next_item_size > 0 && post_residual >= next_item_size {
        let next_waste = post_residual - next_item_size;
        let nw = next_waste as f64 / bin_capacity as f64;
        score -= (1.0 - nw) * 8.0;
        // Perfect pairing bonus.
        if next_waste == 0 {
            score -= 10.0;
        }
    } else if next_item_size > 0 {
        // Next item won't fit here: slight penalty for leaving a stranded residual.
        score += 4.0;
    }

    // Prefer bins below mean residual (consolidate waste into few bins).
    let residual = bin_residual as f64;
    if residual < mean_residual {
        score -= (mean_residual - residual) * 0.15;
    } else {
        score += (residual - mean_residual) * 0.10;
    }

    // Time horizon: as stream progresses, be more conservative about new bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if is_new_bin {
        score += progress * 15.0;
    }

    // Mild preference for reusing already-open bins as open bin count grows.
    if !is_new_bin {
        score -= (open_bins_count.min(20) as f64) * 0.3;
    }

    // Penalize very small dead space creation asymmetrically (unusable slivers).
    if post_residual > 0 && post_residual < 10 {
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Base: normalized post-residual with quadratic waste penalty
    let mut score = post / cap + (post / cap) * (post / cap);

    // Smooth non-linear coupling of post_residual with stream progress:
    // late in the stream, tight fits matter more (penalize large residuals quadratically)
    let coupling = (post / cap) * (1.0 - progress) * (1.0 - progress);
    score += 0.5 * coupling * (post / cap);

    // Reward tight fits (small post_residual) increasingly as stream progresses
    score -= (1.0 - post / cap) * (1.0 - post / cap) * (0.3 + 0.7 * progress);

    // Last-chance bin: strongly reward using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 1.5 + 2.0 * progress;
    }

    // Lookahead: if next item fits exactly into post_residual, reward heavily
    if next_item_size > 0 && next_item_size as f64 == post {
        score -= 2.0;
    } else if next_item_size > 0 && (next_item_size as u32) <= post_residual {
        // next item fits but not perfectly: mild reward scaled by fill ratio
        score -= 0.5 * (next_item_size as f64 / post.max(1.0));
    } else if next_item_size > 0 && (next_item_size as u32) > post_residual {
        // next item would not fit here: penalize leaving residual that strands it
        score += 0.3 * (1.0 - post / cap);
    }

    // Penalize bins far from mean residual (prefer balanced residual usage)
    let dev = (post - mean_residual).abs() / cap;
    score += 0.2 * dev * dev;

    // Slight preference for using existing bins over opening new ones
    if bin_residual == bin_capacity {
        score += 0.8 + 0.5 * progress;
    } else {
        score -= 0.1;
    }

    // Mild penalty when many bins are open (encourage consolidation)
    score += 0.01 * (open_bins_count as f64).ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: classify leftover space by
    // capacity fractions (eighths) and integer division thresholds.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Dead-space penalty: tiny leftovers (<= capacity/16) are nearly unusable.
    if post_residual <= bin_capacity / 16 {
        score += 40.0;
    } else if post_residual <= bin_capacity / 8 {
        score += 18.0;
    }

    // Perfect fit bonus via modulo classes on post_residual.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual % 10 == 0 {
        score -= 12.0;
    } else if post_residual % 5 == 0 {
        score -= 6.0;
    }

    // Harmonic divisibility: does next item divide into the post-residual exactly?
    if next_item_size > 0 && next_item_size <= post_residual {
        if post_residual % next_item_size == 0 {
            score -= 25.0;
        } else if next_item_size >= post_residual * 3 / 4 {
            score -= 15.0; // next item nearly fills the leftover
        } else if next_item_size <= post_residual / 2 {
            score -= 8.0;
        }
    } else if next_item_size > post_residual && next_item_size > 0 {
        // Next item cannot use this leftover: penalize large leftover mildly.
        score += post / cap * 10.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when open bins have poor fits.
    if bin_residual == bin_capacity {
        let pressure = mean_residual / cap;
        score = 55.0 - pressure * 20.0
            + (open_bins_count as f64) * 0.5
            - (item_size as f64) * 0.15;
        if fitting_bins_count == 0 {
            score -= 100.0; // nothing fits anywhere: must open
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 5.0; // big item following: fresh bin useful
        }
    }

    // Slight preference for tighter bins overall.
    score += (bin_residual as f64 / cap) * 3.0;

    // Late-stream consolidation: reuse bins more aggressively near the end.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (post_residual as f64 / cap) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals in [1, 9] are unusable for any item (min size 1),
    // but tiny gaps under ~10 are the classic "dead space" trap. Penalize hard.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Also penalize small-ish gaps that few future items can use.
    if post_residual >= 10 && post_residual < 20 {
        score += 15.0;
    }

    // Perfect fit is ideal.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead: if the next item fits exactly into the post_residual, reward strongly.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 35.0;
    }
    // If next item cannot fit into post_residual, this bin wastes space for the lookahead.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 10.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: discourage spreading across many bins; encourage consolidation
    // when many bins are already open.
    score += open_bins_count as f64 * 1.5;

    // Prefer bins tighter than the mean residual (better fill).
    score -= (mean_residual - bin_residual as f64) * 0.5;

    // New-bin candidate handling: opening a new bin wastes (capacity - item) immediately.
    // Only attractive when no good existing option exists; make it moderately costly,
    // but give it a bonus when item is large and residuals are small.
    if bin_residual == bin_capacity {
        score += 30.0;
        let progress = step_index as f64 / (total_items.max(1) as f64);
        if item_size > 70 && mean_residual < 15.0 {
            score -= 55.0 * (0.5 + 0.5 * progress);
        }
    }

    // Mild encouragement to fill large residual bins with large items early.
    if item_size >= 50 && bin_residual >= item_size && bin_residual < bin_capacity {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: smaller post_residual is already favored by the base term.

    // 2-step lookahead: if the next item fits exactly into post_residual, strongly reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 50.0;
        } else if post_residual >= next_item_size {
            // next item fits, but penalize leftover slack after both placements
            score -= 10.0 - 0.2 * ((post_residual - next_item_size) as f64);
        } else {
            // next item cannot use the leftover: penalize dead space
            let waste = (post_residual as f64) - (next_item_size as f64).min(post_residual as f64);
            score += 0.3 * waste;
            // extra penalty if next item would need a new bin anyway
            score += 5.0;
        }
    }

    // Relative to mean residual: prefer bins with residual below mean (well-packed)
    let mean_res = mean_residual;
    if (bin_residual as f64) < mean_res {
        score -= 2.0;
    } else {
        score += 0.05 * ((bin_residual as f64) - mean_res);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Penalize opening a new bin unless the fit is poor
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive if no open bin fits well
        score += 20.0;
        if fitting_bins_count == 0 {
            score -= 30.0;
        } else if post_residual > 40 {
            score -= 5.0;
        }
    }

    // Late in the stream: prefer closing out bins (reduce open bin count)
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress > 0.8 && post_residual < 10 {
        score -= 8.0;
    }

    // Slight penalty for leaving very small unusable slivers
    if post_residual > 0 && post_residual < 5 {
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let is_new_bin = bin_residual == bin_capacity;

    // Reward tight fits strongly
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize large dead space, more so early when bins can still be filled
    if post_residual > 0 && post_residual < 10 {
        score -= 8.0; // nearly perfect fill
    }

    // Lookahead: bonus if next item fits the post residual
    if next_item_size > 0 {
        if (post_residual as u32) >= next_item_size {
            score -= 12.0;
            // extra bonus if it fits snugly
            let gap = post_residual as i64 - next_item_size as i64;
            if gap < 10 { score -= 10.0; }
        } else {
            score += 6.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 15.0;
    }

    // New bin candidate handling
    if is_new_bin {
        // Prefer new bin late in stream or when few fitting bins / poor alternatives
        score += 10.0 + 20.0 * (1.0 - t);
        if fitting_bins_count > 1 {
            score += 25.0; // discourage wasting a fresh bin when alternatives exist
        }
        if next_item_size > 0 && post_residual as u32 >= next_item_size {
            score -= 5.0;
        }
    }

    // Global state coupling: prefer bins with residual near mean (balanced packing)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Slight preference for more-filled bins as stream progresses
    score -= t * (bin_capacity - bin_residual) as f64 * 0.05;

    // Mild penalty for many open bins to encourage consolidation early
    score += 0.1 * open_bins_count as f64 * (1.0 - t);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr;
    // Non-linear coupling: residual value decays with stream progress
    score -= pr * (0.5 + 0.5 * progress) * (1.0 - norm_pr * norm_pr);
    // Penalize large dead space quadratically, amplified late in stream
    score += 8.0 * norm_pr * norm_pr * (0.3 + 0.7 * progress) * cap;
    // Reward tight fits
    let tight = 1.0 - (pr / cap);
    score -= 20.0 * tight * tight * tight;
    // Last-chance bonus
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }
    // New-bin candidate: mildly discourage unless current residuals are large
    if bin_residual == bin_capacity {
        score += 10.0 + 0.5 * (mean_residual / cap) * (1.0 - progress);
        score -= 5.0 * progress;
    }
    // Lookahead synergy: if next item fits post-residual, reward
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 6.0 * (1.0 - (next_item_size as f64 / pr.max(1.0)).powi(2));
    } else if next_item_size > 0 {
        score += 4.0;
    }
    // Crowding penalty: many open bins with low mean residual
    score += 0.3 * open_bins_count as f64 * (1.0 - mean_residual / cap).max(0.0);
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fits are ideal.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of the post-residual: small residues are dead space.
    let c = bin_capacity as f64;
    let pr = post_residual as f64;

    // Penalize residues in "dead" bands: 1..=9 and 41..=60 style gaps.
    if post_residual > 0 && post_residual <= 9 {
        score += 30.0;
    }
    if post_residual >= 41 && post_residual <= 60 {
        score += 12.0;
    }

    // Modulo-class logic: residues that are multiples of common item sizes
    // (10, 20, 25, 50) are more likely to be fillable later.
    let fillable_classes: [u32; 4] = [10, 20, 25, 50];
    for &k in &fillable_classes {
        if post_residual % k == 0 && post_residual > 0 {
            score -= 8.0;
        }
    }

    // Lookahead: if next item fits the post-residual exactly, reward strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 400.0;
        } else if next_item_size <= post_residual {
            // Reward proportional closeness of the fit.
            let tightness = next_item_size as f64 / post_residual as f64;
            score -= 50.0 * tightness;
        } else {
            // Next item cannot use the residue: mild penalty scaled by waste.
            score += (next_item_size as f64 - pr) * 0.2;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer it
    // over opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: penalize opening a new bin when decent fits exist,
    // but allow it when the current bin would leave a large awkward residue.
    if bin_residual == bin_capacity {
        // Baseline cost of a fresh bin.
        score += 40.0;
        // If many bins already fit the item, opening a new one is wasteful.
        if fitting_bins_count > 0 {
            score += 25.0 * (fitting_bins_count as f64).min(5.0);
        }
        // Large items (>= half capacity) pack well into fresh bins.
        if item_size * 2 >= bin_capacity {
            score -= 30.0;
        }
        // Early stream: opening bins is cheaper (more future items to fill them).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 20.0 * (1.0 - progress);
    }

    // Prefer bins with residuals below the mean (compact the tight bins first).
    score -= (mean_residual - pr) * 0.15;

    // Small global tie-breaker favoring tighter fits as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += pr * 0.05 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += (10.0 - post_residual as f64) * 12.0;
    }
    // Perfect fit gets a large reward.
    if post_residual == 0 {
        score -= 60.0;
    }
    // Reward tight fits relative to bin residual (high fill ratio).
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 25.0;

    // Pressure from number of open bins: discourage spreading when many bins open.
    score += open_bins_count as f64 * 1.5;

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if next item fits exactly in the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap == 0 {
            score -= 35.0;
        } else if gap < 10 {
            score -= 10.0;
        }
    }
    // Penalize if next item would be blocked by tiny dead space left behind.
    if next_item_size > post_residual && post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // New-bin candidate: only attractive when no open bin offers a decent fit
    // or open-bin pressure is high; otherwise keep it mildly unattractive.
    if bin_residual == bin_capacity {
        let decent_fit_exists = mean_residual >= item_size as f64 * 1.1;
        if decent_fit_exists && fitting_bins_count > 0 {
            score += 55.0 + open_bins_count as f64 * -0.8;
        } else {
            score -= 5.0;
        }
        // Late in the stream, prefer consolidating into existing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
    }

    // Slight nudge toward bins below the mean residual (balancing residuals).
    if bin_residual as f64 > mean_residual {
        score += 3.0;
    } else {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward perfect or near-perfect fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches next item size.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual as f64 == nxt {
            score -= 500.0;
        } else {
            let gap = (post_residual as f64 - nxt).abs();
            if post_residual as u32 >= next_item_size {
                // next item can still fit here: reward closeness
                score -= 150.0 * (1.0 - gap / bin_capacity as f64);
            } else {
                // dead space relative to the next item
                score += 50.0 + gap * 0.5;
            }
        }
    } else {
        // last item: just minimize post residual
        score += 0.0;
    }

    // Compare against mean residual: prefer bins tighter than average.
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate: penalize opening a new bin unless item is large
    // and no tight fit is available (encourage consolidation).
    if bin_residual == bin_capacity {
        score += 80.0;
        if item_size >= bin_capacity / 2 {
            score -= 60.0;
        }
        if next_item_size > 0 && (bin_capacity as f64 - next_item_size as f64) < item_size as f64 {
            score -= 20.0;
        }
    }

    // Mild penalty for many open bins: encourage filling existing ones.
    score += open_bins_count as f64 * 0.05;

    // Slight preference for tighter bins as the stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (bin_residual as f64 / bin_capacity as f64) * 10.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize large post_residual relative to capacity.
    score += 0.6 * (post_residual as f64 / bin_capacity as f64) * (post_residual as f64);

    // Penalize dead space that is too small for typical items (unusable gap).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Lookahead: if next item fits into the post_residual, reward this placement.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 0.5 * next_item_size as f64;
        } else {
            // Next item won't fit here; slight penalty proportional to wasted pairing.
            score += 0.15 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // Global state coupling: many open bins with high mean residual -> prefer filling existing bins.
    let openness = open_bins_count as f64;
    score -= 0.3 * mean_residual / (openness + 1.0).sqrt();

    // Time horizon: early in stream, be more willing to open new bins (higher score on new bins
    // is avoided by subtracting here); late in stream, consolidate.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate score.
        score += 20.0 * progress + 0.5 * openness;
        if next_item_size > 0 && bin_capacity >= next_item_size {
            score -= 5.0;
        }
    } else {
        score -= 10.0 * (1.0 - progress);
    }

    // Prefer bins whose residual is close to item_size (perfect fill reward).
    let tightness = 1.0 - (post_residual as f64 / bin_residual.max(1) as f64);
    score -= 8.0 * tightness * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: quadratic penalty on wasted residual (dead space).
    let mut score = norm_pr * norm_pr * 100.0 + norm_pr * 10.0;

    // Perfect fit reward: subtract aggressively as post_residual -> 0.
    score -= (1.0 - norm_pr).powi(3) * 30.0;

    // Stream-progress coupling: late in the stream, waste is costlier;
    // early on, spreading load across bins is cheaper.
    let pressure = progress.powf(1.5);
    score += norm_pr * pressure * 40.0;
    score -= (1.0 - progress) * pr * 0.05;

    // Mean-residual coupling: if this bin's residual is far below the mean
    // residual of open bins, it is a poor-fit bin; penalize.
    let bin_res = bin_residual as f64;
    let dev = (bin_res - mean_residual) / cap;
    score += (dev * dev) * 15.0;

    // Last-chance bin: strongly favor using the only bin that fits,
    // otherwise a new bin gets opened.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Lookahead coupling: reward if the next item fits exactly into
    // the post residual; penalize if next item would be stranded.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let nxt_norm = nxt / cap;
            score -= (1.0 - ((pr - nxt) / cap)) * 20.0 * (1.0 - nxt_norm);
        } else {
            // Next item won't fit here: leftover residual risk grows.
            score += norm_pr * 12.0;
        }
    }

    // New-bin candidate: empty bin should only win when fits are bad.
    if bin_residual == bin_capacity {
        // Base cost of opening a bin, eased early in the stream.
        score = 60.0 - progress * 25.0 + norm_pr * 5.0;
        if fitting_bins_count <= 2 {
            // Few alternatives: opening is more acceptable.
            score -= 15.0;
        }
    }

    // Mild penalty for proliferating open bins late in stream.
    score += (open_bins_count as f64).ln() * progress * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residuals that are "usable slots"
    // for common item sizes (multiples of 10 and small remainders).
    let pr = post_residual as u32;
    if pr == 0 {
        score -= 25.0; // perfect fit is ideal
    } else if pr < 10 {
        // dead space below smallest item: heavily penalize
        score += 30.0;
    } else {
        // residual divisible into harmonic classes by modulo 10
        let m = pr % 10;
        score -= match m {
            0 => 18.0,   // aligns with class-10 items
            5 => 10.0,   // half-class still useful
            2 | 4 | 6 | 8 => 4.0,
            _ => 0.0,
        };
        // integer division thresholds: bigger usable slots preferred
        let slots = pr / 20;
        score -= slots as f64 * 6.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 22.0;
        } else if next_item_size <= pr {
            // fits but not perfectly: partial reward scaled by fill ratio
            let fill = next_item_size as f64 / pr.max(1) as f64;
            score -= 8.0 * fill;
        } else {
            score += 6.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate handling: only prefer opening a new bin when the
    // current item is large relative to residual (poor fit) late in stream.
    if bin_residual == bin_capacity {
        let tight = item_size as f64 / cap;
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        // empty bin baseline: prefer it only if fit is bad
        score = 60.0 - 40.0 * tight - 10.0 * progress;
        if next_item_size > 0 && next_item_size >= bin_capacity {
            score -= 20.0;
        }
    }

    // Mild pressure to consolidate when many bins are open.
    score += open_bins_count as f64 * 0.05;
    // Slight preference for bins below mean residual (keeps big holes free).
    if (bin_residual as f64) < mean_residual {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that cannot hold the smallest
    // plausible item are pure waste — penalize heavily.
    let dead_threshold = 10u32.min(bin_capacity);
    if post_residual > 0 && post_residual < dead_threshold {
        score += 40.0 + (dead_threshold - post_residual) as f64;
    }

    // Reward tight fits (small post_residual) with a non-linear bonus.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 25.0 * tightness * tightness;

    // Dead space relative to the lookahead item: if the next item could have
    // used this residual but won't after placement, penalize.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0;
    }

    // Open-bin pressure: discourage spreading across many bins unless the fit
    // is genuinely good.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 0.6 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Penalize bins whose residual deviates badly from the mean residual
    // (keeps bin states homogeneous, easier to close out).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        score += 12.0 + 2.0 * open_bins_count as f64;
        if fitting_bins_count == 0 {
            score -= 50.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward exact or near-exact fits.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 300.0;
    } else if post_residual <= 15 {
        score -= 100.0;
    }

    // Aggressive 2-step lookahead: if next item fits exactly in post_residual,
    // this is a perfect chain — heavily reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 900.0;
        } else if post_residual > next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            // Reward chains where next item leaves little dead space.
            if slack <= 5.0 {
                score -= 400.0;
            } else if slack <= 15.0 {
                score -= 150.0;
            } else {
                // Penalize leaving a gap much larger than next item (dead space).
                score += slack * 0.5;
            }
        } else {
            // Next item cannot fit in the leftover; leftover becomes dead space
            // unless small. Penalize proportionally.
            let gap = (post_residual as f64) / bin_capacity as f64;
            score += gap * 200.0;
        }
    }

    // Relative to mean residual: prefer bins that are already "tight"
    // (below-mean residual) to consolidate packing.
    if (bin_residual as f64) < mean_residual {
        score -= 30.0;
    } else {
        score += (bin_residual as f64 - mean_residual) * 0.3;
    }

    // Last-chance bin: if this is the only bin that fits, avoid forcing
    // a new bin unless the fit is terrible.
    if fitting_bins_count == 1 {
        score -= 80.0;
    }

    // New-bin candidate handling: opening a new bin should only win when
    // no open bin offers a decent fit. Penalize the fresh bin moderately,
    // but less when many bins are open (fragmentation) or stream is early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let mut new_bin_score = 250.0;
        // Later in the stream, be more willing to open new bins to keep options.
        new_bin_score -= progress * 100.0;
        // Many open bins with high mean residual => fragmentation; new bin fine.
        if open_bins_count > 3 && mean_residual > 30.0 {
            new_bin_score -= 60.0;
        }
        score = score.min(new_bin_score);
        score = new_bin_score.max(score.min(new_bin_score));
        score = new_bin_score;
    }

    // Mild tie-break: prefer bins with less residual overall.
    score += bin_residual as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item nearly fills the residual.
    let tight = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 60.0 * tight * tight;

    // Penalize dead space that no future item (sizes 1..=100) can realistically use.
    if post_residual > 0 {
        let dead = if post_residual < 10 { post_residual as f64 } else { 0.0 };
        score += 8.0 * dead;
    }

    // Lookahead coupling: if the next item fits into the post-residual, reward this placement.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 25.0;
        } else {
            // Penalty scaled by how much of next item would be wasted.
            let miss = (next_item_size as f64 - post_residual as f64).min(50.0);
            score += 0.3 * miss;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: penalize opening a new bin mildly, more so early in the
    // stream and when many bins are already open with slack.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 30.0 + 40.0 * (1.0 - progress) + 2.0 * open_bins_count as f64;
        // Allow opening a new bin late in the stream when existing residuals are small.
        if mean_residual < item_size as f64 * 0.5 {
            score -= 25.0;
        }
    }

    // Prefer bins whose residual is close to the mean (balance load), avoiding fragmentation.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Prefer leaving residuals that are either 0 or large enough to be useful.
    if post_residual > 0 && post_residual < 50 {
        score += 0.2 * (50 - post_residual) as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let fill = 1.0 - norm_pr;
    let tight = (item_size as f64 / cap) * fill;

    // Smooth polynomial coupling: tight fits rewarded more as stream progresses
    score -= 40.0 * tight * (0.5 + progress);

    // Penalize dead space quadratically, stronger late in stream
    score += 60.0 * norm_pr * norm_pr * (0.3 + progress);

    // Interact with mean residual: prefer bins near the mean (balance)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 15.0 * dev * dev;

    // Lookahead coupling: if next item fits the post residual, reward
    if next_item_size > 0 {
        let gap = pr - next_item_size as f64;
        if gap >= 0.0 {
            score -= 20.0 * (1.0 - gap / cap) * (0.5 + progress);
        } else {
            score += 8.0 * (-gap / cap);
        }
    }

    // Last-chance bin: strong reward to avoid opening new bins
    if fitting_bins_count == 1 {
        score -= 35.0 * (0.4 + progress);
    }

    // Mild penalty for spreading across too many open bins
    score += 1.5 * (open_bins_count as f64).ln();

    // Smooth progress-dependent scaling of base residual
    score *= 1.0 + 0.3 * progress * (1.0 - progress) * 4.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins partitioned by residual size classes.
    let capacity_f = bin_capacity as f64;
    let post_f = post_residual as f64;
    let frac = post_f / capacity_f; // residual fraction

    // Class index via integer division thresholds (harmonic classes: 1/2, 1/3, 1/4, ...)
    let class = if post_residual == 0 { 0u32 }
        else if post_residual >= bin_capacity / 2 { 1 }
        else if post_residual >= bin_capacity / 3 { 2 }
        else if post_residual >= bin_capacity / 4 { 3 }
        else if post_residual >= bin_capacity / 8 { 4 }
        else { 5 };

    // Reward small residuals, especially exact / near-zero fits.
    match class {
        0 => score -= 50.0,                    // perfect fit
        1 => score -= 25.0,                    // leaves a half-slot
        2 => score -= 12.0,                    // leaves a third-slot
        3 => score -= 6.0,
        4 => score -= 2.0,
        _ => score += 8.0,                     // large dead space: penalize
    }

    // Modulo arithmetic: does post_residual pair with the lookahead item?
    if next_item_size > 0 && next_item_size <= post_residual {
        // Lookahead fits exactly into the leftover: strong reward.
        if post_residual == next_item_size {
            score -= 40.0;
        } else {
            let gap = post_residual - next_item_size;
            // Harmonic coupling: gap small relative to next item is good.
            let ratio = gap as f64 / next_item_size as f64;
            score -= 20.0 * (1.0 - ratio.min(1.0));
            // Bonus if next item would fill a harmonic class slot (half/third/quarter).
            let n = next_item_size;
            if post_residual % n == 0 {
                score -= 10.0;
            }
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        // Lookahead cannot use this leftover: penalize dead space proportionally.
        score += 0.15 * post_f * (1.0 - step_index as f64 / total_items.max(1) as f64);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Many open bins with high mean residual: discourage spreading waste.
    if open_bins_count > 2 {
        let dev = mean_residual - post_f;
        if dev > 0.0 {
            score -= 0.05 * dev; // prefer bins tighter than the mean
        } else {
            score += 0.05 * (-dev);
        }
    }

    // New-bin candidate: only attractive if no decent fit exists; make it costly otherwise.
    if bin_residual == bin_capacity {
        score += 20.0 + 0.1 * (open_bins_count as f64);
    }

    // Slight late-stream tightening: waste matters more near the end.
    score += 0.02 * post_f * (step_index as f64 / total_items.max(1) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (1.0 + (10 - post_residual) as f64 / 10.0);
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 40.0;
    }

    // Reward tight fits relative to bin capacity.
    let tightness = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= 10.0 * tightness;

    // If next item can use the post_residual, reward; otherwise penalize.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 8.0 * (next_item_size as f64 / post_residual.max(1) as f64);
        } else if post_residual > 0 {
            score += 12.0 * (1.0 - post_residual as f64 / next_item_size as f64);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: discourage spreading across many bins when fit is loose.
    score += (open_bins_count as f64).sqrt() * (post_residual as f64 / bin_capacity as f64) * 6.0;

    // New-bin candidate: only attractive when no open bin gives a decent fit.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 100.0;
        } else {
            // Prefer existing bins unless all fits are very poor (large post_residual).
            let best_possible = if post_residual == 0 { 0.0 } else { post_residual as f64 };
            if best_possible > 30.0 {
                score -= 5.0 + best_possible / 10.0;
            } else {
                score += 30.0;
            }
        }
    }

    // Mild stream-progression tiebreaker: later in stream, prefer consolidating.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 2.0 * progress * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-exact fits (small dead space is disproportionately bad).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 60.0;
    } else if post_residual <= 15 {
        score -= 20.0;
    }

    // 2-step lookahead: if the next item fits exactly into the post residual,
    // this placement sets up a perfect follow-up.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 400.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 150.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit here afterward: penalize leaving a large
            // unusable-looking gap relative to next item.
            let gap = (next_item_size - post_residual) as f64;
            score += 0.3 * gap.min(50.0);
        }
    }

    // Relative-to-mean residual shaping: prefer bins whose post residual
    // sits near the mean residual (keeps bin portfolio balanced).
    let pr = post_residual as f64;
    let dev = (pr - mean_residual).abs();
    score += 0.25 * dev;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // Penalize opening a new bin when existing bins offer decent fits.
    if bin_residual == bin_capacity {
        let base = 40.0 + 0.5 * item_size as f64;
        score += base;
        if next_item_size > 0 && next_item_size <= item_size {
            score += 20.0; // future small items can fill leftovers elsewhere
        }
        if open_bins_count == 0 {
            score -= 200.0; // must open a bin
        }
    }

    // Late in the stream, tighten packing: discourage loose fits.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base fit quality: strongly reward tight fits (small post_residual).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 2.5 * tightness * tightness * post_residual as f64;

    // Penalize dead space: residuals too small for any plausible future item.
    if post_residual > 0 {
        let dead = if post_residual < 10 { 1.0 } else { (post_residual as f64 - 10.0).min(40.0) / 40.0 };
        score += 3.0 * dead * (1.0 - tightness);
    }

    // Lookahead: reward bins whose leftover can host the next item exactly-ish.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 6.0 / (1.0 + slack);
        } else {
            score += 1.5;
        }
    } else {
        // Last item: pure tightness matters.
        score -= 3.0 * tightness;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate handling: only attractive when existing fits are poor
    // or the item is large relative to typical residuals.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let pressure = (open_bins_count as f64).ln().max(0.5);
        let fit_poor = if fitting_bins_count <= 1 { 1.0 } else { 0.0 };
        let big_item = item_size as f64 / bin_capacity as f64;
        let bonus = fit_poor * 10.0 + big_item * 4.0 * (1.0 - progress);
        score = score - bonus + 2.0 * pressure + 0.5 * mean_residual / 10.0;
    }

    // Mild preference to fill nearly-full bins as stream progresses.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 1.0 * tightness;

    // Tie-break with slight noise-free determinism via bin residual hash.
    score += ((bin_residual as f64 * 0.017) % 0.1) - 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Tight-fit reward: strongly favor small post_residual, amplified later in stream
    let tightness = 1.0 - (pr / cap);
    score -= tightness * tightness * (30.0 + 40.0 * progress);

    // Penalize post_residual that is too small to be useful (dead space)
    let min_useful = 10.0;
    if pr < min_useful && pr > 0.0 {
        score += (min_useful - pr) * 3.0;
    }
    if pr == 0.0 {
        score -= 25.0; // perfect closure bonus
    }

    // Coupling with mean residual: prefer bins whose residual deviates from mean toward closure
    let dev = pr - mean_residual;
    score += 0.15 * dev * dev / cap;

    // Lookahead: reward if next item fits post_residual, penalize near-miss
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            score -= (1.0 - (nx / pr)) * 12.0;
        } else {
            score += (nx - pr) * 0.4;
        }
    }

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 {
        score -= 35.0;
    }

    // New-bin candidate: make it attractive only when open bins fit poorly
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count > 0 { fitting_bins_count as f64 } else { 1.0 };
        score = 20.0 + 10.0 * pressure - 15.0 * progress;
        if next_item_size > 0 && (next_item_size as f64) <= cap - item_size as f64 {
            score -= 5.0;
        }
    }

    // Mild penalty for many open bins to encourage consolidation
    score += 0.5 * open_bins_count as f64 * (pr / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: exact-fill and tiny dead space are gold.
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fill
    } else if pr <= 5 {
        score -= 25.0;
    } else if pr <= 10 {
        score -= 10.0;
    } else if pr <= 20 {
        score += 5.0;
    } else {
        score += 12.0;
    }

    // Modulo-10 harmonic class: residuals that are multiples of 10 pair well
    // with the common size grid (sizes often multiples of 5 or 10).
    if pr % 10 == 0 {
        score -= 8.0;
    } else if pr % 5 == 0 {
        score -= 4.0;
    } else {
        score += 3.0;
    }

    // Lookahead coupling: does the next item fit the post-residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // Chain-friendly: next item can follow here.
            let slack = (pr - next_item_size) as f64;
            score -= 14.0 - 0.05 * slack;
            if (pr % 10 == 0 && next_item_size % 10 == 0)
                || (pr % 5 == 0 && next_item_size % 5 == 0) {
                score -= 6.0; // harmonic grid alignment
            }
        } else if next_item_size <= bin_residual && next_item_size > pr {
            // Next item fits this bin only if we DON'T place current item here.
            score += 18.0;
        }
        // If next item fits nowhere after placement, mild penalty.
        if next_item_size > pr && next_item_size > bin_residual {
            score += 4.0;
        }
    } else {
        // Last item: greedily prefer tightest fit.
        score -= 20.0;
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0).min(4.0);
    }

    // New-bin candidate handling: only attractive when current item is large
    // (poor fit anywhere) or open bins are nearly saturated.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let fill_frac = item_size as f64 / cap;
        score = 55.0 - 30.0 * fill_frac; // base reluctance
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a bin
        }
        if item_size >= 60 {
            score -= 20.0; // large items deserve fresh bins
        }
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 15.0; // can pair next item into fresh bin
        }
        if open_bins_count > 0 && mean_residual > item_size as f64 {
            score += 10.0; // an open bin could still host it
        }
        // Harmonic class: fresh bin post-residual multiple of 10 is promising.
        if pr % 10 == 0 {
            score -= 5.0;
        }
    } else {
        // Prefer bins whose residual is closest to item size (tight fit).
        let tightness = (bin_residual - item_size) as f64 / cap;
        score += 20.0 * tightness;
    }

    // Stream progression: early on, be conservative with dead space;
    // later, allow slightly looser packing to close bins out.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 - 0.15 * progress;

    // Mean-residual coupling: penalize widening residual dispersion.
    score += 0.08 * (post_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
