    } else if post_residual < 20 {
        score += 15.0;
    }

    // Reward very tight fits (near-perfect packing).
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead coupling: penalize leaving a gap that the next item cannot use.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 25.0;
    }
    // Reward gaps that exactly accommodate the next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 20.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; prefer filling.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (0.5 + progress);

    // New-bin candidate: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        score = (bin_capacity as f64) + open_bins_count as f64 * 10.0;
        if fitting_bins_count == 0 {
            score -= 1000.0; // must open a new bin
        }
    } else if fitting_bins_count > 0 {
        // Slight preference for bins tighter than average.
        score -= (mean_residual - bin_residual as f64) * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post_residual relative to capacity).
    let tightness = post_residual as f64 / bin_capacity as f64;
    score -= 40.0 * (1.0 - tightness).powf(6.0);

    // Perfect fit: overwhelming reward.
    if post_residual == 0 {
        score -= 500.0;
    }

    // Aggressive 2-step lookahead: reward bins whose residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Chain fit: the leftover exactly (or near-exactly) accommodates the next item.
            let chain_waste = (post_residual - next_item_size) as f64;
            score -= 60.0 - 0.5 * chain_waste;
            if post_residual == next_item_size {
                score -= 120.0; // perfect 2-item chain fill
            }
        } else {
            // Penalize leaving dead space the next item cannot use.
            score += 0.4 * post_residual as f64;
        }
    }

    // Relative-to-mean coupling: prefer bins with residual below mean (consolidating fuller bins),
    // penalize dipping into bins with above-average residual.
    score += 0.3 * (mean_residual - bin_residual as f64);

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: only attractive when the item is large relative to capacity
    // or no good chaining exists; otherwise discourage bin proliferation.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let load = item_size as f64 / bin_capacity as f64;
        let mut new_bin_bonus = -30.0 * load; // base: discourage new bins
        if next_item_size > 0 && post_residual >= next_item_size {
            new_bin_bonus += 50.0; // new bin enables a clean 2-item chain
        }
        if open_bins_count == 0 {
            new_bin_bonus -= 200.0;
        }
        // Later in the stream, slightly prefer reusing open bins.
        new_bin_bonus += 20.0 * progress;
        score += new_bin_bonus;
    }

    // Mild penalty for wasting space in bins that are already mostly empty.
    if bin_residual as f64 > mean_residual + 0.5 * bin_capacity as f64 {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post_residual relative to capacity)
    let tightness = post_residual as f64 / bin_capacity as f64;
    score -= 40.0 * (1.0 - tightness) * (1.0 - tightness);

    // Penalize leaving dead space that no typical item can use
    if post_residual > 0 && post_residual < 10 {
        score -= 15.0; // small unusable sliver: actually good, item consumed the bin fully
    }
    if post_residual >= 10 && post_residual < 20 {
        score += 6.0; // awkward gap zone
    }

    // Lookahead: reward if the next item fits into post_residual
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 18.0;
            // bonus scaled by how well next item fits remaining space
            let slack_after_next = post_residual - next_item_size;
            score -= 10.0 * (1.0 - slack_after_next as f64 / bin_capacity as f64);
        } else {
            score += 8.0;
            // if next item would fit this bin now but not after placement, penalize
            if next_item_size <= bin_residual {
                score += 10.0;
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Many open bins: prefer consolidation into existing bins
    let open_frac = open_bins_count as f64 / (total_items.max(1) as f64).sqrt().max(1.0);
    if bin_residual < bin_capacity {
        score -= 5.0 * open_frac.min(3.0);
    }

    // Mean residual coupling: prefer bins below mean residual (tighter bins)
    score += 0.15 * (mean_residual - bin_residual as f64);

    // New-bin candidate handling: penalize opening a new bin unless it's clearly better
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin
        score += 45.0;
        // More attractive late in the stream? No — keep constant, but reduce if
        // existing bins are very fragmented (high mean residual means poor fits around)
        if mean_residual < item_size as f64 {
            score -= 25.0; // existing bins are too full anyway
        }
        // If no open bin fits well, opening new is fine
        if fitting_bins_count == 0 {
            score -= 50.0;
        }
        // Large items early: opening fresh bins is often good
        let progress = step_index as f64 / (total_items.max(1) as f64);
        if item_size > 60 && progress < 0.5 {
            score -= 10.0;
        }
        // Next item much smaller: fresh bin keeps space for it
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 12.0;
        }
    }

    // Mild time-horizon effect: later in stream, be greedier about tight fits
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * (1.0 - tightness);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr_norm = pr / cap;
    let base = pr * pr / cap;
    let mut score = base
        + 12.0 * pr_norm * pr_norm * (1.0 - pr_norm)
        + 30.0 * progress * (pr_norm - 0.5) * (pr_norm - 0.5);
    if pr == 0.0 { score -= 50.0; }
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 15.0 * (next_item_size as f64 / cap);
    } else if next_item_size > 0 {
        score += 8.0 * (1.0 - (next_item_size as f64 - pr) / cap);
    }
    if fitting_bins_count == 1 { score -= 25.0; }
    score += 0.5 * (mean_residual - pr) * progress;
    if bin_residual == bin_capacity { score += 40.0 + 20.0 * progress; }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
