    // Fraction of capacity remaining: prefer bins with structured fractions
    let frac = pr / cap;
    if (frac - (frac.round())).abs() < 0.05 {
        score -= 12.0; // residual near a clean fraction of capacity
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 90.0;
    }

    // Many open bins: prefer tightening existing bins over spreading
    if open_bins_count > 4 {
        score -= 0.5 * (open_bins_count as f64).ln() * (item_size as f64 / cap);
    }

    // Early stream: keep bins flexible (avoid near-full early), late stream: pack tight
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - progress) * frac * 20.0;
    score -= progress * pr * 0.3;

    // Prefer bins whose residual is far from mean residual (odd bins get filled)
    if pr > mean_residual {
        score -= 8.0;
    } else {
        score += 4.0;
    }

    // New-bin candidate: only attractive when nothing fits well
    if bin_residual == bin_capacity {
        let desperation = if next_item_size > 0 && next_item_size > post_residual { 1.0 } else { 0.0 };
        score = cap * 1.5 - 30.0 * desperation - 20.0 * progress;
        if fitting_bins_count == 0 {
            score -= 500.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead space penalty: residuals too small to hold the smallest item are useless.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual < 20 {
        score += 12.0;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Reward bins that can also host the lookahead item (k=2 chaining).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 6.0; // dead space relative to the known future item
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: make it attractive only when open bins are crowded or fit is poor.
    if bin_residual == bin_capacity {
        let pressure = (open_bins_count as f64) * 1.5 + mean_residual * 0.3;
        let fit_quality = (item_size as f64) / (bin_capacity as f64);
        score = bin_capacity as f64 - pressure - fit_quality * 20.0;
        if fitting_bins_count <= 1 {
            score -= 25.0; // opening fresh is better than forcing a bad fit
        }
    }

    // Mild open-bin pressure: prefer compacting into fewer bins early on.
    score += (open_bins_count as f64) * 0.05;

    // Late-stream consolidation: waste tolerance decreases as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += post_residual as f64 * progress * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual), with mild nonlinearity.
    let tightness = (post_residual as f64) / (bin_capacity as f64);
    score += 8.0 * tightness * tightness;

    // --- 2-step lookahead: exact match of next item into the residual ---
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let post = post_residual as f64;
        if post == nxt {
            // Perfect chaining: this bin will be exactly filled by the next item.
            score -= 60.0;
        } else if post >= nxt {
            // Next item fits: reward proportionally to how well it fills.
            let fill_after_next = (post - nxt) / (bin_capacity as f64);
            score -= 25.0 * (1.0 - fill_after_next);
        } else {
            // Next item does NOT fit: penalize dead space that blocks it.
            let gap = nxt - post;
            score += 6.0 + 0.35 * gap;
        }
        // Coupling with mean residual: bins whose residual is far below mean
        // are "odd bins"; matching the next item there is extra valuable.
        let dev = (post - mean_residual).abs();
        score -= 3.0 * (1.0 / (1.0 + dev / 20.0)) * (post >= nxt as u32 as f64) as f64;
    }

    // --- Last-chance logic: this is the only bin that fits the item ---
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Prefer opening a new bin only when open bins fit poorly.
        // If some open bin has a near-perfect fit, discourage new bin.
        let poor_fits = (post_residual as f64) / (bin_capacity as f64);
        // Slight default penalty so we only open when lookahead rewards it.
        score += 12.0;
        // If the next item is large relative to a fresh bin, opening is fine.
        if next_item_size > 0 && (next_item_size as f64) > 0.7 * (bin_capacity as f64) {
            score -= 4.0;
        }
        // Early in the stream, opening bins is cheap; later, consolidate.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 10.0 * progress;
        let _ = poor_fits;
    }

    // --- Penalize creating very small unusable residuals ---
    if post_residual > 0 && post_residual < 10 {
        score += 18.0;
    }

    // --- Many open bins: favor consolidation into existing bins ---
    if open_bins_count > 3 {
        score -= 2.0 * (open_bins_count as f64).ln();
    }

    // Small deterministic tie-breaker scaled by residual.
    score += (post_residual as f64) * 0.001;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for near-perfect fits.
    let tightness = (post_residual as f64) / (bin_capacity as f64);
    score += 30.0 * tightness * tightness;

    // Last-chance bin: heavily favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize unless no open bin fits well.
    if bin_residual == bin_capacity {
        let mut base_penalty = 25.0;
        if fitting_bins_count == 0 {
            base_penalty = -50.0; // forced open
        } else if post_residual as f64 > mean_residual {
            base_penalty += 10.0;
        }
        // Later in the stream, consolidation matters more; opening new bins is costlier.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        base_penalty += 20.0 * progress;
        // Many open bins: prefer packing into existing ones.
        base_penalty += 2.0 * (open_bins_count as f64).ln().max(0.0);
        score += base_penalty;
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Good: leaves room for the next item, but only mildly (avoid hoarding large gaps).
            score -= 6.0;
            // Extra reward if next item fits almost exactly.
            let gap = post_residual - next_item_size;
            if gap <= 5 {
                score -= 8.0;
            }
        } else if post_residual > 0 {
            // Penalize leaving dead space too small for typical items.
            let dead = post_residual as f64;
            if dead < 10.0 {
                score += 12.0 * (10.0 - dead) / 10.0;
            }
        }
    }

    // Prefer bins whose residual is below mean (conserving large residuals for large items).
    if bin_residual as f64 > mean_residual + 20.0 && bin_residual != bin_capacity {
        score += 5.0;
    }

    // Small deterministic tie-breaker spreading bins.
    score += (bin_residual % 7) as f64 * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Smooth polynomial coupling of post_residual with stream progress
    let prn = pr / cap; // normalized post residual in [0,1]
    let poly = prn * prn * (1.0 - prn) * (1.0 - progress);
    score -= 30.0 * poly;

    // Tight fits favored more as stream progresses
    let fit = item_size as f64 / cap;
    score -= 20.0 * fit * progress * (1.0 - prn);

    // Penalize dead space that is too small for typical items, smoothly
    let dead = prn * (1.0 - prn * 4.0).max(0.0);
    score += 15.0 * dead;

    // Lookahead: reward leaving room for the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= 10.0 * (nxt / cap) * (1.0 - progress);
        } else {
            score += 8.0 * (1.0 - pr / nxt.max(1.0));
        }
    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Mild preference to consolidate when many bins are open
    score -= 3.0 * (open_bins_count as f64).ln().max(0.0) * (1.0 - prn);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: perfect-fit classes (0, and small
    // residuals that pair with common item sizes) are heavily rewarded.
    let perfect = post_residual == 0;
    if perfect {
        score -= 1000.0;
    } else {
        // Modulo-harmonic bonus: residuals in {20,25,30,40,50,60,75} are
        // reusable by typical item sizes; detect via divisibility structure.
        let r = post_residual;
        let harmonic = (r % 10 == 0 && r <= 50)
            || (r % 25 == 0)
            || (r % 20 == 0 && r <= 60);
        if harmonic {
            score -= 30.0;
        }
        // Penalize dead space that is too small to hold any plausible item
        // (below the minimum item size) but nonzero.
        if r < 10 {
            score += 60.0;
        }
        // Penalize awkward residuals: larger than the smallest useful class
        // but not matching a harmonic class => likely stranded.
        if r > 10 && !harmonic {
            score += 15.0;
        }
    }

    // Lookahead coupling: if the next item fits the post-residual exactly,
    // strongly reward; if it cannot fit, penalize lightly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 200.0;
        } else if next_item_size > post_residual && post_residual > 0 {
            score += 20.0;
        }
    }

    // Last-chance bin: if this is the only bin that can fit the item,
    // using it avoids opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate handling: an empty bin is a fallback. Make it
    // attractive only when no open bin offers a good (harmonic) fit.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, reduced late in the stream or
        // when many bins are open and mean residual is high (fragmentation).
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut open_cost = 120.0 - 40.0 * progress;
        if open_bins_count > 0 && mean_residual > 25.0 {
            open_cost += 30.0;
        }
        score = open_cost + (bin_capacity - item_size) as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post_residual)
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 3.0 * tightness * item_size as f64;

    // Penalize small unusable dead space (< 10, min item size)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }
    // Penalize moderately small gaps that few future items can use
    if post_residual >= 10 && post_residual < 30 {
        score += 6.0 * (1.0 - post_residual as f64 / 30.0);
    }

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 40.0;
    }

    // Open bins pressure: when many bins are open, prefer filling existing ones
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * 0.15 * (0.5 + progress);

    // New-bin candidate handling: penalize opening a new bin unless existing fits are bad
    if bin_residual == bin_capacity {
        score += 18.0;
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
        // Late in the stream, avoid leaving many half-full bins
        if progress > 0.8 {
            score += 10.0;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Lookahead coupling: if next item could use the post_residual, reward leaving it
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 4.0;
    }
    // If next item cannot use the leftover, penalize
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 3.0;
    }

    // Prefer bins with residual below mean (fill fuller bins first)
    if (bin_residual as f64) < mean_residual {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward perfect match of post_residual with next item.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Strong reward for exact match, decaying quadratically with distance.
        score -= 30.0 * (1.0 - (diff / 100.0)).powi(2) * (1.0 - diff / 100.0).max(0.0);
        // Extra bonus for exact fit for the next item.
        if post_residual == next_item_size {
            score -= 40.0;
        }
        // Penalize post_residual that is too small for the next item (dead space)
        // but only mildly if it is still usable.
        if post_residual < next_item_size {
            score += 0.5 * (next_item_size - post_residual) as f64;
        }
    } else {
        // Last item: minimize waste directly.
        score += 10.0 * (post_residual as f64 / bin_capacity as f64);
    }

    // Relative-to-mean coupling: prefer bins whose post_residual sits near mean_residual
    // (keeps residual distribution uniform, easier future packing).
    let mean_gap = (post_residual as f64 - mean_residual).abs();
    score += 0.3 * mean_gap;

    // Penalize very tight fits that leave unusable slivers (< 10, the min item size).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate (empty bin): make it attractive only when fit is good
    // and few bins are open; otherwise prefer reusing existing bins.
    if bin_residual == bin_capacity {
        score += 20.0 + 2.0 * open_bins_count as f64;
        // Empty bin leaves post_residual = capacity - item; encourage when it
        // can host the next item too.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 25.0;
        }
    }

    // Mild early-stream preference for consolidating into few bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.1 * (post_residual as f64 / bin_capacity as f64) * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits: squared post-residual penalty.
    score += (post_residual as f64) * (post_residual as f64) / (bin_capacity as f64);

    // Reward near-perfect fills.
    if post_residual < 5 {
        score -= 50.0;
    } else if post_residual < 10 {
        score -= 20.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Penalize opening a new bin when good alternatives exist,
    // but allow it if existing residuals are large/wasteful.
    if bin_residual == bin_capacity {
        let waste = if fitting_bins_count > 0 {
            mean_residual
        } else {
            0.0
        };
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let new_bin_penalty = 40.0 + 30.0 * progress - waste.min(40.0);
        score += new_bin_penalty.max(5.0);
    }

    // Lookahead: if the next item fits in the post-residual, reward this placement.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 10.0 + (post_residual - next_item_size) as f64 * 0.1;
        } else {
            // Next item won't fit here; penalize leaving awkward gaps slightly.
            score += (next_item_size - post_residual) as f64 * 0.05;
        }
    }

    // Prefer filling bins with many open bins (consolidation pressure).
    score += open_bins_count as f64 * 0.5;

    // Mild preference for bins already below mean residual (balance avoidance of fragmentation).
    score -= (mean_residual - bin_residual as f64) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let t = step_index as f64 / total_items.max(1) as f64;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let prn = pr / cap;
    score += prn * prn * (1.0 - t) * 20.0;      // early: penalize large residual more strongly
    score -= prn * (1.0 - prn) * t * 15.0;      // late: reward tight fits quadratically

    // Dead-space penalty: residual that likely cannot fit future items
    if next_item_size > 0 && (next_item_size as f64) > pr {
        score += (next_item_size as f64 - pr) * 0.6;
    } else if next_item_size > 0 {
        score -= 4.0 * (1.0 - (pr - next_item_size as f64) / cap);
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // Prefer bins below mean residual (fill emptier bins first, smooth coupling)
    score += (mean_residual - pr) * 0.15 * (1.0 + t);

    // Penalize opening new bins as stream progresses (smoothly)
    if bin_residual == bin_capacity {
        score += 8.0 + 30.0 * t * t;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Harmonic class of post_residual: dead-space quality in capacity fractions
    let frac = post / cap;
    // Classify unusable space: residual too small for typical items (1..=100)
    if post > 0 && post < 10 {
        score += 40.0; // tiny dead sliver is worthless
    } else if frac < 0.25 {
        score += 6.0; // small pocket, marginally usable
    } else if frac < 0.5 {
        score -= 2.0;
    } else if frac < 0.75 {
        score -= 6.0;
    } else {
        score -= 10.0; // large residual keeps bin flexible
    }

    // Integer-division thresholds on post_residual vs next_item_size lookahead
    if next_item_size > 0 {
        if post >= next_item_size {
            // Exact fit for lookahead: strong reward
            if post == next_item_size { score -= 25.0; }
            else {
                let div = post / next_item_size.max(1);
                score -= 8.0 * (div.min(3) as f64);
            }
        } else {
            // Lookahead won't fit here: penalize proportionally
            score += 5.0 * (1.0 - post / (next_item_size.max(1) as f64).min(cap));
        }
    } else {
        // Last item: any residual is pure waste; prefer minimal leftover
        score += 30.0;
    }

    // Perfect fit reward
    if post == 0 { score -= 50.0; }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Penalize opening a new bin when decent existing fits exist
    if bin_residual == bin_capacity {
        score += 12.0;
        if fitting_bins_count > 0 {
            // worse if existing bins would leave small residuals
            score += 10.0;
        }
        if open_bins_count == 0 { score -= 30.0; }
    }

    // Stream progression: later in stream, waste matters more
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.3 * progress;

    // Coupling with mean residual: avoid making bin set unbalanced
    score += 0.15 * (post - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

