    score += 0.3 * ((bin_residual as f64) - mean_residual);

    // New-bin candidate: make it attractive only when the item fits poorly everywhere
    // (large post_residual elsewhere) by giving the empty bin a moderate baseline.
    if bin_residual == bin_capacity {
        score += 10.0;
    }

    score
}

