pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual relative to item size.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize creating dead space that no plausible item can use.
    if post_residual > 0 && post_residual < 10 {
        score += 18.0;
    }

    // Lookahead coupling: if the next item fits the post_residual exactly-ish, reward strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            score -= 8.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // Next item won't fit here: mildly penalize leaving large leftovers.
            score += 0.05 * (post_residual as f64 - next_item_size as f64).abs();
        }
    }

    // Last-chance bin: strong reward to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when existing bins are crowded or fit is poor.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let crowded = mean_residual < item_size as f64 * 1.2;
        score += 40.0 - 15.0 * progress - if crowded { 35.0 } else { 0.0 }
                 - 2.0 * (open_bins_count as f64).ln().max(0.0);
        // Perfect-fit item in a fresh bin is great.
        if item_size == bin_capacity {
            score -= 100.0;
        }
    } else {
        // Prefer bins whose residual is close to the item (best-fit flavor).
        score += 0.15 * (bin_residual as f64 - item_size as f64);
        // Spread load when many bins are open and mean residual is high.
        if mean_residual > 50.0 {
            score += 3.0;
        }
    }

    // Mild time pressure: later in the stream, consolidate more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * fit_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Smooth polynomial coupling of post_residual with stream progress:
    // early on, prefer tight fits less aggressively (keep bins flexible);
    // later, punish large post_residual super-linearly.
    let p2 = progress * progress;
    let p3 = p2 * progress;
    score += pr * (0.5 * p2 + 1.5 * p3);

    // Reward small dead space nonlinearly (waste term).
    let waste = pr / cap;
    score += 40.0 * waste * waste * (0.3 + progress);

    // Tight fit bonus: smooth sigmoid-like reward near zero post_residual.
    let tight = (-pr / (0.15 * cap)).exp();
    score -= 12.0 * tight * (1.0 - 0.5 * progress);

    // Last-chance bin: strong reward so we don't open a new bin unnecessarily.
    if fitting_bins_count == 1 {
        score -= 8.0 + 6.0 * progress;
    }

    // Penalize bins far from mean residual (fragmentation pressure), smoothed.
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 5.0 * dev * dev;

    // Lookahead coupling: if next item fits in post_residual, reward this placement.
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 10.0 * (-slack / (0.2 * cap)).exp() * (1.0 - progress);
    } else if next_item_size > 0 {
        score += 4.0 * progress;
    }

    // Mild penalty for many open bins (encourage consolidation early).
    score += 0.15 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class logic on post_residual ---
    // Classify the leftover space into residue classes modulo 10 (item granularity band).
    let pr_class = post_residual % 10;
    // Dead-space classes: leftovers in [1..9] that few items can fill are bad.
    // Class 0 (perfect multiple of 10) is ideal; odd/tiny classes are worst.
    let class_penalty: f64 = match pr_class {
        0 => -14.0,
        1 | 2 => 6.0,
        3 | 4 => 2.0,
        5 => 0.0, // half-slot: fillable by mid items
        6 | 7 | 8 | 9 => 3.0,
        _ => 0.0,
    };
    score += class_penalty;

    // Integer-division thresholds: deep-fill reward when bin is mostly consumed.
    let fill_quotient = (bin_capacity - post_residual) / (bin_capacity / 4); // 0..=4
    score -= match fill_quotient {
        4 => 30.0, // >=75% full: excellent consolidation
        3 => 14.0,
        2 => 5.0,
        _ => 0.0,
    };

    // --- Lookahead coupling with next_item_size ---
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // This bin can also host the next item: strong reward, scaled by
            // how tight the follow-up fit is (harmonic pairing).
            let pair_tightness = (post_residual - next_item_size) as f64;
            score -= 18.0 - 0.15 * pair_tightness;
        } else {
            // Next item won't fit here: mild penalty proportional to the gap.
            let gap = (next_item_size - post_residual) as f64;
            score += 0.08 * gap;
        }
        // Modulo pairing: if next item exactly matches the post residual class band
        if next_item_size <= post_residual && (post_residual - next_item_size) % 10 == 0 {
            score -= 6.0;
        }
    } else {
        // Last item of the stream: waste is permanent, punish heavily.
        score += 1.5 * post_residual as f64;
    }

    // --- Last-chance logic ---
    if fitting_bins_count == 1 && bin_residual >= item_size {
        // If this is the only bin that fits, using it avoids opening a new bin.
        score -= 20.0;
    } else if fitting_bins_count > 2 {
        // Many alternatives: be picky, penalize mediocre fits.
        score += 0.05 * (fitting_bins_count as f64 - 2.0) * post_residual as f64;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin: baseline cost of +capacity-ish, discounted early in
        // the stream or when open bins are already crowded.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let crowding = if open_bins_count > 0 {
            (mean_residual / bin_capacity as f64).min(1.0)
        } else {
            0.0
        };
        score = bin_capacity as f64
            - 25.0 * (1.0 - crowding)   // cheap to open when existing bins are full
            - 20.0 * progress            // late-stream consolidation is less valuable
            - 10.0 * crowding;
        // Never open a new bin when a perfect or near-perfect fit exists elsewhere.
        if post_residual == 0 { score += 0.0; } // n/a for empty bin, keep symmetry
        if fitting_bins_count >= 1 && mean_residual >= item_size as f64 {
            score += 8.0; // some open bin has decent room: discourage new bin
        }
    }

    // --- Mean-residual coupling: prefer bins below mean residual (tighter bins) ---
    if bin_residual as f64 > mean_residual {
        score += 0.10 * (bin_residual as f64 - mean_residual);
    } else {
        score -= 0.05 * (mean_residual - bin_residual as f64);
    }

    // Small deterministic tie-breaker on step parity (harmonic alternation).
    if step_index % 2 == 0 {
        score -= 0.01;
    } else {
        score += 0.01;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful
    // later (below the minimum conceivable item size) are heavily penalized.
    let min_item = 1.0f64;
    if post_residual > 0 && (post_residual as f64) < min_item + 8.0 {
        score += 40.0; // unusable sliver -> strong penalty
    }

    // Reward tight fits (small post_residual relative to bin capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize leaving a gap that no small item could exploit well:
    // a mid-sized dead zone is worse than a near-empty or near-full one.
    let pr = post_residual as f64;
    if pr > 0.0 && pr < 25.0 {
        score += 0.8 * (25.0 - pr); // rising penalty as gap shrinks into uselessness
    }

    // Open-bin pressure: discourage spreading across many bins unless the fit is good.
    if fitting_bins_count > 1 {
        score += 1.5 * open_bins_count as f64;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // current bins have poor residual fit for this item.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base cost of opening a new bin.
        score += 20.0 + 2.0 * open_bins_count as f64;
        // If this item would leave a bad gap in an existing bin, new bin is better.
        let wasted_in_existing = (mean_residual - item_size as f64).abs();
        if wasted_in_existing > 30.0 {
            score -= 0.5 * wasted_in_existing;
        }
        // Early stream: allow more bins; late stream: consolidate.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 15.0 * progress;
    } else {
        // Prefer bins whose residual matches the item well.
        let fit_gap = (bin_residual as f64 - item_size as f64).abs();
        score += 0.3 * fit_gap;
    }

    // Lookahead: if next item fits exactly in post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap_after_next = post_residual - next_item_size;
        if gap_after_next <= 5 {
            score -= 10.0; // chains two items perfectly
        }
    } else if next_item_size > 0 && (post_residual as f64) < next_item_size as f64 {
        score += 3.0; // post_residual useless for the known next item
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
