pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good.
    let tight_fit_bonus = 40.0 * (-post_residual as f64 / 12.0).exp();
    score -= tight_fit_bonus;

    // Penalize large dead space relative to capacity.
    score += (post_residual as f64 / bin_capacity as f64).powi(3) * 30.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual >= next_item_size {
            score -= 8.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // Next item won't fit here; slight penalty if we waste space now.
            score += 4.0 * (post_residual as f64 / bin_capacity as f64);
        }
    }

    // Global state: penalize spreading residual mass when mean residual is already high.
    score += 0.15 * (mean_residual - post_residual as f64).abs();

    // Prefer bins whose residual differs from the item size in a "complementary" way:
    // moderate penalty for very large residuals (encourage filling fuller bins first).
    score += 0.1 * bin_residual as f64;

    // Time horizon: later in the stream, be more conservative — keep residuals usable.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64 / bin_capacity as f64) * 10.0;

    // New-bin candidate handling: opening a new bin is only attractive when no
    // open bin fits well. Penalize the empty-bin call by default.
    if bin_residual == bin_capacity {
        // Base cost of a new bin.
        score += 20.0;
        // If many bins fit the item, opening a new bin is wasteful.
        score += 12.0 * (fitting_bins_count as f64).min(5.0);
        // If open bins are fragmented (high mean residual), a new bin is more acceptable.
        score -= (mean_residual / bin_capacity as f64) * 15.0;
        // Late in the stream, avoid opening new bins.
        score += progress * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let fit_frac = pr / cap; // 0..1 residual fraction after placement
    let item_frac = item_size as f64 / cap;

    let mut score = pr as f64;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // early on, prefer tight fits less strongly; late, strongly prefer small post_residual.
    let poly = fit_frac * fit_frac * (1.0 + 2.5 * progress) + 0.8 * fit_frac * progress;
    score += 40.0 * poly;

    // Reward near-perfect fits smoothly (small post_residual bonus, stronger late).
    score -= 30.0 * (1.0 - fit_frac) * (1.0 - fit_frac) * (0.5 + progress);

    // Dead-space penalty: residual too small for typical future items (smooth trough).
    let next_frac = next_item_size as f64 / cap;
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).max(0.0) / cap;
        let wasted = if pr < next_item_size as f64 {
            (next_item_size as f64 - pr) / cap
        } else {
            0.0
        };
        // Penalize when this bin's post-residual can't host the next item (wasted),
        // but reward leaving just enough room (small gap).
        score += 25.0 * wasted * (0.4 + 0.6 * progress);
        score -= 10.0 * (1.0 - gap.min(1.0)) * gap * 4.0 * (1.0 - wasted);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 60.0 * (1.0 - 0.5 * fit_frac);
    }

    // Many open bins with high mean residual: prefer consolidating into fuller bins.
    let crowding = (open_bins_count as f64).ln1p();
    let fullness = 1.0 - bin_residual as f64 / cap;
    score -= 8.0 * crowding * fullness * (0.3 + 0.7 * progress);

    // Mean-residual coupling: if this bin's residual is far below mean, it's a good filler.
    let dev = (mean_residual - bin_residual as f64) / cap;
    score -= 6.0 * dev.tanh();

    // New-bin candidate: penalize opening a new bin unless current fits are all poor.
    if bin_residual == bin_capacity {
        let poor_fit = (fitting_bins_count == 0) as i32 as f64;
        score += 50.0 - 45.0 * poor_fit + 10.0 * progress;
        // Opening early is more acceptable when stream is young.
        score -= 15.0 * (1.0 - progress) * (1.0 - progress);
    }

    // Mild item-size interaction: large items deserve tighter placement.
    score += 12.0 * item_frac * fit_frac;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual in low classes get a discount.
    if post_residual == 0 {
        score -= 50.0; // perfect fit
    } else {
        // Harmonic class of post_residual: modulo buckets penalize awkward leftovers
        let pr = post_residual;
        let class = pr % 10;
        // Dead space that is too small for the smallest item (1) is fine only if 0;
        // leftover that can't fit next_item is penalized.
        if next_item_size > 0 && pr < next_item_size {
            score += 8.0 + 0.1 * (next_item_size - pr) as f64;
        }
        // Reward leftovers that exactly accommodate next item (mod-friendly couplings)
        if next_item_size > 0 && pr == next_item_size {
            score -= 12.0;
        }
        // Harmonic thresholds: leftover divisible by common item sizes is reusable
        if pr % 25 == 0 || pr % 20 == 0 || pr % 50 == 0 {
            score -= 3.0;
        }
        // Penalize mid-range waste classes (10..30) which are least reusable
        if pr >= 10 && pr <= 30 && class >= 5 {
            score += 2.0;
        }
        // Fraction-of-capacity coupling
        let frac = pr as f64 / bin_capacity as f64;
        score += 5.0 * (frac - 0.5).abs();
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize mildly, but allow opening when all fits are poor
    if bin_residual == bin_capacity {
        score += 6.0;
        // If current bin fit would leave unusable sliver, opening new bin is attractive
        if post_residual < 5 {
            score -= 10.0;
        }
    }

    // Late in stream: consolidate into fewer bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 4.0 * progress * (mean_residual / bin_capacity as f64);

    // Prefer bins below mean residual (more filled) slightly
    score += 0.05 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += (10.0 - post_residual as f64) * 8.0;
    }
    // Zero residual is a perfect fit: strong reward.
    if post_residual == 0 {
        score -= 60.0;
