    // Reward tight fits relative to item size.
    let tightness = item_size as f64 / bin_capacity as f64;
    score -= tightness * 25.0;

    // Dead space relative to capacity.
    let dead = post_residual as f64 / bin_capacity as f64;
    score += dead * dead * 40.0;

    // Lookahead: if next item fits exactly into post_residual, reward strongly.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let gap = (post_residual - next_item_size) as f64;
            score -= 20.0 - gap * 0.3;
        } else {
            score += 6.0;
        }
    }

    // Last-chance bin: strongly favor using it instead of opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (0.4 + 0.6 * progress);

    // Mean residual coupling: prefer bins below mean residual (tighter bins).
    score -= (mean_residual - post_residual as f64) * 0.25;

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 50.0;
        } else {
            // Opening a new bin when alternatives exist: penalize,
            // unless the only fits would leave large dead space.
            score += 30.0 + open_bins_count as f64 * 2.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Penalize creating unusable dead space (too small for the smallest plausible item).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // 2-step lookahead: reward when post_residual matches next item size exactly or closely.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual > next_item_size {
            // Next item can also fit here: reward proportionally to how well it fills.
            let fill = next_item_size as f64 / post_residual as f64;
            score -= 200.0 * fill;
        } else {
            // Next item won't fit in the residual: penalize wasted lookahead opportunity.
            score += 30.0 * (next_item_size - post_residual) as f64 / item_size.max(1) as f64;
        }
    }

    // Relative to mean residual: bins with larger-than-average residual are better targets.
    let dev = bin_residual as f64 - mean_residual;
    score -= 0.5 * dev;

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 300.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are crowded.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let crowded = mean_residual < item_size as f64 * 1.5;
        if crowded {
            score -= 50.0;
        } else {
            score += 150.0 + 100.0 * (1.0 - progress);
        }
    }

    // Slight preference for fuller bins overall.
    score -= 0.3 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
