        let consolidation_pressure = (mean_residual / bin_capacity as f64) * (open_bins_count as f64).ln().max(1.0);
        if bin_residual < bin_capacity {
            score -= consolidation_pressure * 8.0;
        }
    }

    // New-bin candidate: only attractive when the item fits poorly everywhere else
    // (i.e., this empty bin gives a large post-residual but the fit is "clean").
    if bin_residual == bin_capacity {
        let waste = bin_capacity - item_size;
        // Fresh bin cost grows over time as open-bin count grows.
        let mut new_bin_score = 55.0 + (open_bins_count as f64) * 3.0;
        // A fresh bin is good if the item is large (leaves small unusable residue)
        // or if no other bin fits well (post_residual of others would be large).
        new_bin_score -= (item_size as f64 / bin_capacity as f64) * 45.0;
        if next_item_size > 0 && waste >= next_item_size {
            new_bin_score -= 12.0; // fresh bin can also host the next item
        }
        score += new_bin_score;
    }

    // Mild time-horizon modulation: early on, be slightly greedy for tight fits.
    score -= (1.0 - progress) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items as f64).max(1.0);
    let post = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_post = post / cap;

    let mut score = post;

    // Smooth polynomial coupling: residual cost grows super-linearly as stream progresses
    let t = progress;
    let coupling = 1.0 + 2.0 * t * t;
    score += coupling * norm_post * norm_post * cap * 0.5;

    // Penalize residual that cannot fit the lookahead item (smooth falloff)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let slack = post - nxt;
        let fit_term = slack / (slack.abs() + nxt).max(1.0);
        score += 8.0 * (1.0 - fit_term) * (1.0 - 0.5 * t);
    }

    // Reward tight fits (small post_residual relative to item)
    let tightness = 1.0 - (post / (bin_residual as f64).max(1.0));
    score -= 6.0 * tightness * tightness;

    // Last-chance bonus: only bin that fits
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate: prefer opening a new bin early or when open bins are fragmented
    let is_new = bin_residual == bin_capacity && item_size > 0;
    if is_new {
        let fragmentation = (mean_residual - post).abs();
        score = cap * (0.9 + 0.5 * t) + fragmentation * 0.3 - 5.0 * (1.0 - t);
    }

    // Mild penalty for spreading across many open bins
    score += 0.05 * open_bins_count as f64 * t;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward exact small classes (perfect fits)
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 10 {
        score -= 50.0;
    } else if post_residual <= 20 {
        score -= 20.0;
    }

    // Dead-space penalty: residuals that no typical item (1..=100) can use well.
    // Residual in (0,10) is nearly unusable; penalize heavily unless it is 0.
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Modulo-class logic: residuals that are multiples of common item classes
    // (10, 20, 25, 50) are more reusable.
    let pr = post_residual;
    if pr % 50 == 0 && pr > 0 { score -= 15.0; }
    else if pr % 25 == 0 && pr > 0 { score -= 10.0; }
    else if pr % 10 == 0 && pr > 0 { score -= 6.0; }
    if pr % 10 == 9 || pr % 10 == 1 { score += 3.0; }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 80.0;
        } else if next_item_size <= pr {
            // next item fits: reward proportionally to how well it fills leftover
            let fill_after_next = (pr - next_item_size) as f64;
            score -= 20.0 * (1.0 - fill_after_next / cap);
            if (pr - next_item_size) < 10 && (pr - next_item_size) > 0 {
                score += 10.0; // creates tiny dead space after next
            }
        } else {
            // next item cannot use this bin's leftover: mild penalty
            score += 8.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 60.0;
    }

    // Prefer filling fuller bins (tightness reward).
    let tightness = 1.0 - (post_residual as f64) / cap;
    score -= 25.0 * tightness * tightness;

    // New-bin candidate handling: only attractive when no good existing option.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        // Base cost of opening a new bin.
        score += 120.0;
        // If this bin is the only fitting bin and the fit is bad, opening is fine.
        if fitting_bins_count == 0 {
            score -= 200.0;
        } else if fitting_bins_count == 1 {
            // Compare: poor fit into lone bin vs new bin
            if post_residual > 0 && post_residual < 15 {
                score -= 100.0; // existing bin would leave dead space; open new
            }
        }
        // Late in the stream, avoid proliferating bins.
        score += 40.0 * progress;
        // Many open bins with high mean residual: prefer reusing them.
        if mean_residual > (item_size as f64) * 1.5 {
            score += 25.0;
        }
        if open_bins_count > 8 {
            score += 30.0;
        }
    }

    // Small tie-breaker toward bins with residual close to item size.
    let diff = (bin_residual as i64 - item_size as i64).unsigned_abs() as f64;
    score += 0.05 * diff;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    let dead = post_residual as f64;
    if dead > 0.0 && dead < 10.0 {
        score += 40.0 * (10.0 - dead) / 10.0; // worst near gap=1..9
    }
    // Reward tight fits strongly.
    let tightness = (item_size as f64) / (bin_residual as f64).max(1.0);
    score -= 25.0 * tightness * tightness;

    // Perfect fill bonus.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Dead space relative to capacity: penalize large wasted fractions mildly.
    score += 0.15 * dead * dead / (bin_capacity as f64);

    // Open-bin pressure: discourage opening new bins when many are open,
    // encourage consolidation when few bins are open.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (1.0 - progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize when pressure high, discount when item
        // would leave a bad gap in any existing bin.
        score += 10.0 + 2.0 * pressure;
        if dead > 0.0 && dead < 10.0 { score -= 20.0; } // allow new bin if it avoids tiny-gap placement
    } else {
        score -= 1.5 * pressure.min(10.0);
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Lookahead: if next item fits the post-residual, reward leaving exactly
    // that much space; penalize if post_residual is just barely too small.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if (nx - dead).abs() < 1.0 {
            score -= 20.0;
        } else if dead > 0.0 && dead < nx {
            score += 8.0 * (nx - dead) / nx; // gap too small for next item
        } else if dead >= nx {
            score -= 6.0 * (dead - nx) / bin_capacity as f64;
        }
    }

    // Mean-residual coupling: prefer bins whose residual is near the mean
    // (keeps bins balanced), penalize outliers.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward: item exactly fills the bin.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Tightness: reward small post_residual relative to capacity.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 60.0 * tightness * tightness;

    // 2-step lookahead: exact match of next item into post_residual is ideal.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            // Next item fits, but leaves more fragmentation: mild penalty scaled by leftover.
            let leftover = (post_residual - next_item_size) as f64;
            score -= 80.0 - 0.5 * leftover;
        } else {
            // Next item cannot use the leftover: penalize dead space proportionally.
            let dead = (next_item_size - post_residual) as f64;
            score += 0.4 * dead;
        }
    }

    // Compare post_residual against mean residual across open bins.
    // Leaving this bin with residual near the mean keeps flexibility.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.3 * dev;

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // Penalize spreading across many open bins slightly; encourage consolidation
    // when few bins fit the item.
    if fitting_bins_count > 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate (empty bin): make it expensive unless it enables a
    // perfect fit for the next item or current fit is impossible elsewhere.
    if bin_residual == bin_capacity {
        score = 200.0 + 0.5 * item_size as f64;
        if next_item_size > 0 && next_item_size == item_size {
            score -= 60.0; // pair two items in one fresh bin
        }
        if fitting_bins_count == 0 {
            score -= 1000.0; // no alternative: must open new bin
        }
    }

    // Slight progression-aware nudge: late in the stream, favor tight packing.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: the smaller the post_residual relative to item size, the better.
    let tightness = post_residual as f64 / (item_size.max(1) as f64);
    score -= tightness * 6.0;

    // Penalize large dead space (unusable residual) more aggressively as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if post_residual < item_size.min(bin_capacity / 4) && post_residual > 0 {
        score += (1.0 + 3.0 * progress) * (post_residual as f64);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly in the post_residual, reward this placement.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0;
        } else if post_residual >= next_item_size {
            score -= 8.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // Next item won't fit here; slight penalty for fragmenting space.
            score += 3.0 * (next_item_size - post_residual) as f64 / bin_capacity as f64;
        }
    }

    // New-bin candidate logic: an empty bin is only attractive when open bins have poor fit
    // or are nearly full on average.
    if bin_residual == bin_capacity {
        let avg_pressure = mean_residual / bin_capacity as f64;
        // Penalize new bins when existing bins are roomy and numerous.
        score += 15.0 + 10.0 * avg_pressure + (open_bins_count as f64).sqrt() * 2.0;
        // Late in the stream, opening a fresh bin is more acceptable.
        score -= 20.0 * progress;
    }

    // Mild preference for filling fuller bins (lower residual) among open bins.
    score += (bin_residual as f64 - mean_residual) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr as f64;
    // Non-linear coupling of post_residual with stream progress
    score += 40.0 * norm_pr * norm_pr * (0.5 + progress);
    score -= 25.0 * norm_pr * (1.0 - progress) * (1.0 - progress);
    // Reward tight fits more strongly as stream progresses
    let tightness = 1.0 - norm_pr;
    score -= 30.0 * tightness * tightness * (0.3 + 0.7 * progress);
    // Penalize dead space relative to mean residual of open bins
    score += 10.0 * (norm_pr - mean_residual / cap).abs();
    // Lookahead: favor residual that can host next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= 15.0 * (1.0 - (pr - nxt) / cap) * (0.5 + progress);
        } else {
            score += 20.0 * (nxt - pr) / cap;
        }
    }
    // Last-chance bin: strong reward to use it rather than open new bin
    if fitting_bins_count == 1 {
        score -= 50.0 * (1.0 - norm_pr);
    }
    // New-bin candidate: penalize opening bins when good fits exist, more so later
    if bin_residual == bin_capacity {
        score += 60.0 * (0.4 + 0.6 * progress) + 5.0 * open_bins_count as f64;
    }
    // Mild crowding penalty
    score += 2.0 * open_bins_count as f64 * norm_pr;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: perfect fits (residual 0) are ideal.
    if post_residual == 0 {
        score -= 200.0;
    } else {
        // Integer-division thresholds on post_residual: small leftovers are dead space.
        let cls = post_residual / 10; // harmonic class bucket (capacity fractions of 10)
        score += cls as f64 * 3.0;

        // Modulo-style coupling: residuals that pair well with common item sizes.
        // If the next item can exactly fill the leftover, reward strongly.
        if next_item_size > 0 {
            if next_item_size == post_residual {
                score -= 150.0;
            } else if next_item_size < post_residual {
                let nxt_post = post_residual - next_item_size;
                if nxt_post == 0 { score -= 120.0; }
                else if nxt_post <= 5 { score -= 40.0; }
                else { score += (nxt_post / 10) as f64 * 2.0; }
            } else {
                // next item cannot fit here: leftover likely dead space
                score += 15.0;
            }
        }
    }

    // Tightness reward: fraction of bin used by this placement.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= fill * 30.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }
    if fitting_bins_count > 1 {
        // With many options, prefer the tightest; add mild penalty scaled by options.
        score += (fitting_bins_count as f64).ln() * 2.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // no open bin fits well (large post_residual everywhere) or stream is early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let best_alt = if fitting_bins_count > 0 { mean_residual } else { 1e9 };
        // Penalize new bins when open bins have small residuals (good fits exist).
        score += 120.0 - best_alt * 1.5;
        // Late in the stream, avoid spreading items across new bins.
        score += progress * 40.0;
        // If many bins already open and mean residual is large, consolidation is better.
        score += (open_bins_count as f64).sqrt() * 5.0;
    }

    // Mild pressure to consolidate into existing bins as they fill up.
    score -= mean_residual * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to hold even the
    // smallest future item (1..=100 interface, but keep a conservative
    // dead-zone) are heavily penalized.
    let dead_zone = 10.0f64;
    if (post_residual as f64) < dead_zone && post_residual > 0 {
        score += (dead_zone - post_residual as f64) * 6.0;
    }

    // Perfect / near-perfect fits get a strong reward.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Reward bins whose residual closely matches the item (tight packing).
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score += tightness * 0.15;

    // Pressure from number of open bins: discourage spreading across many
    // bins, but allow new bins when the fit would be terrible.
    score += open_bins_count as f64 * 0.5;

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin unless the fit is awful.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate logic: an empty bin is only attractive if the current
    // fit elsewhere would leave a large awkward gap, or the item is huge.
    if bin_residual == bin_capacity {
        let poor_fit = post_residual as f64 > 0.0 && (post_residual as f64) < 20.0;
        if poor_fit {
            score -= 25.0; // opening fresh is better than making dead space
        } else {
            score += 30.0; // default: prefer existing bins
        }
        // Huge items fill a fresh bin well.
        if item_size >= 70 {
            score -= 10.0;
        }
    }

    // Lookahead: if the next item would fit the post-residual, reward this
    // placement (leaves a useful gap).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 4.0;
    }

    // Mild drift with stream progress: later in the stream, consolidate more
    // aggressively (favor existing bins).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 3.0;

    // Mean residual coupling: if this bin's post-residual deviates far below
    // the mean, it's becoming an outlier dead bin; penalize.
    let dev = mean_residual - post_residual as f64;
    if dev > 0.0 {
        score += dev * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact/near match with next item.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect chain fit (next item exactly fills the post residual) is heavily rewarded.
        if post_residual as i64 == next_item_size as i64 {
            score -= 40.0;
        } else if post_residual >= next_item_size {
            // Next item fits here afterwards: reward proportional to tightness of chain.
            score -= 15.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // Next item cannot use the post residual: penalize leftover dead space.
            score += 0.5 * gap;
        }
    }

    // Reward tight fits relative to current residual.
    let tightness = 1.0 - (post_residual as f64 / bin_residual.max(1) as f64);
    score -= 10.0 * tightness;

    // Penalize placements that leave residuals far from mean residual structure.
    score += 0.3 * ((post_residual as f64 - mean_residual).abs());

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Slight preference to fill existing bins when many are open.
    score += 0.2 * open_bins_count as f64;

    // Prefer compacting early in the stream; allow more spreading later.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 2.5 * tightness * tightness * bin_capacity as f64;

    // Penalize large dead space quadratically: residual that can't fit typical items is wasted.
    if post_residual > 0 {
        let dead = post_residual as f64;
        score += 0.35 * dead * dead / bin_capacity as f64;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Lookahead: reward bins whose post_residual can host the next item (k=2 chaining).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0 + 0.25 * next_item_size as f64;
        } else {
            // Penalize leaving a residual just below the next item (unusable dead space).
            let gap = (next_item_size - post_residual) as f64;
            if post_residual > 0 {
                score += 0.4 * gap;
            }
        }
    } else {
        // Last item: strongly prefer zero residual.
        score += 0.5 * post_residual as f64;
    }

    // Last-chance bin: if this is the only fitting bin, strongly favor using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // existing fitting options are scarce or residuals are highly fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = if open_bins_count > 0 {
            (mean_residual / bin_capacity as f64).abs()
        } else {
            1.0
        };
        // Base penalty for opening a new bin.
        score += 25.0;
        // Attractive when few bins fit the item or open bins are nearly full.
        if fitting_bins_count == 0 {
            score -= 40.0;
        } else if fragmentation < 0.15 {
            score -= 10.0 * (1.0 - fragmentation);
        }
        // Slightly less willing to open bins late in the stream.
        score += 8.0 * progress;
    }

    // Mild preference to fill bins with larger residual spread from the mean
    // (balance load across open bins).
    score += 0.05 * (bin_residual as f64 - mean_residual).abs();

    // Encourage consolidation when many bins are open.
    if open_bins_count > 4 {
        score -= 0.5 * open_bins_count as f64 * tightness;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let prn = pr / cap;
    let is_new_bin = (bin_residual == bin_capacity) as f64;

    let mut score = pr;

    // smooth non-linear coupling of post_residual with stream progress
    let coupling = prn * prn * (1.0 - progress) * 40.0
                 - prn * (1.0 - prn) * progress * 25.0;
    score += coupling;

    // reward tight fits, penalize dead space more strongly later in stream
    score -= (1.0 - prn) * (1.0 - prn) * (30.0 + 40.0 * progress);

    // lookahead: reward leaving space for the next item
    let ni = next_item_size as f64;
    if ni > 0.0 {
        let gap = (pr - ni).abs();
        score -= (1.0 - gap / cap) * 20.0 * (1.0 - progress);
        if ni > pr {
            score += 15.0 * (1.0 - progress);
        }
    }

    // last-chance bin: strong bonus to avoid opening a new bin
    if fitting_bins_count == 1 && is_new_bin < 0.5 {
        score -= 35.0;
    }

    // penalize scattering across too many open bins early
    score += (open_bins_count as f64).ln() * (1.0 - progress) * 5.0;

    // new-bin candidate: prefer only when it yields good future utility
    score += is_new_bin * (55.0 - 30.0 * progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues that pair well with common small items
    let pr = post_residual;
    // Class A: post_residual is a multiple of 10 or 20 -> highly reusable
    if pr > 0 && (pr % 10 == 0) {
        score -= 6.0 + (pr / 10) as f64 * 0.8;
    }
    // Class B: awkward residues (1..10 mod 10) -> dead space penalty
    if pr > 0 && pr % 10 != 0 {
        score += 3.0 + (10 - (pr % 10) as i64) as f64 * 0.5;
    }

    // Integer-division threshold classes on post_residual
    let pr_class = pr / 15; // coarse harmonic bucket
    score -= pr_class as f64 * 2.0;

    // Lookahead coupling: does next item fit exactly / snugly into post_residual?
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 15.0; // perfect pairing
        } else if next_item_size <= pr {
            let slack = (pr - next_item_size) as i64;
            // harmonic bonus if slack lands in a friendly residue class
            if slack % 10 == 0 {
                score -= 8.0;
            } else if slack <= 5 {
                score -= 5.0;
            } else {
                score -= 2.0;
            }
        } else {
            // next item won't fit here: mild penalty for trapping residual
            score += 2.0 + (next_item_size - pr).min(20) as f64 * 0.15;
        }
    } else {
        // last item: prefer tightest fill
        score -= 10.0;
    }

    // Fraction-of-capacity coupling: residual as fraction of capacity
    let frac = post_residual as f64 / cap;
    score += frac * frac * 4.0; // large leftover fraction penalized quadratically

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: penalize unless current bins are nearly full / crowded
    if bin_residual == bin_capacity {
        let crowd = open_bins_count as f64;
        let mean_r = mean_residual;
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        // Opening fresh bin is attractive only if open bins have small mean residual
        score += 8.0 + mean_r * 0.6 + crowd * 0.4 - progress * 3.0;
        // If item is large, fresh bin is more attractive
        score -= item_size as f64 * 0.05;
    }

    // Prefer bins with residual close to item size (tight fit) via modular distance
    let diff = if bin_residual >= item_size { bin_residual - item_size } else { 0 };
    score -= (20u32.saturating_sub(diff)) as f64 * 0.4;

    // Mean-residual harmonic alignment: reward bins below mean residual (tighter than average)
    if (bin_residual as f64) < mean_residual {
        score -= 2.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals below the minimum item size are pure waste.
    let min_item = 1.0f64;
    if (post_residual as f64) < min_item {
        score += 1000.0;
    }
    // Penalize small-but-usable gaps less than they deserve? No: penalize gaps that
    // are too small to be attractive for typical items.
    if post_residual > 0 && post_residual < 20 {
        score += 40.0 - post_residual as f64;
    }

    // Reward tight fits (small post_residual) super-linearly.
    if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 10 {
        score -= 12.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Open-bin pressure: discourage opening new bins when many bins are open.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // New bin baseline: its post_residual is large, add pressure scaled by open bins.
        score += 15.0 + 2.0 * open_bins_count as f64;
        // But if no open bin fits well, opening a new bin is fine.
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
        // Last-chance bin exists: make new bin less attractive.
        if fitting_bins_count == 1 {
            score += 20.0;
        }
    } else {
        // Reward using existing bins, especially last-chance ones.
        if fitting_bins_count == 1 {
            score -= 15.0;
        }
    }

    // Lookahead: if the next item fits the post_residual, reward this placement.
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        score -= 10.0;
    }
    // Penalize leaving a gap that just barely fails to fit the next item.
    if next_item_size > post_residual && post_residual > 0 && (next_item_size - post_residual) <= 10 {
        score += 8.0;
    }

    // Mild mean-residual coupling: prefer bins whose residual is below mean (tighter bins).
    score -= (mean_residual - bin_residual as f64) * 0.1;

    // Slight stream-progression pressure: late in the stream, consolidate more.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * (post_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-exact fits: penalize post_residual deviation from next item (2-step lookahead).
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 2.5 * (1.0 - gap / (bin_capacity as f64)).max(0.0) * (post_residual as f64);
        // Strong bonus if the next item exactly fills this bin afterward.
        if post_residual as i64 == next_item_size as i64 {
            score -= 30.0;
        } else if post_residual as i64 >= next_item_size as i64 {
            score -= 8.0;
        }
    }

    // Penalize small unusable dead space (fragmentation).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 20.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Relative to mean residual: prefer bins tighter than average.
    score -= 0.5 * (mean_residual - post_residual as f64);

    // New empty bin candidate: penalize mildly unless nothing else fits well,
    // so we only open new bins when open bins are poor fits.
    if bin_residual == bin_capacity {
        score += 10.0;
        // If no lookahead match exists in open bins, opening is fine.
        if next_item_size > 0 && next_item_size >= bin_residual {
            score -= 25.0;
        }
    }

    // Slight preference to consolidate early vs late in the stream.
    score -= 3.0 * (step_index as f64 / total_items.max(1) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: quadratic bonus for small post-residual.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize dead space that cannot be used by the next item (lookahead coupling).
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 6.0 + 0.35 * (post_residual as f64);
        } else {
            // Reward bins whose leftover exactly accommodates the next item.
            let gap = post_residual as f64 - next_item_size as f64;
            if gap < 10.0 {
                score -= 8.0 * (1.0 - gap / 10.0);
            }
        }
    } else {
        // Last item: maximize packing density aggressively.
        score -= 10.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // Many open bins with slack: discourage wasting residual in already-loose bins.
    let slack_gap = bin_residual as f64 - mean_residual;
    if slack_gap > 0.0 {
        score += 0.08 * slack_gap;
    } else {
        score -= 0.04 * (-slack_gap);
    }

    // Time horizon: early in stream, prefer consolidating into fewer bins;
    // late in stream, allow opening new bins for clean fits.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // New-bin candidate handling: penalize opening a new bin unless it gives a
    // near-perfect fit for the item or the stream is early with many bins open.
    if bin_residual == bin_capacity {
        let perfect_fit = (bin_capacity - item_size) as f64;
        let open_bonus = 1.0 / (1.0 + open_bins_count as f64);
        let new_bin_penalty = 14.0 * (1.0 - progress) + 10.0 * open_bonus;
        score += new_bin_penalty;
        // Reward large items going into fresh bins (they leave structured space).
        score -= 0.10 * item_size as f64;
        let _ = perfect_fit;
    }

    // Slight preference for bins with residual close to item size (exactness).
    let exactness = (bin_residual - item_size) as f64;
    score += 0.05 * exactness * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;

    // Base: penalize leftover space, quadratically so small residuals are strongly favored.
    let mut score = post * post / cap;

    // Linear waste term scaled by stream progress: later in the stream, waste matters more.
    score += post * (0.5 + progress);

    // Smooth non-linear coupling: tightness ratio (item/residual) rewarded non-linearly.
    let tightness = if bin_residual > 0 { item / bin_residual as f64 } else { 0.0 };
    score -= 8.0 * tightness * tightness * (1.0 + progress);

    // Penalize residuals too small to hold the smallest conceivable follow-up item,
    // smoothly via a bell-shaped dead-space penalty around mid residuals.
    let dead = (post / cap).powi(2) * (1.0 - (post / cap));
    score += 12.0 * dead * (0.5 + progress);

    // Last-chance bonus: if this is the only fitting bin, strongly reward using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 + 10.0 * progress;
    }

    // Lookahead: reward if next item fits the post residual (chaining), penalize otherwise.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual >= next_item_size {
            let fill = nxt / post;
            score -= 6.0 * fill * (1.0 - fill + 0.5 * fill * fill);
        } else {
            score += 3.0 * (1.0 - post / nxt.max(1.0));
        }
    }

    // Mild penalty for opening new bins when many bins are already open and mean residual is high.
    let is_new_bin = bin_residual == bin_capacity && post_residual == bin_capacity - item_size;
    if is_new_bin {
        score += 4.0 + open_bins_count as f64 * 0.5 + (mean_residual / cap) * 6.0;
        // But if no open bin fits tightly, opening is fine: soften via item size.
        score -= (item / cap) * 5.0;
    }

    // Mean-residual alignment: prefer bins whose residual is near the mean (keeps bin sizes balanced).
    score += 0.05 * (post - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residual modulo capacity quartiles
    let q = bin_capacity / 4;
    let class = post_residual % q;
    // Penalize residuals that fall in awkward "dead zone" classes (too small to be useful)
    if post_residual > 0 {
        if class < q / 3 {
            score += (q / 3 - class) as f64 * 0.7; // tiny unusable slivers
        } else if class > 2 * q {
            score -= (class - 2 * q) as f64 * 0.35; // large chunks are reusable
        }
    }

    // Integer-division harmonic: how many items of the next size fit in post residual
    if next_item_size > 0 {
        let fits = post_residual / next_item_size;
        score -= fits as f64 * 6.0;
        // Bonus if next item fits exactly (perfect pairing)
        if post_residual == next_item_size {
            score -= 15.0;
        } else if post_residual >= next_item_size {
            score -= 4.0;
        } else {
            score += 8.0; // next item cannot follow here -> dead space risk
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        // Among multiple candidates, prefer tightest fill (post_residual already encodes this)
        score -= 2.0;
    }

    // New-bin candidate logic: only attractive when current fit is terrible
    if bin_residual == bin_capacity && bin_capacity > 0 {
        let fill = item_size as f64 / bin_capacity as f64;
        if fill >= 0.9 {
            score -= 30.0; // nearly full fresh bin: great
        } else if fill < 0.35 {
            score += 20.0; // dumping small item in fresh bin wastes it
        } else {
            score += mean_residual - (bin_capacity - item_size) as f64; // compare against open-bin mean
        }
    }

    // Progress coupling: late in stream, consolidate aggressively
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 5.0;
    score += (open_bins_count as f64).ln() * 0.8;

    // Mean residual coupling: penalize creating below-mean waste
    if (post_residual as f64) < mean_residual * 0.5 {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for any
    // plausible future item (min size 1, but typical items >= 10) are wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // unusable sliver -> strong penalty
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 10.0;
    }

    // Tightness reward: fraction of bin consumed by this placement.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 25.0 * fill;

    // Dead-space ratio penalty (nonlinear): small post_residual relative to
    // capacity is fine, but larger leftovers that no item can pair with hurt.
    let dead_ratio = post_residual as f64 / bin_capacity as f64;
    if post_residual > 0 && post_residual < item_size {
        score += 15.0 * (1.0 - dead_ratio);
    }

    // Open-bin pressure: penalize spreading across many open bins slightly,
    // but only mildly so tight fits still win.
    score += 0.6 * open_bins_count as f64;

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin (unless post_residual is dead space).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
        if post_residual >= 10 {
            score -= 15.0;
        }
    }

    // Lookahead: if the next item fits exactly in the post_residual,
    // reward heavily (perfect chaining).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size < post_residual && post_residual - next_item_size < 10 {
            score -= 20.0;
        }
        // Penalize leaving a gap the next item almost-but-does-not fit.
        if post_residual > 0 && next_item_size > post_residual && next_item_size - post_residual <= 5 {
            score += 10.0;
        }
    }

    // New-bin candidate handling: an empty bin has a large natural score
    // (post_residual = capacity). Make it attractive only when no open bin
    // offers a good fit (i.e., best open-bin residual leaves dead space).
    if bin_residual == bin_capacity {
        // baseline for fresh bin: cost of committing a new bin
        score = (bin_capacity - item_size) as f64 + 0.6 * open_bins_count as f64;
        if next_item_size > 0 && (bin_capacity - item_size) >= next_item_size {
            score -= 12.0; // fresh bin keeps lookahead options open
        }
        if fitting_bins_count == 0 {
            score -= 50.0; // no open bin fits: must open
        }
        // If mean residual across open bins is large, prefer reusing bins.
        score += 0.15 * mean_residual;
    }

    // Mild stream-progression adaptation: later in the stream, consolidation
    // matters more, so tighten the dead-space penalty.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 10.0 * progress * dead_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward exact match of post_residual with next item
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 250.0;
        } else if post_residual >= next_item_size {
            // next item still fits here: mild reward proportional to leftover
            score -= 0.3 * (post_residual as f64 - next_item_size as f64);
        } else {
            // next item cannot fit: penalize wasted potential
            score += 0.5 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // Tightness: penalize leaving large unusable gaps relative to mean residual
    let gap = post_residual as f64 - mean_residual;
    score += 0.2 * gap;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 300.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are crowded
    if bin_residual == bin_capacity {
        score += 120.0;
        if next_item_size > 0 {
            score -= 0.4 * (next_item_size as f64 - post_residual as f64).abs();
        }
        // open new bin when few bins can fit the item
        score += 20.0 * fitting_bins_count as f64;
    }

    // Progression: later in stream, consolidate more aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 5.0 * (post_residual as f64 / bin_capacity as f64);

    // Small penalty for many open bins to encourage consolidation
    score += 0.1 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // New-bin candidate handling: only attractive when existing fits are poor.
    if bin_residual == bin_capacity {
        // Cost of opening a new bin, amortized by progress.
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut new_bin_score = 40.0 + 60.0 * (1.0 - progress);
        // If few bins can fit, opening may be wise; if many fit, discourage.
        if fitting_bins_count == 0 {
            new_bin_score -= 100.0;
        } else {
            new_bin_score += fitting_bins_count as f64 * 5.0;
        }
        // If the next item would fit snugly in a fresh bin, mildly favor it.
        if next_item_size > 0 && next_item_size <= bin_capacity {
            new_bin_score -= (bin_capacity - next_item_size) as f64 * 0.1;
        }
        return new_bin_score;
    }

    // Reward tight fits: perfect fill gets a big bonus.
    if post_residual == 0 {
        score -= 200.0;
    } else {
        // Small post-residual is good, but leave room for common small items.
        score -= (bin_capacity as f64 - post_residual as f64) * 0.5;
        // Penalize residuals that are too small to hold typical future items.
        if post_residual < 10 {
            score += 15.0;
        }
    }

    // Lookahead: if the next item fits exactly in post_residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 120.0;
        } else if next_item_size < post_residual {
            score -= (post_residual - next_item_size) as f64 * 0.3;
        } else {
            // Next item won't fit here; slight penalty for wasting the slot.
            score += (next_item_size - post_residual) as f64 * 0.1;
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 50.0;
    }

    // Prefer bins with residual below the mean (tighter bins get filled first).
    score += (mean_residual - bin_residual as f64) * 0.4;

    // Late in the stream, consolidate: favor bins already in use over spreading.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;

    // Base: waste after placement, damped for large post_residual (flexibility value)
    let mut score = pr * (1.0 - 0.4 * (pr / cap).powi(3));

    // Non-linear polynomial coupling of post_residual with stream progress:
    // early on, keep bins flexible (penalize small residuals more); later, tolerate tight fits
    let flex = (pr / cap).powi(2);
    score += 20.0 * flex * (1.0 - progress) * (1.0 - fit_ratio);

    // Tight-fit reward: quadratic in fill ratio
    score -= 15.0 * fit_ratio.powi(2);

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 12.0;
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0).ln().max(0.0);
    }

    // Prefer bins below mean residual (fill emptier bins first), smooth coupling
    score += 0.3 * (mean_residual - bin_residual as f64).max(0.0) * (1.0 - progress);

    // Lookahead: reward leaving room for the next item, penalize near-miss residuals
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            score -= 6.0 * (1.0 - (nx / (pr + 1.0)).powi(2));
        } else {
            score += 5.0 * ((nx - pr) / cap);
        }
    }

    // New-bin candidate: encourage opening a fresh bin when current fit is poor
    if bin_residual == bin_capacity {
        score -= 8.0 + 10.0 * (1.0 - fit_ratio);
    }

    // Mild penalty for too many open bins
    score += (open_bins_count as f64).sqrt() * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic classes of post_residual: residues near multiples of 10 are
    // "usable pockets" for small items; dead space classes get penalized.
    let pr = post_residual;
    let residue_class = (pr % 10) as f64;
    let pocket = if pr == 0 { 0.0 } else { 10.0 - residue_class };
    score += pocket * 0.6;

    // Reward filling bins almost exactly (tight fit bonus).
    if pr == 0 {
        score -= 60.0;
    } else if pr <= 5 {
        score -= 40.0;
    } else if pr <= 10 {
        score -= 15.0;
    }

    // Penalize leaving space that next item cannot use (lookahead coupling).
    if next_item_size > 0 {
        if pr >= next_item_size {
            // next item fits in the leftover: reward proportional to slack match
            let m = (pr - next_item_size) as f64;
            score -= 12.0 * (1.0 - m / cap).max(0.0);
        } else {
            // leftover too small for lookahead: dead space penalty
            score += 0.35 * (next_item_size - pr) as f64;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        let tightness = (item_size as f64 / cap).min(1.0);
        // big items justify new bins; small items should reuse open bins
        score += 45.0 * (1.0 - tightness);
        if fitting_bins_count > 0 {
            score += 30.0;
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 8.0; // pairing large items together is fine
        }
    }

    // Mild pressure to consolidate when many bins are open.
    score += 0.05 * open_bins_count as f64 * (bin_residual as f64 / cap);

    // Late-stream bias: prefer tightening existing bins as stream ends.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * (1.0 - post_residual as f64 / cap);

    // Mean-residual coupling: avoid bins far below average fullness.
    score += 0.2 * (mean_residual - bin_residual as f64).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to fit
    // typical future items (<= 10) are pure waste; penalize hard.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 20 {
        // Small gap: only usable by tiny items; mild penalty.
        score += 18.0;
    }

    // Reward near-perfect fits (small but nonzero post_residual is great
    // only if it is actually small relative to item size).
    if post_residual == 0 {
        score -= 25.0; // perfect packing
    } else {
        let fit_ratio = item_size as f64 / bin_residual as f64;
        score -= 20.0 * fit_ratio; // tighter fill => lower score
    }

    // Open-bin pressure: with many bins open, prefer reusing existing bins
    // over spreading out; penalize placements that waste large residuals.
    let pressure = open_bins_count as f64;
    if post_residual > 40 {
        score += 0.15 * pressure;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            score -= 8.0;
        }
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    // Make it attractive only when the current item is large and no good
    // fit exists; otherwise keep it slightly unattractive to encourage reuse.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        if item_size > 50 {
            score -= 5.0 + 5.0 * progress;
        } else {
            score += 10.0;
        }
    }

    // Mild drift toward mean residual alignment: prefer bins whose residual
    // is close to the mean (balanced usage).
    let diff = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * diff;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for exact or near-exact fit (small dead space)
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 500.0;
    } else if post_residual <= 10 {
        score -= 200.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches the next item well
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if post_residual as f64 >= next {
            let slack = post_residual as f64 - next;
            // Perfect chain: next item exactly fills the remainder
            if slack == 0.0 {
                score -= 800.0;
            } else if slack <= 10.0 {
                score -= 400.0 - slack * 10.0;
            } else {
                score -= 100.0 / (1.0 + slack);
            }
        } else {
            // Next item cannot fit here: penalize proportionally to the gap
            let gap = next - post_residual as f64;
            score += gap * 2.0;
        }
    }

    // Relative to mean residual: prefer bins tighter than average
    let dev = post_residual as f64 - mean_residual;
    score += dev * 0.5;

    // Last chance: if this is the only bin that fits, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 300.0;
    }

    // New-bin candidate: only attractive when current fit is poor
    if bin_residual == bin_capacity {
        let fit_quality = post_residual as f64 / bin_capacity as f64; // high = loose fit
        score += 50.0 + fit_quality * 400.0;
        // Opening a new bin is fine early when few bins are open
        score -= open_bins_count as f64 * 3.0;
        // Late in the stream, avoid spreading too thin
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 40.0;
        // If next item is large, a fresh bin is more valuable
        if next_item_size > 0 && next_item_size as f64 > mean_residual {
            score -= 100.0;
        }
    }

    // Mild penalty for leaving residuals that are hard to fill (odd sizes)
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize proportionally how well the item fills the bin.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 2.5 * fill_ratio * (item_size as f64 / bin_residual.max(1) as f64);

    // Penalize large dead space after placement, especially if it's too small
    // for typical future items (unusable sliver).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual >= 10 && post_residual < 30 {
        score += 8.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            // Reward leaving space the next item can use, scaled by how snug.
            score -= 12.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // Penalize leaving space that the next item cannot use.
            score += 6.0 * (1.0 - post_residual as f64 / next_item_size as f64);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Time horizon: early in the stream, be conservative and keep bins tidy;
    // later, prioritize consolidation to close bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 10.0 * (bin_residual as f64 / bin_capacity as f64);

    // Global state coupling: when many bins are open with high mean residual,
    // discourage spreading; prefer bins with residual near the mean (balance).
    if open_bins_count > 1 {
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.15 * dev;
        // Many open bins: favor filling existing bins over opening new ones.
        score -= 0.5 * open_bins_count.min(50) as f64 * 0.1;
    }

    // New-bin candidate handling: opening a new bin is only attractive when the
    // item is large and no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        let decent_fit_exists = fitting_bins_count > 0
            && mean_residual >= item_size as f64 * 1.15;
        if decent_fit_exists {
            // Penalize opening a new bin when a reasonable fit exists.
            score += 60.0;
        } else {
            // Mild preference for a fresh bin when fits are poor.
            score -= 5.0 + 0.5 * item_size as f64;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Normalize post-residual
    let x = pr / cap; // in [0,1)

    // Non-linear polynomial coupling: penalize small residuals (dead space) quadratically
    score += 8.0 * (1.0 - x) * (1.0 - x) * cap * 0.1;

    // Reward tight fits more strongly as stream progresses
    let tightness = 1.0 - x;
    score -= 6.0 * tightness * tightness * tightness * (0.5 + progress);

    // Lookahead coupling: if next item fits in post-residual, reward
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let fits_next = (pr >= nx) as i32 as f64;
        let slack = ((pr - nx).abs()) / cap;
        score -= 5.0 * fits_next * (1.0 - slack * slack);
        // penalize post-residual that is just barely too small for next item
        let near_miss = ((nx - pr) / cap).max(0.0);
        score += 4.0 * near_miss * (1.0 - near_miss) * (1.0 - progress);
    }

    // Last-chance bin bonus: avoid opening new bins when only one bin fits
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 3.0;
    }

    // Mild penalty for scattering across many bins relative to mean residual
    score += 0.05 * (open_bins_count as f64).ln().max(0.0) * (pr - mean_residual).abs() / cap;

    // Prefer using fuller (existing) bins over the fresh-bin candidate
    if bin_residual == bin_capacity {
        score += 2.0 + 3.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fits are heavily rewarded.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class: how well post_residual aligns with typical future item sizes.
    // Small post_residual that is "dead" (below min plausible item size) is penalized.
    if post_residual > 0 && post_residual < 5 {
        score += 25.0; // tiny unusable sliver
    }

    // Modulo-10 harmonic classes: post_residual divisible by 10 is reusable by
    // common item sizes; reward it.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 8.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 120.0;
        } else if next_item_size <= post_residual {
            score -= (post_residual - next_item_size) as f64 * 0.5;
        } else {
            // next item won't fit here; penalize wasted large residuals less strongly
            score += 5.0;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: neutral-ish baseline; only attractive when no open bin
    // is a good fit. Penalize opening new bins mildly, scaled by stream progress.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = 45.0 + 30.0 * progress;
        // If next item is huge, a fresh bin is more attractive.
        if next_item_size > 70 {
            score -= 10.0;
        }
    }

    // Prefer tighter bins: penalize bins with residual far above the mean.
    let dev = bin_residual as f64 - mean_residual;
    if bin_residual < bin_capacity {
        score += dev * 0.3;
    }

    // Many open bins: encourage consolidation into existing bins.
    if open_bins_count > 4 && bin_residual < bin_capacity {
        score -= 3.0;
    }

    // Integer-division threshold on post_residual: residuals >= half capacity
    // are flexible; slightly reward.
    if post_residual >= bin_capacity / 2 {
        score -= 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals that are small but nonzero are unusable.
    let dead_zone = 10.0;
    if post_residual > 0 && (post_residual as f64) < dead_zone {
        score += (dead_zone - post_residual as f64) * 8.0;
    }
    // Perfect fit reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward bins whose residual is close to the item (tight fit).
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score += tightness * 0.6;

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones;
    // with few open bins, opening a new bin is cheaper.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize when many bins are open, reward when stream is early.
        score += pressure * 6.0;
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= (1.0 - progress) * 5.0;
    } else {
        score -= pressure * 2.0;
    }

    // Lookahead: if the next item fits the post-residual, this placement is valuable.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 && (post_residual as f64) < next_item_size as f64 {
        score += 6.0; // creates a gap the next item cannot use
    }

    // Prefer bins with below-average residual (consolidate waste).
    if bin_residual != bin_capacity {
        score += (bin_residual as f64 - mean_residual) * 0.15;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strongly reward zero waste.
    if post_residual == 0 {
        score -= 200.0;
    }

    // Two-step lookahead: reward residual that exactly matches next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 150.0;
        } else if post_residual > next_item_size {
            // Reward leaving room for the next item, proportional to tightness.
            score -= 0.5 * (next_item_size as f64 / (post_residual as f64 + 1.0));
        } else {
            // Next item won't fit here; penalize proportionally to dead space.
            score += 0.3 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // Compare residual against mean residual across open bins:
    // prefer bins whose residual is tighter (less waste) than average.
    score += 0.4 * (mean_residual - post_residual as f64);

    // Last-chance bin: avoid opening a new bin if this is the only fit.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: penalize opening a bin unless the item is large
    // relative to capacity or many bins are already open.
    if bin_residual == bin_capacity {
        score += 40.0
            - 0.5 * item_size as f64
            - 0.05 * open_bins_count as f64;
    }

    // Slight preference for filling bins more as the stream progresses.
    score -= 0.1 * (step_index as f64 / (total_items as f64 + 1.0)) * (bin_capacity - post_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit bonus: reward small post_residual non-linearly.
    if post_residual > 0 {
        score -= 12.0 * (1.0 - post_residual as f64 / bin_capacity as f64).powi(3);
    } else {
        // Perfect fill is heavily rewarded.
        score -= 30.0;
    }

    // Penalize creating dead space that is too small to be useful for typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Lookahead: reward bins whose post_residual can host the next item exactly or well.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 10.0 * (1.0 - slack / bin_capacity as f64);
        if post_residual == next_item_size {
            score -= 15.0; // chained perfect fit
        }
    } else if next_item_size > 0 && post_residual > 0 {
        // Post-residual cannot host next item: penalize proportionally to wasted potential.
        score += 3.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: default mild penalty; allow opening when open bins fit poorly.
    if bin_residual == bin_capacity {
        let mut new_bin_score = 18.0;
        // Time horizon: later in the stream, prefer consolidating into open bins.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        new_bin_score += 15.0 * progress;
        // More open bins with high mean residual -> avoid opening yet another bin.
        new_bin_score += 2.0 * (open_bins_count as f64).sqrt();
        new_bin_score += mean_residual / bin_capacity as f64 * 10.0;
        // If this item is large relative to capacity, opening fresh is less painful.
        new_bin_score -= 6.0 * (item_size as f64 / bin_capacity as f64);
        // If next item is large too, a fresh bin can host a good pair.
        if next_item_size >= item_size && next_item_size + item_size <= bin_capacity {
            new_bin_score -= 8.0;
        }
        score = new_bin_score;
    }

    // Mild penalty for very full open bins when many alternatives exist (keep flexibility).
    if bin_residual != bin_capacity && post_residual > 0 && open_bins_count > 3 {
        score += (post_residual as f64 / bin_capacity as f64) * 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let residual_norm = post / cap;

    // Base: prefer tight fits, with non-linear (quadratic) coupling to stream progress.
    // Early in the stream, waste matters less (many items remain to fill gaps);
    // late in the stream, dead space is nearly unrecoverable, so weight grows.
    let mut score = post * (1.0 + 1.5 * progress * progress);

    // Smooth non-linear penalty on large leftover space (dead space amplification).
    score += 30.0 * residual_norm * residual_norm * (0.5 + progress);

    // Reward using existing bins, especially when alternatives are scarce.
    let scarcity = 1.0 / (fitting_bins_count as f64 + 1.0);
    score -= 8.0 * scarcity * (1.0 - residual_norm);

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // strongly favor this bin; if it would be wasted, mild penalty.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (post - nxt).abs();
        score += 0.3 * gap;
        if nxt <= post {
            score -= 10.0 * (1.0 - gap / cap) * (0.5 + progress);
        }
    }

    // New-bin candidate handling: empty bin has residual == capacity.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Prefer opening a new bin only when no open bin fits, or when all
        // fits are terrible and the stream is still long (plenty of future items
        // to fill the fresh bin).
        let future_left = (total_items.saturating_sub(step_index)) as f64;
        let badness = mean_residual / cap; // high mean residual => open bins are roomy
        let pressure = (fitting_bins_count as f64).min(3.0) / 3.0;
        score = cap
            + 20.0 * pressure
            - 15.0 * (1.0 - pressure) * (1.0 - progress)
            - 10.0 * badness * progress
            - 5.0 * (future_left / (total_items.max(1) as f64)) * (1.0 - pressure);
    } else {
        // Mild preference for bins below mean residual (balance load smoothly).
        score += 0.15 * (mean_residual - post);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic classes: reward residuals that belong to "useful" classes.
    // Class the post_residual by integer division into harmonic bands of capacity.
    let band = post_residual / 10; // harmonic class of leftover space
    // Small residuals (bands 0..3) are near-perfect fits: heavily reward.
    match band {
        0 => score -= 30.0,
        1 => score -= 22.0,
        2 => score -= 14.0,
        3 => score -= 7.0,
        4 => score -= 2.0,
        5 => score += 1.0, // half-full leftovers: mildly awkward
        6 => score += 2.0,
        7 => score += 1.0,
        8 => score -= 1.0, // nearly empty bin: still flexible
        _ => {}
    }

    // Dead-space penalty: residual that no plausible future item can use well.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver
    }

    // Modulo coupling: if next item divides evenly into post_residual,
    // this placement chains perfectly.
    if next_item_size > 0 && next_item_size <= post_residual {
        let q = post_residual / next_item_size;
        let r = post_residual % next_item_size;
        if r == 0 {
            score -= 18.0; // perfect fill of the remainder
        } else if r <= 10 {
            score -= 6.0;
        } else {
            score += r as f64 * 0.3;
        }
        // Reward if next item fits snugly leaving small class-0 residual
        if q >= 1 && r < next_item_size / 2 {
            score -= 3.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: empty bin (residual == capacity).
    if bin_residual == bin_capacity {
        // Prefer new bin only when existing fits are terrible (large post_residual)
        // or when open bins are congested and item is large.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = 55.0
            + 0.4 * item_size as f64
            - 10.0 * progress
            - (open_bins_count as f64 * 0.5);
        // If next item is small, a fresh bin keeps flexibility.
        if next_item_size > 0 && next_item_size <= 30 {
            score -= 8.0;
        }
        // If item nearly fills a bin alone, new bin is great.
        if item_size >= 90 {
            score -= 20.0;
        }
    }

    // Mild pressure to consolidate: prefer bins tighter than the mean residual.
    if (post_residual as f64) < mean_residual {
        score -= 2.0;
    } else {
        score += (post_residual as f64 - mean_residual) * 0.15;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = 0.0;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress ratio of the stream
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Reward tight fits: subtract more when post_residual is small relative to capacity
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Perfect fit bonus (item exactly fills bin)
    if post_residual == 0 {
        score -= 100.0;
    }

    // Aggressive 2-step lookahead: reward when next item exactly matches post_residual
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).unsigned_abs();
        if diff == 0 {
            score -= 80.0; // chain: this bin becomes perfect for the next item
        } else {
            // penalize residuals that are awkward relative to next item
            let rel = diff as f64 / bin_capacity as f64;
            score += 20.0 * rel;
            // small residual that next item can't use = dead space
            if post_residual < next_item_size && post_residual < 10 {
                score += 15.0;
            }
        }
    }

    // Compare against mean residual: bins already below mean residual are valuable to fill
    let residual_f = post_residual as f64;
    if mean_residual > 0.0 {
        let ratio = residual_f / mean_residual;
        if ratio < 1.0 {
            score -= 10.0 * (1.0 - ratio);
        } else {
            score += 8.0 * (ratio - 1.0).min(3.0);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 60.0;
    } else if fitting_bins_count > 1 {
        // with multiple options, prefer tighter ones (already handled) but
        // slightly penalize leaving many bins idle
        score += 2.0 * open_bins_count as f64 * (1.0 - tightness);
    }

    // New-bin candidate handling: opening a new bin is only attractive early in the
    // stream or when the fit is terrible. Penalize the empty bin (residual == capacity)
    // increasingly as the stream progresses.
    if bin_residual == bin_capacity {
        let open_penalty = 40.0 + 60.0 * progress + 0.5 * open_bins_count as f64;
        score += open_penalty;
        // but if item is huge and would leave a big residual in any bin, opening is fine
        if item_size >= 80 {
            score -= 30.0;
        }
    }

    // Late-stream consolidation: prefer filling existing bins tightly
    if progress > 0.7 {
        score -= 10.0 * tightness;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward near-perfect fits.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score -= 30.0 * (1.0 - tightness).powi(6);

    // Penalize small unusable dead space (< smallest possible item).
    if post_residual < 10 && post_residual > 0 {
        score += 40.0;
    }

    // Lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            score -= 8.0 * (next_item_size as f64 / post_residual.max(1) as f64);
        } else {
            // next item won't fit here; slight penalty for wasting space now
            score += 3.0 * (post_residual as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 1.0 } else {
            (item_size as f64 / bin_residual as f64).min(1.0)
        };
        // Base penalty for opening a new bin, reduced under pressure.
        score += 60.0 * (1.0 - pressure);
        // Early in the stream, opening bins is cheaper (more future items to fill them).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 1.0 };
        score += 20.0 * progress;
        // Few open bins relative to stream -> opening is fine.
        score -= (open_bins_count.min(20) as f64) * 0.5;
    } else {
        // Prefer bins with less residual among fitting bins (best-fit bias),
        // but avoid over-fragmenting when many bins are open.
        let frag = open_bins_count as f64 / (total_items.max(1) as f64).sqrt();
        score += 2.0 * frag * (post_residual as f64 / bin_capacity as f64);
    }

    // Mild global balancing: prefer bins whose residual is below mean (tighter bins).
    score += 0.05 * (mean_residual - post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_ratio = item_size as f64 / cap;
    let next_ratio = next_item_size as f64 / cap;

    // Base: waste after placement, damped quadratically (small dead space is fine).
    let mut score = pr + 0.9 * (pr * pr) / cap;

    // Reward tight fits smoothly: subtract a bump centered at low post_residual.
    let tightness = (1.0 - pr / cap).powi(3);
    score -= 12.0 * tightness * (1.0 + progress);

    // Penalize post residual that cannot fit the lookahead item (smooth coupling).
    if next_item_size > 0 {
        let gap = (next_item_size as f64 - pr).max(0.0);
        score += 0.6 * gap * (1.0 - progress);
        // Reward residual that exactly accommodates the next item.
        let match_bonus = (pr - next_ratio * cap).abs();
        score -= 4.0 * (1.0 - match_bonus / cap).max(0.0) * (1.0 - fit_ratio);
    }

    // Last-chance bin: strongly reward using it (avoid opening new bins).
    if fitting_bins_count == 1 {
        score -= 8.0 + 6.0 * progress;
    }

    // Late stream: prefer consolidating into existing bins, penalize fragmentation.
    score += progress * 2.0 * (pr / cap) * (pr / cap);

    // Coupling with mean residual: bins far below mean residual are attractive.
    score -= 1.5 * (mean_residual - pr) / cap;

    // Mild penalty scaled by number of open bins to discourage spreading.
    score += 0.05 * open_bins_count as f64 * (pr / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: exact-fill and tiny dead-space classes are gold.
    let post = post_residual;
    if post == 0 {
        score -= 1000.0; // perfect fit
    } else if post <= 5 {
        score -= 300.0;
    } else if post <= 10 {
        score -= 100.0;
    }

    // Modulo arithmetic on post_residual: residuals that are harmonic multiples
    // of common small item sizes (10..=20) are reusable.
    let harmonic_bonus = (2..=10).map(|k| {
        let m = post % (k * 10);
        if m == 0 { 60.0 } else if m <= 5 { 20.0 } else { 0.0 }
    }).sum::<f64>();
    score -= harmonic_bonus;

    // Penalize dead space relative to bin capacity fraction.
    let frac = post as f64 / bin_capacity as f64;
    score += frac * frac * 120.0;

    // Lookahead coupling: if next item fits the post residual, big reward.
    if next_item_size > 0 && next_item_size <= post {
        let slack = post - next_item_size;
        score -= 150.0 - slack as f64 * 1.5;
    } else if next_item_size > post && next_item_size > 0 {
        score += 40.0; // this bin can't serve the next item
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 250.0;
    }

    // New-bin candidate: only attractive when existing bins are congested
    // or mean residual is very low (nothing useful left).
    if bin_residual == bin_capacity {
        let congestion = open_bins_count as f64;
        let desperation = (mean_residual - item_size as f64).max(0.0);
        score = 60.0 + congestion * 2.0 - desperation * 3.0;
        if fitting_bins_count == 0 {
            score -= 500.0;
        }
        if fitting_bins_count == 1 {
            score += 300.0; // don't abandon the last usable bin
        }
    }

    // Mild pressure to consolidate across many open bins.
    score += open_bins_count as f64 * 1.5;

    // Stream progression: early on, be picky about waste; late, prioritize closing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (post as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: unusable small gaps are heavily penalized.
    // A residual that is too small for the smallest conceivable item (1) is pure
    // waste; a residual that is too small for typical items but nonzero is also
    // nearly useless. Penalize the "dead zone" non-linearly.
    if post_residual > 0 {
        // Dead zone: gap too small to be useful for anything but tiny items.
        if post_residual < 10 {
            score += 40.0 * (10.0 - post_residual as f64);
        } else if post_residual < 25 {
            score += 15.0 * (25.0 - post_residual as f64);
        }
        // Perfect fit bonus: leaving exactly zero residual is ideal.
        if post_residual == 0 {
            score -= 60.0;
        }
    } else {
        score -= 60.0;
    }

    // Reward closing the bin tightly relative to the current item's footprint:
    // high fill ratio is desirable.
    let fill = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= 25.0 * fill;

    // Open-bin pressure: with many open bins, prefer consolidating into existing
    // bins rather than spreading; penalize lightly proportional to open count.
    score += 0.8 * open_bins_count as f64;

    // Mean residual coupling: if this bin's residual is far below the mean, it is
    // already "full-ish"; placing here is good. If far above mean, penalize.
    let dev = bin_residual as f64 - mean_residual;
    score += 0.35 * dev;

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoid new-bin proliferation).
    if fitting_bins_count == 1 {
        score -= 45.0;
    }

    // New-bin candidate handling: an empty bin should only win when existing bins
    // fit poorly. Give the empty bin a baseline penalty that tight-fit bonuses on
    // real bins can overcome, but which scales with how many bins already fit.
    if bin_residual == bin_capacity {
        // Opening a new bin is costly when open bins are plentiful; also mild
        // penalty that grows over the stream (early on, opening is cheaper).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 + 25.0 * progress + 1.5 * fitting_bins_count as f64;
    }

    // Lookahead: if the next item fits exactly in this bin's post-residual, reward
    // placing the current item here (chain fit).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 35.0;
    }
    // If next item cannot fit in post-residual but could fit elsewhere, mild
    // penalty for stranding the next item's options.
    if next_item_size > post_residual && next_item_size > 0 {
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness: reward near-full packing.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 25.0 * tightness;

    // 2-step lookahead: if next item fits exactly or well in post_residual, big reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        let next_fit = 1.0 - ((post_residual - next_item_size) as f64) / (bin_capacity as f64);
        score -= 35.0 * next_fit;
        if post_residual == next_item_size {
            score -= 20.0; // perfect chaining
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        // dead space the next item cannot use
        score += 10.0 * ((post_residual as f64) / (bin_capacity as f64));
    }

    // Compare against mean residual: penalize leaving residual far above mean (wasteful bin).
    score += 0.3 * ((post_residual as f64) - mean_residual).max(0.0);
    score -= 0.15 * (mean_residual - (post_residual as f64)).max(0.0);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let pressure = (open_bins_count as f64).sqrt();
        let good_fit_exists = fitting_bins_count > 0 && (bin_residual - item_size) as f64 > mean_residual * 0.5;
        score += 15.0 + 8.0 * pressure;
        if good_fit_exists {
            score += 25.0; // discourage opening new bin when a decent fit exists
        }
        if fitting_bins_count == 0 {
            score -= 100.0; // must open new bin
        }
        // Late in stream, prefer consolidating into open bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Fractional progress through the stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Reward tight fits: strongly prefer small post_residual, superlinearly.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 3.0 * fit_ratio * fit_ratio * bin_capacity as f64;

    // Perfect fill is ideal.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Penalize leaving residual that is too small to hold even the smallest
    // future item (dead space), scaled by how much dead space it creates.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 2.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size < post_residual {
            // next item fits: mildly reward, more if it leaves little waste again.
            let second_waste = post_residual - next_item_size;
            score -= 10.0 - (second_waste as f64).min(10.0);
        } else {
            // next item would NOT fit here: penalize if it could have fit
            // had we placed slightly differently — mild penalty for blocking.
            score += 2.0;
        }
    }

    // Last-chance bin: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: opening a fresh bin should be penalized, but less so
    // when the item is large relative to capacity (poor fit elsewhere is likely)
    // and when few open bins exist.
    if bin_residual == bin_capacity {
        let item_frac = item_size as f64 / bin_capacity as f64;
        let mut new_bin_penalty = 18.0;
        // Large items waste less in a fresh bin.
        new_bin_penalty -= 12.0 * item_frac;
        // More open bins with slack -> prefer reusing them.
        new_bin_penalty += (open_bins_count as f64).sqrt() * 1.5;
        // If many bins fit the item, opening a new one is wasteful.
        if fitting_bins_count > 1 {
            new_bin_penalty += 6.0 * (fitting_bins_count as f64 - 1.0).min(4.0);
        }
        // Late in the stream, consolidation matters more.
        new_bin_penalty += 5.0 * progress;
        score += new_bin_penalty;
    }

    // Global slack coupling: if mean residual across open bins is large,
    // encourage packing into existing bins (penalize spread).
    if bin_residual != bin_capacity {
        let slack_gap = mean_residual - bin_residual as f64;
        score += 0.3 * slack_gap;
    }

    // Mild preference for fuller bins (smaller residual) beyond raw post_residual.
    score -= 0.05 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Base: waste after placement, smoothly normalized.
    let mut score = post / cap;

    // Non-linear penalty on dead space: small residuals are nearly useless.
    let dead = (post / cap).powi(3);
    score += 2.0 * dead;

    // Reward tight fits: smooth Gaussian-like bump near zero residual.
    let tightness = (-(post * post) / (2.0 * (0.15 * cap).powi(2))).exp();
    score -= 3.0 * tightness;

    // Lookahead coupling: penalize if post_residual cannot host next item.
    if next_item_size > 0 {
        let fits_next = if post_residual >= next_item_size { 1.0 } else { 0.0 };
        score -= 0.8 * fits_next * (post / cap);
        score += 0.5 * (1.0 - fits_next) * (1.0 + progress);
    }

    // Last-chance bonus: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 1.5 + progress;
    }

    // Crowding pressure: many open bins -> prefer filling existing ones.
    let crowd = (open_bins_count as f64).ln().max(0.0);
    score -= 0.1 * crowd * (1.0 - post / cap);

    // Mean residual alignment: prefer bins close to the mean residual (balance).
    let mean_gap = (post - mean_residual).abs() / cap;
    score += 0.3 * mean_gap * mean_gap;

    // New-bin candidate: empty bin should score worse than a decent fit,
    // but better than a terrible fit late in the stream.
    if bin_residual == bin_capacity {
        score += 1.2 + 0.5 * (1.0 - progress);
        score -= 0.3 * progress * (post / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: which "slot family" does the leftover fall into?
    let classes: [u32; 6] = [5, 10, 20, 25, 34, 50];
    let mut class_penalty = 0.0;
    for (i, &c) in classes.iter().enumerate() {
        if post_residual % c == 0 && post_residual > 0 {
            class_penalty = (i as f64) * 3.0; // finer classes (5,10) are more reusable
            break;
        }
    }
    score -= class_penalty;

    // Dead-space penalty: leftover too small for the smallest plausible item
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Perfect fit reward
    if post_residual == 0 {
        score -= 100.0;
    }

    // Lookahead coupling: does post_residual accommodate the next item?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= (next_item_size as f64) * 0.8;
        } else {
            score += (next_item_size as f64) * 0.3; // dead space relative to lookahead
        }
    }

    // Integer-division threshold on post_residual: leftover in [10,34] is prime reuse territory
    let half = post_residual / 2;
    if half >= 10 && half < 34 {
        score -= 8.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new one
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: make it attractive only when existing fits are poor
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = 55.0 + progress * 20.0;
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            score -= 30.0;
        }
        if fitting_bins_count == 1 {
            score += 60.0; // don't open new bin when a last-chance bin exists
        }
        if mean_residual > (item_size as f64) {
            score += 15.0; // existing space suffices on average
        }
    }

    // Slight preference for fuller bins overall
    score -= (1.0 - (bin_residual as f64) / cap) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small for typical future
    // items are nearly worthless; treat them as heavily penalized.
    let dead_threshold = 10.0;
    if post_residual > 0 && (post_residual as f64) < dead_threshold {
        score += 45.0 * (1.0 - post_residual as f64 / dead_threshold);
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 60.0;
    }

    // Reward tight fits generally (small post_residual relative to item size).
    score -= 0.8 * (item_size as f64 / (post_residual as f64 + 1.0));

    // Lookahead: if the next item fits exactly in the post-residual, reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 12.0;
        // Extra reward for near-exact chain fit.
        let gap = (post_residual - next_item_size) as f64;
        if gap < dead_threshold {
            score -= 10.0 * (1.0 - gap / dead_threshold);
        }
    }
    // If next item cannot use the leftover, mildly penalize large leftovers.
    if next_item_size > 0 && next_item_size > post_residual && post_residual > 0 {
        score += 4.0;
    }

    // Open-bin pressure: discourage scattering across many bins; prefer
    // filling existing bins when the fit is decent.
    score += 0.35 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Last-chance bin: if this is the only bin that fits, avoid opening a new
    // bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin by default; allow it only
    // when all existing fits would create bad dead space.
    if bin_residual == bin_capacity {
        score += 30.0;
        // Early in the stream, opening bins is cheaper.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 15.0 * (1.0 - progress);
        // If mean residual of open bins is large, spreading is fine.
        score -= 0.1 * mean_residual;
    }

    // Mean-residual coupling: prefer bins whose residual is near the mean
    // (keeps the bin pool homogeneous and predictable).
    score += 0.15 * ((bin_residual as f64 - mean_residual).abs());

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Dead-space penalty: residual that is too small to be useful (below min item size 1..100, treat <10 as dead)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // 2-step lookahead: reward if next item fits exactly into post_residual (perfect chain)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as f64 - nxt).abs() < 0.5 {
            score -= 40.0; // perfect next-fit
        } else if post_residual >= next_item_size {
            // next item fits: reward proportional to how much slack remains after the pair
            let pair_residual = post_residual as f64 - nxt;
            score -= 20.0 * (1.0 - pair_residual / cap);
        } else {
            // next item does NOT fit here: penalize leaving awkward space
            score += 8.0 * (nxt - post_residual as f64) / cap;
        }
    } else {
        // last item: prefer minimal residual
        score -= 10.0;
    }

    // Tightness reward: fill bins tightly relative to capacity
    score -= 15.0 * (item_size as f64 / cap);

    // Compare against mean residual: prefer bins whose post_residual is near/below mean (keeps balance)
    score += 0.3 * (post_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using the only bin that fits
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a new bin wastes capacity if an open bin fits well.
    if bin_residual == bin_capacity {
        // base cost of a fresh bin
        score += 5.0;
        if fitting_bins_count > 0 {
            // an existing bin can fit: only open new bin if existing fits are poor
            let best_existing = mean_residual;
            if best_existing >= item_size as f64 * 1.2 {
                score -= 20.0; // existing bins have lots of room, don't open new
            }
        }
        // early in stream, prefer consolidation; late, opening is fine
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * (1.0 - progress);
    }

    // Mild penalty per open bin to discourage bin proliferation
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where post_residual is small.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - tightness) * 25.0;

    // Penalize dead space quadratically for small residuals.
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Lookahead coupling: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0 + 0.15 * next_item_size as f64;
        } else {
            score += 6.0;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Time horizon: early in stream, be conservative (avoid fragmenting bins);
    // later, prefer closing bins out (fill them fully).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * post_residual as f64 * 0.3;
    score -= progress * 10.0;

    // Global state: if many bins open with high mean residual, prefer filling
    // existing bins rather than opening new ones.
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize unless nothing else fits well.
        score += 15.0 + open_bins_count as f64 * 2.0;
        if mean_residual > item_size as f64 * 1.5 {
            score += 10.0;
        }
    } else {
        // Existing bin: slight reward scaled by how much it reduces mean residual.
        score -= (mean_residual - post_residual as f64).max(0.0) * 0.5;
    }

    // Prefer bins with residual close to item_size (perfect fit detection).
    let fit_gap = (bin_residual - item_size) as f64;
    score -= (-fit_gap * fit_gap / 200.0) + 8.0 * (-fit_gap.abs() / 10.0).exp();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let prog2 = progress * progress;
    let prog3 = prog2 * progress;
    score -= 18.0 * norm_pr * (1.0 - progress) * (1.0 + prog2);
    score += 10.0 * norm_pr * norm_pr * (0.5 + prog3);

    // Reward tight fits via smooth cubic of fill ratio
    let fill = 1.0 - norm_pr;
    score -= 14.0 * fill * fill * fill * (1.0 + progress);

    // Penalize dead space that cannot fit the lookahead item
    if next_item_size > 0 {
        let gap = pr - next_item_size as f64;
        if gap > 0.0 {
            let wasted = gap / cap;
            score += 22.0 * wasted * wasted * (1.0 + prog2);
        } else {
            score -= 8.0 * (-gap / cap) * (1.0 - progress);
        }
    }

    // Last-chance bin bonus (smoothly weighted by progress)
    if fitting_bins_count == 1 {
        score -= 25.0 + 20.0 * progress;
    }

    // Mild pressure to consolidate when many bins are open
    let open_norm = open_bins_count as f64 / (1.0 + open_bins_count as f64);
    score += 6.0 * open_norm * norm_pr * (0.5 + progress);

    // Deviation from mean residual: prefer bins near the mean
    let dev = (pr - mean_residual) / cap;
    score += 5.0 * dev * dev;

    // Slight preference for larger items filling bins deeply
    score -= 4.0 * norm_item * (1.0 - norm_pr);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: residuals grouped by integer division
    // into classes of width 10 (capacity fraction classes).
    let class_width = 10u32;
    let post_class = post_residual / class_width;
    let exact_fit = (post_residual == 0) as i32;

    // Reward exact and tiny leftovers (perfect packing classes).
    if exact_fit == 1 {
        score -= 60.0;
    } else if post_class == 0 {
        score -= 25.0; // leftover < 10: dead space class, but small
    } else if post_class == 1 {
        score -= 8.0;
    } else if post_class == 2 {
        score += 6.0; // mid-range leftover ~20-29: moderately useful
    } else {
        score += 12.0; // large leftover: wasteful unless reusable
    }

    // Modulo-arithmetic coupling: leftovers that are multiples of common
    // item-size divisors are more reusable.
    if post_residual > 0 && item_size > 0 {
        let m = post_residual % item_size;
        if m == 0 {
            score -= 10.0;
        } else {
            score += (m as f64) * 0.5;
        }
    }

    // Lookahead: if the next item fits into the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 80.0;
        } else if next_item_size <= post_residual {
            // harmonic class match between next item and leftover class
            let next_class = next_item_size / class_width;
            let post_c = post_residual / class_width;
            if next_class == post_c {
                score -= 20.0;
            }
            score -= (next_item_size as f64) * 0.15;
        } else {
            // next item cannot use the leftover: penalize large leftovers more
            score += (post_residual as f64) * 0.1;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Avoid spreading across too many open bins when a tight fit exists.
    let tightness = (bin_residual - item_size) as f64 / (bin_capacity as f64);
    score += tightness * 10.0;

    // Slight bias toward filling older/more-filled bins as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 5.0;

    // Penalize deviating from mean residual (keep bins balanced).
    let mean_post = mean_residual - item_size as f64;
    score += (post_residual as f64 - mean_post).abs() * 0.05;

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 100.0;
        } else {
            // opening a new bin wastes the residual of the bin we skipped;
            // make it unattractive unless that residual is tiny (class 0).
            let best_possible = 100.0;
            score += best_possible;
            if post_class == 0 && fitting_bins_count == 1 {
                score -= 30.0;
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10 - post_residual) as f64;
    }
    if post_residual == 0 {
