    }

    // Reward tight fits relative to item size.
    score -= 0.5 * (item_size as f64 / bin_capacity as f64) * (bin_residual - post_residual).max(0) as f64;

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 50.0;
        } else if next_item_size > post_residual {
            // next item won't fit here; small gap penalty amplified
            if post_residual < 10 && post_residual > 0 {
                score += 20.0;
            }
        } else if post_residual - next_item_size < 10 {
            score += 15.0; // would create another dead gap
        }
    }

    // Open-bin pressure: discourage spreading across many bins.
    score += 2.0 * open_bins_count as f64;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Mean residual coupling: prefer bins below mean residual (tighter bins).
    score += 0.3 * (mean_residual - post_residual as f64);

    // New-bin candidate: only attractive when no open bin is a good fit.
    if bin_residual == bin_capacity {
        let bad_open = if fitting_bins_count == 0 { 0.0 } else { 25.0 };
        score += 15.0 + bad_open + 1.5 * open_bins_count as f64;
        // late in stream, prefer reusing bins even more
        score += 20.0 * (step_index as f64 / total_items.max(1) as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
