pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Base: best-fit core — prefer smallest post residual.
    let mut score = post_residual as f64;

    // Progress of the stream (0..1).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // ---- New-bin candidate handling ----
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Opening a new bin wastes the residual of all currently open bins.
        // Penalize proportionally to how much space is stranded in open bins.
        let stranded = if open_bins_count > 0 { mean_residual * open_bins_count as f64 } else { 0.0 };
        score += 60.0 + 0.6 * stranded;
        // Reward opening a new bin when nothing fits well elsewhere (last-chance pressure).
        if fitting_bins_count == 0 {
            score -= 80.0;
        } else if fitting_bins_count == 1 {
            score -= 30.0;
        }
        // Early in the stream, opening bins is cheaper (more items to come that may pair).
        score -= 25.0 * (1.0 - progress);
        // If the next item is large, a fresh bin with big residual is valuable.
        if next_item_size > 0 {
            let slack_after_next = if post_residual >= next_item_size { (post_residual - next_item_size) as f64 } else { 0.0 };
            score -= 0.4 * slack_after_next;
        }
        return score;
    }

    // ---- Open-bin scoring ----
    // Penalize large dead space nonlinearly (wasted capacity grows superlinearly).
    score += 0.02 * (post_residual as f64) * (post_residual as f64) / 100.0;

    // Perfect / near-perfect fit reward.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 10 {
        score -= 25.0;
    }

    // Lookahead coupling: if next item fits exactly in post residual, strong reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual > next_item_size {
            let gap = (post_residual - next_item_size) as f64;
            // Reward small gaps (next item leaves tiny remainder).
            score -= 15.0 * (1.0 - gap / 100.0);
        } else {
            // Next item cannot fit here; slight penalty proportional to overshoot.
            let over = (next_item_size - post_residual) as f64;
            score += 0.15 * over;
        }
    } else {
        // Last item: closing a bin tightly is all that matters.
        score -= 30.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoid stranding residual).
    if fitting_bins_count == 1 {
        score -= 35.0;
    }

    // Global pressure: many open bins with high mean residual -> tighten fits,
    // prefer bins below mean residual (consolidate fragmented space).
    if open_bins_count > 1 {
        let dev = bin_residual as f64 - mean_residual;
        score += 0.05 * dev;
        // Encourage consolidation when fragmentation is high.
        if mean_residual > 50.0 {
            score += 10.0;
        }
    }

    // Time horizon: late in the stream, prefer tighter fits to avoid opening bins
    // that will barely be used.
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let mut score = pr;

    // Normalize post_residual relative to capacity
    let pr_norm = pr / bin_capacity as f64;

    // Non-linear polynomial coupling: squared and cubic terms of post_residual
    // Penalize large residuals super-linearly (dead space is worse than it looks)
    score += 8.0 * pr_norm * pr_norm * (1.0 + progress);

    // Reward tight fits (small post_residual) with a smooth inverse coupling
    let tightness = (1.0 - pr_norm).powi(3);
    score -= 6.0 * tightness;

    // Lookahead: if next item fits into post_residual, reward this bin smoothly
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        let fill_after_next = (pr - next_item_size as f64) / bin_capacity as f64;
        score -= 5.0 * (1.0 - fill_after_next).powi(2);
    } else if next_item_size > 0 {
        // Next item won't fit here: mild penalty growing with stream progress
        score += 2.0 * progress;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
    }

    // Coupling with mean residual: bins far from the mean residual get a
    // smooth quadratic deviation penalty (encourages residual homogenization)
    let dev = pr - mean_residual;
    score += 0.03 * dev * dev / (1.0 + progress);

    // New-bin candidate: penalize smoothly, but relax penalty as progress
    // increases and open bins are few (sometimes spreading is better)
    if bin_residual == bin_capacity {
        let openness = (open_bins_count as f64).ln_1p();
        score += 12.0 - 4.0 * progress - 1.5 * openness;
    }

    // Mild stream-progress drift: later in stream, prefer filling existing
    // bins more aggressively (smooth linear interaction)
    score -= 3.0 * progress * (1.0 - pr_norm);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
