    // Residuals divisible by 10 (capacity fractions) are "reusable" classes.
    let cap_frac = (bin_capacity / 10) as f64; // 10
    let post = post_residual as f64;

    // Modulo-10 harmonic penalty: residual % 10 == 0 means item is a multiple of 10,
    // leaving a class-aligned residual likely reusable by future multiples of 10.
    if post_residual % 10 == 0 {
