    let slot_class = post_residual / 10; // which decile of capacity the residual sits in
    match slot_class {
        0 => score += 20.0,          // <10: dead space
        1 => score += 4.0,           // 10-19: only tiny items fit
        2 => score += 1.0,           // 20-29
        3 => score -= 2.0,           // 30-39: good mid-size slot
        4 => score -= 3.0,           // 40-49
        5 => score -= 4.0,           // 50-59
        _ => score -= 5.0,           // >=60: large usable slot
    }

    // Lookahead coupling: does the next item fit the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Harmonic match: next item's class aligns with residual class
            if next_item_size % 10 == post_residual % 10 {
                score -= 12.0;
            } else {
                score -= 5.0;
            }
            // Bonus if next item exactly fills post residual
            if next_item_size == post_residual {
                score -= 25.0;
            }
        } else {
            score += 8.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: prefer opening a new bin when all fits are poor.
    if bin_residual == bin_capacity {
        // Base reluctance: opening new bins is expensive.
        score = bin_capacity as f64 * cap_frac * 0.5 + 40.0; // ~90
        // But if the only alternative leaves <20 dead space, allow it.
        if fitting_bins_count == 0 {
