    // Strict dead-space avoidance: hard penalty for small unusable gaps.
    // A gap below the minimum item size (1..100 interface => treat < 8 as dead)
    // is wasted forever; penalize it steeply, non-linearly.
    if post_residual > 0 && post_residual < 8 {
        score += 40.0 + (8 - post_residual) as f64 * 6.0;
    }
    // Mid-range gaps that few items can still use are also risky.
    if post_residual >= 8 && post_residual < 20 {
        score += 8.0 + (20 - post_residual) as f64 * 0.8;
    }

    // Perfect fit reward: filling the bin completely is ideal.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post-residual,
    // strongly reward this placement (chain fill).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size <= post_residual {
            score -= (post_residual - next_item_size) as f64 * 0.15;
        } else {
            // Next item won't fit here: the leftover is more likely dead space.
            score += 2.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new one
    // unless the fit is terrible.
    if fitting_bins_count == 1 && post_residual < bin_capacity as f64 {
        score -= 6.0;
    }

    // Open-bin pressure: many open bins -> prefer consolidating into existing
    // bins to allow closing streams; few open bins -> tolerate new bins less.
    let pressure = open_bins_count as f64 * 0.35;
    // New-bin candidate gets the pressure penalty plus a mild exploration bonus
    // so it only wins when fits are bad.
    if bin_residual == bin_capacity {
        score += pressure - 5.0;
    } else {
        score -= 5.0; // reward using an existing bin slightly
    }

    // Progress-aware tightness: later in the stream, squeeze harder on wasted space.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * 0.1 * progress;

    // Deviation from mean residual: prefer bins whose residual is already tight
    // (small residual means the item fills a large fraction).
    if bin_residual > 0 {
        let fill_fraction = item_size as f64 / bin_residual as f64;
        score -= fill_fraction * 10.0;
    }
    if (bin_residual as f64 - mean_residual).abs() > 30.0 {
        score += 1.5; // mild penalty for anomalous bins
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress factor: early in stream, be more conservative; later, exploit existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Two-step lookahead: reward if the next item exactly fills the post residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            // Perfect chain: this placement sets up an exact fit next step.
            score -= 40.0;
        } else if next_item_size <= post_residual {
            // Next item still fits here: partial reward scaled by tightness.
            let tight = next_item_size as f64 / post_residual as f64;
            score -= 10.0 + 20.0 * tight;
        } else {
            // Next item won't fit: penalize wasted potential, scaled by how close it was.
            let miss = (next_item_size - post_residual) as f64;
            score += 5.0 + miss.min(50.0);
        }
    } else {
        // Last item: prefer minimal residual as usual.
        score += 0.0;
    }

    // Reward tight fits overall.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 15.0 * fill_ratio * fill_ratio;

    // Penalize creating dead space below the minimum item size (unusable gap).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Compare against mean residual: prefer bins tighter than average.
    if mean_residual > 0.0 {
        let rel = post_residual as f64 / mean_residual;
        score += 8.0 * (rel - 1.0);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive early in the stream or when open bins are crowded.
    if bin_residual == bin_capacity {
        let crowding = open_bins_count as f64 / (mean_residual / bin_capacity as f64).max(0.5);
        let bias = 35.0 - 25.0 * progress - 5.0 * (open_bins_count as f64).ln().max(0.0);
        score += bias + 0.5 * crowding;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let resid = bin_residual as f64;
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Core: prefer small post-residual (tight fit).
    let mut score = post;

    // Waste ratio: penalize leaving large unusable gaps relative to capacity.
    score += (post / cap).powi(3) * 40.0;

    // Dead-space penalty: if post-residual is too small for the smallest plausible future item.
    if post > 0.0 && post < 10.0 {
        score += 25.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            score -= 15.0 * (1.0 - (post - nxt) / cap);
        } else {
            score += 8.0 * (1.0 - post / nxt.max(1.0));
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a new bin is costly early, cheap late.
    let is_new_bin = bin_residual == bin_capacity && post == resid - item_size as f64;
    if is_new_bin {
        let open_pressure = (open_bins_count as f64 / (1.0 + mean_residual / cap.max(1.0))).ln();
        score += 20.0 + open_pressure * 10.0 - t * 15.0;
        // Opening a new bin is fine if no existing bin gives a decent fit.
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
    }

    // Global fragmentation: if mean residual is high, encourage consolidating into fuller bins.
    score += (mean_residual - post) * 0.15;

    // Slight preference for bins with less residual overall (pack tightly).
    score += resid * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Non-linear waste penalty: quadratic in normalized post residual
    let norm_pr = pr / cap;
    score += 40.0 * norm_pr * norm_pr;

    // Smooth coupling of waste with stream progress: late stream punishes waste harder
    score += 30.0 * norm_pr * norm_pr * progress * (1.0 - progress) * 4.0;

    // Reward tight fits with smooth saturating term
    let tightness = 1.0 - norm_pr;
    score -= 25.0 * tightness * tightness;

    // Lookahead: reward if next item fits in post residual (smooth logistic-like)
    if next_item_size > 0 {
        let fits = (post_residual >= next_item_size) as i32 as f64;
        let ratio = next_item_size as f64 / pr.max(1.0);
        score -= 18.0 * fits * (1.0 - ratio).max(0.0);
        score += 10.0 * (1.0 - fits) * ratio.min(1.0);
    }

    // Last-chance bin bonus (smooth in fitting_bins_count)
    let last_chance = 1.0 / (fitting_bins_count as f64);
    score -= 15.0 * last_chance * tightness;

    // New-bin candidate penalty: opening a new bin should be costly unless waste unavoidable
    let is_new_bin = (bin_residual == bin_capacity) as i32 as f64;
    score += 60.0 * is_new_bin * (1.0 - tightness * tightness);

    // Mild pressure to consolidate into fewer bins as stream progresses
    score += 0.5 * open_bins_count as f64 * progress * norm_pr;

    // Alignment of bin residual with mean residual (prefer typical bins)
    score += 0.05 * (pr - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: exact fill is perfect.
    if post_residual == 0 {
        score -= 200.0;
    }

    // Harmonic classes of post_residual: residuals divisible by small
    // capacity fractions (e.g. 10, 20, 25, 50) are more reusable.
    let r = post_residual;
    let mut harmonic_bonus = 0.0;
    if r > 0 {
        if r % 50 == 0 { harmonic_bonus += 25.0; }
        else if r % 25 == 0 { harmonic_bonus += 18.0; }
        else if r % 20 == 0 { harmonic_bonus += 14.0; }
        else if r % 10 == 0 { harmonic_bonus += 10.0; }
        if r % 5 == 0 { harmonic_bonus += 4.0; }
    }
    score -= harmonic_bonus;

    // Lookahead coupling: reward leaving exactly next_item_size,
    // or a harmonic superset of it.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            let gap = post_residual - next_item_size;
            if gap % 10 == 0 && gap <= 30 {
                score -= 20.0;
            }
        } else {
            // Next item cannot use this residual class: mild penalty.
            score += 8.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 90.0;
    }

    // Dead-space penalty: small awkward residuals (1..=9) are hard to fill.
    if post_residual > 0 && post_residual < 10 {
        score += 35.0;
    }

    // New-bin candidate handling: penalize opening a fresh bin unless
    // no good alternative exists.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let mut new_bin_penalty = 120.0;
        // Early in stream, new bins are cheaper (more future items to fill them).
        new_bin_penalty *= 1.0 - 0.4 * progress;
        // Many open bins: prefer filling existing ones.
        new_bin_penalty += 6.0 * open_bins_count as f64;
        // If several bins fit, definitely prefer them over a new bin.
        if fitting_bins_count > 1 {
            new_bin_penalty += 40.0;
        }
        // Large item leaving a large hole in a fresh bin is fine later;
        // small item in a fresh bin wastes capacity.
        if item_size < 40 {
            new_bin_penalty += 25.0;
        }
        score += new_bin_penalty;
    } else {
        // Prefer bins whose residual is close to the item (waste minimization).
        let tightness = (bin_residual - item_size) as f64 / bin_capacity as f64;
        score += 15.0 * tightness;

        // Prefer bins with residual below mean residual (consolidate small holes).
        if (bin_residual as f64) < mean_residual {
            score -= 6.0;
        }
    }

    // Slight preference for older bins (close them out).
    if bin_residual < bin_capacity {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small for typical items are wasted.
    let dead_threshold = 20.0;
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += (dead_threshold - post_residual as f64) * 3.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    if item_size > 0 {
        let tightness = 1.0 - (post_residual as f64) / (bin_residual as f64);
        score -= tightness * item_size as f64 * 0.8;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead: if next item fits in the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0 + next_item_size as f64 * 0.2;
    }
    // If next item cannot fit, penalize slightly (dead space for the future).
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 5.0;
    }

    // Open bins pressure: discourage spreading across many bins.
    score += open_bins_count as f64 * 0.5;

    // Mean residual coupling: prefer bins whose residual is near the mean
    // (keeps a balanced pool), penalize outliers.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.3;

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when open bins would leave bad fits.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, softened as stream progresses.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score = bin_capacity as f64 * (1.0 + 0.3 * (1.0 - progress));
        // If no open bin fits well, opening is reasonable.
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
        if open_bins_count == 0 {
            score -= 100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer exact or near-exact matches with the next item (2-step lookahead).
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score += 0.35 * gap;
        if post_residual == next_item_size {
            score -= 25.0; // perfect chain: this bin absorbs the next item exactly
        } else if post_residual >= next_item_size {
            score -= 8.0; // next item still fits here, good continuation
        } else {
            // dead space relative to lookahead: penalize proportionally
            score += 0.5 * (next_item_size - post_residual) as f64;
        }
    } else {
        // Last item: only the final leftover matters.
        score += 0.2 * post_residual as f64;
    }

    // Reward tight fits (small post_residual) relative to mean residual of open bins.
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // Penalize creating very small unusable slivers (< 10, minimum item size),
    // unless the lookahead item fills them.
    if post_residual > 0 && post_residual < 10 && post_residual != next_item_size {
        score += 20.0;
    }

    // Mild preference for filling bins in later stages of the stream (consolidation).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 3.0 * progress;

    // Slight penalty when many bins are already open: encourage consolidation.
    score += 0.15 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: prefer bins where the item fills a large fraction of residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize leaving awkward dead space (small but nonzero post-residual).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else if post_residual > 0 {
            score += 6.0;
        }
        // Bonus if post-residual exactly accommodates next item tightly.
        if post_residual == next_item_size {
            score -= 10.0;
        }
    }

    // Last-chance pressure: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // mean residual across open bins is small (bins nearly full) or no real bin fits well.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let openness = mean_residual / bin_capacity as f64;
        // Penalize new bins when existing bins still have plenty of room.
        score += 20.0 + 40.0 * openness;
        // Slight discount late in the stream to keep consolidation.
        score -= 10.0 * progress;
        // If many bins are open, discourage spreading further.
        score += 2.0 * (open_bins_count as f64).sqrt();
    } else {
        // Prefer bins below mean residual (filling emptier bins first keeps balance).
        let diff = mean_residual - bin_residual as f64;
        score += 0.05 * diff;
    }

    // Mild preference for bins with larger residual among equals (keep small slivers usable later).
    score -= 0.02 * bin_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let norm_pr = pr / cap;
    let p_term = norm_pr * norm_pr * (0.5 + progress) + norm_pr * (1.0 - progress) * 0.5;
    score += 10.0 * p_term;

    // Penalize dead space relative to mean residual (smooth quadratic)
    let dr = pr - mean_residual;
    score += 0.05 * dr * dr / cap;

    // Lookahead: reward if next item fits the post residual (smooth coupling)
    if next_item_size > 0 {
        let fits = (next_item_size as f64 <= pr) as i32 as f64;
        let tight = 1.0 - ((next_item_size as f64 - pr).abs()) / cap;
        score -= 15.0 * fits * (0.5 + 0.5 * tight);
        // penalize leaving gap just below next item size (smooth bump)
        let gap = pr - next_item_size as f64;
        if gap > 0.0 && gap < 10.0 {
            score += (10.0 - gap) * (1.0 - progress);
        }
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 20.0 * (1.0 - progress);
    }

    // Early stream: prefer consolidating into fewer bins (smooth in open count)
    score += (open_bins_count as f64).ln().max(0.0) * (1.0 - progress) * 2.0;

    // New-bin candidate: penalize unless post_residual would be large and stream early
    if bin_residual == bin_capacity {
        score += 5.0 - 30.0 * (1.0 - progress) * (item_size as f64 / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
