    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // New-bin candidate handling: an empty bin has large residual; make it attractive
    // only when the current bin would leave a very poor fit.
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        score += 5.0;
        if fitting_bins_count >= 1 && (post_residual as f64) < dead_threshold {
