            score -= 40.0;
        }
        // late in the stream, prefer consolidating into open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
    }

    // Mild preference to keep residuals near mean (balance load across bins).
    score += ((post_residual as f64) - mean_residual).abs() * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual near zero is good.
    score -= 12.0 * (1.0 - post_residual as f64 / bin_capacity as f64).powi(3);

    // Perfect fit bonus.
    if post_residual == 0 {
