        } else if next_item_size <= post_residual {
            // Next item fits but leaves slack; reward proportional to how full it gets.
            score -= 10.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // Next item won't use this bin's leftover; penalize dead space slightly.
            score += 0.05 * post_residual as f64;
        }
    }

    // Relative-to-mean coupling: bins with residual well below mean are scarce resources;
    // prefer using them for large items (small post_residual).
    if mean_residual > 0.0 {
