        score += 18.0
            - 15.0 * big_item
            - 5.0 * progress
            - (open_bins_count as f64).min(10.0) * 0.5;
        if fitting_bins_count > 0 && post_residual as f64 > 0.35 * bin_capacity as f64 {
            // An open bin already leaves comparable slack; discourage new bin.
            score += 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: strongly favor bins where item fills most of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 2.5 * fill_ratio * (bin_residual as f64);

    // Penalize large leftover dead space relative to capacity.
    let dead = post_residual as f64 / bin_capacity as f64;
    score += 3.0 * dead * dead * (bin_capacity as f64);

    // Lookahead coupling: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 0.6 * next_item_size as f64;
        } else {
            // post-residual too small for next item: mild penalty unless it's near-zero waste
            score += 0.3 * (next_item_size as f64 - post_residual as f64).min(20.0);
        }
        // Perfect chain: item + next item exactly fits residual
        if post_residual == next_item_size {
            score -= 5.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 4.0 + 0.05 * (bin_residual as f64);
    }

    // New-bin candidate handling: opening a new bin is costly; discourage unless
    // no open bin fits well (residual of this empty call is full capacity).
    if bin_residual == bin_capacity {
        // Base cost of a new bin, modulated by stream progress and open-bin load.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let mut new_bin_cost = 55.0;
        // Late in the stream, fewer items remain: reusing bins matters more.
        new_bin_cost -= 15.0 * progress;
        // Many open bins with slack: prefer reusing them.
        new_bin_cost += 1.5 * open_bins_count as f64;
        // If mean residual across open bins is large, opening new bin is bad.
        new_bin_cost += 0.4 * mean_residual;
        // If the item is huge, a fresh bin gives a clean fit.
        if item_size as f64 > 0.6 * bin_capacity as f64 {
            new_bin_cost -= 10.0;
        }
        score += new_bin_cost;
    }

    // Mild preference for bins with below-average residual (consolidate slack).
    score += 0.15 * (mean_residual - bin_residual as f64);

    // Time-horizon term: early in stream, be conservative with bin reuse quality.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 2.0 * (1.0 - progress) * dead;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let mut score = pr as f64;
    // Smooth non-linear coupling of post_residual with stream progress
    let poly = norm_pr * (1.0 - progress) + norm_pr * norm_pr * progress;
    score += 20.0 * poly * (1.0 - norm_pr);
    // Penalize large dead space more strongly later in the stream
    score += (norm_pr - 0.5) * (norm_pr - 0.5) * 30.0 * progress;
    // Reward tight fits (small post_residual) with a smooth saturating term
    score -= 15.0 * (1.0 - norm_pr) * (1.0 - norm_pr);
    // Last-chance bin: strong bonus to use it rather than open a new one
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }
    // Lookahead: penalize if post_residual cannot fit next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr < nx {
            score += 10.0 + 0.5 * (nx - pr);
        } else {
            score -= 5.0 * (1.0 - (pr - nx) / cap);
        }
    }
    // Mild preference for consolidating residual mass
    score -= 3.0 * ((pr - mean_residual) / cap);
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify leftover space into
    // capacity fractions (dead-space classes). Small post_residual is good.
    let cap = bin_capacity as f64;
    let post_f = post_residual as f64;
    let class = (post_f / cap * 8.0).floor(); // 0..7 harmonic class
    score += class * 4.0; // penalize larger leftover classes

    // Perfect / near-perfect fits get strong rewards.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 50.0;
    } else if post_residual <= 10 {
        score -= 25.0;
    }

    // Modular arithmetic on post_residual: leftovers divisible by small
    // integers are more likely reusable by future items.
    if post_residual > 0 {
        let reusable = (post_residual % 10 == 0) as i32
            + (post_residual % 5 == 0) as i32
            + (post_residual % 2 == 0) as i32;
        score -= 6.0 * reusable as f64;
    }

    // Lookahead coupling: reward if the next item fits exactly in the
    // post residual (chained fit); penalize if next item barely misses.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 80.0;
        } else if next_item_size < post_residual {
            let slack = post_residual - next_item_size;
            if slack <= 5 {
                score -= 30.0;
            } else {
                score -= (slack as f64).sqrt() * 2.0;
            }
        } else {
            // next item cannot use this bin's leftover: leftover risks waste
            score += (post_f - next_item_size as f64).abs().min(20.0);
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor it.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // New-bin candidate (empty bin): penalize opening a new bin unless the
    // item is large relative to capacity or open bins are crowded.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let crowding = open_bins_count as f64 / (mean_residual / cap + 1.0);
        score = cap as f64 * 1.5
            - item_size as f64 * 0.8
            - crowding * 3.0
            - progress * 5.0;
        // large items prefer fresh bins
        if item_size >= 60 {
            score -= 30.0;
        }
        // opening a bin when many bins fit the item is wasteful
        if fitting_bins_count > 3 {
            score += 25.0;
        }
    }

    // Mean residual coupling: prefer filling bins whose residual deviates
    // from the mean (reduce variance of leftovers).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score -= dev * 0.15;

    // Mild tightness reward: bins with less residual before placement are
    // naturally tighter fits.
    score += (bin_residual as f64 - post_f) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful
    // for typical items are heavily penalized (unusable gap).
    let min_item = 1.0f64;
    let gap = post_residual as f64;
    if gap > 0.0 && gap < min_item {
        score += 1000.0;
    }
    // General dead-space pressure: quadratic penalty scaled by how "unusable"
    // the leftover is relative to the smallest conceivable item.
    score += 0.8 * gap * gap / bin_capacity as f64;

    // Reward tight fits: the smaller the post_residual relative to the item,
    // the better the packing.
    let fill = item_size as f64 / bin_residual.max(1) as f64;
    score -= 15.0 * fill;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 2 {
        score -= 25.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: when many bins are open, discourage new bins and
    // encourage consolidating into existing ones.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are open or late in stream.
        score += 10.0 + 2.0 * open_bins_count as f64 + 20.0 * progress;
        // But if the next item would fit nicely in the fresh bin's residual,
        // opening a new bin can be attractive (lookahead pairing).
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 8.0 + next_item_size as f64 * 0.1;
        }
        // If no open bin gives a good fit (mean residual low), a new bin is fine.
        if mean_residual < item_size as f64 * 0.5 {
            score -= 12.0;
        }
    } else {
        // Slight preference for bins whose residual is close to the item (best fit).
        score += 0.05 * (bin_residual as f64 - item_size as f64);
        // Lookahead: reward bins where the next item also fits the leftover.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 5.0;
        }
        // Prefer bins below mean residual (concentrate filling).
        if (bin_residual as f64) < mean_residual {
            score -= 3.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches the next item
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack_after_pair = post_residual - next_item_size;
            score -= 2.0 * next_item_size as f64;
            score += 0.5 * slack_after_pair as f64;
            if slack_after_pair == 0 {
                score -= 500.0;
            }
        } else {
            // next item cannot follow in this bin; penalize small post_residuals
            // that become dead space
            let dead = post_residual as f64;
            if dead < 10.0 {
                score += 300.0 * (10.0 - dead);
            }
        }
    }

    // Compare against mean residual: bins with residual far above mean absorb
    // fragmentation better; penalize using a bin that is already tight.
    let dev = bin_residual as f64 - mean_residual;
    score += 0.3 * dev;

    // Last chance: strongly favor the only bin that can fit the item
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 400.0;
    }

    // New-bin candidate: keep it attractive only when current bins are fragmented
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = if open_bins_count > 0 {
            mean_residual / bin_capacity as f64
        } else {
            0.0
        };
        // Open a new bin when mean residual across open bins is too small to be useful
        score = 60.0 + 100.0 * (1.0 - fragmentation) - 50.0 * progress;
        if next_item_size > 0 && next_item_size >= item_size {
            // next item is big; fresh bin preserves space for it
            score -= 30.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: minimize post_residual relative to capacity.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= tightness * 30.0;

    // Penalize leaving residuals that are too small to be useful later,
    // unless they are exactly zero (perfect fit).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 20.0 + 0.25 * (next_item_size as f64);
        } else {
            score += 8.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: penalize opening a new bin when open bins
    // fit well, but allow it when the item fits poorly everywhere.
    if bin_residual == bin_capacity {
        let spread = (mean_residual - post_residual as f64).abs();
        if fitting_bins_count > 0 {
            score += 35.0 + spread * 0.1;
        } else {
            score -= 10.0;
        }
    }

    // Global state coupling: with many open bins, prefer consolidating into
    // bins with low residual (near-full bins) to close them out.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let bin_pressure = open_bins_count as f64 / 10.0;
    score += (mean_residual - post_residual as f64) * (0.05 + 0.05 * bin_pressure);

    // Early in the stream, be more tolerant of spreading across bins;
    // later, tighten packing to minimize residual waste.
    score += (1.0 - progress) * 5.0;

    // Slight preference for bins whose residual is close to the mean
    // (keeps the pool of residuals balanced for future items).
    score += 0.03 * (bin_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr_norm = pr / cap;

    // Base: waste left behind, with smooth non-linear shaping over stream progress.
    let mut score = pr * (1.0 + 0.6 * progress * progress);

    // Polynomial coupling: large residuals become more costly as the stream advances.
    let quad = pr_norm * pr_norm * (1.0 + 2.0 * progress);
    score += quad * cap;

    // Reward tight fits (small post_residual) with a smooth saturating bonus.
    let tight = 1.0 - pr_norm;
    score -= tight * tight * item_size as f64 * (0.4 + 0.4 * progress);

    // Last-chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0 + 15.0 * progress;
    }

    // Lookahead: if the next item fits the post_residual, reward this placement.
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 10.0 + 8.0 * (1.0 - pr_norm);
    }

    // Penalize spreading across many open bins; encourage consolidation.
    score += (open_bins_count as f64) * 0.5 * pr_norm;

    // New-bin candidate: keep neutral-ish, slightly favored when open bins are full-ish.
    if bin_residual == bin_capacity {
        score = pr + 20.0 - 15.0 * (mean_residual / cap).min(1.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core tight-fit reward: heavily discount bins that end up with small post_residual.
    let pr = post_residual as f64;
    score -= 90.0 * (1.0 - pr / bin_capacity as f64).powi(4);

    // Harmonic class logic on post_residual: residual classes divisible by common
    // item sizes (10..80 are multiples of 5/10) are reusable; odd remainders are dead space.
    let class5 = post_residual % 5;
    let class10 = post_residual % 10;
    if class5 == 0 {
        score -= 8.0; // aligns with common item granularity
    } else {
        score += 6.0 + class5 as f64; // penalize misaligned dead space
    }
    if class10 == 0 {
        score -= 5.0;
    }

    // Integer-division thresholds: post_residual buckets of 20.
    let bucket = post_residual / 20;
    score += match bucket {
        0 => -25.0, // nearly full bin, excellent
        1 => -10.0,
        2 => 0.0,
        3 => 8.0,
        _ => 15.0, // mostly empty bin, weak use
    };

    // Lookahead coupling: reward if next item fits the post_residual harmonically.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 18.0;
            if post_residual % next_item_size == 0 && post_residual > 0 {
                score -= 12.0; // perfect modular fill next step
            }
            let gap = (post_residual - next_item_size) as f64;
            score -= 10.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // next item won't fit here; small residual left behind is worse
            score += 4.0 + (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only attractive when open bins are congested or late stream.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let congestion = if open_bins_count > 0 {
            mean_residual / bin_capacity as f64
        } else {
            1.0
        };
        score = 55.0 + 25.0 * (1.0 - congestion) - 20.0 * progress;
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 5.0;
        }
    }

    // Mild dispersion penalty: avoid draining a bin far below mean residual when many bins fit.
    if fitting_bins_count > 2 {
        let dev = bin_residual as f64 - mean_residual;
        if dev > 0.0 {
            score += dev * 0.05;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for any
    // realistic future item (min size 1, but practically small gaps) are waste.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0; // unusable sliver
    } else if post_residual >= 10 && post_residual < 20 {
        score += 15.0; // only fits tiny items
    } else if post_residual == 0 {
        score -= 30.0; // perfect fit: fully packed bin
    }

    // Reward tight fits relative to item size.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * tightness;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: when many bins are open, discourage spreading into new bins.
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive if item fits poorly everywhere else.
        let spread_pressure = open_bins_count as f64 * 2.0;
        score += spread_pressure;
        // A new bin is fine if the next item is large (needs fresh space).
        if next_item_size > 60 {
            score -= 15.0;
        }
        // Late in the stream, avoid opening new bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
    } else {
        // Existing bin: slightly favor bins with residuals close to item needs.
        score += 0.1 * (mean_residual - bin_residual as f64).abs();
    }

    // Lookahead: if the next item fits exactly in the post residual, big reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 35.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        score += 5.0; // next item won't fit here anyway; less concern about leaving room
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when the next item exactly fills the residual.
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = (post_residual as i64 - next_item_size as i64) as f64;
        // Perfect match for next item: strong reward.
        if gap == 0.0 {
            score -= 200.0;
        } else {
            // Partial match: reward proportional to tightness of the 2-step fit.
            score -= 120.0 * (1.0 - gap / bin_capacity as f64);
        }
    } else if next_item_size > post_residual && next_item_size > 0 {
        // Next item cannot use this bin's leftover: penalize dead space creation.
        score += 40.0 * (post_residual as f64 / bin_capacity as f64);
    }

    // Prefer bins whose residual is already small (compact packing relative to mean).
    let dev = post_residual as f64 - mean_residual;
    score += 0.35 * dev;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // Penalize wasteful fits that leave very small unusable slivers.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // New-bin candidate (pristine empty bin): make it attractive only when
    // no open bin offers a good 2-step match; otherwise keep it mildly costly.
    if bin_residual == bin_capacity {
        let good_lookahead = next_item_size > 0 && next_item_size <= post_residual
            && (post_residual as i64 - next_item_size as i64) <= 15;
        if good_lookahead {
            score += 30.0; // an existing bin likely matched already; don't open new
        } else {
            score -= 60.0 + 0.5 * open_bins_count as f64; // fresh bin is fine
        }
    }

    // Mild late-stream bias toward tightening existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 20.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through the stream (0..1)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Perfect fit bonus: strongly favor filling a bin exactly.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Small residuals are valuable only if the next item can use them.
        if next_item_size > 0 {
            if next_item_size <= post_residual {
                // Residual remains usable: reward proportionally to its utility.
                score -= 5.0 + 10.0 * (next_item_size as f64 / post_residual as f64);
            } else {
                // Dead space: penalize small unusable leftovers, worse late in stream.
                let waste = post_residual as f64 / bin_capacity as f64;
                score += 8.0 * waste * (0.5 + progress);
            }
        }
    }

    // Tightness reward: the fuller the bin gets, the better (relative to capacity).
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 15.0 * fill_ratio * fill_ratio;

    // Last-chance bin: if this is the only open bin that fits, strongly prefer it
    // over opening a new bin, unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: only attractive when no good open option exists.
    if bin_residual == bin_capacity {
        // Base reluctance to open a new bin.
        score += 10.0;
        // More reluctance when many bins are already open (avoid bin proliferation).
        score += 2.0 * (open_bins_count as f64).sqrt();
        // If the item is large relative to capacity, opening a fresh bin is fine.
        score -= 12.0 * (item_size as f64 / bin_capacity as f64);
        // If mean residual across open bins is small, open bins are crowded:
        // a new bin becomes more attractive.
        score -= mean_residual * 0.15;
        // Lookahead: if next item is large, a fresh bin gives it room.
        if next_item_size > 0 && next_item_size > bin_capacity / 2 {
            score -= 6.0;
        }
    } else {
        // Prefer reusing bins whose residual is close to the item (best-fit sharpening).
        score += 0.3 * (mean_residual - bin_residual as f64).abs();
    }

    // Early-stream exploration: slightly favor consolidating into existing bins early,
    // favor tighter packing decisions later.
    score *= 1.0 + 0.1 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Non-linear waste penalty: dead space that is too small to be useful is heavily penalized.
    let waste_frac = pr / cap; // 0..1
    score += 40.0 * waste_frac * waste_frac * (1.0 + progress);

    // Reward tight fits (small post_residual) super-linearly.
    score -= 25.0 * (1.0 - waste_frac).powi(3);

    // Coupling with mean residual: prefer bins whose residual is below mean (compact bins first).
    let mr = mean_residual.max(0.0);
    let dev = (bin_residual as f64 - mr) / cap;
    score += 15.0 * dev * dev.abs();

    // Lookahead: if the next item could use this post-residual, reward saving it here.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            score -= 12.0 * (1.0 - (pr - nxt) / cap).abs();
        } else {
            score += 8.0 * ((nxt - pr) / cap);
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Late in the stream, prefer consolidating into existing bins rather than opening new ones.
    let open_f = open_bins_count as f64;
    score += (1.0 + progress) * (open_f / (open_f + 5.0)) * 10.0;

    // New-bin candidate: smooth sigmoid-ish gate — only attractive when fit in open bins is bad.
    let is_new = (bin_residual as f64 - cap).abs() < 1e-9;
    if is_new {
        // Neutral baseline; add penalty that shrinks as stream progresses / many bins open.
        score += 20.0 * (1.0 - progress * 0.5) * (open_f / (open_f + 10.0));
        // But if the item is huge relative to capacity, a fresh bin is natural.
        score -= 15.0 * (item_size as f64 / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: perfect-fit class heavily rewarded.
    let pr = post_residual as u32;
    if pr == 0 {
        score -= 60.0;
    } else if pr <= 10 {
        score -= 25.0;
    } else if pr <= 20 {
        score -= 10.0;
    } else if pr <= 30 {
        score += 5.0;
    } else {
        score += 12.0;
    }

    // Lookahead coupling: reward bins whose post_residual can host next item.
    if next_item_size > 0 && pr >= next_item_size {
        score -= 18.0 + 0.15 * (pr - next_item_size) as f64;
    }
    // Penalize near-miss: next item barely fails to fit (dead space risk).
    if next_item_size > 0 && pr > 0 && pr < next_item_size && next_item_size - pr <= 10 {
        score += 8.0;
    }

    // Tightness reward relative to capacity fractions.
    let tight = 1.0 - (post_residual as f64) / cap;
    score -= 20.0 * tight * tight;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: default unattractive; attractive only when open bins fit poorly.
    if bin_residual == bin_capacity {
        let base = 45.0;
        let scarcity = if fitting_bins_count == 0 { 0.0 } else { (fitting_bins_count as f64).min(4.0) * 8.0 };
        let big_item = if item_size > 50 { 10.0 } else { 0.0 };
        score = base + scarcity - big_item;
        if next_item_size > 0 && next_item_size > bin_residual - item_size {
            score -= 5.0; // next item can't fit current bins anyway
        }
    }

    // Mild pressure to consolidate as stream progresses.
    score += 0.02 * (step_index as f64 / total_items.max(1) as f64) * (post_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64) / 10.0;
    }

    // Reward perfect fits strongly.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Reward placements that leave room for the lookahead item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 10.0;
    }

    // Last-chance bin before opening a new one: strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Penalize opening new bins when open bins are underutilized.
    if bin_residual == bin_capacity {
        score += 30.0 + 5.0 * open_bins_count as f64;
        if mean_residual > 2.0 * item_size as f64 {
            score += 20.0;
        }
    } else {
        // Mild pressure: prefer bins with larger residuals when many bins open.
        score += 0.05 * open_bins_count as f64;
    }

    // Prefer tight fits relative to bin residual.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
