pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: quadratic penalty on wasted space.
    score += (post_residual as f64) * (post_residual as f64) / (bin_capacity as f64);

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless it's genuinely needed.
    if bin_residual == bin_capacity {
        let base_penalty = 25.0;
        // Cheaper to open new bins early in the stream.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += base_penalty * (0.5 + progress);
        // If many bins already fit the item, opening a new one is wasteful.
        if fitting_bins_count > 1 {
            score += 20.0;
        }
        // If the next item is small, a fresh bin is more valuable.
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 10.0;
        }
        // Penalize opening new bins when existing residuals are large.
        score += mean_residual * 0.3;
    }

    // Lookahead coupling: reward bins whose residual pairs well with the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0; // perfect pair
        } else if post_residual > next_item_size {
            let gap = post_residual - next_item_size;
            score += gap as f64 * 0.5; // prefer residual close to next item
        }
    }

    // Slight preference for bins with below-average residual (consolidate waste).
    score += (bin_residual as f64 - mean_residual) * 0.1;

    // Mild pressure to use open bins as their count grows.
    if bin_residual != bin_capacity {
        score -= (open_bins_count as f64).sqrt() * 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: post residual (waste), scaled by stream progress pressure.
    let mut score = post * (1.0 + 0.5 * progress);

    // Smooth polynomial coupling of post_residual with progress:
    // early on, tight fits matter less; later, minimize dead space aggressively.
    let post_norm = post / cap;
    score += 20.0 * post_norm * post_norm * (0.5 + progress);

    // Reward near-perfect fits: subtract bonus proportional to item fill fraction, coupled with progress.
    let fill = item_size as f64 / cap;
    score -= 30.0 * fill * fill * (1.0 - progress);

    // Last-chance bonus: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 25.0 + 15.0 * fill;
    }

    // Penalize bins with residuals much larger than mean (avoid hoarding space),
    // smooth quadratic coupling with mean residual.
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 10.0 * dev * dev;

    // Lookahead: if next item fits into post_residual, reward this placement.
    if next_item_size > 0 && (next_item_size as f64) <= post {
        score -= 8.0 + 10.0 * (next_item_size as f64 / cap);
    }

    // Mild penalty for spreading across many bins early (prefer consolidation).
    score += (open_bins_count as f64).ln() * 2.0 * (1.0 - progress);

    // New-bin candidate: make it attractive only when open bins would leave large waste.
    if bin_residual == bin_capacity {
        // Neutral base; competing bins with small post_residual will beat it.
        score = cap * (0.6 - 0.3 * progress) + 10.0 * dev.abs();
        if fitting_bins_count <= 1 {
            score -= 40.0; // if no real alternative, opening a bin is fine
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: heavily favor bins where the item nearly fills the bin.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 60.0 * fit_ratio * fit_ratio;

    // Harmonic class of post_residual: dead space that no future item (1..=100)
    // can perfectly fill is worse. Residuals that are multiples of common sizes
    // (10..80 grid) are more reusable.
    let pr = post_residual;
    if pr > 0 {
        let dead = if pr < 10 { 1.0 } else { 0.0 };
        score += 40.0 * dead;
        // Modulo-10 harmonic class: residuals divisible by 10 are reusable by
        // grid-aligned items; penalize awkward classes more as they shrink.
        let class = pr % 10;
        if class != 0 {
            score += 4.0 + (10 - class) as f64 * 0.5;
        }
        // Integer-division thresholds: can a plausible next item fit?
        if next_item_size > 0 {
            if next_item_size <= pr {
                // Lookahead fits here: reward keeping room for it.
                score -= 25.0 * (next_item_size as f64 / pr as f64);
            } else {
                // Lookahead cannot use this residual: penalize proportionally.
                score += 10.0 * (next_item_size as f64 / bin_capacity as f64);
            }
        }
    } else {
        // Perfect closure: bin exactly filled.
        score -= 80.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when the
    // item is large relative to capacity or existing residuals are poor.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let spread = mean_residual - post_residual as f64; // how much better avg bins are
        let penalty = 55.0
            - 20.0 * (item_size as f64 / bin_capacity as f64)
            - 15.0 * progress
            + 0.6 * spread.max(0.0)
            + 2.0 * open_bins_count as f64;
        score += penalty.max(0.0);
    }

    // Mild preference to consolidate into bins with below-average residual
    // (balance load, keep large residual bins free for big future items).
    if bin_residual != bin_capacity {
        let dev = mean_residual - bin_residual as f64;
        score += 0.3 * dev;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize unusable small gaps: residuals too small to hold even the
    // smallest plausible item are pure dead space.
    if post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0;
    }

    // Reward tight fits strongly (small post_residual relative to item).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * tightness;

    // Penalize exact-fill waste only mildly; perfect fill is ideal.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Dead space relative to capacity: quadratic penalty on unusable fraction.
    let dead = post_residual as f64 / bin_capacity as f64;
    score += 30.0 * dead * dead;

    // Open-bins pressure: fewer open bins is better when fits exist;
    // penalize spreading across many bins.
    score += 1.5 * open_bins_count as f64;

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // Lookahead: if next item fits the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }
    // If next item would leave this bin stranded, penalize slightly.
    if next_item_size > post_residual && post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // Mean residual coupling: prefer bins below mean residual (tighter bins).
    score += 0.5 * (mean_residual - bin_residual as f64);

    // New-bin candidate: make empty bins moderately attractive only when
    // no open bin fits well (high post_residual elsewhere pushes score up),
    // but discourage needless new bins early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = 45.0 + 10.0 * progress + 2.0 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 8.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual relative to capacity.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Exact fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual can
    // accommodate the next item (chain packing), penalize near-miss dead space.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = post_residual - next_item_size;
            score -= 25.0 * (1.0 - slack as f64 / bin_capacity as f64);
        } else {
            let miss = (next_item_size - post_residual) as f64;
            score += 8.0 * (miss / item_size.max(1) as f64).min(1.5);
        }
    }

    // Compare against mean residual: bins with residual near mean are neutral;
    // bins far above mean (wastefully empty) are penalized for big items.
    let res_f = bin_residual as f64;
    if res_f > mean_residual + 10.0 && item_size < 40 {
        score += 6.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Penalize opening a new bin when decent existing fits exist.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 + 15.0 * (1.0 - progress);
        if next_item_size > 0 && post_residual < next_item_size {
            score += 10.0; // fresh bin wasted on this item
        }
    }

    // Mild bonus for keeping many bins active and balanced.
    score -= 0.5 * (open_bins_count as f64).ln().max(0.0) * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
