pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;

    // Base: tight fit is good (small post_residual), with a smooth
    // non-linear polynomial coupling to stream progress.
    // Early on, moderate residual waste is tolerated; late, waste is punished harder.
    let norm_post = post / cap;
    let base = post * (1.0 + 1.5 * progress * progress) + 40.0 * norm_post * norm_post * (0.5 + progress);

    // Reward near-perfect fits with a smooth saturating term.
    let fit_bonus = -30.0 * (-post / 12.0).exp();

    // Lookahead coupling: if the next item can use this post-residual, reward;
    // otherwise penalize residual that neither helps nor is tiny.
    let lookahead = if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            -20.0 * (1.0 - (post - nxt) / cap)
        } else {
            10.0 * ((nxt - post) / cap) * (1.0 + progress)
        }
    } else {
        0.0
    };

    // Last-chance bin: strongly favor using the only fitting bin.
    let last_chance = if fitting_bins_count == 1 { -25.0 } else { 0.0 };

    // Penalize crowding when many bins are open with high mean residual
    // (encourages consolidation into fuller bins).
    let consolidation = (mean_residual - post) * 0.15 * (open_bins_count as f64).ln().max(1.0);

    // New-bin candidate (empty bin): penalize unless it is genuinely better.
    // Scale penalty down as progress grows (late items may warrant fresh bins).
    let is_new_bin = (bin_residual as f64 - cap).abs() < 0.5;
    let new_bin_penalty = if is_new_bin {
        60.0 + 25.0 * (1.0 - progress) + item * 0.2
    } else {
        0.0
    };

    base + fit_bonus + lookahead + last_chance + consolidation + new_bin_penalty
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover matches common
    // item-size classes (multiples of 10 / small values) are more reusable.
    let class = if post_residual == 0 {
        0.0
    } else if post_residual <= 10 {
        1.0
    } else if post_residual % 10 == 0 {
        2.0
    } else if post_residual % 5 == 0 {
        3.0
    } else {
        4.0
    };
    score += class * 4.0;

    // Reward when the leftover can exactly host the lookahead item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 12.0;
        } else if post_residual >= next_item_size {
            score -= 4.0 - (post_residual - next_item_size) as f64 / 20.0;
        } else {
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Penalize opening a brand-new bin unless current bins are nearly full.
    if bin_residual == bin_capacity {
        let pressure = mean_residual / bin_capacity as f64;
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 30.0 + 40.0 * (1.0 - pressure) - 10.0 * progress;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // pairing large items into fresh bins is fine
        }
    }

    // Slight preference for filling bins that are already quite full.
    let fullness = 1.0 - bin_residual as f64 / bin_capacity as f64;
    score -= 6.0 * fullness;

    // Mild penalty for leftover that no typical item (>=10) can use.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small for the smallest
