    }

    // Dead space is worse if the gap cannot fit the lookahead item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 10.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 5.0;
    }

    // Open-bin pressure: discourage spreading across many bins; favor
    // consolidating into existing bins, but allow new bins when existing
    // fits are poor (large post_residual).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.15 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: make it moderately unattractive unless existing
    // placements leave big dead space.
    if bin_residual == bin_capacity {
        score += 12.0;
    }

    // Deviation from mean residual: prefer bins whose residual is closer to
    // the item, avoiding both huge and tiny residuals.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Tight fit: small relative waste
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 8.0 * tightness * (item_size as f64 / bin_capacity as f64);

    // 2-step lookahead: reward bins whose post_residual matches next item
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual >= next_item_size {
            let gap = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // next item won't fit here; penalize proportionally to leftover
            score += 10.0 * (next_item_size as f64 - post_residual as f64) / bin_capacity as f64;
        }
    }

    // Relative to mean residual: prefer filling below-average-residual bins
    score += 3.0 * (bin_residual as f64 - mean_residual) / bin_capacity as f64;

    // Last chance: strongly favor the only bin that fits
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // New-bin candidate handling: only attractive when open bins fit poorly
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let poor_fit_penalty = if post_residual > 0 { 20.0 + post_residual as f64 * 0.3 } else { 0.0 };
        score = (bin_capacity as f64) + poor_fit_penalty - 15.0 * progress;
    }

    // Slight penalty for opening many bins
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (non-linear in post_residual).
    let tightness = (bin_residual - post_residual) as f64 / bin_capacity as f64;
    score -= 30.0 * tightness * tightness;

    // Penalize leaving residual that is small-but-unusable for typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead coupling: reward if next item can fit into post_residual.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 15.0;
        } else {
            // Penalize residuals that block the next item only marginally.
            let gap = (next_item_size - post_residual) as f64;
            if gap < 10.0 {
                score += 8.0;
            }
        }
    }

    // Global state: when many bins are open with high mean residual,
    // discourage opening a new bin (new-bin candidate gets residual == capacity).
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 20.0 + 0.5 * open_bins_count as f64 - 0.1 * mean_residual;
        // Late in the stream, closing out bins is preferable to opening new ones.
        score -= 10.0 * progress;
    } else {
        // Favor bins with residual far below the mean (they are nearly full).
        if (bin_residual as f64) < mean_residual {
            score -= 5.0;
        }
    }

    // Mild entropy-free exploration term: prefer mid-life bins slightly.
    score += 0.01 * (open_bins_count as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;
    let is_new_bin = (bin_residual == bin_capacity) as f64;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = pr_norm * (1.0 + 2.0 * progress * pr_norm + 3.0 * progress * progress * pr_norm * pr_norm);

    // Tight fit reward: strongly favor small post residuals
    let tight_fit = -(1.0 - pr_norm).powi(3) * 30.0;

    // Dead-space penalty grows with stream progress (less time to fill leftovers)
    let dead_space = pr_norm * pr_norm * (1.0 + progress) * 15.0;

    // Last-chance bonus: strongly prefer the only fitting bin
    let last_chance = if fitting_bins_count == 1 && is_new_bin == 0.0 { -25.0 } else { 0.0 };

    // Lookahead: reward if next item can fit in the post residual
    let lookahead = if next_item_size > 0 && (next_item_size as f64) <= pr {
        -10.0 * (next_item_size as f64 / cap)
    } else {
        pr_norm * 5.0
    };

    // New bin candidate: penalize mildly, more so early in the stream; relax late
    let new_bin_pen = is_new_bin * (10.0 + 15.0 * (1.0 - progress) + open_bins_count as f64 * 0.5);

    // Mean residual coupling: prefer bins deviating from mean residual (consolidation)
    let mean_coupling = ((bin_residual as f64 - mean_residual) / cap) * 5.0 * (1.0 - is_new_bin);

    let mut score = poly * 20.0 + tight_fit + dead_space + last_chance + lookahead + new_bin_pen + mean_coupling;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: dead space that is "usable"
    // for common item sizes should be rewarded less harshly.
    let pr = post_residual;
    let harmonic_usable = (pr >= 10 && pr <= 80) || pr == 0;
    if harmonic_usable {
        score -= 6.0;
    } else if pr > 0 {
        // dead space in (1..10) or awkward slivers
        score += 4.0;
    }

    // Modulo-class coupling: does post_residual pair with the lookahead item?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // lookahead fits exactly into the remainder -> strong reward
            score -= 10.0;
            if pr == next_item_size {
                score -= 8.0; // perfect packing of the pair
            }
        } else {
            // lookahead cannot use this bin's remainder; penalize proportionally
            score += (next_item_size - pr) as f64 * 0.15;
        }
        // harmonic class: does next_item_size divide into post_residual's
        // integer-division structure (e.g. 2x or 3x chunking)?
        if pr >= 2 * next_item_size && pr <= 3 * next_item_size {
            score -= 3.0;
        }
    }

    // Fraction-of-capacity thresholds on post_residual
    let frac = post_residual as f64 / cap;
    if frac < 0.1 {
        score += 5.0; // nearly full bin: fine, but tiny slivers are waste
    } else if frac > 0.6 {
        score += 2.0; // leaving a big hole is wasteful when item fits elsewhere
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // New-bin candidate: only attractive when no good fit exists
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        score = cap * 0.9;
        if fitting_bins_count == 0 {
            score -= cap; // must open
        } else if fitting_bins_count == 1 {
            // last chance bin exists: prefer it unless it would be a terrible fit
            if post_residual as f64 / cap > 0.5 {
                score -= 5.0;
            }
        }
        // late in the stream, avoid proliferating bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
        // many open bins with high mean residual -> keep compacting instead
        if mean_residual > 30.0 && open_bins_count > 2 {
            score += 15.0;
        }
    }

    // Mild compaction pressure: prefer bins tighter than the mean
    if (bin_residual as f64) < mean_residual {
        score -= 1.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small nonzero gaps are useless.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 40.0;
    } else {
        // Reward tighter fits smoothly.
        score -= (1.0 - (post_residual as f64) / (bin_capacity as f64)) * 15.0;
    }

    // Dead-space relative to capacity: quadratic penalty for small gaps.
    let gap_frac = post_residual as f64 / bin_capacity as f64;
    if gap_frac > 0.0 && gap_frac < 0.15 {
        score += 50.0 * (0.15 - gap_frac) / 0.15;
    }

    // Open bins pressure: discourage spreading across many bins.
    score += open_bins_count as f64 * 2.5;

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: reward leaving room for the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else if post_residual > 0 {
            score += 15.0; // leaves a gap that cannot fit the next item
        }
    }

    // Mean residual coupling: prefer bins below mean residual (tighter bins).
    score += (mean_residual - post_residual as f64) * 0.3;

    // Progress: as stream nears end, be less eager to open new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses.
        score += 20.0 + 30.0 * progress + open_bins_count as f64 * 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Perfect fit: strongly reward leaving zero waste.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Aggressive 2-step lookahead: does the next item fit in the leftover?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward chains where the next item can also be placed here.
            // Reward is slightly stronger early in the stream (more future to benefit).
            score -= next_item_size as f64 * (1.1 - 0.4 * progress);
        } else {
            // Leftover is dead space with respect to the next item:
            // penalize proportional to the mismatch gap.
            let gap = (next_item_size - post_residual) as f64;
            score += gap * (0.4 + 0.3 * progress);
        }
    }

    // Last-chance bonus: if this is the only open bin that fits the item,
    // strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Consolidation pressure: mildly penalize placing into bins whose residual
    // is much larger than the mean (keeps nearly-empty bins for large items).
    let diff = bin_residual as f64 - mean_residual;
    if diff > 0.0 {
        score += 0.05 * diff;
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        let mut penalty = 20.0 + 0.3 * bin_capacity as f64;
        // If the item is large relative to typical open space, a fresh bin is
        // more acceptable; relax the penalty.
        if item_size as f64 > mean_residual {
            penalty -= 10.0;
        }
        // Late in the stream, avoid sprawling into new bins.
        penalty += 10.0 * progress;
        // If no open bin fits at all, opening a new bin is unavoidable-ish;
        // soften the penalty so it can win when it must.
        if fitting_bins_count == 0 {
            penalty -= 25.0;
        }
        score += penalty;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;

    // Base: prefer minimizing leftover space (tight fits win).
    let mut score = post;

    // Strong reward for near-perfect fits (post_residual small relative to capacity).
    let fit_ratio = post / cap;
    score -= (1.0 - fit_ratio).powi(6) * cap * 0.8;

    // Penalize residuals that are "awkward": too small for typical future items
    // but not zero (dead space). Dead-space zone: 1..=10 unusable slivers.
    if post > 0.0 && post < 12.0 {
        score += (12.0 - post) * 2.5;
    }

    // Lookahead coupling: if the next item could exactly fill this bin's
    // post_residual, big reward; if next item cannot fit into post_residual,
    // mild penalty only when other bins exist to absorb it.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (nxt - post).abs() < 1.0 {
            score -= cap * 1.5;
        } else if nxt > post {
            // next item won't fit here anyway; dead space is more acceptable
            score += 5.0;
        } else {
            // next item fits with some slack: reward proportional to combined fill
            score -= (cap - (post - nxt)) * 0.3;
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= cap * 2.0;
    }

    // New-bin candidate handling: only attractive when the item leaves a
    // large, reusable residual or few bins fit the item.
    if bin_residual == bin_capacity {
        // Opening a new bin: penalize mildly by default.
        score += cap * 0.6;
        // But if the item is large (leaves small residual) or many bins already
        // exist with high mean residual (fragmentation), new bin is fine.
        if item / cap > 0.6 {
            score -= cap * 0.9;
        }
        if open_bins_count > 0 && mean_residual > 40.0 {
            score -= mean_residual * 0.4;
        }
        // Early in the stream, opening bins is cheap and useful.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= (1.0 - progress) * cap * 0.3;
    }

    // Global fragmentation pressure: many open bins with high mean residual
    // -> discourage spreading, prefer consolidating into fuller bins.
    if open_bins_count > 3 {
        let fullness = 1.0 - bin_residual as f64 / cap;
        score -= fullness * open_bins_count as f64 * 1.5;
        score += mean_residual * 0.15;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // later in the stream, tight fits (small post_residual) are rewarded more strongly.
    let tightness = 1.0 - (post / cap).min(1.0);
    score -= 30.0 * tightness * tightness * (0.3 + 0.7 * progress);

    // Penalize large dead space super-linearly as stream progresses.
    score += 6.0 * (post / cap) * (post / cap) * (1.0 + 2.0 * progress);

    // Reward bins whose post-residual can still host the next item (lookahead coupling).
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        let fit_quality = (post_residual as f64 - next_item_size as f64) / cap;
        score -= 8.0 * (1.0 - fit_quality) * (0.5 + 0.5 * progress);
    } else if next_item_size > 0 {
        score += 4.0 * progress;
    }

    // Last-chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate: penalize mildly early, more when open bins are poorly utilized.
    if bin_residual == bin_capacity {
        score += 10.0 + 0.5 * open_bins_count as f64;
        // Allow opening a new bin late in the stream if existing residuals are large/wasteful.
        score -= 12.0 * (mean_residual / cap).min(1.0) * progress;
    }

    // Slight preference for bins with residual close to the mean (balanced packing).
    score += 0.05 * (post - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-fit residual: bins whose leftover falls into
    // "useful" modular classes (multiples of common item sizes) are rewarded.
    let pr = post_residual;
    let useful = if pr == 0 { 1.0 }
        else if pr <= 10 { 0.9 }
        else if pr % 20 == 0 || pr % 25 == 0 || pr % 30 == 0 || pr % 50 == 0 { 0.6 }
        else if pr % 10 == 0 { 0.75 }
        else if pr < 20 { 0.5 }
        else { 0.0 };
    score -= useful * 12.0;

    // Lookahead: reward if the next item fits into the post residual,
    // with a harmonic bonus when next size divides/matches the leftover.
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if next_item_size <= pr {
            score -= 10.0;
            if pr % next_item_size.max(1) == 0 { score -= 4.0; }
        } else {
            score += 0.15 * (next_item_size - pr) as f64;
        }
        // If next item cannot fit ANY bin at residual 100 either, dampen lookahead.
        if n > cap { score += 5.0; }
    }

    // Last-chance bin: strongly favor using the only bin that fits,
    // unless the fit is terrible (huge dead space).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
        if post_residual > 60 { score += 10.0; }
    }

    // New-bin candidate: make it attractive only when no open bin gives a tight fit.
    if bin_residual == bin_capacity {
        // Base penalty so a decent existing fit wins; decay as stream progresses
        // and open bins accumulate (fragmentation risk).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 20.0 - 8.0 * progress;
        // If mean residual across open bins is large, opening new bin is wasteful.
        score += 0.10 * mean_residual;
        // If item is large, opening a fresh bin is relatively better.
        score -= 0.08 * item_size as f64;
    } else {
        // Prefer fuller bins: penalize bins with lots of residual left.
        score += 0.05 * (bin_residual as f64 - mean_residual).abs();
        // Tight-fit reward: closeness of item to bin residual.
        score -= 0.20 * (bin_residual - item_size) as f64 * 0.0; // neutralized; post_residual already encodes this
    }

    // Slight preference to spread load when many bins open (balance residuals).
    if bin_residual != bin_capacity {
        score += 0.03 * (post_residual as f64 - mean_residual).abs();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps (1..=10) are almost unusable
    // for future items (sizes >= 1 but typically larger), so penalize them hard.
    if post_residual > 0 && post_residual <= 10 {
        score += 40.0 * (1.0 - post_residual as f64 / 10.0);
    }
    // Perfect fit is heavily rewarded.
    if post_residual == 0 {
        score -= 30.0;
    }
    // Moderate gaps (11..=25) are mildly penalized: they can host small items but waste capacity.
    else if post_residual <= 25 {
        score += 6.0 * (1.0 - post_residual as f64 / 25.0);
    }

    // Reward bins whose residual is close to the item (tight fit ratio).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 10.0 * tightness;

    // Lookahead coupling: if the next item fits exactly in the post residual, reward strongly.
    if next_item_size > 0 && post_residual >= next_item_size {
        if post_residual == next_item_size {
            score -= 25.0;
        } else {
            score -= 8.0 * (next_item_size as f64 / post_residual as f64);
        }
    }
    // If next item cannot fit in the post residual, the leftover is likely dead space.
    else if next_item_size > post_residual && post_residual > 0 {
        score += 5.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; with few open bins,
    // allow opening new ones (mildly penalize new bins via residual term already = capacity).
    score += 0.35 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate handling: an empty bin has post_residual = capacity - item.
    // Penalize opening a new bin unless the fit is bad in all existing bins.
    if bin_residual == bin_capacity {
        score += 12.0;
        if fitting_bins_count == 0 {
            score -= 60.0; // no alternative: new bin is fine
        }
    }

    // Progress-based calibration: late in the stream, prefer consolidating into
    // existing bins to avoid stranding capacity.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 6.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Mean-residual coupling: if this bin's residual is far below the mean, it is
    // nearly full already — placing here consolidates waste.
    let deviation = mean_residual - bin_residual as f64;
    score -= 0.05 * deviation;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect-fit reward: strongly favor placements that leave near-zero residual.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual < 10 {
        score -= 300.0;
    } else if post_residual <= 15 {
        score -= 80.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches the next item exactly.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 120.0 / (1.0 + diff);
        // Exact chain match: this bin then next item fits perfectly.
        if post_residual == next_item_size {
            score -= 250.0;
        }
        // Penalize residual that is just barely too small for the next item
        // (dead space that blocks a good follow-up placement).
        if next_item_size > post_residual && next_item_size - post_residual <= 10 {
            score += 60.0;
        }
    }

    // Compare post_residual to mean residual: prefer leaving average-sized slack,
    // penalize creating outliers far below the mean (fragmentation).
    let frag = mean_residual - post_residual as f64;
    if frag > 0.0 {
        score += 0.35 * frag;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bin fit is poor.
    if bin_residual == bin_capacity {
        let good_fit = (post_residual as f64) < 0.25 * bin_capacity as f64;
        if good_fit {
            score -= 50.0; // placing a large item in a fresh bin is fine
        } else {
            score += 90.0 + 0.5 * post_residual as f64;
        }
        // Early in the stream, prefer filling existing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += (1.0 - progress) * 40.0;
    }

    // Mild preference for tighter bins when many bins are open.
    score += 0.15 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 0.87;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let post = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_post = post / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_post * norm_post * (1.0 + 2.0 * progress) + norm_post * (0.5 + progress * progress);
    score += 12.0 * poly;

    // Reward tight fits (small post_residual) more strongly later in the stream
    let tightness = 1.0 - norm_post;
    score -= (item_size as f64 / cap) * (1.0 + 3.0 * progress) * tightness;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + 20.0 * progress;
    }

    // Penalize opening a new bin when open bins exist that fit, especially early
    let is_new_bin = bin_residual == bin_capacity && post_residual == bin_capacity.saturating_sub(item_size);
    if is_new_bin {
        let fit_pressure = 1.0 / (1.0 + fitting_bins_count as f64);
        score += 30.0 * fit_pressure * (1.0 - 0.5 * progress);
        // Still allow new bin if it would create a near-perfect slot for the next item
        if next_item_size > 0 && post_residual >= next_item_size {
            let perfect_next = (post_residual - next_item_size) as f64 / cap;
            score -= 20.0 * (1.0 - perfect_next) * (1.0 - perfect_next);
        } else if next_item_size == 0 {
            score += 15.0;
        }
    }

    // Lookahead: bonus if post_residual accommodates the next item well
    if next_item_size > 0 && !is_new_bin {
        if post_residual >= next_item_size {
            let next_fit = (post_residual - next_item_size) as f64 / cap;
            score -= 10.0 * (1.0 - next_fit) * (1.0 - next_fit);
        } else {
            score += 5.0 * (next_item_size.saturating_sub(post_residual) as f64 / cap);
        }
    }

    // Mean residual coupling: prefer bins below mean residual (more filled)
    score += (mean_residual - post as f64).max(0.0) * 0.3;

    // Mild penalty for proliferating open bins
    score += (open_bins_count as f64).ln().max(0.0) * 2.0 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: quantize post_residual into capacity fractions
    let cap = bin_capacity as f64;
    let post_frac = post_residual as f64 / cap;
    let item_frac = item_size as f64 / cap;

    // Class of post_residual via integer division thresholds (harmonic bins of capacity)
    let class = post_residual / 10; // 0..=10 harmonic class
    match class {
        0 => score -= 60.0,          // near-perfect fit, reward heavily
        1 => score -= 40.0,
        2 => score -= 25.0,
        3 => score -= 10.0,
        4 => score += 5.0,
        5 => score += 12.0,          // half-empty: moderately bad dead space
        6 => score += 18.0,
        7 => score += 25.0,
        8 => score += 32.0,
        9 => score += 40.0,
        _ => score += 45.0,
    }

    // Modulo arithmetic coupling: leftover compatible with common item classes is reusable
    let r = post_residual % 10;
    if r == 0 {
        score -= 8.0; // leftover is a multiple of 10, matches typical item granularity
    } else if r >= 7 {
        score += 4.0; // awkward sliver
    }

    // Lookahead: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 55.0;
        } else if next_item_size <= post_residual {
            score -= (post_residual - next_item_size) as f64 * 0.6;
            // harmonic class match between next item and leftover
            if post_residual / 10 == next_item_size / 10 {
                score -= 6.0;
            }
        } else {
            // next item won't fit here; penalize less if leftover still broadly useful
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Penalize tight fits that leave unusable residue relative to mean residual
    if post_residual > 0 && (post_residual as f64) < mean_residual * 0.25 {
        score += 10.0;
    }

    // New-bin candidate: only attractive when open bins have poor fits or stream is early
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mean_tightness = 1.0 - mean_residual / cap;
        let bonus = 70.0 * pressure + 35.0 * (1.0 - mean_tightness) + 20.0 * (1.0 - progress);
        // large items prefer fresh bins to avoid fragmentation
        let big_item_bonus = if item_frac > 0.5 { 25.0 } else { 0.0 };
        score = 95.0 + cap - post_residual as f64 - bonus - big_item_bonus;
    }

    // Slight preference for fuller bins overall
    score -= item_frac * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful
    // (below the minimum plausible item size) are pure waste -> heavy penalty.
    let dead_threshold = 10.0;
    if (post_residual as f64) < dead_threshold {
        // Unusable sliver: penalize proportionally to how much capacity is locked away.
        score += 40.0 + 0.5 * post_residual as f64;
    } else if post_residual == 0 {
        // Perfect fill: reward strongly.
        score -= 60.0;
    }

    // Reward tight fits: fraction of residual consumed by the item.
    if bin_residual > 0 {
        let fill_ratio = item_size as f64 / bin_residual as f64;
        score -= 25.0 * fill_ratio * fill_ratio;
    }

    // Penalize leaving a gap that exactly matches the next item only mildly,
    // but heavily penalize gaps that are just barely too small for the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0; // next item can chain here: good
        } else if post_residual > 0 && post_residual < next_item_size {
            score += 12.0; // stranded gap relative to lookahead
        }
    }

    // Open-bin pressure: discourage spreading across many bins unless the fit is good.
    score += 1.5 * open_bins_count as f64 * (1.0 - item_size as f64 / bin_capacity as f64);

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when all open bins
    // would leave large unusable dead space.
    if bin_residual == bin_capacity {
        // Baseline score for a fresh bin: neutral residual (capacity itself),
        // adjusted by how scattered current residuals are.
        score = bin_capacity as f64 * 0.5;
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a new bin
        } else if mean_residual > 60.0 {
            score -= 5.0; // open bins are roomy anyway; opening another is cheap
        } else {
            score += 20.0; // prefer packing into existing bins
        }
    }

    // Mild stream-progression adaptation: later in the stream, be slightly more
    // conservative about opening bins (consolidation pressure).
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        score += 5.0 * progress * (mean_residual / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong penalty for large wasted space relative to capacity.
    let waste_ratio = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * waste_ratio * waste_ratio;

    // Reward exact/tight fits: small post_residual gets a bonus.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches next item size.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if gap == 0.0 {
            score -= 20.0;
        } else if post_residual as f64 >= next_item_size as f64 {
            // Next item fits exactly-ish: big reward.
            score -= 12.0 / (1.0 + gap / 10.0);
        } else {
            // Next item won't fit: mild penalty proportional to leftover.
            score += 6.0 * gap / 50.0;
        }
    }

    // Relative-to-mean coupling: bins with residual far below mean are precious
    // (already tight); prefer filling them to consolidate.
    let dev = (bin_residual as f64 - mean_residual) / (bin_capacity as f64);
    score += 10.0 * dev;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 18.0;
    }

    // New-bin candidate: make it attractive only when no good fit exists,
    // i.e., when the item fits poorly everywhere. Penalize opening a new bin
    // when tight fits are available.
    if bin_residual == bin_capacity {
        score += 15.0;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // fresh bin helps both current and next item
        }
        if fitting_bins_count == 1 {
            score += 30.0; // don't open new bin when only one bin fits
        }
    }

    // Early stream: slightly prefer consolidating into few bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base preference: tight fit (small post_residual) is good.
    // Normalize post_residual relative to capacity.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * fit_ratio * fit_ratio;

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly reward using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 60.0;
    } else if fitting_bins_count > 1 {
        // With several candidate bins, extra weight on tightness.
        score += 10.0 * fit_ratio;
    }

    // Lookahead: if the next item fits exactly in the post residual,
    // strongly reward this placement (perfect chaining).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 50.0;
        } else if post_residual >= next_item_size {
            let rem_after_next = post_residual - next_item_size;
            score -= 15.0 * (rem_after_next as f64 / bin_capacity as f64);
        } else {
            // Next item won't fit here; penalize leaving awkward residual.
            let waste = post_residual as f64 / bin_capacity as f64;
            score += 12.0 * waste * waste;
        }
    }

    // Penalize opening a brand-new bin when other bins could fit the item.
    if bin_residual == bin_capacity && fitting_bins_count > 0 {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 80.0 + 60.0 * (1.0 - progress);
        // If mean residual across open bins is large, opening new bin is extra wasteful.
        score += (mean_residual / bin_capacity as f64) * 50.0;
    }

    // Slight reward for keeping number of open bins down (consolidation).
    score += 0.5 * open_bins_count as f64;

    // Encourage filling bins nearly completely (dead-space aversion).
    if post_residual < item_size && post_residual > 0 {
        // residual too small for the current item size class -> likely dead space
        score += 8.0;
    }

    // Mild time-dependent tightness pressure: as stream progresses,
    // care more about compactness.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.3 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 1 { step_index as f64 / (total_items as f64 - 1.0) } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Tight-fit reward: non-linearly reward small post_residual.
    let tight = 1.0 - (pr / cap);
    score -= 30.0 * tight * tight * tight;

    // Penalize dead space relative to item size: post_residual much larger than
    // typical item sizes is unusable. Smooth polynomial in pr/cap.
    let waste = (pr / cap).powi(2);
    score += 20.0 * waste * (0.5 + 0.5 * progress);

    // Coupling with next item: reward residuals that can host the lookahead item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let slack = (pr - nxt) / cap;
            score -= 15.0 * (1.0 - slack) * (1.0 - progress);
        } else {
            // Post-residual too small for next item: mild penalty growing with progress.
            score += 8.0 * (1.0 - pr / cap) * (0.3 + 0.7 * progress);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0 + 20.0 * progress;
    }

    // Mean-residual context: prefer bins whose residual deviates from mean
    // (consolidate space into few bins). Smooth interaction.
    let dev = (pr - mean_residual).abs();
    score += 0.05 * dev * (1.0 - tight);

    // Slight bias toward filling existing bins as stream progresses.
    score += 5.0 * (1.0 - progress) * (pr / cap);

    // New-bin candidate should lose unless residuals are all nearly unusable.
    if bin_residual == bin_capacity {
        score += 60.0 - 25.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residuals that are "perfect fits"
    // for common item sizes (divisors of capacity / small multiples).
    let pr = post_residual;
    if pr == 0 {
        score -= 1000.0; // perfect closure
    } else if pr <= 10 {
        score -= 80.0;   // near-perfect dead space
    } else {
        // Penalize residuals in "dead zones": too small for smallest item (1..100 range)
        let min_item = 1u32;
        if pr < 10 {
            score += 30.0; // unusable sliver
        }
        // Harmonic bonus: residuals divisible by small integers pair well
        if pr % 10 == 0 { score -= 25.0; }
        else if pr % 5 == 0 { score -= 12.0; }
        else if pr % 3 == 0 { score -= 6.0; }
        let _ = min_item;
    }

    // Lookahead coupling: does post_residual fit the next item exactly or well?
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 150.0; // exact pairing
        } else if next_item_size < pr {
            let slack = (pr - next_item_size) as f64;
            // harmonic class of the leftover after the lookahead
            let lr = pr - next_item_size;
            let mut bonus = 40.0 - 0.35 * slack;
            if lr % 10 == 0 { bonus += 20.0; }
            else if lr % 5 == 0 { bonus += 10.0; }
            if lr == 0 { bonus += 60.0; }
            score -= bonus.max(0.0);
        } else {
            // next item cannot fit here: mild penalty scaled by overflow
            score += 0.2 * (next_item_size - pr) as f64;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 60.0;
    }

    // Many open bins: prefer filling existing bins over opening new ones
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let crowding = (open_bins_count as f64).ln().max(0.0);
    if bin_residual < bin_capacity {
        score -= 8.0 * crowding * (0.5 + 0.5 * progress);
    } else {
        // New-bin candidate: penalize unless mean residual across open bins is tiny
        score += 15.0 + 0.5 * mean_residual;
        if mean_residual < (item_size as f64) * 0.5 {
            score -= 40.0; // open bins nearly full; new bin is fine
        }
    }

    // Slight preference for tight fits overall
    score += 0.1 * (bin_residual - item_size) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to hold even the
    // smallest plausible item (1) are already dead; penalize gaps that are
    // too small to be useful for typical upcoming items.
    let dead_threshold = 10.0f64.min(bin_capacity as f64 * 0.1);
    if (post_residual as f64) < dead_threshold {
        // Perfect fit zone: strongly reward leaving nothing usable wasted.
        score -= 25.0 * (dead_threshold - post_residual as f64 + 1.0);
    }

    // Penalize "awkward" residuals: gaps that fit nothing likely next
    // (small but nonzero leftovers in the 1..=5 range are worst).
    if post_residual >= 1 && post_residual <= 5 {
        score += 40.0;
    }

    // Reward tight fits relative to item size.
    if item_size > 0 {
        let tightness = item_size as f64 / bin_residual.max(1) as f64;
        score -= 15.0 * tightness;
    }

    // Open-bin pressure: when many bins are open, prefer consolidating
    // into existing bins over spreading; when few bins are open, opening
    // a new bin is cheaper.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += 6.0 * pressure;

    // Last-chance bin: if this is the only bin that fits, strongly favor it
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless the current item
    // is large or residuals across open bins are already fragmented.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let fragmentation = mean_residual - (post_residual as f64);
        let lookahead_need = if next_item_size > 0 {
            (next_item_size as f64 / bin_capacity as f64).powi(2)
        } else {
            0.0
        };
        // Open a new bin only if existing bins are fragmented or the next
        // item is huge and would leave bad gaps elsewhere.
        let open_bonus = 20.0 * fragmentation / (bin_capacity as f64)
            + 10.0 * lookahead_need
            - 12.0;
        score += open_bonus;
        // Late in the stream, avoid proliferating bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 15.0 * progress;
    }

    // Lookahead: reward placements that keep room for the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    } else if next_item_size > 0 {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next_item_size
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 8.0 / (1.0 + diff);
        // Perfect chain: next item exactly fills this bin
        if post_residual == next_item_size {
            score -= 25.0;
        }
        // Next item could still fit comfortably but not perfectly
        if next_item_size <= post_residual && post_residual - next_item_size <= 10 {
            score -= 10.0;
        }
    }

    // Penalize large dead space relative to mean residual across open bins
    let pr = post_residual as f64;
    if pr < mean_residual {
        score += 0.6 * (mean_residual - pr);
    } else {
        score -= 0.3 * (pr - mean_residual);
    }

    // Penalize unusable tiny fragments (dead space below minimum item size)
    if pr > 0.0 && pr < 10.0 {
        score += 15.0 * (10.0 - pr);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: prefer it only when post_residual is large (fresh capacity)
    if bin_residual == bin_capacity {
        score -= 0.4 * pr;
        // discourage opening new bin when a good fit exists in open bins
        if fitting_bins_count > 0 && post_residual <= 15 {
            score += 30.0;
        }
    }

    // Slight preference for filling bins more completely as stream progresses
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (bin_capacity - post_residual) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    if bin_residual == bin_capacity {
        // Brand-new empty bin candidate: baseline penalty so we prefer good fits
        // into existing bins, but allow opening when fits are poor or scarce.
        score = 45.0 + item_size as f64 * 0.35;
        if fitting_bins_count > 0 {
            score += 18.0 + 6.0 / fitting_bins_count as f64;
        }
        // If this item would leave a residual smaller than typical item sizes,
        // a fresh bin is actually attractive (tight packing start).
        if next_item_size > 0 && next_item_size as f64 > post_residual as f64 {
            score -= 12.0;
        }
        // Late in the stream, opening bins is less costly (fewer future items).
        score -= t * 20.0;
        // If mean residual across open bins is very fragmented, fresh bin helps.
        if mean_residual < 25.0 {
            score -= 15.0;
        }
    } else {
        // Perfect fill is ideal.
        if post_residual == 0 {
            score -= 40.0;
        }
        // Lookahead: reward if next item can also fit into the leftover space.
        if next_item_size > 0 {
            if (next_item_size as f64) <= post_residual as f64 {
                score -= 14.0;
            } else if (next_item_size as f64) <= bin_residual as f64 {
                score += 6.0; // consumes space the next item could have used
            }
        }
        // Last-chance bin: strongly favor using it to avoid opening a new bin.
        if fitting_bins_count == 1 {
            score -= 28.0;
        }
        // Prefer bins whose residual is tight relative to the mean (good fits).
        score += (post_residual as f64 - mean_residual).abs() * 0.08;
        // Slight bias to fill fuller bins first as stream progresses.
        score -= (bin_capacity - bin_residual) as f64 * 0.05;
        score -= t * 4.0;
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits (low post residual), with non-linear shaping
    let mut score = norm_pr * (1.0 + 2.0 * norm_pr * norm_pr);

    // Smooth polynomial coupling of post_residual with stream progress:
    // early on, dead space matters less; later, squeeze harder.
    let progress_coupling = 1.0 + 1.5 * progress * progress;
    score *= progress_coupling;

    // Reward bins whose residual after placement matches the next item size
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        let gap = (post_residual as f64 - next_item_size as f64) / cap;
        score -= 0.8 * (1.0 - gap).max(0.0);
    } else if next_item_size > 0 {
        // Penalize residuals that cannot host the lookahead item
        score += 0.5 * (next_item_size as f64 - pr) / cap;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 2.0 + 2.0 * progress;
    }

    // Compare against mean residual: bins with more slack than average are
    // cheaper to fill (smooth term)
    score -= 0.3 * ((mean_residual - pr) / cap);

    // Mild penalty when many bins are open: encourage consolidation
    score += 0.05 * open_bins_count as f64 * norm_pr;

    // New-bin candidate: only attractive if no open bin fits well
    if bin_residual == bin_capacity {
        score += 3.0 + 2.0 * progress - 0.5 * item_size as f64 / cap;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residual classes by capacity quarters
    let q = (post_residual * 4) as i64 / bin_capacity as i64; // 0..3
    match q {
        0 => score -= 25.0,             // near-perfect fill
        1 => score += 5.0,              // small leftover
        2 => score += 12.0,             // half-empty bin is wasteful
        _ => score += 20.0,             // mostly empty after placement
    }

    // Modulo arithmetic on post_residual: leftovers divisible by small sizes are reusable
    let pr = post_residual;
    if pr > 0 {
        if pr % 10 == 0 { score -= 8.0; }
        else if pr % 5 == 0 { score -= 4.0; }
        else if pr < 10 { score += 6.0; } // dead sliver
    }

    // Lookahead: does next item fit the post-residual exactly or at all?
    if next_item_size > 0 {
        let n = next_item_size;
        if n <= pr {
            if pr % n == 0 { score -= 15.0; }        // perfect chain
            else if (pr / n) >= 2 { score -= 8.0; }  // multiple fits
            else { score -= 3.0; }
        } else {
            score += 7.0; // next item cannot use this bin's leftover
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 18.0;
    }

    // New-bin candidate: penalize opening a new bin mildly, less so early in stream
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let openness = mean_residual / cap;
        score = cap * (0.85 + 0.3 * progress) - 10.0 * openness;
        if fitting_bins_count == 0 { score -= 30.0; } // no alternative
    }

    // Prefer bins whose residual is close to item size (tight fit)
    let tightness = (bin_residual - item_size) as f64 / cap;
    score += 10.0 * tightness * tightness;

    // Many open bins: encourage consolidation into emptier bins
    if open_bins_count > 3 {
        score += 0.5 * open_bins_count as f64 * (1.0 - (post_residual as f64 / cap));
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize unusable dead space: residuals too small for typical items
    let dead_zone = if post_residual > 0 && post_residual < 10 { 60.0 } else { 0.0 };
    let small_gap = if post_residual >= 10 && post_residual < 30 { 15.0 } else { 0.0 };
    score += dead_zone + small_gap;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 100.0;
    }

    // Reward leaving room for the lookahead item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0 + (next_item_size as f64) * 0.2;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 8.0;
    }

    // Last-chance bin: strong reward to use it instead of opening a new one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = (open_bins_count as f64).sqrt() * (1.0 + progress);
    if bin_residual == bin_capacity {
        score += 25.0 + pressure * 4.0;
    } else {
        score -= pressure * 0.5;
    }

    // Prefer bins tighter than average (good fill)
    score += (post_residual as f64 - mean_residual) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fit (small post_residual) relative to capacity
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 60.0 * tightness * tightness;

    // Reward perfect fits strongly
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    }

    // 2-step lookahead: reward if next item fits into post_residual
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // next item can also go here: bonus proportional to how well it matches
            let pair_waste = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - pair_waste / bin_capacity as f64);
        } else {
            // next item won't fit here: penalize leaving residual that's too small
            let gap = (next_item_size - post_residual) as f64;
            score += 10.0 * (gap / bin_capacity as f64);
        }
    }

    // Compare against mean residual across open bins
    score += 0.5 * (post_residual as f64 - mean_residual);

    // Last-chance bin: strong reward to use it (avoid opening new bin)
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: penalize unless current bins are poor fits
    if bin_residual == bin_capacity {
        score += 45.0;
        // If item is large, opening a new bin is more reasonable
        if item_size >= bin_capacity / 2 {
            score -= 20.0;
        }
        // Many open bins with small mean residual: new bin attractive
        if mean_residual < item_size as f64 * 0.5 {
            score -= 15.0;
        }
    }

    // Late in stream: consolidate, avoid opening new bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= 10.0 * progress;
    } else {
        score += 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let is_new_bin = bin_residual == bin_capacity;
    let mut score = post_residual as f64;

    // Penalize dead space that the lookahead item cannot use.
    if next_item_size > 0 && post_residual < next_item_size {
        let waste = (next_item_size - post_residual) as f64;
        score += waste * (0.5 + 0.5 * progress);
    }
    // Reward residuals that the next item can slot into (pairing bonus).
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score += slack * 0.2;
    }
    // Reward tight fits relative to the fleet's mean residual.
    score += 0.25 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 12.0 + 5.0 * progress;
    }

    // Penalize crowding when many bins are already open and this fit is loose.
    if fitting_bins_count > 2 && post_residual > bin_capacity / 2 {
        score += (fitting_bins_count as f64) * 1.5;
    }

    // New-bin candidate: make it lose unless all open options are poor fits.
    if is_new_bin {
        score += 35.0 + (open_bins_count as f64) * 4.0 + 10.0 * (1.0 - progress);
        // But if the next item would perfectly fill this fresh bin's residual,
        // opening a new bin becomes attractive.
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 30.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let t = progress;
    let poly = 1.0 + 0.8 * t - 1.5 * t * t + 1.2 * t * t * t;
    score *= poly;

    // Reward tight fits more aggressively as stream progresses
    let tightness = 1.0 - pr / cap;
    score -= tightness * tightness * (20.0 + 30.0 * t);

    // Penalize dead space that cannot fit the next item (smooth quadratic)
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).max(0.0);
        score += 0.5 * gap * gap / cap;
    }

    // Last-resort bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Mild penalty when many bins are open (prefer consolidation)
    score += open_bins_count as f64 * (0.5 + 0.5 * t);

    // Prefer bins whose residual is near the mean (balance residuals smoothly)
    let dev = pr - mean_residual;
    score += 0.2 * dev * dev / cap;

    // New-bin candidate: penalize so it only wins when fits are truly bad
    if bin_residual == bin_capacity {
        score += 15.0 + 25.0 * t;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose residual falls into "useful"
    // small classes (<=10, <=20) are rewarded since small dead space is cheap.
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fit
    } else if pr <= 5 {
        score -= 40.0;
    } else if pr <= 10 {
        score -= 25.0;
    } else if pr <= 20 {
        score -= 10.0;
    } else {
        // penalize large unusable leftovers via modulo classes
        let m = pr % 10;
        score += (m as f64) * 1.5; // awkward residuals are harder to fill
        score += (pr as f64) * 0.35;
    }

    // Lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 && next_item_size <= pr {
        let gap = (pr - next_item_size) as f64;
        score -= 35.0 - gap * 0.8;
        if gap == 0.0 {
            score -= 25.0; // chained perfect fit
        }
    } else if next_item_size > 0 && next_item_size > pr {
        // next item won't fit here; penalize proportionally to wasted potential
        score += 8.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        // competition: prefer tighter fits among many candidates
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // Prefer filling already-open bins over opening new ones, scaled by progress.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // new-bin candidate: penalize more as stream progresses / many bins open
        score += 20.0 + 30.0 * progress + 2.0 * open_bins_count as f64;
        // but if item is large and mean residual can't hold it, new bin is fine
        if (item_size as f64) > mean_residual {
            score -= 25.0;
        }
    } else {
        score -= 6.0 + 4.0 * progress;
        // bonus for bins tighter than mean (efficiently filling)
        if (bin_residual as f64) < mean_residual {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: post_residual in the "unusable gap" band
    // (too small for the smallest plausible item) is heavily penalized.
    let gap_floor = 10u32; // smallest known item size
    if post_residual > 0 && post_residual < gap_floor {
        score += (gap_floor - post_residual) as f64 * 25.0;
    }
    // Perfect fit is strongly rewarded.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= gap_floor {
        // Residual just above the dead-space band: mildly risky.
        score += 8.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = post_residual as f64 / (item_size as f64 + 1.0);
    score += tightness * 10.0;

    // New-bin candidate: penalize opening a new bin unless the item fits
    // poorly everywhere (last chance) or there are no open bins.
    if bin_residual == bin_capacity {
        let last_chance = fitting_bins_count <= 1;
        let pressure = open_bins_count as f64 / 8.0;
        let mut new_bin_penalty = 45.0 + pressure * 20.0;
        if last_chance {
            new_bin_penalty *= 0.25;
        }
        // Early in the stream, opening bins is cheaper (more items to come
        // will fill them); later, consolidation matters more.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        new_bin_penalty *= 1.0 + progress * 0.8;
        score += new_bin_penalty;
    }

    // Open-bins pressure: mildly discourage spreading into already-open bins
    // when mean residual is high (bins are under-filled).
    if bin_residual != bin_capacity {
        score += (mean_residual - post_residual as f64) * 0.15;
    }

    // Lookahead (k=2): reward leaving post_residual that can host next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else if post_residual > 0 {
            score += 6.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}
